['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

typedef struct {
    uint32_t tag;
} MAC_EVENT_TAG;

typedef struct {
    int type;
    size_t length;
    void *data; // Pointer to actual data, can be casted based on type
} MAC_FRAME_DATA;

typedef struct FrameNode {
    MAC_FRAME_DATA frame_data;
    struct FrameNode* next;
} FrameNode;

typedef struct {
    MAC_EVENT_TAG event_tag;
    uint64_t timestamp;
    FrameNode* head;
    pthread_rwlock_t lock; // Read-write lock for concurrent access
} NetworkEvent;

typedef struct {
    NetworkEvent* events;
    size_t count;
    pthread_mutex_t alloc_lock;
} DynamicList;

void init_dynamic_list(DynamicList* list) {
    list->events = NULL;
    list->count = 0;
    pthread_mutex_init(&list->alloc_lock, NULL);
}

void free_frame_node(FrameNode* node) {
    if (node->frame_data.data != NULL) {
        free(node->frame_data.data); // Free the actual data
    }
    free(node);
}

void delete_event(NetworkEvent* event) {
    FrameNode* current = event->head;
    while (current != NULL) {
        FrameNode* temp = current;
        current = current->next;
        free_frame_node(temp);
    }
    pthread_rwlock_destroy(&event->lock);
    free(event);
}

int add_event(DynamicList* list, MAC_EVENT_TAG tag, uint64_t timestamp, MAC_FRAME_DATA frame_data) {
    pthread_mutex_lock(&list->alloc_lock);

    NetworkEvent* new_event = (NetworkEvent*)malloc(sizeof(NetworkEvent));
    if (!new_event) {
        pthread_mutex_unlock(&list->alloc_lock);
        return -1; // Memory allocation failed
    }

    new_event->event_tag = tag;
    new_event->timestamp = timestamp;
    new_event->head = NULL;

    FrameNode* frame_node = (FrameNode*)malloc(sizeof(FrameNode));
    if (!frame_node) {
        free(new_event);
        pthread_mutex_unlock(&list->alloc_lock);
        return -1; // Memory allocation failed
    }

    frame_node->frame_data = frame_data;
    frame_node->next = NULL;

    pthread_rwlock_init(&new_event->lock, NULL);

    FrameNode** head_ptr = (FrameNode**)&new_event->head;
    while (*head_ptr != NULL) {
        head_ptr = &((*head_ptr)->next);
    }
    *head_ptr = frame_node;

    size_t new_count = list->count + 1;
    NetworkEvent* new_events = realloc(list->events, new_count * sizeof(NetworkEvent));
    if (!new_events) {
        delete_event(new_event); // Clean up on failure
        pthread_mutex_unlock(&list->alloc_lock);
        return -1; // Memory allocation failed
    }

    list->events = new_events;
    list->events[list->count++] = *new_event;

    pthread_mutex_unlock(&list->alloc_lock);
    return 0; // Success
}

void free_dynamic_list(DynamicList* list) {
    for (size_t i = 0; i < list->count; ++i) {
        delete_event(&list->events[i]);
    }
    free(list->events);
    pthread_mutex_destroy(&list->alloc_lock);
}
```

This code provides a function to manage a dynamic list of network events using a custom data structure, supporting concurrent read and write operations with minimal latency impact. Memory management strategies like frame node deletion and careful reallocation ensure efficient resource utilization suitable for low-latency systems. The lock-free design is partially achieved using `pthread_rwlock_t` for event-level protection while maintaining overall simplicity.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int key;
    long offset;
} record;

record* allocate_and_initialize_records(int num_records, long min_offset, long max_offset) {
    if (num_records <= 0 || min_offset > max_offset) return NULL;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Dynamically allocate memory for the records
    record *records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        pthread_mutex_destroy(&lock);
        return NULL;  // Handle allocation failure
    }

    srand(pthread_self()); // Seed with thread ID to ensure randomness in multithreaded context

    // Initialize records with unique keys and random offsets within the given range
    for (int i = 0; i < num_records; ++i) {
        pthread_mutex_lock(&lock);
        records[i].key = i;
        records[i].offset = min_offset + rand() % (max_offset - min_offset + 1);
        pthread_mutex_unlock(&lock);
    }

    // Sort the records by key
    for (int i = 0; i < num_records - 1; ++i) {
        for (int j = 0; j < num_records - i - 1; ++j) {
            if (records[j].key > records[j + 1].key) { // Swap logic
                record temp = records[j];
                records[j] = records[j + 1];
                records[j + 1] = temp;
            }
        }
    }

    pthread_mutex_destroy(&lock);

    return records; 
}

void free_records(record *records) {
    if (records) {
        free(records);
    }
}

// Usage example
int main() {
    int num_records = 1000;
    long min_offset = 0;
    long max_offset = 9999;

    record* my_records = allocate_and_initialize_records(num_records, min_offset, max_offset);

    if (my_records) {
        // Use the records as needed...

        // Free allocated memory
        free_records(my_records);
    } else {
        fprintf(stderr, "Failed to allocate memory for records.\n");
    }

    return 0;
}
```

This code defines a C function `allocate_and_initialize_records` that dynamically allocates and initializes an array of `record` structures with unique keys and random offsets. It ensures thread safety during initialization using mutexes, handles potential allocation failures gracefully, sorts the records by key in ascending order, and provides a mechanism to release allocated memory via the `free_records` function.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "log4c.h"

#define BUFFER_SIZE 8192

typedef struct {
    char *keywords;
    char *output_file;
} options_t;

void usage() {
    printf("Usage: program [options] input_file\n"
           "Options:\n"
           "  --help          Display this help message and exit.\n"
           "  -c keywords     Specify comma-separated list of keywords for filtering lines.\n"
           "  -o output_file  Specify the output file path.\n");
}

int parse_options(int argc, char *argv[], options_t *options) {
    int opt;
    while ((opt = getopt(argc, argv, "hc:o:")) != -1) {
        switch (opt) {
            case 'h':
                usage();
                exit(0);
            case 'c':
                options->keywords = strdup(optarg);
                break;
            case 'o':
                options->output_file = strdup(optarg);
                break;
            default:
                fprintf(stderr, "Unknown option %c\n", opt);
                return 1;
        }
    }
    if (optind >= argc) {
        fprintf(stderr, "Expected argument after options\n");
        return 1;
    }
    return 0;
}

void process_file(const char *input_file, const char *output_file, const char *keywords) {
    FILE *in = fopen(input_file, "r");
    if (!in) {
        log4c_category_log(log4c_category_get("default"), LOG4C_PRIORITY_ERROR,
                           "Failed to open input file: %s", strerror(errno));
        return;
    }

    FILE *out = output_file ? fopen(output_file, "w") : stdout;
    if (!out && output_file) {
        log4c_category_log(log4c_category_get("default"), LOG4C_PRIORITY_ERROR,
                           "Failed to open output file: %s", strerror(errno));
        fclose(in);
        return;
    }

    char buffer[BUFFER_SIZE];
    size_t keywords_len = strlen(keywords);
    while (fgets(buffer, BUFFER_SIZE, in)) {
        if (strstr(buffer, keywords) != NULL || !keywords[0]) {
            fprintf(out, "%s", buffer);
        }
    }

    fclose(in);
    if (out != stdout) fclose(out);
}

int main(int argc, char *argv[]) {
    log4c_init();
    log4c_category_t *logger = log4c_category_get("default");
    log4c_conf_file_set("log4c.conf");

    options_t options = {0};
    if (parse_options(argc, argv, &options)) {
        return 1;
    }

    const char *input_file = argv[optind];
    process_file(input_file, options.output_file, options.keywords);

    free(options.keywords);
    free(options.output_file);

    log4c_fini();
    return 0;
}
```

### Notes:
- **Log4C Library**: Ensure you have the Log4C library installed and configured. The `log4c.conf` file should be properly set up for logging configurations.
- **Thread Safety**: This example does not include explicit threading; however, if concurrent access is needed, consider using mutexes or other synchronization mechanisms.
- **Error Handling**: Basic error handling is included. Extend this as necessary to handle specific edge cases and interruptions.
- **Buffer Size**: The buffer size can be adjusted based on performance testing with your specific use case.
- **Modularity**: Functions are separated for parsing options, processing files, and main execution, allowing easy modifications and enhancements.

Ensure you compile the program with `-llog4c` to link against the Log4C library. Adjust logging configurations in `log4c.conf` as needed for different environments or verbosity levels.']

