['```c
#include <stdio.h>
#include <stdarg.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define DEBUG_PRIORITY 1
#define INFO_PRIORITY 2
#define ERROR_PRIORITY 3

typedef struct {
    FILE *stream;
    int priority;
    const char* priority_name;
} Logger;

static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void add_logger(Logger **loggers, size_t *count, Logger new_logger) {
    pthread_mutex_lock(&log_mutex);

    *loggers = realloc(*loggers, (*count + 1) * sizeof(Logger));
    if (*loggers == NULL) {
        perror("Failed to allocate memory for loggers");
        exit(EXIT_FAILURE);
    }

    (*loggers)[*count] = new_logger;
    (*count)++;

    pthread_mutex_unlock(&log_mutex);
}

void remove_logger(Logger **loggers, size_t *count, int index) {
    if (index < 0 || index >= *count) return;

    pthread_mutex_lock(&log_mutex);

    for (size_t i = index; i < *count - 1; ++i) {
        (*loggers)[i] = (*loggers)[i + 1];
    }

    *loggers = realloc(*loggers, (*count - 1) * sizeof(Logger));
    if (*count > 0 && *loggers == NULL) {
        perror("Failed to reallocate memory for loggers");
        exit(EXIT_FAILURE);
    }

    (*count)--;

    pthread_mutex_unlock(&log_mutex);
}

void log_debug_message(Logger **loggers, size_t count, int condition, int priority_level, const char *format, ...) {
    if (!condition) return;

    va_list args;
    va_start(args, format);

    char buffer[4096];
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    pthread_mutex_lock(&log_mutex);

    for (size_t i = 0; i < count; ++i) {
        if (priority_level <= loggers[i]->priority) {
            fprintf(loggers[i]->stream, "%s: %s\n", loggers[i]->priority_name, buffer);
            fflush(loggers[i]->stream);
        }
    }

    pthread_mutex_unlock(&log_mutex);
}
