['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <errno.h>

// Structure to hold semaphore state and logs
typedef struct {
    sem_t sem;
    int max_value;
    pthread_mutex_t mutex;
} Semaphore;

Semaphore* init_semaphore(int initial, int max) {
    if (initial > max || initial < 0 || max <= 0) {
        fprintf(stderr, "Invalid semaphore limits: initial=%d, max=%d\n", initial, max);
        return NULL;
    }

    Semaphore *sem = malloc(sizeof(Semaphore));
    if (!sem) {
        perror("Failed to allocate memory for semaphore");
        return NULL;
    }

    sem_init(&sem->sem, 0, initial);
    sem->max_value = max;
    pthread_mutex_init(&sem->mutex, NULL);

    return sem;
}

void resize_semaphore(Semaphore *sem, int new_max) {
    if (!sem || new_max <= 0) {
        fprintf(stderr, "Invalid new maximum value: %d\n", new_max);
        return;
    }

    pthread_mutex_lock(&sem->mutex);

    int current_value = sem_getvalue(&sem->sem, NULL);
    if (new_max < current_value) {
        fprintf(stderr, "Cannot reduce semaphore max below current count\n");
        pthread_mutex_unlock(&sem->mutex);
        return;
    }

    sem->max_value = new_max;

    // Adjust the semaphore limit
    if (sem->max_value != SEM_VALUE_MAX) {
        sem_t temp_sem;
        sem_init(&temp_sem, 0, current_value);
        sem_destroy(&sem->sem);
        sem_init(&sem->sem, 0, sem->max_value);

        while (current_value > 0 && sem_trywait(&temp_sem) == 0) {
            sem_post(&sem->sem);
            current_value--;
        }
        sem_destroy(&temp_sem);
    }

    pthread_mutex_unlock(&sem->mutex);

    printf("Semaphore resized to new max value: %d\n", new_max);
}

void semaphore_wait(Semaphore *sem, int timeout_ms) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += timeout_ms / 1000;
    ts.tv_nsec += (timeout_ms % 1000) * 1000000;

    pthread_mutex_lock(&sem->mutex);

    while (1) {
        if (sem_timedwait(&sem->sem, &ts) == 0) {
            break; // Successfully acquired semaphore
        } else if (errno == ETIMEDOUT) {
            fprintf(stderr, "Semaphore wait timed out\n");
            pthread_mutex_unlock(&sem->mutex);
            return;
        }

        // Retry logic for EINTR or other transient errors can be added here

        clock_gettime(CLOCK_REALTIME, &ts);  // Refresh timeout
    }

    pthread_mutex_unlock(&sem->mutex);

    printf("Semaphore acquired by a thread\n");
}

void semaphore_post(Semaphore *sem) {
    if (!sem) return;

    pthread_mutex_lock(&sem->mutex);
    sem_post(&sem->sem);
    pthread_mutex_unlock(&sem->mutex);

    printf("Semaphore released, current value: %d\n", (int)(sem_getvalue(&sem->sem, NULL)));
}

void delete_semaphore(Semaphore *sem) {
    if (!sem) return;

    pthread_mutex_lock(&sem->mutex);

    sem_destroy(&sem->sem);
    pthread_mutex_unlock(&sem->mutex);

    free(sem);
    printf("Semaphore deleted\n");
}

int main() {
    Semaphore *sem = init_semaphore(1, 5); // Initialize semaphore with initial count of 1 and max value of 5

    if (!sem) return EXIT_FAILURE;

    resize_semaphore(sem, 10);  // Resize semaphore to have a max value of 10

    pthread_t thread;
    pthread_create(&thread, NULL, (void *(*)(void *)) semaphore_wait, sem);

    sleep(1); // Simulate delay before releasing

    semaphore_post(sem);

    pthread_join(thread, NULL);

    delete_semaphore(sem);

    return EXIT_SUCCESS;
}
```']

