#include <mutex>
#include <chrono>

std::mutex mtx; // Global mutex for thread safety

void updateOrInsertCounter(std::vector<std::pair<std::string, int>>& counterList,
                           const std::string& key,
                           std::chrono::time_point<std::chrono::system_clock> timestamp = std::chrono::system_clock::now()) {
    std::lock_guard<std::mutex> lock(mtx); // Ensure thread safety

    for (auto& pair : counterList) {
        if (pair.first == key) {
            ++pair.second;
            return;  // Exit after updating the found key
        }
    }

    // If key not found, insert a new pair with value 1
    counterList.emplace_back(key, 1);
}
