public class StateLoader {

    private static final String DEFAULT_THEME_DIRECTORY = "/default/theme/directory";
    private File defaultThemeDirectory;
    private Bitmap themeBitmap; // Assume Bitmap is a placeholder for an actual bitmap object
    private final ReentrantLock lock = new ReentrantLock();

    public StateLoader() {
        setDefaultThemeDirectory();
    }

    private void setDefaultThemeDirectory() {
        if (defaultThemeDirectory == null || !defaultThemeDirectory.exists()) {
            defaultThemeDirectory = new File(DEFAULT_THEME_DIRECTORY);
            if (!defaultThemeDirectory.exists()) {
                boolean created = defaultThemeDirectory.mkdirs();
                if (!created) {
                    throw new RuntimeException("Failed to create default theme directory.");
                }
            }
        }
    }

    public Object loadState(String filePath) {
        ObjectInputStream ois = null;
        try {
            ois = new ObjectInputStream(new FileInputStream(filePath));
            Object object = ois.readObject();
            if (object instanceof MoSTState) {
                return object;
            }
            return null;
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace(); // Log exception appropriately
        } finally {
            try {
                if (ois != null) {
                    ois.close();
                }
            } catch (IOException e) {
                e.printStackTrace(); // Log exception appropriately
            }
        }
        return null;
    }

    public void cacheTheme(Bitmap newThemeBitmap) {
        lock.lock();
        try {
            if (themeBitmap != null && !newThemeBitmap.equals(themeBitmap)) {
                themeBitmap.recycle();
            }
            themeBitmap = newThemeBitmap;
        } finally {
            lock.unlock();
        }
    }

    public Bitmap getTheme() {
        lock.lock();
        try {
            return themeBitmap;
        } finally {
            lock.unlock();
        }
    }

    public void clearThemeCache() {
        lock.lock();
        try {
            if (themeBitmap != null) {
                themeBitmap.recycle();
                themeBitmap = null;
            }
        } finally {
            lock.unlock();
        }
    }
}

