### 2. Rate Limiting for Login Attempts

Implement rate limiting using a custom middleware and a cache store (e.g., Redis).

```csharp
// Install necessary packages via NuGet:
// Microsoft.Extensions.Caching.StackExchangeRedis

public class RateLimitMiddleware
{
    private readonly RequestDelegate _next;
    private readonly IDistributedCache _cache;

    public RateLimitMiddleware(RequestDelegate next, IDistributedCache cache)
    {
        _next = next;
        _cache = cache;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        var ipAddress = context.Connection.RemoteIpAddress?.ToString();
        if (string.IsNullOrEmpty(ipAddress)) return;

        var key = $"login_attempts:{ipAddress}";
        var attempts = await _cache.GetStringAsync(key);

        if (!string.IsNullOrEmpty(attempts) && int.Parse(attempts) >= 10)
        {
            context.Response.StatusCode = StatusCodes.Status429TooManyRequests;
            await context.Response.WriteAsync("Rate limit exceeded. Try again later.");
            return;
        }

        await _next(context);

        if (context.Response.StatusCode == StatusCodes.Status200OK || 
            context.Response.StatusCode == StatusCodes.Status401Unauthorized)
        {
            var attemptsValue = string.IsNullOrEmpty(attempts) ? 1 : int.Parse(attempts) + 1;
            await _cache.SetStringAsync(key, attemptsValue.ToString(), new DistributedCacheEntryOptions
            {
                AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(15),
                SlidingExpiration = TimeSpan.FromMinutes(5)
            });
        }
    }
}

// Register middleware in Startup.cs
public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
{
    // Other configurations...
    app.UseMiddleware<RateLimitMiddleware>();
}
```

