      try {
        const module = require(this.modulePath);

        if (typeof module.tests !== 'function') {
          throw new Error('Module does not export a `tests` function');
        }

        resolve(module.tests());
      } catch (error) {
        console.error(`Failed to load tests for module ${this.modulePath}:`, error.message);
        reject(error);
      }
    });
  }

  runSingleTest(test, attempt = 1) {
    return new Promise((resolve, reject) => {
      const testProcess = fork(path.resolve(__dirname, 'testRunner.js'), [
        JSON.stringify({
          testName: test.name,
          testFunction: test.fn.toString(),
          config: this.config
        })
      ]);

      let result;

      testProcess.on('message', (message) => {
        result = message;
        console.log(`Test ${test.name}:`, result.status);
      });

      testProcess.on('error', (error) => {
        reject(error);
      });

      testProcess.on('exit', (code) => {
        if (code === 0) {
          this.resetMockingLibrary();
          resolve(result);
        } else if (attempt <= this.retryLimit) {
          console.log(`Retrying test ${test.name} (Attempt ${attempt + 1})`);
          return resolve(this.runSingleTest(test, attempt + 1));
        } else {
          reject(new Error(`Test ${test.name} failed after ${this.retryLimit} attempts`));
        }
      });

      this.updateSharedState(test.name);
    });
  }

  resetMockingLibrary() {
    // Reset the mocking library to a known state
    require('blueslip').reset();
    console.log('Blueslip library has been reset');
  }

  updateSharedState(testName) {
    // Log and manage shared state changes
    this.sharedState[testName] = { status: 'running' };
    console.log(`Shared State Updated for ${testName}:`, JSON.stringify(this.sharedState));
  }
}

// Usage:
// (example usage, actual configuration would be different)
const orchestrator = new TestOrchestrator('./path/to/module', {
  retryLimit: 3,
  environment: 'development'
});
orchestrator.runTests().catch(console.error);
```

