// Define a class for handling entity extraction logic
class EntityExtractor {
    constructor(entities) {
        this.entities = new Set(entities.map(entity => entity.toLowerCase()));
    }

    // Function to clean and normalize text, ignoring punctuation and special characters
    normalizeText(text) {
        return text.replace(/[^a-zA-Z\s]/g, '').toLowerCase();
    }

    // Check if a word or sequence of words is an entity of interest
    containsEntity(wordsArray) {
        for (let i = 0; i < wordsArray.length; i++) {
            let combinedWord = '';
            for (let j = i; j < Math.min(i + 3, wordsArray.length); j++) { // Check up to trigrams
                if (combinedWord) combinedWord += ' ';
                combinedWord += wordsArray[j];
                if (this.entities.has(combinedWord)) {
                    return true;
                }
            }
        }
        return false;
    }

    extractEntities(pageText) {
        const normalizedText = this.normalizeText(pageText);
        const wordsArray = normalizedText.split(/\s+/);
        const extractedEntities = {};

        for (let i = 0; i < wordsArray.length; i++) {
            if (this.containsEntity(wordsArray.slice(i))) {
                let entity = '';
                for (let j = i; j < Math.min(i + 3, wordsArray.length); j++) { // Check up to trigrams
                    if (entity) entity += ' ';
                    entity += wordsArray[j];
                    if (this.entities.has(entity)) {
                        break;
                    }
                }

                extractedEntities[entity] = (extractedEntities[entity] || 0) + 1;
            }
        }

        return extractedEntities;
    }
}

// Main function to process all pages and count entity occurrences
function processDocument(pages, entitiesOfInterest) {
    const extractor = new EntityExtractor(entitiesOfInterest);
    const totalCounts = {};

    for (const pageText of pages) {
        const pageCounts = extractor.extractEntities(pageText);

        // Aggregate counts from the current page
        for (const [entity, count] of Object.entries(pageCounts)) {
            if (entitiesOfInterest.includes(entity.toLowerCase())) { // Ensure entity is valid
                totalCounts[entity] = (totalCounts[entity] || 0) + count;
            }
        }
    }

    return totalCounts;
}

// Example usage:
const pages = [
    "General Lee commanded the Confederate forces during the Battle of Gettysburg.",
    "Ulysses S. Grant was a key figure in winning the Civil War for the Union."
];
const entitiesOfInterest = ["general lee", "ulysses s. grant", "battle of gettysburg"];

console.log(processDocument(pages, entitiesOfInterest));
```

This code defines an `EntityExtractor` class responsible for handling entity extraction logic and a main function `processDocument` that processes multiple pages to count occurrences of specified entities. The approach is designed to handle varying text lengths efficiently while being flexible enough to update the list of entities easily.']

['```javascript
function renderFooterScripts(scripts, renderCritical) {
    if (!Array.isArray(scripts)) return '';

    const validTypes = new Set([
        "text/javascript",
        "module",
        "application/javascript",
        "text/ecmascript"
    ]);

    // Sort scripts by dependencies and priority
    scripts.sort((a, b) => (a.dependencyOrder || 0) - (b.dependencyOrder || 0));

    const renderScript = ({ src, async = false, defer = false, type = "", priority = "" }) => {
        if (!validTypes.has(type)) {
            console.error(`Invalid script type: ${type}`);
            return '';
        }

        let attributes = `src="${src}"`;
        if (async) attributes += ' async';
        if (defer) attributes += ' defer';
        if (type) attributes += ` type="${type}"`;

        return `<script${attributes}></script>`;
    };

    const filteredScripts = scripts.filter(script => {
        if (!renderCritical && script.priority === "critical") return false;
        return renderCritical ? script.priority === "critical" : true;
    });

    // Defer non-critical scripts by default for performance
    const finalScripts = filteredScripts.map(script => {
        if (script.priority !== 'critical') script.defer = true;
        return renderScript(script);
    }).filter(Boolean);

    return finalScripts.join('');
}
```

This function handles the rendering of `<script>` tags from an array of script objects, considering priority, dependencies, and valid types. It ensures scripts are rendered in the correct order and defers non-critical scripts for performance optimization. Invalid types are logged as errors but do not halt processing.']

