angular.module('dialogApp', [])
  .controller('DialogController', ['$scope', '$window', function($scope, $window) {
    const DEFAULT_PLACEHOLDER = 'Data Not Available';

    function fetchAndUpdateField(resourceId, url, fieldNames, timeout) {
      let retryCount = 0;
      const maxRetries = 3;

      function fetchData(field, attempt) {
        return new Promise((resolve, reject) => {
          $window.fetch(url + `?resourceId=${resourceId}&fieldName=${field}`)
            .then(response => response.json())
            .then(data => resolve({ field, data }))
            .catch(error => {
              if (attempt < maxRetries) {
                const delay = Math.pow(2, attempt) * 100; // Exponential backoff
                setTimeout(() => fetchData(field, attempt + 1), delay);
              } else {
                reject(new Error(`Failed to fetch data for field: ${field}`));
              }
            });
        });
      }

      function updateFieldInList(field, data) {
        const dialogElement = $scope.forwardList.find(el => el.name === field);
        if (dialogElement) {
          dialogElement.value = data;
        } else {
          console.error(`Field not found: ${field}`);
        }
      }

      Promise.allSettled(fieldNames.map(field => fetchData(field, retryCount)))
        .then(results => {
          results.forEach(result => {
            if (result.status === 'fulfilled') {
              updateFieldInList(result.value.field, result.value.data);
            } else {
              const dialogElement = $scope.forwardList.find(el => el.name === result.reason.message.split(':')[1]);
              if (dialogElement) {
                dialogElement.value = DEFAULT_PLACEHOLDER;
              }
            }
          });
        })
        .catch(error => console.error(`Error: ${error.message}`));

      setTimeout(() => {
        const parentMessage = { type: 'dataFetchComplete', resourceId };
        try {
          $window.parent.postMessage(parentMessage, '*');
        } catch (e) {
          console.error('Failed to post message to parent window:', e);
        }
      }, timeout);
    }

    // Example usage
    $scope.forwardList = [
      { name: 'field1', value: '' },
      { name: 'field2', value: '' },
      // Add more fields as needed
    ];

    $scope.updateDialogFields = function(resourceId, url, fieldNames, timeout) {
      fetchAndUpdateField(resourceId, url, fieldNames, timeout);
    };
  }]);
