import java.util.List;
import java.util.concurrent.*;
import java.util.logging.*;

public class ServiceManager {

    private static final int MAX_INSTANCES = 50;
    private ExecutorService executorService;
    private List<ServiceInstance> activeInstances;
    private Logger logger;

    public ServiceManager() {
        this.logger = Logger.getLogger(ServiceManager.class.getName());
        this.activeInstances = new CopyOnWriteArrayList<>();
        this.executorService = Executors.newFixedThreadPool(MAX_INSTANCES);
        setupLogger();
    }

    private void setupLogger() {
        try {
            FileHandler fileHandler = new FileHandler("service_manager.log", true);
            SimpleFormatter formatter = new SimpleFormatter();
            fileHandler.setFormatter(formatter);
            logger.addHandler(fileHandler);
            logger.setLevel(Level.ALL);
        } catch (IOException e) {
            System.err.println("Failed to set up logger: " + e.getMessage());
        }
    }

    public void startService() {
        if (activeInstances.size() < MAX_INSTANCES) {
            ServiceInstance instance = new ServiceInstance();
            activeInstances.add(instance);
            executorService.submit(() -> {
                try {
                    long startTime = System.currentTimeMillis();
                    int successfulCompletions = instance.processTasks();
                    long endTime = System.currentTimeMillis();

                    double totalProcessingTime = (endTime - startTime) / 1000.0;
                    double averageProcessingTime = totalProcessingTime / successfulCompletions;

                    logger.info("Service Instance Stopped: Total Time=" + totalProcessingTime +
                            ", Average Time=" + averageProcessingTime +
                            ", Successful Completions=" + successfulCompletions);

                    sendMetricsToDashboard(totalProcessingTime, averageProcessingTime, successfulCompletions);
                } catch (Exception e) {
                    logger.log(Level.SEVERE, "Error in service instance", e);
                }
            });
        } else {
            logger.warning("Maximum instances already running.");
        }
    }

    public void stopService(ServiceInstance instance) {
        activeInstances.remove(instance);
        logger.info("Service Instance Stopped: ID=" + instance.getId());
    }

    private void sendMetricsToDashboard(double totalProcessingTime, double averageProcessingTime, int successfulCompletions) {
        // Implement integration with external analytics dashboard
    }

    public void adjustMaxInstances(int newMaxInstances) {
        if (newMaxInstances < 1 || newMaxInstances > 100) { // Assumed max limit for illustration
            logger.warning("Invalid max instances value: " + newMaxInstances);
            return;
        }

        this.MAX_INSTANCES = newMaxInstances;

        while (activeInstances.size() > MAX_INSTANCES) {
            ServiceInstance instanceToStop = activeInstances.remove(activeInstances.size() - 1);
            stopService(instanceToStop);
        }

        logger.info("Adjusted maximum instances to: " + MAX_INSTANCES);
    }

    public static void main(String[] args) {
        ServiceManager manager = new ServiceManager();

        // Simulate dynamic load conditions
        for (int i = 0; i < 10; i++) {
            manager.startService();
        }

        // Adjust the max instances based on external configuration management input
        manager.adjustMaxInstances(30);
    }

    private static class ServiceInstance {
        private final int id;
        private static int counter;

        public ServiceInstance() {
            this.id = ++counter;
        }

        public int getId() {
            return id;
        }

        public int processTasks() throws InterruptedException {
            // Simulate processing tasks
            Thread.sleep((long) (Math.random() * 1000));
            return new Random().nextInt(10); // Simulated successful completions count
        }
    }
}
