```rust
use reqwest::{Client, Method, Response, Error};
use std::collections::HashMap;
use tokio::sync::RwLock;
use log::{info, error};

struct HttpClientConfig {
    base_url: String,
    headers: HashMap<String, String>,
}

#[derive(Clone)]
pub struct HttpClient {
    client: Client,
    config: RwLock<HttpClientConfig>,
}

impl HttpClient {
    pub fn new(base_url: &str) -> Self {
        let mut headers = HashMap::new();
        headers.insert("User-Agent".to_string(), "Rust-HTTP-Client/1.0".to_string());

        let client = ClientBuilder::new()
            .danger_accept_invalid_certs(true)
            .build()
            .expect("Failed to build HTTP client");

        HttpClient {
            client,
            config: RwLock::new(HttpClientConfig {
                base_url: base_url.to_string(),
                headers,
            }),
        }
    }

    pub async fn send_request(
        &self,
        method: Method,
        path: &str,
        body: Option<String>,
    ) -> Result<Response, Error> {
        let config = self.config.read().await;

        info!("Sending request to {:?} {}", method, path);

        let mut request_builder = self.client.request(method, format!("{}/{}", config.base_url, path));

        for (key, value) in &config.headers {
            request_builder = request_builder.header(key.clone(), value);
        }

        if let Some(body_content) = body {
            info!("Request body: {}", body_content);
            request_builder = request_builder.body(body_content);
        }

        let response = request_builder.send().await?;

        info!(
            "Received response with status: {}",
            response.status()
        );

        Ok(response)
    }

    pub async fn update_config(&self, base_url: Option<String>, headers: HashMap<String, String>) {
        let mut config = self.config.write().await;

        if let Some(new_base_url) = base_url {
            config.base_url = new_base_url;
        }

        config.headers = headers;

        info!("Configuration updated");
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    env_logger::init();

    let client = HttpClient::new("https://api.example.com");

    // Example GET request
    let _response = client.send_request(Method::GET, "resource", None).await?;

    // Update configuration dynamically
    let mut new_headers = HashMap::new();
    new_headers.insert("Authorization".to_string(), "Bearer token123".to_string());

    client.update_config(Some("https://api.newdomain.com".to_string()), new_headers).await;

    Ok(())
}
```

### Key Features:
- **Configurable Headers and Base URL**: The `HttpClient` struct allows for dynamic updates to headers and base URL.
- **Certificate Validation**: Configured with `.danger_accept_invalid_certs(true)` for development purposes. Change as needed for production.
- **Logging Integration**: Uses the `log` crate for tracing requests and responses.
- **Connection Pooling**: Utilizes `reqwest`'s built-in connection pooling.

### Considerations:
- Ensure that certificate validation is properly handled in production environments.
- Test under load to ensure performance meets your application's needs, especially when handling high concurrency.
- Regularly review logs for errors or unusual activity, particularly if integrating with third-party services.']

