```javascript
const crypto = require('crypto');
const fs = require('fs').promises;
const { promisify } = require('util');

function generateSecureRandomString(length, charSet) {
    let randomString = '';
    const maxIndex = charSet.length - 1;
    for (let i = 0; i < length; i++) {
        randomString += charSet[Math.floor(Math.random() * maxIndex)];
    }
    return randomString;
}

async function hashPassword(password, algorithm = 'sha256') {
    try {
        const salt = crypto.randomBytes(16).toString('hex');
        switch (algorithm.toLowerCase()) {
            case 'bcrypt':
                return await promisify(crypto.pbkdf2)(password, salt, 100000, 64, 'sha512').then(hash => `${algorithm}$${salt}$${hash.toString('hex')}`);
            default:
                return crypto.createHash(algorithm).update(password + salt).digest('hex');
        }
    } catch (error) {
        logError(`Hashing failed: ${error.message}`);
        throw new Error('Failed to hash password.');
    }
}

async function readFileAsync(filePath, timeout = 5000) {
    const start = Date.now();

    try {
        const fileContents = await promisify(fs.readFile)(filePath, 'utf8');
        logPerformanceMetrics(`File read completed in ${Date.now() - start} milliseconds.`);
        return fileContents;
    } catch (error) {
        if ((Date.now() - start) > timeout) {
            logError(`Timeout reached after ${timeout / 1000} seconds while reading the file: ${error.message}`);
            throw new Error('File read operation timed out.');
        }

        logError(`Failed to read file: ${error.message}`);
        throw error;
    }
}

function logError(message) {
    // Implement logging to a centralized service here
    console.error(message);  // Example: Basic console logging
}

function logPerformanceMetrics(metrics) {
    // Implement performance metrics logging to a centralized service here
    console.log(metrics);  // Example: Basic console logging
}
