["```javascript
const fs = require('fs');
const path = require('path');
const { Readable } = require('stream');
const axios = require('axios');

class StreamCollector extends Readable {
  constructor(options) {
    super(options);
    this.dataChunks = [];
    this.isPaused = false;
  }

  _read() {}

  pushData(chunk) {
    if (!this.isPaused) {
      this.push(chunk);
    } else {
      this.dataChunks.push(chunk);
    }
  }

  pauseCollection() {
    this.isPaused = true;
  }

  resumeCollection() {
    this.isPaused = false;
    while (this.dataChunks.length > 0 && !this.isPaused) {
      this.push(this.dataChunks.shift());
    }
  }

  getCollectedData() {
    return Buffer.concat([...this.dataChunks, ...this._readableState.buffer]);
  }
}

async function retryAsyncOperation(operation, retries = 3, delay = 1000) {
  for (let attempt = 1; attempt <= retries; attempt++) {
    try {
      return await operation();
    } catch (error) {
      if (attempt === retries) throw error;
      await new Promise(res => setTimeout(res, delay));
    }
  }
}

async function readAndCombinePemFiles(oauthRequest) {
  const keyPath = path.join(oauthRequest.directoryPath, 'key.pem');
  const certPath = path.join(oauthRequest.directoryPath, 'cert.pem');

  async function readFile(filePath) {
    return fs.promises.readFile(filePath, { encoding: 'utf8' });
  }

  try {
    const [privateKey, certificate] = await Promise.all([
      retryAsyncOperation(() => readFile(keyPath)),
      retryAsyncOperation(() => readFile(certPath))
    ]);

    const combinedPemContent = privateKey + '\n\n' + certificate;
    const tempFilePath = path.join(process.cwd(), 'combined.pem');

    fs.writeFileSync(tempFilePath, combinedPemContent);
    return tempFilePath;
  } catch (error) {
    console.error('Error reading or combining PEM files:', error);
    throw new Error('Failed to process PEM files');
  }
}

async function handleStreamData(url) {
  const collector = new StreamCollector();
  let stream;

  async function fetchData() {
    try {
      const response = await axios({
        method: 'get',
        url,
        responseType: 'stream'
      });
      return response.data;
    } catch (error) {
      console.error('Error fetching data:', error);
      throw new Error('Failed to fetch stream data');
    }
  }

  retryAsyncOperation(async () => {
    stream = await fetchData();
    stream.on('data', chunk => collector.pushData(chunk));
    stream.on('end', () => collector.push(null));
  });

  return {
    pause: () => collector.pauseCollection(),
    resume: () => collector.resumeCollection(),
    getData: () => collector.getCollectedData()
  };
}

async function combineOAuthAndStream(oauthRequest, streamUrl) {
  try {
    const pemFilePath = await readAndCombinePemFiles(oauthRequest);
    console.log('Combined PEM file path:', pemFilePath);

    const streamHandler = await handleStreamData(streamUrl);

    // Example usage:
    setTimeout(() => {
      console.log('Pausing data collection...');
      streamHandler.pause();

      setTimeout(() => {
        console.log('Resuming data collection...');
        streamHandler.resume();

        setTimeout(() => {
          const collectedData = streamHandler.getData();
          console.log('Collected Data:', collectedData.toString());
        }, 2000);
      }, 5000);
    }, 3000);

  } catch (error) {
    console.error('An error occurred in combineOAuthAndStream:', error.message);
  }
}

module.exports = { combineOAuthAndStream };
