<?php

session_start();

function authenticateUser($clientId, $clientSecret, $authUrl, $userInfoUrl) {
    // Define trusted domains
    $trustedDomains = ['example.com', 'trusteddomain.org'];

    // Rate limiting setup (simple in-memory counter for demonstration)
    if (!isset($_SESSION['rate_limit'])) {
        $_SESSION['rate_limit'] = [];
    }

    // Check rate limit per client IP
    $clientIp = $_SERVER['REMOTE_ADDR'];
    $currentTime = time();
    $timeWindow = 60; // 1 minute window

    if (isset($_SESSION['rate_limit'][$clientIp])) {
        $requests = &$_SESSION['rate_limit'][$clientIp];
        foreach ($requests as $key => $value) {
            if ($currentTime - $value > $timeWindow) {
                unset($requests[$key]);
            }
        }

        if (count($requests) >= 5) { // Limit to 5 requests per minute
            return ['status' => 'error', 'message' => 'Rate limit exceeded'];
        }
    } else {
        $_SESSION['rate_limit'][$clientIp] = [];
    }

    $_SESSION['rate_limit'][$clientIp][] = $currentTime;

    try {
        // OAuth2 Token Request
        $ch = curl_init();
        curl_setopt($ch, CURLOPT_URL, $authUrl);
        curl_setopt($ch, CURLOPT_POST, 1);
        curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query([
            'grant_type' => 'client_credentials',
            'client_id' => $clientId,
            'client_secret' => $clientSecret
        ]));
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);

        // Handle network timeouts and errors
        curl_setopt($ch, CURLOPT_TIMEOUT, 5);
        curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, 5);

        $response = curl_exec($ch);
        $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);

        if ($httpCode != 200) {
            throw new Exception('OAuth2 Authentication failed.');
        }

        $data = json_decode($response, true);
        curl_close($ch);

        // Store the access token securely in session
        $_SESSION['access_token'] = $data['access_token'];

        // Retrieve User Information using Access Token
        $userInfoCh = curl_init();
        curl_setopt($userInfoCh, CURLOPT_URL, $userInfoUrl);
        curl_setopt($userInfoCh, CURLOPT_HTTPHEADER, [
            'Authorization: Bearer ' . $data['access_token']
        ]);
        curl_setopt($userInfoCh, CURLOPT_RETURNTRANSFER, true);

        // Handle network timeouts and errors
        curl_setopt($userInfoCh, CURLOPT_TIMEOUT, 5);
        curl_setopt($userInfoCh, CURLOPT_CONNECTTIMEOUT, 5);

        $userResponse = curl_exec($userInfoCh);
        $userInfoHttpCode = curl_getinfo($userInfoCh, CURLINFO_HTTP_CODE);
        curl_close($userInfoCh);

        if ($userInfoHttpCode != 200) {
            throw new Exception('Failed to retrieve user information.');
        }

        $userInfoData = json_decode($userResponse, true);

        // DNS resolution for registered domain name and IP address
        $domainName = $_SERVER['HTTP_HOST'];
        if (!in_array($domainName, $trustedDomains)) {
            return ['status' => 'error', 'message' => 'Unauthorized domain access.'];
        }

        $ipAddress = gethostbyname($domainName);
        if ($ipAddress == $domainName) { // Failed DNS resolution
            throw new Exception('DNS resolution error.');
        }

        return [
            'status' => 'success',
            'user_info' => $userInfoData,
            'domain' => $domainName,
            'ip_address' => $ipAddress
        ];

    } catch (Exception $e) {
        return ['status' => 'error', 'message' => $e->getMessage()];
    }
}

