<?php

use Psr\Log\LoggerInterface;
use GuzzleHttp\Client as HttpClient;
use Doctrine\DBAL\Connection;

class PasswordUpdater {
    private $dbConnection;
    private $logger;
    private $httpClient;
    private $identityProviderUrl;

    public function __construct(Connection $dbConnection, LoggerInterface $logger, string $identityProviderUrl) {
        $this->dbConnection = $dbConnection;
        $this->logger = $logger;
        $this->httpClient = new HttpClient();
        $this->identityProviderUrl = $identityProviderUrl;
    }

    public function updatePassword(int $userId, string $newPassword): bool {
        if (!$this->validatePasswordStrength($newPassword)) {
            $this->logger->warning("Password strength validation failed for user {$userId}.");
            return false;
        }

        try {
            // Begin distributed transaction
            $this->dbConnection->beginTransaction();

            // Update password in the primary database
            $stmt = $this->dbConnection->prepare('UPDATE users SET password_hash = ? WHERE id = ?');
            $hashedPassword = password_hash($newPassword, PASSWORD_BCRYPT);
            $stmt->execute([$hashedPassword, $userId]);

            // Ensure atomicity with external services
            if (!$this->updateExternalServices($userId, $hashedPassword)) {
                throw new \Exception("Failed to update external services.");
            }

            // Commit transaction
            $this->dbConnection->commit();

            // Log successful password update
            $this->logger->info("Password updated successfully for user {$userId}.");

        } catch (\Exception $e) {
            // Rollback in case of failure
            $this->dbConnection->rollBack();
            $this->logger->error("Password update failed for user {$userId}: " . $e->getMessage());

            return false;
        }

        return true;
    }

    private function validatePasswordStrength(string $password): bool {
        // Implement client-side and server-side validation rules
        return preg_match('/^(?=.*[A-Za-z])(?=.*\d)[A-Za-z\d]{8,}$/', $password);
    }

    private function updateExternalServices(int $userId, string $hashedPassword): bool {
        try {
            $response = $this->httpClient->post($this->identityProviderUrl . '/update-password', [
                'json' => ['user_id' => $userId, 'hashed_password' => $hashedPassword]
            ]);

            return $response->getStatusCode() === 200;
        } catch (\Exception $e) {
            // Handle transient failures and retries
            $this->logger->warning("Transient failure while updating external services for user {$userId}: " . $e->getMessage());
            return false;
        }
    }

    public function setup2FA(int $userId): bool {
        try {
            $response = $this->httpClient->post($this->identityProviderUrl . '/setup-2fa', [
                'json' => ['user_id' => $userId]
            ]);

            return $response->getStatusCode() === 200;
        } catch (\Exception $e) {
            $this->logger->error("Failed to setup 2FA for user {$userId}: " . $e->getMessage());
            return false;
        }
    }

    public function monitorPerformance(): void {
        // Implement metrics and monitoring logic
        $metrics = [
            'passwordUpdateAttempts' => 0,
            'successfulUpdates' => 0,
            'failedUpdates' => 0,
        ];

        // Example metric collection
        $metrics['passwordUpdateAttempts']++;
        if ($this->updatePassword(123, 'newSecureP@ssw0rd')) {
            $metrics['successfulUpdates']++;
        } else {
            $metrics['failedUpdates']++;
        }

        // Log or send metrics to a monitoring service
        $this->logger->info("Performance Metrics: " . json_encode($metrics));
    }
}

```

