#define MAX_PACKET_SIZE 1500
#define SLIDING_WINDOW_MS 50

typedef struct {
    size_t packet_size;
    int priority_score;
    uint64_t timestamp; // Use for sliding window management
} Packet;

typedef struct {
    Packet packets[100]; // Buffer to hold packets in the sliding window
    size_t count;
    pthread_mutex_t lock;
    uint64_t last_cleared_time;
} SlidingWindowMetrics;

// Simulated external packet logging service function
void log_packet_event(const Packet *packet);

// Function prototypes for utility functions
int calculate_priority_score(Packet *packet, int network_congestion);
bool should_log_packet(int current_network_utilization);

// Thread-safe function to process packets
void process_packet(Packet *packet, int network_congestion, int current_network_utilization) {
    static SlidingWindowMetrics metrics;

    pthread_mutex_lock(&metrics.lock);

    // Check if sliding window needs to be cleared based on time elapsed
    uint64_t now = clock();
    if (now - metrics.last_cleared_time >= SLIDING_WINDOW_MS * CLOCKS_PER_SEC / 1000) {
        // Clear old packets from the window
        size_t new_count = 0;
        for (size_t i = 0; i < metrics.count && packet[i].timestamp > now - SLIDING_WINDOW_MS * CLOCKS_PER_SEC / 1000; ++i) {
            if (new_count < sizeof(metrics.packets) / sizeof(Packet)) {
                metrics.packets[new_count++] = packet[i];
            }
        }
        metrics.count = new_count;
        metrics.last_cleared_time = now;
    }

    // Calculate priority score
    int priority_score = calculate_priority_score(packet, network_congestion);

    // Determine if the packet should be processed or logged
    bool process_packet = (packet->packet_size <= MAX_PACKET_SIZE && 
                           priority_score > 50); // Example threshold

    if (process_packet) {
        // Process packet logic here...

        // Add to sliding window metrics
        if (metrics.count < sizeof(metrics.packets) / sizeof(Packet)) {
            metrics.packets[metrics.count++] = *packet;
        }
    }

    // Log packet event during low network utilization periods
    if (process_packet && should_log_packet(current_network_utilization)) {
        log_packet_event(packet);
    }

    pthread_mutex_unlock(&metrics.lock);
}

// Example priority score calculation based on congestion and performance
int calculate_priority_score(Packet *packet, int network_congestion) {
    // Placeholder logic for priority computation
    return (MAX_PACKET_SIZE - packet->packet_size) + 100 - network_congestion;
}

// Check if the logging condition is met
bool should_log_packet(int current_network_utilization) {
    // Example: Log only when utilization is below a certain threshold
    return current_network_utilization < 30; 
}
