async function asyncReduce(array, initialAccumulator, callback, timeout = 5000) {
    const startTime = Date.now();

    return new Promise(async (resolve, reject) => {
        let accumulator = initialAccumulator;

        for (let i = 0; i < array.length; i++) {
            // Check for timeout
            if ((Date.now() - startTime) > timeout) {
                return reject(new Error("Operation timed out"));
            }

            const element = array[i];

            try {
                // Attempt to process each element with retry logic
                await attemptProcessElement(element, accumulator, callback);
                accumulator = await callback(accumulator, element);

            } catch (error) {
                return reject(new Error(`Error processing element at index ${i}: ${error.message}`));
            }
        }

        resolve(accumulator);
    });
}

async function attemptProcessElement(element, accumulator, callback, retries = 3) {
    try {
        await processElementWithRetry(element, retries);
        await callback(accumulator, element);
    } catch (error) {
        throw new Error(`Failed to process element: ${error.message}`);
    }
}

async function processElementWithRetry(element, retries) {
    while (retries > 0) {
        try {
            // Simulate processing with potential external service calls
            await simulateAsyncOperation();
            break; // Exit if successful
        } catch (error) {
            if (isTransientError(error)) {
                retries--;
                if (retries === 0) throw error;
