void processLine(char *line, int isLastFieldNumeric1, int isLastFieldNumeric2) {
    char *token, *lastToken1 = NULL, *lastToken2 = NULL, *outputBuffer = malloc(BUFFER_SIZE);
    if (!outputBuffer) exit(EXIT_FAILURE);

    token = strtok(line, " \t\n");
    while (token != NULL) {
        size_t len = strlen(outputBuffer);
        int appendComma = len > 0;

        if (isLastFieldNumeric1 && strcmp(token, lastToken2)) {
            sprintf(outputBuffer + len, "%s%s%d", appendComma ? "," : "", token, atoi(lastToken1));
        } else {
            sprintf(outputBuffer + len, "%s%s", appendComma ? "," : "", token);
        }

        if (isLastFieldNumeric1 && strcmp(token, lastToken2)) {
            isLastFieldNumeric1 = 0;
        }

        if (!isLastFieldNumeric1) {
            lastToken2 = lastToken1;
            lastToken1 = token;
        } else {
            lastToken1 = token;
        }

        token = strtok(NULL, " \t\n");
    }

    printf("%s\n", outputBuffer);
    free(outputBuffer);
}

void readAndProcessFile(const char *filePath) {
    FILE *file = fopen(filePath, "r");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", filePath);
        return;
    }

    char line[BUFFER_SIZE];
    while (fgets(line, BUFFER_SIZE, file)) {
        pthread_mutex_lock(&cacheManager.lock);

        int isLastFieldNumeric1 = 0, isLastFieldNumeric2 = 0;

        // Determine if the last two fields are numeric
        char *token = strtok(line + strlen(line) - BUFFER_SIZE, " \t\n");
        if (token && isdigit(token[0])) {
            isLastFieldNumeric2 = 1;
            token = strtok(NULL, " \t\n");
            if (token && isdigit(token[0])) {
                isLastFieldNumeric1 = 1;
            }
        }

        processLine(line, isLastFieldNumeric1, isLastFieldNumeric2);

        pthread_mutex_unlock(&cacheManager.lock);
    }

    fclose(file);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <file_path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    recycleBitmaps();
    setDefaultThemeDirectory("/default/theme/dir");

    readAndProcessFile(argv[1]);

    pthread_mutex_destroy(&cacheManager.lock);
    return 0;
}
