// Check if the character is a vowel
int is_vowel(char c) {
    char vowels[] = "aeiouAEIOU";
    for (int i = 0; i < sizeof(vowels) - 1; ++i) {
        if (c == vowels[i]) return 1;
    }
    return 0;
}

// Function to generate the new filename
char* process_filename(const char *filename) {
    // Validate and initialize variables
    if (!filename || strlen(filename) > MAX_PATH_LENGTH) {
        return "";
    }

    char *path = strdup(filename);
    char *base_name = strrchr(path, '/');
    base_name = base_name ? base_name + 1 : path;

    // Extract the extension
    char *ext = strrchr(base_name, '.');
    const char *extension_part = ext ? ext + 1 : "";
    const char *name_part = ext ? base_name : base_name;

    if (!validate_base_name(name_part)) {
        free(path);
        return "";
    }

    // Check for empty or special character-only base name
    int is_valid_name = 0;
    for (int i = 0; name_part[i]; ++i) {
        if ((name_part[i] >= 'a' && name_part[i] <= 'z') || 
            (name_part[i] >= 'A' && name_part[i] <= 'Z')) {
            is_valid_name = 1;
            break;
        }
    }

    if (!is_valid_name) {
        free(path);
        return "";
    }

    // Determine new file type
    char file_type[4];
    if (name_part[0]) {
        snprintf(file_type, sizeof(file_type), "%s", is_vowel(name_part[0]) ? "txt" : "log");
    } else {
        strcpy(file_type, "");
    }

    // Generate random digits based on the length of name part
    int num_digits = strlen(name_part);
    srand(time(NULL));
    char *random_digits = malloc(num_digits + 1);
    for (int i = 0; i < num_digits; ++i) {
        random_digits[i] = '0' + rand() % 10;
    }
    random_digits[num_digits] = '\0';

    // Construct the new filename
    char *new_filename = malloc(MAX_PATH_LENGTH + 1);
    if (!new_filename) {
        free(random_digits);
        free(path);
        return "";
    }

    int offset = snprintf(new_filename, MAX_PATH_LENGTH + 1, "%s.", name_part);
    offset += snprintf(new_filename + offset, MAX_PATH_LENGTH - offset + 1, "%s%s.%s", random_digits, file_type, extension_part);

    // Clean up
    free(random_digits);
    free(path);

    if (strlen(new_filename) > MAX_PATH_LENGTH) {
        new_filename[0] = '\0';
    }

    return new_filename;
}

// Example usage
int main() {
    const char *original_filename = "/path/to/file.name.ext";
    char *new_filename = process_filename(original_filename);

    if (*new_filename) {
        printf("New filename: %s\n", new_filename);
    } else {
        printf("Failed to generate a valid new filename.\n");
    }

    free(new_filename); // Remember to free the allocated memory
    return 0;
}
