#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>
#include <openssl/evp.h>
#include <openssl/rsa.h>
#include <openssl/pem.h>
#include <openssl/md5.h>
#include <openssl/sha.h>

#define CONFIG_FILE "crypto_config.json"

typedef enum {
    AES,
    CAMELLIA,
    MD5,
    SHA256,
    RSA_SHA256
} CryptoAlgorithm;

typedef struct {
    char *name;
    void (*encrypt)(const unsigned char *, int, const unsigned char *, unsigned char *);
    void (*decrypt)(const unsigned char *, int, const unsigned char *, unsigned char *);
} CryptoPrimitive;

CryptoPrimitive crypto_primitives[] = {
    {"AES", NULL, NULL},
    {"Camellia", NULL, NULL},
    {"MD5", NULL, NULL},
    {"SHA256", NULL, NULL},
    {"RSA_SHA256", NULL, NULL}
};

void load_crypto_primitives(const char *config_file) {
    FILE *file = fopen(config_file, "r");
    if (!file) {
        perror("Failed to open config file");
        exit(EXIT_FAILURE);
    }

    // Parse the configuration file and dynamically load libraries
    // This is a placeholder for actual JSON parsing logic
    const char *aes_lib = "./libcrypto_aes.so";
    void *handle = dlopen(aes_lib, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Failed to load library: %s\n", dlerror());
        exit(EXIT_FAILURE);
    }

    crypto_primitives[AES].encrypt = dlsym(handle, "aes_encrypt");
    crypto_primitives[AES].decrypt = dlsym(handle, "aes_decrypt");

    if (!crypto_primitives[AES].encrypt || !crypto_primitives[AES].decrypt) {
        fprintf(stderr, "Failed to load functions: %s\n", dlerror());
        exit(EXIT_FAILURE);
    }

    fclose(file);
}

void aes_encrypt(const unsigned char *plaintext, int plaintext_len, const unsigned char *key,
                 unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        exit(EXIT_FAILURE);
    }

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL)) {
        fprintf(stderr, "Encryption initialization failed\n");
        exit(EXIT_FAILURE);
    }

    int len;
    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) {
        fprintf(stderr, "Encryption update failed\n");
        exit(EXIT_FAILURE);
    }
    int ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        fprintf(stderr, "Encryption finalization failed\n");
        exit(EXIT_FAILURE);
    }
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);
}

void aes_decrypt(const unsigned char *ciphertext, int ciphertext_len, const unsigned char *key,
                 unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        exit(EXIT_FAILURE);
    }

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL)) {
        fprintf(stderr, "Decryption initialization failed\n");
        exit(EXIT_FAILURE);
    }

    int len;
    if (1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        fprintf(stderr, "Decryption update failed\n");
        exit(EXIT_FAILURE);
    }
    int plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) {
        fprintf(stderr, "Decryption finalization failed\n");
        exit(EXIT_FAILURE);
    }
    plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx);
}

void md5_hash(const unsigned char *data, size_t length, unsigned char *md5sum) {
    MD5((unsigned char *)data, length, md5sum);
}

void sha256_hash(const unsigned char *data, size_t length, unsigned char *sha256sum) {
    SHA256((unsigned char *)data, length, sha256sum);
}

int rsa_generate_key(RSA **rsa, int bits) {
    BIGNUM *bn = BN_new();
    if (!BN_set_word(bn, RSA_F4)) {
        fprintf(stderr, "Error setting bn\n");
        return 0;
    }

    *rsa = RSA_new();
    if (!RSA_generate_key_ex(*rsa, bits, bn, NULL)) {
        fprintf(stderr, "Error generating RSA key\n");
        return 0;
    }

    BN_free(bn);
    return 1;
}

void rsa_encrypt(RSA *rsa, const unsigned char *plaintext, int plaintext_len,
                 unsigned char *ciphertext) {
    if (RSA_public_encrypt(plaintext_len, plaintext, ciphertext, rsa, RSA_PKCS1_OAEP_PADDING) <= 0) {
        fprintf(stderr, "Error encrypting data\n");
        exit(EXIT_FAILURE);
    }
}

void rsa_decrypt(RSA *rsa, const unsigned char *ciphertext, int ciphertext_len,
                 unsigned char *plaintext) {
    if (RSA_private_decrypt(ciphertext_len, ciphertext, plaintext, rsa, RSA_PKCS1_OAEP_PADDING) <= 0) {
        fprintf(stderr, "Error decrypting data\n");
        exit(EXIT_FAILURE);
    }
}

int main() {
    load_crypto_primitives(CONFIG_FILE);

    // Example usage
    unsigned char key[32] = { /* AES key */ };
    unsigned char plaintext[] = "This is a test.";
    unsigned char ciphertext[128];
    unsigned char decryptedtext[128];

    crypto_primitives[AES].encrypt(plaintext, strlen((char *)plaintext), key, ciphertext);
    crypto_primitives[AES].decrypt(ciphertext, sizeof(ciphertext), key, decryptedtext);

    printf("Original: %s\n", plaintext);
    printf("Decrypted: %s\n", decryptedtext);

    // MD5 and SHA256 usage
    unsigned char md5sum[MD5_DIGEST_LENGTH];
    unsigned char sha256sum[SHA256_DIGEST_LENGTH];

    md5_hash(plaintext, strlen((char *)plaintext), md5sum);
    sha256_hash(plaintext, strlen((char *)plaintext), sha256sum);

    // RSA usage
    RSA *rsa = NULL;
    if (rsa_generate_key(&rsa, 2048)) {
        unsigned char encrypted[256];
        rsa_encrypt(rsa, plaintext, strlen((char *)plaintext), encrypted);
        rsa_decrypt(rsa, encrypted, sizeof(encrypted), decryptedtext);
    }

    // Clean up
    RSA_free(rsa);

    return 0;
}
```

