// Initialize AES-256-CBC cipher with given password
EVP_CIPHER_CTX* initialize_aes_cipher(const char *password) {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[AES_256_KEY_LENGTH];
    unsigned char iv[AES_BLOCK_SIZE];

    // Generate a random IV
    if (!RAND_bytes(iv, sizeof(iv))) {
        fprintf(stderr, "Error generating random bytes for IV\n");
        return NULL;
    }

    // Use Argon2 as KDF (considered modern and secure)
    int ret = PKCS5_PBKDF2_HMAC(password, strlen(password),
                                NULL, 0,
                                10000, EVP_sha256(),
                                AES_256_KEY_LENGTH,
                                key);

    if (ret != 1) {
        fprintf(stderr, "Error deriving key using PBKDF2\n");
        return NULL;
    }

    // Create and initialize the cipher context
    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Unable to create cipher context\n");
        return NULL;
    }

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        fprintf(stderr, "Error initializing AES encryption\n");
        return NULL;
    }

    return ctx;
}

// Cleanup and release the cipher context
