#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define TIMEOUT_SECONDS 10

typedef struct {
    pid_t pid;
    int stdout_pipe[2];
    int stderr_pipe[2];
} Command;

void handle_sigchld(int sig) {
    while (waitpid(-1, NULL, WNOHANG) > 0);
}

int execute_command(const char* cmd, const char* stdout_log, const char* stderr_log) {
    Command command;
    if (pipe(command.stdout_pipe) < 0 || pipe(command.stderr_pipe) < 0) {
        perror("Pipe creation failed");
        return -1;
    }

    command.pid = fork();
    if (command.pid < 0) {
        perror("Fork failed");
        close(command.stdout_pipe[0]);
        close(command.stdout_pipe[1]);
        close(command.stderr_pipe[0]);
        close(command.stderr_pipe[1]);
        return -1;
    } else if (command.pid == 0) {
        dup2(command.stdout_pipe[1], STDOUT_FILENO);
        dup2(command.stderr_pipe[1], STDERR_FILENO);

        close(command.stdout_pipe[0]);
        close(command.stdout_pipe[1]);
        close(command.stderr_pipe[0]);
        close(command.stderr_pipe[1]);

        execlp("sh", "sh", "-c", cmd, (char *)NULL);
        perror("Exec failed");
        exit(EXIT_FAILURE);
    }

    close(command.stdout_pipe[1]);
    close(command.stderr_pipe[1]);

    int stdout_fd = open(stdout_log, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    int stderr_fd = open(stderr_log, O_WRONLY | O_CREAT | O_TRUNC, 0644);

    if (stdout_fd < 0 || stderr_fd < 0) {
        perror("Failed to open log files");
        return -1;
    }

    struct sigaction sa;
    sa.sa_handler = handle_sigchld;
    sa.sa_flags = SA_RESTART | SA_NOCLDSTOP;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGCHLD, &sa, NULL) == -1) {
        perror("Error setting signal handler");
        return -1;
    }

    clock_t start_time = clock();
    int status = 0;

    while (1) {
        int wpid = waitpid(command.pid, &status, WNOHANG);
        if (wpid > 0) break; // Process has finished

        ssize_t bytes_read_stdout, bytes_read_stderr;
        char buffer[4096];

        do {
            bytes_read_stdout = read(command.stdout_pipe[0], buffer, sizeof(buffer));
            if (bytes_read_stdout > 0) write(stdout_fd, buffer, bytes_read_stdout);
        } while (bytes_read_stdout > 0);

        do {
            bytes_read_stderr = read(command.stderr_pipe[0], buffer, sizeof(buffer));
            if (bytes_read_stderr > 0) write(stderr_fd, buffer, bytes_read_stderr);
        } while (bytes_read_stderr > 0);

        clock_t current_time = clock();
        double elapsed_time = ((double)(current_time - start_time)) / CLOCKS_PER_SEC;
        if (elapsed_time >= TIMEOUT_SECONDS) {
            kill(command.pid, SIGKILL);
            waitpid(command.pid, NULL, 0); // Ensure cleanup
            close(stdout_fd);
            close(stderr_fd);
            return -1; // Timeout occurred
        }

        usleep(100000); // Sleep for 100ms to prevent busy waiting
    }

    close(stdout_fd);
    close(stderr_fd);

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        return 0; // Success
    } else {
        return -1; // Failure
    }
}
