public class WebsiteManager
{
    private const int TimeoutDuration = 30000; // 30 seconds for example
    private const string WebConfigTemplate = @"
        <?xml version='1.0' encoding='utf-8'?>
        <configuration>
            <system.webServer>
                <defaultDocument>
                    <files>
                        <clear />
                        <add value='index.html'/>
                    </files>
                </defaultDocument>
            </system.webServer>
        </configuration>";

    public async Task<string> AddAndStartWebsite(string directoryPath, Action<bool> onStartupComplete)
    {
        try
        {
            // Validate and create the directory if necessary
            string fullPath = Path.GetFullPath(directoryPath);
            Directory.CreateDirectory(fullPath);

            // Check for web.config file
            string webConfigPath = Path.Combine(fullPath, "web.config");
            if (!File.Exists(webConfigPath))
            {
                File.WriteAllText(webConfigPath, WebConfigTemplate);
            }

            // Integrate with external resource availability service (mocked here)
            bool resourcesAvailable = await CheckResourcesAvailabilityAsync();
            int retryCount = 0;
            const int MaxRetries = 3;

            while (!resourcesAvailable && retryCount < MaxRetries)
            {
                await Task.Delay(1000); // Wait before retrying
                resourcesAvailable = await CheckResourcesAvailabilityAsync();
                retryCount++;
            }

            if (!resourcesAvailable)
            {
                Console.WriteLine("Resource availability check failed.");
                onStartupComplete(false);
                return "Failed: Resource Availability";
            }

            // Start website in non-blocking manner with timeout handling
            CancellationTokenSource cts = new CancellationTokenSource(TimeoutDuration);

            Task.Run(async () =>
            {
                try
                {
                    ProcessStartInfo psi = new ProcessStartInfo("cmd.exe")
                    {
                        Arguments = $"/c iisexpress /path:{fullPath}",
                        RedirectStandardOutput = true,
                        UseShellExecute = false,
                        CreateNoWindow = true
                    };

                    using (Process process = new Process { StartInfo = psi })
                    {
                        process.Start();

                        // Wait for the startup with cancellation support
                        await Task.WhenAny(process.WaitForExitAsync(cts.Token), Task.Delay(TimeoutDuration, cts.Token));

                        if (!process.HasExited)
                        {
                            process.Kill(); // Forcefully kill the process if it hasn't exited
                            Console.WriteLine("Startup timed out.");
                        }

                        onStartupComplete(process.ExitCode == 0);
                    }
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error during startup: {ex.Message}");
                    onStartupComplete(false);
                }
            }, cts.Token).Wait();

            return "Success";
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
            return $"Error: {ex.Message}";
        }
    }

    private async Task<bool> CheckResourcesAvailabilityAsync()
    {
        // Mock implementation for resource availability check
        await Task.Delay(500); // Simulate async work

        // Implement actual checks here (e.g., checking ports, environment variables)
        return true;
    }

    public void StopWebsite()
    {
        Process.Start("cmd.exe", "/c iisexpress /stop");
    }
}
