['```java
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class FileProcessingPipeline {

    private static final Logger logger = Logger.getLogger(FileProcessingPipeline.class.getName());
    private final ExecutorService executorService;

    public FileProcessingPipeline() {
        this.executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    }

    public void processDirectories(Path sourceDir, Path targetDir) {
        try {
            Files.createDirectories(targetDir);
            Map<String, List<Path>> filesByType = new HashMap<>();

            // Collect files by type
            Files.walk(sourceDir)
                .filter(Files::isRegularFile)
                .forEach(file -> {
                    String extension = getFileExtension(file);
                    if (extension != null) {
                        filesByType.computeIfAbsent(extension, k -> new ArrayList<>()).add(file);
                    }
                });

            // Backup target directory state
            Path backupDir = targetDir.resolve("backup");
            Files.createDirectories(backupDir);

            // Process each file type in parallel
            for (Map.Entry<String, List<Path>> entry : filesByType.entrySet()) {
                executorService.submit(() -> processFileType(entry.getKey(), entry.getValue(), sourceDir, targetDir, backupDir));
            }

        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error processing directories", e);
        }
    }

    private void processFileType(String fileType, List<Path> files, Path sourceDir, Path targetDir, Path backupDir) {
        Path typeDir = targetDir.resolve(fileType.substring(1)); // Remove leading dot
        try {
            Files.createDirectories(typeDir);

            for (Path file : files) {
                Path destFile = typeDir.resolve(sourceDir.relativize(file).toString());
                if (!Files.exists(destFile)) {
                    Files.copy(file, destFile);
                }
            }

            executeCommandForFileType(fileType, typeDir);
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Failed to process files of type: " + fileType, e);
            revertChanges(backupDir, targetDir);
            throw new RuntimeException("Processing failed for file type: " + fileType, e);
        }
    }

    private String getFileExtension(Path path) throws IOException {
        String fileName = path.getFileName().toString();
        int dotIndex = fileName.lastIndexOf('.');
        return (dotIndex != -1) ? fileName.substring(dotIndex) : null;
    }

    private void executeCommandForFileType(String fileType, Path typeDir) {
        // Simulate command execution
        try {
            ProcessBuilder processBuilder = new ProcessBuilder("echo", "Processing files of type: " + fileType);
            processBuilder.directory(typeDir.toFile());
            Process process = processBuilder.start();
            int exitCode = process.waitFor();
            if (exitCode != 0) {
                throw new IOException("Command execution failed for file type: " + fileType);
            }
        } catch (IOException | InterruptedException e) {
            logger.log(Level.SEVERE, "Failed to execute command for file type: " + fileType, e);
            throw new RuntimeException(e);
        }
    }

    private void revertChanges(Path backupDir, Path targetDir) throws IOException {
        Files.walk(targetDir)
            .filter(Files::isRegularFile)
            .forEach(file -> {
                try {
                    if (!file.equals(targetDir.resolve("backup"))) {
                        Files.move(file, backupDir.resolve(targetDir.relativize(file).toString()));
                    }
                } catch (IOException e) {
                    logger.log(Level.SEVERE, "Failed to revert file: " + file, e);
                }
            });

        // Cleanup
        try {
            Files.walk(backupDir)
                .sorted((a, b) -> -Files.compare(a, b))
                .forEach(file -> {
                    try {
                        if (!file.equals(backupDir)) {
                            Files.delete(file);
                        }
                    } catch (IOException e) {
                        logger.log(Level.SEVERE, "Failed to delete backup file: " + file, e);
                    }
                });
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error cleaning up backups", e);
        }
    }

    public void shutdown() {
        executorService.shutdown();
    }

    public static void main(String[] args) {
        FileProcessingPipeline pipeline = new FileProcessingPipeline();

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            System.out.println("Enter source directory:");
            Path sourceDir = Paths.get(reader.readLine().trim());

            System.out.println("Enter target directory:");
            Path targetDir = Paths.get(reader.readLine().trim());

            pipeline.processDirectories(sourceDir, targetDir);
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error reading input", e);
        } finally {
            pipeline.shutdown();
        }
    }
}
```

This Java application dynamically manages directory structures for a file-processing pipeline. It accepts user input for source and target directories, categorizes files by type, copies them to designated subdirectories, executes command-line utilities, and ensures atomic operations with robust error handling and logging. The solution is designed for concurrency and extensibility.']

