    json_t *api_base_url = json_object_get(config, "api_base_url");
    json_t *max_connections = json_object_get(config, "max_connections");

    if (!json_is_integer(server_port) || json_integer_value(server_port) <= 0) {
        return false;
    }

    const char *url_str = json_string_value(api_base_url);
    if (!url_str || (strncmp(url_str, "http://", 7) != 0 && strncmp(url_str, "https://", 8) != 0)) {
        return false;
    }

    if (!json_is_integer(max_connections) || json_integer_value(max_connections) <= 0 || json_integer_value(max_connections) >= 1024) {
        return false;
    }

    const char *log_level = json_string_value(json_object_get(config, "log_level"));
    bool valid_log_level = !log_level || 
                           (strcmp(log_level, "DEBUG") == 0 ||
                            strcmp(log_level, "INFO") == 0 ||
                            strcmp(log_level, "WARN") == 0 ||
                            strcmp(log_level, "ERROR") == 0 ||
                            strcmp(log_level, "FATAL") == 0);

    if (!valid_log_level) {
        return false;
    }

    // Check cache
    if (strcmp(config_cache.api_base_url, url_str) == 0 && config_cache.is_valid) {
        return true;
    }

    // Network reachability check with timeout simulation
    bool reachable = is_network_reachable(url_str);
    if (!reachable) {
        return false;
    }

    // Update cache
    strncpy(config_cache.api_base_url, url_str, sizeof(config_cache.api_base_url));
    config_cache.is_valid = true;

    return true;
}

bool process_json_config(const char *json_data) {
    json_error_t error;
    json_t *config = json_loads(json_data, 0, &error);

    if (!config) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        return false;
    }

    bool result = validate_config(config);
    json_decref(config);

