```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Newtonsoft.Json.Linq;

public interface ICryptoProvider
{
    byte[] Encrypt(byte[] data, string key);
    byte[] Decrypt(byte[] data, string key);
}

public class AESCryptoProvider : ICryptoProvider
{
    public byte[] Encrypt(byte[] data, string key)
    {
        using (Aes aesAlg = Aes.Create())
        {
            var keyBytes = Encoding.UTF8.GetBytes(key.PadRight(32));
            aesAlg.Key = keyBytes;
            aesAlg.IV = new byte[16]; // Default to zero IV for simplicity

            ICryptoTransform encryptor = aesAlg.CreateEncryptor(aesAlg.Key, aesAlg.IV);
            using (var msEncrypt = new MemoryStream())
            {
                using (var csEncrypt = new CryptoStream(msEncrypt, encryptor, CryptoStreamMode.Write))
                {
                    csEncrypt.Write(data, 0, data.Length);
                }
                return msEncrypt.ToArray();
            }
        }
    }

    public byte[] Decrypt(byte[] data, string key)
    {
        using (Aes aesAlg = Aes.Create())
        {
            var keyBytes = Encoding.UTF8.GetBytes(key.PadRight(32));
            aesAlg.Key = keyBytes;
            aesAlg.IV = new byte[16]; // Default to zero IV for simplicity

            ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);
            using (var msDecrypt = new MemoryStream(data))
            {
                using (var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    var plaintext = new byte[data.Length];
                    var bytesRead = csDecrypt.Read(plaintext, 0, plaintext.Length);
                    Array.Resize(ref plaintext, bytesRead);
                    return plaintext;
                }
            }
        }
    }
}

// Implement other providers like CamelliaCryptoProvider, MD5CryptoProvider etc.

public class CryptoManager
{
    private static ICryptoProvider _cryptoProvider;

    public static void LoadConfiguration(string configPath)
    {
        var configFile = File.ReadAllText(configPath);
        var jsonConfig = JObject.Parse(configFile);

        string providerType = jsonConfig["provider"].ToString();

        switch (providerType)
        {
            case "AES":
                _cryptoProvider = new AESCryptoProvider();
                break;
            // Add cases for other providers like Camellia, MD5, etc.
            default:
                throw new NotSupportedException($"Provider {providerType} is not supported.");
        }
    }

    public static byte[] Encrypt(byte[] data, string key)
    {
        return _cryptoProvider.Encrypt(data, key);
    }

    public static byte[] Decrypt(byte[] data, string key)
    {
        return _cryptoProvider.Decrypt(data, key);
    }
}

public class RSACryptoManager
{
    private RSA _rsa;

    public RSACryptoManager()
    {
        _rsa = RSA.Create();
    }

    public byte[] EncryptWithRSA(byte[] data, string publicKeyXml)
    {
        using (var rsa = RSA.Create())
        {
            rsa.ImportFromPem(publicKeyXml.ToCharArray());
            return rsa.Encrypt(data, RSAEncryptionPadding.OaepSHA256);
        }
    }

    public byte[] DecryptWithRSA(byte[] encryptedData, string privateKeyXml)
    {
        using (var rsa = RSA.Create())
        {
            rsa.ImportFromPem(privateKeyXml.ToCharArray());
            return rsa.Decrypt(encryptedData, RSAEncryptionPadding.OaepSHA256);
        }
    }
}

