public class DecryptionService
{
    private const int KeySize = 32; // AES-256 bit key size

    public string DecryptMessage(string base64EncodedCipherText, string password, string kdfAlgorithm)
    {
        try
        {
            var (key, iv) = DeriveKeyAndIV(password, kdfAlgorithm);

            using var aesAlg = Aes.Create();
            aesAlg.Key = key;
            aesAlg.IV = iv;

            using var decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

            var cipherBytes = Convert.FromBase64String(base64EncodedCipherText);
            using var msDecrypt = new MemoryStream(cipherBytes);
            using var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read);
            using var srDecrypt = new StreamReader(csDecrypt);

            return srDecrypt.ReadToEnd();
        }
        catch (Exception ex)
        {
            // Log the exception details
            Console.WriteLine($"Decryption failed: {ex.Message}");
            throw new DecryptionException("Failed to decrypt message.", ex);
        }
    }

    private (byte[], byte[]) DeriveKeyAndIV(string password, string kdfAlgorithm)
    {
        byte[] salt = GenerateUniqueSalt();

        // Assume external authentication service validates the password
        if (!ExternalAuthService.ValidatePassword(password))
            throw new AuthenticationException("Invalid credentials.");

        switch (kdfAlgorithm.ToLower())
        {
            case "pbkdf2":
                return DerivePBKDF2KeyAndIV(password, salt);
            case "bcrypt":
                return DeriveBCryptKeyAndIV(password, salt);
            case "scrypt":
                return DeriveScryptKeyAndIV(password, salt);
            default:
                throw new NotSupportedException($"KDF algorithm '{kdfAlgorithm}' is not supported.");
        }
    }

    private (byte[], byte[]) DerivePBKDF2KeyAndIV(string password, byte[] salt)
    {
        using var rfc2898DeriveBytes = new Rfc2898DeriveBytes(password, salt, 10000);
        var key = rfc2898DeriveBytes.GetBytes(KeySize);
        var iv = GenerateSecureRandomIV();
        return (key, iv);
    }

    private (byte[], byte[]) DeriveBCryptKeyAndIV(string password, byte[] salt)
    {
        string hashedPassword = BCrypt.Net.BCrypt.HashPassword(password, salt, workFactor: 12);
        byte[] key = Convert.FromBase64String(hashedPassword.Substring(29, KeySize * 2));
        var iv = GenerateSecureRandomIV();
        return (key, iv);
    }

    private (byte[], byte[]) DeriveScryptKeyAndIV(string password, byte[] salt)
    {
        // Pseudo-code for scrypt as .NET lacks native support
        // Use a third-party library like Konscious.Security.Cryptography.Scrypt
        var key = new byte[KeySize]; // Populate with Scrypt derived key
        var iv = GenerateSecureRandomIV();
        return (key, iv);
    }

    private byte[] GenerateUniqueSalt()
    {
        using var rng = RandomNumberGenerator.Create();
        byte[] salt = new byte[16];
        rng.GetBytes(salt);
        return salt;
    }

    private byte[] GenerateSecureRandomIV()
    {
        using var aesAlg = Aes.Create();
        aesAlg.GenerateIV();
        return aesAlg.IV;
    }
}

