using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Logging; // Assuming use of Microsoft.Extensions.Logging

public class AesDecryptor
{
    private readonly ILogger<AesDecryptor> _logger;

    public AesDecryptor(ILogger<AseDecryptor> logger)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public byte[] Decrypt(byte[]? ciphertext, byte[] key, byte[] iv = null)
    {
        try
        {
            if (ciphertext == null || key == null || !IsValidKeySize(key))
            {
                LogError("Invalid input parameters.");
                return Array.Empty<byte>();
            }

            iv ??= GenerateSecureRandomIV(key.Length);

            using var aes = Aes.Create();
            aes.Key = key;
            aes.IV = iv;
            aes.Mode = CipherMode.CBC;

            var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
            using var ms = new MemoryStream(ciphertext);
            using var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read);

            using var resultStream = new MemoryStream();
            cs.CopyTo(resultStream);
            return resultStream.ToArray();
        }
        catch (Exception ex)
        {
            LogError("Decryption failed.", ex);
            return Array.Empty<byte>();
        }
    }

    public byte[] Decrypt(string? base64Ciphertext, byte[] key, byte[] iv = null)
    {
        try
        {
            if (string.IsNullOrEmpty(base64Ciphertext) || key == null || !IsValidKeySize(key))
            {
                LogError("Invalid input parameters.");
                return Array.Empty<byte>();
            }

            var ciphertext = Convert.FromBase64String(base64Ciphertext);
            return Decrypt(ciphertext, key, iv);
        }
        catch (Exception ex)
        {
            LogError("Decryption failed.", ex);
            return Array.Empty<byte>();
        }
    }

    private bool IsValidKeySize(byte[] key) => key.Length == 16 || key.Length == 24 || key.Length == 32;

    private byte[] GenerateSecureRandomIV(int size)
    {
        using var rng = RandomNumberGenerator.Create();
        var iv = new byte[size];
        rng.GetBytes(iv);
        return iv;
    }

    private void LogError(string message, Exception ex = null)
    {
        var logLevel = GetLogLevelFromEnvironment();
        _logger.Log(logLevel, ex, message);
    }

    private LogLevel GetLogLevelFromEnvironment()
    {
        // Assuming an environment variable named "LOG_LEVEL"
        var levelStr = Environment.GetEnvironmentVariable("LOG_LEVEL");
        return Enum.TryParse(levelStr, true, out LogLevel logLevel) ? logLevel : LogLevel.Error;
    }
}

