use std::fs;
use std::path::{Path, PathBuf};
use std::sync::Mutex;
use tokio::sync::RwLock;
use tokio::task;
use log::{info, error};
use reqwest;

lazy_static! {
    static ref DIRECTORY_INIT_LOCK: RwLock<()> = RwLock::new(());
}

async fn fetch_default_directory_name() -> Result<String, reqwest::Error> {
    let response = reqwest::get("https://example.com/config/default-directory")
        .await?
        .text()
        .await?;
    Ok(response)
}

fn create_workspace_dir(path: &Path) -> Result<(), std::io::Error> {
    if !path.exists() {
        fs::create_dir_all(path)?;
    }
    info!("Workspace directory created or already exists at {:?}", path);
    Ok(())
}

async fn initialize_project_workspace(
    base_path: &str,
    provided_name: Option<String>,
) -> Result<(), Box<dyn std::error::Error>> {
    let config_lock = DIRECTORY_INIT_LOCK.read().await;

    // Determine the workspace name
    let workspace_name = match provided_name.as_deref() {
        Some(name) => name,
        None => fetch_default_directory_name().await?,
    };

    let path_buf: PathBuf = [base_path, &workspace_name]
        .iter()
        .map(|p| p.replace(' ', "\\ ")) // Handle spaces in paths
        .collect();

    create_workspace_dir(&path_buf)?;

    drop(config_lock); // Release the read lock

    Ok(())
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    env_logger::init();

    let base_path = ".";
    match initialize_project_workspace(base_path, None).await {
        Ok(_) => info!("Project workspace initialized successfully."),
        Err(e) => error!("Failed to initialize project workspace: {}", e),
    }

    Ok(())
}
```

