#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

#define MAX_THREADS 4

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Helper function to find the largest integer in an array
int findLargest(int *array, size_t size) {
    if (!array || size == 0) return -1; // Invalid input handling

    int max_value = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > max_value) {
            max_value = array[i];
        }
    }
    return max_value;
}

// Helper function to swap two records
void swapRecords(record *a, record *b) {
    record temp = *a;
    *a = *b;
    *b = temp;
}

// Sorting function (QuickSort)
void quickSort(int *keys, record *records, int left, int right) {
    if (left >= right) return;

    int pivot = keys[left];
    int i = left + 1, j = right;
    while (i <= j) {
        while (i <= right && keys[i] < pivot) ++i;
        while (j > left && keys[j] > pivot) --j;
        if (i <= j) {
            swapRecords(&records[i], &records[j]);
            int temp = keys[i];
            keys[i] = keys[j];
            keys[j] = temp;
            i++;
            j--;
        }
    }
    quickSort(keys, records, left, j);
    quickSort(keys, records, i, right);
}

// Main processing function
int processAndSortRecords(long *offsets, int *keys, record *records, size_t num_records, int range_min, int range_max) {
    pthread_mutex_lock(&lock);

    // Validate inputs
    if (num_records == 0 || !offsets || !keys || !records) {
        pthread_mutex_unlock(&lock);
        return -1; // Error code for invalid input
    }

    // Initialize records with random values
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand() % (range_max - range_min + 1) + range_min;
    }

    // QuickSort the records based on keys
    quickSort(keys, records, 0, num_records - 1);

    pthread_mutex_unlock(&lock);
    return 0; // Success code
}

// Function to read integers from standard input and find the largest one
void readIntegersAndFindLargest() {
    int n;
    printf("Enter the number of integers: ");
    scanf("%d", &n);

    if (n <= 0) {
        printf("Invalid number of integers.\n");
        return;
    }

    int *array = malloc(n * sizeof(int));
    if (!array) {
        perror("Failed to allocate memory for array");
        return;
    }

    printf("Enter %d integers:\n", n);
    for (int i = 0; i < n; ++i) {
        scanf("%d", &array[i]);
    }

    int largest = findLargest(array, n);
    if (largest != -1) {
        printf("The largest integer is: %d\n", largest);
    } else {
        printf("Error finding the largest integer.\n");
    }

    free(array);
}

int main() {
    size_t num_records = 10;
    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc(num_records * sizeof(int));
    record *records = malloc(num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(records);
        return -1;
    }

    // Initialize keys with some values (for example purposes)
    for (size_t i = 0; i < num_records; ++i) {
        keys[i] = rand() % 100;
    }

    int result = processAndSortRecords(offsets, keys, records, num_records, 1, 100);
    if (result == 0) {
        printf("Records processed and sorted successfully.\n");
    } else {
        fprintf(stderr, "Error processing records\n");
    }

    // Read integers from standard input and find the largest one
    readIntegersAndFindLargest();

    free(offsets);
    free(keys);
    free(records);

    pthread_mutex_destroy(&lock);

    return 0;
}
