['Here's a C code implementation for managing a collection of records with unique integer keys and long offset values using a linked list:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int key;
    long offset;
    struct Record* next;
} Record;

typedef struct {
    Record* head;
    pthread_mutex_t lock;
} RecordList;

// Initialize the record list
void initRecordList(RecordList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Generate a random integer within a range [min, max]
int generateRandomInt(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Check if a key exists in the list
int keyExists(RecordList* list, int key) {
    pthread_mutex_lock(&list->lock);
    Record* current = list->head;
    while (current != NULL) {
        if (current->key == key) {
            pthread_mutex_unlock(&list->lock);
            return 1; // Key exists
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return 0; // Key does not exist
}

// Insert a new record
void insertRecord(RecordList* list, int key, long offset) {
    if (keyExists(list, key)) return;

    Record* newRecord = (Record*)malloc(sizeof(Record));
    if (!newRecord) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    newRecord->key = key;
    newRecord->offset = offset;
    newRecord->next = NULL;

    pthread_mutex_lock(&list->lock);
    newRecord->next = list->head;
    list->head = newRecord;
    pthread_mutex_unlock(&list->lock);
}

// Free all records
void freeRecords(RecordList* list) {
    pthread_mutex_lock(&list->lock);
    Record* current = list->head;
    while (current != NULL) {
        Record* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
}

// Destroy the record list
void destroyRecordList(RecordList* list) {
    freeRecords(list);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    RecordList list;
    initRecordList(&list);

    // Example usage: Insert records with random keys and offsets
    for (int i = 0; i < 1000000; ++i) {
        int key = generateRandomInt(1, 2000000);
        long offset = rand() % 1000000;
        insertRecord(&list, key, offset);
    }

    // Clean up
    destroyRecordList(&list);

    return 0;
}
```

### Key Points:
- **Thread Safety**: The code uses a mutex (`pthread_mutex_t`) to ensure thread-safe operations on the linked list.
- **Memory Management**: Each record is dynamically allocated and properly freed to prevent memory leaks.
- **Data Integrity**: The `keyExists` function ensures no duplicate keys are inserted.
- **Performance Considerations**: While the linked list provides O(1) insertion, lookups are O(n). For better performance with large datasets, consider using a hash table or other data structures.']

