```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Record structure definition
typedef struct {
    int key;
    long offset;
} record;

// Collection manager structure
typedef struct {
    record *records;
    size_t count;
    pthread_mutex_t lock; // Mutex for thread safety
} RecordCollection;

// Function to initialize the collection with random records
void init_record_collection(RecordCollection *collection, size_t num_records, long offset_min, long offset_max) {
    if (num_records == 0 || collection == NULL) return;

    pthread_mutex_init(&collection->lock, NULL);
    collection->records = malloc(num_records * sizeof(record));
    collection->count = num_records;

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < num_records; ++i) {
        collection->records[i].key = i;
        collection->records[i].offset = offset_min + rand() % (offset_max - offset_min + 1);
    }

    // Sort records by key using a simple sort algorithm for demonstration
    qsort(collection->records, num_records, sizeof(record), 
          [](const void *a, const void *b) -> int {
              record *recA = (record *)a;
              record *recB = (record *)b;
              return recA->key - recB->key; // Ascending order
          });
}

// Function to safely add a new record to the collection
void add_record(RecordCollection *collection, int key, long offset) {
    pthread_mutex_lock(&collection->lock);

    size_t new_count = collection->count + 1;
    record *new_records = realloc(collection->records, new_count * sizeof(record));

    if (new_records == NULL) { // Handle memory allocation failure
        perror("Failed to reallocate memory");
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    collection->records = new_records;
    collection->records[collection->count].key = key;
    collection->records[collection->count].offset = offset;
    ++collection->count;

    // Re-sort after insertion
    qsort(collection->records, collection->count, sizeof(record),
          [](const void *a, const void *b) -> int {
              record *recA = (record *)a;
              record *recB = (record *)b;
              return recA->key - recB->key; // Ascending order
          });

    pthread_mutex_unlock(&collection->lock);
}

// Function to safely remove a record from the collection by key
void remove_record(RecordCollection *collection, int key) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            memmove(&collection->records[i], &collection->records[i + 1],
                    (collection->count - i - 1) * sizeof(record));
            --collection->count;

            // Resize memory to save space
            collection->records = realloc(collection->records, collection->count * sizeof(record));

            if (collection->records == NULL && collection->count > 0) { // Handle reallocation failure
                perror("Failed to reallocate memory");
            }

            break; // Exit after removal
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

// Function to safely update a record's offset by key
void update_record_offset(RecordCollection *collection, int key, long new_offset) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            collection->records[i].offset = new_offset;
            break;
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

// Function to release all allocated memory
void free_record_collection(RecordCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    if (collection->records != NULL) {
        free(collection->records);
        collection->records = NULL;
    }

    collection->count = 0;

    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
}

// Example usage
int main() {
    RecordCollection collection;
    init_record_collection(&collection, 10, 100, 999);

    add_record(&collection, 11, 555);
    remove_record(&collection, 5);
    update_record_offset(&collection, 7, 777);

    free_record_collection(&collection);
    return 0;
}
```

This code provides a dynamic collection of records with thread-safe operations and ensures memory is properly managed. The sorting uses `qsort`, which is efficient for most use cases, and mutexes ensure concurrent access safety. The solution balances simplicity and efficiency while providing modularity for integration into larger systems.']

['```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.AsynchronousSocketChannel;
import java.nio.channels.CompletionHandler;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class FileTransferService {

    private static final int BUFFER_SIZE = 1024; // Configurable buffer size
    private static final String ALLOWED_CHARS_REGEX = "[\\x00-\\x1F\\x7F]"; // Control characters

    private AsynchronousSocketChannel channel;
    private ScheduledExecutorService rateLimiter;

    public FileTransferService(String host, int port) throws IOException {
        this.channel = AsynchronousSocketChannel.open();
        this.channel.connect(new InetSocketAddress(host, port)).get();

        this.rateLimiter = Executors.newScheduledThreadPool(1);
    }

    public void startStreaming() {
        channel.read(buffer -> {
            if (buffer.hasRemaining()) {
                ByteBuffer chunk = buffer.duplicate().compact();
                if (!isValidChunk(chunk)) {
                    log("Invalid data chunk received.");
                    return;
                }

                rateLimiter.schedule(() -> computeHashAndLog(chunk), 0, TimeUnit.MILLISECONDS);
            } else {
                try {
                    channel.read(buffer); // Continue reading
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }, ByteBuffer.allocate(BUFFER_SIZE), null).addListener((future) -> {
            if (future.isDone() && future.cause() != null) {
                log("Read operation failed: " + future.cause().getMessage());
            }
        });
    }

    private boolean isValidChunk(ByteBuffer chunk) {
        byte[] data = new byte[chunk.remaining()];
        chunk.get(data);

        for (byte b : data) {
            if (b <= 0x1F || b == 0x7F) { // Null or control characters
                return false;
            }
        }
        return true;
    }

    private void computeHashAndLog(ByteBuffer chunk) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hash = md.digest(chunk.array(), chunk.position(), chunk.remaining());

            log("Chunk processed at " + System.currentTimeMillis() + ": SUCCESS");

        } catch (NoSuchAlgorithmException | IOException e) {
            log("Hash computation failed: " + e.getMessage());
        }
    }

    private void log(String message) {
        // Logging mechanism (to file or console)
        System.out.println(message);
    }

    public void shutdown() throws IOException {
        channel.close();
        rateLimiter.shutdown();
    }

    public static void main(String[] args) {
        try {
            FileTransferService service = new FileTransferService("localhost", 8080);
            service.startStreaming();

            Runtime.getRuntime().addShutdownHook(new Thread(() -> {
                try {
                    service.shutdown();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }));

        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
```

This Java code implements a simple file transfer service using Java NIO to establish an asynchronous, persistent connection with a remote server. It processes incoming data in chunks of 1024 bytes, validates the chunk for control characters, computes MD5 hashes, and logs each operation's status. A rate-limiter is used to control the number of hash computations per second, and proper lifecycle management ensures resources are released appropriately. Adjust the host and port in `main()` to connect to your server.']

