            delete[] offsetValues;
            delete[] keys;
        }

        RecordProcessor(const RecordProcessor& other) 
            : recordCount(other.recordCount), rng(other.rng),
              records(nullptr), offsetValues(nullptr), keys(nullptr) {

            try {
                records = new Record[recordCount];
                offsetValues = new long[recordCount]();
                keys = new int[recordCount];

                std::copy_n(other.keys, recordCount, keys);
                std::copy_n(other.records, recordCount, records);

                for (size_t i = 0; i < recordCount; ++i) {
                    offsetValues[i] = other.offsetValues[i];
                }
            } catch (const std::bad_alloc& e) {
                delete[] records;
                delete[] offsetValues;
                delete[] keys;
                throw;
            }
        }

        RecordProcessor& operator=(const RecordProcessor& other) {
            if (this != &other) {
                delete[] records;
                delete[] offsetValues;
                delete[] keys;

                recordCount = other.recordCount;
                rng = other.rng;

                try {
                    records = new Record[recordCount];
                    offsetValues = new long[recordCount]();
                    keys = new int[recordCount];

                    std::copy_n(other.keys, recordCount, keys);
                    std::copy_n(other.records, recordCount, records);

                    for (size_t i = 0; i < recordCount; ++i) {
                        offsetValues[i] = other.offsetValues[i];
                    }
                } catch (const std::bad_alloc& e) {
                    delete[] records;
                    delete[] offsetValues;
                    delete[] keys;
                    throw;
                }
            }

            return *this;
        }

        void sortRecords() {
            std::sort(records, records + recordCount,
                      [this](const Record &a, const Record &b) -> bool {
                          return keys[&a - records] < keys[&b - records];
                      });
        }

    private:
        size_t recordCount;
        RandomNumberGenerator rng;
        Record* records;
        long* offsetValues;
        int* keys;
    };

    void findAndPrintLargestInteger() {
