['Below is a C implementation that follows your requirements. This code dynamically allocates memory for three types of arrays: `double` precision floating-point values, `char` strings (up to 256 characters), and pointers to `struct node`. The nodes are organized into a balanced binary search tree (BST). Memory allocation failures are handled gracefully by returning an error code.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Node {
    int key;
    struct Node *left, *right;
} Node;

// Function prototypes
Node* create_node(int key);
void insert_bst(Node** root, Node* new_node);
void free_tree(Node* root);
int populate_bst(Node** root, int min_range, int max_range, size_t num_nodes);
void initialize_memory(double **d_array, char ***c_array, Node*** n_array, size_t array_size);

// Function to create a new node
Node* create_node(int key) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->key = key;
    new_node->left = new_node->right = NULL;
    return new_node;
}

// Function to insert a node into the BST
void insert_bst(Node** root, Node* new_node) {
    if (*root == NULL) {
        *root = new_node;
        return;
    }

    if (new_node->key < (*root)->key)
        insert_bst(&((*root)->left), new_node);
    else if (new_node->key > (*root)->key)
        insert_bst(&((*root)->right), new_node);
}

// Function to free all nodes in the BST
void free_tree(Node* root) {
    if (root == NULL) return;
    free_tree(root->left);
    free_tree(root->right);
    free(root);
}

// Function to populate the BST with random keys within a specified range
int populate_bst(Node** root, int min_range, int max_range, size_t num_nodes) {
    srand(time(NULL)); // Seed for randomness

    Node* nodes = (Node*)malloc(num_nodes * sizeof(Node));
    if (!nodes) return -1; // Memory allocation failure

    for (size_t i = 0; i < num_nodes; ++i) {
        int key = min_range + rand() % (max_range - min_range + 1);
        nodes[i] = *create_node(key);
        if (!nodes[i]) { // Handle memory allocation failure
            free_tree(*root);
            free(nodes);
            return -1;
        }
    }

    for (size_t i = 0; i < num_nodes; ++i) {
        insert_bst(root, &nodes[i]);
    }

    free(nodes);
    return 0;
}

// Function to initialize memory for different data types
void initialize_memory(double **d_array, char ***c_array, Node*** n_array, size_t array_size) {
    *d_array = (double*)malloc(array_size * sizeof(double));
    if (!*d_array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    *c_array = (char**)malloc(array_size * sizeof(char*));
    if (!*c_array) {
        free(*d_array);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < array_size; ++i) {
        (*c_array)[i] = (char*)malloc(256 * sizeof(char));
        if (!(*c_array)[i]) {
            while (--i >= 0)
                free((*c_array)[i]);
            free(*c_array);
            free(*d_array);
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
    }

    *n_array = (Node**)malloc(array_size * sizeof(Node*));
    if (!*n_array) {
        while (--i >= 0)
            free((*c_array)[i]);
        free(*c_array);
        free(*d_array);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

int main() {
    Node* root = NULL;

    // Example usage
    int result = populate_bst(&root, 10, 100, 50); // Populate BST with random keys from 10 to 100
    if (result == -1) {
        fprintf(stderr, "Failed to populate the binary search tree\n");
        return EXIT_FAILURE;
    }

    double *d_array;
    char **c_array;
    Node **n_array;

    initialize_memory(&d_array, &c_array, &n_array, 10);

    // Clean up
    free_tree(root);
    for (size_t i = 0; i < 10; ++i) {
        free(c_array[i]);
    }
    free(c_array);
    free(d_array);
    free(n_array);

    return EXIT_SUCCESS;
}
```

