// Define constants
#define INITIAL_LIST_SIZE 10
#define FRAME_DATA_MAX_SIZE 256

typedef struct {
    uint8_t tag[6];
} MAC_EVENT_TAG;

typedef struct {
    uint8_t data[FRAME_DATA_MAX_SIZE];
    size_t length;
} MAC_FRAME_DATA;

typedef struct {
    MAC_EVENT_TAG mac_event_tag;
    time_t timestamp;
    MAC_FRAME_DATA *frames;
    size_t frame_count;
} NetworkEvent;

typedef struct {
    NetworkEvent *events;
    size_t capacity;
    atomic_size_t count;
    pthread_rwlock_t lock;
} EventList;

// Function prototypes
EventList* create_event_list();
void destroy_event_list(EventList *list);
int add_event(EventList *list, MAC_EVENT_TAG tag, time_t timestamp, const uint8_t *data, size_t length);
int resize_event_list(EventList *list, size_t new_capacity);
void handle_buffer_overflow();

// Create a new event list
EventList* create_event_list() {
    EventList *list = (EventList*)malloc(sizeof(EventList));
    if (!list) return NULL;

    pthread_rwlock_init(&list->lock, NULL);
    list->events = (NetworkEvent*)calloc(INITIAL_LIST_SIZE, sizeof(NetworkEvent));
    if (!list->events) {
        free(list);
        return NULL;
    }
    list->capacity = INITIAL_LIST_SIZE;
    atomic_store(&list->count, 0);

    return list;
}

// Destroy the event list
void destroy_event_list(EventList *list) {
    pthread_rwlock_destroy(&list->lock);
    for (size_t i = 0; i < atomic_load(&list->count); ++i) {
        free(list->events[i].frames);
    }
    free(list->events);
    free(list);
}

// Add an event to the list
int add_event(EventList *list, MAC_EVENT_TAG tag, time_t timestamp, const uint8_t *data, size_t length) {
    pthread_rwlock_wrlock(&list->lock);

    if (atomic_load(&list->count) >= list->capacity) {
        if (resize_event_list(list, list->capacity * 2) != 0) {
            pthread_rwlock_unlock(&list->lock);
            return -1;
        }
    }

    size_t index = atomic_fetch_add(&list->count, 1);
    NetworkEvent *event = &list->events[index];

    event->mac_event_tag = tag;
    event->timestamp = timestamp;

    if (length > FRAME_DATA_MAX_SIZE) {
        handle_buffer_overflow();
        pthread_rwlock_unlock(&list->lock);
        return -2; // Buffer overflow
    }

    event->frame_count = 1;
    event->frames = (MAC_FRAME_DATA*)malloc(sizeof(MAC_FRAME_DATA));
    if (!event->frames) {
        pthread_rwlock_unlock(&list->lock);
        return -3; // Memory allocation failure
    }
    memcpy(event->frames[0].data, data, length);
    event->frames[0].length = length;

    pthread_rwlock_unlock(&list->lock);
    return 0;
}

// Resize the event list
int resize_event_list(EventList *list, size_t new_capacity) {
    NetworkEvent *new_events = (NetworkEvent*)realloc(list->events, new_capacity * sizeof(NetworkEvent));
    if (!new_events) return -1;

    list->events = new_events;
    list->capacity = new_capacity;
    return 0;
}

// Handle buffer overflow condition
void handle_buffer_overflow() {
    fprintf(stderr, "Buffer overflow detected\n");
