#include <string.h>

#define ERROR_CODE -1

typedef struct {
    int value;
} record;

typedef pthread_mutex_t mutex_t;

// Function to find the maximum in an array of integers
int findMax(int *arr, size_t n) {
    if (n == 0) return INT_MIN;
    int max = arr[0];
    for (size_t i = 1; i < n; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Comparison function for qsort
int compareKeys(const void *a, const void *b) {
    int keyA = *(const int *)a;
    int keyB = *(const int *)b;
    return (keyA - keyB);
}

// Thread-safe function to process and sort records
int processAndSortRecords(size_t num_records, long min_value, long max_value) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for the arrays
    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc(num_records * sizeof(int));
    record *records = malloc(num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        pthread_mutex_destroy(&mutex);
        free(offsets);
        free(keys);
        free(records);
        return ERROR_CODE;
    }

    // Populate the records with random values
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = rand() % (max_value - min_value + 1) + min_value;
        keys[i] = rand();
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Sort the records based on their corresponding key values
    qsort(keys, num_records, sizeof(int), compareKeys);

    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < num_records; ++i) {
        printf("Key: %d, Record Value: %d\n", keys[i], records[i].value);
    }
    pthread_mutex_unlock(&mutex);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
    pthread_mutex_destroy(&mutex);

    return 0;
}

// Helper function to read integers from standard input and find the maximum
void readAndFindMax() {
    size_t n;
    if (scanf("%zu", &n) != 1) return;

    int *arr = malloc(n * sizeof(int));
    if (!arr) return;

    for (size_t i = 0; i < n; ++i) {
        scanf("%d", &arr[i]);
    }

    int max_value = findMax(arr, n);
    printf("Maximum value: %d\n", max_value);

    free(arr);
}

int main() {
    size_t num_records;
    long min_value = 0, max_value = 100;

    if (scanf("%zu", &num_records) != 1) return EXIT_FAILURE;

    int result = processAndSortRecords(num_records, min_value, max_value);
    if (result == ERROR_CODE) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    readAndFindMax();
    return EXIT_SUCCESS;
}

