### Java Function

```java
import java.util.Arrays;
import java.util.Random;

public class DisjointPairs {

    private static int find(int[] parent, int i) {
        if (parent[i] != i) {
            parent[i] = find(parent, parent[i]);
        }
        return parent[i];
    }

    private static void union(int[] parent, int i, int j) {
        int rootI = find(parent, i);
        int rootJ = find(parent, j);
        if (rootI != rootJ) {
            parent[rootJ] = rootI;
        }
    }

    public static int countDisjointPairs(int[] array) {
        if (array == null || array.length < 2) return 0;

        int n = array.length;
        int[] parent = new int[n];
        for (int i = 0; i < n; ++i) parent[i] = i;

        Random rand = new Random();
        long startMillis = System.currentTimeMillis();

        int disjointCount = 0;
        Arrays.sort(array);

        for (int i = 0; i < n - 1; ++i) {
            for (int j = i + 1; j < n; ++j) {
                if (array[i] != array[j]) { // Ensure pairs are disjoint
                    int indexI = rand.nextInt(n);
                    int indexJ = rand.nextInt(n);

                    long startTime = System.currentTimeMillis();

                    union(parent, indexI, indexJ);

                    long endTime = System.currentTimeMillis();
                    System.out.println("Disjoint check time: " + (endTime - startTime) + " ms");

                    disjointCount++;
                }
            }
        }

        long endMillis = System.currentTimeMillis();
        System.out.println("Total Disjoint Pairs Check Time: " + (endMillis - startMillis) + " ms");

        return disjointCount;
    }

    public static void main(String[] args) {
        int[] testArray = {1, 2, 3, 4, 5};
        System.out.println("Disjoint Pairs Count: " + countDisjointPairs(testArray));
    }
}
