#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Node {
    char *data;
    struct Node *next;
} Node;

// Global variables for managing memory pools and linked list
double *floatArray = NULL;
size_t floatArraySize = 0;
Node *head = NULL, *tail = NULL;
pthread_mutex_t lock;

// Function prototypes
void initializeMemoryManager(size_t doubleCount);
void freeMemoryManager();
int insertNode(const char *data);
void traverseAndPrintList();

// Initializes memory manager
void initializeMemoryManager(size_t doubleCount) {
    floatArraySize = doubleCount;
    floatArray = (double *)malloc(sizeof(double) * doubleCount);

    if (!floatArray) {
        fprintf(stderr, "Failed to allocate memory for floats\n");
        exit(EXIT_FAILURE);
    }

    head = tail = NULL;

    pthread_mutex_init(&lock, NULL);
}

// Frees all allocated resources
void freeMemoryManager() {
    pthread_mutex_lock(&lock);

    // Free linked list nodes
    Node *current = head;
    while (current) {
        Node *temp = current;
        current = current->next;
        free(temp->data);
        free(temp);
    }

    // Free float array
    free(floatArray);

    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);
}

// Inserts a new node at the end of the linked list
int insertNode(const char *data) {
    pthread_mutex_lock(&lock);

    Node *newNode = (Node *)malloc(sizeof(Node));
    if (!newNode) {
        fprintf(stderr, "Failed to allocate memory for new node\n");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    size_t len = strlen(data) + 1;
    newNode->data = (char *)malloc(len * sizeof(char));
    if (!newNode->data) {
        free(newNode);
        fprintf(stderr, "Failed to allocate memory for node data\n");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    strcpy(newNode->data, data);
    newNode->next = NULL;

    if (tail == NULL) { // List is empty
        head = tail = newNode;
    } else {
        tail->next = newNode;
        tail = newNode;
    }

    pthread_mutex_unlock(&lock);
    return 0;
}

// Traverses the linked list and prints each node's data
void traverseAndPrintList() {
    pthread_mutex_lock(&lock);

    Node *current = head;
    while (current) {
        printf("%s\n", current->data);
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

int main() {
    initializeMemoryManager(10); // Initialize for 10 double values

    insertNode("First");
    insertNode("Second");
    insertNode("Third");

    traverseAndPrintList();

    freeMemoryManager();
    return 0;
}
