// Perform an HTTP request with retry logic and exponential backoff
json_object* http_request(const char *url, int retries, int delay) {
    CURL *curl;
    CURLcode res;
    char error[CURL_ERROR_SIZE];
    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Accept: application/json");

    json_object *response_json = NULL;
    char *data_buffer = malloc(1);
    size_t data_size = 0;

    for (int attempt = 0; attempt < retries; ++attempt) {
        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl = curl_easy_init();

        if(curl) {
            curl_easy_setopt(curl, CURLOPT_URL, url);
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_data);
            curl_easy_setopt(curl, CURLOPT_WRITEDATA, &data_buffer);
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

            res = curl_easy_perform(curl);

            if(res != CURLE_OK) {
                snprintf(error, CURL_ERROR_SIZE, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
                printf("Attempt %d/%d for URL %s failed: %s\n", attempt + 1, retries, url, error);

                free(data_buffer);
                data_size = 0;
                data_buffer = malloc(1);

                sleep(delay * (1 << attempt)); // Exponential backoff
            } else {
                break; // Success
            }

            curl_easy_cleanup(curl);
        }

        curl_slist_free_all(headers);
        curl_global_cleanup();
    }

    if(res == CURLE_OK && data_size > 0) {
        response_json = json_tokener_parse(data_buffer);
    }

    free(data_buffer);
    return response_json;
}

