    Config *config = (Config *)arg;

    Node *head = NULL, *tail = NULL;

    for (int i = 0; i < config->num_endpoints; ++i) {
        json_object *response_json = http_request(config->endpoints[i], config->retry_attempts, BASE_DELAY_SECONDS);

        if(response_json != NULL) {
            Node *new_node = create_node(response_json);

            if(tail == NULL) {
                head = new_node;
                tail = new_node;
            } else {
                tail->next = new_node;
                tail = new_node;
            }
