        // Merge linked lists from each thread
        while(results[i]) {
            Node *current = results[i];
            printf("%s\n", json_object_to_json_string(current->data));  // Handle JSON data
            results[i] = current->next;
            free(json_object_get_string(current->data));
            free(current);
        }
    }

    free(config);
    free(results);

