void execute_command(const char *command, const char *arg) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        exit(0);
    } else if (pid > 0) { // Parent process
        int status;
        waitpid(pid, &status, 0); // Wait for the child to complete
        if (WIFEXITED(status) && WEXITSTATUS(status) == 0)
            printf("Command executed successfully\n");
        else
            printf("Command execution failed\n");
    } else { // Child process
        execlp(command, command, arg, NULL);
        perror("execlp");
        exit(1); // Exit with error if execlp fails
    }
}

void initialize_structures(size_t size, int min_val, int max_val, const char *command, const char *arg) {
    long *offsets = (long *)malloc(size * sizeof(long));
    int *keys = (int *)malloc(size * sizeof(int));
    record *records = (record *)malloc(size * sizeof(record));

    if (!offsets || !keys || !records) {
        perror("Memory allocation failed");
        free(offsets);
        free(keys);
        free(records);
        exit(0);
    }

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    for (size_t i = 0; i < size; ++i) {
        offsets[i] = i * sizeof(long);
        keys[i] = rand() % 100; // Random key
        records[i].value = min_val + rand() % (max_val - min_val + 1); // Random record value within range
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    long elapsed_time_ns = end.tv_sec * 1000000000L + end.tv_nsec - start.tv_sec * 1000000000L - start.tv_nsec;
    printf("Initialization took %ld milliseconds\n", elapsed_time_ns / 1000000L);

    execute_command(command, arg);

    free(offsets);
    free(keys);
    free(records);
}

