const size_t MAX_MEMORY_THRESHOLD = 10 * 1024 * 1024; // 10 MB
const int RETRY_LIMIT = 5;

std::mutex data_mutex;
std::vector<int> shared_data;

void processStream(const std::string& stream) {
    std::lock_guard<std::mutex> guard(data_mutex);

    std::istringstream iss(stream);
    std::string token;
    size_t current_size = 0;

    while (getline(iss, token, ',')) {
        // Trim spaces
        token.erase(token.find_last_not_of(" \t\n\r\f\v") + 1);

        if (!token.empty()) {
            int number = std::stoi(token);

            // Check memory threshold
            current_size += sizeof(int);
            if (current_size > MAX_MEMORY_THRESHOLD) {
                Logger::error("Memory overflow error: Data size exceeded the maximum allowed limit.");
                exit(EXIT_FAILURE);
            }

            shared_data.push_back(number);
        }
    }
}

void sortAndFindLargest() {
    std::lock_guard<std::mutex> guard(data_mutex);

    // Sort in descending order
    std::sort(shared_data.begin(), shared_data.end(), std::greater<int>());

    if (!shared_data.empty()) {
        Logger::info("Largest integer: " + std::to_string(shared_data.front()));
    }
}

void retryWithExponentialBackoff(std::function<bool()> operation) {
    int attempt = 0;
    while (attempt < RETRY_LIMIT) {
        if (operation()) {
            return;
        }

        int wait_time = (1 << attempt); // Exponential backoff
        std::this_thread::sleep_for(std::chrono::seconds(wait_time));
        ++attempt;
    }

    Logger::error("Failed to complete operation after several retries.");
}

bool fetchMetadata(int number) {
    // Mock API call with potential failure
    static std::default_random_engine generator;
    static std::uniform_int_distribution<int> distribution(0, 10);

    if (distribution(generator) > 7) { // Simulate a network failure 30% of the time
        Logger::warn("Failed to retrieve metadata for integer: " + std::to_string(number));
        return false;
    }

    Logger::info("Successfully retrieved metadata for integer: " + std::to_string(number));
    return true;
}

void handleDataStream(const std::string& stream) {
    processStream(stream);
    sortAndFindLargest();

    // Process each number to fetch metadata
    for (const auto& num : shared_data) {
        retryWithExponentialBackoff([num]() { return fetchMetadata(num); });
    }
}

