import java.util.concurrent.RecursiveTask;
import java.util.concurrent.ForkJoinPool;

public class DisjointPairs {

    private static int[] parent;

    public static void main(String[] args) {
        // Example usage
        int[] array = {1, 2, 3, 4, 5};
        System.out.println(countDisjointPairs(array));
    }

    public static int countDisjointPairs(int[] array) {
        if (array == null || array.length < 2) return 0;

        parent = new int[array.length];
        for (int i = 0; i < array.length; ++i) {
            parent[i] = i;
        }

        ForkJoinPool pool = new ForkJoinPool();
        RecursiveTask<Integer> task = new PairCountTask(array, 0, array.length);
        return pool.invoke(task);
    }

    private static class PairCountTask extends RecursiveTask<Integer> {
        private final int[] array;
        private final int start;
        private final int end;

        private static final int THRESHOLD = 1000; // Adjust based on performance testing

        public PairCountTask(int[] array, int start, int end) {
            this.array = array;
            this.start = start;
            this.end = end;
        }

        @Override
        protected Integer compute() {
            if (end - start <= THRESHOLD) {
                return countPairsDirectly();
            } else {
                int mid = (start + end) / 2;
                PairCountTask leftTask = new PairCountTask(array, start, mid);
                PairCountTask rightTask = new PairCountTask(array, mid, end);

                leftTask.fork();
                int rightResult = rightTask.compute();
                int leftResult = leftTask.join();

                return leftResult + rightResult;
            }
        }

        private int countPairsDirectly() {
            int count = 0;

            for (int i = start; i < end - 1; ++i) {
                for (int j = i + 1; j < end; ++j) {
                    if (find(array[i]) != find(array[j])) {
                        union(array[i], array[j]);
                        count++;
                    }
                }
            }

            return count;
        }

        private int find(int value) {
            if (parent[value] != value) {
                parent[value] = find(parent[value]);
            }
            return parent[value];
        }

        private void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);

            if (rootA != rootB) {
                parent[rootB] = rootA;
            }
        }
    }
}
