#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef long offset_t;
typedef int key_t;

#define VALUE_MIN 1
#define VALUE_MAX 100

typedef struct {
    int value_t; // Example field, can be expanded as needed.
} record_t;

// Error logging function
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Mutexes for synchronization
pthread_mutex_t offset_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t key_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t record_mutex = PTHREAD_MUTEX_INITIALIZER;

static unsigned int seed = 0; // For consistent random number generation

void initialize_data_structures(size_t size, offset_t **offsets, key_t **keys, record_t ***records) {
    if (size <= 0 || !offsets || !keys || !records) {
        log_error("Invalid input parameters.");
        return;
    }

    // Allocate memory for offsets
    *offsets = malloc(size * sizeof(offset_t));
    if (*offsets == NULL) {
        log_error("Failed to allocate memory for offsets.");
        return;
    }

    pthread_mutex_lock(&offset_mutex);
    for (size_t i = 0; i < size; ++i) {
        (*offsets)[i] = 0L; // Initialize with a default value
    }
    pthread_mutex_unlock(&offset_mutex);

    // Allocate memory for keys
    *keys = malloc(size * sizeof(key_t));
    if (*keys == NULL) {
        log_error("Failed to allocate memory for keys.");
        free(*offsets);
        return;
    }

    pthread_mutex_lock(&key_mutex);
    for (size_t i = 0; i < size; ++i) {
        (*keys)[i] = 0; // Initialize with a default value
    }
    pthread_mutex_unlock(&key_mutex);

    // Allocate memory for records
    *records = malloc(size * sizeof(record_t *));
    if (*records == NULL) {
        log_error("Failed to allocate memory for record pointers.");
        free(*offsets);
        free(*keys);
        return;
    }

    pthread_mutex_lock(&record_mutex);
    for (size_t i = 0; i < size; ++i) {
        (*records)[i] = malloc(sizeof(record_t));
        if ((*records)[i] == NULL) {
            log_error("Failed to allocate memory for a record.");
            // Free already allocated resources
            while (i > 0) {
                free((*records)[--i]);
            }
            free(*records);
            free(*keys);
            free(*offsets);
            return;
        }
        (*records)[i]->value_t = 0; // Initialize with a default value
    }
    pthread_mutex_unlock(&record_mutex);

    // Seed random number generator once
    if (seed == 0) {
        srand(time(NULL));
        seed++;
    }

    // Fill records with random values
    for (size_t i = 0; i < size; ++i) {
        (*records)[i]->value_t = VALUE_MIN + rand() % (VALUE_MAX - VALUE_MIN + 1);
    }
}

void verify_initialization(size_t size, offset_t *offsets, key_t *keys, record_t **records) {
    if (!offsets || !keys || !records) return;

    pthread_mutex_lock(&offset_mutex);
    for (size_t i = 0; i < size; ++i) {
        if (offsets[i] != 0L) {
            log_error("Offset array not correctly initialized.");
        }
    }
    pthread_mutex_unlock(&offset_mutex);

    pthread_mutex_lock(&key_mutex);
    for (size_t i = 0; i < size; ++i) {
        if (keys[i] != 0) {
            log_error("Key array not correctly initialized.");
        }
    }
    pthread_mutex_unlock(&key_mutex);

    pthread_mutex_lock(&record_mutex);
    for (size_t i = 0; i < size; ++i) {
        if (records[i]->value_t == 0) { // Assuming a default value of zero indicates uninitialized
            log_error("Record array not correctly initialized.");
        }
    }
    pthread_mutex_unlock(&record_mutex);

    printf("All structures are correctly initialized.\n");
}

void cleanup_data_structures(size_t size, offset_t *offsets, key_t *keys, record_t **records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) {
        for (size_t i = 0; i < size; ++i) {
            if (records[i]) free(records[i]);
        }
        free(records);
    }
}

int main() {
    size_t size = 10; // Example size
    offset_t *offsets;
    key_t *keys;
    record_t **records;

    initialize_data_structures(size, &offsets, &keys, &records);

    verify_initialization(size, offsets, keys, records);

    cleanup_data_structures(size, offsets, keys, records);

    return 0;
}
