} LinkedList;

// Function prototypes
void freeAll(long** offsets, int** keys, record** records, LinkedList* list);
int initializeDataStructures(long*** offsets, int*** keys, record*** records, LinkedList** list, size_t numRecords, int minValue, int maxValue, unsigned int seed);

void freeAll(long** offsets, int** keys, record** records, LinkedList* list) {
    if (offsets && *offsets) {
        free(*offsets);
        *offsets = NULL;
    }

    if (keys && *keys) {
        free(*keys);
        *keys = NULL;
    }

    if (records && *records) {
        for (size_t i = 0; i < numRecords; ++i) {
            (*records)[i].offsetPtr = NULL;
            (*records)[i].keyPtr = NULL;
        }
        free(*records);
        *records = NULL;
    }

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int initializeDataStructures(long*** offsets, int*** keys, record*** records, LinkedList** list, size_t numRecords, int minValue, int maxValue, unsigned int seed) {
    if (numRecords == 0) return -1;

    // Initialize random number generator
    srand(seed);

    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE_NP); 

    *list = malloc(sizeof(LinkedList));
    if (!*list) return -1;

    (*list)->head = NULL;
    if (pthread_mutex_init(&(*list)->lock, &attr)) {
        free(*list);
        pthread_mutexattr_destroy(&attr);
        return -1;
    }
    pthread_mutexattr_destroy(&attr);

    // Allocate memory for offsets and keys
    *offsets = malloc(numRecords * sizeof(long));
    if (!*offsets) {
        freeAll(NULL, NULL, NULL, *list);
        return -1;
    }

    *keys = malloc(numRecords * sizeof(int));
    if (!*keys) {
        free(*offsets);
        freeAll(NULL, NULL, NULL, *list);
        return -1;
    }

    // Allocate memory for records
    *records = malloc(numRecords * sizeof(record));
    if (!*records) {
        free(*offsets);
        free(*keys);
        freeAll(NULL, NULL, NULL, *list);
        return -1;
    }

    pthread_mutex_lock(&(*list)->lock);

    // Initialize offsets and keys
    for (size_t i = 0; i < numRecords; ++i) {
        (*offsets)[i] = rand() % ((long)(UINTPTR_MAX) / sizeof(long)) * sizeof(long);
        (*keys)[i] = rand() % 1000; // Example key range, can be modified

        (*records)[i].value = minValue + rand() % (maxValue - minValue + 1);
        (*records)[i].offsetPtr = &(*offsets)[i];
        (*records)[i].keyPtr = &(*keys)[i];

        Node* newNode = malloc(sizeof(Node));
        if (!newNode) {
            pthread_mutex_unlock(&(*list)->lock);
            freeAll(offsets, keys, records, *list);
            return -1;
        }
        newNode->rec = (*records)[i];
        newNode->next = (*list)->head;
        (*list)->head = newNode;
    }

    pthread_mutex_unlock(&(*list)->lock);

    return 0; // Success
}

int main() {
    long* offsets = NULL;
    int* keys = NULL;
    record* records = NULL;
