int resolve_and_process(const char **hostnames, int hostname_count) {
    struct addrinfo hints, *res, *p;
    char ipstr[INET6_ADDRSTRLEN];
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    for (int i = 0; i < hostname_count; ++i) {
        if ((status = getaddrinfo(hostnames[i], NULL, &hints, &res)) != 0) {
            fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
            return DNS_ERROR;
        }

        for (p = res; p != NULL; p = p->ai_next) {
            void *addr;
            if (p->ai_family == AF_INET) { // IPv4
                struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
                addr = &(ipv4->sin_addr);
            } else { // IPv6
                struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
                addr = &(ipv6->sin6_addr);
            }

            inet_ntop(p->ai_family, addr, ipstr, sizeof(ipstr));
            printf("Resolved IP for %s: %s\n", hostnames[i], ipstr);
        }
        freeaddrinfo(res);
    }

    // Reading integers from standard input
    int *numbers = NULL;
    size_t count = 0;
    size_t capacity = 10;
    numbers = malloc(capacity * sizeof(int));

    if (!numbers) return DNS_ERROR;

    int num;
    while (scanf("%d", &num) == 1) {
        if (count >= capacity) {
            capacity *= 2;
            numbers = realloc(numbers, capacity * sizeof(int));
            if (!numbers) return DNS_ERROR;
        }
        numbers[count++] = num;
    }

    find_and_print_largest(numbers, count);

    free(numbers);
    return 0;
}

// Example usage
int main() {
    const char *hostnames[] = {"example.com", "google.com"};
    int hostname_count = sizeof(hostnames) / sizeof(hostnames[0]);

    if (resolve_and_process(hostnames, hostname_count) != 0) {
        fprintf(stderr, "Error resolving hostnames.\n");
    }

    return 0;
}
