// Thread-safe function to generate and populate an array of structures.
NFAPI_CRC_INDICATION_PDU_T* generate_crc_indication_pdu_array(size_t num_elements) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);
    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        pthread_mutex_unlock(&lock);
        pthread_mutex_destroy(&lock);
        return NULL;
    }

    for (size_t i = 0; i < num_elements; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rand() % 65536;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
