#include <stdio.h>
#include <stdlib.h>
import <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <errno.h>
#include <unistd.h>
#include <netdb.h>
#include <time.h>

#define MAX_LINE_LENGTH 1024
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_ERROR 2
#define RETRY_LIMIT 5
#define INITIAL_BACKOFF 100 // milliseconds

typedef struct {
    sem_t semaphore;
    int initial_value;
} Semaphore;

void log_event(const char *message, int level) {
    if (level >= LOG_LEVEL_INFO) {
        printf("%s\n", message);
    }
}

void init_semaphore(Semaphore *sem, int value) {
    if (sem_init(&sem->semaphore, 0, value)) {
        perror("Semaphore initialization failed");
        exit(EXIT_FAILURE);
    }
    sem->initial_value = value;
}

void destroy_semaphore(Semaphore *sem) {
    sem_destroy(&sem->semaphore);
}

char *resolve_hostname(const char *hostname) {
    struct addrinfo hints, *res, *p;
    int retries = 0, backoff = INITIAL_BACKOFF;
    char ipstr[INET6_ADDRSTRLEN];

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    while (retries < RETRY_LIMIT) {
        if (getaddrinfo(hostname, NULL, &hints, &res) == 0) {
            for(p = res; p != NULL; p = p->ai_next) {
                void *addr;
                if (p->ai_family == AF_INET) { // IPv4
                    struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
                    addr = &(ipv4->sin_addr);
                } else { // IPv6
                    struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
                    addr = &(ipv6->sin6_addr);
                }
                inet_ntop(p->ai_family, addr, ipstr, sizeof(ipstr));
                freeaddrinfo(res);
                return strdup(ipstr);
            }
        } else {
            log_event("DNS resolution failed", LOG_LEVEL_ERROR);
            sleep(backoff / 1000.0); // Convert milliseconds to seconds
            backoff *= 2; // Exponential backoff
            retries++;
        }
    }

    freeaddrinfo(res);
    return NULL;
}

void *process_line(void *arg) {
    char *line = (char *)arg;
    if (!line) return NULL;

    char *token, *next_token;
    char *last_field1 = NULL, *last_field2 = NULL;
    double sum = 0.0, avg = 0.0;
    int field_count = 0;

    token = strtok_r(line, " \t\n", &next_token);
    while (token) {
        if (field_count > 0 && last_field1 == NULL) {
            last_field1 = strdup(token);
        } else if (last_field1 != NULL) {
            last_field2 = strdup(token);
        }
        token = strtok_r(NULL, " \t\n", &next_token);
        field_count++;
    }

    if (last_field1 && last_field2) {
        sum = atof(last_field1) + atof(last_field2);
        avg = sum / 2;
        printf("%s %s %.2f\n", line, last_field2, avg); // Output with new average
        free(last_field1);
        free(last_field2);
    } else {
        printf("%s\n", line);
    }

    return NULL;
}

void process_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, file)) != -1) {
        pthread_t thread;
        pthread_create(&thread, NULL, process_line, line);
        pthread_join(thread, NULL); // Ensure thread completion before continuing
        free(line);
        line = NULL; // Reset for next iteration
    }

    if (line) free(line);
    fclose(file);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    Semaphore sem;
    init_semaphore(&sem, 1);

    pthread_t dns_thread;
    char hostname[] = "example.com";
    pthread_create(&dns_thread, NULL, (void *(*)(void *))resolve_hostname, (void *)hostname);
    pthread_join(dns_thread, NULL);

    process_file(argv[1]);

    destroy_semaphore(&sem);
    return EXIT_SUCCESS;
}
