import java.io.*;
import java.net.URL;
import java.nio.file.*;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.*;

public class TextFileProcessor {

    private static final Pattern URL_PATTERN = 
        Pattern.compile("https?://[\\w.-]+(?:/[\\w.-]*)*(?:/?)");

    public List<String> processTextFile(String filePath) {
        List<String> cleanedLines = new ArrayList<>();

        try (BufferedReader reader = Files.newBufferedReader(Paths.get(filePath))) {
            String line;

            while ((line = reader.readLine()) != null) {
                // Convert to lowercase and remove punctuation
                String cleanedLine = cleanLine(line);

                // Extract and log URLs
                extractAndLogURLs(cleanedLine);

                cleanedLines.add(cleanedLine);
            }
        } catch (IOException e) {
            System.err.println("Error processing file: " + e.getMessage());
        }

        return cleanedLines;
    }

    private String cleanLine(String line) {
        // Convert to lowercase
        String lowerCase = line.toLowerCase();

        // Remove punctuation using regular expression
        return lowerCase.replaceAll("\\p{Punct}", "");
    }

    private void extractAndLogURLs(String content) {
        Matcher matcher = URL_PATTERN.matcher(content);
        while (matcher.find()) {
            try {
                new URL(matcher.group());
                logValidURL(matcher.group());
            } catch (Exception e) {
                // Invalid URL, do nothing
            }
        }
    }

    private void logValidURL(String url) {
        // Append the valid URLs to an output log file
        String logFilePath = "valid_urls.log";

        try (BufferedWriter writer = Files.newBufferedWriter(Paths.get(logFilePath), 
                                                              StandardOpenOption.CREATE, 
                                                              StandardOpenOption.APPEND)) {
            writer.write(url);
            writer.newLine();
        } catch (IOException e) {
            System.err.println("Error logging URL: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        TextFileProcessor processor = new TextFileProcessor();
        List<String> cleanedLines = processor.processTextFile("path/to/your/textfile.txt");

        // Output the result to check
        for (String line : cleanedLines) {
            System.out.println(line);
        }
    }
}
