```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Logging;

public class EncryptionService : IDisposable
{
    private readonly Aes _aes;
    private readonly IMemoryCache _cache;
    private readonly ILogger<EncryptionService> _logger;
    private static readonly object _lock = new();
    private byte[] _key;
    private byte[] _iv;
    private const int MaxDecryptionTimeMilliseconds = 1000;

    public EncryptionService(ILogger<EncryptionService> logger, IMemoryCache cache)
    {
        _aes = Aes.Create();
        _aes.Mode = CipherMode.CBC;
        _aes.Padding = PaddingMode.PKCS7;
        _cache = cache;
        _logger = logger;
    }

    public void InitializeKeyAndIV(byte[] key, byte[] iv)
    {
        if (key == null || iv == null) throw new ArgumentNullException("Key and IV must not be null.");

        ValidateLength(key.Length, 16, 24, 32);
        ValidateLength(iv.Length, 16);

        _lock.EnterWriteLock();
        try
        {
            _key = key;
            _iv = iv ?? GenerateRandomIV(16); // Default to 128 bits if IV is not provided.
        }
        finally
        {
            _lock.ExitWriteLock();
        }
    }

    public byte[] Encrypt(byte[] plaintext)
    {
        ValidatePlaintext(plaintext);

        using var encryptor = _aes.CreateEncryptor(_key, _iv);
        return ProcessCiphertext(CryptoTransformDirection.Encrypt, encryptor, plaintext);
    }

    public byte[] Decrypt(string base64CipherText)
    {
        try
        {
            if (_cache.TryGetValue(base64CipherText, out byte[] cachedResult))
                return cachedResult;

            var cipherBytes = Convert.FromBase64String(base64CipherText);
            var decryptedData = ProcessCiphertext(CryptoTransformDirection.Decrypt, GetDecryptor(), cipherBytes);

            _cache.Set(base64CipherText, decryptedData, TimeSpan.FromMinutes(5));
            LogDecryptionSuccess();

            return decryptedData;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Decryption failed.");
            return Array.Empty<byte>();
        }
    }

    private byte[] ProcessCiphertext(CryptoTransformDirection direction, ICryptoTransform transform, byte[] data)
    {
        using var ms = new MemoryStream();
        using (var cs = new CryptoStream(ms, transform, direction))
        {
            cs.Write(data, 0, data.Length);
            cs.FlushFinalBlock();
        }
        return ms.ToArray();
    }

    private void ValidatePlaintext(byte[] plaintext)
    {
        if (plaintext == null) throw new ArgumentNullException(nameof(plaintext));
    }

    private AesCryptoServiceProvider GetDecryptor()
    {
        _lock.EnterReadLock();
        try
        {
            var decryptor = _aes.CreateDecryptor(_key, _iv);
            return decryptor as AesCryptoServiceProvider;
        }
        finally
        {
            _lock.ExitReadLock();
        }
    }

    private byte[] GenerateRandomIV(int length)
    {
        using var rng = new RNGCryptoServiceProvider();
        var iv = new byte[length];
        rng.GetBytes(iv);
        return iv;
    }

    private void ValidateLength(int length, params int[] validLengths)
    {
        if (validLengths.Length == 0 || !Array.Exists(validLengths, l => l == length))
            throw new ArgumentException($"Invalid length: {length}. Valid lengths are {string.Join(", ", validLengths)}.");
    }

    private void LogDecryptionSuccess()
    {
        _logger.LogInformation("Decryption succeeded.");
    }

    public void Dispose()
    {
        _aes?.Dispose();
    }
}

// Extension method to handle the conversion of CryptoTransformDirection
public static class CryptoTransformExtensions
{
    public enum CryptoTransformDirection
    {
        Encrypt,
        Decrypt
    }
}
```

