}

int main() {
    pthread_t input_thread, graph_thread;

    pthread_create(&input_thread, NULL, read_and_process_integers, NULL);
    pthread_create(&graph_thread, NULL, modify_graph_database, NULL);

    pthread_join(input_thread, NULL);
    pthread_join(graph_thread, NULL);

    pthread_mutex_destroy(&lock);
    return 0;
}
```

