#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>

typedef struct {
    int *numbers;
    size_t count;
} data_t;

#define INITIAL_CAPACITY 16
#define LOAD_FACTOR 0.75

typedef struct hash_node {
    char *key;
    data_t value;
    struct hash_node *next;
} hash_node_t;

typedef struct {
    hash_node_t **buckets;
    size_t capacity;
    size_t size;
    pthread_rwlock_t lock;
} hash_table_t;

unsigned int hash(const char *key, size_t capacity) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++))
        hash = ((hash << 5) + hash) + c;
    return hash % capacity;
}

void init_hash_table(hash_table_t *table, size_t initial_capacity) {
    table->buckets = calloc(initial_capacity, sizeof(hash_node_t*));
    if (!table->buckets) {
        perror("Failed to allocate buckets");
        exit(EXIT_FAILURE);
    }
    table->capacity = initial_capacity;
    table->size = 0;
    pthread_rwlock_init(&table->lock, NULL);
}

void resize_hash_table_if_needed(hash_table_t *table) {
    double load_factor = (double)table->size / table->capacity;
    if (load_factor > LOAD_FACTOR) {
        size_t new_capacity = table->capacity * 2;
        hash_node_t **new_buckets = calloc(new_capacity, sizeof(hash_node_t*));
        if (!new_buckets) {
            perror("Failed to allocate new buckets");
            exit(EXIT_FAILURE);
        }

        for (size_t i = 0; i < table->capacity; ++i) {
            hash_node_t *node = table->buckets[i];
            while (node) {
                size_t index = hash(node->key, new_capacity);
                hash_node_t *next = node->next;
                node->next = new_buckets[index];
                new_buckets[index] = node;
                node = next;
            }
        }

        free(table->buckets);
        table->buckets = new_buckets;
        table->capacity = new_capacity;
    }
}

void insert_or_update(hash_table_t *table, const char *key, data_t value) {
    pthread_rwlock_wrlock(&table->lock);

    size_t index = hash(key, table->capacity);
    hash_node_t *node = table->buckets[index];
    while (node) {
        if (strcmp(node->key, key) == 0) {
            free(node->value.numbers);
            node->value = value;
            pthread_rwlock_unlock(&table->lock);
            return;
        }
        node = node->next;
    }

    hash_node_t *new_node = malloc(sizeof(hash_node_t));
    if (!new_node) {
        perror("Failed to allocate new node");
        pthread_rwlock_unlock(&table->lock);
        exit(EXIT_FAILURE);
    }
    new_node->key = strdup(key);
    new_node->value = value;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;
    ++table->size;

    resize_hash_table_if_needed(table);

    pthread_rwlock_unlock(&table->lock);
}

data_t lookup(hash_table_t *table, const char *key) {
    pthread_rwlock_rdlock(&table->lock);

    size_t index = hash(key, table->capacity);
    hash_node_t *node = table->buckets[index];
    while (node) {
        if (strcmp(node->key, key) == 0) {
            data_t value = node->value;
            pthread_rwlock_unlock(&table->lock);
            return value;
        }
        node = node->next;
    }

    pthread_rwlock_unlock(&table->lock);
    return (data_t){NULL, 0};
}

void delete(hash_table_t *table, const char *key) {
    pthread_rwlock_wrlock(&table->lock);

    size_t index = hash(key, table->capacity);
    hash_node_t *node = table->buckets[index];
    hash_node_t *prev = NULL;
    while (node) {
        if (strcmp(node->key, key) == 0) {
            if (prev) {
                prev->next = node->next;
            } else {
                table->buckets[index] = node->next;
            }
            free(node->key);
            free(node->value.numbers);
            free(node);
            --table->size;
            break;
        }
        prev = node;
        node = node->next;
    }

    pthread_rwlock_unlock(&table->lock);
}

void prune(hash_table_t *table, int (*predicate)(const char *, const data_t)) {
    pthread_rwlock_wrlock(&table->lock);

    for (size_t i = 0; i < table->capacity; ++i) {
        hash_node_t **node = &table->buckets[i];
        while (*node) {
            if (predicate((*node)->key, (*node)->value)) {
                hash_node_t *to_delete = *node;
                *node = to_delete->next;
                free(to_delete->key);
                free(to_delete->value.numbers);
                free(to_delete);
                --table->size;
            } else {
                node = &(*node)->next;
            }
        }
    }

    pthread_rwlock_unlock(&table->lock);
}

void serialize(hash_table_t *table, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    pthread_rwlock_rdlock(&table->lock);

    fwrite(&table->capacity, sizeof(size_t), 1, file);
    fwrite(&table->size, sizeof(size_t), 1, file);

    for (size_t i = 0; i < table->capacity; ++i) {
        hash_node_t *node = table->buckets[i];
        while (node) {
            size_t key_len = strlen(node->key);
            fwrite(&key_len, sizeof(size_t), 1, file);
            fwrite(node->key, sizeof(char), key_len + 1, file);

            fwrite(&node->value.count, sizeof(size_t), 1, file);
            fwrite(node->value.numbers, sizeof(int), node->value.count, file);

            node = node->next;
        }
    }

    pthread_rwlock_unlock(&table->lock);
    fclose(file);
}

void deserialize(hash_table_t *table, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    size_t new_capacity, new_size;

    fread(&new_capacity, sizeof(size_t), 1, file);
    fread(&new_size, sizeof(size_t), 1, file);

    free(table->buckets);
    table->buckets = calloc(new_capacity, sizeof(hash_node_t*));
    if (!table->buckets) {
        perror("Failed to allocate buckets");
        fclose(file);
        exit(EXIT_FAILURE);
    }
    table->capacity = new_capacity;
    table->size = 0;

    for (size_t i = 0; i < new_size; ++i) {
        size_t key_len;
        fread(&key_len, sizeof(size_t), 1, file);

        char *key = malloc(key_len + 1);
        if (!key) {
            perror("Failed to allocate memory for key");
            fclose(file);
            exit(EXIT_FAILURE);
        }
        fread(key, sizeof(char), key_len + 1, file);

        size_t count;
        fread(&count, sizeof(size_t), 1, file);

        int *numbers = malloc(count * sizeof(int));
        if (!numbers) {
            perror("Failed to allocate memory for numbers");
            free(key);
            fclose(file);
            exit(EXIT_FAILURE);
        }
        fread(numbers, sizeof(int), count, file);

        data_t value = {numbers, count};
        insert_or_update(table, key, value);
        free(key);
    }

    pthread_rwlock_init(&table->lock, NULL);
    fclose(file);
}

void cleanup_hash_table(hash_table_t *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        hash_node_t *node = table->buckets[i];
        while (node) {
            hash_node_t *next = node->next;
            free(node->key);
            free(node->value.numbers);
            free(node);
            node = next;
        }
    }
    free(table->buckets);
    pthread_rwlock_destroy(&table->lock);
}

// Example predicate function for pruning
int age_based_expiration(const char *key, const data_t value) {
    // Implement your expiration logic here
    return 0; // Return non-zero if the entry should be pruned
}

// Example usage
int main() {
    hash_table_t table;
    init_hash_table(&table, INITIAL_CAPACITY);

    data_t value = {malloc(3 * sizeof(int)), 3};
    value.numbers[0] = 1;
    value.numbers[1] = 2;
    value.numbers[2] = 3;

    insert_or_update(&table, "key1", value);
    data_t result = lookup(&table, "key1");
    printf("Value count: %zu\n", result.count);

    delete(&table, "key1");

    serialize(&table, "hash_table.bin");
    cleanup_hash_table(&table);

    hash_table_t new_table;
    init_hash_table(&new_table, INITIAL_CAPACITY);
    deserialize(&new_table, "hash_table.bin");

    cleanup_hash_table(&new_table);
    return 0;
}
