function traverseDOM(node, selector, conditionCallback, results = []) {
    if (!node || !conditionCallback || typeof node.matches !== 'function') {
        return [];
    }

    // Check if the current node matches the CSS selector and satisfies the condition
    if (node.matches(selector) && conditionCallback(node)) {
        results.push(node);
        return results;
    }

    // Recursively traverse child nodes
    for (let child of node.children || []) {
        const result = traverseDOM(child, selector, conditionCallback, results);
        if (result.length > 0) { // If a matching element is found in the subtree
            break; // Halt further traversal
        }
    }

    return results;
}

