#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int key;
    long offset;
    struct Record *next;
} Record;

typedef struct {
    Record *head;
    pthread_mutex_t lock;
} RecordList;

RecordList* create_record_list() {
    RecordList *list = (RecordList *)malloc(sizeof(RecordList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_record_list(RecordList *list) {
    Record *current = list->head;
    while (current != NULL) {
        Record *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

char* generate_new_filename(const char *filename, int min_key, int max_key) {
    if (!filename || strlen(filename) == 0) return "";

    // Determine base name and extension
    const char *base = strrchr(filename, '/');
    if (base != NULL) base++; else base = filename;

    const char *ext = strchr(base, '.');
    char ext_part[256] = {0};
    if (ext != NULL) {
        strcpy(ext_part, ext);
    } else {
        return "";
    }

    char base_name[256] = {0};
    strncpy(base_name, base, strcspn(base, ext_part));

    // Determine new file type
    char file_type[4];
    if (isalpha(base_name[0]) && strchr("aeiouAEIOU", base_name[0])) {
        strcpy(file_type, "txt");
    } else {
        strcpy(file_type, "log");
    }

    // Generate random number of digits for new extension
    int base_len = strlen(base_name);
    int num_digits = (base_len > 0) ? rand() % base_len + 1 : 3;
    char digit_str[11];
    sprintf(digit_str, "%0*d", num_digits, rand());

    // Construct new filename
    char new_filename[256] = {0};
    strncpy(new_filename, filename, strcspn(filename, ext_part));

    char new_ext[256];
    snprintf(new_ext, sizeof(new_ext), ".%s.%s", digit_str, file_type);
    strcat(new_filename, new_ext);

    return strdup(new_filename);
}

int is_key_unique(RecordList *list, int key) {
    pthread_mutex_lock(&list->lock);
    Record *current = list->head;
    while (current != NULL) {
        if (current->key == key) {
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return 1;
}

void add_record(RecordList *list, int key, long offset) {
    if (!is_key_unique(list, key)) return;

    Record *new_record = (Record *)malloc(sizeof(Record));
    new_record->key = key;
    new_record->offset = offset;
    new_record->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_record->next = list->head;
    list->head = new_record;
    pthread_mutex_unlock(&list->lock);
}

void remove_record(RecordList *list, int key) {
    pthread_mutex_lock(&list->lock);

    Record *current = list->head;
    Record *prev = NULL;

    while (current != NULL && current->key != key) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);

    pthread_mutex_unlock(&list->lock);
}

Record* find_record(RecordList *list, int key) {
    pthread_mutex_lock(&list->lock);
    Record *current = list->head;

    while (current != NULL) {
        if (current->key == key) {
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void process_records(const char *filename, int min_key, int max_key) {
    RecordList *record_list = create_record_list();
    srand(time(NULL));

    // Example: Adding records
    for (int i = 0; i < 1000000; ++i) { // Simulate large scale data
        int key = rand() % (max_key - min_key + 1) + min_key;
        long offset = rand();
        add_record(record_list, key, offset);
    }

    char *new_filename = generate_new_filename(filename, min_key, max_key);

    if (*new_filename) {
        printf("New filename: %s\n", new_filename);
    } else {
        printf("Failed to generate a new filename.\n");
    }

    free(new_filename);
    free_record_list(record_list);
}

int main() {
    const char *filename = "example/path/to/file.ext";
    process_records(filename, 1, 1000000);
    return 0;
}
