#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Record {
    int value;
    struct Record *next;
} Record;

// Function prototypes
void initialize_data(long nOffsets, int nKeys);
Record* insert_record(Record *head, int value);
Record* delete_record(Record **head, int key);
void free_records(Record *head);
int execute_command_and_update_list(const char *command, const char *filePath, const char *backupDir);

// Main function to initialize and manage data
void initialize_data(long nOffsets, int nKeys) {
    if (nOffsets <= 0 || nKeys <= 0) return;

    // Allocate memory for offsets and keys arrays
    long *offsets = malloc(nOffsets * sizeof(long));
    int *keys = malloc(nKeys * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize offsets and keys
    for (long i = 0; i < nOffsets; ++i) {
        offsets[i] = rand() % 10000;  // Example initialization
    }
    for (int j = 0; j < nKeys; ++j) {
        keys[j] = rand() % 10000;  // Example initialization
    }

    // Allocate memory for records array and linked list head
    Record *recordsArray = malloc(nOffsets * sizeof(Record));
    Record *head = NULL;

    if (!recordsArray) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize records with random values and linked list
    for (long i = 0; i < nOffsets; ++i) {
        recordsArray[i].value = rand() % 100;
        if (head == NULL) {
            head = &recordsArray[i];
        } else {
            Record *current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = &recordsArray[i];
        }
    }

    // Simulate command execution and linked list update
    execute_command_and_update_list("echo 'Command output'", "config.txt", "./backup");

    // Free allocated resources
    free(offsets);
    free(keys);
    free_records(head);
}

// Insert a new record into the linked list
Record* insert_record(Record *head, int value) {
    Record *newRecord = malloc(sizeof(Record));
    if (!newRecord) return head;
    newRecord->value = value;
    newRecord->next = head;
    return newRecord;
}

// Delete a record from the linked list by key
Record* delete_record(Record **head, int key) {
    Record *current = *head, *prev = NULL;

    while (current != NULL && current->value != key) {
        prev = current;
        current = current->next;
    }

    if (!current) return *head;  // Key not found

    if (prev == NULL) {  // Head needs to be removed
        *head = current->next;
    } else {
        prev->next = current->next;
    }
    free(current);
    return *head;
}

// Free all records in the linked list
void free_records(Record *head) {
    Record *current = head, *temp;

    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }
}

// Execute a command and update the linked list of records based on output
int execute_command_and_update_list(const char *command, const char *filePath, const char *backupDir) {
    // Check if configuration file exists
    FILE *file = fopen(filePath, "r");
    if (file) {
        fclose(file);

        // Backup and delete the file
        char backupPath[256];
        snprintf(backupPath, sizeof(backupPath), "%s/config_backup.txt", backupDir);
        remove(backupPath);  // Remove existing backup if any
        rename(filePath, backupPath);
    }

    // Execute command
    FILE *fp = popen(command, "r");
    if (!fp) {
        fprintf(stderr, "Failed to execute command.\n");
        return -1;
    }

    char buffer[128];
    Record *head = NULL;

    while (fgets(buffer, sizeof(buffer), fp)) {
        int value = atoi(buffer);
        head = insert_record(head, value);  // Update linked list with command output
    }

    if (pclose(fp) == -1) {
        fprintf(stderr, "Failed to close the process.\n");
        return -1;
    }

    // Free records after processing command output
    free_records(head);

    return 0;
}

// Initialize random number generator
int main() {
    srand((unsigned int)time(NULL));
    initialize_data(100, 50);
    return 0;
}
