#define PASSWORD_MAX 9999

// Function to check password strength
int is_strong_password(int password) {
    // Example criteria: must be a four-digit number with no repeated digits
    if (password < PASSWORD_MIN || password > PASSWORD_MAX)
        return 0;

    int digits[10] = {0};
    int temp = password;
    while (temp > 0) {
        int digit = temp % 10;
        if (++digits[digit] > 1) return 0; // Check for repeated digits
        temp /= 10;
    }
    return 1;
}

// Function to generate random integers within a specified range
int generate_random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

record* initialize_arrays(long num_offsets, int num_keys) {
    if (num_offsets <= 0 || num_keys <= 0)
        return NULL;

    // Seed the random number generator
    srand(time(NULL));

    // Allocate memory for arrays and records
    long *offsets = malloc(num_offsets * sizeof(long));
    int *keys = malloc(num_keys * sizeof(int));
    record *records = malloc(num_keys * sizeof(record));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
