        offsets[i] = generate_random_int(1, 1000); // Example range for offsets
    }

    // Initialize keys and records with valid strong passwords
    for (int i = 0; i < num_keys; ++i) {
        int key;
        do {
            key = generate_random_int(PASSWORD_MIN, PASSWORD_MAX);
        } while (!is_strong_password(key));

        keys[i] = key;
        records[i].value = key; // Initialize record with the same value as key
    }

    printf("Arrays and records initialized successfully.\n");

    // Free memory (if needed immediately after initialization)
