    *precision_ints = (int*)malloc(num_records * sizeof(int));
    *records = (Record*)malloc(num_records * sizeof(Record));
    *handlers = (Handler*)malloc(num_records * sizeof(Handler));

    if (!*precision_ints || !*records || !*handlers) {
        free(*precision_ints);
        free(*records);
        free(*handlers);
        return ERROR_CODE;
    }

    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        (*precision_ints)[i] = rand(); // Random precision integer
        (*records)[i].timestamp = *(time_t*)generate_timestamp();
        if (!(*records)[i].timestamp) {
            (*records)[i].timestamp = time(NULL); // Fallback to local clock
        }
        (*records)[i].unique_id = rand() % 10000; // Random unique ID

        (*records)[i].events = (Event**)malloc(10 * sizeof(Event*)); // Initial capacity
        if (!(*records)[i].events) {
            return ERROR_CODE;
        }
        (*records)[i].event_count = 0;

        // Initialize handler as needed
    }

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hash_table[i] = NULL;
    }

    return 0;
}

void cleanup(int* precision_ints, Record* records, Handler* handlers, int num_records) {
    if (!precision_ints || !records || !handlers) return;

    for (int i = 0; i < num_records; ++i) {
        free(records[i].events);
        // Cleanup handler as needed
    }

    free(precision_ints);
    free(records);
    free(handlers);

    // Cleanup hash table
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        Node* node = hash_table[i];
        while (node) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }
}

