int validate_identifier(const char* identifier) {
    while (*identifier) {
        if (!isalnum(*identifier) && *identifier != '-') return -1;
        identifier++;
    }
    return 0;
}

void log_message(const char *message) {
    printf("[LOG] %s\n", message);
}

Record* allocate_records(size_t size, int *error_code) {
    Record *records = (Record *)malloc(size * sizeof(Record));
    if (!records) {
        *error_code = 1;
        return NULL;
    }
    log_message("Allocated memory for records");
    return records;
}

int* allocate_int_array(size_t size, int *error_code) {
    int *array = (int *)malloc(size * sizeof(int));
    if (!array) {
        *error_code = 1;
        return NULL;
    }
    log_message("Allocated memory for integer array");
    return array;
}

long* allocate_long_array(size_t size, int *error_code) {
    long *array = (long *)malloc(size * sizeof(long));
    if (!array) {
        *error_code = 1;
        return NULL;
    }
    log_message("Allocated memory for long array");
    return array;
}

int find_largest_integer(int *arr, size_t size) {
    int largest = arr[0];
    for (size_t i = 1; i < size; i++) {
        if (arr[i] > largest) largest = arr[i];
    }
    log_message("Found the largest integer");
    return largest;
}

void sort_records(Record *records, int *keys, size_t size) {
    for (size_t i = 0; i < size - 1; i++) {
        for (size_t j = 0; j < size - i - 1; j++) {
            if (keys[j] > keys[j + 1]) {
                int temp_key = keys[j];
                keys[j] = keys[j + 1];
                keys[j + 1] = temp_key;

                Record temp_record = records[j];
                records[j] = records[j + 1];
                records[j + 1] = temp_record;
            }
        }
    }
    log_message("Sorted the records");
}

void free_memory(Record *records, size_t record_size, int *keys, long *offsets) {
    for (size_t i = 0; i < record_size; i++) {
        free(records[i].user_id);
    }
    free(records);
    free(keys);
    free(offsets);
    log_message("Freed all allocated memory");
}

int processAndSortRecords(size_t record_count, int range_min, int range_max) {
    pthread_mutex_lock(&mutex);

    int error_code = 0;
    long *offsets = allocate_long_array(record_count, &error_code);
    if (error_code) return -1;

    int *keys = allocate_int_array(record_count, &error_code);
    if (error_code) {
        free(offsets);
        return -1;
    }

    Record *records = allocate_records(record_count, &error_code);
    if (error_code) {
        free(offsets);
        free(keys);
        return -1;
    }

    for (size_t i = 0; i < record_count; i++) {
        keys[i] = rand() % (range_max - range_min + 1) + range_min;

        records[i].value = rand() % (range_max - range_min + 1) + range_min;

        char user_id[MAX_IDENTIFIER_LENGTH];
        snprintf(user_id, MAX_IDENTIFIER_LENGTH, "user-%d", i);

        if (validate_identifier(user_id)) {
            log_message("Invalid identifier format");
            free_memory(records, record_count, keys, offsets);
            return -2;
        }

        records[i].user_id = strdup(user_id);
    }

    int input_size;
    printf("Enter number of integers: ");
    scanf("%d", &input_size);

    if (input_size <= 0) {
        free_memory(records, record_count, keys, offsets);
        return -3;
    }

    int *input_array = allocate_int_array(input_size, &error_code);
    if (error_code) {
        free_memory(records, record_count, keys, offsets);
        return -1;
    }

    printf("Enter integers: ");
    for (int i = 0; i < input_size; i++) {
        scanf("%d", &input_array[i]);
    }

    int largest = find_largest_integer(input_array, input_size);
    printf("Largest integer: %d\n", largest);

    free(input_array);

    sort_records(records, keys, record_count);

    for (size_t i = 0; i < record_count; i++) {
        printf("Record %zu: Value=%d, Key=%d, User ID=%s\n",
               i, records[i].value, keys[i], records[i].user_id);
    }

    free_memory(records, record_count, keys, offsets);

    pthread_mutex_unlock(&mutex);
    return 0;
}

int main() {
    srand(time(NULL));
    processAndSortRecords(10, 1, 100);
    return 0;
}
