#include <iostream>
#include <vector>
#include <algorithm>
#include <thread>
#include <mutex>
#include <random>
#include <limits>

namespace RecordManager {

    struct Record {
        long id;
        std::vector<int> values;
        // Additional metadata can be added here

        bool operator<(const Record& other) const {
            return id < other.id;
        }
    };

    class Processor {
    private:
        std::vector<Record> records_;
        std::mutex mtx_;
        std::mt19937 rng_;

        void populateRecords(size_t size, int minVal, int maxVal) {
            std::uniform_int_distribution<long> idDist(0, std::numeric_limits<long>::max());
            std::uniform_int_distribution<int> valueDist(minVal, maxVal);

            for (size_t i = 0; i < size; ++i) {
                Record record;
                record.id = idDist(rng_);
                record.values.push_back(valueDist(rng_));
                records_.push_back(record);
            }
        }

    public:
        Processor(size_t size, int minVal, int maxVal, unsigned long seed)
            : rng_(seed) {
            if (size > 0 && size <= 10000000) {
                populateRecords(size, minVal, maxVal);
            } else {
                throw std::runtime_error("Invalid input size");
            }
        }

        void sortRecords() {
            std::lock_guard<std::mutex> lock(mtx_);
            std::sort(records_.begin(), records_.end());
        }

        void processAndSortRecords(size_t size, int minVal, int maxVal) {
            try {
                populateRecords(size, minVal, maxVal);
                sortRecords();
            } catch (const std::exception& e) {
                std::cerr << "Error: " << e.what() << '\n';
            }
        }

        void printLargestInteger() {
            int largest = std::numeric_limits<int>::min();
            int num;
            while (std::cin >> num) {
                if (num > largest) {
                    largest = num;
                }
            }
            std::cout << "Largest integer: " << largest << '\n';
        }

        ~Processor() {
            // Clean up resources if necessary
        }
    };

} // namespace RecordManager

void stressTest() {
    const size_t dataSize = 10000000; // Test with maximum data size
    int minValue = -1000, maxValue = 1000;
    unsigned long seed = 12345;

    RecordManager::Processor processor(dataSize, minValue, maxValue, seed);

    std::thread t1(&RecordManager::Processor::processAndSortRecords, &processor, dataSize, minValue, maxValue);
    std::thread t2(&RecordManager::Processor::processAndSortRecords, &processor, dataSize / 2, minValue, maxValue);

    t1.join();
    t2.join();

    processor.printLargestInteger(); // Test the helper function
}

int main() {
    stressTest();
    return 0;
}
