    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGHUP, &sa, NULL);

    log_file = fopen("pipeline.log", "a");
    if (!log_file) {
        free(offsets);
        free(keys);
        free(data_values);
        free(records);
        log_message("Failed to open log file.");
        exit(EXIT_FAILURE);
    }

    // Example of deleting files and executing commands
    const char *files_to_delete[] = {"file1.txt", "file2.txt"};
    size_t num_files = sizeof(files_to_delete) / sizeof(files_to_delete[0]);
    pthread_t threads[num_files];

    for (size_t i = 0; i < num_files; ++i) {
        if (access(files_to_delete[i], F_OK) != -1) {
            if (remove(files_to_delete[i]) == 0) {
                log_message("File deleted.");
            } else {
                char msg[256];
                sprintf(msg, "Failed to delete file: %s", files_to_delete[i]);
                log_message(msg);
            }
        }

        pthread_create(&threads[i], NULL, execute_command, (void *)(intptr_t)i);
    }

    for (size_t i = 0; i < num_files; ++i) {
        pthread_join(threads[i], NULL);
    }

    fclose(log_file);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(data_values);
    free(records);
}

void handle_signal(int signal) {
    log_message("Received signal, cleaning up...");
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

void* execute_command(void *arg) {
    size_t index = (size_t)(intptr_t)arg;
    const char *commands[] = {"echo 'Command 1'", "echo 'Command 2'"};

    FILE *fp = popen(commands[index], "r");
