            std::lock_guard<std::mutex> lock(mtx);
            records.push_back({value});
        }

        const std::vector<Record>& getRecords() const {
            return records;
        }
    };

    class DataProcessor {
    private:
        DatabaseManager& dbManager;
        DataManager& dataManager;

    public:
        DataProcessor(DatabaseManager& db, DataManager& dm) : 
            dbManager(db), dataManager(dm) {}

        void process(int numRecords) {
            std::string createTable = "CREATE TABLE IF NOT EXISTS records (id INTEGER PRIMARY KEY, value INT);";
            if (!dbManager.execute(createTable)) return;

            for (int i = 0; i < numRecords; ++i) {
                DataGenerator generator(1, 100);
                int randomValue = generator.generate();
                dataManager.addRecord(randomValue);

                if (!dbManager.insertRecord(randomValue)) {
                    std::cerr << "Failed to insert record" << std::endl;
                }
            }
        }

