        static void showRecords(const std::vector<T>& records) {
            for (const auto& record : records) {
                std::cout << "Record Value: " << record.value << std::endl;
            }
        }
    };

} // namespace DynamicDataProcessor

int main() {
    using namespace DynamicDataProcessor;

    DatabaseManager db("records.db");
    DataManager dataManager;
    DataProcessor processor(db, dataManager);

    UserInterface::display("Starting Data Processing...");

