#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

// Define struct node to hold string data
typedef struct Node {
    char *data;
    struct Node *next;
} Node;

// Global variables for the three distinct structures
double *floatArray = NULL;
Node *head = NULL;
char **strArray = NULL;

// Mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize memory and structures
void initMemory(int doubleCount, int strCount) {
    pthread_mutex_lock(&lock);

    // Allocate memory for float array
    floatArray = (double *)malloc(doubleCount * sizeof(double));
    if (!floatArray) {
        fprintf(stderr, "Failed to allocate memory for floats\n");
        exit(EXIT_FAILURE);
    }

    // Initialize string array
    strArray = (char **)malloc(strCount * sizeof(char *));
    if (!strArray) {
        fprintf(stderr, "Failed to allocate memory for strings\n");
        free(floatArray);
        pthread_mutex_unlock(&lock);
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < strCount; i++) {
        strArray[i] = NULL;
    }

    // Initialize linked list
    head = NULL;

    pthread_mutex_unlock(&lock);
}

// Function to insert a node into the linked list
void insertNode(const char *data) {
    Node *newNode = (Node *)malloc(sizeof(Node));
    if (!newNode) {
        fprintf(stderr, "Failed to allocate memory for new node\n");
        return;
    }

    newNode->data = strdup(data);
    if (!newNode->data) {
        free(newNode);
        return;
    }
    newNode->next = NULL;

    pthread_mutex_lock(&lock);

    // Insert at the beginning of the list
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

// Function to print all nodes in the linked list
void traverseList() {
    Node *current = head;

    pthread_mutex_lock(&lock);

    while (current != NULL) {
        printf("Node data: %s\n", current->data);
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

// Function to delete a node from the linked list
void deleteNode(const char *data) {
    Node *current = head;
    Node *prev = NULL;

    pthread_mutex_lock(&lock);

    while (current != NULL && strcmp(current->data, data) != 0) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&lock);
        return; // Node not found
    }

    if (prev == NULL) { // Deleting head node
        head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current->data);
    free(current);

    pthread_mutex_unlock(&lock);
}

// Function to verify the integrity of the linked list
int verifyList() {
    Node *current = head;

    while (current != NULL) {
        if (!current->data || !current->next) {
            pthread_mutex_lock(&lock);
            traverseList();
            pthread_mutex_unlock(&lock);
            return 0; // Integrity check failed
        }
        current = current->next;
    }

    return 1; // Integrity check passed
}

// Function to clean up resources
void cleanup() {
    Node *current = head;

    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp->data);
        free(temp);
    }
    head = NULL;

    if (floatArray) {
        free(floatArray);
    }

    for (int i = 0; strArray && i < sizeof(strArray)/sizeof(char*); i++) {
        if (strArray[i]) {
            free(strArray[i]);
        }
    }

    if (strArray) {
        free(strArray);
    }

    pthread_mutex_destroy(&lock);
}

// Example usage
int main() {
    initMemory(100, 50);

    insertNode("First Node");
    insertNode("Second Node");

    traverseList();

    deleteNode("First Node");

    if (verifyList()) {
        printf("Linked list integrity verified.\n");
    } else {
        printf("Linked list integrity check failed.\n");
    }

    cleanup();

    return 0;
}
```

