char* perform_http_request(const char *url, int *error_code) {
    CURL *curl;
    CURLcode res;
    MemoryStruct chunk;

    chunk.size = 0;
    chunk.data = malloc(1); // will be grown as needed by the realloc above
    if (!chunk.data) {
        *error_code = -1;
        return NULL;
    }

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if(curl) {
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Authorization: Bearer ");
        headers = curl_slist_append(headers, oauth_token);

        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, fwrite);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);

        res = curl_easy_perform(curl);

        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            *error_code = -2;
        } else {
            *error_code = 0;
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);

        // Handle response
        if (chunk.size > 0) {
            chunk.data = realloc(chunk.data, chunk.size + 1);
            if (!chunk.data) {
                *error_code = -3;
                return NULL;
            }
            chunk.data[chunk.size] = '\0';
        } else {
            free(chunk.data);
            chunk.data = NULL;
            *error_code = -4;
        }

    } else {
        *error_code = -5;
        free(chunk.data);
        curl_global_cleanup();
    }

    return chunk.data;
}

void refresh_oauth_token() {
    pthread_mutex_lock(&mutex);
    // Example: Fetch new token logic
    strcpy(oauth_token, "new_access_token");
    time_t now = time(NULL);
    token_expiry_time = now + 3600; // Assume token valid for an hour
    pthread_mutex_unlock(&mutex);
}

