    getrlimit(RLIMIT_AS, &rl);

    if (rl.rlim_cur > MAX_MEMORY_USAGE) {
        rl.rlim_cur = MAX_MEMORY_USAGE;
        setrlimit(RLIMIT_AS, &rl);
    }
}

int main(int argc, char *argv[]) {
