// Definitions for file event structures
typedef struct {
    size_t block_size;
    void* data;
} FILE_BLOCK_DATA;

typedef struct {
    int tag; // FILE_EVENT_TAG
    size_t file_size;
    time_t last_modified;
    size_t num_blocks;
    FILE_BLOCK_DATA* blocks;
} FileEvent;

// Structure to manage a dynamic list of file events with thread safety
typedef struct {
    FileEvent** events;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} FileEventList;

// Function prototypes
FileEventList* createFileEventList(size_t initial_capacity);
int addFileBlock(FileEventList* list, int event_tag, size_t file_size, time_t last_modified, FILE_BLOCK_DATA block);
void resizeFileEventList(FileEventList* list, size_t new_capacity);

// Create a new FileEventList with the given initial capacity
FileEventList* createFileEventList(size_t initial_capacity) {
    FileEventList* list = (FileEventList*)malloc(sizeof(FileEventList));
    if (!list) return NULL;

    list->events = (FileEvent**)calloc(initial_capacity, sizeof(FileEvent*));
    if (!list->events) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);

    return list;
}

// Add a block to an event or create a new event if not existing
int addFileBlock(FileEventList* list, int event_tag, size_t file_size, time_t last_modified, FILE_BLOCK_DATA block) {
    if (!list || !block.data) return -1;

    pthread_mutex_lock(&list->lock);

    // Find the event with the given tag or create a new one
    FileEvent* event = NULL;
    for (size_t i = 0; i < list->count; ++i) {
        if (list->events[i]->tag == event_tag) {
            event = list->events[i];
            break;
        }
    }

    if (!event) {
        // Resize if necessary
        if (list->count >= list->capacity) {
            resizeFileEventList(list, list->capacity * 2);
        }

        event = (FileEvent*)malloc(sizeof(FileBlockData));
        if (!event) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }

        event->tag = event_tag;
        event->file_size = file_size;
        event->last_modified = last_modified;
        event->num_blocks = 0;

        list->events[list->count++] = event;
    }

    // Resize blocks array if necessary
    if (event->num_blocks >= (event->capacity ?: 1)) {
        size_t new_capacity = event->capacity ? event->capacity * 2 : 4;
        FILE_BLOCK_DATA* new_blocks = realloc(event->blocks, new_capacity * sizeof(FILE_BLOCK_DATA));
        if (!new_blocks) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        event->blocks = new_blocks;
        event->capacity = new_capacity;
    }

    // Add the block
    FILE_BLOCK_DATA* new_block = &event->blocks[event->num_blocks++];
    new_block->block_size = block.block_size;
    new_block->data = malloc(block.block_size);
    if (!new_block->data) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    memcpy(new_block->data, block.data, block.block_size);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Resize the FileEventList to accommodate more events
void resizeFileEventList(FileEventList* list, size_t new_capacity) {
    FileEvent** new_events = (FileEvent**)realloc(list->events, new_capacity * sizeof(FileEvent*));
    if (!new_events) return;

    memset(new_events + list->count, 0, (new_capacity - list->count) * sizeof(FileEvent*));
    list->events = new_events;
    list->capacity = new_capacity;
}

// Clean up the FileEventList
void destroyFileEventList(FileEventList* list) {
    if (!list) return;

    for (size_t i = 0; i < list->count; ++i) {
        FileEvent* event = list->events[i];
        for (size_t j = 0; j < event->num_blocks; ++j) {
            free(event->blocks[j].data);
        }
        free(event->blocks);
        free(event);
    }

    free(list->events);
    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond);
    free(list);
}
