#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

typedef struct {
    float value;
    int id;
    bool active;
} Element;

typedef struct Node {
    void *data; // Can store any type, use casting as needed.
    struct Node *next;
} Node;

typedef struct HashTable {
    size_t size;
    Node **buckets;
} HashTable;

// Function prototypes
HashTable* createHashTable(size_t size);
void freeHashTable(HashTable *table);
unsigned long hash(void *data, size_t size, size_t tableSize);
Node* createNode(void *data);
void insertHashTable(HashTable *table, void *data, size_t dataSize);
void resizeHashTable(HashTable **table);

// Function to initialize and manage arrays
int initializeDataStructures(double **doubleArray, char **charArray, Element ***elementPtrArray, size_t numElements) {
    // Allocate memory for double array
    *doubleArray = (double *)malloc(numElements * sizeof(double));
    if (*doubleArray == NULL) return -1;

    // Allocate memory for char array
    *charArray = (char *)malloc(numElements * sizeof(char));
    if (*charArray == NULL) {
        free(*doubleArray);
        return -1;
    }

    // Allocate memory for element pointer array and its elements
    *elementPtrArray = (Element **)malloc(numElements * sizeof(Element *));
    if (*elementPtrArray == NULL) {
        free(*doubleArray);
        free(*charArray);
        return -1;
    }

    for (size_t i = 0; i < numElements; ++i) {
        (*elementPtrArray)[i] = (Element *)malloc(sizeof(Element));
        if ((*elementPtrArray)[i] == NULL) {
            // Free previously allocated memory
            while (i > 0) {
                free((*elementPtrArray)[--i]);
            }
            free(*doubleArray);
            free(*charArray);
            free(*elementPtrArray);
            return -1;
        }
    }

    // Create a hash table for efficient data management
    HashTable *hashTable = createHashTable(101); // Initial size, should be prime

    if (hashTable == NULL) {
        for (size_t i = 0; i < numElements; ++i) {
            free((*elementPtrArray)[i]);
        }
        free(*doubleArray);
        free(*charArray);
        free(*elementPtrArray);
        return -1;
    }

    // Example of inserting data into the hash table
    for (size_t i = 0; i < numElements; ++i) {
        insertHashTable(hashTable, *elementPtrArray + i, sizeof(Element));
    }

    printf("Data structures initialized successfully.\n");

    // Return a success code or handle hashTable lifecycle outside this function

    return 0;
}

// Hash table functions
HashTable* createHashTable(size_t size) {
    HashTable *table = (HashTable *)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->size = size;
    table->buckets = (Node **)calloc(size, sizeof(Node *));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    return table;
}

void freeHashTable(HashTable *table) {
    for (size_t i = 0; i < table->size; ++i) {
        Node *current = table->buckets[i];
        while (current) {
            Node *next = current->next;
            free(current);
            current = next;
        }
    }
    free(table->buckets);
    free(table);
}

unsigned long hash(void *data, size_t dataSize, size_t tableSize) {
    unsigned char *bytes = (unsigned char *)data;
    unsigned long h = 5381;
    for (size_t i = 0; i < dataSize; ++i)
        h = ((h << 5) + h) + bytes[i]; /* hash * 33 + c */
    return h % tableSize;
}

Node* createNode(void *data) {
    Node *node = (Node *)malloc(sizeof(Node));
    if (!node) return NULL;

    node->data = data;
    node->next = NULL;
    return node;
}

void insertHashTable(HashTable *table, void *data, size_t dataSize) {
    unsigned long index = hash(data, dataSize, table->size);
    Node *newNode = createNode(data);

    if (!newNode) return;

    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;
}

void resizeHashTable(HashTable **table) {
    size_t newSize = (*table)->size * 2;
    Node **newBuckets = (Node **)calloc(newSize, sizeof(Node *));

    if (!newBuckets) return;

    for (size_t i = 0; i < (*table)->size; ++i) {
        Node *current = (*table)->buckets[i];
        while (current) {
            Node *next = current->next;
            unsigned long newIndex = hash(current->data, sizeof(Element), newSize);
            current->next = newBuckets[newIndex];
            newBuckets[newIndex] = current;
            current = next;
        }
    }

    free((*table)->buckets);
    (*table)->size = newSize;
    (*table)->buckets = newBuckets;
}

int main() {
    double *doubleArray;
    char *charArray;
    Element **elementPtrArray;

    if (initializeDataStructures(&doubleArray, &charArray, &elementPtrArray, 10) != 0) {
        fprintf(stderr, "Failed to initialize data structures.\n");
        return EXIT_FAILURE;
    }

    // Free allocated resources
    free(doubleArray);
    free(charArray);
    for (size_t i = 0; i < 10; ++i) {
        free(elementPtrArray[i]);
    }
    free(elementPtrArray);

    return EXIT_SUCCESS;
}
```

### Key Points:
