- **Hash Table**: Uses separate chaining with a dynamic resizing mechanism to handle collisions and growth efficiently.
- **Thread Safety & Synchronization**: Not explicitly implemented in this example. In production, consider using mutexes or other synchronization primitives for concurrent access.
- **Scalability**: The hash table can be resized dynamically as the dataset grows, ensuring efficient performance over time.

This implementation provides a foundation that can be expanded to meet specific application requirements, such as integrating with external libraries and handling various data formats.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct NetworkPerformanceMetrics {
    int cellId;
    time_t timeStamp;
    double throughput;
} NetworkPerformanceMetrics;

typedef struct Node {
    NetworkPerformanceMetrics data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* init_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

NetworkPerformanceMetrics* allocate_metrics_array(size_t count, int seed, double min_throughput, double max_throughput) {
    NetworkPerformanceMetrics* array = (NetworkPerformanceMetrics*)malloc(count * sizeof(NetworkPerformanceMetrics));
    if (!array) return NULL;

    srand(seed);

    for (size_t i = 0; i < count; ++i) {
        array[i].cellId = rand() % 1000;
        array[i].timeStamp = time(NULL);
        array[i].throughput = min_throughput + ((double)rand() / RAND_MAX) * (max_throughput - min_throughput);
    }

    return array;
}

void calculate_moving_average(NetworkPerformanceMetrics* array, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        double sum = 0.0;
        int num_elements = 0;

        for (int j = i - 9; j <= i && j >= 0; ++j) {
            sum += array[j].throughput;
            num_elements++;
        }

        if (num_elements > 0) {
            double moving_average = sum / num_elements;
            array[i].throughput = moving_average;
        }
    }
}

void insert_into_list(LinkedList* list, NetworkPerformanceMetrics metric) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;

    new_node->data = metric;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

void initialize_and_populate(size_t count, int seed, double min_throughput, double max_throughput, LinkedList* list) {
    NetworkPerformanceMetrics* metrics_array = allocate_metrics_array(count, seed, min_throughput, max_throughput);
    if (!metrics_array) return;

    calculate_moving_average(metrics_array, count);

    for (size_t i = 0; i < count; ++i) {
        insert_into_list(list, metrics_array[i]);
    }

    free(metrics_array);
}

void dynamic_resize(LinkedList* list, size_t new_count, int seed, double min_throughput, double max_throughput) {
    NetworkPerformanceMetrics* temp_array = allocate_metrics_array(new_count, seed, min_throughput, max_throughput);
    if (!temp_array) return;

    calculate_moving_average(temp_array, new_count);

    for (size_t i = 0; i < new_count; ++i) {
        insert_into_list(list, temp_array[i]);
    }

    free(temp_array);
}

void cleanup(LinkedList* list) {
    free_linked_list(list);
}
```

