// Define a record structure
typedef struct {
    int key;
    long offset;
    double dataValue;
} Record;

// Logger function
void log_message(const char *message) {
    FILE *log_file = fopen("app_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

// Signal handler for graceful shutdown
volatile sig_atomic_t keep_running = 1;
void handle_signal(int signal) {
    keep_running = 0;
}

// AES-256-CBC initialization
EVP_CIPHER_CTX* initialize_aes(const char *password) {
    unsigned char salt[8];
    RAND_bytes(salt, sizeof(salt));

    // Derive key using EVP_BytesToKey
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
    int key_length = 32; // AES-256

    PKCS5_PBKDF2_HMAC(password, strlen(password), salt, sizeof(salt),
                      10000, EVP_sha256(), key_length, key);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        log_message("AES initialization failed");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

// Function to free AES context
void free_aes_context(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
}

// Memory allocation and error handling function
Record* allocate_and_initialize_records(size_t num_records, long **offsets, int **keys, double **dataValues) {
    Record *records = NULL;
    offsets = malloc(sizeof(long *));
    keys = malloc(sizeof(int *));
    dataValues = malloc(sizeof(double *));

    if (!offsets || !keys || !dataValues) {
        log_message("Memory allocation for arrays failed");
        goto error_cleanup;
    }

    *offsets = malloc(num_records * sizeof(long));
    *keys = malloc(num_records * sizeof(int));
    *dataValues = malloc(num_records * sizeof(double));

    if (!(*offsets) || !(*keys) || !(*dataValues)) {
        log_message("Memory allocation for arrays failed");
        goto error_cleanup;
    }

    records = calloc(num_records, sizeof(Record));
    if (!records) {
        log_message("Memory allocation for records failed");
        goto error_cleanup;
    }

    // Initialize the data
    for (size_t i = 0; i < num_records; ++i) {
        (*offsets)[i] = (long)i * 10;
        (*keys)[i] = (int)i;
        (*dataValues)[i] = (double)(i + 0.5);

        records[i].key = (*keys)[i];
        records[i].offset = (*offsets)[i];
        records[i].dataValue = (*dataValues)[i];
    }

    return records;

error_cleanup:
    if (records) free(records);
    if (*offsets) free(*offsets);
    if (*keys) free(*keys);
    if (*dataValues) free(*dataValues);
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (dataValues) free(dataValues);

    return NULL;
}

// Function to manage file deletion and command execution
void execute_command(const char *command, const char *filePath) {
    struct stat buffer;
    if (stat(filePath, &buffer) == 0) {
        unlink(filePath); // Delete the file if it exists
    }

    clock_t start = clock();

    FILE *fp = popen(command, "r");
    if (!fp) {
        log_message("Command execution failed");
        return;
    }

    char line[128];
    while (fgets(line, sizeof(line), fp) != NULL) {
        // Process the output
    }

    pclose(fp);

    clock_t end = clock();
    double time_taken = ((double)(end - start)) / CLOCKS_PER_SEC;
    log_message("Command execution completed in: ");
    char timeLog[50];
    snprintf(timeLog, sizeof(timeLog), "%f seconds", time_taken);
    log_message(timeLog);
}

