#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
#include <time.h>
#include <string.h>
#include <stdint.h>

// Assuming record is defined as follows:
typedef struct {
    int value;
} record;

#define ERROR_CODE -1

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static unsigned long call_count = 0;
static double total_duration = 0.0;

void log_execution(unsigned long count, double duration) {
    printf("Call Count: %lu\n", count);
    printf("Total Duration: %.2f seconds\n", duration);
}

int imageToPdfConverter(const char* jpegFile, const char* pdfFile) {
    pthread_mutex_lock(&mutex);

    clock_t start_time = clock();

    // Update call count
    call_count++;

    int num;
    int largest_int = INT_MIN;

    printf("Enter integers (end with non-integer input):\n");
    while (scanf("%d", &num) == 1) {
        if (num > largest_int) {
            pthread_mutex_lock(&pthread_mutex_t temp_mutex);
            largest_int = num; // Store in thread-safe manner
            pthread_mutex_unlock(&temp_mutex);
        }
    }

    unsigned long offset_count = rand() % 100 + 1;
    size_t key_size = sizeof(int) * offset_count;
    int* keys = (int*)malloc(key_size);

    if (!keys) {
        pthread_mutex_unlock(&mutex);
        return ERROR_CODE; // Handle memory allocation failure
    }

    for (unsigned long i = 0; i < offset_count; ++i) {
        keys[i] = rand() % largest_int;
    }

    record* records = (record*)malloc(offset_count * sizeof(record));
    if (!records) {
        free(keys);
        pthread_mutex_unlock(&mutex);
        return ERROR_CODE;
    }

    for (unsigned long i = 0; i < offset_count; ++i) {
        records[i].value = rand() % largest_int;
    }

    // Sort records based on keys
    qsort(records, offset_count, sizeof(record), 
          (int (*)(const void*, const void*))((a, b) -> int) { return keys[a - records] - keys[b - records]; });

    char command[256];
    snprintf(command, sizeof(command), "convert %s %s", jpegFile, pdfFile);

    if (system(command) != 0) {
        fprintf(stderr, "Conversion failed.\n");
    }

    free(keys);
    free(records);

    clock_t end_time = clock();
    double duration = ((double)(end_time - start_time)) / CLOCKS_PER_SEC;
    total_duration += duration;

    log_execution(call_count, total_duration);

    pthread_mutex_unlock(&mutex);

    return 0; // Success
}
```

