#include <stdio.h>
#include <stdlib.h>

#define MAX_UE 1000
#define DEFAULT_POWER_CONTROL_VALUE 10
#define M 5

typedef struct {
    int ue_id;
    int radio_resources[M];
    int power_control_settings;
    int allocated_bandwidth;
} LTE_UE_Context;

typedef struct {
    LTE_UE_Context contexts[MAX_UE];
    int bandwidth_pool;
    int active_ue_count;
} LTE_System;

void initialize_lte_system(LTE_System *system, int total_bandwidth) {
    system->bandwidth_pool = total_bandwidth;
    system->active_ue_count = 0;

    for (int i = 0; i < MAX_UE; ++i) {
        system->contexts[i].ue_id = -1; // Indicates unused context
        system->contexts[i].power_control_settings = DEFAULT_POWER_CONTROL_VALUE;
        system->contexts[i].allocated_bandwidth = 0;
        for (int j = 0; j < M; ++j) {
            system->contexts[i].radio_resources[j] = 0; // No resource allocated initially
        }
    }
}

int allocate_ue_context(LTE_System *system, int ue_id, int requested_bandwidth) {
    if (system->active_ue_count >= MAX_UE) {
        return -1; // Maximum UE contexts reached
    }

    for (int i = 0; i < MAX_UE; ++i) {
        if (system->contexts[i].ue_id == -1) { // Find an unused context
            system->contexts[i].ue_id = ue_id;

            // Check bandwidth availability
            if (requested_bandwidth > system->bandwidth_pool) {
                return -2; // Insufficient bandwidth in pool
            }

            system->contexts[i].allocated_bandwidth = requested_bandwidth;
            system->bandwidth_pool -= requested_bandwidth;
            ++system->active_ue_count;

            // Initialize radio resources allocation (simplified example)
            for (int j = 0; j < M && j < requested_bandwidth / 10; ++j) {
                system->contexts[i].radio_resources[j] = 1; // Allocate resource
            }

            return i; // Return index of allocated UE context
        }
    }

    return -3; // No available contexts found
}

void free_ue_context(LTE_System *system, int ue_index) {
    if (ue_index < 0 || ue_index >= MAX_UE || system->contexts[ue_index].ue_id == -1) {
        return; // Invalid context index or already freed
    }

    system->bandwidth_pool += system->contexts[ue_index].allocated_bandwidth;
    system->contexts[ue_index].ue_id = -1; // Mark as unused
    system->active_ue_count--;

    for (int j = 0; j < M; ++j) {
        system->contexts[ue_index].radio_resources[j] = 0;
    }
}

void print_system_status(const LTE_System *system) {
    printf("Active UE Count: %d\n", system->active_ue_count);
    printf("Available Bandwidth Pool: %d\n", system->bandwidth_pool);

    for (int i = 0; i < MAX_UE && system->contexts[i].ue_id != -1; ++i) {
        printf("UE ID: %d, Allocated Bandwidth: %d\n",
               system->contexts[i].ue_id,
               system->contexts[i].allocated_bandwidth);
    }
}

int main() {
    LTE_System lte_system;
    initialize_lte_system(&lte_system, 10000); // Total bandwidth of 10000 units

    int ue_index = allocate_ue_context(&lte_system, 1, 2000);
    if (ue_index < 0) {
        printf("Failed to allocate UE context: %d\n", ue_index);
    } else {
        printf("UE Context allocated at index: %d\n", ue_index);
    }

    print_system_status(&lte_system);

    free_ue_context(&lte_system, ue_index);
    print_system_status(&lte_system);

    return 0;
}
```

