namespace DataProcessing {

    class DataProcessor {
    public:
        DataProcessor(size_t size, unsigned int seed);
        ~DataProcessor();

        void process();
        void serializeToFile(const std::string& filename);

    private:
        std::vector<long> offsets;
        std::vector<int> keys;
        std::vector<double> measurements;

        double mean;
        double median;
        double stddev;

        static const unsigned int errorCode = 1;

        void computeStatistics();
        void findMinMax(const std::vector<double>& data);
        bool updateSeedFromExternalSource();

    private:
        mutable std::mutex mtx; // Mutex for thread safety
    };

    DataProcessor::DataProcessor(size_t size, unsigned int seed) : mean(0), median(0), stddev(0) {
        std::mt19937 generator(seed);

        try {
            offsets.resize(size);
            keys.resize(size);
            measurements.resize(size);

            std::uniform_int_distribution<long> distLong(-10000, 10000);
            std::uniform_int_distribution<int> distInt(-5000, 5000);
            std::uniform_real_distribution<double> distDouble(0.0, 1.0);

            for (size_t i = 0; i < size; ++i) {
                offsets[i] = distLong(generator);
                keys[i] = distInt(generator);
                measurements[i] = distDouble(generator);
            }

        } catch (...) {
            std::cerr << "Memory allocation failed" << std::endl;
            exit(errorCode);
        }
    }

    DataProcessor::~DataProcessor() {}

    void DataProcessor::process() {
        std::lock_guard<std::mutex> lock(mtx);

        computeStatistics();
        findMinMax(measurements);
    }

    void DataProcessor::computeStatistics() {
        size_t n = measurements.size();

        double sum = 0;
        for (double value : measurements) {
            sum += value;
        }
        mean = sum / n;

        std::vector<double> sortedMeasurements = measurements;
        std::sort(sortedMeasurements.begin(), sortedMeasurements.end());
        median = sortedMeasurements[n / 2];

        double sq_sum = 0;
        for (double value : measurements) {
            sq_sum += value * value;
        }
        stddev = std::sqrt(sq_sum / n - mean * mean);
    }

    void DataProcessor::findMinMax(const std::vector<double>& data) {
        auto it = data.begin();
        double minVal = *it, maxVal = *it;

        for (++it; it != data.end(); ++it) {
            if (*it < minVal) minVal = *it;
            if (*it > maxVal) maxVal = *it;
        }

        std::cout << "Min: " << minVal << ", Max: " << maxVal << '\n';
    }

    void DataProcessor::serializeToFile(const std::string& filename) {
        std::lock_guard<std::mutex> lock(mtx);

        std::ofstream file(filename);
        if (!file.is_open()) {
            std::cerr << "Failed to open file for serialization" << std::endl;
            return;
        }

        file << "Mean: " << mean << "\nMedian: " << median << "\nStandard Deviation: " << stddev << '\n';
    }

    bool DataProcessor::updateSeedFromExternalSource() {
        // Implement seed update logic here, potentially involving network operations
        // For now, return false to indicate no update occurred
        return false;
    }
}

int main() {
