#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CHILDREN 2 // For binary tree
#define CHAR_ARRAY_SIZE 256
#define NUM_NODES 100
#define NUM_EDGES_PER_NODE 10

typedef struct Edge {
    void *destination;
    double weight;
} Edge;

typedef struct Node {
    int key;
    struct Node **children;
    Edge *edges;
} Node;

typedef struct MemoryPool {
    size_t block_size;
    unsigned char *pool;
    size_t pool_size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool *initialize_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool *mp = (MemoryPool *)malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->block_size = block_size;
    mp->pool_size = block_size * num_blocks;
    mp->pool = (unsigned char *)malloc(mp->pool_size);
    if (!mp->pool) {
        free(mp);
        return NULL;
    }
    pthread_mutex_init(&mp->lock, NULL);

    return mp;
}

void *memory_pool_alloc(MemoryPool *mp) {
    if (!mp || mp->pool_size <= 0)
        return NULL;

    pthread_mutex_lock(&mp->lock);
    void *block = mp->pool + (mp->pool_size -= mp->block_size);
    pthread_mutex_unlock(&mp->lock);

    return block;
}

void release_memory_pool(MemoryPool *mp) {
    if (!mp) return;
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

int allocate_and_initialize_data_structures(double **double_array, char (*char_strings)[CHAR_ARRAY_SIZE], Node ***node_pointers, Edge ***edge_pointers, MemoryPool *memory_pool) {
    if (!memory_pool) return -1;

    // Allocate and initialize the double array
    *double_array = (double *)memory_pool_alloc(memory_pool);
    if (!*double_array)
        return -2;
    for (int i = 0; i < NUM_NODES; ++i)
