    if (!*char_strings)
        return -3;
    for (int i = 0; i < NUM_NODES; ++i) {
        snprintf((*char_strings)[i], CHAR_ARRAY_SIZE, "String %d", i);
    }

    // Allocate and initialize node pointers
    *node_pointers = (Node **)memory_pool_alloc(memory_pool);
    if (!*node_pointers)
        return -4;
    for (int i = 0; i < NUM_NODES; ++i) {
        (*node_pointers)[i] = (Node *)memory_pool_alloc(memory_pool);
        if (!(*node_pointers)[i])
            return -5;

        // Initialize node structure
        (*node_pointers)[i]->key = rand() % 1000; // Random key within range
        (*node_pointers)[i]->children = (Node **)malloc(MAX_CHILDREN * sizeof(Node *));
        memset((*node_pointers)[i]->children, 0, MAX_CHILDREN * sizeof(Node *));

        // Allocate and initialize edges for each node
        (*node_pointers)[i]->edges = (Edge *)memory_pool_alloc(memory_pool);
        if (!(*node_pointers)[i]->edges)
            return -6;

        for (int j = 0; j < NUM_EDGES_PER_NODE; ++j) {
            (*node_pointers)[i]->edges[j].destination = NULL; // In a real implementation, this should point to another node
            (*node_pointers)[i]->edges[j].weight = ((double)rand() / RAND_MAX); // Assign random weight
        }
    }

    // Allocate and initialize edge pointers
    *edge_pointers = (Edge **)memory_pool_alloc(memory_pool);
    if (!*edge_pointers)
        return -7;
    for (int i = 0; i < NUM_NODES; ++i) {
        (*edge_pointers)[i] = (Edge *)malloc(NUM_EDGES_PER_NODE * sizeof(Edge));
        if (!(*edge_pointers)[i])
            return -8;

        // Initialize edges
        for (int j = 0; j < NUM_EDGES_PER_NODE; ++j) {
            (*edge_pointers)[i][j].destination = NULL;
            (*edge_pointers)[i][j].weight = ((double)rand() / RAND_MAX);
        }
    }

    return 0; // Success
}

void cleanup(double *double_array, char (*char_strings)[CHAR_ARRAY_SIZE], Node **node_pointers, MemoryPool *memory_pool) {
    if (double_array)
        free(double_array); // Assuming single allocation for simplicity in this example

    if (char_strings)
        free(char_strings);

    if (node_pointers) {
        for (int i = 0; i < NUM_NODES; ++i) {
            if (node_pointers[i]) {
                free(node_pointers[i]->children);
                free(node_pointers[i]);
            }
        }
        free(node_pointers);
    }

    release_memory_pool(memory_pool);
}

int main() {
