    if (tag->RNTI <= 0) {  // Example condition, modify as needed
        fprintf(stderr, "Invalid CRC Tag\n");
        exit(1);
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu_list(size_t count, int seed) {
    pthread_t threads[MAX_THREADS];
    size_t per_thread = count / MAX_THREADS;
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdus == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    srand(seed);

    void* thread_func(void* arg) {
        size_t start_idx = *(size_t*)arg;
        for (size_t i = start_idx; i < start_idx + per_thread && i < count; ++i) {
            NFAPI_CRC_INDICATION_PDU_T *pdu = &pdus[i];
            pdu->RX_UE_INFORMATION_TAG = rand() % 1000; // Example value
            pdu->RNTI = rand() % 100000;

            pdu->CRC_DATA.RX_UE_INFORMATION_TAG = pdu->RX_UE_INFORMATION_TAG;
            pdu->CRC_DATA.RNTI = pdu->RNTI;
            validate_crc_tag(&pdu->CRC_DATA);

            pthread_mutex_lock(&lock);
            pdu->CRCFLAG = rand() % 2; // Random CRC flag
            fprintf(log_file, "Created PDU: RNTI=%d, CRCFLAG=%d\n", pdu->RNTI, pdu->CRCFLAG);
            pthread_mutex_unlock(&lock);
        }
        return NULL;
    }

    size_t start_indices[MAX_THREADS];
    for (size_t i = 0; i < MAX_THREADS; ++i) {
        start_indices[i] = i * per_thread;
        if (pthread_create(&threads[i], NULL, thread_func, &start_indices[i])) {
            fprintf(stderr, "Error creating thread\n");
            exit(1);
        }
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    return pdus;
}

int main(int argc, char *argv[]) {
    if (argc != 3 && argc != 4) {
        fprintf(stderr, "Usage: %s <count> <seed> [export_filename]\n", argv[0]);
        exit(1);
    }

    size_t count = strtoul(argv[1], NULL, 10);
    int seed = atoi(argv[2]);
    const char *export_file = argc == 4 ? argv[3] : NULL;

    initialize_log();
    NFAPI_CRC_INDICATION_PDU_T *pdus = create_pdu_list(count, seed);

    if (export_file != NULL) {
        export_to_binary(export_file, pdus, count);
    }

    close_log();
    free(pdus);

    return 0;
}
```

### Key Features:
- **Thread Safety**: Uses mutex for thread-safe logging.
- **Dynamic Memory Management**: Allocates memory dynamically and ensures it is freed.
- **Logging System**: Logs each PDU creation to a file with `RNTI` and `CRCFLAG`.
- **Binary Export**: Exports the list of structures to a binary file if specified.
- **Configuration**: Configurable number of PDUs via command-line argument.
- **Random CRCFLAG**: Uses a seed for reproducibility.']

