#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef struct {
    char *str;
    double value;
} entry;

#define INITIAL_CAPACITY 4
#define GROWTH_FACTOR 2

entry* create_entries(int num_initial, ...) {
    va_list args;
    va_start(args, num_initial);

    entry *entries = malloc(sizeof(entry) * INITIAL_CAPACITY);
    if (!entries) return NULL;

    int capacity = INITIAL_CAPACITY;
    int count = 0;

    for (int i = 0; i < num_initial; ++i) {
        char *str = va_arg(args, char*);
        entries[count].str = strdup(str);
        entries[count].value = 0.0;
        count++;
        if (count == capacity) resize_entries(entries, &capacity);
    }

    va_end(args);
    return entries;
}

void resize_entries(entry* entries, int *capacity) {
    int new_capacity = (*capacity) * GROWTH_FACTOR;

    // Check for potential integer overflow
    if (new_capacity < *capacity) {
        fprintf(stderr, "Integer overflow detected during resizing.\n");
        exit(EXIT_FAILURE);
    }

    entry *temp_entries = realloc(entries, sizeof(entry) * new_capacity);
    if (!temp_entries) {
        free(entries);
        fprintf(stderr, "Memory allocation failed during resizing.\n");
        exit(EXIT_FAILURE);
    }
    entries = temp_entries;
    *capacity = new_capacity;
}

void add_entry(entry* entries, int *count, int *capacity, const char *str) {
    if (*count == *capacity) resize_entries(entries, capacity);

    entries[*count].str = strdup(str);
    entries[*count].value = 0.0;
    (*count)++;
}

double generate_random_double(double min, double max) {
    return min + (max - min) * ((double)rand() / RAND_MAX);
}

int main() {
    srand(time(NULL));

    int count = 0;
    entry *entries = create_entries(2, "First Entry", "Second Entry");

    if (!entries) {
        fprintf(stderr, "Initial entries creation failed.\n");
        return EXIT_FAILURE;
    }

    add_entry(entries, &count, &INITIAL_CAPACITY, "Third Entry");

    for (int i = 0; i < count; ++i) {
        printf("Entry %d: %s, %.2f\n", i + 1, entries[i].str, entries[i].value);
    }

    free(entries); // Remember to deallocate each strdup-ed string before freeing the array
    for (int i = 0; i < count; ++i) {
        free(entries[i].str);
    }

    return EXIT_SUCCESS;
}
