} MAC_FRAME_DATA;

typedef struct {
    MAC_EVENT_TAG event_tag;
    long timestamp;
    MAC_FRAME_DATA *frames;
    size_t frame_count;
} NetworkEvent;

// Memory pool structure
typedef struct {
    void *start;
    size_t size;
    pthread_mutex_t lock;
    // Add more fields if needed for buddy system or chunk allocation
} MemoryPool;

// Node in the linked list of network events
typedef struct EventNode {
    NetworkEvent event;
    struct EventNode *next;
} EventNode;

// List structure to manage network events
typedef struct {
    EventNode *head;
    pthread_mutex_t mutex;
    size_t count;
    const size_t max_events;
    MemoryPool pool;
} EventList;

// Function prototypes
void initialize_event_list(EventList *list, size_t max_events, size_t pool_size);
int add_event(EventList *list, NetworkEvent event);
NetworkEvent* get_event(EventList *list, size_t index);
int remove_event(EventList *list, size_t index);
void free_event_list(EventList *list);

// Initialize the event list and memory pool
void initialize_event_list(EventList *list, size_t max_events, size_t pool_size) {
    pthread_mutex_init(&list->mutex, NULL);
    list->head = NULL;
    list->count = 0;
    list->max_events = max_events;

    // Initialize memory pool
    pthread_mutex_init(&list->pool.lock, NULL);
    list->pool.start = malloc(pool_size);
    if (!list->pool.start) {
        perror("Failed to allocate memory pool");
        exit(EXIT_FAILURE);
    }
    list->pool.size = pool_size;
}

// Add a new event to the list
int add_event(EventList *list, NetworkEvent event) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= list->max_events) {
        fprintf(stderr, "Max events reached. Cannot add more.\n");
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    EventNode *new_node = (EventNode *)malloc(sizeof(EventNode));
    if (!new_node) {
        perror("Failed to allocate event node");
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    // Allocate memory for frames within the pool
    pthread_mutex_lock(&list->pool.lock);
    void *frame_memory = list->pool.start; // Simplified: no fragmentation handling
    if (frame_memory) {
        new_node->event.frames = (MAC_FRAME_DATA *)frame_memory;
        pthread_mutex_unlock(&list->pool.lock);
    } else {
        fprintf(stderr, "Memory pool exhausted.\n");
        free(new_node);
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    new_node->event.event_tag = event.event_tag;
    new_node->event.timestamp = event.timestamp;
    new_node->event.frame_count = event.frame_count;

    // Copy frame data
    for (size_t i = 0; i < event.frame_count; ++i) {
        memcpy(new_node->event.frames[i].data, event.frames[i].data, event.frames[i].length);
        new_node->event.frames[i].length = event.frames[i].length;
    }

    // Add to list
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Retrieve an event by index
NetworkEvent* get_event(EventList *list, size_t index) {
    if (index >= list->count) {
        fprintf(stderr, "Index out of bounds.\n");
        return NULL;
    }

    pthread_mutex_lock(&list->mutex);
    EventNode *current = list->head;
    for (size_t i = 0; i < index && current != NULL; ++i) {
        current = current->next;
    }
    NetworkEvent *event = current ? &current->event : NULL;
    pthread_mutex_unlock(&list->mutex);
    return event;
}

// Remove an event by index
int remove_event(EventList *list, size_t index) {
    if (index >= list->count) {
        fprintf(stderr, "Index out of bounds.\n");
        return -1;
    }

    pthread_mutex_lock(&list->mutex);
    EventNode **current = &list->head;
    for (size_t i = 0; i < index && *current != NULL; ++i) {
        current = &(*current)->next;
    }

    if (*current == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    EventNode *to_remove = *current;
    *current = to_remove->next;
    free(to_remove);

    list->count--;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Free all resources associated with the event list
void free_event_list(EventList *list) {
    pthread_mutex_lock(&list->mutex);

    EventNode *current = list->head;
    while (current != NULL) {
        EventNode *next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->count = 0;

    // Free memory pool
    pthread_mutex_lock(&list->pool.lock);
    free(list->pool.start);
    pthread_mutex_unlock(&list->pool.lock);

    pthread_mutex_unlock(&list->mutex);
}

int main() {
    EventList event_list;
    initialize_event_list(&event_list, 100, 1024 * 1024); // Example: max 100 events, 1MB pool

    // Add, get, and remove events as needed
    NetworkEvent new_event = { .event_tag = {123}, .timestamp = 1617181920, .frame_count = 2 };
    MAC_FRAME_DATA frames[2] = {
        {.data = (unsigned char *)"Frame1", .length = strlen("Frame1")},
        {.data = (unsigned char *)"Frame2", .length = strlen("Frame2")}
    };
    new_event.frames = frames;

    add_event(&event_list, new_event);

    NetworkEvent *retrieved_event = get_event(&event_list, 0);
    if (retrieved_event) {
        printf("Retrieved event tag: %u\n", retrieved_event->event_tag.tag);
    }

    remove_event(&event_list, 0);
    free_event_list(&event_list);

    return 0;
}
