int manage_memory(int num_offsets, int num_keys, int num_records, int min_value, int max_value, unsigned int seed) {
    // Handle edge cases
    if (num_offsets < 0 || num_keys < 0 || num_records < 0) {
        fprintf(stderr, "Error: Negative size provided.\n");
        return -1;
    }

    // Seed the random number generator
    srand(seed);

    // Allocate memory for Offset array using calloc for zero-initialized memory
    Offset *offsets = (Offset *)calloc(num_offsets, sizeof(Offset));
    if (!offsets) {
        fprintf(stderr, "Error: Memory allocation failed for offsets.\n");
        return -1;
    }

    // Allocate memory for Key array using malloc
    Key *keys = (Key *)malloc(num_keys * sizeof(Key));
    if (!keys) {
        fprintf(stderr, "Error: Memory allocation failed for keys.\n");
        free(offsets);
        return -1;
    }

    // Initialize key fields sequentially
    for (int i = 0; i < num_keys; ++i) {
        keys[i].key = i;
    }

    // Allocate memory for Record array using malloc
    Record *records = (Record *)malloc(num_records * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Error: Memory allocation failed for records.\n");
        free(offsets);
        free(keys);
        return -1;
    }

    // Generate random values for each record
    for (int i = 0; i < num_records; ++i) {
        int range = max_value - min_value + 1;
        records[i].value = rand() % range + min_value;
