#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char *str;
    double value;
} entry;

#define INITIAL_CAPACITY 4
#define GROWTH_FACTOR 2

entry* create_entries(size_t initial_count, const char **strings, int min_val, int max_val) {
    srand(time(NULL));

    size_t capacity = INITIAL_CAPACITY;
    entry *array = (entry *)malloc(capacity * sizeof(entry));

    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (size_t i = 0; i < initial_count && i < capacity && strings[i]; ++i) {
        array[i].str = strdup(strings[i]);
        array[i].value = ((double)(rand() % (max_val - min_val + 1)) / RAND_MAX * (max_val - min_val) + min_val);
    }

    for (size_t i = initial_count; i < capacity; ++i) {
        array[i].str = NULL;
        array[i].value = 0.0;
    }

    return resize_entries(array, &capacity, initial_count);
}

entry* resize_entries(entry *array, size_t *capacity, size_t current_size) {
    if (current_size >= *capacity) {
        *capacity *= GROWTH_FACTOR;
        entry *new_array = realloc(array, *capacity * sizeof(entry));

        if (!new_array) {
            free(array);
            fprintf(stderr, "Memory reallocation failed\n");
            return NULL;
        }

        for (size_t i = current_size; i < *capacity; ++i) {
            new_array[i].str = NULL;
            new_array[i].value = 0.0;
        }

        array = new_array;
    }

    return array;
}

void add_entry(entry **array, size_t *capacity, const char *new_str, int min_val, int max_val) {
    if (!(*array)) {
        *array = create_entries(1, (const char*[]){new_str}, min_val, max_val);
    } else {
        (*array)[(*capacity - 1)].str = strdup(new_str);
        (*array)[(*capacity - 1)].value = ((double)(rand() % (max_val - min_val + 1)) / RAND_MAX * (max_val - min_val) + min_val);

        *array = resize_entries(*array, capacity, (*capacity)++);
    }
}

void free_entries(entry *array, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (array[i].str) {
            free(array[i].str);
        }
    }
    free(array);
}
