    collection->offsets = (long *)calloc(num_offsets, sizeof(long));
    if (!collection->offsets) {
        free(collection->keys);
        free(collection);
        perror("Failed to allocate memory for offsets");
        return NULL;
    }

    collection->count = num_keys; // Assuming keys and offsets are related by count
    return collection;
}

void set_random_values(RecordCollection *collection, int min_val, int max_val) {
    if (!collection || !collection->keys) return;

    srand(time(NULL));
    for (size_t i = 0; i < collection->count; ++i) {
        pthread_mutex_lock(&lock); // Ensure thread-safe access
        collection->keys[i] = min_val + rand() % (max_val - min_val + 1);
        pthread_mutex_unlock(&lock);
    }
}

void free_records(RecordCollection *collection) {
    if (!collection) return;

    free(collection->keys);
    free(collection->offsets);
    free(collection);
}

int main() {
    pthread_mutex_init(&lock, NULL);

    size_t num_keys = 100000;
    size_t num_offsets = 100000;

    RecordCollection *collection = initialize_records(num_keys, num_offsets);
    if (!collection) {
        fprintf(stderr, "Initialization failed.\n");
        return EXIT_FAILURE;
    }

    set_random_values(collection, 1, 100);

    // Simulate system integration and operations
    // ...

    free_records(collection);
    pthread_mutex_destroy(&lock);

    return EXIT_SUCCESS;
}
```

