public:
    template <typename ServiceType>
    void registerService() {
        auto service = std::make_shared<ServiceType>();
        services[typeid(ServiceType)] = service;
    }

    template <typename ServiceType>
    std::shared_ptr<ServiceType> getService() {
        return std::static_pointer_cast<ServiceType>(services.at(typeid(ServiceType)));
    }
};

