    time_t timestamp;
    size_t frame_count;
    MAC_FRAME_DATA* frames;
    struct NetworkEvent* next;
} NetworkEvent;

// Global variables for action cooldown and logging
static const int COOLDOWN_PERIOD = 9; // seconds
static unsigned long last_action_time = 0;
static pthread_mutex_t action_lock = PTHREAD_MUTEX_INITIALIZER;
static FILE* log_file = NULL;

// Function prototypes
void initialize_log(const char* filename, bool verbose);
void log_message(const char* message, int verbosity_level);
NetworkEvent* create_event();
int add_frame(NetworkEvent* event, MAC_FRAME_DATA frame_data);
void free_event(NetworkEvent* event);
bool select_action(unsigned int seed);
void synchronize_time(time_t *current_time);

// Initialize logging
void initialize_log(const char* filename, bool verbose) {
    log_file = fopen(filename, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", filename);
        exit(EXIT_FAILURE);
    }
}

// Log messages with verbosity control
void log_message(const char* message, int verbosity_level) {
    static const int LOG_VERBOSITY = 1; // Change as needed
    if (verbosity_level <= LOG_VERBOSITY && log_file) {
        fprintf(log_file, "%s\n", message);
        fflush(log_file);
    }
}

// Create a new network event
NetworkEvent* create_event() {
    NetworkEvent* event = (NetworkEvent*)malloc(sizeof(NetworkEvent));
    if (!event) {
        log_message("Memory allocation failed for NetworkEvent.", 1);
        return NULL;
    }

    event->next = NULL;
    event->frames = NULL;
    event->frame_count = 0;

    synchronize_time(&event->timestamp);

    return event;
}

// Add a frame to an existing network event
int add_frame(NetworkEvent* event, MAC_FRAME_DATA frame_data) {
    if (!event || !frame_data.data) {
        log_message("Invalid input for adding frame.", 1);
        return -1;
    }

    MAC_FRAME_DATA* new_frames = (MAC_FRAME_DATA*)realloc(
        event->frames,
        sizeof(MAC_FRAME_DATA) * (event->frame_count + 1)
    );

    if (!new_frames) {
        log_message("Memory reallocation failed for frames.", 1);
        return -1;
    }

    memcpy(&new_frames[event->frame_count], &frame_data, sizeof(frame_data));
    event->frames = new_frames;
    event->frame_count++;

    return 0; // Success
}

// Free a network event and its associated resources
void free_event(NetworkEvent* event) {
    if (!event) return;

    free(event->frames);
    free(event);
}

// Select an action based on a seeded random function
bool select_action(unsigned int seed) {
    pthread_mutex_lock(&action_lock);

    time_t current_time;
    synchronize_time(&current_time);

    unsigned long elapsed = (unsigned long)difftime(current_time, last_action_time);

    if (elapsed < COOLDOWN_PERIOD) {
        pthread_mutex_unlock(&action_lock);
        return false; // Cooldown not yet expired
    }

    srand(seed + (unsigned int)time(NULL));
    bool action_selected = rand() % 2 == 0;

    last_action_time = current_time;
    pthread_mutex_unlock(&action_lock);

    log_message(action_selected ? "Action 1 selected." : "Action 2 selected.", 1);
    return action_selected;
}

// Synchronize local time with an external source
void synchronize_time(time_t *current_time) {
    // Mock implementation of time synchronization.
