import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

class Record {
    int key;
    long offset;
    double precisionData;
}

public class ResourceManager {

    private static final Random random = new Random();
    private ExecutorService executor = Executors.newCachedThreadPool();

    public void manageResources(int arraySize, List<String> commands) {
        try {
            long[] offsets = allocateArray(arraySize);
            int[] keys = allocateIntArray(arraySize);
            double[] precisionData = allocateDoubleArray(arraySize);

            Record[] records = new Record[arraySize];
            for (int i = 0; i < arraySize; i++) {
                records[i] = new Record();
                records[i].key = random.nextInt(100);
                records[i].offset = random.nextLong() & ((1L << 30) - 1); // Limit to 30 bits
                records[i].precisionData = Math.random() * 100.0;
            }

            // Simulate external data source updates
            refreshCacheFromExternalSource();

            for (String command : commands) {
                executor.submit(() -> executeCommand(command));
            }

        } catch (OutOfMemoryError e) {
            logError("Out of memory while allocating resources");
        } finally {
            cleanup();
        }
    }

    private long[] allocateArray(int size) {
        try {
            return new long[size];
        } catch (OutOfMemoryError e) {
            throw new RuntimeException("Failed to allocate array", e);
        }
    }

    private int[] allocateIntArray(int size) {
        try {
            return new int[size];
        } catch (OutOfMemoryError e) {
            throw new RuntimeException("Failed to allocate integer array", e);
        }
    }

    private double[] allocateDoubleArray(int size) {
        try {
            return new double[size];
        } catch (OutOfMemoryError e) {
            throw new RuntimeException("Failed to allocate double array", e);
        }
    }

    private void executeCommand(String command) {
        try {
            File tempFile = new File(command + ".tmp");
            if (tempFile.exists()) {
                Files.delete(tempFile.toPath());
            }

            long startTime = System.currentTimeMillis();
            Process process = Runtime.getRuntime().exec(new String[]{"bash", "-c", command}, null, new File("."));
            int exitCode = process.waitFor();
            long endTime = System.currentTimeMillis();

            logInfo("Command executed in " + (endTime - startTime) + " ms with exit code: " + exitCode);
        } catch (IOException | InterruptedException e) {
            logError("Error executing command: " + command, e);
        }
    }

    private void refreshCacheFromExternalSource() {
        // Simulate refreshing cache
        try {
            Thread.sleep(1000); // Simulating network delay
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private void cleanup() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }

    private synchronized void logInfo(String message) {
        // Simulate logging
        System.out.println("INFO: " + message);
    }

    private synchronized void logError(String message, Throwable throwable) {
        // Simulate error logging
        System.err.println("ERROR: " + message);
        throwable.printStackTrace();
    }
}
```

