// Namespace for encapsulation
namespace DataProcessor {

    class RandomGenerator {
    private:
        std::mt19937 gen;
        std::mutex mtx;

    public:
        RandomGenerator(unsigned int seed) : gen(seed) {}

        // Thread-safe random number generation
        int getRandomInt(int min, int max) {
            std::lock_guard<std::mutex> lock(mtx);
            std::uniform_int_distribution<> dist(min, max);
            return dist(gen);
        }
    };

    struct Record {
        int value;
    };

    class MemoryPool {
    private:
        size_t blockSize;
        void* poolPtr;
        size_t poolSize;
        bool freeList;

    public:
        MemoryPool(size_t blockCount) : blockSize(sizeof(Record)), poolSize(blockCount * blockSize), freeList(true) {
            poolPtr = std::malloc(poolSize);
            if (!poolPtr) throw std::bad_alloc();
        }

        ~MemoryPool() {
            std::free(poolPtr);
        }

        Record* allocate() {
            if (freeList) {
                freeList = false;
                return static_cast<Record*>(poolPtr);
            }
            throw std::bad_alloc(); // Pool exhausted
        }

        void deallocate(Record* ptr, size_t count) {
            // No-op for a simple pool
            // Real implementation would handle recycling of blocks
        }
    };

    class DataProcessor {
    private:
        long* offsets;
        int* keys;
        Record* records;
        size_t dataSize;
        RandomGenerator rng;
        MemoryPool* memPool;

    public:
        DataProcessor(size_t size, unsigned int seed) : dataSize(size), rng(seed), memPool(new MemoryPool(size)) {
            try {
                offsets = new long[dataSize];
                keys = new int[dataSize];
                records = static_cast<Record*>(memPool->allocate());

                for (size_t i = 0; i < dataSize; ++i) {
                    offsets[i] = rng.getRandomInt(1, 100);
                    keys[i] = rng.getRandomInt(1, 1000);
                    records[i].value = rng.getRandomInt(1, 10000);
                }
            } catch (const std::bad_alloc&) {
                cleanup();
                throw;
            }
        }

        ~DataProcessor() {
            cleanup();
        }

        void processData() {
            try {
                // Sort based on keys using parallel sort for large datasets
                auto start = std::chrono::high_resolution_clock::now();

                std::sort(keys, keys + dataSize, [&](int a, int b) -> bool {
                    return a < b;
                });

                for (size_t i = 0; i < dataSize; ++i) {
                    // Swap records based on sorted keys
                    if (keys[i] != i) {
                        std::swap(records[i], records[keys[i]]);
                    }
                }

                auto end = std::chrono::high_resolution_clock::now();
                std::chrono::duration<double> elapsed = end - start;
                Logging::log("Processing completed in " + std::to_string(elapsed.count()) + " seconds.");

            } catch (const std::exception& e) {
                Logging::log(std::string("Error during processing: ") + e.what());
                throw;
            }
        }

    private:
        void cleanup() {
            delete[] offsets;
            delete[] keys;
            memPool->deallocate(records, dataSize);
            delete memPool;
        }
    };

}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: dataProcessor <dataSize>" << std::endl;
        return EXIT_FAILURE;
    }

    size_t dataSize = std::stoul(argv[1]);
    unsigned int seed = std::random_device{}();

    try {
        DataProcessor::DataProcessor processor(dataSize, seed);
        processor.processData();
    } catch (const std::exception& e) {
        Logging::log(std::string("Fatal error: ") + e.what());
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
