#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_HASH_TABLE_SIZE 1024

typedef struct Record {
    int value;
    int *key;
} Record;

typedef struct HashNode {
    int key;
    Record *record;
    struct HashNode *next;
} HashNode;

typedef struct {
    HashNode **table;
    size_t capacity;
    pthread_mutex_t lock;
    size_t num_records;
    size_t total_memory_used;
} RecordsPool;

unsigned long hash(int key, size_t capacity) {
    return (key & 0x7FFFFFFF) % capacity;
}

RecordsPool* create_records_pool() {
    RecordsPool *pool = malloc(sizeof(RecordsPool));
    pool->capacity = INITIAL_HASH_TABLE_SIZE;
    pool->table = calloc(pool->capacity, sizeof(HashNode *));
    pthread_mutex_init(&pool->lock, NULL);
    pool->num_records = 0;
    pool->total_memory_used = 0;
    return pool;
}

void resize_hash_table(RecordsPool *pool);

Record* add_record(RecordsPool *pool, int key, int value) {
    pthread_mutex_lock(&pool->lock);

    unsigned long index = hash(key, pool->capacity);
    HashNode *node = pool->table[index];

    while (node) {
        if (node->key == key) {
            node->record->value = value;
            pthread_mutex_unlock(&pool->lock);
            return node->record;
        }
        node = node->next;
    }

    // Add new record
    HashNode *new_node = malloc(sizeof(HashNode));
    new_node->key = key;
    new_node->record = malloc(sizeof(Record));
    new_node->record->value = value;
    new_node->record->key = &key;  // Assuming external management of keys

    pool->num_records++;
    pool->total_memory_used += sizeof(*new_node) + sizeof(*(new_node->record));

    if (pool->num_records > pool->capacity * 0.7) {
        resize_hash_table(pool);
    }

    new_node->next = pool->table[index];
    pool->table[index] = new_node;

    pthread_mutex_unlock(&pool->lock);
    return new_node->record;
}

void update_record(RecordsPool *pool, int key, int value) {
    Record *record = find_record(pool, key);
    if (record) {
        record->value = value;
    }
}

Record* find_record(RecordsPool *pool, int key) {
    pthread_mutex_lock(&pool->lock);

    unsigned long index = hash(key, pool->capacity);
    HashNode *node = pool->table[index];

    while (node) {
        if (node->key == key) {
            pthread_mutex_unlock(&pool->lock);
            return node->record;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&pool->lock);
    return NULL;
}

void remove_record(RecordsPool *pool, int key) {
    pthread_mutex_lock(&pool->lock);

    unsigned long index = hash(key, pool->capacity);
    HashNode *node = pool->table[index];
    HashNode *prev = NULL;

    while (node) {
        if (node->key == key) {
            if (prev) {
                prev->next = node->next;
            } else {
                pool->table[index] = node->next;
            }

            free(node->record);
            free(node);

            pool->num_records--;
            pool->total_memory_used -= sizeof(*node) + sizeof(*(node->record));

            pthread_mutex_unlock(&pool->lock);
            return;
        }
        prev = node;
        node = node->next;
    }

    pthread_mutex_unlock(&pool->lock);
}

void resize_hash_table(RecordsPool *pool) {
    size_t new_capacity = pool->capacity * 2;
    HashNode **new_table = calloc(new_capacity, sizeof(HashNode *));

    for (size_t i = 0; i < pool->capacity; ++i) {
        HashNode *node = pool->table[i];

        while (node) {
            unsigned long new_index = hash(node->key, new_capacity);
            HashNode *next_node = node->next;

            node->next = new_table[new_index];
            new_table[new_index] = node;

            node = next_node;
        }
    }

    free(pool->table);
    pool->table = new_table;
    pool->capacity = new_capacity;
}

void print_statistics(RecordsPool *pool) {
    pthread_mutex_lock(&pool->lock);

    printf("Active records: %zu\n", pool->num_records);
    printf("Total memory used: %zu bytes\n", pool->total_memory_used);

    pthread_mutex_unlock(&pool->lock);
}

void free_records_pool(RecordsPool *pool) {
    for (size_t i = 0; i < pool->capacity; ++i) {
        HashNode *node = pool->table[i];

        while (node) {
            HashNode *next_node = node->next;
            free(node->record);
            free(node);
            node = next_node;
        }
    }

    free(pool->table);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}
```

### Usage
- Use `create_records_pool()` to initialize the records pool.
- Manage records using `add_record()`, `update_record()`, and `remove_record()`.
- Retrieve statistics with `print_statistics()`.
- Clean up with `free_records_pool()`.']

