        free(*resolved_ips);
        return -3; // Memory allocation failure
    }

    srand((unsigned int)time(NULL));  // Seed random number generator

    for (size_t i = 0; i < num_hostnames; ++i) {
        u_char *ip_address_buffer = &((*resolved_ips)[i * 16]);
        record *rec = &(*records)[i];

        rec->value = RANDOM_RANGE_MIN + rand() % (RANDOM_RANGE_MAX - RANDOM_RANGE_MIN + 1);

        for (int attempt = 0; attempt < DNS_RETRY_LIMIT; ++attempt) {
            int result = resolve_hostname(hostnames[i], ip_address_buffer, 16);
            if (result == 0) { // Success
                printf("Resolved %s\n", hostnames[i]);
                break;
            }
            exponential_backoff(attempt);
        }

        if (result != 0) {
            fprintf(stderr, "Failed to resolve hostname: %s after %d attempts\n", hostnames[i], DNS_RETRY_LIMIT);
        }
    }

    return 0; // Success
}

void find_and_print_largest_record(record *records, size_t num_records) {
    if (!records || num_records == 0) {
        printf("No records to process.\n");
        return;
    }

    int largest_value = records[0].value;
    for (size_t i = 1; i < num_records; ++i) {
        if (records[i].value > largest_value) {
            largest_value = records[i].value;
        }
    }

    printf("Largest value in records: %d\n", largest_value);
}

void free_resources(u_char *resolved_ips, record *records) {
    if (resolved_ips != NULL) {
        free(resolved_ips);
    }
    if (records != NULL) {
        free(records);
    }
}
