typedef struct {
    time_t timestamp;
} RequestTimestamp;

typedef struct {
    int sessionId;
    time_t startTime;
    time_t endTime;
    RequestTimestamp *requestTimestamps;
    size_t requestCount;
    double totalRequestDuration;
    double averageRequestRate;
    double maxResponseTime;
} UserSessionStats;

void initializeUserSession(UserSessionStats *session, int sessionId, time_t startTime) {
    session->sessionId = sessionId;
    session->startTime = startTime;
    session->endTime = 0; // Will be updated when the session ends
    session->requestTimestamps = NULL;
    session->requestCount = 0;
    session->totalRequestDuration = 0.0;
    session->averageRequestRate = 0.0;
    session->maxResponseTime = 0.0;
}

void updateSessionStatistics(UserSessionStats *session, time_t newRequestTimestamp) {
    RequestTimestamp *newRequests = realloc(session->requestTimestamps, (session->requestCount + 1) * sizeof(RequestTimestamp));
    if (!newRequests) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    session->requestTimestamps = newRequests;

    session->requestTimestamps[session->requestCount].timestamp = newRequestTimestamp;
    session->requestCount++;

    // Update total request duration
    time_t currentDuration = difftime(newRequestTimestamp, session->startTime);
    if (currentDuration > 0) {
        session->totalRequestDuration += currentDuration;
    }

    // Calculate average request rate over time
    if (session->requestCount > 1) {
        double totalTimeInSeconds = difftime(newRequestTimestamp, session->startTime);
        session->averageRequestRate = (double)(session->requestCount - 1) / totalTimeInSeconds;
    }

    // Update max response time between requests
    if (session->requestCount > 1) {
        size_t i;
        double responseTime = difftime(newRequestTimestamp, session->requestTimestamps[session->requestCount - 2].timestamp);
        if (responseTime > session->maxResponseTime) {
            session->maxResponseTime = responseTime;
        }
    }

    // Update end time
    if (difftime(newRequestTimestamp, session->endTime) > 0) {
        session->endTime = newRequestTimestamp;
    }
}

void finalizeSessionStatistics(UserSessionStats *session) {
    if (session->requestCount == 0) return;

    // Finalize average request rate
    double totalTimeInSeconds = difftime(session->endTime, session->startTime);
    if (totalTimeInSeconds > 0) {
        session->averageRequestRate /= totalTimeInSeconds;
    }
}

void freeUserSessionStats(UserSessionStats *session) {
    free(session->requestTimestamps);
    memset(session, 0, sizeof(UserSessionStats));
}
