typedef struct {
    time_t seconds;
    long   nanoseconds;
} timestamp;

typedef struct resource_usage {
    double metric_value;
    char status_indicator;
    timestamp log_timestamp;
    struct resource_usage *next;
} resource_usage;

typedef struct {
    resource_usage *head;
    pthread_rwlock_t lock;
} ResourceCollection;

ResourceCollection* create_resource_collection() {
    ResourceCollection *collection = malloc(sizeof(ResourceCollection));
    if (!collection) return NULL;

    collection->head = NULL;
    if (pthread_rwlock_init(&collection->lock, NULL) != 0) {
        free(collection);
        return NULL;
    }

    return collection;
}

int add_resource_usage(ResourceCollection *collection, double metric_value, char status_indicator, timestamp log_timestamp) {
    resource_usage *new_record = malloc(sizeof(resource_usage));
    if (!new_record) return -1;

    new_record->metric_value = metric_value;
    new_record->status_indicator = status_indicator;
    new_record->log_timestamp = log_timestamp;
    new_record->next = NULL;

    pthread_rwlock_wrlock(&collection->lock);

    new_record->next = collection->head;
    collection->head = new_record;

    pthread_rwlock_unlock(&collection->lock);
    return 0;
}

int remove_resource_usage(ResourceCollection *collection, timestamp query_timestamp) {
