} Item;

#define ACTIVE 1

// Function to check if an ID already exists in the list
int id_exists(int id, Item *items, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (items[i].id == id) return 1;
    }
    return 0;
}

// Function to generate a unique name for each item
void generate_unique_name(char **name, int id) {
    *name = malloc(50); // Assuming names are not longer than 49 characters + null terminator
    if (*name) {
        snprintf(*name, 50, "Item_%d", id);
    }
}

// Function to initialize the list of items
Item* initialize_item_list(size_t num_items, int (*external_id_generator)(void)) {
    if (num_items == 0 || external_id_generator == NULL) return NULL;

    Item *items = malloc(num_items * sizeof(Item));
    if (!items) return NULL;

    for (size_t i = 0; i < num_items; ++i) {
        int id;
        do {
            id = external_id_generator();
        } while (id_exists(id, items, i));

        generate_unique_name(&items[i].name, id);
        items[i].id = id;
        items[i].status = ACTIVE;
    }

    return items;
}

// Function to deallocate the list of items
void free_item_list(Item *items, size_t num_items) {
    if (!items) return;

    for (size_t i = 0; i < num_items; ++i) {
        free(items[i].name);
    }
    free(items);
}

