['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_FRAMES 10000
#define LOG_FILE_NAME "network_events.log"

typedef struct {
    uint32_t tag;
} MAC_EVENT_TAG;

typedef struct {
    size_t length;
    char *data;
} MAC_FRAME_DATA;

typedef struct NetworkEvent {
    MAC_EVENT_TAG event_tag;
    time_t timestamp;
    MAC_FRAME_DATA frames[1]; // Flexible array member for variable-length frames
} NetworkEvent, *NetworkEventPtr;

typedef struct Node {
    NetworkEvent network_event;
    size_t frame_count;
    struct Node* next;
} Node, *NodePtr;

typedef struct {
    NodePtr head;
    pthread_mutex_t lock;
    int log_file_rotation_count;
    time_t last_log_rotation_time;
} EventList, *EventListPtr;

void rotate_logs(EventListPtr event_list) {
    char new_filename[256];
    snprintf(new_filename, sizeof(new_filename), "network_events_%d.log", event_list->log_file_rotation_count++);
    fclose(fopen(LOG_FILE_NAME, "r")); // Close the current log file
    rename(LOG_FILE_NAME, new_filename); // Rename it
    FILE* log_file = fopen(LOG_FILE_NAME, "w");
    if (!log_file) {
        perror("Failed to open log file for rotation");
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "Log rotated at %s\n", ctime(&event_list->last_log_rotation_time));
    fclose(log_file);
}

void log_event(EventListPtr event_list, const char* message) {
    pthread_mutex_lock(&event_list->lock);
    FILE *log_file = fopen(LOG_FILE_NAME, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    time_t current_time = time(NULL);
    if (difftime(current_time, event_list->last_log_rotation_time) >= 86400) { // 24 hours
        rotate_logs(event_list);
        event_list->last_log_rotation_time = current_time;
    }

    fprintf(log_file, "%s\n", message);
    fclose(log_file);
    pthread_mutex_unlock(&event_list->lock);
}

void init_event_list(EventListPtr event_list, int garbage_collection_interval) {
    event_list->head = NULL;
    pthread_mutex_init(&event_list->lock, NULL);
    event_list->log_file_rotation_count = 0;
    time_t current_time = time(NULL);
    event_list->last_log_rotation_time = current_time;

    // Start a background thread for garbage collection
    pthread_t gc_thread;
    pthread_create(&gc_thread, NULL, (void *(*)(void *))[] (void* arg) {
        EventListPtr elist = (EventListPtr)arg;
        while (1) {
            sleep(garbage_collection_interval);
            time_t current_time = time(NULL);
            NodePtr prev = NULL;
            for (NodePtr node = elist->head; node != NULL; ) {
                if (difftime(current_time, node->network_event.timestamp) > garbage_collection_interval * 60) { // Convert minutes to seconds
                    NodePtr to_delete = node;
                    node = node->next;
                    if (prev == NULL) {
                        elist->head = node;
                    } else {
                        prev->next = node;
                    }
                    for (size_t i = 0; i < to_delete->frame_count; ++i) {
                        free(to_delete->network_event.frames[i].data);
                    }
                    free(to_delete);
                    log_event(elist, "Garbage collected a stale event.");
                } else {
                    prev = node;
                    node = node->next;
                }
            }
        }
    }, event_list);

    pthread_detach(gc_thread);
}

int append_frame(EventListPtr event_list, MAC_EVENT_TAG event_tag, time_t timestamp, MAC_FRAME_DATA* frame_data, size_t frame_count) {
    if (frame_count == 0) return -1;

    NodePtr new_node = (NodePtr)calloc(1, sizeof(Node) + sizeof(MAC_FRAME_DATA) * frame_count);
    if (!new_node) {
        log_event(event_list, "Memory allocation failed for a new node.");
        return -2;
    }

    new_node->network_event.event_tag = event_tag;
    new_node->network_event.timestamp = timestamp;

    for (size_t i = 0; i < frame_count; ++i) {
        if (frame_data[i].length == 0 || frame_data[i].data == NULL) {
            log_event(event_list, "Invalid MAC_FRAME_DATA encountered.");
            free(new_node);
            return -3;
        }
        new_node->network_event.frames[i] = frame_data[i];
    }

    new_node->frame_count = frame_count;

    pthread_mutex_lock(&event_list->lock);
    if (event_list->head == NULL) {
        event_list->head = new_node;
    } else {
        NodePtr current = event_list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&event_list->lock);

    log_event(event_list, "Appended a new frame successfully.");
    return 0;
}

void free_event_list(EventListPtr event_list) {
    pthread_mutex_lock(&event_list->lock);
    NodePtr current = event_list->head;
    while (current != NULL) {
        NodePtr to_delete = current;
        current = current->next;

        for (size_t i = 0; i < to_delete->frame_count; ++i) {
            free(to_delete->network_event.frames[i].data);
        }
        free(to_delete);
    }
    event_list->head = NULL;
    pthread_mutex_unlock(&event_list->lock);
    pthread_mutex_destroy(&event_list->lock);
}

// Example main function for demonstration
int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <garbage_collection_interval_minutes>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int garbage_collection_interval = atoi(argv[1]);

    EventList event_list;
    init_event_list(&event_list, garbage_collection_interval);

    // Simulate adding some frames
    MAC_FRAME_DATA frames[] = {
        { .length = 4, .data = strdup("ABCD") },
        { .length = 3, .data = strdup("EFG") }
    };

    append_frame(&event_list, (MAC_EVENT_TAG){.tag=1}, time(NULL), frames, 2);

    // Free resources
    free_event_list(&event_list);

    return EXIT_SUCCESS;
}
```

### Key Features:
- **Dynamic Memory Management**: The code allocates memory dynamically for each network event and its frame data.
- **Garbage Collection**: A background thread handles garbage collection, freeing events that are older than a specified interval.
- **Log Rotation**: Logs are rotated every 24 hours to manage file sizes efficiently.
- **Error Handling**: The function checks for invalid inputs and manages memory allocation failures gracefully.
- **Thread Safety**: Mutexes ensure safe concurrent access to the event list.

This code provides a robust framework for managing network events with efficient memory usage, logging, and garbage collection. Adjustments may be needed based on specific system requirements or constraints.']

