    struct Record* next;
} Record;

typedef struct {
    Record** records; // Array of pointers to records
    long* offsets;
    int* keys;
    size_t record_count;
    size_t offset_count;
    size_t key_count;
} Collection;

void initialize_collection(Collection* collection, size_t initial_size) {
    if (!collection) return;

    collection->records = (Record**)malloc(initial_size * sizeof(Record*));
    collection->offsets = (long*)calloc(initial_size, sizeof(long));
    collection->keys = (int*)malloc(initial_size * sizeof(int));

    collection->record_count = 0;
    collection->offset_count = 0;
    collection->key_count = 0;

    if (!collection->records || !collection->offsets || !collection->keys) {
        // Handle memory allocation failure
        free(collection->records);
        free(collection->offsets);
        free(collection->keys);
        fprintf(stderr, "Failed to initialize collection\n");
        exit(EXIT_FAILURE);
    }
}

void resize_collection(Collection* collection, size_t new_size) {
    if (!collection || new_size <= collection->record_count) return;

    Record** new_records = (Record**)realloc(collection->records, new_size * sizeof(Record*));
    long* new_offsets = (long*)realloc(collection->offsets, new_size * sizeof(long));
    int* new_keys = (int*)realloc(collection->keys, new_size * sizeof(int));

    if (!new_records || !new_offsets || !new_keys) {
        // Handle memory allocation failure
        free(new_records);
        free(new_offsets);
        free(new_keys);
        fprintf(stderr, "Failed to resize collection\n");
        exit(EXIT_FAILURE);
    }

    collection->records = new_records;
    collection->offsets = new_offsets;
    collection->keys = new_keys;

    for (size_t i = collection->record_count; i < new_size; ++i) {
        collection->records[i] = NULL;
        collection->offsets[i] = 0;
    }

    collection->key_count = new_size;
}

void add_record(Collection* collection, int value, long offset, int key) {
    if (!collection || collection->record_count >= collection->key_count) {
        resize_collection(collection, collection->key_count * 2);
    }

    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Failed to allocate memory for new record\n");
        exit(EXIT_FAILURE);
    }

    new_record->value = value;
    new_record->next = NULL;

    collection->records[collection->record_count] = new_record;
    collection->offsets[collection->record_count] = offset;
    collection->keys[collection->record_count] = key;
    collection->record_count++;

    adjust_random_range_based_on_keys(collection);
}

void adjust_random_range_based_on_keys(Collection* collection) {
    if (!collection || collection->key_count == 0) return;

    int sum = 0;
    for (size_t i = 0; i < collection->key_count && i < collection->record_count; ++i) {
        sum += collection->keys[i];
    }

    double average_key_value = (double)sum / collection->key_count;

    // Dynamically adjust the range for new records based on the keys' average value
    int random_range_min = (int)(average_key_value - 10);
    int random_range_max = (int)(average_key_value + 10);

    printf("Random range adjusted to [%d, %d]\n", random_range_min, random_range_max);
}

void free_collection(Collection* collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->record_count; ++i) {
        free(collection->records[i]);
    }

    free(collection->records);
    free(collection->offsets);
    free(collection->keys);

    collection->records = NULL;
    collection->offsets = NULL;
    collection->keys = NULL;
}

int main() {
    Collection my_collection;
    initialize_collection(&my_collection, 10);

    // Example usage
    add_record(&my_collection, 42, 100, 5);
    add_record(&my_collection, 56, 200, 7);

    free_collection(&my_collection);

    return 0;
}
