#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <unistd.h>
#include <time.h>

#define MAX_TASKS 100
#define DEFAULT_MAX_CONCURRENT 4

typedef struct record {
    int key;
    struct record* next;
} record;

typedef struct task {
    char input_file[256];
    char output_file[256];
    void (*callback)(const char*);
    time_t creation_time;
} task;

typedef struct {
    task tasks[MAX_TASKS];
    int head, tail, size;
    pthread_mutex_t lock;
} task_queue;

typedef struct config {
    int max_concurrent;
    int logging_level;
    char default_output_dir[256];
} config;

config global_config = {DEFAULT_MAX_CONCURRENT, 1, "."};

pthread_mutex_t alloc_lock;

void* allocate_safe(size_t size) {
    pthread_mutex_lock(&alloc_lock);
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_unlock(&alloc_lock);
    return ptr;
}

void release_safe(void* ptr) {
    pthread_mutex_lock(&alloc_lock);
    free(ptr);
    pthread_mutex_unlock(&alloc_lock);
}

record* create_record(int key) {
    record* new_node = (record*)allocate_safe(sizeof(record));
    new_node->key = key;
    new_node->next = NULL;
    return new_node;
}

void insert_sorted(record** head, int key) {
    record* new_node = create_record(key);
    if (!(*head) || (*head)->key >= key) {
        new_node->next = *head;
        *head = new_node;
    } else {
        record* current = *head;
        while (current->next && current->next->key < key) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
}

void delete_record(record** head, int key) {
    if (!(*head)) return;
    record* temp = *head;
    if (temp->key == key) {
        *head = temp->next;
        release_safe(temp);
        return;
    }
    while (temp->next && temp->next->key != key) {
        temp = temp->next;
    }
    if (!temp->next) return;
    record* to_delete = temp->next;
    temp->next = to_delete->next;
    release_safe(to_delete);
}

void initialize_task_queue(task_queue* tq) {
    tq->head = tq->tail = tq->size = 0;
    pthread_mutex_init(&tq->lock, NULL);
}

int enqueue_task(task_queue* tq, const char* input_file, const char* output_file, void (*callback)(const char*)) {
    pthread_mutex_lock(&tq->lock);
    if (tq->size >= MAX_TASKS) {
        pthread_mutex_unlock(&tq->lock);
        return -1;
    }
    task* new_task = &tq->tasks[tq->tail];
    strcpy(new_task->input_file, input_file);
    strcpy(new_task->output_file, output_file);
    new_task->callback = callback;
    new_task->creation_time = time(NULL);
    tq->tail = (tq->tail + 1) % MAX_TASKS;
    tq->size++;
    pthread_mutex_unlock(&tq->lock);
    return 0;
}

task* dequeue_task(task_queue* tq) {
    pthread_mutex_lock(&tq->lock);
    if (tq->size == 0) {
        pthread_mutex_unlock(&tq->lock);
        return NULL;
    }
    task* result = &tq->tasks[tq->head];
    tq->head = (tq->head + 1) % MAX_TASKS;
    tq->size--;
    pthread_mutex_unlock(&tq->lock);
    return result;
}

void parse_config(const char* config_file_path) {
    FILE* file = fopen(config_file_path, "r");
    if (!file) {
        fprintf(stderr, "Failed to open configuration file\n");
        exit(EXIT_FAILURE);
    }
    fscanf(file, "%d %d %s", &global_config.max_concurrent, &global_config.logging_level, global_config.default_output_dir);
    fclose(file);
}

void cleanup(record** head, task_queue* tq) {
    while (*head) {
        delete_record(head, (*head)->key);
    }
    pthread_mutex_destroy(&tq->lock);
}

void imageConversionManager(const char* config_file_path) {
    parse_config(config_file_path);

    task_queue tq;
    initialize_task_queue(&tq);

    record* sorted_records = NULL;

    pthread_mutex_init(&alloc_lock, NULL);

    // Simulate adding random records
    for (int i = 0; i < 10; ++i) {
        int key = rand() % 100;
        insert_sorted(&sorted_records, key);
    }

    // Example of enqueueing a task
    enqueue_task(&tq, "input.jpg", "output.pdf", NULL);

    // Simulate processing tasks
    while ((task* tsk = dequeue_task(&tq))) {
        printf("Processing: %s to %s\n", tsk->input_file, tsk->output_file);
        if (tsk->callback) tsk->callback(tsk->output_file);
    }

    // Cleanup
    cleanup(&sorted_records, &tq);

    pthread_mutex_destroy(&alloc_lock);
}

int main() {
    srand(time(NULL));
    imageConversionManager("config.txt");
    return 0;
}
