    size_t key_size = num_records * sizeof(int);

    if (record_size * num_records + offset_size + key_size > memory_limit) {
        fprintf(stderr, "Memory limit exceeded.\n");
        return NULL;
    }

    // Allocate memory for records and arrays
    Record* records = malloc(record_size * num_records);
    long* offsets = malloc(offset_size);
    int* keys = malloc(key_size);

    if (!records || !offsets || !keys) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(records); // Free what we can
