```c
#include <stdio.h>
#include <stdlib.h>
import "pthread.h"
#include <string.h>

#define MAX_EVENTS 1024
#define MAX_FRAME_SIZE 256

typedef struct {
    unsigned int tag;
    long timestamp;
} MAC_EVENT_TAG;

typedef struct {
    unsigned char data[MAX_FRAME_SIZE];
    size_t length;
} MAC_FRAME_DATA;

typedef struct {
    MAC_EVENT_TAG event_tag;
    long timestamp;
    MAC_FRAME_DATA frames[10]; // Adjust based on expected usage
    size_t frame_count;
} NetworkEvent;

typedef struct {
    NetworkEvent* events[MAX_EVENTS];
    pthread_mutex_t lock;
    size_t current_size;
    size_t max_events;
    size_t memory_pool_size;
    unsigned char* memory_pool;
    size_t used_memory;
    size_t peak_memory_usage;
} EventManager;

EventManager em = {0};

void initialize_event_manager(size_t max_events, size_t memory_pool_size) {
    pthread_mutex_init(&em.lock, NULL);
    em.max_events = max_events;
    em.memory_pool_size = memory_pool_size;
    em.memory_pool = (unsigned char*)aligned_alloc(64, memory_pool_size); // Aligned allocation
    if (!em.memory_pool) {
        fprintf(stderr, "Memory pool allocation failed\n");
        exit(EXIT_FAILURE);
    }
    em.current_size = 0;
    em.used_memory = 0;
    em.peak_memory_usage = 0;
}

void* allocate_from_pool(size_t size) {
    pthread_mutex_lock(&em.lock);
    if (em.used_memory + size > em.memory_pool_size) {
        fprintf(stderr, "Buffer overflow detected\n");
        pthread_mutex_unlock(&em.lock);
        return NULL;
    }
    void* ptr = &em.memory_pool[em.used_memory];
    em.used_memory += size;
    if (em.used_memory > em.peak_memory_usage) {
        em.peak_memory_usage = em.used_memory;
    }
    pthread_mutex_unlock(&em.lock);
    return ptr;
}

void add_event(MAC_EVENT_TAG event_tag, long timestamp, MAC_FRAME_DATA* frames, size_t frame_count) {
    if (frame_count > 10 || em.current_size >= em.max_events) {
        fprintf(stderr, "Event addition failed: invalid input or max events reached\n");
        return;
    }

    NetworkEvent* new_event = allocate_from_pool(sizeof(NetworkEvent));
    if (!new_event) {
        fprintf(stderr, "Failed to add event due to memory constraints\n");
        return;
    }

    new_event->event_tag = event_tag;
    new_event->timestamp = timestamp;
    new_event->frame_count = frame_count;

    for (size_t i = 0; i < frame_count; ++i) {
        size_t frame_size = frames[i].length <= MAX_FRAME_SIZE ? frames[i].length : MAX_FRAME_SIZE;
        if (frame_size > MAX_FRAME_SIZE) {
            fprintf(stderr, "Frame data overflow detected\n");
            continue;
        }
        memcpy(new_event->frames[i].data, frames[i].data, frame_size);
        new_event->frames[i].length = frame_size;
    }

    pthread_mutex_lock(&em.lock);
    em.events[em.current_size++] = new_event;
    pthread_mutex_unlock(&em.lock);

    printf("Event added successfully. Current memory usage: %zu bytes\n", em.used_memory);
}

void cleanup_event_manager() {
    for (size_t i = 0; i < em.current_size; ++i) {
        free(em.events[i]);
    }
    free(em.memory_pool);
    pthread_mutex_destroy(&em.lock);
}

int main() {
    initialize_event_manager(MAX_EVENTS, 1024 * 1024); // Example pool size

    MAC_EVENT_TAG tag = {0x01, 0};
    long ts = 123456789;
    MAC_FRAME_DATA frames[2] = {{{'a', 'b', 'c'}, 3}, {{'d', 'e', 'f'}, 3}};

    add_event(tag, ts, frames, 2);

    cleanup_event_manager();
    return 0;
}
