    std::string str(length, ' ');
    std::mt19937 gen(std::random_device{}());
    std::uniform_int_distribution<> dist(0, sizeof(alphanum) - 2);

    for (size_t i = 0; i < length; ++i)
        str[i] = alphanum[dist(gen)];

    return str;
}

bool DataPipeline::loadFromCSV(const std::string& filename) {
    std::ifstream file(filename);
    if (!file.is_open())
        return false;

    records_.clear();
    std::string line, item;
    while (std::getline(file, line)) {
        std::stringstream ss(line);
        Record record;
        std::getline(ss, item, ',');
        record.offset = std::stol(item);

        std::getline(ss, item, ',');
        record.key = std::stoi(item);

        std::getline(ss, item, ',');
        record.weight = std::stod(item);

        std::getline(ss, record.description, ',');

        records_.push_back(record);
    }
    return true;
}

bool DataPipeline::saveToJSON(const std::string& filename) const {
    Json::Value root;
    for (const auto& record : records_) {
        Json::Value obj;
        obj["offset"] = record.offset;
        obj["key"] = record.key;
        obj["weight"] = record.weight;
        obj["description"] = record.description;

        root.append(obj);
    }

    std::ofstream file(filename);
    if (!file.is_open())
        return false;

    Json::StreamWriterBuilder writer;
    file << Json::writeString(writer, root);

    return true;
}

bool DataPipeline::processParallel(int threadPoolSize) {
    std::vector<std::thread> threads;
    size_t blockSize = records_.size() / threadPoolSize;

    for (int i = 0; i < threadPoolSize; ++i) {
        threads.emplace_back([this, i, blockSize]() {
            size_t start = i * blockSize;
            size_t end = (i == threadPoolSize - 1) ? records_.size() : start + blockSize;

            std::sort(records_.begin() + start, records_.begin() + end);
        });
    }

    for (auto& t : threads)
        t.join();

    return true;
}

// Helper function to find and print the largest integer in an array of integers read from standard input.
void findAndPrintLargestInteger() {
    std::vector<int> numbers;
    int number;

    while (std::cin >> number) {
        numbers.push_back(number);
    }

    if (!numbers.empty()) {
        auto maxIt = std::max_element(numbers.begin(), numbers.end());
        std::cout << "The largest integer is: " << *maxIt << std::endl;
    } else {
        std::cout << "No integers were provided." << std::endl;
    }
}

} // namespace DynamicDataProcessor

int main() {
    using namespace DynamicDataProcessor;

    DataPipeline processor(1000);
    if (processor.loadFromCSV("data.csv")) {
        processor.saveToJSON("output.json");
    }

    if (!processor.processParallel(4)) {
        std::cerr << "Error processing data in parallel." << std::endl;
    }

    findAndPrintLargestInteger();

    return 0;
}
``` 

