    list->events = malloc(10 * sizeof(FILE_EVENT_TAG*));
    list->count = 0;
    list->capacity = 10;
    list->storage_type = type;
    list->compression_level = Z_DEFAULT_COMPRESSION; // Default zlib compression
}

void destroyFileEventList(FileEventList* list) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        free(list->events[i]->blocks);
        free(list->events[i]);
    }
    free(list->events);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int addEvent(FileEventList* list, FILE_EVENT_TAG* event) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        FILE_EVENT_TAG** new_events = realloc(list->events, new_capacity * sizeof(FILE_EVENT_TAG*));
        if (!new_events) {
            logError("Memory allocation failed");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->events = new_events;
        list->capacity = new_capacity;
    }

    FILE_BLOCK_DATA* compressed_blocks = malloc(event->block_count * sizeof(FILE_BLOCK_DATA));
    if (!compressed_blocks) {
        logError("Memory allocation failed");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    for (size_t i = 0; i < event->block_count; ++i) {
        compressData(&event->blocks[i], list->compression_level);
        compressed_blocks[i] = event->blocks[i];
    }

    FILE_EVENT_TAG* new_event = malloc(sizeof(FILE_EVENT_TAG));
    if (!new_event) {
        free(compressed_blocks);
        logError("Memory allocation failed");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    *new_event = (FILE_EVENT_TAG){event->event_tag, event->metadata, compressed_blocks, event->block_count};
    list->events[list->count++] = new_event;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int removeEvent(FileEventList* list, unsigned long event_tag) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->events[i]->event_tag == event_tag) {
            free(list->events[i]->blocks);
            free(list->events[i]);
            memmove(&list->events[i], &list->events[i + 1],
                    (list->count - i - 1) * sizeof(FILE_EVENT_TAG*));
            list->count--;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&list->lock);
    logError("Event not found");
    return -1;
}

