// Custom memory pool (simplified version)
#define MEMORY_POOL_SIZE 1024 * 1024
void* memoryPool = NULL;

void initializeMemoryPool() {
    if (!memoryPool) {
        memoryPool = malloc(MEMORY_POOL_SIZE);
        if (!memoryPool) {
            perror("Failed to allocate memory pool");
            exit(EXIT_FAILURE);
        }
    }
}

void* customMalloc(size_t size) {
    // Simple allocation logic for demonstration
    void* ptr = malloc(size);
    if (!ptr && memoryPool) {
        ptr = malloc(size);  // Try from the main heap after failing from pool
    }
    return ptr;
}

void cleanupMemory() {
    if (memoryPool) {
        free(memoryPool);
        memoryPool = NULL;
    }
}

// Linked list management
Node* createNode(Record record) {
    Node* newNode = customMalloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate node");
        exit(EXIT_FAILURE);
    }
    newNode->record = record;
    newNode->next = NULL;
    return newNode;
}

void appendToLinkedList(Node** head, Record record) {
    Node* newNode = createNode(record);
    if (*head == NULL) {
        *head = newNode;
    } else {
        Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
}

