}

float getRandomFloat(float min, float max) {
    return ((float)rand() / RAND_MAX) * (max - min) + min;
}

// Command execution with retry mechanism
void executeCommandWithRetry(const char* command, int retries) {
    for (int attempt = 0; attempt < retries; ++attempt) {
        FILE* pipe = popen(command, "r");
        if (!pipe) {
            log("Failed to open pipe for command");
            sleep(1);  // Simple backoff
            continue;
        }

        char buffer[128];
        while (fgets(buffer, sizeof(buffer), pipe) != NULL) {
            printf("%s", buffer);
        }

        int result = pclose(pipe);
        if (result == -1) {
            log("Error occurred during command execution");
        } else {
            log("Command executed successfully");
            break;
        }
    }
}

// Function to manage memory and initialize arrays and records
void manageMemoryAndInitialize() {
    srand(time(NULL));  // Seed random number generator

    long* offsets = customMalloc(1000 * sizeof(long));
    int* keys = customMalloc(1000 * sizeof(int));
    double* precisionDataValues = customMalloc(1000 * sizeof(double));
    float* secondaryPrecisionDataValues = customMalloc(1000 * sizeof(float));

    if (!offsets || !keys || !precisionDataValues || !secondaryPrecisionDataValues) {
        perror("Memory allocation failed");
        cleanupMemory();
        exit(EXIT_FAILURE);
    }

    Node* recordsHead = NULL;
    for (int i = 0; i < 1000; ++i) {
        offsets[i] = getRandomLong(1, 1000000);
        keys[i] = getRandomInt(1, 10000);
        precisionDataValues[i] = getRandomDouble(0.0, 100.0);
        secondaryPrecisionDataValues[i] = getRandomFloat(0.0f, 100.0f);

        Record record = {keys[i], offsets[i], precisionDataValues[i], secondaryPrecisionDataValues[i]};
        appendToLinkedList(&recordsHead, record);
    }

    // Setup signal handling
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signalHandler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Execute commands and log results
    executeCommandWithRetry("ls -l", 3);

    // Cleanup
    cleanupMemory();
}

int main() {
    initializeMemoryPool();
    manageMemoryAndInitialize();
    return 0;
}
