#include <pthread.h>

typedef struct {
    int value;
    long offset;
} Record;

#define ERROR_CODE_ALLOC_FAIL 1

void* manage_and_sort_records(void *arg) {
    size_t num_records = *(size_t *)arg;
    size_t random_range_start, random_range_end;

    // Memory allocation
    long *offsets = (long *)malloc(num_records * sizeof(long));
    int *keys = (int *)malloc(num_records * sizeof(int));
    Record *records = (Record *)malloc(num_records * sizeof(Record));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return (void *)(size_t)ERROR_CODE_ALLOC_FAIL;
    }

    // Initialize structures
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = i * sizeof(Record); // example offset logic
        keys[i] = rand() % (random_range_end - random_range_start + 1) + random_range_start;
        records[i].value = rand() % (random_range_end - random_range_start + 1) + random_range_start;
        records[i].offset = offsets[i];
    }

    // Custom sorting algorithm: Insertion Sort for simplicity with handling duplicates
    void insertion_sort(Record *records, int *keys, size_t num_records) {
        for (size_t i = 1; i < num_records; ++i) {
            Record temp_record = records[i];
            int key_temp = keys[i];

            int j = i - 1;
            while (j >= 0 && keys[j] > key_temp) {
                records[j + 1] = records[j];
                keys[j + 1] = keys[j];
                --j;
            }
            records[j + 1] = temp_record;
            keys[j + 1] = key_temp;
        }
    }

    insertion_sort(records, keys, num_records);

    // Memory cleanup
    free(offsets);
    free(keys);
    free(records);

    return NULL;
}

int main() {
    size_t num_datasets = 5;
    size_t dataset_sizes[] = {10, 20, 30, 40, 50};

    pthread_t threads[num_datasets];

    for (size_t i = 0; i < num_datasets; ++i) {
        if (pthread_create(&threads[i], NULL, manage_and_sort_records, &dataset_sizes[i])) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (size_t i = 0; i < num_datasets; ++i) {
        void *status;
        if (pthread_join(threads[i], &status) != 0) {
            perror("Failed to join thread");
            continue;
        }
        if ((size_t)status == ERROR_CODE_ALLOC_FAIL) {
            fprintf(stderr, "Memory allocation failed for dataset %zu\n", i);
        }
    }

    return EXIT_SUCCESS;
}
