    pthread_mutex_init(&logger->lock, NULL);
}

void logger_cleanup(Logger *logger) {
    if (logger->file) fclose(logger->file);
    pthread_mutex_destroy(&logger->lock);
}

void log_message(Logger *logger, LogLevel level, const char *message) {
    if (level < logger->level) return;

    pthread_mutex_lock(&logger->lock);
    fprintf(logger->file, "[%ld] %s: %s\n", time(NULL), get_log_level_string(level), message);
    fflush(logger->file);
    pthread_mutex_unlock(&logger->lock);
}

const char* get_log_level_string(LogLevel level) {
    switch (level) {
        case LOG_ERROR: return "ERROR";
        case LOG_WARN:  return "WARN";
        case LOG_INFO:  return "INFO";
        case LOG_DEBUG: return "DEBUG";
        default:        return "UNKNOWN";
    }
}

// NetworkEventList structure
typedef struct {
    NetworkEvent **events;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} NetworkEventList;

void initialize_event_list(NetworkEventList *list, size_t initial_capacity) {
    list->events = malloc(initial_capacity * sizeof(NetworkEvent*));
    if (!list->events) {
        perror("Failed to allocate memory for event list");
        exit(EXIT_FAILURE);
    }
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void cleanup_event_list(NetworkEventList *list, Logger *logger) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        free(list->events[i]->frames);
        free(list->events[i]);
    }
    free(list->events);
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
}

int add_event(NetworkEventList *list, MAC_EVENT_TAG tag, MAC_FRAME_DATA *frame_data_array, size_t frame_count) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NetworkEvent **new_events = realloc(list->events, new_capacity * sizeof(NetworkEvent*));
        if (!new_events) {
            log_message(logger, LOG_ERROR, "Failed to reallocate memory for event list");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        memset(new_events + list->capacity, 0, (new_capacity - list->capacity) * sizeof(NetworkEvent*));
        list->events = new_events;
        list->capacity = new_capacity;
    }

    NetworkEvent *event = malloc(sizeof(NetworkEvent));
    if (!event) {
        log_message(logger, LOG_ERROR, "Failed to allocate memory for a network event");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    event->event_tag = tag;
    event->timestamp = time(NULL);

    event->frames = malloc(frame_count * sizeof(MAC_FRAME_DATA));
    if (!event->frames) {
        free(event);
        log_message(logger, LOG_ERROR, "Failed to allocate memory for frames");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    memcpy(event->frames, frame_data_array, frame_count * sizeof(MAC_FRAME_DATA));

    event->frame_count = frame_count;

    list->events[list->count++] = event;

    pthread_mutex_unlock(&list->lock);

    log_message(logger, LOG_INFO, "Event added successfully");

    return 0;
}

void test_event_list(NetworkEventList *list) {
    MAC_EVENT_TAG tag = {.tag = 1};
    MAC_FRAME_DATA frames[] = {
        { .data_type = 2, .length = 10 },
        { .data_type = 3, .length = 20 }
    };

    add_event(list, tag, frames, sizeof(frames) / sizeof(MAC_FRAME_DATA));

    // Additional testing logic can be added here
}

int main() {
    Logger logger;
    NetworkEventList event_list;

    logger_init(&logger, LOG_INFO, "network_events.log");

    initialize_event_list(&event_list, 10);
    test_event_list(&event_list);

    cleanup_event_list(&event_list, &logger);
    logger_cleanup(&logger);

    return 0;
}
```

### Key Considerations:

1. **Thread Safety:** The function uses `pthread_mutex_t` to ensure thread-safe operations on the event list.
2. **Dynamic Allocation:** Events and their frames are dynamically allocated with checks for allocation failures.
3. **Re-sizing Strategy:** When the capacity is reached, the list's capacity is doubled, minimizing reallocation overhead under high-throughput conditions.
4. **Logging:** A basic logging mechanism records operations to a file with minimal lock contention.
5. **Error Handling:** The code includes error handling for memory allocation failures and logs appropriate messages.
6. **Cleanup:** Proper cleanup ensures no memory leaks when the list is destroyed.

This implementation provides an efficient and scalable method for managing dynamic network events while being mindful of performance and resource usage in a high-throughput environment.']

