#define MAX_NLE_COUNT 100
#define MAX_CONNECTIONS_PER_NLE 50
#define TOTAL_CONNECTION_LIMIT 500
#define CONFIG_PROFILE_SIZE sizeof(ConfigurationProfile)

typedef struct ActiveConnection {
    int id;
} ActiveConnection;

typedef struct ConfigurationProfile {
