int fetch_initial_config(ConfigurationProfile **profile) {
    // Simulate fetching from an external data source
    *profile = (ConfigurationProfile *)malloc(CONFIG_PROFILE_SIZE);
    if (*profile == NULL) return -1;  // Error handling for allocation failure
    printf("Fetched configuration profile.\n");
    return 0;
}

int validate_total_connections(size_t current_count, size_t new_connections) {
    if (current_count + new_connections > TOTAL_CONNECTION_LIMIT) {
        logging.warning(f"Connection limit exceeded. Current: {current_count}, Attempted: {new_connections}. Initiating graceful degradation.");
        return -1;
    }
    return 0;
}

NetworkLayerEntity* initialize_nle(int nle_count, size_t connections_per_nle) {
    if (nle_count > MAX_NLE_COUNT || connections_per_nle > MAX_CONNECTIONS_PER_NLE)
        return NULL;

    NetworkLayerEntity *NLEs = (NetworkLayerEntity *)malloc(nle_count * sizeof(NetworkLayerEntity));
    if (!NLEs) return NULL;  // Error handling for allocation failure

    size_t total_connections = 0;

    for (int i = 0; i < nle_count; ++i) {
        NLEs[i].NID = i + 1;

        if (validate_total_connections(total_connections, connections_per_nle)) {
            logging.error(f"Initialization failed due to connection limit exceeded. Rolling back.")
            free(NLEs);
            return NULL;
        }

        NLEs[i].ActiveConnections = (ActiveConnection *)malloc(connections_per_nle * sizeof(ActiveConnection));
        if (!NLEs[i].ActiveConnections) {
            logging.error(f"Memory allocation failed for ActiveConnections in NLE {i}. Rolling back.")
            // Free previously allocated resources
            while (i-- > 0) free(NLEs[i].ActiveConnections);
            free(NLEs);
            return NULL;
        }

        for (size_t j = 0; j < connections_per_nle; ++j) {
            NLEs[i].ActiveConnections[j].id = j + 1;
        }

        NLEs[i].connection_count = connections_per_nle;

        if (fetch_initial_config(&NLEs[i].ConfigProfile)) {
            logging.error(f"Failed to fetch configuration profile for NLE {i}. Rolling back.")
            free(NLEs[i].ActiveConnections);
            // Free previously allocated resources
            while (--i >= 0) free(NLEs[i].ActiveConnections);
            free(NLEs);
            return NULL;
        }

        total_connections += connections_per_nle;
    }

    logging.info("NLE instances initialized successfully.")
    return NLEs;
}

void cleanup_network_layer_entities(NetworkLayerEntity *nles, int nle_count) {
    if (!nles) return;

    for (int i = 0; i < nle_count; ++i) {
        free(nles[i].ActiveConnections);
        free(nles[i].ConfigProfile);
    }
    free(nles);
}

// Example usage
int main() {
    int nle_count = 5;
    size_t connections_per_nle = 50;

    NetworkLayerEntity *nles = initialize_nle(nle_count, connections_per_nle);
    if (!nles) {
        logging.error("Failed to initialize NLE instances.")
        return EXIT_FAILURE;
    }

    // Use the initialized entities...

    cleanup_network_layer_entities(nles, nle_count);

    return EXIT_SUCCESS;
}
```

This implementation takes care of initializing multiple Network Layer Entities (NLEs), managing memory efficiently and providing error handling. The function `initialize_nle` sets up each NLE with a unique identifier, a list of active connections, and a configuration profile. It ensures that the total number of connections does not exceed a specified limit, handles potential errors during initialization gracefully, and provides logging for tracking.

The code is designed to be extensible, allowing additional configurations or connection management logic to be added later without significant refactoring. The `cleanup_network_layer_entities` function ensures that all dynamically allocated memory is properly freed, preventing memory leaks. This makes the system robust and adaptable to varying load conditions while maintaining performance and scalability.']

