        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<> dis(0.1, 10.0); // Simulated throughput range

        metric->throughput = dis(gen);
        metric->timeStamp = std::chrono::steady_clock::now();
    }

    void calculateMovingAverage(std::vector<NetworkPerformanceMetrics>& metrics, size_t index) {
        const size_t windowSize = 10;
        double sum = 0.0;

        for (size_t i = std::max(size_t(0), index - windowSize + 1); i <= index; ++i) {
            sum += metrics[i].throughput;
        }

        if (index >= windowSize - 1) {
            metrics[index].movingAverageThroughput = sum / windowSize;
        }
    }

    void addVerticesAndEdges(boost::adjacency_list<boost::vecS, boost::vecS, boost::undirectedS>& graph) {
        // Example of adding vertices and edges
        size_t numVertices = 100;
        for (size_t i = 0; i < numVertices; ++i) {
            boost::add_vertex(graph);
        }

        for (size_t i = 0; i < numVertices - 1; ++i) {
            boost::add_edge(i, i + 1, graph);
        }
