    return keys;
}

record* initialize_records(size_t count, int* records_size_out) {
    size_t available_memory = (MAX_BUFFER_SIZE - sizeof(long)*MAX_BUFFER_SIZE/sizeof(long)) / sizeof(record);

    if (count > available_memory) {
        *records_size_out = 0;
        return NULL;
    }

    record* records = (record*)malloc(count * sizeof(record));
    if (!records) {
        *records_size_out = 0;
        return NULL;
    }

