    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < count;) {
        int rand_val = rand() % (RANDOM_RANGE_MAX - RANDOM_RANGE_MIN + 1) + RANDOM_RANGE_MIN;

        if (!used_values[rand_val]) {
            records[i].value = rand_val;
            used_values[rand_val] = 1;
            ++i;
        }
