#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_STRING_LENGTH 10

typedef struct {
    long offset;
    int key;
    double value;
    char field[MAX_STRING_LENGTH + 1];
} record;

// Predefined list of strings for the `char` field
const char* predefined_strings[] = {"alpha", "beta", "gamma", "delta", "epsilon"};
size_t num_predefined_strings = sizeof(predefined_strings) / sizeof(predefined_strings[0]);

// Synchronization primitives
pthread_mutex_t data_access_mutex = PTHREAD_MUTEX_INITIALIZER;
int retry_attempts = 3; // Configurable number of retries for external access
unsigned int timeout_ms = 1000; // Timeout in milliseconds

double calculate_value(long offset, int key) {
    return (double)(offset + key) / (1.0 + fabs((double)key));
}

const char* select_random_string() {
    size_t index = rand() % num_predefined_strings;
    size_t string_length = strlen(predefined_strings[index]);
    const char* substring = predefined_strings[index];

    if (string_length > MAX_STRING_LENGTH) {
        return strndup(substring, MAX_STRING_LENGTH);
    } else {
        return strndup(substring, string_length);
    }
}

int access_external_data_with_retry(void (*data_access_func)(record*)) {
    int attempt = 0;
    while (attempt < retry_attempts) {
        if (pthread_mutex_lock(&data_access_mutex) != 0) {
            fprintf(stderr, "Mutex lock failed\n");
            return -1;
        }

        // Simulate data access delay
        usleep(timeout_ms * 1000);

        (*data_access_func)(NULL);  // Replace NULL with actual record pointer as needed

        if (pthread_mutex_unlock(&data_access_mutex) != 0) {
            fprintf(stderr, "Mutex unlock failed\n");
            return -1;
        }

        attempt++;
    }
    return 0; // Success
}

record* initialize_records(size_t num_records, long offset_min, long offset_max, int key_start) {
    if (num_records == 0 || offset_min > offset_max || key_start < 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }

    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        perror("Memory allocation failed for records array");
        return NULL;
    }

    srand(time(NULL));

    long range = offset_max - offset_min + 1;

    for (size_t i = 0; i < num_records; ++i) {
        record* rec = &records[i];

        // Initialize fields
        rec->offset = rand() % range + offset_min;
        rec->key = key_start + i;
        rec->value = calculate_value(rec->offset, rec->key);

        const char* random_string = select_random_string();
        strncpy(rec->field, random_string, MAX_STRING_LENGTH);
        rec->field[MAX_STRING_LENGTH] = '\0'; // Ensure null-termination

        free((void*)random_string);  // Free allocated string
    }

    return records;
}

void cleanup_records(record* records) {
    if (records) {
        free(records);
    }
}

// Example function to simulate external data access
void example_external_data_access_func(record* rec) {
    // Simulate some processing or delay for accessing external resources
}

int main() {
    size_t num_records = 100;
    long offset_min = 0, offset_max = 1000000;
    int key_start = 1;

    if (access_external_data_with_retry(example_external_data_access_func) != 0) {
        fprintf(stderr, "Failed to access external data\n");
        return EXIT_FAILURE;
    }

    record* records = initialize_records(num_records, offset_min, offset_max, key_start);
    if (!records) {
        fprintf(stderr, "Failed to initialize records\n");
        return EXIT_FAILURE;
    }

    // Use the records for some processing...

    cleanup_records(records);

    return EXIT_SUCCESS;
}
