typedef struct Node {
    FILE_EVENT_TAG event;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t lock;
} EventList;

EventList *create_event_list() {
    EventList *list = malloc(sizeof(EventList));
    list->head = NULL;
