void add_file_event(EventList *list, FILE_EVENT_TAG event) {
    Node *new_node = malloc(sizeof(Node));
    new_node->event = event;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);

    resize_list_if_needed(list);
}

void remove_file_event(EventList *list, atomic_int tag) {
    pthread_mutex_lock(&list->lock);
    Node **current = &list->head;

    while (*current) {
        if (atomic_load(&(*current)->event.tag) == tag) {
            Node *to_delete = *current;
            *current = to_delete->next;
            free(to_delete);
            break;
        }
        current = &((*current)->next);
    }
    pthread_mutex_unlock(&list->lock);
}

