void free_event_list(EventList *list) {
    Node *current = list->head;
    while (current) {
        Node *next = current->next;
        for (size_t i = 0; i < current->event.block_count; ++i) {
            free(current->event.blocks[i].data);
        }
        free(current->event.blocks);
        free(current);
        current = next;
