#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>
#include <stdatomic.h>

#define INITIAL_CAPACITY 1024

typedef struct {
    uint32_t userId;
    time_t sessionStart;
    time_t sessionEnd;
    double sessionDuration; // in seconds
    int activityScore;
} UserSessionData;

typedef struct {
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    atomic_size_t resize_lock;
    UserSessionData *data;
} SessionHashTable;

double random_normal(double mean, double stddev) {
    static const double inv_sqrt_2pi = 0.3989422804014327; // precomputed inverse sqrt(2*pi)
    static uint32_t hasSpare = 0;
    static double spare;

    if (hasSpare) {
        hasSpare = 0;
        return mean + stddev * spare;
    }

    double u1, u2, w, mult;
    do {
        u1 = rand() / (RAND_MAX + 1.0);
        u2 = rand() / (RAND_MAX + 1.0);

        w = (double)sqrt(-2.0 * log(u1)) * cos(2.0 * M_PI * u2);
        mult = inv_sqrt_2pi * w;
    } while (u1 - 0.5 < fabs(w));

    spare = (double)std::sqrt(-2.0 * std::log(u1)) * std::sin(2.0 * M_PI * u2);
    hasSpare = 1;

    return mean + stddev * mult;
}

SessionHashTable* create_session_hash_table(size_t initial_capacity) {
    SessionHashTable *table = (SessionHashTable *)malloc(sizeof(SessionHashTable));
    if (!table) {
        perror("Failed to allocate memory for session hash table");
        return NULL;
    }

    pthread_mutex_init(&table->lock, NULL);
    atomic_store_explicit(&table->resize_lock, 0, memory_order_relaxed);

    table->capacity = initial_capacity;
    table->count = 0;
    table->data = (UserSessionData *)calloc(table->capacity, sizeof(UserSessionData));
    if (!table->data) {
        perror("Failed to allocate memory for session data");
        pthread_mutex_destroy(&table->lock);
        free(table);
        return NULL;
    }

    return table;
}

void resize_table(SessionHashTable *table) {
    size_t new_capacity = table->capacity * 2;
    UserSessionData *new_data = (UserSessionData *)calloc(new_capacity, sizeof(UserSessionData));
    if (!new_data) {
        perror("Failed to allocate memory during resizing");
        return;
    }

    for (size_t i = 0; i < table->count; ++i) {
        size_t hash_idx = table->data[i].userId % new_capacity;
        while (new_data[hash_idx].userId != 0) {
            hash_idx = (hash_idx + 1) % new_capacity;
        }
        new_data[hash_idx] = table->data[i];
    }

    free(table->data);
    table->data = new_data;
    table->capacity = new_capacity;
}

void insert_session(SessionHashTable *table, uint32_t userId, time_t sessionStart, double meanDuration, double stddev) {
    if (atomic_load_explicit(&table->resize_lock, memory_order_relaxed)) return;

    if (table->count >= table->capacity) {
        resize_table(table);
    }

    size_t hash_idx = userId % table->capacity;
    while (table->data[hash_idx].userId != 0) {
        hash_idx = (hash_idx + 1) % table->capacity;
    }

    UserSessionData *session = &table->data[hash_idx];
    session->userId = userId;
    session->sessionStart = sessionStart;
    session->sessionEnd = sessionStart + random_normal(meanDuration, stddev);
    session->sessionDuration = difftime(session->sessionEnd, session->sessionStart);

    // Calculate activityScore based on business logic thresholds
    if (session->sessionDuration < 300) {
        session->activityScore = 1;
    } else if (session->sessionDuration < 600) {
        session->activityScore = 2;
    } else {
        session->activityScore = 3;
    }

    table->count++;
}

void free_session_hash_table(SessionHashTable *table) {
    if (!table) return;

    pthread_mutex_lock(&table->lock);
    for (size_t i = 0; i < table->capacity; ++i) {
        // In a real-world application, you might want to log or process each session before freeing
    }
    free(table->data);
    pthread_mutex_unlock(&table->lock);

    pthread_mutex_destroy(&table->lock);
    free(table);
}

int main() {
    srand(time(NULL));  // Seed random number generator

    SessionHashTable *sessionTable = create_session_hash_table(INITIAL_CAPACITY);
    if (!sessionTable) return EXIT_FAILURE;

    // Simulate inserting sessions
    for (uint32_t i = 0; i < 1000000; ++i) {
        insert_session(sessionTable, i, time(NULL), 500.0, 50.0); // mean = 500ms, stddev = 50ms
    }

    free_session_hash_table(sessionTable);
    return EXIT_SUCCESS;
}
```

This code provides a basic implementation of a hash table to manage user session data with random session durations based on a normal distribution. It includes dynamic resizing and simple thread safety using mutexes for concurrent access. Note that in a production environment, more advanced techniques such as lock-free programming might be necessary for higher performance under heavy concurrency.']

