#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>

#define MAX_STRING_LENGTH 15

typedef struct record {
    long offset;
    int key;
    double precisionValue;
    char string[MAX_STRING_LENGTH + 5]; // Extra space for hex prefix
    bool isPrimeOffset;
} Record;

bool is_prime(long num) {
    if (num <= 1) return false;
    if (num <= 3) return true;
    if (num % 2 == 0 || num % 3 == 0) return false;

    for (long i = 5; i * i <= num; i += 6) {
        if (num % i == 0 || num % (i + 2) == 0)
            return false;
    }
    return true;
}

double calculate_precision_value(long offset, int key) {
    double value = (double)(offset * key) / (1.0 + abs(offset - key));
    return round(value * 100.0) / 100.0; // Round to two decimal places
}

Record* initialize_records(int numRecords, long rangeMin, long rangeMax, int startKey, const char* substrings[], int numSubstrings) {
    if (numRecords <= 0 || rangeMin >= rangeMax || startKey < 0 || numSubstrings <= 0) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    Record *records = malloc(numRecords * sizeof(Record));
    if (!records) {
        perror("Memory allocation failed for records.");
        return NULL;
    }

    long offsets[numRecords];
    bool uniqueOffsets[rangeMax - rangeMin + 1] = {false};
    int key = startKey;

    // Initialize random number generator
    srand(time(NULL));

    // Generate unique offsets
    for (int i = 0; i < numRecords; ++i) {
        long offset;
        do {
            offset = rand() % (rangeMax - rangeMin + 1) + rangeMin;
        } while (uniqueOffsets[offset - rangeMin]);

        offsets[i] = offset;
        uniqueOffsets[offset - rangeMin] = true;
    }

    // Populate records
    for (int i = 0; i < numRecords; ++i) {
        Record *record = &records[i];
        record->offset = offsets[i];
        record->key = key++;

        // Calculate double precision value
        record->precisionValue = calculate_precision_value(record->offset, record->key);

        // Populate string with hexadecimal prefix and substring
        snprintf(record->string, sizeof(record->string), "%X_%s", record->key, substrings[i % numSubstrings]);
        if (strlen(record->string) > MAX_STRING_LENGTH) {
            strncpy(record->string, record->string + strlen(record->string) - MAX_STRING_LENGTH, MAX_STRING_LENGTH);
            record->string[MAX_STRING_LENGTH] = '\0';
        }

        // Determine if the offset is prime
        record->isPrimeOffset = is_prime(record->offset);
    }

    return records;
}

void free_records(Record *records, int numRecords) {
    free(records);
}

int main() {
    const char* substrings[] = {"Alpha", "Beta", "Gamma", "Delta"};
    int numSubstrings = sizeof(substrings) / sizeof(substrings[0]);

    Record *records = initialize_records(10, 100, 200, 1, substrings, numSubstrings);
    if (!records) {
        fprintf(stderr, "Failed to initialize records.\n");
        return EXIT_FAILURE;
    }

    // Example usage of the records
    for (int i = 0; i < 10; ++i) {
        printf("Offset: %ld, Key: %d, Precision Value: %.2f, String: %s, Is Prime: %s\n",
               records[i].offset,
               records[i].key,
               records[i].precisionValue,
               records[i].string,
               records[i].isPrimeOffset ? "Yes" : "No");
    }

    free_records(records, 10);
    return EXIT_SUCCESS;
}
