    if (identifier <= 0 || identifier > MAX_IDENTIFIER)
        return -1;

    pthread_mutex_lock(&collection->lock);

    // Resize if necessary
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Entry* resized_entries = realloc(collection->entries, new_capacity * sizeof(Entry));
        if (!resized_entries) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Memory allocation failed
        }
        collection->entries = resized_entries;
        collection->capacity = new_capacity;
    }

    Entry* entry = &collection->entries[collection->count++];
    entry->timestamp = timestamp;
    entry->identifier = identifier;

    gmp_randstate_t rand_state;
    gmp_randinit_default(rand_state);
    adaptive_precision_calculation(rand_state, timestamp, identifier, &(entry->value));
    gmp_randclear(rand_state);

    strncpy(entry->string, get_random_string(string_pool, pool_size), sizeof(entry->string) - 1);
    entry->string[sizeof(entry->string) - 1] = '\0';

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

double calculate_value(long timestamp, int identifier) {
    // Placeholder for complex formula
    double value = (double)timestamp / (identifier + 1.0);
    return value;
}

char* get_random_string(const char** string_pool, size_t pool_size) {
