        return NULL;

    time_t t;
    srand((unsigned) time(&t));
    int index = rand() % pool_size;

    return strdup(string_pool[index]);
}

void handle_external_data_read(void (*callback)(const char*, size_t)) {
    // Simulated data read with retry logic
    for (int attempt = 0; attempt < RETRY_MAX_ATTEMPTS; ++attempt) {
        int result = callback("data", 4); // Example: replace with actual read operation
        if (result == 0) return;

        usleep(RETRY_DELAY_INITIAL_MS * (1 << attempt)); // Exponential backoff
    }
