#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} Record;

// Hash function prototype
unsigned long hash(int key);

// Structure for data processing node
typedef struct Node {
    long offset;
    int key;
    Record record;
    struct Node* next;
} Node;

// Hash table size and structure
#define TABLE_SIZE 1024

Node* hashtable[TABLE_SIZE];

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

unsigned long hash(int key) {
    // Custom hash function to minimize collisions
    return ((unsigned long)key * 2654435761U) % TABLE_SIZE;
}

void initialize_hashtable() {
    for (int i = 0; i < TABLE_SIZE; i++) {
        hashtable[i] = NULL;
    }
}

void log_error(const char* error_message) {
    fprintf(stderr, "Error: %s\n", error_message);
}

Record generate_random_record(int min_value, int max_value) {
    if (min_value > max_value) {
        log_error("Invalid range for random record generation");
        exit(EXIT_FAILURE);
    }

    Record record;
    record.value = rand() % (max_value - min_value + 1) + min_value;

    // Business rule check
    if (record.value < 0 || record.value > 100) { // Example business rule
        log_error("Record value out of acceptable range");
        exit(EXIT_FAILURE);
    }

    return record;
}

void* process_data(void* arg) {
    int key = *(int*)arg;

    pthread_mutex_lock(&lock);

    unsigned long index = hash(key);
    Node** head = &hashtable[index];

    // Check if the node already exists
    while (*head != NULL) {
        if ((*head)->key == key) {
            pthread_mutex_unlock(&lock);
            return NULL;
        }
        head = &(*head)->next;
    }

    // Allocate and initialize a new node
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_error("Memory allocation failed");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    new_node->offset = rand();  // Simulating offset value assignment
    new_node->key = key;
    new_node->record = generate_random_record(0, 100); // Example range [0, 100]
    new_node->next = *head;

    *head = new_node;

    pthread_mutex_unlock(&lock);

    return NULL;
}

void deallocate_memory() {
    for (int i = 0; i < TABLE_SIZE; i++) {
        Node* head = hashtable[i];
        while (head != NULL) {
            Node* temp = head;
            head = head->next;
            free(temp);
        }
    }
}

int main() {
    srand(time(NULL));

    initialize_hashtable();

    int keys[] = {1, 2, 3, 4, 5}; // Example keys

    pthread_t threads[sizeof(keys) / sizeof(int)];

    for (size_t i = 0; i < sizeof(keys) / sizeof(int); i++) {
        if (pthread_create(&threads[i], NULL, process_data, &keys[i]) != 0) {
            log_error("Thread creation failed");
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < sizeof(threads) / sizeof(pthread_t); i++) {
        pthread_join(threads[i], NULL);
    }

    deallocate_memory();

    return 0;
}
