#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    unsigned int mac_event_tag;
    time_t timestamp;
} MAC_EVENT;

typedef struct {
    unsigned char *data;
    size_t length;
} MAC_FRAME_DATA;

typedef struct EventNode {
    MAC_EVENT event;
    MAC_FRAME_DATA *frames;
    size_t frame_count;
    struct EventNode *next;
} EventNode;

#define INITIAL_POOL_SIZE 1024
#define MEMORY_POOL_GROWTH_FACTOR 2

typedef struct {
    unsigned char *pool;
    size_t pool_size;
    size_t used_memory;
    pthread_rwlock_t lock;
} MemoryPool;

static MemoryPool *create_memory_pool(size_t initial_size) {
    MemoryPool *mp = malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->pool = malloc(initial_size);
    if (!mp->pool) {
        free(mp);
        return NULL;
    }

    mp->pool_size = initial_size;
    mp->used_memory = 0;
    pthread_rwlock_init(&mp->lock, NULL);

    return mp;
}

static void destroy_memory_pool(MemoryPool *mp) {
    pthread_rwlock_destroy(&mp->lock);
    free(mp->pool);
    free(mp);
}

static int allocate_from_pool(MemoryPool *mp, size_t size) {
    pthread_rwlock_wrlock(&mp->lock);

    if (size > mp->pool_size - mp->used_memory) {
        size_t new_size = mp->pool_size * MEMORY_POOL_GROWTH_FACTOR;
        while (new_size < mp->used_memory + size)
            new_size *= MEMORY_POOL_GROWTH_FACTOR;

        unsigned char *new_pool = realloc(mp->pool, new_size);
        if (!new_pool) {
            pthread_rwlock_unlock(&mp->lock);
            return -1;
        }

        mp->pool = new_pool;
        mp->pool_size = new_size;
    }

    void *ptr = (void*)(mp->pool + mp->used_memory);
    mp->used_memory += size;

    pthread_rwlock_unlock(&mp->lock);

    return ptr;
}

typedef struct {
    EventNode *head;
    MemoryPool *memory_pool;
} EventList;

static EventList* create_event_list() {
    EventList *el = malloc(sizeof(EventList));
    if (!el) return NULL;

    el->head = NULL;
    el->memory_pool = create_memory_pool(INITIAL_POOL_SIZE);
    if (!el->memory_pool) {
        free(el);
        return NULL;
    }

    return el;
}

static void destroy_event_list(EventList *el) {
    pthread_rwlock_wrlock(&el->memory_pool->lock);

    EventNode *current = el->head;
    while (current) {
        for (size_t i = 0; i < current->frame_count; ++i)
            free(current->frames[i].data);

        EventNode *next = current->next;
        free(current->frames);
        free(current);

        current = next;
    }

    destroy_memory_pool(el->memory_pool);

    pthread_rwlock_unlock(&el->memory_pool->lock);
    free(el);
}

static int add_event(EventList *el, MAC_EVENT event, MAC_FRAME_DATA *frames, size_t frame_count) {
    EventNode *node = malloc(sizeof(EventNode));
    if (!node) return -1;

    node->event = event;
    node->frame_count = frame_count;

    pthread_rwlock_wrlock(el->memory_pool->lock);

    int result = allocate_from_pool(el->memory_pool, sizeof(MAC_FRAME_DATA) * frame_count);
    if (result == -1) {
        free(node);
        pthread_rwlock_unlock(el->memory_pool->lock);
        return -1;
    }

    node->frames = (MAC_FRAME_DATA*)((unsigned char*)el->memory_pool->pool + result);

    for (size_t i = 0; i < frame_count; ++i)
        memcpy(node->frames[i].data, frames[i].data, frames[i].length);

    node->frames[i - 1].length = frames[i - 1].length;

    pthread_rwlock_unlock(el->memory_pool->lock);

    node->next = el->head;
    el->head = node;

    return 0;
}

static int remove_event(EventList *el, unsigned int mac_event_tag) {
    pthread_rwlock_wrlock(&el->memory_pool->lock);

    EventNode **current = &el->head;
    while (*current && (*current)->event.mac_event_tag != mac_event_tag) {
        current = &(*current)->next;
    }

    if (!*current)
        goto unlock;

    *current = (*current)->next;
    free((*current)->frames);

    pthread_rwlock_unlock(el->memory_pool->lock);

    free(*current);

unlock:
    pthread_rwlock_unlock(&el->memory_pool->lock);

    return 0;
}

static MAC_EVENT* get_event(EventList *el, unsigned int mac_event_tag) {
    pthread_rwlock_rdlock(&el->memory_pool->lock);

    EventNode *node = el->head;
    while (node && node->event.mac_event_tag != mac_event_tag) {
        node = node->next;
    }

    if (!node) {
        pthread_rwlock_unlock(&el->memory_pool->lock);
        return NULL;
    }

    MAC_EVENT *result = malloc(sizeof(MAC_EVENT));
    if (!result) {
        pthread_rwlock_unlock(&el->memory_pool->lock);
        return NULL;
    }

    *result = node->event;
    memcpy(result, &node->event, sizeof(MAC_EVENT));

    pthread_rwlock_unlock(&el->memory_pool->lock);

    return result;
}

int main() {
    EventList *el = create_event_list();

    MAC_EVENT event1 = { .mac_event_tag = 1234, .timestamp = time(NULL) };
    MAC_FRAME_DATA frames1[] = { {.data = (unsigned char*)"frame1", .length = strlen("frame1") + 1} };

    add_event(el, event1, frames1, sizeof(frames1) / sizeof(MAC_FRAME_DATA));

    MAC_EVENT *retrieved_event = get_event(el, 1234);

    if (retrieved_event) {
        printf("Retrieved Event Tag: %u\n", retrieved_event->mac_event_tag);
        free(retrieved_event);
    }

    remove_event(el, 1234);

    destroy_event_list(el);

    return 0;
}
