int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

long time_diff_ms(struct timespec start, struct timespec end) {
    long sec_diff = end.tv_sec - start.tv_sec;
    long nsec_diff = end.tv_nsec - start.tv_nsec;
    return (sec_diff * 1000L) + nsec_diff / 1000000L;
}

typedef struct UnionFind {
    int* parent;
    size_t size;
} UnionFind;

UnionFind* uf_create(size_t size) {
    UnionFind* uf = malloc(sizeof(UnionFind));
    if (!uf) return NULL;

    uf->parent = calloc(size, sizeof(int));
    if (!uf->parent) {
        free(uf);
        return NULL;
    }

    uf->size = size;
    for (size_t i = 0; i < size; ++i) {
        uf->parent[i] = -1;
    }

    return uf;
}

int uf_find(UnionFind* uf, int x) {
    if (uf->parent[x] < 0)
        return x;
    else
        return uf->parent[x] = uf_find(uf, uf->parent[x]);
}

void uf_unite(UnionFind* uf, int x, int y) {
    x = uf_find(uf, x);
    y = uf_find(uf, y);

    if (x != y) {
        if (uf->parent[y] < uf->parent[x]) {
            uf->parent[x] = y;
        } else {
            if (uf->parent[x] == uf->parent[y])
                --uf->parent[x];
            uf->parent[y] = x;
        }
    }
}

int uf_count_sets(UnionFind* uf) {
    int count = 0;
    for (size_t i = 0; i < uf->size; ++i)
        if (uf_find(uf, i) == i && uf->parent[i] < 0)
            ++count;
    return count;
}

void free_union_find(UnionFind* uf) {
    free(uf->parent);
    free(uf);
}

int manage_memory_and_identify_disjoint_pairs(long *offsets, int *keys, size_t num_records, 
                                              int min_value, int max_value, long* disjoint_time) {

    Record* head = NULL;
    Record** tail = &head;

    // Initialize random number generator
    srand(time(NULL));

    for (size_t i = 0; i < num_records; ++i) {
        Record* new_record = malloc(sizeof(Record));
        if (!new_record) {
            free_linked_list(head);
            return -1;
        }

        new_record->value = random_int(min_value, max_value);
        new_record->next = NULL;

        *tail = new_record;
        tail = &new_record->next;
    }

    UnionFind* uf = uf_create(num_records);
    if (!uf) {
        free_linked_list(head);
        return -1;
    }

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    // Assume keys are pairs to unite in the Union-Find data structure
    for (size_t i = 0; i < num_records; ++i) {
        if (keys[i] != -1) { // Assuming -1 indicates no pair
            uf_unite(uf, i, keys[i]);
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    *disjoint_time = time_diff_ms(start, end);

    int disjoint_pairs_count = uf_count_sets(uf);

    free_linked_list(head);
    free_union_find(uf);

    return disjoint_pairs_count;
}
