#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define the structures
typedef struct {
    size_t length;
    unsigned char *data;
} offset_t;

typedef struct {
    int key;
    int value;
} key_t;

typedef struct {
    int data[100]; // Assuming a fixed maximum number of records for simplicity
    size_t count;
} record_t;

// Define a structure to hold all allocated resources
typedef struct {
    offset_t *offsets;
    key_t *keys;
    record_t *records;
    pthread_mutex_t lock;
} pipeline_state_t;

// Function prototypes
pipeline_state_t* init_pipeline(size_t max_records, size_t key_range, size_t offset_size);
void reset_pipeline(pipeline_state_t *state, size_t max_records, size_t key_range, size_t offset_size);
void free_pipeline(pipeline_state_t *state);

// Initialize the pipeline state
pipeline_state_t* init_pipeline(size_t max_records, size_t key_range, size_t offset_size) {
    pipeline_state_t *state = (pipeline_state_t*)malloc(sizeof(pipeline_state_t));
    if (!state) return NULL;

    pthread_mutex_init(&state->lock, NULL);

    // Allocate memory for offsets
    state->offsets = (offset_t*)calloc(offset_size, sizeof(offset_t));
    if (!state->offsets) {
        free(state);
        return NULL;
    }

    // Allocate memory for keys
    state->keys = (key_t*)malloc(key_range * sizeof(key_t));
    if (!state->keys) {
        free(state->offsets);
        free(state);
        return NULL;
    }

    // Allocate memory for records
    state->records = (record_t*)calloc(max_records, sizeof(record_t));
    if (!state->records) {
        free(state->keys);
        free(state->offsets);
        free(state);
        return NULL;
    }

    return state;
}

// Reset the pipeline state
void reset_pipeline(pipeline_state_t *state, size_t max_records, size_t key_range, size_t offset_size) {
    pthread_mutex_lock(&state->lock);

    // Free and reallocate memory for offsets
    free(state->offsets);
    state->offsets = (offset_t*)calloc(offset_size, sizeof(offset_t));
    if (!state->offsets) {
        pthread_mutex_unlock(&state->lock);
        return;
    }

    // Free and reallocate memory for keys
    free(state->keys);
    state->keys = (key_t*)malloc(key_range * sizeof(key_t));
    if (!state->keys) {
        free(state->offsets);
        pthread_mutex_unlock(&state->lock);
        return;
    }

    // Free and reallocate memory for records
    free(state->records);
    state->records = (record_t*)calloc(max_records, sizeof(record_t));
    if (!state->records) {
        free(state->keys);
        free(state->offsets);
        pthread_mutex_unlock(&state->lock);
        return;
    }

    // Reset record counts
    for (size_t i = 0; i < max_records; ++i) {
        state->records[i].count = 0;
    }

    pthread_mutex_unlock(&state->lock);
}

// Free the pipeline state
void free_pipeline(pipeline_state_t *state) {
    if (!state) return;

    pthread_mutex_lock(&state->lock);

    // Free all allocated resources
    free(state->offsets);
    free(state->keys);
    free(state->records);

    pthread_mutex_unlock(&state->lock);
    pthread_mutex_destroy(&state->lock);
    free(state);
}

int main() {
    size_t max_records = 10;
    size_t key_range = 50;
    size_t offset_size = 20;

    pipeline_state_t *pipeline = init_pipeline(max_records, key_range, offset_size);
    if (!pipeline) {
        fprintf(stderr, "Failed to initialize pipeline\n");
        return EXIT_FAILURE;
    }

    // Simulate some operations
    reset_pipeline(pipeline, max_records, key_range, offset_size);

    free_pipeline(pipeline);
    return EXIT_SUCCESS;
}
