bool validate_crc_indication_tag(CRC_INDICATION_REL8_TAG tag) {
    // Implement validation logic here; assuming it's always valid for demonstration
    return true;
}

// Function to log entries in a circular buffer
void log_entry(DynamicList *list, const char *message) {
    pthread_mutex_lock(&list->lock);
    strncpy(list->log_buffer[list->log_index], message, 255);
    list->log_index = (list->log_index + 1) % LOG_BUFFER_SIZE;
    if (list->log_count < LOG_BUFFER_SIZE) {
        list->log_count++;
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to generate a random CRCFLAG
bool generate_random_crcflag() {
    return rand() % 2 == 0; // Randomly true or false
}

// Thread-safe function to add an element to the dynamic list
void add_element(DynamicList *list) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_ELEMENTS) {
        log_entry(list, "List is full. Cannot add new element.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    // Simulate checking system resources and memory usage
    // This would be a call to the external resource management system in practice

    NFAPI_CRC_INDICATION_PDU_T *new_element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_element) {
        log_entry(list, "Memory allocation failed.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_element->rnti = rand(); // Generate a random RNTI
    new_element->ue_info.RNTI = new_element->rnti;

    do {
        new_element->crc_indication.CRCFLAG = generate_random_crcflag();
    } while (!validate_crc_indication_tag(new_element->crc_indication));

    list->elements[list->count++] = new_element;
    char log_message[256];
    snprintf(log_message, sizeof(log_message), "Added element with RNTI: %u\n", new_element->rnti);
    log_entry(list, log_message);

    pthread_mutex_unlock(&list->lock);
}

// Function to release an element (for simulation purposes)
void release_element(DynamicList *list, size_t index) {
    if (index < list->count && list->elements[index]) {
        free(list->elements[index]);
        memmove(&list->elements[index], &list->elements[index + 1], 
                (list->count - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        list->count--;
    }
}

// Main function to demonstrate usage
int main() {
    srand(time(NULL)); // Seed random number generator

    DynamicList nfa_list;
    init_dynamic_list(&nfa_list);

    pthread_t threads[MAX_ELEMENTS];
    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        if (pthread_create(&threads[i], NULL, (void *(*)(void *))add_element, &nfa_list)) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Cleanup
    for (size_t i = 0; i < nfa_list.count; ++i) {
        release_element(&nfa_list, i);
    }

    pthread_mutex_destroy(&nfa_list.lock);

    return 0;
}
