int allocate_crc_indication_pdu_array(size_t N, NFAPI_CRC_INDICATION_PDU_T **array) {
    size_t required_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    if (required_size > MAX_BUFFER_SIZE) {
        return ERROR_MEMORY_ALLOCATION_FAILURE;
    }

    *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(required_size);
    if (*array == NULL) {
        return ERROR_MEMORY_ALLOCATION_FAILURE;
