            free(*array);
            pthread_mutex_unlock(&rnti_mutex);
            return ERROR_MEMORY_ALLOCATION_FAILURE;
        }

        uint32_t rnti = rx_ue_info.RNTI;

        while (seen_rntis[rnti - 1]) { // Ensure RNTI is unique
            if (fetch_rx_ue_information_tag(&rx_ue_info) != 0) {
                free(*array);
                pthread_mutex_unlock(&rnti_mutex);
