#include <stdio.h>
#include <stdlib.h>
import threading

#define INITIAL_SIZE 10
#define ERROR_OUT_OF_MEMORY -1
#define ERROR_BUFFER_OVERFLOW -2
#define ERROR_INVALID_INDEX -3

typedef struct {
    unsigned int mac_event_tag;
    time_t timestamp;
} MAC_EVENT_HEADER;

typedef struct {
    unsigned char data[256]; // Example size for frame data
    unsigned int length;
} MAC_FRAME_DATA;

typedef struct {
    MAC_EVENT_HEADER header;
    MAC_FRAME_DATA frames[];
} NETWORK_EVENT;

typedef struct {
    NETWORK_EVENT *events;
    size_t count;
    size_t capacity;
    threading.Lock lock;
} EventList;

EventList* create_event_list() {
    EventList* list = (EventList*)malloc(sizeof(EventList));
    if (!list) return NULL;

    list->events = (NETWORK_EVENT*)calloc(INITIAL_SIZE, sizeof(NETWORK_EVENT));
    if (!list->events) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = INITIAL_SIZE;
    threading.Lock_init(&list->lock);
    return list;
}

int add_event(EventList* list, MAC_EVENT_HEADER header, MAC_FRAME_DATA* frame_data, size_t frame_count) {
    if (!list || frame_count == 0) return ERROR_INVALID_INDEX;

    size_t required_capacity = list->count + 1;

    // Check and expand capacity if necessary
    while (required_capacity > list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NETWORK_EVENT* temp_events = (NETWORK_EVENT*)realloc(list->events, new_capacity * sizeof(NETWORK_EVENT));
        if (!temp_events) return ERROR_OUT_OF_MEMORY;

        list->events = temp_events;
        list->capacity = new_capacity;
    }

    threading.Lock_acquire(&list->lock);

    int index = list->count++;
    NETWORK_EVENT* event = &list->events[index];

    // Initialize the MAC_EVENT_HEADER
    event->header = header;

    // Add frames to the network event, ensuring no overflow and valid data addition
    size_t total_frame_size = 0;
    for (size_t i = 0; i < frame_count; ++i) {
        if (frame_data[i].length > sizeof(event->frames)) {
            threading.Lock_release(&list->lock);
            return ERROR_BUFFER_OVERFLOW;
        }

        event->frames[total_frame_size / sizeof(MAC_FRAME_DATA)] = frame_data[i];
        total_frame_size += frame_data[i].length;

        // Validate against the maximum allocation
        if (total_frame_size > sizeof(NETWORK_EVENT) - sizeof(MAC_EVENT_HEADER)) {
            threading.Lock_release(&list->lock);
            return ERROR_BUFFER_OVERFLOW;
        }
    }

    threading.Lock_release(&list->lock);

    return 0;  // Success
}

int add_batch_events(EventList* list, MAC_EVENT_HEADER headers[], MAC_FRAME_DATA frames[][256], size_t frame_counts[], size_t event_count) {
    if (!list || !headers || !frames || !frame_counts || event_count == 0)
        return ERROR_INVALID_INDEX;

    threading.Lock_acquire(&list->lock);

    for (size_t i = 0; i < event_count; ++i) {
        int status = add_event(list, headers[i], frames[i], frame_counts[i]);
        if (status != 0) {
            threading.Lock_release(&list->lock);
            return status;
        }
    }

    threading.Lock_release(&list->lock);

    return 0;  // Success
}

void iterate_and_process_events(EventList* list, void (*process_event)(NETWORK_EVENT*)) {
    if (!list || !process_event) return;

    threading.Lock_acquire(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        process_event(&list->events[i]);
    }

    threading.Lock_release(&list->lock);
}

void free_event_list(EventList* list) {
    if (!list) return;

    threading.Lock_acquire(&list->lock);

    free(list->events);
    threading.Lock_release(&list->lock);

    free(list);
}
```

### Key Points:
- This code implements a dynamic event list with thread-safe operations using locks.
- Memory management ensures minimal fragmentation by doubling the capacity when expanding.
- The `add_event` and `add_batch_events` functions handle adding events, ensuring atomicity and preventing buffer overflow.
- Iterating over events supports concurrent reads while write operations are protected with mutexes for thread safety.']

