#define MAX_TIMESTAMP 2147483647
#define MIN_TIMESTAMP 0
#define SYSTEM_MEMORY_LIMIT 104857600 // Example limit: 100 MB

typedef struct {
    long timestamp;
    char *message;
} LogEntry;

typedef struct {
    char session_id[16];
} SessionInfo;

typedef struct {
    char ip_address[15];
    char geolocation[50];
} Metadata;

typedef struct {
    pthread_mutex_t lock;
    int count;
    int head;
    int tail;
    int max_size;
    long *timestamps;
    char **usernames;
    LogEntry *log_entries;
    SessionInfo *session_ids;
    Metadata *metadata;
    int access_count;
} CircularBuffer;

void log_error(const char *error_message) {
    // Placeholder for logging error to an external service
    printf("ERROR: %s\n", error_message);
}

int is_valid_timestamp(long timestamp) {
    return (timestamp >= MIN_TIMESTAMP && timestamp <= MAX_TIMESTAMP);
}

CircularBuffer* create_circular_buffer(int size) {
    CircularBuffer *buffer = malloc(sizeof(CircularBuffer));
    if (!buffer) {
        log_error("Memory allocation failed for buffer");
        return NULL;
    }

    pthread_mutex_init(&buffer->lock, NULL);

    buffer->max_size = size;
    buffer->count = 0;
    buffer->head = 0;
    buffer->tail = 0;
    buffer->timestamps = malloc(size * sizeof(long));
    buffer->usernames = malloc(size * sizeof(char*));
    buffer->log_entries = malloc(size * sizeof(LogEntry));
    buffer->session_ids = malloc(size * sizeof(SessionInfo));
    buffer->metadata = malloc(size * sizeof(Metadata));
    buffer->access_count = 0;

    if (!buffer->timestamps || !buffer->usernames || !buffer->log_entries ||
        !buffer->session_ids || !buffer->metadata) {
        log_error("Memory allocation failed for circular buffer components");
        free(buffer);
        return NULL;
    }

    return buffer;
}

int add_log_entry(CircularBuffer *buffer, long timestamp, const char *username,
                  const char *message, const SessionInfo *session_id,
                  const Metadata *metadata) {
    pthread_mutex_lock(&buffer->lock);

    if (buffer->count == buffer->max_size) {
        buffer->tail = (buffer->tail + 1) % buffer->max_size;
        buffer->head = buffer->tail; // Overwrite the oldest entry
    } else {
        buffer->head = (buffer->head + 1) % buffer->max_size;
        buffer->count++;
    }

    if (!is_valid_timestamp(timestamp)) {
        log_error("Invalid timestamp detected");
        pthread_mutex_unlock(&buffer->lock);
        return -1; // Invalid timestamp
    }

    buffer->timestamps[buffer->head] = timestamp;
    buffer->usernames[buffer->head] = strdup(username);
    buffer->log_entries[buffer->head].timestamp = timestamp;
    buffer->log_entries[buffer->head].message = strdup(message);
    memcpy(&buffer->session_ids[buffer->head], session_id, sizeof(SessionInfo));
    memcpy(&buffer->metadata[buffer->head], metadata, sizeof(Metadata));

    buffer->access_count++;

    pthread_mutex_unlock(&buffer->lock);

    return 0;
}

void free_circular_buffer(CircularBuffer *buffer) {
    if (!buffer) return;

    for (int i = 0; i < buffer->max_size; ++i) {
        free(buffer->usernames[i]);
        free(buffer->log_entries[i].message);
    }

    pthread_mutex_destroy(&buffer->lock);

    free(buffer->timestamps);
    free(buffer->usernames);
    free(buffer->log_entries);
    free(buffer->session_ids);
    free(buffer->metadata);
    free(buffer);
}

int main() {
    int num_entries = 100; // Example number of entries
    CircularBuffer *cb = create_circular_buffer(num_entries);

    if (!cb) {
        log_error("Failed to initialize circular buffer");
        return EXIT_FAILURE;
    }

    SessionInfo session_id = {"SESSION123"};
    Metadata metadata = {"192.168.1.1", "Some Location"};

    for (int i = 0; i < num_entries * 2; ++i) { // Attempt double the entries to test overflow
        add_log_entry(cb, i, "user" + std::to_string(i), "log message", &session_id, &metadata);
    }

    free_circular_buffer(cb);

    return EXIT_SUCCESS;
}
