void log_creation(NFAPI_CRC_INDICATION_PDU_T pdu) {
    FILE *log_file = fopen("creation_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "RNTI: %u, CRCFLAG: %d\n", pdu.RNTI, pdu.crc_indication_rel8_tag.CRCFLAG);
        fclose(log_file);
    }
}

// Function to export list to binary file
int export_to_binary(Node* head, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    Node* current = head;
    while (current) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
    fclose(file);
    return 0;
}

// Function to create and populate list
Node* create_population_list() {
    int n;
    unsigned int seed;

    if (load_config(&n, &seed) != 0) {
        fprintf(stderr, "Failed to load configuration\n");
        return NULL;
    }

    srand(seed);
    pthread_mutex_lock(&lock);

    Node *head = NULL, *tail = NULL;

    for (int i = 0; i < n; ++i) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&lock);
            // Free previously allocated nodes
            while (head) {
                Node *temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
        }

        new_node->data.RNTI = rand();
        new_node->data.crc_indication_rel8_tag.CRCFLAG = rand() & 1;

        if (!validate_crc_tag(&(new_node->data.crc_indication_rel8_tag))) {
            free(new_node);
            continue; // Skip invalid entries
        }

        log_creation(new_node->data);

        new_node->next = NULL;
        if (tail) {
            tail->next = new_node;
            tail = new_node;
        } else {
            head = tail = new_node;
        }
    }

    pthread_mutex_unlock(&lock);
    return head;
}

// Function to free list
void free_population_list(Node* head) {
    Node *current = head, *temp;
    while (current) {
        temp = current;
        current = current->next;
        free(temp);
    }
}

int main() {
    Node* list = create_population_list();
    if (!list) return 1;

    // Example export to binary
    if (export_to_binary(list, "output.bin") != 0) {
        fprintf(stderr, "Failed to export data\n");
    }

    free_population_list(list);
    pthread_mutex_destroy(&lock);

    return 0;
}
