    int urgent;
    size_t data_length;
    uint8_t *data; // Variable-length MAC_FRAME_DATA
} NetworkEvent;

typedef struct {
    NetworkEvent **events;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t cond_var;
    FILE *log_file;
} EventList;

// Initialize a new event list
void init_event_list(EventList *list, size_t initial_capacity) {
    list->events = malloc(initial_capacity * sizeof(NetworkEvent *));
    if (!list->events) {
        perror("Failed to allocate memory for events");
        exit(EXIT_FAILURE);
    }
    list->capacity = initial_capacity;
    list->count = 0;

    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond_var, NULL);

    // Open log file
    list->log_file = fopen("event_log.txt", "a");
    if (!list->log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

// Resize the event list when capacity is reached
void resize_event_list(EventList *list) {
    size_t new_capacity = list->capacity * 2;
    NetworkEvent **new_events = realloc(list->events, new_capacity * sizeof(NetworkEvent *));
    if (!new_events) {
        perror("Failed to reallocate memory for events");
        exit(EXIT_FAILURE);
    }
    list->events = new_events;
    list->capacity = new_capacity;

    log_event_action(list, "Resized event list", 0);
}

// Log an action performed on the list
void log_event_action(EventList *list, const char *action, size_t index) {
    time_t now = time(NULL);
    fprintf(list->log_file, "[%s] Action: %s at index %zu\n", ctime(&now), action, index);
    fflush(list->log_file);
}

// Add an event to the list
void add_event(EventList *list, NetworkEvent *event) {
    pthread_mutex_lock(&list->mutex);

    if (list->count == list->capacity) {
        resize_event_list(list);
    }

    // Check for buffer overflow conditions in data length
    if (event->data_length > MAX_FRAME_SIZE) {  // Define a suitable max size
        fprintf(stderr, "Buffer overflow detected\n");
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    list->events[list->count++] = event;

    log_event_action(list, "Added event", list->count - 1);

    pthread_cond_signal(&list->cond_var);
    pthread_mutex_unlock(&list->mutex);
}

// Remove an event from the list
void remove_event(EventList *list, size_t index) {
    pthread_mutex_lock(&list->mutex);

    if (index >= list->count) {
        fprintf(stderr, "Invalid index\n");
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    free(list->events[index]->data);
    free(list->events[index]);
    memmove(&list->events[index], &list->events[index + 1],
            (list->count - index - 1) * sizeof(NetworkEvent *));
    list->count--;

    log_event_action(list, "Removed event", index);

    pthread_mutex_unlock(&list->mutex);
}

// Sort events based on priority and urgency
void sort_events(EventList *list) {
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->count - 1; ++i) {
        for (size_t j = 0; j < list->count - i - 1; ++j) {
            NetworkEvent *current = list->events[j];
            NetworkEvent *next = list->events[j + 1];

            if ((current->urgent && !next->urgent) ||
                (!current->urgent && next->urgent && current->priority < next->priority) ||
                (current->priority > next->priority)) {
                // Swap events
                NetworkEvent *temp = list->events[j];
                list->events[j] = list->events[j + 1];
                list->events[j + 1] = temp;
            }
        }
    }

    pthread_mutex_unlock(&list->mutex);
}

// Monitoring function to track performance (placeholder)
void monitor_performance(EventList *list) {
    // Placeholder for monitoring logic
}

// Clean up the event list
void destroy_event_list(EventList *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->events[i]->data);
        free(list->events[i]);
    }
    free(list->events);

    pthread_mutex_destroy(&list->mutex);
    pthread_cond_destroy(&list->cond_var);

    if (list->log_file) {
        fclose(list->log_file);
    }
}

// Example usage
int main() {
    EventList event_list;
    init_event_list(&event_list, 10);

    NetworkEvent *event1 = malloc(sizeof(NetworkEvent));
    event1->timestamp = time(NULL);
    event1->priority = 5;
    event1->urgent = 0;
    event1->data_length = 128; // Example length
    event1->data = malloc(event1->data_length);

    add_event(&event_list, event1);

    sort_events(&event_list);

    destroy_event_list(&event_list);

    return 0;
}
