#include <pthread.h>
#include <stdint.h>

#define MAX_ELEMENTS 10000

typedef struct {
    uint32_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
} CRCList;

CRCList* create_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    return list;
}

int add_element(CRCList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (list->count >= MAX_ELEMENTS) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -2;

    new_node->data = element;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

int update_element(CRCList* list, uint16_t rnti, NFAPI_CRC_INDICATION_PDU_T updated_data) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;

    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            current->data = updated_data;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1;
}

int remove_element(CRCList* list, size_t index) {
    if (index >= list->count) return -1;

    pthread_mutex_lock(&list->lock);
    Node *current = list->head, *prev = NULL;

    if (index == 0) {
        list->head = current->next;
        free(current);
    } else {
        for (size_t i = 0; current != NULL && i < index; ++i) {
            prev = current;
            current = current->next;
        }
        if (current == NULL) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        prev->next = current->next;
        free(current);
    }

    list->count--;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void serialize_list(CRCList* list, uint8_t** buffer) {
    pthread_mutex_lock(&list->lock);

    *buffer = (uint8_t*)malloc(list->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*buffer) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* current = list->head;
    size_t i = 0;

    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* data_ptr = (*buffer + i * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        *data_ptr = current->data;
        current = current->next;
        ++i;
    }

    pthread_mutex_unlock(&list->lock);
}

int deserialize_list(CRCList* list, uint8_t* buffer, size_t num_elements) {
    if (num_elements > MAX_ELEMENTS) return -1;

    pthread_mutex_lock(&list->lock);

    Node* new_head = NULL;
    Node** ptr_to_link = &new_head;

    for (size_t i = 0; i < num_elements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* data_ptr = (NFAPI_CRC_INDICATION_PDU_T*)(buffer + i * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            // Clean up already added nodes
            while (new_head != NULL) {
                Node* temp = new_head;
                new_head = new_head->next;
                free(temp);
            }
            pthread_mutex_unlock(&list->lock);
            return -2;
        }

        *data_ptr = *(NFAPI_CRC_INDICATION_PDU_T*)data_ptr;
        new_node->next = NULL;

        *ptr_to_link = new_node;
        ptr_to_link = &new_node->next;
    }

    list->head = new_head;
    list->count = num_elements;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

void destroy_list(CRCList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}
