typedef struct {
    time_t timestamp;
    float temperature;
    char identifier[10];
} sensor_data;

// Function to read historical data and return an average trend value
float get_historical_temperature_trend(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return 0.0f;

    float sum = 0.0f;
    int count = 0;
    float temp;

    while (fscanf(file, "%f", &temp) == 1) {
        sum += temp;
        count++;
    }

    fclose(file);

    return count > 0 ? sum / count : 0.0f;
}

// Function to generate a random temperature within a range based on historical trend
float generate_temperature(float trend, float min_range, float max_range) {
    float range = (max_range - min_range);
    float random_value = ((float) rand() / RAND_MAX) * range + min_range;
    return random_value + trend;
}

// Function to initialize and populate sensor data array
sensor_data* init_sensor_data_array(size_t initial_size, const char *historical_file, 
                                    float min_temp, float max_temp, char **error_log) {
    if (!initial_size || !historical_file || !min_temp || !max_temp) {
        if (error_log) *error_log = strdup("Invalid arguments provided.");
        return NULL;
    }

    sensor_data* data_array = malloc(initial_size * sizeof(sensor_data));
    if (!data_array) {
        if (error_log) *error_log = strdup("Memory allocation failed for sensor_data array.");
        return NULL;
    }

    float trend = get_historical_temperature_trend(historical_file);

    srand((unsigned int) time(NULL));

    for (size_t i = 0; i < initial_size; ++i) {
        data_array[i].timestamp = time(NULL);
        data_array[i].temperature = generate_temperature(trend, min_temp, max_temp);
        snprintf(data_array[i].identifier, sizeof(data_array[i].identifier), "ID%zu", i + 1);
    }

    return data_array;
}

// Function to resize the sensor_data array
sensor_data* resize_sensor_data_array(sensor_data *array, size_t current_size, 
                                      size_t new_size, char **error_log) {
    if (!array || !new_size) {
        if (error_log) *error_log = strdup("Invalid arguments provided for resizing.");
        return NULL;
    }

    sensor_data* resized_array = realloc(array, new_size * sizeof(sensor_data));
    if (!resized_array && current_size > 0) {
        if (error_log) *error_log = strdup("Memory reallocation failed for sensor_data array.");
        free(array);
        return NULL;
    }

    // Initialize new elements
    float trend = get_historical_temperature_trend("historical_data.txt");
    srand((unsigned int) time(NULL));

    for (size_t i = current_size; i < new_size; ++i) {
        resized_array[i].timestamp = time(NULL);
        resized_array[i].temperature = generate_temperature(trend, 0.0f, 100.0f); // Assume range
        snprintf(resized_array[i].identifier, sizeof(resized_array[i].identifier), "ID%zu", i + 1);
    }

    return resized_array;
}

// Function to free allocated sensor_data array memory
void free_sensor_data_array(sensor_data *array) {
    if (array) {
        free(array);
    }
}
