    struct HashNode *next;
} HashNode;

typedef struct {
    HashNode **buckets;
    size_t size;
    size_t count;
    pthread_mutex_t lock;
} HashTable;

unsigned int hash_function(uint32_t key, size_t size) {
    return key % size;
}

HashTable* create_hash_table(size_t initial_size) {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    table->buckets = (HashNode**)calloc(initial_size, sizeof(HashNode*));
    table->size = initial_size;
    table->count = 0;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void resize_hash_table(HashTable *table) {
    size_t new_size = table->size * 2;
    HashNode **new_buckets = (HashNode**)calloc(new_size, sizeof(HashNode*));

    for (size_t i = 0; i < table->size; ++i) {
        HashNode *node = table->buckets[i];
        while (node) {
            unsigned int new_index = hash_function(node->key, new_size);
            HashNode *next_node = node->next;
            node->next = new_buckets[new_index];
            new_buckets[new_index] = node;
            node = next_node;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->size = new_size;
}

void insert_to_hash_table(HashTable *table, uint32_t key, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&table->lock);

    if ((double)table->count / table->size >= HASH_TABLE_LOAD_FACTOR) {
        resize_hash_table(table);
    }

    unsigned int index = hash_function(key, table->size);
    HashNode *node = (HashNode*)malloc(sizeof(HashNode));
    node->key = key;
    node->pdu = pdu;
    node->next = table->buckets[index];
    table->buckets[index] = node;

    table->count++;
    pthread_mutex_unlock(&table->lock);
}

NFAPI_CRC_INDICATION_PDU_T* find_in_hash_table(HashTable *table, uint32_t key) {
    unsigned int index = hash_function(key, table->size);

    pthread_mutex_lock(&table->lock);
    HashNode *node = table->buckets[index];
    while (node) {
        if (node->key == key) {
            pthread_mutex_unlock(&table->lock);
            return &node->pdu;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void delete_from_hash_table(HashTable *table, uint32_t key) {
    unsigned int index = hash_function(key, table->size);

    pthread_mutex_lock(&table->lock);
    HashNode *node = table->buckets[index];
    HashNode *prev_node = NULL;

    while (node) {
        if (node->key == key) {
            if (prev_node) {
                prev_node->next = node->next;
            } else {
                table->buckets[index] = node->next;
            }
            free(node);
            table->count--;
            break;
        }
        prev_node = node;
        node = node->next;
    }

    pthread_mutex_unlock(&table->lock);
}

void destroy_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->size; ++i) {
        HashNode *node = table->buckets[i];
        while (node) {
            HashNode *next_node = node->next;
            free(node);
            node = next_node;
        }
    }

    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

