#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <stdbool.h>

#define INITIAL_TABLE_SIZE 101

typedef struct {
    float f;
    int i;
    bool b;
} element_t;

typedef struct hash_node {
    char *key;
    element_t *value;
    struct hash_node *next;
} hash_node_t;

typedef struct {
    hash_node_t **buckets;
    size_t size;
    size_t count;
} hashtable_t;

unsigned long hash_function(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c;
    return hash;
}

hashtable_t* create_hashtable(size_t size) {
    hashtable_t *table = malloc(sizeof(hashtable_t));
    if (!table) return NULL;

    table->buckets = calloc(size, sizeof(hash_node_t*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->size = size;
    table->count = 0;
    return table;
}

void resize_hashtable(hashtable_t *table);

int hashtable_insert(hashtable_t *table, const char *key, element_t *value) {
    if (!table || !key) return -1;

    unsigned long index = hash_function(key) % table->size;
    hash_node_t *new_node = malloc(sizeof(hash_node_t));
    if (!new_node) return -1;

    new_node->key = strdup(key);
    new_node->value = value;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;
    table->count++;

    if ((float)table->count / table->size > 0.7) {
        resize_hashtable(table);
    }

    return 0;
}

element_t* hashtable_lookup(hashtable_t *table, const char *key) {
    if (!table || !key) return NULL;

    unsigned long index = hash_function(key) % table->size;
    for (hash_node_t *node = table->buckets[index]; node; node = node->next) {
        if (strcmp(node->key, key) == 0)
            return node->value;
    }

    return NULL;
}

void resize_hashtable(hashtable_t *table) {
    size_t new_size = table->size * 2;
    hash_node_t **new_buckets = calloc(new_size, sizeof(hash_node_t*));
    if (!new_buckets) {
        fprintf(stderr, "Failed to allocate memory for resizing hashtable.\n");
        return;
    }

    for (size_t i = 0; i < table->size; ++i) {
        hash_node_t *node = table->buckets[i];
        while (node) {
            hash_node_t *next = node->next;

            unsigned long new_index = hash_function(node->key) % new_size;
            node->next = new_buckets[new_index];
            new_buckets[new_index] = node;

            node = next;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->size = new_size;
}

void free_hashtable(hashtable_t *table) {
    if (!table) return;

    for (size_t i = 0; i < table->size; ++i) {
        hash_node_t *node = table->buckets[i];
        while (node) {
            hash_node_t *next = node->next;
            free(node->key);
            free(node->value);
            free(node);
            node = next;
        }
    }

    free(table->buckets);
    free(table);
}

void* dns_resolve(const char *hostname, u_char *ip_address) {
    struct hostent *host_info = gethostbyname(hostname);
    if (!host_info || !host_info->h_addr_list[0]) {
        fprintf(stderr, "DNS resolution failed for %s\n", hostname);
        return NULL;
    }

    inet_pton(AF_INET, inet_ntoa(*(struct in_addr *)host_info->h_addr_list[0]), ip_address);
    return host_info;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <hostname>\n", argv[0]);
        return EXIT_FAILURE;
    }

    double *double_array = malloc(10 * sizeof(double));
    char *char_array = malloc(20 * sizeof(char));
    struct element *element_pointers = malloc(5 * sizeof(struct element*));

    if (!double_array || !char_array || !element_pointers) {
        fprintf(stderr, "Memory allocation failed\n");
        free(double_array);
        free(char_array);
        free(element_pointers);
        return EXIT_FAILURE;
    }

    hashtable_t *hash_table = create_hashtable(INITIAL_TABLE_SIZE);
    if (!hash_table) {
        fprintf(stderr, "Failed to create hash table.\n");
        free(double_array);
        free(char_array);
        free(element_pointers);
        return EXIT_FAILURE;
    }

    element_t elem = {1.0f, 2, true};
    hashtable_insert(hash_table, "key1", &elem);

    u_char ip_address[4];
    if (dns_resolve(argv[1], ip_address) == NULL) {
        free_hashtable(hash_table);
        free(double_array);
        free(char_array);
        free(element_pointers);
        return EXIT_FAILURE;
    }

    printf("IP Address: %s\n", inet_ntoa(*(struct in_addr){.s_addr = *(unsigned int *)ip_address}));

    element_t *retrieved_elem = hashtable_lookup(hash_table, "key1");
    if (retrieved_elem) {
        printf("Element found: float=%f, int=%d, bool=%d\n", retrieved_elem->f, retrieved_elem->i, retrieved_elem->b);
    }

    free_hashtable(hash_table);
    free(double_array);
    free(char_array);
    free(element_pointers);

    return EXIT_SUCCESS;
}
