int allocate_and_initialize_arrays(MemoryManager *manager, size_t initial_size) {
    manager->offsets = calloc(initial_size, sizeof(long));
    if (!manager->offsets) return -1;

    manager->keys = calloc(initial_size, sizeof(int));
    if (!manager->keys) {
        free(manager->offsets);
        return -1;
    }

    return 0;
}

// Allocate and initialize records
