int set_random_record_values(MemoryManager *manager, int min_value, int max_value, int unique) {
    if (unique) {
        int *values_set = calloc(max_value - min_value + 1, sizeof(int));
        if (!values_set) return -1;

        srand(time(NULL)); // Ensure thread-safe initialization
        for (size_t i = 0; i < manager->record_count; ++i) {
            int value;
            do {
                value = rand() % (max_value - min_value + 1) + min_value;
            } while (values_set[value - min_value]);

            values_set[value - min_value] = 1;
            manager->records[i].value = value;
        }

        free(values_set);
    } else {
        srand(time(NULL)); // Ensure thread-safe initialization
        for (size_t i = 0; i < manager->record_count; ++i) {
            manager->records[i].value = rand() % (max_value - min_value + 1) + min_value;
        }
    }

