    fprintf(stderr, "Error occurred: %d\n", error_code);
}

// Serialize state to a file
void serialize_state(const MemoryManager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for serialization");
        return;
    }

    pthread_mutex_lock(&manager->lock);
    fwrite(manager->offsets, sizeof(long), manager->offset_count, file);
    fwrite(manager->keys, sizeof(int), manager->key_count, file);
    fwrite(manager->records, sizeof(record), manager->record_count, file);
    pthread_mutex_unlock(&manager->lock);

    fclose(file);
}

// Deserialize state from a file
void deserialize_state(MemoryManager *manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for deserialization");
        return;
    }

    pthread_mutex_lock(&manager->lock);
    fread(manager->offsets, sizeof(long), manager->offset_count, file);
    fread(manager->keys, sizeof(int), manager->key_count, file);
    fread(manager->records, sizeof(record), manager->record_count, file);
    pthread_mutex_unlock(&manager->lock);

    fclose(file);
}

// Resize memory
size_t resize_memory(MemoryManager *manager, size_t new_size) {
    pthread_mutex_lock(&manager->lock);

    long *new_offsets = realloc(manager->offsets, new_size * sizeof(long));
    if (!new_offsets) {
        pthread_mutex_unlock(&manager->lock);
        return manager->offset_count;
    }

    int *new_keys = realloc(manager->keys, new_size * sizeof(int));
    if (!new_keys) {
        free(new_offsets);
        pthread_mutex_unlock(&manager->lock);
        return manager->key_count;
    }

    record *new_records = realloc(manager->records, new_size * sizeof(record));
    if (!new_records) {
        free(new_offsets);
        free(new_keys);
        pthread_mutex_unlock(&manager->lock);
        return manager->record_count;
    }

    manager->offsets = new_offsets;
    manager->keys = new_keys;
    manager->records = new_records;

    manager->offset_count = new_size;
    manager->key_count = new_size;
    manager->record_count = new_size;

    pthread_mutex_unlock(&manager->lock);

    return new_size;
}

// Example usage
int main() {
    MemoryManager *manager = initialize_memory_manager(100);
    if (!manager) {
        fprintf(stderr, "Failed to initialize memory manager\n");
        return EXIT_FAILURE;
    }

    set_random_record_values(manager, 1, KEY_RANGE, 1);

    serialize_state(manager, "state.bin");

    free_memory_manager(manager);

    MemoryManager *new_manager = initialize_memory_manager(50);
    if (!new_manager) {
        fprintf(stderr, "Failed to reinitialize memory manager\n");
        return EXIT_FAILURE;
    }

    deserialize_state(new_manager, "state.bin");

    free_memory_manager(new_manager);

    return EXIT_SUCCESS;
}
