```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>

typedef struct {
    long *offset;
    int key_index;
} Record;

void* random_int_range(int min, int max) {
    double fraction = (double)rand() / RAND_MAX;
    return (void*)(long)((fraction * ((max - min) + 1)) + min);
}

void initialize_memory(size_t num_offsets, size_t num_keys, size_t num_records,
                       long step_size, int min_value, int max_value,
                       const char* memory_footprint_threshold) {
    // Convert memory footprint threshold to bytes
    size_t max_bytes = atoll(memory_footprint_threshold);

    // Calculate required memory and check against the threshold
    size_t offset_size = num_offsets * sizeof(long);
    size_t key_size = num_keys * sizeof(int);
    size_t record_size = num_records * sizeof(Record);

    if (offset_size + key_size + record_size > max_bytes) {
        fprintf(stderr, "Memory allocation exceeds the allowed threshold.\n");
        return;
    }

    // Allocate and initialize offsets
    long *offsets = aligned_alloc(64, offset_size);
    for (size_t i = 0; i < num_offsets; ++i) {
        offsets[i] = i * step_size;
    }

    // Allocate and initialize keys
    int *keys = aligned_alloc(64, key_size);
    for (size_t i = 0; i < num_keys; ++i) {
        keys[i] = i;
    }

    // Seed the random number generator
    srand((unsigned int)time(NULL));

    // Allocate and initialize records
    Record *records = aligned_alloc(64, record_size);
    for (size_t i = 0; i < num_records; ++i) {
        if (i >= num_offsets || i >= num_keys) {
            fprintf(stderr, "Number of records exceeds the number of available offsets or keys.\n");
            free(offsets);
            free(keys);
            free(records);
            return;
        }
        records[i].offset = &offsets[i];
        records[i].key_index = i;

        // Set random integer field
        int *random_field = (int*)random_int_range(min_value, max_value);
        printf("Record %zu: Random value set to %d\n", i, *random_field);

    }

    // Synchronization and cleanup would be handled by the calling code if multi-threaded
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    initialize_memory(10, 15, 8, 5, 1, 100, "1024"); // Example usage
    return 0;
}
```

### Key Considerations:

- **Alignment**: Memory allocations are aligned to 64 bytes using `aligned_alloc` for potential performance improvements in a multi-threaded environment.

- **Random Number Generation**: Uses `srand` and `rand` seeded with the current time, ensuring reproducibility across multiple function calls while considering minimal overhead.

- **Memory Management**: All memory is manually allocated and deallocated without relying on automatic constructs like vectors. This ensures granular control over memory usage but requires careful handling to avoid leaks or corruption.

- **Error Handling**: Basic checks are in place for exceeding the allowed memory footprint threshold, although more robust error checking might be necessary depending on use case requirements.

This function can serve as a template and may need further refinement based on specific system constraints and performance characteristics.']

