    UE_INFO_HEADER header;
    CRC_INDICATION_REL8_TAG crcInfo;
    time_t timestamp;
    size_t packetLength;
    int sequenceNumber;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_STRUCTURES 10000

void initializeRandom() {
    srand((unsigned int)time(NULL));
}

NFAPI_CRC_INDICATION_PDU_T* createDynamicList(size_t count, size_t *allocatedSize) {
    if (count > MAX_STRUCTURES || count == 0) {
        fprintf(stderr, "Invalid count: %zu\n", count);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        list[i].header.RX_UE_INFORMATION_TAG = rand() % 65536;
        list[i].header.RNTI = rand() % 4294967295U;
        list[i].crcInfo.CRCFLAG = rand() & 1;
        list[i].timestamp = time(NULL);
        list[i].packetLength = rand() % 1500; // Simulating typical Ethernet MTU
        list[i].sequenceNumber = i + 1;
    }

    *allocatedSize = count * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    return list;
}

void freeDynamicList(NFAPI_CRC_INDICATION_PDU_T* list) {
    if (list) {
        free(list);
    }
}

int main() {
    size_t allocatedSize = 0;
    initializeRandom();

    NFAPI_CRC_INDICATION_PDU_T *crcIndicationList = createDynamicList(5000, &allocatedSize);

    if (crcIndicationList) {
        printf("Allocated %zu bytes for %zu structures.\n", allocatedSize, 5000);
        freeDynamicList(crcIndicationList);
    }

    return 0;
}
