['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define INITIAL_CAPACITY 10
#define MAX_EXECUTION_TIME_MS 1000

typedef struct {
    int value;
} Record;

typedef struct {
    size_t offset_size;
    size_t keys_size;
    long *offsets;
    int *keys;
    size_t records_capacity;
    size_t records_count;
    Record *records;
    pthread_mutex_t lock;
} MemoryManager;

MemoryManager* create_memory_manager(size_t offsets_needed, size_t keys_needed) {
    MemoryManager *manager = malloc(sizeof(MemoryManager));
    if (!manager) return NULL;

    manager->offset_size = offsets_needed;
    manager->keys_size = keys_needed;
    manager->records_capacity = INITIAL_CAPACITY;
    manager->records_count = 0;

    pthread_mutex_init(&manager->lock, NULL);

    // Allocate memory for offsets and keys
    manager->offsets = malloc(offsets_needed * sizeof(long));
    manager->keys = malloc(keys_needed * sizeof(int));

    if (!manager->offsets || !manager->keys) {
        free(manager->offsets);
        free(manager->keys);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
        return NULL;
    }

    // Initialize memory with zero
    memset(manager->offsets, 0, offsets_needed * sizeof(long));
    memset(manager->keys, 0, keys_needed * sizeof(int));

    // Allocate initial capacity for records
    manager->records = malloc(INITIAL_CAPACITY * sizeof(Record));
    if (!manager->records) {
        free(manager->offsets);
        free(manager->keys);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
        return NULL;
    }

    memset(manager->records, 0, INITIAL_CAPACITY * sizeof(Record));

    return manager;
}

bool resize_records(MemoryManager *manager, size_t new_capacity) {
    Record *new_records = realloc(manager->records, new_capacity * sizeof(Record));
    if (!new_records) return false;

    pthread_mutex_lock(&manager->lock);
    manager->records = new_records;
    manager->records_capacity = new_capacity;
    pthread_mutex_unlock(&manager->lock);

    memset(manager->records + manager->records_count,
           0, (new_capacity - manager->records_count) * sizeof(Record));

    return true;
}

bool initialize_random_values(MemoryManager *manager, int min_value, int max_value, bool unique) {
    if (!manager) return false;

    srand(time(NULL)); // Simple seeding; consider more robust external seeding in practice

    for (size_t i = 0; i < manager->records_count; ++i) {
        int value;
        do {
            value = min_value + rand() % (max_value - min_value + 1);
        } while (unique && contains(manager, value));

        manager->records[i].value = value;
    }

    return true;
}

bool contains(MemoryManager *manager, int value) {
    for (size_t i = 0; i < manager->records_count; ++i) {
        if (manager->records[i].value == value) {
            return true;
        }
    }
    return false;
}

void cleanup_memory_manager(MemoryManager **manager) {
    if (!manager || !*manager) return;

    MemoryManager *m = *manager;

    pthread_mutex_destroy(&m->lock);
    free(m->offsets);
    free(m->keys);
    free(m->records);

    free(*manager);
    *manager = NULL;
}

bool execute_with_timeout(void (*func)(void *), void *arg, unsigned int max_time_ms) {
    struct timespec start, end;

    if (clock_gettime(CLOCK_MONOTONIC, &start)) return false;

    func(arg);

    if (clock_gettime(CLOCK_MONOTONIC, &end)) return false;

    long elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000L + (end.tv_nsec - start.tv_nsec);
    return elapsed_ns / 1000000L <= max_time_ms;
}

void process_memory_manager(MemoryManager *manager) {
    if (!manager || manager->records_count == 0) return;

    initialize_random_values(manager, 1, 100, true);

    // Simulate serialization
    printf("Serialized state: capacity=%zu, count=%zu\n", manager->records_capacity, manager->records_count);
}

int main() {
    MemoryManager *manager = create_memory_manager(10, 20);
    if (!manager) {
        fprintf(stderr, "Failed to initialize memory manager\n");
        return EXIT_FAILURE;
    }

    if (resize_records(manager, 50)) {
        pthread_mutex_lock(&manager->lock);
        manager->records_count = 50; // Simulate filling records
        pthread_mutex_unlock(&manager->lock);

        if (!execute_with_timeout(process_memory_manager, manager, MAX_EXECUTION_TIME_MS)) {
            fprintf(stderr, "Operation exceeded time limit\n");
        }
    } else {
        fprintf(stderr, "Failed to resize records\n");
    }

    cleanup_memory_manager(&manager);
    return EXIT_SUCCESS;
}
```

This C code defines a `MemoryManager` structure and functions to manage memory for arrays and structures. It includes:

1. Memory allocation for long offsets and int keys using a simple custom pool.
2. A grow-only allocation strategy for an array of `Record` structs, with resizing logic.
3. Random value initialization with optional uniqueness using the standard library's random number generator.
4. Error checking with cleanup on failure and graceful handling of allocation errors.
5. Execution time constraint enforcement via a timer.
6. Basic serialization demonstration (printing state).
7. Thread safety ensured by mutex locks for concurrent access.

This code is intended to serve as a starting point, providing a foundation that can be expanded upon or modified to suit specific requirements and constraints in a distributed system environment.']

