    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
};

class DynamicListManager {
public:
    DynamicListManager() : max_size(10000) {}

    void addElement(const NFAPI_CRC_INDICATION_PDU_T& element) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (elements_.size() < max_size) {
            elements_.push_back(element);
        } else {
            throw std::runtime_error("List has reached maximum capacity");
        }
    }

    void updateElement(uint16_t rnti, const NFAPI_CRC_INDICATION_PDU_T& element) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& e : elements_) {
            if (e.RNTI == rnti) {
                e = element;
                return;
            }
        }
    }

    void removeElementByIndex(size_t index) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (index < elements_.size()) {
            elements_.erase(elements_.begin() + index);
        } else {
            throw std::out_of_range("Index out of range");
        }
    }

    void serialize(const std::string& filename) const {
        std::lock_guard<std::mutex> lock(mutex_);
        std::ofstream file(filename, std::ios::binary);
        if (!file.is_open()) {
            throw std::runtime_error("Failed to open file for writing");
        }
        size_t size = elements_.size();
        file.write(reinterpret_cast<const char*>(&size), sizeof(size));
        for (const auto& element : elements_) {
            file.write(reinterpret_cast<const char*>(&element), sizeof(element));
        }
    }

    void deserialize(const std::string& filename) {
        std::lock_guard<std::mutex> lock(mutex_);
        std::ifstream file(filename, std::ios::binary);
        if (!file.is_open()) {
            throw std::runtime_error("Failed to open file for reading");
        }
        size_t size;
        file.read(reinterpret_cast<char*>(&size), sizeof(size));
        elements_.clear();
        elements_.reserve(size);
        for (size_t i = 0; i < size; ++i) {
            NFAPI_CRC_INDICATION_PDU_T element;
            file.read(reinterpret_cast<char*>(&element), sizeof(element));
            elements_.push_back(element);
        }
    }

private:
    mutable std::mutex mutex_;
    std::vector<NFAPI_CRC_INDICATION_PDU_T> elements_;
    const size_t max_size;
};

void insertStringAfter(std::forward_list<std::string>& flist, const std::string& target, const std::string& to_insert) {
    auto it = flist.before_begin();
    for (auto curr = flist.begin(); curr != flist.end(); ++curr) {
        if (*curr == target) {
            flist.insert_after(curr, to_insert);
            return;
        }
        it = curr;
    }
    flist.insert_after(it, to_insert);
}

