#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <errno.h>

typedef struct {
    int value;
} Record;

#define INITIAL_OFFSET_ARRAY_SIZE 10
#define INITIAL_KEY_ARRAY_SIZE 5
#define INITIAL_RECORD_ARRAY_SIZE 20
#define MAX_RANDOM_VALUE 100

// Global variables for memory management and synchronization
long* offsets = NULL;
int* keys = NULL;
Record* records = NULL;
size_t offset_array_size = 0, key_array_size = 0, record_array_size = 0;

pthread_mutex_t lock;
unsigned long start_time;

void initialize_timer() {
    struct timespec spec;
    clock_gettime(CLOCK_REALTIME, &spec);
    start_time = spec.tv_sec * 1000000000 + spec.tv_nsec; // nanoseconds
}

uint64_t get_current_time_ns() {
    struct timespec spec;
    clock_gettime(CLOCK_REALTIME, &spec);
    return spec.tv_sec * 1000000000 + spec.tv_nsec;
}

void* memory_pool = NULL;
size_t pool_size = 1024 * 1024; // 1 MB

long allocate_from_memory_pool(size_t size) {
    if (!memory_pool || (char*)memory_pool + pool_size - (char*)offsets < size) {
        void* new_pool = realloc(memory_pool, pool_size * 2);
        if (!new_pool) return -1;
        memory_pool = new_pool;
        pool_size *= 2;
    }
    long offset = (char*)offsets - (char*)memory_pool;
    offsets = (long*)((char*)offsets + size);
    return offset;
}

void initialize_memory() {
    pthread_mutex_init(&lock, NULL);

    if ((offsets = malloc(INITIAL_OFFSET_ARRAY_SIZE * sizeof(long))) == NULL ||
        (keys = malloc(INITIAL_KEY_ARRAY_SIZE * sizeof(int))) == NULL ||
        (records = calloc(INITIAL_RECORD_ARRAY_SIZE, sizeof(Record))) == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < INITIAL_OFFSET_ARRAY_SIZE; ++i)
        offsets[i] = allocate_from_memory_pool(sizeof(long));
    for (size_t i = 0; i < INITIAL_KEY_ARRAY_SIZE; ++i)
        keys[i] = rand() % MAX_RANDOM_VALUE;

    unsigned int seed = time(NULL);
    srand(seed);
}

void initialize_records(size_t size) {
    if (records == NULL || record_array_size != size) {
        Record* new_records = realloc(records, size * sizeof(Record));
        if (!new_records) {
            fprintf(stderr, "Memory reallocation failed\n");
            cleanup();
            exit(EXIT_FAILURE);
        }
        records = new_records;
        memset(records + record_array_size, 0, (size - record_array_size) * sizeof(Record));
        record_array_size = size;
    }

    for (size_t i = 0; i < record_array_size; ++i)
        records[i].value = rand() % MAX_RANDOM_VALUE;
}

void cleanup() {
    pthread_mutex_destroy(&lock);
    free(offsets);
    free(keys);
    free(records);
    free(memory_pool);
}

int main(int argc, char** argv) {
    initialize_timer();
    initialize_memory();

    size_t record_count = INITIAL_RECORD_ARRAY_SIZE;

    while (get_current_time_ns() - start_time < 5 * 1000000000) { // 5 seconds limit
        pthread_mutex_lock(&lock);
        if (record_count > record_array_size) {
            initialize_records(record_count);
        }
        for (size_t i = 0; i < record_array_size; ++i)
            records[i].value = rand() % MAX_RANDOM_VALUE;
        pthread_mutex_unlock(&lock);

        // Sleep or do other work
    }

    cleanup();
    return 0;
}
```

