#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_USER_IDENTIFIER_LENGTH 100
#define USER_IDENTIFIER_REGEX "^[A-Za-z0-9]+(-[A-Za-z0-9]+)*$"
#define ERROR_CODE -1

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    char *userIdentifier;
    int value;
} record_t;

typedef struct {
    CRC_INDICATION_REL8_TAG crcTag;
    int rnti;
    unsigned long rxUeInformationTag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
} Logger;

void initLogger(Logger *logger, const char *filePath);
void logError(Logger *logger, const char *message);
void logWarning(Logger *logger, const char *message);

int validateUserIdentifier(const char *identifier) {
    if (strlen(identifier) > MAX_USER_IDENTIFIER_LENGTH) return 0;
    return regexp_match(USER_IDENTIFIER_REGEX, identifier);
}

long getLargestInteger(long *array, size_t size) {
    long largest = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > largest) largest = array[i];
    }
    return largest;
}

int compareNFAPIDeclarations(const void *a, const void *b) {
    NFAPI_CRC_INDICATION_PDU_T *pduA = (NFAPI_CRC_INDICATION_PDU_T *)a;
    NFAPI_CRC_INDICATION_PDU_T *pduB = (NFAPI_CRC_INDICATION_PDU_T *)b;
    return pduA->rnti - pduB->rnti; // Modify based on actual sorting criteria
}

int compareRecords(const void *a, const void *b) {
    record_t *recordA = (record_t *)a;
    record_t *recordB = (record_t *)b;
    return recordA->value - recordB->value; // Modify based on actual sorting criteria
}

void freeResources(NFAPI_CRC_INDICATION_PDU_T **pfcp_pdus, long *offsets, int *keys, record_t *records, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        if (pfcp_pdus[i]) free(pfcp_pdus[i]);
        if (records[i].userIdentifier) free(records[i].userIdentifier);
    }
    free(pfcp_pdus);
    free(offsets);
    free(keys);
    free(records);
}

int populateAndSortNFACRCRecords(NFAPI_CRC_INDICATION_PDU_T ***pfcp_pdus, long **offsets, int **keys,
                                 record_t **records, size_t *n, Logger *logger) {
    if (pthread_mutex_lock(&logger->mutex)) return ERROR_CODE;

    srand((unsigned)time(NULL));

    // Memory allocation
    *pfcp_pdus = calloc(*n, sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!*pfcp_pdus) {
        logError(logger, "Memory allocation failed for pfcp_pdus");
        pthread_mutex_unlock(&logger->mutex);
        return ERROR_CODE;
    }

    *offsets = malloc(*n * sizeof(long));
    if (!*offsets) {
        logError(logger, "Memory allocation failed for offsets");
        freeResources(*pfcp_pdus, NULL, NULL, NULL, *n);
        pthread_mutex_unlock(&logger->mutex);
        return ERROR_CODE;
    }

    *keys = malloc(*n * sizeof(int));
    if (!*keys) {
        logError(logger, "Memory allocation failed for keys");
        freeResources(*pfcp_pdus, *offsets, NULL, NULL, *n);
        pthread_mutex_unlock(&logger->mutex);
        return ERROR_CODE;
    }

    *records = malloc(*n * sizeof(record_t));
    if (!*records) {
        logError(logger, "Memory allocation failed for records");
        freeResources(*pfcp_pdus, *offsets, *keys, NULL, *n);
        pthread_mutex_unlock(&logger->mutex);
        return ERROR_CODE;
    }

    // Population
    for (size_t i = 0; i < *n; ++i) {
        (*pfcp_pdus)[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!(*pfcp_pdus)[i]) {
            logError(logger, "Memory allocation failed for a single PDU");
            freeResources(*pfcp_pdus, *offsets, *keys, *records, i);
            pthread_mutex_unlock(&logger->mutex);
            return ERROR_CODE;
        }

        (*pfcp_pdus)[i]->crcTag.CRCFLAG = rand() % 2; // Set randomly
        (*pfcp_pdus)[i]->rnti = rand(); // Assign random RNTI
        (*pfcp_pdus)[i]->rxUeInformationTag = rand();

        (*offsets)[i] = rand(); // Random offset value

        (*keys)[i] = rand() % 100; // Random key in a specified range

        char identifier[MAX_USER_IDENTIFIER_LENGTH];
        snprintf(identifier, sizeof(identifier), "User-%zu", i + 1);

        if (!validateUserIdentifier(identifier)) {
            logWarning(logger, "Invalid user identifier format");
            continue;
        }

        (*records)[i].userIdentifier = strdup(identifier);
        if (!(*records)[i].userIdentifier) {
            logError(logger, "Memory allocation failed for a single record's user identifier");
            freeResources(*pfcp_pdus, *offsets, *keys, *records, i);
            pthread_mutex_unlock(&logger->mutex);
            return ERROR_CODE;
        }

        (*records)[i].value = rand() % 1000; // Random value within range
    }

    // Sorting
    qsort(*pfcp_pdus, *n, sizeof(NFAPI_CRC_INDICATION_PDU_T *), compareNFAPIDeclarations);
    qsort(*records, *n, sizeof(record_t), compareRecords);

    pthread_mutex_unlock(&logger->mutex);
    return 0;
}
