// Initialize memory pool
MemoryPool* init_memory_pool(size_t block_size, int max_blocks) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->max_blocks = max_blocks;
    pool->free_list = NULL;
    pthread_mutex_init(&pool->lock, NULL);

    // Pre-allocate memory blocks
    for (int i = 0; i < max_blocks; ++i) {
        MemNode* node = malloc(sizeof(MemNode));
        if (!node) {
            while (--i >= 0) free(pool->free_list);
            free(pool);
            return NULL;
        }
        node->memory = malloc(block_size);
        if (!node->memory) {
            while (--i >= 0) free(pool->free_list);
            free(node);
            free(pool);
            return NULL;
        }
        node->size = block_size;
        node->next = pool->free_list;
        pool->free_list = node;
    }

    return pool;
}

// Allocate from memory pool
void* pool_alloc(MemoryPool* pool, size_t size) {
    if (size > pool->block_size) return NULL;

    pthread_mutex_lock(&pool->lock);
    if (!pool->free_list) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    MemNode* node = pool->free_list;
    pool->free_list = node->next;
    pthread_mutex_unlock(&pool->lock);

    return node->memory;
}

// Free memory back to the pool
void pool_free(MemoryPool* pool, void* ptr) {
    if (!ptr) return;

    MemNode* node = malloc(sizeof(MemNode));
    if (!node) return;

    node->memory = ptr;
    pthread_mutex_lock(&pool->lock);
    node->next = pool->free_list;
    pool->free_list = node;
    pthread_mutex_unlock(&pool->lock);
}

