<?php
session_start();

function authenticateUser($clientId, $clientSecret, $authUrl, $userInfoUrl) {
    // Step 1: Get access token using OAuth 2.0
    $ch = curl_init();
    curl_setopt($ch, CURLOPT_URL, $authUrl);
    curl_setopt($ch, CURLOPT_POST, true);
    curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query([
        'client_id' => $clientId,
        'client_secret' => $clientSecret,
        'grant_type' => 'client_credentials'
    ]));
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);

    $response = curl_exec($ch);
    if (curl_errno($ch)) {
        error_log('OAuth 2.0 request failed: ' . curl_error($ch));
        return false;
    }

    $data = json_decode($response, true);
    curl_close($ch);

    if (!isset($data['access_token'])) {
        error_log('Failed to retrieve access token');
        return false;
    }

    // Step 2: Store the access token in session
    $_SESSION['access_token'] = $data['access_token'];

    // Step 3: Retrieve user information using the access token
    $ch = curl_init();
    curl_setopt($ch, CURLOPT_URL, $userInfoUrl);
    curl_setopt($ch, CURLOPT_HTTPHEADER, [
        'Authorization: Bearer ' . $_SESSION['access_token']
    ]);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);

    $response = curl_exec($ch);
    if (curl_errno($ch)) {
        error_log('User info request failed: ' . curl_error($ch));
        return false;
    }

    $userInfo = json_decode($response, true);
    curl_close($ch);

    if (!$userInfo) {
        error_log('Failed to retrieve user information');
        return false;
    }

    // Step 4: Initialize and manage records using C extension
    $nfaApiInstance = new NFAPI();
    $recordId = uniqid(); // Unique ID for each record

    $nfaApiInstance->insertRecord($recordId, $userInfo['user_id'], rand(0, 1));

    return true;
}

class NFAPI {
    public function __construct() {
        if (!extension_loaded('nfapi')) {
            die("The nfapi extension is not loaded.");
        }
    }

    public function insertRecord($id, $rx_ue_info_tag, $crcflag) {
        // Call the C extension to insert a record
        nfapi_insert_record($id, $rx_ue_info_tag, $crcflag);
    }
}
