typedef struct {
    int seconds;
    int microseconds;
} timestamp;

typedef struct resource_monitoring {
    double metric_value;
    char status_indicator;
    timestamp time_log;
    struct resource_monitoring *next; // For linked list implementation
} resource_monitoring;

// Thread-safe insertion function
void insert_record(resource_monitoring **head, resource_monitoring *new_node) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    if (*head == NULL || (*head)->time_log.seconds > new_node->time_log.seconds ||
        ((*head)->time_log.seconds == new_node->time_log.seconds &&
         (*head)->time_log.microseconds >= new_node->time_log.microseconds)) {

        new_node->next = *head;
        *head = new_node;
    } else {
        resource_monitoring *current = *head;
        while (current->next != NULL && 
               (current->next->time_log.seconds < new_node->time_log.seconds ||
                (current->next->time_log.seconds == new_node->time_log.seconds &&
                 current->next->time_log.microseconds < new_node->time_log.microseconds))) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    pthread_mutex_destroy(&lock);
}

// Function to create a new record
resource_monitoring* create_record(double metric_value, char status_indicator, int seconds, int microseconds) {
    resource_monitoring *new_node = (resource_monitoring*)malloc(sizeof(resource_monitoring));
    if (!new_node) return NULL;

    new_node->metric_value = metric_value;
    new_node->status_indicator = status_indicator;
    new_node->time_log.seconds = seconds;
    new_node->time_log.microseconds = microseconds;
    new_node->next = NULL;

    return new_node;
}

// Query records within a time range
void query_records(resource_monitoring *head, int start_seconds, int end_seconds) {
    resource_monitoring *current = head;
    while (current != NULL) {
        if ((current->time_log.seconds >= start_seconds && current->time_log.seconds <= end_seconds)) {
            printf("Metric: %.2f, Status: %c, Time: %d.%06d\n",
                   current->metric_value,
                   current->status_indicator,
                   current->time_log.seconds,
                   current->time_log.microseconds);
        }
        current = current->next;
    }
}

// Function to free all allocated memory
void free_records(resource_monitoring *head) {
    resource_monitoring *temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    resource_monitoring *head = NULL;

    // Example usage
    insert_record(&head, create_record(10.5, 'A', 100, 500000));
    insert_record(&head, create_record(12.3, 'B', 101, 200000));
    insert_record(&head, create_record(11.0, 'C', 99, 999999));

    printf("Records between 99 and 102 seconds:\n");
    query_records(head, 99, 102);

    free_records(head);
    return 0;
}
