using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
import Newtonsoft.Json;
using System.Net.Http;
using System.Threading.Tasks;

public class ServerEndpointProcessor
{
    private readonly string _configFilePath;
    private const string EndpointConfigKey = "endpoints";

    public ServerEndpointProcessor(string configFilePath)
    {
        _configFilePath = configFilePath ?? throw new ArgumentNullException(nameof(configFilePath));
    }

    // Process configuration to extract and validate server endpoints
    public async Task<List<ServerEndpoint>> GetValidEndpointsAsync()
    {
        try
        {
            var configFileContent = await File.ReadAllTextAsync(_configFilePath);
            dynamic configJson = JsonConvert.DeserializeObject(configFileContent);

            if (configJson == null || !(configJson[EndpointConfigKey] is JArray endpoints))
                return new List<ServerEndpoint>();

            var serverEndpoints = endpoints.Select(ep =>
            {
                try
                {
                    var address = ep["address"]?.ToString();
                    if (string.IsNullOrWhiteSpace(address)) throw new Exception("Invalid endpoint address");

                    var latency = await MeasureLatencyAsync(address);

                    return new ServerEndpoint { Address = address, Latency = latency };
                }
                catch (Exception)
                {
                    // Ignore invalid endpoints
                    return null;
                }
            })
            .Where(ep => ep != null && ep.Latency < double.MaxValue) // Filter out failed measurements
            .OrderBy(ep => ep.Latency) // Prioritize by lower latency
            .ToList();

            return serverEndpoints;
        }
        catch (Exception)
        {
            // Handle or log exceptions as needed, but return empty list on failure.
            return new List<ServerEndpoint>();
        }
    }

    // Measure network latency to a server endpoint
    private async Task<double> MeasureLatencyAsync(string address)
    {
        try
        {
            using (var client = new HttpClient())
            {
                var stopwatch = Stopwatch.StartNew();

                var response = await client.GetAsync(address);
                stopwatch.Stop();

                if (!response.IsSuccessStatusCode)
                    return double.MaxValue; // Consider non-success responses as high latency

                return stopwatch.Elapsed.TotalMilliseconds;
            }
        }
        catch
        {
            return double.MaxValue; // High latency for failed attempts
        }
    }

    // Update environment variables based on configuration settings
    public void UpdateEnvironmentVariables()
    {
        try
        {
            var configFileContent = File.ReadAllText(_configFilePath);
            dynamic configJson = JsonConvert.DeserializeObject(configFileContent);

            if (configJson == null)
                return;

            foreach (var setting in configJson.settings)
            {
                string key = setting["key"]?.ToString();
                string value = setting["value"]?.ToString();

                if (!string.IsNullOrWhiteSpace(key) && !string.IsNullOrWhiteSpace(value))
                    Environment.SetEnvironmentVariable(key, value);
            }
        }
        catch
        {
            // Handle or log exceptions as needed, ensure idempotency by ignoring failures.
        }
    }

    public class ServerEndpoint
    {
        public string Address { get; set; }
        public double Latency { get; set; }
    }
