#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    int value;
    char *string;
} record;

typedef struct {
    record **data;
    size_t count;
    pthread_mutex_t lock;
    FILE *log_file;
} dataset;

// Error codes
#define SUCCESS 0
#define ALLOC_FAIL -1
#define INIT_FAIL -2

// Logging function
void log_message(dataset *ds, const char *message) {
    pthread_mutex_lock(&ds->lock);
    fprintf(ds->log_file, "%s\n", message);
    fflush(ds->log_file);
    pthread_mutex_unlock(&ds->lock);
}

// Callback for user-defined actions during initialization
typedef void (*init_callback)(record *);

// Function to initialize dataset
int init_dataset(dataset *ds, size_t count, int value_range_min, int value_range_max, init_callback cb) {
    if (count == 0 || ds->log_file == NULL) return INIT_FAIL;

    pthread_mutex_init(&ds->lock, NULL);
    ds->data = malloc(count * sizeof(record *));
    if (!ds->data) {
        log_message(ds, "Memory allocation for records failed");
        return ALLOC_FAIL;
    }

    srand(time(NULL));

    for (size_t i = 0; i < count; ++i) {
        record *rec = calloc(1, sizeof(record));
        if (!rec) {
            log_message(ds, "Memory allocation for individual record failed");
            free(ds->data);
            return ALLOC_FAIL;
        }

        rec->offset = rand();
        rec->key = rand() % 100; // Assuming keys are between 0 and 99
        rec->value = value_range_min + (rand() % (value_range_max - value_range_min + 1));

        const char *example_string = "Example String";
        size_t string_len = strlen(example_string) + 1;
        rec->string = malloc(string_len);
        if (!rec->string) {
            log_message(ds, "Memory allocation for record string failed");
            free(rec);
            continue; // Skip this record
        }
        memcpy(rec->string, example_string, string_len);

        pthread_mutex_lock(&ds->lock);
        ds->data[i] = rec;
        pthread_mutex_unlock(&ds->lock);

        if (cb) cb(rec);  // User-defined callback

        log_message(ds, "Record initialized successfully");
    }

    ds->count = count;

    return SUCCESS;
}

// Function to sort records based on key
void sort_records(dataset *ds) {
    pthread_mutex_lock(&ds->lock);

    for (size_t i = 0; i < ds->count - 1; ++i) {
        size_t min_idx = i;
        for (size_t j = i + 1; j < ds->count; ++j) {
            if (ds->data[j]->key < ds->data[min_idx]->key) {
                min_idx = j;
            }
        }

        record *temp = ds->data[i];
        ds->data[i] = ds->data[min_idx];
        ds->data[min_idx] = temp;
    }

    pthread_mutex_unlock(&ds->lock);
}

// Function to free dataset memory
void free_dataset(dataset *ds) {
    if (!ds || !ds->data) return;

    for (size_t i = 0; i < ds->count; ++i) {
        if (ds->data[i]) {
            free(ds->data[i]->string);
            free(ds->data[i]);
        }
    }

    free(ds->data);
    pthread_mutex_destroy(&ds->lock);
}

// Main function to demonstrate usage
int main() {
    dataset ds;
    FILE *log = fopen("dataset.log", "w");
    if (!log) return EXIT_FAILURE;

    ds.log_file = log;

    int result = init_dataset(&ds, 1000, 1, 100, NULL);
    if (result != SUCCESS) {
        printf("Failed to initialize dataset\n");
        fclose(log);
        return EXIT_FAILURE;
    }

    sort_records(&ds);

    // Do something with the sorted records...

    free_dataset(&ds);
    fclose(log);

    return EXIT_SUCCESS;
}
