    char url[2048];
    Header* headers;
    char body[4096];
    time_t timestamp;
    struct HttpRequest* next;
} HttpRequest;

// Node structure for the linked list to manage requests in a thread-safe manner.
typedef struct RequestNode {
    HttpRequest* request;
    struct RequestNode* next;
} RequestNode;

// Linked list head and lock for thread-safety.
RequestNode* list_head = NULL;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

// Helper function prototypes
int is_duplicate(HttpRequest* req);
void add_request_to_list(HttpRequest* req);
HttpRequest* get_most_recent_request();
void sort_requests_by_timestamp();
void log_message(const char* message, int verbosity);

// Main function to process and filter HTTP requests.
void processAndFilterHTTPRequests() {
    char input[4096];
    HttpRequest* current_req = NULL;

    while (fgets(input, sizeof(input), stdin)) {
        if (!current_req) {
            current_req = malloc(sizeof(HttpRequest));
            if (!current_req) break; // Memory allocation failed.
        }

        sscanf(input, "%s %s", current_req->url, input + strlen(current_req->url) + 1);
        time(&current_req->timestamp); // For simplicity, use current system time.

        // Parse headers (assuming a simple format for demonstration).
        Header* header = malloc(sizeof(Header));
        if (!header) {
            free(current_req);
            break; // Memory allocation failed.
        }
        sscanf(input + strlen(current_req->url) + 1, "%255[^:]: %1023[^\n]", header->key, header->value);
        header->next = current_req->headers;
        current_req->headers = header;

        pthread_mutex_lock(&list_lock);
        if (!is_duplicate(current_req)) {
            add_request_to_list(current_req);
        }
        pthread_mutex_unlock(&list_lock);

        log_message("Processed a new request.", 1); // Example of logging.
    }

    sort_requests_by_timestamp();

    HttpRequest* most_recent = get_most_recent_request();
    if (most_recent) {
        printf("Most recent request URL: %s\n", most_recent->url);
    }

    // Clean up resources.
    while (list_head != NULL) {
        RequestNode* temp_node = list_head;
        list_head = list_head->next;

        HttpRequest* req = temp_node->request;
        Header* header = req->headers;
        while (header) {
            Header* to_free = header;
            header = header->next;
            free(to_free);
        }

        free(req);
        free(temp_node);
    }

    pthread_mutex_unlock(&list_lock); // Though not necessary here as it's called after destruction.
}

int is_duplicate(HttpRequest* req) {
    RequestNode* node = list_head;
    while (node != NULL) {
        HttpRequest* existing_req = node->request;
        if (strcmp(existing_req->url, req->url) == 0 &&
            strcmp(existing_req->headers->key, req->headers->key) == 0 &&
            strcmp(existing_req->headers->value, req->headers->value) == 0) {
            return 1; // Duplicate found.
        }
        node = node->next;
    }
    return 0; // No duplicate.
}

void add_request_to_list(HttpRequest* req) {
    RequestNode* new_node = malloc(sizeof(RequestNode));
    if (!new_node) return;

    new_node->request = req;
    new_node->next = list_head;
    list_head = new_node;
}

HttpRequest* get_most_recent_request() {
    HttpRequest* most_recent = NULL;
    RequestNode* node = list_head;
    time_t latest_timestamp = 0;

    while (node != NULL) {
        if (node->request->timestamp > latest_timestamp) {
            latest_timestamp = node->request->timestamp;
            most_recent = node->request;
        }
        node = node->next;
    }

    return most_recent;
}

