    } crc_info;
} NFAPI_CRC_INDICATION_PDU_T;

// Thread-safe list management using mutex
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t count;
    pthread_mutex_t lock;
} ListManager;

// Validate CRC tag integrity (example implementation)
int validate_crc_tag(const unsigned char* crc_tag) {
    // Example validation logic: ensure all bytes are non-zero
    for(int i = 0; i < 4; ++i) {
        if(crc_tag[i] == 0) return 0;
    }
    return 1;
}

// Initialize list manager
void init_list_manager(ListManager *manager) {
    manager->elements = (NFAPI_CRC_INDICATION_PDU_T *)calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

// Add element to list
int add_element(ListManager *manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (manager->count >= MAX_ELEMENTS) return -1;

    pthread_mutex_lock(&manager->lock);

    if (!validate_crc_tag(pdu.crc_info.CRC_INDICATION_REL8_TAG)) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // CRC tag invalid
    }

    manager->elements[manager->count++] = pdu;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Serialize list to binary file
int serialize_list(ListManager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    size_t written_bytes = fwrite(manager->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T), manager->count, file);

    fclose(file);

    return (written_bytes == manager->count) ? 0 : -2;
}

// Deserialize list from binary file
int deserialize_list(ListManager *manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t read_elements = fread(manager->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T), MAX_ELEMENTS, file);

    manager->count = (read_elements == 0 && ferror(file)) ? 0 : read_elements;

    fclose(file);

    return 0;
}

// Clean up list manager
void cleanup_list_manager(ListManager *manager) {
    free(manager->elements);
    pthread_mutex_destroy(&manager->lock);
}

int main() {
    ListManager manager;
    init_list_manager(&manager);

    // Example usage: adding and serializing elements
    NFAPI_CRC_INDICATION_PDU_T example_pdu = {1, 12345, {{0x01, 0x02, 0x03, 0x04}, 1}};

    if (add_element(&manager, example_pdu) == 0) {
        serialize_list(&manager, "data.bin");
    }

    deserialize_list(&manager, "data.bin");

    cleanup_list_manager(&manager);
    return 0;
}
