int manageMemoryAndSortRecords(int recordCount, int rangeMin, int rangeMax);
void insertNode(Node **head, const char *data);
void printList(Node *head);
void freeList(Node *head);

// Thread-safe memory management with mutex lock
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int manageMemoryAndSortRecords(int recordCount, int rangeMin, int rangeMax) {
    pthread_mutex_lock(&lock);

    // Allocate memory for KeyValue array and check for allocation failure
    KeyValue *keyValues = (KeyValue *)malloc(recordCount * sizeof(KeyValue));
    if (!keyValues) {
        pthread_mutex_unlock(&lock);
        return ERROR_ALLOC;
    }

    // Populate KeyValue with random keys and offsets
    srand(time(NULL));
    for (int i = 0; i < recordCount; ++i) {
        keyValues[i].key = rand() % (rangeMax - rangeMin + 1) + rangeMin;
        keyValues[i].offset = rand();
    }

    // Sort KeyValue array by keys
    qsort(keyValues, recordCount, sizeof(KeyValue), 
          [](const void *a, const void *b) {
              return ((KeyValue *)a)->key - ((KeyValue *)b)->key;
          });

    // Allocate memory for Record array and check allocation failure
    Record *records = (Record *)malloc(recordCount * sizeof(Record));
    if (!records) {
        free(keyValues);
        pthread_mutex_unlock(&lock);
        return ERROR_ALLOC;
    }

    // Populate Record with random values within specified range
    for (int i = 0; i < recordCount; ++i) {
        records[i].value = rand() % (rangeMax - rangeMin + 1) + rangeMin;
    }

    // Free allocated memory for keyValues after use
    free(keyValues);

    pthread_mutex_unlock(&lock);
    return SUCCESS;
}

void insertNode(Node **head, const char *data) {
    Node *newNode = (Node *)malloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate memory for new node");
        exit(ERROR_ALLOC);
    }

    newNode->data = strdup(data);
    if (!newNode->data) {
        free(newNode);
        perror("Failed to duplicate string data");
        exit(ERROR_ALLOC);
    }

    newNode->next = *head;
    *head = newNode;
}

void printList(Node *head) {
    while (head != NULL) {
        printf("%s\n", head->data);
        head = head->next;
    }
}

void freeList(Node *head) {
    Node *tmp;
    while (head != NULL) {
        tmp = head;
        head = head->next;
        free(tmp->data);
        free(tmp);
    }
}

// Example usage
int main() {
    int status = manageMemoryAndSortRecords(1000, 1, 100);

    if (status == SUCCESS) {
        printf("Memory management and sorting completed successfully.\n");
    } else {
        fprintf(stderr, "Error managing memory or sorting records.\n");
    }

    Node *head = NULL;
    insertNode(&head, "First node data");
    insertNode(&head, "Second node data");
    printList(head);
    freeList(head);

    return 0;
}
```

