class ResourceLoader {
public:
    enum StatusCode { SUCCESS, FILE_NOT_FOUND, MEMORY_ALLOCATION_ERROR, API_FAILURE };

    struct ItemDetails {
        long offset;
        int key;
        Record record;
    };

private:
    std::vector<ItemDetails> items_;
    std::map<int, std::string> metadataCache_;

public:
    ResourceLoader() = default;

    StatusCode initializeResourceBundle(const std::string& filepath) {
        Logging::log(Logging::INFO, "Initializing resource bundle from file: " + filepath);

        // Load the resource file
        std::ifstream file(filepath);
        if (!file.is_open()) {
            Logging::log(Logging::ERROR, "Failed to open file: " + filepath);
            return StatusCode::FILE_NOT_FOUND;
        }

        // Read items from the file into memory
        ItemDetails item;
        while (file.read(reinterpret_cast<char*>(&item.offset), sizeof(item.offset))
               && file.read(reinterpret_cast<char*>(&item.key), sizeof(item.key))) {

            try {
                fetchRecordData(item);
                items_.push_back(item);
            } catch (const std::bad_alloc&) {
                Logging::log(Logging::ERROR, "Memory allocation failed for record key: " + std::to_string(item.key));
                return StatusCode::MEMORY_ALLOCATION_ERROR;
            }
        }

        file.close();

        // Log final metrics
        Logging::log(Logging::INFO, "Successfully initialized resource bundle with " + std::to_string(items_.size()) + " items.");

        return StatusCode::SUCCESS;
    }

private:
    void fetchRecordData(ItemDetails& item) {
        static std::random_device rd;
        static std::mt19937 gen(rd());
        static std::uniform_int_distribution<> dis(1, 100); // Random range for example

        std::string metadata;
        if (ExternalAPI::fetchMetadata(item.key, metadata)) {
            metadataCache_[item.key] = metadata;

            item.record.value = dis(gen);
            Logging::log(Logging::INFO, "Fetched and cached metadata for key: " + std::to_string(item.key));
        } else {
            Logging::log(Logging::ERROR, "Failed to fetch metadata for key: " + std::to_string(item.key));
            throw std::runtime_error("API failure");
        }
    }
};

int main() {
    ResourceLoader loader;
    auto status = loader.initializeResourceBundle("resource_data.bin");

    if (status == ResourceLoader::SUCCESS) {
        Logging::log(Logging::INFO, "Resource bundle loaded successfully.");
    } else {
        Logging::log(Logging::ERROR, "Failed to load resource bundle. Status code: " + std::to_string(status));
    }

    return 0;
}
