// Define the Record structure
typedef struct Record {
    int key;
    long offset;
    struct Record *prev;
    struct Record *next;
} Record;

// Define the HashTableEntry and HashTable structures
#define INITIAL_SIZE 101

typedef struct HashTableEntry {
    int key;
    Record *record;
    struct HashTableEntry *next;
} HashTableEntry;

typedef struct HashTable {
    size_t size;
    HashTableEntry **table;
    pthread_mutex_t lock;
} HashTable;

// Function prototypes
void initHashTable(HashTable *ht, size_t size);
unsigned int hashFunction(int key, size_t size);
void insertRecord(HashTable *ht, Record *record);
Record* findRecordByKey(HashTable *ht, int key);
void resizeHashTableIfNeeded(HashTable *ht);
int generateRandomIntInRange(int min, int max);

// Initialize the HashTable
void initHashTable(HashTable *ht, size_t size) {
    ht->size = size;
    ht->table = malloc(sizeof(HashTableEntry*) * size);
    memset(ht->table, 0, sizeof(HashTableEntry*) * size);
    pthread_mutex_init(&ht->lock, NULL);
}

// Hash function
unsigned int hashFunction(int key, size_t size) {
    return (unsigned int)(key % size);
}

// Insert a record into the HashTable
void insertRecord(HashTable *ht, Record *record) {
    unsigned int index = hashFunction(record->key, ht->size);

    pthread_mutex_lock(&ht->lock);

    // Check for duplicate keys
    HashTableEntry *entry = ht->table[index];
    while (entry != NULL) {
        if (entry->key == record->key) {
            fprintf(stderr, "Duplicate key detected: %d\n", record->key);
            pthread_mutex_unlock(&ht->lock);
            return;
        }
        entry = entry->next;
    }

    // Create a new hash table entry
    HashTableEntry *newEntry = malloc(sizeof(HashTableEntry));
    if (!newEntry) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&ht->lock);
        return;
    }
    newEntry->key = record->key;
    newEntry->record = record;
    newEntry->next = ht->table[index];
    ht->table[index] = newEntry;

    // Resize the hash table if needed
    resizeHashTableIfNeeded(ht);

    pthread_mutex_unlock(&ht->lock);
}

// Find a record by key in the HashTable
Record* findRecordByKey(HashTable *ht, int key) {
    unsigned int index = hashFunction(key, ht->size);

    pthread_mutex_lock(&ht->lock);
    HashTableEntry *entry = ht->table[index];
    while (entry != NULL) {
        if (entry->key == key) {
            Record *record = entry->record;
            pthread_mutex_unlock(&ht->lock);
            return record;
        }
        entry = entry->next;
    }
    pthread_mutex_unlock(&ht->lock);

    return NULL;
}

// Resize the HashTable if needed
void resizeHashTableIfNeeded(HashTable *ht) {
    size_t loadFactorThreshold = 0.75;
    size_t numElements = 0;

    for (size_t i = 0; i < ht->size; ++i) {
        HashTableEntry *entry = ht->table[i];
        while (entry != NULL) {
            ++numElements;
            entry = entry->next;
        }
    }

    float loadFactor = (float)numElements / ht->size;

    if (loadFactor > loadFactorThreshold) {
        size_t newSize = ht->size * 2;
        HashTable newHT;
        initHashTable(&newHT, newSize);

        for (size_t i = 0; i < ht->size; ++i) {
            HashTableEntry *entry = ht->table[i];
            while (entry != NULL) {
                insertRecord(&newHT, entry->record);
                HashTableEntry *temp = entry;
                entry = entry->next;
                free(temp);
            }
        }

        pthread_mutex_lock(&ht->lock);
        free(ht->table);
        ht->size = newSize;
        ht->table = newHT.table;
        pthread_mutex_unlock(&ht->lock);

        pthread_mutex_destroy(&newHT.lock);
        free(newHT.table);
    }
}

// Generate a random integer within a specified range
int generateRandomIntInRange(int min, int max) {
    if (min > max) {
        fprintf(stderr, "Invalid range: %d to %d\n", min, max);
        return 0;
    }
    srand(time(NULL));
    return rand() % (max - min + 1) + min;
}

// Initialize the collection of records
void initializeRecordCollection(HashTable *ht, int numRecords, int keyRangeMin, int keyRangeMax) {
    for (int i = 0; i < numRecords; ++i) {
        Record *record = malloc(sizeof(Record));
        if (!record) {
            fprintf(stderr, "Memory allocation failed\n");
            continue;
        }
        record->key = generateRandomIntInRange(keyRangeMin, keyRangeMax);
        record->offset = (long)i * 100; // Example offset
        record->prev = NULL;
        record->next = NULL;

        insertRecord(ht, record);
    }
}

int main() {
    HashTable ht;
    initHashTable(&ht, INITIAL_SIZE);

    int numRecords = 10;
    int keyRangeMin = 1;
    int keyRangeMax = 100;

    initializeRecordCollection(&ht, numRecords, keyRangeMin, keyRangeMax);

    // Example of finding a record
    int searchKey = 50;
    Record *record = findRecordByKey(&ht, searchKey);
    if (record) {
        printf("Found record with key %d at offset %ld\n", record->key, record->offset);
    } else {
        printf("Record not found for key %d\n", searchKey);
    }

    // Cleanup
    pthread_mutex_destroy(&ht.lock);
    free(ht.table);

    return 0;
}
