#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
    double value;
    char *str;
} Record;

typedef struct {
    Record **records;
    size_t count;
    pthread_mutex_t lock;
} RecordCollection;

#define MAX_STRING_LENGTH 256
#define CSV_HEADER "Key,Offset,Value,String\n"

int initialize_collection(RecordCollection *collection, size_t num_records, int key_min, int key_max) {
    if (!collection || num_records == 0) return -1;

    collection->records = malloc(num_records * sizeof(Record *));
    if (collection->records == NULL) return -2;

    collection->count = num_records;
    pthread_mutex_init(&collection->lock, NULL);

    srand(time(NULL));
    int keys[num_records];
    for (size_t i = 0; i < num_records; ++i) {
        do {
            keys[i] = rand() % (key_max - key_min + 1) + key_min;
        } while (i > 0 && keys[i] == keys[i - 1]);
    }

    for (size_t i = 0; i < num_records; ++i) {
        collection->records[i] = malloc(sizeof(Record));
        if (!collection->records[i]) return -3;

        collection->records[i]->key = keys[i];
        collection->records[i]->offset = i;
        collection->records[i]->value = (double)rand() / RAND_MAX;

        collection->records[i]->str = malloc(MAX_STRING_LENGTH);
        if (!collection->records[i]->str) return -4;

        snprintf(collection->records[i]->str, MAX_STRING_LENGTH, "String%d", (int)i + 1);
    }

    qsort(collection->records, num_records, sizeof(Record *), compare_keys);

    return 0;
}

void destroy_collection(RecordCollection *collection) {
    if (!collection) return;

    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i]->str);
        free(collection->records[i]);
    }
    free(collection->records);
    pthread_mutex_unlock(&collection->lock);

    pthread_mutex_destroy(&collection->lock);
}

int export_to_csv(const RecordCollection *collection, const char *filename) {
    if (!collection || !filename) return -1;

    FILE *file = fopen(filename, "w");
    if (!file) return -2;

    fprintf(file, CSV_HEADER);

    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        fprintf(file, "%d,%ld,%.6f,\"%s\"\n", 
                collection->records[i]->key, 
                collection->records[i]->offset,
                collection->records[i]->value,
                collection->records[i]->str);
    }
    pthread_mutex_unlock(&collection->lock);

    fclose(file);

    return 0;
}

int compare_keys(const void *a, const void *b) {
    Record **recordA = (Record **)a;
    Record **recordB = (Record **)b;

    if ((*recordA)->key < (*recordB)->key) return -1;
    if ((*recordA)->key > (*recordB)->key) return 1;
    return 0;
}
