// Define the record structure
typedef struct {
    int value;
} record;

// Function prototypes
long* allocate_and_initialize_offsets(size_t count, long min_val, long max_val);
int* generate_keys(size_t count, int min_val, int max_val, int (*validate)(int));
record* initialize_records(size_t count, int min_val, int max_val, int (*validate)(int));

// Validation function example
int validate_key(int key) {
    // Example criteria: key must be even
    return key % 2 == 0;
}

long generate_random_long(long min, long max) {
    return rand() % (max - min + 1) + min;
}

int generate_valid_int(int min, int max, int (*validate)(int)) {
    int value;
    do {
        value = rand() % (max - min + 1) + min;
    } while (!validate(value));
    return value;
}

// Allocate and initialize an array of long offsets
long* allocate_and_initialize_offsets(size_t count, long min_val, long max_val) {
    if (count == 0) return NULL;

    long* offsets = malloc(count * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < count; ++i) {
        offsets[i] = generate_random_long(min_val, max_val);
    }
    return offsets;
}

// Generate an array of keys with validation
int* generate_keys(size_t count, int min_val, int max_val, int (*validate)(int)) {
    if (count == 0 || !validate) return NULL;

    int* keys = malloc(count * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < count; ++i) {
        keys[i] = generate_valid_int(min_val, max_val, validate);
    }
    return keys;
}

// Initialize an array of records with validation
record* initialize_records(size_t count, int min_val, int max_val, int (*validate)(int)) {
    if (count == 0 || !validate) return NULL;

    record* records = malloc(count * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < count; ++i) {
        records[i].value = generate_valid_int(min_val, max_val, validate);
    }
    return records;
}

// Function to set up encryption cipher
EVP_CIPHER_CTX* setup_cipher(const char* cipher_name, int mode) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create EVP_CIPHER_CTX\n");
        return NULL;
    }

    const EVP_CIPHER* cipher = EVP_get_cipherbyname(cipher_name);
    if (!cipher) {
        fprintf(stderr, "Unknown cipher %s\n", cipher_name);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (EVP_CipherInit_ex(ctx, cipher, NULL, NULL, NULL, mode) != 1) {
        fprintf(stderr, "Failed to initialize cipher\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

// Main function demonstrating the setup
int main() {
    // Seed random number generator
    srand(time(NULL));

    size_t count = 1000; // Example count
    long min_offset = 0, max_offset = 100;
    int min_key = 0, max_key = 255;

    // Allocate and initialize components
    long* offsets = allocate_and_initialize_offsets(count, min_offset, max_offset);
    int* keys = generate_keys(count, min_key, max_key, validate_key);
    record* records = initialize_records(count, min_key, max_key, validate_key);

    // Setup cipher example
    const char* cipher_name = "aes-256-cbc";
    EVP_CIPHER_CTX* ctx = setup_cipher(cipher_name, 1); // 1 for encrypt

    if (ctx) {
        // Use the context...
        EVP_CIPHER_CTX_free(ctx);
    }

    // Clean up
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
```

This code provides a scalable and thread-safe approach to allocating and initializing arrays of offsets, keys, and records. It includes random value generation with validation and integrates OpenSSL for encryption setup. The function `setup_cipher` handles different encryption modes, including ECB, EDE, EDE3, and CFB, with flexibility for runtime changes. Error handling and memory management are incorporated to ensure robustness.']

