#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <errno.h>

typedef struct {
    int key;
    long offset;
    double value;
    char *name;
    int meta1;
    int meta2;
} Record;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int compareRecords(const void* a, const void* b) {
    const Record* recordA = (const Record*)a;
    const Record* recordB = (const Record*)b;
    return recordA->key - recordB->key;
}

void freeRecords(Record* records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(records[i].name);
    }
    free(records);
}

Record* initializeRecords(size_t count) {
    Record* records = malloc(count * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    srand(time(NULL));

    for (size_t i = 0; i < count; ++i) {
        records[i].key = rand() % 10000;
        records[i].offset = i * 10L;
        records[i].value = (double)rand() / RAND_MAX * 100.0;
        size_t nameLength = rand() % 21 + 1; // Max length constraint
        records[i].name = malloc(nameLength);
        if (!records[i].name) {
            perror("Failed to allocate memory for record name");
            freeRecords(records, i);
            return NULL;
        }
        snprintf(records[i].name, nameLength, "Record_%ld", (long)i);
        records[i].meta1 = rand() % 1000;
        records[i].meta2 = rand() % 1000;
    }

    qsort(records, count, sizeof(Record), compareRecords);

    return records;
}

void exportToCSV(const Record* records, size_t count, const char* filename) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fprintf(file, "Key,Offset,Value,Name,Meta1,Meta2\n");

    for (size_t i = 0; i < count; ++i) {
        fprintf(file, "%d,%ld,%.2f,\"%s\",%d,%d\n",
                records[i].key,
                records[i].offset,
                records[i].value,
                records[i].name,
                records[i].meta1,
                records[i].meta2);
    }

    fclose(file);
}

void manageRecords(size_t count) {
    Record* records = initializeRecords(count);
    if (!records)
        return;

    const char* csvFilename = "output.csv";

    pthread_mutex_lock(&mutex);

    exportToCSV(records, count, csvFilename);

    pthread_mutex_unlock(&mutex);

    freeRecords(records, count);
}

int main() {
    size_t recordCount = 1000; // Example: Initialize 1000 records

    manageRecords(recordCount);

    return 0;
}
```

