```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRING_LENGTH 256
#define NODE_KEY_RANGE 1000
#define NUM_NODES 10

typedef struct edge {
    void *destination;
    double weight;
} Edge;

typedef struct node {
    int key;
    struct node **children; // Binary search tree children
    Edge **edges;
    size_t num_edges;
} Node;

typedef struct resource_bundle {
    double *floats;
    char (*strings)[MAX_STRING_LENGTH];
    Node **nodes;
    pthread_mutex_t mutex;
    pthread_rwlock_t rwlock;
} ResourceBundle;

// Utility function to allocate memory and handle errors
void *allocate_memory(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Initialize the resource bundle from a file
int initialize_resource_bundle(const char *file_path, ResourceBundle **bundle) {
    FILE *file = fopen(file_path, "r");
    if (!file) {
        perror("File opening failed");
        return -1;
    }

    // Memory allocation for the resource bundle
    *bundle = allocate_memory(sizeof(ResourceBundle));
    (*bundle)->floats = allocate_memory(NUM_NODES * sizeof(double));
    (*bundle)->strings = allocate_memory(NUM_NODES * sizeof(char[MAX_STRING_LENGTH]));
    (*bundle)->nodes = allocate_memory(NUM_NODES * sizeof(Node*));

    // Initialize synchronization primitives
    pthread_mutex_init(&(*bundle)->mutex, NULL);
    pthread_rwlock_init(&(*bundle)->rwlock, NULL);

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < NUM_NODES; ++i) {
        (*bundle)->floats[i] = rand() / (double)RAND_MAX;

        snprintf((*bundle)->strings[i], MAX_STRING_LENGTH, "String %d", i);

        Node *node = allocate_memory(sizeof(Node));
        node->key = rand() % NODE_KEY_RANGE;
        node->children = allocate_memory(2 * sizeof(Node*)); // Binary tree
        node->edges = NULL; // No edges initially
        node->num_edges = 0;

        (*bundle)->nodes[i] = node;
    }

    fclose(file);
    return NUM_NODES;
}

// Clean up memory used by the resource bundle
void cleanup_resource_bundle(ResourceBundle *bundle) {
    if (!bundle) return;

    for (int i = 0; i < NUM_NODES; ++i) {
        free(bundle->nodes[i]->children);
        if (bundle->nodes[i]->edges) {
            free(bundle->nodes[i]->edges);
        }
        free(bundle->nodes[i]);
    }

    free(bundle->floats);
    free(bundle->strings);
    free(bundle->nodes);

    pthread_mutex_destroy(&bundle->mutex);
    pthread_rwlock_destroy(&bundle->rwlock);
    free(bundle);
}

// Thread-safe function to get a node's key
int get_node_key_safe(ResourceBundle *bundle, int index) {
    if (!bundle || index < 0 || index >= NUM_NODES) return -1;

    pthread_rwlock_rdlock(&bundle->rwlock);
    int key = bundle->nodes[index]->key;
    pthread_rwlock_unlock(&bundle->rwlock);

    return key;
}

// Thread-safe function to update a node's key
void set_node_key_safe(ResourceBundle *bundle, int index, int new_key) {
    if (!bundle || index < 0 || index >= NUM_NODES) return;

    pthread_rwlock_wrlock(&bundle->rwlock);
    bundle->nodes[index]->key = new_key;
    pthread_rwlock_unlock(&bundle->rwlock);
}

// Example main function
int main() {
    ResourceBundle *bundle;
    const char *file_path = "resource_file.txt";

    int result = initialize_resource_bundle(file_path, &bundle);
    if (result == -1) {
        fprintf(stderr, "Failed to initialize resource bundle.\n");
        return EXIT_FAILURE;
    }

    printf("Number of items in the bundle: %d\n", result);

    // Example usage of thread-safe functions
    int key = get_node_key_safe(bundle, 0);
    printf("Node 0 Key: %d\n", key);

    set_node_key_safe(bundle, 0, 42);
    key = get_node_key_safe(bundle, 0);
    printf("Updated Node 0 Key: %d\n", key);

    cleanup_resource_bundle(bundle);
    return EXIT_SUCCESS;
}
```

This code sets up a resource bundle with arrays of doubles, strings, nodes, and edges. It includes thread safety using mutexes and read-write locks to allow concurrent access. The nodes are initialized with random keys and empty edge lists. Memory is dynamically allocated and freed properly.']

