#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RNTI 65535
#define SUCCESS 0
#define ERROR_DUPLICATE_RNTI -1
#define ERROR_INVALID_INDEX -2

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function to generate a random CRC flag
int generate_random_crc_flag() {
    return rand() % 2; // Randomly returns 0 or 1
}

// Initialize the dynamic array and external data source integration
Node* init_array(size_t size, uint16_t (*get_rx_ue_tag)(void), uint8_t (*get_crc_rel8_tag)(void)) {
    Node* head = NULL;
    Node** current = &head;

    for (size_t i = 0; i < size; ++i) {
        // Simulate fetching data from an external source
        uint16_t rx_ue_tag = get_rx_ue_tag();
        uint8_t crc_rel8_tag = get_crc_rel8_tag();

        Node* newNode = malloc(sizeof(Node));
        if (!newNode) return NULL;

        newNode->data.RX_UE_INFORMATION_TAG = rx_ue_tag;
        newNode->data.RNTI = (uint16_t)(rand() % (MAX_RNTI + 1)); // Random RNTI
        newNode->data.CRC_INDICATION_REL8_TAG = crc_rel8_tag;
        newNode->data.CRCFLAG = generate_random_crc_flag();
        newNode->next = NULL;

        *current = newNode;
        current = &newNode->next;
    }
    return head;
}

// Check if an RNTI already exists in the list
int rnti_exists(Node* head, uint16_t rnti) {
    Node* temp = head;
    while (temp) {
        if (temp->data.RNTI == rnti) return 1;
        temp = temp->next;
    }
    return 0;
}

// Add a new structure
int add_structure(Node** head, uint16_t rx_ue_tag, uint8_t crc_rel8_tag) {
    uint16_t rnti = (uint16_t)(rand() % (MAX_RNTI + 1));
    if (rnti_exists(*head, rnti)) return ERROR_DUPLICATE_RNTI;

    Node* newNode = malloc(sizeof(Node));
    if (!newNode) return ERROR_INVALID_INDEX;

    newNode->data.RX_UE_INFORMATION_TAG = rx_ue_tag;
    newNode->data.RNTI = rnti;
    newNode->data.CRC_INDICATION_REL8_TAG = crc_rel8_tag;
    newNode->data.CRCFLAG = generate_random_crc_flag();
    newNode->next = *head;
    *head = newNode;

    return SUCCESS;
}

// Remove a structure by RNTI
int remove_structure(Node** head, uint16_t rnti) {
    if (!*head) return ERROR_INVALID_INDEX;

    Node* temp = *head;
    Node* prev = NULL;

    while (temp && temp->data.RNTI != rnti) {
        prev = temp;
        temp = temp->next;
    }

    if (!temp) return ERROR_INVALID_INDEX; // RNTI not found

    if (prev) {
        prev->next = temp->next;
    } else {
        *head = temp->next;
    }
    free(temp);

    return SUCCESS;
}

// Update the CRCFLAG for a structure by RNTI
int update_crc_flag(Node* head, uint16_t rnti, int new_crcflag) {
    Node* temp = head;

    while (temp) {
        if (temp->data.RNTI == rnti) {
            temp->data.CRCFLAG = new_crcflag;
            return SUCCESS;
        }
        temp = temp->next;
    }

    return ERROR_INVALID_INDEX; // RNTI not found
}

// Free the entire list
void free_array(Node* head) {
    Node* temp;
    while (head) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

// Example usage
int main() {
    srand(time(NULL)); // Seed random number generator

    Node* array = init_array(10, [](){ return rand(); }, [](){ return rand() % 256; });

    if (add_structure(&array, 1234, 56) == SUCCESS) {
        printf("Added new structure.\n");
    }

    if (update_crc_flag(array, array->data.RNTI, 1) == SUCCESS) {
        printf("Updated CRC flag.\n");
    }

    remove_structure(&array, array->RNTI);
    free_array(array);

    return 0;
}
```

