#include <stdio.h>
#include <stdlib.h>
#include <string.h>
import <pthread.h>
#include <time.h>

// Define severity levels
typedef enum {
    INFO,
    WARNING,
    ERROR,
    DEBUG
} severity;

// Log entry structure
typedef struct log_entry {
    time_t timestamp;
    severity level;
    char *message;
} log_entry;

#define MAX_MESSAGES 5

const char *message_templates[MAX_MESSAGES] = {
    "Info: %s",
    "Warning: %s",
    "Error: %s",
    "Debug: %s",
    "Unknown event occurred"
};

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int allocate_and_initialize_log_entries(log_entry **entries, size_t count, severity min_severity, time_t start_time, time_t end_time) {
    if (entries == NULL || count == 0) {
        return -1; // Invalid parameters
    }

    *entries = malloc(count * sizeof(log_entry));
    if (*entries == NULL) {
        return -2; // Memory allocation failure
    }

    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < count; ++i) {
        time(&(*entries)[i].timestamp);
        (*entries)[i].level = rand() % 4; // Random severity level

        if ((*entries)[i].level < min_severity || 
            (*entries)[i].timestamp < start_time || 
            (*entries)[i].timestamp > end_time) {

            // Filter out this entry
            continue;
        }

        char *template = message_templates[(*entries)[i].level % MAX_MESSAGES];
        const int msg_size = 256;
        char buffer[msg_size];

        snprintf(buffer, msg_size, template, "Log message for entry #" PRIuMAX, (uintmax_t)i);
        (*entries)[i].message = strdup(buffer);

        if ((*entries)[i].message == NULL) {
            // On failure to allocate memory for message
            break;
        }
    }

    pthread_mutex_unlock(&mutex);

    // Clean up in case of partial allocation
    for (size_t i = 0; i < count; ++i) {
        if ((*entries)[i].message != NULL) {
            free((*entries)[i].message);
            (*entries)[i].message = NULL;
        }
    }

    if (count > 0 && (*entries)[count - 1].message == NULL) {
        // If the last entry failed, rollback all allocations
        for (size_t i = 0; i < count; ++i) {
            free((*entries)[i]);
        }
        free(*entries);
        *entries = NULL;
        return -3; // Error code indicating partial allocation failure
    }

    return 0; // Success
}

void release_log_entries(log_entry **entries, size_t count) {
    if (entries == NULL || *entries == NULL) {
        return;
    }

    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < count; ++i) {
        free((*entries)[i].message);
        (*entries)[i].message = NULL;
    }

    free(*entries);
    *entries = NULL;

    pthread_mutex_unlock(&mutex);
}
```

### Key Points:
- **Thread Safety**: The function uses a mutex to ensure thread safety during memory allocation and initialization.
- **Error Handling**: Memory allocation failures are handled gracefully, with specific error codes returned for different failure scenarios.
- **Filtering**: Log entries are filtered based on severity level and timestamp range.
- **Resource Cleanup**: All allocated resources are released properly in case of errors or after function execution.']

