volatile int retentionPolicyUpdated = 0;

void* initCellularTraffic(void* arg) {
    pthread_mutex_lock(&globalList.lock);

    CellularTrafficEvent* newEvent = (CellularTrafficEvent*)malloc(sizeof(CellularTrafficEvent));
    if (!newEvent) return NULL;

