    newEvent->trafficData.data = rand(); // Example traffic data

    newEvent->next = globalList.head;
    globalList.head = newEvent;

    pthread_mutex_unlock(&globalList.lock);
    return NULL;
}

void cleanupOldEvents() {
    pthread_mutex_lock(&globalList.lock);

    time_t currentTime = time(NULL);
    CellularTrafficEvent **current = &globalList.head, *temp;

    while (*current) {
        if (currentTime - (*current)->eventTime > globalList.retentionPeriod) {
            temp = *current;
            *current = (*current)->next;
            free(temp);
        } else {
            current = &(*current)->next;
        }
    }

    pthread_mutex_unlock(&globalList.lock);
}

void updateRetentionPolicy(time_t newRetentionPeriod) {
    pthread_mutex_lock(&globalList.lock);

    globalList.retentionPeriod = newRetentionPeriod;
    retentionPolicyUpdated = 1;

    pthread_cond_signal(&policyUpdateCond);

    pthread_mutex_unlock(&globalList.lock);
}

void* eventCleanupThread(void* arg) {
    while (1) {
        cleanupOldEvents();

        if (retentionPolicyUpdated) {
            pthread_cond_wait(&policyUpdateCond, &globalList.lock);
            retentionPolicyUpdated = 0;
        }

        // Sleep for a fixed interval
        sleep(60); // Run every minute
    }
}

void exportRetainedEvents() {
    pthread_mutex_lock(&globalList.lock);

    CellularTrafficEvent* current = globalList.head;

    while (current) {
        // Export event in standardized format
        printf("Exporting: cellId=%d, eventTime=%ld\n", current->cellId, current->eventTime);

        // Ensure sensitive data is masked or removed here

        current = current->next;
    }

    pthread_mutex_unlock(&globalList.lock);
}

void startDistributedLinkedList() {
    pthread_t cleanupThread;

    pthread_create(&cleanupThread, NULL, eventCleanupThread, NULL);

    for (int i = 0; i < MAX_EVENTS; i++) {
        initCellularTraffic(NULL);
