        if (difftime(time(NULL), (*current)->eventTime) > retentionPeriod) {
            CellularTrafficEvent *toDelete = *current;
            *current = (*current)->next;
            free(toDelete);
        } else {
            current = &(*current)->next;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

