    int age;
    char unique_id[UNIQUE_ID_LEN];
    char registration_date[METADATA_SIZE];
} Record;

typedef struct {
    long offset;
    int key;
    Record record;
    char metadata[METADATA_SIZE];
    pthread_mutex_t lock; // for thread safety
    unsigned long last_accessed; // timestamp for LRU eviction strategy
} UserProfile;

UserProfile *profiles = NULL;
size_t profile_count = 0;
pthread_mutex_t profiles_lock = PTHREAD_MUTEX_INITIALIZER;
unsigned long current_time = 0; // Simulated time, would be updated by a timer

// Function prototypes
void initialize_profiles(size_t count);
void cleanup_profiles();
int validate_age(int age);
void log_error(const char *message);
UserProfile* allocate_profile(long offset, int key, const Record* record, const char* metadata);
void evict_infrequently_accessed_records();

// Main function to create and manage user profiles
void initialize_profiles(size_t count) {
    if (count == 0) return;

    pthread_mutex_lock(&profiles_lock);

    size_t required_memory = sizeof(UserProfile) * count;
    if (required_memory > SYSTEM_LIMIT) {
        log_error("Memory allocation exceeds system limit");
        pthread_mutex_unlock(&profiles_lock);
        return;
    }

    profiles = malloc(required_memory);
    if (!profiles) {
        log_error("Failed to allocate memory for user profiles");
        pthread_mutex_unlock(&profiles_lock);
        return;
    }

    profile_count = count;

    // Initialize mutexes
    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_init(&profiles[i].lock, NULL);
    }

    pthread_mutex_unlock(&profiles_lock);

    // Example of filling profiles with data
    for (size_t i = 0; i < count; ++i) {
        Record rec;
        strcpy(rec.name, "User");
        sprintf(rec.unique_id, "%08lu", current_time + i); // Simulating unique ID generation
        strcpy(rec.registration_date, "2023-10-01");

        if (!validate_age(i % 100)) { // Simulated age data
            log_error("Invalid age detected, skipping profile initialization");
            continue;
        }

        char metadata[METADATA_SIZE] = "Some additional info";

        UserProfile *profile = allocate_profile(0, i, &rec, metadata);
        if (profile) {
            pthread_mutex_lock(&profile->lock);
            profile->last_accessed = current_time; // Update access time
            pthread_mutex_unlock(&profile->lock);
        }
    }

    // Periodic eviction of infrequently accessed records
    evict_infrequently_accessed_records();
}

void cleanup_profiles() {
    if (!profiles) return;

    for (size_t i = 0; i < profile_count; ++i) {
        pthread_mutex_destroy(&profiles[i].lock);
    }

    free(profiles);
    profiles = NULL;
    profile_count = 0;
}

int validate_age(int age) {
    return age >= MIN_AGE && age <= MAX_AGE;
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

UserProfile* allocate_profile(long offset, int key, const Record* record, const char* metadata) {
    pthread_mutex_lock(&profiles_lock);

    for (size_t i = 0; i < profile_count; ++i) {
        if (!pthread_mutex_trylock(&profiles[i].lock)) { // Try to lock the mutex
            profiles[i].offset = offset;
            profiles[i].key = key;
            memcpy(&profiles[i].record, record, sizeof(Record));
            strncpy(profiles[i].metadata, metadata, METADATA_SIZE - 1);

            pthread_mutex_unlock(&profiles[i].lock); // Unlock after setting data
            pthread_mutex_unlock(&profiles_lock);
            return &profiles[i];
        }
    }

    pthread_mutex_unlock(&profiles_lock);
    return NULL;
}

void evict_infrequently_accessed_records() {
    // Eviction logic based on last access time and some threshold
    unsigned long eviction_threshold = current_time - 3600; // Example: 1 hour threshold

    for (size_t i = 0; i < profile_count; ++i) {
        pthread_mutex_lock(&profiles[i].lock);

        if (profiles[i].last_accessed < eviction_threshold) {
            // Evict this profile
            memset(&profiles[i], 0, sizeof(UserProfile)); // Simulate clearing data
            log_error("Evicted infrequently accessed record");
        }

        pthread_mutex_unlock(&profiles[i].lock);
    }
}

// For testing purposes
int main() {
    initialize_profiles(10);

    cleanup_profiles();

    return 0;
}
```

