    NetworkPerformanceMetrics data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t mutex; // For simplicity in this example, using a lock
} ConcurrentList;

void initialize_concurrent_list(ConcurrentList* list) {
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

void destroy_concurrent_list(ConcurrentList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
}

int insert_metric(ConcurrentList* list, NetworkPerformanceMetrics metric) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->data = metric;
    new_node->next = NULL;

    pthread_mutex_lock(&list->mutex);

    if (list->head == NULL || list->count < 10) {
        new_node->next = list->head;
        list->head = new_node;
    } else {
        Node* current = list->head;
        for (int i = 0; i < 9; ++i) {
            current = current->next;
        }
        current->next = new_node;
    }

    if (list->count >= 10) {
        free(list->head);
        list->head = new_node;
    } else {
        ++list->count;
    }

    pthread_mutex_unlock(&list->mutex);

    return 0;
}

double calculate_moving_average(ConcurrentList* list) {
    double sum = 0.0;
    Node* current = list->head;

    for (int i = 0; i < 10 && current != NULL; ++i, current = current->next) {
        sum += current->data.throughput;
    }

    return current == NULL ? 0 : sum / 10.0;
}

