#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

#define MEMORY_ALLOCATION_ERROR -1

record* create_and_sort_records(size_t size, int min_val, int max_val) {
    if (size == 0 || min_val > max_val) return NULL;

    // Allocate memory for records
    record* records = (record*)malloc(size * sizeof(record));
    if (!records) return (void*)(intptr_t)MEMORY_ALLOCATION_ERROR;

    // Generate random values
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);
    srand(pthread_self());  // Seed with thread ID for better randomness in multi-threaded environments

    #pragma omp parallel for
    for (size_t i = 0; i < size; ++i) {
        int random_value = min_val + rand() % (max_val - min_val + 1);
        pthread_mutex_lock(&lock);
        records[i].value = random_value;
        pthread_mutex_unlock(&lock);
    }

    // Sort the array
    qsort(records, size, sizeof(record), [](const void* a, const void* b) -> int {
        record* recA = (record*)a;
        record* recB = (record*)b;
        return recA->value - recB->value;
    });

    // Destroy lock
    pthread_mutex_destroy(&lock);

    return records;
}

void free_records(record* records) {
    if (records) {
        free(records);
    }
}
