public class DatabaseHelper
{
    public static IDataReader ExecuteQuery(SqlConnection connection, string commandText, List<object> parameters)
    {
        if (connection == null) throw new ArgumentNullException(nameof(connection));
        if (string.IsNullOrWhiteSpace(commandText)) throw new ArgumentException("Command text cannot be null or whitespace.", nameof(commandText));

        using (SqlCommand command = new SqlCommand(commandText, connection))
        {
            // Add parameters to the command
            for (int i = 0; i < parameters.Count; i++)
            {
                command.Parameters.AddWithValue($"@p{i}", parameters[i]);
            }

            try
            {
                // Open connection if it's not already open
                if (connection.State != ConnectionState.Open)
                    connection.Open();

                return command.ExecuteReader(CommandBehavior.CloseConnection);
            }
            catch (SqlException ex)
            {
                // Handle exception, potentially logging or rethrowing with additional context
                throw new InvalidOperationException("An error occurred while executing the SQL command.", ex);
            }
        }
    }
}
