#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_LOGS 10000000
#define LOG_ENTRY_SIZE 256
#define TIMESTAMP_SIZE sizeof(time_t)
#define USER_ID_SIZE 32
#define LOG_ID_SIZE 64

typedef struct {
    char logID[LOG_ID_SIZE];
    time_t timestamp;
    char userID[USER_ID_SIZE];
    char *entries; // Variable-length entries
} LogEntry;

typedef struct {
    LogEntry *logs[MAX_LOGS];
    int size;
    pthread_mutex_t lock;
} LogManager;

LogManager logManager;

void init_log_manager() {
    logManager.size = 0;
    pthread_mutex_init(&logManager.lock, NULL);
}

int add_log_entry(const char *logID, time_t timestamp, const char *userID, const char *entries) {
    pthread_mutex_lock(&logManager.lock);

    if (logManager.size >= MAX_LOGS) {
        fprintf(stderr, "Log manager is full.\n");
        pthread_mutex_unlock(&logManager.lock);
        return -1;
    }

    LogEntry *newLog = malloc(sizeof(LogEntry));
    if (!newLog) {
        fprintf(stderr, "Memory allocation failed.\n");
        pthread_mutex_unlock(&logManager.lock);
        return -1;
    }

    strncpy(newLog->logID, logID, LOG_ID_SIZE);
    newLog->timestamp = timestamp;
    strncpy(newLog->userID, userID, USER_ID_SIZE);

    size_t entryLen = strlen(entries) + 1;
    if (entryLen > LOG_ENTRY_SIZE) {
        fprintf(stderr, "Entry too large.\n");
        free(newLog);
        pthread_mutex_unlock(&logManager.lock);
        return -1;
    }

    newLog->entries = malloc(entryLen);
    if (!newLog->entries) {
        fprintf(stderr, "Memory allocation for entries failed.\n");
        free(newLog);
        pthread_mutex_unlock(&logManager.lock);
        return -1;
    }
    strcpy(newLog->entries, entries);

    logManager.logs[logManager.size++] = newLog;

    pthread_mutex_unlock(&logManager.lock);
    return 0;
}

void *housekeeping(void *arg) {
    time_t current_time;
    while (1) {
        sleep(86400); // Run daily
        pthread_mutex_lock(&logManager.lock);

        current_time = time(NULL);
        for (int i = 0; i < logManager.size; ++i) {
            double age_in_days = difftime(current_time, logManager.logs[i]->timestamp) / (60 * 60 * 24);
            if (age_in_days > *(double *)arg) {
                free(logManager.logs[i]->entries);
                free(logManager.logs[i]);
                memmove(&logManager.logs[i], &logManager.logs[i + 1],
                        sizeof(LogEntry*) * (logManager.size - i - 1));
                logManager.size--;
                i--; // Adjust index after removal
            }
        }

        pthread_mutex_unlock(&logManager.lock);
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <days_to_retain>\n", argv[0]);
        return EXIT_FAILURE;
    }

    double daysToRetain = atof(argv[1]);

    init_log_manager();

    pthread_t housekeeping_thread;
    pthread_create(&housekeeping_thread, NULL, housekeeping, &daysToRetain);

    // Example usage
    add_log_entry("001", time(NULL), "user123", "This is a log entry.");

    pthread_join(housekeeping_thread, NULL);
    return 0;
}
```

### Key Points:
