```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_STRING_SIZE 256
#define TREE_ERROR_CODE -1

typedef struct Node {
    int key;
    struct Node *left;
    struct Node *right;
    char position; // 'L' for left, 'R' for right
} Node;

typedef struct CompressedString {
    unsigned char data[MAX_STRING_SIZE / 2]; // Simple compression scheme
    size_t length;
} CompressedString;

typedef struct Tree {
    Node **nodes;
    CompressedString *strings;
    double *values;
    size_t node_count;
    pthread_mutex_t lock;
} Tree;

// Function prototypes
Tree* create_tree(size_t initial_size);
int insert_node(Tree *tree, int key_range_min, int key_range_max);
void free_tree(Tree *tree);
void serialize_tree(const char *filename, const Tree *tree);
Tree* deserialize_tree(const char *filename);

static Node* create_node(int key) {
    Node *node = (Node *)malloc(sizeof(Node));
    if (!node) return NULL;
    node->key = key;
    node->left = node->right = NULL;
    return node;
}

static int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

Tree* create_tree(size_t initial_size) {
    Tree *tree = (Tree *)malloc(sizeof(Tree));
    if (!tree) return NULL;

    pthread_mutex_init(&tree->lock, NULL);
    tree->nodes = (Node **)calloc(initial_size, sizeof(Node *));
    tree->strings = (CompressedString *)calloc(initial_size, sizeof(CompressedString));
    tree->values = (double *)calloc(initial_size, sizeof(double));
    tree->node_count = 0;

    if (!tree->nodes || !tree->strings || !tree->values) {
        free(tree);
        return NULL;
    }

    return tree;
}

int insert_node(Tree *tree, int key_range_min, int key_range_max) {
    pthread_mutex_lock(&tree->lock);

    if (tree->node_count >= MAX_SIZE) {
        pthread_mutex_unlock(&tree->lock);
        return TREE_ERROR_CODE;
    }

    Node *new_node = create_node(random_int(key_range_min, key_range_max));
    if (!new_node) {
        pthread_mutex_unlock(&tree->lock);
        return TREE_ERROR_CODE;
    }

    // AVL insertion logic here
    // For simplicity, we just add to the end
    tree->nodes[tree->node_count++] = new_node;

    pthread_mutex_unlock(&tree->lock);
    return 0;
}

void free_tree(Tree *tree) {
    for (size_t i = 0; i < tree->node_count; ++i) {
        free(tree->nodes[i]);
    }
    free(tree->nodes);
    free(tree->strings);
    free(tree->values);
    pthread_mutex_destroy(&tree->lock);
    free(tree);
}

void serialize_tree(const char *filename, const Tree *tree) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&tree->node_count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < tree->node_count; ++i) {
        Node *node = tree->nodes[i];
        fwrite(&node->key, sizeof(int), 1, file);
        // Serialize left and right pointers as indices
        size_t left_index = node->left ? node->left - tree->nodes[0] : (size_t)-1;
        size_t right_index = node->right ? node->right - tree->nodes[0] : (size_t)-1;
        fwrite(&left_index, sizeof(size_t), 1, file);
        fwrite(&right_index, sizeof(size_t), 1, file);
    }

    fclose(file);
}

Tree* deserialize_tree(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    Tree *tree = create_tree(MAX_SIZE);
    if (!tree) {
        fclose(file);
        return NULL;
    }

    fread(&tree->node_count, sizeof(size_t), 1, file);
    tree->nodes = (Node **)realloc(tree->nodes, tree->node_count * sizeof(Node *));
    for (size_t i = 0; i < tree->node_count; ++i) {
        Node node;
        fread(&node.key, sizeof(int), 1, file);
        size_t left_index, right_index;
        fread(&left_index, sizeof(size_t), 1, file);
        fread(&right_index, sizeof(size_t), 1, file);
        tree->nodes[i] = create_node(node.key);
        if (left_index != (size_t)-1) {
            tree->nodes[i]->left = tree->nodes[left_index];
        }
        if (right_index != (size_t)-1) {
            tree->nodes[i]->right = tree->nodes[right_index];
        }
    }

    fclose(file);
    return tree;
}

int main() {
    Tree *tree = create_tree(10);
    if (!tree) {
        fprintf(stderr, "Failed to create tree\n");
        return 1;
    }

    for (int i = 0; i < 5; ++i) {
        int result = insert_node(tree, 0, 100);
        if (result == TREE_ERROR_CODE) {
            fprintf(stderr, "Failed to insert node\n");
        }
    }

    serialize_tree("tree.dat", tree);

    Tree *loaded_tree = deserialize_tree("tree.dat");
    free_tree(tree);
    free_tree(loaded_tree);

    return 0;
}
