#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define CONFIG_FILE "config.txt"
#define MAX_EVENTS 1000

typedef struct {
    unsigned int tag;
    time_t timestamp;
} MAC_EVENT_TAG;

typedef struct {
    unsigned int type;
    size_t length;
    void *data;
} MAC_FRAME_DATA;

typedef struct EventNode {
    MAC_EVENT_TAG eventTag;
    time_t timestamp;
    size_t numFrames;
    MAC_FRAME_DATA *frames;
    struct EventNode *next;
} EventNode;

typedef struct {
    EventNode *head;
    pthread_mutex_t lock;
} NetworkEventList;

// Function declarations
int load_config(int *numStructures, unsigned int *seed);
NetworkEventList* init_network_event_list();
void destroy_network_event_list(NetworkEventList *list);
int add_frame_to_event(NetworkEventList *list, MAC_EVENT_TAG eventTag, MAC_FRAME_DATA frameData);
void log_event_creation(MAC_EVENT_TAG eventTag, time_t timestamp);
void export_to_binary_file(const char *filename, NetworkEventList *list);

// Function implementations

int load_config(int *numStructures, unsigned int *seed) {
    FILE *file = fopen(CONFIG_FILE, "r");
    if (!file) return -1;

    fscanf(file, "%d %u", numStructures, seed);
    fclose(file);
    return 0;
}

NetworkEventList* init_network_event_list() {
    NetworkEventList *list = (NetworkEventList *)malloc(sizeof(NetworkEventList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_network_event_list(NetworkEventList *list) {
    EventNode *current = list->head;
    while (current) {
        EventNode *next = current->next;
        for (size_t i = 0; i < current->numFrames; ++i) {
            free(current->frames[i].data);
        }
        free(current->frames);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_frame_to_event(NetworkEventList *list, MAC_EVENT_TAG eventTag, MAC_FRAME_DATA frameData) {
    if (!frameData.data || frameData.length == 0) return -1;

    time_t now = time(NULL);

    pthread_mutex_lock(&list->lock);

    EventNode **nodePtr = &list->head;
    while (*nodePtr && ((*nodePtr)->eventTag.tag != eventTag.tag)) {
        nodePtr = &(*nodePtr)->next;
    }

    if (!*nodePtr) { // Create new event
        *nodePtr = (EventNode *)malloc(sizeof(EventNode));
        if (!*nodePtr) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }

        (*nodePtr)->eventTag = eventTag;
        (*nodePtr)->timestamp = now;
        (*nodePtr)->numFrames = 0;
        (*nodePtr)->frames = NULL;
        (*nodePtr)->next = NULL;

        log_event_creation(eventTag, now);
    }

    EventNode *currentEvent = *nodePtr;

    currentEvent->frames = (MAC_FRAME_DATA *)realloc(currentEvent->frames,
        sizeof(MAC_FRAME_DATA) * (currentEvent->numFrames + 1));
    if (!currentEvent->frames) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    currentEvent->frames[currentEvent->numFrames] = frameData;
    currentEvent->numFrames++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void log_event_creation(MAC_EVENT_TAG eventTag, time_t timestamp) {
    FILE *logFile = fopen("event_log.txt", "a");
    if (!logFile) return;

    fprintf(logFile, "Event Tag: %u, Timestamp: %ld\n", eventTag.tag, timestamp);
    fclose(logFile);
}

void export_to_binary_file(const char *filename, NetworkEventList *list) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    EventNode *current = list->head;
    while (current) {
        fwrite(&current->eventTag, sizeof(MAC_EVENT_TAG), 1, file);
        fwrite(&current->timestamp, sizeof(time_t), 1, file);
        fwrite(&current->numFrames, sizeof(size_t), 1, file);

        for (size_t i = 0; i < current->numFrames; ++i) {
            fwrite(&current->frames[i], sizeof(MAC_FRAME_DATA), 1, file);
            if (current->frames[i].data) {
                fwrite(current->frames[i].data, current->frames[i].length, 1, file);
            }
        }

        current = current->next;
    }

    fclose(file);
}

int main() {
    int numStructures;
    unsigned int seed;

    if (load_config(&numStructures, &seed) != 0) {
        fprintf(stderr, "Failed to load configuration.\n");
        return EXIT_FAILURE;
    }

    NetworkEventList *eventList = init_network_event_list();
    if (!eventList) {
        fprintf(stderr, "Failed to initialize network event list.\n");
        return EXIT_FAILURE;
    }

    // Simulate adding frames (should be replaced with real data)
    MAC_EVENT_TAG sampleTag = {12345, time(NULL)};
    MAC_FRAME_DATA sampleFrameData = {1, 10, malloc(10)};

    if (add_frame_to_event(eventList, sampleTag, sampleFrameData) != 0) {
        fprintf(stderr, "Failed to add frame to event.\n");
    }

    export_to_binary_file("exported_data.bin", eventList);

    destroy_network_event_list(eventList);

    return EXIT_SUCCESS;
}
