#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>

// Define the element struct
typedef struct {
    float f;
    int i;
    bool b;
} Element;

// Define the metadata struct
typedef struct {
    char *s; // string
    time_t timestamp; // timestamp
} Metadata;

// Node for hash table
typedef struct HashNode {
    void *data;
    size_t key_size;
    struct HashNode *next;
} HashNode;

// LRU Cache node
typedef struct LRUNode {
    void *key;
    void *value;
    struct LRUNode *prev, *next;
} LRUNode;

// Hash Table with LRU Cache
typedef struct {
    size_t capacity;
    size_t count;
    HashNode **buckets;
    LRUNode *lru_head, *lru_tail;
    pthread_mutex_t lock;
} HashTable;

#define INITIAL_CAPACITY 16

HashTable* create_hash_table() {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->capacity = INITIAL_CAPACITY;
    table->count = 0;
    table->buckets = (HashNode**)calloc(table->capacity, sizeof(HashNode*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->lru_head = table->lru_tail = NULL;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

unsigned int hash_function(const void *key, size_t key_size) {
    unsigned long hash = 5381;
    const char *data = (const char*)key;

    for (size_t i = 0; i < key_size; ++i)
        hash = ((hash << 5) + hash) + data[i]; /* hash * 33 + c */

    return hash % INITIAL_CAPACITY;
}

void resize_hash_table(HashTable *table);

HashNode* get_node(const void *key, size_t key_size, HashTable *table) {
    unsigned int index = hash_function(key, key_size);
    HashNode *node = table->buckets[index];

    while (node) {
        if (node->key_size == key_size && memcmp(node->data, key, key_size) == 0)
            return node;
        node = node->next;
    }
    return NULL;
}

void insert_hash_table(HashTable *table, const void *key, size_t key_size, void *value) {
    pthread_mutex_lock(&table->lock);

    HashNode *node = get_node(key, key_size, table);
    if (node) {
        node->data = value;
    } else {
        if ((float)table->count / table->capacity > 0.7)
            resize_hash_table(table);

        node = (HashNode*)malloc(sizeof(HashNode));
        if (!node) {
            pthread_mutex_unlock(&table->lock);
            return;
        }

        node->data = malloc(key_size);
        if (!node->data) {
            free(node);
            pthread_mutex_unlock(&table->lock);
            return;
        }

        memcpy(node->data, key, key_size);
        node->key_size = key_size;
        unsigned int index = hash_function(key, key_size);

        node->next = table->buckets[index];
        table->buckets[index] = node;
        ++table->count;

        // Update LRU
        LRUNode *lru_node = (LRUNode*)malloc(sizeof(LRUNode));
        if (!lru_node) {
            free(node->data);
            free(node);
            pthread_mutex_unlock(&table->lock);
            return;
        }

        lru_node->key = node->data;
        lru_node->value = value;

        if (table->lru_head) {
            table->lru_tail->next = lru_node;
            lru_node->prev = table->lru_tail;
            lru_node->next = NULL;
            table->lru_tail = lru_node;
        } else {
            table->lru_head = table->lru_tail = lru_node;
            lru_node->prev = lru_node->next = NULL;
        }
    }

    pthread_mutex_unlock(&table->lock);
}

void* hash_table_lookup(HashTable *table, const void *key, size_t key_size) {
    pthread_mutex_lock(&table->lock);

    HashNode *node = get_node(key, key_size, table);
    if (node) {
        // Update LRU
        LRUNode *lru_node = NULL;
        for (LRUNode *cur = table->lru_head; cur; cur = cur->next) {
            if (cur->key == node->data) {
                lru_node = cur;
                break;
            }
        }

        if (lru_node && lru_node != table->lru_tail) {
            if (lru_node->prev)
                lru_node->prev->next = lru_node->next;

            if (lru_node->next)
                lru_node->next->prev = lru_node->prev;

            if (table->lru_head == lru_node)
                table->lru_head = lru_node->next;

            lru_node->next = NULL;
            lru_node->prev = table->lru_tail;
            table->lru_tail->next = lru_node;
            table->lru_tail = lru_node;
        }

        pthread_mutex_unlock(&table->lock);
        return node->data;
    }

    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void remove_lru(HashTable *table) {
    if (!table->lru_head)
        return;

    LRUNode *node = table->lru_head;
    unsigned int index = hash_function(node->key, node->key_size);

    HashNode *head_node = table->buckets[index];
    HashNode *prev_node = NULL;

    while (head_node) {
        if (head_node->data == node->key) {
            if (prev_node)
                prev_node->next = head_node->next;
            else
                table->buckets[index] = head_node->next;

            free(head_node->data);
            free(head_node);

            --table->count;
            break;
        }
        prev_node = head_node;
        head_node = head_node->next;
    }

    if (node == table->lru_tail)
        table->lru_tail = node->prev;

    if (node->prev)
        node->prev->next = node->next;

    if (table->lru_head == node)
        table->lru_head = node->next;

    free(node);
}

void resize_hash_table(HashTable *table) {
    size_t new_capacity = table->capacity * 2;
    HashNode **new_buckets = (HashNode**)calloc(new_capacity, sizeof(HashNode*));
    if (!new_buckets) return;

    for (size_t i = 0; i < table->capacity; ++i) {
        HashNode *node = table->buckets[i];
        while (node) {
            HashNode *next_node = node->next;
            unsigned int index = hash_function(node->data, node->key_size);

            node->next = new_buckets[index];
            new_buckets[index] = node;

            node = next_node;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->capacity = new_capacity;
}

void free_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        HashNode *node = table->buckets[i];
        while (node) {
            HashNode *next_node = node->next;

            if (node->data)
                free(node->data);

            free(node);
            node = next_node;
        }
    }

    while (table->lru_head) {
        LRUNode *node = table->lru_head;
        table->lru_head = node->next;

        if (node->key)
            free(node->key);

        free(node);
    }

    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

int resolve_hostname(const char *hostname, u_char ip_array[4]) {
    struct hostent *host_info = gethostbyname(hostname);
    if (!host_info) return -1;

    memcpy(ip_array, *(struct in_addr **)host_info->h_addr_list, sizeof(struct in_addr));
    return 0;
}

int main() {
    // Initialize hash table
    HashTable *table = create_hash_table();
    if (!table) {
        fprintf(stderr, "Failed to initialize hash table\n");
        return EXIT_FAILURE;
    }

    // Insert some data into the hash table
    double d_data[] = {1.0, 2.0};
    char c_data[] = "Hello";
    Element e_data[] = {{1.0f, 1, true}, {2.0f, 2, false}};
    Metadata m_data[] = {
        {"metadata1", time(NULL)},
        {"metadata2", time(NULL)}
    };

    insert_hash_table(table, &d_data[0], sizeof(d_data[0]), (void*)&e_data[0]);
    insert_hash_table(table, c_data, strlen(c_data) + 1, (void*)&m_data[0]);

    // Lookup data from hash table
    void *result = hash_table_lookup(table, &d_data[0], sizeof(d_data[0]));
    if (result) {
        Element *element = (Element*)result;
        printf("Found element: %f, %d, %d\n", element->f, element->i, element->b);
    }

    // Resolve hostname
    u_char ip_array[4];
    if (resolve_hostname("example.com", ip_array) == 0) {
        char ip_str[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, ip_array, ip_str, INET_ADDRSTRLEN);
        printf("Resolved IP: %s\n", ip_str);
    } else {
        fprintf(stderr, "Failed to resolve hostname\n");
    }

    // Free hash table
    free_hash_table(table);

    return EXIT_SUCCESS;
}
