#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RNTI 65535

typedef struct {
    unsigned int CRCFLAG;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    unsigned short RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    CRC_INDICATION_REL8_TAG_T CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_creation(unsigned short rnti, int crcflag) {
    printf("Created structure with RNTI: %u, CRCFLAG: %d\n", rnti, crcflag);
}

int validate_crc_indication(CRC_INDICATION_REL8_TAG_T *tag) {
    return tag->CRCFLAG == 0 || tag->CRCFLAG == 1;
}

void generate_random_crc_flag(CRC_INDICATION_REL8_TAG_T *tag) {
    int flag = rand() % 2;
    tag->CRCFLAG = flag;
}

NFAPI_CRC_INDICATION_PDU_T* generate_nfa_list(int n, unsigned short seed) {
    srand(seed);
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) return NULL;

    for (int i = 0; i < n; ++i) {
        pthread_mutex_lock(&mutex);

        list[i].RX_UE_INFORMATION_TAG = rand() % MAX_RNTI;
        list[i].RNTI = rand() % MAX_RNTI;
        generate_random_crc_flag(&(list[i].CRC_INDICATION_REL8_TAG));

        if (validate_crc_indication(&(list[i].CRC_INDICATION_REL8_TAG))) {
            log_creation(list[i].RNTI, list[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
        } else {
            fprintf(stderr, "Validation failed for RNTI: %u\n", list[i].RNTI);
            free(list);
            return NULL;
        }

        pthread_mutex_unlock(&mutex);
    }
    return list;
}

void export_to_binary_file(NFAPI_CRC_INDICATION_PDU_T *list, int n, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fwrite(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), n, file);
    fclose(file);
}

