#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>

typedef struct {
    int value;
} record;

#define MAX_FILES 10
#define MAX_RECORDS 10000000

int createDirectoryAndSetEnv(const char *sessionName) {
    char envVar[256];
    snprintf(envVar, sizeof(envVar), "SESSION_DIR_%s", sessionName);

    char dirPath[512];
    sprintf(dirPath, "/tmp/%s", sessionName);

    // Check if directory exists
    struct stat st = {0};
    if (stat(dirPath, &st) == -1) {
        if (mkdir(dirPath, 0700) != 0) {
            perror("Failed to create directory");
            return -1;
        }
    } else if (!S_ISDIR(st.st_mode)) {
        fprintf(stderr, "Not a directory\n");
        return -1;
    }

    // Set environment variable
    setenv(envVar, dirPath, 1);

    char logSubdir[512];
    sprintf(logSubdir, "%s/logs", dirPath);
    if (mkdir(logSubdir, 0700) != 0 && errno != EEXIST) {
        perror("Failed to create logs subdirectory");
        return -2;
    }

    return 0;
}

void *processFile(void *arg) {
    // Cast argument
    char **files = (char **)arg;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (int i = 0; files[i] != NULL; ++i) {
        FILE *file = fopen(files[i], "r");
        if (!file) {
            perror("Failed to open file");
            continue;
        }

        long offsetSize = 1000000; // Example size
        int keySize = 1000000;
        record *records = malloc(offsetSize * sizeof(record));
        int *keys = malloc(keySize * sizeof(int));

        if (!records || !keys) {
            perror("Memory allocation failed");
            free(records);
            free(keys);
            fclose(file);
            continue;
        }

        // Populate with random values
        for (long j = 0; j < offsetSize; ++j) {
            records[j].value = rand() % 1000;
            keys[j] = rand() % 1000;
        }

        // Sort based on keys
        qsort(keys, keySize, sizeof(int), (int (*)(const void *, const void *))strcmp);

        int largestInt = INT_MIN;
        int number;

        while (fscanf(file, "%d", &number) == 1) {
            if (number > largestInt) {
                largestInt = number;
            }
        }

        fclose(file);
        free(records);
        free(keys);

        pthread_mutex_lock(&lock);
        printf("Largest integer in file %s: %d\n", files[i], largestInt);
        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_destroy(&lock);
    return NULL;
}

int processAndSortRecordsWithDir(char **inputFiles, const char *sessionName) {
    if (createDirectoryAndSetEnv(sessionName)) {
        fprintf(stderr, "Failed to set up directory and environment\n");
        return -1;
    }

    pthread_t threads[MAX_FILES];
    for (int i = 0; i < MAX_FILES && inputFiles[i] != NULL; ++i) {
        if (pthread_create(&threads[i], NULL, processFile, &inputFiles)) {
            perror("Failed to create thread");
            return -1;
        }
    }

    for (int i = 0; i < MAX_FILES && inputFiles[i] != NULL; ++i) {
        pthread_join(threads[i], NULL);
