#include <pthread.h>
#include <stdalign.h>

#define INITIAL_CAPACITY 16

typedef struct {
    int key;
    long offset;
    int value;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} RecordCollection;

RecordCollection* init_collection() {
    RecordCollection *collection = (RecordCollection *)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->capacity = INITIAL_CAPACITY;
    collection->size = 0;
    collection->records = (Record *)aligned_alloc(alignof(Record), sizeof(Record) * collection->capacity);
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void free_collection(RecordCollection *collection) {
    if (collection) {
        pthread_mutex_destroy(&collection->lock);
        free(collection->records);
        free(collection);
    }
}

int resize_if_needed(RecordCollection *collection) {
    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record *new_records = (Record *)realloc(collection->records, sizeof(Record) * new_capacity);
        if (!new_records) return -1;

        collection->records = new_records;
        collection->capacity = new_capacity;
    }
    return 0;
}

void update_record(RecordCollection *collection, int key, long offset) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->records[i].key == key) {
            collection->records[i].offset = offset;
            collection->records[i].value += offset; // Example update logic
            break;
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

void add_record(RecordCollection *collection, int key, long offset) {
    if (resize_if_needed(collection) != 0) {
        fprintf(stderr, "Failed to resize collection\n");
        return;
    }

    Record new_record = {key, offset, offset}; // Example initialization

    pthread_mutex_lock(&collection->lock);

    collection->records[collection->size++] = new_record;

    pthread_mutex_unlock(&collection->lock);
}

void log_performance_metrics(RecordCollection *collection) {
    printf("Current size: %zu\n", collection->size);
    printf("Current capacity: %zu\n", collection->capacity);
}

int main() {
    RecordCollection *collection = init_collection();
    if (!collection) {
        fprintf(stderr, "Failed to initialize collection\n");
        return EXIT_FAILURE;
    }

    // Simulate updates
    add_record(collection, 1, 100L);
    update_record(collection, 1, 150L);

    log_performance_metrics(collection);

    free_collection(collection);

    return EXIT_SUCCESS;
}
