#include <string.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <time.h>

#define MAX_OFFSETS 1000
#define KEY_LENGTH 1000
#define RECORD_COUNT 500
#define RANDOM_RANGE_MAX 100

typedef struct {
    int value;
} Record;

typedef struct {
    char *ip_address;
    long *offsets;
    int *keys;
    Record *records;
    size_t offset_count;
    size_t key_length;
    size_t record_count;
} HostInfo;

int resolve_and_process_host(const char *hostname, HostInfo *host_info) {
    if (!hostname || !host_info) return -1;

    struct addrinfo hints, *res, *p;
    int status;
    char ipstr[INET6_ADDRSTRLEN];

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        return -1;
    }

    for(p = res; p != NULL; p = p->ai_next) {
        void *addr;
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin_addr);
        }

        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        break;  // if we get here, it means we found an address
    }

    freeaddrinfo(res);

    host_info->ip_address = strdup(ipstr);

    srand(time(NULL));
    host_info->offset_count = (rand() % MAX_OFFSETS) + 1;
    host_info->keys = malloc(sizeof(int) * KEY_LENGTH);
    if (!host_info->keys) return -1;

    for(size_t i = 0; i < KEY_LENGTH; ++i) {
        host_info->keys[i] = rand() % RANDOM_RANGE_MAX;
    }

    host_info->offsets = malloc(sizeof(long) * host_info->offset_count);
    if (!host_info->offsets) return -1;

    for(size_t i = 0; i < host_info->offset_count; ++i) {
        host_info->offsets[i] = (long)(rand() % RANDOM_RANGE_MAX);
    }

    host_info->record_count = (rand() % RECORD_COUNT) + 1;
    host_info->records = malloc(sizeof(Record) * host_info->record_count);
    if (!host_info->records) return -1;

    for(size_t i = 0; i < host_info->record_count; ++i) {
        host_info->records[i].value = rand() % RANDOM_RANGE_MAX;
    }

    return 0;
}

void free_host_info(HostInfo *host_info) {
    if (host_info) {
        free(host_info->ip_address);
        free(host_info->offsets);
        free(host_info->keys);
        free(host_info->records);
    }
}
