#define SUCCESS 0
#define FAILURE -1

int allocateAndInitialize(
    long* offsetArray, 
    int* keyArray, 
    Record** recordsArray, 
    size_t arraySize, 
    size_t numRecords,
    size_t maxMemoryUsage, 
    int minValue, 
    int maxValue) {

    // Calculate memory requirements
    size_t long_size = sizeof(long);
    size_t int_size = sizeof(int);
    size_t record_size = sizeof(Record);

    size_t totalMemoryRequired = arraySize * (long_size + int_size) + numRecords * record_size;
    if (totalMemoryRequired > maxMemoryUsage) {
        return FAILURE;
    }

    // Seed random number generator
    srand(time(NULL));

    // Allocate memory for arrays and handle potential failure
    offsetArray = (long*)malloc(arraySize * long_size);
    if (!offsetArray) {
        goto cleanup;
    }
    keyArray = (int*)malloc(arraySize * int_size);
    if (!keyArray) {
        free(offsetArray);
        goto cleanup;
    }

    // Allocate memory for records
    *recordsArray = (Record*)malloc(numRecords * record_size);
    if (!(*recordsArray)) {
        free(offsetArray);
        free(keyArray);
        goto cleanup;
    }

    // Initialize arrays and records with random values
