#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_HASH_SIZE 64
#define LOAD_FACTOR 0.75

typedef struct {
    int userId;
    time_t sessionStart;
    time_t sessionEnd;
    double sessionDuration;
    int activityScore;
} UserSessionData;

typedef struct Node {
    UserSessionData data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    size_t size;
    size_t count;
    Node** buckets;
    pthread_rwlock_t lock;
} HashTable;

HashTable* createHashTable(size_t size) {
    HashTable* table = malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->size = size;
    table->count = 0;
    table->buckets = calloc(size, sizeof(Node*));
    pthread_rwlock_init(&table->lock, NULL);

    if (!table->buckets) {
        free(table);
        return NULL;
    }
    return table;
}

unsigned long hashFunction(int userId, size_t tableSize) {
    // Custom hash function for better distribution
    return (userId * 2654435761u) % tableSize; 
}

int resizeHashTable(HashTable* table);

Node* createNode(UserSessionData data) {
    Node* node = malloc(sizeof(Node));
    if (!node) return NULL;

    node->data = data;
    node->prev = node->next = NULL;
    return node;
}

int insertToHashTable(HashTable* table, UserSessionData data) {
    unsigned long index = hashFunction(data.userId, table->size);
    Node* newNode = createNode(data);

    if (!newNode) return -1;

    pthread_rwlock_wrlock(&table->lock);

    newNode->next = table->buckets[index];
    if (table->buckets[index]) {
        table->buckets[index]->prev = newNode;
    }
    table->buckets[index] = newNode;

    table->count++;
    if ((double)table->count / table->size > LOAD_FACTOR) {
        pthread_rwlock_unlock(&table->lock);
        resizeHashTable(table);
    } else {
        pthread_rwlock_unlock(&table->lock);
    }

    return 0;
}

int retrieveFromHashTable(HashTable* table, int userId, UserSessionData *data) {
    unsigned long index = hashFunction(userId, table->size);

    pthread_rwlock_rdlock(&table->lock);

    Node* current = table->buckets[index];
    while (current) {
        if (current->data.userId == userId) {
            *data = current->data;
            pthread_rwlock_unlock(&table->lock);
            return 0;
        }
        current = current->next;
    }

    pthread_rwlock_unlock(&table->lock);
    return -1; // Not found
}

int deleteFromHashTable(HashTable* table, int userId) {
    unsigned long index = hashFunction(userId, table->size);

    pthread_rwlock_wrlock(&table->lock);

    Node* current = table->buckets[index];
    while (current) {
        if (current->data.userId == userId) {
            if (current->prev) current->prev->next = current->next;
            if (current->next) current->next->prev = current->prev;

            if (table->buckets[index] == current) table->buckets[index] = current->next;

            free(current);
            table->count--;
            pthread_rwlock_unlock(&table->lock);
            return 0;
        }
        current = current->next;
    }

    pthread_rwlock_unlock(&table->lock);
    return -1; // Not found
}

int resizeHashTable(HashTable* table) {
    size_t newSize = table->size * 2;
    Node** newBuckets = calloc(newSize, sizeof(Node*));

    if (!newBuckets) return -1;

    for (size_t i = 0; i < table->size; ++i) {
        Node* current = table->buckets[i];
        while (current) {
            Node* next = current->next;
            unsigned long newIndex = hashFunction(current->data.userId, newSize);

            current->next = newBuckets[newIndex];
            if (newBuckets[newIndex]) newBuckets[newIndex]->prev = current;

            newBuckets[newIndex] = current;
            current = next;
        }
    }

    free(table->buckets);
    table->buckets = newBuckets;
    table->size = newSize;

    return 0;
}

void deleteHashTable(HashTable* table) {
    for (size_t i = 0; i < table->size; ++i) {
        Node* current = table->buckets[i];
        while (current) {
            Node* next = current->next;
            free(current);
            current = next;
        }
    }

    free(table->buckets);
    pthread_rwlock_destroy(&table->lock);
    free(table);
}

UserSessionData* initializeSessions(int numberOfUsers, int *resultCount) {
    if (!numberOfUsers || numberOfUsers <= 0) return NULL;

    HashTable* sessionTable = createHashTable(INITIAL_HASH_SIZE);
    if (!sessionTable) return NULL;

    UserSessionData* sessions = malloc(sizeof(UserSessionData) * numberOfUsers);
    if (!sessions) {
        deleteHashTable(sessionTable);
        return NULL;
    }

    for (int i = 0; i < numberOfUsers; ++i) {
        UserSessionData session;
        session.userId = i + 1; // Unique user ID
        session.sessionStart = time(NULL); // Simulated start time
        session.sessionEnd = session.sessionStart + rand() % 10000; // Random end time
        session.sessionDuration = difftime(session.sessionEnd, session.sessionStart);
        session.activityScore = rand() % 1000; // Simulated activity score

        if (insertToHashTable(sessionTable, session) != 0) {
            free(sessions);
            deleteHashTable(sessionTable);
            return NULL;
        }

        sessions[i] = session;
    }

    *resultCount = numberOfUsers;
    deleteHashTable(sessionTable);

    return sessions;
}

int main() {
    int numberOfSessions = 100; // Example number
    int resultCount;
    UserSessionData* sessions = initializeSessions(numberOfSessions, &resultCount);

    if (!sessions) {
        fprintf(stderr, "Failed to initialize sessions\n");
        return EXIT_FAILURE;
    }

    printf("Initialized %d user sessions successfully.\n", resultCount);

    free(sessions);
    return EXIT_SUCCESS;
}
