typedef struct {
    size_t size;
    time_t mod_time;
    mode_t permissions;
} file_info;

int get_file_metadata(const char *path, file_info *info) {
    struct stat st;
    if (stat(path, &st) == -1) {
        return 0; // File not found or inaccessible
    }
    info->size = st.st_size;
    info->mod_time = st.st_mtime;
    info->permissions = st.st_mode;
    return 1;
}

file_info* process_file_paths(const char **paths, size_t num_files) {
