    if (!files) {
        perror("Failed to allocate memory for files");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < num_files; ++i) {
        if (!get_file_metadata(paths[i], &files[i])) {
            fprintf(stderr, "Warning: Could not retrieve metadata for file '%s'\n", paths[i]);
        }
    }

    return files;
}

