    pthread_cond_t cond;
    int active_count;
} RequestQueue;

RequestQueue request_queue = {NULL, NULL, PTHREAD_MUTEX_INITIALIZER, PTHREAD_COND_INITIALIZER, 0};

void enqueue_request(const char *hostname) {
    QueueNode *node = (QueueNode *)malloc(sizeof(QueueNode));
    node->hostname = hostname;
    node->next = NULL;

    pthread_mutex_lock(&request_queue.lock);
    if (request_queue.tail == NULL) {
        request_queue.head = request_queue.tail = node;
    } else {
        request_queue.tail->next = node;
        request_queue.tail = node;
    }
    pthread_cond_signal(&request_queue.cond);
    pthread_mutex_unlock(&request_queue.lock);
}

QueueNode* dequeue_request() {
    pthread_mutex_lock(&request_queue.lock);
    while (request_queue.head == NULL && request_queue.active_count < MAX_CONCURRENT_REQUESTS) {
        pthread_cond_wait(&request_queue.cond, &request_queue.lock);
    }

    if (request_queue.head == NULL) {
        pthread_mutex_unlock(&request_queue.lock);
        return NULL;
    }

    QueueNode *node = request_queue.head;
    request_queue.head = node->next;
    if (request_queue.head == NULL) {
        request_queue.tail = NULL;
    }

    request_queue.active_count++;
    pthread_mutex_unlock(&request_queue.lock);

    return node;
}

void* resolve_dns(void *arg) {
