    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo(node->hostname, NULL, &hints, &res) != 0) {
        perror("DNS resolution error");
        goto cleanup;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        char ipstr[INET_ADDRSTRLEN];
        inet_ntop(p->ai_family, get_in_addr((struct sockaddr *)p->ai_addr), ipstr, sizeof(ipstr));

        // Example processing
        printf("Resolved IP: %s\n", ipstr);
    }

cleanup:
    freeaddrinfo(res);

    pthread_mutex_lock(&request_queue.lock);
    request_queue.active_count--;
    pthread_cond_signal(&request_queue.cond);
    pthread_mutex_unlock(&request_queue.lock);

    free(node->hostname); // Assuming hostname was dynamically allocated
    free(node);
    return NULL;
}

StatusCode resolve_and_process_host(const char *hostname, DnsResult *result) {
    result->ip_address = NULL;
    result->offsets = NULL;
    result->record_count = 0;
    result->records = NULL;

    enqueue_request(strdup(hostname));

    while (request_queue.active_count < MAX_CONCURRENT_REQUESTS || request_queue.head != NULL) {
        QueueNode *node = dequeue_request();
        if (!node) continue;

        pthread_t thread_id;
        pthread_create(&thread_id, NULL, resolve_dns, node);
        pthread_detach(thread_id);

        sleep(RETRY_DELAY_SECONDS); // Simulate retry delay in case of failure
    }

    return SUCCESS; // Simplified return for this example
}

