        }
    }

    pthread_mutex_unlock(&list->lock);

    if (log_buf->index >= LOG_ENTRIES) log_buf->index = 0;
    if (log_buf->count < LOG_ENTRIES) ++log_buf->count;
}

void* manage_pdu_list(void* arg) {
    PduList* list = pdu_list_create();
    LogBuffer log_buf = {.index = 0, .count = 0};
    pthread_mutex_init(&log_buf.lock, NULL);

    while (1) {
        if (!can_allocate_memory()) {
            release_resources();
            sleep(1); // Simulate waiting for resources
            continue;
        }

        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 1000; // Example tag generation
