    double *floatArray = malloc(numMetrics * sizeof(double));
    char **charStrings = malloc(numMetrics * sizeof(char *));
    Node **nodePointers = malloc(numNodes * sizeof(Node *));

    if (floatArray == NULL || charStrings == NULL || nodePointers == NULL) {
        // Handle allocation failure
        printf("Memory allocation failed\n");
        free(floatArray);
        for (int i = 0; i < numMetrics; ++i) {
            free(charStrings[i]);
        }
        free(charStrings);
        for (int i = 0; i < numNodes; ++i) {
            free(nodePointers[i]);
        }
        free(nodePointers);
        return;
    }

    // Initialize char strings and random keys for nodes
    srand(time(NULL));
    for (int i = 0; i < numMetrics; ++i) {
        charStrings[i] = malloc(256 * sizeof(char));
        if (charStrings[i] == NULL) break;
        snprintf(charStrings[i], 256, "String%d", i);

        floatArray[i] = ((double)rand() / RAND_MAX) * MAX_THROUGHPUT;
    }

    for (int i = 0; i < numNodes; ++i) {
