        // Create nodes with random keys
        nodePointers[i]->key = rand() % 1000;
        nodePointers[i]->left = nodePointers[i]->right = NULL;

        // Insertion logic for balanced binary search tree omitted for brevity
    }

    // Cleanup: Free all dynamically allocated memory
