['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

typedef struct {
    uint64_t mac_event_tag;
    uint64_t timestamp;
    size_t frame_count;
    void **frame_data; // Array of pointers to MAC_FRAME_DATA
} NetworkEvent;

typedef struct {
    NetworkEvent *events;
    size_t max_events;
    size_t current_size;
    size_t event_capacity;
    pthread_mutex_t lock;
    size_t memory_pool_size;
    size_t frame_size;
} EventManager;

EventManager *event_manager_create(size_t max_events, size_t frame_size, size_t memory_pool_size) {
    EventManager *em = (EventManager *)malloc(sizeof(EventManager));
    if (!em) return NULL;

    em->events = (NetworkEvent *)aligned_alloc(64, max_events * sizeof(NetworkEvent));
    if (!em->events) {
        free(em);
        return NULL;
    }

    em->max_events = max_events;
    em->current_size = 0;
    em->event_capacity = max_events;
    em->frame_size = frame_size;
    em->memory_pool_size = memory_pool_size;

    pthread_mutex_init(&em->lock, NULL);

    return em;
}

bool event_manager_add_event(EventManager *em, uint64_t tag, uint64_t timestamp, void **data, size_t count) {
    if (count > em->frame_size / sizeof(void *)) return false; // Frame overflow check

    pthread_mutex_lock(&em->lock);

    if (em->current_size >= em->max_events) {
        pthread_mutex_unlock(&em->lock);
        return false;
    }

    NetworkEvent *event = &em->events[em->current_size++];
    event->mac_event_tag = tag;
    event->timestamp = timestamp;
    event->frame_count = count;

    // Allocate and copy frame data
    event->frame_data = (void **)malloc(count * sizeof(void *));
    if (!event->frame_data) {
        em->current_size--;
        pthread_mutex_unlock(&em->lock);
        return false; // Memory allocation failure
    }

    for (size_t i = 0; i < count; ++i) {
        event->frame_data[i] = data[i];
    }

    pthread_mutex_unlock(&em->lock);

    // Log successful addition
    printf("Event added: tag=%llu, timestamp=%llu\n", tag, timestamp);

    return true;
}

bool event_manager_remove_event(EventManager *em, size_t index) {
    if (index >= em->current_size) return false; // Out of bounds

    pthread_mutex_lock(&em->lock);

    NetworkEvent *event = &em->events[index];

    for (size_t i = 0; i < event->frame_count; ++i) {
        free(event->frame_data[i]);
    }
    free(event->frame_data);

    memmove(&em->events[index], &em->events[index + 1],
            (em->current_size - index - 1) * sizeof(NetworkEvent));
    em->current_size--;

    pthread_mutex_unlock(&em->lock);

    // Log successful removal
    printf("Event removed at index: %zu\n", index);

    return true;
}

NetworkEvent *event_manager_get_event(EventManager *em, size_t index) {
    if (index >= em->current_size) return NULL; // Out of bounds

    pthread_mutex_lock(&em->lock);

    NetworkEvent *event = &em->events[index];

    pthread_mutex_unlock(&em->lock);

    return event;
}

void event_manager_update_config(EventManager *em, size_t max_events, size_t frame_size, size_t memory_pool_size) {
    pthread_mutex_lock(&em->lock);

    em->max_events = max_events;
    em->frame_size = frame_size;
    em->memory_pool_size = memory_pool_size;

    // Adjust event storage if needed
    if (em->current_size >= em->event_capacity) {
        NetworkEvent *new_events = (NetworkEvent *)aligned_alloc(64, max_events * sizeof(NetworkEvent));
        if (!new_events) {
            pthread_mutex_unlock(&em->lock);
            return; // Memory allocation failure
        }

        memcpy(new_events, em->events, em->current_size * sizeof(NetworkEvent));
        free(em->events);
        em->events = new_events;
        em->event_capacity = max_events;
    }

    pthread_mutex_unlock(&em->lock);

    // Log configuration update
    printf("Configuration updated: max_events=%zu, frame_size=%zu, memory_pool_size=%zu\n",
           max_events, frame_size, memory_pool_size);
}

void event_manager_destroy(EventManager *em) {
    if (!em) return;

    pthread_mutex_lock(&em->lock);

    for (size_t i = 0; i < em->current_size; ++i) {
        NetworkEvent *event = &em->events[i];
        for (size_t j = 0; j < event->frame_count; ++j) {
            free(event->frame_data[j]);
        }
        free(event->frame_data);
    }

    free(em->events);

    pthread_mutex_unlock(&em->lock);
    pthread_mutex_destroy(&em->lock);

    free(em);
}
```

This C code defines an `EventManager` for managing a list of network events. It supports thread-safe operations to add, remove, and access events, using a memory pool strategy to minimize fragmentation. The manager allows runtime configuration updates without restarts and includes error handling and logging mechanisms for robust operation in high-concurrency environments.']

