#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    int status_flag;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} Collection;

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2

void initialize_collection(Collection *collection, time_t start_time, double interval) {
    pthread_mutex_init(&collection->lock, NULL);
    collection->capacity = INITIAL_CAPACITY;
    collection->count = 0;
    collection->records = (Record *)malloc(collection->capacity * sizeof(Record));
    if (!collection->records) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < collection->capacity; ++i) {
        time_t current_time = start_time + (time_t)(interval * i);
        collection->records[i].timestamp = current_time;
        collection->records[i].status_flag = 0; // Default status flag
    }
}

void resize_collection(Collection *collection) {
    pthread_mutex_lock(&collection->lock);

    size_t new_capacity = collection->capacity * GROWTH_FACTOR;
    Record *new_records = (Record *)realloc(collection->records, new_capacity * sizeof(Record));
    if (!new_records) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }

    collection->records = new_records;
    collection->capacity = new_capacity;

    pthread_mutex_unlock(&collection->lock);
}

void add_record(Collection *collection, time_t timestamp, int status_flag) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity) {
        resize_collection(collection);
    }

    Record new_record = {timestamp, status_flag};
    collection->records[collection->count++] = new_record;

    pthread_mutex_unlock(&collection->lock);
}

void fetch_external_time(time_t *start_time, double interval) {
    // Simulate fetching time from an external source with potential latency
    time_t current_time;
    if (clock_gettime(CLOCK_REALTIME, &current_time)) {
        perror("Failed to get current time");
        exit(EXIT_FAILURE);
    }

    *start_time = current_time;
    *interval = 60; // Example interval in seconds

    // Handle network latency and other synchronization issues here
}

void cleanup_collection(Collection *collection) {
    pthread_mutex_destroy(&collection->lock);
    free(collection->records);
}

int main() {
    Collection collection;

    time_t start_time;
    double interval;

    fetch_external_time(&start_time, &interval);

    initialize_collection(&collection, start_time, interval);

    // Example of adding a record
    add_record(&collection, time(NULL), 1);

    cleanup_collection(&collection);

    return 0;
}
```

