#define MAX_STRUCTURES 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} UE_INFO;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    UE_INFO ue_info;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus[MAX_STRUCTURES];
    size_t count;
    pthread_mutex_t lock;
} PDU_List;

void initialize_list(PDU_List *list) {
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int add_pdu(PDU_List *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_STRUCTURES || !pdu) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Error: List full or invalid input
    }

    int crc_flag = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    if (crc_flag != 0 && crc_flag != 1) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Error: Invalid CRCFLAG
    }

    pdu->crc_indication.CRCFLAG = crc_flag;
    list->pdus[list->count++] = pdu;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void reset_list(PDU_List *list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        free(list->pdus[i]);
    }
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
}

void destroy_list(PDU_List *list) {
    reset_list(list);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    PDU_List list;
    initialize_list(&list);

    for (size_t i = 0; i < MAX_STRUCTURES; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            fprintf(stderr, "Memory allocation failed\n");
            break;
        }
        pdu->ue_info.RX_UE_INFORMATION_TAG = rand();
        pdu->ue_info.RNTI = rand();

        int result = add_pdu(&list, pdu);
        if (result != 0) {
            free(pdu); // Clean up on failure
        }
    }

    reset_list(&list);
    destroy_list(&list);

    return 0;
}
