    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->configs[i].identifier, new_config.identifier) == 0) {
            manager->configs[i] = new_config;
            pthread_mutex_unlock(&manager->lock);
            return 0; // Updated existing config
        }
    }

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        LTEPHY_TransportChannelConfig *new_configs = (LTEPHY_TransportChannelConfig *)realloc(manager->configs, new_capacity * sizeof(LTEPHY_TransportChannelConfig));
        if (!new_configs) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }

        manager->configs = new_configs;
        manager->capacity = new_capacity;
    }

    if (manager->count < MAX_CONFIGURATIONS) {
        manager->configs[manager->count++] = new_config;
        pthread_mutex_unlock(&manager->lock);
        return 1; // Added new config
    } else {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Exceeded maximum configurations
    }
