['Below is a C implementation of a function to initialize and populate a doubly-linked list of `PacketData` structures. The code includes memory allocation, linking logic, error handling, and mechanisms for freeing allocated memory.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct PacketData {
    int PacketIdentifier;
    time_t Timestamp;
    size_t DataLength;

    struct PacketData* prev;
    struct PacketData* next;
} PacketData;

typedef struct DoublyLinkedList {
    PacketData* head;
    PacketData* tail;
    pthread_mutex_t lock;  // For thread-safe operations
} DoublyLinkedList;

DoublyLinkedList* create_doubly_linked_list() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) {
        perror("Failed to allocate memory for the list");
        return NULL;
    }
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

PacketData* create_packet(int identifier, time_t timestamp, size_t data_length) {
    PacketData* packet = (PacketData*)malloc(sizeof(PacketData));
    if (!packet) {
        perror("Failed to allocate memory for a packet");
        return NULL;
    }
    packet->PacketIdentifier = identifier;
    packet->Timestamp = timestamp;
    packet->DataLength = data_length;
    packet->prev = NULL;
    packet->next = NULL;
    return packet;
}

void add_packet(DoublyLinkedList* list, PacketData* packet) {
    if (!list || !packet) return;

    pthread_mutex_lock(&list->lock);

    if (list->tail) {
        // Link new packet at the end of the list
        list->tail->next = packet;
        packet->prev = list->tail;
        list->tail = packet;
    } else {
        // Initialize the list with the first packet
        list->head = packet;
        list->tail = packet;
    }

    pthread_mutex_unlock(&list->lock);
}

void free_packet_list(DoublyLinkedList* list) {
    if (!list) return;

    PacketData* current = list->head;
    while (current) {
        PacketData* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example function to demonstrate adding packets
void populate_list(DoublyLinkedList* list, int count) {
    for (int i = 0; i < count; ++i) {
        PacketData* packet = create_packet(i, time(NULL), sizeof(int) * 100); // Example values
        if (!packet) continue;

        add_packet(list, packet);

        // Simulate retry mechanism for transient failures
        int retries = 3;
        while (retries > 0 && !list->tail) {
            printf("Transient error detected. Retrying...\n");
            add_packet(list, packet);
            --retries;
        }
    }
}

int main() {
    DoublyLinkedList* list = create_doubly_linked_list();
    if (!list) return EXIT_FAILURE;

    populate_list(list, 1000); // Example usage

    free_packet_list(list);

    return EXIT_SUCCESS;
}
```

### Key Features:
- **Thread Safety**: Uses `pthread_mutex_t` to ensure that operations on the list are thread-safe.
- **Error Handling**: Checks for memory allocation failures and prints errors using `perror`.
- **Memory Management**: Frees all allocated packets and the list structure properly.
- **Scalability Considerations**: Designed with locks to allow concurrent access without data corruption.']

