#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <errno.h>

// Define record structure
typedef struct {
    int value;
} Record;

// Linked list node for managing records
typedef struct Node {
    Record *record;
    struct Node *next;
} Node;

// Custom memory pool allocator context
typedef struct {
    size_t block_size;
    size_t total_blocks;
    void **free_list;
    pthread_mutex_t lock;
} MemoryPool;

// Dynamic arrays and linked list structure
typedef struct {
    long *offsets;
    int *keys;
    Record **records;
    Node *head;
    pthread_rwlock_t rwlock; // For thread-safe access to records and linked list
    size_t max_records;
    size_t current_records;
} DataStructure;

// Function declarations
MemoryPool* create_memory_pool(size_t block_size, size_t total_blocks);
void free_memory_pool(MemoryPool *pool);
void* pool_alloc(MemoryPool *pool);
void pool_free(MemoryPool *pool, void *ptr);

DataStructure* initialize_data_structure(size_t max_records, int min_range, int max_range);
void cleanup_data_structure(DataStructure *ds, MemoryPool *pool);
int add_record(DataStructure *ds, MemoryPool *pool, int key);
Node* find_record(DataStructure *ds, int key);

// Thread-safe custom memory pool allocator
MemoryPool* create_memory_pool(size_t block_size, size_t total_blocks) {
    if (block_size == 0 || total_blocks == 0) return NULL;

    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pthread_mutex_init(&pool->lock, NULL);
    pool->block_size = block_size;
    pool->total_blocks = total_blocks;
    pool->free_list = (void**)calloc(total_blocks, sizeof(void*));

    char *memory = (char*)malloc(block_size * total_blocks);
    if (!memory) {
        free(pool->free_list);
        free(pool);
        return NULL;
    }

    for (size_t i = 0; i < total_blocks; ++i) {
        pool->free_list[i] = memory + i * block_size;
    }

    pthread_mutex_lock(&pool->lock);
    // Pre-fill the free list
    for (size_t i = 1; i < total_blocks; ++i) {
        *(void**)(memory + (i - 1) * block_size) = pool->free_list[i];
    }
    *(void**)(memory + (total_blocks - 1) * block_size) = NULL;
    pthread_mutex_unlock(&pool->lock);

    return pool;
}

void free_memory_pool(MemoryPool *pool) {
    if (!pool) return;

    pthread_mutex_destroy(&pool->lock);
    free(pool->free_list);
    free(pool);
}

void* pool_alloc(MemoryPool *pool) {
    if (!pool) return NULL;

    pthread_mutex_lock(&pool->lock);
    void *block = pool->free_list[0];
    if (block == NULL) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Out of memory
    }

    void **next_block = (void**)block;
    pool->free_list[0] = *next_block;
    pthread_mutex_unlock(&pool->lock);

    return block;
}

void pool_free(MemoryPool *pool, void *ptr) {
    if (!pool || !ptr) return;

    pthread_mutex_lock(&pool->lock);
    *(void**)ptr = pool->free_list[0];
    pool->free_list[0] = ptr;
    pthread_mutex_unlock(&pool->lock);
}

// Initialize data structures
DataStructure* initialize_data_structure(size_t max_records, int min_range, int max_range) {
    if (max_records == 0 || min_range > max_range) return NULL;

    DataStructure *ds = (DataStructure*)malloc(sizeof(DataStructure));
    if (!ds) return NULL;

    pthread_rwlock_init(&ds->rwlock, NULL);
    ds->offsets = (long*)calloc(max_records, sizeof(long));
    ds->keys = (int*)calloc(max_records, sizeof(int));
    ds->records = (Record**)calloc(max_records, sizeof(Record*));
    ds->head = NULL;
    ds->max_records = max_records;
    ds->current_records = 0;

    if (!ds->offsets || !ds->keys || !ds->records) {
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        pthread_rwlock_destroy(&ds->rwlock);
        free(ds);
        return NULL;
    }

    // Seed random number generator
    srand(time(NULL));

    return ds;
}

// Cleanup data structures and memory pool
void cleanup_data_structure(DataStructure *ds, MemoryPool *pool) {
    if (!ds || !pool) return;

    pthread_rwlock_wrlock(&ds->rwlock);
    Node *current = ds->head;
    while (current) {
        Node *temp = current;
        current = current->next;
        pool_free(pool, temp->record);
        free(temp);
    }
    pthread_rwlock_unlock(&ds->rwlock);

    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    pthread_rwlock_destroy(&ds->rwlock);
    free(ds);
}

// Add a record to the data structure
int add_record(DataStructure *ds, MemoryPool *pool, int key) {
    if (!ds || !pool) return -1;

    pthread_rwlock_wrlock(&ds->rwlock);

    if (ds->current_records >= ds->max_records) {
        pthread_rwlock_unlock(&ds->rwlock);
        return -1; // Max records reached
    }

    Record *new_record = (Record*)pool_alloc(pool);
    if (!new_record) {
        pthread_rwlock_unlock(&ds->rwlock);
        return -1; // Memory allocation failure
    }

    new_record->value = rand() % (key_range + 1 - min_range) + min_range;

    Node *new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pool_free(pool, new_record);
        pthread_rwlock_unlock(&ds->rwlock);
        return -1; // Memory allocation failure
    }

    new_node->record = new_record;
    new_node->next = ds->head;
    ds->head = new_node;

    int index = ds->current_records++;
    ds->keys[index] = key;
    ds->records[index] = new_record;

    pthread_rwlock_unlock(&ds->rwlock);

    return 0; // Success
}

// Find a record by key
Node* find_record(DataStructure *ds, int key) {
    if (!ds) return NULL;

    pthread_rwlock_rdlock(&ds->rwlock);
    for (size_t i = 0; i < ds->current_records; ++i) {
        if (ds->keys[i] == key) {
            Node *node = (Node*)malloc(sizeof(Node));
            node->record = ds->records[i];
            node->next = NULL;
            pthread_rwlock_unlock(&ds->rwlock);
            return node;
        }
    }

    pthread_rwlock_unlock(&ds->rwlock);

    return NULL; // Record not found
}

int main() {
    size_t max_records = 1000; // Example limit, can be configurable
    int min_range = 1;
    int max_range = 100;

    MemoryPool *pool = create_memory_pool(sizeof(Record), max_records);
    if (!pool) {
        fprintf(stderr, "Failed to create memory pool\n");
        return EXIT_FAILURE;
    }

    DataStructure *ds = initialize_data_structure(max_records, min_range, max_range);
    if (!ds) {
        fprintf(stderr, "Failed to initialize data structure\n");
        free_memory_pool(pool);
        return EXIT_FAILURE;
    }

    // Example usage
    for (int i = 0; i < 10; ++i) {
        int key = rand() % 100 + 1; // Random key example
        if (add_record(ds, pool, key) != 0) {
            fprintf(stderr, "Failed to add record\n");
        }
    }

    Node *found_node = find_record(ds, 50); // Example search for key 50
    if (found_node && found_node->record) {
        printf("Found record with value: %d\n", found_node->record->value);
        free(found_node); // Clean up node after use
    } else {
        printf("Record not found\n");
    }

    cleanup_data_structure(ds, pool);
    free_memory_pool(pool);

    return EXIT_SUCCESS;
}
