// Helper function to find and print the median value.
int findMedian(int *arr, int n) {
    if (n == 0) return -1; // Edge case for empty array

    qsort(arr, n, sizeof(int), (int (*)(const void *, const void *))strcmp);

    if (n % 2 != 0)
        return arr[n / 2];
    else
        return (arr[(n - 1) / 2] + arr[n / 2]) / 2;
}

// Comparison function for qsort.
int compareInts(const void *a, const void *b) {
    int keyA = *(const int *)a;
    int keyB = *(const int *)b;

    return (keyA > keyB) - (keyA < keyB);
}

void processAndSortRecords(int fd) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    const size_t max_records = 10000000; // Max records supported
    size_t num_records = 0;
    int read_size;

    long *offsets = NULL;
    int *keys = NULL;
