    keys = malloc(max_records * sizeof(int));
    records = malloc(max_records * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(records);
        pthread_mutex_unlock(&lock);
        return;
    }

    log_allocation(max_records * sizeof(long));
    log_allocation(max_records * sizeof(int));
