        offsets[i] = rand() % 100000;
        keys[i] = rand() % 100000;

        if ((read_size = read(fd, &records[i].value, sizeof(int))) != sizeof(int)) {
            // Handle potential partial reads.
            break;
        }
        num_records++;
    }

    // Sort records based on the key values.
    qsort(keys, num_records, sizeof(int), compareInts);
    for (size_t i = 0; i < num_records; ++i) {
        int index = -1;
        for (size_t j = 0; j < num_records; ++j) {
            if (keys[j] == keys[i]) {
                index = j;
                break;
            }
        }

        // Assuming `offsets` are used to map records appropriately after sorting.
    }

    // Find and print median of the read values.
    pthread_mutex_lock(&lock);
    int median = findMedian((int *)records, num_records);
    printf("Median value: %d\n", median);
    pthread_mutex_unlock(&lock);

    // Free allocated memory with logging
