```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <dirent.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>

typedef struct Record {
    int field_int;
    long field_long;
    double field_double;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
    struct Node* prev;
} Node;

Node* create_node(Record data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        perror("Failed to allocate memory for a new node");
        exit(EXIT_FAILURE);
    }
    node->data = data;
    node->next = NULL;
    node->prev = NULL;
    return node;
}

void free_list(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

Record generate_random_record() {
    Record record;
    record.field_int = rand() % 100; // Example range [0, 99]
    record.field_long = rand() % 1000000000L; // Example range
    record.field_double = ((double)rand() / RAND_MAX) * 100.0; // Example range [0.0, 100.0]
    return record;
}

int clear_directory(const char* dir_path) {
    DIR* dir = opendir(dir_path);
    if (!dir) {
        perror("Failed to open directory");
        return -1;
    }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char path[1024];
        snprintf(path, sizeof(path), "%s/%s", dir_path, entry->d_name);

        struct stat st;
        if (stat(path, &st) != 0) {
            perror("Failed to get file status");
            closedir(dir);
            return -1;
        }

        if (S_ISDIR(st.st_mode))
            clear_directory(path);
        else
            remove(path);
    }
    closedir(dir);
    return 0;
}

int check_and_clear_dir(const char* dir_path) {
    struct stat st;
    if (stat(dir_path, &st) == 0 && S_ISDIR(st.st_mode)) {
        return clear_directory(dir_path);
    } else {
        mkdir(dir_path, 0777); // Create directory if it doesn't exist
        return 0; // Nothing to clear if it's not a directory
    }
}

void monitor_memory_usage() {
    FILE* pipe = popen("free -h | grep 'Mem:'", "r");
    if (!pipe) return;

    char buffer[128];
    while (fgets(buffer, sizeof(buffer), pipe)) {
        printf("%s", buffer); // Log the memory usage
    }
    pclose(pipe);
}

void execute_command(const char* command, const char* envp[], const char* working_dir) {
    int retry_count = 3;
    FILE* file = fopen("lockfile.lock", "r");

    if (file) {
        fclose(file);
        remove("lockfile.lock");
    }

    while (retry_count--) {
        FILE* fp = popen(command, "w");
        if (!fp) continue;

        // Execute the command
        pclose(fp);

        break;  // Exit loop if successful
    }

    if (retry_count == 0) {
        fprintf(stderr, "Failed to execute command after retries\n");
    }
}

void setup_and_monitor() {
    const char* dir_path = "./data";

    if (check_and_clear_dir(dir_path)) {
        fprintf(stderr, "Error clearing directory\n");
        exit(EXIT_FAILURE);
    }

    srand((unsigned int)time(NULL));

    long* offset_array = (long*)malloc(100 * sizeof(long)); // Example size
    int* keys_array = (int*)malloc(100 * sizeof(int));
    double* float_numbers = (double*)malloc(100 * sizeof(double));

    if (!offset_array || !keys_array || !float_numbers) {
        perror("Failed to allocate memory for arrays");
        free(offset_array);
        free(keys_array);
        free(float_numbers);
        exit(EXIT_FAILURE);
    }

    Node* head = NULL;
    for (int i = 0; i < 100; ++i) { // Example size
        Record record = generate_random_record();
        Node* node = create_node(record);

        if (!head) {
            head = node;
        } else {
            Node* temp = head;
            while (temp->next) temp = temp->next;
            temp->next = node;
            node->prev = temp;
        }
    }

    const char* command = "echo 'System check'"; // Example command
    execute_command(command, NULL, dir_path);

    monitor_memory_usage();

    free_list(head);
    free(offset_array);
    free(keys_array);
    free(float_numbers);
}

int main() {
    setup_and_monitor();
    return 0;
}
```

