void rate_limit_check() {
    struct timeval current_time;
    gettimeofday(&current_time, NULL);

    if (structures_created > 0) {
        long seconds = (current_time.tv_sec - last_time.tv_sec);
        if (seconds == 0 && structures_created >= MAX_STRUCTS_PER_SEC) {
            sleep(1); // Delay to maintain rate limit
        } else if (seconds > 0) {
            structures_created = 0;
            gettimeofday(&last_time, NULL);
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T* get_memory_from_pool() {
    pthread_mutex_lock(&mutex);
    if (available_indices[0] != -1) {
        int index = available_indices[0];
        for (int i = 1; i < POOL_SIZE; ++i) {
            available_indices[i-1] = available_indices[i];
        }
        available_indices[POOL_SIZE-1] = -1;
        pthread_mutex_unlock(&mutex);
        return memory_pool[index];
    } else {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
}

void return_memory_to_pool(NFAPI_CRC_INDICATION_PDU_T* struct_ptr) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < POOL_SIZE; ++i) {
        if (available_indices[i] == -1) {
            available_indices[i] = i;
            memory_pool[i] = struct_ptr;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

