            if (available_indices[index] != -1) {
                pdu = *(memory_pool[available_indices[index]]);
                fwrite(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
                available_indices[index] = -1; // Mark as used
            }
        } else {
