#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

typedef struct {
    uint64_t mac_event_tag;
    uint64_t timestamp;
    size_t frame_count;
} MAC_EVENT_HEADER;

typedef struct {
    void* data;
    size_t length;
} MAC_FRAME_DATA;

typedef struct EventNode {
    MAC_EVENT_HEADER header;
    MAC_FRAME_DATA* frames;
    struct EventNode* next;
} EventNode;

typedef struct {
    EventNode* head;
    EventNode* tail;
    pthread_mutex_t lock; // For thread-safe writes
    size_t event_count;
} EventList;

// Function prototypes
EventList* create_event_list();
int add_event(EventList* list, uint64_t mac_event_tag, uint64_t timestamp, MAC_FRAME_DATA* frames, size_t frame_count);
void process_events(EventList* list, int reverse, void (*callback)(MAC_EVENT_HEADER*, MAC_FRAME_DATA*, size_t));
void free_event_list(EventList** list);

// Helper functions
static EventNode* create_node(uint64_t mac_event_tag, uint64_t timestamp, MAC_FRAME_DATA* frames, size_t frame_count);
static void destroy_node(EventNode* node);

EventList* create_event_list() {
    EventList* list = (EventList*)malloc(sizeof(EventList));
    if (!list) return NULL;
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->event_count = 0;
    return list;
}

int add_event(EventList* list, uint64_t mac_event_tag, uint64_t timestamp, MAC_FRAME_DATA* frames, size_t frame_count) {
    if (!list || !frames || frame_count == 0) return -1;

    pthread_mutex_lock(&list->lock);

    EventNode* new_node = create_node(mac_event_tag, timestamp, frames, frame_count);
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->event_count++;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

static EventNode* create_node(uint64_t mac_event_tag, uint64_t timestamp, MAC_FRAME_DATA* frames, size_t frame_count) {
    EventNode* node = (EventNode*)malloc(sizeof(EventNode));
    if (!node) return NULL;

    node->header.mac_event_tag = mac_event_tag;
    node->header.timestamp = timestamp;
    node->header.frame_count = frame_count;

    node->frames = (MAC_FRAME_DATA*)malloc(frame_count * sizeof(MAC_FRAME_DATA));
    if (!node->frames) {
        free(node);
        return NULL;
    }

    for (size_t i = 0; i < frame_count; ++i) {
        node->frames[i].data = frames[i].data;
        node->frames[i].length = frames[i].length;
    }

    node->next = NULL;
    return node;
}

void process_events(EventList* list, int reverse, void (*callback)(MAC_EVENT_HEADER*, MAC_FRAME_DATA*, size_t)) {
    if (!list || !callback) return;

    pthread_mutex_lock(&list->lock);

    EventNode* current = reverse ? list->tail : list->head;
    while (current) {
        callback(&current->header, current->frames, current->header.frame_count);
        current = reverse ? current->next == NULL ? list->head : current->next : current->next == NULL ? list->tail : current->prev;
    }

    pthread_mutex_unlock(&list->lock);
}

void free_event_list(EventList** list) {
    if (!list || !*list) return;

    EventNode* node = (*list)->head;
    while (node) {
        EventNode* next_node = node->next;
        destroy_node(node);
        node = next_node;
    }

    pthread_mutex_destroy(&(*list)->lock);
    free(*list);
    *list = NULL;
}

static void destroy_node(EventNode* node) {
    if (!node) return;

    free(node->frames);
    free(node);
}
```

