    Node** buckets;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(size_t size) {
    HashTable* table = malloc(sizeof(HashTable));
    table->buckets = calloc(size, sizeof(Node*));
    table->size = size;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void free_node(Node* node) {
    if (node) {
        free(node);
    }
}

void free_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->size; ++i) {
        Node* current = table->buckets[i];
        while (current) {
            Node* temp = current;
            current = current->next;
            free_node(temp);
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

unsigned long custom_hash(int key, size_t hash_size) {
    return ((unsigned long)key * 2654435761u) % hash_size;
}

void resize_hash_table(HashTable* table);

int add_to_hash_table(HashTable* table, int key, long offset) {
    pthread_mutex_lock(&table->lock);

    unsigned long index = custom_hash(key, table->size);
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&table->lock);
        return -1; // Memory allocation failed
    }
    new_node->key = key;
    new_node->offset = offset;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;

    if (pthread_mutex_trylock(&table->lock) == 0) { // Check load factor for resizing
        pthread_mutex_unlock(&table->lock);

        size_t count = 0;
        for (size_t i = 0; i < table->size; ++i) {
            Node* current = table->buckets[i];
            while (current) {
                ++count;
                current = current->next;
            }
        }

        if ((float)count / table->size > 0.7f) { // Load factor threshold
            resize_hash_table(table);
        }

        pthread_mutex_lock(&table->lock);
    }

    pthread_mutex_unlock(&table->lock);
    return 0; // Success
}

void resize_hash_table(HashTable* table) {
    size_t new_size = table->size * 2;
    Node** new_buckets = calloc(new_size, sizeof(Node*));

    for (size_t i = 0; i < table->size; ++i) {
        Node* current = table->buckets[i];
        while (current) {
            Node* next_node = current->next;
            unsigned long index = custom_hash(current->key, new_size);
            current->next = new_buckets[index];
            new_buckets[index] = current;
            current = next_node;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->size = new_size;
}

int manage_memory_and_initialize(long* offsets, int* keys, Record* records, size_t num_keys) {
    HashTable* hash_table = create_hash_table(INITIAL_HASH_SIZE);

    for (size_t i = 0; i < num_keys; ++i) {
        if (!keys || !offsets || !records) {
            free_hash_table(hash_table);
            return -1; // Invalid pointers
        }

        offsets[i] = rand(); // Simulate offset generation
        keys[i] = rand() % MAX_RECORDS;

        if (add_to_hash_table(hash_table, keys[i], offsets[i]) != 0) {
            free_hash_table(hash_table);
            return -2; // Failed to add key-offset pair
        }

        records[i].value = rand() % 100; // Simulate record value assignment within range
    }

    free_hash_table(hash_table);
    return 0; // Success
}
