#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    float value;
} Record;

#define SUCCESS 0
#define ALLOCATION_FAILURE -1

// Mutex for thread-safe operations
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
int initialize_and_sort_records(Record **records, size_t num_records, 
                                long offset_min, long offset_max, 
                                int key_min, int key_max, 
                                float value_min, float value_max);
void deallocate_memory(Record *records);

// Helper function to swap two records
void swap_records(Record *a, Record *b) {
    Record temp = *a;
    *a = *b;
    *b = temp;
}

int initialize_and_sort_records(Record **records, size_t num_records,
                                long offset_min, long offset_max, 
                                int key_min, int key_max, 
                                float value_min, float value_max) {
    if (pthread_mutex_lock(&mutex)) {
        return ALLOCATION_FAILURE;
    }

    // Allocate memory for records
    *records = malloc(num_records * sizeof(Record));
    if (*records == NULL) {
        pthread_mutex_unlock(&mutex);
        return ALLOCATION_FAILURE;
    }

    srand(time(NULL));  // Seed the random number generator

    // Initialize records with random values
    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].offset = offset_min + rand() % (offset_max - offset_min + 1);
        (*records)[i].key = key_min + rand() % (key_max - key_min + 1);
        (*records)[i].value = value_min + ((float)rand() / RAND_MAX) * (value_max - value_min);
    }

    // Sort records by key using quicksort
    int left = 0;
    int right = num_records - 1;

    void quicksort(int l, int r) {
        if (l >= r) return;
        Record pivot = (*records)[(l + r) / 2];
        int i = l, j = r;

        while (i <= j) {
            while ((*records)[i].key < pivot.key) ++i;
            while ((*records)[j].key > pivot.key) --j;
            if (i <= j) swap_records(&(*records)[i], &(*records)[j]), i++, j--;
        }

        quicksort(l, j);
        quicksort(i, r);
    }

    quicksort(left, right);

    pthread_mutex_unlock(&mutex);
    return SUCCESS;
}

void deallocate_memory(Record *records) {
    if (pthread_mutex_lock(&mutex)) {
        return;  // Handle lock failure as needed
    }

    free(records);

    pthread_mutex_unlock(&mutex);
}
```

This code implements a C function to manage memory for a dynamic dataset of records, ensuring thread safety using mutexes. It initializes each record with random values within specified ranges and sorts them by their key values using quicksort. Memory allocation failures are handled gracefully, returning a specific error code. The function also includes mechanisms to deallocate the allocated memory safely.']

