import <string.h>

#define MAX_REQUESTS 100000
#define MIN_CQI 0
#define MAX_CQI 15

typedef struct {
    int identifier;
    int cqi;
    char grantInfoTag[256];
} PDCCHRequest;

typedef struct {
    PDCCHRequest *requests;
    size_t count;
    size_t capacity;
} RequestList;

void init_request_list(RequestList *list) {
    list->count = 0;
    list->capacity = MAX_REQUESTS;
    list->requests = (PDCCHRequest *)malloc(sizeof(PDCCHRequest) * list->capacity);
}

int add_request(RequestList *list, int identifier, int cqi, const char *grantInfoTag) {
    if (cqi < MIN_CQI || cqi > MAX_CQI) return -1;
    if (list->count >= list->capacity) return -2;

    PDCCHRequest new_request = {identifier, cqi, ""};
    strncpy(new_request.grantInfoTag, grantInfoTag, sizeof(new_request.grantInfoTag));

    list->requests[list->count++] = new_request;
    return 0;
}

int serialize_requests(const RequestList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    size_t write_size = fwrite(list->requests, sizeof(PDCCHRequest), list->count, file);
    fclose(file);

    return (write_size == list->count) ? 0 : -2;
}

int deserialize_requests(RequestList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    PDCCHRequest buffer[MAX_REQUESTS];
    size_t read_size = fread(buffer, sizeof(PDCCHRequest), MAX_REQUESTS, file);
    fclose(file);

    list->count = read_size;
    list->capacity = read_size < MAX_REQUESTS ? MAX_REQUESTS : read_size;
    list->requests = (PDCCHRequest *)realloc(list->requests, list->capacity * sizeof(PDCCHRequest));
    memcpy(list->requests, buffer, read_size * sizeof(PDCCHRequest));

    return 0;
}

void free_request_list(RequestList *list) {
    free(list->requests);
    list->count = 0;
    list->capacity = 0;
}

// Additional functions for external data fetching and error handling could be added here.

int main() {
    RequestList list;
    init_request_list(&list);

    // Example usage
    if (add_request(&list, 1, 10, "Grant Info A") == 0) {
        printf("Request added successfully.\n");
    }

    if (serialize_requests(&list, "requests.dat") == 0) {
        printf("Requests serialized successfully.\n");
    }

    RequestList newList;
    init_request_list(&newList);

    if (deserialize_requests(&newList, "requests.dat") == 0) {
        printf("Requests deserialized successfully.\n");
    }

    free_request_list(&list);
    free_request_list(&newList);

    return 0;
}
