    if (!file) return -1;

    while (head) {
        fwrite(&head->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        head = head->next;
    }

    fclose(file);
    return 0;
}

void* thread_function(void *arg) {
