#define MAX_FRAMES 10000
#define LOG_FILE_SIZE (24 * 60 * 60) // Assuming log file size of one day for rotation

typedef struct {
    uint64_t mac_event_tag;
    time_t timestamp;
} MAC_EVENT;

typedef struct {
    char* data;
    size_t length;
    int type;
} MAC_FRAME_DATA;

typedef struct Node {
    MAC_EVENT event;
    MAC_FRAME_DATA frames[MAX_FRAMES];
    int frame_count;
    pthread_mutex_t lock;
    struct Node* next;
} ListElement;

typedef struct {
    ListElement* head;
    pthread_mutex_t list_lock;
    int frame_add_count;
    int frame_remove_count;
    int frame_access_count;
    FILE* log_file;
    time_t last_gc_time;
    int gc_interval_minutes; // Time in minutes for garbage collection interval
} EventList;

void initialize_event_list(EventList* event_list, int gc_interval) {
    pthread_mutex_init(&event_list->list_lock, NULL);
    event_list->head = NULL;
    event_list->frame_add_count = 0;
    event_list->frame_remove_count = 0;
    event_list->frame_access_count = 0;

    // Open log file
    event_list->log_file = fopen("event_log.txt", "a");

    event_list->gc_interval_minutes = gc_interval;
    event_list->last_gc_time = time(NULL);
}

void log_event(const char* message, EventList* event_list) {
    pthread_mutex_lock(&event_list->list_lock);
    fprintf(event_list->log_file, "%s\n", message);
    if (ftell(event_list->log_file) > LOG_FILE_SIZE) {
        fclose(event_list->log_file);
        rename("event_log.txt", "event_log_oldest.txt");
        event_list->log_file = fopen("event_log.txt", "w");
    }
    pthread_mutex_unlock(&event_list->list_lock);
}

void add_frame(EventList* event_list, MAC_EVENT event, MAC_FRAME_DATA frame) {
    pthread_mutex_lock(&event_list->list_lock);

    ListElement* current = event_list->head;
    while (current && current->next) {
        current = current->next;
    }

    if (!current || current->frame_count >= MAX_FRAMES) {
        ListElement* new_node = malloc(sizeof(ListElement));
        pthread_mutex_init(&new_node->lock, NULL);
        *new_node = (ListElement){ .event = event, .frame_count = 0, .next = NULL };

        if (current) current->next = new_node;
        else event_list->head = new_node;

        current = new_node;
    }

    pthread_mutex_lock(&current->lock);

    if (current->frame_count < MAX_FRAMES) {
        current->frames[current->frame_count++] = frame;
        event_list->frame_add_count++;
        log_event("Frame added", event_list);
    } else {
        log_event("Buffer overflow condition detected", event_list);
    }

    pthread_mutex_unlock(&current->lock);

    pthread_mutex_unlock(&event_list->list_lock);
}

void garbage_collect(EventList* event_list) {
    time_t current_time = time(NULL);
    if (difftime(current_time, event_list->last_gc_time) >= event_list->gc_interval_minutes * 60) {
        ListElement* current = event_list->head;
        while (current) {
            pthread_mutex_lock(&current->lock);

            // Implement garbage collection logic here

            pthread_mutex_unlock(&current->lock);

            current = current->next;
        }

        event_list->last_gc_time = current_time;
    }
}

void destroy_event_list(EventList* event_list) {
    ListElement* current = event_list->head;

    while (current) {
        ListElement* to_free = current;
        current = current->next;

        pthread_mutex_lock(&to_free->lock);

        free(to_free->frames);
        pthread_mutex_unlock(&to_free->lock);

        pthread_mutex_destroy(&to_free->lock);
        free(to_free);
    }

    pthread_mutex_unlock(&event_list->list_lock);
    fclose(event_list->log_file);
}

// Implement other necessary functions, including the web interface update mechanism,
// secure authentication, and third-party timestamp synchronization
// as described in the task.

int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <gc_interval_minutes>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int gc_interval = atoi(argv[1]);

    EventList event_list;
    initialize_event_list(&event_list, gc_interval);

    // Add frames and perform operations

    destroy_event_list(&event_list);
    return 0;
}
