#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_SIZE 16

typedef enum {
    STATUS_OK,
    STATUS_ERROR,
    // Add other statuses as needed
} enum_status;

typedef struct element {
    float f;
    int i;
    _Bool b;
    enum_status *status;
} struct_element;

typedef struct hash_node {
    char key[256];
    void *data;
    struct hash_node *next;
} hash_node_t;

typedef struct hash_table {
    size_t size;
    hash_node_t **buckets;
    pthread_mutex_t lock;
} hash_table_t;

hash_table_t* create_hash_table(size_t initial_size) {
    hash_table_t *table = malloc(sizeof(hash_table_t));
    if (!table) return NULL;

    table->size = initial_size;
    table->buckets = calloc(table->size, sizeof(hash_node_t *));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    pthread_mutex_init(&table->lock, NULL);
    return table;
}

unsigned long hash_function(const char *key) {
    unsigned long hash = 5381;
    int c;

    while ((c = *key++))
        hash = ((hash << 5) + hash) + c;

    return hash;
}

void resize_hash_table(hash_table_t *table);

void insert(hash_table_t *table, const char *key, void *data) {
    pthread_mutex_lock(&table->lock);

    unsigned long index = hash_function(key) % table->size;
    hash_node_t *node = malloc(sizeof(hash_node_t));
    if (!node) {
        pthread_mutex_unlock(&table->lock);
        return;
    }

    strncpy(node->key, key, sizeof(node->key) - 1);
    node->data = data;
    node->next = table->buckets[index];
    table->buckets[index] = node;

    // Consider resizing the hash table if needed
    resize_hash_table(table);

    pthread_mutex_unlock(&table->lock);
}

void* lookup(hash_table_t *table, const char *key) {
    unsigned long index = hash_function(key) % table->size;

    pthread_mutex_lock(&table->lock);
    for (hash_node_t *node = table->buckets[index]; node; node = node->next) {
        if (strcmp(node->key, key) == 0) {
            pthread_mutex_unlock(&table->lock);
            return node->data;
        }
    }

    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void delete(hash_table_t *table, const char *key) {
    unsigned long index = hash_function(key) % table->size;

    pthread_mutex_lock(&table->lock);
    hash_node_t **node_ptr = &table->buckets[index];

    while (*node_ptr) {
        if (strcmp((*node_ptr)->key, key) == 0) {
            hash_node_t *to_delete = *node_ptr;
            *node_ptr = to_delete->next;
            free(to_delete);
            break;
        }
        node_ptr = &(*node_ptr)->next;
    }

    pthread_mutex_unlock(&table->lock);
}

void resize_hash_table(hash_table_t *table) {
    size_t new_size = table->size * 2;
    hash_node_t **new_buckets = calloc(new_size, sizeof(hash_node_t *));

    if (!new_buckets) return;

    for (size_t i = 0; i < table->size; ++i) {
        hash_node_t *node = table->buckets[i];

        while (node) {
            unsigned long new_index = hash_function(node->key) % new_size;

            hash_node_t *next_node = node->next;
            node->next = new_buckets[new_index];
            new_buckets[new_index] = node;

            node = next_node;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->size = new_size;
}

void clear_hash_table(hash_table_t *table) {
    pthread_mutex_lock(&table->lock);

    for (size_t i = 0; i < table->size; ++i) {
        hash_node_t *node = table->buckets[i];

        while (node) {
            hash_node_t *next = node->next;
            free(node);
            node = next;
        }

        table->buckets[i] = NULL;
    }

    pthread_mutex_unlock(&table->lock);
}

void serialize_hash_table(hash_table_t *table, const char *filename) {
    FILE *file = fopen(filename, "wb");

    if (!file) return;

    fwrite(&table->size, sizeof(size_t), 1, file);

    for (size_t i = 0; i < table->size; ++i) {
        hash_node_t *node = table->buckets[i];

        while (node) {
            fwrite(node->key, sizeof(char), strlen(node->key) + 1, file);

            // Assuming data is a pointer to struct_element for demonstration
            struct_element *data = node->data;
            if (data) {
                fwrite(&data->f, sizeof(float), 1, file);
                fwrite(&data->i, sizeof(int), 1, file);
                fwrite(&data->b, sizeof(_Bool), 1, file);

                enum_status *status_ptr = data->status;
                if (status_ptr) {
                    fwrite(status_ptr, sizeof(enum_status), 1, file);
                }
            }

            node = node->next;
        }
    }

    fclose(file);
}

void deserialize_hash_table(hash_table_t *table, const char *filename) {
    FILE *file = fopen(filename, "rb");

    if (!file) return;

    size_t new_size;
    fread(&new_size, sizeof(size_t), 1, file);

    clear_hash_table(table); // Clear existing data
    table->size = new_size;
    hash_node_t **new_buckets = calloc(new_size, sizeof(hash_node_t *));

    if (!new_buckets) return;

    for (size_t i = 0; i < new_size; ++i) {
        char key[256];
        size_t len = fread(key, sizeof(char), sizeof(key)-1, file);
        if (len == 0 || ferror(file)) break;

        float f;
        int i;
        _Bool b;
        enum_status status;

        fread(&f, sizeof(float), 1, file);
        fread(&i, sizeof(int), 1, file);
        fread(&b, sizeof(_Bool), 1, file);

        fread(&status, sizeof(enum_status), 1, file);

        struct_element *element = malloc(sizeof(struct_element));
        if (!element) continue;

        element->f = f;
        element->i = i;
        element->b = b;

        enum_status *enum_ptr = malloc(sizeof(enum_status));
        if (enum_ptr) {
            *enum_ptr = status;
            element->status = enum_ptr;
        }

        unsigned long index = hash_function(key) % new_size;

        hash_node_t *node = malloc(sizeof(hash_node_t));
        if (!node) {
            free(element);
            continue;
        }

        strncpy(node->key, key, sizeof(node->key)-1);
        node->data = element;
        node->next = new_buckets[index];
        new_buckets[index] = node;
    }

    free(table->buckets);
    table->buckets = new_buckets;

    fclose(file);
}

void destroy_hash_table(hash_table_t *table) {
    clear_hash_table(table);
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}
