// Configuration and compression settings
typedef struct Config {
    int cache_size;
    int use_compression;
} Config;

Config config = {10, 1};

typedef struct MAC_FRAME_DATA {
    unsigned char *data;
    size_t length;
} MAC_FRAME_DATA;

typedef struct Event {
    unsigned long mac_event_tag;
    time_t timestamp;
    MAC_FRAME_DATA *frames;
    size_t frame_count;
    struct Event *next;
} Event;

typedef struct {
    Event *head;
    pthread_mutex_t lock;
    Event **cache;
    size_t cache_size;
    size_t cache_index;
    pthread_cond_t not_empty;
} EventList;

// Initialize the event list
EventList* init_event_list(size_t initial_cache_size) {
    EventList *list = (EventList*)malloc(sizeof(EventList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->cache = (Event**)calloc(initial_cache_size, sizeof(Event*));
    list->cache_size = initial_cache_size;
    list->cache_index = 0;
    pthread_cond_init(&list->not_empty, NULL);
    return list;
}

// Add a frame to an event
int add_frame(Event *event, unsigned long mac_event_tag, time_t timestamp, MAC_FRAME_DATA *frame) {
    pthread_mutex_lock(&event->lock);

    if (event->frame_count >= 1000) { // Arbitrary limit for demonstration
        pthread_mutex_unlock(&event->lock);
        log_event("Buffer overflow condition detected");
        return -1;
    }

    event->frames = realloc(event->frames, sizeof(MAC_FRAME_DATA) * (event->frame_count + 1));
    if (!event->frames) {
        pthread_mutex_unlock(&event->lock);
        log_event("Memory allocation failed for frames");
        return -1;
    }

    event->frames[event->frame_count] = *frame;
    event->frame_count++;

    // Log the addition
    char log_message[256];
    snprintf(log_message, sizeof(log_message), "Frame added to event %lu at %ld with frame count: %zu",
             mac_event_tag, timestamp, event->frame_count);
    log_event(log_message);

    pthread_mutex_unlock(&event->lock);
    return 0;
}

// Add an event to the list
int add_event(EventList *list, unsigned long mac_event_tag, time_t timestamp, MAC_FRAME_DATA *frames, size_t frame_count) {
    Event *new_event;

    // Try to get from cache first
    pthread_mutex_lock(&list->lock);
    if (list->cache_index < list->cache_size && list->cache[list->cache_index]) {
        new_event = list->cache[list->cache_index++];
    } else {
        new_event = malloc(sizeof(Event));
        if (!new_event) {
            pthread_mutex_unlock(&list->lock);
            log_event("Memory allocation failed for event");
            return -1;
        }
    }

    new_event->mac_event_tag = mac_event_tag;
    new_event->timestamp = timestamp;
    new_event->frames = malloc(sizeof(MAC_FRAME_DATA) * frame_count);
    if (!new_event->frames) {
        free(new_event);
        pthread_mutex_unlock(&list->lock);
        log_event("Memory allocation failed for event frames");
        return -1;
    }

    memcpy(new_event->frames, frames, sizeof(MAC_FRAME_DATA) * frame_count);
    new_event->frame_count = frame_count;
    new_event->next = list->head;
    list->head = new_event;

    pthread_cond_signal(&list->not_empty);
    pthread_mutex_unlock(&list->lock);

    // Log the event addition
    char log_message[256];
    snprintf(log_message, sizeof(log_message), "Event %lu added with %zu frames at %ld",
             mac_event_tag, frame_count, timestamp);
    log_event(log_message);

    return 0;
}

// Free resources associated with an event list
void free_event_list(EventList *list) {
    Event *current = list->head;
    while (current) {
        Event *next = current->next;
        free(current->frames);
        free(current);
        current = next;
    }
    free(list->cache);
    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->not_empty);
    free(list);
}

// Compression/decompression stubs
void compress_frame(MAC_FRAME_DATA *frame) {
    // Implement compression logic here, if config.use_compression is true
}

void decompress_frame(MAC_FRAME_DATA *frame) {
    // Implement decompression logic here, if needed
}
