#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_OFFSETS_SIZE 1000 // Maximum reasonable size for offsets array
#define MAX_KEYS_SIZE 1000    // Maximum reasonable size for keys array

typedef struct {
    char *data;
    int value;
} record;

int initialize_structures(long* offsets, int offsets_size,
                          int* keys, int keys_size,
                          record* records) {

    if (offsets_size > MAX_OFFSETS_SIZE || keys_size > MAX_KEYS_SIZE) {
        fprintf(stderr, "Error: Input sizes exceed maximum limits.\n");
        return -1;
    }

    for (int i = 0; i < keys_size; ++i) {
        if (keys[i] < 0) {
            fprintf(stderr, "Error: Keys contain a negative value.\n");
            free(offsets);
            free(keys);
            return -1;
        }
    }

    offsets = malloc(sizeof(long) * offsets_size);
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        return -1;
    }

    keys = malloc(sizeof(int) * keys_size);
    if (!keys) {
        perror("Failed to allocate memory for keys");
        free(offsets);
        return -1;
    }

    int records_size = (offsets_size < keys_size) ? offsets_size : keys_size;
    records = malloc(sizeof(record) * records_size);
    if (!records) {
        perror("Failed to allocate memory for records");
        free(offsets);
        free(keys);
        return -1;
    }

    srand(time(NULL)); // Seed the random number generator
    for (int i = 0; i < records_size; ++i) {
        records[i].data = malloc(sizeof(char) * offsets_size);
        if (!records[i].data) {
            perror("Failed to allocate memory for record data");
            free(offsets);
            free(keys);
            // Free previously allocated records
            while (i > 0) {
                free(records[--i].data);
            }
            free(records);
            return -1;
        }
        records[i].value = rand() % 101; // Random value between 0 and 100
    }

    return 0; // Success
}

void cleanup(long* offsets, int* keys, record* records, long offsets_size, int keys_size) {
    free(offsets);
    free(keys);
    if (records) {
        for (int i = 0; i < ((offsets_size < keys_size) ? offsets_size : keys_size); ++i) {
            free(records[i].data);
        }
        free(records);
    }
}

// Example usage
int main() {
    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;

    // Define sizes for offsets and keys arrays
    long offsets_size = 500; // User-defined, validate during initialization
    int keys_size = 400;     // User-defined, validate during initialization

    // Initialize the structures
    if (initialize_structures(offsets, offsets_size, keys, keys_size, records) != 0) {
        fprintf(stderr, "Failed to initialize structures.\n");
        return -1;
    }

    // Use the initialized structures...

    // Clean up allocated memory
    cleanup(offsets, keys, records, offsets_size, keys_size);

    return 0;
}
