['Below is a C implementation that fulfills the specified requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10

typedef struct {
    unsigned int mac_event_tag;
    time_t timestamp;
} MAC_EVENT_TAG;

typedef struct {
    unsigned char *data;
    size_t length;
} MAC_FRAME_DATA;

typedef struct {
    MAC_EVENT_TAG event_tag;
    time_t timestamp;
    MAC_FRAME_DATA *frames;
    size_t frame_count;
} NetworkEvent;

typedef struct {
    NetworkEvent **events;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    pthread_rwlock_t rwlock;
} EventList;

void init_event_list(EventList *list) {
    list->capacity = INITIAL_CAPACITY;
    list->size = 0;
    list->events = (NetworkEvent **)malloc(list->capacity * sizeof(NetworkEvent *));
    if (!list->events) {
        perror("Failed to allocate memory for event list");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&list->lock, NULL);
    pthread_rwlock_init(&list->rwlock, NULL);
}

void resize_event_list(EventList *list) {
    size_t new_capacity = list->capacity * 2;
    NetworkEvent **new_events = (NetworkEvent **)realloc(list->events, new_capacity * sizeof(NetworkEvent *));
    if (!new_events) {
        perror("Failed to reallocate memory for event list");
        exit(EXIT_FAILURE);
    }
    list->events = new_events;
    list->capacity = new_capacity;
}

void add_event(EventList *list, NetworkEvent *event) {
    pthread_rwlock_wrlock(&list->rwlock);

    if (list->size == list->capacity) {
        resize_event_list(list);
    }

    if (!event || event->frames == NULL) {
        fprintf(stderr, "Invalid input for adding event\n");
        pthread_rwlock_unlock(&list->rwlock);
        return;
    }

    list->events[list->size] = event;
    list->size++;

    pthread_rwlock_unlock(&list->rwlock);
}

void remove_event(EventList *list, size_t index) {
    if (index >= list->size) {
        fprintf(stderr, "Index out of bounds\n");
        return;
    }

    pthread_rwlock_wrlock(&list->rwlock);

    free(list->events[index]->frames);
    free(list->events[index]);
    memmove(&list->events[index], &list->events[index + 1], (list->size - index - 1) * sizeof(NetworkEvent *));
    list->size--;

    pthread_rwlock_unlock(&list->rwlock);
}

void cleanup_expired_events(EventList *list, time_t current_time, int expiration_seconds) {
    pthread_rwlock_wrlock(&list->rwlock);

    for (size_t i = 0; i < list->size; ) {
        if (current_time - list->events[i]->timestamp > expiration_seconds) {
            free(list->events[i]->frames);
            free(list->events[i]);
            memmove(&list->events[i], &list->events[i + 1], (list->size - i - 1) * sizeof(NetworkEvent *));
            list->size--;
        } else {
            i++;
        }
    }

    pthread_rwlock_unlock(&list->rwlock);
}

void serialize_event_list(EventList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for serialization");
        return;
    }

    pthread_rwlock_rdlock(&list->rwlock);

    fwrite(&list->size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < list->size; ++i) {
        fwrite(&list->events[i]->event_tag.mac_event_tag, sizeof(unsigned int), 1, file);
        fwrite(&list->events[i]->timestamp, sizeof(time_t), 1, file);
        fwrite(&list->events[i]->frame_count, sizeof(size_t), 1, file);
        for (size_t j = 0; j < list->events[i]->frame_count; ++j) {
            fwrite(&list->events[i]->frames[j].length, sizeof(size_t), 1, file);
            fwrite(list->events[i]->frames[j].data, list->events[i]->frames[j].length, 1, file);
        }
    }

    pthread_rwlock_unlock(&list->rwlock);
    fclose(file);
}

void deserialize_event_list(EventList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for deserialization");
        return;
    }

    size_t event_count;
    fread(&event_count, sizeof(size_t), 1, file);

    pthread_rwlock_wrlock(&list->rwlock);
    resize_event_list(list);
    list->size = event_count;

    for (size_t i = 0; i < event_count; ++i) {
        NetworkEvent *event = malloc(sizeof(NetworkEvent));
        if (!event) {
            perror("Failed to allocate memory for network event");
            fclose(file);
            pthread_rwlock_unlock(&list->rwlock);
            return;
        }

        fread(&event->event_tag.mac_event_tag, sizeof(unsigned int), 1, file);
        fread(&event->timestamp, sizeof(time_t), 1, file);

        fread(&event->frame_count, sizeof(size_t), 1, file);
        event->frames = malloc(event->frame_count * sizeof(MAC_FRAME_DATA));
        if (!event->frames) {
            perror("Failed to allocate memory for frames");
            free(event);
            fclose(file);
            pthread_rwlock_unlock(&list->rwlock);
            return;
        }

        for (size_t j = 0; j < event->frame_count; ++j) {
            fread(&event->frames[j].length, sizeof(size_t), 1, file);
            event->frames[j].data = malloc(event->frames[j].length);
            if (!event->frames[j].data) {
                perror("Failed to allocate memory for frame data");
                free(event->frames);
                free(event);
                fclose(file);
                pthread_rwlock_unlock(&list->rwlock);
                return;
            }
            fread(event->frames[j].data, event->frames[j].length, 1, file);
        }

        list->events[i] = event;
    }

    pthread_rwlock_unlock(&list->rwlock);
    fclose(file);
}

void log_operations_per_second(EventList *list) {
    static size_t last_logged_size = 0;
    static time_t last_log_time = 0;

    time_t current_time = time(NULL);
    if (current_time - last_log_time >= 1) {
        printf("Operations per second: %zu\n", list->size - last_logged_size);
        last_logged_size = list->size;
        last_log_time = current_time;
    }
}

void cleanup(EventList *list) {
    pthread_rwlock_wrlock(&list->rwlock);

    for (size_t i = 0; i < list->size; ++i) {
        free(list->events[i]->frames);
        free(list->events[i]);
    }

    free(list->events);
    pthread_rwlock_unlock(&list->rwlock);

    pthread_mutex_destroy(&list->lock);
    pthread_rwlock_destroy(&list->rwlock);
}
```

### Key Features:
- **Thread Safety**: Uses `pthread_rwlock_t` for concurrent access, allowing multiple readers or one writer.
- **Dynamic Memory Management**: Resizes the list as needed and ensures proper memory allocation and deallocation.
- **Error Handling**: Provides error messages for invalid inputs and memory allocation failures.
- **Event Cleanup**: Removes expired events based on a configurable policy.
- **Serialization/Deserialization**: Saves and loads event data to/from disk.
- **Logging**: Logs operations per second without significantly impacting performance.

This implementation is designed to handle high concurrency, ensure data integrity, and provide robust error handling.']

