// Define a structure for Skill
struct Skill {
    int id;
    std::string name;

    Skill(int skillId, const std::string& skillName) : id(skillId), name(skillName) {}
};

class SkillManager {
public:
    SkillManager(size_t maxMemorySize)
        : maxMemorySize_(maxMemorySize),
          currentMemoryUsage_(0),
          lastUsedTime(std::unordered_map<int, std::chrono::steady_clock::time_point>()) {}

    // Function to select and execute a skill
    Skill* selectAndExecuteSkill(int skillId) {
        std::shared_lock lock(mutex_);

        auto now = std::chrono::steady_clock::now();
        if (lastUsedTime.count(skillId) &&
            std::chrono::duration_cast<std::chrono::seconds>(now - lastUsedTime[skillId]).count() < 10) {
            return nullptr; // Skill is on cooldown
        }

        auto it = skills_.find(skillId);
        if (it != skills_.end()) {
            lock.unlock();
            std::unique_lock ulock(mutex_);
            lastUsedTime[skillId] = now;
            std::cout << "Executing skill ID: " << it->second.id << ", Name: " << it->second.name << std::endl;

            return &it->second;
        }
        return nullptr;
    }

    // Function to add a new skill
    bool addSkill(int id, const std::string& name) {
        std::unique_lock lock(mutex_);

        if (currentMemoryUsage_ + sizeof(Skill) > maxMemorySize_) {
            return false; // Not enough memory
        }

        skills_[id] = Skill(id, name);
        currentMemoryUsage_ += sizeof(Skill);

        return true;
    }

private:
    size_t maxMemorySize_;
    size_t currentMemoryUsage_;
    std::unordered_map<int, Skill> skills_;
    mutable std::shared_mutex mutex_;
    std::unordered_map<int, std::chrono::steady_clock::time_point> lastUsedTime; // For cooldown management
};

// Example of a main function demonstrating usage
int main() {
    SkillManager skillManager(1024 * 1024); // Maximum memory size limit

    // Add skills
    skillManager.addSkill(1, "Fireball");
    skillManager.addSkill(2, "Ice Blast");

    // Simulate selecting and executing a skill
    std::thread t1([&]() { 
        if (skillManager.selectAndExecuteSkill(1)) {
            std::this_thread::sleep_for(std::chrono::seconds(5));
            skillManager.selectAndExecuteSkill(1); // Should be on cooldown
        }
    });

    std::thread t2([&]() {
        skillManager.selectAndExecuteSkill(2);
    });

    t1.join();
    t2.join();

    return 0;
}
