    int *keys = malloc(sizeof(int) * max_offset);
    Record *records = malloc(sizeof(Record) * max_offset);

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(offsets); free(keys); free(records);
        return;
