        records[i].key = keys[i];
        records[i].value = rand() % random_range;
    }

    pthread_mutex_lock(&data_store.lock);

    // Insert records into data store
    for (int i = 0; i < max_offset && data_store.size < MAX_DATA_STORE_SIZE; ++i) {
        data_store.records = realloc(data_store.records, sizeof(Record) * (data_store.size + 1));
        if (!data_store.records) {
            fprintf(stderr, "Reallocation failed.\n");
            break;
        }
        data_store.records[data_store.size++] = records[i];
    }

    pthread_mutex_unlock(&data_store.lock);

    // Simulate network operations
    DnsResult dns_result = {0};
    pthread_mutex_lock(&network_requests_lock);

    if (active_network_requests < MAX_NETWORK_REQUESTS) {
        active_network_requests++;
        pthread_mutex_unlock(&network_requests_lock);

        struct hostent *host_info;
        host_info = gethostbyname("example.com"); // Replace with actual hostname
        if (!host_info) {
            fprintf(stderr, "DNS resolution failed.\n");
            active_network_requests--;
            pthread_mutex_lock(&network_requests_lock);
            pthread_mutex_unlock(&network_requests_lock);
            return;
        }

        memcpy(&dns_result.ip_address, host_info->h_addr_list[0], sizeof(struct in_addr));

        // Simulate network timeout or other errors
        sleep(1);  // Network delay simulation

        active_network_requests--;
    } else {
        fprintf(stderr, "Network request limit reached.\n");
    }

    pthread_mutex_unlock(&network_requests_lock);

    // Example cleanup
    free(offsets);
    free(keys);
    if (records) {
        free(records);
    }
}

int main() {
