import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;
import javax.annotation.PreDestroy;

public class SessionManager {

    private final ConcurrentHashMap<String, UserSession> sessionMap;
    private final ScheduledExecutorService scheduler;
    private final Cache<String, UserSession> cache;
    private final Logger logger = Logger.getLogger(SessionManager.class.getName());
    private final int inactiveDurationMs;

    public SessionManager(int inactiveDurationSeconds) {
        this.sessionMap = new ConcurrentHashMap<>();
        this.scheduler = Executors.newScheduledThreadPool(2);
        this.cache = Caffeine.newBuilder()
                .expireAfterWrite(inactiveDurationSeconds, TimeUnit.SECONDS)
                .maximumSize(1000)
                .build();
        this.inactiveDurationMs = inactiveDurationSeconds * 1000;

        initializeLogger();
        scheduleCleanupTask();
    }

    public UserSession createOrUpdateSession(String sessionId, UserSession session) {
        logger.info("Creating/Updating session: " + sessionId);
        UserSession existingSession = sessionMap.put(sessionId, session);
        cache.put(sessionId, session);
        return existingSession;
    }

    public void deleteSession(String sessionId) {
        logger.info("Deleting session: " + sessionId);
        sessionMap.remove(sessionId);
        cache.invalidate(sessionId);
    }

    private void scheduleCleanupTask() {
        scheduler.scheduleAtFixedRate(this::cleanupExpiredSessions, 1, 10, TimeUnit.MINUTES);
        scheduler.scheduleWithFixedDelay(this::logSessionMetrics, 0, 15, TimeUnit.MINUTES);
    }

    private void cleanupExpiredSessions() {
        long currentTime = System.currentTimeMillis();
        sessionMap.entrySet().removeIf(entry -> 
            entry.getValue().getStatus() == UserSession.Status.EXPIRED ||
            (currentTime - entry.getValue().getLastActivityTimestamp()) > inactiveDurationMs
        );
        logger.info("Cleanup expired sessions completed.");
    }

    private void logSessionMetrics() {
        int activeSessions = sessionMap.values().stream()
                .filter(session -> session.getStatus() == UserSession.Status.ACTIVE)
                .count();
        logger.info("Active Sessions: " + activeSessions);
        // Add additional logging for cache hit rates, memory usage, etc.
    }

    @PreDestroy
    public void shutdown() {
        scheduler.shutdownNow();
        logger.info("Graceful shutdown initiated.");
    }

    private void initializeLogger() {
        Handler fileHandler = new RotatingFileHandler("session_manager.log", 1024 * 1024, 3);
        logger.addHandler(fileHandler);
        logger.setLevel(Level.ALL);
    }

    public static class UserSession {
        private String userId;
        private long lastActivityTimestamp;
        private List<String> activeDocuments;
        private Status status;

        public enum Status { ACTIVE, INACTIVE, EXPIRED }

        // Getters and Setters
    }

    public static void main(String[] args) {
        SessionManager manager = new SessionManager(300); // 5-minute inactive duration
        // Simulate session creation, updates, deletion.
    }
}
