#include <time.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>

#define MAX_EVENTS 1000
#define BUFFER_SIZE 1024

typedef struct {
    int MAC_EVENT_TAG;
    time_t timestamp;
} NetworkEvent;

typedef struct {
    NetworkEvent event;
    void *MAC_FRAME_DATA;
    size_t frame_length;
} EventData;

typedef struct {
    EventData *events;
    size_t count;
    pthread_mutex_t lock;
} ResourceManager;

typedef struct {
    long offset;
    int key;
} KeyValue;

int validateDirectoryName(const char *dirName) {
    for (size_t i = 0; dirName[i] != '\0'; ++i) {
        if ((dirName[i] < 'a' || dirName[i] > 'z') && 
            (dirName[i] < 'A' || dirName[i] > 'Z') &&
            (dirName[i] < '0' || dirName[i] > '9') &&
            dirName[i] != '_' && dirName[i] != '-') {
            return -1;
        }
    }
    if (strcmp(dirName, "CON") == 0 || strcmp(dirName, "PRN") == 0 ||
        strcmp(dirName, "AUX") == 0 || strcmp(dirName, "NUL") == 0) {
        return -1;
    }
    return 0;
}

int createDirectory(const char *dirPath) {
    struct stat st = {0};
    if (stat(dirPath, &st) == -1) {
        if (mkdir(dirPath, 0700) != 0) {
            perror("Failed to create directory");
            return errno;
        }
    } else if (!S_ISDIR(st.st_mode)) {
        fprintf(stderr, "Path exists but is not a directory\n");
        return EACCES;
    }
    return 0;
}

int setEnvVariable(const char *varName, const char *dirPath) {
    char *existingValue = getenv(varName);
    if (existingValue && strcmp(existingValue, dirPath) == 0)
        return 0;

    if (setenv(varName, dirPath, 1) != 0) {
        perror("Failed to set environment variable");
        return errno;
    }
    return 0;
}

int findLargestInteger(int *arr, size_t n) {
    int largest = arr[0];
    for (size_t i = 1; i < n; ++i) {
        if (arr[i] > largest)
            largest = arr[i];
    }
    return largest;
}

void sortKeyValuePairs(KeyValue *array, size_t n) {
    qsort(array, n, sizeof(KeyValue), [](const void *a, const void *b) -> int {
        KeyValue *keyA = (KeyValue *) a;
        KeyValue *keyB = (KeyValue *) b;
        return keyA->key - keyB->key;
    });
}

ResourceManager* resourceManager(size_t initialCapacity) {
    ResourceManager *rm = malloc(sizeof(ResourceManager));
    if (!rm) return NULL;

    rm->events = calloc(initialCapacity, sizeof(EventData));
    if (!rm->events) {
        free(rm);
        return NULL;
    }

    pthread_mutex_init(&rm->lock, NULL);
    rm->count = 0;

    return rm;
}

void addNetworkEvent(ResourceManager *rm, int MAC_EVENT_TAG, time_t timestamp, void *MAC_FRAME_DATA, size_t frame_length) {
    if (!rm) return;

    pthread_mutex_lock(&rm->lock);

    if (rm->count >= MAX_EVENTS) {
        fprintf(stderr, "Buffer overflow detected\n");
        pthread_mutex_unlock(&rm->lock);
        return;
    }

    rm->events[rm->count].event.MAC_EVENT_TAG = MAC_EVENT_TAG;
    rm->events[rm->count].event.timestamp = timestamp;
    rm->events[rm->count].MAC_FRAME_DATA = malloc(frame_length);
    if (!rm->events[rm->count].MAC_FRAME_DATA) {
        fprintf(stderr, "Memory allocation failed for frame data\n");
        pthread_mutex_unlock(&rm->lock);
        return;
    }
    memcpy(rm->events[rm->count].MAC_FRAME_DATA, MAC_FRAME_DATA, frame_length);
    rm->events[rm->count].frame_length = frame_length;

    rm->count++;

    pthread_mutex_unlock(&rm->lock);
}

void freeResourceManager(ResourceManager *rm) {
    if (!rm) return;
    for (size_t i = 0; i < rm->count; ++i) {
        free(rm->events[i].MAC_FRAME_DATA);
    }
    free(rm->events);
    pthread_mutex_destroy(&rm->lock);
    free(rm);
}

int main() {
    ResourceManager *rm = resourceManager(10);
    if (!rm) {
        fprintf(stderr, "Failed to initialize resource manager\n");
        return EXIT_FAILURE;
    }

    // Example usage of addNetworkEvent
    int tag = 1;
    time_t ts = time(NULL);
    char data[BUFFER_SIZE] = {0};
    addNetworkEvent(rm, tag, ts, data, sizeof(data));

    freeResourceManager(rm);

    KeyValue keyValuePairs[100];
    for (size_t i = 0; i < 100; ++i) {
        keyValuePairs[i].offset = rand() % 10000;
        keyValuePairs[i].key = rand() % 1000;
    }
    sortKeyValuePairs(keyValuePairs, 100);

    int numbers[10];
    for (size_t i = 0; i < 10; ++i) {
        scanf("%d", &numbers[i]);
    }

    printf("Largest number: %d\n", findLargestInteger(numbers, 10));

    char dirName[] = "my_directory";
    if (validateDirectoryName(dirName) != 0) {
        fprintf(stderr, "Invalid directory name\n");
        return EXIT_FAILURE;
    }

    if (createDirectory(dirName) != 0) {
        return EXIT_FAILURE;
    }

    setEnvVariable("MY_DIR", dirName);

    return EXIT_SUCCESS;
}
