RecordArray* create_record_array(size_t initial_capacity, int min_key, int max_key) {
    RecordArray *array = (RecordArray *)malloc(sizeof(RecordArray));
    if (!array) return NULL;

    array->records = (Record *)calloc(initial_capacity, sizeof(Record));
    if (!array->records) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->count = 0;

    pthread_mutex_init(&array->mutex, NULL);

    // Seed random number generator
