    return array;
}

void free_record_array(RecordArray *array) {
    if (array) {
        pthread_mutex_destroy(&array->mutex);
        free(array->records);
        free(array);
    }
}

int resize_record_array(RecordArray *array) {
    size_t new_capacity = array->capacity * 2;
    Record *new_records = (Record *)realloc(array->records, new_capacity * sizeof(Record));
    if (!new_records) return -1;

    array->records = new_records;
    array->capacity = new_capacity;
    return 0;
}

void update_records(RecordArray *array) {
    pthread_mutex_lock(&array->mutex);

    int min_key = 0; // Define the range or fetch from configuration
    int max_key = 100;

    if (array->count >= array->capacity && resize_record_array(array) != 0) {
        fprintf(stderr, "Failed to resize record array\n");
        pthread_mutex_unlock(&array->mutex);
        return;
    }

    for (size_t i = 0; i < array->count; ++i) {
        // Simulate random key assignment and data update
        int new_key = rand() % (max_key - min_key + 1) + min_key;
        double data_update = ((double)new_key / max_key) * 100.0;

        array->records[i].key = new_key;
        array->records[i].data += data_update; // Example update strategy
    }

    pthread_mutex_unlock(&array->mutex);
}
