        printf("Invalid input: %d. Must be between 1 and %d.\n", N, MAX_STRUCTURES);
        return NULL;
    }

    // Attempt to dynamically allocate memory
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

