            free(pdu_array);
            return NULL;
        }

        // Randomly set the CRCFLAG to simulate completion of CRC calculation
        pdu_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        pthread_mutex_unlock(&global_mutex);
    }

    return pdu_array;
}

int main() {
