#define INITIAL_CAPACITY 10

typedef struct {
    int cellId;
    time_t timeStamp;
    double throughput;
    double movingAvgThroughput;
} NetworkPerformanceMetrics;

typedef struct Node {
    NetworkPerformanceMetrics data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    _Atomic size_t count;
} LockFreeList;

void initializeNode(Node* node, int cellId, time_t timeStamp, double throughput) {
    node->data.cellId = cellId;
    node->data.timeStamp = timeStamp;
    node->data.throughput = throughput;
    node->data.movingAvgThroughput = 0.0; // Initial value
}

LockFreeList* createLockFreeList() {
    LockFreeList* list = (LockFreeList*)malloc(sizeof(LockFreeList));
    if (!list) return NULL;

    list->head = NULL;
    atomic_init(&list->count, 0);
    return list;
}

void pushFront(LockFreeList* list, NetworkPerformanceMetrics metrics) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    initializeNode(newNode, metrics.cellId, metrics.timeStamp, metrics.throughput);

    while (1) {
        newNode->next = list->head;
        if (__sync_bool_compare_and_swap(&list->head, newNode->next, newNode)) {
            break;
        }
    }

    atomic_fetch_add(&list->count, 1);
}

double calculateMovingAverage(LockFreeList* list, int n) {
    double sum = 0.0;
    size_t count = atomic_load(&list->count);
    Node* current = list->head;

    for (size_t i = 0; i < count && i < n; ++i) {
        if (!current) break;
        sum += current->data.throughput;
        current = current->next;
    }

    return count > 0 ? sum / ((double)n < count ? n : count) : 0.0;
}

