        double throughput = minThroughput + ((double)rand() / RAND_MAX) * (maxThroughput - minThroughput);

        NetworkPerformanceMetrics metrics = { .cellId = i, .timeStamp = timeStamp, .throughput = throughput };
        pushFront(metricsList, metrics);

        // Calculate moving average for the last 10 entries
        double avg = calculateMovingAverage(metricsList, 10);
        Node* current = metricsList->head;

        for (size_t j = 0; j < atomic_load(&metricsList->count) && j <= i; ++j) {
