```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_EVENTS 1000
#define MAX_FRAME_SIZE 1024

typedef struct {
    int tag;
    size_t length;
    char data[];
} MAC_FRAME_DATA;

typedef struct {
    int event_tag;
    time_t timestamp;
    MAC_FRAME_DATA *frames;
    size_t frame_count;
} MAC_EVENT;

typedef struct EventNode {
    MAC_EVENT event;
    struct EventNode *next;
} EventNode;

typedef struct {
    EventNode *head;
    pthread_mutex_t lock;
    size_t max_events;
    size_t memory_pool_size;
} EventList;

EventList event_list = {NULL, PTHREAD_MUTEX_INITIALIZER, MAX_EVENTS, 0};

void initialize_event_list(size_t max_events, size_t pool_size) {
    pthread_mutex_lock(&event_list.lock);
    event_list.max_events = max_events;
    event_list.memory_pool_size = pool_size;
    pthread_mutex_unlock(&event_list.lock);
}

int add_event(MAC_EVENT event) {
    pthread_mutex_lock(&event_list.lock);

    if (get_current_event_count() >= event_list.max_events) {
        fprintf(stderr, "Maximum events reached.\n");
        pthread_mutex_unlock(&event_list.lock);
        return -1;
    }

    EventNode *new_node = malloc(sizeof(EventNode));
    if (!new_node) {
        perror("Failed to allocate memory for new event node");
        pthread_mutex_unlock(&event_list.lock);
        return -1;
    }

    memcpy(&new_node->event, &event, sizeof(MAC_EVENT));

    new_node->next = event_list.head;
    event_list.head = new_node;

    printf("Event added successfully.\n");

    pthread_mutex_unlock(&event_list.lock);
    return 0;
}

size_t get_current_event_count() {
    size_t count = 0;
    EventNode *current = event_list.head;
    while (current) {
        count++;
        current = current->next;
    }
    return count;
}

void free_event_list() {
    pthread_mutex_lock(&event_list.lock);
    EventNode *current = event_list.head;
    while (current) {
        EventNode *next = current->next;
        free(current->event.frames);
        free(current);
        current = next;
    }
    event_list.head = NULL;
    pthread_mutex_unlock(&event_list.lock);
}

void process_command_line(int argc, char *argv[]) {
    size_t max_events = MAX_EVENTS;
    size_t pool_size = 1024 * 1024; // Default 1MB

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--max-events") == 0 && i + 1 < argc) {
            max_events = strtoul(argv[++i], NULL, 10);
        } else if (strcmp(argv[i], "--pool-size") == 0 && i + 1 < argc) {
            pool_size = strtoul(argv[++i], NULL, 10);
        }
    }

    initialize_event_list(max_events, pool_size);
}

int main(int argc, char *argv[]) {
    process_command_line(argc, argv);

    // Example usage
    MAC_EVENT event;
    event.event_tag = 1;
    time(&event.timestamp);
    size_t frame_count = 2;
    event.frames = malloc(frame_count * sizeof(MAC_FRAME_DATA) + 
                          (frame_count * MAX_FRAME_SIZE));
    if (!event.frames) {
        perror("Failed to allocate memory for frames");
        return EXIT_FAILURE;
    }
    event.frame_count = frame_count;

    // Add example frames
    strcpy(event.frames[0].data, "Frame 1 data");
    event.frames[0].tag = 101;
    event.frames[0].length = strlen(event.frames[0].data);

    strcpy(event.frames[1].data, "Frame 2 data");
    event.frames[1].tag = 102;
    event.frames[1].length = strlen(event.frames[1].data);

    add_event(event);
    free_event_list();

    return EXIT_SUCCESS;
}
```

This code provides a basic framework for managing network events with the specified requirements. It includes thread-safe operations, dynamic memory allocation, and command-line configuration. Further enhancements can be made based on specific needs, such as more detailed error logging or integration with other systems.']

