NFAPI_CRC_INDICATION_PDU_T* allocate_crc_pdu_array(size_t N) {
    if (N == 0) return NULL;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);
    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&lock);
        pthread_mutex_destroy(&lock);
        return NULL;
    }

    int ue_info[3];
    for (size_t i = 0; i < N; ++i) {
        int retries = 0;
        while (retries < 5) { // Retry up to 5 times
            if (fetch_external_ue_info(ue_info) == 0) {
                array[i].RX_UE_INFORMATION_TAG = ue_info[0];
                array[i].RNTI = ue_info[1];
                array[i].CRC_INDICATION_REL8_TAG = ue_info[2];
                array[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
                break;
            }
            retries++;
            usleep((1 << retries) * 10000); // Exponential backoff
        }

        if (retries == 5) {
            fprintf(stderr, "Failed to fetch UE information after multiple attempts\n");
            free(array);
            pthread_mutex_unlock(&lock);
            pthread_mutex_destroy(&lock);
            return NULL;
        }
    }

    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);

    return array;
}

void cleanup_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (array) {
        free(array);
    }
}
