#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char src_ip[16];
    char dst_ip[16];
    uint16_t src_port;
    uint16_t dst_port;
    int status; // 0: closed, 1: open
} Connection;

typedef struct Node {
    Connection data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
} DynamicArray;

DynamicArray* init_dynamic_array() {
    DynamicArray* arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    arr->head = NULL;
    pthread_mutex_init(&arr->lock, NULL);
    arr->count = 0;
    return arr;
}

void free_node(Node* node) {
    if (node) {
        free(node);
    }
}

Connection* find_connection(DynamicArray* arr, const char* src_ip, uint16_t src_port,
                            const char* dst_ip, uint16_t dst_port) {
    pthread_mutex_lock(&arr->lock);

    Node* current = arr->head;
    while (current) {
        if (strcmp(current->data.src_ip, src_ip) == 0 &&
            current->data.src_port == src_port &&
            strcmp(current->data.dst_ip, dst_ip) == 0 &&
            current->data.dst_port == dst_port) {
            pthread_mutex_unlock(&arr->lock);
            return &current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&arr->lock);
    return NULL;
}

void add_connection(DynamicArray* arr, const Connection* conn) {
    Node** current = &(arr->head);

    pthread_mutex_lock(&arr->lock);

    while (*current) {
        if (strcmp((*current)->data.src_ip, conn->src_ip) == 0 &&
            (*current)->data.src_port == conn->src_port &&
            strcmp((*current)->data.dst_ip, conn->dst_ip) == 0 &&
            (*current)->data.dst_port == conn->dst_port) {
            pthread_mutex_unlock(&arr->lock);
            return; // Connection already exists
        }
        current = &(*current)->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&arr->lock);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    *current = new_node;
    new_node->data = *conn;
    new_node->next = NULL;

    arr->count++;
    pthread_mutex_unlock(&arr->lock);
}

void remove_connection(DynamicArray* arr, const char* src_ip, uint16_t src_port,
                       const char* dst_ip, uint16_t dst_port) {
    Node** current = &(arr->head);

    pthread_mutex_lock(&arr->lock);

    while (*current) {
        if (strcmp((*current)->data.src_ip, src_ip) == 0 &&
            (*current)->data.src_port == src_port &&
            strcmp((*current)->data.dst_ip, dst_ip) == 0 &&
            (*current)->data.dst_port == dst_port) {

            Node* to_free = *current;
            *current = (*current)->next;

            free_node(to_free);
            arr->count--;
            pthread_mutex_unlock(&arr->lock);
            return;
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&arr->lock);
}

void update_connection_status(DynamicArray* arr, const char* src_ip, uint16_t src_port,
                              const char* dst_ip, uint16_t dst_port, int status) {
    Connection* conn = find_connection(arr, src_ip, src_port, dst_ip, dst_port);

    if (conn) {
        pthread_mutex_lock(&arr->lock);
        conn->status = status;
        pthread_mutex_unlock(&arr->lock);
    }
}

size_t get_active_connections_count(DynamicArray* arr) {
    size_t count;

    pthread_mutex_lock(&arr->lock);
    count = arr->count;
    pthread_mutex_unlock(&arr->lock);

    return count;
}

void free_dynamic_array(DynamicArray* arr) {
    Node* current = arr->head;
    while (current) {
        Node* next = current->next;
        free_node(current);
        current = next;
    }

    pthread_mutex_destroy(&arr->lock);
    free(arr);
}
```

