#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    unsigned char *data;
    size_t length;
} MAC_FRAME_DATA;

typedef struct {
    int MAC_EVENT_TAG;
    long timestamp;
    MAC_FRAME_DATA *frames;
    size_t frame_count;
} NetworkEvent;

typedef struct {
    NetworkEvent **events;
    size_t event_count;
    size_t capacity;
} EventList;

#define INITIAL_CAPACITY 10

// Align memory to the nearest multiple of ALIGNMENT
void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_MSC_VER)
    ptr = _aligned_malloc(size, alignment);
#else
    if (posix_memalign(&ptr, alignment, size)) ptr = NULL;
#endif
    return ptr;
}

// Free memory with proper alignment handling
void aligned_free(void *ptr) {
#if defined(_MSC_VER)
    _aligned_free(ptr);
#else
    free(ptr);
#endif
}

EventList* create_event_list() {
    EventList *list = (EventList*)malloc(sizeof(EventList));
    list->events = (NetworkEvent**)aligned_alloc(16, INITIAL_CAPACITY * sizeof(NetworkEvent*));
    list->event_count = 0;
    list->capacity = INITIAL_CAPACITY;
    return list;
}

void expand_event_list(EventList *list) {
    size_t new_capacity = list->capacity * 2;
    NetworkEvent **new_events = (NetworkEvent**)aligned_alloc(16, new_capacity * sizeof(NetworkEvent*));
    memcpy(new_events, list->events, list->event_count * sizeof(NetworkEvent*));
    aligned_free(list->events);
    list->events = new_events;
    list->capacity = new_capacity;
}

void add_event(EventList *list, NetworkEvent *new_event) {
    if (list->event_count >= list->capacity) expand_event_list(list);

    int found = 0;
    for (size_t i = 0; i < list->event_count; ++i) {
        if (list->events[i]->MAC_EVENT_TAG == new_event->MAC_EVENT_TAG) {
            found = 1;
            break;
        }
    }

    if (!found) {
        list->events[list->event_count++] = new_event;
    } else {
        printf("Event with tag %d already exists.\n", new_event->MAC_EVENT_TAG);
    }
}

NetworkEvent* find_event_by_tag(EventList *list, int tag) {
    for (size_t i = 0; i < list->event_count; ++i) {
        if (list->events[i]->MAC_EVENT_TAG == tag) return list->events[i];
    }
    return NULL;
}

void remove_event(EventList *list, int tag) {
    size_t index_to_remove = SIZE_MAX;
    for (size_t i = 0; i < list->event_count; ++i) {
        if (list->events[i]->MAC_EVENT_TAG == tag) {
            index_to_remove = i;
            break;
        }
    }

    if (index_to_remove != SIZE_MAX) {
        aligned_free(list->events[index_to_remove]->frames);
        free(list->events[index_to_remove]);

        for (size_t i = index_to_remove; i < list->event_count - 1; ++i) {
            list->events[i] = list->events[i + 1];
        }

        --list->event_count;
    } else {
        printf("Event with tag %d not found.\n", tag);
    }
}

long get_timestamp(EventList *list, int tag) {
    NetworkEvent *event = find_event_by_tag(list, tag);
    if (event) return event->timestamp;

    printf("Event with tag %d not found.\n", tag);
    return -1; // Indicate error
}

void process_events(EventList *list, void (*process_frame)(MAC_FRAME_DATA* frame)) {
    for (size_t i = 0; i < list->event_count; ++i) {
        NetworkEvent *event = list->events[i];
        for (size_t j = 0; j < event->frame_count; ++j) {
            process_frame(&event->frames[j]);
        }
    }
}

void free_event_list(EventList *list) {
    for (size_t i = 0; i < list->event_count; ++i) {
        aligned_free(list->events[i]->frames);
        free(list->events[i]);
    }
    aligned_free(list->events);
    free(list);
}
