typedef struct {
    int value;
    char *identifier;
} Record;

typedef struct {
    pthread_mutex_t lock;
} ThreadSafeContext;

unsigned long xorshift128plus_state[2];

void seed_xorshift128plus(unsigned long s) {
    if (s == 0) s = 1; // avoid zero seed
    xorshift128plus_state[0] = s;
    xorshift128plus_state[1] = s != 0 ? s : 123456789; // second state can't be zero too
}

unsigned long xorshift128plus() {
    unsigned long s1 = xorshift128plus_state[0];
    unsigned long s0 = xorshift128plus_state[1];
    unsigned long result = s0 + s1;

    s1 ^= s1 << 23;
    s1 ^= s1 >> 17;
    s1 ^= s0 ^ (s0 >> 26);
    xorshift128plus_state[0] = s0;
    xorshift128plus_state[1] = s1;

    return result;
}

unsigned int generate_random(unsigned int min, unsigned int max) {
    return (xorshift128plus() % (max - min + 1)) + min;
}

int initialize_data(long size, ThreadSafeContext *context) {
    pthread_mutex_lock(&context->lock);

    long *offset = malloc(size * sizeof(long));
    int *key = malloc(size * sizeof(int));
    Record *records = malloc(size * sizeof(Record));

    if (!offset || !key || !records) {
        if (offset) free(offset);
        if (key) free(key);
        if (records) {
            for (long i = 0; i < size; ++i) {
                free(records[i].identifier);
            }
            free(records);
        }
        pthread_mutex_unlock(&context->lock);
        return -1;
    }

    for (long i = 0; i < size; ++i) {
        offset[i] = i * 10L; // Example initialization
        key[i] = i % 256;    // Example initialization

        records[i].value = generate_random(1, 100); // Random value in range [1, 100]

        char id[50];
        snprintf(id, sizeof(id), "ID_%ld", i);
        size_t len = strlen(id) + 1;
        records[i].identifier = malloc(len);
        if (!records[i].identifier) {
            for (long j = 0; j < i; ++j) free(records[j].identifier);
            free(offset);
            free(key);
            free(records);
            pthread_mutex_unlock(&context->lock);
            return -1;
        }
        strcpy(records[i].identifier, id);
    }

    pthread_mutex_unlock(&context->lock);

    // Assuming we have some mechanism to store these pointers safely
    printf("Data initialized successfully.\n");

    return 0; // Success
}

int main() {
    ThreadSafeContext context = {PTHREAD_MUTEX_INITIALIZER};
    seed_xorshift128plus(12345); // Seed with a known value for reproducibility

    long size = 1000;
    int result = initialize_data(size, &context);

    if (result != 0) {
        fprintf(stderr, "Failed to initialize data.\n");
    }

    pthread_mutex_destroy(&context.lock);
    return 0;
}
```

### Key Points:

- **Thread Safety**: A mutex is used to ensure that the initialization function can be safely called from multiple threads.
- **Memory Management**: The code carefully allocates and frees memory, checking for allocation failures at each step.
- **Pseudo-Random Number Generation**: A custom `xorshift128plus` generator provides reproducible random numbers based on a seed.
- **Error Handling**: If any allocation fails, the function cleans up already allocated resources before returning an error code.
- **Initialization Logic**: Demonstrates how arrays and structures can be initialized with simple patterns or values.']

