int validate_input(int num_points, int grid_size) {
    if (num_points <= 0 || grid_size <= 0) return 0;
    if (num_points > 10000) return 0; // Ensure it's within manageable range
    return 1;
}

void initialize_memory(double **doubles, char ***strings, point **points, int num_elements, int max_string_length) {
    *doubles = (double *)malloc(num_elements * sizeof(double));
    if (!*doubles) { log_memory_usage("Failed to allocate memory for doubles"); exit(EXIT_FAILURE); }

    *strings = (char **)malloc(num_elements * sizeof(char *));
    if (!*strings) { 
        free(*doubles);
        log_memory_usage("Failed to allocate memory for strings");
        exit(EXIT_FAILURE); 
    }

    for (int i = 0; i < num_elements; ++i) {
        (*strings)[i] = (char *)malloc(max_string_length * sizeof(char));
        if (!(*strings)[i]) { 
            log_memory_usage("Failed to allocate memory for string");
            while (i-- > 0) free((*strings)[i]);
            free(*strings);
            free(*doubles);
            exit(EXIT_FAILURE); 
        }
    }

    *points = (point *)malloc(num_elements * sizeof(point));
    if (!*points) { 
        log_memory_usage("Failed to allocate memory for points");
        while (--i >= 0) free((*strings)[i]);
        free(*strings);
        free(*doubles);
        exit(EXIT_FAILURE); 
    }
}

void populate_points(point *points, int num_points, int grid_size) {
    #pragma omp parallel for
    for (int i = 0; i < num_points; ++i) {
        points[i].x = rand() % grid_size;
        points[i].y = rand() % grid_size;
    }
}

void calculate_distances(point *points, double **distances, int num_points) {
    *distances = (double *)malloc(num_points * num_points * sizeof(double));
    if (!*distances) { 
        log_memory_usage("Failed to allocate memory for distances");
        free(points);
        exit(EXIT_FAILURE); 
    }

    #pragma omp parallel for collapse(2)
    for (int i = 0; i < num_points; ++i) {
        for (int j = 0; j < num_points; ++j) {
            double dx = points[i].x - points[j].x;
            double dy = points[i].y - points[j].y;
            (*distances)[i * num_points + j] = sqrt(dx * dx + dy * dy);
        }
    }
}

void free_memory(double *doubles, char **strings, int num_strings, point *points, double *distances) {
    for (int i = 0; i < num_strings; ++i) {
        free(strings[i]);
    }
    free(strings);
    free(doubles);
    free(points);
    free(distances);
}

double calculate_total_distance(double *distances, int num_points) {
    double total_distance = 0.0;
    #pragma omp parallel for reduction(+:total_distance)
    for (int i = 0; i < num_points; ++i) {
        for (int j = 0; j < num_points; ++j) {
            total_distance += distances[i * num_points + j];
        }
    }
    return total_distance;
}

void process_data(int num_doubles, int grid_size, char max_string_length, double distance_threshold) {
    if (!validate_input(num_doubles, grid_size)) {
        log_memory_usage("Invalid input parameters");
        return;
    }

    double *doubles = NULL;
    char **strings = NULL;
    point *points = NULL;
    double *distances = NULL;

    initialize_memory(&doubles, &strings, &points, num_doubles, max_string_length);

    populate_points(points, num_doubles, grid_size);
    calculate_distances(points, &distances, num_doubles);

    double total_distance = calculate_total_distance(distances, num_doubles);
    if (total_distance > distance_threshold) {
        log_memory_usage("Total distance exceeds threshold");
        free_memory(doubles, strings, num_doubles, points, distances);
        return;
    }

    // Integrate with existing pipeline (simulated here)
    printf("Processing completed successfully. Total Distance: %f\n", total_distance);

    free_memory(doubles, strings, num_doubles, points, distances);
}

int main() {
    int num_elements = 1000; // Example user input
    int grid_size = 100;
    char max_string_length = MAX_STRING_LENGTH;
    double distance_threshold = MAX_DISTANCE_THRESHOLD;

    process_data(num_elements, grid_size, max_string_length, distance_threshold);

    return 0;
}
