#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

#define INITIAL_QUEUE_SIZE 1024

typedef struct {
    uint64_t timestamp;
    char event_type[32];
    void *payload;
} Event;

typedef struct {
    Event **events;
    size_t capacity;
    size_t count;
    atomic_size_t head;
    atomic_size_t tail;
    pthread_mutex_t lock;
} EventQueue;

EventQueue* create_event_queue(size_t initial_capacity) {
    EventQueue *queue = malloc(sizeof(EventQueue));
    if (!queue) return NULL;

    queue->events = calloc(initial_capacity, sizeof(Event *));
    if (!queue->events) {
        free(queue);
        return NULL;
    }

    queue->capacity = initial_capacity;
    queue->count = 0;
    atomic_store(&queue->head, 0);
    atomic_store(&queue->tail, 0);
    pthread_mutex_init(&queue->lock, NULL);

    return queue;
}

void destroy_event_queue(EventQueue *queue) {
    for (size_t i = 0; i < queue->count; ++i) {
        free(queue->events[i]);
    }
    free(queue->events);
    pthread_mutex_destroy(&queue->lock);
    free(queue);
}

int resize_event_queue(EventQueue *queue, size_t new_capacity) {
    Event **new_events = realloc(queue->events, new_capacity * sizeof(Event *));
    if (!new_events) return -1;

    queue->events = new_events;
    queue->capacity = new_capacity;
    return 0;
}

int enqueue_event(EventQueue *queue, Event *event) {
    pthread_mutex_lock(&queue->lock);

    size_t tail = atomic_load(&queue->tail);
    if (queue->count == queue->capacity) {
        if (resize_event_queue(queue, queue->capacity * 2) != 0) {
            pthread_mutex_unlock(&queue->lock);
            return -1;
        }
    }

    queue->events[tail] = event;
    atomic_store(&queue->tail, (tail + 1) % queue->capacity);
    ++queue->count;

    pthread_mutex_unlock(&queue->lock);
    return 0;
}

int dequeue_event(EventQueue *queue, Event **event) {
    pthread_mutex_lock(&queue->lock);

    size_t head = atomic_load(&queue->head);
    if (queue->count == 0) {
        pthread_mutex_unlock(&queue->lock);
        return -1;
    }

    *event = queue->events[head];
    free(queue->events[head]);
    atomic_store(&queue->head, (head + 1) % queue->capacity);
    --queue->count;

    pthread_mutex_unlock(&queue->lock);
    return 0;
}

void* event_handler(void *arg) {
    EventQueue *queue = (EventQueue *)arg;

    while (1) {
        Event *event = NULL;
        if (dequeue_event(queue, &event) == 0) {
            // Process the event
            printf("Processing event: %s\n", event->event_type);
            free(event);  // Assuming payload is dynamically allocated
        }
    }

    return NULL;
}

int main() {
    EventQueue *queue = create_event_queue(INITIAL_QUEUE_SIZE);
    if (!queue) {
        fprintf(stderr, "Failed to create event queue\n");
        return EXIT_FAILURE;
    }

    pthread_t threads[100];
    for (int i = 0; i < 100; ++i) {
        pthread_create(&threads[i], NULL, event_handler, queue);
    }

    // Simulate adding events
    for (size_t i = 0; i < 10000; ++i) {
        Event *event = malloc(sizeof(Event));
        if (!event) continue;

        event->timestamp = i;
        snprintf(event->event_type, sizeof(event->event_type), "Type%d", i % 10);
        enqueue_event(queue, event);
    }

    for (int i = 0; i < 100; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_event_queue(queue);
    return EXIT_SUCCESS;
}
