#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <errno.h>

#define MAX_ENTRIES 1000000
#define LOG_MESSAGE_MAX_LENGTH 256
#define LOG_ENTRY_SIZE sizeof(LogEntry)
#define TIMESTAMP_SIZE sizeof(time_t)

typedef enum { INFO, WARNING, ERROR } Severity;

typedef struct {
    time_t timestamp;
    char message[LOG_MESSAGE_MAX_LENGTH];
    Severity severity;
} LogEntry;

typedef struct {
    LogEntry *entries;
    size_t count;
    pthread_mutex_t lock;
} LogManager;

LogManager log_manager = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

void report_metrics(size_t total_count, double avg_length) {
    // Integrate with external monitoring service
    printf("Total Entries: %zu\n", total_count);
    printf("Average Length: %.2f\n", avg_length);
}

int add_log_entry(const char *message, Severity severity) {
    if (log_manager.count >= MAX_ENTRIES) return -1;

    pthread_mutex_lock(&log_manager.lock);

    time_t now = time(NULL);
    size_t message_len = strlen(message);

    if (message_len >= LOG_MESSAGE_MAX_LENGTH) {
        pthread_mutex_unlock(&log_manager.lock);
        fprintf(stderr, "Message too long\n");
        return -2;
    }

    LogEntry *entry = &log_manager.entries[log_manager.count++];
    entry->timestamp = now;
    strncpy(entry->message, message, LOG_MESSAGE_MAX_LENGTH);
    entry->severity = severity;

    pthread_mutex_unlock(&log_manager.lock);

    return 0;
}

void initialize_log_manager() {
    log_manager.entries = malloc(MAX_ENTRIES * LOG_ENTRY_SIZE);
    if (!log_manager.entries) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
}

void finalize_log_manager() {
    free(log_manager.entries);
}

int main(int argc, char *argv[]) {
    if (argc != 2 || atoi(argv[1]) > MAX_ENTRIES) {
        fprintf(stderr, "Usage: %s <number_of_entries>\n", argv[0]);
        return EXIT_FAILURE;
    }

    size_t num_entries = atoi(argv[1]);

    initialize_log_manager();

    for (size_t i = 0; i < num_entries; ++i) {
        char message[LOG_MESSAGE_MAX_LENGTH];
        snprintf(message, LOG_MESSAGE_MAX_LENGTH, "Log entry %zu", i);
        if (add_log_entry(message, INFO) != 0) {
            fprintf(stderr, "Failed to add log entry\n");
        }
    }

    size_t total_length = 0;
    for (size_t i = 0; i < log_manager.count; ++i) {
        total_length += strlen(log_manager.entries[i].message);
    }

    double avg_length = log_manager.count > 0 ? (double)total_length / log_manager.count : 0.0;

    report_metrics(log_manager.count, avg_length);

    finalize_log_manager();

    return EXIT_SUCCESS;
}
```

### Key Features:
- **Concurrency**: Uses `pthread_mutex_t` for thread-safe operations.
- **Error Handling**: Gracefully handles memory allocation failure and message length validation.
- **Metrics Reporting**: Reports total entries and average message length.
- **Initialization/Finalization**: Manages dynamic memory allocation for log entries.
- **Input Validation**: Ensures the number of entries does not exceed `MAX_ENTRIES`.']

