// Define the session structure
typedef struct {
    int sessionId;
    char activityLog[256];
    double resourceConsumption;
} Session;

// Memory pool for managing session objects
typedef struct {
    size_t chunkSize;
    size_t totalChunks;
    void *memoryPool;
    pthread_mutex_t lock;
} MemoryPool;

// Global memory pool
MemoryPool globalMemPool;

void initializeMemoryPool(size_t initialSize, size_t chunkSize) {
    globalMemPool.chunkSize = chunkSize;
    globalMemPool.totalChunks = initialSize;
    globalMemPool.memoryPool = malloc(globalMemPool.chunkSize * globalMemPool.totalChunks);
    pthread_mutex_init(&globalMemPool.lock, NULL);
}

void* allocateSession() {
    pthread_mutex_lock(&globalMemPool.lock);

    if (globalMemPool.memoryPool == NULL) {
        // Double the pool size on exhaustion
        globalMemPool.totalChunks *= 2;
        void *newMemoryPool = realloc(globalMemPool.memoryPool, 
                                      globalMemPool.chunkSize * globalMemPool.totalChunks);

        if (newMemoryPool == NULL) {
            fprintf(stderr, "Failed to allocate memory.\n");
            pthread_mutex_unlock(&globalMemPool.lock);
            return NULL;
        }
        globalMemPool.memoryPool = newMemoryPool;
    }

    void *sessionPtr = globalMemPool.memoryPool;
    globalMemPool.memoryPool += globalMemPool.chunkSize;

    pthread_mutex_unlock(&globalMemPool.lock);
    return sessionPtr;
}

void freeSession(void *sessionPtr) {
    // For simplicity, freeing individual sessions is not implemented.
    // In practice, implement a mechanism to track and recycle freed slots.
}

// Function to manage user sessions
void* manageUserSessions(void *arg) {
    Session *newSession = (Session *)allocateSession();
    if (!newSession) {
        fprintf(stderr, "Failed to allocate session.\n");
        return NULL;
    }

    // Populate session data - this would be more complex in practice
    newSession->sessionId = rand();  // Simulated unique ID
    snprintf(newSession->activityLog, sizeof(newSession->activityLog), 
             "User activity log for session %d", newSession->sessionId);
    newSession->resourceConsumption = (double)rand() / RAND_MAX * 100;

    printf("Session %d created with resource consumption: %.2f\n", 
           newSession->sessionId, newSession->resourceConsumption);

    // Simulate activity and log handling
    sleep(1); // Represents session activity duration

    freeSession(newSession);
    return NULL;
}

void runUserSessionManager(int numThreads) {
    pthread_t threads[numThreads];

    for (int i = 0; i < numThreads; ++i) {
        if (pthread_create(&threads[i], NULL, manageUserSessions, NULL) != 0) {
            fprintf(stderr, "Failed to create thread.\n");
        }
    }

    for (int i = 0; i < numThreads; ++i) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    initializeMemoryPool(10, sizeof(Session)); // Initialize memory pool with initial size and chunk size

    runUserSessionManager(5); // Simulate managing sessions with 5 concurrent threads

    free(globalMemPool.memoryPool);  // Cleanup
    pthread_mutex_destroy(&globalMemPool.lock);

    return 0;
}
