#define MAX_TASKS 500000

typedef struct {
    char* command_line;
    int priority;
    time_t timestamp;
    int completed;
    int paused;
} Task;

typedef struct Node {
    Task task;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} PriorityQueue;

typedef struct {
    Task* tasks;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} TaskPool;

PriorityQueue* create_priority_queue() {
    PriorityQueue* pq = (PriorityQueue*)malloc(sizeof(PriorityQueue));
    pq->head = NULL;
    pthread_mutex_init(&pq->lock, NULL);
    return pq;
}

void destroy_priority_queue(PriorityQueue* pq) {
    Node* current = pq->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&pq->lock);
    free(pq);
}

int enqueue_task(PriorityQueue* pq, Task task) {
    pthread_mutex_lock(&pq->lock);

    Node** current = &pq->head;
    while (*current && (*current)->task.priority >= task.priority) {
        current = &(*current)->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->task = task;
    new_node->next = *current;
    *current = new_node;

    pthread_mutex_unlock(&pq->lock);
    return 0;
}

Task dequeue_task(PriorityQueue* pq) {
    pthread_mutex_lock(&pq->lock);

    if (pq->head == NULL) {
        pthread_mutex_unlock(&pq->lock);
        Task empty_task = {NULL, -1, 0, 1, 0};
        return empty_task;
    }

    Node* node_to_remove = pq->head;
    Task task = node_to_remove->task;
    pq->head = node_to_remove->next;
    free(node_to_remove);

    pthread_mutex_unlock(&pq->lock);
    return task;
}

TaskPool* create_task_pool(size_t initial_capacity) {
    TaskPool* pool = (TaskPool*)malloc(sizeof(TaskPool));
    pool->tasks = (Task*)malloc(initial_capacity * sizeof(Task));
    pool->capacity = initial_capacity;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_task_pool(TaskPool* pool) {
    free(pool->tasks);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int add_task(TaskPool* pool, Task task) {
    pthread_mutex_lock(&pool->lock);

    if (pool->count >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        Task* new_tasks = (Task*)realloc(pool->tasks, new_capacity * sizeof(Task));
        if (!new_tasks) {
            pthread_mutex_unlock(&pool->lock);
            return -1; // Memory allocation failed
        }
        pool->tasks = new_tasks;
        pool->capacity = new_capacity;
    }

    pool->tasks[pool->count++] = task;

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

int update_task(TaskPool* pool, int index, Task updated_task) {
    pthread_mutex_lock(&pool->lock);

    if (index < 0 || index >= pool->count) {
        pthread_mutex_unlock(&pool->lock);
        return -1; // Index out of bounds
    }

    pool->tasks[index] = updated_task;

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

int mark_task_completed(TaskPool* pool, int index) {
    pthread_mutex_lock(&pool->lock);

    if (index < 0 || index >= pool->count) {
        pthread_mutex_unlock(&pool->lock);
        return -1; // Index out of bounds
    }

    pool->tasks[index].completed = 1;

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

int pause_task(TaskPool* pool, int index) {
    pthread_mutex_lock(&pool->lock);

    if (index < 0 || index >= pool->count || pool->tasks[index].paused) {
        pthread_mutex_unlock(&pool->lock);
        return -1; // Index out of bounds or already paused
    }

    pool->tasks[index].paused = 1;

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

int resume_task(TaskPool* pool, int index) {
    pthread_mutex_lock(&pool->lock);

    if (index < 0 || index >= pool->count || !pool->tasks[index].paused) {
        pthread_mutex_unlock(&pool->lock);
        return -1; // Index out of bounds or not paused
    }

    pool->tasks[index].paused = 0;

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

void get_task_statistics(TaskPool* pool, int* active_count, int* pending_count, int* completed_count, size_t* memory_usage) {
    *active_count = 0;
    *pending_count = 0;
    *completed_count = 0;

    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->tasks[i].completed) {
            (*completed_count)++;
        } else if (pool->tasks[i].paused) {
            (*pending_count)++;
        } else {
            (*active_count)++;
        }
    }

    *memory_usage = sizeof(TaskPool) + pool->capacity * sizeof(Task);

    pthread_mutex_unlock(&pool->lock);
}

int main() {
    TaskPool* pool = create_task_pool(1000);
    PriorityQueue* pq = create_priority_queue();

    // Example usage
    Task task1 = { "echo Hello", 5, time(NULL), 0, 0 };
    add_task(pool, task1);

    enqueue_task(pq, task1);

    int active_count, pending_count, completed_count;
    size_t memory_usage;

    get_task_statistics(pool, &active_count, &pending_count, &completed_count, &memory_usage);
    printf("Active: %d, Pending: %d, Completed: %d, Memory Usage: %zu\n", active_count, pending_count, completed_count, memory_usage);

    destroy_priority_queue(pq);
    destroy_task_pool(pool);

    return 0;
}
