#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <stdint.h>

#define MAX_THREADS 1000
#define INITIAL_EVENT_CAPACITY 10

typedef struct {
    uint32_t macEventTag;
    uint64_t timestamp;
    size_t numFrames;
    struct {
        uint16_t length;
        uint8_t data[];
    } frames[];
} NetworkEvent;

typedef struct {
    pthread_mutex_t mutex;
    pthread_rwlock_t rwlock;
    NetworkEvent *events;
    size_t capacity;
    size_t count;
} EventList;

typedef struct {
    int cellId;
    uint64_t timeStamp;
    double throughput;
    double movingAvgThroughput[10];
    size_t avgIndex;
    size_t numEntries;
} NetworkPerformanceMetrics;

typedef struct {
    NetworkPerformanceMetrics *metricsArray;
    size_t metricsCapacity;
    pthread_mutex_t metricsMutex;
} PerformanceMetricsManager;

// Function prototypes
void initializeEventList(EventList *eventList);
int addNetworkEvent(EventList *eventList, NetworkEvent event);
int removeNetworkEvent(EventList *eventList, uint64_t timestamp);
void resizeEventList(EventList *eventList);
double calculateThroughput(double throughputData[], size_t numEntries);

// Initialize the dynamic list for network events
void initializeEventList(EventList *eventList) {
    pthread_mutex_init(&eventList->mutex, NULL);
    pthread_rwlock_init(&eventList->rwlock, NULL);
    eventList->capacity = INITIAL_EVENT_CAPACITY;
    eventList->count = 0;
    eventList->events = malloc(eventList->capacity * sizeof(NetworkEvent));
    if (!eventList->events) {
        perror("Failed to allocate memory for events");
        exit(EXIT_FAILURE);
    }
}

// Add a new network event ensuring thread safety
int addNetworkEvent(EventList *eventList, NetworkEvent event) {
    pthread_rwlock_wrlock(&eventList->rwlock);

    // Check if resizing is needed
    if (eventList->count == eventList->capacity) {
        resizeEventList(eventList);
    }

    // Add the new event
    memcpy((void*)&eventList->events[eventList->count], &event, sizeof(NetworkEvent));

    eventList->count++;

    pthread_rwlock_unlock(&eventList->rwlock);
    return 0;
}

// Remove a network event by timestamp
int removeNetworkEvent(EventList *eventList, uint64_t timestamp) {
    pthread_rwlock_wrlock(&eventList->rwlock);

    for (size_t i = 0; i < eventList->count; ++i) {
        if (eventList->events[i].timestamp == timestamp) {
            memmove((void*)&eventList->events[i], 
                    (void*)&eventList->events[i + 1],
                    (eventList->count - i - 1) * sizeof(NetworkEvent));
            eventList->count--;
            break;
        }
    }

    pthread_rwlock_unlock(&eventList->rwlock);
    return 0;
}

// Resize the dynamic list to accommodate more events
void resizeEventList(EventList *eventList) {
    size_t newCapacity = eventList->capacity * 2;
    NetworkEvent *newEvents = realloc(eventList->events, newCapacity * sizeof(NetworkEvent));
    if (!newEvents) {
        perror("Failed to reallocate memory for events");
        exit(EXIT_FAILURE);
    }

    eventList->events = newEvents;
    eventList->capacity = newCapacity;
}

// Initialize the performance metrics manager
void initializePerformanceMetricsManager(PerformanceMetricsManager *manager, size_t initialCapacity) {
    pthread_mutex_init(&manager->metricsMutex, NULL);
    manager->metricsCapacity = initialCapacity;
    manager->metricsArray = malloc(manager->metricsCapacity * sizeof(NetworkPerformanceMetrics));
    if (!manager->metricsArray) {
        perror("Failed to allocate memory for metrics");
        exit(EXIT_FAILURE);
    }
}

// Calculate the moving average throughput
double calculateThroughput(double throughputData[], size_t numEntries) {
    double sum = 0;
    for (size_t i = 0; i < numEntries; ++i) {
        sum += throughputData[i];
    }
    return sum / numEntries;
}
