#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_KEY 1000
#define MAX_FILE_PATH_LENGTH 256
#define LOGGING_SERVICE "logging_service_placeholder"
#define CACHE_SIZE 50

typedef struct {
    int value;
    char *filePath;
} Record;

typedef struct CacheNode {
    Record record;
    struct CacheNode* next;
} CacheNode;

typedef struct {
    CacheNode* head;
    pthread_mutex_t lock;
} Cache;

void log_event(const char* message) {
    // Placeholder for integration with an external logging service
    printf("LOG: %s\n", message);
}

int validate_record(int key, const char *filePath) {
    if (key < 0 || key > MAX_KEY)
        return -1;
    if (strlen(filePath) > MAX_FILE_PATH_LENGTH)
        return -2;
    // Additional validation logic can be added here
    return 0;
}

void* malloc_safe(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        log_event("Memory allocation failed");
    }
    return ptr;
}

void free_safe(void* ptr) {
    if (ptr) {
        free(ptr);
        log_event("Memory deallocation performed");
    }
}

Record create_record(int value, char* filePath) {
    Record record = { .value = value, .filePath = filePath };
    return record;
}

int compare_records(const void *a, const void *b) {
    const Record *recA = (const Record *) a;
    const Record *recB = (const Record *) b;

    if (recA->value < recB->value)
        return -1;
    else if (recA->value > recB->value)
        return 1;
    else {
        // If keys are the same, sort by file path length in descending order
        int lenA = strlen(recA->filePath);
        int lenB = strlen(recB->filePath);
        return lenB - lenA; 
    }
}

void init_cache(Cache *cache) {
    cache->head = NULL;
    pthread_mutex_init(&cache->lock, NULL);
}

CacheNode* find_in_cache(Cache *cache, int key) {
    CacheNode *current = cache->head;

    while (current != NULL) {
        if (current->record.value == key)
            return current;
        current = current->next;
    }
    return NULL;
}

void insert_into_cache(Cache *cache, Record record) {
    CacheNode* newNode = malloc_safe(sizeof(CacheNode));
    if (!newNode) return;

    newNode->record = record;
    newNode->next = cache->head;
    cache->head = newNode;

    pthread_mutex_lock(&cache->lock);
    // If cache exceeds size, remove the last node
    CacheNode *current = cache->head, *prev = NULL;
    int count = 0;
    while (current != NULL && count < CACHE_SIZE) {
        current = current->next;
        count++;
    }
    if (count > CACHE_SIZE) {
        current = cache->head;
        while (current->next != NULL)
            prev = current, current = current->next;
        free_safe(prev);
        prev->next = NULL;
    }
    pthread_mutex_unlock(&cache->lock);
}

void processAndSortRecords(const char *filename, long **offsets, int **keys, Record ***records, int *error_code) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        *error_code = 1; // Error opening file
        return;
    }

    Cache cache;
    init_cache(&cache);

    size_t capacity = 1024; // Starting with an initial allocation size
    long* offsetArray = malloc_safe(sizeof(long) * capacity);
    int* keyArray = malloc_safe(sizeof(int) * capacity);
    Record** recordArray = malloc_safe(sizeof(Record*) * capacity);
    if (!offsetArray || !keyArray || !recordArray) {
        *error_code = 2; // Memory allocation error
        fclose(file);
        free_safe(offsetArray);
        free_safe(keyArray);
        free_safe(recordArray);
        return;
    }

    int count = 0;
    char line[512];
    while (fgets(line, sizeof(line), file)) {
        if (count >= capacity) {
            capacity *= 2;
            offsetArray = realloc_safe(offsetArray, sizeof(long) * capacity);
            keyArray = realloc_safe(keyArray, sizeof(int) * capacity);
            recordArray = realloc_safe(recordArray, sizeof(Record*) * capacity);
            if (!offsetArray || !keyArray || !recordArray) {
                *error_code = 2; // Memory allocation error
                break;
            }
        }

        int key;
        char filePath[MAX_FILE_PATH_LENGTH];

        // Assume input format is: key file_path
        if (sscanf(line, "%d %255s", &key, filePath) == 2) {
            if (validate_record(key, filePath) != 0) {
                log_event("Skipping malformed record");
                continue;
            }

            long offset = ftell(file);
            int value = rand() % MAX_KEY; // Randomly generated for the example
            size_t len = strlen(filePath);

            char *strPath = malloc_safe(sizeof(char) * (len + 1));
            if (!strPath) {
                *error_code = 2;
                continue;
            }
            strcpy(strPath, filePath);

            Record *record = malloc_safe(sizeof(Record));
            if (!record) {
                free_safe(strPath);
                *error_code = 2;
                continue;
            }

            record->value = value;
            record->filePath = strPath;

            offsetArray[count] = offset;
            keyArray[count] = key;
            recordArray[count] = record;

            CacheNode* cacheEntry = find_in_cache(&cache, key);
            if (!cacheEntry) {
                insert_into_cache(&cache, *record);
            }

            count++;
        } else {
            log_event("Skipping malformed record");
        }
    }

    fclose(file);

    qsort(recordArray, count, sizeof(Record*), compare_records);

    // Set output pointers
    *offsets = offsetArray;
    *keys = keyArray;
    *records = recordArray;

    *error_code = 0; // Success
}

void realloc_safe(void **ptr, size_t newSize) {
    void *newPtr = realloc(*ptr, newSize);
    if (!newPtr && newSize > 0) {
        log_event("Memory reallocation failed");
    }
    *ptr = newPtr;
}
