    DataArrays data;
    data.offsets = (long *)malloc(recordCount * sizeof(long));
    data.keys = (int *)malloc(recordCount * sizeof(int));
    data.records = (Record *)malloc(recordCount * sizeof(Record));

    if (!data.offsets || !data.keys || !data.records) {
