        free(data.keys);
        free(data.records);
        pthread_mutex_unlock(&cacheMutex);
        return -2;
    }

    size_t validCount = 0;
    char line[1024];
    while (fgets(line, sizeof(line), file) && validCount < recordCount) {
        int key, value;
        char filePath[MAX_STRING_LENGTH];

        if (sscanf(line, "%d %d %[^\n]", &key, &value, filePath) == 3) {
            data.offsets[validCount] = rand() % 1000; // Example randomization
