#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_RNTI 65535

typedef struct {
    int frequency;
    int bandwidth;
} SRS_CONFIG;

typedef struct {
    unsigned short TX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    SRS_CONFIG *SRS_CONFIG;
} NR_SRS_REQUEST_PDU_T;

typedef struct Node {
    NR_SRS_REQUEST_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} SRSList;

void init_list(SRSList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int validate_srs_config(SRS_CONFIG* config) {
    return (config->frequency > 0 && config->bandwidth > 0);
}

int add_to_list(SRSList* list, NR_SRS_REQUEST_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (pdu.RNTI >= MAX_RNTI || !validate_srs_config(pdu.SRS_CONFIG)) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;

    printf("Added RNTI: %lu, Frequency: %d, Bandwidth: %d\n", 
           pdu.RNTI, pdu.SRS_CONFIG->frequency, pdu.SRS_CONFIG->bandwidth);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void free_list(SRSList* list) {
    Node *current = list->head, *next;

    while (current != NULL) {
        next = current->next;
        free(current->data.SRS_CONFIG);
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
}

int export_list_to_file(const char* filename, SRSList* list) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    Node *current = list->head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NR_SRS_REQUEST_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
    return 0;
}

int load_list_from_file(const char* filename, SRSList* list) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    NR_SRS_REQUEST_PDU_T pdu;
    while (fread(&pdu, sizeof(NR_SRS_REQUEST_PDU_T), 1, file)) {
        if (add_to_list(list, pdu) != 0) {
            fclose(file);
            return -1;
        }
    }

    fclose(file);
    return 0;
}

int main() {
    SRSList list;
    init_list(&list);

    // Example usage
    NR_SRS_REQUEST_PDU_T pdu = { .TX_UE_INFORMATION_TAG = 1, .RNTI = 12345 };
    pdu.SRS_CONFIG = malloc(sizeof(SRS_CONFIG));
    if (pdu.SRS_CONFIG) {
        pdu.SRS_CONFIG->frequency = 1200;
        pdu.SRS_CONFIG->bandwidth = 50;

        add_to_list(&list, pdu);
    }

    export_list_to_file("srs_data.bin", &list);

    free_list(&list);

    // Load from file
    SRSList loaded_list;
    init_list(&loaded_list);
    load_list_from_file("srs_data.bin", &loaded_list);

    free_list(&loaded_list);

    return 0;
}
