// Define constants
#define MAX_STRING_LENGTH 256
#define CACHE_SIZE 100

// Error codes
typedef enum {
    SUCCESS = 0,
    MEMORY_ALLOCATION_FAILURE = -1,
    FILE_READ_ERROR = -2
} ErrorCode;

// Record structure
typedef struct {
    int value;
    char *filePath;
    size_t filePathLength;
    time_t timestamp;
    int refCount;
} Record;

// Cache entry
typedef struct {
    Record record;
    time_t lastAccessed;
} CacheEntry;

// Cache structure
typedef struct {
    CacheEntry entries[CACHE_SIZE];
    int count;
} Cache;

// Function prototypes
ErrorCode initializeAndSortRecords(const char *filePath, long *offsets, int *keys, Record **records, time_t *timestamps);
static void logEvent(const char *message);
static void logWarning(const char *message);
static ErrorCode readAndInitializeData(const char *filePath, long **offsets, int **keys, Record ***records, time_t **timestamps, size_t *recordCount);
static int compareRecords(const void *a, const void *b);
static void updateCache(Cache *cache, Record *record);
static CacheEntry* findInCache(Cache *cache, int key);

// Mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

ErrorCode initializeAndSortRecords(const char *filePath, long *offsets, int *keys, Record **records, time_t *timestamps) {
    pthread_mutex_lock(&lock);

    size_t recordCount;
    ErrorCode result = readAndInitializeData(filePath, (long**)&offsets, (int**)&keys, (Record***)&records, (time_t**)&timestamps, &recordCount);

    if (result != SUCCESS) {
        logEvent("Initialization failed.");
        pthread_mutex_unlock(&lock);
        return result;
    }

    qsort(records, recordCount, sizeof(Record*), compareRecords);

    // Initialize cache
    Cache cache = { .count = 0 };

    for (size_t i = 0; i < recordCount; ++i) {
        updateCache(&cache, records[i]);
    }

    logEvent("Initialization and sorting completed successfully.");
    pthread_mutex_unlock(&lock);

    return SUCCESS;
}

static void logEvent(const char *message) {
    // Implement logging to external service
    printf("Log: %s\n", message);
}

static void logWarning(const char *message) {
    // Implement warning logging to external service
    printf("Warning: %s\n", message);
}

static ErrorCode readAndInitializeData(const char *filePath, long **offsets, int **keys, Record ***records, time_t **timestamps, size_t *recordCount) {
    FILE *file = fopen(filePath, "r");
    if (!file) return FILE_READ_ERROR;

    // Estimate record count (for simplicity, assume 1000 records)
    *recordCount = 1000;

    *offsets = malloc(*recordCount * sizeof(long));
    *keys = malloc(*recordCount * sizeof(int));
    *records = malloc(*recordCount * sizeof(Record*));
    *timestamps = malloc(*recordCount * sizeof(time_t));

    if (!*offsets || !*keys || !*records || !*timestamps) {
        free(*offsets); free(*keys); free(*records); free(*timestamps);
        fclose(file);
        return MEMORY_ALLOCATION_FAILURE;
    }

    size_t i = 0;
    while (i < *recordCount && fscanf(file, "%ld %d", &((*offsets)[i]), &((*keys)[i])) == 2) {
        (*records)[i] = malloc(sizeof(Record));
        if (!(*records)[i]) {
            logWarning("Memory allocation for record failed.");
            break;
        }

        // Random initialization for demonstration purposes
        srand(time(NULL) + i);
        int value = rand() % 1000;
        size_t filePathLength = (rand() % MAX_STRING_LENGTH) + 1;
        (*records)[i]->value = value;

        char *filePath = malloc(filePathLength + 1);
        if (!filePath) {
            logWarning("Memory allocation for file path failed.");
            free((*records)[i]);
            break;
        }
        snprintf(filePath, filePathLength + 1, "file%d", i);
        (*records)[i]->filePath = filePath;
        (*records)[i]->filePathLength = filePathLength;

        (*timestamps)[i] = time(NULL); // Simulate timestamp
        (*records)[i]->timestamp = (*timestamps)[i];
        (*records)[i]->refCount = 0;

        i++;
    }

    fclose(file);
    *recordCount = i;
    return SUCCESS;
}

static int compareRecords(const void *a, const void *b) {
    Record **ra = (Record **)a;
    Record **rb = (Record **)b;
    int keyDiff = (*ra)->value - (*rb)->value;

    if (keyDiff != 0) return keyDiff;

    // Compare by file path length descending
    if ((*ra)->filePathLength != (*rb)->filePathLength)
        return (*rb)->filePathLength - (*ra)->filePathLength;

    // Finally, compare by timestamp ascending
    return difftime((*ra)->timestamp, (*rb)->timestamp);
}

static void updateCache(Cache *cache, Record *record) {
    CacheEntry *entry = findInCache(cache, record->value);

    if (entry) {
        entry->lastAccessed = time(NULL);
    } else {
        if (cache->count < CACHE_SIZE) {
            entry = &cache->entries[cache->count++];
            memcpy(entry, &(Record){.filePath = strdup(record->filePath)}, sizeof(CacheEntry));
        }
        // Implement eviction policy if needed
    }

    record->refCount++;
}

static CacheEntry* findInCache(Cache *cache, int key) {
    for (int i = 0; i < cache->count; ++i) {
        if (cache->entries[i].record.value == key)
            return &cache->entries[i];
    }
    return NULL;
}
