    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM; // TCP stream sockets

    s = getaddrinfo(res_arg->hostname, NULL, &hints, &result);
    if (s != 0) {
