        for (size_t i = 0; i < read && is_numeric; ++i) {
            if (!isdigit(line[i])) {
                is_numeric = 0;
                break;
            }
        }

        if (is_numeric) {
            char *tokens[10];
            int token_count = 0;
            char *token = strtok(line, " \t\n");
            while (token) {
                tokens[token_count++] = token;
                token = strtok(NULL, " \t\n");
            }

            // Ensure there are at least two fields to average
            if (token_count >= 2) {
                int last1 = atoi(tokens[token_count - 1]);
                int last2 = atoi(tokens[token_count - 2]);

                float avg = (last1 + last2) / 2.0;
                printf("Line: %s Average of last two fields: %.2f\n", line, avg);
            }
        } else {
