    fprintf(stderr, "ERROR: %s\n", message);
}

// Function to initialize a record with random values
void init_record(Record *record) {
    if (record == NULL) return;
    record->key = rand() % 1000000; // Example range for key
    record->offset = rand() % 1000000000L; // Example range for offset
    record->value = (double)(rand() % 10000) / 100.0; // Example range for value
    record->status = 'A' + (rand() % 26); // Random status from A-Z
}

// Function to check memory usage
size_t get_memory_usage(size_t record_size, size_t num_records) {
    return record_size * num_records;
}

// Function to allocate and initialize records with duplicate resolution
Record* allocate_and_initialize_records(size_t num_records) {
    if (num_records > MAX_RECORDS) {
        log_error("Number of records exceeds maximum limit.");
        return NULL;
    }

    Record *records = malloc(num_records * sizeof(Record));
    if (!records) {
        log_error("Memory allocation failed for records array.");
        return NULL;
    }

    size_t record_size = sizeof(Record);
    if (get_memory_usage(record_size, num_records) > MEMORY_LIMIT) {
        free(records);
        log_error("Memory usage exceeds the limit of 8 MB.");
        return NULL;
    }

    srand(time(NULL)); // Seed for randomness

    int *key_map = calloc(num_records, sizeof(int));
    if (!key_map) {
        free(records);
        log_error("Memory allocation failed for key map.");
        return NULL;
    }

    size_t successful_allocations = 0;

    while (successful_allocations < num_records) {
        Record *record = &records[successful_allocations];

        int duplicate_found = 0;
        init_record(record);

        // Resolve duplicates
        if (key_map[record->key % MAX_RECORDS] == record->key) {
            duplicate_found = 1; 
        } else {
            key_map[record->key % MAX_RECORDS] = record->key;
        }

        if (!duplicate_found) successful_allocations++;

        // Log potential memory usage issues
        if (get_memory_usage(record_size, successful_allocations + 1) > MEMORY_LIMIT * 0.9) {
            log_error("Approaching maximum memory limit.");
        }
    }

    free(key_map);
    return records;
}

// Function to free allocated records
void deallocate_records(Record *records) {
    if (records != NULL) {
        free(records);
    }
}

int main() {
    size_t num_records = 5000; // Example number of records

    Record *records = allocate_and_initialize_records(num_records);

    if (!records) {
        return EXIT_FAILURE;
    }

    // Use the allocated and initialized records here...

    // Deallocate memory upon successful execution
    deallocate_records(records);

    return EXIT_SUCCESS;
}
