// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to check directory validity and existence
int validate_and_create_directory(const char *parent_dir, const char *dir_name) {
    // Validate the directory name
    if (strchr(dir_name, '/') || strchr(dir_name, '\\') || !*dir_name) {
        fprintf(stderr, "Invalid directory name.\n");
        return -1;
    }

    // Construct full path
    size_t len = strlen(parent_dir) + strlen(dir_name) + 2; // for '/' and '\0'
    char *full_path = (char *)malloc(len);
    if (!full_path) {
        perror("Failed to allocate memory");
        return -1;
    }
    snprintf(full_path, len, "%s/%s", parent_dir, dir_name);

    // Check if parent directory exists
    struct stat st = {0};
    if (stat(parent_dir, &st) == -1) {
        fprintf(stderr, "Parent directory does not exist or is inaccessible.\n");
        free(full_path);
        return -1;
    }

    // Create the directory
    if (mkdir(full_path, 0700) == -1 && errno != EEXIST) {
        perror("Failed to create directory");
        free(full_path);
        return -1;
    }

    printf("Directory created: %s\n", full_path);

    // Set environment variable
    char *env_value = getenv("DIR_PATH");
    if (!env_value || strcmp(env_value, full_path)) {
        if (setenv("DIR_PATH", full_path, 1) != 0) {
            perror("Failed to set environment variable");
        }
    }

    free(full_path);
    return 0;
}

// Helper function to find the largest integer
int find_largest(int *array, size_t size) {
    int max = INT_MIN;
    for (size_t i = 0; i < size; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

// Function to sort records
void sort_records(Record *records, size_t size) {
    qsort(records, size, sizeof(Record), [](const void *a, const void *b) -> int {
        Record *recA = (Record *)a;
        Record *recB = (Record *)b;
        return recA->key - recB->key;
    });
}

// Main function to manage resources
void resourceManager(int min_val, int max_val) {
    if (min_val > max_val) {
        fprintf(stderr, "Invalid range.\n");
        return;
    }

    pthread_mutex_lock(&mutex);

    // Read input size
    size_t size = 0;
    scanf("%zu", &size);
    if (size == 0 || size > MAX_INPUT_SIZE) {
        fprintf(stderr, "Invalid input size.\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Allocate memory for records
    Record *records = (Record *)aligned_alloc(64, sizeof(Record) * size);
    if (!records) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Initialize records with random values
    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        records[i].key = rand() % (max_val - min_val + 1) + min_val;
    }

    // Sort the records
    sort_records(records, size);

    // Log sorted keys
    printf("Sorted Keys: ");
    for (size_t i = 0; i < size; ++i) {
        printf("%d ", records[i].key);
    }
    printf("\n");

    // Find largest integer using helper function
    int *int_array = (int *)malloc(size * sizeof(int));
    if (!int_array) {
        perror("Failed to allocate memory");
        free(records);
        pthread_mutex_unlock(&mutex);
        return;
    }

    for (size_t i = 0; i < size; ++i) {
        int_array[i] = records[i].key;
    }

    printf("Largest Integer: %d\n", find_largest(int_array, size));

    // Cleanup
    free(records);
    free(int_array);

    pthread_mutex_unlock(&mutex);
}

int main() {
    char parent_dir[] = ".";
    char dir_name[] = "new_directory";

    if (validate_and_create_directory(parent_dir, dir_name) != 0) {
        return EXIT_FAILURE;
    }

    resourceManager(1, 100); // Example range

    return EXIT_SUCCESS;
}
