#include <arpa/inet.h>
#include <time.h>

#define MAX_CONNECTIONS 5000
#define MAX_MEMORY_USAGE_MB 4
#define MEMORY_THRESHOLD_MB 3

typedef enum {
    CONNECTED,
    DISCONNECTED,
    LISTENING
} ConnectionState;

typedef struct {
    in_addr_t ip_address;
    uint16_t port_number;
    ConnectionState state;
    time_t last_activity;
} Connection;

typedef struct Node {
    Connection connection;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    size_t memory_usage; // In bytes
} ConnectionPool;

void log_warning(const char *message) {
    fprintf(stderr, "%s\n", message);
}

ConnectionPool* create_connection_pool() {
    ConnectionPool* pool = (ConnectionPool*)malloc(sizeof(ConnectionPool));
    if (!pool) return NULL;
    pool->head = NULL;
    pool->count = 0;
    pool->memory_usage = sizeof(ConnectionPool);
    return pool;
}

void free_connection_pool(ConnectionPool* pool) {
    Node* current = pool->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(pool);
}

int add_connection(ConnectionPool* pool, in_addr_t ip_address, uint16_t port_number) {
    if (pool->count >= MAX_CONNECTIONS) return -1;

    // Check for uniqueness
    Node* current = pool->head;
    while (current) {
        if (current->connection.ip_address == ip_address && current->connection.port_number == port_number)
            return -1; // IP and Port must be unique
        current = current->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_warning("Memory allocation failed for a new connection.");
        return -2;
    }

    size_t new_memory_usage = sizeof(Connection) + sizeof(Node);
    if (pool->memory_usage + new_memory_usage > MAX_MEMORY_USAGE_MB * 1024 * 1024) {
        free(new_node);
        log_warning("Memory usage exceeded the maximum limit of 4 MB.");
        return -3;
    }

    pool->memory_usage += new_memory_usage;

    if (pool->memory_usage > MEMORY_THRESHOLD_MB * 1024 * 1024) {
        log_warning("Warning: Memory usage exceeds 3 MB threshold.");
    }

    new_node->connection.ip_address = ip_address;
    new_node->connection.port_number = port_number;
    new_node->connection.state = DISCONNECTED;
    new_node->connection.last_activity = time(NULL);
    new_node->next = pool->head;
    pool->head = new_node;
    pool->count++;

    return 0; // Success
}

int update_connection(ConnectionPool* pool, in_addr_t ip_address, uint16_t port_number, ConnectionState state) {
    Node* current = pool->head;
    while (current) {
        if (current->connection.ip_address == ip_address && current->connection.port_number == port_number) {
            current->connection.state = state;
            current->connection.last_activity = time(NULL);
            return 0; // Success
        }
        current = current->next;
    }
    return -1; // Connection not found
}

int remove_connection(ConnectionPool* pool, in_addr_t ip_address, uint16_t port_number) {
    Node *current = pool->head, *prev = NULL;
    while (current) {
        if (current->connection.ip_address == ip_address && current->connection.port_number == port_number) {
            size_t freed_memory = sizeof(Connection) + sizeof(Node);
            pool->memory_usage -= freed_memory;

            if (prev)
                prev->next = current->next;
            else
                pool->head = current->next;

            free(current);
            pool->count--;
            return 0; // Success
        }
        prev = current;
        current = current->next;
    }
    return -1; // Connection not found
}

