['Below is a C implementation of the described logging system. This code includes a memory pool for efficient allocation, thread-safe operations using mutexes, dynamic resizing, and configuration parameters. It also provides error handling and monitoring capabilities.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_LOG_LEVELS 5
#define LOG_LEVEL_INFO 1

typedef struct {
    int id;
    time_t timestamp;
    int log_level;
    char *message;
} LogEntry;

typedef struct {
    LogEntry **entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} LogManager;

LogManager* create_log_manager(size_t initial_capacity, size_t max_message_size);
void destroy_log_manager(LogManager *manager);
int add_log_entry(LogManager *manager, int id, int log_level, const char *message);
LogEntry* get_log_entry(LogManager *manager, int id);
int delete_log_entry(LogManager *manager, int id);
void resize_memory_pool(LogManager *manager);

LogManager* create_log_manager(size_t initial_capacity, size_t max_message_size) {
    LogManager *manager = (LogManager *)malloc(sizeof(LogManager));
    if (!manager) return NULL;

    manager->entries = (LogEntry **)calloc(initial_capacity, sizeof(LogEntry *));
    if (!manager->entries) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_log_manager(LogManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->entries[i]->message);
        free(manager->entries[i]);
    }
    free(manager->entries);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_log_entry(LogManager *manager, int id, int log_level, const char *message) {
    if (!manager || log_level < 0 || log_level >= MAX_LOG_LEVELS) return -1;

    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        resize_memory_pool(manager);
    }

    LogEntry *entry = (LogEntry *)malloc(sizeof(LogEntry));
    if (!entry) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    entry->id = id;
    entry->timestamp = time(NULL);
    entry->log_level = log_level;
    size_t message_length = strlen(message) + 1;
    entry->message = (char *)malloc(message_length);
    if (!entry->message) {
        free(entry);
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    strcpy(entry->message, message);

    manager->entries[manager->count++] = entry;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

LogEntry* get_log_entry(LogManager *manager, int id) {
    if (!manager) return NULL;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->entries[i]->id == id) {
            LogEntry *entry = manager->entries[i];
            pthread_mutex_unlock(&manager->lock);
            return entry;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

int delete_log_entry(LogManager *manager, int id) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->entries[i]->id == id) {
            free(manager->entries[i]->message);
            free(manager->entries[i]);
            manager->entries[i] = manager->entries[--manager->count];
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1;
}

void resize_memory_pool(LogManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    LogEntry **new_entries = (LogEntry **)realloc(manager->entries, new_capacity * sizeof(LogEntry *));
    if (!new_entries) return;

    memset(new_entries + manager->capacity, 0, manager->capacity * sizeof(LogEntry *));
    manager->entries = new_entries;
    manager->capacity = new_capacity;
}

// Example usage
int main() {
    LogManager *manager = create_log_manager(100, 256);
    if (!manager) {
        fprintf(stderr, "Failed to create log manager\n");
        return EXIT_FAILURE;
    }

    add_log_entry(manager, 1, LOG_LEVEL_INFO, "This is a test log entry.");
    LogEntry *entry = get_log_entry(manager, 1);
    if (entry) {
        printf("Log Entry: ID=%d, Level=%d, Message=%s\n", entry->id, entry->log_level, entry->message);
        delete_log_entry(manager, 1);
    }

    destroy_log_manager(manager);
    return EXIT_SUCCESS;
}
```

### Key Features:
- **Thread Safety**: Uses `pthread_mutex_t` for thread-safe operations.
- **Dynamic Memory Management**: Resizes the memory pool when capacity is reached.
- **Error Handling**: Checks for null pointers and allocation failures.
- **Configuration**: Initial capacity can be set at creation.
- **Efficiency**: Minimizes fragmentation by doubling the pool size on resize.

### Considerations:
- **Performance**: Use aligned allocations if needed for specific architectures.
- **Extensibility**: Functions can be extended to support more features like logging sinks.
- **Monitoring**: Add metrics collection as needed for integration with monitoring tools.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_OFFSETS 1000
#define RAND_MAX_SIZE 256

typedef struct {
    long offset;
    int key;
    char *buffer;
} record;

// Prototype declarations
long* allocate_offsets(size_t num_offsets);
int* retrieve_unique_keys(int desired_size, size_t *retrieved_count);
void fill_random_bytes(char *buf, size_t length);
void initialize_records(record **records, long *offsets, int *keys, size_t offsets_size, size_t keys_size);
void deallocate_resources(long *offsets, record *records[], size_t num_records);
int validate_integrity(record *records[], size_t num_records);

long* allocate_offsets(size_t num_offsets) {
    if (num_offsets > MAX_OFFSETS) {
        fprintf(stderr, "Requested offsets exceed maximum allowed limit.\n");
        return NULL;
    }
    long *offsets = (long *)malloc(num_offsets * sizeof(long));
    for (size_t i = 0; i < num_offsets; ++i) {
        offsets[i] = rand() % RAND_MAX_SIZE + 1; // Ensure non-zero
    }
    return offsets;
}

int* retrieve_unique_keys(int desired_size, size_t *retrieved_count) {
    int *keys = (int *)malloc(desired_size * sizeof(int));
    int found_keys = 0;

    while (found_keys < desired_size) {
        int key = rand() % 10000; // Example range for keys
        int duplicate = 0;

        for (size_t i = 0; i < found_keys; ++i) {
            if (keys[i] == key) {
                duplicate = 1;
                break;
            }
        }

        if (!duplicate) {
            keys[found_keys++] = key;
        }
    }

    *retrieved_count = found_keys;
    return keys;
}

void fill_random_bytes(char *buf, size_t length) {
    for (size_t i = 0; i < length; ++i) {
        buf[i] = rand() % 256; // Random byte
    }
}

void initialize_records(record **records, long *offsets, int *keys, size_t offsets_size, size_t keys_size) {
    if (!records || !offsets || !keys) return;

    for (size_t i = 0; i < offsets_size && i < keys_size; ++i) {
        records[i] = (record *)malloc(sizeof(record));
        records[i]->offset = offsets[i];
        records[i]->key = keys[i];
        records[i]->buffer = (char *)malloc(records[i]->offset);
        fill_random_bytes(records[i]->buffer, records[i]->offset);
    }
}

void deallocate_resources(long *offsets, record **records, size_t num_records) {
    if (offsets) free(offsets);

    for (size_t i = 0; i < num_records; ++i) {
        if (records[i]) {
            free(records[i]->buffer);
            free(records[i]);
        }
    }

    free(records);
}

int validate_integrity(record **records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        if (!records[i] || !records[i]->buffer) return 0;

        // Check random bytes are within valid range
        for (long j = 0; j < records[i]->offset; ++j) {
            if (records[i]->buffer[j] > 255 || records[i]->buffer[j] < 0)
                return 0;
        }
    }
    return 1;
}

void manage_memory(size_t num_offsets, size_t num_keys) {
    srand(time(NULL)); // Seed for reproducibility

    long *offsets = allocate_offsets(num_offsets);
    if (!offsets) return;

    size_t retrieved_count;
    int *keys = retrieve_unique_keys(num_keys, &retrieved_count);

    record **records = (record **)malloc(retrieved_count * sizeof(record *));
    initialize_records(records, offsets, keys, num_offsets, retrieved_count);

    // Integrity check
    if (!validate_integrity(records, retrieved_count)) {
        fprintf(stderr, "Data integrity validation failed.\n");
    }

    deallocate_resources(offsets, records, retrieved_count);
}

int main() {
    size_t num_offsets = 100; // Example input
    size_t num_keys = 50;

    manage_memory(num_offsets, num_keys);

    return 0;
}
