void sortDocumentsByTimestamp() {
    pthread_mutex_lock(&lock);
    qsort(document_entries, entry_count, sizeof(DocumentEntry), compareEntries);
    pthread_mutex_unlock(&lock);
}

int compareEntries(const void *a, const void *b) {
    DocumentEntry *entryA = (DocumentEntry *)a;
    DocumentEntry *entryB = (DocumentEntry *)b;
    return (entryA->timestamp > entryB->timestamp) - (entryA->timestamp < entryB->timestamp);
}

void backupState() {
