#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_PDU_COUNT 1000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t count;
    pthread_mutex_t lock;
    FILE *log_file;
} PDU_Manager;

static void log_message(PDU_Manager *manager, const char *message) {
    if (manager->log_file != NULL) {
        fprintf(manager->log_file, "%s\n", message);
        fflush(manager->log_file); // Ensuring real-time logging
    }
}

PDU_Manager* create_pdu_manager(FILE *log_file, uint32_t random_seed) {
    PDU_Manager *manager = malloc(sizeof(PDU_Manager));
    if (!manager) {
        perror("Failed to allocate memory for manager");
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->pdus = NULL;
    manager->count = 0;
    manager->log_file = log_file;

    srand(random_seed); // Set random seed

    return manager;
}

void free_pdu_manager(PDU_Manager *manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->lock);
        for (size_t i = 0; i < manager->count; ++i) {
            free(manager->pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
        }
        free(manager->pdus);
        fclose(manager->log_file); // Ensure log file is closed
        free(manager);
    }
}

int populate_pdu(PDU_Manager *manager, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (manager->count >= MAX_PDU_COUNT) return -1;

    pthread_mutex_lock(&manager->lock);

    size_t start_size = manager->pdus ? manager->count : 0;
    manager->pdus = realloc(manager->pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (start_size + 1));
    if (!manager->pdus) {
        log_message(manager, "Memory allocation failed");
        pthread_mutex_unlock(&manager->lock);
        return -2;
    }

    // Generate unique CRCFLAG
    uint8_t crcflag = rand() % 256;
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG == crcflag) {
            log_message(manager, "Unique CRCFLAG generation failed");
            pthread_mutex_unlock(&manager->lock);
            return -3;
        }
    }

    pdu->RX_UE_INFORMATION_TAG = rand();
    pdu->RNTI = rand() % 65536;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = crcflag;

    manager->pdus[manager->count++] = *pdu;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int main() {
    FILE *log_file = fopen("performance.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    PDU_Manager *manager = create_pdu_manager(log_file, time(NULL));
    if (!manager) {
        fclose(log_file);
        return EXIT_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu;

    // Simulate processing
    for (int i = 0; i < 10000; ++i) {
        int status = populate_pdu(manager, &pdu);
        if (status != 0) {
            log_message(manager, "Failed to populate PDU");
        }
    }

    free_pdu_manager(manager);

    return EXIT_SUCCESS;
}
```

### Key Points:
1. **Thread Safety**: Mutex is used to ensure thread-safe operations.
2. **Unique CRCFLAG**: Ensures uniqueness within the allocated list.
3. **Error Logging**: Logs allocation errors and unique flag generation issues.
4. **Reproducibility**: Uses a seed for random number generation.
5. **Resource Management**: Handles memory allocation failures gracefully.

This code provides a framework that can be expanded upon to meet further requirements, such as integrating with existing logging systems or implementing additional caching mechanisms.']

