#define MAX_ITEMS 10000000

typedef struct {
    int value;
} record;

typedef struct {
    char *name;
    double val;
} item;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t max_items_ever_allocated = 0;

// Custom hash function for strings
unsigned long custom_hash(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % MAX_ITEMS;
}

// Function to initialize random numbers within a given range
double init_random_double(double min, double max) {
    return min + (max - min) * rand() / (RAND_MAX + 1.0);
}

// Resize the items array dynamically
item* resize_items_array(item **items, size_t *capacity) {
    pthread_mutex_lock(&mutex);

    if (*capacity == 0)
        *capacity = 16;
    else
        *capacity *= 2;

    item *new_items = realloc(*items, sizeof(item) * (*capacity));
    if (!new_items) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Track maximum items ever allocated
    max_items_ever_allocated = (max_items_ever_allocator > *capacity) ? max_items_ever_allocator : *capacity;

    pthread_mutex_unlock(&mutex);

    return new_items;
}

// Function to add an item at runtime
void add_item(item **items, size_t *size, size_t *capacity, const char *name) {
    if (*size >= *capacity)
        *items = resize_items_array(items, capacity);

    items[*size].name = strdup(name);
    items[*size].val = 0.0;
    (*size)++;
}

// Function to process and sort records
void processAndSortRecordsWithDir(const char *dir_name) {
    pthread_mutex_lock(&mutex);

    // Create directory if it doesn't exist
    struct stat st = {0};
    if (stat(dir_name, &st) == -1) {
        mkdir(dir_name, 0700);
    }

    // Set environment variable
    setenv("PROCESS_DIR", dir_name, 1);

    char log_dir_path[256];
    snprintf(log_dir_path, sizeof(log_dir_path), "%s/logs", dir_name);
    if (mkdir(log_dir_path, 0700) && errno != EEXIST) {
        fprintf(stderr, "Log directory creation failed\n");
        exit(EXIT_FAILURE);
    }

    // Assume input_files is a list of file paths to process
    const char *input_files[] = {"file1", "file2"}; // Placeholder for actual files
    size_t num_files = sizeof(input_files) / sizeof(input_files[0]);

    for (size_t i = 0; i < num_files; ++i) {
        FILE *fp = fopen(input_files[i], "r");
        if (!fp) {
            perror("Error opening file");
            continue;
        }

        size_t num_records, capacity = 0, size = 0;
        long offset_values[MAX_ITEMS];
        int keys[MAX_ITEMS];
        record records[MAX_ITEMS];

        // Populate with random data
        srand(time(NULL));
        for (size_t j = 0; j < MAX_ITEMS && fscanf(fp, "%ld %d", &offset_values[j], &keys[j]) == 2; ++j) {
            records[j].value = rand() % 100;
        }
        num_records = j;

        // Sort records by keys
        qsort(records, num_records, sizeof(record), (int (*)(const void *, const void *))strcmp);

        fclose(fp);
    }

    pthread_mutex_unlock(&mutex);
}

// Main function for demonstration purposes
int main() {
    processAndSortRecordsWithDir("new_directory");

    return 0;
}
