#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_STRING_LENGTH 256
#define INITIAL_POOL_SIZE 1024

typedef struct {
    char packet_tag[64];
    void *context_info;
} CONTEXT_INFO;

typedef struct {
    CONTEXT_INFO data_packet;
} DATA_PACKET;

typedef struct item {
    char string[MAX_STRING_LENGTH];
    int index;
    time_t timestamp;
    struct item* next;
} ITEM;

typedef struct {
    DATA_PACKET** map;
    size_t capacity;
} HASH_MAP;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;

void* memory_pool;
size_t pool_size;

void init_memory_pool(size_t initial_size) {
    memory_pool = malloc(initial_size);
    if (!memory_pool) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    pool_size = initial_size;
}

void* allocate_from_pool(size_t size) {
    pthread_mutex_lock(&mutex);
    void *block = memory_pool; // Simplistic: Assumes the entire block is available
    if (size > pool_size) {
        fprintf(stderr, "Allocation failed: requested size exceeds available memory\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    pool_size -= size;
    pthread_mutex_unlock(&mutex);
    return block;
}

void free_to_pool(void* ptr, size_t size) {
    pthread_mutex_lock(&mutex);
    // Simplistic addition back to the pool
    memory_pool = ptr; 
    pool_size += size;
    pthread_mutex_unlock(&mutex);
}

ITEM* create_item(const char *str, int idx, time_t ts) {
    ITEM* item = allocate_from_pool(sizeof(ITEM));
    if (item) {
        strncpy(item->string, str, MAX_STRING_LENGTH - 1);
        item->index = idx;
        item->timestamp = ts;
        item->next = NULL;
    }
    return item;
}

void free_item(ITEM *item) {
    free_to_pool(item, sizeof(ITEM));
}

HASH_MAP* create_hash_map(size_t capacity) {
    HASH_MAP* map = allocate_from_pool(sizeof(HASH_MAP));
    if (map) {
        pthread_rwlock_wrlock(&rwlock);
        map->capacity = capacity;
        map->map = allocate_from_pool(capacity * sizeof(DATA_PACKET*));
        memset(map->map, 0, capacity * sizeof(DATA_PACKET*));
        pthread_rwlock_unlock(&rwlock);
    }
    return map;
}

void free_hash_map(HASH_MAP *hash_map) {
    pthread_rwlock_wrlock(&rwlock);
    free_to_pool(hash_map->map, hash_map->capacity * sizeof(DATA_PACKET*));
    free_to_pool(hash_map, sizeof(HASH_MAP));
    pthread_rwlock_unlock(&rwlock);
}

float* allocate_float_array(size_t count) {
    return (float*)allocate_from_pool(count * sizeof(float));
}

void free_float_array(float* array) {
    size_t count = pool_size / sizeof(float); // Simplistic calculation
    free_to_pool(array, count * sizeof(float));
}

void add_item(ITEM **head, ITEM *new_item) {
    pthread_mutex_lock(&mutex);
    new_item->next = *head;
    *head = new_item;
    pthread_mutex_unlock(&mutex);
}

ITEM* remove_item(ITEM **head, int index) {
    pthread_mutex_lock(&mutex);
    ITEM *prev = NULL, *curr = *head;

    while (curr && curr->index != index) {
        prev = curr;
        curr = curr->next;
    }

    if (!curr) {
        pthread_mutex_unlock(&mutex);
        return NULL; // Not found
    }

    if (prev) {
        prev->next = curr->next;
    } else {
        *head = curr->next;
    }

    ITEM* removed_item = curr;
    free_to_pool(curr, sizeof(ITEM));
    pthread_mutex_unlock(&mutex);

    return removed_item;
}

void verify_linked_list_integrity(const ITEM *head) {
    const ITEM *current = head;
    while (current && current->next) {
        if (current->timestamp > current->next->timestamp) { // Simplistic verification
            fprintf(stderr, "Linked list integrity violation: out of order timestamps\n");
            break;
        }
        current = current->next;
    }
}

void custom_log(const char *message) {
    static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&log_mutex);
    printf("%s\n", message); // Simplistic logging, replace with a more efficient method as needed
    pthread_mutex_unlock(&log_mutex);
}

// Example usage:
int main() {
    init_memory_pool(INITIAL_POOL_SIZE);

    ITEM *list_head = NULL;
    add_item(&list_head, create_item("Item1", 1, time(NULL)));
    verify_linked_list_integrity(list_head);

    float* array = allocate_float_array(1000);
    HASH_MAP* hash_map = create_hash_map(256);

    // Simulate operations...

    remove_item(&list_head, 1);
    free_float_array(array);
    free_hash_map(hash_map);

    return 0;
}
