#define MAX_DNS_REQUESTS 5
#define DNS_TIMEOUT_SECONDS 2

typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int resolve_dns(const char *hostname, struct in_addr *ip) {
    struct hostent *he;
    struct timeval tv;
    fd_set set;
    int s = socket(AF_INET, SOCK_STREAM, IPPROTO_IP);
    if (s == -1)
        return -1;

    FD_ZERO(&set);
    FD_SET(s, &set);

    tv.tv_sec = DNS_TIMEOUT_SECONDS;
    tv.tv_usec = 0;

    if (select(s + 1, NULL, NULL, NULL, &tv) < 0) {
        close(s);
        return -1;
    }

    he = gethostbyname2(hostname, AF_INET);
    close(s);

    if (!he)
        return -1;

    memcpy(ip, he->h_addr_list[0], sizeof(struct in_addr));
    return 0;
}

void *dns_worker(void *arg) {
    char **hostnames = (char **)arg;
    struct in_addr ip;
    for (int i = 0; hostnames[i] != NULL; i++) {
        if (resolve_dns(hostnames[i], &ip) == 0) {
            printf("Resolved %s to %s\n", hostnames[i], inet_ntoa(ip));
        } else {
            fprintf(stderr, "Failed to resolve %s\n", hostnames[i]);
        }
    }
    return NULL;
}

int create_and_populate_array(int num_pdus, NFAPI_CRC_INDICATION_PDU_T **pdus) {
    *pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*pdus)
        return -1;

    for (int i = 0; i < num_pdus; i++) {
        (*pdus)[i].RX_UE_INFORMATION_TAG = rand() % 256;
        (*pdus)[i].RNTI = rand() % 65536;
        (*pdus)[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    char *hostnames[] = {"example.com", "another-example.com", NULL};
    pthread_t threads[MAX_DNS_REQUESTS];
    int active_threads = 0;

    for (int i = 0; hostnames[i] != NULL; i++) {
        while (active_threads >= MAX_DNS_REQUESTS) {
            usleep(100000); // Sleep for 100ms
        }

        pthread_t thread;
        if (pthread_create(&thread, NULL, dns_worker, (void *)hostnames)) {
            fprintf(stderr, "Error creating thread\n");
            free(*pdus);
            return -1;
        }
        threads[active_threads++] = thread;
    }

    for (int i = 0; i < active_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

void free_array(NFAPI_CRC_INDICATION_PDU_T *pdus) {
    free(pdus);
}
