#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

// Constants for memory pool size
#define INITIAL_POOL_SIZE 1000
#define MAX_PDU_COUNT 10000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Memory pool structure
typedef struct {
    size_t capacity;
    size_t count;
    NFAPI_CRC_INDICATION_PDU_T* pdus;
    pthread_mutex_t lock;
} MemoryPool;

// Logging mechanism
#define LOG_BUFFER_SIZE 1000

typedef struct {
    char buffer[LOG_BUFFER_SIZE][256];
    atomic_size_t head;
    atomic_size_t tail;
    pthread_mutex_t log_lock;
} LogBuffer;

LogBuffer log_buffer = { .head = 0, .tail = 0, .log_lock = PTHREAD_MUTEX_INITIALIZER };

// Function prototypes
void initialize_memory_pool(MemoryPool* pool);
NFAPI_CRC_INDICATION_PDU_T* allocate_pdu_from_pool(MemoryPool* pool);
void free_memory_pool(MemoryPool* pool);
void log_message(const char* message);

// Global variables for list management and synchronization
NFAPI_CRC_INDICATION_PDU_T* pdu_list[MAX_PDU_COUNT];
atomic_size_t list_count = 0;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize memory pool
void initialize_memory_pool(MemoryPool* pool) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->capacity = INITIAL_POOL_SIZE;
    pool->count = 0;
    pool->pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(pool->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

// Allocate PDU from memory pool
NFAPI_CRC_INDICATION_PDU_T* allocate_pdu_from_pool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count < pool->capacity) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &pool->pdus[pool->count++];
        pthread_mutex_unlock(&pool->lock);
        return pdu;
    } else {
        // Handle memory allocation failure
        pthread_mutex_unlock(&pool->lock);
        log_message("Memory pool exhausted, dropping PDU");
        return NULL;
    }
}

// Free memory pool
void free_memory_pool(MemoryPool* pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool->pdus);
}

// Log message to buffer and flush when full
void log_message(const char* message) {
    size_t tail = atomic_fetch_add(&log_buffer.tail, 1) % LOG_BUFFER_SIZE;

    pthread_mutex_lock(&log_buffer.log_lock);
    snprintf(log_buffer.buffer[tail], sizeof(log_buffer.buffer[tail]), "%s\n", message);
    if ((tail + 1) % LOG_BUFFER_SIZE == atomic_load(&log_buffer.head)) {
        // Buffer is full, flush to disk
        for (size_t i = log_buffer.head; i != tail; i = (i + 1) % LOG_BUFFER_SIZE) {
            FILE* log_file = fopen("logs.txt", "a");
            if (log_file) {
                fputs(log_buffer.buffer[i], log_file);
                fclose(log_file);
            }
        }
        atomic_store(&log_buffer.head, tail + 1);
    }
    pthread_mutex_unlock(&log_buffer.log_lock);
}

// Add PDU to list with unique CRCFLAG
int add_pdu_to_list(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    unsigned int crcflag = rand(); // Use a CSPRNG in practice
    while (1) {
        pthread_mutex_lock(&list_lock);
        if (atomic_load(&list_count) < MAX_PDU_COUNT) {
            for (size_t i = 0; i < atomic_load(&list_count); ++i) {
                if (pdu_list[i]->CRC_INDICATION_REL8_TAG.CRCFLAG == crcflag) {
                    pthread_mutex_unlock(&list_lock);
                    crcflag = rand(); // Reassign CRCFLAG
                    break;
                }
            } else {
                pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = crcflag;
                pdu_list[atomic_fetch_add(&list_count, 1)] = pdu;
                pthread_mutex_unlock(&list_lock);
                return 0; // Success
            }
        } else {
            pthread_mutex_unlock(&list_lock);
            log_message("List is full, dropping PDU");
            return -1; // Failure
        }
    }
}

// Initialize the system
void initialize_system() {
    MemoryPool pool;
    initialize_memory_pool(&pool);

    // Set a random seed for reproducibility
    srand(time(NULL)); // Replace with CSPRNG in practice

    // Add PDUs to list
    for (size_t i = 0; i < MAX_PDU_COUNT; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_pdu_from_pool(&pool);
        if (pdu != NULL) {
            add_pdu_to_list(pdu);
        }
    }

    // Cleanup
    free_memory_pool(&pool);
}

int main() {
    initialize_system();
    return 0;
}
```

This code provides a basic implementation of the requirements. It includes thread-safe operations, memory management with a custom pool, logging mechanisms, and unique CRCFLAG assignment. For a production system, you would need to replace `rand()` with a CSPRNG and implement more robust error handling, configuration updates, and performance optimizations.']

