struct record {
    int value;
    time_t timestamp;
    unsigned long unique_id;
};

typedef struct {
    pthread_mutex_t lock;
} memory_manager;

void* init_memory_manager(memory_manager *mgr) {
    pthread_mutex_init(&mgr->lock, NULL);
}

void destroy_memory_manager(memory_manager *mgr) {
    pthread_mutex_destroy(&mgr->lock);
}

int is_password_strong(int value) {
    // Dummy strength check logic
    return value > PASSWORD_STRENGTH_THRESHOLD;
}

struct record* create_record_array(size_t size, memory_manager *mgr) {
    struct record *records = (struct record*) malloc(sizeof(struct record) * size);
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return records;
}

void free_records(struct record *records, size_t size) {
    free(records);
}

int read_integers_from_input(int **array, size_t *size) {
    char buffer[256];
    int count = 0;

    while (fgets(buffer, sizeof(buffer), stdin)) {
        if (sscanf(buffer, "%d", &(*array)[count]) == 1) {
            count++;
        }
    }

    *size = count;
    return (*size > 0);
}

int largest_integer(int *array, size_t size) {
    int max_val = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > max_val) {
            max_val = array[i];
        }
    }
    return max_val;
}

void convert_jpeg_to_pdf(const char *jpeg_path, const char *pdf_path) {
    Image *image = NULL;
    image = CastImage(image_read(jpeg_path), "PDF");
    if (!image) {
        fprintf(stderr, "Failed to read JPEG file\n");
        exit(EXIT_FAILURE);
    }

    // Set up error handling
    MagickBooleanType status = MagickSetErrorVerbose(img, true);

    status = ImageWrite(image, pdf_path);
    if (status == False) {
        fprintf(stderr, "Failed to convert JPEG to PDF\n");
        image_destroy(image);
        exit(EXIT_FAILURE);
    }

    image_destroy(image);
}

void processMediaAndData() {
    memory_manager mgr;
    init_memory_manager(&mgr);

    int *input_array = NULL;
    size_t input_size;

    if (!read_integers_from_input(&input_array, &input_size)) {
        fprintf(stderr, "No integers read from input\n");
        return 1;
    }

    struct record *records = create_record_array(input_size, &mgr);
    int largest_num = -1;

    for (size_t i = 0; i < input_size; ++i) {
        pthread_mutex_lock(&mgr.lock);

        if (!is_password_strong(input_array[i])) {
            fprintf(stderr, "Password strength check failed for %d\n", input_array[i]);
            continue;
        }

        records[i].value = input_array[i];
        records[i].timestamp = time(NULL);
        records[i].unique_id = (unsigned long)rand();

        if (input_array[i] > largest_num) {
            largest_num = input_array[i];
        }

        pthread_mutex_unlock(&mgr.lock);
    }

    printf("Largest integer: %d\n", largest_num);

    // Example file paths
    const char *jpeg_path = "example.jpg";
    const char *pdf_path = "output.pdf";

    convert_jpeg_to_pdf(jpeg_path, pdf_path);

    free_records(records, input_size);
    free(input_array);

    destroy_memory_manager(&mgr);

    return 0;
}
```

**Notes:**
- The function uses `pthread_mutex_t` for thread-safe memory operations.
- It reads integers from standard input and stores them in an array.
- Each integer is checked against a simple password strength criteria.
- The largest integer is determined using a straightforward linear search.
- ImageMagick's C API is used to convert JPEG images to PDF format with error handling.
- Memory allocation failures are handled by exiting the program gracefully.']

