```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_MEMORY_USAGE_MB 50 * 1024 * 1024 // 50 MB
#define MAX_STRUCTURE_SIZE 64 * 1024         // 64 KB
#define MEMORY_THRESHOLD_PERCENTAGE 90

typedef struct {
    unsigned int RNTI;
    unsigned int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev; // For LRU management
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t current_memory_usage;
} LinkedList;

// Function prototypes
LinkedList* create_list();
void destroy_list(LinkedList* list);
int add_structure(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T structure);
Node* find_lru_node(LinkedList* list);
void remove_node(Node* node, LinkedList* list);
void log_memory_usage(size_t current, size_t max_capacity);

// Create a new linked list
LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->current_memory_usage = 0;
    return list;
}

// Destroy the linked list and free all allocated memory
void destroy_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }
    free(list);
}

// Validate CRC_INDICATION_REL8_TAG for correctness
int validate_crc_tag(CRC_INDICATION_REL8_TAG tag) {
    // Implement your validation logic here, return 1 if valid else 0
    // Example:
    return (tag.CRCFLAG % 2 == 0); // Dummy condition: even CRCFLAG is considered valid
}

// Add a new structure to the linked list
int add_structure(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T structure) {
    if (!validate_crc_tag(structure.CRC_INDICATION_REL8_TAG)) {
        printf("Invalid CRC tag, ignoring structure.\n");
        return 0;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node || sizeof(NFAPI_CRC_INDICATION_PDU_T) > MAX_STRUCTURE_SIZE) {
        printf("Memory allocation failed or size constraint exceeded.\n");
        if (new_node) free(new_node);
        return 0;
    }

    // Calculate new memory usage
    size_t potential_memory_usage = list->current_memory_usage + sizeof(NFAPI_CRC_INDICATION_PDU_T);

    while (potential_memory_usage > MAX_MEMORY_USAGE_MB) {
        Node* lru_node = find_lru_node(list);
        if (!lru_node) return 0; // Unable to free enough memory
        remove_node(lru_node, list);
    }

    new_node->data = structure;
    new_node->next = NULL;

    if (list->tail == NULL) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }

    list->current_memory_usage += sizeof(NFAPI_CRC_INDICATION_PDU_T);

    // Log memory usage if it exceeds threshold
    float memory_percentage = (float)list->current_memory_usage / MAX_MEMORY_USAGE_MB * 100;
    if (memory_percentage > MEMORY_THRESHOLD_PERCENTAGE) {
        log_memory_usage(list->current_memory_usage, MAX_MEMORY_USAGE_MB);
    }

    return 1;
}

// Find the least recently used node
Node* find_lru_node(LinkedList* list) {
    Node* lru = NULL;
    Node* current = list->head;

    while (current != NULL) {
        if (!lru || strcmp(&current->data.RX_UE_INFORMATION_TAG, &lru->data.RX_UE_INFORMATION_TAG) < 0)
            lru = current;
        current = current->next;
    }

    return lru;
}

// Remove a node from the linked list
void remove_node(Node* node, LinkedList* list) {
    if (node == NULL || node == list->tail && node == list->head) {
        list->head = list->tail = NULL;
    } else if (node == list->head) {
        list->head = node->next;
        if (list->head) list->head->prev = NULL;
    } else if (node == list->tail) {
        list->tail = node->prev;
        if (list->tail) list->tail->next = NULL;
    } else {
        Node* prev_node = node->prev;
        Node* next_node = node->next;
        prev_node->next = next_node;
        next_node->prev = prev_node;
    }

    list->current_memory_usage -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
    free(node);
}

// Log the current memory usage and capacity
void log_memory_usage(size_t current, size_t max_capacity) {
    printf("Memory usage is at %.2f%% of maximum capacity. Current: %zu bytes, Capacity: %zu bytes\n",
           (float)current / max_capacity * 100, current, max_capacity);
}

int main() {
    // Example usage
    LinkedList* list = create_list();

    NFAPI_CRC_INDICATION_PDU_T structure;
    structure.RX_UE_INFORMATION_TAG = 1;
    structure.RNTI = 12345;
    structure.CRC_INDICATION_REL8_TAG.CRCFLAG = 2; // Valid example

    add_structure(list, structure);

    destroy_list(list);

    return 0;
}
```

### Key Points:
- **Memory Constraints:** The implementation ensures that memory usage does not exceed 50 MB. It calculates and logs when it reaches a predefined threshold.
- **LRU Management:** It uses linked list pointers to maintain least recently used nodes, allowing efficient removal of the oldest entries.
- **Validation:** Before adding a structure, it validates the `CRC_INDICATION_REL8_TAG` and logs invalid tags.
- **Dynamic Memory Management:** The code dynamically manages memory by allocating new structures only when there is sufficient capacity or after freeing older structures.']

