typedef struct {
    int type;
    void *payload;
    struct metadata *metadata;
} struct_event;

typedef struct {
    char context[256];
} struct_metadata;

typedef struct {
    time_t timestamp;
    unsigned long unique_id;
    struct_event **events;
    size_t num_events;
    struct_metadata **metadatas;
    size_t num_metadatas;
} struct_record;

typedef struct handler_node {
    struct record *record;
    struct handler_node *next;
} struct_handler;

// Hash table for events
typedef struct {
    struct event **buckets;
    size_t size;
    size_t (*hash_function)(struct event *, size_t);
} hash_table;

// Function prototypes
void init_metadata(struct metadata **metadata, size_t count);
unsigned long generate_unique_id();
time_t current_time();
size_t hash_by_type(struct event *event, size_t table_size);
size_t hash_by_payload(struct event *event, size_t table_size);
size_t hash_by_timestamp(struct_event *event, size_t table_size);
void insert_event(hash_table *table, struct_event *event);
struct event* find_event(hash_table *table, void *key);

// Main function to allocate and initialize arrays
int create_and_init_arrays(int num_elements, int type) {
    if (num_elements < 5 || num_elements > 15) return -1;

    size_t element_size = sizeof(void*);
    void **arrays[num_elements];

    for (int i = 0; i < num_elements; ++i) {
        arrays[i] = malloc(type * element_size);
        if (!arrays[i]) {
            // Free already allocated memory
            for (int j = 0; j < i; ++j) free(arrays[j]);
            return -2;
        }
    }

    for (int i = 0; i < num_elements; ++i) {
        if (type == sizeof(struct_record*)) {
            struct_record *record = malloc(sizeof(struct_record));
            if (!record) {
                // Free already allocated memory
                for (int j = 0; j <= i; ++j) free(arrays[j]);
                return -2;
            }
            record->timestamp = current_time();
            record->unique_id = generate_unique_id();
            init_metadata((struct metadata**)&(record->metadatas), 5); // Assume 5 as a default
            arrays[i][0] = (void*)record;
        } else if (type == sizeof(struct_handler*)) {
            struct_handler *handler = malloc(sizeof(struct_handler));
            if (!handler) {
                for (int j = 0; j <= i; ++j) free(arrays[j]);
                return -2;
            }
