['Below is the implementation of the C code based on your requirements. This includes functions for adding, updating, removing `Measurement` objects from a doubly linked list, as well as exporting the collection to a file.

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pthread.h>

typedef struct Measurement {
    double value;
    char *identifier;
    struct Measurement *prev;
    struct Measurement *next;
} Measurement;

typedef struct {
    Measurement *head;
    Measurement *tail;
    pthread_mutex_t lock;
} MeasurementList;

Measurement* create_measurement(double min, double max, int sequence) {
    Measurement *measurement = (Measurement *)malloc(sizeof(Measurement));
    if (!measurement) return NULL;

    // Generate a random value within the specified range
    srand(time(NULL) ^ (intptr_t)pthread_self());
    measurement->value = min + ((double)rand() / RAND_MAX) * (max - min);

    // Create a unique identifier based on current time and sequence number
    char buffer[50];
    snprintf(buffer, sizeof(buffer), "ID_%ld_%d", time(NULL), sequence);
    measurement->identifier = strdup(buffer);
    if (!measurement->identifier) {
        free(measurement);
        return NULL;
    }

    measurement->prev = measurement->next = NULL;

    return measurement;
}

MeasurementList* create_list() {
    MeasurementList *list = (MeasurementList *)malloc(sizeof(MeasurementList));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

int add_measurement(MeasurementList *list, double min, double max) {
    pthread_mutex_lock(&list->lock);

    int sequence = 1;
    Measurement *current = list->head;
    while (current) {
        sequence++;
        current = current->next;
    }

    Measurement *newMeasurement = create_measurement(min, max, sequence);
    if (!newMeasurement) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    if (list->tail) {
        list->tail->next = newMeasurement;
        newMeasurement->prev = list->tail;
        list->tail = newMeasurement;
    } else {
        list->head = list->tail = newMeasurement;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int update_measurement(MeasurementList *list, double newValue) {
    pthread_mutex_lock(&list->lock);

    Measurement *current = list->head;
    while (current) {
        current->value = newValue; // Assuming the entire list is updated
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_measurement(MeasurementList *list, const char *identifier) {
    pthread_mutex_lock(&list->lock);

    Measurement *current = list->head;
    while (current && strcmp(current->identifier, identifier) != 0) {
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Not found
    }

    if (current->prev) {
        current->prev->next = current->next;
    } else {
        list->head = current->next;
    }

    if (current->next) {
        current->next->prev = current->prev;
    } else {
        list->tail = current->prev;
    }

    free(current->identifier);
    free(current);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int export_measurements(MeasurementList *list, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        perror("Unable to open file for writing");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    Measurement *current = list->head;
    while (current) {
        fprintf(file, "Value: %f, Identifier: %s\n", current->value, current->identifier);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);

    return 0;
}

void free_list(MeasurementList *list) {
    pthread_mutex_lock(&list->lock);

    Measurement *current = list->head;
    while (current) {
        Measurement *toFree = current;
        current = current->next;

        free(toFree->identifier);
        free(toFree);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
```

### Key Points:
- **Concurrency**: The `pthread_mutex_t lock` ensures that the list operations are thread-safe.
- **Error Handling**: Memory allocation failures and file opening errors are handled gracefully.
- **Dynamic Memory Management**: Each measurement is dynamically allocated, and memory is freed appropriately to prevent leaks.']

