#define INITIAL_CAPACITY 10

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t used;
    size_t capacity;
    pthread_mutex_t lock; // Mutex for thread-safety
} CRC_Indication_Manager;

// Function prototypes
CRC_Indication_Manager* create_manager();
void free_manager(CRC_Indication_Manager *manager);
int add_pdu(CRC_Indication_Manager *manager, NFAPI_CRC_INDICATION_PDU_T pdu);
NFAPI_CRC_INDICATION_PDU_T* get_pdu(CRC_Indication_Manager *manager, size_t index);

// Function implementations
CRC_Indication_Manager* create_manager() {
    CRC_Indication_Manager *manager = (CRC_Indication_Manager*) malloc(sizeof(CRC_Indication_Manager));
    if (!manager) return NULL;

    manager->array = (NFAPI_CRC_INDICATION_PDU_T *) calloc(INITIAL_CAPACITY, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);

    manager->used = 0;
    manager->capacity = INITIAL_CAPACITY;

    return manager;
}

void free_manager(CRC_Indication_Manager *manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->lock);
        free(manager->array);
        free(manager);
    }
}

int add_pdu(CRC_Indication_Manager *manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&manager->lock);

    if (manager->used == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_array) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Out of memory
        }

        manager->array = new_array;
        manager->capacity = new_capacity;
    }

    manager->array[manager->used++] = pdu;

    // Simulate setting CRCFLAG randomly
    srand(time(NULL) + rand());  // Ensure randomness across threads and calls
    pdu.crcRel8Tag.crcFlag = rand() % 2;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu(CRC_Indication_Manager *manager, size_t index) {
    if (index >= manager->used) {
        // Handle out-of-bounds error appropriately
        return NULL;
    }

    pthread_mutex_lock(&manager->lock);
    NFAPI_CRC_INDICATION_PDU_T *pdu = &manager->array[index];
    pthread_mutex_unlock(&manager->lock);

    return pdu;
}

// Logging function for monitoring and debugging purposes
