#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        _Atomic int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    size_t capacity;
    size_t count;
    NFAPI_CRC_INDICATION_PDU_T *data;
    pthread_mutex_t lock;
    _Atomic size_t error_count;
} CRCIndicationList;

CRCIndicationList* create_crc_indication_list(size_t max_capacity) {
    CRCIndicationList *list = malloc(sizeof(CRCIndicationList));
    if (!list) return NULL;

    list->capacity = 0;
    list->count = 0;
    list->data = NULL;
    pthread_mutex_init(&list->lock, NULL);
    atomic_store(&list->error_count, 0);

    size_t allocation_size = max_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    list->data = malloc(allocation_size);
    if (!list->data) {
        free(list);
        return NULL;
    }
    list->capacity = max_capacity;

    // Initialize CRCFLAG randomly
    srand(time(NULL));
    for (size_t i = 0; i < max_capacity; ++i) {
        pthread_mutex_lock(&list->lock);
        if (list->count >= max_capacity) break;

        list->data[list->count].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
        list->data[list->count].RX_UE_INFORMATION_TAG = rand();
        list->data[list->count].RNTI = rand();
        atomic_fetch_add(&list->count, 1);

        pthread_mutex_unlock(&list->lock);
    }

    return list;
}

int add_crc_indication(CRCIndicationList *list, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (!list || !entry) return -1;

    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        pthread_mutex_unlock(&list->lock);
        atomic_fetch_add(&list->error_count, 1);
        return -2;
    }

    size_t index = atomic_load(&list->count);
    list->data[index] = entry;
    atomic_fetch_add(&list->count, 1);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_crc_indication_list(CRCIndicationList *list, size_t *count) {
    if (!list || !count) return NULL;

    pthread_mutex_lock(&list->lock);
    *count = atomic_load(&list->count);
    NFAPI_CRC_INDICATION_PDU_T *result = malloc(*count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (result) {
        for (size_t i = 0; i < *count; ++i) {
            result[i] = list->data[i];
        }
    }
    pthread_mutex_unlock(&list->lock);
    return result;
}

void free_crc_indication_list(CRCIndicationList *list) {
    if (!list) return;

    pthread_mutex_destroy(&list->lock);
    free(list->data);
    free(list);
}

void report_crc_indication_list_status(CRCIndicationList *list, size_t *valid_entries, size_t *error_count) {
    if (!list || !valid_entries || !error_count) return;

    pthread_mutex_lock(&list->lock);
    *valid_entries = atomic_load(&list->count);
    *error_count = atomic_load(&list->error_count);
    pthread_mutex_unlock(&list->lock);
}

int main() {
    CRCIndicationList *list = create_crc_indication_list(1000);
    if (!list) {
        printf("Failed to create list\n");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T entry = {.RX_UE_INFORMATION_TAG = 1234, .RNTI = 5678};
    if (add_crc_indication(list, entry) != 0) {
        printf("Error adding indication\n");
    }

    size_t valid_entries;
    report_crc_indication_list_status(list, &valid_entries, NULL);
    printf("Valid entries: %zu\n", valid_entries);

    NFAPI_CRC_INDICATION_PDU_T *data = get_crc_indication_list(list, &valid_entries);
    if (data) {
        // Process data
        free(data);
    }

    free_crc_indication_list(list);
    return 0;
}
