#include <time.h>

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG; // Randomly set value
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;
    FILE* log_file;
} NFAPIList;

// Function to create a new node
Node* create_node(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = pdu;
    new_node->next = NULL;
    return new_node;
}

// Function to initialize the list
NFAPIList* init_list(const char* log_filename) {
    NFAPIList* list = (NFAPIList*)malloc(sizeof(NFAPIList));
    if (!list) return NULL;

    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    // Open log file
    list->log_file = fopen(log_filename, "a");
    if (!list->log_file) {
        free(list);
        return NULL;
    }
    return list;
}

// Function to destroy the list and free memory
void destroy_list(NFAPIList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    fclose(list->log_file);
    free(list);
}

// Function to log operations
void log_operation(NFAPIList* list, const char* message) {
    if (list->log_file) {
        fprintf(list->log_file, "%s\n", message);
        fflush(list->log_file);
    }
}

// Function to add or update an entry in the list
void add_or_update_entry(NFAPIList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    Node** current = &list->head;
    while (*current) {
        if ((*current)->data.RNTI == pdu.RNTI) {
            (*current)->data = pdu; // Update existing entry
            log_operation(list, "Updated entry with RNTI: ");
            pthread_mutex_unlock(&list->lock);
            return;
        }
        current = &(*current)->next;
    }

    Node* new_node = create_node(pdu);
    if (new_node) {
        new_node->next = list->head;
        list->head = new_node;
        list->count++;
        log_operation(list, "Added entry with RNTI: ");
    } else {
        log_operation(list, "Failed to add entry due to memory allocation failure");
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to serialize the list to a file
int serialize_list(NFAPIList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
    log_operation(list, "Serialized list to file");
    return 0;
}

// Function to deserialize the list from a file
int deserialize_list(NFAPIList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    pthread_mutex_lock(&list->lock);

    // Clear existing list
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;

    NFAPI_CRC_INDICATION_PDU_T pdu;
    while (fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        add_or_update_entry(list, pdu);
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
    log_operation(list, "Deserialized list from file");
    return 0;
}

// Function to get statistics about the list
void get_list_stats(NFAPIList* list) {
    pthread_mutex_lock(&list->lock);

    printf("Number of elements: %zu\n", list->count);
    // Add more stats as needed

    pthread_mutex_unlock(&list->lock);
}
