```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_LIST_SIZE 10000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
    int successful_adds;
    int failed_adds;
    int successful_updates;
    int failed_updates;
    FILE* log_file;
} CRCList;

CRCList* create_list(const char* log_path, size_t max_size) {
    if (max_size > MAX_LIST_SIZE) return NULL;

    CRCList* list = malloc(sizeof(CRCList));
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->successful_adds = 0;
    list->failed_adds = 0;
    list->successful_updates = 0;
    list->failed_updates = 0;

    list->log_file = fopen(log_path, "w");
    if (!list->log_file) {
        free(list);
        return NULL;
    }
    return list;
}

void log_operation(CRCList* list, const char* operation, int success) {
    fprintf(list->log_file, "%s: %s\n", operation, success ? "Success" : "Failure");
    if (strcmp(operation, "Add") == 0)
        success ? list->successful_adds++ : list->failed_adds++;
    else if (strcmp(operation, "Update") == 0)
        success ? list->successful_updates++ : list->failed_updates++;
}

void add_entry(CRCList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= MAX_LIST_SIZE) {
        log_operation(list, "Add", 0);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        log_operation(list, "Add", 0);
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_node->data = entry;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    log_operation(list, "Add", 1);

    pthread_mutex_unlock(&list->lock);
}

void update_entry(CRCList* list, unsigned int rnti, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current) {
        if (current->data.RNTI == rnti) {
            current->data = entry;
            log_operation(list, "Update", 1);
            break;
        }
        current = current->next;
    }

    if (!current) {
        log_operation(list, "Update", 0);
    }

    pthread_mutex_unlock(&list->lock);
}

void serialize_list(CRCList* list, const char* file_path) {
    pthread_mutex_lock(&list->lock);

    FILE* file = fopen(file_path, "wb");
    if (!file) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* current = list->head;
    while (current) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);

    pthread_mutex_unlock(&list->lock);
}

void deserialize_list(CRCList* list, const char* file_path) {
    pthread_mutex_lock(&list->lock);

    FILE* file = fopen(file_path, "rb");
    if (!file) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    while (fread(&(NFAPI_CRC_INDICATION_PDU_T){0}, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        add_entry(list, *(NFAPI_CRC_INDICATION_PDU_T*)file);
    }

    fclose(file);

    pthread_mutex_unlock(&list->lock);
}

void filter_and_sort(CRCList* list, unsigned int tag) {
    pthread_mutex_lock(&list->lock);

    Node** array = malloc(sizeof(Node*) * list->size);
    size_t count = 0;

    Node* current = list->head;
    while (current) {
        if (current->data.RX_UE_INFORMATION_TAG == tag) {
            array[count++] = current;
        }
        current = current->next;
    }

    // Simple bubble sort by RNTI
    for (size_t i = 0; i < count - 1; i++) {
        for (size_t j = 0; j < count - i - 1; j++) {
            if (array[j]->data.RNTI > array[j + 1]->data.RNTI) {
                Node* temp = array[j];
                array[j] = array[j + 1];
                array[j + 1] = temp;
            }
        }
    }

    // Print sorted entries
    for (size_t i = 0; i < count; i++) {
        printf("RNTI: %u, CRCFLAG: %d\n", array[i]->data.RNTI, array[i]->data.CRCFLAG);
    }

    free(array);

    pthread_mutex_unlock(&list->lock);
}

void destroy_list(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    fclose(list->log_file);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void random_crcflag(NFAPI_CRC_INDICATION_PDU_T* entry) {
    srand(time(NULL));
    entry->CRCFLAG = rand() % 2;
}

int main() {
    CRCList* list = create_list("log.txt", MAX_LIST_SIZE);

    if (!list) return EXIT_FAILURE;

    NFAPI_CRC_INDICATION_PDU_T entry1 = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 1001 };
    random_crcflag(&entry1);
    add_entry(list, entry1);

    NFAPI_CRC_INDICATION_PDU_T entry2 = { .RX_UE_INFORMATION_TAG = 2, .RNTI = 1002 };
    random_crcflag(&entry2);
    add_entry(list, entry2);

    update_entry(list, 1001, (NFAPI_CRC_INDICATION_PDU_T){.RX_UE_INFORMATION_TAG = 1, .RNTI = 1001, .CRCFLAG = 1});

    serialize_list(list, "data.bin");
    deserialize_list(list, "data.bin");

    filter_and_sort(list, 1);

    destroy_list(list);
    return EXIT_SUCCESS;
}
