#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef enum { INT_TYPE, FLOAT_TYPE, STRUCT_TYPE, TIMESTAMP_TYPE, THREAD_ID_TYPE } DataType;

typedef struct {
    int intValue;
} IntData;

typedef struct {
    float floatValue;
} FloatData;

typedef struct {
    char complexStr[100];
} StructData;

typedef struct {
    time_t timestampValue;
} TimestampData;

typedef struct {
    pthread_t threadIdValue;
} ThreadIdData;

typedef union {
    IntData intData;
    FloatData floatData;
    StructData structData;
    TimestampData timestampData;
    ThreadIdData threadIdData;
} DataUnion;

typedef struct Node {
    void *data;
    DataType type;
    struct Node *left, *right;
    unsigned int height;
} Node;

typedef struct BST {
    Node *root;
    pthread_mutex_t lock;
} BST;

// Function prototypes
Node* newNode(void *data, DataType type);
int height(Node *N);
int max(int a, int b);
Node* rightRotate(Node *y);
Node* leftRotate(Node *x);
int getBalance(Node *N);
Node* insertNode(Node *node, void *data, DataType type);
BST* createBST();
void freeNode(Node *node);
void destroyBST(BST *tree);
Node* search(Node *root, void *key, DataType keyType);
Node* minValueNode(Node *node);
Node* deleteNode(Node *root, void *key, DataType keyType);
int BST_insert(BST *tree, void *data, DataType type);
int BST_delete(BST *tree, void *key, DataType keyType);
void *BST_search(BST *tree, void *key, DataType keyType);

// Node creation
Node* newNode(void *data, DataType type) {
    Node *node = (Node *)malloc(sizeof(Node));
    if (!node) return NULL;
    node->data = malloc(100); // Adjust size based on expected data
    memcpy(node->data, data, 100);
    node->type = type;
    node->left = node->right = NULL;
    node->height = 1;
    return node;
}

// Height of the tree
int height(Node *N) {
    if (N == NULL)
        return 0;
    return N->height;
}

// Maximum of two integers
int max(int a, int b) {
    return (a > b) ? a : b;
}

// Right rotate subtree rooted with y
Node* rightRotate(Node *y) {
    Node *x = y->left;
    Node *T2 = x->right;

    // Perform rotation
    x->right = y;
    y->left = T2;

    // Update heights
    y->height = max(height(y->left), height(y->right)) + 1;
    x->height = max(height(x->left), height(x->right)) + 1;

    return x;
}

// Left rotate subtree rooted with x
Node* leftRotate(Node *x) {
    Node *y = x->right;
    Node *T2 = y->left;

    // Perform rotation
    y->left = x;
    x->right = T2;

    // Update heights
    x->height = max(height(x->left), height(x->right)) + 1;
    y->height = max(height(y->left), height(y->right)) + 1;

    return y;
}

// Get balance factor of node N
int getBalance(Node *N) {
    if (N == NULL)
        return 0;
    return height(N->left) - height(N->right);
}

// Insert a new node with given data
Node* insertNode(Node *node, void *data, DataType type) {
    if (node == NULL)
        return newNode(data, type);

    if (type == INT_TYPE && *(int *)data < *(int *)(node->data))
        node->left = insertNode(node->left, data, type);
    else if (type == FLOAT_TYPE && *(float *)data < *(float *)(node->data))
        node->left = insertNode(node->left, data, type);
    else
        node->right = insertNode(node->right, data, type);

    node->height = 1 + max(height(node->left), height(node->right));

    int balance = getBalance(node);

    // Left Left Case
    if (balance > 1 && (type == INT_TYPE ? *(int *)data < *(int *)(node->left->data) : *(float *)data < *(float *)(node->left->data)))
        return rightRotate(node);

    // Right Right Case
    if (balance < -1 && (type == INT_TYPE ? *(int *)data > *(int *)(node->right->data) : *(float *)data > *(float *)(node->right->data)))
        return leftRotate(node);

    // Left Right Case
    if (balance > 1 && (type == INT_TYPE ? *(int *)data > *(int *)(node->left->data) : *(float *)data > *(float *)(node->left->data))) {
        node->left = leftRotate(node->left);
        return rightRotate(node);
    }

    // Right Left Case
    if (balance < -1 && (type == INT_TYPE ? *(int *)data < *(int *)(node->right->data) : *(float *)data < *(float *)(node->right->data))) {
        node->right = rightRotate(node->right);
        return leftRotate(node);
    }

    return node;
}

// Create a new BST
BST* createBST() {
    BST *tree = (BST *)malloc(sizeof(BST));
    if (!tree) return NULL;
    tree->root = NULL;
    pthread_mutex_init(&tree->lock, NULL);
    return tree;
}

// Free a node
void freeNode(Node *node) {
    if (node != NULL) {
        free(node->data);
        free(node);
    }
}

// Destroy the BST
void destroyBST(BST *tree) {
    if (tree) {
        pthread_mutex_destroy(&tree->lock);
        // Implement tree traversal to free all nodes
        free(tree);
    }
}

// Search for a node with given key
Node* search(Node *root, void *key, DataType keyType) {
    if (root == NULL || 
       (keyType == INT_TYPE && *(int *)key == *(int *)(root->data)) ||
       (keyType == FLOAT_TYPE && *(float *)key == *(float *)(root->data)))
        return root;

    if ((keyType == INT_TYPE ? *(int *)key < *(int *)(root->data) : *(float *)key < *(float *)(root->data)))
        return search(root->left, key, keyType);

    return search(root->right, key, keyType);
}

// Find the node with minimum value
Node* minValueNode(Node *node) {
    Node *current = node;
    while (current->left != NULL)
        current = current->left;
    return current;
}

// Delete a node with given key
Node* deleteNode(Node *root, void *key, DataType keyType) {
    if (root == NULL)
        return root;

    if ((keyType == INT_TYPE && *(int *)key < *(int *)(root->data)) ||
        (keyType == FLOAT_TYPE && *(float *)key < *(float *)(root->data)))
        root->left = deleteNode(root->left, key, keyType);
    else if ((keyType == INT_TYPE && *(int *)key > *(int *)(root->data)) ||
             (keyType == FLOAT_TYPE && *(float *)key > *(float *)(root->data)))
        root->right = deleteNode(root->right, key, keyType);
    else {
        if ((root->left == NULL) || (root->right == NULL)) {
            Node *temp = root->left ? root->left : root->right;

            if (temp == NULL) {
                temp = root;
                root = NULL;
            } else
                *root = *temp;

            freeNode(temp);
        } else {
            Node *temp = minValueNode(root->right);

            freeNode(root->data);

            *(void **)(&root->data) = temp->data;
            root->type = temp->type;

            root->right = deleteNode(root->right, temp->data, temp->type);
        }
    }

    if (root == NULL)
        return root;

    root->height = 1 + max(height(root->left), height(root->right));

    int balance = getBalance(root);

    // Left Left Case
    if (balance > 1 && getBalance(root->left) >= 0)
        return rightRotate(root);

    // Left Right Case
    if (balance > 1 && getBalance(root->left) < 0) {
        root->left = leftRotate(root->left);
        return rightRotate(root);
    }

    // Right Right Case
    if (balance < -1 && getBalance(root->right) <= 0)
        return leftRotate(root);

    // Right Left Case
    if (balance < -1 && getBalance(root->right) > 0) {
        root->right = rightRotate(root->right);
        return leftRotate(root);
    }

    return root;
}

// Insert data into the BST
int BST_insert(BST *tree, void *data, DataType type) {
    if (!tree || !data) return -1;

    pthread_mutex_lock(&tree->lock);
    tree->root = insertNode(tree->root, data, type);
    pthread_mutex_unlock(&tree->lock);

    return 0;
}

// Delete data from the BST
int BST_delete(BST *tree, void *key, DataType keyType) {
    if (!tree || !key) return -1;

    pthread_mutex_lock(&tree->lock);
    tree->root = deleteNode(tree->root, key, keyType);
    pthread_mutex_unlock(&tree->lock);

    return 0;
}

// Search data in the BST
void *BST_search(BST *tree, void *key, DataType keyType) {
    if (!tree || !key) return NULL;

    pthread_mutex_lock(&tree->lock);
    Node *result = search(tree->root, key, keyType);
    pthread_mutex_unlock(&tree->lock);

    return result ? result->data : NULL;
}

// Example usage
int main() {
    BST *tree = createBST();

    int intData = 10;
    BST_insert(tree, &intData, INT_TYPE);

    float floatData = 20.5f;
    BST_insert(tree, &floatData, FLOAT_TYPE);

    void *result = BST_search(tree, &intData, INT_TYPE);
    if (result) printf("Found: %d\n", *(int *)result);

    destroyBST(tree);
    return 0;
}
