#define MAX_ENTRIES 1000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

// Function prototypes
int insert_or_update_entry(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T entry);
int remove_oldest_entry(DynamicArray* array);
void print_all_entries(const DynamicArray* array);

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->head = NULL;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

int insert_or_update_entry(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&array->lock);

    Node* current = array->head;
    Node* prev = NULL;

    while (current != NULL) {
        if (current->data.RNTI == entry.RNTI) {
            current->data.CRCFLAG = entry.CRCFLAG;
            pthread_mutex_unlock(&array->lock);
            return 0; // Success
        }
        prev = current;
        current = current->next;
    }

    if (array->count >= MAX_ENTRIES) {
        remove_oldest_entry(array);
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Failure
    }
    new_node->data = entry;
    new_node->next = array->head;
    array->head = new_node;
    array->count++;

    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

int remove_oldest_entry(DynamicArray* array) {
    if (array->head == NULL) return -1;

    Node* temp = array->head;
    array->head = array->head->next;
    free(temp);
    array->count--;
    return 0;
}

void print_all_entries(const DynamicArray* array) {
    pthread_mutex_lock((pthread_mutex_t*)&array->lock);

    Node* current = array->head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRCFLAG: %d\n",
               current->data.RTX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.CRCFLAG);
        current = current->next;
    }

    pthread_mutex_unlock((pthread_mutex_t*)&array->lock);
}

void destroy_dynamic_array(DynamicArray* array) {
    Node* current = array->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&array->lock);
    free(array);
}
