#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int hour;
    int minute;
} timestamp;

typedef struct {
    double metric_value;
    char status_indicator;
    timestamp start_time;
    timestamp end_time;
} resource_monitoring;

typedef struct node {
    resource_monitoring data;
    struct node* next;
} list_node;

// Global lock for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void free_resource_list(list_node* head) {
    while (head != NULL) {
        list_node* temp = head;
        head = head->next;
        free(temp);
    }
}

int compare_timestamps(const void* a, const void* b) {
    resource_monitoring* recordA = (resource_monitoring*)a;
    resource_monitoring* recordB = (resource_monitoring*)b;

    if (recordA->start_time.hour < recordB->start_time.hour) return -1;
    if (recordA->start_time.hour > recordB->start_time.hour) return 1;

    if (recordA->start_time.minute < recordB->start_time.minute) return -1;
    if (recordA->start_time.minute > recordB->start_time.minute) return 1;

    return 0;
}

void smooth_metrics(resource_monitoring* records, size_t count) {
    for (size_t i = 1; i < count - 1; ++i) {
        records[i].metric_value = (records[i-1].metric_value + records[i].metric_value + records[i+1].metric_value) / 3.0;
    }
}

list_node* allocate_resources(size_t num_records, int error_code) {
    pthread_mutex_lock(&lock);

    list_node* head = NULL;
    list_node** current_ptr = &head;

    for (size_t i = 0; i < num_records; ++i) {
        list_node* new_node = malloc(sizeof(list_node));
        if (!new_node) {
            free_resource_list(head);
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        resource_monitoring* record = &new_node->data;

        // Simulate metric value and status
        record->metric_value = (rand() % 100) / 10.0; 
        record->status_indicator = 'A' + rand() % 3;
        record->start_time.hour = rand() % 24;
        record->start_time.minute = rand() % 60;
        record->end_time.hour = record->start_time.hour + (rand() % 3);
        record->end_time.minute = record->start_time.minute + (rand() % 30);

        *current_ptr = new_node;
        current_ptr = &new_node->next;
    }

    pthread_mutex_unlock(&lock);
    return head;
}

list_node* query_resources(list_node* head, timestamp start_range, timestamp end_range) {
    list_node* result_head = NULL;
    list_node** result_ptr = &result_head;

    while (head != NULL) {
        if ((head->data.start_time.hour >= start_range.hour && 
             head->data.start_time.minute >= start_range.minute) &&
            (head->data.end_time.hour <= end_range.hour &&
             head->data.end_time.minute <= end_range.minute)) {

            list_node* new_node = malloc(sizeof(list_node));
            if (!new_node) {
                free_resource_list(result_head);
                return NULL;
            }

            *result_ptr = new_node;
            result_ptr = &new_node->next;
            memcpy(&new_node->data, &(head->data), sizeof(resource_monitoring));
        }
        head = head->next;
    }
    *result_ptr = NULL;
    return result_head;
}

list_node* sort_resources(list_node* head) {
    if (!head || !head->next) return head;

    size_t count = 0;
    list_node* temp = head;
    while (temp != NULL) {
        ++count;
        temp = temp->next;
    }

    resource_monitoring* array = malloc(count * sizeof(resource_monitoring));
    if (!array) return NULL;

    temp = head;
    size_t i = 0;
    while (temp != NULL) {
        array[i++] = temp->data;
        temp = temp->next;
    }

    qsort(array, count, sizeof(resource_monitoring), compare_timestamps);

    list_node* sorted_head = NULL;
    list_node** current_ptr = &sorted_head;

    for (i = 0; i < count; ++i) {
        list_node* new_node = malloc(sizeof(list_node));
        if (!new_node) {
            free(array);
            free_resource_list(sorted_head);
            return NULL;
        }

        *current_ptr = new_node;
        current_ptr = &new_node->next;

        new_node->data = array[i];
    }

    *current_ptr = NULL;
    free(array);

    return sorted_head;
}

void initialize_and_query_resources(size_t num_records, timestamp start_range, timestamp end_range) {
    list_node* resources = allocate_resources(num_records, -1);
    if (!resources) {
        printf("Memory allocation failed.\n");
        return;
    }

    // Sort and smooth metrics
    resources = sort_resources(resources);
    size_t count = 0;
    list_node* temp = resources;
    while (temp != NULL) {
        ++count;
        temp = temp->next;
    }
    smooth_metrics(&(resources->data), count);

    // Query records within the specified time range
    list_node* queried_records = query_resources(resources, start_range, end_range);
    if (!queried_records) {
        printf("Memory allocation failed during query.\n");
    }

    free_resource_list(resources);
    free_resource_list(queried_records);
}

int main() {
    srand(time(NULL));

    timestamp start_query = {9, 0};
    timestamp end_query = {17, 0};

    initialize_and_query_resources(10, start_query, end_query);

    return 0;
}
