#define MAX_PATH_LENGTH 256
#define CACHE_SIZE 10

typedef struct Directory {
    char name[MAX_PATH_LENGTH];
    struct Directory* parent;
    DIR* dir_handle;
    struct Directory** children;
    int child_count;
} Directory;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Directory* root_directory;
Directory* cache[CACHE_SIZE];

void log_message(const char* message) {
    FILE* log_file = fopen("directory_manager.log", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

int validate_name(const char* name) {
    // Implement validation logic for names
    return 1; // Placeholder
}

Directory* get_directory(const char* path) {
    pthread_mutex_lock(&lock);

    // Check cache first
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (cache[i] && strcmp(cache[i]->name, path) == 0) {
            pthread_mutex_unlock(&lock);
            return cache[i];
        }
    }

    // Traverse the directory structure
    Directory* current = root_directory;
    char *token = strtok((char*)path, "/");
    while (token != NULL) {
        int found = 0;
        for (int i = 0; i < current->child_count; ++i) {
            if (strcmp(current->children[i]->name, token) == 0) {
                current = current->children[i];
                found = 1;
                break;
            }
        }
        if (!found) {
            pthread_mutex_unlock(&lock);
            return NULL;
        }
        token = strtok(NULL, "/");
    }

    // Add to cache
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (cache[i] == NULL || strcmp(cache[i]->name, path) != 0) {
            cache[i] = current;
            break;
        }
    }

    pthread_mutex_unlock(&lock);
    return current;
}

void add_directory(Directory* parent, const char* name) {
    pthread_mutex_lock(&lock);

    if (!validate_name(name)) {
        log_message("Invalid directory name");
        pthread_mutex_unlock(&lock);
        return;
    }

    Directory* new_dir = malloc(sizeof(Directory));
    strncpy(new_dir->name, name, MAX_PATH_LENGTH - 1);
    new_dir->parent = parent;
    new_dir->dir_handle = opendir(name); // Open the directory
    new_dir->children = NULL;
    new_dir->child_count = 0;

    if (new_dir->dir_handle == NULL) {
        free(new_dir);
        log_message("Failed to create directory");
        pthread_mutex_unlock(&lock);
        return;
    }

    parent->children = realloc(parent->children, sizeof(Directory*) * (parent->child_count + 1));
    parent->children[parent->child_count++] = new_dir;

    pthread_mutex_unlock(&lock);
}

void delete_directory(const char* path) {
    // Implement directory deletion logic
}

void list_directory(const char* path) {
    Directory* dir = get_directory(path);
    if (!dir || !dir->dir_handle) {
        log_message("Directory not found");
        return;
    }

    struct dirent* entry;
    while ((entry = readdir(dir->dir_handle)) != NULL) {
        printf("%s\n", entry->d_name);
    }
}

void process_operations() {
    char operation[10];
    char path[MAX_PATH_LENGTH];

    while (scanf("%s %s", operation, path) == 2) {
        if (strcmp(operation, "create") == 0) {
            Directory* parent = get_directory(path); // Simplified for demonstration
            add_directory(parent, path);
        } else if (strcmp(operation, "delete") == 0) {
            delete_directory(path);
        } else if (strcmp(operation, "list") == 0) {
            list_directory(path);
        } else {
            log_message("Invalid operation");
        }
    }
}

int main() {
    root_directory = malloc(sizeof(Directory));
    root_directory->name[0] = '\0';
    root_directory->parent = NULL;
    root_directory->dir_handle = opendir("/"); // Open the root directory
    root_directory->children = NULL;
    root_directory->child_count = 0;

    if (root_directory->dir_handle == NULL) {
        fprintf(stderr, "Failed to open root directory\n");
        return 1;
    }

    process_operations();

    // Cleanup
    free(root_directory);
    pthread_mutex_destroy(&lock);

    return 0;
}
