```c
// packet.c

#include "packet.h"
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

Packet_List* create_packet_list(size_t initial_capacity) {
    Packet_List *list = (Packet_List *)malloc(sizeof(Packet_List));
    list->packets = (Network_Packet *)malloc(initial_capacity * sizeof(Network_Packet));
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

bool add_packet(Packet_List *list, const Network_Packet *packet) {
    if (pthread_mutex_lock(&list->lock)) return false;

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        Network_Packet *new_packets = (Network_Packet *)realloc(list->packets, new_capacity * sizeof(Network_Packet));
        if (!new_packets) {
            pthread_mutex_unlock(&list->lock);
            return false;
        }
        list->packets = new_packets;
        list->capacity = new_capacity;
    }

    memcpy(&list->packets[list->count], packet, sizeof(Network_Packet));

    // Handle potential buffer overflow
    if (packet->payload_size > 0 && !packet->Packet_Data) {
        free(list->lock);
        free(list->packets);
        free(list);
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    list->count++;
    bool success = true;

    pthread_mutex_unlock(&list->lock);

    return success;
}

bool remove_packet(Packet_List *list, uint32_t packet_id) {
    if (pthread_mutex_lock(&list->lock)) return false;

    for (size_t i = 0; i < list->count; ++i) {
        if (list->packets[i].Packet_ID == packet_id) {
            memmove(&list->packets[i], &list->packets[i + 1],
                    (list->count - i - 1) * sizeof(Network_Packet));
            list->count--;
            success = true;
            break;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return success;
}

void destroy_packet_list(Packet_List *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        free(list->packets[i].Packet_Data);
    }
    free(list->packets);
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

