#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_NAME_LEN 256
#define CACHE_SIZE 10
#define CONFIG_FILE "config.dat"

typedef struct KeyValue {
    char key[MAX_NAME_LEN];
    char value[MAX_NAME_LEN];
} KeyValue;

typedef struct Section {
    char name[MAX_NAME_LEN];
    KeyValue *keys;
    size_t num_keys;
    struct Section *parent;
    struct Section *children;
    size_t num_children;
} Section;

typedef struct CacheEntry {
    char path[MAX_NAME_LEN * 2]; // Max path length
    Section *section;
} CacheEntry;

Section root;
pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;
CacheEntry cache[CACHE_SIZE];
size_t cache_count = 0;

int is_valid_name(const char *name) {
    for (const char *p = name; *p != '\0'; p++) {
        if (!((*p >= 'a' && *p <= 'z') || (*p >= 'A' && *p <= 'Z') ||
              (*p >= '0' && *p <= '9') || *p == '_')) {
            return 0;
        }
    }
    return 1;
}

Section* find_section(Section *section, const char *path) {
    if (strcmp(path, section->name) == 0) {
        return section;
    }

    for (size_t i = 0; i < section->num_children; i++) {
        Section *found = find_section(&section->children[i], path);
        if (found != NULL) {
            return found;
        }
    }
    return NULL;
}

void log_change(const char *message) {
    FILE *log_file = fopen("config.log", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

Section* cache_lookup(const char *path) {
    for (size_t i = 0; i < cache_count; i++) {
        if (strcmp(cache[i].path, path) == 0) {
            return cache[i].section;
        }
    }
    return NULL;
}

void cache_add(Section *section, const char *path) {
    if (cache_count >= CACHE_SIZE) {
        // Simple LRU eviction
        memmove(&cache[0], &cache[1], sizeof(CacheEntry) * (CACHE_SIZE - 1));
        cache_count--;
    }
    strcpy(cache[cache_count].path, path);
    cache[cache_count].section = section;
    cache_count++;
}

Section* load_section_from_file(const char *path);

void configManager() {
    char operation[10], path[MAX_NAME_LEN * 2];
    char key[MAX_NAME_LEN], value[MAX_NAME_LEN];

    while (scanf("%s %s", operation, path) == 2) {
        pthread_mutex_lock(&config_lock);

        if (!is_valid_name(path)) {
            printf("Invalid section name: %s\n", path);
            pthread_mutex_unlock(&config_lock);
            continue;
        }

        Section *section = cache_lookup(path);
        if (operation[0] == 'C' && !section) { // Create
            section = load_section_from_file(path); // Load from file or create new
            if (!section) {
                printf("Cannot find parent section for: %s\n", path);
                pthread_mutex_unlock(&config_lock);
                continue;
            }
            cache_add(section, path);
            log_change("Created section: ");
        } else if (operation[0] == 'D' && section) { // Delete
            // Implement deletion logic
            log_change("Deleted section: ");
        } else if (operation[0] == 'R') { // Retrieve
            if (!section) {
                printf("Section not found: %s\n", path);
            }
        }

        if (strcmp(operation, "RETRIEVE") == 0) {
            scanf("%s %s", key, value);
            section = find_section(&root, path);
            if (section) {
                for (size_t i = 0; i < section->num_keys; i++) {
                    if (strcmp(section->keys[i].key, key) == 0) {
                        printf("%s: %s\n", key, section->keys[i].value);
                        break;
                    }
                }
            } else {
                printf("Key not found: %s\n", key);
            }
        }

        pthread_mutex_unlock(&config_lock);
    }
}

Section* load_section_from_file(const char *path) {
