['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define the structure for each record.
typedef struct {
    long offset;
    int key;
} Record;

// Define a node in the linked list to handle hash collisions.
typedef struct Node {
    Record data;
    struct Node* next;
} Node;

// Hash table entry with a mutex lock for concurrency control.
typedef struct {
    Node* head;
    pthread_mutex_t lock; // Mutex lock for thread-safe access.
} HashTableEntry;

#define TABLE_SIZE 101 // Choosing a prime number to reduce collisions.

// Function prototypes
unsigned int hashFunction(int key);
HashTableEntry* createHashTable();
Node* insertRecord(HashTableEntry* table, Record record);
Record* findRecordByKey(HashTableEntry* table, int key);
void freeHashTable(HashTableEntry* table);

// Create the hash table and initialize mutexes.
HashTableEntry* createHashTable() {
    HashTableEntry* table = (HashTableEntry*)malloc(TABLE_SIZE * sizeof(HashTableEntry));
    if (!table) {
        perror("Failed to allocate memory for hash table");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < TABLE_SIZE; ++i) {
        table[i].head = NULL;
        pthread_mutex_init(&table[i].lock, NULL); // Initialize mutex.
    }
    return table;
}

// Simple hash function to minimize collisions.
unsigned int hashFunction(int key) {
    return (unsigned int)(key % TABLE_SIZE);
}

// Insert a record into the hash table in a thread-safe manner.
Node* insertRecord(HashTableEntry* table, Record record) {
    unsigned int index = hashFunction(record.key);

    pthread_mutex_lock(&table[index].lock); // Lock for thread safety.

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate memory for node");
        exit(EXIT_FAILURE);
    }
    newNode->data = record;
    newNode->next = table[index].head;
    table[index].head = newNode;

    pthread_mutex_unlock(&table[index].lock); // Unlock after insertion.

    return newNode; // Return the inserted node (optional).
}

// Find a record by its key in a thread-safe manner.
Record* findRecordByKey(HashTableEntry* table, int key) {
    unsigned int index = hashFunction(key);

    pthread_mutex_lock(&table[index].lock); // Lock for thread safety.

    Node* current = table[index].head;
    while (current) {
        if (current->data.key == key) {
            Record* foundRecord = &(current->data);
            pthread_mutex_unlock(&table[index].lock);
            return foundRecord; // Return pointer to the record.
        }
        current = current->next;
    }

    pthread_mutex_unlock(&table[index].lock); // Unlock if not found.
    return NULL; // Return NULL if not found.
}

// Free all allocated memory in the hash table.
void freeHashTable(HashTableEntry* table) {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        pthread_mutex_lock(&table[i].lock); // Lock to ensure thread-safe access.

        Node* current = table[i].head;
        while (current) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }

        pthread_mutex_unlock(&table[i].lock);
        pthread_mutex_destroy(&table[i].lock); // Destroy mutex.
    }
    free(table); // Free the hash table itself.
}

// Example usage
int main() {
    HashTableEntry* hashTable = createHashTable();

    Record r1 = {12345, 10};
    insertRecord(hashTable, r1);

    Record* foundRecord = findRecordByKey(hashTable, 10);
    if (foundRecord) {
        printf("Found record with key %d: offset %ld\n", foundRecord->key, foundRecord->offset);
    } else {
        printf("Record not found.\n");
    }

    freeHashTable(hashTable);
    return 0;
}
```

### Explanation

- **Concurrency**: Each bucket in the hash table has its own mutex lock to allow safe concurrent access.
- **Performance**: The hash function is designed to distribute keys evenly across a prime-sized array, reducing collisions and enhancing lookup speed.
- **Scalability**: The `Record` structure can be easily extended without changing much of the logic due to minimal dependencies on specific fields for hashing or storage.
- **Memory Management**: All dynamic memory allocations are carefully managed, ensuring that every allocation is paired with a corresponding deallocation to prevent leaks.
- **Documentation and Usability**: Inline comments explain key sections. Example usage is provided in `main()`.

The design ensures thread-safety, efficient memory use, and scalability for future enhancements while keeping integration smooth and documentation clear.']

