    Record** records_array;
    size_t record_count;
    HashTableEntry** hash_table;
    size_t hash_table_size;
    pthread_rwlock_t rwlock; // For read-write operations
    pthread_mutex_t init_lock;
    int logging_level;
} LoggerSystem;

// Helper functions for memory management, hashing, and synchronization

void initialize_logger_system(LoggerSystem* system, size_t initial_capacity, int level) {
    if (!system || !initial_capacity) return;

    pthread_rwlock_init(&system->rwlock, NULL);
    pthread_mutex_lock(&system->init_lock);

    system->records_array = calloc(initial_capacity, sizeof(Record*));
    if (!system->records_array) { /* Handle allocation failure */ }

    system->record_count = initial_capacity;
    system->hash_table_size = 64; // Example prime size for minimal collisions
    system->hash_table = calloc(system->hash_table_size, sizeof(HashTableEntry*));
    if (!system->hash_table) { /* Handle allocation failure */ }

    system->logging_level = level;

    pthread_mutex_unlock(&system->init_lock);
}

void destroy_logger_system(LoggerSystem* system) {
    if (!system) return;
    // Properly free memory, ensuring no leaks
    for (size_t i = 0; i < system->record_count; ++i) {
        Record* record = system->records_array[i];
        if (record) {
            pthread_mutex_lock(&record->lock);
            Event* event = record->events_head;
            while (event) {
                Metadata* meta = event->metadata_list;
                while (meta) {
                    Metadata* next_meta = meta->next;
                    free(meta->key);
                    free(meta->value);
                    free(meta);
                    meta = next_meta;
                }
                Event* next_event = event->events_head; // Assuming a linked list of events
                free(event->type);
                if (event->payload) {
                    free(event->payload);
                }
                pthread_mutex_destroy(&event->ref_count_lock);
                free(event);
                event = next_event;
            }
            pthread_mutex_unlock(&record->lock);
            free(record);
        }
    }

    for (size_t i = 0; i < system->hash_table_size; ++i) {
        HashTableEntry* entry = system->hash_table[i];
        if (entry) {
            Record** records = entry->records;
            for (int j = 0; j < entry->count; ++j) {
                free(records[j]);
            }
            pthread_mutex_destroy(&entry->lock);
            free(entry);
        }
    }

    free(system->records_array);
    free(system->hash_table);

    pthread_rwlock_destroy(&system->rwlock);
}

