    if (!cache) {
        perror("Failed to allocate memory for LRU cache");
        exit(EXIT_FAILURE);
    }

    cache->capacity = capacity;
    cache->head = NULL;
    cache->tail = NULL;
    cache->hash = hash_function;
    cache->eq = equality_function;
    pthread_mutex_init(&cache->lock, NULL);

    return cache;
