void lru_cache_put(LRUCache *cache, void *key, FileEvent *value) {
    pthread_mutex_lock(&cache->lock);

    // Check if key already exists
    CacheNode *current = cache->head;
    while (current) {
        if (cache->eq(current->key, key)) {
            current->value = value;
            pthread_mutex_unlock(&cache->lock);
            return;
        }
        current = current->next;
    }

    // Add new node
    CacheNode *new_node = malloc(sizeof(CacheNode));
    if (!new_node) {
        perror("Failed to allocate memory for cache node");
        exit(EXIT_FAILURE);
    }
    new_node->key = key;
    new_node->value = value;

    if (cache->head == NULL) {
        cache->head = cache->tail = new_node;
    } else {
        cache->tail->next = new_node;
        new_node->prev = cache->tail;
        cache->tail = new_node;
    }

    // Evict least recently used item if necessary
    if (cache->capacity <= count_cache_nodes(cache)) {
        CacheNode *to_evict = cache->head;
        cache->head = cache->head->next;
        if (cache->head) {
            cache->head->prev = NULL;
        } else {
            cache->tail = NULL;
        }
        free(to_evict);
    }

    pthread_mutex_unlock(&cache->lock);
}

FileEvent* lru_cache_get(LRUCache *cache, void *key) {
    pthread_mutex_lock(&cache->lock);

    CacheNode *current = cache->head;
    while (current) {
        if (cache->eq(current->key, key)) {
            // Move node to the end
            if (current == cache->tail) return current->value;

            if (current->prev) current->prev->next = current->next;
            if (current->next) current->next->prev = current->prev;
            if (current == cache->head) cache->head = current->next;

            current->next = NULL;
            current->prev = cache->tail;
            if (cache->tail) cache->tail->next = current;
            cache->tail = current;

            pthread_mutex_unlock(&cache->lock);
            return current->value;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

size_t count_cache_nodes(LRUCache *cache) {
    size_t count = 0;
    CacheNode *current = cache->head;
    while (current) {
        ++count;
        current = current->next;
    }
    return count;
}
