    int priority;
    struct Message** messages;
    size_t message_count;
    pthread_mutex_t lock; // For thread-safe operations
} Node;

typedef struct Processor {
    // Define processor structure fields as needed
} Processor;

// Binary tree node for efficient lookups
typedef struct TreeNode {
    void* data;
    int priority;
    struct TreeNode* left;
    struct TreeNode* right;
} TreeNode;

TreeNode* root = NULL; // Root of the binary search tree

pthread_mutex_t bst_lock = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
Node* create_node(int id);
void free_node(Node* node);
int compare_priority(void* a, void* b);
void insert_into_bst(TreeNode** root, void* data, int priority);
void* find_in_bst(TreeNode* root, int priority);

// Create a new node with random ID and default priority
Node* create_node(int id) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    pthread_mutex_init(&node->lock, NULL);
    node->id = id ? id : rand(); // Random unique identifier if not provided
    node->priority = DEFAULT_PRIORITY;
    node->messages = NULL;
    node->message_count = 0;

    return node;
}

// Free resources allocated for a node
void free_node(Node* node) {
    if (!node) return;

    pthread_mutex_lock(&node->lock);
    // Free messages
    for (size_t i = 0; i < node->message_count; ++i) {
        free(node->messages[i]->content_type);
        free(node->messages[i]->payload);
        free(node->messages[i]);
    }
    free(node->messages);

    pthread_mutex_unlock(&node->lock);
    pthread_mutex_destroy(&node->lock);
    free(node);
}

// Compare nodes based on priority for binary search tree insertion
int compare_priority(void* a, void* b) {
    Node* node_a = (Node*)a;
    Node* node_b = (Node*)b;

    return node_a->priority - node_b->priority;
}

// Insert data into the BST maintaining sorted order by priority
void insert_into_bst(TreeNode** root, void* data, int priority) {
    if (!root || !data) return;

    pthread_mutex_lock(&bst_lock);

    TreeNode* new_node = (TreeNode*)malloc(sizeof(TreeNode));
    if (!new_node) return; // Handle allocation failure

    new_node->data = data;
    new_node->priority = priority;
    new_node->left = new_node->right = NULL;

    if (*root == NULL) {
        *root = new_node;
    } else {
        TreeNode* current = *root;
        while (1) {
            if (priority < current->priority) {
                if (current->left == NULL) {
                    current->left = new_node;
                    break;
                }
                current = current->left;
            } else {
                if (current->right == NULL) {
                    current->right = new_node;
                    break;
                }
                current = current->right;
            }
        }
    }

    pthread_mutex_unlock(&bst_lock);
}

// Find a node in the BST by priority
void* find_in_bst(TreeNode* root, int priority) {
    if (!root || !root->data) return NULL;

    TreeNode* current = root;
    while (current) {
        if (priority == current->priority) {
            return current->data;
        } else if (priority < current->priority) {
            current = current->left;
        } else {
            current = current->right;
        }
    }

    return NULL;
}

// Initialize the system with a given number of nodes
void initialize_system(size_t node_count) {
    srand(time(NULL)); // Seed for random ID generation

    for (size_t i = 0; i < node_count; ++i) {
        Node* node = create_node(0);
        if (!node) {
            fprintf(stderr, "Failed to allocate memory for node\n");
            continue;
        }

        insert_into_bst(&root, node, node->priority);
    }
}

// Clean up resources used by the system
void cleanup_system() {
    // Implement in-order traversal to free all nodes from BST

    pthread_mutex_lock(&bst_lock);

    void inorder_free(TreeNode* root) {
        if (!root) return;

        inorder_free(root->left);
        free_node((Node*)root->data);
        free(root);
        inorder_free(root->right);
    }

    inorder_free(root);
    root = NULL;

    pthread_mutex_unlock(&bst_lock);
}

int main() {
    size_t node_count = 1000; // Example number of nodes

    initialize_system(node_count);

    // Perform operations on the system...

    cleanup_system();

    return 0;
}
