    MAC_EVENT_TAG exampleTag = { .tag = 1, .timestamp = 123456789 };
    MAC_FRAME_DATA exampleFrames[3] = {
        { (unsigned char *) "Frame1", 6 },
        { (unsigned char *) "Frame2", 6 },
        { (unsigned char *) "Frame3", 6 }
    };

    addNetworkEvent(exampleTag, 987654321, exampleFrames, 3);

    return NULL;
}

void initializeRecords(int numRecords, int range) {
    Record *records = malloc(numRecords * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < numRecords; ++i) {
        records[i].value = rand() % range;
        records[i].offsetRef = i * sizeof(Record); // Simple offset reference
    }

    customSort(records, numRecords);

    free(records);
}

void customSort(Record *records, int numRecords) {
    for (int i = 0; i < numRecords - 1; ++i) {
        for (int j = 0; j < numRecords - i - 1; ++j) {
            if (records[j].value > records[j + 1].value) {
                Record temp = records[j];
                records[j] = records[j + 1];
                records[j + 1] = temp;
            }
        }
    }
}

int addNetworkEvent(MAC_EVENT_TAG tag, long timestamp, MAC_FRAME_DATA frames[], int frameCount) {
