        pthread_mutex_unlock(&globalLock);
        return -1; // Error: Event list full
    }

    NetworkEvent *newEvent = malloc(sizeof(NetworkEvent));
    if (!newEvent) {
        pthread_mutex_unlock(&globalLock);
        return -3; // Error: Memory allocation failed for new event
    }

    pthread_mutex_init(&newEvent->lock, NULL);

    newEvent->eventTag.tag = tag.tag;
    newEvent->timestamp = timestamp;
    memcpy(newEvent->frames, frames, sizeof(MAC_FRAME_DATA) * frameCount);
    newEvent->frameCount = frameCount;

    networkEvents[eventCount++] = newEvent;

    pthread_mutex_unlock(&globalLock);

    return 0; // Success
}

int main() {
    int numThreads = 4;
    pthread_t threads[numThreads];

    for (int i = 0; i < numThreads; ++i) {
        if (pthread_create(&threads[i], NULL, threadFunc, NULL)) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    for (int i = 0; i < numThreads; ++i) {
        pthread_join(threads[i], NULL);
    }

    initializeRecords(100, 10000);

    // Clean up
    for (int i = 0; i < eventCount; ++i) {
        pthread_mutex_destroy(&networkEvents[i]->lock);
        free(networkEvents[i]);
    }

    return 0;
}
```

### Key Features:
- **Multi-threading**: The code includes a basic example of threading with `pthread_create` and `pthread_join`.
- **Thread Safety**: Uses mutexes to protect shared resources (`globalLock` for the global event list, individual locks within each `NetworkEvent`).
- **Memory Management**: Proper allocation checks and error handling are in place. Cleanup is performed at the end.
- **Custom Sort**: Implements a simple bubble sort for sorting records based on integer values.

This code assumes that additional constraints like buffer sizes or specific alignment requirements are not overly restrictive beyond what's shown here, making it suitable as an example implementation.']

