#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pthread.h>
#include <string.h>
#include <errno.h>
#include "logging_library.h" // Assuming a logging library is included here

typedef struct {
    int value;
} record;

// Helper function to calculate the median of an array
int findMedian(int *array, size_t n) {
    if (n % 2 == 0) {
        return (array[n / 2 - 1] + array[n / 2]) / 2;
    } else {
        return array[n / 2];
    }
}

// Comparator function for qsort
int compare(const void *a, const void *b) {
    int keyA = *(const int *)a;
    int keyB = *(const int *)b;
    return keyA - keyB;
}

void processAndSortRecords(int fd, size_t recordCount) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Memory allocation logging
    log_memory_event("Allocating memory for offset array");
    long *offsets = malloc(recordCount * sizeof(long));
    if (!offsets) {
        log_error("Memory allocation failed for offsets");
        return;
    }

    log_memory_event("Allocating memory for keys array");
    int *keys = malloc(recordCount * sizeof(int));
    if (!keys) {
        log_error("Memory allocation failed for keys");
        free(offsets);
        return;
    }

    log_memory_event("Allocating memory for records array");
    record *records = malloc(recordCount * sizeof(record));
    if (!records) {
        log_error("Memory allocation failed for records");
        free(keys);
        free(offsets);
        return;
    }

    int *fileIntegers = NULL;
    size_t fileSize = 0;

    // Read integers from file descriptor
    char buffer[1024];
    ssize_t bytesRead;
    while ((bytesRead = read(fd, buffer, sizeof(buffer) - 1)) > 0) {
        buffer[bytesRead] = '\0';
        int *tokens = (int *)strtok((char *)buffer, " \n");
        size_t currentSize = fileSize;

        // Resize the fileIntegers array
        fileIntegers = realloc(fileIntegers, (currentSize + bytesRead / sizeof(int)) * sizeof(int));
        if (!fileIntegers) {
            log_error("Memory reallocation failed for file integers");
            free(records);
            free(keys);
            free(offsets);
            return;
        }

        // Copy new tokens to the array
        while (tokens != NULL) {
            fileIntegers[fileSize++] = atoi(tokens);
            tokens = (int *)strtok(NULL, " \n");
        }
    }

    if (bytesRead < 0) {
        log_error("Error reading from file descriptor: %s", strerror(errno));
        free(fileIntegers);
        free(records);
        free(keys);
        free(offsets);
        return;
    }

    // Initialize records with random values
    for (size_t i = 0; i < recordCount; ++i) {
        offsets[i] = rand() % fileSize;
        keys[i] = fileIntegers[offsets[i]];
        records[i].value = keys[i];
    }

    // Sort the records based on their key values
    qsort(keys, recordCount, sizeof(int), compare);

    // Print median of integers read from the file descriptor
    if (fileSize > 0) {
        printf("Median: %d\n", findMedian(fileIntegers, fileSize));
    }

    // Clean up and deallocate memory with logging
    log_memory_event("Deallocating records array");
    free(records);

    log_memory_event("Deallocating keys array");
    free(keys);

    log_memory_event("Deallocating offsets array");
    free(offsets);

    log_memory_event("Deallocating file integers array");
    free(fileIntegers);

    pthread_mutex_destroy(&lock);
}
```

### Explanation:
- **Memory Management**: The function dynamically allocates memory for the required arrays and ensures proper deallocation. It uses logging to track these events.
- **Concurrency**: A mutex is used to ensure thread safety during execution.
- **Error Handling**: Checks are in place for successful memory allocation and file reading operations.
- **Sorting and Median Calculation**: The `qsort` function is used for sorting, and a helper function calculates the median of the integer array read from the file descriptor.']

