void update_lru(int index) {
    if (cache.used_count < MAX_CACHE_SIZE) {
        cache.data[++cache.lru_index] = cache.data[index];
    } else {
        // Evict least recently used
        int lru_evict_index = (cache.lru_index + 1) % MAX_CACHE_SIZE;
        memmove(&cache.data[lru_evict_index], &cache.data[0],
                (++cache.lru_index - lru_evict_index) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
}

