        if (!tree[i]) return -1;

        pthread_mutex_lock(&lock);
        tree[i]->key = rand() % (max_key - min_key + 1) + min_key;
        tree[i]->left = NULL;
        tree[i]->right = NULL;
        tree[i]->metadata_head = metadata_array[i];
        pthread_mutex_unlock(&lock);
    }

    // Example logic to balance and link nodes in a BST
    for (int i = 0; i < node_count / 2; ++i) {
        int left_index = 2 * i + 1;
        int right_index = 2 * i + 2;

        if (left_index < node_count) tree[i]->left = tree[left_index];
        if (right_index < node_count) tree[i]->right = tree[right_index];
