// Function prototypes for CircularBuffer operations
void circularBufferInit(CircularBuffer *cb);
void circularBufferAdd(CircularBuffer *cb, double value);
double circularBufferGetAverage(const CircularBuffer *cb);

// Thread safety mechanism
pthread_mutex_t metricsMutex = PTHREAD_MUTEX_INITIALIZER;

// Helper function to generate random integer within range
int getRandomInt(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Function to insert a node into the binary search tree
Node* insert(Node* root, int key) {
    if (!root)
        return newNode(key);

    if (key < root->key)
        root->left = insert(root->left, key);
    else if (key > root->key)
        root->right = insert(root->right, key);

    return root;
}

// Function to create a new Node
Node* newNode(int key) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->key = key;
    node->left = node->right = NULL;
    return node;
}

void freeTree(Node* root) {
    if (root) {
        freeTree(root->left);
        freeTree(root->right);
        free(root);
    }
}

// Function to initialize the network metrics
int initializeNetworkMetrics(int numMetrics, NetworkPerformanceMetrics *metricsArray) {
    pthread_mutex_lock(&metricsMutex);

    // Error code
    const int MEMORY_ERROR = -1;

    double* floatArray;
    char** stringArray;
    Node** nodeArray;

    // Dynamic memory allocation for arrays
    if (!(floatArray = (double*)malloc(numMetrics * sizeof(double))) ||
        !(stringArray = (char**)malloc(numMetrics * sizeof(char*))) ||
        !(nodeArray = (Node**)malloc(numMetrics * sizeof(Node*)))) {

        pthread_mutex_unlock(&metricsMutex);
        return MEMORY_ERROR;
    }

    for (int i = 0; i < numMetrics; ++i) {
        stringArray[i] = (char*)malloc(256 * sizeof(char));
        if (!stringArray[i]) {
            free(floatArray);
            for (int j = 0; j < i; ++j)
                free(stringArray[j]);
            free(stringArray);
            free(nodeArray);
            pthread_mutex_unlock(&metricsMutex);
            return MEMORY_ERROR;
        }
    }

    time_t currentTime = time(NULL);
    CircularBuffer cb;
    circularBufferInit(&cb);

    for (int i = 0; i < numMetrics; ++i) {
        metricsArray[i].cellId = i + 1;
        metricsArray[i].timeStamp = currentTime - TIMESTAMP_INTERVAL * i;

        // Synthetic traffic model
        double syntheticThroughput = ((double)rand() / RAND_MAX) * MAX_THROUGHPUT;
        metricsArray[i].throughput = syntheticThroughput;

        circularBufferAdd(&cb, syntheticThroughput);
        metricsArray[i].movingAverageThroughput = circularBufferGetAverage(&cb);

        // Populate node array with random keys
        int keyRangeMin = 1, keyRangeMax = 1000; // Arbitrary range
        Node* newNodePtr = insert(NULL, getRandomInt(keyRangeMin, keyRangeMax));
        if (i == 0) {
            metricsArray[i].treeRoot = newNodePtr;
        } else {
            nodeArray[i - 1]->right = newNodePtr;
        }
        nodeArray[i] = newNodePtr;

        // Populate float and string arrays
        floatArray[i] = syntheticThroughput / 2.0; // Example operation
        snprintf(stringArray[i], 256, "Data for cell %d", metricsArray[i].cellId);
    }

    pthread_mutex_unlock(&metricsMutex);

    // Cleanup allocated memory to prevent leaks
    free(floatArray);
    for (int i = 0; i < numMetrics; ++i) {
        free(stringArray[i]);
    }
    free(stringArray);
    free(nodeArray);
    freeTree(metricsArray[0].treeRoot); // Assuming tree starts at index 0

    return 0;
}

// Main function to demonstrate usage
int main() {
    int numMetrics = 60;
    NetworkPerformanceMetrics metricsArray[numMetrics];
    int result = initializeNetworkMetrics(numMetrics, metricsArray);

    if (result == -1) {
        printf("Memory allocation error\n");
        return EXIT_FAILURE;
    }

    // Display some of the initialized data
    for (int i = 0; i < numMetrics && i < 10; ++i) {
        printf("Cell ID: %d, Timestamp: %ld, Throughput: %.2f Mbps, Moving Avg: %.2f Mbps\n",
               metricsArray[i].cellId,
               metricsArray[i].timeStamp,
               metricsArray[i].throughput,
               metricsArray[i].movingAverageThroughput);
    }

    return EXIT_SUCCESS;
}
