int deserialize_from_json(PeerDiscoveryRequest **requests, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading\n");
        return -1;
    }

    json_object_t *json_array = json_parse_file(file);
    fclose(file);

    size_t count = json_get_size(json_array);
