```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <stdint.h>

// Definitions
#define MAX_EVENT_SIZE 1024 // Max number of events in the pool
#define MAX_FRAME_SIZE 256  // Max size for each frame

typedef struct {
    uint64_t offset;  // Assuming long is 8 bytes
} Offset;

typedef struct {
    int key;
} Key;

typedef struct {
    uint32_t mac_event_tag;
    uint64_t timestamp;
    struct {
        uint16_t type;
        uint8_t data[MAX_FRAME_SIZE];
    } frames[0];  // Flexible array member for variable number of frames
} NetworkEvent;

// Memory pool structure
typedef struct {
    NetworkEvent* events;
    size_t event_count;
    size_t max_event_size;
    pthread_mutex_t lock;
} EventPool;

typedef struct {
    Offset* offsets;
    Key* keys;
    size_t offset_count;
    size_t key_count;
    pthread_rwlock_t rwlock;  // Read-write lock for better performance
} DataStructures;

// Global variables
EventPool event_pool = {0};
DataStructures data_structs = {0};

void init_event_pool(size_t max_events) {
    pthread_mutex_init(&event_pool.lock, NULL);
    event_pool.max_event_size = max_events;
    event_pool.events = calloc(max_events, sizeof(NetworkEvent));
}

void destroy_event_pool() {
    free(event_pool.events);
    pthread_mutex_destroy(&event_pool.lock);
}

int add_network_event(uint32_t mac_event_tag, uint64_t timestamp, size_t frame_count) {
    pthread_mutex_lock(&event_pool.lock);

    for (size_t i = 0; i < event_pool.event_count; ++i) {
        if (event_pool.events[i].mac_event_tag == 0) {  // Unused slot
            NetworkEvent* event = &event_pool.events[i];
            event->mac_event_tag = mac_event_tag;
            event->timestamp = timestamp;

            size_t required_size = sizeof(NetworkEvent) + frame_count * sizeof(((NetworkEvent*)0)->frames[0]);
            if (required_size > sizeof(NetworkEvent)) {
                event = realloc(event, required_size);
                if (!event) {
                    pthread_mutex_unlock(&event_pool.lock);
                    return -1;  // Memory allocation error
                }
                &event_pool.events[i] = *event;
            }

            for (size_t j = 0; j < frame_count; ++j) {
                event->frames[j].type = 0;  // Initialize with a default value or real type
                memset(event->frames[j].data, 0, MAX_FRAME_SIZE);
            }
            pthread_mutex_unlock(&event_pool.lock);
            return i;
        }
    }

    pthread_mutex_unlock(&event_pool.lock);
    return -1;  // Pool full error
}

void remove_network_event(size_t index) {
    if (index >= event_pool.event_count) return;

    pthread_mutex_lock(&event_pool.lock);
    NetworkEvent* event = &event_pool.events[index];
    *event = (NetworkEvent){0};  // Reset the event
    pthread_mutex_unlock(&event_pool.lock);
}

void init_data_structures(size_t num_offsets, size_t num_keys) {
    pthread_rwlock_init(&data_structs.rwlock, NULL);
    data_structs.offset_count = num_offsets;
    data_structs.key_count = num_keys;

    data_structs.offsets = calloc(num_offsets, sizeof(Offset));
    if (!data_structs.offsets) exit(EXIT_FAILURE);  // Handle allocation failure

    data_structs.keys = malloc(num_keys * sizeof(Key));
    if (!data_structs.keys) {
        free(data_structs.offsets);
        exit(EXIT_FAILURE);
    }
}

void destroy_data_structures() {
    pthread_rwlock_destroy(&data_structs.rwlock);
    free(data_structs.offsets);
    free(data_structs.keys);
}

// Example usage
int main() {
    init_event_pool(MAX_EVENT_SIZE);
    init_data_structures(10, 5);

    int event_index = add_network_event(1, 1234567890, 3);
    if (event_index >= 0) {
        printf("Added event at index %d\n", event_index);
    } else {
        fprintf(stderr, "Failed to add network event\n");
    }

    remove_network_event(event_index);

    destroy_data_structures();
    destroy_event_pool();

    return 0;
}
