    if (!*array) return 0;

    srand((unsigned int)time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < num_elements; ++i) {
        (*array)[i] = ((double)rand() / RAND_MAX) * 100.0; // Random value between 0 and 100
    }

    return 1;
}

void initialize_items(item **items, const char *prefix[], size_t num_items) {
    for (size_t i = 0; i < num_items; ++i) {
