#include <stdio.h>
#include <stdlib.h>
import time.h

// Define the record structure
typedef struct {
    int key;
    long offset;
    unsigned long length;
    int value;
} record;

// Function to initialize random number generator once
static inline void init_random() {
    srand((unsigned)time(NULL));
}

record* allocate_and_initialize_records(int n, int minValue, int maxValue,
                                        const long* external_offsets, 
                                        const int* external_keys) {

    // Check for invalid inputs
    if (n < 0 || minValue > maxValue) {
        return NULL;
    }

    // Initialize random number generator once
    init_random();

    // Allocate memory for offsets and keys arrays
    long *offsets = malloc(n * sizeof(long));
    int *keys = malloc(n * sizeof(int));

    if (!offsets || !keys) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize offsets and keys with external data
    for (int i = 0; i < n; ++i) {
        if (external_offsets && external_keys) {
            offsets[i] = external_offsets[i];
            keys[i] = external_keys[i];
        } else {
            free(offsets);
            free(keys);
            return NULL;
        }
    }

    // Allocate memory for the records array
    record *records = malloc(n * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Populate records with initialized data and random values
    for (int i = 0; i < n; ++i) {
        records[i].key = keys[i];
        records[i].offset = offsets[i];
        records[i].length = rand() % 1001; // Random length between 0 and 1000

        if (minValue <= maxValue) {
            records[i].value = minValue + rand() % (maxValue - minValue + 1);
        } else {
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }
    }

    // Free the temporary arrays as they are no longer needed
    free(offsets);
    free(keys);

    return records; // Return pointer to the array of records
}
