#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef enum { DEBUG, INFO, WARNING, ERROR } LogLevel;

typedef struct {
    time_t timestamp;
    LogLevel level;
    char *message;
    int pid;
} log_entry;

#define MAX_LOG_FILES 100
#define MAX_ENTRIES_PER_FILE 1000

// Global variables for logging mechanism
static pthread_mutex_t call_count_lock = PTHREAD_MUTEX_INITIALIZER;
static unsigned long function_call_count = 0;
static double total_execution_duration = 0.0;

void increment_call_count(double duration) {
    pthread_mutex_lock(&call_count_lock);
    function_call_count++;
    total_execution_duration += duration;
    pthread_mutex_unlock(&call_count_lock);
}

int processAndAnalyzeLogFiles() {
    clock_t start_time, end_time;
    start_time = clock();

    char **log_filenames = malloc(MAX_LOG_FILES * sizeof(char *));
    if (!log_filenames) return 1;

    time_t *timestamps = malloc(MAX_LOG_FILES * MAX_ENTRIES_PER_FILE * sizeof(time_t));
    if (!timestamps) {
        free(log_filenames);
        return 1;
    }

    log_entry *entries = malloc(MAX_LOG_FILES * MAX_ENTRIES_PER_FILE * sizeof(log_entry));
    if (!entries) {
        free(timestamps);
        free(log_filenames);
        return 1;
    }

    // Simulate reading filenames from standard input
    for (int i = 0; i < MAX_LOG_FILES && fgets(log_filenames[i], 256, stdin); i++) {
        log_filenames[i][strcspn(log_filenames[i], "\n")] = '\0'; // Remove newline character

        // Generate random log entries
        for (int j = 0; j < MAX_ENTRIES_PER_FILE; j++) {
            time(&timestamps[i * MAX_ENTRIES_PER_FILE + j]);
            entries[i * MAX_ENTRIES_PER_FILE + j].timestamp = timestamps[i * MAX_ENTRIES_PER_FILE + j];
            entries[i * MAX_ENTRIES_PER_FILE + j].level = rand() % 4;
            entries[i * MAX_ENTRIES_PER_FILE + j].message = strdup("Sample log message");
            entries[i * MAX_ENTRIES_PER_FILE + j].pid = rand();
        }
    }

    // Filter and sort by timestamp
    qsort(entries, MAX_LOG_FILES * MAX_ENTRIES_PER_FILE, sizeof(log_entry), 
          (int (*)(const void *, const void *))strcmp);

    // Analyze log levels
    int level_counts[4] = {0};
    for (int i = 0; i < MAX_LOG_FILES * MAX_ENTRIES_PER_FILE; i++) {
        if (entries[i].timestamp != 0) { // Valid entry
            level_counts[entries[i].level]++;
        }
    }

    double total_entries = 0;
    for (int i = 0; i < 4; i++) {
        total_entries += level_counts[i];
    }

    printf("Log Level Analysis:\n");
    for (int i = 0; i < 4; i++) {
        printf("%s: %d (%.2f%%)\n", 
               i == DEBUG ? "DEBUG" : i == INFO ? "INFO" : i == WARNING ? "WARNING" : "ERROR",
               level_counts[i], (total_entries > 0) ? (level_counts[i] * 100 / total_entries) : 0);
    }

    // Clean up
    for (int i = 0; i < MAX_LOG_FILES; i++) {
        free(log_filenames[i]);
        for (int j = 0; j < MAX_ENTRIES_PER_FILE; j++) {
            if (entries[i * MAX_ENTRIES_PER_FILE + j].message) {
                free(entries[i * MAX_ENTRIES_PER_FILE + j].message);
            }
        }
    }

    free(log_filenames);
    free(timestamps);
    free(entries);

    end_time = clock();
    increment_call_count((double)(end_time - start_time) / CLOCKS_PER_SEC);

    return 0;
}
