['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_TIMESTAMP 2147483647
#define MIN_SESSION_DURATION 1 // in seconds
#define SYSTEM_MEMORY_LIMIT 1048576000 // Example: 1GB

typedef struct {
    int person_id;
    char name[100];
} Person;

typedef struct {
    int session_id;
    time_t timestamp;
    int duration; // in seconds
    int person_id;
} Session;

typedef struct {
    int activity_id;
    time_t event_time;
    int session_id;
    char type[50];
} Activity;

typedef struct Node {
    int key;
    void *value;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} HashMap;

void hashmap_init(HashMap* map) {
    map->head = NULL;
    pthread_mutex_init(&map->lock, NULL);
}

Node* hashmap_create_node(int key, void *value) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->key = key;
    node->value = value;
    node->next = NULL;
    return node;
}

void hashmap_put(HashMap* map, int key, void *value) {
    pthread_mutex_lock(&map->lock);

    Node** curr = &map->head;
    while (*curr) {
        if ((*curr)->key == key) {
            (*curr)->value = value;
            pthread_mutex_unlock(&map->lock);
            return;
        }
        curr = &(*curr)->next;
    }

    Node* node = hashmap_create_node(key, value);
    if (node) {
        node->next = map->head;
        map->head = node;
    }

    pthread_mutex_unlock(&map->lock);
}

void* hashmap_get(HashMap* map, int key) {
    pthread_mutex_lock(&map->lock);

    Node* curr = map->head;
    while (curr) {
        if (curr->key == key) {
            pthread_mutex_unlock(&map->lock);
            return curr->value;
        }
        curr = curr->next;
    }

    pthread_mutex_unlock(&map->lock);
    return NULL;
}

void free_resources(Person** persons, Session* sessions, Activity* activities, size_t num_sessions, HashMap* person_map, HashMap* activity_map) {
    if (persons) for (size_t i = 0; i < num_sessions; ++i) free(persons[i]);
    free(persons);

    for (size_t i = 0; i < num_sessions; ++i) {
        Node* curr = person_map->head;
        while (curr && ((Person*)curr->value)->person_id == sessions[i].person_id)
            curr = curr->next;
        if (curr) free(curr);
    }

    pthread_mutex_destroy(&person_map->lock);

    for (size_t i = 0; i < num_sessions; ++i) {
        Node* curr = activity_map->head;
        while (curr && ((Activity*)curr->value)->session_id == sessions[i].session_id)
            curr = curr->next;
        if (curr) free(curr);
    }

    pthread_mutex_destroy(&activity_map->lock);

    free(sessions);
    free(activities);
}

int validate_session(const Session* session, size_t num_sessions) {
    if (session->timestamp > MAX_TIMESTAMP || session->duration < MIN_SESSION_DURATION)
        return 0;
    for (size_t i = 0; i < num_sessions; ++i)
        if (session->person_id != ((Session*)session)[i].person_id)
            return 0;
    return 1;
}

void log_memory_usage(size_t usage) {
    printf("Current memory usage: %zu bytes\n", usage);
    if (usage > SYSTEM_MEMORY_LIMIT * 0.9) // 90% threshold
        printf("Warning: Memory usage approaching system limit.\n");
}

int allocate_and_initialize(int num_sessions, Person*** persons, Session** sessions, Activity** activities, HashMap* person_map, HashMap* activity_map) {
    if (num_sessions <= 0)
        return -1;

    size_t estimated_size = sizeof(Person*) * num_sessions + sizeof(Session) * num_sessions + sizeof(Activity) * num_sessions;
    log_memory_usage(estimated_size);

    // Check memory limits
    if (estimated_size > SYSTEM_MEMORY_LIMIT) {
        fprintf(stderr, "Error: Memory allocation exceeds system limit.\n");
        return -1;
    }

    *persons = (Person**)malloc(sizeof(Person*) * num_sessions);
    *sessions = (Session*)malloc(sizeof(Session) * num_sessions);
    *activities = (Activity*)malloc(sizeof(Activity) * num_sessions);

    if (!*persons || !*sessions || !*activities) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free_resources(*persons, *sessions, *activities, num_sessions, person_map, activity_map);
        return -1;
    }

    for (size_t i = 0; i < num_sessions; ++i) {
        (*sessions)[i].session_id = i + 1;
        (*sessions)[i].timestamp = time(NULL); // current time
        (*sessions)[i].duration = MIN_SESSION_DURATION + rand() % 3600; // Random duration between 1 and 3600 seconds

        if (!validate_session(&(*sessions)[i], num_sessions)) {
            fprintf(stderr, "Warning: Invalid session data at index %zu.\n", i);
            continue;
        }

        (*persons)[i] = (Person*)malloc(sizeof(Person));
        if (!(*persons)[i]) {
            fprintf(stderr, "Error: Memory allocation failed for person at index %zu.\n", i);
            free_resources(*persons, *sessions, *activities, num_sessions, person_map, activity_map);
            return -1;
        }

        (*persons)[i]->person_id = (*sessions)[i].person_id;
        snprintf((*persons)[i]->name, sizeof((*persons)[i])->name, "Person_%d", (*persons)[i]->person_id);

        hashmap_put(person_map, (*sessions)[i].session_id, *(*persons + i));

        for (int j = 0; j < rand() % 5 + 1; ++j) { // Random number of activities per session
            (*activities)[i * 5 + j].activity_id = j + 1;
            (*activities)[i * 5 + j].event_time = time(NULL);
            (*activities)[i * 5 + j].session_id = (*sessions)[i].session_id;
            snprintf((*activities)[i * 5 + j].type, sizeof((*activities)[i * 5 + j]).type, "Activity_Type_%d", j);

            hashmap_put(activity_map, (*activities)[i * 5 + j].activity_id, &(*activities)[i * 5 + j]);
        }
    }

    log_memory_usage(estimated_size);
    return 0;
}
