// Database interaction
class EmployeeDatabase {
private:
    sqlite3* db;

public:
    EmployeeDatabase(const std::string& dbName) {
        if (sqlite3_open(dbName.c_str(), &db)) {
            throw std::runtime_error("Can't open database: " + std::string(sqlite3_errmsg(db)));
        }
    }

    ~EmployeeDatabase() {
        sqlite3_close(db);
    }

    void queryEmployees(int supervisorId) const {
        std::string sql = "SELECT name, city, address FROM Employees WHERE supervisor_id = ?";
        sqlite3_stmt* stmt;
        if (sqlite3_prepare_v2(db, sql.c_str(), -1, &stmt, nullptr) != SQLITE_OK) {
            throw std::runtime_error("Failed to prepare statement: " + std::string(sqlite3_errmsg(db)));
        }

        sqlite3_bind_int(stmt, 1, supervisorId);

        while (sqlite3_step(stmt) == SQLITE_ROW) {
            const char* name = reinterpret_cast<const char*>(sqlite3_column_text(stmt, 0));
            const char* city = reinterpret_cast<const char*>(sqlite3_column_text(stmt, 1));
            const char* address = reinterpret_cast<const char*>(sqlite3_column_text(stmt, 2));

            std::cout << "Name: " << name << ", City: " << city << ", Address: " << address << "\n";
        }

        sqlite3_finalize(stmt);
    }
};

int main() {
    BalancedBST bst;
    EmployeeDatabase db("employees.db");

    // Example usage
    bst.insert(bst.generateRandomKey(0, 100));
    std::cout << (bst.find(42) ? "Found" : "Not found") << "\n";

    try {
        db.queryEmployees(1);
    } catch (const std::exception& e) {
        std::cerr << e.what() << "\n";
    }

    return 0;
}
