#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define CACHE_SIZE 100
#define HASH_TABLE_SIZE 256
#define RANDOM_RANGE_MAX 1000

typedef struct record {
    int value;
    pthread_mutex_t lock; // Lock for thread-safe operations on individual records
} record;

typedef struct list_node {
    record *data;
    struct list_node *next;
} list_node;

typedef struct linked_list {
    list_node *head;
    pthread_mutex_t mutex;
} linked_list;

typedef struct cache_entry {
    int key;
    record data;
    int access_count; // Simple counter to track frequency of access
} cache_entry;

typedef struct hash_table {
    void **buckets[HASH_TABLE_SIZE];
    pthread_rwlock_t rwlock[HASH_TABLE_SIZE];
} hash_table;

// Function prototypes
void initialize_system(long *offsets, int num_offsets, int *keys, int num_keys, record *records, int num_records, linked_list *list, hash_table *hash);
void free_resources(long *offsets, int *keys, record *records, linked_list *list, hash_table *hash, cache_entry *cache, int cache_size);
void serialize_data(FILE *file, long *offsets, int num_offsets, int *keys, int num_keys, record *records, int num_records);
int deserialize_data(FILE *file, long **offsets, int *num_offsets, int **keys, int *num_keys, record ***records, int *num_records);

void initialize_system(long *offsets, int num_offsets, int *keys, int num_keys, record *records, int num_records, linked_list *list, hash_table *hash) {
    if (!offsets || !keys || !records || !list || !hash) return;

    // Initialize arrays
    for (int i = 0; i < num_offsets; ++i) offsets[i] = rand() % RANDOM_RANGE_MAX;
    for (int i = 0; i < num_keys; ++i) keys[i] = rand() % RANDOM_RANGE_MAX;

    // Initialize records with random values
    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        pthread_mutex_init(&records[i].lock, NULL);
        records[i].value = rand() % RANDOM_RANGE_MAX;
    }

    // Initialize linked list
    pthread_mutex_init(&list->mutex, NULL);
    list->head = NULL;

    // Initialize hash table
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hash->buckets[i] = NULL;
        pthread_rwlock_init(&hash->rwlock[i], NULL);
    }

    printf("System initialized successfully.\n");
}

void free_resources(long *offsets, int *keys, record *records, linked_list *list, hash_table *hash, cache_entry *cache, int cache_size) {
    // Free records
    for (int i = 0; i < num_records; ++i) {
        pthread_mutex_destroy(&records[i].lock);
    }
    free(records);

    // Free linked list nodes
    pthread_mutex_lock(&list->mutex);
    list_node *current = list->head;
    while (current != NULL) {
        list_node *temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);

    // Free hash table
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        if (hash->buckets[i] != NULL) free(hash->buckets[i]);
        pthread_rwlock_destroy(&hash->rwlock[i]);
    }

    // Free cache entries
    for (int i = 0; i < cache_size; ++i) {
        free(cache);
    }

    printf("Resources freed successfully.\n");
}

void serialize_data(FILE *file, long *offsets, int num_offsets, int *keys, int num_keys, record *records, int num_records) {
    if (!file || !offsets || !keys || !records) return;

    fwrite(&num_offsets, sizeof(int), 1, file);
    fwrite(offsets, sizeof(long), num_offsets, file);

    fwrite(&num_keys, sizeof(int), 1, file);
    fwrite(keys, sizeof(int), num_keys, file);

    fwrite(&num_records, sizeof(int), 1, file);
    for (int i = 0; i < num_records; ++i) {
        pthread_mutex_lock(&records[i].lock);
        fwrite(&records[i], sizeof(record), 1, file);
        pthread_mutex_unlock(&records[i].lock);
    }

    printf("Data serialized successfully.\n");
}

int deserialize_data(FILE *file, long **offsets, int *num_offsets, int **keys, int *num_keys, record ***records, int *num_records) {
    if (!file || !offsets || !keys || !records) return -1;

    fread(num_offsets, sizeof(int), 1, file);
    *offsets = (long *)malloc(*num_offsets * sizeof(long));
    if (!*offsets) return -1;
    fread(*offsets, sizeof(long), *num_offsets, file);

    fread(num_keys, sizeof(int), 1, file);
    *keys = (int *)malloc(*num_keys * sizeof(int));
    if (!*keys) {
        free(*offsets);
        return -1;
    }
    fread(*keys, sizeof(int), *num_keys, file);

    fread(num_records, sizeof(int), 1, file);
    *records = (record **)malloc(*num_records * sizeof(record *));
    if (!*records) {
        free(*offsets);
        free(*keys);
        return -1;
    }

    for (int i = 0; i < *num_records; ++i) {
        (*records)[i] = (record *)malloc(sizeof(record));
        if (!(*records)[i]) {
            // Free previously allocated memory in case of error
            while (--i >= 0) free((*records)[i]);
            free(*offsets);
            free(*keys);
            free(*records);
            return -1;
        }
        pthread_mutex_init(&(*records[i])->lock, NULL);
        fread((*records)[i], sizeof(record), 1, file);
    }

    printf("Data deserialized successfully.\n");
    return 0;
}
