// Memory Pool Functions
MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool *pool = (MemoryPool *)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->records = (Record *)malloc(initial_size * sizeof(Record));
    if (!pool->records) {
        free(pool);
        return NULL;
    }

    pool->capacity = initial_size;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);

    log_message("INFO", "Memory pool created");
    return pool;
}

void destroy_memory_pool(MemoryPool *pool) {
    if (pool) {
        free(pool->records);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
        log_message("INFO", "Memory pool destroyed");
    }
}

Record* allocate_record(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->count >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        Record *new_records = (Record *)realloc(pool->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&pool->lock);
            log_message("ERROR", "Memory reallocation failed");
            return NULL;
        }

        pool->records = new_records;
        pool->capacity = new_capacity;
    }

    Record *record = &pool->records[pool->count++];
    pthread_mutex_unlock(&pool->lock);

    return record;
}

// Hash Table Functions
HashTable* create_hash_table(void) {
    HashTable *table = (HashTable *)malloc(sizeof(HashTable));
    if (!table) return NULL;

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        table->buckets[i] = NULL;
    }

    pthread_mutex_init(&table->lock, NULL);
    log_message("INFO", "Hash table created");
    return table;
}

void destroy_hash_table(HashTable *table) {
    if (table) {
        for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
            RecordNode *node = table->buckets[i];
            while (node) {
                RecordNode *next_node = node->next;
                free(node);
                node = next_node;
            }
        }

        pthread_mutex_destroy(&table->lock);
        free(table);
        log_message("INFO", "Hash table destroyed");
    }
}

int hash_function(unsigned long unique_id) {
    return (unique_id % HASH_TABLE_SIZE);
}

RecordNode* insert_record(HashTable *table, Record *record) {
    int index = hash_function(record->unique_id);

    pthread_mutex_lock(&table->lock);

    RecordNode *node = (RecordNode *)malloc(sizeof(RecordNode));
    if (!node) {
        pthread_mutex_unlock(&table->lock);
        log_message("ERROR", "Failed to allocate node for hash table");
        return NULL;
    }

    node->record = record;
    node->next = table->buckets[index];
    table->buckets[index] = node;

    pthread_mutex_unlock(&table->lock);

    log_message("INFO", "Record inserted into hash table");
    return node;
}

RecordNode* find_record(HashTable *table, unsigned long unique_id) {
    int index = hash_function(unique_id);

    pthread_mutex_lock(&table->lock);

    RecordNode *node = table->buckets[index];
    while (node) {
        if (node->record->unique_id == unique_id) {
            pthread_mutex_unlock(&table->lock);
            return node;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&table->lock);
    return NULL;  // Record not found
}
