typedef enum { SUCCESS, MEMORY_ERROR, DIRECTORY_CREATION_ERROR } ErrorCode;

ErrorCode createDirectoryWithEnvVar(const char *dirName) {
    char *envValue = getenv("MY_DIRECTORY_PATH");

    if (envValue) {
        return SUCCESS; // Directory path is already set.
    }

    int result = mkdir(dirName, 0777);
    if (result != 0 && errno != EEXIST) {
        perror("Error creating directory");
        return DIRECTORY_CREATION_ERROR;
    }

    setenv("MY_DIRECTORY_PATH", dirName, 1); // Set the environment variable.
    return SUCCESS;
}

