    if (keys) free(keys);
    if (records) free(records);
    if (metadata) free(metadata);
}

ErrorCode processAndSortRecordsWithDir(const char *dirName, size_t count) {
    long *offsets = malloc(count * sizeof(long));
    int *keys = malloc(count * sizeof(int));
    record_t *records = malloc(count * sizeof(record_t));
    metadata_t *metadata = malloc(count * sizeof(metadata_t));

    if (!offsets || !keys || !records || !metadata) {
        freeResources(offsets, keys, records, metadata);
        return MEMORY_ERROR;
    }

    // Populate arrays with random values.
    for (size_t i = 0; i < count; ++i) {
        offsets[i] = rand() % 100000;
        keys[i] = rand() % 1000;
        records[i].value = rand() % 100;
        metadata[i].timestamp = time(NULL);
        metadata[i].status_flag = rand() % 2;
    }

    // Sort based on key values.
    for (size_t i = 0; i < count - 1; ++i) {
        for (size_t j = 0; j < count - i - 1; ++j) {
            if (keys[j] > keys[j + 1]) {
                int tempKey = keys[j];
                keys[j] = keys[j + 1];
                keys[j + 1] = tempKey;

                long tempOffset = offsets[j];
                offsets[j] = offsets[j + 1];
                offsets[j + 1] = tempOffset;

                record_t tempRecord = records[j];
                records[j] = records[j + 1];
                records[j + 1] = tempRecord;

                metadata_t tempMeta = metadata[j];
                metadata[j] = metadata[j + 1];
                metadata[j + 1] = tempMeta;
            }
        }
    }

    // Handle directory creation and environment variable setting.
    ErrorCode dirResult = createDirectoryWithEnvVar(dirName);
    if (dirResult != SUCCESS) {
        freeResources(offsets, keys, records, metadata);
        return dirResult;
    }

    logOperation("Records processed and sorted");

    // Reading integers from stdin and finding the largest integer.
    int *inputArray = NULL;
    size_t inputCount = 0;

    while (scanf("%d", &inputArray) == 1) {
        size_t newSize = (inputCount + 1) * sizeof(int);
        int *newArray = realloc(inputArray, newSize);

        if (!newArray) {
            freeResources(offsets, keys, records, metadata);
            free(inputArray);
            return MEMORY_ERROR;
        }

        inputArray = newArray;
        inputArray[inputCount++] = inputArray;
    }

    int maxInt = (inputCount > 0) ? inputArray[0] : INT_MIN;
    for (size_t i = 1; i < inputCount; ++i) {
        if (inputArray[i] > maxInt) {
            maxInt = inputArray[i];
        }
    }

    printf("Largest integer: %d\n", maxInt);
    free(inputArray);

    freeResources(offsets, keys, records, metadata);
    return SUCCESS;
}

void *threadFunction(void *arg) {
