long random_long(long min, long max) {
    return min + rand() % (max - min + 1);
}

int random_int(int min, int max) {
    return min + rand() % (max - min + 1);
}

double random_double(double min, double max) {
    return min + ((double)rand() / RAND_MAX) * (max - min);
}

char* random_string(size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    char *str = malloc(length + 1);
    if (!str) return NULL;
    for (size_t i = 0; i < length; i++) {
        int key = rand() % (int)(sizeof(charset) - 1);
        str[i] = charset[key];
    }
    str[length] = '\0';
    return str;
}

bool clear_directory(const char *path) {
    DIR *dir = opendir(path);
    if (!dir) return false;

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char full_path[1024];
        snprintf(full_path, sizeof(full_path), "%s/%s", path, entry->d_name);
        struct stat statbuf;
        if (stat(full_path, &statbuf) != 0) continue;

        if (S_ISDIR(statbuf.st_mode)) {
            clear_directory(full_path);
            rmdir(full_path);
        } else {
            unlink(full_path);
        }
    }

    closedir(dir);
    return true;
}

bool execute_command_with_retries(const char *command, int retries, const char **files) {
    for (int attempt = 0; attempt < retries; ++attempt) {
        if (system(command) == 0) {
            for (const char **file = files; *file != NULL; ++file) {
                unlink(*file);
            }
            return true;
        } else {
            sleep(1); // Wait before retrying
        }
    }
    return false;
}

void log_system_resources(const char *logfile) {
    FILE *log = fopen(logfile, "a");
    if (!log) return;

    // Log memory, swap usage, and CPU load (example placeholders)
    fprintf(log, "Memory: %ld KB\n", 1024); // Placeholder
    fprintf(log, "Swap: %ld KB\n", 2048);   // Placeholder
    fprintf(log, "CPU Load: %.2f%%\n", 10.5); // Placeholder

    fclose(log);
}

void free_linked_list(Node *head) {
    Node *current = head;
    while (current) {
        Node *next = current->next;
        free(current->data.str);
        free(current);
        current = next;
    }
}

