    const char *directory_path = "./test_directory";
    const int num_records = 10;
    const int retries = 3;

    if (!clear_directory(directory_path)) {
        fprintf(stderr, "Failed to clear directory\n");
        return EXIT_FAILURE;
    }

    init_random();

    Node *head = NULL, *tail = NULL;
    for (int i = 0; i < num_records; ++i) {
        Node *new_node = malloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed\n");
            free_linked_list(head);
            return EXIT_FAILURE;
        }

        new_node->data.l = random_long(1, 100);
        new_node->data.i = random_int(1, 1000);
        new_node->data.d = random_double(1.0, 10.0);
        new_node->data.str = random_string(10);

        new_node->next = NULL;
        if (tail) {
            tail->next = new_node;
            new_node->prev = tail;
        } else {
            head = new_node;
            new_node->prev = NULL;
        }
        tail = new_node;
    }

    const char *command = "echo Test Command";
    const char *files_to_delete[] = { "file1.txt", "file2.txt", NULL };

    if (!execute_command_with_retries(command, retries, files_to_delete)) {
