#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <math.h>

typedef enum {
    MEDIA_TYPE_A,
    MEDIA_TYPE_B,
    // Add more media types as needed
} media_type;

typedef struct {
    double value;
    char status;
    unsigned int id;
    media_type type;
} MediaData;

typedef struct {
    MediaData *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    FILE *log_file;
    int call_count;
    clock_t total_duration;
} MediaProcessor;

int initialize_processor(MediaProcessor *processor, size_t initial_capacity) {
    processor->data = (MediaData *)malloc(initial_capacity * sizeof(MediaData));
    if (!processor->data) return -1;

    processor->capacity = initial_capacity;
    processor->count = 0;
    pthread_mutex_init(&processor->lock, NULL);
    processor->log_file = fopen("media_processor.log", "a");
    if (!processor->log_file) {
        free(processor->data);
        return -1;
    }
    processor->call_count = 0;
    processor->total_duration = 0;

    return 0;
}

void log_operation(const MediaProcessor *processor, const char *message) {
    pthread_mutex_lock(&processor->lock);
    fprintf(processor->log_file, "%s\n", message);
    fflush(processor->log_file);
    pthread_mutex_unlock(&processor->lock);
}

double generate_normal(double mean, double stddev) {
    static unsigned int hasSpare = 0;
    static double spare;

    if (hasSpare) {
        hasSpare = 0;
        return mean + spare * stddev;
    }

    double u1, u2, w, mult;
    do {
        u1 = rand() / (RAND_MAX + 1.0);
        u2 = rand() / (RAND_MAX + 1.0);
        w = sqrt(-2.0 * log(u1));
        mult = w * cos(2.0 * M_PI * u2);
        spare = w * sin(2.0 * M_PI * u2);
    } while (u1 <= DBL_EPSILON);

    hasSpare = 1;

    return mean + mult * stddev;
}

int add_media_data(MediaProcessor *processor, double mean, double stddev, unsigned int id, media_type type) {
    pthread_mutex_lock(&processor->lock);

    if (processor->count >= processor->capacity) {
        size_t new_capacity = processor->capacity * 2;
        MediaData *new_data = realloc(processor->data, new_capacity * sizeof(MediaData));
        if (!new_data) {
            log_operation(processor, "Failed to reallocate memory");
            pthread_mutex_unlock(&processor->lock);
            return -1;
        }
        processor->data = new_data;
        processor->capacity = new_capacity;
    }

    MediaData new_data_point;
    new_data_point.value = generate_normal(mean, stddev);
    new_data_point.status = 'N'; // Default status
    new_data_point.id = id;
    new_data_point.type = type;

    processor->data[processor->count++] = new_data_point;
    qsort(processor->data, processor->count, sizeof(MediaData), [](const void *a, const void *b) {
        MediaData *da = (MediaData *)a;
        MediaData *db = (MediaData *)b;
        return da->id - db->id;
    });

    log_operation(processor, "Added new media data");
    pthread_mutex_unlock(&processor->lock);

    return 0;
}

void free_processor(MediaProcessor *processor) {
    pthread_mutex_lock(&processor->lock);
    if (processor->data) free(processor->data);
    if (processor->log_file) fclose(processor->log_file);
    pthread_mutex_unlock(&processor->lock);
    pthread_mutex_destroy(&processor->lock);
}

int processAndConvertMedia(const char *input_filename, const char *output_filename) {
    MediaProcessor processor;
    if (initialize_processor(&processor, 10) != 0) return -1;

    // Example usage
    add_media_data(&processor, 0.0, 1.0, 123, MEDIA_TYPE_A);
    add_media_data(&processor, 5.0, 2.0, 456, MEDIA_TYPE_B);

    clock_t start = clock();
    system("convert input.jpg output.pdf"); // Replace with actual conversion command
    processor.total_duration += (clock() - start);
    processor.call_count++;

    free_processor(&processor);

    return 0;
}

int read_and_find_max(size_t *array, size_t size) {
    if (!array || size == 0) return -1;

    size_t max_value = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > max_value) {
            max_value = array[i];
        }
    }

    printf("Max value: %zu\n", max_value);
    return 0;
}

int convert_image_to_pdf(const char *input_filename, const char *output_filename) {
    int result = system(("convert " + std::string(input_filename) + " " + std::string(output_filename)).c_str());
    if (result != 0) {
        fprintf(stderr, "Failed to convert image\n");
        return 1;
    }
    return 0;
