#include <iostream>
#include <vector>
#include <unordered_set>
#include <mutex>
#include <shared_mutex>
#include <atomic>
#include <thread>
#include <condition_variable>
#include <queue>
#include <functional>

class LogEntry {
public:
    enum Priority { ERROR, WARNING, INFO };

    LogEntry(int id, Priority priority) : id_(id), priority_(priority) {}

    bool operator<(const LogEntry& other) const {
        return priority_ > other.priority_; // Higher priorities first
    }

    int getId() const { return id_; }
    Priority getPriority() const { return priority_; }

private:
    int id_;
    Priority priority_;
};

class DynamicLogBufferPool {
public:
    DynamicLogBufferPool(size_t initialSize = 1000000)
        : buffer_(initialSize), bufferSize_(initialSize) {
        resizeThreshold_ = 0.75 * bufferSize_;
    }

    void addLogEntry(const LogEntry& entry) {
        std::unique_lock lock(mutex_);

        if (buffer_.size() > resizeThreshold_) {
            resizeBuffer();
        }

        // Duplicate detection
        if (duplicateEntries_.find(entry.getId()) == duplicateEntries_.end()) {
            buffer_.push(entry);
            duplicateEntries_.insert(entry.getId());

            cv_.notify_one();  // Notify one waiting consumer
        }
    }

    LogEntry getNextLogEntry() {
        std::unique_lock lock(mutex_);

        cv_.wait(lock, [this]() { return !buffer_.empty(); });

        auto log = buffer_.top();
        buffer_.pop();

        duplicateEntries_.erase(log.getId());

        return log;
    }

    void resizeBuffer() {
        size_t newSize = bufferSize_ * 2;
        std::lock_guard<std::mutex> guard(mutex_);
        buffer_.resize(newSize);
        bufferSize_ = newSize;
        resizeThreshold_ = 0.75 * bufferSize_;
    }

private:
    std::priority_queue<LogEntry> buffer_;
    size_t bufferSize_;
    size_t resizeThreshold_;
    mutable std::mutex mutex_;
    std::condition_variable cv_;
    std::unordered_set<int> duplicateEntries_; // Detect duplicates
};

// Example usage and test
void producer(DynamicLogBufferPool& pool, int threadId) {
    for (int i = 0; i < 100; ++i) {
        LogEntry entry(i + threadId * 100, LogEntry::INFO);
        pool.addLogEntry(entry);
    }
}

void consumer(DynamicLogBufferPool& pool) {
    for (int i = 0; i < 10000; ++i) {
        auto log = pool.getNextLogEntry();
        std::cout << "Processed log with ID: " << log.getId() << "\n";
    }
}

int main() {
    DynamicLogBufferPool pool;

    const int numThreads = 10;
    std::vector<std::thread> producers;

    for (int i = 0; i < numThreads; ++i) {
        producers.emplace_back(producer, std::ref(pool), i);
    }

    std::thread consumerThread(consumer, std::ref(pool));

    for (auto& t : producers) {
        t.join();
    }

    consumerThread.join();

    return 0;
}
```

