use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::hash::{Hasher, BuildHasherDefault};
use std::num::NonZeroUsize;
use rand::Rng;
use std::time::Instant;

#[derive(Debug)]
struct Record {
    value: i32,
}

fn custom_hash<T>(t: &T) -> u64
where
    T: Hash + Copy,
{
    use std::collections::hash_map::DefaultHasher;
    let mut s = DefaultHasher::new();
    t.hash(&mut s);
    s.finish()
}

type CustomHashMap<K, V> = HashMap<K, V, BuildHasherDefault<CustomHasher>>;

struct CustomHasher([u64; 2]);

impl Hasher for CustomHasher {
    fn write(&mut self, bytes: &[u8]) {
        // A simple custom hash function
        let mut h1 = self.0[0];
        let mut h2 = self.0[1];

        for &byte in bytes.iter() {
            h1 = h1.wrapping_mul(31).wrapping_add(u64::from(byte));
            h2 = h2.wrapping_mul(53).wrapping_add(u64::from(byte));
        }

        self.0[0] = h1;
        self.0[1] = h2;
    }

    fn finish(&self) -> u64 {
        self.0[0].wrapping_add(self.0[1])
    }
}

fn manage_memory(num_records: usize, value_range: std::ops::Range<i32>) -> (bool, Vec<String>) {
    let mut logs = Vec::new();
    let offsets = Arc::new(Mutex::new(Vec::with_capacity(num_records)));
    let keys = Arc::new(Mutex::new(HashMap::with_capacity_and_hasher(
        num_records,
        BuildHasherDefault::<CustomHasher>::default(),
    )));
    let records = Arc::new(Mutex::new(Vec::with_capacity(num_records)));

    // Simulate concurrent access
    let handles: Vec<_> = (0..4).map(|_| {
        std::thread::spawn({
            let offsets = Arc::clone(&offsets);
            let keys = Arc::clone(&keys);
            let records = Arc::clone(&records);

            move || {
                let mut rng = rand::thread_rng();
                for i in 0..num_records {
                    let offset = i as u64;
                    let key = i as usize;

                    // Lock and update offsets
                    if let Ok(mut offsets) = offsets.lock() {
                        offsets.push(offset);
                    } else {
                        logs.push("Failed to lock offsets".to_string());
                    }

                    // Lock-free approach for keys using atomic operations
                    let mut keys_guard = keys.lock().unwrap();
                    keys_guard.insert(key, offset);

                    // Create and initialize records
                    let record_value: i32;
                    loop {
                        record_value = rng.gen_range(value_range.clone());
                        if value_range.contains(&record_value) {
                            break;
                        }
                    }

                    let record = Record { value: record_value };
                    if let Ok(mut records_guard) = records.lock() {
                        records_guard.push(record);
                    } else {
                        logs.push("Failed to lock records".to_string());
                    }
                }
            }
        })
    }).collect();

    for handle in handles {
        handle.join().unwrap();
    }

    // Evaluate memory usage and log
    let start_time = Instant::now();
    let mut offsets_guard = offsets.lock().unwrap();
    let mut keys_guard = keys.lock().unwrap();
    let mut records_guard = records.lock().unwrap();

    while !offsets_guard.is_empty() && !keys_guard.is_empty() && !records_guard.is_empty() {
        if offsets_guard.len() != num_records || keys_guard.len() != num_records || records_guard.len() != num_records {
            logs.push("Memory integrity issue".to_string());
            return (false, logs);
        }
    }

    let elapsed_time = start_time.elapsed();
    logs.push(format!("Execution time: {:?}", elapsed_time));

    (true, logs)
}

fn main() {
    let (success, logs) = manage_memory(1000, 1..100);
    if success {
        println!("Memory management successful.");
    } else {
        eprintln!("Errors encountered:");
        for log in logs {
            eprintln!("{}", log);
        }
    }
}
```

