    }

    public void cleanupResources() {
        executor.shutdownNow();
        records.clear();

        try {
            Files.walk(Paths.get(System.getProperty("java.io.tmpdir")))
                    .sorted((p1, p2) -> Long.compare(p1.toFile().lastModified(), p2.toFile().lastModified()))
                    .map(Path::toFile)
                    .forEach(File::deleteOnExit);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void handleBatchOperations(Consumer<Map<String, Record>> batchOperation) {
        Map<String, Record> snapshot = new HashMap<>(records);
        batchOperation.accept(snapshot);

        // Apply changes back to the main map in a thread-safe manner
        records.putAll(snapshot);
    }

    public void processFiles(Path directory) throws Exception {
