#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_THREADS 1000

typedef struct {
    uint32_t MAC_EVENT_TAG;
    time_t timestamp;
    size_t frame_data_size;
    uint8_t *MAC_FRAME_DATA;
} NetworkEvent;

typedef struct {
    int cellId;
    time_t timestamp;
    double throughput;
} NetworkPerformanceMetrics;

typedef struct {
    NetworkEvent *events;
    size_t event_count;
    size_t capacity;
    pthread_mutex_t lock;
} EventList;

typedef struct {
    NetworkPerformanceMetrics *metricsArray;
    size_t entryCount;
    size_t capacity;
    size_t index;
    double totalThroughput;
    pthread_rwlock_t metricsLock;
} PerformanceMetricsList;

void initEventList(EventList *list) {
    list->events = NULL;
    list->event_count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void freeEventList(EventList *list) {
    for (size_t i = 0; i < list->event_count; ++i) {
        free(list->events[i].MAC_FRAME_DATA);
    }
    free(list->events);
    pthread_mutex_destroy(&list->lock);
}

int addNetworkEvent(EventList *list, NetworkEvent event) {
    pthread_mutex_lock(&list->lock);

    if (list->event_count == list->capacity) {
        size_t new_capacity = list->capacity == 0 ? 16 : list->capacity * 2;
        NetworkEvent *new_events = realloc(list->events, new_capacity * sizeof(NetworkEvent));
        if (!new_events) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation error
        }
        list->events = new_events;
        list->capacity = new_capacity;
    }

    list->events[list->event_count++] = event;
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

void initPerformanceMetrics(PerformanceMetricsList *metrics) {
    metrics->metricsArray = NULL;
    metrics->entryCount = 0;
    metrics->capacity = 10;
    metrics->index = 0;
    metrics->totalThroughput = 0.0;

    pthread_rwlock_init(&metrics->metricsLock, NULL);
}

void freePerformanceMetrics(PerformanceMetricsList *metrics) {
    free(metrics->metricsArray);
    pthread_rwlock_destroy(&metrics->metricsLock);
}

int addNetworkPerformanceMetric(PerformanceMetricsList *metrics, NetworkPerformanceMetrics metric) {
    pthread_rwlock_wrlock(&metrics->metricsLock);

    if (metrics->entryCount == metrics->capacity) {
        size_t new_capacity = metrics->capacity * 2;
        NetworkPerformanceMetrics *new_metricsArray = realloc(metrics->metricsArray, new_capacity * sizeof(NetworkPerformanceMetrics));
        if (!new_metricsArray) {
            pthread_rwlock_unlock(&metrics->metricsLock);
            return -1; // Memory allocation error
        }
        metrics->metricsArray = new_metricsArray;
        metrics->capacity = new_capacity;
    }

    if (metrics->entryCount < 10) {
        metrics->totalThroughput += metric.throughput;
    } else {
        metrics->totalThroughput -= metrics->metricsArray[metrics->index].throughput;
        metrics->totalThroughput += metric.throughput;
    }

    int idx = (metrics->index + metrics->entryCount) % 10;
    metrics->metricsArray[idx] = metric;
    if (metrics->entryCount < 10) {
        ++metrics->entryCount;
    }

    metrics->index = (metrics->index + 1) % 10;

    pthread_rwlock_unlock(&metrics->metricsLock);

    return 0; // Success
}

double getMovingAverageThroughput(PerformanceMetricsList *metrics) {
    pthread_rwlock_rdlock(&metrics->metricsLock);

    double average = metrics->entryCount < 10 ? (metrics->totalThroughput / metrics->entryCount) : (metrics->totalThroughput / 10.0);

    pthread_rwlock_unlock(&metrics->metricsLock);

    return average;
}

// Simulated traffic model function to mimic real-world peak and off-peak patterns.
double simulateTrafficModel() {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    int hour = local_time->tm_hour;

    if (hour >= 8 && hour < 20) { // Peak hours
        return (rand() % 100 + 50.0); // Higher throughput
    } else { // Off-peak hours
        return (rand() % 50 + 10.0); // Lower throughput
    }
}

void generateAndLogPerformanceMetrics(PerformanceMetricsList *metrics) {
    NetworkPerformanceMetrics metric;
    metric.cellId = rand(); // Unique cell ID for simplicity
    metric.timestamp = time(NULL);
    metric.throughput = simulateTrafficModel();

    addNetworkPerformanceMetric(metrics, metric);

    double averageThroughput = getMovingAverageThroughput(metrics);
    printf("Current moving average throughput: %.2f\n", averageThroughput);
}

// Example usage
int main() {
    EventList event_list;
    initEventList(&event_list);

    PerformanceMetricsList metrics;
    initPerformanceMetrics(&metrics);

    for (int i = 0; i < 100; ++i) {
        generateAndLogPerformanceMetrics(&metrics);
    }

    freeEventList(&event_list);
    freePerformanceMetrics(&metrics);

    return 0;
}
