#include <pthread.h>

#define MAX_STRING_LENGTH 1024
#define ERROR_CODE -1

typedef struct {
    int value;
} record;

typedef struct {
    double x, y;
} point;

// Function prototypes
int initialize_and_sort(int n, long *offsets, int *keys, record **records,
                        double *doubles, char **strings, point **points, 
                        double **distances);

void free_resources(long *offsets, int *keys, record *records, double *doubles,
                    char **strings, point *points, double *distances);

double calculate_euclidean_distance(point a, point b);
void *distance_calculator(void *args);

// Initialize and sort records
int initialize_and_sort(int n, long *offsets, int *keys, record **records,
                        double *doubles, char **strings, point **points, 
                        double **distances) {
    if (n <= 0 || offsets == NULL || keys == NULL || records == NULL ||
        doubles == NULL || strings == NULL || points == NULL || distances == NULL) {
        return ERROR_CODE;
    }

    pthread_t threads[4];
    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);

    offsets = (long *)malloc(n * sizeof(long));
    keys = (int *)malloc(n * sizeof(int));
    records = (record **)malloc(n * sizeof(record *));
    doubles = (double *)malloc(n * sizeof(double));
    strings = (char **)malloc(n * sizeof(char *));
    points = (point **)malloc(n * sizeof(point *));
    distances = (double **)malloc((n * (n - 1) / 2) * sizeof(double));

    if (!offsets || !keys || !records || !doubles || !strings || !points || !distances) {
        free_resources(offsets, keys, NULL, doubles, strings, points, distances);
        return ERROR_CODE;
    }

    for (int i = 0; i < n; ++i) {
        offsets[i] = rand() % 100000;
        keys[i] = rand() % 100;

        records[i] = (record *)malloc(sizeof(record));
        if (!records[i]) {
            free_resources(offsets, keys, NULL, doubles, strings, points, distances);
            return ERROR_CODE;
        }
        records[i]->value = rand() % 1000;

        doubles[i] = (double)rand() / RAND_MAX * 100.0;

        strings[i] = (char *)malloc(MAX_STRING_LENGTH);
        if (!strings[i]) {
            free_resources(offsets, keys, NULL, doubles, strings, points, distances);
            return ERROR_CODE;
        }
        snprintf(strings[i], MAX_STRING_LENGTH, "String %d", i);

        points[i] = (point *)malloc(sizeof(point));
        if (!points[i]) {
            free_resources(offsets, keys, NULL, doubles, strings, points, distances);
            return ERROR_CODE;
        }
        int grid_size = 10; // Example grid size
        points[i]->x = rand() % grid_size;
        points[i]->y = rand() % grid_size;
    }

    // Sort records based on key values
    for (int i = 0; i < n - 1; ++i) {
        for (int j = 0; j < n - i - 1; ++j) {
            if (keys[j] > keys[j + 1]) {
                int temp_key = keys[j];
                keys[j] = keys[j + 1];
                keys[j + 1] = temp_key;

                long temp_offset = offsets[j];
                offsets[j] = offsets[j + 1];
                offsets[j + 1] = temp_offset;

                record *temp_record = records[j];
                records[j] = records[j + 1];
                records[j + 1] = temp_record;
            }
        }
    }

    // Calculate Euclidean distances in parallel
    int index = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            distances[index] = calculate_euclidean_distance(*points[i], *points[j]);
            if (distances[index++] > 100.0) { // Example threshold
                free_resources(offsets, keys, NULL, doubles, strings, points, distances);
                return ERROR_CODE;
            }
