#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_AUDIO_FRAMES 1000
#define SAMPLE_MIN -32768
#define SAMPLE_MAX 32767
#define THRESHOLD_LEVEL 5000

typedef struct {
    short *samples;
    float timestamp;
} audioFrame;

// Third-party WAV processing library headers
extern int third_party_wav_process(const char* input_name, const char* output_name);

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initializeRandom() {
    srand(time(NULL));
}

short generateRandomSample() {
    return (short)(rand() % (SAMPLE_MAX - SAMPLE_MIN + 1) + SAMPLE_MIN);
}

float generateRandomTimestamp() {
    return (float)(rand() / (RAND_MAX / 100.0)); // Example: timestamps between 0 and 100
}

audioFrame* allocateAudioFrames(int num_frames, int samples_per_frame, int *error_code) {
    audioFrame *frames = malloc(num_frames * sizeof(audioFrame));
    if (!frames) {
        *error_code = -1;
        return NULL;
    }

    for (int i = 0; i < num_frames; ++i) {
        frames[i].samples = malloc(samples_per_frame * sizeof(short));
        if (!frames[i].samples) {
            *error_code = -2;
            free(frames);
            return NULL;
        }
        frames[i].timestamp = generateRandomTimestamp();
    }

    return frames;
}

void releaseAudioFrames(audioFrame *frames, int num_frames, int samples_per_frame) {
    for (int i = 0; i < num_frames; ++i) {
        free(frames[i].samples);
    }
    free(frames);
}

float maxTimestamp(float *timestamps, size_t count) {
    float max_ts = timestamps[0];
    for (size_t i = 1; i < count; ++i) {
        if (timestamps[i] > max_ts) {
            max_ts = timestamps[i];
        }
    }
    return max_ts;
}

void filterAudioFrames(audioFrame *frames, int num_frames, int samples_per_frame) {
    for (int i = 0; i < num_frames; ++i) {
        float moving_average = 0.0f;
        short sum = 0;

        for (int j = 0; j < samples_per_frame; ++j) {
            sum += frames[i].samples[j];
        }

        moving_average = (float)sum / samples_per_frame;

        if (moving_average > THRESHOLD_LEVEL) {
            for (int j = 0; j < samples_per_frame; ++j) {
                frames[i].samples[j] = 0; // Suppress noise
            }
        }
    }
}

void processAudioStream(int num_frames, int samples_per_frame, const char *input_file, const char *output_file) {
    initializeRandom();

    int error_code;
    audioFrame *frames = allocateAudioFrames(num_frames, samples_per_frame, &error_code);
    if (!frames || error_code != 0) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    for (int i = 0; i < num_frames; ++i) {
        for (int j = 0; j < samples_per_frame; ++j) {
            frames[i].samples[j] = generateRandomSample();
        }
    }

    filterAudioFrames(frames, num_frames, samples_per_frame);

    float *timestamps = malloc(num_frames * sizeof(float));
    if (!timestamps) {
        releaseAudioFrames(frames, num_frames, samples_per_frame);
        fprintf(stderr, "Memory allocation for timestamps failed\n");
        return;
    }

    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_frames; ++i) {
        scanf("%f", &timestamps[i]);
    }
    float max_ts = maxTimestamp(timestamps, num_frames);
    printf("Maximum Timestamp: %f\n", max_ts);
    pthread_mutex_unlock(&lock);

    free(timestamps);

    int wav_process_status = third_party_wav_process(input_file, output_file);

    releaseAudioFrames(frames, num_frames, samples_per_frame);
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <num_frames> <samples_per_frame> <input_file> <output_file>\n", argv[0]);
        return 1;
    }

    int num_frames = atoi(argv[1]);
    int samples_per_frame = atoi(argv[2]);
    const char *input_file = argv[3];
    const char *output_file = argv[4];

    processAudioStream(num_frames, samples_per_frame, input_file, output_file);

    return 0;
}
