    MAC_EVENT_NODE *head;
    pthread_mutex_t mutex;
    size_t capacity; // Preallocated memory
    bool preallocate_memory;
} MAC_EVENT_LIST;

MAC_EVENT_LIST* initialize_mac_event_list(bool preallocate, size_t expected_frame_count) {
    MAC_EVENT_LIST *list = malloc(sizeof(MAC_EVENT_LIST));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->capacity = 0;
    list->preallocate_memory = preallocate;

    if (preallocate) {
        // Preallocation logic
        list->capacity = expected_frame_count * sizeof(MAC_FRAME_DATA); 
    }

    return list;
}

bool validate_mac_frame_data(const MAC_FRAME_DATA *frame_data) {
    // Implement frame data validation here.
    // Return false if invalid, true otherwise.
    return frame_data != NULL && frame_data->length > 0 && frame_data->data != NULL;
}

int add_mac_frame(MAC_EVENT_LIST *list, const MAC_EVENT_HEADER *header, const MAC_FRAME_DATA *frames, size_t count) {
    pthread_mutex_lock(&list->mutex);

    // Check for buffer overflow conditions
    if (list->capacity < count * sizeof(MAC_FRAME_DATA)) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Error: Buffer Overflow
    }

    MAC_EVENT_NODE *node = malloc(sizeof(MAC_EVENT_NODE));
    if (!node) {
        pthread_mutex_unlock(&list->mutex);
        return -2; // Error: Memory Allocation Failed
    }

    node->header = *header;
    node->frames = malloc(count * sizeof(MAC_FRAME_DATA));
    if (!node->frames) {
        free(node);
        pthread_mutex_unlock(&list->mutex);
        return -3; // Error: Frame Data Memory Allocation Failed
    }

    node->frame_count = 0;

    for (size_t i = 0; i < count; ++i) {
        if (!validate_mac_frame_data(&frames[i])) {
            free(node->frames); 
            free(node);
            pthread_mutex_unlock(&list->mutex);
            return -4; // Error: Invalid Frame Data
        }
        memcpy(&(node->frames[node->frame_count]), &frames[i], sizeof(MAC_FRAME_DATA));
        node->frame_count++;
    }

    node->next = list->head;
    list->head = node;

    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

