```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define KEY_RANGE 1000
#define PACKET_HEADER_SIZE sizeof(struct PacketHeader)
#define MAX_THREADS 10

typedef struct PacketHeader {
    int source;
    int destination;
    char data[64];
} PacketHeader;

typedef struct Edge {
    struct PacketHeader *packet;
    struct Edge *next;
} Edge;

typedef struct Node {
    int key;
    struct Node *left, *right;
    struct Edge *edges;
} Node;

pthread_mutex_t bst_lock = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
Node* insert(Node* node, int key);
void balanceTree(Node** root);
void freeBST(Node* node);
int compareKeys(int a, int b);

// Initialize and populate the tree with random packet headers
Node* initAndPopulateTree(int numNodes) {
    Node *root = NULL;
    srand(time(NULL));

    for (int i = 0; i < numNodes; ++i) {
        int key = rand() % KEY_RANGE;

        // Allocate memory for a new packet header
        PacketHeader *packetHeader = malloc(PACKET_HEADER_SIZE);
        if (!packetHeader) {
            freeBST(root);
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }

        // Randomly fill the packet header data
        packetHeader->source = rand() % 256;
        packetHeader->destination = rand() % 256;

        // Insert into BST
        pthread_mutex_lock(&bst_lock);
        root = insert(root, key);

        // Add packet to the node's edge list
        Edge *edge = malloc(sizeof(Edge));
        if (!edge) {
            free(packetHeader);
            freeBST(root);
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }
        edge->packet = packetHeader;
        edge->next = root ? root->edges : NULL;
        if (root) root->edges = edge;

        pthread_mutex_unlock(&bst_lock);

        // Balance the tree after insertion
        balanceTree(&root);
    }

    return root;
}

Node* insert(Node *node, int key) {
    if (!node) {
        Node *newNode = malloc(sizeof(Node));
        if (!newNode) return NULL;

        newNode->key = key;
        newNode->left = newNode->right = NULL;
        newNode->edges = NULL;
        return newNode;
    }

    if (compareKeys(key, node->key) < 0)
        node->left = insert(node->left, key);
    else if (compareKeys(key, node->key) > 0)
        node->right = insert(node->right, key);

    // Return the unchanged node pointer if no insertion occurred
    return node;
}

void balanceTree(Node** root) {
    // Implement balancing logic such as AVL rotations here
    // Placeholder for actual balancing code
}

int compareKeys(int a, int b) {
    return (a > b) - (a < b);
}

// Free the entire BST and its associated packets and edges
void freeBST(Node* node) {
    if (!node) return;

    freeBST(node->left);
    freeBST(node->right);

    Edge *edge = node->edges;
    while (edge) {
        Edge *temp = edge;
        edge = edge->next;
        free(temp->packet);
        free(temp);
    }

    free(node);
}

int main() {
    int numNodes = 1000; // Example number of nodes to populate
    Node* root = initAndPopulateTree(numNodes);

    if (root) {
        printf("BST with packet headers initialized.\n");
        freeBST(root); // Clean up resources
    }

    return 0;
}
```

