#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

// Define the structure
typedef struct NetworkPerformanceMetrics {
    uint32_t cellId;
    time_t timeStamp;
    double throughput;
    struct NetworkPerformanceMetrics *next;
} NetworkPerformanceMetrics;

// Node for a linked list
typedef struct {
    NetworkPerformanceMetrics *head;
    pthread_mutex_t lock;
    size_t count;
} MetricsList;

// Initialize the metrics list
int initMetricsList(MetricsList *list, uint32_t seed) {
    if (!list)
        return -1; // Error: NULL pointer

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;

    srand(seed);

    return 0; // Success
}

// Generate a random throughput value within the range [min, max]
double generateRandomThroughput(double min, double max) {
    if (max <= min)
        return min;

    return min + ((double)rand() / RAND_MAX * (max - min));
}

// Insert a new metric into the list
int insertMetric(MetricsList *list, uint32_t cellId, time_t timeStamp, double throughput) {
    if (!list || !throughput)
        return -1; // Error: NULL pointer or invalid throughput

    NetworkPerformanceMetrics *newNode = malloc(sizeof(NetworkPerformanceMetrics));
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed\n");
        return -2; // Error: Memory allocation failure
    }

    newNode->cellId = cellId;
    newNode->timeStamp = timeStamp;
    newNode->throughput = throughput;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);

    // Insert at the beginning for efficiency
    newNode->next = list->head;
    list->head = newNode;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

// Calculate moving average throughput of last N entries
double calculateMovingAverage(MetricsList *list, size_t N) {
    if (!list || N == 0)
        return 0.0;

    pthread_mutex_lock(&list->lock);

    NetworkPerformanceMetrics *current = list->head;
    double sum = 0.0;
    size_t count = 0;

    while (current && count < N) {
        sum += current->throughput;
        current = current->next;
        count++;
    }

    pthread_mutex_unlock(&list->lock);

    return count > 0 ? sum / count : 0.0;
}

// Free the list
void freeMetricsList(MetricsList *list) {
    if (!list)
        return;

    NetworkPerformanceMetrics *current = list->head;
    NetworkPerformanceMetrics *next;

    pthread_mutex_lock(&list->lock);

    while (current) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    MetricsList list;
    if (initMetricsList(&list, 42) != 0) { // Initialize with a seed
        fprintf(stderr, "Failed to initialize metrics list\n");
        return -1;
    }

    for (uint32_t i = 0; i < 100; ++i) {
        time_t timeStamp = time(NULL);
        double throughput = generateRandomThroughput(10.0, 100.0);

        if (insertMetric(&list, i, timeStamp, throughput) != 0) {
            fprintf(stderr, "Failed to insert metric\n");
            freeMetricsList(&list);
            return -1;
        }
    }

    printf("Moving average of last 10 metrics: %.2f\n", calculateMovingAverage(&list, 10));

    freeMetricsList(&list);

    return 0;
}
```

This code demonstrates a thread-safe implementation for managing `NetworkPerformanceMetrics` in a linked list. It includes random throughput generation, moving average calculation over the last N entries, and ensures proper memory management with logging on failures. The structure is designed to accommodate concurrent access efficiently by using mutex locks.']

