class MemoryPool {
public:
    MemoryPool(size_t size) : poolSize_(size), usage_(0) {
        // Initialize memory pool
    }

    void* allocate(size_t size) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (usage_ + size > poolSize_) throw std::bad_alloc();
        void* ptr = std::malloc(size);
        usage_ += size;
        return ptr;
    }

    void deallocate(void* ptr, size_t size) {
        std::lock_guard<std::mutex> lock(mutex_);
        std::free(ptr);
        usage_ -= size;
    }

    size_t currentUsage() const { return usage_; }
    size_t peakUsage() const { return peakUsage_; }

private:
    mutable std::mutex mutex_;
    size_t poolSize_;
    size_t usage_;
    size_t peakUsage_ = 0;

public:
    void updatePeakUsage(size_t current) {
        if (current > peakUsage_) {
            peakUsage_ = current;
        }
    }
};

typedef boost::adjacency_list<boost::vecS, boost::vecS, boost::undirectedS> Graph;

class NetworkGraphManager {
public:
    NetworkGraphManager(size_t maxEvents, size_t maxFrameSize, size_t poolSize)
        : maxAllowedEvents_(maxEvents), maxFrameSize_(maxFrameSize),
          memoryPool_(std::make_shared<MemoryPool>(poolSize)) {}

    void addNetworkEvent(const NETWORK_EVENT& event) {
        std::lock_guard<std::mutex> lock(mutex_);

        if (events_.size() >= maxAllowedEvents_) {
            logError("Max events limit reached");
            return;
        }

        // Add vertex
        Graph::vertex_descriptor v = boost::add_vertex(graph_);
        vertices_[v] = event;

        // Add edges based on frame data
        for (const auto& frame : event.frameData) {
            if (frame.data.size() > maxFrameSize_) {
                logError("Frame size exceeds limit");
                continue;
            }
            Graph::vertex_descriptor u = boost::add_vertex(graph_);
            vertices_[u] = NETWORK_EVENT{0, {}, {}};
            boost::add_edge(v, u, graph_);
        }

        logSuccess();
    }

    void configure(size_t maxEvents, size_t maxFrameSize, size_t poolSize) {
        std::lock_guard<std::mutex> lock(mutex_);
        maxAllowedEvents_ = maxEvents;
        maxFrameSize_ = maxFrameSize;
        memoryPool_->updatePeakUsage(memoryPool_->currentUsage());
        // Reconfigure if necessary
    }

private:
    void logSuccess() {
        std::lock_guard<std::mutex> lock(logMutex_);
        ++successCount_;
        logMessage("Event added successfully");
    }

    void logError(const std::string& message) {
        std::lock_guard<std::mutex> lock(logMutex_);
        ++errorCount_;
        logMessage(message);
    }

    void logMessage(const std::string& message) const {
        // Simulate logging to file or console
        std::ofstream logFile("log.txt", std::ios_base::app);
        if (logFile.is_open()) {
            logFile << "[" << std::chrono::system_clock::now().time_since_epoch().count() << "] " << message << '\n';
            logFile.close();
        } else {
            std::cerr << "Logging failed\n";
        }
    }

private:
    Graph graph_;
    std::unordered_map<Graph::vertex_descriptor, NETWORK_EVENT> vertices_;
    size_t maxAllowedEvents_;
    size_t maxFrameSize_;

    std::shared_ptr<MemoryPool> memoryPool_;
    mutable boost::mutex mutex_;

    size_t successCount_ = 0;
    size_t errorCount_ = 0;

    mutable std::mutex logMutex_;
};

// Example usage
int main() {
    NetworkGraphManager manager(100, 1024, 1048576); // Configurable parameters

    NETWORK_EVENT event = {1, std::chrono::system_clock::now(), {{1, "data1"}, {2, "data2"}}};
    manager.addNetworkEvent(event);

    return 0;
}
