    PGconn* pgConnections[2]; // Support for two PostgreSQL instances
    std::shared_mutex cacheMutex;
    std::unordered_map<int, Record> cache;

public:
    DynamicDataProcessor() {
        if (sqlite3_open("local.db", &localDb) != SQLITE_OK) {
            throw std::runtime_error("Failed to open local SQLite database.");
        }

        // Initialize PostgreSQL connections
        char* conninfo = "host=localhost dbname=test user=postgres password=password";
        pgConnections[0] = PQconnectdb(conninfo);
        if (PQstatus(pgConnections[0]) != CONNECTION_OK) {
            throw std::runtime_error("Failed to connect to PostgreSQL instance 1.");
        }

        conninfo = "host=remotehost dbname=test user=postgres password=password";
        pgConnections[1] = PQconnectdb(conninfo);
        if (PQstatus(pgConnections[1]) != CONNECTION_OK) {
            throw std::runtime_error("Failed to connect to PostgreSQL instance 2.");
        }
    }

    ~DynamicDataProcessor() {
        sqlite3_close(localDb);

        for (int i = 0; i < 2; ++i) {
            PQfinish(pgConnections[i]);
        }
    }

    void fetchDataFromSQLite(const std::string& query) {
        char* errMsg;
        int rc = sqlite3_exec(localDb, query.c_str(), [](void*, int argc, char** argv, char**) -> int {
            for (int i = 0; i < argc; ++i) {
                std::cout << "Column " << i << ": " << (argv[i] ? argv[i] : "NULL") << "\n";
            }
            return 0;
        }, nullptr, &errMsg);

        if (rc != SQLITE_OK) {
            std::cerr << "SQLite error: " << errMsg << std::endl;
            sqlite3_free(errMsg);
        }
    }

    void fetchDataFromPostgreSQL(const std::string& query) {
        for (int i = 0; i < 2; ++i) {
            if (PQstatus(pgConnections[i]) == CONNECTION_OK) {
                PGresult* res = PQexec(pgConnections[i], query.c_str());
                if (PQresultStatus(res) != PGRES_TUPLES_OK) {
                    std::cerr << "PostgreSQL error: " << PQerrorMessage(pgConnections[i]) << std::endl;
                } else {
                    // Process result
                    for (int j = 0; j < PQntuples(res); ++j) {
                        std::cout << "Row " << j << ": " << PQgetvalue(res, j, 0) << "\n";
                    }
                }
                PQclear(res);
            }
        }
    }

    void processData(const Record& record) {
        // Implement adaptive parsing and data processing logic
    }

    void processInParallel(std::vector<Record>& records) {
        std::vector<std::thread> threads;
        for (auto& record : records) {
            threads.emplace_back(&DynamicDataProcessor::processData, this, std::ref(record));
        }

        for (auto& thread : threads) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void cacheRecord(int key, const Record& record) {
        std::unique_lock lock(cacheMutex);
        cache[key] = record;
    }

    Record getFromCache(int key) {
        std::shared_lock lock(cacheMutex);
        auto it = cache.find(key);
        if (it != cache.end()) {
            return it->second;
        }
        return {}; // Return empty record if not found
    }

    void monitorPerformance() {
        // Implement performance monitoring and alerting logic.
    }
};

int main() {
    DynamicDataProcessor processor;

    std::vector<Record> records = {
        {1, 100, {{"field1", "value1"}, {"field2", "value2"}}},
        {2, 101, {{"field3", "value3"}, {"field4", "value4"}}}
    };

    processor.processInParallel(records);

    // Fetch data example
    processor.fetchDataFromSQLite("SELECT * FROM my_table;");
    processor.fetchDataFromPostgreSQL("SELECT * FROM my_table;");

    return 0;
}
