#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int cellId;
    long timeStamp;
    float throughput;
    float movingAverage;
} NetworkPerformanceMetrics;

typedef struct {
    NetworkPerformanceMetrics *metricsArray;
    size_t capacity;
    size_t currentSize;
    pthread_mutex_t lock;
    size_t windowSize; // Default is 10, can be dynamically changed
    int minWindowSize;
    int maxWindowSize;
} NetworkMetricsManager;

void initializeNetworkMetrics(NetworkMetricsManager *manager,
                             size_t numEntries,
                             int minWindowSize,
                             int maxWindowSize) {

    pthread_mutex_init(&manager->lock, NULL);
    manager->minWindowSize = minWindowSize;
    manager->maxWindowSize = maxWindowSize;
    manager->windowSize = 10; // Default window size
    manager->capacity = numEntries > 0 ? numEntries : 10000;
    manager->currentSize = 0;

    manager->metricsArray = (NetworkPerformanceMetrics *)malloc(manager->capacity * sizeof(NetworkPerformanceMetrics));
    if (!manager->metricsArray) {
        perror("Failed to allocate memory for metrics array");
        pthread_mutex_destroy(&manager->lock);
        return;
    }

    // Initialize with simulated data
    for (size_t i = 0; i < manager->capacity; ++i) {
        manager->metricsArray[i].cellId = rand() % 1000; // Simulated unique cell ID
        manager->metricsArray[i].timeStamp = time(NULL); // Current timestamp
        manager->metricsArray[i].throughput = (float)(rand() % 100 + 1); // Random throughput value
        manager->metricsArray[i].movingAverage = 0.0f;
    }
}

void updateWindowSettings(NetworkMetricsManager *manager, size_t newSize) {
    pthread_mutex_lock(&manager->lock);

    if (newSize >= manager->minWindowSize && newSize <= manager->maxWindowSize) {
        manager->windowSize = newSize;

        for (size_t i = 0; i < manager->currentSize; ++i) {
            size_t windowStartIndex = i >= manager->windowSize ? i - manager->windowSize : 0;
            float sum = 0.0f;
            size_t count = 0;

            for (size_t j = windowStartIndex; j <= i && j < manager->currentSize; ++j) {
                sum += manager->metricsArray[j].throughput;
                count++;
            }
            manager->metricsArray[i].movingAverage = count > 0 ? sum / count : 0.0f;
        }
    } else {
        fprintf(stderr, "Invalid window size: %zu\n", newSize);
    }

    pthread_mutex_unlock(&manager->lock);
}

void addOrUpdateMetric(NetworkMetricsManager *manager,
                       int cellId,
                       long timeStamp,
                       float throughput) {
    pthread_mutex_lock(&manager->lock);

    // Find existing metric or create a new one
    NetworkPerformanceMetrics *metric = NULL;
    for (size_t i = 0; i < manager->currentSize; ++i) {
        if (manager->metricsArray[i].cellId == cellId) {
            metric = &manager->metricsArray[i];
            break;
        }
    }

    if (!metric && manager->currentSize < manager->capacity) {
        metric = &manager->metricsArray[manager->currentSize++];
    }

    if (metric) {
        metric->cellId = cellId;
        metric->timeStamp = timeStamp;
        metric->throughput = throughput;

        size_t windowStartIndex = manager->currentSize > manager->windowSize ? manager->currentSize - manager->windowSize : 0;
        float sum = 0.0f;
        size_t count = 0;

        for (size_t j = windowStartIndex; j < manager->currentSize && j < manager->capacity; ++j) {
            sum += manager->metricsArray[j].throughput;
            count++;
        }

        metric->movingAverage = count > 0 ? sum / count : 0.0f;
    }

    pthread_mutex_unlock(&manager->lock);
}

void cleanupNetworkMetrics(NetworkMetricsManager *manager) {
    if (manager->metricsArray) {
        free(manager->metricsArray);
    }
    pthread_mutex_destroy(&manager->lock);
}
