// Memory pool for reusing allocations
typedef struct {
    size_t block_size;
    void *blocks[MAX_EVENTS];
    int num_blocks;
} memory_pool;

pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

memory_pool event_pool = { sizeof(event), {0}, 0 };

void initialize_memory_pool() {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < MAX_EVENTS; ++i) {
        event_pool.blocks[i] = malloc(sizeof(event));
    }
    event_pool.num_blocks = MAX_EVENTS;
    pthread_mutex_unlock(&pool_lock);
}

event* allocate_event_from_pool() {
    pthread_mutex_lock(&pool_lock);
    if (event_pool.num_blocks > 0) {
        event *e = (event*)event_pool.blocks[--event_pool.num_blocks];
        pthread_mutex_unlock(&pool_lock);
        return e;
    }
    pthread_mutex_unlock(&pool_lock);
    return malloc(sizeof(event));
}

void release_memory_pool() {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < MAX_EVENTS; ++i) {
        if (event_pool.blocks[i]) {
            free(event_pool.blocks[i]);
        }
    }
    event_pool.num_blocks = 0;
    pthread_mutex_unlock(&pool_lock);
}

