typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG:1;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct record {
    int value;
    struct record* next;
} record_t;

// Task structure for conversion tasks
typedef struct task {
    char input_path[256];
    char output_path[256];
    void (*callback)(int);
    time_t creation_time;
    struct task* next;
} task_t;

// Global variables and mutexes
pthread_mutex_t queue_mutex = PTHREAD_MUTEX_INITIALIZER;
task_t* task_queue = NULL;
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

// Configuration parameters
typedef struct {
    int max_concurrent_tasks;
    char default_output_dir[256];
    int logging_level;
} config_t;

config_t config;

// Function prototypes
void* nfaapiImageConverter(void *arg);
void processTask(task_t* task);
task_t* createTask(const char* input_path, const char* output_path, void (*callback)(int));
void addTaskToQueue(task_t* task);
void* workerThread(void *arg);
void releaseAllResources();
void logStatus(const char* status);

// Helper functions
record_t* createLinkedList(int size, int min_val, int max_val) {
    record_t* head = NULL;
    for (int i = 0; i < size; ++i) {
        record_t* new_record = malloc(sizeof(record_t));
        if (!new_record) return NULL;
        new_record->value = rand() % (max_val - min_val + 1) + min_val;
        new_record->next = head;
        head = new_record;
    }
    return head;
}

void sortLinkedList(record_t* head) {
    if (!head || !head->next) return;
    record_t *i, *j;
    int temp;

    for (i = head; i != NULL; i = i->next) {
        for (j = i->next; j != NULL; j = j->next) {
            if (i->value > j->value) {
                temp = i->value;
                i->value = j->value;
                j->value = temp;
            }
        }
    }
}

void* nfaapiImageConverter(void *arg) {
    config_t local_config;
    parseConfig("config_file.cfg", &local_config);

    // Set global configuration
    pthread_mutex_lock(&queue_mutex);
    memcpy(&config, &local_config, sizeof(config));
    pthread_mutex_unlock(&queue_mutex);

    int num_threads = config.max_concurrent_tasks;
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, workerThread, NULL);
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    return NULL;
}

void* workerThread(void *arg) {
    while (1) {
        task_t* task = NULL;

        pthread_mutex_lock(&queue_mutex);
        if (task_queue != NULL) {
            task = task_queue;
            task_queue = task->next;
        }
        pthread_mutex_unlock(&queue_mutex);

        if (task) {
            processTask(task);
            free(task);
        } else {
            break; // Exit thread when no tasks are left
        }
    }

    return NULL;
}

void processTask(task_t* task) {
    logStatus("Task started");

    // Simulate image conversion using external library
    if (!externalImageConvert(task->input_path, task->output_path)) {
        logStatus("Error during processing");
        return;
    }

    // Validate output file
    if (!validateOutputFile(task->output_path)) {
        logStatus("Validation failed");
        return;
    }

    logStatus("Task completed");

    // Call callback function if provided
    if (task->callback) {
        task->callback(0); // Assuming 0 indicates success
    }
}

task_t* createTask(const char* input_path, const char* output_path, void (*callback)(int)) {
    task_t* new_task = malloc(sizeof(task_t));
    if (!new_task) return NULL;

    strncpy(new_task->input_path, input_path, sizeof(new_task->input_path) - 1);
    strncpy(new_task->output_path, output_path, sizeof(new_task->output_path) - 1);
    new_task->callback = callback;
    new_task->creation_time = time(NULL);
    new_task->next = NULL;

    return new_task;
}

void addTaskToQueue(task_t* task) {
    pthread_mutex_lock(&queue_mutex);

    if (!task_queue || task->creation_time < task_queue->creation_time) {
        task->next = task_queue;
        task_queue = task;
    } else {
        task_t* current = task_queue;
        while (current->next && current->next->creation_time < task->creation_time) {
            current = current->next;
        }
        task->next = current->next;
        current->next = task;
    }

    pthread_mutex_unlock(&queue_mutex);
}

void releaseAllResources() {
    pthread_mutex_lock(&queue_mutex);
    task_t* current = task_queue;
    while (current) {
        task_t* next = current->next;
        free(current);
        current = next;
    }
    task_queue = NULL;
    pthread_mutex_unlock(&queue_mutex);

    // Release other resources if needed
}

void logStatus(const char* status) {
    pthread_mutex_lock(&log_mutex);
    FILE* log_file = fopen("conversion.log", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", status);
        fclose(log_file);
    }
    pthread_mutex_unlock(&log_mutex);
}

int main() {
    // Example usage
    pthread_t nfaapi_thread;
    pthread_create(&nfaapi_thread, NULL, nfaapiImageConverter, NULL);
    pthread_join(nfaapi_thread, NULL);

    return 0;
}
