#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_TIMESTAMP 2147483647L
#define MIN_TIMESTAMP 0L
#define TIMESTAMP_FORMAT "%%Y-%%m-%%d %%H:%%M:%%S"
#define SESSION_ID_LEN 16
#define USERNAME_LEN 32
#define MESSAGE_LEN 256

typedef struct {
    long timestamp;
    char message[MESSAGE_LEN];
    char session_id[SESSION_ID_LEN];
} log_t;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t count;
    size_t head;
    size_t tail;
    log_t *logs;
} circular_buffer_t;

circular_buffer_t* create_circular_buffer(size_t capacity) {
    circular_buffer_t *cb = malloc(sizeof(circular_buffer_t));
    if (!cb) return NULL;

    pthread_mutex_init(&cb->lock, NULL);
    cb->capacity = capacity;
    cb->count = 0;
    cb->head = 0;
    cb->tail = 0;
    cb->logs = malloc(capacity * sizeof(log_t));
    if (!cb->logs) {
        free(cb);
        return NULL;
    }

    return cb;
}

void destroy_circular_buffer(circular_buffer_t *cb) {
    pthread_mutex_destroy(&cb->lock);
    free(cb->logs);
    free(cb);
}

int is_valid_timestamp(long timestamp) {
    struct tm tm;
    char str[100];
    snprintf(str, sizeof(str), "%ld", timestamp);
    if (strptime(str, TIMESTAMP_FORMAT, &tm) == NULL || difftime(mktime(&tm), timestamp) != 0) {
        return 0;
    }
    return timestamp >= MIN_TIMESTAMP && timestamp <= MAX_TIMESTAMP;
}

int add_log_entry(circular_buffer_t *cb, long timestamp, const char *username, const char *message, const char *session_id) {
    pthread_mutex_lock(&cb->lock);

    if (!is_valid_timestamp(timestamp)) {
        fprintf(stderr, "Invalid timestamp: %ld\n", timestamp);
        pthread_mutex_unlock(&cb->lock);
        return -1;
    }

    if (cb->count == cb->capacity) {
        // Drop the oldest entry
        cb->tail = (cb->tail + 1) % cb->capacity;
        cb->head = (cb->head + 1) % cb->capacity;
        cb->count--;
    } else {
        cb->count++;
    }

    log_t *log_entry = &cb->logs[cb->head];
    log_entry->timestamp = timestamp;
    strncpy(log_entry->message, message, MESSAGE_LEN - 1);
    log_entry->message[MESSAGE_LEN - 1] = '\0';
    strncpy(log_entry->session_id, session_id, SESSION_ID_LEN - 1);
    log_entry->session_id[SESSION_ID_LEN - 1] = '\0';

    cb->head = (cb->head + 1) % cb->capacity;

    pthread_mutex_unlock(&cb->lock);
    return 0;
}

void* flush_logs_to_storage(void *arg) {
    circular_buffer_t *cb = (circular_buffer_t *)arg;
    while (1) {
        // Simulate flushing to storage
        printf("Flushing logs...\n");
        sleep(10); // Adjust as needed
    }
    return NULL;
}

void* monitor_performance(void *arg) {
    size_t processed_logs = 0;
    time_t start_time = time(NULL);

    while (1) {
        if (difftime(time(NULL), start_time) >= 1.0) {
            printf("Processed %zu logs per second\n", processed_logs);
            processed_logs = 0;
            start_time = time(NULL);
        }
        sleep(1); // Adjust as needed
    }
}

void* adjust_buffer_size(void *arg) {
    circular_buffer_t *cb = (circular_buffer_t *)arg;

    while (1) {
        // Simulate buffer size adjustment based on usage patterns
        printf("Adjusting buffer size...\n");
        sleep(60); // Adjust as needed
    }
}

void process_log_entries(size_t num_entries, size_t system_limit) {
    circular_buffer_t *cb = create_circular_buffer(system_limit);
    if (!cb) {
        fprintf(stderr, "Failed to create circular buffer\n");
        return;
    }

    pthread_t flush_thread, monitor_thread, adjust_thread;

    pthread_create(&flush_thread, NULL, flush_logs_to_storage, cb);
    pthread_create(&monitor_thread, NULL, monitor_performance, NULL);
    pthread_create(&adjust_thread, NULL, adjust_buffer_size, cb);

    for (size_t i = 0; i < num_entries; ++i) {
        long timestamp = rand() % (MAX_TIMESTAMP - MIN_TIMESTAMP + 1) + MIN_TIMESTAMP;
        char username[USERNAME_LEN] = "user";
        snprintf(username, USERNAME_LEN, "user%d", i);
        char message[MESSAGE_LEN] = "Log message";
        snprintf(message, MESSAGE_LEN, "Message %zu", i);
        char session_id[SESSION_ID_LEN];
        snprintf(session_id, SESSION_ID_LEN, "%016lx", (unsigned long)timestamp);

        add_log_entry(cb, timestamp, username, message, session_id);
    }

    pthread_join(flush_thread, NULL);
    pthread_join(monitor_thread, NULL);
    pthread_join(adjust_thread, NULL);

    destroy_circular_buffer(cb);
}

int main() {
    size_t num_entries = 1000;
    size_t system_limit = 500;

    process_log_entries(num_entries, system_limit);

    return 0;
}
