#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>

typedef struct {
    uint64_t tag; // MAC_EVENT_TAG
    time_t timestamp;
} NetworkEventHeader;

typedef struct {
    uint8_t data[256]; // Example fixed size for a frame
} MAC_FRAME_DATA;

typedef struct FrameNode {
    MAC_FRAME_DATA *frame_data;
    struct FrameNode *next;
} FrameNode;

typedef struct {
    NetworkEventHeader header;
    FrameNode *frames; // Linked list of frames
} NetworkEvent;

typedef struct {
    NetworkEvent *events;
    size_t count;
    pthread_mutex_t lock;
} EventList;

#define FRAME_DATA_SIZE 256

void init_event_list(EventList *list) {
    list->events = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

NetworkEvent* create_network_event(uint64_t tag, time_t timestamp) {
    NetworkEvent *event = malloc(sizeof(NetworkEvent));
    if (!event) return NULL;

    event->header.tag = tag;
    event->header.timestamp = timestamp;
    event->frames = NULL;

    return event;
}

FrameNode* create_frame_node(const uint8_t *data, size_t length) {
    if (length > FRAME_DATA_SIZE) {
        fprintf(stderr, "Error: Frame data exceeds maximum allowed size.\n");
        return NULL;
    }

    MAC_FRAME_DATA *frame_data = malloc(sizeof(MAC_FRAME_DATA));
    if (!frame_data) {
        fprintf(stderr, "Memory allocation failed for frame data.\n");
        return NULL;
    }

    memcpy(frame_data->data, data, length);
    FrameNode *node = malloc(sizeof(FrameNode));
    if (!node) {
        free(frame_data);
        fprintf(stderr, "Memory allocation failed for frame node.\n");
        return NULL;
    }

    node->frame_data = frame_data;
    node->next = NULL;

    return node;
}

void add_frame_to_event(NetworkEvent *event, const uint8_t *data, size_t length) {
    FrameNode *node = create_frame_node(data, length);
    if (!node) return;

    node->next = event->frames;
    event->frames = node;
}

void free_frames(FrameNode *head) {
    while (head) {
        FrameNode *temp = head;
        head = head->next;
        free(temp->frame_data);
        free(temp);
    }
}

void delete_network_event(NetworkEvent **event) {
    if (!event || !*event) return;

    free_frames((*event)->frames);
    free(*event);
    *event = NULL;
}

int add_event(EventList *list, NetworkEvent *event) {
    pthread_mutex_lock(&list->lock);

    if (!event) {
        fprintf(stderr, "Error: Attempt to add a null event.\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    // Resize the events array
    size_t new_count = list->count + 1;
    NetworkEvent **new_events = realloc(list->events, sizeof(NetworkEvent*) * new_count);
    if (!new_events) {
        fprintf(stderr, "Memory allocation failed when adding event.\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    list->events = new_events;
    list->events[list->count] = event;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

NetworkEvent* get_event(const EventList *list, size_t index) {
    if (index >= list->count) {
        fprintf(stderr, "Error: Index out of bounds when accessing events.\n");
        return NULL;
    }

    return list->events[index];
}

void delete_all_events(EventList *list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        delete_network_event(&list->events[i]);
    }

    free(list->events);
    list->events = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
}

void destroy_event_list(EventList *list) {
    if (!list) return;

    delete_all_events(list);
    pthread_mutex_destroy(&list->lock);
}
