#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define ERROR_CODE -1

typedef struct {
    int value;
} record;

void free_memory(long *offsets, int *keys, record *records);
int populate_records_with_random_values(record *records, size_t count, int min_val, int max_val);

int initialize_and_sort(size_t offset_count, size_t key_count, size_t record_count, 
                        long (*offsets)[], int (*keys)[], record **records) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    *offsets = (long *)malloc(offset_count * sizeof(long));
    *keys = (int *)malloc(key_count * sizeof(int));
    *records = (record *)malloc(record_count * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        pthread_mutex_destroy(&lock);
        free_memory(*offsets, *keys, *records);
        return ERROR_CODE;
    }

    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < offset_count; ++i) {
        (*offsets)[i] = rand() % 100000; // Initialize with a random long value
    }

    for (size_t i = 0; i < key_count; ++i) {
        (*keys)[i] = rand() % 1000; // Initialize with a random int key
    }

    if (populate_records_with_random_values(*records, record_count, 1, 100)) {
        pthread_mutex_unlock(&lock);
        pthread_mutex_destroy(&lock);
        free_memory(*offsets, *keys, *records);
        return ERROR_CODE;
    }

    // Sort records based on keys
    for (size_t i = 0; i < record_count - 1; ++i) {
        size_t min_idx = i;
        for (size_t j = i + 1; j < record_count; ++j) {
            if ((*keys)[min_idx] > (*keys)[j]) {
                min_idx = j;
            }
        }

        if (min_idx != i) {
            int key_temp = (*keys)[i];
            (*keys)[i] = (*keys)[min_idx];
            (*keys)[min_idx] = key_temp;

            record rec_temp = (*records)[i];
            (*records)[i] = (*records)[min_idx];
            (*records)[min_idx] = rec_temp;
        }
    }

    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);

    return 0; // Success
}

void free_memory(long *offsets, int *keys, record *records) {
    if (offsets != NULL) free(offsets);
    if (keys != NULL) free(keys);
    if (records != NULL) free(records);
}

int populate_records_with_random_values(record *records, size_t count, int min_val, int max_val) {
    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
    }
    return 0; // Success
}

char* process_string(const char *input, size_t size_limit) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    pthread_mutex_lock(&lock);

    if (strlen(input) >= size_limit) {
        pthread_mutex_unlock(&lock);
        pthread_mutex_destroy(&lock);
        return NULL; // Input string exceeds the limit
    }

    char *result = (char *)malloc((size_limit + 2) * sizeof(char)); // Allocate space for new string and slash

    if (result == NULL) {
        pthread_mutex_unlock(&lock);
        pthread_mutex_destroy(&lock);
        return NULL;
    }

    strcpy(result, input);
    strcat(result, "/");

    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);

    return result;
}

// Example usage:
int main() {
    size_t offset_count = 10, key_count = 5, record_count = 5;
    long *offsets;
    int *keys;
    record *records;

    if (initialize_and_sort(offset_count, key_count, record_count, &offsets, &keys, &records) == ERROR_CODE) {
        printf("Memory allocation failed.\n");
        return EXIT_FAILURE;
    }

    // Process strings
    const char *input_string = "test";
    size_t size_limit = 10;

    char *processed_string = process_string(input_string, size_limit);
    if (processed_string != NULL) {
        printf("Processed string: %s\n", processed_string);
        free(processed_string);
    } else {
        printf("String exceeds the specified limit.\n");
    }

    // Free allocated memory
    free_memory(offsets, keys, records);

    return EXIT_SUCCESS;
}
