#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the point structure
typedef struct {
    double x;
    double y;
} Point;

// Node for Binary Search Tree
typedef struct BSTNode {
    Point data;
    struct BSTNode *left, *right;
} BSTNode;

// Function prototypes
BSTNode* insertPoint(BSTNode* root, Point newPoint);
void deleteTree(BSTNode* node);
void updateCoordinates(Point* point, double xRangeMin, double xRangeMax, double yRangeMin, double yRangeMaxY);
void* parallelUpdate(void* args);

// Thread-safe lock for concurrent updates
pthread_mutex_t bstMutex = PTHREAD_MUTEX_INITIALIZER;

BSTNode* insertPoint(BSTNode* root, Point newPoint) {
    if (root == NULL) {
        BSTNode* newNode = malloc(sizeof(BSTNode));
        if (!newNode) return NULL;
        newNode->data = newPoint;
        newNode->left = newNode->right = NULL;
        return newNode;
    }

    if ((newPoint.x < root->data.x) || 
       (newPoint.x == root->data.x && newPoint.y <= root->data.y)) {
        BSTNode* leftChild = insertPoint(root->left, newPoint);
        if (!leftChild) return NULL; // Allocation failed
        root->left = leftChild;
    } else {
        BSTNode* rightChild = insertPoint(root->right, newPoint);
        if (!rightChild) return NULL; // Allocation failed
        root->right = rightChild;
    }

    return root;
}

void deleteTree(BSTNode* node) {
    if (node != NULL) {
        deleteTree(node->left);
        deleteTree(node->right);
        free(node);
    }
}

void updateCoordinates(Point* point, double xRangeMin, double xRangeMax, double yRangeMin, double yRangeMaxY) {
    point->x = xRangeMin + ((double) rand() / RAND_MAX) * (xRangeMax - xRangeMin);
    point->y = yRangeMin + ((double) rand() / RAND_MAX) * (yRangeMaxY - yRangeMin);
}

// Structure to hold batch update data
typedef struct {
    Point* points;
    size_t count;
} BatchUpdateData;

void* parallelUpdate(void* args) {
    BatchUpdateData* batch = (BatchUpdateData*) args;

    for (size_t i = 0; i < batch->count; ++i) {
        updateCoordinates(&batch->points[i], -100.0, 100.0, -100.0, 100.0);

        pthread_mutex_lock(&bstMutex);
        insertPoint(batch->root, batch->points[i]);
        pthread_mutex_unlock(&bstMutex);
    }

    return NULL;
}

void initializeAndProcessData(size_t numFloats, size_t numStrings, size_t numPoints) {
    float* floats = malloc(numFloats * sizeof(float));
    char** strings = malloc(numStrings * sizeof(char*));
    Point* points = malloc(numPoints * sizeof(Point));

    if (!floats || !strings || !points) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(floats); free(strings); free(points);
        return;
    }

    // Initialize float array with random values
    for (size_t i = 0; i < numFloats; ++i) {
        floats[i] = ((float) rand() / RAND_MAX) * 100.0f;
    }

    // Initialize strings with sample text
    const char* sampleText[] = {"example1", "example2", "example3"};
    for (size_t i = 0; i < numStrings && i < sizeof(sampleText)/sizeof(sampleText[0]); ++i) {
        size_t len = strlen(sampleText[i]) + 1;
        strings[i] = malloc(len);
        if (!strings[i]) {
            fprintf(stderr, "Memory allocation failed for string.\n");
            break;
        }
        strcpy(strings[i], sampleText[i]);
    }

    // Initialize point array with random coordinates
    BSTNode* root = NULL;
    pthread_t threads[4];  // Assume a maximum of 4 concurrent updates

    for (size_t i = 0; i < numPoints; ++i) {
        updateCoordinates(&points[i], -100.0, 100.0, -100.0, 100.0);

        pthread_mutex_lock(&bstMutex);
        root = insertPoint(root, points[i]);
        if (!root) { // Allocation failed
            fprintf(stderr, "Memory allocation failed for BST.\n");
            deleteTree(root);
            break;
        }
        pthread_mutex_unlock(&bstMutex);
    }

    // Simulate periodic updates (batch processing)
    BatchUpdateData updateData[numThreads];
    size_t batchSize = numPoints / 4;

    for (int i = 0; i < 4 && i * batchSize < numPoints; ++i) {
        updateData[i].points = points + (i * batchSize);
        updateData[i].count = (i == 3) ? (numPoints - i * batchSize) : batchSize;
        updateData[i].root = root;

        if (pthread_create(&threads[i], NULL, parallelUpdate, &updateData[i])) {
            fprintf(stderr, "Error creating thread.\n");
        }
    }

    for (int i = 0; i < 4 && i * batchSize < numPoints; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Free resources
    deleteTree(root);
    free(floats);

    for (size_t i = 0; i < numStrings && strings[i]; ++i) {
        free(strings[i]);
    }

    free(strings);
    free(points);
}

int main() {
    srand(time(NULL));
    initializeAndProcessData(10, 5, 1000); // Example usage
    return 0;
}
```']

