// Function to calculate the MD5 hash of a provided string
void calculate_md5_hash(const char *input, unsigned char output[MD5_DIGEST_LENGTH]) {
    if (input == NULL || output == NULL) return;

    // Calculate the length of the input string
    size_t len = strlen(input);

    // Allocate memory for the MD5 context and initialize it
    MD5_CTX md5_ctx;
    MD5_Init(&md5_ctx);

    // Update the MD5 context with the data to hash (input string)
    MD5_Update(&md5_ctx, input, len);

    // Finalize the MD5 hashing process and store the result in output buffer
    MD5_Final(output, &md5_ctx);

    // No need to free memory as we used stack allocation for MD5 context
}

// Example usage of calculate_md5_hash
int main() {
    const char *input_string = "Hello, World!";
    unsigned char md5_digest[MD5_DIGEST_LENGTH];

    calculate_md5_hash(input_string, md5_digest);

    // Print the MD5 hash as a hexadecimal string
    printf("MD5 Hash: ");
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        printf("%02x", md5_digest[i]);
    }
    printf("\n");

    return 0;
}
