#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

#define INITIAL_HASH_TABLE_SIZE 16
#define LOAD_FACTOR_THRESHOLD 0.75

typedef struct {
    int user_id;
    time_t timestamp;
} Activity;

typedef struct {
    int user_id;
    time_t last_accessed;
    Activity *activities;
    size_t activity_count;
} Session;

typedef struct HashTableNode {
    Session session;
    struct HashTableNode *next;
} HashTableNode;

typedef struct {
    HashTableNode **buckets;
    size_t size;
    size_t count;
    pthread_mutex_t lock;
} HashTable;

// Function prototypes
HashTable* create_hash_table(size_t size);
unsigned int hash(int user_id, size_t size);
void insert_session(HashTable *table, Session session);
Session* find_session(HashTable *table, int user_id);
void resize_hash_table(HashTable *table);

// Example HTTP client and logging functions (mock implementations)
void fetch_user_profile_async(const char *user_id);
void log_message(const char *message);

// Thread-safe hash table operations
HashTable* create_hash_table(size_t size) {
    HashTable *table = malloc(sizeof(HashTable));
    table->size = size;
    table->count = 0;
    table->buckets = calloc(size, sizeof(HashTableNode *));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

unsigned int hash(int user_id, size_t size) {
    return (unsigned int)(user_id % size);
}

void insert_session(HashTable *table, Session session) {
    unsigned int index = hash(session.user_id, table->size);
    HashTableNode *new_node = malloc(sizeof(HashTableNode));
    new_node->session = session;
    new_node->next = NULL;

    pthread_mutex_lock(&table->lock);
    if (table->buckets[index] == NULL) {
        table->buckets[index] = new_node;
    } else {
        HashTableNode *current = table->buckets[index];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    table->count++;

    if ((double)table->count / table->size > LOAD_FACTOR_THRESHOLD) {
        resize_hash_table(table);
    }

    pthread_mutex_unlock(&table->lock);
}

Session* find_session(HashTable *table, int user_id) {
    unsigned int index = hash(user_id, table->size);
    HashTableNode *current = table->buckets[index];

    while (current != NULL) {
        if (current->session.user_id == user_id) {
            return &current->session;
        }
        current = current->next;
    }

    return NULL;
}

void resize_hash_table(HashTable *table) {
    size_t new_size = table->size * 2;
    HashTableNode **new_buckets = calloc(new_size, sizeof(HashTableNode *));

    for (size_t i = 0; i < table->size; ++i) {
        HashTableNode *current = table->buckets[i];
        while (current != NULL) {
            unsigned int new_index = hash(current->session.user_id, new_size);
            HashTableNode *next_node = current->next;

            current->next = new_buckets[new_index];
            new_buckets[new_index] = current;

            current = next_node;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->size = new_size;
}

// Mock functions for HTTP client and logging
void fetch_user_profile_async(const char *user_id) {
    // Simulate asynchronous HTTP request
    sleep(1);  // Simulate network delay
    log_message("Fetched user profile for ID: ");
    printf("%s\n", user_id);
}

void log_message(const char *message) {
    // Simple logging to stdout (mock implementation)
    printf("[%ld] %s\n", time(NULL), message);
}

int main() {
    HashTable *session_table = create_hash_table(INITIAL_HASH_TABLE_SIZE);

    Session session1 = {1, time(NULL), NULL, 0};
    insert_session(session_table, session1);

    fetch_user_profile_async("12345");

    Session *found_session = find_session(session_table, 1);
    if (found_session) {
        printf("Session found for user ID: %d\n", found_session->user_id);
    }

    // Cleanup
    free(session_table->buckets);
    pthread_mutex_destroy(&session_table->lock);
    free(session_table);

    return 0;
}
```

### Key Points:
- **Hash Table**: Manages sessions with dynamic resizing to handle load efficiently.
- **Thread Safety**: Uses mutexes to ensure safe concurrent access.
- **Asynchronous HTTP Client**: Simulated with a delay function; real implementation would use libraries like `libcurl` or `CAsyncIO`.
- **Logging**: Simple logging function for demonstration; in practice, integrate with a service like `syslog`.

This code is a basic framework and should be extended with error handling, actual network requests, and robust logging as per the requirements.']

['```c
#include <stdio.h>
