#include <pthread.h>
#include <unistd.h>

#define MAX_LOG_ENTRIES 1000000
#define DEFAULT_ROTATION_HOURS 24
#define LOG_FILE_SIZE_LIMIT 10485760 // 10 MB

typedef enum {
    SEVERITY_INFO,
    SEVERITY_WARNING,
    SEVERITY_ERROR
} SeverityLevel;

typedef struct LogEntry {
    time_t timestamp;
    SeverityLevel severity;
    char *message;
    size_t message_length;
} LogEntry;

typedef struct {
    LogEntry *entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    FILE *log_stats_file;
} LogManager;

LogManager log_manager = {0};

void init_log_manager() {
    log_manager.capacity = 1024; // Initial allocation
    log_manager.entries = calloc(log_manager.capacity, sizeof(LogEntry));
    if (!log_manager.entries) {
        perror("Failed to allocate memory for log entries");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&log_manager.lock, NULL);

    char *log_stats_filename = "log_stats.log";
    log_manager.log_stats_file = fopen(log_stats_filename, "a");
    if (!log_manager.log_stats_file) {
        perror("Failed to open log stats file");
        exit(EXIT_FAILURE);
    }
}

void destroy_log_manager() {
    for (size_t i = 0; i < log_manager.count; ++i) {
        free(log_manager.entries[i].message);
    }
    free(log_manager.entries);
    pthread_mutex_destroy(&log_manager.lock);
    if (log_manager.log_stats_file) {
        fclose(log_manager.log_stats_file);
    }
}

void resize_log_entries() {
    size_t new_capacity = log_manager.capacity * 2;
    LogEntry *new_entries = realloc(log_manager.entries, new_capacity * sizeof(LogEntry));
    if (!new_entries) {
        perror("Failed to reallocate memory for log entries");
        exit(EXIT_FAILURE);
    }
    log_manager.entries = new_entries;
    log_manager.capacity = new_capacity;
}

void add_log_entry(time_t timestamp, SeverityLevel severity, const char *message) {
    pthread_mutex_lock(&log_manager.lock);

    if (log_manager.count == log_manager.capacity) {
        resize_log_entries();
    }

    LogEntry *entry = &log_manager.entries[log_manager.count++];
    entry->timestamp = timestamp;
    entry->severity = severity;
    entry->message_length = strlen(message);
    entry->message = malloc(entry->message_length + 1);
    if (!entry->message) {
        perror("Failed to allocate memory for log message");
        exit(EXIT_FAILURE);
    }
    strncpy(entry->message, message, entry->message_length + 1);

    pthread_mutex_unlock(&log_manager.lock);
}

void serialize_and_send_to_service(const LogEntry *entry) {
    // Placeholder for integration with external logging service
    // Example: snprintf(serialized_data, sizeof(serialized_data), "timestamp:%ld,severity:%d,message:%s", entry->timestamp, entry->severity, entry->message);
}

void log_rotation() {
    size_t rotation_interval = DEFAULT_ROTATION_HOURS * 3600;
    time_t current_time = time(NULL);

    for (size_t i = 0; i < log_manager.count; ++i) {
        if (current_time - log_manager.entries[i].timestamp > rotation_interval) {
            free(log_manager.entries[i].message);
            memmove(&log_manager.entries[i], &log_manager.entries[i + 1], (log_manager.count - i - 1) * sizeof(LogEntry));
            --log_manager.count;
            --i; // Recheck current index
        }
    }

    if (fseek(log_manager.log_stats_file, 0, SEEK_END) == 0 && ftell(log_manager.log_stats_file) > LOG_FILE_SIZE_LIMIT) {
        fclose(log_manager.log_stats_file);
        char new_filename[256];
        snprintf(new_filename, sizeof(new_filename), "log_stats_%ld.log", time(NULL));
        rename("log_stats.log", new_filename);
        log_manager.log_stats_file = fopen("log_stats.log", "a");
    }
}

void record_log_operation(const char *operation) {
    pthread_mutex_lock(&log_manager.lock);

    fprintf(log_manager.log_stats_file, "%s\n", operation);
    fflush(log_manager.log_stats_file); // Ensure data is written to disk

    pthread_mutex_unlock(&log_manager.lock);
}

int main() {
    init_log_manager();

    add_log_entry(time(NULL), SEVERITY_INFO, "This is an info log entry.");
    add_log_entry(time(NULL) + 10000, SEVERITY_WARNING, "This is a warning log entry.");
    add_log_entry(time(NULL) + 20000, SEVERITY_ERROR, "This is an error log entry.");

    record_log_operation("Added 3 entries");

    log_rotation();

    destroy_log_manager();
    return 0;
}
```

