#define TEMP_MIN -50.0
#define TEMP_MAX 50.0

typedef struct {
    double temperature;
    char location[256];
} DataRecord;

typedef struct {
    char *memory;
    size_t size;
} MemoryBuffer;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

struct MemoryStruct {
    char *memory;
    size_t size;
};

static size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    struct MemoryStruct *mem = (struct MemoryStruct *) userp;

    char *ptr = realloc(mem->memory, mem->size + realsize + 1);
    if(ptr == NULL) {
        // out of memory!
        printf("not enough memory (realloc returned NULL)\n");
        return 0;
    }

    mem->memory = ptr;
    memcpy(&(mem->memory[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->memory[mem->size] = '\0';

    return realsize;
}

int fetchApiData(MemoryBuffer *buffer) {
    CURL *curl_handle;
    struct MemoryStruct chunk;

    chunk.memory = malloc(1);  // will be grown as needed by the realloc above
    chunk.size = 0;    // no data at this point

    curl_global_init(CURL_GLOBAL_ALL);

    curl_handle = curl_easy_init();
    if(curl_handle) {
        curl_easy_setopt(curl_handle, CURLOPT_URL, "http://api.example.com/temperature");
        curl_easy_setopt(curl_handle, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
        curl_easy_setopt(curl_handle, CURLOPT_WRITEDATA, (void *)&chunk);

        CURLcode res = curl_easy_perform(curl_handle);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            free(chunk.memory);
            return -1;
        }

        buffer->memory = chunk.memory;
        buffer->size = chunk.size;

        curl_easy_cleanup(curl_handle);
    }
    curl_global_cleanup();

    return 0;
}

int readLocalFile(const char *filename, MemoryBuffer *buffer) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("fopen");
        return -1;
    }

    fseek(file, 0, SEEK_END);
    size_t filesize = ftell(file);
    rewind(file);

    buffer->memory = (char *)malloc(filesize + 1);
    if (!buffer->memory) {
        perror("malloc");
        fclose(file);
        return -1;
    }

    fread(buffer->memory, 1, filesize, file);
    buffer->memory[filesize] = '\0';
    buffer->size = filesize;

    fclose(file);

    return 0;
}

int processAndAnalyzeData(const char *filename) {
    pthread_mutex_lock(&mutex);

    MemoryBuffer apiData, localFileData;
    int result;

    if ((result = fetchApiData(&apiData)) != 0 || (result = readLocalFile(filename, &localFileData)) != 0) {
        pthread_mutex_unlock(&mutex);
        return -1; // error code for failed data fetching
    }

    char *dataSource = apiData.memory;
    size_t totalSize = apiData.size;

    if (localFileData.memory) {
        dataSource = malloc(totalSize + localFileData.size + 1);
        if (!dataSource) {
            pthread_mutex_unlock(&mutex);
            return -2; // error code for memory allocation failure
        }
        strcpy(dataSource, apiData.memory);
        strcat(dataSource, localFileData.memory);
        totalSize += localFileData.size;
    }

    DataRecord *records = NULL;
    int recordCount = 0;

    char *token = strtok(dataSource, "\n");
    while (token) {
        double temp;
        char location[256];
        if (sscanf(token, "%lf %[^\t\n]", &temp, location) == 2 && TEMP_MIN <= temp && temp <= TEMP_MAX) {
            records = realloc(records, sizeof(DataRecord) * (recordCount + 1));
            if (!records) {
                pthread_mutex_unlock(&mutex);
                return -3; // error code for memory allocation failure
            }
            records[recordCount].temperature = temp;
            strncpy(records[recordCount].location, location, sizeof(records[recordCount].location) - 1);
            recordCount++;
        }
        token = strtok(NULL, "\n");
    }

    if (localFileData.memory) free(localFileData.memory);

    // Sort records by location
    qsort(records, recordCount, sizeof(DataRecord), [](const void *a, const void *b) {
        DataRecord *recordA = (DataRecord *)a;
        DataRecord *recordB = (DataRecord *)b;
        return strcmp(recordA->location, recordB->location);
    });

    // Calculate averages
    double sumTemp = 0.0, count = 1.0;
    char currentLocation[256];
    strncpy(currentLocation, records[0].location, sizeof(currentLocation) - 1);

    for (int i = 1; i <= recordCount; i++) {
        if (i == recordCount || strcmp(records[i].location, currentLocation) != 0) {
            printf("Average temperature in %s: %.2f\n", currentLocation, sumTemp / count);
            sumTemp = records[i].temperature;
            count = 1.0;
            strncpy(currentLocation, records[i].location, sizeof(currentLocation) - 1);
        } else {
            sumTemp += records[i].temperature;
            count++;
        }
    }

    free(records);

    pthread_mutex_unlock(&mutex);
    return 0; // success
}
