    for (int i = 0; i < numMetrics; ++i) {
        NetworkPerformanceMetrics metric(i, calculateThroughput(rand() % 100));

        if (!metadataAPI.fetchMetadata()) {
            // Handle API failure: retry with exponential backoff
            int retries = 0;
            while (retries < 3 && !metadataAPI.fetchMetadata()) {
                std::this_thread::sleep_for(std::chrono::milliseconds(100 * (1 << retries)));
                ++retries;
            }
        }

        updateMovingAverage(networkMetrics, metric);
    }

    for (auto& user : users) {
        if (user.age < 18 || user.age > 120) {
            std::cerr << "Invalid age detected: " << user.age << "\n";
        }
    }

