    long* offsets = new(std::nothrow) long[numRecords];
    int* keys = new(std::nothrow) int[numRecords];
    struct record {
        int value;
    } *records = new(std::nothrow) record[numRecords];

    if (!offsets || !keys || !records) {
        delete[] offsets;
        delete[] keys;
        delete[] records;
        return -1; // Error code for memory allocation failure
    }

    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 100);

    for (int i = 0; i < numRecords; ++i) {
        offsets[i] = static_cast<long>(rand() % 10000);
        keys[i] = rand();
        records[i].value = dis(gen); // Random value between 0 and 100
    }

    delete[] offsets;
    delete[] keys;
    delete[] records;

    return 0; // Success code
}

