```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RNTI 65535

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} NFAPI_CRC_MANAGER;

int populate_crc_array(NFAPI_CRC_MANAGER *manager, size_t N) {
    if (N == 0 || manager == NULL) return -1;

    // Initialize RNTI tracking
    int rnti_used[MAX_RNTI + 1] = {0};

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < N; ++i) {
        if (manager->size == manager->capacity) {
            size_t new_capacity = (manager->capacity == 0) ? 4 : manager->capacity * 2;
            NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!new_array) {
                fprintf(stderr, "Memory allocation failed\n");
                pthread_mutex_unlock(&manager->lock);
                return -1; // Memory allocation failure
            }
            manager->array = new_array;
            manager->capacity = new_capacity;
        }

        NFAPI_CRC_INDICATION_PDU_T *pdu = &manager->array[manager->size];

        // Generate unique RX_UE_INFORMATION_TAG
        pdu->RX_UE_INFORMATION_TAG = rand() % 10000;

        // Ensure uniqueness of RNTI across array
        unsigned short rnti;
        do {
            rnti = rand() % (MAX_RNTI + 1);
        } while (rnti_used[rnti]);

        pdu->RNTI = rnti;
        rnti_used[rnti] = 1;

        // Set CRCFLAG randomly
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; 

        manager->size++;
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

NFAPI_CRC_MANAGER* create_crc_manager(size_t initial_capacity) {
    NFAPI_CRC_MANAGER *manager = malloc(sizeof(NFAPI_CRC_MANAGER));
    if (!manager) return NULL;

    manager->array = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        free(manager);
        return NULL;
    }

    manager->size = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_crc_manager(NFAPI_CRC_MANAGER *manager) {
    if (manager) {
        free(manager->array);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}
