#define MAX_DEVICES 100
#define DEVICE_NAME_MAX_LEN 15
#define MAC_ADDRESS_MAX_LEN 18 // XX:XX:XX:XX:XX:XX + \0

typedef struct {
    char timestamp[20];      // Assuming ISO format "YYYY-MM-DDTHH:MM:SS"
    float temperature;
    char *mac_address;       // Deferred allocation until first write
} DataEntry;

typedef struct {
    char device_name[DEVICE_NAME_MAX_LEN + 1];
    int device_id;
    size_t data_count;
    DataEntry *data_entries;
} DeviceConfig;

int validate_mac_address(const char* mac) {
    if (strlen(mac) != MAC_ADDRESS_MAX_LEN - 1)
        return 0;

    for (size_t i = 0; i < strlen(mac); ++i) {
        if ((i % 3 == 2 && mac[i] != ':') ||
            ((mac[i] >= '0' && mac[i] <= '9') || 
             (mac[i] >= 'A' && mac[i] <= 'F') || 
             (mac[i] >= 'a' && mac[i] <= 'f')) == 0) {
            return 0;
        }
    }

    return 1;
}

int add_device(DeviceConfig *devices, size_t *device_count, const char* name, int device_id,
               const char* timestamp, float temperature, const char* mac_address) {

    if (*device_count >= MAX_DEVICES || strlen(name) > DEVICE_NAME_MAX_LEN) {
        fprintf(stderr, "Error: Cannot add more devices or invalid device name length.\n");
        return -1;
    }

    for (size_t i = 0; i < *device_count; ++i) {
        if (strcmp(devices[i].device_name, name) == 0) {
            fprintf(stderr, "Error: Duplicate device name detected.\n");
            return -2;
        }
    }

    if (!validate_mac_address(mac_address)) {
        fprintf(stderr, "Error: Invalid MAC address format.\n");
        return -3;
    }

    DeviceConfig new_device = { .device_name = "", .device_id = 0, .data_count = 0, .data_entries = NULL };
    strncpy(new_device.device_name, name, DEVICE_NAME_MAX_LEN);
    new_device.device_name[DEVICE_NAME_MAX_LEN] = '\0';
    new_device.device_id = device_id;

    DataEntry data;
    strcpy(data.timestamp, timestamp);
    data.temperature = temperature;
    data.mac_address = strdup(mac_address); // Deferred allocation on first write

    devices[*device_count].data_entries = malloc(sizeof(DataEntry));
    if (!devices[*device_count].data_entries) {
        fprintf(stderr, "Error: Memory allocation for device data entries failed.\n");
        free(data.mac_address);
        return -4;
    }

    *(devices[*device_count].data_entries) = data;
    devices[*device_count].data_count = 1;

    (*device_count)++;

    return 0;
}

void free_devices(DeviceConfig *devices, size_t device_count) {
    for (size_t i = 0; i < device_count; ++i) {
        if (devices[i].data_entries != NULL) {
            for (size_t j = 0; j < devices[i].data_count; ++j) {
                free(devices[i].data_entries[j].mac_address);
            }
            free(devices[i].data_entries);
        }
    }
}

int main() {
    DeviceConfig devices[MAX_DEVICES];
    size_t device_count = 0;

    add_device(devices, &device_count, "DeviceA", 1, "2023-01-01T12:00:00", 25.5, "AA:BB:CC:DD:EE:FF");
    // Further device additions...

    free_devices(devices, device_count);

    return 0;
}
