    HANDOVER,
    // Add additional modes as needed
} RRC_CONNECTION_MODE;

typedef struct {
    int cell_id;
    RRC_CONNECTION_MODE connection_mode;
    PHY_CHANNEL_STATE phy_channel_state;
} NFAPI_RRC_MESSAGE_PDU_T;

typedef struct Node {
    NFAPI_RRC_MESSAGE_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;  // For thread safety
} LinkedList;

// Function prototypes
LinkedList* create_list();
void free_list(LinkedList* list);
int add_element(LinkedList* list, NFAPI_RRC_MESSAGE_PDU_T element);
int is_cell_id_unique(LinkedList* list, int cell_id);
void handle_error(const char* message);

// Create and initialize the linked list
LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) {
        handle_error("Failed to allocate memory for linked list");
        return NULL;
    }

    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Free the allocated linked list
void free_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Add an element to the linked list
int add_element(LinkedList* list, NFAPI_RRC_MESSAGE_PDU_T element) {
    pthread_mutex_lock(&list->lock);

    if (!is_cell_id_unique(list, element.cell_id)) {
        pthread_mutex_unlock(&list->lock);
        return -1;  // Cell ID already exists
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        handle_error("Failed to allocate memory for node");
        pthread_mutex_unlock(&list->lock);
        return -2;  // Memory allocation failure
    }

    new_node->data = element;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Check if a CELL_ID is unique in the linked list
int is_cell_id_unique(LinkedList* list, int cell_id) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.cell_id == cell_id) {
            return 0;  // Not unique
        }
        current = current->next;
    }
    return 1;  // Unique
}

// Handle errors by logging and returning appropriate error codes
void handle_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Example usage of the linked list management function
int main() {
    LinkedList* list = create_list();
    if (!list) return -1;

    NFAPI_RRC_MESSAGE_PDU_T pdu;

    for (int i = 0; i < 10; ++i) {
        pdu.cell_id = i;   // Simulate cell ID from an external data feed
        pdu.connection_mode = CONNECTED;
        pdu.phy_channel_state.modulation = 4;
        pdu.phy_channel_state.coding_scheme = 2;

        if (add_element(list, pdu) != 0) {
            printf("Failed to add element with CELL_ID %d\n", pdu.cell_id);
        }
    }

    free_list(list);
    return 0;
}
