        if (!(*items)[i]) {
            while (--i >= 0) free((*items)[i]);
            free(*items);
            *items = NULL;
            return -2;
        }

        // Initialize locks
        pthread_rwlock_init(&(*items)[i]->rwlock, NULL);

        (*items)[i]->productID = rand() % 10000;  // Random product ID
        (*items)[i]->stockQuantity = 50;          // Default stock quantity
        (*items)[i]->orders = NULL;
        (*items)[i]->numOrders = 0;

