            while (--i >= 0) free((*consumers)[i]);
            free(*consumers);
            *consumers = NULL;
            for (int j = 0; j < numItems; ++j)
                free((*items)[j]);
            free(*items);
            *items = NULL;
            return -2;
        }

        // Initialize consumer-specific locks
        pthread_mutex_init(&(*consumers)[i]->lock, NULL);

        (*consumers)[i]->userID = i + 1;  // Example user ID
        (*consumers)[i]->preferences = NULL;
        (*consumers)[i]->numPreferences = 0;

        (*consumers)[i]->purchaseHistory = NULL;
        (*consumers)[i]->numPurchases = 0;
    }

    return 0; // Success
}

// Insert an order into the BST, ensuring concurrent safety and balance maintenance
bst_node* insert_order(bst_node* root, order* newOrder) {
    if (!root)
        return create_bst_node(newOrder);

    pthread_rwlock_wrlock(&root->rwlock);
    int compareResult = difftime(newOrder->orderDate, root->orderData->orderDate);

    if (compareResult < 0) {
        if (!root->left)
            root->left = create_bst_node(newOrder);
        else
            root->left = insert_order(root->left, newOrder);
    } else {
        if (!root->right)
            root->right = create_bst_node(newOrder);
        else
            root->right = insert_order(root->right, newOrder);
    }

    pthread_rwlock_unlock(&root->rwlock);

    return balance_bst(root); // Balance the tree after insertion
}

// Function to free BST nodes recursively
bst_node* free_bst(bst_node* node) {
    if (!node)
        return NULL;

    pthread_rwlock_wrlock(&node->rwlock);
    free_bst(node->left);
    free_bst(node->right);

    // Free the current node's data
    free(node->orderData);  // Ensure to correctly manage memory for order details

    pthread_rwlock_unlock(&node->rwlock);

    pthread_rwlock_destroy(&node->rwlock);
    free(node);
