int serialize_file_event_list(FileEventList *list, FILE *file) {
    if (!list || !file) return -1;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current) {
        fwrite(&(current->event), sizeof(FILE_EVENT_TAG), 1, file);
        for (size_t i = 0; i < current->event.num_blocks; ++i) {
            size_t block_size = current->event.blocks[i].block_size;
            fwrite(&block_size, sizeof(size_t), 1, file);
            fwrite(current->event.blocks[i].data, block_size, 1, file);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    log_operation("SERIALIZE", "File event list serialized successfully.");
    return 0;
}

int deserialize_file_event_list(FileEventList *list, FILE *file) {
    if (!list || !file) return -1;

    pthread_mutex_lock(&list->lock);

    // Clear existing list
    Node *current = list->head;
    while (current) {
        Node *to_remove = current;
        current = current->next;
        free(to_remove->event.blocks);
        free(to_remove);
    }
    list->head = NULL;

    FILE_EVENT_TAG event;
    while (fread(&event, sizeof(FILE_EVENT_TAG), 1, file)) {
        size_t total_block_size = 0;
        for (size_t i = 0; i < event.num_blocks; ++i) {
            size_t block_size = 0;
            fread(&block_size, sizeof(size_t), 1, file);
            if (block_size > list->max_block_size) continue;

            total_block_size += block_size;
        }

        FILE_BLOCK_DATA *blocks = malloc(sizeof(FILE_BLOCK_DATA) + total_block_size);
        if (!blocks) {
            log_operation("ERROR", "Memory allocation failed during deserialization.");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }

        event.blocks = blocks;
        size_t offset = 0;

        for (size_t i = 0; i < event.num_blocks; ++i) {
            size_t block_size = 0;
            fread(&block_size, sizeof(size_t), 1, file);
            if (block_size > list->max_block_size) continue;

            blocks[i].block_size = block_size;
            fread(blocks[i].data, block_size, 1, file);
            offset += block_size;
        }

        add_file_event(list, event); // Re-add to the list
    }

    pthread_mutex_unlock(&list->lock);

    log_operation("DESERIALIZE", "File event list deserialized successfully.");
    return 0;
}

// Function to perform garbage collection on unused events
void garbage_collect(FileEventList *list) {
    if (!list) return;

    // Placeholder for actual garbage collection logic
    log_operation("GARBAGE_COLLECT", "Performed garbage collection on file events.");
}

// Example function to monitor list state (simplified)
void report_file_event_list_state(const FileEventList *list) {
    if (!list) return;

    size_t active_events = 0;
    size_t total_block_size = 0;
    Node *current = list->head;

    while (current) {
        ++active_events;
        for (size_t i = 0; i < current->event.num_blocks; ++i) {
            total_block_size += current->event.blocks[i].block_size;
        }
        current = current->next;
    }

    printf("Active Events: %zu\n", active_events);
    printf("Total Block Size: %zu bytes\n", total_block_size);
}

// Function to destroy the file event list and free all resources
void destroy_file_event_list(FileEventList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current) {
        Node *to_free = current;
        current = current->next;
        free(to_free->event.blocks);
        free(to_free);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);

    log_operation("DESTROY", "File event list destroyed.");
}
