#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    size_t numRecords;
    pthread_mutex_t lock;
} DataStructure;

// Memory pool for efficient allocation
void* memoryPool = NULL;
size_t poolSize = 0;

void* allocateFromPool(size_t size) {
    if (memoryPool == NULL || poolSize < size) return malloc(size);
    void *ptr = memoryPool;
    memoryPool += size;
    poolSize -= size;
    return ptr;
}

void returnToPool(void *ptr, size_t size) {
    // Simple pool management for demonstration
    free(ptr);  // For real use, implement a more sophisticated memory pooling mechanism.
}

DataStructure* initDataStructure(size_t numRecords) {
    DataStructure *ds = (DataStructure*)allocateFromPool(sizeof(DataStructure));
    pthread_mutex_init(&ds->lock, NULL);

    ds->offsets = (long*)allocateFromPool(numRecords * sizeof(long));
    ds->keys = (int*)allocateFromPool(numRecords * sizeof(int));

    if (!ds->offsets || !ds->keys) {
        returnToPool(ds->offsets, numRecords * sizeof(long));
        returnToPool(ds->keys, numRecords * sizeof(int));
        pthread_mutex_destroy(&ds->lock);
        returnToPool(ds, sizeof(DataStructure));
        return NULL;
    }

    ds->records = (record**)allocateFromPool(numRecords * sizeof(record*));
    if (!ds->records) {
        returnToPool(ds->offsets, numRecords * sizeof(long));
        returnToPool(ds->keys, numRecords * sizeof(int));
        pthread_mutex_destroy(&ds->lock);
        returnToPool(ds, sizeof(DataStructure));
        return NULL;
    }

    for (size_t i = 0; i < numRecords; ++i) {
        ds->records[i] = (record*)allocateFromPool(sizeof(record));
        if (!ds->records[i]) {
            while (i > 0) {
                --i;
                returnToPool(ds->records[i], sizeof(record));
            }
            returnToPool(ds->offsets, numRecords * sizeof(long));
            returnToPool(ds->keys, numRecords * sizeof(int));
            returnToPool(ds->records, numRecords * sizeof(record*));
            pthread_mutex_destroy(&ds->lock);
            returnToPool(ds, sizeof(DataStructure));
            return NULL;
        }
    }

    ds->numRecords = numRecords;

    // Random number generator initialization
    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < numRecords; ++i) {
        ds->records[i]->value = rand() % (100 - 1 + 1) + 1;
    }

    return ds;
}

void cleanupDataStructure(DataStructure *ds, size_t numRecords) {
    if (!ds) return;

    pthread_mutex_lock(&ds->lock);
    for (size_t i = 0; i < numRecords; ++i) {
        returnToPool(ds->records[i], sizeof(record));
    }
    returnToPool(ds->records, numRecords * sizeof(record*));

    returnToPool(ds->keys, numRecords * sizeof(int));
    returnToPool(ds->offsets, numRecords * sizeof(long));

    pthread_mutex_unlock(&ds->lock);
    pthread_mutex_destroy(&ds->lock);
    returnToPool(ds, sizeof(DataStructure));
}

// Usage example
int main() {
    size_t numRecords = 1000;
    DataStructure* ds = initDataStructure(numRecords);

    if (ds) {
        // Use the data structure
        cleanupDataStructure(ds, numRecords);
    }

    return 0;
}
