#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int userId;
    time_t sessionStart;
    time_t sessionEnd;
    double sessionDuration;
    int activityScore;
} UserSessionData;

typedef struct Node {
    UserSessionData data;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t capacity;
    pthread_mutex_t lock;
} HashTable;

void logEvent(const char* message) {
    // Placeholder for integration with an external logging library
    printf("%s\n", message);
}

HashTable* createHashTable(size_t capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = (Node**)calloc(capacity, sizeof(Node*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->capacity = capacity;
    pthread_mutex_init(&table->lock, NULL);
    logEvent("HashTable created.");
    return table;
}

size_t hashFunction(int userId, size_t capacity) {
    return userId % capacity;
}

void insertSession(HashTable* table, UserSessionData data) {
    pthread_mutex_lock(&table->lock);

    size_t index = hashFunction(data.userId, table->capacity);
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&table->lock);
        logEvent("Memory allocation failed for new session node.");
        return;
    }

    newNode->data = data;
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;

    pthread_mutex_unlock(&table->lock);
    logEvent("Session inserted.");
}

UserSessionData* findSession(HashTable* table, int userId) {
    pthread_mutex_lock(&table->lock);

    size_t index = hashFunction(userId, table->capacity);
    Node* node = table->buckets[index];

    while (node) {
        if (node->data.userId == userId) {
            pthread_mutex_unlock(&table->lock);
            return &node->data;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&table->lock);
    logEvent("Session not found.");
    return NULL;
}

void deleteHashTable(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        Node* current = table->buckets[i];
        while (current) {
            Node* temp = current;
            current = current->next;
            free(temp);
            logEvent("Node deallocated.");
        }
    }

    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
    logEvent("HashTable deallocated.");
}

void initializeAndManageSessions(int seed, int numSessions) {
    srand(seed);

    HashTable* table = createHashTable(INITIAL_CAPACITY);
    if (!table) {
        fprintf(stderr, "Failed to create hash table.\n");
        return;
    }

    for (int i = 0; i < numSessions; ++i) {
        UserSessionData session;
        session.userId = rand() % 1000 + 1;
        session.sessionStart = time(NULL) - (rand() % 3600);
        session.sessionEnd = session.sessionStart + (rand() % 300 + 1);
        session.sessionDuration = difftime(session.sessionEnd, session.sessionStart);

        // Simulate activity score based on random actions
        session.activityScore = rand() % 100;

        insertSession(table, session);
    }

    // Example of retrieval and deletion
    int userIdToFind = 123; // Placeholder user ID for demonstration
    UserSessionData* foundSession = findSession(table, userIdToFind);
    if (foundSession) {
        printf("Found Session: UserId=%d, Duration=%.2f\n", 
               foundSession->userId, foundSession->sessionDuration);
    }

    deleteHashTable(table);
}

int main() {
    initializeAndManageSessions(42, 20); // Example seed and number of sessions
    return 0;
}
