#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_HASH_TABLE_SIZE 16
#define LOAD_FACTOR_THRESHOLD 0.75

typedef struct Record {
    long offset;
    int key;
    char buffer[101]; // 100 characters + null terminator
    union {
        long long_val;
        int int_val;
    } rand_value;
    struct Record *prev, *next;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct HashTable {
    Node** buckets;
    size_t size;
    size_t count;
    pthread_mutex_t lock;
} HashTable;

// Forward declarations
void initialize_record(Record* rec, int key, long offset);
void init_hash_table(HashTable* table);
Node* create_node(int key, long offset);
int hash_function(int key, size_t size);
void resize_hash_table(HashTable* table);
void insert_to_list(Node** head, Node* new_node);
void remove_from_list(Node** head, Node* node);
Record* find_record_by_key(HashTable* table, int key);
Node* lookup_in_hash_table(HashTable* table, int key);

// Function implementations
void initialize_record(Record* rec, int key, long offset) {
    if (rec == NULL || offset < 0) return;

    rec->key = key;
    rec->offset = offset;

    // Initialize buffer to null-terminated string
    memset(rec->buffer, '\0', sizeof(rec->buffer));

    // Randomly assign a value in the union
    srand(time(NULL));
    if (rand() % 2) {
        rec->rand_value.int_val = rand() % 100001;
    } else {
        rec->rand_value.long_val = rand() % 100001;
    }
}

void init_hash_table(HashTable* table) {
    table->size = INITIAL_HASH_TABLE_SIZE;
    table->count = 0;
    table->buckets = calloc(table->size, sizeof(Node*));

    if (!table->buckets) {
        fprintf(stderr, "Failed to allocate memory for hash table buckets.\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&table->lock, NULL);
}

Node* create_node(int key, long offset) {
    Node* node = malloc(sizeof(Node));
    if (!node) {
        perror("Failed to allocate memory for new node.");
        return NULL;
    }

    initialize_record(&(node->record), key, offset);

    node->next = NULL;

    return node;
}

int hash_function(int key, size_t size) {
    return abs(key % size);
}

void resize_hash_table(HashTable* table) {
    size_t new_size = table->size * 2;
    Node** new_buckets = calloc(new_size, sizeof(Node*));

    if (!new_buckets) {
        fprintf(stderr, "Failed to allocate memory for hash table resize.\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < table->size; ++i) {
        Node* node = table->buckets[i];
        while (node) {
            int new_index = hash_function(node->record.key, new_size);

            // Insert into the new bucket
            Node* next_node = node->next;
            node->next = new_buckets[new_index];
            new_buckets[new_index] = node;

            node = next_node;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->size = new_size;
}

void insert_to_list(Node** head, Node* new_node) {
    if (!head || !new_node) return;

    pthread_mutex_lock(head); // Ensure thread safety
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(head);
}

void remove_from_list(Node** head, Node* node) {
    if (!head || !node) return;

    pthread_mutex_lock(head); // Ensure thread safety
    Node** current = head;

    while (*current != NULL && *current != node) {
        current = &(*current)->next;
    }

    if (*current == NULL) {
        pthread_mutex_unlock(head);
        return; // Node not found
    }

    *current = node->next;
    free(node);

    pthread_mutex_unlock(head);
}

Record* find_record_by_key(HashTable* table, int key) {
    if (!table || table->count == 0) return NULL;

    Node* node = lookup_in_hash_table(table, key);
    return (node != NULL) ? &(node->record) : NULL;
}

Node* lookup_in_hash_table(HashTable* table, int key) {
    if (!table) return NULL;

    pthread_mutex_lock(&(table->lock));

    int index = hash_function(key, table->size);
    Node* node = table->buckets[index];

    while (node != NULL && node->record.key != key) {
        node = node->next;
    }

    pthread_mutex_unlock(&(table->lock));
    return node;
}

// Function to insert a record into the hash table
void insert_record(HashTable* table, int key, long offset) {
    if (!table || key < 0) return;

    pthread_mutex_lock(&(table->lock));

    // Check for duplicate keys
    Node* existing_node = lookup_in_hash_table(table, key);
    if (existing_node) {
        fprintf(stderr, "Duplicate key found: %d\n", key);
        pthread_mutex_unlock(&(table->lock));
        return;
    }

    Node* new_node = create_node(key, offset);
    if (!new_node) {
        pthread_mutex_unlock(&(table->lock));
        return;
    }

    // Insert into hash table
    int index = hash_function(key, table->size);
    insert_to_list(&(table->buckets[index]), new_node);

    ++(table->count);

    // Check load factor and resize if necessary
    if ((double)table->count / (double)table->size > LOAD_FACTOR_THRESHOLD) {
        resize_hash_table(table);
    }

    pthread_mutex_unlock(&(table->lock));
}

// Example usage of the implemented functions
int main() {
    HashTable table;
    init_hash_table(&table);

    // Insert records
    insert_record(&table, 1, 1000L);
    insert_record(&table, 2, 2000L);
    insert_record(&table, 3, 3000L);

    // Lookup a record
    Record* rec = find_record_by_key(&table, 2);
    if (rec) {
        printf("Record found: Key=%d, Offset=%ld\n", rec->key, rec->offset);
    } else {
        printf("Record not found.\n");
    }

    return 0;
}
