    char* comment;
    int rating;
} UserPreferenceValue;

// Structure for storing user preferences
typedef struct {
    char* appName;
    int appVersion;
    double performanceMetric;
    UserPreferenceValue value; // Could be a string or an integer
    int valueType; // 0 for string, 1 for integer
} UserPreferenceRecord;

// Metadata structure
typedef struct {
    char* appName;
    time_t lastUpdate;
    size_t userCount;
} AppMetadata;

// Node for hash table chaining
typedef struct HashNode {
    UserPreferenceRecord record;
    struct HashNode* next;
} HashNode;

// Cache structure with mutex for concurrency control
typedef struct {
    HashNode** table;
    size_t capacity;
    pthread_mutex_t lock;
} PreferenceCache;

#define INITIAL_CAPACITY 16

unsigned int hashFunction(const char* str, size_t capacity) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % capacity;
}

PreferenceCache* createCache(size_t initialCapacity) {
    PreferenceCache* cache = (PreferenceCache*)malloc(sizeof(PreferenceCache));
    if (!cache) return NULL;

    cache->capacity = initialCapacity > 0 ? initialCapacity : INITIAL_CAPACITY;
    cache->table = (HashNode**)calloc(cache->capacity, sizeof(HashNode*));

    pthread_mutex_init(&cache->lock, NULL);

    return cache;
}

void freeCache(PreferenceCache* cache) {
    for (size_t i = 0; i < cache->capacity; ++i) {
        HashNode* node = cache->table[i];
        while (node) {
            HashNode* temp = node;
            node = node->next;
            free(temp->record.appName);
            if (temp->record.valueType == 0)
                free(temp->record.value.comment);
            free(temp);
        }
    }

    free(cache->table);
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

int cacheInsert(PreferenceCache* cache, const UserPreferenceRecord* record) {
    unsigned int index = hashFunction(record->appName, cache->capacity);

    pthread_mutex_lock(&cache->lock);

    HashNode* newNode = (HashNode*)malloc(sizeof(HashNode));
    if (!newNode) {
        pthread_mutex_unlock(&cache->lock);
        return -1;
    }

    newNode->record = *record;
    newNode->next = cache->table[index];
    cache->table[index] = newNode;

    pthread_mutex_unlock(&cache->lock);

    return 0;
}

UserPreferenceRecord* cacheRetrieve(PreferenceCache* cache, const char* appName) {
    unsigned int index = hashFunction(appName, cache->capacity);
    pthread_mutex_lock(&cache->lock);

    HashNode* node = cache->table[index];
    while (node) {
        if (strcmp(node->record.appName, appName) == 0) {
            UserPreferenceRecord* record = (UserPreferenceRecord*)malloc(sizeof(UserPreferenceRecord));
            if (!record) {
                pthread_mutex_unlock(&cache->lock);
                return NULL;
            }
            *record = node->record;
            pthread_mutex_unlock(&cache->lock);
            return record;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&cache->lock);

    return NULL; // Not found
}

// Sample usage function to demonstrate how to use the cache
void exampleUsage() {
    PreferenceCache* cache = createCache(INITIAL_CAPACITY);

    UserPreferenceRecord record1 = {"AppA", 1, 99.5, .value.comment = "Great app!", .valueType = 0};
    free(record1.value.comment); // Normally you should manage memory carefully

    int ret = cacheInsert(cache, &record1);
    if (ret == 0) {
        UserPreferenceRecord* retrieved = cacheRetrieve(cache, "AppA");
        if (retrieved) {
            printf("Retrieved: %s, Version: %d, Performance: %.2f\n",
                   retrieved->appName,
                   retrieved->appVersion,
                   retrieved->performanceMetric);
            free(retrieved->value.comment); // Free the dynamically allocated comment
            free(retrieved);
        }
    }

    freeCache(cache);
}
```']

