    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;  // Mutex for thread safety
} DynamicLinkedList;

// Function to create a new node
Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

// Initialize the linked list
void init_list(DynamicLinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

// Insert a node at the end of the list
void insert_node(DynamicLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);

    pthread_mutex_lock(&list->mutex);

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* temp = list->head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }

    pthread_mutex_unlock(&list->mutex);
}

// Delete a node by RX_UE_INFORMATION_TAG
bool delete_node(DynamicLinkedList* list, unsigned long tag) {
    pthread_mutex_lock(&list->mutex);

    Node *temp = list->head, *prev = NULL;

    while (temp != NULL && temp->data.RX_UE_INFORMATION_TAG != tag) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) {  // Not found
        pthread_mutex_unlock(&list->mutex);
        return false;
    }

    if (prev == NULL) {
        list->head = temp->next;  // Head needs to be updated
    } else {
        prev->next = temp->next;
    }

    free(temp);

    pthread_mutex_unlock(&list->mutex);
    return true;
}

// Traverse the linked list and print data
void traverse_list(DynamicLinkedList* list) {
    pthread_mutex_lock(&list->mutex);

    Node* current = list->head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %lu, RNTI: %lu, CRCFLAG: %d\n",
               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.CRC_INDICATION_REL8_TAG.CRCFLAG);
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
}

// Function to free the entire list
void free_list(DynamicLinkedList* list) {
    pthread_mutex_lock(&list->mutex);

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;

    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

// Function to generate a random CRC flag
void set_random_crc_flag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu) {
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }
}

int main() {
    DynamicLinkedList list;
    init_list(&list);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T data1 = {1, 12345};
    set_random_crc_flag(&data1);
    insert_node(&list, data1);

    NFAPI_CRC_INDICATION_PDU_T data2 = {2, 67890};
    set_random_crc_flag(&data2);
    insert_node(&list, data2);

    traverse_list(&list);

    delete_node(&list, 1);
    traverse_list(&list);

    free_list(&list);
    return 0;
}
