        size_t numStations = rand() % MAX_STATIONS_PER_EVENT + 1; // Random number of stations

        for (size_t j = 0; j < numStations; ++j) {
            ASSOC_STA_INFO* stationInfo = malloc(sizeof(ASSOC_STA_INFO));
            if (!stationInfo) {
                pthread_mutex_unlock(&eventArray->lock);
                logError(MEMORY_ALLOCATION_FAILED, "Failed to allocate memory for station info");
                return MEMORY_ALLOCATION_FAILED;
            }

            unsigned char macAddr[MAC_ADDR_SIZE] = {0xAA, 0xBB, 0xCC, 0xDD, 0xEE, (unsigned char)(j + i * MAX_STATIONS_PER_EVENT)};
            memcpy(stationInfo->macAddr, macAddr, MAC_ADDR_SIZE);

            snprintf(stationInfo->ssid, SSID_MAX_LEN, "SSID_%zu", j); // Simulated SSID

            eventArray->events[i].stations[j] = stationInfo;
        }

        eventArray->events[i].numStations = numStations;
    }

    eventArray->count = numEvents;
    pthread_mutex_unlock(&eventArray->lock);
    return SUCCESS;
}

// Function to free allocated resources
void cleanupNetworkEvents(NetworkEventArray* eventArray) {
    if (eventArray == NULL) return;

    pthread_mutex_lock(&eventArray->lock);

    for (size_t i = 0; i < eventArray->count; ++i) {
        for (size_t j = 0; j < eventArray->events[i].numStations; ++j) {
            free(eventArray->events[i].stations[j]);
        }
    }

    pthread_mutex_unlock(&eventArray->lock);
    pthread_mutex_destroy(&eventArray->lock);
}

