    ErrorCode result = initNetworkEvents(&networkEvents, 10);

    if (result == SUCCESS) {
        printf("Network events initialized successfully.\n");
    } else {
        printf("Failed to initialize network events.\n");
    }

    cleanupNetworkEvents(&networkEvents);
    return 0;
}
