#define MAX_TREE_SIZE 1024

typedef struct {
    int value;
} record;

typedef struct node {
    int key;
    struct node *left, *right;
    char position; // 'L' for left child, 'R' for right child
} node_t;

typedef struct {
    pthread_mutex_t lock;
    node_t **nodes;
    size_t count;
    size_t capacity;
} bstree_t;

typedef enum { SUCCESS, MEMORY_ERROR, INSERTION_ERROR } status_t;

status_t create_bstree(bstree_t *tree, size_t initial_capacity);
void destroy_bstree(bstree_t *tree);
int rand_int_range(int min, int max);
node_t* create_node();
status_t insert_node(bstree_t *tree, node_t *root, int key, char position);
void free_tree(node_t *root);
void log_tree(const bstree_t *tree);

// Thread-safe random number generator initialization
