DynamicList* create_list();
int add_element(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T element);
void serialize_list(const char *filename, const DynamicList *list);
void free_list(DynamicList *list);

// Helper functions for error logging and performance monitoring
void log_error(const char *message) {
    // Implement a simple logging mechanism
    fprintf(stderr, "Error: %s\n", message);
}

void log_performance(const char *message) {
    // Implement performance metric logging
    printf("Performance: %s\n", message);
}

DynamicList* create_list() {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) {
        log_error("Failed to allocate memory for list");
        return NULL;
    }

    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(10, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        log_error("Failed to allocate memory for initial data array");
        return NULL;
    }

    list->size = 0;
    list->capacity = 10;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

int add_element(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (pthread_mutex_lock(&list->lock)) {
        log_error("Failed to lock mutex");
        return -1;
    }

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->lock);
            log_error("Failed to reallocate memory for data array");
            return -1;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    list->data[list->size] = element;
    list->size++;

    if (pthread_mutex_unlock(&list->lock)) {
        log_error("Failed to unlock mutex");
        return -1;
    }

    return 0;
}

void serialize_list(const char *filename, const DynamicList *list) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        log_error("Failed to open file for writing");
        return;
    }

    pthread_mutex_lock(&list->lock);

    size_t written = fwrite(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->size, file);
    if (written != list->size) {
        log_error("Failed to write all elements to file");
    } else {
        log_performance("Serialization successful");
    }

    pthread_mutex_unlock(&list->lock);

    fclose(file);
}

void free_list(DynamicList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    free(list->data);
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    DynamicList *list = create_list();
    if (!list) return -1;

    srand(time(NULL));

    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T element;
        element.RX_UE_INFORMATION_TAG = rand() % 100000;
        element.RNTI = rand() % 10000;
        element.CRCFLAG = rand() & 1;

        if (add_element(list, element) != 0) {
            log_error("Failed to add element");
            break;
        }
    }

    serialize_list("crc_indication.bin", list);
    free_list(list);

    return 0;
}
