} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
    size_t size;
} LinkedList;

LinkedList* create_list() {
    LinkedList* list = malloc(sizeof(LinkedList));
    if (list) {
        list->head = NULL;
        pthread_mutex_init(&list->lock, NULL);
        list->size = 0;
    }
    return list;
}

void destroy_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int insert_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!list || list->size >= MAX_NODES) return -1;

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

int delete_node(LinkedList* list, RX_UE_INFORMATION_TAG ue_info_tag) {
    if (!list || !list->head) return -1;

    Node *current = list->head, *prev = NULL;
    pthread_mutex_lock(&list->lock);
    while (current != NULL && current->data.ue_info_tag != ue_info_tag) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Not found
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    list->size--;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

void traverse_list(LinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        callback(current->data);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

