import "memory_pool.h" // Assume this is a custom header for your memory pool

#define MAX_RECORDS 1000
#define MIN_INT_RANGE 1
#define MAX_INT_RANGE 100
#define KEY_SIZE sizeof(int)

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t count;
    pthread_mutex_t lock; // Lock for thread safety during updates
} resource_bundle;

// Function prototypes
resource_bundle* create_resource_bundle(const char *filename);
void destroy_resource_bundle(resource_bundle *rb);
int load_from_file(resource_bundle *rb, const char *filename);
void insert_record(resource_bundle *rb, int key, record rec);
record* lookup_key(resource_bundle *rb, int key);
void update_real_time_data(resource_bundle *rb);

// Function to create a resource bundle
resource_bundle* create_resource_bundle(const char *filename) {
    resource_bundle *rb = memory_pool_alloc(sizeof(resource_bundle));
    if (!rb) return NULL;

    rb->offsets = memory_pool_alloc(MAX_RECORDS * sizeof(long));
    rb->keys = memory_pool_alloc(MAX_RECORDS * KEY_SIZE);
    rb->records = memory_pool_alloc(MAX_RECORDS * sizeof(record));
    rb->count = 0;

    pthread_mutex_init(&rb->lock, NULL);

    load_from_file(rb, filename);

    return rb;
}

// Function to destroy a resource bundle
void destroy_resource_bundle(resource_bundle *rb) {
    if (!rb) return;

    memory_pool_free(rb->offsets);
    memory_pool_free(rb->keys);
    memory_pool_free(rb->records);

    pthread_mutex_destroy(&rb->lock);
    memory_pool_free(rb);
}

// Function to load data from a file
int load_from_file(resource_bundle *rb, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return 0;

    int key;
    long offset;
    while (fscanf(file, "%ld %d", &offset, &key) == 2 && rb->count < MAX_RECORDS) {
        pthread_mutex_lock(&rb->lock);
        rb->offsets[rb->count] = offset;
        rb->keys[rb->count] = key;
        rb->records[rb->count].value = rand() % (MAX_INT_RANGE - MIN_INT_RANGE + 1) + MIN_INT_RANGE;
        rb->count++;
        pthread_mutex_unlock(&rb->lock);
    }

    fclose(file);

    return rb->count;
}

// Function to insert a record
void insert_record(resource_bundle *rb, int key, record rec) {
    pthread_mutex_lock(&rb->lock);

    if (rb->count < MAX_RECORDS) {
        rb->keys[rb->count] = key;
        rb->records[rb->count] = rec;
        rb->offsets[rb->count] = 0; // Placeholder for offsets logic
        rb->count++;
    }

    pthread_mutex_unlock(&rb->lock);
}

// Function to lookup a record by key
record* lookup_key(resource_bundle *rb, int key) {
    for (size_t i = 0; i < rb->count; ++i) {
        if (rb->keys[i] == key) return &rb->records[i];
    }

    return NULL;
}

// Function to update real-time data
