// Function to simulate DNS resolution with retry logic
int resolve_dns_with_retry(const char *hostname, char *ip_buffer) {
    int retries = 0;
    struct hostent *host;
    time_t start_time = time(NULL);

    while (retries <= MAX_RETRIES) {
        if (time(NULL) - start_time > 100) { // Ensure timeout after 100 ms
            return -1; // DNS resolution failed due to timeout
        }

        host = gethostbyname(hostname);
        if (host != NULL && host->h_addrtype == AF_INET) {
            inet_ntop(AF_INET, host->h_addr_list[0], ip_buffer, INET_ADDRSTRLEN);
            return 0; // Success
        }

        int retry_delay_ms = RETRY_DELAY_BASE_MS * (1 << retries);
        usleep(retry_delay_ms * 1000); // Exponential backoff in microseconds
        retries++;
    }

    return -1; // DNS resolution failed after retries
}

// Function to dynamically initialize and populate NFAPI_CRC_INDICATION_PDU_T structures
int populate_nfa_crc_indication_pdu_list(size_t num_pdu, NFAPI_CRC_INDICATION_PDU_T **pdu_list) {
    *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_pdu * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdu_list == NULL) return -1; // Memory allocation failure

    srand(time(NULL)); // Seed random number generator
    for (size_t i = 0; i < num_pdu; ++i) {
        (*pdu_list)[i].RX_UE_INFORMATION_TAG = rand() % 65536; // Random 16-bit value
        (*pdu_list)[i].RNTI = rand() % 4294967296UL; // Random 32-bit value
        (*pdu_list)[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random 0 or 1
    }

    char ip_buffer[INET_ADDRSTRLEN];
    if (resolve_dns_with_retry("example.com", ip_buffer) != 0) {
        fprintf(stderr, "Warning: DNS resolution failed for example.com\n");
        return -1;
    }

    // Validate the integrity of the IP address (basic check)
    struct sockaddr_in sa;
    if (inet_pton(AF_INET, ip_buffer, &(sa.sin_addr)) <= 0) {
        free(*pdu_list);
        return -1; // Invalid IP address
    }

    return 0; // Success
}
