typedef struct {
    char *name;
    int priority;
    void *data;
} item;

#define BUFFER_SIZE 256

// Function to allocate and initialize an array of items
item* create_items(int count) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // For concurrency handling
    item *items = NULL;
    char buffer[BUFFER_SIZE];

    if (count <= 0) return NULL;

    // Allocate memory for the items array
    items = (item *)malloc(count * sizeof(item));
    if (!items) {
        log_error("Failed to allocate memory for items array.");
        goto cleanup;
    }

    for (int i = 0; i < count; ++i) {
        snprintf(buffer, BUFFER_SIZE, "Item_%d", i);

        // Validate name using external library function
        if (!validate_name(buffer)) {
            log_error("Name validation failed.");
            goto cleanup;
        }

        pthread_mutex_lock(&lock);

        items[i].name = strdup(buffer);  // Allocate and copy the unique identifier
        if (!items[i].name) {
            log_error("Failed to allocate memory for item name.");
            pthread_mutex_unlock(&lock);
            goto cleanup;
        }

        size_t length = strlen(items[i].name) + 1;  // Include null terminator
        items[i].data = malloc(length);             // Allocate buffer for data

        if (!items[i].data) {
            log_error("Failed to allocate memory for item data.");
            pthread_mutex_unlock(&lock);
            goto cleanup;
        }

        memcpy(items[i].data, items[i].name, length);  // Copy name into data

        items[i].priority = i;  // Set priority (could be customized)

        pthread_mutex_unlock(&lock);

        log_info("Initialized item %d: %s", i, buffer);
    }

    return items;

cleanup:
    if (items) {
        for (int i = 0; i < count; ++i) {
            free(items[i].name);
            free(items[i].data);
        }
        free(items);
    }

