// Custom memory pool allocator structure
typedef struct MemoryPool {
    size_t element_size;
    size_t capacity;
    size_t count;
    void *pool;
    pthread_mutex_t lock; 
} MemoryPool;

MemoryPool* create_memory_pool(size_t element_size, size_t initial_capacity) {
    MemoryPool *mp = (MemoryPool*) malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->element_size = element_size;
    mp->capacity = initial_capacity;
    mp->count = 0;
    mp->pool = malloc(element_size * initial_capacity);
    pthread_mutex_init(&mp->lock, NULL);

    return mp;
}

void* memory_pool_alloc(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->count == mp->capacity) { // Resize if necessary
        size_t new_capacity = mp->capacity * 2;
        void *new_pool = realloc(mp->pool, mp->element_size * new_capacity);
        if (!new_pool) {
            pthread_mutex_unlock(&mp->lock);
            return NULL;
        }
        mp->pool = new_pool;
        mp->capacity = new_capacity;
    }

    void *allocated_memory = ((char*)mp->pool) + (mp->count * mp->element_size);
    mp->count++;
    pthread_mutex_unlock(&mp->lock);

    return allocated_memory;
}

void memory_pool_free(MemoryPool *mp, void *ptr) {
    // Implement if necessary for specific use cases
    // Typically not used in a custom pool allocator
}

void destroy_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

typedef struct Collection {
    MemoryPool *record_pool;
    Record **records; // Dynamic array of pointers to records
    size_t count;
    size_t capacity;
    pthread_rwlock_t rwlock;
} Collection;

Collection* create_collection(size_t initial_capacity) {
    Collection *col = (Collection*) malloc(sizeof(Collection));
    if (!col) return NULL;

    col->record_pool = create_memory_pool(sizeof(Record), initial_capacity);
    col->records = (Record**) memory_pool_alloc(col->record_pool);
    for (size_t i = 0; i < initial_capacity; ++i) {
        ((char*)col->records)[i * sizeof(Record*)] = NULL;
    }
    col->count = 0;
    col->capacity = initial_capacity;
    pthread_rwlock_init(&col->rwlock, NULL);

    return col;
}

void* find_record(Collection *col, int key) {
    pthread_rwlock_rdlock(&col->rwlock);
    for (size_t i = 0; i < col->count; ++i) {
        if (col->records[i] && col->records[i]->key == key) {
            void *record_ptr = col->records[i];
            pthread_rwlock_unlock(&col->rwlock);
            return record_ptr;
        }
    }
    pthread_rwlock_unlock(&col->rwlock);
    return NULL;
}

int update_record(Collection *col, int key, long offset, void *record_data, const char *metadata) {
    pthread_rwlock_wrlock(&col->rwlock);

    Record *record = (Record*) find_record(col, key);
    if (!record) {
        // Allocate new record if not found
        record = (Record*) memory_pool_alloc(col->record_pool);
        if (!record) {
            pthread_rwlock_unlock(&col->rwlock);
            return -1;
        }
        if (col->count == col->capacity) { // Resize records array
            size_t new_capacity = col->capacity * 2;
            Record **new_records = (Record**) memory_pool_alloc(col->record_pool);
            for (size_t i = 0; i < col->capacity; ++i) {
                ((char*)new_records)[i * sizeof(Record*)] = ((char*)col->records)[i * sizeof(Record*)];
            }
            free(((char*)col->records));
            col->records = new_records;
            col->capacity = new_capacity;
        }

        record->key = key;
        col->records[col->count++] = record;
    }

    // Update the existing record
    record->offset = offset;
    record->record_data = record_data;
    snprintf(record->metadata, sizeof(record->metadata), "%s", metadata);

    pthread_rwlock_unlock(&col->rwlock);
    return 0; // Success
}

void destroy_collection(Collection *col) {
    for (size_t i = 0; i < col->count; ++i) {
        free(col->records[i]);  // Assuming dynamic allocation of record_data
    }
    pthread_rwlock_destroy(&col->rwlock);
    memory_pool_free(col->record_pool, col->records); 
    destroy_memory_pool(col->record_pool);
    free(col);
}

// Example usage (not part of the solution)
int main() {
    Collection *col = create_collection(INITIAL_CAPACITY);

    update_record(col, 1, 100, "Record Data 1", "Meta1");
    update_record(col, 2, 200, "Record Data 2", "Meta2");

    Record *record = (Record*) find_record(col, 1);
    if (record) {
        printf("Key: %d, Offset: %ld\n", record->key, record->offset);
    }

    destroy_collection(col);

    return 0;
}
```

This code provides a thread-safe dynamic collection management system using custom memory pools and supports concurrent access with read-write locks. It addresses efficient resizing and updates without reallocating the entire structure.']

