#define MAX_EVENTS 10000
#define DEFAULT_PRECISION_RANGE 10
#define DEFAULT_TIMESTAMP_RANGE (60 * 60) // 1 hour

typedef struct {
    time_t timestamp;
    int precision;
    char message[256];
} Event;

typedef struct {
    int valid_RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
    Event events[MAX_EVENTS];
    size_t num_events;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int dns_resolve(const char* hostname, struct in_addr* ip) {
    struct hostent *host_entry;
    struct in_addr **addr_list;
    int addr_count, i;

    if ((host_entry = gethostbyname(hostname)) == NULL) {
        fprintf(stderr, "DNS resolution failed for %s\n", hostname);
        return -1;
    }

    addr_list = (struct in_addr **) host_entry->h_addr_list;
    addr_count = host_entry->h_length;

    // Assume the first resolved IP address is valid
    for (i = 0; i < addr_count; ++i) {
        if (addr_list[i] != NULL) {
            *ip = *addr_list[i];
            return 0;
        }
    }

    return -1;
}

void generate_random_event(Event* event, const char* messages[], size_t message_count) {
    event->timestamp = rand() % DEFAULT_TIMESTAMP_RANGE;
    event->precision = rand() % DEFAULT_PRECISION_RANGE;
    int msg_index = rand() % message_count;
    strncpy(event->message, messages[msg_index], sizeof(event->message));
}

int validate_event_data(Event* events, size_t num_events) {
    for (size_t i = 0; i < num_events; ++i) {
        if (events[i].timestamp < 0 || events[i].precision < 0 || strlen(events[i].message) == 0) {
            return -1;
        }
    }
    return 0;
}

int compare_events(const void* a, const void* b) {
    Event* eventA = (Event*)a;
    Event* eventB = (Event*)b;
    if (eventA->timestamp != eventB->timestamp)
        return (eventA->timestamp > eventB->timestamp) - (eventA->timestamp < eventB->timestamp);
    return 0; // Maintain stability
}

NFAPI_CRC_INDICATION_PDU_T* initialize_event_array(size_t num_events, const char* hostname) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;

    pthread_mutex_lock(&mutex);
    memset(pdu, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    struct in_addr resolved_ip;
    if (dns_resolve(hostname, &resolved_ip) == -1) {
        fprintf(stderr, "DNS resolution failed. Continuing with default events.\n");
    } else {
        printf("Resolved IP: %s\n", inet_ntoa(resolved_ip));
    }

    const char* messages[] = {"Error", "Warning", "Info", "Debug"};
    size_t message_count = sizeof(messages) / sizeof(messages[0]);

    for (size_t i = 0; i < num_events; ++i) {
        if (num_events > MAX_EVENTS || !validate_event_data(&pdu->events[i], 1)) {
            generate_random_event(&pdu->events[i], messages, message_count);
            pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
        } else {
            fprintf(stderr, "Invalid data detected at index %zu. Skipping...\n", i);
            continue;
        }
    }

    qsort(pdu->events, num_events, sizeof(Event), compare_events);

    pdu->num_events = num_events;

    pthread_mutex_unlock(&mutex);

    return pdu;
}

void free_event_array(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu) {
        free(pdu);
    }
}
