#define MAX_RETRIES 5
#define BACKOFF_FACTOR 2
#define THROTTLE_THRESHOLD 100 // Example threshold for throttling

typedef struct {
    int qci;
    int rsrp; // Signal strength in dBm
    int rsrq; // Signal quality
} MeasurementReport;

