    size_t capacity;
    LTEUEContextInfo* data;
} ContextList;

// Function to generate random integers within a range
int rand_range(int min, int max) {
    return min + rand() % (max - min + 1);
}

// Callback function for writing received data from HTTP request
size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    ((char *)userp)[0] += size * nmemb;
    return size * nmemb;
}

// Function to fetch and parse JSON data using an external HTTP service
int fetch_and_parse_json(char **parsed_data, size_t *data_size) {
    CURL *curl;
    CURLcode res;
    char *url = "http://example.com/network-parameters";
    int retries = 0;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();

    if(curl) {
        while (retries < MAX_RETRIES) {
            curl_easy_setopt(curl, CURLOPT_URL, url);
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);

            char buffer[4096] = {0};
            size_t total_size = 0;

            curl_easy_setopt(curl, CURLOPT_WRITEDATA, &buffer);
            res = curl_easy_perform(curl);

            if (res == CURLE_OK) {
                *parsed_data = strdup(buffer);
                *data_size = strlen(buffer);
                break;
            } else {
                retries++;
                sleep(pow(BACKOFF_FACTOR, retries)); // Exponential backoff
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "HTTP request failed after %d attempts\n", MAX_RETRIES);
            curl_easy_cleanup(curl);
            curl_global_cleanup();
            return -1; // Error code for HTTP failure
        }
    } else {
        fprintf(stderr, "Failed to initialize CURL\n");
        return -2;
    }

    curl_easy_cleanup(curl);
    curl_global_cleanup();

    return 0; // Success
}

// Function to parse JSON data and populate LTE UE Context Information structures
