        (*context_list)->data[i].measurementReport.qci = rand_range(1, 9);
        (*context_list)->data[i].measurementReport.rsrp = rand_range(-140, -50); // dBm
        (*context_list)->data[i].measurementReport.rsrq = rand_range(-15, -3); // QdB
    }

    return 0; // Success
}

// Main function to initialize and populate LTE UE Context Information structures
int init_and_populate_contexts(ContextList **context_list) {
    char *parsed_data = NULL;
    size_t data_size = 0;

    int http_status = fetch_and_parse_json(&parsed_data, &data_size);
    if (http_status != 0) {
