        // Insert with priority handling, here using simple insertion sort for demonstration.
        size_t i;
        for (i = structure_list.count; i > 0 && structure_list.list[i - 1].priority < data.priority; --i) {
            structure_list.list[i] = structure_list.list[i - 1];
