        structure_list.last_successful_add_time = current_time;

        trigger_callback(&data.data);

        pthread_mutex_unlock(&structure_list.lock);
        log_circular_buffer("Structure added successfully");
    } else {
        release_resources(0); // Simulate resource release
        log_circular_buffer("List full, waiting for space...");
        pthread_mutex_unlock(&structure_list.lock);
