void export_to_file(Queue* queue, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    Node* current = queue->front;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
}

void enqueue(NFAPI_CRC_INDICATION_PDU_T* data) {
    sem_wait(&queue.empty_slots);
    pthread_mutex_lock(&queue.mutex);

    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = *data;
    new_node->next = NULL;

    if (queue.rear == NULL) {
        queue.front = queue.rear = new_node;
    } else {
        queue.rear->next = new_node;
        queue.rear = new_node;
    }
    queue.size++;

    pthread_mutex_unlock(&queue.mutex);
    sem_post(&queue.full_slots);
}

NFAPI_CRC_INDICATION_PDU_T* dequeue() {
    sem_wait(&queue.full_slots);
    pthread_mutex_lock(&queue.mutex);

    if (queue.front == NULL) {
        pthread_mutex_unlock(&queue.mutex);
        sem_post(&queue.empty_slots);
        return NULL;
    }

    Node* temp = queue.front;
    NFAPI_CRC_INDICATION_PDU_T* data = &temp->data;
    queue.front = queue.front->next;

    if (queue.front == NULL) {
        queue.rear = NULL;
    }

    free(temp);
    queue.size--;

    pthread_mutex_unlock(&queue.mutex);
    sem_post(&queue.empty_slots);

    return data;
}

void* producer(void* arg) {
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_from_pool();
        if (!pdu) continue;

        pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu->RNTI = rand() % 10000;
        pdu->CRCFLAG = rand() % 2;

        if (validate_and_correct_crc_tag(pdu)) {
            enqueue(pdu);
            log_creation(pdu->RNTI, pdu->CRCFLAG);
        } else {
            deallocate_to_pool(pdu); // Reallocate if invalid
        }
    }
    return NULL;
}

void* consumer(void* arg) {
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = dequeue();
        if (!pdu) continue;

        // Process data
        deallocate_to_pool(pdu);
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    init_memory_pool();

    sem_init(&queue.empty_slots, 0, MAX_QUEUE_SIZE);
    sem_init(&queue.full_slots, 0, 0);

    pthread_t producer_thread, consumer_thread;
    pthread_create(&producer_thread, NULL, producer, NULL);
    pthread_create(&consumer_thread, NULL, consumer, NULL);

    pthread_join(producer_thread, NULL);
    pthread_join(consumer_thread, NULL);

    export_to_file(&queue, "output.bin");

    return 0;
}
