    if (!list) return NULL;

    list->events = calloc(INITIAL_CAPACITY, sizeof(MAC_EVENT*));
    if (!list->events) {
        free(list);
        return NULL;
    }

    list->capacity = INITIAL_CAPACITY;
    list->count = 0;

    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);

    log_event("Event list created.");
    return list;
}

int add_event(EventList* list, MAC_EVENT* event) {
    if (!list || !event) return -1;

    pthread_mutex_lock(&list->lock);

    while (list->count == list->capacity) {
        pthread_cond_wait(&list->cond, &list->lock);
    }

    if (list->events[list->count] == NULL)
        list->events[list->count] = malloc(sizeof(MAC_EVENT));

    // Ensure proper alignment and prevent buffer overflow
    list->events[list->count]->mac_event_tag = event->mac_event_tag;
    list->events[list->count]->timestamp = event->timestamp;
    list->events[list->count]->data_length = event->data_length;

    list->events[list->count]->mac_frame_data = malloc(event->data_length);
    if (!list->events[list->count]->mac_frame_data) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    memcpy(list->events[list->count]->mac_frame_data, event->mac_frame_data, event->data_length);

    list->count++;

    // Log addition
    log_event("Event added.");

    pthread_cond_broadcast(&list->cond);
    pthread_mutex_unlock(&list->lock);

    return 0;
}

void resize_event_list(EventList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    size_t new_capacity = list->capacity * 2;
    MAC_EVENT** new_events = realloc(list->events, new_capacity * sizeof(MAC_EVENT*));
    if (new_events == NULL) {
        log_event("Failed to resize event list.");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    memset(new_events + list->capacity, 0, (new_capacity - list->capacity) * sizeof(MAC_EVENT*));

    list->events = new_events;
    list->capacity = new_capacity;

    log_event("Event list resized.");

    pthread_mutex_unlock(&list->lock);
}

void free_event_list(EventList* list) {
    if (!list) return;

    for (size_t i = 0; i < list->count; i++) {
        free(list->events[i]->mac_frame_data);
        free(list->events[i]);
    }
    free(list->events);

    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond);

