#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int key;
    long offset;
    float value;
} Record;

unsigned int simple_hash(int index, time_t current_time) {
    return (index * 2654435761u + current_time) % UINT_MAX; // A common hashing function
}

Record* manage_records(size_t n, long max_offset_limit, float min_value, float max_value, size_t* total_size) {
    if (n == 0 || max_offset_limit < 0 || min_value > max_value) return NULL;

    Record* records = malloc(n * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    time_t current_time = time(NULL);
    unsigned int keys[n];
    for (size_t i = 0; i < n; ++i) {
        keys[i] = 0;
    }

    unsigned int retry_limit = 10;
    int unique_keys_generated = 0;

    srand((unsigned int)current_time);

    for (size_t i = 0; i < n && unique_keys_generated < n; ++i) {
        pthread_mutex_lock(&lock);

        long offset = i % (max_offset_limit + 1); // Ensure offsets do not exceed limit
        float value = min_value + ((float)rand() / RAND_MAX) * (max_value - min_value);

        unsigned int hash;
        for (int attempt = 0; attempt < retry_limit; ++attempt) {
            hash = simple_hash(i, current_time);
            int is_unique = 1;

            for (size_t j = 0; j < unique_keys_generated; ++j) {
                if (keys[j] == hash) {
                    is_unique = 0;
                    break;
                }
            }

            if (is_unique) {
                keys[unique_keys_generated++] = hash;
                records[i].key = hash;
                records[i].offset = offset;
                records[i].value = value;
                break;
            }
        }

        pthread_mutex_unlock(&lock);

        if (attempt == retry_limit - 1 && unique_keys_generated < n) {
            fprintf(stderr, "Failed to generate unique key for record %zu after %d attempts\n", i + 1, retry_limit);
            free(records);
            return NULL;
        }
    }

    pthread_mutex_destroy(&lock);

    *total_size = n * sizeof(Record);
    return records;
}

void free_records(Record* records) {
    if (records) {
        free(records);
    }
}
```

