#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char *name;
    int priority;
    void *data;
} item;

typedef struct {
    item **items;
    size_t capacity;
    size_t count;
    size_t total_memory_usage;
    pthread_mutex_t lock;
} ItemCollection;

#define INITIAL_CAPACITY 10
#define MAX_ITEMS 1000

void log_message(const char *message) {
    // Placeholder for integration with the existing logging system
    printf("%s\n", message);
}

void* safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

ItemCollection* create_collection(size_t initial_capacity) {
    ItemCollection *collection = (ItemCollection*)safe_malloc(sizeof(ItemCollection));
    collection->items = (item**)safe_malloc(initial_capacity * sizeof(item*));
    if (!collection->items) {
        free(collection);
        exit(EXIT_FAILURE);
    }

    memset(collection->items, 0, initial_capacity * sizeof(item*));
    collection->capacity = initial_capacity;
    collection->count = 0;
    collection->total_memory_usage = 0;

    pthread_mutex_init(&collection->lock, NULL);

    log_message("ItemCollection created");
    return collection;
}

void free_item(item *it) {
    if (it) {
        free(it->name);
        free(it->data);
        free(it);
    }
}

int add_item(ItemCollection *collection, const char *name_template, int priority) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        item **new_items = (item**)safe_malloc(new_capacity * sizeof(item*));
        if (!new_items) {
            log_message("Failed to expand the array");
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }

        memcpy(new_items, collection->items, collection->capacity * sizeof(item*));
        memset(new_items + collection->capacity, 0, (new_capacity - collection->capacity) * sizeof(item*));

        free(collection->items);
        collection->items = new_items;
        collection->capacity = new_capacity;

        log_message("Expanded ItemCollection capacity");
    }

    item *it = (item*)safe_malloc(sizeof(item));
    char name_buffer[256];
    snprintf(name_buffer, sizeof(name_buffer), "%s%d", name_template, collection->count);

    it->name = strdup(name_buffer);
    if (!it->name) {
        free_item(it);
        pthread_mutex_unlock(&collection->lock);
        log_message("Failed to allocate memory for item name");
        return -1;
    }

    it->priority = priority;
    size_t data_size = strlen(it->name) + 1;
    it->data = safe_malloc(data_size);
    strcpy((char*)it->data, it->name);

    collection->items[collection->count++] = it;
    collection->total_memory_usage += sizeof(item) + strlen(it->name) + 1 + data_size;

    pthread_mutex_unlock(&collection->lock);

    log_message("Item added to ItemCollection");
    return 0;
}

void free_collection(ItemCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        free_item(collection->items[i]);
    }

    free(collection->items);
    pthread_mutex_unlock(&collection->lock);

    pthread_mutex_destroy(&collection->lock);
    free(collection);

    log_message("ItemCollection freed");
}

void monitor_memory_usage(const ItemCollection *collection) {
    printf("Total memory usage: %zu bytes\n", collection->total_memory_usage);
}
