        return NULL;

    MetricsManager *manager = malloc(sizeof(MetricsManager));
    manager->capacity = initialSize;
    manager->count = 0;
    manager->metricsArray = malloc(manager->capacity * sizeof(NetworkPerformanceMetrics));
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void resizeMetricsArray(MetricsManager *manager) {
    size_t newCapacity = manager->capacity * 2;
    NetworkPerformanceMetrics *newArray = realloc(manager->metricsArray, newCapacity * sizeof(NetworkPerformanceMetrics));

    if (newArray != NULL) {
        manager->metricsArray = newArray;
        manager->capacity = newCapacity;
    } else {
        perror("Failed to resize metrics array");
        exit(EXIT_FAILURE);
    }
}

void populateNetworkMetrics(MetricsManager *manager, size_t numEntries, ...) {
