        if (manager->count == manager->capacity)
            resizeMetricsArray(manager);

        int cellId = va_arg(args, int);
        NetworkPerformanceMetrics *metric = &manager->metricsArray[manager->count];

        metric->cellId = cellId;
        metric->timestamp = time(NULL);
        metric->throughput = generateThroughput();

        manager->count++;
