typedef struct {
    int priority;
    char *buffer;
    atomic_int ref_count;
    unsigned long task_id;
} Task;

#define INITIAL_THREADS 4
#define MAX_TASKS 1024

pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t task_cond = PTHREAD_COND_INITIALIZER;

Task *task_pool[MAX_TASKS];
int num_tasks = 0;
unsigned long seed = 1; // User-provided seed for reproducibility

void initialize_task(Task **task, char *buffer, int priority) {
    if (*task == NULL) {
        *task = (Task *)malloc(sizeof(Task));
        (*task)->priority = priority;
        (*task)->buffer = strdup(buffer);
        atomic_store(&(*task)->ref_count, 1);
    } else {
        atomic_fetch_add(&(*task)->ref_count, 1);
    }
}

unsigned long generate_task_id() {
    return seed++;
}

void *worker_thread(void *arg) {
    while (1) {
        Task *current_task = NULL;

        pthread_mutex_lock(&pool_mutex);

        for (int i = 0; i < num_tasks && current_task == NULL; ++i) {
            if (atomic_load(&task_pool[i]->ref_count) > 0) {
                current_task = task_pool[i];
            }
        }

        if (current_task) {
            atomic_fetch_sub(&current_task->ref_count, 1);
        } else {
            pthread_cond_wait(&task_cond, &pool_mutex);
            continue;
        }

        pthread_mutex_unlock(&pool_mutex);

        // Process the task
        process_task(current_task);

        free(current_task->buffer);
        free(current_task);
    }
    return NULL;
}

void add_task(char *buffer, int priority) {
    Task *new_task = (Task *)malloc(sizeof(Task));
    new_task->priority = priority;
    new_task->buffer = strdup(buffer);
    new_task->task_id = generate_task_id();
    atomic_store(&new_task->ref_count, 1);

    pthread_mutex_lock(&pool_mutex);
    if (num_tasks < MAX_TASKS) {
        task_pool[num_tasks++] = new_task;
    }
    pthread_cond_broadcast(&task_cond);
    pthread_mutex_unlock(&pool_mutex);
}

void manage_thread_pool(int initial_threads) {
    pthread_t threads[initial_threads];

