        if (workload > num_tasks && initial_threads < MAX_TASKS) {
            pthread_t new_thread;
            if (pthread_create(&new_thread, NULL, worker_thread, NULL) == 0) {
                initial_threads++;
            }
        } else if (workload < num_tasks / 2 && initial_threads > INITIAL_THREADS) {
            // Consider reducing threads or using a more sophisticated approach
        }
