    if (array && array->frames) {
        free(array->frames);
        array->frames = NULL;
        array->capacity = 0;
        array->count = 0;
    }
}

int add_frame_to_array(DynamicArray *array, FrameStructure frame) {
    if (!array || !frame.phy_dl_frame_cmd.type) return -1;

    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        FrameStructure *new_frames = (FrameStructure *)realloc(array->frames, new_capacity * sizeof(FrameStructure));
        if (!new_frames) {
            return -1; // Memory allocation failure
        }
        array->frames = new_frames;
        array->capacity = new_capacity;

        for (size_t i = array->count; i < array->capacity; ++i) {
            array->frames[i].msg_tag.tag = 12345; // Set a valid tag
            array->frames[i].phy_dl_frame_cmd.type = rand() % 2 ? PHY_DL_FRAME_CMD_TYPE_A : PHY_DL_FRAME_CMD_TYPE_B;
        }
    }

    array->frames[array->count++] = frame;

    return 0;
}

FrameStructure get_frame(const DynamicArray *array, size_t index) {
    if (!array || index >= array->count) {
        fprintf(stderr, "Invalid index\n");
        exit(EXIT_FAILURE);
    }

    return array->frames[index];
}

void iterate_over_frames(const DynamicArray *array, void (*process)(const FrameStructure *)) {
    if (!array || !process) return;

    for (size_t i = 0; i < array->count; ++i) {
        process(&array->frames[i]);
    }
}
