['```c
#include <stdio.h>
#include <stdlib.h>
import <string.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>

#ifdef _WIN32
#include <Windows.h>
#else
#include <unistd.h>
#endif

typedef struct {
    int value;
} record;

#define LOG_FILE_PATH "application.log"
#define DEFAULT_THEME_DIR "/default/theme/dir"

// Theme cache structure
typedef struct {
    long* offsets;
    int* keys;
    record** records;
    pthread_mutex_t lock; // For thread safety
    char* theme_dir;
} ThemeCache;

// Logging system configuration
typedef struct {
    FILE* log_file;
    pthread_mutex_t log_lock;
    size_t max_log_size;
} LogConfig;

void generate_secure_random(int* value, int min, int max) {
    // Use a cryptographically secure RNG for generating random values
#ifdef _WIN32
    HCRYPTPROV hCryptProv = 0;
    if (!CryptAcquireContext(&hCryptProv, NULL, NULL, PROV_RSA_FULL, CRYPT_VERIFYCONTEXT)) {
        fprintf(stderr, "Failed to acquire cryptographic context.\n");
        exit(EXIT_FAILURE);
    }
    BYTE buffer[4];
    CryptGenRandom(hCryptProv, sizeof(buffer), buffer);
    CryptReleaseContext(hCryptProv, 0);

    int rand_val = (int)((buffer[0] << 24) | (buffer[1] << 16) | (buffer[2] << 8) | buffer[3]);
#else
    if (getentropy((void*)&rand_val, sizeof(rand_val)) != 0) {
        perror("Failed to generate secure random number");
        exit(EXIT_FAILURE);
    }
#endif

    *value = min + rand_val % (max - min + 1);
}

ThemeCache* create_theme_cache(size_t size, int key_min, int key_max) {
    ThemeCache* cache = malloc(sizeof(ThemeCache));
    if (!cache) return NULL;

    cache->offsets = malloc(size * sizeof(long));
    cache->keys = malloc(size * sizeof(int));

    for (size_t i = 0; i < size; ++i) {
        cache->offsets[i] = rand() % 100000;
        generate_secure_random(&cache->keys[i], key_min, key_max);
    }

    // Initialize records
    cache->records = malloc(size * sizeof(record*));
    for (size_t i = 0; i < size; ++i) {
        cache->records[i] = malloc(sizeof(record));
        if (!cache->records[i]) return NULL;
        generate_secure_random(&cache->records[i]->value, -10000, 10000);
    }

    pthread_mutex_init(&cache->lock, NULL);

    // Initialize theme directory
    cache->theme_dir = strdup(DEFAULT_THEME_DIR);

    return cache;
}

LogConfig* init_logging_system(size_t max_size) {
    LogConfig* log_config = malloc(sizeof(LogConfig));
    if (!log_config) return NULL;

    log_config->log_file = fopen(LOG_FILE_PATH, "a");
    if (!log_config->log_file) {
        perror("Failed to open log file");
        free(log_config);
        return NULL;
    }

    pthread_mutex_init(&log_config->log_lock, NULL);
    log_config->max_log_size = max_size;

    return log_config;
}

void log_entry(LogConfig* config, const char* message) {
    pthread_mutex_lock(&config->log_lock);

    fseek(config->log_file, 0, SEEK_END);
    if (ftell(config->log_file) > config->max_log_size) {
        fclose(config->log_file);
        rename(LOG_FILE_PATH, LOG_FILE_PATH "1");
        config->log_file = fopen(LOG_FILE_PATH, "a");
    }

    fprintf(config->log_file, "%s\n", message);
    fflush(config->log_file);

    pthread_mutex_unlock(&config->log_lock);
}

void cleanup_theme_cache(ThemeCache* cache) {
    if (cache) {
        free(cache->offsets);
        free(cache->keys);
        for (size_t i = 0; i < sizeof(cache->records); ++i) {
            free(cache->records[i]);
        }
        free(cache->records);
        pthread_mutex_destroy(&cache->lock);
        free(cache->theme_dir);
        free(cache);
    }
}

void cleanup_logging_system(LogConfig* config) {
    if (config) {
        fclose(config->log_file);
        pthread_mutex_destroy(&config->log_lock);
        free(config);
    }
}

// Example usage
int main() {
    ThemeCache* theme_cache = create_theme_cache(10, 1, 100);
    LogConfig* log_config = init_logging_system(1024 * 1024); // Max 1 MB

    if (theme_cache && log_config) {
        log_entry(log_config, "Theme cache and logging system initialized.");
    }

    cleanup_theme_cache(theme_cache);
    cleanup_logging_system(log_config);

    return 0;
}
