        nfa_crc_pdu->records[i].offset = rand() % 100000;

        // Simulate the Key Array with unique random int keys
        do {
            nfa_crc_pdu->records[i].key = rand() % 100000;
        } while (i > 0 && nfa_crc_pdu->records[i].key == nfa_crc_pdu->records[i - 1].key);

        // Allocate and initialize buffer for each record
        size_t buffer_size = snprintf(NULL, 0, "Buffer_%zu") + 1;
        char *buffer = malloc(buffer_size);
        if (!buffer) {
            fprintf(stderr, "Memory allocation failed for buffer\n");
            free_memory_pool(nfa_crc_pdu->records, num_elements);
            free_memory_pool(nfa_crc_pdu->unions, num_elements);
            free(nfa_crc_pdu->buffers);
            pthread_mutex_destroy(&nfa_crc_pdu->mutex);
            free(nfa_crc_pdu);
            exit(EXIT_FAILURE);
        }
        snprintf(buffer, buffer_size, "Buffer_%zu");
        nfa_crc_pdu->buffers[i] = buffer;

        // Populate union with a random number
        if (rand() % 2) {
            nfa_crc_pdu->unions[i].l_val = rand() % 100001;
        } else {
            nfa_crc_pdu->unions[i].i_val = rand() % 100001;
        }
    }

    pthread_mutex_unlock(&nfa_crc_pdu->mutex);

    return nfa_crc_pdu;
}

// Function to free memory pool
void free_memory_pool(void *pool, size_t num_elements) {
    if (pool) {
        free(pool);
    }
}

// Function to destroy the NFAPI_CRC_INDICATION_PDU_T array
void destroy_nfa_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T *nfa_crc_pdu) {
    if (!nfa_crc_pdu) return;

    pthread_mutex_lock(&nfa_crc_pdu->mutex);

    for (size_t i = 0; i < nfa_crc_pdu->count; ++i) {
        free(nfa_crc_pdu->buffers[i]);
    }

