#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 10000
#define MAX_OFFSET 1000000
#define HASH_TABLE_SIZE 4096

typedef struct {
    int key;
    long offset;
    float value;
} Record;

typedef struct {
    uint32_t keys[HASH_TABLE_SIZE];
    pthread_mutex_t mutex;
} HashTable;

int log_collisions = 0;
pthread_mutex_t logging_lock = PTHREAD_MUTEX_INITIALIZER;

uint32_t hash_function(int index, time_t system_time, unsigned int secret_seed) {
    return (index ^ system_time ^ secret_seed) % HASH_TABLE_SIZE;
}

void log_collision() {
    pthread_mutex_lock(&logging_lock);
    log_collisions++;
    fprintf(stderr, "Key collision at %ld\n", time(NULL));
    pthread_mutex_unlock(&logging_lock);
}

int validate_key(HashTable* hash_table, uint32_t key) {
    uint32_t hashed_key = key % HASH_TABLE_SIZE;
    pthread_mutex_lock(&(hash_table->mutex));

    int exists = (hash_table->keys[hashed_key] == key);

    if (!exists) {
        hash_table->keys[hashed_key] = key;
    } else {
        log_collision();
    }

    pthread_mutex_unlock(&(hash_table->mutex));
    return !exists;
}

Record* allocate_records(size_t n, unsigned int secret_seed, float value_threshold, int *status_code) {
    if (n > MAX_RECORDS) {
        *status_code = -1;
        fprintf(stderr, "Error: Requested number of records exceeds the maximum limit.\n");
        return NULL;
    }

    size_t total_size = n * sizeof(Record);
    Record* records = (Record*)malloc(total_size);

    if (!records) {
        *status_code = -2;
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    HashTable hash_table = { .keys = {0}, .mutex = PTHREAD_MUTEX_INITIALIZER };
    time_t system_time = time(NULL);

    float sum_values = 0.0f;
    for (size_t i = 0; i < n; i++) {
        records[i].offset = (i % MAX_OFFSET);

        uint32_t key = hash_function(i, system_time, secret_seed);
        while (!validate_key(&hash_table, key)) {
            key = hash_function(key + 1, system_time, secret_seed);
        }
        records[i].key = key;

        float random_value = (float)rand() / RAND_MAX;
        if (sum_values + random_value > value_threshold && i != n - 1) {
            continue; // skip to ensure threshold is not exceeded
        }

        sum_values += random_value;
        records[i].value = random_value;
    }

    *status_code = 0;
    return records;
}

void free_records(Record* records) {
    free(records);
}
```

