#include <pthread.h>

// Define the record structure
typedef struct {
    int key;
    long offset;
    float value;
} Record;

// Mutex for thread safety in multi-threaded environments
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize random number generator
void init_random() {
    srand(time(NULL));
}

// Custom hash function to generate unique keys
int generate_key(int index) {
    time_t current_time;
    pthread_mutex_lock(&mutex);
    current_time = time(NULL);
    pthread_mutex_unlock(&mutex);

    return (index * 2654435761 + current_time) % INT_MAX;
}

// Function to allocate memory for records and initialize them
Record* create_records(size_t n, long max_offset, float min_value, float max_value, int retry_limit) {
    Record *records = NULL;

    // Try allocating memory for the records array
    records = (Record*)malloc(n * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (size_t i = 0; i < n; ++i) {
        long offset = i % max_offset;

        // Generate a unique key with retry mechanism
        int key_generated = 0;
        for (int retries = 0; retries <= retry_limit; ++retries) {
            records[i].key = generate_key(i);
            if (!key_generated || (retries > 0 && !is_duplicate(records, i))) {
                key_generated = 1;
                break;
            }
        }

        if (!key_generated) {
            fprintf(stderr, "Failed to generate a unique key for record %zu\n", i);
            free(records);
            return NULL;
        }

        records[i].offset = offset;

        // Set the float value to a random number within specified range
        records[i].value = min_value + ((float)rand() / RAND_MAX) * (max_value - min_value);

    }

    return records;
}

// Function to check for duplicate keys in the record array
int is_duplicate(Record *records, size_t current_index) {
    for (size_t i = 0; i < current_index; ++i) {
        if (records[i].key == records[current_index].key) {
            return 1;
        }
    }
    return 0;
}

// Function to free allocated memory
void free_records(Record *records) {
    free(records);
}

// Example main function for testing
int main() {
    size_t n = 100; // Number of records
    long max_offset = 10;
    float min_value = 0.0f, max_value = 1.0f;
    int retry_limit = 5;

    init_random();

    Record *records = create_records(n, max_offset, min_value, max_value, retry_limit);
    if (!records) {
        return EXIT_FAILURE;
    }

    // Use the records...

    free_records(records);

    return EXIT_SUCCESS;
}
