['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct NetworkPerformanceMetrics {
    int cellId;
    time_t timeStamp;
    double throughput;
    double movingAverageThroughput;
} NetworkPerformanceMetrics;

typedef struct ListNode {
    NetworkPerformanceMetrics data;
    struct ListNode *next;
} ListNode;

typedef struct {
    ListNode *head;
    pthread_mutex_t lock;
} LinkedList;

void initRandom(int seed) {
    srand(seed);
}

double getRandomThroughput(double min, double max) {
    return (min + ((double)rand() / RAND_MAX) * (max - min));
}

LinkedList* createLinkedList() {
    LinkedList *list = malloc(sizeof(LinkedList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void addMetric(LinkedList *list, NetworkPerformanceMetrics metric) {
    ListNode *newNode = malloc(sizeof(ListNode));
    newNode->data = metric;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

NetworkPerformanceMetrics* allocateAndInitialize(int count, int seed, double minThroughput, double maxThroughput) {
    NetworkPerformanceMetrics *metricsArray = malloc(count * sizeof(NetworkPerformanceMetrics));
    LinkedList *metricList = createLinkedList();

    initRandom(seed);

    for (int i = 0; i < count; ++i) {
        metricsArray[i].cellId = i;
        metricsArray[i].timeStamp = time(NULL);
        metricsArray[i].throughput = getRandomThroughput(minThroughput, maxThroughput);

        double sum = 0.0;
        int avgCount = 0;

        pthread_mutex_lock(&metricList->lock);
        ListNode *current = metricList->head;
        while (current && avgCount < 10) {
            sum += current->data.throughput;
            ++avgCount;
            current = current->next;
        }
        pthread_mutex_unlock(&metricList->lock);

        metricsArray[i].movingAverageThroughput = (avgCount > 0) ? (sum / avgCount) : 0.0;

        addMetric(metricList, metricsArray[i]);
    }

    return metricsArray;
}

void freeLinkedList(LinkedList *list) {
    pthread_mutex_lock(&list->lock);
    ListNode *current = list->head;
    while (current != NULL) {
        ListNode *temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    int recordCount = 1000;
    int seed = 42;
    double minThroughput = 1.0, maxThroughput = 100.0;

    NetworkPerformanceMetrics *metrics = allocateAndInitialize(recordCount, seed, minThroughput, maxThroughput);

    // Example usage of the metrics
    for (int i = 0; i < recordCount; ++i) {
        printf("Cell ID: %d, Throughput: %.2f, Moving Average: %.2f\n",
               metrics[i].cellId,
               metrics[i].throughput,
               metrics[i].movingAverageThroughput);
    }

    free(metrics);

    return 0;
}
```

