['Below is a C implementation for managing dynamic lists of custom-defined network event structures, initializing arrays, and handling memory efficiently while addressing performance constraints, scalability, error handling, and extensibility.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define constants for maximum sizes to prevent excessive memory usage.
#define MAX_OFFSETS_SIZE 1024
#define MAX_KEYS_SIZE 256

typedef struct {
    char* data;
    int value;
} record;

typedef struct {
    unsigned long mac_event_tag;
    time_t timestamp;
    void* frames; // Pointer to dynamically allocated MAC_FRAME_DATA
    size_t frame_count; // Number of frames in the list
} NetworkEvent;

// Function prototypes.
NetworkEvent* create_network_event(unsigned long mac_event_tag, time_t timestamp);
void add_mac_frame(NetworkEvent* event, const void* frame_data, size_t length);
void free_network_event(NetworkEvent* event);
int initialize_arrays(long** offsets_array, int* offsets_size,
                      int** keys_array, int* keys_size,
                      record*** records_array, int* records_count);

// Implementations
NetworkEvent* create_network_event(unsigned long mac_event_tag, time_t timestamp) {
    NetworkEvent* event = (NetworkEvent*)malloc(sizeof(NetworkEvent));
    if (!event) return NULL;

    event->mac_event_tag = mac_event_tag;
    event->timestamp = timestamp;
    event->frames = NULL; // Initially no frames
    event->frame_count = 0;

    return event;
}

void add_mac_frame(NetworkEvent* event, const void* frame_data, size_t length) {
    if (!event || !frame_data) return;

    // Resize the frames array to accommodate new data.
    void** new_frames = realloc(event->frames, (event->frame_count + 1) * sizeof(void*));
    if (!new_frames) {
        fprintf(stderr, "Memory allocation failed for frame addition.\n");
        return;
    }

    event->frames = new_frames;
    event->frames[event->frame_count] = malloc(length);
    if (!event->frames[event->frame_count]) {
        fprintf(stderr, "Memory allocation failed for frame data.\n");
        free(event->frames);
        event->frames = NULL; // Clean up
        event->frame_count--;
        return;
    }

    memcpy(event->frames[event->frame_count], frame_data, length);
    event->frame_count++;
}

void free_network_event(NetworkEvent* event) {
    if (!event) return;

    for (size_t i = 0; i < event->frame_count; ++i) {
        free(event->frames[i]);
    }
    free(event->frames);

    free(event);
}

int initialize_arrays(long** offsets_array, int* offsets_size,
                      int** keys_array, int* keys_size,
                      record*** records_array, int* records_count) {

    if (!offsets_array || !keys_array || !records_array || !offsets_size || !keys_size || !records_count)
        return -1;

    // Get user inputs for sizes.
    printf("Enter the size of offsets array (up to %d): ", MAX_OFFSETS_SIZE);
    scanf("%d", offsets_size);

    if (*offsets_size <= 0 || *offsets_size > MAX_OFFSETS_SIZE) {
        fprintf(stderr, "Invalid size for offsets array.\n");
        return -1;
    }

    printf("Enter the size of keys array (up to %d): ", MAX_KEYS_SIZE);
    scanf("%d", keys_size);

    if (*keys_size <= 0 || *keys_size > MAX_KEYS_SIZE) {
        fprintf(stderr, "Invalid size for keys array.\n");
        return -1;
    }

    // Initialize offsets.
    *offsets_array = (long*)malloc(*offsets_size * sizeof(long));
    if (!*offsets_array) {
        fprintf(stderr, "Failed to allocate memory for offsets array.\n");
        return -1;
    }

    // Initialize keys and validate input.
    *keys_array = (int*)malloc(*keys_size * sizeof(int));
    printf("Enter %d non-negative integer keys:\n", *keys_size);
    for (int i = 0; i < *keys_size; ++i) {
        int key;
        scanf("%d", &key);

        if (key < 0) {
            fprintf(stderr, "Invalid key value: %d\n", key);
            free(*offsets_array);
            free(*keys_array);
            return -1;
        }

        (*keys_array)[i] = key;
    }

    // Initialize records.
    srand(time(NULL));
    *records_count = *offsets_size;  // Same size as offsets for simplicity.
    *records_array = (record**)malloc(*records_count * sizeof(record*));
    if (!*records_array) {
        fprintf(stderr, "Failed to allocate memory for records array.\n");
        free(*offsets_array);
        free(*keys_array);
        return -1;
    }

    for (int i = 0; i < *records_count; ++i) {
        (*records_array)[i] = (record*)malloc(sizeof(record));
        if (!(*records_array)[i]) {
            fprintf(stderr, "Failed to allocate memory for a record.\n");

            // Free already allocated records.
            while (i > 0 && (*records_array)[--i])
                free((*records_array)[i]);

            free(*records_array);
            free(*offsets_array);
            free(*keys_array);

            return -1;
        }

        (*records_array)[i]->data = (char*)malloc(sizeof(char) * *offsets_size);
        if (!(*records_array)[i]->data) {
            fprintf(stderr, "Failed to allocate memory for record data.\n");

            // Free already allocated records.
            while (i >= 0 && (*records_array)[i])
                free((*records_array)[i--]);

            free(*records_array);
            free(*offsets_array);
            free(*keys_array);

            return -1;
        }

        memset((*records_array)[i]->data, 0, *offsets_size);
        (*records_array)[i]->value = rand() % 101; // Random value between 0 and 100.
    }

    return 0;
}
