#define MAX_STRUCTURE_SIZE 64 * 1024 // 64 KB
#define MEMORY_LIMIT 50 * 1024 * 1024 // 50 MB

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG; // Randomly set
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    int priority; // 1 for high-priority, 0 for normal
    struct Node* next;
    time_t timestamp; // Timestamp to determine the oldest entry
} Node;

typedef struct {
    Node* head;
    size_t current_memory_usage;
    pthread_mutex_t lock;
    int paused;
} LinkedList;

void log_message(const char* message) {
    printf("%s\n", message);
}

int validate_crc(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Placeholder for CRC validation logic
    return 1; // Assume valid for this example
