Node* create_node(NFAPI_CRC_INDICATION_PDU_T data, int priority) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->data = data;
    new_node->priority = priority;
    new_node->timestamp = time(NULL);
    new_node->next = NULL;

    return new_node;
}

void free_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->current_memory_usage = 0;
}

void delete_oldest_node(LinkedList* list, size_t memory_to_free) {
    pthread_mutex_lock(&list->lock);

    Node *prev = NULL, *curr = list->head;

    while (curr && (list->current_memory_usage > MEMORY_LIMIT - memory_to_free)) {
        if (!prev || prev->priority != 1) { // Skip high-priority nodes
            size_t node_size = sizeof(Node) + sizeof(NFAPI_CRC_INDICATION_PDU_T);

            Node* to_delete = curr;
            list->current_memory_usage -= node_size;

            if (prev) {
                prev->next = curr->next;
            } else {
                list->head = curr->next;
            }

            free(to_delete);

            curr = list->head; // Reset to head after deletion
        } else {
            prev = curr;
            curr = curr->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void manage_memory(LinkedList* list) {
    if (list->current_memory_usage > MEMORY_LIMIT) {
        log_message("Memory limit exceeded, freeing oldest entries...");
        delete_oldest_node(list, 0); // Attempt to free up memory
    }
}

int add_to_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data, int priority) {
    pthread_mutex_lock(&list->lock);

    if (validate_crc(&data)) {
        Node* new_node = create_node(data, priority);
        if (!new_node || sizeof(Node) + sizeof(NFAPI_CRC_INDICATION_PDU_T) > MAX_STRUCTURE_SIZE) {
            free(new_node);
            log_message("Failed to add node: Size exceeds limit or memory allocation failed.");
            pthread_mutex_unlock(&list->lock);
            return 0;
        }

        size_t new_memory_usage = list->current_memory_usage + sizeof(Node) + sizeof(NFAPI_CRC_INDICATION_PDU_T);

        if (new_memory_usage > MEMORY_LIMIT) {
            delete_oldest_node(list, new_memory_usage - list->current_memory_usage);
        }

        new_node->next = list->head;
        list->head = new_node;
        list->current_memory_usage += sizeof(Node) + sizeof(NFAPI_CRC_INDICATION_PDU_T);

        log_message("Node added successfully.");
    } else {
        log_message("CRC validation failed, node not added.");
    }

    pthread_mutex_unlock(&list->lock);
    return 1;
}

void export_to_file(LinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        log_message("Failed to open file for writing.");
        return;
    }

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
    log_message("Export completed.");

    pthread_mutex_unlock(&list->lock);
}

void* manage_list(void* arg) {
    LinkedList* list = (LinkedList*)arg;

    while (!list->paused) {
        NFAPI_CRC_INDICATION_PDU_T new_data;
        // Populate new_data with random values
        srand(time(NULL));
        new_data.RX_UE_INFORMATION_TAG = rand();
        new_data.RNTI = rand() % 65536; // Example RNTI value range
        new_data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        add_to_list(list, new_data, 0);

        manage_memory(list);
    }

    return NULL;
}

void start_thread(LinkedList* list) {
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, manage_list, list)) {
        log_message("Failed to create thread.");
    } else {
        pthread_detach(thread_id); // Allow the main program to exit without joining
    }
}

int main() {
    LinkedList list = { .head = NULL, .current_memory_usage = 0, .paused = 0 };
    pthread_mutex_init(&list.lock, NULL);

    start_thread(&list);

    // Simulate user interactions or conditions here

