#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_TRANSACTIONS 1000
#define HASH_TABLE_SIZE 256

typedef enum {
    FINANCIAL_TRANSACTION,
    INFORMATIONAL_LOG
} TransactionType;

typedef struct {
    int transactionId;
    time_t timestamp;
    TransactionType transactionType;
} Transaction;

typedef struct HashTableEntry {
    char *key;
    int frequency;
    struct HashTableEntry *next;
} HashTableEntry;

typedef struct {
    HashTableEntry **table;
} HashTable;

// Function prototypes
Transaction* initializeTransactions(int count);
char** initializeStringArray(int count);
HashTable* createHashTable();
void insertIntoHashTable(HashTable *hashTable, const char *key);
int getFrequencyFromHashTable(HashTable *hashTable, const char *key);
void freeTransactions(Transaction *transactions, int count);
void freeStringArray(char **strings, int count);
void freeHashTable(HashTable *hashTable);
void generateReport(const Transaction *transactions, int transactionCount, HashTable *hashTable);
void handleNetworkRetry(int attempt);

// Function implementation
Transaction* initializeTransactions(int count) {
    Transaction *transactions = (Transaction*)malloc(count * sizeof(Transaction));
    if (!transactions) return NULL;

    srand(time(NULL));
    for (int i = 0; i < count; ++i) {
        transactions[i].transactionId = rand() % 100000;
        transactions[i].timestamp = time(NULL);
        transactions[i].transactionType = rand() % 2 ? FINANCIAL_TRANSACTION : INFORMATIONAL_LOG;
    }
    return transactions;
}

char** initializeStringArray(int count) {
    char **strings = (char**)malloc(count * sizeof(char*));
    if (!strings) return NULL;

    for (int i = 0; i < count; ++i) {
        strings[i] = (char*)malloc(50 * sizeof(char));
        if (!strings[i]) break;
        snprintf(strings[i], 50, "String_%d", rand() % 100);
    }
    return strings;
}

HashTable* createHashTable() {
    HashTable *hashTable = (HashTable*)malloc(sizeof(HashTable));
    if (!hashTable) return NULL;

    hashTable->table = (HashTableEntry**)calloc(HASH_TABLE_SIZE, sizeof(HashTableEntry*));
    if (!hashTable->table) {
        free(hashTable);
        return NULL;
    }
    return hashTable;
}

void insertIntoHashTable(HashTable *hashTable, const char *key) {
    unsigned int index = hash(key) % HASH_TABLE_SIZE;
    HashTableEntry *entry = (HashTableEntry*)malloc(sizeof(HashTableEntry));
    if (!entry) return;

    entry->key = strdup(key);
    entry->frequency = 1;
    entry->next = hashTable->table[index];
    hashTable->table[index] = entry;
}

int getFrequencyFromHashTable(HashTable *hashTable, const char *key) {
    unsigned int index = hash(key) % HASH_TABLE_SIZE;
    HashTableEntry *entry = hashTable->table[index];

    while (entry) {
        if (strcmp(entry->key, key) == 0) {
            return entry->frequency;
        }
        entry = entry->next;
    }
    return 0;
}

void freeTransactions(Transaction *transactions, int count) {
    free(transactions);
}

void freeStringArray(char **strings, int count) {
    for (int i = 0; i < count; ++i) {
        free(strings[i]);
    }
    free(strings);
}

void freeHashTable(HashTable *hashTable) {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashTableEntry *entry = hashTable->table[i];
        while (entry) {
            HashTableEntry *temp = entry;
            entry = entry->next;
            free(temp->key);
            free(temp);
        }
    }
    free(hashTable->table);
    free(hashTable);
}

void generateReport(const Transaction *transactions, int transactionCount, HashTable *hashTable) {
    FILE *file = fopen("report.txt", "w");
    if (!file) return;

    fprintf(file, "Financial Transactions:\n");
    for (int i = 0; i < transactionCount; ++i) {
        if (transactions[i].transactionType == FINANCIAL_TRANSACTION) {
            fprintf(file, "ID: %d, Timestamp: %ld\n", transactions[i].transactionId, transactions[i].timestamp);
        }
    }

    fprintf(file, "\nInformational Logs Frequency:\n");
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashTableEntry *entry = hashTable->table[i];
        while (entry) {
            if (getFrequencyFromHashTable(hashTable, entry->key) > 1) {
                fprintf(file, "%s: %d\n", entry->key, entry->frequency);
            }
            entry = entry->next;
        }
    }

    fclose(file);
}

unsigned int hash(const char *str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }

    return hash % HASH_TABLE_SIZE;
}

void handleNetworkRetry(int attempt) {
    if (attempt > 0) {
        int sleepTime = (1 << attempt);
        sleep(sleepTime);
    }
}

int processUserInputAndGenerateReport() {
    int transactionCount = MAX_TRANSACTIONS;
    Transaction *transactions = initializeTransactions(transactionCount);
    if (!transactions) return -1;

    char **strings = initializeStringArray(transactionCount);
    if (!strings) {
        freeTransactions(transactions, transactionCount);
        return -2;
    }

    HashTable *hashTable = createHashTable();
    if (!hashTable) {
        freeTransactions(transactions, transactionCount);
        freeStringArray(strings, transactionCount);
        return -3;
    }

    for (int i = 0; i < transactionCount; ++i) {
        insertIntoHashTable(hashTable, strings[i]);
    }

    generateReport(transactions, transactionCount, hashTable);

    // Simulate network dependency with retry mechanism
    int attempt = 0;
    while (!networkCheck() && attempt < 5) {
        handleNetworkRetry(attempt++);
    }
    if (attempt == 5) return -4;

    freeTransactions(transactions, transactionCount);
    freeStringArray(strings, transactionCount);
    freeHashTable(hashTable);

    return 0;
}

// Simulate network check function
int networkCheck() {
    return rand() % 2; // Randomly simulate success or failure
}
