    return list;
}

int add_request(SRS_Request_List *list, NR_SRS_REQUEST_PDU_T request) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->max_size) {
        pthread_mutex_unlock(&list->lock);
        log_activity("Addition failed: List is full");
        return -1;
    }

    size_t new_memory = sizeof(NR_SRS_REQUEST_PDU_T);
    if (request.srs_config != NULL) {
        new_memory += sizeof(void *); // Adjust based on actual allocation
    }

    if ((list->total_allocated_memory + new_memory) > list->max_size) {
        pthread_mutex_unlock(&list->lock);
        log_activity("Addition failed: Memory limit exceeded");
        return -1;
    }

    list->elements = (NR_SRS_REQUEST_PDU_T *)realloc(list->elements, (list->count + 1) * sizeof(NR_SRS_REQUEST_PDU_T));
    if (!list->elements) {
        pthread_mutex_unlock(&list->lock);
        log_activity("Addition failed: Memory allocation error");
        return -1;
    }

    list->elements[list->count] = request;
    list->total_allocated_memory += new_memory;
    list->count++;

    char log_msg[256];
    snprintf(log_msg, sizeof(log_msg), "Added RNTI %d", request.rnti);
    log_activity(log_msg);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void free_list(SRS_Request_List *list) {
    pthread_mutex_lock(&list->lock);

    if (list->elements) {
        for (size_t i = 0; i < list->count; ++i) {
            if (list->elements[i].srs_config != NULL) {
                free(list->elements[i].srs_config);
            }
        }
        free(list->elements);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);

    log_activity("List freed");
    free(list);
}

int import_from_file(SRS_Request_List *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    pthread_mutex_lock(&list->lock);

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    list->elements = (NR_SRS_REQUEST_PDU_T *)realloc(list->elements, count * sizeof(NR_SRS_REQUEST_PDU_T));
    if (!list->elements) {
        pthread_mutex_unlock(&list->lock);
        fclose(file);
        return -1;
    }

    fread(list->elements, sizeof(NR_SRS_REQUEST_PDU_T), count, file);
    list->count = count;

    pthread_mutex_unlock(&list->lock);
    log_activity("Imported from file");
    fclose(file);
    return 0;
}

int export_to_file(const SRS_Request_List *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock((pthread_mutex_t *)&list);

    fwrite(&list->count, sizeof(size_t), 1, file);
    fwrite(list->elements, sizeof(NR_SRS_REQUEST_PDU_T), list->count, file);

    pthread_mutex_unlock((pthread_mutex_t *)&list);
    log_activity("Exported to file");
    fclose(file);
    return 0;
}

void log_activity(const char *message) {
    FILE *log_file = fopen("activity.log", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}
