ErrorCode handleNetworkEventsAndMediaTasks(NetworkEvent **events, size_t eventCount) {
    if (!events || !eventCount) return ERR_INVALID_INPUT;

    MemoryPool memoryPool(sizeof(Record), 1024);

    if (!memoryPool.init()) return ERR_MEMORY_ALLOC;

    int logLevel = MAX_LOG_LEVEL; // Set desired verbosity level
    char *logBuffer = (char *)malloc(eventCount * 256); // Dynamic buffer for logging

