        NetworkEvent *event = events[i];

        if (!event || !event->frames) {
            snprintf(logBuffer, sizeof(char) * 256, "Invalid network event at index %zu\n", i);
            fprintf(stderr, "%s", logBuffer); // Log error
            continue;
        }

        for (size_t j = 0; j < event->frameCount; ++j) {
            MAC_FRAME_DATA *frameData = &event->frames[j];

            if (!frameData || !frameData->data || frameData->length == 0) {
                snprintf(logBuffer, sizeof(char) * 256, "Invalid frame data at index %zu\n", j);
                fprintf(stderr, "%s", logBuffer); // Log error
                continue;
            }

            // Process each frame for media conversion
            if (frameData->length > MAX_FRAME_SIZE) {
                snprintf(logBuffer, sizeof(char) * 256, "Frame overflow detected at index %zu\n", j);
                fprintf(stderr, "%s", logBuffer); // Log buffer overflow error
                return ERR_BUFFER_OVERFLOW;
            }

            mediaConversionLibrary(frameData->data, frameData->length);

            if (logLevel > 1) { // Verbose logging
                snprintf(logBuffer, sizeof(char) * 256, "Processed frame at index %zu\n", j);
                fprintf(stdout, "%s", logBuffer);
            }
        }

        StructRecord record = {
            .timestamp = event->timestamp,
            .uniqueID = rand() % 10000 // Random unique ID
        };

        Record *recordStruct = (Record *)memoryPool.allocate();
        if (!recordStruct) {
            snprintf(logBuffer, sizeof(char) * 256, "Failed to allocate memory for record at index %zu\n", i);
            fprintf(stderr, "%s", logBuffer); // Log allocation error
            continue;
        }

        recordStruct->value = (int)event->timestamp; // Store timestamp as int value

        if (logLevel > 0) { // Basic logging
            snprintf(logBuffer, sizeof(char) * 256, "Processed event at index %zu\n", i);
            fprintf(stdout, "%s", logBuffer);
        }
    }

    free(logBuffer);
    memoryPool.cleanup();

    return OK;
}
