#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <zlib.h>

// Define MAC_EVENT_TAG, timestamp, and MAC_FRAME_DATA structures.
typedef struct {
    uint8_t tag[6]; // Example: Ethernet type or similar
} MAC_EVENT_TAG;

typedef struct {
    time_t timestamp;
} EventTimestamp;

typedef struct {
    char data[256];
    size_t length;
    // Other frame-specific fields...
} MAC_FRAME_DATA;

typedef struct FrameNode {
    MAC_FRAME_DATA frame;
    struct FrameNode* next;
} FrameNode;

typedef struct NetworkEvent {
    MAC_EVENT_TAG event_tag;
    EventTimestamp timestamp;
    FrameNode* frames; // Linked list for variable number of frames
    struct NetworkEvent* next;
} NetworkEvent;

typedef struct {
    NetworkEvent* head;
    pthread_mutex_t lock;
} EventList;

// Function to initialize the event list.
void init_event_list(EventList* el) {
    el->head = NULL;
    pthread_mutex_init(&el->lock, NULL);
}

// Function to add a new network event.
int add_network_event(EventList* el, MAC_EVENT_TAG tag, time_t timestamp, MAC_FRAME_DATA frames[], size_t frame_count) {
    pthread_mutex_lock(&el->lock);

    NetworkEvent* new_event = (NetworkEvent*)malloc(sizeof(NetworkEvent));
    if (!new_event) {
        pthread_mutex_unlock(&el->lock);
        return -1; // Memory allocation failed
    }

    memcpy(&new_event->event_tag, &tag, sizeof(MAC_EVENT_TAG));
    new_event->timestamp.timestamp = timestamp;
    new_event->frames = NULL;

    FrameNode* current_frame = NULL;
    for (size_t i = 0; i < frame_count; ++i) {
        FrameNode* new_frame_node = (FrameNode*)malloc(sizeof(FrameNode));
        if (!new_frame_node) {
            // Free previously allocated frames
            while (current_frame) {
                FrameNode* temp = current_frame;
                current_frame = current_frame->next;
                free(temp);
            }
            free(new_event);
            pthread_mutex_unlock(&el->lock);
            return -1; // Memory allocation failed
        }

        memcpy(&new_frame_node->frame, &frames[i], sizeof(MAC_FRAME_DATA));
        new_frame_node->next = NULL;

        if (!current_frame) {
            new_event->frames = new_frame_node;
        } else {
            current_frame->next = new_frame_node;
        }
        current_frame = new_frame_node;
    }

    new_event->next = el->head;
    el->head = new_event;

    pthread_mutex_unlock(&el->lock);
    return 0; // Success
}

// Function to export events in a compressed format.
int export_events(EventList* el, const char* file_path) {
    FILE* file = fopen(file_path, "wb");
    if (!file) return -1;

    z_stream strm;
    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;

    if (deflateInit(&strm, Z_BEST_COMPRESSION) != Z_OK) {
        fclose(file);
        return -1;
    }

    unsigned char out[4096];
    int flush = Z_FINISH;
    int have;

    pthread_mutex_lock(&el->lock);

    NetworkEvent* current_event = el->head;
    while (current_event) {
        // Serialize event data
        size_t serialized_size = 1024; // Example size, calculate based on actual structure
        unsigned char buffer[serialized_size];

        // Fill the buffer with serialized data from current_event...

        strm.avail_in = serialized_size;
        strm.next_in = (Bytef*)buffer;

        do {
            strm.avail_out = sizeof(out);
            strm.next_out = out;
            deflate(&strm, flush);

            have = sizeof(out) - strm.avail_out;
            if (fwrite(out, 1, have, file) != have || ferror(file)) {
                fclose(file);
                deflateEnd(&strm);
                pthread_mutex_unlock(&el->lock);
                return -1; // Write error
            }
        } while (strm.avail_out == 0);

        current_event = current_event->next;
    }

    flush = Z_FINISH;
    if (deflate(&strm, Z_FINISH) != Z_STREAM_END) {
        fclose(file);
        deflateEnd(&strm);
        pthread_mutex_unlock(&el->lock);
        return -1; // Deflation error
    }

    while (strm.avail_out == 0) {
        strm.avail_out = sizeof(out);
        strm.next_out = out;
        deflate(&strm, Z_FINISH);

        have = sizeof(out) - strm.avail_out;
        if (fwrite(out, 1, have, file) != have || ferror(file)) {
            fclose(file);
            deflateEnd(&strm);
            pthread_mutex_unlock(&el->lock);
            return -1; // Write error
        }
    }

    deflateEnd(&strm);
    fclose(file);

    pthread_mutex_unlock(&el->lock);
    return 0;
}

// Function to clean up the event list.
void cleanup_event_list(EventList* el) {
    pthread_mutex_lock(&el->lock);

    NetworkEvent* current = el->head;
    while (current) {
        FrameNode* frame_node = current->frames;
        while (frame_node) {
            FrameNode* temp = frame_node;
            frame_node = frame_node->next;
            free(temp);
        }
        NetworkEvent* temp_event = current;
        current = current->next;
        free(temp_event);
    }

    pthread_mutex_unlock(&el->lock);
    pthread_mutex_destroy(&el->lock);
}

// Example usage
int main() {
    EventList event_list;
    init_event_list(&event_list);

    MAC_EVENT_TAG example_tag = {{0x01, 0x02, 0x03, 0x04, 0x05, 0x06}};
    time_t now = time(NULL);
    MAC_FRAME_DATA frames[] = {
        {"Frame1", sizeof("Frame1")},
        {"Frame2", sizeof("Frame2")}
    };

    add_network_event(&event_list, example_tag, now, frames, 2);

    export_events(&event_list, "events.gz");

    cleanup_event_list(&event_list);
    return 0;
}
