class RandomHelper {
private:
    int MinValue;
    int MaxValue;
    unsigned int seed;

public:
    RandomHelper(int minValue, int maxValue, unsigned int seed = 0) : MinValue(minValue), MaxValue(maxValue), seed(seed) {}

    int getRandomInt() {
        if (seed == 0) {
            srand(time(NULL));
        } else {
            srand(seed);
        }
        return MinValue + rand() % ((MaxValue - MinValue) + 1);
    }

    std::string toString() const {
        return "Range: [" + std::to_string(MinValue) + ", " + std::to_string(MaxValue) + "]";
    }
};

void initializeRecords(long* offsets, int* keys, record* records, size_t numRecords, int minValue, int maxValue, unsigned int seed = 0) {
    if (numRecords == 0 || minValue > maxValue) return;

    RandomHelper randomHelper(minValue, maxValue, seed);

    for (size_t i = 0; i < numRecords; ++i) {
        offsets[i] = i * sizeof(record); // Example initialization
        keys[i] = static_cast<int>(randomHelper.getRandomInt());
        records[i].value = randomHelper.getRandomInt();
    }

    printf("%s\n", randomHelper.toString().c_str());
}

int main() {
    size_t numRecords = 10;
    long* offsets = (long*)malloc(numRecords * sizeof(long));
    int* keys = (int*)malloc(numRecords * sizeof(int));
    record* records = (record*)malloc(numRecords * sizeof(record));

    initializeRecords(offsets, keys, records, numRecords, 1, 100, 12345);

    for (size_t i = 0; i < numRecords; ++i) {
        printf("Offset: %ld, Key: %d, Record Value: %d\n", offsets[i], keys[i], records[i].value);
    }

