#define MAX_SIZE 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    char CRCFLAG; // Assuming CRCFLAG is a single character for simplicity
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t used;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

void initDynamicArray(DynamicArray *a, size_t initialCapacity) {
    a->array = (NFAPI_CRC_INDICATION_PDU_T *)calloc(initialCapacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!a->array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    a->used = 0;
    a->capacity = initialCapacity;
    pthread_mutex_init(&a->lock, NULL);
}

void freeDynamicArray(DynamicArray *a) {
    free(a->array);
    pthread_mutex_destroy(&a->lock);
}

int resizeIfNeeded(DynamicArray *a) {
    if (a->used >= a->capacity && a->capacity < MAX_SIZE) {
        size_t newCapacity = a->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *newArray = (NFAPI_CRC_INDICATION_PDU_T *)realloc(a->array, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newArray) {
            perror("Failed to reallocate memory");
            return -1;
        }
        a->array = newArray;
        a->capacity = newCapacity;
    } else if (a->used >= MAX_SIZE) {
        fprintf(stderr, "Reached maximum array size\n");
        return -2;
    }
    return 0;
}

void addPDU(DynamicArray *a, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&a->lock);

    if (resizeIfNeeded(a) != 0) {
        pthread_mutex_unlock(&a->lock);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &a->array[a->used++];
    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    pdu->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

    // Simple pseudo-random generator for demonstration
    srand(RX_UE_INFORMATION_TAG + RNTI + CRC_INDICATION_REL8_TAG);
    pdu->CRCFLAG = (rand() % 2) ? '1' : '0';

    pthread_mutex_unlock(&a->lock);
}

void iterateArray(DynamicArray *a, void (*func)(NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&a->lock);

    for (size_t i = 0; i < a->used; ++i) {
        func(&a->array[i]);
    }

    pthread_mutex_unlock(&a->lock);
}

// Example function to process each PDU
void processPDU(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    printf("Processing PDU: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d, CRCFLAG=%c\n",
           pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG, pdu->CRCFLAG);
}

int main() {
    DynamicArray a;
    initDynamicArray(&a, 4);

    addPDU(&a, 1, 100, 200);
    addPDU(&a, 2, 101, 201);
    addPDU(&a, 3, 102, 202);

    iterateArray(&a, processPDU);

    freeDynamicArray(&a);
    return 0;
}
