#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_THROUGHPUT 100.0
#define MIN_THROUGHPUT 10.0

typedef struct {
    int cellId;
    time_t timeStamp;
    double throughput;
} NetworkPerformanceMetrics;

typedef struct {
    double *buffer;
    size_t capacity;
    size_t count;
    size_t start;
    pthread_mutex_t lock;
} CircularBuffer;

void initializeCircularBuffer(CircularBuffer *cb, size_t capacity) {
    cb->buffer = (double *)malloc(capacity * sizeof(double));
    if (!cb->buffer) {
        perror("Failed to allocate memory for circular buffer");
        exit(EXIT_FAILURE);
    }
    cb->capacity = capacity;
    cb->count = 0;
    cb->start = 0;
    pthread_mutex_init(&cb->lock, NULL);
}

void pushToCircularBuffer(CircularBuffer *cb, double value) {
    pthread_mutex_lock(&cb->lock);
    cb->buffer[cb->start] = value;
    if (cb->count < cb->capacity) {
        cb->count++;
    } else {
        cb->start = (cb->start + 1) % cb->capacity;
    }
    pthread_mutex_unlock(&cb->lock);
}

double getMovingAverage(CircularBuffer *cb) {
    double sum = 0.0;
    size_t count = cb->count;
    if (count == 0) return 0;

    pthread_mutex_lock(&cb->lock);
    for (size_t i = 0; i < count; ++i) {
        size_t index = (cb->start + i) % cb->capacity;
        sum += cb->buffer[index];
    }
    pthread_mutex_unlock(&cb->lock);

    return sum / count;
}

void initializeNetworkMetrics(int numMetrics, NetworkPerformanceMetrics *metricsArray, CircularBuffer *circularBuffer) {
    if (!numMetrics || !metricsArray || !circularBuffer) {
        fprintf(stderr, "Invalid input parameters.\n");
        return;
    }

    time_t currentTime = time(NULL);
    int cellIdBase = 1;

    for (int i = 0; i < numMetrics; ++i) {
        metricsArray[i].cellId = cellIdBase + (i % 256);

        metricsArray[i].timeStamp = currentTime - (60 - i);
        if (metricsArray[i].timeStamp < 0) {
            metricsArray[i].timeStamp = 0;
        }

        double throughput = MIN_THROUGHPUT + ((MAX_THROUGHPUT - MIN_THROUGHPUT) * rand() / RAND_MAX);

        pushToCircularBuffer(circularBuffer, throughput);
        if (i >= 9) { // Only calculate moving average after at least 10 entries
            metricsArray[i].throughput = getMovingAverage(circularBuffer);
        } else {
            metricsArray[i].throughput = throughput;
        }
    }

    pthread_mutex_destroy(&circularBuffer->lock);
    free(circularBuffer->buffer);
}
```

This code defines the `NetworkPerformanceMetrics` and `CircularBuffer` structures, initializes the circular buffer, and populates the network metrics array with unique cell IDs, timestamps, and throughput values. It also calculates moving averages using a mutex for thread safety.']

