int thread_safe_rand_int(RandomGenerator *rng, int min, int max) {
    pthread_mutex_lock(&rng->lock);
    rng->seed ^= rng->seed << 13;
    rng->seed ^= rng->seed >> 17;
    rng->seed ^= rng->seed << 5;
    int random_value = (int)(((double)(rng->seed & 0x7FFFFFFF) / (double)0x7FFFFFFF) * ((max - min + 1) + 0.5)) + min;
    pthread_mutex_unlock(&rng->lock);
    return random_value;
}

// Custom memory allocator using a memory pool
typedef struct {
    size_t unit_size;
    void **free_list;
    size_t free_count;
} MemoryPool;

void init_memory_pool(MemoryPool *pool, size_t unit_size, size_t initial_capacity) {
    pool->unit_size = unit_size;
    pool->free_list = (void **)malloc(initial_capacity * sizeof(void *));
    pool->free_count = 0;
}

void* memory_pool_alloc(MemoryPool *pool) {
    if (pool->free_count == 0) {
        size_t new_capacity = (pool->free_count == 0) ? 10 : pool->free_count * 2;
        void **new_free_list = (void **)realloc(pool->free_list, new_capacity * sizeof(void *));
        for (size_t i = pool->free_count; i < new_capacity; ++i) {
            new_free_list[i] = malloc(pool->unit_size);
        }
        pool->free_list = new_free_list;
    }

    if (pool->free_count > 0) {
        void *allocated_memory = pool->free_list[--(pool->free_count)];
        return allocated_memory;
    } else {
        return NULL; // Allocation failed
    }
}

void memory_pool_free(MemoryPool *pool, void *ptr) {
    pool->free_list[(pool->free_count)++] = ptr;
}

// Eviction policy (LRU or other strategy)
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

void evict_lru(Node **head, LogCallback log_cb) {
    if (*head == NULL || (*head)->next == NULL) return;

    Node *temp = *head;
    while (temp->next->next != NULL) {
        temp = temp->next;
    }
    log_cb("Evicting LRU item.");
    free(temp->next);
    temp->next = NULL;
}

// Main function
int allocate_and_initialize(NFAPI_CRC_INDICATION_PDU_T **list, size_t *size,
                            long offset[], int keys[], size_t max_list_size,
                            size_t desired_structures, LogCallback log_cb) {

