struct NetworkPerformanceMetrics {
    int cellId;
    std::chrono::time_point<std::chrono::system_clock> timeStamp;
    double throughput;

    NetworkPerformanceMetrics(int id, std::chrono::time_point<std::chrono::system_clock> tp)
        : cellId(id), timeStamp(tp) {}

    void calculateThroughput(double trafficData) {
        // Simulated throughput calculation.
        throughput = trafficData * (1.0 + 0.5 * ((rand() % 100) / 100.0));
    }
};

// Function to populate datasets with robust error handling and logging.
int populateNFADataset(std::vector<NFAPI_CRC_INDICATION_PDU_T>& nfapiData,
                       std::vector<NetworkPerformanceMetrics>& perfData, 
                       int numEntries, MetadataService& metadataService) {

    const int MAX_RETRIES = 5;
    const double BACKOFF_FACTOR = 1.5;
    double movingAverageThroughput[10] = {0};

    nfapiData.reserve(numEntries);
    perfData.reserve(numEntries);

    for (int i = 0; i < numEntries; ++i) {
        try {
            // Asynchronously populate NFAPI data
            std::thread([this, &nfapiData]() mutable {
                nfapiData.emplace_back();
            }).detach();

            // Calculate Network Performance Metrics.
            auto now = std::chrono::system_clock::now();
            NetworkPerformanceMetrics metrics(i + 1, now);
            double simulatedTrafficData = rand() % 1000;
            metrics.calculateThroughput(simulatedTrafficData);

            perfData.push_back(metrics);

            // Update moving average throughput
            for (int j = 9; j > 0; --j) {
                movingAverageThroughput[j] = movingAverageThroughput[j - 1];
            }
            movingAverageThroughput[0] = metrics.throughput;
            double avgThroughput = 0;
            for (int k = 0; k < 10 && k < i + 1; ++k) {
                avgThroughput += movingAverageThroughput[k];
            }
            if ((i + 1) > 0) avgThroughput /= std::min(10, i + 1);

            // Fetch user metadata with retries.
            UserMetadata userMeta;
            int attempt = 0;
            bool success = false;

            while (attempt < MAX_RETRIES && !success) {
                if (metadataService.fetchData(userMeta)) {
                    success = true;
                } else {
                    std::this_thread::sleep_for(std::chrono::milliseconds(static_cast<int>(pow(BACKOFF_FACTOR, attempt))));
                    ++attempt;
                }
            }

            if (!success) {
                // Logging failure to fetch metadata.
                std::cerr << "Failed to fetch user metadata after " << MAX_RETRIES << " attempts." << std::endl;
                return -1; // Indicate error due to external service unavailability.
            }
        } catch (const std::bad_alloc&) {
            std::cerr << "Memory allocation failed." << std::endl;
            return -2; // Specific error code for memory failure
        }

    }

    return 0; // Success code.
}

// Main function to demonstrate usage
int main() {
    MetadataService metadataService;

    const int numEntries = 1000;
    std::vector<NFAPI_CRC_INDICATION_PDU_T> nfapiData;
    std::vector<NetworkPerformanceMetrics> perfData;

    int result = populateNFADataset(nfapiData, perfData, numEntries, metadataService);
    if (result != 0) {
        std::cerr << "Error occurred: Code " << result << std::endl;
    }

    // Output for validation purposes
    std::cout << "NFAPI Data size: " << nfapiData.size() << std::endl;
    std::cout << "Performance Metrics Data size: " << perfData.size() << std::endl;

    return 0;
}
