        ERR_print_errors_fp(stderr);
        close(sock);
        SSL_CTX_free(ctx);
        return -1;
    }

    SSL_set_fd(ssl, sock);

    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connection failed");
        close(sock);
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        return -1;
    }

    int status = SSL_connect(ssl);
    if (status != 1) {
        ERR_print_errors_fp(stderr);
        close(sock);
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        return -1;
    }

    const char *http_request = "GET / HTTP/1.1\r\nHost: example.com\r\nConnection: close\r\n\r\n";
    SSL_write(ssl, http_request, strlen(http_request));

    unsigned char buffer[4096];
    int bytes;
    size_t total_bytes = 0;
    *response_body = malloc(sizeof(char) * 16384);
    if (!*response_body) {
        perror("Memory allocation failed");
        close(sock);
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        return -1;
    }

    while ((bytes = SSL_read(ssl, buffer, sizeof(buffer))) > 0) {
        memcpy(*response_body + total_bytes, buffer, bytes);
        total_bytes += bytes;
    }

    if (bytes < 0) {
        perror("SSL read failed");
        close(sock);
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        return -1;
    }

    close(sock);
    SSL_free(ssl);
    SSL_CTX_free(ctx);

    (*response_body)[total_bytes] = '\0';
    return 0;
}

