#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int sensor_id;
    time_t timestamp;
    float temperature_reading;
} SensorData;

typedef struct {
    size_t alignment;
    void *(*allocate)(size_t);
    void (*deallocate)(void *);
} CustomAllocator;

typedef struct {
    pthread_mutex_t mutex;
    unsigned int state;
} RandomState;

void *custom_allocate(size_t size, const CustomAllocator *allocator) {
    if (!allocator || !allocator->allocate)
        return NULL;

    // Ensure the requested memory is aligned
    void *ptr = allocator->allocate(size + allocator->alignment - 1);
    uintptr_t raw_ptr = (uintptr_t) ptr;
    uintptr_t aligned_ptr = (raw_ptr + allocator->alignment - 1) & ~(allocator->alignment - 1);

    if ((aligned_ptr - raw_ptr) < size)
        return NULL;

    void *aligned_memory = (void *) aligned_ptr;
    memset(aligned_memory, 0, size);
    return aligned_memory;
}

void custom_deallocate(void *ptr, const CustomAllocator *allocator) {
    if (!ptr || !allocator->deallocate)
        return;
    uintptr_t raw_ptr = (uintptr_t) ptr & ~(allocator->alignment - 1);
    allocator->deallocate((void *) raw_ptr);
}

static unsigned int random_state_get(RandomState *state) {
    unsigned int x = state->state;
    x ^= x << 16u;
    x ^= x >> 5u;
    x ^= x << 1u;
    state->state = x;
    return x * 0x6c078965u;
}

static void random_state_init(RandomState *state) {
    if (!state)
        return;

    pthread_mutex_lock(&state->mutex);
    state->state = (unsigned int) time(NULL);
    pthread_mutex_unlock(&state->mutex);
}

float thread_safe_random_float(RandomState *state, float min, float max) {
    if (!state)
        return 0.0f;

    unsigned int rand_val;
    pthread_mutex_lock(&state->mutex);
    rand_val = random_state_get(state);
    pthread_mutex_unlock(&state->mutex);

    return min + (rand_val / (float) UINT_MAX) * (max - min);
}

void fetch_sensor_data(SensorData **sensor_data_array, int num_sensors, int max_readings_per_sensor,
                       float temp_min, float temp_max, const CustomAllocator *allocator) {

    if (!sensor_data_array || !allocator)
        return;

    RandomState rand_state;
    random_state_init(&rand_state);

    for (int i = 0; i < num_sensors; ++i) {
        sensor_data_array[i] = custom_allocate(sizeof(SensorData) * max_readings_per_sensor, allocator);

        if (!sensor_data_array[i]) {
            fprintf(stderr, "Failed to allocate memory for sensor %d\n", i);
            return;
        }

        for (int j = 0; j < max_readings_per_sensor; ++j) {
            SensorData *data = &sensor_data_array[i][j];
            data->sensor_id = i;
            data->timestamp = time(NULL);
            data->temperature_reading = thread_safe_random_float(&rand_state, temp_min, temp_max);

            // Simulate a network delay or failure handling
            if (thread_safe_random_float(&rand_state, 0.0f, 1.0f) < 0.01f) {
                fprintf(stderr, "Network error occurred while fetching data for sensor %d\n", i);
                custom_deallocate(sensor_data_array[i], allocator);
                sensor_data_array[i] = NULL;
                break; // Break and proceed to the next sensor
            }
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <num_sensors> <max_readings_per_sensor> <temp_min> <temp_max>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int num_sensors = atoi(argv[1]);
    int max_readings_per_sensor = atoi(argv[2]);
    float temp_min = atof(argv[3]);
    float temp_max = atof(argv[4]);

    if (num_sensors <= 0 || max_readings_per_sensor <= 0)
        return EXIT_FAILURE;

    CustomAllocator allocator = {
        .alignment = sizeof(void *),
        .allocate = malloc,
        .deallocate = free
    };

    SensorData **sensor_data_array = custom_allocate(num_sensors * sizeof(SensorData *), &allocator);

    if (!sensor_data_array) {
        fprintf(stderr, "Failed to allocate memory for sensor data pointers\n");
        return EXIT_FAILURE;
    }

    fetch_sensor_data(sensor_data_array, num_sensors, max_readings_per_sensor,
                      temp_min, temp_max, &allocator);

    // Clean up
    for (int i = 0; i < num_sensors; ++i) {
        if (sensor_data_array[i]) {
            custom_deallocate(sensor_data_array[i], &allocator);
        }
    }

    custom_deallocate(sensor_data_array, &allocator);

    return EXIT_SUCCESS;
}
