int serializeList(const DynamicList_t* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) return 0;

    gzFile compressed_file = gzdopen(fileno(file), "wb9");
    if (compressed_file == NULL) {
        fclose(file);
        return 0;
    }

    for (size_t i = 0; i < list->count; ++i) {
        fwrite(&list->elements[i], sizeof(MAC_PhyLayerIndication_t), 1, compressed_file);
        size_t data_length = list->elements[i].rlc_am_data_pdu.length;
        if (fwrite(&data_length, sizeof(size_t), 1, compressed_file) != 1 ||
            fwrite(list->elements[i].rlc_am_data_pdu.data, data_length, 1, compressed_file) != 1) {
            gzclose(compressed_file);
            fclose(file);
            return 0;
        }
    }

    gzclose(compressed_file);
    fclose(file);
    return 1;
}

int deserializeList(DynamicList_t* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) return 0;

    gzFile compressed_file = gzdopen(fileno(file), "rb");
    if (compressed_file == NULL) {
        fclose(file);
        return 0;
    }

    size_t count = 0;
    while (!feof(compressed_file)) {
        if (count >= MAX_ELEMENTS) break;

        MAC_PhyLayerIndication_t element;
        if (fread(&element, sizeof(MAC_PhyLayerIndication_t), 1, compressed_file) != 1) break;

        size_t data_length = 0;
        if (fread(&data_length, sizeof(size_t), 1, compressed_file) != 1 || 
            fread(element.rlc_am_data_pdu.data, data_length, 1, compressed_file) != 1) {
            gzclose(compressed_file);
            fclose(file);
            return 0;
        }

        element.rlc_am_data_pdu.length = data_length;
        if (!validateRLCDataPDU(element.rlc_am_data_pdu)) continue;

        list->elements[count++] = element;
    }

    list->count = count;
    gzclose(compressed_file);
    fclose(file);

    return 1;
}
