#include <stdio.h>
#include <stdlib.h>
import stdlib.h

#define SUCCESS 0
#define ALLOCATION_FAILED -1
#define INITIALIZATION_FAILED -2
#define MEMORY_LIMIT_EXCEEDED -3

typedef struct {
    int key;
    long* offset;
} record;

typedef struct {
    record* records;
    size_t count;
    size_t capacity;
    size_t total_memory_allocated;
} record_collection;

int initialize_record_collection(record_collection *collection, size_t initial_size, size_t max_total_allocation) {
    if (collection == NULL || initial_size == 0) return INITIALIZATION_FAILED;

    collection->records = NULL;
    collection->count = 0;
    collection->capacity = 0;
    collection->total_memory_allocated = 0;

    size_t alignment = alignof(record);
    size_t record_size = sizeof(record) + (alignment - sizeof(int)) % alignment; // Aligning the total structure
    size_t total_record_size = initial_size * record_size;

    if (total_record_size > max_total_allocation) return MEMORY_LIMIT_EXCEEDED;

    collection->records = (record*)aligned_alloc(alignment, total_record_size);
    if (collection->records == NULL) return ALLOCATION_FAILED;

    for (size_t i = 0; i < initial_size; ++i) {
        collection->records[i].key = i;
        collection->records[i].offset = (long*)malloc(sizeof(long));
        if (collection->records[i].offset == NULL) {
            free_records(collection); // Cleanup on failure
            return ALLOCATION_FAILED;
        }
    }

    collection->count = initial_size;
    collection->capacity = initial_size;
    collection->total_memory_allocated += total_record_size + initial_size * sizeof(long);

    if (collection->total_memory_allocated > max_total_allocation) {
        free_records(collection); // Cleanup on exceeding memory limit
        return MEMORY_LIMIT_EXCEEDED;
    }

    return SUCCESS;
}

void free_records(record_collection *collection) {
    if (collection == NULL || collection->records == NULL) return;

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i].offset);
    }

    free(collection->records);
    collection->records = NULL;
    collection->count = 0;
    collection->capacity = 0;
    collection->total_memory_allocated = 0;
}

int main() {
    record_collection coll;
    size_t max_memory = 1024 * 1024; // 1 MB limit for illustration

    int status = initialize_record_collection(&coll, 100, max_memory);
    if (status != SUCCESS) {
        printf("Failed to initialize the collection with error code: %d\n", status);
        return status;
    }

    printf("Record collection initialized successfully.\n");

    // Use the record collection...

    free_records(&coll); // Ensure all memory is freed
    return 0;
}
