        pthread_mutex_unlock(&lock);
    }

    for (int j = 0; j < num_keys; ++j) {
        pthread_mutex_lock(&lock);
        keys[j] = key_min + rand() % (key_max - key_min + 1);
        pthread_mutex_unlock(&lock);
    }

    // Initialize records with random values and logging identifier
    for (int k = 0; k < num_records; ++k) {
