#define MAX_EVENTS 10000 // Example limit; adjust based on expected load
#define MEMORY_THRESHOLD 0.8

typedef enum {
    MAC_EVENT_TAG_VALID,
    MAC_EVENT_TAG_INVALID
} MacEventType;

typedef struct {
    int tag;
    size_t length;
    void *data;
} MacFrameData;

typedef struct NetworkEvent {
    MacEventType mac_event_tag;
    time_t timestamp;
    MacFrameData *frames;
    size_t frame_count;
} NetworkEvent;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static NetworkEvent *event_list[MAX_EVENTS];
static size_t event_count = 0;
static size_t allocated_memory = 0;

void log_operation(const char *message, int error_code) {
    time_t now = time(NULL);
    printf("[%s] %s (Error Code: %d)\n", ctime(&now), message, error_code);
}

int validate_mac_frame_data(MacFrameData *frame) {
    if (!frame || frame->length == 0 || !frame->data) {
        log_operation("Invalid MAC Frame Data detected", -1);
        return 0;
    }
    return 1;
}

void handle_memory_allocation(size_t expected_count, size_t element_size) {
    pthread_mutex_lock(&mutex);

    if (allocated_memory < expected_count * element_size * MEMORY_THRESHOLD) {
        allocated_memory += expected_count * element_size;
        // Optionally trigger garbage collection here
    }

    pthread_mutex_unlock(&mutex);
}

int add_network_event(NetworkEvent *new_event) {
    if (!new_event || new_event->frame_count == 0) return -1;

    for (size_t i = 0; i < new_event->frame_count; ++i) {
        if (!validate_mac_frame_data(&new_event->frames[i])) {
            return -2;
        }
    }

    pthread_mutex_lock(&mutex);

    if (event_count >= MAX_EVENTS) {
        log_operation("Event list is full", -3);
        pthread_mutex_unlock(&mutex);
        return -3; // Event list overflow
    }

    event_list[event_count++] = new_event;
    handle_memory_allocation(event_count, sizeof(NetworkEvent));

    pthread_mutex_unlock(&mutex);

    log_operation("Network event added successfully", 0);
    return 0;
}

void initialize_network_event(size_t frame_count) {
    NetworkEvent *event = (NetworkEvent *)malloc(sizeof(NetworkEvent));
    if (!event) {
        log_operation("Failed to allocate memory for Network Event", -4);
        return;
    }

    event->frames = (MacFrameData *)malloc(frame_count * sizeof(MacFrameData));
    if (!event->frames) {
        free(event);
        log_operation("Failed to allocate memory for MAC Frame Data array", -5);
        return;
    }

    event->frame_count = frame_count;

    pthread_mutex_lock(&mutex);

    add_network_event(event);

    pthread_mutex_unlock(&mutex);
}

void process_frame_data(NetworkEvent *event) {
    // Placeholder for processing logic, e.g., aggregation and transmission
    log_operation("Processing network event", 0);
}

void cleanup() {
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < event_count; ++i) {
        free(event_list[i]->frames);
        free(event_list[i]);
    }
    event_count = 0;

    pthread_mutex_unlock(&mutex);
}

int main() {
    // Example usage
    initialize_network_event(5);

    cleanup();
    return 0;
}
```

This implementation covers dynamic memory management, data validation, concurrency control via mutexes, logging, and error handling. It's designed to handle high-throughput scenarios by efficiently managing network events and ensuring thread safety with minimal memory fragmentation.

Adjust parameters like `MAX_EVENTS`, `MEMORY_THRESHOLD`, and logging levels based on your specific needs and hardware capabilities for optimal performance under different workloads.']

