    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc(num_records * sizeof(int));
    record **records = malloc(num_records * sizeof(record*));

    if (!offsets || !keys || !records) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    // Initialize offsets and keys
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = get_random_value(min_offset, max_offset);
        keys[i] = get_random_value(min_key, max_key);

        record *new_record = malloc(sizeof(record));
        if (!new_record) {
            perror("Failed to allocate memory for record");
            exit(EXIT_FAILURE);
        }
        new_record->value = get_random_value(min_key, max_key);
        records[i] = new_record;

        insert_record(new_record);
    }

    // Return a pointer to the allocated data
    return malloc(sizeof(void*) * 3 + num_records * sizeof(long) +
                  num_records * sizeof(int) +
                  num_records * sizeof(record*));
}

// Cleanup function to free all resources
void cleanup_data(void *data, size_t num_records) {
    pthread_mutex_lock(&lock);

    Node *current = head;
    while (current) {
        Node *temp = current;
        current = current->next;
        free(temp->data);
        free(temp);
    }
    head = NULL;

    pthread_mutex_unlock(&lock);

    // Free allocated arrays
    long **offsets_ptr = ((long**)data) + 1;
    int **keys_ptr = offsets_ptr + num_records;
    record ***records_ptr = keys_ptr + num_records;

    free(*offsets_ptr);
    free(*keys_ptr);
    for (size_t i = 0; i < num_records; ++i) {
        free((*records_ptr)[i]);
    }
    free(*records_ptr);

    // Free the main data pointer
    free(data);
}

int main() {
    pthread_mutex_init(&lock, NULL);

    size_t num_records = 100;
    long min_offset = 0, max_offset = 100;
    int min_key = 1, max_key = 10;
    unsigned int seed = time(NULL);

    void *data = initialize_data(seed, num_records, min_offset, max_offset, min_key, max_key);

    // Use the data...

    cleanup_data(data, num_records);

    pthread_mutex_destroy(&lock);
    return 0;
}
```

This C code defines a function to dynamically allocate and initialize arrays for offsets, keys, and records. It also initializes a linked list with thread safety using mutexes. The `initialize_data` function sets up the data structures based on user-provided parameters, while the `cleanup_data` function ensures all allocated memory is properly released.']

