// Function to initialize the dynamic array of structures
NFAPI_CRC_INDICATION_PDU_T* init_crc_array(uint32_t n, uint32_t seed) {
    if (n <= 0) return NULL;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_destroy(&lock);
        return NULL;
    }

    srand(seed);
    for (uint32_t i = 0; i < n; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 65536; // Example tag
        array[i].RNTI = rand() % 65536;                   // Example RNTI
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1; // Random CRCFLAG (0 or 1)
    }

    pthread_mutex_lock(&lock);
    printf("Array initialized with %u elements\n", n);
    pthread_mutex_unlock(&lock);

    return array;
}

// Function to resize the dynamic array
NFAPI_CRC_INDICATION_PDU_T* resize_crc_array(NFAPI_CRC_INDICATION_PDU_T* old_array, uint32_t old_size, uint32_t new_size) {
    if (new_size == 0 && old_array) {
        free(old_array);
        return NULL;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(old_array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        fprintf(stderr, "Memory reallocation failed\n");
        free(old_array);
        pthread_mutex_destroy(&lock);
        return NULL;
    }

    for (uint32_t i = old_size; i < new_size; ++i) {
        new_array[i].RX_UE_INFORMATION_TAG = rand() % 65536; // Example tag
        new_array[i].RNTI = rand() % 65536;                   // Example RNTI
        new_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1; // Random CRCFLAG (0 or 1)
    }

    pthread_mutex_lock(&lock);
    printf("Array resized to %u elements\n", new_size);
    pthread_mutex_unlock(&lock);

    return new_array;
}

// Function to safely access an element in the array
NFAPI_CRC_INDICATION_PDU_T* safe_access_crc_array(NFAPI_CRC_INDICATION_PDU_T* array, uint32_t size, uint32_t index) {
