#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <uuid/uuid.h>

#define MIN_IDENTIFIER_LENGTH 10
#define MAX_IDENTIFIER_LENGTH 20
#define MEMORY_THRESHOLD (1024 * 1024) // 1 MB as an example threshold

typedef struct {
    long offset;
    int key;
    char id[MAX_IDENTIFIER_LENGTH + 1]; // Including null-terminator
} record;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_status(const char* message, int count) {
    printf("%s: %d\n", message, count);
}

int allocate_and_initialize_records(record** records, size_t num_records, int key_min, int key_max) {
    if (num_records == 0 || records == NULL) return 0;

    pthread_mutex_lock(&mutex);

    size_t total_memory_needed = num_records * sizeof(record);
    size_t attempt_count = 0;

    while (total_memory_needed <= MEMORY_THRESHOLD && attempt_count < 3) {
        *records = malloc(total_memory_needed);
        if (*records != NULL) break;

        log_status("Memory allocation failed, retrying...", 0);
        total_memory_needed += sizeof(record); // Attempt to increment size
        attempt_count++;
    }

    pthread_mutex_unlock(&mutex);

    if (*records == NULL) {
        log_status("Failed to allocate memory after retries.", 0);
        return 0;
    }

    int valid_records = 0;
    uuid_t uuid;

    for (size_t i = 0; i < num_records; ++i) {
        uuid_generate_random(uuid);

        char* buffer_start = (*records)[i].id;

        // Generate a unique identifier
        if (!uuid_unparse_lower(uuid, buffer_start)) {
            goto cleanup;
        }

        // Ensure the string is null-terminated and within bounds
        size_t id_length = strlen(buffer_start);
        if (id_length < MIN_IDENTIFIER_LENGTH || id_length > MAX_IDENTIFIER_LENGTH) {
            continue;  // Skip this record if identifier length is invalid
        }

        (*records)[i].offset = i;
        (*records)[i].key = rand() % (key_max - key_min + 1) + key_min;

        valid_records++;
    }

    log_status("Total successfully allocated and initialized records", valid_records);
    return valid_records;

cleanup:
    for (int j = 0; j < i; ++j) {
        (*records)[j].id[0] = '\0';
    }
    free(*records);
    *records = NULL;
    log_status("Memory freed due to error during processing.", 0);

    return valid_records;
}
```

This function manages memory allocation for an array of `record` structures, initializes each record with random keys and unique identifiers using UUIDs, handles errors gracefully, ensures thread safety, logs status messages, and attempts retries on allocation failure up to a defined limit. It also includes cleanup code to free allocated resources in case of errors during initialization.']

