#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 16
#define VALID_TIMESTAMP_MIN 1000000000L // Example valid range for timestamps
#define VALID_TIMESTAMP_MAX 2000000000L

typedef struct {
    char *key;
    long timestamp;
    double value;
} Entry;

typedef struct {
    Entry *entries;
    size_t capacity;
    size_t size;
    pthread_rwlock_t lock;
} Collection;

void init_collection(Collection *collection) {
    collection->entries = (Entry *)malloc(INITIAL_CAPACITY * sizeof(Entry));
    if (!collection->entries) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    collection->capacity = INITIAL_CAPACITY;
    collection->size = 0;
    pthread_rwlock_init(&collection->lock, NULL);
}

void free_collection(Collection *collection) {
    for (size_t i = 0; i < collection->size; ++i) {
        free(collection->entries[i].key);
    }
    free(collection->entries);
    pthread_rwlock_destroy(&collection->lock);
}

int validate_timestamp(long timestamp) {
    return timestamp >= VALID_TIMESTAMP_MIN && timestamp <= VALID_TIMESTAMP_MAX;
}

void resize_collection_if_needed(Collection *collection) {
    if (collection->size == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Entry *new_entries = (Entry *)realloc(collection->entries, new_capacity * sizeof(Entry));
        if (!new_entries) {
            perror("Failed to reallocate memory");
            exit(EXIT_FAILURE);
        }
        collection->entries = new_entries;
        collection->capacity = new_capacity;
    }
}

void insert_entry(Collection *collection, const char *key, long timestamp, double value) {
    pthread_rwlock_wrlock(&collection->lock);

    if (!validate_timestamp(timestamp)) {
        fprintf(stderr, "Invalid timestamp: %ld\n", timestamp);
        pthread_rwlock_unlock(&collection->lock);
        return;
    }

    resize_collection_if_needed(collection);

    Entry *entry = &collection->entries[collection->size++];
    entry->key = strdup(key);
    if (!entry->key) {
        perror("Failed to duplicate key");
        exit(EXIT_FAILURE);
    }
    entry->timestamp = timestamp;
    entry->value = value;

    pthread_rwlock_unlock(&collection->lock);
}

void iterate_collection(Collection *collection, void (*operation)(double *)) {
    pthread_rwlock_rdlock(&collection->lock);

    for (size_t i = 0; i < collection->size; ++i) {
        operation(&collection->entries[i].value);
    }

    pthread_rwlock_unlock(&collection->lock);
}

// Example usage
void example_operation(double *value) {
    printf("Value: %.2f\n", *value);
}

int main() {
    Collection collection;
    init_collection(&collection);

    insert_entry(&collection, "key1", 1500000000L, 3.14);
    insert_entry(&collection, "key2", 1600000000L, 2.71);

    iterate_collection(&collection, example_operation);

    free_collection(&collection);
    return 0;
}
