        // Initialize with random CRCFLAG for simplicity
        (*pdu_array)[i]->crc_rel8_tag.CRCFLAG = rand() % 2;
    }

    // Allocate memory for offset array
    *offset_array = (long*)malloc(num_pdu * long_size);
    if (*offset_array == NULL) {
        free_allocated_memory(*pdu_array, NULL, NULL, NULL);
        pthread_mutex_unlock(&allocation_mutex);
        return -1;  // Allocation failure
    }

    // Allocate memory for key array
    *key_array = (int*)malloc(num_pdu * int_size);
    if (*key_array == NULL) {
        free_allocated_memory(*pdu_array, *offset_array, NULL, NULL);
        pthread_mutex_unlock(&allocation_mutex);
        return -1;  // Allocation failure
    }

    // Allocate memory for record array
    *record_array = (record_t**)malloc(num_pdu * sizeof(record_t*));
    if (*record_array == NULL) {
        free_allocated_memory(*pdu_array, *offset_array, *key_array, NULL);
        pthread_mutex_unlock(&allocation_mutex);
        return -1;  // Allocation failure
    }

    for (int i = 0; i < num_pdu; ++i) {
        (*record_array)[i] = (record_t*)malloc(record_size);
        if ((*record_array)[i] == NULL) {
            free_allocated_memory(*pdu_array, *offset_array, *key_array, *record_array);
            pthread_mutex_unlock(&allocation_mutex);
            return -1;  // Allocation failure
        }

        (*record_array)[i]->value = i;  // Example initialization
        (*record_array)[i]->ptr_to_long = &(*offset_array)[i];
    }

    pthread_mutex_unlock(&allocation_mutex);
    return 0;  // Success
}

void free_allocated_memory(NFAPI_CRC_INDICATION_PDU_T* pdu_array, long* offset_array,
                           int* key_array, record_t* record_array) {
    if (pdu_array != NULL) {
        for (int i = 0; pdu_array[i] != NULL; ++i) {
            free(pdu_array[i]);
        }
        free(pdu_array);
    }

    if (offset_array != NULL) {
        free(offset_array);
    }

    if (key_array != NULL) {
        free(key_array);
    }

    if (record_array != NULL) {
        for (int i = 0; record_array[i] != NULL; ++i) {
            free(record_array[i]);
        }
        free(record_array);
    }
}
