#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define PAGE_SIZE 4096

typedef struct {
    int key;
    long *offset;
} record;

typedef struct {
    record *records;
    size_t count;
    size_t capacity;
    size_t max_memory;
    pthread_mutex_t lock;
} RecordCollection;

// Logging function
void log_message(const char *message) {
    printf("%s\n", message);  // Basic logging, can be expanded to file or system logs
}

// Initialize the record collection
int initialize_collection(RecordCollection *collection, size_t initial_count, size_t max_memory) {
    pthread_mutex_init(&collection->lock, NULL);

    if (initial_count == 0 || max_memory < sizeof(record)) return -1;

    collection->records = NULL;
    collection->count = 0;
    collection->capacity = initial_count;
    collection->max_memory = max_memory;

    size_t total_size = collection->capacity * sizeof(record);
    void *aligned_mem = _mm_malloc(total_size, PAGE_SIZE);

    if (!aligned_mem) {
        log_message("Failed to allocate memory.");
        return -1;
    }

    memset(aligned_mem, 0, total_size);

    for (size_t i = 0; i < collection->capacity; ++i) {
        aligned_mem[i].offset = NULL;
    }

    collection->records = (record *)aligned_mem;

    log_message("Collection initialized.");
    return 0;
}

// Add a record to the collection
int add_record(RecordCollection *collection, int key, long offset_value) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        size_t total_size = new_capacity * sizeof(record);

        if (total_size > collection->max_memory) {
            log_message("Memory limit exceeded, cannot expand.");
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }

        void *aligned_mem = _mm_realloc(collection->records, total_size, PAGE_SIZE);

        if (!aligned_mem) {
            log_message("Failed to reallocate memory.");
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }

        memset(aligned_mem + collection->capacity, 0, (new_capacity - collection->capacity) * sizeof(record));

        for (size_t i = collection->capacity; i < new_capacity; ++i) {
            aligned_mem[i].offset = NULL;
        }

        collection->records = (record *)aligned_mem;
        collection->capacity = new_capacity;
    }

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Duplicate key
        }
    }

    long *offset_ptr = malloc(sizeof(long));
    if (!offset_ptr) {
        log_message("Failed to allocate memory for offset.");
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    *offset_ptr = offset_value;

    collection->records[collection->count].key = key;
    collection->records[collection->count].offset = offset_ptr;
    ++(collection->count);

    log_message("Record added successfully.");
    pthread_mutex_unlock(&collection->lock);
    return 0;
}

// Free all allocated resources
void free_collection(RecordCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].offset) {
            free(collection->records[i].offset);
        }
    }

    _mm_free(collection->records);
    collection->records = NULL;
    collection->count = 0;
    collection->capacity = 0;

    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);

    log_message("All resources freed.");
}

// Example usage
int main() {
    RecordCollection coll;
    if (initialize_collection(&coll, 10, 1024 * PAGE_SIZE) != 0) {
        return -1;
    }

    add_record(&coll, 1, 100);
    add_record(&coll, 2, 200);

    free_collection(&coll);
    return 0;
}
```

