#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    long* offset_ptr;
    int* key_ptr;
    int value;
} Record;

typedef struct HashNode {
    Record record;
    struct HashNode* next;
} HashNode;

#define HASH_TABLE_SIZE 101

HashNode* hash_table[HASH_TABLE_SIZE];
pthread_mutex_t hash_table_locks[HASH_TABLE_SIZE];

unsigned int hash_function(int key, size_t table_size) {
    return (unsigned int)(key % table_size);
}

void init_hash_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hash_table[i] = NULL;
        pthread_mutex_init(&hash_table_locks[i], NULL);
    }
}

void free_hash_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashNode* current = hash_table[i];
        while (current != NULL) {
            HashNode* to_free = current;
            current = current->next;
            free(to_free);
        }
        pthread_mutex_destroy(&hash_table_locks[i]);
    }
}

void insert_record(Record record, int key) {
    unsigned int index = hash_function(key, HASH_TABLE_SIZE);
    pthread_mutex_lock(&hash_table_locks[index]);

    HashNode* new_node = (HashNode*)malloc(sizeof(HashNode));
    if (!new_node) {
        perror("Failed to allocate memory for HashNode");
        exit(EXIT_FAILURE);
    }
    new_node->record = record;
    new_node->next = hash_table[index];
    hash_table[index] = new_node;

    pthread_mutex_unlock(&hash_table_locks[index]);
}

void manage_memory(long num_offsets, int num_keys, int num_records,
                   long offset_step_size, int min_value, int max_value) {
    if (num_offsets <= 0 || num_keys <= 0 || num_records <= 0) return;

    // Calculate memory footprint limits
    const size_t max_memory_footprint = 1024 * 1024; // 1 MB for example
    size_t offset_array_size = num_offsets * sizeof(long);
    size_t key_array_size = num_keys * sizeof(int);
    size_t record_struct_size = num_records * sizeof(Record);

    if (offset_array_size + key_array_size + record_struct_size > max_memory_footprint) {
        fprintf(stderr, "Memory constraints exceeded.\n");
        return;
    }

    // Allocate memory for offsets and keys
    long* offsets = aligned_alloc(64, offset_array_size);
    int* keys = aligned_alloc(64, key_array_size);

    if (!offsets || !keys) {
        perror("Failed to allocate aligned memory");
        exit(EXIT_FAILURE);
    }

    // Initialize offsets and keys
    for (long i = 0; i < num_offsets; ++i) {
        offsets[i] = i * offset_step_size;
    }

    for (int i = 0; i < num_keys; ++i) {
        keys[i] = i;
    }

    // Seed the random number generator
    srand((unsigned int)time(NULL));

    // Allocate memory for records
    Record* records = aligned_alloc(64, record_struct_size);

    if (!records) {
        perror("Failed to allocate aligned memory");
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }

    init_hash_table();

    // Initialize and insert records into hash table
    for (int i = 0; i < num_records; ++i) {
        int key_idx = rand() % num_keys;
        long offset_idx = rand() % num_offsets;

        Record record = { offsets + offset_idx, keys + key_idx, 0 };
        record.value = min_value + (rand() % (max_value - min_value + 1));

        insert_record(record, *(record.key_ptr));
    }

    // Cleanup
    free(offsets);
    free(keys);
    free(records);
    free_hash_table();
}

int main() {
    manage_memory(1000, 500, 300, 10, 1, 100);
    return 0;
}
```

