#define MAX_MEMORY_USAGE 1024 * 1024 // 1 MB limit for demonstration purposes

typedef struct {
    long offset;
    int key;
    int value;
    unsigned char iv[16];
    EVP_CIPHER_CTX *cipher_ctx;
} Record;

// Function to derive a key from a password using PBKDF2 with SHA-256
int derive_key(const char *password, const unsigned char salt[], int salt_len,
               unsigned char key_out[], size_t key_out_len) {
    return PKCS5_PBKDF2_HMAC(password, strlen(password), salt, salt_len,
                             10000, EVP_sha256(), key_out_len, key_out);
}

// Function to initialize and encrypt a record
int init_and_encrypt_record(Record *record, const char *password, int min_offset, 
                            int max_offset, int min_key, int max_key, 
                            int min_value, int max_value) {
    // Generate random offset, key, and value within specified ranges
    record->offset = rand() % (max_offset - min_offset + 1) + min_offset;
    record->key = rand() % (max_key - min_key + 1) + min_key;
    record->value = rand() % (max_value - min_value + 1) + min_value;

    // Generate a random IV
    if (!RAND_bytes(record->iv, sizeof(record->iv))) {
        fprintf(stderr, "Error generating IV\n");
        return -1;
    }

    // Derive encryption key from password
    unsigned char salt[16];
    if (!RAND_bytes(salt, sizeof(salt))) {
        fprintf(stderr, "Error generating salt\n");
        return -1;
    }
    unsigned char key[EVP_MAX_KEY_LENGTH];
    if (derive_key(password, salt, sizeof(salt), key, sizeof(key)) <= 0) {
        fprintf(stderr, "Key derivation failed\n");
        return -1;
    }

    // Initialize cipher context
    record->cipher_ctx = EVP_CIPHER_CTX_new();
    if (!record->cipher_ctx) {
        fprintf(stderr, "Cipher context allocation failed\n");
        return -1;
    }
    if (EVP_EncryptInit_ex(record->cipher_ctx, EVP_aes_256_cbc(), NULL, key, record->iv) != 1) {
        fprintf(stderr, "Cipher initialization failed\n");
        EVP_CIPHER_CTX_free(record->cipher_ctx);
        return -1;
    }

    return 0;
}

// Function to clean up and free resources
void cleanup_record(Record *record) {
    if (record->cipher_ctx) {
        EVP_CIPHER_CTX_free(record->cipher_ctx);
        record->cipher_ctx = NULL;
    }
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <password>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *password = argv[1];
    int num_records = 100; // Example number of records
    size_t total_memory_usage = sizeof(Record) * num_records;

    if (total_memory_usage > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Exceeded maximum memory usage\n");
        return EXIT_FAILURE;
    }

    Record *records = malloc(total_memory_usage);
    if (!records) {
        perror("Memory allocation failed");
        return EXIT_FAILURE;
    }

    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        if (init_and_encrypt_record(&records[i], password, 1, 100, 1, 50, 10, 100) != 0) {
            fprintf(stderr, "Failed to initialize and encrypt record %d\n", i);
            for (int j = 0; j < i; ++j) {
                cleanup_record(&records[j]);
            }
            free(records);
            return EXIT_FAILURE;
        }
    }

    // Perform operations with records...

    // Cleanup
    for (int i = 0; i < num_records; ++i) {
        cleanup_record(&records[i]);
    }
    free(records);

    return EXIT_SUCCESS;
}
