#define KEY_SIZE 32 // 256 bits
#define IV_SIZE 12  // GCM standard size for IV
#define SALT_SIZE 16
#define ITERATIONS 10000

typedef struct {
    double x, y;
} point;

typedef struct {
    char *name;
    int age;
} user;

void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

void* allocate_memory(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) handle_error("Memory allocation failed");
    return ptr;
}

double* init_double_array(size_t n) {
    double *arr = (double*)allocate_memory(n * sizeof(double));
    for (size_t i = 0; i < n; ++i) arr[i] = (double)i;
    return arr;
}

point* init_point_array(size_t n) {
    point *arr = (point*)allocate_memory(n * sizeof(point));
    for (size_t i = 0; i < n; ++i) {
        arr[i].x = (double)i;
        arr[i].y = (double)(n - i);
    }
    return arr;
}

user* init_user_array(size_t n) {
    user *arr = (user*)allocate_memory(n * sizeof(user));
    for (size_t i = 0; i < n; ++i) {
        char name[20];
        snprintf(name, sizeof(name), "User_%zu", i);
        arr[i].name = strdup(name);
        arr[i].age = 20 + i;
    }
    return arr;
}

int** init_fibonacci_2d_array(size_t rows, size_t cols) {
    int **arr = (int**)allocate_memory(rows * sizeof(int*));
    for (size_t i = 0; i < rows; ++i) {
        arr[i] = (int*)allocate_memory(cols * sizeof(int));
        int a = 0, b = 1;
        for (size_t j = 0; j < cols; ++j) {
            arr[i][j] = a;
            int temp = a + b;
            a = b;
            b = temp;
        }
    }
    return arr;
}

void cleanup(double *arr, size_t n) {
    free(arr);
}

void cleanup_point(point *arr, size_t n) {
    free(arr);
}

void cleanup_user(user *arr, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        free(arr[i].name);
    }
    free(arr);
}

void cleanup_fibonacci(int **arr, size_t rows) {
    for (size_t i = 0; i < rows; ++i) {
        free(arr[i]);
    }
    free(arr);
}

void derive_key_iv(const char *passphrase, unsigned char *salt, unsigned char *key, unsigned char *iv) {
    if (!RAND_bytes(salt, SALT_SIZE)) handle_error("Random salt generation failed");

    EVP_PKEY_CTX *pctx = EVP_PKEY_CTX_new_id(EVP_PKEY_HMAC, NULL);
    if (!pctx) handle_error("EVP_PKEY_CTX creation failed");

    if (EVP_PKEY_derive_init(pctx) <= 0 ||
        EVP_PKEY_CTX_set_hmac_key_length(pctx, KEY_SIZE * 8) <= 0 ||
        EVP_PKEY_CTX_set1_password(pctx, passphrase) <= 0 ||
        EVP_PKEY_CTX_add1_other_pkey(pctx, EVP_PKEY_new_raw_private_key(EVP_PKEY_HMAC, NULL, salt, SALT_SIZE)) <= 0 ||
        EVP_PKEY_derive(pctx, key, &KEY_SIZE) <= 0) {
        handle_error("Key derivation failed");
    }

    if (RAND_bytes(iv, IV_SIZE) <= 0) handle_error("Random IV generation failed");

    EVP_PKEY_free(EVP_PKEY_CTX_get0_pkey(pctx));
    EVP_PKEY_CTX_free(pctx);
}

EVP_CIPHER_CTX* init_cipher(const char *passphrase) {
    unsigned char salt[SALT_SIZE], key[KEY_SIZE], iv[IV_SIZE];
    derive_key_iv(passphrase, salt, key, iv);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) handle_error("EVP_CIPHER_CTX creation failed");

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv) <= 0) {
        handle_error("Cipher initialization failed");
    }

    return ctx;
}

void cleanup_cipher(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
}
