    list->capacity = INITIAL_CAPACITY;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond_var, NULL);
}

void resize_event_list(EventList* list) {
    size_t new_capacity = list->capacity * 2;
    FileEvent** new_events = realloc(list->events, new_capacity * sizeof(FileEvent*));
    if (new_events) {
        list->events = new_events;
        list->capacity = new_capacity;
    }
}

int add_event(EventList* list, FileEvent* event) {
    pthread_mutex_lock(&list->lock);
    if (list->count == list->capacity) {
        resize_event_list(list);
    }

