    while (1) {
        pthread_mutex_lock(&list->lock);

        if (list->count == 0) {
            pthread_cond_wait(&list->cond_var, &list->lock);
        }

        // Process an event
        FileEvent* event = list->events[--list->count];
        printf("Processing event...\n");

        pthread_mutex_unlock(&list->lock);

        // Simulate processing time
        sleep(1);
    }
}

void cleanup(EventList* list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->events[i]->blocks);
        free(list->events[i]);
    }
    free(list->events);
    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond_var);
}

int main() {
    EventList list;
    init_event_list(&list);

    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; ++i) {
