    double value;
} Item;

typedef struct {
    long *offsets;
    int *keys;
    Item **items;
    size_t item_capacity;
    size_t item_count;
    pthread_mutex_t mutex;
    unsigned int rng_state; // For reproducibility
} DataStructure;

static inline unsigned int custom_rng(unsigned int state) {
    return state = (state * 1103515245 + 12345) & ((1 << 31) - 1);
}

unsigned int hash_string(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % (ITEM_ARRAY_INITIAL_CAPACITY);
}

DataStructure* initialize_data_structure() {
    DataStructure *ds = malloc(sizeof(DataStructure));
    if (!ds) {
        perror("Failed to allocate DataStructure");
        return NULL;
    }

    ds->offsets = calloc(OFFSET_ARRAY_SIZE, sizeof(long));
    if (!ds->offsets) {
        perror("Failed to allocate offsets array");
        free(ds);
        return NULL;
    }

    ds->keys = malloc(OFFSET_ARRAY_SIZE * sizeof(int));
    if (!ds->keys) {
        perror("Failed to allocate keys array");
        free(ds->offsets);
        free(ds);
        return NULL;
    }

    ds->items = calloc(ITEM_ARRAY_INITIAL_CAPACITY, sizeof(Item *));
    if (!ds->items) {
        perror("Failed to allocate items array");
        free(ds->keys);
        free(ds->offsets);
        free(ds);
        return NULL;
    }

    for (size_t i = 0; i < OFFSET_ARRAY_SIZE; ++i) {
        ds->offsets[i] = i * 1000L;
        ds->keys[i] = rand() % KEY_ARRAY_MAX_VALUE + 1;
    }

    pthread_mutex_init(&ds->mutex, NULL);
    ds->item_capacity = ITEM_ARRAY_INITIAL_CAPACITY;
    ds->item_count = 0;
    ds->rng_state = 12345; // Seed for reproducibility

    return ds;
}

int add_item(DataStructure *ds, const char *user_str) {
    pthread_mutex_lock(&ds->mutex);

    if (ds->item_count == ds->item_capacity) {
        size_t new_capacity = ds->item_capacity * 2;
        Item **new_items = realloc(ds->items, new_capacity * sizeof(Item *));
        if (!new_items) {
            perror("Failed to resize items array");
            pthread_mutex_unlock(&ds->mutex);
            return -1;
        }
        ds->items = new_items;
        ds->item_capacity = new_capacity;
    }

    Item *new_item = malloc(sizeof(Item));
    if (!new_item) {
        perror("Failed to allocate item");
        pthread_mutex_unlock(&ds->mutex);
        return -1;
    }

    new_item->str = strdup(user_str);
    new_item->value = 0.0;

    ds->items[ds->item_count++] = new_item;

    pthread_mutex_unlock(&ds->mutex);
    return 0;
}

double generate_random_double(double min, double max) {
    unsigned int rng = custom_rng(ds->rng_state);
    double scaled_value = ((double)rng / UINT_MAX) * (max - min) + min;
    ds->rng_state = rng; // Update state
    return scaled_value;
}

void free_data_structure(DataStructure *ds) {
    pthread_mutex_lock(&ds->mutex);

    for (size_t i = 0; i < ds->item_count; ++i) {
        if (ds->items[i]) {
            free(ds->items[i]->str);
            free(ds->items[i]);
        }
    }

    free(ds->offsets);
    free(ds->keys);
    free(ds->items);

    pthread_mutex_unlock(&ds->mutex);
    pthread_mutex_destroy(&ds->mutex);
    free(ds);
}

int main() {
    DataStructure *ds = initialize_data_structure();
    if (!ds) return 1;

    add_item(ds, "Sample Item 1");
    add_item(ds, "Sample Item 2");

    for (size_t i = 0; i < ds->item_count; ++i) {
        printf("Item %zu: %s\n", i, ds->items[i]->str);
    }

    free_data_structure(ds);

    return 0;
}
```

