    MAC_FRAME_DATA frames[10]; // Adjust size as necessary
    size_t frame_count;
} NetworkEvent;

typedef struct Node {
    NetworkEvent data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    size_t capacity; // Size of allocated list
    size_t current_size; // Number of active nodes
} EventList;

EventList* create_event_list(size_t initial_capacity) {
    EventList* list = (EventList*)malloc(sizeof(EventList));
    if (!list) return NULL;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);

    list->head = NULL;
    list->tail = NULL;
    list->capacity = initial_capacity;
    list->current_size = 0;

    return list;
}

int add_event(EventList* list, NetworkEvent event) {
    if (pthread_mutex_lock(&list->lock) != 0)
        return -1;

    if (list->current_size >= list->capacity) {
        size_t new_capacity = list->capacity * 2; // Simple expansion policy
        // Memory management strategies can be applied here

        pthread_mutex_unlock(&list->lock);
        pthread_cond_signal(&list->cond); // Notify potential waiters
        return -1;
    }

    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    node->data = event;
    node->next = NULL;

    if (list->tail) {
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    } else {
        list->head = node;
        list->tail = node;
        node->prev = NULL;
    }

    ++(list->current_size);
    pthread_mutex_unlock(&list->lock);

    return 0;
}

void* iterate_events(EventList* list, int reverse) {
    if (pthread_mutex_lock(&list->lock) != 0)
        return NULL;

    Node** current = reverse ? &list->tail : &list->head;

    while (*current) {
        pthread_mutex_unlock(&list->lock);
        NetworkEvent* event = &((*current)->data);

        // Process the event
        printf("Processing event: %llu\n", event->event.mac_event_tag);

        *current = reverse ? (*current)->prev : (*current)->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void destroy_event_list(EventList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond);
    free(list);
}

// Additional functions for batch processing, error handling, and failover strategies can be implemented here.

int main() {
    EventList* list = create_event_list(10);

    NetworkEvent event;
    event.event.mac_event_tag = 1;
    event.event.timestamp = time(NULL);
    event.frame_count = 0;

    add_event(list, event);

    iterate_events(list, 0);

    destroy_event_list(list);

    return 0;
}
