    time_t timestamp;
    size_t audio_data_size;
    unsigned char *audio_data; // Aligned to cache line size
} AudioEvent;

typedef struct {
    AudioEvent **events;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} AudioEventList;

#define CACHE_LINE_SIZE 64

static inline void align_audio_data(size_t *size, unsigned char **data) {
    size_t padding = (CACHE_LINE_SIZE - (*size % CACHE_LINE_SIZE)) % CACHE_LINE_SIZE;
    *size += padding;
    *data = realloc(*data, *size);
    memset((unsigned char *)*data + (*size - padding), 0, padding); // Padding
}

AudioEventList* create_audio_event_list() {
    AudioEventList *list = malloc(sizeof(AudioEventList));
    if (!list) return NULL;

    list->events = calloc(INITIAL_CAPACITY, sizeof(AudioEvent *));
    if (!list->events) {
        free(list);
        return NULL;
    }

    list->capacity = INITIAL_CAPACITY;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

int add_audio_event(AudioEventList *list, int event_id, time_t timestamp, size_t audio_data_size, unsigned char *audio_data) {
    if (!list || !audio_data) return -1;

    pthread_mutex_lock(&list->mutex);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        AudioEvent **new_events = realloc(list->events, new_capacity * sizeof(AudioEvent *));
        if (!new_events) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failed
        }
        list->events = new_events;
        list->capacity = new_capacity;
    }

    AudioEvent *event = malloc(sizeof(AudioEvent));
    if (!event) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Memory allocation failed
    }

    event->event_id = event_id;
    event->timestamp = timestamp;

    align_audio_data(&audio_data_size, &audio_data);

    event->audio_data_size = audio_data_size;
    event->audio_data = malloc(audio_data_size);
    if (!event->audio_data) {
        free(event);
        pthread_mutex_unlock(&list->mutex);
        return -1; // Memory allocation failed
    }
    memcpy(event->audio_data, audio_data, audio_data_size);

    list->events[list->count++] = event;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int remove_audio_event(AudioEventList *list, int index) {
    if (!list || index < 0 || index >= list->count) return -1;

    pthread_mutex_lock(&list->mutex);

    AudioEvent *event = list->events[index];
    free(event->audio_data);
    free(event);
    memmove(&list->events[index], &list->events[index + 1], (list->count - index - 1) * sizeof(AudioEvent *));
    list->count--;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void destroy_audio_event_list(AudioEventList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->count; ++i) {
        free(list->events[i]->audio_data);
        free(list->events[i]);
    }
    free(list->events);

    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}
```']

