#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>

// Define constants for pool size adjustments.
#define INITIAL_POOL_SIZE 1024
#define GROWTH_FACTOR 2

typedef struct {
    uint64_t MAC_EVENT_TAG;
    time_t timestamp;
} MAC_FRAME_DATA;

typedef struct NetworkEvent {
    uint64_t MAC_EVENT_TAG;
    time_t timestamp;
    int frame_count;
    MAC_FRAME_DATA* frames;
    struct NetworkEvent* next;
} NetworkEvent;

// Memory pool structure
typedef struct {
    size_t block_size;
    size_t current_size;
    size_t max_size;
    void* memory_pool;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool event_pool = { sizeof(NetworkEvent), 0, INITIAL_POOL_SIZE, NULL, PTHREAD_MUTEX_INITIALIZER };

// Logging mechanism (simplified)
void log_memory_usage() {
    printf("Current memory usage: %zu bytes\n", event_pool.current_size);
}

// Memory management functions
NetworkEvent* allocate_network_event() {
    pthread_mutex_lock(&event_pool.lock);

    if (!event_pool.memory_pool || event_pool.current_size >= event_pool.max_size) {
        size_t new_size = event_pool.max_size * GROWTH_FACTOR;
        void* new_pool = realloc(event_pool.memory_pool, new_size * sizeof(NetworkEvent));

        if (!new_pool) {
            pthread_mutex_unlock(&event_pool.lock);
            return NULL; // Handle allocation failure
        }

        event_pool.memory_pool = new_pool;
        event_pool.max_size = new_size;
    }

    NetworkEvent* event = (NetworkEvent*)event_pool.memory_pool + event_pool.current_size++;
    memset(event, 0, sizeof(NetworkEvent));

    pthread_mutex_unlock(&event_pool.lock);
    log_memory_usage();
    return event;
}

void deallocate_network_event(NetworkEvent* event) {
    // For simplicity, we're not freeing individual events in a real scenario.
    // Implement an advanced memory management strategy here if needed.

    // Just decrement the current size
    pthread_mutex_lock(&event_pool.lock);
    event_pool.current_size--;
    pthread_mutex_unlock(&event_pool.lock);
}

// Thread-safe list operations with fine-grained locking
typedef struct {
    NetworkEvent* head;
    pthread_mutex_t lock;
} EventList;

EventList event_list = { NULL, PTHREAD_MUTEX_INITIALIZER };

void add_event(NetworkEvent* event) {
    pthread_mutex_lock(&event_list.lock);

    event->next = event_list.head;
    event_list.head = event;

    pthread_mutex_unlock(&event_list.lock);
}

NetworkEvent* get_next_event() {
    pthread_mutex_lock(&event_list.lock);

    NetworkEvent* event = event_list.head;
    if (event) {
        event_list.head = event->next;
    }

    pthread_mutex_unlock(&event_list.lock);
    return event;
}

// Main processing function
void network_event_processor() {
    while (1) { // Continuously process events
        NetworkEvent* event = get_next_event();
        if (!event) continue; // No event to process

        // Process the event here...

        deallocate_network_event(event);
    }
}

int main() {
    // Initialize and start network event processing
    pthread_t processor_thread;
    pthread_create(&processor_thread, NULL, (void*)network_event_processor, NULL);

    // Simulate adding events for demonstration
    NetworkEvent* event = allocate_network_event();
    if (event) {
        add_event(event);
    }

    pthread_join(processor_thread, NULL);
    return 0;
}
```

