void insertRecord(DoublyLinkedList *list, Record *record) {
    pthread_mutex_lock(&list->lock);

    if (!list->head) {
        list->head = record;
        list->tail = record;
    } else {
        list->tail->next = record;
        record->prev = list->tail;
        list->tail = record;
    }

    pthread_mutex_unlock(&list->lock);
}

void deleteRecord(DoublyLinkedList *list, Record *record) {
    if (!record || !list) return;

    pthread_mutex_lock(&list->lock);

    if (record->prev) record->prev->next = record->next;
    if (record->next) record->next->prev = record->prev;

    if (record == list->head) list->head = record->next;
    if (record == list->tail) list->tail = record->prev;

    pthread_mutex_unlock(&list->lock);
    free(record);
}

Record* getFirstRecord(DoublyLinkedList *list) {
    return list ? list->head : NULL;
}

Record* getLastRecord(DoublyLinkedList *list) {
    return list ? list->tail : NULL;
}

