#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    int value;
} Record;

typedef struct {
    Record **buckets;
    size_t bucket_count;
    size_t record_count;
    float load_factor_threshold;
} HashTable;

unsigned long custom_hash(int key, size_t bucket_count) {
    return (unsigned long)key * 2654435761 % (unsigned long)bucket_count; // A variant of the FNV-1a hash function
}

HashTable* create_hash_table(size_t initial_bucket_count, float load_factor_threshold) {
    HashTable *table = malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = calloc(initial_bucket_count, sizeof(Record *));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->bucket_count = initial_bucket_count;
    table->record_count = 0;
    table->load_factor_threshold = load_factor_threshold;

    return table;
}

void resize_hash_table(HashTable *table);

int insert_record(HashTable *table, long offset, int key, int value) {
    if (!table) return -1;

    if (table->record_count + 1 > table->bucket_count * table->load_factor_threshold) {
        resize_hash_table(table);
    }

    unsigned long index = custom_hash(key, table->bucket_count);
    Record **bucket = &table->buckets[index];

    while (*bucket != NULL) {
        if ((*bucket)->key == key) {
            return -2; // Key already exists
        }
        bucket = &(*bucket)->next;
    }

    *bucket = malloc(sizeof(Record));
    if (!*bucket) return -1;

    (*bucket)->offset = offset;
    (*bucket)->key = key;
    (*bucket)->value = value;
    (*bucket)->next = NULL;

    table->record_count++;

    return 0; // Success
}

void resize_hash_table(HashTable *table) {
    size_t new_bucket_count = table->bucket_count * 2;
    Record **new_buckets = calloc(new_bucket_count, sizeof(Record *));
    if (!new_buckets) return;

    for (size_t i = 0; i < table->bucket_count; ++i) {
        Record *current = table->buckets[i];
        while (current != NULL) {
            Record *next = current->next;
            unsigned long new_index = custom_hash(current->key, new_bucket_count);

            current->next = new_buckets[new_index];
            new_buckets[new_index] = current;

            current = next;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->bucket_count = new_bucket_count;
}

void delete_hash_table(HashTable *table) {
    if (!table) return;

    for (size_t i = 0; i < table->bucket_count; ++i) {
        Record *current = table->buckets[i];
        while (current != NULL) {
            Record *next = current->next;
            free(current);
            current = next;
        }
    }

    free(table->buckets);
    free(table);
}

void print_hash_table(const HashTable *table) {
    if (!table) return;

    for (size_t i = 0; i < table->bucket_count; ++i) {
        const Record *current = table->buckets[i];
        while (current != NULL) {
            printf("Offset: %ld, Key: %d, Value: %d\n", current->offset, current->key, current->value);
            current = current->next;
        }
    }
}

void populate_and_update_hash_table(HashTable *table, size_t num_records, int value_range_min, int value_range_max) {
    if (!table) return;

    srand(time(NULL)); // Seed for random number generation
    for (size_t i = 0; i < num_records; ++i) {
        long offset = rand();
        int key = rand() % 10000;
        insert_record(table, offset, key, value_range_min + rand() % (value_range_max - value_range_min + 1));
    }

    for (size_t i = 0; i < table->bucket_count; ++i) {
        Record *current = table->buckets[i];
        while (current != NULL) {
            current->value = value_range_min + rand() % (value_range_max - value_range_min + 1);
            current = current->next;
        }
    }
}

int main() {
    size_t initial_bucket_count = 16;
    float load_factor_threshold = 0.75f;
    int value_range_min = 10, value_range_max = 100;

    HashTable *table = create_hash_table(initial_bucket_count, load_factor_threshold);
    if (!table) return EXIT_FAILURE;

    populate_and_update_hash_table(table, 1000, value_range_min, value_range_max);

    print_hash_table(table);

    delete_hash_table(table);
    return EXIT_SUCCESS;
}
