#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_PREFS 100

typedef struct {
    char *username;
    char **preferences; // dynamic array of strings for preferences
} UserProfile;

typedef struct {
    time_t timestamp;
    int offset;
    int status_flag; // 0 or 1 representing boolean
    UserProfile *user_profile;
} Record;

// Linked list node to manage user profiles
typedef struct Node {
    int id;
    char *username;
    UserProfile profile;
    struct Node* next;
} Node;

// Global head for user profile linked list and a mutex for thread safety
Node *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void add_user_profile(int id, const char *username);
UserProfile *find_user_profile_by_id(int id);
Record create_record(time_t timestamp, int offset, int status_flag, UserProfile *profile);
void delete_user_profile(int id);
void free_memory(Node *node);

// Utility function to handle memory allocation failures
#define HANDLE_ALLOC_FAIL(ptr) if (!ptr) { perror("Allocation failed"); exit(EXIT_FAILURE); }

// Function to add a new user profile
void add_user_profile(int id, const char *username) {
    pthread_mutex_lock(&lock);

    UserProfile profile;
    profile.username = strdup(username);
    profile.preferences = NULL;

    Node *new_node = malloc(sizeof(Node));
    HANDLE_ALLOC_FAIL(new_node);

    new_node->id = id;
    new_node->username = strdup(username);
    new_node->profile = profile;
    new_node->next = head;

    head = new_node;

    pthread_mutex_unlock(&lock);
}

// Function to find a user profile by ID
UserProfile *find_user_profile_by_id(int id) {
    pthread_mutex_lock(&lock);

    Node *current = head;
    while (current != NULL) {
        if (current->id == id) {
            UserProfile *profile = &current->profile;
            pthread_mutex_unlock(&lock);
            return profile;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
    return NULL; // Profile not found
}

// Function to create a record linked to a user profile
Record create_record(time_t timestamp, int offset, int status_flag, UserProfile *profile) {
    Record record;
    record.timestamp = timestamp;
    record.offset = offset;
    record.status_flag = status_flag;
    record.user_profile = profile;
    return record;
}

// Function to delete a user profile by ID
void delete_user_profile(int id) {
    pthread_mutex_lock(&lock);

    Node **indirect = &head;
    while (*indirect != NULL) {
        if ((*indirect)->id == id) {
            Node *to_delete = *indirect;
            *indirect = to_delete->next;

            free(to_delete->username);
            for (int i = 0; i < MAX_PREFS && to_delete->profile.preferences[i]; ++i) {
                free(to_delete->profile.preferences[i]);
            }
            free(to_delete->profile.preferences);

            free_memory(to_delete);
            pthread_mutex_unlock(&lock);
            return;
        }
        indirect = &(*indirect)->next;
    }

    pthread_mutex_unlock(&lock);
}

// Function to recursively free memory for a node
void free_memory(Node *node) {
    if (node == NULL) return;

    free(node->username);
    for (int i = 0; i < MAX_PREFS && node->profile.preferences[i]; ++i) {
        free(node->profile.preferences[i]);
    }
    free(node->profile.preferences);

    free_memory(node->next);
    free(node);
}

// Additional functions would include:
// - Function to serialize records and profiles into a custom binary format with compression.
// - Mechanisms for interacting with persistent storage (e.g., database operations).
// - Extensible data structure management allowing new profile attributes or types.

int main() {
    // Example usage
    add_user_profile(1, "Alice");
    UserProfile *profile = find_user_profile_by_id(1);

    if (profile) {
        Record record = create_record(time(NULL), 42, 1, profile);

        printf("Record created for user: %s\n", record.user_profile->username);
    }

    delete_user_profile(1);

    return 0;
}
