```c
#include <pthread.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <stdio.h>

#define INITIAL_POOL_SIZE 1000
#define MAX_THREADS 1000

typedef struct {
    uint32_t protocol_id;
    uint32_t message_type;
    uint32_t message_size;
    void *data_blocks; // Pointer to variable-length sequence of blocks
} ProtocolBuffer;

typedef struct {
    ProtocolBuffer **buffers;
    size_t capacity;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} BufferPool;

static BufferPool buffer_pool = {NULL, 0, PTHREAD_MUTEX_INITIALIZER, PTHREAD_COND_INITIALIZER};

void custom_alloc(size_t size, void **ptr) {
    *ptr = aligned_alloc(64, size); // Align to cache line
    if (!*ptr) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
}

void custom_free(void *ptr) {
    free(ptr);
}

int resize_buffer_pool(size_t new_capacity) {
    pthread_mutex_lock(&buffer_pool.mutex);

    ProtocolBuffer **new_buffers = realloc(buffer_pool.buffers, new_capacity * sizeof(ProtocolBuffer *));
    if (!new_buffers) {
        perror("Failed to reallocate buffer pool");
        pthread_mutex_unlock(&buffer_pool.mutex);
        return -1;
    }

    for (size_t i = buffer_pool.capacity; i < new_capacity; ++i) {
        custom_alloc(sizeof(ProtocolBuffer), (void **)&new_buffers[i]);
        memset(new_buffers[i], 0, sizeof(ProtocolBuffer));
    }

    buffer_pool.buffers = new_buffers;
    buffer_pool.capacity = new_capacity;

    pthread_mutex_unlock(&buffer_pool.mutex);
    return 0;
}

int init_buffer_pool() {
    resize_buffer_pool(INITIAL_POOL_SIZE);
    return 0;
}

void log_metrics(size_t utilization, size_t throughput) {
    // Placeholder for integration with a logging framework
    printf("Buffer Pool Utilization: %zu%%\n", (utilization * 100 / buffer_pool.capacity));
    printf("Message Throughput: %zu messages/sec\n", throughput);
}

int add_message_block(uint32_t protocol_id, uint32_t message_type, const void *data, size_t data_size) {
    pthread_mutex_lock(&buffer_pool.mutex);

    for (size_t i = 0; i < buffer_pool.capacity; ++i) {
        ProtocolBuffer *buf = buffer_pool.buffers[i];

        if (!buf->protocol_id && !buf->message_blocks) { // Find an unused buffer
            buf->protocol_id = protocol_id;
            buf->message_type = message_type;
            buf->message_size = data_size;

            custom_alloc(data_size, (void **)&buf->data_blocks);
            memcpy(buf->data_blocks, data, data_size);

            pthread_mutex_unlock(&buffer_pool.mutex);
            return 0; // Success
        }
    }

    // No available buffer found, resize pool
    if (resize_buffer_pool(buffer_pool.capacity * 2) != 0) {
        pthread_mutex_unlock(&buffer_pool.mutex);
        return -1;
    }

    pthread_mutex_unlock(&buffer_pool.mutex);
    return add_message_block(protocol_id, message_type, data, data_size); // Retry after resizing
}

int main() {
    if (init_buffer_pool() != 0) {
        fprintf(stderr, "Failed to initialize buffer pool\n");
        exit(EXIT_FAILURE);
    }

    // Example usage
    const char *message = "Hello, Protocol Buffers!";
    add_message_block(1, 1001, message, strlen(message) + 1);

    log_metrics(INITIAL_POOL_SIZE / 2, INITIAL_POOL_SIZE); // Dummy metrics

    // Clean up
    for (size_t i = 0; i < buffer_pool.capacity; ++i) {
        custom_free(buffer_pool.buffers[i]->data_blocks);
        custom_free(buffer_pool.buffers[i]);
    }
    free(buffer_pool.buffers);

    pthread_mutex_destroy(&buffer_pool.mutex);
    pthread_cond_destroy(&buffer_pool.cond);

    return 0;
}
```

### Key Points:
- **Thread Safety**: Uses a mutex to ensure thread-safe access to the buffer pool.
- **Dynamic Resizing**: Automatically resizes the buffer pool when needed, ensuring no data corruption during resizing.
- **Memory Management**: Custom allocator aligns memory for cache efficiency and handles allocation errors gracefully.
- **Logging Integration**: Placeholder function `log_metrics` simulates integration with a logging framework.
- **Concurrency Considerations**: Designed to minimize contention by using a mutex lock around critical sections.

This implementation provides a foundation for managing protocol buffers in high-throughput network services, ensuring scalability, thread safety, and efficient memory usage.']

