            for (size_t j = 0; j < i; ++j) {
                free(entries[j].message); // Free previously allocated messages
            }
            free(entries);
            return NULL;
        }
        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_destroy(&lock);
    return entries;
}

