        free(entries[i].name);
    }

    // Free arrays
    if (offsets != NULL) {
        free(offsets);
    }
    if (keys != NULL) {
        free(keys);
    }
    if (entries != NULL) {
        free(entries);
    }

    pthread_mutex_unlock(&lock);
}

