#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_TRANSACTIONS 500000000
#define LOG_ROTATION_TIME (24 * 60 * 60) // 24 hours in seconds

typedef struct TransactionItem {
    char* data;
    size_t size;
} TransactionItem;

typedef struct FileBlockData {
    unsigned int block_id;
    char* data;
    size_t size;
} FileBlockData;

typedef struct TransactionEvent {
    char transaction_id[64];
    time_t timestamp;
    TransactionItem* items;
    size_t num_items;
    char file_event_tag[32];
    struct {
        size_t size;
        time_t last_modified;
    } metadata;
    FileBlockData* blocks;
    size_t num_blocks;
} TransactionEvent;

typedef struct Node {
    TransactionEvent event;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    FILE* log_file;
    time_t log_rotation_time;
} TransactionList;

TransactionList* create_transaction_list() {
    TransactionList* list = malloc(sizeof(TransactionList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->log_file = fopen("transaction_log.txt", "a");
    if (!list->log_file) {
        free(list);
        return NULL;
    }
    list->log_rotation_time = time(NULL);

    return list;
}

void log_transaction(TransactionList* list, const char* message) {
    pthread_mutex_lock(&list->lock);
    if (time(NULL) - list->log_rotation_time > LOG_ROTATION_TIME) {
        fclose(list->log_file);
        char new_filename[256];
        snprintf(new_filename, sizeof(new_filename), "transaction_log_%ld.txt", time(NULL));
        rename("transaction_log.txt", new_filename);
        list->log_file = fopen("transaction_log.txt", "a");
        list->log_rotation_time = time(NULL);
    }
    fprintf(list->log_file, "%s\n", message);
    fflush(list->log_file);
    pthread_mutex_unlock(&list->lock);
}

void add_transaction(TransactionList* list, TransactionEvent event) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return;

    memcpy(&new_node->event, &event, sizeof(event));
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    // Add to head for O(1) insertion
    new_node->next = list->head;
    list->head = new_node;

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "Added transaction ID: %s", event.transaction_id);
    log_transaction(list, log_message);

    pthread_mutex_unlock(&list->lock);
}

TransactionEvent* get_transaction(TransactionList* list, const char* transaction_id) {
    Node* current = list->head;

    while (current) {
        if (strcmp(current->event.transaction_id, transaction_id) == 0) {
            return &current->event;
        }
        current = current->next;
    }

    return NULL; // Transaction not found
}

void remove_transaction(TransactionList* list, const char* transaction_id) {
    pthread_mutex_lock(&list->lock);

    Node **indirect = &list->head;
    while (*indirect && strcmp((*indirect)->event.transaction_id, transaction_id) != 0) {
        indirect = &(*indirect)->next;
    }

    if (*indirect) {
        Node* to_delete = *indirect;
        *indirect = to_delete->next;

        char log_message[256];
        snprintf(log_message, sizeof(log_message), "Removed transaction ID: %s", to_delete->event.transaction_id);
        log_transaction(list, log_message);

        free(to_delete);
    }

    pthread_mutex_unlock(&list->lock);
}

void destroy_transaction_list(TransactionList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* next = current->next;

        // Free transaction items
        for (size_t i = 0; i < current->event.num_items; ++i) {
            free(current->event.items[i].data);
        }
        free(current->event.items);

        // Free file block data
        for (size_t i = 0; i < current->event.num_blocks; ++i) {
            free(current->event.blocks[i].data);
        }
        free(current->event.blocks);

        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    fclose(list->log_file);
    free(list);
}

int main() {
    TransactionList* list = create_transaction_list();

    if (!list) {
        fprintf(stderr, "Failed to initialize transaction list\n");
        return EXIT_FAILURE;
    }

    // Example usage
    TransactionEvent event = {
        .transaction_id = "TX12345",
        .timestamp = time(NULL),
        .items = NULL,
        .num_items = 0,
        .file_event_tag = "FILE_TAG",
        .metadata = {1024, time(NULL)},
        .blocks = NULL,
        .num_blocks = 0
    };

    add_transaction(list, event);

    TransactionEvent* retrieved_event = get_transaction(list, "TX12345");
    if (retrieved_event) {
        printf("Transaction ID: %s\n", retrieved_event->transaction_id);
    }

    remove_transaction(list, "TX12345");

    destroy_transaction_list(list);

    return EXIT_SUCCESS;
}
```

