#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    char* log_level;
    char* message;
} log_entry;

char* allocate_message(const char* msg) {
    // Example implementation; actual implementation may vary.
    size_t len = strlen(msg);
    char* allocated_msg = (char*)malloc(len + 1);
    if (!allocated_msg) return NULL;
    strcpy(allocated_msg, msg);
    return allocated_msg;
}

int compact_logs(log_entry** log_array, int num_entries, time_t threshold) {
    int write_index = 0;

    for (int i = 0; i < num_entries; ++i) {
        if (difftime(time(NULL), (*log_array)[i].timestamp) <= threshold) {
            // Move the entry forward
            (*log_array)[write_index] = (*log_array)[i];
            write_index++;
        } else {
            // Free resources for entries older than threshold
            free((*log_array)[i].message);
            (*log_array)[i].message = NULL;
        }
    }

    // Truncate the array to new size
    num_entries = write_index;

    return num_entries;
}

log_entry* initialize_log_entries(int capacity, const char** log_levels, const char** messages) {
    log_entry* log_array = (log_entry*)malloc(capacity * sizeof(log_entry));
    if (!log_array) return NULL;

    for (int i = 0; i < capacity; ++i) {
        time(&log_array[i].timestamp);
        log_array[i].log_level = strdup(log_levels[i]);

        char* message = allocate_message(messages[i]);
        if (!message) {
            // Handle allocation failure: skip entry, free allocated memory
            if (log_array[i].log_level) free(log_array[i].log_level);
            continue;
        }
        log_array[i].message = message;
    }

    return log_array;
}

void free_log_entries(log_entry* log_array, int num_entries) {
    for (int i = 0; i < num_entries; ++i) {
        if (log_array[i].message) free(log_array[i].message);
        if (log_array[i].log_level) free(log_array[i].log_level);
    }
    free(log_array);
}

// Example usage
int main() {
    const char* log_levels[] = {"INFO", "WARN", "ERROR"};
    const char* messages[] = {"System started", "Disk almost full", "User logged in"};

    int capacity = sizeof(log_levels) / sizeof(log_levels[0]);
    time_t threshold = 60 * 60; // Retain logs within the last hour

    log_entry* log_array = initialize_log_entries(capacity, log_levels, messages);
    if (!log_array) {
        fprintf(stderr, "Failed to allocate memory for log entries.\n");
        return EXIT_FAILURE;
    }

    int num_entries = capacity;
    num_entries = compact_logs(&log_array, num_entries, threshold);

    // Log usage and metrics reporting could be added here

    free_log_entries(log_array, num_entries);
    return 0;
}
