#include <pthread.h>
#include <stdlib.h>
#include <stdatomic.h>
#include <string.h>

typedef struct {
    long timestamp;
    int priority;
    char* message;
} entry;

typedef struct {
    atomic_size_t size;
    atomic_size_t capacity;
    entry* entries;
    pthread_mutex_t resize_lock;  // Mutex for resizing operations
} entry_array;

entry* allocate_entry(long timestamp, int priority, const char* msg) {
    entry* e = (entry*)malloc(sizeof(entry));
    if (!e) return NULL;

    e->timestamp = timestamp;
    e->priority = priority;
    e->message = allocate_message(msg);
    return e ? e : free(e), NULL;
}

int resize_entry_array(entry_array* arr, size_t new_capacity) {
    pthread_mutex_lock(&arr->resize_lock);

    entry* new_entries = (entry*)realloc(arr->entries, sizeof(entry) * new_capacity);
    if (!new_entries) {
        pthread_mutex_unlock(&arr->resize_lock);
        return -1;
    }

    arr->entries = new_entries;
    atomic_store(&arr->capacity, new_capacity);
    pthread_mutex_unlock(&arr->resize_lock);

    return 0;
}

entry_array* create_entry_array(size_t initial_capacity) {
    entry_array* arr = (entry_array*)malloc(sizeof(entry_array));
    if (!arr) return NULL;

    pthread_mutex_init(&arr->resize_lock, NULL);
    atomic_store(&arr->size, 0);
    atomic_store(&arr->capacity, initial_capacity);

    arr->entries = (entry*)calloc(initial_capacity, sizeof(entry));
    if (!arr->entries) {
        free(arr);
        return NULL;
    }

    return arr;
}

int add_entry(entry_array* arr, long timestamp, int priority, const char* msg) {
    size_t current_size = atomic_load(&arr->size);

    if (current_size >= atomic_load(&arr->capacity)) {
        size_t new_capacity = atomic_load(&arr->capacity) * 2;
        if (resize_entry_array(arr, new_capacity) != 0) {
            return -1; // Resize failed
        }
    }

    entry* e = allocate_entry(timestamp, priority, msg);
    if (!e) return -1;

    size_t index = atomic_fetch_add(&arr->size, 1);
    arr->entries[index] = *e;
    free(e);

    return 0;
}

void cleanup_entry_array(entry_array* arr) {
    for (size_t i = 0; i < atomic_load(&arr->size); ++i) {
        if (arr->entries[i].message) free(arr->entries[i].message);
    }
    free(arr->entries);
    pthread_mutex_destroy(&arr->resize_lock);
    free(arr);
}

// Mock implementation of allocate_message for demonstration purposes
char* allocate_message(const char* msg) {
    size_t len = strlen(msg) + 1;
    char* new_msg = (char*)malloc(len);
    if (!new_msg) return NULL;
    memcpy(new_msg, msg, len);
    return new_msg;
}
