#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdatomic.h>
#include <time.h>
#include <pthread.h>

typedef struct NetworkPerformanceMetrics {
    uint32_t cellId;
    uint64_t timeStamp;
    double throughput;
} NetworkPerformanceMetrics;

typedef struct Node {
    NetworkPerformanceMetrics data;
    struct Node* next;
} Node;

typedef struct SlabAllocator {
    size_t element_size;
    size_t capacity;
    void** free_list;
    pthread_mutex_t lock; // For slab allocator locking
} SlabAllocator;

#define LOG(fmt, ...) printf("[%s:%d] " fmt "\n", __FILE__, __LINE__, ##__VA_ARGS__)

// Utility to initialize random number generator with a seed.
void init_random(uint64_t seed) {
    srand((unsigned int)(seed ^ time(NULL)));
}

// Thread-safe slab allocator initialization
SlabAllocator* slab_allocator_init(size_t element_size, size_t initial_capacity) {
    SlabAllocator* allocator = (SlabAllocator*)malloc(sizeof(SlabAllocator));
    if (!allocator) return NULL;

    allocator->element_size = element_size;
    allocator->capacity = initial_capacity;
    allocator->free_list = (void**)calloc(initial_capacity, sizeof(void*));

    pthread_mutex_init(&allocator->lock, NULL);

    for (size_t i = 0; i < initial_capacity; ++i) {
        void* block = malloc(element_size);
        if (!block) {
            LOG("Failed to allocate memory block.");
            return NULL;
        }
        allocator->free_list[i] = block;
    }

    LOG("Slab allocator initialized.");
    return allocator;
}

// Allocate an element from the slab allocator
void* slab_allocator_alloc(SlabAllocator* allocator) {
    pthread_mutex_lock(&allocator->lock);
    if (allocator->capacity == 0) {
        pthread_mutex_unlock(&allocator->lock);
        return NULL; // No more free elements
    }

    void* block = allocator->free_list[--allocator->capacity];
    pthread_mutex_unlock(&allocator->lock);

    LOG("Allocated element from slab allocator.");
    return block;
}

// Free all elements in the slab allocator
void slab_allocator_free(SlabAllocator* allocator) {
    pthread_mutex_lock(&allocator->lock);
    for (size_t i = 0; i < allocator->capacity; ++i) {
        free(allocator->free_list[i]);
    }
    free(allocator->free_list);
    pthread_mutex_unlock(&allocator->lock);

    LOG("Freed all elements in slab allocator.");
}

// Create a lock-free linked list node
Node* create_node(NetworkPerformanceMetrics data) {
    Node* node = (Node*)slab_allocator_alloc(global_slab_allocator);
    if (!node) return NULL;

    node->data = data;
    node->next = NULL;

    LOG("Created new node.");
    return node;
}

// Insert node into the lock-free linked list
void insert_node(Node** head, Node* new_node) {
    atomic_store_explicit((atomic_uintptr_t*)head, (uintptr_t)new_node, memory_order_release);

    while (__sync_bool_compare_and_swap(head, NULL, (Node*)new_node)) {
        // Spin-wait loop for lock-free insertion
    }

    LOG("Inserted node into linked list.");
}

// Function to dynamically allocate and initialize the array of metrics
NetworkPerformanceMetrics* init_network_performance_metrics(size_t initial_capacity, uint64_t seed, double min_throughput, double max_throughput) {
    if (!global_slab_allocator) global_slab_allocator = slab_allocator_init(sizeof(Node), initial_capacity * 2);

    NetworkPerformanceMetrics* metrics_array = (NetworkPerformanceMetrics*)malloc(initial_capacity * sizeof(NetworkPerformanceMetrics));
    if (!metrics_array) return NULL;

    init_random(seed);

    for (size_t i = 0; i < initial_capacity; ++i) {
        NetworkPerformanceMetrics metric;
        metric.cellId = i + 1;
        metric.timeStamp = time(NULL); // Just using current time for simplicity
        metric.throughput = min_throughput + ((double)rand() / RAND_MAX * (max_throughput - min_throughput));

        Node* node = create_node(metric);
        if (!node) {
            LOG("Failed to allocate node, memory might be exhausted.");
            break;
        }

        insert_node(&global_head, node);
    }

    return metrics_array;
}

// Free all resources used by the network performance metrics
void free_network_performance_metrics(NetworkPerformanceMetrics* metrics_array) {
    Node* current = global_head;
    while (current) {
        Node* next = current->next;
        slab_allocator_free(global_slab_allocator); // Assuming all nodes are allocated from this allocator.
        free(current);
        current = next;
    }

    if (metrics_array) free(metrics_array);

    LOG("Freed network performance metrics.");
}

SlabAllocator* global_slab_allocator = NULL;
Node* atomic_compare_exchange_head(Node** head, Node* expected, Node* desired) {
    return __atomic_compare_exchange_n(head, &expected, desired, false, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST);
}
Node* global_head = NULL;

int main() {
    NetworkPerformanceMetrics* metrics = init_network_performance_metrics(100, 12345, 0.1, 10.0);

    if (metrics) {
        // Process the metrics
    }

    free_network_performance_metrics(metrics);

    return 0;
}
