#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG tag;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_RX_UE_TAG 1024
#define MIN_RNTI 1
#define MAX_RNTI 65535

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function prototypes
Node* create_node(NFAPI_CRC_INDICATION_PDU_T pdu);
void free_list(Node** head);
int add_to_list(Node** head, NFAPI_CRC_INDICATION_PDU_T pdu);
void shuffle_list(Node* head);

Node* create_node(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = pdu;
    new_node->next = NULL;
    return new_node;
}

void free_list(Node** head) {
    Node* current = *head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int add_to_list(Node** head, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (pdu.RX_UE_INFORMATION_TAG >= MAX_RX_UE_TAG || 
        pdu.RNTI < MIN_RNTI || pdu.RNTI > MAX_RNTI) {
        return -1; // Invalid tag or RNTI
    }

    Node* new_node = create_node(pdu);
    if (!new_node) return -2; // Memory allocation failure

    new_node->next = *head;
    *head = new_node;
    return 0;
}

void shuffle_list(Node* head) {
    if (!head || !head->next) return;

    int count = 0;
    Node* current = head;
    while (current) {
        count++;
        current = current->next;
    }

    srand(time(NULL));
    for (int i = 0; i < count * 10; ++i) { // Shuffle multiple times
        int index1 = rand() % count;
        int index2 = rand() % count;

        Node* prev1 = NULL, *node1 = head;
        while (index1-- && node1->next) {
            prev1 = node1;
            node1 = node1->next;
        }

        Node* prev2 = NULL, *node2 = head;
        while (index2-- && node2->next) {
            prev2 = node2;
            node2 = node2->next;
        }

        if (prev1 == prev2 && node1 == node2) continue; // No swap needed

        if (prev1) prev1->next = node2;
        else head = node2;

        if (prev2) prev2->next = node1;
        else head = node1;

        Node* temp = node1->next;
        node1->next = node2->next;
        node2->next = temp;
    }
}

int main() {
    Node* list_head = NULL;

    // Example usage
    for (int i = 0; i < 100; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = {
            .RX_UE_INFORMATION_TAG = rand() % MAX_RX_UE_TAG,
            .RNTI = MIN_RNTI + (rand() % (MAX_RNTI - MIN_RNTI + 1)),
            .tag = { .CRCFLAG = rand() % 2 }
        };

        if (add_to_list(&list_head, pdu) != 0) {
            printf("Failed to add PDU: RX_UE_INFORMATION_TAG=%d, RNTI=%d\n", 
                   pdu.RX_UE_INFORMATION_TAG, pdu.RNTI);
        }
    }

    shuffle_list(list_head);

    // Process the list...

    free_list(&list_head);
    return 0;
}
