```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_UE_COUNT 10000

typedef struct {
    int ue_id;
    int active_radio_bearers_count;
    int *active_radio_bearers; // Dynamic array of radio bearer IDs
    time_t last_update_timestamp;
} UEContext;

// Simulating external database interface functions
int db_read_ue_context(int ue_id, UEContext *context);
int db_write_ue_context(const UEContext *context);

typedef struct {
    UEContext *contexts[MAX_UE_COUNT];
    pthread_rwlock_t lock; // Reader-writer lock for concurrency control
} UEMgmtSystem;

void initialize_system(UEMgmtSystem *system) {
    for (int i = 0; i < MAX_UE_COUNT; i++) {
        system->contexts[i] = NULL;
    }
    pthread_rwlock_init(&system->lock, NULL);
}

void destroy_context(UEContext *context) {
    if (context != NULL) {
        free(context->active_radio_bearers);
        free(context);
    }
}

int add_or_update_ue_context(UEMgmtSystem *system, int ue_id, const int *radio_bearers, int bearer_count) {
    pthread_rwlock_wrlock(&system->lock);

    UEContext *context = NULL;
    if (db_read_ue_context(ue_id, &context)) {
        context = malloc(sizeof(UEContext));
        if (!context) return -1; // Allocation failure
        context->ue_id = ue_id;
        context->active_radio_bearers_count = bearer_count;
        context->active_radio_bearers = malloc(bearer_count * sizeof(int));
        if (!context->active_radio_bearers) {
            destroy_context(context);
            return -1; // Allocation failure
        }
        memcpy(context->active_radio_bearers, radio_bearers, bearer_count * sizeof(int));
    }

    context->last_update_timestamp = time(NULL);

    for (int i = 0; i < MAX_UE_COUNT; i++) {
        if (system->contexts[i] == NULL || system->contexts[i]->ue_id == ue_id) {
            if (system->contexts[i]) destroy_context(system->contexts[i]);
            system->contexts[i] = context;
            break;
        }
    }

    pthread_rwlock_unlock(&system->lock);

    // Write to database
    return db_write_ue_context(context);
}

time_t get_latest_update_timestamp(UEMgmtSystem *system, int ue_id) {
    time_t timestamp = 0;

    pthread_rwlock_rdlock(&system->lock);
    for (int i = 0; i < MAX_UE_COUNT; i++) {
        if (system->contexts[i] && system->contexts[i]->ue_id == ue_id) {
            timestamp = system->contexts[i]->last_update_timestamp;
            break;
        }
    }
    pthread_rwlock_unlock(&system->lock);

    return timestamp;
}

int main() {
    UEMgmtSystem system;
    initialize_system(&system);

    // Example usage
    int radio_bearers[] = {1, 2, 3};
    add_or_update_ue_context(&system, 1234, radio_bearers, 3);
    time_t timestamp = get_latest_update_timestamp(&system, 1234);

    printf("Last update timestamp: %ld\n", timestamp);

    // Cleanup
    for (int i = 0; i < MAX_UE_COUNT; i++) {
        destroy_context(system.contexts[i]);
    }
    pthread_rwlock_destroy(&system.lock);

    return 0;
}
```

This code includes:

- **Thread-Safety**: Uses a reader-writer lock (`pthread_rwlock_t`) to manage concurrent access, optimizing for scenarios with more read operations than writes.
- **Memory Management**: Handles dynamic memory allocation and deallocation for UE contexts and their associated data.
- **Database Integration**: Simulated database interaction through `db_read_ue_context` and `db_write_ue_context`.
- **Error Handling**: Basic error handling for memory allocation failures. Additional logging and error handling should be implemented as needed.

This design supports high concurrency, efficient read/write operations, and can be easily scaled horizontally by distributing the load across multiple instances of this system.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct metadata {
    unsigned long access_count;
    double insertion_time;
    double deletion_time;
} metadata_t;

typedef struct node {
    int key;
    struct node *left, *right;
    metadata_t meta;
} node_t;

#define CACHE_SIZE 128
node_t* cache[CACHE_SIZE];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

// Function prototypes
void initialize_cache();
int insert(node_t** root, int key);
int delete_node(node_t** root, int key);
node_t* search(node_t* root, int key);
void serialize_tree(node_t* root, FILE* file);
node_t* deserialize_tree(FILE* file);
void free_tree(node_t* root);
void log_performance(metadata_t meta);

// Initialize cache
void initialize_cache() {
    for (int i = 0; i < CACHE_SIZE; ++i) {
        cache[i] = NULL;
    }
}

// Hash function for caching
unsigned int hash_key(int key) {
    return key % CACHE_SIZE;
}

// Insert node with thread safety and logging
int insert(node_t** root, int key) {
    pthread_mutex_lock(&lock);

    time_t start_time = clock();
    // BST insertion logic here...
    node_t* newNode = (node_t*)malloc(sizeof(node_t));
    if (!newNode) {
        pthread_mutex_unlock(&lock);
        return -1;  // Memory allocation failure
    }
    newNode->key = key;
    newNode->left = newNode->right = NULL;

    unsigned int cache_index = hash_key(key);
    cache[cache_index] = newNode;

    time_t end_time = clock();
    metadata_t meta = {0, (double)(end_time - start_time) / CLOCKS_PER_SEC, 0.0};
    log_performance(meta);

    pthread_mutex_unlock(&lock);
    return 0;
}

// Delete node with thread safety and logging
int delete_node(node_t** root, int key) {
    pthread_mutex_lock(&lock);

    time_t start_time = clock();
    // BST deletion logic here...
    unsigned int cache_index = hash_key(key);
    if (cache[cache_index]) {
        free(cache[cache_index]);
        cache[cache_index] = NULL;
    }

    time_t end_time = clock();
    metadata_t meta = {0, 0.0, (double)(end_time - start_time) / CLOCKS_PER_SEC};
    log_performance(meta);

    pthread_mutex_unlock(&lock);
    return 0;
}

// Search node with caching
node_t* search(node_t* root, int key) {
    unsigned int cache_index = hash_key(key);
    if (cache[cache_index]) {
        return cache[cache_index];
    }

    // BST search logic here...
    pthread_mutex_lock(&lock);

    node_t* result = NULL;
    // Search for the node
    if (result) {
        cache[cache_index] = result;
    }

    pthread_mutex_unlock(&lock);
    return result;
}

// Serialize tree to file
void serialize_tree(node_t* root, FILE* file) {
    if (!root) return;

    fwrite(&(root->key), sizeof(int), 1, file);
    serialize_tree(root->left, file);
    serialize_tree(root->right, file);
}

// Deserialize tree from file
node_t* deserialize_tree(FILE* file) {
    int key;
    if (fread(&key, sizeof(int), 1, file)) {
        node_t* newNode = (node_t*)malloc(sizeof(node_t));
        if (!newNode) return NULL;

        newNode->key = key;
        newNode->left = deserialize_tree(file);
        newNode->right = deserialize_tree(file);

        return newNode;
    }
    return NULL;
}

// Free the entire tree
void free_tree(node_t* root) {
    if (root) {
        free_tree(root->left);
        free_tree(root->right);
        free(root);
    }
}

// Log performance of operations
void log_performance(metadata_t meta) {
    // Logging logic here...
    printf("Access Count: %lu, Insertion Time: %.6f, Deletion Time: %.6f\n",
           meta.access_count, meta.insertion_time, meta.deletion_time);
}

int main() {
    node_t* root = NULL;
    initialize_cache();

    srand(time(NULL));
    int N = 1000;

    for (int i = 0; i < N; ++i) {
        int key = rand() % 10000;
        insert(&root, key);
    }

    FILE *file = fopen("bst_serialized.dat", "wb");
    if (file) {
        serialize_tree(root, file);
        fclose(file);
    }

    free_tree(root);
    return 0;
}
```']

