void shuffleList(NFAPI_CRC_INDICATION_PDU_T *list, int count);
void freeList(NFAPI_CRC_INDICATION_PDU_T *list, int count);

NFAPI_CRC_INDICATION_PDU_T* populateAndShuffleCRCIndications(int N) {
    if (N <= 0) return NULL;

    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        // Log memory allocation failure
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    int count = 0;
    for (int i = 0; i < N; ++i) {
        int tag = rand() % MAX_RX_UE_INFO_TAG + 1;
        int rnti = rand() % MAX_RNTI + 1;

        if (!validateAndAddRecord(list, count, tag, rnti)) {
            fprintf(stderr, "Validation or duplication error\n");
            freeList(list, i);
            return NULL;
        }

        list[count].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG
    }

    shuffleList(list, count);

    // Log memory allocation success and number of records processed
    printf("Memory allocated for %d records\n", N);

    return list;
}

int validateAndAddRecord(NFAPI_CRC_INDICATION_PDU_T *list, int count, int new_tag, int new_rnti) {
    if (new_tag <= 0 || new_tag > MAX_RX_UE_INFO_TAG ||
        new_rnti <= 0 || new_rnti > MAX_RNTI) {
        return 0; // Invalid tag or RNTI
    }

    for (int i = 0; i < count; ++i) {
        if ((list[i].RX_UE_INFORMATION_TAG == new_tag && list[i].RNTI == new_rnti) ||
            list[i].RX_UE_INFORMATION_TAG == new_tag || list[i].RNTI == new_rnti) {
            return 0; // Duplicate found
        }
    }

    list[count].RX_UE_INFORMATION_TAG = new_tag;
    list[count].RNTI = new_rnti;
    return 1;
}

void shuffleList(NFAPI_CRC_INDICATION_PDU_T *list, int count) {
    for (int i = count - 1; i > 0; --i) {
        int j = rand() % (i + 1);
        NFAPI_CRC_INDICATION_PDU_T temp = list[i];
        list[i] = list[j];
        list[j] = temp;
    }

    // Sort records with identical tags by RNTI in descending order
    for (int i = 0; i < count - 1; ++i) {
        if (list[i].RX_UE_INFORMATION_TAG == list[i + 1].RX_UE_INFORMATION_TAG) {
            if (list[i].RNTI < list[i + 1].RNTI) {
                NFAPI_CRC_INDICATION_PDU_T temp = list[i];
                list[i] = list[i + 1];
                list[i + 1] = temp;
            }
        }
    }
}

void freeList(NFAPI_CRC_INDICATION_PDU_T *list, int count) {
    free(list);
    // Log memory deallocation
    printf("Memory freed for %d records\n", count);
}
