#include <stdio.h>
#include <stdlib.h>
import time
from threading import Lock, Thread
import logging

#define MAX_AMOUNT 1000000
#define MAX_SYSTEM_MEMORY 10485760 // Example: 10 MB limit for transactions
#define RETRY_ATTEMPTS 3
#define RETRY_BACKOFF_MS 100
#define CACHE_SIZE 100

typedef struct {
    time_t timestamp;
    int transaction_id;
    double amount;
    char status[20];
} Transaction;

typedef struct {
    Transaction *transactions;
    size_t capacity;
    size_t count;
    Lock lock;
    size_t memory_usage;
    Transaction **cache;
    size_t cache_size;
    size_t cache_count;
} TransactionCollection;

void initialize_cache(TransactionCollection *collection) {
    collection->cache = (Transaction **)malloc(CACHE_SIZE * sizeof(Transaction *));
    if (!collection->cache) {
        fprintf(stderr, "Cache initialization failed.\n");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < CACHE_SIZE; ++i) {
        collection->cache[i] = NULL;
    }
    collection->cache_size = CACHE_SIZE;
    collection->cache_count = 0;
}

void free_cache(TransactionCollection *collection) {
    if (collection->cache) {
        free(collection->cache);
        collection->cache = NULL;
    }
}

Transaction* find_in_cache(TransactionCollection *collection, int transaction_id) {
    for (size_t i = 0; i < collection->cache_count; ++i) {
        if (collection->cache[i] && collection->cache[i]->transaction_id == transaction_id) {
            return collection->cache[i];
        }
    }
    return NULL;
}

void add_to_cache(TransactionCollection *collection, Transaction *transaction) {
    if (collection->cache_count < CACHE_SIZE) {
        collection->cache[collection->cache_count++] = transaction;
    } else {
        // Simple eviction strategy: Replace the first one
        free(collection->cache[0]);
        for (size_t i = 1; i < CACHE_SIZE; ++i) {
            collection->cache[i - 1] = collection->cache[i];
        }
        collection->cache[CACHE_SIZE - 1] = transaction;
    }
}

int validate_transaction_amount(double amount) {
    return amount > 0 && amount <= MAX_AMOUNT;
}

void log_error(const char *message) {
    logging.error(message);
}

TransactionCollection* create_transaction_collection(size_t initial_capacity, size_t system_memory_limit) {
    TransactionCollection *collection = (TransactionCollection *)malloc(sizeof(TransactionCollection));
    if (!collection) {
        fprintf(stderr, "Memory allocation failed for transaction collection.\n");
        return NULL;
    }
    collection->transactions = (Transaction *)calloc(initial_capacity, sizeof(Transaction));
    if (!collection->transactions) {
        free(collection);
        fprintf(stderr, "Memory allocation failed for transactions.\n");
        return NULL;
    }
    collection->capacity = initial_capacity;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
    collection->memory_usage = initial_capacity * sizeof(Transaction);
    initialize_cache(collection);

    if (collection->memory_usage > system_memory_limit) {
        fprintf(stderr, "Initial memory usage exceeds system limit.\n");
        free_transaction_collection(collection);
        return NULL;
    }
    return collection;
}

void free_transaction_collection(TransactionCollection *collection) {
    if (collection) {
        for (size_t i = 0; i < collection->count; ++i) {
            free(collection->transactions[i].status); // Assuming dynamic allocation of status strings
        }
        free(collection->transactions);
        pthread_mutex_destroy(&collection->lock);
        free_cache(collection);
        free(collection);
    }
}

void retry_with_backoff(void (*func)(void), int attempts, int backoff_ms) {
    for (int i = 0; i < attempts; ++i) {
        func();
        if (/* condition to check success */) {
            return;
        }
        sleep(backoff_ms / 1000.0); // Convert ms to seconds
    }
}

void add_transaction(TransactionCollection *collection, Transaction transaction) {
    pthread_mutex_lock(&collection->lock);

    retry_with_backoff(() => {
        // Simulate external data source validation
        if (!validate_transaction_amount(transaction.amount)) {
            log_error("Invalid transaction amount detected.");
            return;
        }

        if (transaction.amount < 0 || transaction.amount > MAX_AMOUNT) {
            log_error("Transaction amount out of range.");
            pthread_mutex_unlock(&collection->lock);
            return;
        }
    }, RETRY_ATTEMPTS, RETRY_BACKOFF_MS);

    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Transaction *new_transactions = realloc(collection->transactions, new_capacity * sizeof(Transaction));
        if (!new_transactions) {
            fprintf(stderr, "Memory reallocation failed.\n");
            pthread_mutex_unlock(&collection->lock);
            return;
        }
        collection->transactions = new_transactions;
        collection->capacity = new_capacity;
    }

    transaction.timestamp = time(NULL); // Assign current timestamp
    strncpy(transaction.status, "Pending", sizeof(transaction.status) - 1);

    collection->transactions[collection->count] = transaction;
    ++collection->count;

    add_to_cache(collection, &collection->transactions[collection->count - 1]);
    pthread_mutex_unlock(&collection->lock);
}

Transaction* get_transaction_by_id(TransactionCollection *collection, int transaction_id) {
    Transaction *cached_txn = find_in_cache(collection, transaction_id);
    if (cached_txn) return cached_txn;

    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->transactions[i].transaction_id == transaction_id) {
            add_to_cache(collection, &collection->transactions[i]);
            pthread_mutex_unlock(&collection->lock);
            return &collection->transactions[i];
        }
    }
    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

void process_transactions(TransactionCollection *collection, Transaction transactions[], size_t num_transactions) {
    for (size_t i = 0; i < num_transactions; ++i) {
        add_transaction(collection, transactions[i]);
    }
}

int main() {
    logging.basicConfig(level=logging.ERROR);

    size_t system_memory_limit = MAX_SYSTEM_MEMORY;
    size_t initial_capacity = 10;

    TransactionCollection *collection = create_transaction_collection(initial_capacity, system_memory_limit);
    if (!collection) return EXIT_FAILURE;

    // Example transactions
    Transaction example_transactions[] = {
        { .transaction_id = 1, .amount = 500.0 },
        { .transaction_id = 2, .amount = -100.0 }, // Invalid transaction for testing
        { .transaction_id = 3, .amount = 1500.0 }
    };

    process_transactions(collection, example_transactions, sizeof(example_transactions) / sizeof(Transaction));

    Transaction *txn = get_transaction_by_id(collection, 1);
    if (txn) {
        printf("Transaction ID: %d, Amount: %.2f\n", txn->transaction_id, txn->amount);
    } else {
        printf("Transaction not found.\n");
    }

    free_transaction_collection(collection);

    return EXIT_SUCCESS;
}
