['Below is a C function that manages memory for an array of `record` structures. It includes dynamic resizing, initialization with random values, sorting, thread safety using mutexes, and graceful handling of allocation failures.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define MAX_ID_LENGTH 50
#define RAND_KEY_MIN 0
#define RAND_KEY_MAX 100

typedef struct {
    long offset;
    int key;
    char *id;
} record;

typedef struct {
    record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} record_array;

// Function prototypes
int init_record_array(record_array *arr);
void free_record_array(record_array *arr);
int resize_record_array(record_array *arr, size_t new_capacity);
int initialize_records(record_array *arr, size_t num_records);
int generate_unique_id(char *id, size_t max_length);
int sort_records_by_key(record_array *arr);

// Initialize the record array
int init_record_array(record_array *arr) {
    arr->records = NULL;
    arr->capacity = 0;
    arr->count = 0;
    if (pthread_mutex_init(&arr->lock, NULL) != 0) {
        return -1; // Mutex initialization failed
    }
    return resize_record_array(arr, INITIAL_CAPACITY);
}

// Free the record array resources
void free_record_array(record_array *arr) {
    pthread_mutex_lock(&arr->lock);
    for (size_t i = 0; i < arr->count; ++i) {
        free(arr->records[i].id);
    }
    free(arr->records);
    pthread_mutex_unlock(&arr->lock);
    pthread_mutex_destroy(&arr->lock);
}

// Resize the record array
int resize_record_array(record_array *arr, size_t new_capacity) {
    pthread_mutex_lock(&arr->lock);
    record *new_records = realloc(arr->records, new_capacity * sizeof(record));
    if (!new_records) {
        pthread_mutex_unlock(&arr->lock);
        return -1; // Memory allocation failed
    }
    arr->records = new_records;
    arr->capacity = new_capacity;
    pthread_mutex_unlock(&arr->lock);
    return 0;
}

// Initialize records with random keys and unique IDs
int initialize_records(record_array *arr, size_t num_records) {
    if (num_records > arr->capacity) {
        if (resize_record_array(arr, num_records) != 0) {
            return -1; // Resize failed
        }
    }

    srand(time(NULL)); // Seed random number generator

    pthread_mutex_lock(&arr->lock);
    for (size_t i = 0; i < num_records; ++i) {
        arr->records[i].offset = rand(); // Random offset
        arr->records[i].key = RAND_KEY_MIN + rand() % (RAND_KEY_MAX - RAND_KEY_MIN + 1); // Random key within range

        char id[MAX_ID_LENGTH];
        if (generate_unique_id(id, MAX_ID_LENGTH) != 0 || !id[0]) {
            pthread_mutex_unlock(&arr->lock);
            return -1; // ID generation failed
        }
        arr->records[i].id = malloc(MAX_ID_LENGTH + 1);
        if (!arr->records[i].id) {
            pthread_mutex_unlock(&arr->lock);
            return -1; // Memory allocation for ID failed
        }
        strcpy(arr->records[i].id, id);
    }
    arr->count = num_records;
    pthread_mutex_unlock(&arr->lock);

    // Sort records by key
    if (sort_records_by_key(arr) != 0) {
        return -1; // Sorting failed
    }

    return 0;
}

// Generate a unique ID for each record
int generate_unique_id(char *id, size_t max_length) {
    static int id_counter = 0;
    snprintf(id, max_length, "ID%06d", ++id_counter);
    return 0; // Unique ID generation successful
}

// Sort records by key using a simple bubble sort (for demonstration)
int sort_records_by_key(record_array *arr) {
    pthread_mutex_lock(&arr->lock);
    for (size_t i = 0; i < arr->count - 1; ++i) {
        for (size_t j = 0; j < arr->count - i - 1; ++j) {
            if (arr->records[j].key > arr->records[j + 1].key) {
                record temp = arr->records[j];
                arr->records[j] = arr->records[j + 1];
                arr->records[j + 1] = temp;
            }
        }
    }
    pthread_mutex_unlock(&arr->lock);
    return 0; // Sorting successful
}

// Main function for testing
int main() {
    record_array arr;
    if (init_record_array(&arr) != 0) {
        fprintf(stderr, "Failed to initialize record array\n");
        return EXIT_FAILURE;
    }

    size_t num_records = 20;
    if (initialize_records(&arr, num_records) != 0) {
        fprintf(stderr, "Failed to initialize records\n");
        free_record_array(&arr);
        return EXIT_FAILURE;
    }

    // Print sorted records
    for (size_t i = 0; i < arr.count; ++i) {
        printf("Record %zu: Key=%d, ID=%s\n", i + 1, arr.records[i].key, arr.records[i].id);
    }

    free_record_array(&arr);
    return EXIT_SUCCESS;
}
```

### Design Choices and Considerations:

1. **Dynamic Resizing**: The function uses a dynamic array with periodic resizing to balance memory usage and access speed. This avoids the fragmentation issues of linked lists while maintaining efficient access.

2. **Thread Safety**: A mutex is used to ensure thread safety during operations that modify shared data, preventing race conditions.

3. **Unique IDs**: Simple counter-based unique IDs are generated for each record, ensuring uniqueness with minimal overhead.

4. **Sorting Algorithm**: A basic bubble sort is used for demonstration purposes; in practice, a more efficient algorithm like quicksort or mergesort would be preferable for large datasets.

5. **Error Handling**: The function returns specific error codes for allocation failures and ensures all resources are freed during cleanup to prevent memory leaks.

6. **Scalability and Maintainability**: The design allows for easy adjustments to capacity, ID generation logic, and sorting mechanisms, facilitating future enhancements and debugging.']

