```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>

typedef struct {
    int intValue;
    long longValue;
    double doubleValue;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
    struct Node* prev;
} Node;

// Balanced tree structure
typedef struct TreeNode {
    Record record;
    struct TreeNode* left;
    struct TreeNode* right;
    int height;
} TreeNode;

Node* head = NULL;
pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;
TreeNode* root = NULL;

void signalHandler(int signum) {
    // Handle graceful shutdown
    printf("Signal %d received. Cleaning up...\n", signum);
    exit(signum);
}

int initRandom() {
    srand(time(NULL));
    return 1;
}

Record randomRecord() {
    Record rec;
    rec.intValue = rand() % 100;  // Adjust range as needed
    rec.longValue = rand() % 1000L;
    rec.doubleValue = (double)rand() / RAND_MAX * 100.0;
    return rec;
}

Node* createNode(Record record) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate memory for node");
        exit(EXIT_FAILURE);
    }
    newNode->record = record;
    newNode->next = NULL;
    newNode->prev = NULL;
    return newNode;
}

void appendToDoublyLinkedList(Record record) {
    Node* newNode = createNode(record);

    pthread_mutex_lock(&listMutex);
    if (!head) {
        head = newNode;
    } else {
        Node* temp = head;
        while (temp->next) {
            temp = temp->next;
        }
        temp->next = newNode;
        newNode->prev = temp;
    }
    pthread_mutex_unlock(&listMutex);
}

int height(TreeNode* N) {
    if (N == NULL)
        return 0;
    return N->height;
}

TreeNode* rightRotate(TreeNode* y) {
    TreeNode* x = y->left;
    TreeNode* T2 = x->right;

    x->right = y;
    y->left = T2;

    y->height = (y->left ? height(y->left) : 0) > (y->right ? height(y->right) : 0) ? 
                (y->left ? height(y->left) : 0) + 1 : (y->right ? height(y->right) : 0) + 1;
    x->height = (x->left ? height(x->left) : 0) > (x->right ? height(x->right) : 0) ? 
                (x->left ? height(x->left) : 0) + 1 : (x->right ? height(x->right) : 0) + 1;

    return x;
}

TreeNode* leftRotate(TreeNode* x) {
    TreeNode* y = x->right;
    TreeNode* T2 = y->left;

    y->left = x;
    x->right = T2;

    x->height = (x->left ? height(x->left) : 0) > (x->right ? height(x->right) : 0) ?
                (x->left ? height(x->left) : 0) + 1 : (x->right ? height(x->right) : 0) + 1;
    y->height = (y->left ? height(y->left) : 0) > (y->right ? height(y->right) : 0) ?
                (y->left ? height(y->left) : 0) + 1 : (y->right ? height(y->right) : 0) + 1;

    return y;
}

int getBalance(TreeNode* N) {
    if (N == NULL)
        return 0;
    return height(N->left) - height(N->right);
}

TreeNode* insertNode(TreeNode* node, Record record) {
    if (node == NULL)
        return createNode(record);

    if (record.intValue < node->record.intValue)
        node->left = insertNode(node->left, record);
    else if (record.intValue > node->record.intValue)
        node->right = insertNode(node->right, record);
    else
        return node;

    node->height = 1 + ((node->left ? height(node->left) : 0) > 
                        (node->right ? height(node->right) : 0) ? 
                        (node->left ? height(node->left) : 0) : 
                        (node->right ? height(node->right) : 0));

    int balance = getBalance(node);

    if (balance > 1 && record.intValue < node->left->record.intValue)
        return rightRotate(node);
    if (balance < -1 && record.intValue > node->right->record.intValue)
        return leftRotate(node);
    if (balance > 1 && record.intValue > node->left->record.intValue) {
        node->left = leftRotate(node->left);
        return rightRotate(node);
    }
    if (balance < -1 && record.intValue < node->right->record.intValue) {
        node->right = rightRotate(node->right);
        return leftRotate(node);
    }

    return node;
}

void logPerformanceMetrics(const char* message) {
    // Placeholder for logging performance metrics
    printf("%s\n", message);
}

void executeCommand(const char* command) {
    FILE *fp;
    char result[1024];

    if ((fp = popen(command, "r")) == NULL) {
        perror("popen failed");
        return;
    }

    while (fgets(result, sizeof(result), fp) != NULL)
        printf("%s", result);

    pclose(fp);
}

void setupSignalHandling() {
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);
}

int main() {
    initRandom();
    setupSignalHandling();

    // Initialize data structures with random values
    for (int i = 0; i < 10; i++) {  // Adjust loop count as needed
        Record rec = randomRecord();
        appendToDoublyLinkedList(rec);
        root = insertNode(root, rec);
    }

    executeCommand("ls -l");  // Example command

    logPerformanceMetrics("Execution completed successfully");

    return 0;
}
```

### Key Points:
- **Random Initialization**: Uses `rand()` for generating random values within specified ranges.
- **Data Structures**: Doubly linked list and AVL tree (self-balancing binary search tree) are implemented.
- **Concurrency**: Uses mutexes to ensure thread safety when modifying the doubly linked list.
- **Signal Handling**: Graceful shutdown on receiving signals like SIGINT or SIGTERM.
- **Command Execution**: Uses `popen` for executing shell commands and capturing output.
- **Error Handling**: Includes basic error handling for memory allocation and command execution.

This code provides a foundation for managing distributed file processing with considerations for concurrency, efficient data management, and robustness against failures. Adjustments may be needed based on specific requirements or constraints of the deployment environment.']

['Below is a simplified implementation of a dynamic log management system in C that meets the outlined requirements. This example focuses on the core functionalities and uses POSIX threads for concurrency control.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

#define MAX_LOG_SIZE 1024
#define MEMORY_POOL_SIZE 10

typedef struct {
    time_t timestamp;
    int user_id;
    char message[MAX_LOG_SIZE];
} LogEntry;

typedef struct {
    LogEntry entries[MEMORY_POOL_SIZE];
    pthread_mutex_t lock;
    size_t count;
} LogManager;

LogManager log_manager = {.count = 0, .lock = PTHREAD_MUTEX_INITIALIZER};

void init_log_manager() {
    pthread_mutex_init(&log_manager.lock, NULL);
}

int add_log_entry(int user_id, const char *message) {
    pthread_mutex_lock(&log_manager.lock);

    if (log_manager.count >= MEMORY_POOL_SIZE) {
        pthread_mutex_unlock(&log_manager.lock);
        return -1; // Memory pool full
    }

    LogEntry *entry = &log_manager.entries[log_manager.count++];
    entry->timestamp = time(NULL);
    entry->user_id = user_id;
    strncpy(entry->message, message, MAX_LOG_SIZE);

    pthread_mutex_unlock(&log_manager.lock);
    return 0; // Success
}

int get_log_entry(size_t index, LogEntry *entry) {
    pthread_mutex_lock(&log_manager.lock);

    if (index >= log_manager.count) {
        pthread_mutex_unlock(&log_manager.lock);
        return -1; // Index out of bounds
    }

    *entry = log_manager.entries[index];
    pthread_mutex_unlock(&log_manager.lock);
    return 0; // Success
}

void delete_log_entry(size_t index) {
    pthread_mutex_lock(&log_manager.lock);

    if (index < log_manager.count) {
        memmove(&log_manager.entries[index], &log_manager.entries[index + 1],
                (log_manager.count - index - 1) * sizeof(LogEntry));
        log_manager.count--;
    }

    pthread_mutex_unlock(&log_manager.lock);
}

void prune_logs() {
    pthread_mutex_lock(&log_manager.lock);

    // Example pruning strategy: remove half of the logs
    if (log_manager.count > 0) {
        size_t new_count = log_manager.count / 2;
        memmove(log_manager.entries, &log_manager.entries[new_count],
                new_count * sizeof(LogEntry));
        log_manager.count = new_count;
    }

    pthread_mutex_unlock(&log_manager.lock);
}

void cleanup_log_manager() {
    pthread_mutex_destroy(&log_manager.lock);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <command>\n", argv[0]);
        return EXIT_FAILURE;
    }

    init_log_manager();

    // Example usage
    add_log_entry(1, "This is a test log message.");
    LogEntry entry;
    if (get_log_entry(0, &entry) == 0) {
        printf("Log: %s\n", entry.message);
    }

    prune_logs();
    delete_log_entry(0);

    cleanup_log_manager();
    return EXIT_SUCCESS;
}
```

### Key Points:

- **Concurrency Control**: Uses `pthread_mutex_t` for thread-safe operations.
- **Resource Management**: Implements a simple memory pool and pruning strategy.
- **Performance Optimization**: Minimizes lock contention by using fine-grained locking.
- **Scalability**: Supports dynamic log entry management with basic pruning.
- **Error Reporting**: Provides basic error handling for out-of-bounds access.
- **Integration & Configuration**: Simplified example; extend with APIs and runtime configuration as needed.

This implementation is a starting point. For production use, consider expanding it to handle disk persistence, asynchronous I/O, and more sophisticated resource management.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct OffsetNode {
    long offset;
    struct OffsetNode* next;
} OffsetNode;

typedef struct Record {
    int value;
    double weight;
    double metadata;
    OffsetNode* offsets;
    int* secondaryKeyRef;
} Record;

typedef struct Stats {
    size_t totalAllocated;
    size_t numRecords;
} Stats;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
Stats stats = {0, 0};

#define ALLOCATION_ERROR -1

// Function to log memory operations
void log_memory_operation(const char* operation, size_t bytes) {
    printf("Operation: %s, Bytes: %zu\n", operation, bytes);
}

// Function to allocate and initialize records
int create_records(Record** records, int numRecords, int intValueRange, double weightRange, double metadataRange, int offsetsPerRecord) {
    if (numRecords <= 0 || intValueRange <= 0 || weightRange <= 0 || metadataRange <= 0 || offsetsPerRecord <= 0) {
        return ALLOCATION_ERROR;
    }

    *records = malloc(numRecords * sizeof(Record));
    if (*records == NULL) {
        log_memory_operation("Failed Allocation", numRecords * sizeof(Record));
        return ALLOCATION_ERROR;
    }
    stats.totalAllocated += numRecords * sizeof(Record);
    stats.numRecords = numRecords;

    pthread_mutex_lock(&mutex);

    for (int i = 0; i < numRecords; ++i) {
        (*records)[i].value = rand() % intValueRange + 1;
        (*records)[i].weight = ((double)rand() / RAND_MAX) * weightRange;
        (*records)[i].metadata = ((double)rand() / RAND_MAX) * metadataRange;

        OffsetNode* head = NULL;
        long usedOffsets[off_t] = {0};
        for (int j = 0; j < offsetsPerRecord; ++j) {
            long offset;
            do {
                offset = rand();
            } while (usedOffsets[offset % (sizeof(usedOffsets) / sizeof(long))]++);

            OffsetNode* newNode = malloc(sizeof(OffsetNode));
            if (newNode == NULL) {
                log_memory_operation("Failed Allocation", sizeof(OffsetNode));
                // Free allocated memory
                while (head != NULL) {
                    OffsetNode* temp = head;
                    head = head->next;
                    free(temp);
                }
                free(*records);
                stats.totalAllocated -= numRecords * sizeof(Record);
                stats.numRecords = 0;
                pthread_mutex_unlock(&mutex);
                return ALLOCATION_ERROR;
            }
            newNode->offset = offset;
            newNode->next = head;
            head = newNode;
        }

        (*records)[i].offsets = head;

        int* keyRef = malloc(sizeof(int));
        if (keyRef == NULL) {
            log_memory_operation("Failed Allocation", sizeof(int));
            // Free allocated memory
            while (head != NULL) {
                OffsetNode* temp = head;
                head = head->next;
                free(temp);
            }
            for (int k = 0; k < i; ++k) {
                OffsetNode* current = (*records)[k].offsets;
                while (current != NULL) {
                    OffsetNode* temp = current;
                    current = current->next;
                    free(temp);
                }
            }
            free(*records);
            stats.totalAllocated -= numRecords * sizeof(Record);
            stats.numRecords = 0;
            pthread_mutex_unlock(&mutex);
            return ALLOCATION_ERROR;
        }
        *keyRef = rand() % intValueRange + 1;
        (*records)[i].secondaryKeyRef = keyRef;

        log_memory_operation("Allocation", sizeof(OffsetNode) * offsetsPerRecord + sizeof(int));
    }

    pthread_mutex_unlock(&mutex);
    return 0;
}

// Function to safely update records
void update_records(Record* records, int numRecords, int newIntValueRange, double newWeightRange, double newMetadataRange) {
    if (numRecords <= 0 || newIntValueRange <= 0 || newWeightRange <= 0 || newMetadataRange <= 0) {
        return;
    }

    pthread_mutex_lock(&mutex);

    for (int i = 0; i < numRecords; ++i) {
        records[i].value = rand() % newIntValueRange + 1;
