#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

// Define structure sizes based on your specific data requirements
#define POOL_SIZE 1024

typedef struct {
    int CRCFLAG;
    // Add other fields if needed
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Memory pool for nodes
Node node_pool[POOL_SIZE];
int pool_index = 0;
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

// Thread-safe linked list structure
typedef struct {
    Node* head;
    pthread_mutex_t list_mutex;
} LinkedList;

LinkedList* create_linked_list() {
    LinkedList* ll = malloc(sizeof(LinkedList));
    ll->head = NULL;
    pthread_mutex_init(&ll->list_mutex, NULL);
    return ll;
}

void destroy_linked_list(LinkedList* ll) {
    Node* current = ll->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current); // Assuming you want to free individual nodes
        current = next;
    }
    pthread_mutex_destroy(&ll->list_mutex);
    free(ll);
}

Node* allocate_node() {
    pthread_mutex_lock(&pool_mutex);
    if (pool_index < POOL_SIZE) {
        Node* node = &node_pool[pool_index++];
        pthread_mutex_unlock(&pool_mutex);
        return node;
    } else {
        // Pool exhausted, fallback to malloc
        pthread_mutex_unlock(&pool_mutex);
        return malloc(sizeof(Node));
    }
}

void deallocate_node(Node* node) {
    pthread_mutex_lock(&pool_mutex);
    if (pool_index > 0) {
        node_pool[--pool_index] = *node;
    } else {
        free(node);
    }
    pthread_mutex_unlock(&pool_mutex);
}

void insert_to_list(LinkedList* ll, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = allocate_node();
    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&ll->list_mutex);
    if (ll->head == NULL) {
        ll->head = new_node;
    } else {
        Node* current = ll->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&ll->list_mutex);
}

void persist_state(LinkedList* ll, int retry_attempts, const char* db_path) {
    // Simulate database connectivity and persistence
    for (int attempt = 0; attempt < retry_attempts; ++attempt) {
        if (/* Database connection successful */) {
            pthread_mutex_lock(&ll->list_mutex);
            Node* current = ll->head;
            while (current != NULL) {
                // Persist current node data to the database at db_path
                current = current->next;
            }
            pthread_mutex_unlock(&ll->list_mutex);
            break;
        } else {
            sleep(1);  // Wait before retrying
        }
    }
}

void export_state_to_file(LinkedList* ll, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (file == NULL) return;

    pthread_mutex_lock(&ll->list_mutex);
    Node* current = ll->head;
    while (current != NULL) {
        fprintf(file, "RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
                current->data.RX_UE_INFORMATION_TAG,
                current->data.RNTI,
                current->data.crc_tag.CRCFLAG);
        current = current->next;
    }
    pthread_mutex_unlock(&ll->list_mutex);

    fclose(file);
}

void initialize_data(NFAPI_CRC_INDICATION_PDU_T* pdu, int tag, int rnti) {
    pdu->RX_UE_INFORMATION_TAG = tag;
    pdu->RNTI = rnti;
    pdu->crc_tag.CRCFLAG = rand() % 2; // Randomize CRCFLAG
}

int main() {
    srand(time(NULL));  // Seed random number generator

    LinkedList* ll = create_linked_list();

    for (int i = 0; i < 100; ++i) {  // Example insertion loop
        NFAPI_CRC_INDICATION_PDU_T pdu;
        initialize_data(&pdu, i + 1, i * 10);
        insert_to_list(ll, pdu);
    }

    persist_state(ll, 3, "database_path");
    export_state_to_file(ll, "exported_state.txt");

    destroy_linked_list(ll);

    return 0;
}
