// Define the SENSOR_EVENT_ID, timestamp, sensor type, and data point types.
typedef enum {
    SENSOR_TYPE_A,
    SENSOR_TYPE_B,
    // Add more sensor types as needed.
} SensorType;

typedef struct {
    int id;          // Example ID
    uint64_t timestamp;
    SensorType sensor_type;
    void *data_points;
    size_t data_length;
} SensorEvent;

// Define the dynamic list structure and its node.
typedef struct SensorEventNode {
    SensorEvent event;
    struct SensorEventNode *next;
} SensorEventNode;

typedef struct {
    SensorEventNode *head;
    pthread_mutex_t lock;
} SensorEventList;

// Function prototypes
SensorEventList* create_sensor_event_list();
int add_sensor_event(SensorEventList *list, const SensorEvent *event);
void free_sensor_event_list(SensorEventList *list);

// Create a new sensor event list with initialized mutex.
SensorEventList* create_sensor_event_list() {
    SensorEventList *list = (SensorEventList*)malloc(sizeof(SensorEventList));
    if (!list) return NULL;

    list->head = NULL;
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        free(list);
        return NULL;
    }

    return list;
}

// Add a new sensor event to the list.
int add_sensor_event(SensorEventList *list, const SensorEvent *event) {
    if (!list || !event) return -1;

    SensorEventNode *new_node = (SensorEventNode*)malloc(sizeof(SensorEventNode));
    if (!new_node) return -2;

    // Dynamically allocate memory for data points and copy the event's data.
    new_node->event.data_points = malloc(event->data_length);
    if (!new_node->event.data_points) {
        free(new_node);
        return -3;
    }
    memcpy(new_node->event.data_points, event->data_points, event->data_length);

    // Copy other fields from the input event.
    new_node->event.id = event->id;
    new_node->event.timestamp = event->timestamp;
    new_node->event.sensor_type = event->sensor_type;
    new_node->event.data_length = event->data_length;

    pthread_mutex_lock(&list->lock);

    // Add the new node to the head of the list.
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);

    return 0;  // Success
}

// Free all memory associated with the sensor event list.
void free_sensor_event_list(SensorEventList *list) {
    if (!list) return;

    SensorEventNode *current = list->head;
    while (current) {
        SensorEventNode *next_node = current->next;
        free(current->event.data_points);
        free(current);
        current = next_node;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}
