['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PRODUCTS 100000
#define PRICE_MIN 0.01
#define PRICE_MAX 9999.99

typedef struct {
    int product_id;
    char *product_name;
    double price;
    int stock_quantity;
} Product;

typedef struct {
    Product *products;
    size_t count;
    pthread_mutex_t lock;
} Inventory;

// Function to allocate and initialize inventory
Inventory* create_inventory(size_t initial_capacity) {
    Inventory *inventory = (Inventory*)malloc(sizeof(Inventory));
    if (!inventory) return NULL;

    inventory->products = (Product*)calloc(initial_capacity, sizeof(Product));
    if (!inventory->products) {
        free(inventory->products);
        free(inventory);
        return NULL;
    }

    inventory->count = 0;
    pthread_mutex_init(&inventory->lock, NULL);
    return inventory;
}

// Function to add a product
int add_product(Inventory *inventory, int product_id, const char *product_name, double price, int stock_quantity) {
    if (pthread_mutex_lock(&inventory->lock)) return -1;

    // Validate inputs
    if (price < PRICE_MIN || price > PRICE_MAX) {
        price = fmax(PRICE_MIN, fmin(price, PRICE_MAX));  // Correct price within bounds
        printf("Warning: Product ID %d has out-of-range price. Adjusted to %.2f\n", product_id, price);
    }

    if (stock_quantity < 0) {
        stock_quantity = 0;  // Correct negative stock quantity
        printf("Warning: Product ID %d had negative stock quantity. Adjusted to 0\n", product_id);
    }

    // Ensure capacity and allocate memory if needed
    if (inventory->count >= inventory->products) {
        size_t new_capacity = (size_t)(1.5 * inventory->count + 10);  // Increase capacity by 50% plus a constant factor
        Product *new_products = (Product*)realloc(inventory->products, new_capacity * sizeof(Product));
        if (!new_products) {
            pthread_mutex_unlock(&inventory->lock);
            return -1;
        }

        inventory->products = new_products;
    }

    // Add the product
    int index = inventory->count++;
    inventory->products[index].product_id = product_id;
    inventory->products[index].price = price;
    inventory->products[index].stock_quantity = stock_quantity;

    size_t name_len = strlen(product_name) + 1;  // +1 for null-terminator
    inventory->products[index].product_name = (char*)malloc(name_len);
    if (!inventory->products[index].product_name) {
        pthread_mutex_unlock(&inventory->lock);
        return -1;
    }

    strcpy(inventory->products[index].product_name, product_name);

    pthread_mutex_unlock(&inventory->lock);
    return 0;
}

// Function to update a product
int update_product(Inventory *inventory, int product_id, const char *new_name, double new_price, int new_stock_quantity) {
    if (pthread_mutex_lock(&inventory->lock)) return -1;

    for (size_t i = 0; i < inventory->count; ++i) {
        if (inventory->products[i].product_id == product_id) {
            // Validate and correct data
            if (new_price < PRICE_MIN || new_price > PRICE_MAX) {
                new_price = fmax(PRICE_MIN, fmin(new_price, PRICE_MAX));
                printf("Warning: Update Product ID %d has out-of-range price. Adjusted to %.2f\n", product_id, new_price);
            }

            if (new_stock_quantity < 0) {
                new_stock_quantity = 0;
                printf("Warning: Update Product ID %d had negative stock quantity. Adjusted to 0\n", product_id);
            }

            // Update the product
            size_t name_len = strlen(new_name) + 1;  // +1 for null-terminator
            free(inventory->products[i].product_name);
            inventory->products[i].product_name = (char*)malloc(name_len);
            if (!inventory->products[i].product_name) {
                pthread_mutex_unlock(&inventory->lock);
                return -1;
            }

            strcpy(inventory->products[i].product_name, new_name);
            inventory->products[i].price = new_price;
            inventory->products[i].stock_quantity = new_stock_quantity;

            pthread_mutex_unlock(&inventory->lock);
            return 0;
        }
    }

    printf("Warning: Product ID %d not found for update.\n", product_id);
    pthread_mutex_unlock(&inventory->lock);
    return -1;
}

// Function to free inventory
void free_inventory(Inventory *inventory) {
    if (pthread_mutex_lock(&inventory->lock)) return;

    for (size_t i = 0; i < inventory->count; ++i) {
        free(inventory->products[i].product_name);
    }

    free(inventory->products);
    pthread_mutex_unlock(&inventory->lock);
    pthread_mutex_destroy(&inventory->lock);
    free(inventory);
}

// Example usage
int main() {
    Inventory *inventory = create_inventory(10);

    add_product(inventory, 1, "Laptop", 999.99, 50);
    update_product(inventory, 1, "High-End Laptop", 1099.99, 45);

    // Add more products and handle updates...

    free_inventory(inventory);
    return 0;
}
