        for (int i = 0; i < frameCount && i < MAX_FRAMES; i++) {
            frames[i].samples = malloc(256 * sizeof(short));
            if (!frames[i].samples) handleError("Memory allocation failed for samples");

            for (int j = 0; j < 256; j++) {
                frames[i].samples[j] = rand() % (SAMPLE_RANGE_MAX - SAMPLE_RANGE_MIN + 1) + SAMPLE_RANGE_MIN;
            }

            scanf("%f", &frames[i].timestamp);
        }

