            pthread_mutex_unlock(&lock);
            current = current->next;
        }

        free(timestamps);

        for (int i = 0; i < frameCount && i < MAX_FRAMES; i++) {
            free(frames[i].samples);
        }

        // Simulate processing and storing to WAV
        char command[256];
        snprintf(command, sizeof(command), "third_party_tool %s output.wav", arg);
        system(command);

        if (head) {
            current = head;
            while (current) {
                NFAPI_CRC_INDICATION_PDU_T *temp = current;
                pthread_mutex_lock(&lock);
                current = current->next;
                pthread_mutex_unlock(&lock);
                free(temp);
            }
            head = NULL;
        }
