    size_t N = rand() % (MAX_NFAPI_SIZE + 1);
    *num_elements = N;

    if (*num_elements == 0) {
        fprintf(stderr, "No elements to populate.\n");
        return -2;
    }

    *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return -3;
