    for (size_t i = 0; i < N; ++i) {
        (*array)[i].RX_UE_INFORMATION_TAG = rand() % 256;
        (*array)[i].RNTI = rand() % 1024;
        (*array)[i].CRC_INDICATION_REL8_TAG = rand() % 512;
        (*array)[i].CRCFLAG = rand() % 2; // Randomly set to 0 or 1
    }

