        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

unsigned long hash_function(const void *key, size_t key_size, size_t table_capacity) {
    const unsigned char *data = (const unsigned char *)key;
    unsigned long hash = 5381;
    for (size_t i = 0; i < key_size; ++i) {
        hash = ((hash << 5) + hash) + data[i];
    }
    return hash % table_capacity;
}

bool insert_into_hash_table(HashTable *table, const void *key, size_t key_size, void *value) {
    pthread_mutex_lock(&table->lock);
    unsigned long index = hash_function(key, key_size, table->capacity);
    HashTableEntry *entry = (HashTableEntry *)malloc(sizeof(HashTableEntry));
    entry->key = malloc(key_size);
    memcpy(entry->key, key, key_size);
    entry->value = value;
    entry->next = table->buckets[index];
    table->buckets[index] = entry;
    table->size++;
    pthread_mutex_unlock(&table->lock);

    if ((float)table->size / table->capacity > 0.7) {
        resize_hash_table(table);
    }
    return true;
}

void* lookup_in_hash_table(HashTable *table, const void *key, size_t key_size) {
    unsigned long index = hash_function(key, key_size, table->capacity);
    HashTableEntry *entry = table->buckets[index];
    while (entry) {
        if (memcmp(entry->key, key, key_size) == 0) {
            return entry->value;
        }
        entry = entry->next;
    }
    return NULL;
}

void resize_hash_table(HashTable *table) {
    size_t new_capacity = table->capacity * 2;
    HashTableEntry **new_buckets = (HashTableEntry **)calloc(new_capacity, sizeof(HashTableEntry *));

    for (size_t i = 0; i < table->capacity; ++i) {
        HashTableEntry *entry = table->buckets[i];
        while (entry) {
            HashTableEntry *next_entry = entry->next;
            unsigned long new_index = hash_function(entry->key, strlen((char *)entry->key), new_capacity);
            entry->next = new_buckets[new_index];
            new_buckets[new_index] = entry;
            entry = next_entry;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->capacity = new_capacity;
}

void dns_resolution(const char *hostname, struct in_addr **ip_addresses, size_t *count) {
    struct hostent *host_info = gethostbyname(hostname);
    if (!host_info) {
        printf("DNS resolution failed for %s\n", hostname);
        return;
    }

    int num_ips = host_info->h_length;
    *ip_addresses = (struct in_addr *)malloc(num_ips * sizeof(struct in_addr));
    memcpy(*ip_addresses, host_info->h_addr_list[0], num_ips * sizeof(struct in_addr));
    *count = num_ips;
}

void* function_thread(void *arg) {
    // Example of thread-safe operations
    HashTable *table = (HashTable *)arg;

    const char *hostname = "example.com";
    struct in_addr *ip_addresses;
    size_t count;

    dns_resolution(hostname, &ip_addresses, &count);

    if (count > 0) {
        for (size_t i = 0; i < count; ++i) {
            char ip_str[INET_ADDRSTRLEN];
            inet_ntop(AF_INET, &ip_addresses[i], ip_str, INET_ADDRSTRLEN);
            printf("Resolved IP: %s\n", ip_str);
        }
    }

    free(ip_addresses);

    // Example logging
    static int operation_count = 0;
    pthread_mutex_lock(&table->lock);
    operation_count++;
    if (operation_count % 10 == 0) {
        printf("Operation count: %d\n", operation_count);
    }
    pthread_mutex_unlock(&table->lock);

    return NULL;
}

void initialize_function() {
    size_t array_size = 5;

    double *double_array = allocate_double_array(array_size);
    char **char_array = allocate_char_array(array_size);
    Element **element_array = allocate_element_array(array_size);
    Metadata **metadata_array = allocate_metadata_array(array_size);
    Log **log_array = allocate_log_array(array_size);

    HashTable *hash_table = create_hash_table(16);

    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        pthread_create(&threads[i], NULL, function_thread, (void *)hash_table);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_hash_table(hash_table);
    free(double_array);
    for (size_t i = 0; i < array_size; ++i) {
        free(char_array[i]);
    }
    free(char_array);
    for (size_t i = 0; i < array_size; ++i) {
        free(element_array[i]);
    }
    free(element_array);
    for (size_t i = 0; i < array_size; ++i) {
        free(metadata_array[i]);
    }
    free(metadata_array);
    for (size_t i = 0; i < array_size; ++i) {
        free(log_array[i]);
    }
    free(log_array);
}

int main() {
    initialize_function();
    return 0;
}
```

This code implements the specified requirements, including dynamic memory allocation for arrays, a hash table with resizing and LRU eviction policy, DNS resolution, logging, and thread safety. The function is designed to integrate into an existing application while handling concurrency and potential errors gracefully.']

