// Mutex for thread safety
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Logger function to log messages
void log_message(const char* message) {
    printf("%s\n", message);
}

// Function to generate random strings
char* random_string() {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    char *str = malloc(MAX_STRING_SIZE);
    if (!str) return NULL;

    for (int i = 0; i < MAX_STRING_SIZE - 1; ++i) {
        int key = rand() % (sizeof(charset) - 1);
        str[i] = charset[key];
    }
    str[MAX_STRING_SIZE - 1] = '\0';
    return str;
}

// Function to initialize and allocate memory for records
int create_records(record **records, size_t num_records) {
    if (!records || num_records == 0) {
        log_message("Invalid input parameters.");
        return -1;
    }

    pthread_mutex_lock(&lock);

    *records = malloc(num_records * sizeof(record));
    if (*records == NULL) {
        log_message("Memory allocation for records failed.");
        pthread_mutex_unlock(&lock);
        return -2;
    }

    srand((unsigned int)time(NULL)); // Seed random number generator

    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].key = rand() % 10000; // Example range for key
        (*records)[i].value = ((float)rand() / RAND_MAX) * 100.0f; // Random float between 0 and 100
        (*records)[i].string = random_string();

        if ((*records)[i].string == NULL) {
            log_message("Memory allocation for string failed.");
            free_records(*records, i);
            pthread_mutex_unlock(&lock);
            return -3;
        }
    }

    // Sorting records based on the key values
    qsort(*records, num_records, sizeof(record), [](const void *a, const void *b) {
        record *recA = (record *)a;
        record *recB = (record *)b;
        return recA->key - recB->key;
    });

    pthread_mutex_unlock(&lock);
    log_message("Records initialized and sorted successfully.");
    return 0;
}

// Function to free allocated memory for records
void free_records(record *records, size_t num_records) {
    if (!records) return;

    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < num_records; ++i) {
        free(records[i].string);
    }

    free(records);
    log_message("All records have been freed.");

    pthread_mutex_unlock(&lock);
}

int main() {
    record *records;
    size_t num_records = 10;

    int result = create_records(&records, num_records);

    if (result == 0) {
        // Use the records
    } else {
        log_message("Failed to initialize records.");
    }

    free_records(records, num_records);

    return 0;
}
