// Define the struct for environmental sensor data
typedef struct {
    double temperature; // in Celsius
    int humidity;       // as a percentage
    double pressure;    // in hPa
} SensorData;

// Function prototypes
void initialize_sensor_data(SensorData **sensor_data, size_t count, int humidity_threshold);
void simulate_sensor_reading(SensorData *data);
int compare_temperature(const void *a, const void *b);
void filter_sensors(SensorData **sensor_data, size_t *count, int humidity_threshold);
void free_resources(SensorData **sensor_data, char ***identifiers, double *values);

// Global mutex for thread safety
pthread_mutex_t lock;

void initialize_sensor_data(SensorData **sensor_data, size_t count, int humidity_threshold) {
    pthread_mutex_init(&lock, NULL);

    // Allocate memory for sensor data array
    *sensor_data = (SensorData *)malloc(count * sizeof(SensorData));
    if (*sensor_data == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    // Initialize sensor readings
    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_lock(&lock);
        simulate_sensor_reading(&(*sensor_data)[i]);
        pthread_mutex_unlock(&lock);

        if ((*sensor_data)[i].humidity > humidity_threshold) {
            free_resources(sensor_data, NULL, NULL); // Free only sensor data
            printf("Sensor reading with high humidity filtered out.\n");
            return;
        }
    }

    // Sort the sensor data based on temperature values in ascending order
    qsort(*sensor_data, count, sizeof(SensorData), compare_temperature);

    // Simulate identifiers and double precision floating-point values (if needed)
    char **identifiers = (char **)malloc(count * sizeof(char *));
    if (!identifiers) {
        free_resources(sensor_data, &identifiers, NULL);
        return;
    }

    for (size_t i = 0; i < count; ++i) {
        identifiers[i] = (char *)malloc(20 * sizeof(char)); // Assume max length of identifier is 19 characters + null terminator
        if (!identifiers[i]) {
            free_resources(sensor_data, &identifiers, NULL);
            return;
        }
        snprintf(identifiers[i], 20, "Sensor_%zu", i);
    }

    double *values = (double *)malloc(count * sizeof(double));
    if (!values) {
        free_resources(sensor_data, &identifiers, NULL);
        return;
    }

    for (size_t i = 0; i < count; ++i) {
        values[i] = rand() % 100 / 10.0; // Random double value between 0 and 9.9
    }

    printf("Initialization successful.\n");

    // Release resources on completion
    free_resources(sensor_data, &identifiers, &values);
}

void simulate_sensor_reading(SensorData *data) {
    data->temperature = (rand() % 500 - 50) / 10.0; // Random temperature between -5.0 and 49.9
    data->humidity = rand() % 101;                  // Random humidity between 0 and 100
    data->pressure = (rand() % 1500 + 850);         // Random pressure between 850 and 2349 hPa
}

int compare_temperature(const void *a, const void *b) {
    SensorData *sensorA = (SensorData *)a;
    SensorData *sensorB = (SensorData *)b;
    return (sensorA->temperature > sensorB->temperature) - (sensorA->temperature < sensorB->temperature);
}

void filter_sensors(SensorData **sensor_data, size_t *count, int humidity_threshold) {
    if (*count == 0) return;

    SensorData *filtered = NULL;
    size_t new_count = 0;

    for (size_t i = 0; i < *count; ++i) {
        if ((*sensor_data)[i].humidity <= humidity_threshold) {
            filtered = realloc(filtered, (new_count + 1) * sizeof(SensorData));
            if (!filtered) break;
            filtered[new_count++] = (*sensor_data)[i];
        }
    }

    free(*sensor_data);
    *sensor_data = filtered;
    *count = new_count;
}

void free_resources(SensorData **sensor_data, char ***identifiers, double *values) {
    if (sensor_data && *sensor_data) {
        free(*sensor_data);
        *sensor_data = NULL;
    }

    if (identifiers && *identifiers) {
        for (size_t i = 0; (*identifiers)[i]; ++i) {
            free((*identifiers)[i]);
        }
        free(*identifiers);
        *identifiers = NULL;
    }

    if (values) {
        free(values);
    }

    pthread_mutex_destroy(&lock);
}

int main() {
    size_t count = 100; // Example size
    int humidity_threshold = 70;

    SensorData *sensor_data;
    initialize_sensor_data(&sensor_data, count, humidity_threshold);

    return 0;
}
