size_t calculate_memory_usage() {
    size_t usage = sizeof(Node);
    Node* current = head;
    while (current != NULL) {
        usage += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        current = current->next;
    }
    return usage;
}

