        pthread_mutex_lock(&mutex);
        size_t usage = calculate_memory_usage();
        if (usage > MEMORY_THRESHOLD) {
            memory_management_callback();
        }
        log_performance_metrics(sizeof(Node));
        pthread_mutex_unlock(&mutex);

        sleep(LOG_INTERVAL);
    }
}

void add_to_list(NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&mutex);

    // Validate RNTI
    if (!is_valid_rnti(pdu.rnti)) {
        printf("Invalid RNTI: %d\n", pdu.rnti);
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Set CRCFLAG based on predefined criteria
    pdu.crc_flag = should_set_crc_flag(pdu.rx_ue_information_tag, pdu.rnti);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    new_node->data = pdu;
    new_node->prev = tail;

    if (tail) {
        tail->next = new_node;
        // Ensure no two consecutive structures have the same RNTI
        while (new_node->prev && new_node->prev->data.rnti == pdu.rnti) {
            free(new_node);
            printf("Duplicate RNTI detected. Aborting addition.\n");
            pthread_mutex_unlock(&mutex);
            return;
        }
    } else {
        head = new_node;
    }

    tail = new_node;

    pthread_mutex_unlock(&mutex);
}

void cleanup_list() {
    Node* current = head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    head = tail = NULL;
}

int main() {
