    pthread_t monitor_thread;
    pthread_create(&monitor_thread, NULL, monitor_memory_usage, NULL);

    // Example of adding elements to the list
    for (int i = 0; i < 10000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = { .rx_ue_information_tag = rand(), .rnti = rand() % MAX_RNTI + 1 };
        add_to_list(pdu);
    }

    // Cleanup
    cleanup_list();
    pthread_cancel(monitor_thread);
    pthread_join(monitor_thread, NULL);

    return 0;
}
