        inputQueue.rear = (inputQueue.rear + 1) % QUEUE_SIZE;
        atomic_fetch_add(&_Atomic int, &inputQueue.size, 1);
    }
    pthread_mutex_unlock(&queueLock);
}

audioFrame dequeueFrame() {
