    pthread_mutex_lock(&queueLock);
    if (atomic_load(&_Atomic int, &inputQueue.size) > 0) {
        frame = inputQueue.frames[inputQueue.front];
        inputQueue.front = (inputQueue.front + 1) % QUEUE_SIZE;
        atomic_fetch_sub(&_Atomic int, &inputQueue.size, 1);
    }
    pthread_mutex_unlock(&queueLock);
    return frame;
}

