        audioFrame frame = dequeueFrame();
        free(frame.samples);
    }

    pthread_mutex_destroy(&queueLock);

    NFAPI_CRC_INDICATION_PDU_T *current = crcList.head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }

    pthread_rwlock_destroy(&crcList.rwlock);
}

void addCRCIndication(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_rwlock_wrlock(&crcList.rwlock);
    pdu->next = crcList.head;
    crcList.head = pdu;
    pthread_rwlock_unlock(&crcList.rwlock);
}

