// Initialize the BST with a mutex
BST* initializeBST() {
    BST *bst = (BST *)malloc(sizeof(BST));
    if (!bst) return NULL;

    bst->root = NULL;
    pthread_mutex_init(&bst->lock, NULL);
    return bst;
}

// Create a new node for the BST
Node* createNode(Entry *entry) {
    Node *node = (Node *)malloc(sizeof(Node));
    if (!node) return NULL;
    node->entry = entry;
    node->left = node->right = NULL;
    return node;
}

// Insert an entry into the BST
Node* insert(Node *node, Entry *entry) {
    if (!node) return createNode(entry);

    if (entry->temperature < node->entry->temperature)
        node->left = insert(node->left, entry);
    else if (entry->temperature > node->entry->temperature)
        node->right = insert(node->right, entry);

    return node;
}

