    if (!node || node->entry->temperature == temperature)
        return node;

    if (temperature < node->entry->temperature)
        return search(node->left, temperature);
    else
        return search(node->right, temperature);
}

// Free the entire BST
void freeTree(Node *node) {
    if (!node) return;
    freeTree(node->left);
    freeTree(node->right);
    free(node->entry->identifier);  // Assuming identifier was dynamically allocated
    free(node->entry);
    free(node);
}

