    char *statuses = (char *)malloc(size);
    Entry **entries = (Entry **)malloc(size * sizeof(Entry *));

    if (!temperatures || !statuses || !entries) {
        logMessage("Memory allocation failed.");
        return EXIT_FAILURE;
    }

    BST *bst = initializeBST();
    if (!bst) {
        free(temperatures);
        free(statuses);
        free(entries);
        logMessage("Failed to initialize BST.");
        return EXIT_FAILURE;
    }

    // Populate and insert entries into the BST
    for (int i = 0; i < size; ++i) {
        Entry *entry = (Entry *)malloc(sizeof(Entry));
        if (!entry) continue;

        entry->temperature = temperatures[i];
        entry->status = statuses[i];
        entry->identifier = strdup("Location");  // Example identifier

        entries[i] = entry;

        pthread_mutex_lock(&bst->lock);
        bst->root = insert(bst->root, entry);
        pthread_mutex_unlock(&bst->lock);
    }

    logMessage("Entries inserted into BST.");

    // Free allocated resources
    for (int i = 0; i < size; ++i) {
        if (entries[i]) free(entries[i]->identifier);
        free(entries[i]);
    }

    free(temperatures);
    free(statuses);
    free(entries);
    pthread_mutex_destroy(&bst->lock);
    freeTree(bst->root);
    free(bst);

    logMessage("Resources freed and program completed.");
    return EXIT_SUCCESS;
}
