typedef struct TransactionNode {
    Transaction* transaction;
    struct TransactionNode* next;
} TransactionNode;

typedef struct {
    TransactionNode** table;
    size_t size;
    pthread_mutex_t lock;
} ConcurrentHashMap;

ConcurrentHashMap* createConcurrentMap(size_t size) {
    ConcurrentHashMap* map = malloc(sizeof(ConcurrentHashMap));
    map->table = calloc(size, sizeof(TransactionNode*));
    map->size = size;
    pthread_mutex_init(&map->lock, NULL);
    return map;
}

unsigned int hash(const char *str, size_t size) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c;
    return hash % size;
}

void insertTransaction(ConcurrentHashMap* map, Transaction* transaction) {
    pthread_mutex_lock(&map->lock);
    unsigned int index = hash(transaction->id, map->size);

    TransactionNode* newNode = malloc(sizeof(TransactionNode));
    newNode->transaction = transaction;
    newNode->next = map->table[index];
    map->table[index] = newNode;

    pthread_mutex_unlock(&map->lock);
}

Transaction* findTransaction(ConcurrentHashMap* map, const char *id) {
    unsigned int index = hash(id, map->size);

    pthread_mutex_lock(&map->lock);
    TransactionNode* node = map->table[index];
    while (node != NULL) {
        if (strcmp(node->transaction->id, id) == 0) {
            pthread_mutex_unlock(&map->lock);
            return node->transaction;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&map->lock);

    return NULL;
}

void freeConcurrentMap(ConcurrentHashMap* map) {
    for (size_t i = 0; i < map->size; ++i) {
        TransactionNode* node = map->table[i];
        while (node != NULL) {
            TransactionNode* temp = node;
            node = node->next;
            free(temp->transaction);
            free(temp);
        }
    }
    free(map->table);
    pthread_mutex_destroy(&map->lock);
    free(map);
}

bool isValidTransaction(double amount) {
    return amount > 0 && amount <= 1e6; // Example: realistic range
}

void logError(const char* message) {
    fprintf(stderr, "%s\n", message);
}

int processFinancialTransactions(Transaction** transactions, size_t count) {
    ConcurrentHashMap* transactionMap = createConcurrentMap(1024);

    if (!transactionMap) return -1;

    pthread_t threads[count];
    int status = 0;

    for (size_t i = 0; i < count; ++i) {
        pthread_create(&threads[i], NULL, [](void* arg) -> void* {
            Transaction* transaction = (Transaction*)arg;

            if (!isValidTransaction(transaction->amount)) {
                logError("Invalid transaction amount");
                return NULL;
            }

            // Simulate analytics
            static double totalAmount = 0.0;
            static int transactionCount = 0;
            pthread_mutex_lock(&map);
            totalAmount += transaction->amount;
            ++transactionCount;
            pthread_mutex_unlock(&map);

            insertTransaction(transactionMap, transaction);

            return NULL;
        }, transactions[i]);
    }

    for (size_t i = 0; i < count; ++i) {
        pthread_join(threads[i], NULL);
    }

    freeConcurrentMap(transactionMap);
    return status;
}

int main() {
    // Example usage
    Transaction* transactions[10];
    for (size_t i = 0; i < 10; ++i) {
        transactions[i] = malloc(sizeof(Transaction));
        snprintf(transactions[i]->id, 32, "tx%d", i);
        transactions[i]->amount = (double)(100 * (i + 1));
        strcpy(transactions[i]->currency, "USD");
        transactions[i]->timestamp = time(NULL);
    }

    int result = processFinancialTransactions(transactions, 10);

    if (result != 0) {
        logError("Failed to process transactions");
    } else {
        printf("Successfully processed transactions\n");
    }

    for (size_t i = 0; i < 10; ++i) {
        free(transactions[i]);
    }

    return result;
}
``` 

