    long* offsets = new (std::nothrow) long[numElements];
    int* keys = new (std::nothrow) int[numElements];
    Record* records = new (std::nothrow) Record[numElements];

    if (!offsets || !keys || !records) {
        logger.log("Memory allocation failed.");
        return;
    }

    std::vector<std::pair<int, Record>> recordPairs;

    // Populate arrays with random values
    for (size_t i = 0; i < numElements; ++i) {
        offsets[i] = rand() % 10000; // Random long offset
        keys[i] = rand() % 500;      // Random int key
        records[i].value = rand() % 1000; // Random record value

        recordPairs.emplace_back(keys[i], records[i]);
    }

    // Sort based on keys
