    logger.log("Selected attack strategy: " + std::to_string(selectedAttack));

    // BST operations
    BSTree tree;
    for (int i = 0; i < numElements; ++i) {
        tree.insert(keys[i]);
    }
}

int main() {
    processAndConvertImageToDocument("example.jpeg", "output.pdf");
    return 0;
}
