// Function to initialize the linked list
NFAPI_CRC_INDICATION_PDU_T* createLinkedList(int count, unsigned short rnti_min, unsigned short rnti_max) {
    if (!count || rnti_min >= rnti_max) return NULL;

    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T *head = NULL, *tail = NULL;

    for (int i = 0; i < count; ++i) {
        unsigned short currentRNTI;
        do {
            currentRNTI = getRandomRNTI(rnti_min, rnti_max);
        } while (tail && tail->rnti == currentRNTI);

        NFAPI_CRC_INDICATION_PDU_T *newNode = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newNode) {
            // Cleanup on failure
            while (head) {
                NFAPI_CRC_INDICATION_PDU_T *temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
        }

        newNode->ue_info_tag = (RX_UE_INFORMATION_TAG){};
        newNode->rnti = currentRNTI;
        newNode->crc_rel8_tag.CRCFLAG = rand() % 2; // Random CRCFLAG
        newNode->next = NULL;

        if (!head) {
            head = tail = newNode;
        } else {
            tail->next = newNode;
            tail = newNode;
        }
    }

    return head;
}

// Function to free the linked list
void freeLinkedList(NFAPI_CRC_INDICATION_PDU_T *head) {
    while (head) {
        NFAPI_CRC_INDICATION_PDU_T *temp = head;
        head = head->next;
        free(temp);
    }
