#define MAX_MEMORY_USAGE 1048576 // 1MB for example
#define LOG_BUFFER_SIZE 1024

// Global mutex for thread safety and memory pool management
pthread_mutex_t global_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to generate a random number within a given range
int rand_range(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Logging function
void log_record_creation(int rnti, unsigned char crcflag) {
    static char log_buffer[LOG_BUFFER_SIZE];
    snprintf(log_buffer, LOG_BUFFER_SIZE, "RNTI: %d, CRCFLAG: %u\n", rnti, crcflag);
    printf("%s", log_buffer); // Assuming a simple print for logging
}

// Function to initialize and manage memory allocation for records
NFAPI_CRC_INDICATION_PDU_T* create_records(int num_records, int long_offset_min, int long_offset_max,
                                           int key_min, int key_max, const char *external_data_source) {
    if (num_records <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *records = NULL;
    size_t record_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t total_memory_required = num_records * record_size;

    pthread_mutex_lock(&global_mutex);

    // Check memory limits
    if (total_memory_required > MAX_MEMORY_USAGE) {
        printf("Insufficient memory available.\n");
        pthread_mutex_unlock(&global_mutex);
