    EventRecord record;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t count;
} EventList;

EventList* createEventList() {
    EventList* list = (EventList*)malloc(sizeof(EventList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->count = 0;
    return list;
}

int addEvent(EventList* list, const char* eventID, int priority, time_t timestamp,
             const char* sourceIdentifier, const void* details, size_t detailSize) {
    if (list->count >= MAX_EVENTS) return -1; // Buffer overflow protection

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return -1;

    strncpy(newNode->record.eventID, eventID, sizeof(newNode->record.eventID));
    newNode->record.priority = priority;
    newNode->record.timestamp = timestamp;
    strncpy(newNode->record.sourceIdentifier, sourceIdentifier, sizeof(newNode->record.sourceIdentifier));
    newNode->record.details = malloc(detailSize);
    if (!newNode->record.details) {
        free(newNode);
        return -1;
    }
    memcpy(newNode->record.details, details, detailSize);
    newNode->record.detailSize = detailSize;

    newNode->next = NULL;
    if (list->tail) list->tail->next = newNode;
    else list->head = newNode;
    list->tail = newNode;
    list->count++;

    return 0; // Success
}

void freeEventList(EventList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current->record.details);
        free(current);
        current = next;
    }
    free(list);
}

// Asynchronous housekeeping task
void* housekeepingTask(void* arg) {
    EventList* list = (EventList*)arg;
    time_t now = time(NULL);
    Node** prev = &list->head;
    Node* current = list->head;

    while (current) {
        if (difftime(now, current->record.timestamp) > 30 * 24 * 60 * 60) { // Older than 30 days
            Node* toDelete = current;
            *prev = current->next;
            free(toDelete->record.details);
            free(toDelete);
            list->count--;
        } else {
            prev = &current->next;
        }
        current = *prev;
    }

    return NULL; // Placeholder for pthread_exit if using threads
}

