#define MAX_CONFIGS 100

typedef struct {
    int key;
    long offset;
    int record;
} CustomStruct;

typedef struct {
    CustomStruct *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* init_dynamic_array(size_t initial_capacity) {
    DynamicArray *da = malloc(sizeof(DynamicArray));
    da->array = malloc(initial_capacity * sizeof(CustomStruct));
    da->size = 0;
    da->capacity = initial_capacity;
    pthread_mutex_init(&da->lock, NULL);
    return da;
}

void free_dynamic_array(DynamicArray *da) {
    free(da->array);
    pthread_mutex_destroy(&da->lock);
    free(da);
}

int add_record(DynamicArray *da, int key, long offset, int min_val, int max_val) {
    pthread_mutex_lock(&da->lock);

    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity * 2;
        CustomStruct *new_array = realloc(da->array, new_capacity * sizeof(CustomStruct));
        if (!new_array) {
            pthread_mutex_unlock(&da->lock);
            return -1; // Reallocation failed
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }

    CustomStruct cs = {key, offset, (rand() % (max_val - min_val + 1)) + min_val};
    da->array[da->size++] = cs;

    pthread_mutex_unlock(&da->lock);
    return 0;
}

int update_record(DynamicArray *da, int key, long new_offset) {
    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i].key == key) {
            da->array[i].offset = new_offset;
            pthread_mutex_unlock(&da->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&da->lock);
    return -1; // Key not found
}

int delete_record(DynamicArray *da, int key) {
    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i].key == key) {
            memmove(&da->array[i], &da->array[i + 1], (da->size - i - 1) * sizeof(CustomStruct));
            --da->size;
            pthread_mutex_unlock(&da->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&da->lock);
    return -1; // Key not found
}

void adjust_filename(const char *filename, int max_digits) {
    size_t len = strlen(filename);
    int num_digits = len > max_digits ? max_digits : (int)len;

    char new_ext[10];
    sprintf(new_ext, ".%0*d", num_digits, rand() % 100000);

    char *new_filename = malloc(len + strlen(new_ext) + 1);
    strcpy(new_filename, filename);
    strcat(new_filename, new_ext);

    printf("Adjusted Filename: %s\n", new_filename);
    free(new_filename);
}

int main() {
    srand(time(NULL));

    DynamicArray *da = init_dynamic_array(10);

    add_record(da, 1, 100, 0, 50);
    update_record(da, 1, 200);
    delete_record(da, 1);

    adjust_filename("example.txt", 3);

    free_dynamic_array(da);

    return 0;
}
