```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 16

typedef struct {
    char *resourceId;
    time_t startTime;
    time_t endTime;
    double totalConsumption; // Calculated as (endTime - startTime)
} ResourceUsage;

typedef struct TreeNode {
    ResourceUsage data;
    struct TreeNode *left, *right;
    int height;
} TreeNode;

typedef struct {
    TreeNode *root;
    pthread_mutex_t lock;
} RBSTree;

typedef struct {
    RBSTree *tree;
    char **hashMap;
    size_t capacity;
    pthread_rwlock_t rwlock;
} ResourceUsageManager;

// Function declarations
ResourceUsageManager* initResourceManager(size_t initialCapacity);
void cleanupManager(ResourceUsageManager *manager);
int insertResourceUsage(ResourceUsageManager *manager, ResourceUsage usage);
ResourceUsage* findResourceUsage(ResourceUsageManager *manager, const char *resourceId);
int deleteResourceUsage(ResourceUsageManager *manager, const char *resourceId);
void rebalanceTree(TreeNode **node);
double calculateHeight(TreeNode *node);
void logRebalanceOperation(const char *message);

// Helper functions
static TreeNode* newNode(ResourceUsage data) {
    TreeNode *node = (TreeNode*)malloc(sizeof(TreeNode));
    if (!node) return NULL;
    node->data = data;
    node->left = node->right = NULL;
    node->height = 1;
    return node;
}

static void freeTree(TreeNode *node) {
    if (node) {
        freeTree(node->left);
        freeTree(node->right);
        free(node->data.resourceId);
        free(node);
    }
}

ResourceUsageManager* initResourceManager(size_t initialCapacity) {
    ResourceUsageManager *manager = (ResourceUsageManager*)malloc(sizeof(ResourceUsageManager));
    if (!manager) return NULL;

    manager->tree = (RBSTree*)malloc(sizeof(RBSTree));
    if (!manager->tree) {
        free(manager);
        return NULL;
    }
    pthread_mutex_init(&manager->tree->lock, NULL);
    manager->tree->root = NULL;

    manager->hashMap = (char**)calloc(initialCapacity, sizeof(char*));
    if (!manager->hashMap) {
        free(manager->tree);
        free(manager);
        return NULL;
    }

    pthread_rwlock_init(&manager->rwlock, NULL);
    manager->capacity = initialCapacity;

    return manager;
}

void cleanupManager(ResourceUsageManager *manager) {
    if (manager) {
        pthread_mutex_lock(&manager->tree->lock);
        freeTree(manager->tree->root);
        pthread_mutex_unlock(&manager->tree->lock);

        for (size_t i = 0; i < manager->capacity; ++i) {
            free(manager->hashMap[i]);
        }
        free(manager->hashMap);
        free(manager->tree);
        pthread_rwlock_destroy(&manager->rwlock);
        free(manager);
    }
}

int insertResourceUsage(ResourceUsageManager *manager, ResourceUsage usage) {
    if (!manager || !usage.resourceId) return -1;

    pthread_mutex_lock(&manager->tree->lock);

    // Insert into BST
    TreeNode **node = &manager->tree->root;
    while (*node) {
        int cmp = strcmp(usage.resourceId, (*node)->data.resourceId);
        if (cmp < 0) node = &(*node)->left;
        else if (cmp > 0) node = &(*node)->right;
        else {
            pthread_mutex_unlock(&manager->tree->lock);
            return -1; // Duplicate
        }
    }

    TreeNode *newNodePtr = newNode(usage);
    if (!newNodePtr) {
        pthread_mutex_unlock(&manager->tree->lock);
        return -1;
    }

    *node = newNodePtr;

    // Rebalance tree
    rebalanceTree(&manager->tree->root);

    // Insert into hash map
    size_t index = hashFunction(usage.resourceId, manager->capacity);
    pthread_rwlock_wrlock(&manager->rwlock);
    if (!manager->hashMap[index]) {
        manager->hashMap[index] = strdup(usage.resourceId);
    } else {
        char *current = manager->hashMap[index];
        while (strcmp(current, usage.resourceId) != 0 && current[1] != '\0') {
            current += strlen(current) + 1;
        }
        if (!current[1]) {
            char *newEntry = strdup(usage.resourceId);
            newEntry[strlen(newEntry) + 1] = '\0';
            strcpy(newEntry + strlen(newEntry) + 1, manager->hashMap[index]);
            free(manager->hashMap[index]);
            manager->hashMap[index] = newEntry;
        }
    }
    pthread_rwlock_unlock(&manager->rwlock);

    logRebalanceOperation("Insert operation performed.");
    pthread_mutex_unlock(&manager->tree->lock);
    return 0;
}

ResourceUsage* findResourceUsage(ResourceUsageManager *manager, const char *resourceId) {
    if (!manager || !resourceId) return NULL;

    pthread_rwlock_rdlock(&manager->rwlock);

    size_t index = hashFunction(resourceId, manager->capacity);
    char *entry = manager->hashMap[index];
    while (entry && strcmp(entry, resourceId) != 0) {
        entry += strlen(entry) + 1;
    }

    if (!entry) {
        pthread_rwlock_unlock(&manager->rwlock);
        return NULL;
    }

    pthread_mutex_lock(&manager->tree->lock);

    TreeNode *node = manager->tree->root;
    while (node) {
        int cmp = strcmp(resourceId, node->data.resourceId);
        if (cmp < 0) node = node->left;
        else if (cmp > 0) node = node->right;
        else break;
    }

    pthread_mutex_unlock(&manager->tree->lock);
    pthread_rwlock_unlock(&manager->rwlock);

    return node ? &node->data : NULL;
}

int deleteResourceUsage(ResourceUsageManager *manager, const char *resourceId) {
    if (!manager || !resourceId) return -1;

    pthread_mutex_lock(&manager->tree->lock);

    TreeNode **node = &manager->tree->root;
    while (*node && strcmp(resourceId, (*node)->data.resourceId) != 0) {
        if (strcmp(resourceId, (*node)->data.resourceId) < 0)
            node = &(*node)->left;
        else
            node = &(*node)->right;
    }

    if (!*node) {
        pthread_mutex_unlock(&manager->tree->lock);
        return -1; // Not found
    }

    TreeNode *toDelete = *node;

    if (!toDelete->left || !toDelete->right) {
        *node = toDelete->left ? toDelete->left : toDelete->right;
    } else {
        TreeNode **successor = &toDelete->right;
        while ((*successor)->left) successor = &(*successor)->left;
        toDelete->data = (*successor)->data;
        *node = (*successor)->right;
        toDelete = *successor;
    }

    free(toDelete->data.resourceId);
    free(toDelete);

    rebalanceTree(&manager->tree->root);

    pthread_rwlock_wrlock(&manager->rwlock);
    size_t index = hashFunction(resourceId, manager->capacity);
    char *entry = manager->hashMap[index];
    if (entry && strcmp(entry, resourceId) == 0) {
        free(manager->hashMap[index]);
        manager->hashMap[index] = NULL;
    } else {
        while (entry && strcmp(entry, resourceId) != 0) {
            entry += strlen(entry) + 1;
        }
        if (entry) {
            char *current = manager->hashMap[index];
            if (strcmp(current, resourceId) == 0) {
                strcpy(current, current + strlen(entry) + 1);
            } else {
                while (strcmp(current, resourceId) != 0 && current[1] != '\0') {
                    current += strlen(current) + 1;
                }
                strcpy(current, current + strlen(entry) + 1);
            }
        }
    }
    pthread_rwlock_unlock(&manager->rwlock);

    logRebalanceOperation("Delete operation performed.");
    pthread_mutex_unlock(&manager->tree->lock);
    return 0;
}

void rebalanceTree(TreeNode **node) {
    // AVL Tree rebalancing logic
    if (!*node) return;

    int balance = calculateHeight((*node)->left) - calculateHeight((*node)->right);

    if (balance > 1) {
        if (calculateHeight((*node)->left->left) >= calculateHeight((*node)->left->right)) {
            *node = rotateRight(*node);
        } else {
            (*node)->left = rotateLeft((*node)->left);
            *node = rotateRight(*node);
        }
    } else if (balance < -1) {
        if (calculateHeight((*node)->right->right) >= calculateHeight((*node)->right->left)) {
            *node = rotateLeft(*node);
        } else {
            (*node)->right = rotateRight((*node)->right);
            *node = rotateLeft(*node);
        }
    }

    (*node)->height = 1 + (calculateHeight((*node)->left) > calculateHeight((*node)->right) ? 
                          calculateHeight((*node)->left) : calculateHeight((*node)->right));
}

double calculateHeight(TreeNode *node) {
    return node ? node->height : 0;
}

TreeNode* rotateRight(TreeNode *y) {
    TreeNode *x = y->left;
    TreeNode *T2 = x->right;

    x->right = y;
    y->left = T2;

    y->height = calculateHeight(y->left) > calculateHeight(y->right) ? 
                calculateHeight(y->left) + 1 : calculateHeight(y->right) + 1;
    x->height = calculateHeight(x->left) > calculateHeight(x->right) ? 
                calculateHeight(x->left) + 1 : calculateHeight(x->right) + 1;

    return x;
}

TreeNode* rotateLeft(TreeNode *x) {
    TreeNode *y = x->right;
    TreeNode *T2 = y->left;

    y->left = x;
    x->right = T2;

    x->height = calculateHeight(x->left) > calculateHeight(x->right) ? 
                calculateHeight(x->left) + 1 : calculateHeight(x->right) + 1;
    y->height = calculateHeight(y->left) > calculateHeight(y->right) ? 
                calculateHeight(y->left) + 1 : calculateHeight(y->right) + 1;

    return y;
}

size_t hashFunction(const char *str, size_t capacity) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++)) hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % capacity;
}

void logRebalanceOperation(const char *message) {
    printf("Log: %s\n", message);
}
```

