```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <assert.h>

#define MAX_LOGS 10000000
#define LOG_ENTRY_SIZE sizeof(LogEntry)
#define DAYS_TO_KEEP 30

typedef struct {
    int logID;
    time_t timestamp;
    char userID[256];
    void *entries; // Variable-length sequence of entries
    size_t entrySize;
} LogEntry;

typedef struct {
    LogEntry *logs[MAX_LOGS];
    size_t count;
    pthread_mutex_t lock;
} LogManager;

LogManager logManager = { .count = 0, .lock = PTHREAD_MUTEX_INITIALIZER };

void initLogManager() {
    memset(&logManager, 0, sizeof(logManager));
}

int addLog(int logID, time_t timestamp, const char *userID, void *entries, size_t entrySize) {
    pthread_mutex_lock(&logManager.lock);
    if (logManager.count >= MAX_LOGS) {
        fprintf(stderr, "Max logs reached\n");
        pthread_mutex_unlock(&logManager.lock);
        return -1;
    }
    LogEntry *newLog = malloc(LOG_ENTRY_SIZE + entrySize);
    if (!newLog) {
        perror("Failed to allocate log entry");
        pthread_mutex_unlock(&logManager.lock);
        return -1;
    }
    newLog->logID = logID;
    newLog->timestamp = timestamp;
    strncpy(newLog->userID, userID, sizeof(newLog->userID) - 1);
    newLog->entries = (char *)newLog + LOG_ENTRY_SIZE;
    memcpy(newLog->entries, entries, entrySize);
    newLog->entrySize = entrySize;
    logManager.logs[logManager.count++] = newLog;
    pthread_mutex_unlock(&logManager.lock);
    return 0;
}

void cleanupLogs() {
    time_t currentTime = time(NULL);
    time_t cutoffTime = currentTime - (DAYS_TO_KEEP * 24 * 60 * 60);

    pthread_mutex_lock(&logManager.lock);
    for (size_t i = 0; i < logManager.count; ++i) {
        if (difftime(logManager.logs[i]->timestamp, cutoffTime) < 0) {
            free(logManager.logs[i]);
            memmove(&logManager.logs[i], &logManager.logs[i + 1],
                    (logManager.count - i - 1) * sizeof(LogEntry *));
            --logManager.count;
            --i; // Adjust index after removal
        }
    }
    pthread_mutex_unlock(&logManager.lock);
}

void* housekeepingThread(void *arg) {
    while (1) {
        sleep(24 * 60 * 60); // Run once a day
        cleanupLogs();
    }
    return NULL;
}

void startHousekeeping() {
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, housekeepingThread, NULL);
}

int main() {
    initLogManager();
    startHousekeeping();

    // Example usage
    char userAction[] = "User logged in";
    addLog(1, time(NULL), "user123", userAction, sizeof(userAction));

    return 0;
}
```

