        resize_dynamic_array(arr);
    }

    Record new_record = { .key = key, .offset = offset };
    srand(time(NULL) ^ getpid());  // Seed for randomness
    new_record.record_value = rand() % (max_value - min_value + 1) + min_value;

    arr->records[arr->count++] = new_record;

    pthread_mutex_unlock(&arr->lock);
}

// Function to update a record by key
void update_record(DynamicArray *arr, int key, int new_min_value, int new_max_value) {
    pthread_mutex_lock(&arr->lock);

    for (size_t i = 0; i < arr->count; ++i) {
        if (arr->records[i].key == key) {
            srand(time(NULL) ^ getpid());
            arr->records[i].record_value = rand() % (new_max_value - new_min_value + 1) + new_min_value;
            break;
        }
    }

    pthread_mutex_unlock(&arr->lock);
}

// Function to delete a record by key
void delete_record(DynamicArray *arr, int key) {
    pthread_mutex_lock(&arr->lock);

    for (size_t i = 0; i < arr->count; ++i) {
        if (arr->records[i].key == key) {
            memmove(&arr->records[i], &arr->records[i + 1],
                    sizeof(Record) * (arr->count - i - 1));
            --arr->count;
            break;
        }
    }

    pthread_mutex_unlock(&arr->lock);
}

// Function to parse and modify the filename
void parse_and_modify_filename(const char *filename, char *modified_filename) {
    const char *dot = strrchr(filename, '.');
    int name_length = dot ? (int)(dot - filename) : (int)strlen(filename);

    snprintf(modified_filename, 256, "%s%02d%s", filename, name_length,
             dot ? dot : ".dat");
}

// Function to log operations
void log_operation(const char *message) {
    FILE *log_file = fopen("operations.log", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

// Example usage of the functions defined above
int main() {
    DynamicArray my_array;
    init_dynamic_array(&my_array, 10);

    add_record(&my_array, 1, 1000, 0, 50);
    update_record(&my_array, 1, 0, 100);
    delete_record(&my_array, 1);

    char modified_filename[256];
    parse_and_modify_filename("example", modified_filename);
    printf("Modified Filename: %s\n", modified_filename);

    log_operation("Added a record");

    free(my_array.records);
    pthread_mutex_destroy(&my_array.lock);
    return 0;
}
```

### Explanation

- **Dynamic Array Management**: The `DynamicArray` structure manages an array of records with dynamic resizing.
- **Thread Safety**: Thread safety is ensured using `pthread_mutex_t`.
- **Random Value Assignment**: Random values are assigned to the `record_value` field using `rand()`.
- **Filename Parsing and Modification**: Uses `strrchr`, `snprintf`, and `strcat` (via format specifiers) for filename parsing.
- **Logging**: Simple file logging is implemented with `fopen`, `fprintf`, and `fclose`.

This code serves as a starting point, with extensibility in mind to support additional validation rules, configuration types, and system monitoring.']

