#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum {
    STATUS_ACTIVE,
    STATUS_INACTIVE,
    STATUS_UNKNOWN
} Status;

typedef struct {
    long id;
    long timestamp;
    Status status;
    size_t data_length;
    unsigned char *data_buffer;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordManager;

// Initialize the record manager
void init_record_manager(RecordManager *manager, size_t initial_capacity) {
    manager->records = malloc(initial_capacity * sizeof(Record));
    if (!manager->records) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

// Clean up the record manager
void destroy_record_manager(RecordManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->records[i].data_buffer);
    }
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
}

// Resize the records array
void resize_record_manager(RecordManager *manager, size_t new_capacity) {
    Record *new_records = realloc(manager->records, new_capacity * sizeof(Record));
    if (!new_records) {
        perror("Failed to reallocate memory for records");
        exit(EXIT_FAILURE);
    }
    manager->records = new_records;
    manager->capacity = new_capacity;
}

// Add or update a record
void set_record(RecordManager *manager, long id, long timestamp, Status status, const unsigned char *data_buffer, size_t data_length) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i].id == id) {
            free(manager->records[i].data_buffer);
            if (data_buffer && data_length > 0) {
                manager->records[i].data_buffer = malloc(data_length);
                memcpy(manager->records[i].data_buffer, data_buffer, data_length);
            } else {
                manager->records[i].data_buffer = NULL;
            }
            manager->records[i].timestamp = timestamp;
            manager->records[i].status = status;
            manager->records[i].data_length = data_length;
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    if (manager->count == manager->capacity) {
        resize_record_manager(manager, manager->capacity * 2);
    }

    Record new_record = {id, timestamp, status, data_length};
    new_record.data_buffer = malloc(data_length);
    memcpy(new_record.data_buffer, data_buffer, data_length);

    manager->records[manager->count++] = new_record;
    pthread_mutex_unlock(&manager->lock);
}

// Delete a record
void delete_record(RecordManager *manager, long id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i].id == id) {
            free(manager->records[i].data_buffer);
            memmove(&manager->records[i], &manager->records[i + 1], (manager->count - i - 1) * sizeof(Record));
            manager->count--;
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

// Load data from a file and set the record
void load_data_from_file(RecordManager *manager, long id, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    fseek(file, 0, SEEK_END);
    size_t data_length = ftell(file);
    rewind(file);

    unsigned char *data_buffer = malloc(data_length);
    if (!data_buffer) {
        perror("Failed to allocate memory for data buffer");
        fclose(file);
        return;
    }

    fread(data_buffer, 1, data_length, file);
    fclose(file);

    set_record(manager, id, time(NULL), STATUS_ACTIVE, data_buffer, data_length);
    free(data_buffer);
}

// Example usage
int main() {
    RecordManager manager;
    init_record_manager(&manager, 10);

    load_data_from_file(&manager, 1, "data.bin");
    delete_record(&manager, 1);

    destroy_record_manager(&manager);
    return 0;
}
```

