#include <pthread.h>

#define MAX_TASK_NAME_LEN 256

typedef enum {
    TASK_STATUS_PENDING,
    TASK_STATUS_IN_PROGRESS,
    TASK_STATUS_COMPLETED
} TaskStatus;

typedef struct Task {
    char name[MAX_TASK_NAME_LEN];
    int priority;
    TaskStatus status;
    struct Task* next;
} Task;

typedef struct TaskList {
    Task* head;
    pthread_mutex_t mutex;
} TaskList;

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

TaskList* create_task_list() {
    TaskList* list = (TaskList*)malloc(sizeof(TaskList));
    if (!list) {
        log_error("Failed to allocate memory for task list");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_task_list(TaskList* list) {
    Task* current = list->head;
    while (current) {
        Task* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_task(TaskList* list, const char* name, int priority, TaskStatus status) {
    if (priority < 0 || strlen(name) >= MAX_TASK_NAME_LEN) {
        log_error("Invalid task parameters");
        return -1;
    }

    pthread_mutex_lock(&list->mutex);

    Task* new_task = (Task*)malloc(sizeof(Task));
    if (!new_task) {
        pthread_mutex_unlock(&list->mutex);
        log_error("Failed to allocate memory for new task");
        return -1;
    }

    strncpy(new_task->name, name, MAX_TASK_NAME_LEN);
    new_task->priority = priority;
    new_task->status = status;
    new_task->next = NULL;

    Task** current = &list->head;
    while (*current && (*current)->priority <= priority) {
        current = &(*current)->next;
    }

    new_task->next = *current;
    *current = new_task;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int remove_task(TaskList* list, const char* name) {
    pthread_mutex_lock(&list->mutex);

    Task** current = &list->head;
    while (*current) {
        if (strcmp((*current)->name, name) == 0) {
            Task* to_remove = *current;
            *current = (*current)->next;
            free(to_remove);
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&list->mutex);
    log_error("Task not found");
    return -1;
}

int update_task(TaskList* list, const char* name, int priority, TaskStatus status) {
    if (priority < 0 || strlen(name) >= MAX_TASK_NAME_LEN) {
        log_error("Invalid task parameters");
        return -1;
    }

    pthread_mutex_lock(&list->mutex);

    Task** current = &list->head;
    while (*current) {
        if (strcmp((*current)->name, name) == 0) {
            // Remove the task
            Task* to_update = *current;
            *current = (*current)->next;

            // Update its fields
            strncpy(to_update->name, name, MAX_TASK_NAME_LEN);
            to_update->priority = priority;
            to_update->status = status;

            // Reinsert it in sorted order
            Task** insert_pos = &list->head;
            while (*insert_pos && (*insert_pos)->priority <= priority) {
                insert_pos = &(*insert_pos)->next;
            }

            to_update->next = *insert_pos;
            *insert_pos = to_update;

            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&list->mutex);
    log_error("Task not found");
    return -1;
}

void list_tasks(TaskList* list) {
    pthread_mutex_lock(&list->mutex);

    Task* current = list->head;
    while (current) {
        printf("Name: %s, Priority: %d, Status: %d\n", 
               current->name, current->priority, current->status);
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
}
