namespace UserSessionManager {

    struct UserSessionData {
        int userId;
        std::chrono::system_clock::time_point sessionStart;
        std::chrono::system_clock::time_point sessionEnd;
        double sessionDuration;

        // Populated with default values
        UserSessionData() : userId(0), sessionDuration(0.0) {}
    };

    class SessionManager {
    private:
        std::vector<UserSessionData> sessions;
        std::mutex dataMutex;
        std::default_random_engine generator;

        struct Configuration {
            double mean = 30.0; // Example mean duration
            double variance = 5.0; // Example variance

            void loadFromExternalService() {
                // Simulate loading configuration with error handling
                try {
                    // External service interaction, handle potential exceptions
                    // For example: fetch from a network or database and parse it.

                    // Placeholder for fetched data
                    mean = 45.0;
                    variance = 10.0;
                } catch (...) {
                    std::cerr << "Failed to load configuration from external service" << std::endl;
                }
            }

            bool isValid() const { return mean > 0 && variance > 0; }
        };

    public:
        SessionManager() : generator(std::random_device{}()) {}

        ~SessionManager() = default;

        void initializeConfiguration(Configuration &config) {
            config.loadFromExternalService();
            if (!config.isValid()) {
                // Fall back to defaults or handle error
                std::cerr << "Using default configuration" << std::endl;
            }
        }

        void readBinaryFile(const std::string& filename) {
            std::ifstream file(filename, std::ios::binary);
            if (!file.is_open()) {
                std::cerr << "Could not open input file" << std::endl;
                return;
            }

            UserSessionData tempSession;
            while (file.read(reinterpret_cast<char*>(&tempSession), sizeof(tempSession))) {
                addSession(std::move(tempSession));
            }
        }

        void generateSessions(int count, const Configuration &config) {
            std::normal_distribution<double> distribution(config.mean, config.variance);
            for (int i = 0; i < count; ++i) {
                UserSessionData session;
                session.userId = i + 1;
                auto duration = distribution(generator);
                session.sessionStart = std::chrono::system_clock::now() - std::chrono::seconds(static_cast<long>(duration));
                session.sessionEnd = session.sessionStart + std::chrono::seconds(static_cast<long>(duration));
                session.sessionDuration = duration;

                addSession(std::move(session));
            }
        }

        void writeBinaryFile(const std::string& filename) {
            std::ofstream file(filename, std::ios::binary);
            if (!file.is_open()) {
                std::cerr << "Could not open output file" << std::endl;
                return;
            }

            for (const auto& session : sessions) {
                file.write(reinterpret_cast<const char*>(&session), sizeof(session));
            }
        }

    private:
        void addSession(UserSessionData&& session) {
            std::lock_guard<std::mutex> lock(dataMutex);
            sessions.push_back(std::move(session));
        }
    };

}

int main(int argc, char* argv[]) {
    if (argc < 4) {
        std::cerr << "Usage: processAndSortRecords <input_file> <output_file> <num_sessions>" << std::endl;
        return EXIT_FAILURE;
    }

    std::string inputFilename = argv[1];
    std::string outputFilename = argv[2];
    int numSessions = std::atoi(argv[3]);

    UserSessionManager::Configuration config;
    UserSessionManager::SessionManager sessionManager;

    sessionManager.initializeConfiguration(config);
    if (!config.isValid()) {
        return EXIT_FAILURE;
    }

    sessionManager.readBinaryFile(inputFilename);

    sessionManager.generateSessions(numSessions, config);

    sessionManager.writeBinaryFile(outputFilename);

    return 0;
}
