public class SessionManager {
    private final ConcurrentHashMap<String, UserSession> sessions = new ConcurrentHashMap<>();
    private final ScheduledExecutorService executorService = Executors.newScheduledThreadPool(2);
    private final Cache<String, UserSession> sessionCache;
    private static final int CLEANUP_INTERVAL_SECONDS = 60;
    private static final long INACTIVITY_THRESHOLD_MS = 30_000; // 30 seconds

    public SessionManager() {
        this.sessionCache = Caffeine.newBuilder()
                .expireAfterWrite(10, TimeUnit.MINUTES)
                .maximumSize(1000)
                .build();

        initializeBackgroundTasks();
    }

    private void initializeBackgroundTasks() {
        executorService.scheduleAtFixedRate(this::cleanupExpiredSessions, CLEANUP_INTERVAL_SECONDS, CLEANUP_INTERVAL_SECONDS, TimeUnit.SECONDS);
    }

    public synchronized UserSession createSession(String userId) {
        if (sessions.containsKey(userId)) return sessions.get(userId);

        UserSession session = new UserSession(userId, System.currentTimeMillis());
        sessions.put(userId, session);
        sessionCache.put(userId, session);
        log("Created session for user: " + userId);

        monitorAnomalies();
        return session;
    }

    public synchronized void updateSession(String userId, Map<String, Object> updates) {
        UserSession session = sessions.get(userId);
        if (session != null) {
            session.update(updates);
            log("Updated session for user: " + userId);

            monitorAnomalies();
        }
    }

    public synchronized void deleteSession(String userId) {
        UserSession removedSession = sessions.remove(userId);
        if (removedSession != null) {
            sessionCache.invalidate(userId);
            log("Deleted session for user: " + userId);

            monitorAnomalies();
        }
    }

    private void cleanupExpiredSessions() {
        long currentTime = System.currentTimeMillis();
        sessions.entrySet().removeIf(entry -> 
                currentTime - entry.getValue().getLastActivityTimestamp() > INACTIVITY_THRESHOLD_MS
        );

        log("Cleaned up expired sessions");
    }

    private void monitorAnomalies() {
        // Custom anomaly detection logic here
        int activeSessionsCount = sessions.size();
        if (activeSessionsCount > 1000) { // Example threshold
            sendAlert("Excessive number of active sessions detected: " + activeSessionsCount);
        }
    }

    private void sendAlert(String message) {
        // Integration with third-party notification service
        System.out.println("ALERT: " + message);
    }

    public synchronized void shutdown() {
        executorService.shutdownNow();
        log("Shutdown initiated");

        sessions.clear();
        sessionCache.invalidateAll();
        log("Session manager shut down gracefully");
    }

