#define ERROR_CODE -1

typedef struct {
    int value;
} Record;

void *sortRecords(void *args);
int getLargestInteger(int *array, size_t size);

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to generate random numbers with a custom seed
void setRandomSeed(unsigned int seed) {
    srand(seed);
}

// Helper function to handle errors in memory allocation
int handleError(const char* message) {
    fprintf(stderr, "%s\n", message);
    return ERROR_CODE;
}

// Function to dynamically allocate and manage arrays for records, keys, and offsets
int processAndOrganizeDataWithEnvConfig(size_t numRecords, int rangeMin, int rangeMax, unsigned int seed) {
    pthread_t sortThread;

    // Set the random number generator seed for reproducibility
    setRandomSeed(seed);

    // Allocate memory for arrays
    long *offsets = (long *)malloc(numRecords * sizeof(long));
    int *keys = (int *)malloc(numRecords * sizeof(int));
    Record *records = (Record *)malloc(numRecords * sizeof(Record));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return handleError("Memory allocation failed");
    }

    // Populate records and keys with random values
    for (size_t i = 0; i < numRecords; ++i) {
        offsets[i] = rand() % 100;
        keys[i] = rand() % (rangeMax - rangeMin + 1) + rangeMin;
        records[i].value = rand() % (rangeMax - rangeMin + 1) + rangeMin;
    }

    // Sort the records based on their corresponding key values
    pthread_create(&sortThread, NULL, sortRecords, (void *)keys);
    pthread_join(sortThread, NULL);

    // Read integers from standard input and find the largest integer
    size_t arraySize = 0;
    int *inputArray = NULL;

    while (scanf("%d", &arraySize) == 1) {
        if (!inputArray) {
            inputArray = malloc(arraySize * sizeof(int));
            if (!inputArray) return handleError("Memory allocation failed");
        } else {
            int *temp = realloc(inputArray, arraySize * sizeof(int));
            if (!temp) {
                free(inputArray);
                return handleError("Memory reallocation failed");
            }
            inputArray = temp;
        }

        for (size_t i = 0; i < arraySize; ++i) {
            scanf("%d", &inputArray[i]);
        }

        int largest = getLargestInteger(inputArray, arraySize);
        printf("Largest integer: %d\n", largest);

        free(inputArray);
    }

    // Configuration management and directory operations
    const char *dirName = "configDir";
    const char *envVarName = "CONFIG_PATH";

    pthread_mutex_lock(&mutex);
    char *existingPath = getenv(envVarName);

    if (!existingPath) {
        int result = mkdir(dirName, 0777);
        if (result == -1) return handleError("Failed to create directory");

        setenv(envVarName, dirName, 1);
        printf("Environment variable set: %s=%s\n", envVarName, dirName);
    } else {
        printf("Using existing environment path: %s=%s\n", envVarName, existingPath);
    }
    pthread_mutex_unlock(&mutex);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    return 0;
}

// Function to sort records based on keys
void *sortRecords(void *args) {
    int *keys = (int *)args;
    size_t numKeys = sizeof(keys) / sizeof(keys[0]);

    for (size_t i = 0; i < numKeys - 1; ++i) {
        for (size_t j = 0; j < numKeys - i - 1; ++j) {
            if (keys[j] > keys[j + 1]) {
                int temp = keys[j];
                keys[j] = keys[j + 1];
                keys[j + 1] = temp;
            }
        }
    }

    return NULL;
}

// Helper function to find the largest integer in an array
int getLargestInteger(int *array, size_t size) {
    int largest = array[0];

    for (size_t i = 1; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    return largest;
}

// Unit tests and further concurrency testing would be implemented separately
