void log_attempt(const char *message) {
    pthread_mutex_lock(&logBuffer.lock);
    snprintf(logBuffer.entries[logBuffer.index], sizeof(logBuffer.entries[0]), "%s", message);
    logBuffer.index = (logBuffer.index + 1) % LOG_BUFFER_SIZE;
    if (logBuffer.count < LOG_BUFFER_SIZE) {
        logBuffer.count++;
    }
    pthread_mutex_unlock(&logBuffer.lock);
}

// Memory pool for efficient allocations
char memoryPool[MEMORY_POOL_SIZE];
size_t memoryOffset = 0;

void* allocate_from_pool(size_t size) {
    if (memoryOffset + size > MEMORY_POOL_SIZE) return NULL;
    void *ptr = &memoryPool[memoryOffset];
    memoryOffset += size;
    return ptr;
}

// Initialize the network data structure
