    if (!root) {
        Node *node = allocate_from_pool(sizeof(Node));
        if (!node) return NULL;

        node->key = key;
        node->left = node->right = NULL;
        node->edges = NULL; // Initialize as needed

        return node;
    }

    if (key < root->key)
        root->left = insert_node(root->left, key);
    else if (key > root->key)
        root->right = insert_node(root->right, key);

    return root;
}

