// Memory pool definitions
#define MAX_EVENTS 1000
#define MAX_FRAMES_PER_EVENT 50
#define MEMORY_POOL_SIZE (MAX_EVENTS * sizeof(NETWORK_EVENT) + MAX_EVENTS * MAX_FRAMES_PER_EVENT * sizeof(MAC_FRAME_DATA))

static uint8_t memoryPool[MEMORY_POOL_SIZE];
static pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;
static NETWORK_EVENT *eventList[MAX_EVENTS] = {NULL};
static size_t eventCount = 0;

// Function prototypes
void initializeMemoryPool();
NETWORK_EVENT* allocateNetworkEvent();
MAC_FRAME_DATA* allocateFrameData(NETWORK_EVENT* event);
int addNetworkEvent(uint32_t macEventTag, uint64_t timestamp);
void removeNetworkEvent(NETWORK_EVENT* event);
NETWORK_EVENT* getNetworkEvent(size_t index);
size_t findMaxInt(int *arr, size_t n);
int convertImageToPDF(const char *inputFileName, const char *outputFileName);

// Initialize memory pool
void initializeMemoryPool() {
    pthread_mutex_lock(&listMutex);
    memset(memoryPool, 0, MEMORY_POOL_SIZE);
    pthread_mutex_unlock(&listMutex);
}

NETWORK_EVENT* allocateNetworkEvent() {
    NETWORK_EVENT *event = (NETWORK_EVENT*)memoryPool;
    if (!event) return NULL;

    event->frames = malloc(MAX_FRAMES_PER_EVENT * sizeof(MAC_FRAME_DATA));
    if (!event->frames) {
        free(event);
        return NULL;
    }

    memoryPool += sizeof(NETWORK_EVENT);
    return event;
}

MAC_FRAME_DATA* allocateFrameData(NETWORK_EVENT* event) {
    MAC_FRAME_DATA *frame = (MAC_FRAME_DATA*)(memoryPool + (uintptr_t)(event - (NETWORK_EVENT*)memoryPool));
    if ((size_t)((char*)frame - memoryPool) >= MEMORY_POOL_SIZE) return NULL;

    memoryPool += sizeof(MAC_FRAME_DATA);
    return frame;
}

int addNetworkEvent(uint32_t macEventTag, uint64_t timestamp) {
    pthread_mutex_lock(&listMutex);

    if (eventCount >= MAX_EVENTS) {
        pthread_mutex_unlock(&listMutex);
        fprintf(stderr, "Max events reached\n");
        return -1;
    }

    NETWORK_EVENT *newEvent = allocateNetworkEvent();
    if (!newEvent) {
        pthread_mutex_unlock(&listMutex);
        fprintf(stderr, "Memory allocation failed for network event\n");
        return -2;
    }

    newEvent->macEventTag = macEventTag;
    newEvent->timestamp = timestamp;
    eventList[eventCount++] = newEvent;

    pthread_mutex_unlock(&listMutex);
    return 0;
}

void removeNetworkEvent(NETWORK_EVENT* event) {
    pthread_mutex_lock(&listMutex);

    for (size_t i = 0; i < eventCount; ++i) {
        if (eventList[i] == event) {
            free(event->frames);
            eventList[i] = eventList[--eventCount];
            break;
        }
    }

    pthread_mutex_unlock(&listMutex);
}

NETWORK_EVENT* getNetworkEvent(size_t index) {
    if (index >= eventCount) return NULL;

    pthread_mutex_lock(&listMutex);
    NETWORK_EVENT *event = eventList[index];
    pthread_mutex_unlock(&listMutex);

    return event;
}

size_t findMaxInt(int *arr, size_t n) {
    if (!arr || n == 0) return (size_t)-1;

    int maxVal = arr[0];
    for (size_t i = 1; i < n; ++i) {
        if (arr[i] > maxVal) maxVal = arr[i];
    }

    return (size_t)maxVal;
}

