    for (size_t i = 0; i < arraySize; ++i) {
        scanf("%d", &numbers[i]);
    }

    size_t maxInt = findMaxInt(numbers, arraySize);
    if (maxInt != (size_t)-1) {
        printf("Largest integer: %zu\n", maxInt);
    } else {
        fprintf(stderr, "Error finding the largest integer.\n");
    }

    free(numbers);
    return 0;
}

int convertImageToPDF(const char *inputFileName, const char *outputFileName) {
    char command[256];
    snprintf(command, sizeof(command), "convert %s %s", inputFileName, outputFileName);

    if (system(command) != 0) {
        fprintf(stderr, "Failed to convert image to PDF\n");
        return 1;
    }

    return 0;
}

int processNetworkEventsAndConvertImageToPDF(const char *inputImageName, const char *outputPdfName) {
    initializeMemoryPool();

    // Example usage of adding network events
    addNetworkEvent(1234, 1627890123);
    NETWORK_EVENT *event = getNetworkEvent(0);

    if (event) {
        MAC_FRAME_DATA *frame = allocateFrameData(event);
        if (!frame) {
            fprintf(stderr, "Failed to allocate frame data\n");
            return -1;
        }
    }

    // Process user input and find maximum integer
    processInputAndFindMax();

    // Convert image to PDF
    return convertImageToPDF(inputImageName, outputPdfName);
}
