#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Node {
    char *key;
    double value;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t lock;
} Collection;

Collection* create_collection() {
    Collection *collection = malloc(sizeof(Collection));
    if (!collection) return NULL;
    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

int add_node(Collection *collection, const char *key, double value) {
    pthread_mutex_lock(&collection->lock);

    Node *current = collection->head;
    while (current) {
        if (strcmp(current->key, key) == 0) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Duplicate key
        }
        current = current->next;
    }

    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&collection->lock);
        return -2; // Allocation failure
    }

    new_node->key = strdup(key);
    if (!new_node->key) {
        free(new_node);
        pthread_mutex_unlock(&collection->lock);
        return -3; // Allocation failure for key
    }
    new_node->value = value;
    new_node->next = collection->head;
    collection->head = new_node;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

void refresh_collection(Collection *collection, const char (*keys)[50], double values[], size_t count) {
    for (size_t i = 0; i < count; ++i) {
        add_node(collection, keys[i], values[i]);
    }
}

int calculate_average_value(Collection *collection) {
    pthread_mutex_lock(&collection->lock);

    if (!collection->head) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Empty collection
    }

    double sum = 0.0;
    size_t count = 0;
    Node *current = collection->head;

    while (current) {
        sum += current->value;
        ++count;
        current = current->next;
    }

    int average = round(sum / count);
    pthread_mutex_unlock(&collection->lock);

    return average;
}

void free_collection(Collection *collection) {
    pthread_mutex_lock(&collection->lock);

    Node *current = collection->head;
    while (current) {
        Node *to_free = current;
        current = current->next;
        free(to_free->key);
        free(to_free);
    }
    collection->head = NULL;

    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

// Simulate external data updates
void* update_data_source(void *arg) {
    Collection *collection = (Collection *)arg;

    // Example: Simulating periodic refresh from a remote server
    const char keys[][50] = {"key1", "key2", "key3"};
    double values[] = {10.5, 20.7, 30.8};

    while (1) {
        sleep(5); // Simulate delay between updates
        refresh_collection(collection, keys, values, 3);
    }

    return NULL;
}

int main() {
    Collection *collection = create_collection();
    if (!collection) {
        fprintf(stderr, "Failed to create collection\n");
        return EXIT_FAILURE;
    }

    pthread_t updater_thread;
    if (pthread_create(&updater_thread, NULL, update_data_source, collection)) {
        perror("Thread creation failed");
        free_collection(collection);
        return EXIT_FAILURE;
    }

    // Main thread operations
    int average = calculate_average_value(collection);
    if (average != -1) {
        printf("Average value: %d\n", average);
    } else {
        printf("Collection is empty.\n");
    }

    pthread_join(updater_thread, NULL); // In real applications, this might be a never-ending loop
    free_collection(collection);

    return EXIT_SUCCESS;
}
