} NetworkPerformanceMetrics;

typedef struct {
    NetworkPerformanceMetrics *metrics;
    size_t count;
    size_t capacity;
} MetricsArray;

// Function to resize the array
int resizeMetricsArray(MetricsArray *array, size_t newCapacity) {
    NetworkPerformanceMetrics *newMetrics = realloc(array->metrics, newCapacity * sizeof(NetworkPerformanceMetrics));
    if (!newMetrics) return 0; // Memory allocation failed

    array->metrics = newMetrics;
    array->capacity = newCapacity;
    return 1; // Success
}

// Function to add a metric and compute moving average for the last 10 entries
void addMetric(MetricsArray *array, NetworkPerformanceMetrics newMetric) {
    if (array->count == array->capacity) {
        size_t newCapacity = array->capacity * 2;
        if (!resizeMetricsArray(array, newCapacity)) return; // Handle reallocation failure
    }

    int startIndex = (int)(array->count - 9 < 0 ? 0 : array->count - 9);
    double sum = 0.0;

    for (size_t i = startIndex; i < array->count; ++i) {
        sum += array->metrics[i].throughput;
    }

    newMetric.throughput = sum / (array->count >= 10 ? 10 : (int)(array->count - startIndex + 1));

    array->metrics[array->count++] = newMetric;
}

// Custom serialization function
size_t serializeMetricsArray(const MetricsArray *array, unsigned char **buffer) {
    size_t dataSize = sizeof(int) + sizeof(time_t) + sizeof(double); // cellId, timeStamp, throughput
    size_t totalSize = array->count * dataSize;

    *buffer = malloc(totalSize);
    if (!*buffer) return 0; // Memory allocation failed

    unsigned char *ptr = *buffer;
    for (size_t i = 0; i < array->count; ++i) {
        memcpy(ptr, &array->metrics[i].cellId, sizeof(int));
        ptr += sizeof(int);
        memcpy(ptr, &array->metrics[i].timeStamp, sizeof(time_t));
        ptr += sizeof(time_t);
        memcpy(ptr, &array->metrics[i].throughput, sizeof(double));
        ptr += sizeof(double);
    }

    return totalSize;
}

// Custom deserialization function
int deserializeMetricsArray(const unsigned char *buffer, size_t bufferSize, MetricsArray *array) {
    if (buffer == NULL || array == NULL) return 0;

    size_t expectedSize = sizeof(int) + sizeof(time_t) + sizeof(double);
    if (bufferSize % expectedSize != 0) return 0; // Corrupted data

    size_t count = bufferSize / expectedSize;
    if (!resizeMetricsArray(array, count)) return 0; // Handle reallocation failure

    const unsigned char *ptr = buffer;
    for (size_t i = 0; i < count; ++i) {
        memcpy(&array->metrics[i].cellId, ptr, sizeof(int));
        ptr += sizeof(int);
        memcpy(&array->metrics[i].timeStamp, ptr, sizeof(time_t));
        ptr += sizeof(time_t);
        memcpy(&array->metrics[i].throughput, ptr, sizeof(double));
        ptr += sizeof(double);
    }

    array->count = count;
    return 1; // Success
}

// Function to free the metrics array
void freeMetricsArray(MetricsArray *array) {
    if (array) {
        free(array->metrics);
        array->metrics = NULL;
        array->count = 0;
        array->capacity = 0;
    }
}
