        pthread_mutex_unlock(&mutex);
        return ALLOCATION_ERROR;
    }

    // Allocate memory for keys and ensure alignment
    if (!posix_memalign((void**)keys, 16, num_nodes * sizeof(int))) {
        printf("Key allocation successful.\n");
    } else {
        free(*offsets);
        pthread_mutex_unlock(&mutex);
        return ALLOCATION_ERROR;
    }

    // Allocate memory for records and ensure alignment
    if (!posix_memalign((void**)records, 16, num_nodes * sizeof(record))) {
        printf("Record allocation successful.\n");
    } else {
        free(*offsets);
        free(*keys);
        pthread_mutex_unlock(&mutex);
        return ALLOCATION_ERROR;
    }

    // Allocate memory for values and ensure alignment
    if (!posix_memalign((void**)values, 16, num_nodes * sizeof(double))) {
        printf("Value allocation successful.\n");
    } else {
        free(*offsets);
        free(*keys);
        free(*records);
        pthread_mutex_unlock(&mutex);
        return ALLOCATION_ERROR;
    }

    // Allocate memory for nodes and ensure alignment
    if (!posix_memalign((void**)nodes, 16, num_nodes * sizeof(node_t*))) {
        printf("Node pointer allocation successful.\n");
    } else {
        free(*offsets);
        free(*keys);
        free(*records);
        free(*values);
        pthread_mutex_unlock(&mutex);
        return ALLOCATION_ERROR;
    }

    // Allocate memory for individual nodes
    *nodes = (node_t**)malloc(num_nodes * sizeof(node_t));
    if (*nodes == NULL) {
        free(*offsets);
        free(*keys);
        free(*records);
        free(*values);
        free(*nodes);
        pthread_mutex_unlock(&mutex);
        return ALLOCATION_ERROR;
    }

    for (size_t i = 0; i < num_nodes; i++) {
        (*nodes)[i] = (node_t*)malloc(sizeof(node_t));
        if ((*nodes)[i] == NULL) {
            free(*offsets);
            free(*keys);
            free(*records);
            free(*values);
            for (size_t j = 0; j < i; j++) {
                free((*nodes)[j]);
            }
            free(*nodes);
            pthread_mutex_unlock(&mutex);
            return ALLOCATION_ERROR;
        }

        (*nodes)[i]->children = (node_t**)malloc(2 * sizeof(node_t*)); // max two children for binary tree
        if ((*nodes)[i]->children == NULL) {
            free((*nodes)[i]);
            for (size_t j = 0; j < i; j++) {
                free((*nodes)[j]);
            }
            free(*nodes);
            pthread_mutex_unlock(&mutex);
            return ALLOCATION_ERROR;
        }

        (*nodes)[i]->edges = (edge_t**)malloc(num_edges_per_node * sizeof(edge_t*));
        if ((*nodes)[i]->edges == NULL) {
            free((*nodes)[i]->children);
            free((*nodes)[i]);
            for (size_t j = 0; j < i; j++) {
                free((*nodes)[j]->children);
                free((*nodes)[j]);
            }
            free(*nodes);
            pthread_mutex_unlock(&mutex);
            return ALLOCATION_ERROR;
        }

        // Initialize edges
        for (size_t j = 0; j < num_edges_per_node; j++) {
            (*nodes)[i]->edges[j] = (edge_t*)malloc(sizeof(edge_t));
            if ((*nodes)[i]->edges[j] == NULL) {
                for (size_t k = 0; k < j; k++) {
                    free((*nodes)[i]->edges[k]);
                }
                free((*nodes)[i]->edges);
                free((*nodes)[i]->children);
                free((*nodes)[i]);
                for (size_t l = 0; l < i; l++) {
                    free((*nodes)[l]->children);
                    free((*nodes)[l]->edges);
                    free((*nodes)[l]);
                }
                free(*nodes);
                pthread_mutex_unlock(&mutex);
                return ALLOCATION_ERROR;
            }
        }

        (*nodes)[i]->num_children = 0;
        (*nodes)[i]->num_edges = num_edges_per_node;
    }

    // Populate keys with random values
    populate_keys(*keys, num_nodes, 1, 100);

    // Assign weights to edges based on probability
    for (size_t i = 0; i < num_nodes; i++) {
        assign_edge_weights((*nodes)[i]->edges, (*nodes)[i]->num_edges, 0.5);
    }

    pthread_mutex_unlock(&mutex);
    return SUCCESS;
}

void populate_keys(int *keys, size_t count, int min_value, int max_value) {
    for (size_t i = 0; i < count; i++) {
        keys[i] = rand() % (max_value - min_value + 1) + min_value;
    }
}

void assign_edge_weights(edge_t **edges, size_t count, double weight_probability) {
    for (size_t i = 0; i < count; i++) {
        edges[i]->weight = ((double)rand() / RAND_MAX) <= weight_probability ? rand() % 100 + 1 : 0.0;
    }
}

void free_memory(long *offsets, int *keys, record *records, double *values,
                 node_t **nodes, size_t num_nodes) {
    for (size_t i = 0; i < num_nodes; i++) {
        if (nodes[i]) {
            // Free edges
            for (size_t j = 0; j < nodes[i]->num_edges; j++) {
                free(nodes[i]->edges[j]);
            }
            free(nodes[i]->edges);

            // Free children array
            free(nodes[i]->children);

            // Free node itself
            free(nodes[i]);
        }
    }

    free(nodes);

    free(values);
    free(records);
    free(keys);
    free(offsets);
}
