package com.example.dynfiletransfer;

import org.apache.commons.io.FileUtils;
import io.netty.bootstrap.Bootstrap;
import io.netty.channel.*;
import io.netty.channel.nio.NioEventLoopGroup;
import io.netty.channel.socket.nio.NioSocketChannel;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import java.util.logging.Logger;

public class DynamicFileTransferFramework {

    private static final Logger logger = Logger.getLogger(DynamicFileTransferFramework.class.getName());
    private static final int MAX_RETRIES = 3;
    private static final long TIMEOUT_MS = 5000; // Example timeout

    private final ConcurrentHashMap<String, FileSegment> fileSegments = new ConcurrentHashMap<>();

    public void processFiles(String directoryPath, String searchPattern) {
        try {
            List<File> files = FileUtils.listFiles(new File(directoryPath), Pattern.compile(searchPattern), true);
            for (File file : files) {
                initializeFileSegment(file);
            }
        } catch (IOException e) {
            logger.severe("Error reading files: " + e.getMessage());
        }
    }

    private void initializeFileSegment(File file) {
        int index = ThreadLocalRandom.current().nextInt(100); // Example range
        FileSegment segment = new FileSegment(file.getName(), index);

        try {
            byte[] data = FileUtils.readFileToByteArray(file);
            if (data.length > 0) {
                segment.setChunkIndices(data.length); // Example logic
                fileSegments.put(file.getName(), segment);
            }
        } catch (IOException e) {
            logger.warning("Error reading file: " + e.getMessage());
            return;
        }

        sendFileSegmentToServer(segment);
    }

    private void sendFileSegmentToServer(FileSegment segment) {
        EventLoopGroup group = new NioEventLoopGroup();

        try {
            Bootstrap b = new Bootstrap();
            b.group(group)
                .channel(NioSocketChannel.class)
                .handler(new ChannelInitializer<Channel>() {
                    @Override
                    protected void initChannel(Channel ch) throws Exception {
                        ch.pipeline().addLast(new FileSegmentEncoder(), new FileSegmentDecoder());
                    }
                });

            ChannelFuture future = null;
            for (int i = 0; i < MAX_RETRIES; i++) {
                try {
                    future = b.connect("host", 22).sync(); // Replace with actual FTS server details
                    if (future.isSuccess()) {
                        future.channel().writeAndFlush(segment);
                        break;
                    }
                } catch (Exception e) {
                    logger.warning("Connection attempt " + (i + 1) + " failed: " + e.getMessage());
                }
            }

            if (future != null && !future.isSuccess()) {
                logger.severe("Failed to send file segment after retries");
            }

        } catch (InterruptedException | IOException e) {
            Thread.currentThread().interrupt();
            logger.severe("Network error: " + e.getMessage());
        } finally {
            group.shutdownGracefully();
        }
    }

    static class FileSegment {
        private final String filename;
        private int chunkIndices;

        public FileSegment(String filename, int index) {
            this.filename = filename;
            this.chunkIndices = index;
        }

        public void setChunkIndices(int size) {
            this.chunkIndices = size; // Simplified logic for demonstration
        }
    }

    static class FileSegmentEncoder extends ChannelOutboundHandlerAdapter {
        @Override
        public void write(ChannelHandlerContext ctx, Object msg, ChannelPromise promise) throws Exception {
            if (msg instanceof FileSegment) {
                FileSegment segment = (FileSegment) msg;
                String data = "Filename: " + segment.filename + ", Indices: " + segment.chunkIndices;
                ctx.writeAndFlush(data.getBytes(StandardCharsets.UTF_8), promise);
            } else {
                super.write(ctx, msg, promise);
            }
        }
    }

    static class FileSegmentDecoder extends ChannelInboundHandlerAdapter {
        @Override
        public void channelRead(ChannelHandlerContext ctx, Object msg) throws Exception {
            if (msg instanceof String) {
                logger.info("Received from server: " + msg);
            } else {
                super.channelRead(ctx, msg);
            }
        }

        @Override
        public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) {
            logger.severe("Exception caught in decoder: " + cause.getMessage());
            ctx.close();
        }
    }

    public static void main(String[] args) {
        DynamicFileTransferFramework framework = new DynamicFileTransferFramework();
        framework.processFiles("/path/to/directory", ".*\\.txt$"); // Example usage
    }
}
