    size_t keys_size = num_keys * sizeof(int);
    size_t records_size = num_records * sizeof(record);

    if (offsets_size + keys_size + records_size > max_memory) return NULL;

    long* offsets = (long*)malloc(offsets_size);
    int* keys = (int*)malloc(keys_size);
    record* records = (record*)malloc(records_size);

    if (!offsets || !keys || !records) {
        free(offsets); 
        free(keys); 
        free(records); 
