#define MAX_THREADS 1000

typedef struct {
    uint32_t size;
    time_t last_modified;
} FILE_METADATA;

typedef struct {
    char *data;
    size_t length;
} FILE_BLOCK_DATA;

typedef enum {
    VALID_TAG,
    INVALID_TAG
} FILE_EVENT_TAG;

typedef struct FileEventNode {
    FILE_EVENT_TAG tag;
    FILE_METADATA metadata;
    FILE_BLOCK_DATA *blocks;
    size_t block_count;
    struct FileEventNode *next;
} FileEventNode;

typedef struct {
    FileEventNode *head;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} FileEventList;

// Memory pool for FILE_BLOCK_DATA
#define MEMORY_POOL_SIZE 1024

void *memory_pool[MEMORY_POOL_SIZE];
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

FILE_BLOCK_DATA* allocate_block(size_t length) {
    pthread_mutex_lock(&pool_lock);

    for (int i = 0; i < MEMORY_POOL_SIZE; ++i) {
        if (memory_pool[i] == NULL) {
            FILE_BLOCK_DATA *block = (FILE_BLOCK_DATA*)malloc(sizeof(FILE_BLOCK_DATA));
            block->data = malloc(length);
            block->length = length;
            memory_pool[i] = block;
            pthread_mutex_unlock(&pool_lock);
            return block;
        }
    }

    pthread_mutex_unlock(&pool_lock);
    return NULL; // Out of pool space
}

void free_block(FILE_BLOCK_DATA *block) {
    pthread_mutex_lock(&pool_lock);

    for (int i = 0; i < MEMORY_POOL_SIZE; ++i) {
        if (memory_pool[i] == block) {
            free(block->data);
            free(block);
            memory_pool[i] = NULL;
            break;
        }
    }

    pthread_mutex_unlock(&pool_lock);
}

// Initialize the list
void init_file_event_list(FileEventList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);
}

// Add a file event to the list
int add_file_event(FileEventList *list, FILE_EVENT_TAG tag, FILE_METADATA metadata, FILE_BLOCK_DATA *blocks, size_t block_count) {
    FileEventNode *node = (FileEventNode*)malloc(sizeof(FileEventNode));
    if (!node) return -1;

    node->tag = tag;
    node->metadata = metadata;
    node->block_count = block_count;

    node->blocks = (FILE_BLOCK_DATA*)malloc(block_count * sizeof(FILE_BLOCK_DATA));
    if (!node->blocks) {
        free(node);
        return -1;
    }

    for (size_t i = 0; i < block_count; ++i) {
        node->blocks[i] = blocks[i];
    }

    pthread_mutex_lock(&list->lock);

    // Handle potential buffer overflow
    if (block_count > MEMORY_POOL_SIZE) {
        pthread_mutex_unlock(&list->lock);
        free(node->blocks);
        free(node);
        return -2; // Buffer overflow error code
    }

    node->next = list->head;
    list->head = node;

    pthread_cond_signal(&list->cond);
    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Example function to flush changes (write-back caching)
void flush_to_disk(FileEventList *list) {
    // Implement write-back logic here
}

// Cleanup the list
void cleanup_file_event_list(FileEventList *list) {
    FileEventNode *current = list->head;
    while (current != NULL) {
        FileEventNode *next = current->next;
        for (size_t i = 0; i < current->block_count; ++i) {
            free_block(&current->blocks[i]);
        }
        free(current->blocks);
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond);
}

// Example usage
