    blocks[1] = (FILE_BLOCK_DATA){.data = "block2", .length = 6};

    add_file_event(&list, VALID_TAG, metadata, blocks, 2);

    // Add more functionality and expand this example as needed

    cleanup_file_event_list(&list);

    return 0;
}
