#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY 1024 * 1024 // Maximum memory limit in bytes

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record* records;
    size_t total_memory_used;
    pthread_mutex_t lock;
} MemoryPool;

// Helper function to calculate hash for seeding
unsigned long hash_parameters(int num_offsets, int num_keys) {
    unsigned long hash = 5381;
    int c;
    char params[128];

    snprintf(params, sizeof(params), "%d_%d", num_offsets, num_keys);

    for (char* p = params; *p != '\0'; p++) {
        c = *p;
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }

    return hash;
}

// Function to initialize random number generator
void seed_random(int num_offsets, int num_keys) {
    unsigned long seed = time(NULL) ^ hash_parameters(num_offsets, num_keys);
    srand(seed);
}

// Memory allocation function with constraints and garbage collection strategy
MemoryPool* allocate_and_initialize_memory(int num_offsets, int num_records, int min_value, int max_value) {
    if (num_offsets < 1 || num_offsets > 5000) return NULL;

    int num_keys = (num_offsets % 3 == 0) ? num_offsets / 3 : num_offsets / 2;

    // Calculate sizes
    size_t offsets_size = num_offsets * sizeof(long);
    size_t keys_size = num_keys * sizeof(int);
    size_t records_size = num_records * sizeof(record);

    size_t total_memory_needed = offsets_size + keys_size + records_size;

    if (total_memory_needed > MAX_MEMORY) return NULL;

    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pthread_mutex_init(&pool->lock, NULL);

    // Allocate memory
    pool->offsets = (long*)malloc(offsets_size);
    pool->keys = (int*)malloc(keys_size);
    pool->records = (record*)malloc(records_size);

    if (!pool->offsets || !pool->keys || !pool->records) {
        free(pool->offsets);
        free(pool->keys);
        free(pool->records);
        free(pool);
        return NULL;
    }

    // Initialize memory
    for (int i = 0; i < num_offsets; ++i) pool->offsets[i] = 0; // Example initialization
    for (int i = 0; i < num_keys; ++i) pool->keys[i] = 0;       // Example initialization

    seed_random(num_offsets, num_keys);

    for (int i = 0; i < num_records; ++i) {
        pool->records[i].value = min_value + rand() % (max_value - min_value + 1);
    }

    pthread_mutex_lock(&pool->lock);
    pool->total_memory_used = total_memory_needed;
    pthread_mutex_unlock(&pool->lock);

    return pool;
}

// Function to free allocated memory
void free_allocated_memory(MemoryPool* pool) {
    if (!pool) return;

    pthread_mutex_lock(&pool->lock);
    free(pool->offsets);
    free(pool->keys);
    free(pool->records);
    pthread_mutex_unlock(&pool->lock);

    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

// Function to get current memory usage
size_t get_memory_usage(MemoryPool* pool) {
    size_t memory_used = 0;
    if (pool) {
        pthread_mutex_lock(&pool->lock);
        memory_used = pool->total_memory_used;
        pthread_mutex_unlock(&pool->lock);
    }
    return memory_used;
}
