    char buffer[4]; // Assuming int is 4 bytes
    for (size_t i = 0; i < num_records; ++i) {
        bytes_read = read(fd, buffer, sizeof(int));
        if (bytes_read == -1 || bytes_read != sizeof(int)) {
            break; // Handle partial reads or errors
        }
        keys[i] = *(int *)buffer;
    }

    // Sort records based on keys
    qsort(records, num_records, sizeof(record), compare_ints);

    // Clean up
    free(offsets);
    log_memory_event("Freed offsets", num_records * sizeof(long));
    free(keys);
    log_memory_event("Freed keys", num_records * sizeof(int));
    free(records);
    log_memory_event("Freed records", num_records * sizeof(record));

    pthread_mutex_unlock(&mutex);
}
