#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define INITIAL_CAPACITY 16

typedef struct {
    int cellId;
    time_t timeStamp;
    float throughput;
} NetworkPerformanceMetrics;

typedef struct Node {
    NetworkPerformanceMetrics data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

typedef struct {
    size_t capacity;
    size_t size;
    NetworkPerformanceMetrics** buckets;
    pthread_mutex_t lock;
} HashTable;

void initializeLinkedList(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

Node* createNode(NetworkPerformanceMetrics data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void insertIntoLinkedList(LinkedList* list, NetworkPerformanceMetrics data) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = createNode(data);
    if (newNode) {
        newNode->next = list->head;
        list->head = newNode;
    }
    pthread_mutex_unlock(&list->lock);
}

void freeLinkedList(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
}

void initializeHashTable(HashTable* table, size_t capacity) {
    table->capacity = capacity;
    table->size = 0;
    table->buckets = (NetworkPerformanceMetrics**)calloc(capacity, sizeof(NetworkPerformanceMetrics*));
    if (!table->buckets) exit(EXIT_FAILURE);
    pthread_mutex_init(&table->lock, NULL);
}

unsigned long hashFunction(int cellId, size_t capacity) {
    return (unsigned long)(cellId % capacity);
}

void insertIntoHashTable(HashTable* table, NetworkPerformanceMetrics data) {
    unsigned long index = hashFunction(data.cellId, table->capacity);
    pthread_mutex_lock(&table->lock);
    if (!table->buckets[index]) {
        table->buckets[index] = (NetworkPerformanceMetrics*)malloc(sizeof(NetworkPerformanceMetrics));
        if (!table->buckets[index]) exit(EXIT_FAILURE);
        memcpy(table->buckets[index], &data, sizeof(NetworkPerformanceMetrics));
    } else {
        NetworkPerformanceMetrics* current = table->buckets[index];
        while (current->next) {
            current = current->next;
        }
        current->next = (NetworkPerformanceMetrics*)malloc(sizeof(NetworkPerformanceMetrics));
        if (!current->next) exit(EXIT_FAILURE);
        memcpy(current->next, &data, sizeof(NetworkPerformanceMetrics));
        current->next->next = NULL;
    }
    table->size++;
    pthread_mutex_unlock(&table->lock);
}

void freeHashTable(HashTable* table) {
    pthread_mutex_lock(&table->lock);
    for (size_t i = 0; i < table->capacity; ++i) {
        NetworkPerformanceMetrics* current = table->buckets[i];
        while (current) {
            NetworkPerformanceMetrics* temp = current;
            current = current->next;
            free(temp);
        }
        table->buckets[i] = NULL;
    }
    free(table->buckets);
    pthread_mutex_unlock(&table->lock);
}

void resizeHashTable(HashTable* table, size_t newCapacity) {
    HashTable newTable;
    initializeHashTable(&newTable, newCapacity);

    for (size_t i = 0; i < table->capacity; ++i) {
        NetworkPerformanceMetrics* current = table->buckets[i];
        while (current) {
            insertIntoHashTable(&newTable, *current);
            current = current->next;
        }
    }

    freeHashTable(table);

    memcpy(table, &newTable, sizeof(HashTable));
}

void manageNetworkMetrics(int cellId, float minThroughput, float maxThroughput, unsigned int seed) {
    srand(seed);
    LinkedList metricsList;
    HashTable metricsTable;

    initializeLinkedList(&metricsList);
    initializeHashTable(&metricsTable, INITIAL_CAPACITY);

    for (int i = 0; i < 10000; ++i) { // Simulate large dataset
        NetworkPerformanceMetrics data;
        data.cellId = cellId + i;
        data.timeStamp = time(NULL);
        data.throughput = minThroughput + ((float)(rand() % 1000) / 1000.0f) * (maxThroughput - minThroughput);

        insertIntoLinkedList(&metricsList, data);
        insertIntoHashTable(&metricsTable, data);

        if (metricsTable.size > metricsTable.capacity * 0.75) {
            resizeHashTable(&metricsTable, metricsTable.capacity * 2);
        }
    }

    // Cleanup
    freeLinkedList(&metricsList);
    freeHashTable(&metricsTable);
}

int main() {
    manageNetworkMetrics(1, 10.0f, 100.0f, time(NULL));
    return 0;
}
