    size_t capacity;
} EventList;

// Function prototypes
EventList* create_event_list(size_t initial_capacity);
int add_event(EventList* list, NETWORK_EVENT event);
NETWORK_EVENT get_event(EventList* list, size_t index);
void resize_list(EventList* list);
void log_event_creation(const NETWORK_EVENT* event);
void export_to_binary_file(const char* filename, EventList* list);
void compress_data(uint8_t** data, size_t* length);
void checkpoint_state(EventList* list);

// Create a new dynamic list with initial capacity
EventList* create_event_list(size_t initial_capacity) {
    EventList* list = malloc(sizeof(EventList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);
    list->size = 0;
    list->capacity = initial_capacity;

    return list;
}

// Add a new event to the list
int add_event(EventList* list, NETWORK_EVENT event) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        resize_list(list);
    }

    Node* node = malloc(sizeof(Node));
    if (!node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    memcpy(&node->event, &event, sizeof(NETWORK_EVENT));
    node->next = list->head;
    list->head = node;
    list->size++;

    log_event_creation(&event);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Resize the event list to accommodate more events
void resize_list(EventList* list) {
    // Double the capacity
    list->capacity *= 2;
}

// Retrieve an event by index (for internal use)
NETWORK_EVENT get_event(EventList* list, size_t index) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    for (size_t i = 0; i < index && current != NULL; ++i) {
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return (NETWORK_EVENT){0};
    }

    NETWORK_EVENT event = current->event;
    pthread_mutex_unlock(&list->lock);
    return event;
}

// Log creation of each network event
void log_event_creation(const NETWORK_EVENT* event) {
    printf("Event created: TAG=%d, Timestamp=%ld\n", event->MAC_EVENT_TAG, (long)event->timestamp);
}

// Export the list to a binary file with optional compression
void export_to_binary_file(const char* filename, EventList* list) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        fwrite(&current->event.MAC_EVENT_TAG, sizeof(current->event.MAC_EVENT_TAG), 1, file);
        fwrite(&current->event.timestamp, sizeof(current->event.timestamp), 1, file);
        for (size_t i = 0; i < current->event.frame_count; ++i) {
            fwrite(&current->event.frames[i].length, sizeof(current->event.frames[i].length), 1, file);
            fwrite(current->event.frames[i].data, current->event.frames[i].length, 1, file);
        }
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);

    fclose(file);
}

// Compress data
void compress_data(uint8_t** data, size_t* length) {
    // Placeholder compression logic: real implementation needed
}

// Periodic checkpoint state
void checkpoint_state(EventList* list) {
    // Save current list state to a file or other persistent storage
}

int main() {
    EventList* event_list = create_event_list(10);

    NETWORK_EVENT event = { .MAC_EVENT_TAG = 12345, .timestamp = time(NULL), .frame_count = 1 };
    MAC_FRAME_DATA frame = { .data = (uint8_t*)"Sample data", .length = strlen("Sample data") };
    memcpy(event.frames, &frame, sizeof(frame));

    add_event(event_list, event);
    export_to_binary_file("events.bin", event_list);

    // Clean up
    free(event_list);

    return 0;
}
