    SensorData data;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t lock;
    size_t pool_size;
    size_t used_memory;
    unsigned char *memory_pool;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pthread_mutex_init(&pool->lock, NULL);
    pool->head = NULL;
    pool->pool_size = initial_size;
    pool->used_memory = 0;
    pool->memory_pool = (unsigned char*)calloc(initial_size, sizeof(unsigned char));

    return pool;
}

void* allocate_from_pool(MemoryPool *pool, size_t size) {
    pthread_mutex_lock(&pool->lock);

    if ((size + pool->used_memory) > pool->pool_size) {
        // Resize the memory pool
        unsigned char *new_pool = (unsigned char*)realloc(pool->memory_pool, pool->pool_size * 2);
        if (!new_pool) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        pool->memory_pool = new_pool;
        pool->pool_size *= 2;
    }

    void *ptr = &pool->memory_pool[pool->used_memory];
    pool->used_memory += size;

    pthread_mutex_unlock(&pool->lock);

    return ptr;
}

void deallocate_from_pool(MemoryPool *pool, void *ptr) {
