    SensorData *data = (SensorData*)allocate_from_pool(pool, sizeof(SensorData));
    if (!data) return NULL;

    data->timestamp = timestamp;
    data->sensor_id = sensor_id;
    data->readings = allocate_from_pool(pool, readings_size);
    if (!data->readings) {
        deallocate_from_pool(pool, data);
        return NULL;
    }

    memcpy(data->readings, readings, readings_size);
    data->readings_size = readings_size;

    Node *node = (Node*)allocate_from_pool(pool, sizeof(Node));
    if (!node) {
        deallocate_from_pool(pool, data->readings);
        deallocate_from_pool(pool, data);
        return NULL;
    }

    node->data = *data;
    node->next = pool->head;
    pthread_mutex_lock(&pool->lock);
    pool->head = node;
    pthread_mutex_unlock(&pool->lock);

    return data;
}

void free_memory_pool(MemoryPool *pool) {
    Node *current = pool->head;
    while (current != NULL) {
        Node *next = current->next;
        deallocate_from_pool(pool, &current->data);
        deallocate_from_pool(pool, current);
        current = next;
    }
    pthread_mutex_destroy(&pool->lock);
    free(pool->memory_pool);
    free(pool);
}

// Additional functions for resizing, error handling, logging, and communication can be added here

