// Structure Definitions
typedef struct {
    double value;
    uint64_t timestamp;
    const char* description;
} measurement;

// Custom Memory Pool
#define POOL_SIZE 1024 * 1024 // 1 MB pool for example

char memory_pool[POOL_SIZE];
size_t pool_offset = 0;

void* custom_alloc(size_t size) {
    if (pool_offset + size > POOL_SIZE) return NULL;
    void* ptr = &memory_pool[pool_offset];
    pool_offset += size;
    return ptr;
}

// Data Structure for Records
typedef struct measurement_node {
    measurement data;
    struct measurement_node* left;
    struct measurement_node* right;
} measurement_node;

measurement_node* root = NULL;
pthread_mutex_t tree_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to insert a record into the tree
void insert_measurement(measurement_node** node, measurement data) {
    if (*node == NULL) {
        *node = (measurement_node*)custom_alloc(sizeof(measurement_node));
        if (*node == NULL) return;
        (*node)->data = data;
        (*node)->left = (*node)->right = NULL;
    } else if (data.timestamp < (*node)->data.timestamp) {
        insert_measurement(&(*node)->left, data);
    } else {
        insert_measurement(&(*node)->right, data);
    }
}

// Initialization Function
void initialize_data_structures(float* float_array, char* status_array, measurement* measurements,
                                size_t num_records, const char* log_level) {
    if (float_array == NULL || status_array == NULL || measurements == NULL) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

