    for (size_t i = 0; i < num_records; ++i) {
        float_array[i] = 0.0f; // Default initialization
        status_array[i] = 'N'; // Default status indicator

        measurement data = {0.0, 0, "Default"};
        measurements[i] = data;

        insert_measurement(&root, data);
    }
    pthread_mutex_unlock(&tree_mutex);

    // Log Initialization
    time_t now = time(NULL);
    char* timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    if (strcmp(log_level, "DEBUG") == 0 || strcmp(log_level, "INFO") == 0) {
        printf("[%s] Initialized %zu records\n", timestamp, num_records);
    }
}

// Cleanup Function
void cleanup_data_structures(float* float_array, char* status_array, measurement* measurements,
                             size_t num_records) {
    free(float_array);
    free(status_array);
    free(measurements);

    // Free memory pool
