    char* timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0';

    printf("[%s] Cleaned up resources\n", timestamp);
}

int main(int argc, char** argv) {
    size_t num_records = 100; // Example record count
    float* float_array = (float*)malloc(num_records * sizeof(float));
    char* status_array = (char*)malloc(num_records * sizeof(char));
    measurement* measurements = (measurement*)custom_alloc(num_records * sizeof(measurement));

    if (!float_array || !status_array || !measurements) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    initialize_data_structures(float_array, status_array, measurements, num_records, "INFO");

    cleanup_data_structures(float_array, status_array, measurements, num_records);

    return 0;
}
