Pipeline_Configuration* init_packet_processing_pipeline(size_t num_stages, const int protocol_types[], 
                                                        const size_t buffer_sizes[], const int priorities[]) {

    if (num_stages == 0 || !protocol_types || !buffer_sizes || !priorities) {
        log_message("Invalid configuration parameters.");
        return NULL;
    }

    Pipeline_Configuration *config = malloc(sizeof(Pipeline_Configuration));
    if (!config) {
        log_message("Failed to allocate memory for pipeline configuration.");
        return NULL;
    }

    config->processors = malloc(num_stages * sizeof(Packet_Processor_T*));
    if (!config->processors) {
        free(config);
        log_message("Failed to allocate memory for processors.");
        return NULL;
    }

    pthread_mutex_init(&config->lock, NULL);
    config->num_stages = num_stages;

    for (size_t i = 0; i < num_stages; ++i) {
        Packet_Processor_T *processor = malloc(sizeof(Packet_Processor_T));
        if (!processor) {
            log_message("Failed to allocate memory for a processor.");

            // Free previously allocated processors
            while (--i >= 0)
                free(config->processors[i]);
            free(config->processors);
            pthread_mutex_destroy(&config->lock);
            free(config);

            return NULL;
        }

        processor->protocol_type = protocol_types[i];
        processor->buffer_size = buffer_sizes[i];
        processor->priority = priorities[i];

        // Placeholder for shared resource setup
        processor->shared_resource = NULL; 

        config->processors[i] = processor;

        log_message("Initialized processing stage.");
    }

    return config;
}

void destroy_packet_processing_pipeline(Pipeline_Configuration *config) {
    if (!config) return;

    for (size_t i = 0; i < config->num_stages; ++i) {
        free(config->processors[i]);
    }

    free(config->processors);
    pthread_mutex_destroy(&config->lock);
    free(config);
}
