typedef struct Node {
    unsigned long key;
    void *value;
    struct Node *next;
} HashNode;

typedef struct {
    HashNode **buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} ConcurrentHashTable;

typedef struct LRUCache {
    size_t capacity;
    int count;
    ConcurrentHashTable *hashTable;
    pthread_mutex_t lock;
} LRUCache;

// Function prototypes
void load_config(const char *filename, int *N, unsigned int *seed);
ConcurrentHashTable* create_hash_table(size_t initial_capacity);
void hash_table_insert(ConcurrentHashTable *table, unsigned long key, void *value);
void* hash_table_get(ConcurrentHashTable *table, unsigned long key);
LRUCache* create_lru_cache(size_t capacity);
int lru_cache_put(LRUCache *cache, unsigned long key, void *value);
void* lru_cache_get(LRUCache *cache, unsigned long key);
NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(int N, unsigned int seed);
void log_creation(const char *filename, const NFAPI_CRC_INDICATION_PDU_T *pdu);
int export_to_binary_file(const char *filename, NFAPI_CRC_INDICATION_PDU_T *pdus, size_t count);
void encrypt_and_write(FILE *file, void *data, size_t size, const char *key);

// Implementations

ConcurrentHashTable* create_hash_table(size_t initial_capacity) {
    ConcurrentHashTable *table = malloc(sizeof(ConcurrentHashTable));
    if (!table) return NULL;

    table->buckets = calloc(initial_capacity, sizeof(HashNode*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }
    table->capacity = initial_capacity;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void hash_table_insert(ConcurrentHashTable *table, unsigned long key, void *value) {
    size_t index = key % table->capacity;
    HashNode *new_node = malloc(sizeof(HashNode));
    if (!new_node) return;

    new_node->key = key;
    new_node->value = value;
    new_node->next = NULL;

    pthread_mutex_lock(&table->lock);
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;
    table->size++;
    pthread_mutex_unlock(&table->lock);
}

void* hash_table_get(ConcurrentHashTable *table, unsigned long key) {
    size_t index = key % table->capacity;

    pthread_mutex_lock(&table->lock);
    HashNode *node = table->buckets[index];
    while (node) {
        if (node->key == key) {
            pthread_mutex_unlock(&table->lock);
            return node->value;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&table->lock);

    return NULL;
}

LRUCache* create_lru_cache(size_t capacity) {
    LRUCache *cache = malloc(sizeof(LRUCache));
    if (!cache) return NULL;

    cache->capacity = capacity;
    cache->count = 0;
    cache->hashTable = create_hash_table(capacity);
    pthread_mutex_init(&cache->lock, NULL);

    return cache;
}

int lru_cache_put(LRUCache *cache, unsigned long key, void *value) {
    if (cache->count >= cache->capacity) {
        // Implement LRU eviction logic
    }

    hash_table_insert(cache->hashTable, key, value);
    pthread_mutex_lock(&cache->lock);
    cache->count++;
    pthread_mutex_unlock(&cache->lock);

    return 0;
}

void* lru_cache_get(LRUCache *cache, unsigned long key) {
    pthread_mutex_lock(&cache->lock);
    void *value = hash_table_get(cache->hashTable, key);
    pthread_mutex_unlock(&cache->lock);

    return value;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(int N, unsigned int seed) {
    srand(seed);
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) return NULL;

