        pdus[i].RX_UE_INFORMATION_TAG = rand() % 100;
        pdus[i].RNTI = rand();
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 10;
        pdus[i].CRCFLAG = rand() % 2;

        log_creation("log.txt", &pdus[i]);
    }

    return pdus;
}

void log_creation(const char *filename, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    FILE *file = fopen(filename, "a");
    if (file) {
        fprintf(file, "RNTI: %u, CRCFLAG: %d\n", pdu->RNTI, pdu->CRCFLAG);
