#define MAX_PROFILES 100000
#define CLEANUP_DAYS 30

typedef struct {
    char *id;
    time_t timestamp;
    char status[10];
    char *name;
} UserProfile;

typedef struct {
    UserProfile *profiles[MAX_PROFILES];
    size_t count;
    pthread_mutex_t lock;
} ProfileList;

UserProfile* create_profile(const char *id, const char *status, const char *name) {
    if (!id || !status || !name) return NULL;

    UserProfile *profile = malloc(sizeof(UserProfile));
    if (!profile) return NULL;

    profile->id = strdup(id);
    profile->timestamp = time(NULL);
    strncpy(profile->status, status, sizeof(profile->status) - 1);

    size_t name_len = strlen(name) + 1;
    profile->name = malloc(name_len);
    if (!profile->name) {
        free(profile->id);
        free(profile);
        return NULL;
    }
    strcpy(profile->name, name);

    return profile;
}

void destroy_profile(UserProfile *profile) {
    if (profile) {
        free(profile->id);
        free(profile->name);
        free(profile);
    }
}

int append_profile(ProfileList *list, UserProfile *profile) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_PROFILES) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }

    list->profiles[list->count++] = profile;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

void cleanup_profiles(ProfileList *list, int days) {
    time_t now = time(NULL);
    time_t cutoff = now - (days * 24 * 60 * 60);

    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->profiles[i]->timestamp < cutoff) {
            destroy_profile(list->profiles[i]);
            memmove(&list->profiles[i], &list->profiles[i + 1],
                    (list->count - i - 1) * sizeof(UserProfile*));
            --list->count;
            --i; // Stay at current index after removing
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void log_message(const char *message) {
    FILE *log_file = fopen("app.log", "a");
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "[%s] %s\n", ctime(&now), message);
        fclose(log_file);
    }
}

void rotate_logs() {
    char new_log[256];
    snprintf(new_log, sizeof(new_log), "app_%ld.log", time(NULL) / (24 * 60 * 60));
    rename("app.log", new_log);

    FILE *log_file = fopen("app.log", "w");
    if (!log_file) {
        log_message("Failed to rotate logs.");
    }
    fclose(log_file);
}

void* periodic_cleanup(void* arg) {
    ProfileList *list = (ProfileList*)arg;
    while (1) {
        sleep(86400); // Run once per day
        int days = CLEANUP_DAYS; // This would be dynamically set from environment variables
        cleanup_profiles(list, days);
        rotate_logs();
    }
}

void init_profile_list(ProfileList *list) {
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    pthread_t cleanup_thread;
    if (pthread_create(&cleanup_thread, NULL, periodic_cleanup, list)) {
        log_message("Failed to start cleanup thread.");
    }
}

