// Define a record structure
typedef struct Record {
    int value;
    struct Record* next;
} Record;

// Thread-safe linked list to manage records
typedef struct {
    Record* head;
    pthread_mutex_t lock;
} RecordList;

// Function prototypes
void initialize_list(RecordList* list);
void insert_record(RecordList* list, int value);
int get_random_value(int min, int max, unsigned int seed);
void free_records(RecordList* list);
void log_performance_metrics(const char* message);

// Initialize the linked list with a mutex for thread safety
void initialize_list(RecordList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Insert a new record into the list
void insert_record(RecordList* list, int value) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    new_record->value = value;
    new_record->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_record->next = list->head;
    list->head = new_record;
    pthread_mutex_unlock(&list->lock);

    log_performance_metrics("Inserted record");
}

// Generate a random integer within a specified range using a seed
int get_random_value(int min, int max, unsigned int seed) {
    srand(seed ^ time(NULL));
    return rand() % (max - min + 1) + min;
}

// Free all records in the list
void free_records(RecordList* list) {
    pthread_mutex_lock(&list->lock);
    Record* current = list->head;
    while (current) {
        Record* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
}

// Log performance metrics using a third-party library
void log_performance_metrics(const char* message) {
    // Replace with actual logging implementation
    printf("Log: %s\n", message);
}

// Example usage
int main() {
    RecordList list;
    initialize_list(&list);

    unsigned int seed = 12345;  // User-provided seed for reproducibility

    for (int i = 0; i < 10; ++i) {
        int value = get_random_value(1, 100, seed + i);
        insert_record(&list, value);
    }

    free_records(&list);

    return 0;
}
