} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    int valid_count;
    int invalid_count;
    pthread_mutex_t mutex;
} CRCList;

void init_list(CRCList* list) {
    list->head = NULL;
    list->valid_count = 0;
    list->invalid_count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for node");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void add_structure(CRCList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);

    Node* new_node = create_node(data);
    if (new_node->data.crc_indication_rel8_tag.CRCFLAG) {
        list->valid_count++;
    } else {
        list->invalid_count++;
    }

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->mutex);
}

void update_structure(CRCList* list, RNTI rnti, NFAPI_CRC_INDICATION_PDU_T updated_data) {
    pthread_mutex_lock(&list->mutex);

    Node* current = list->head;
    while (current) {
        if (current->data.rnti == rnti) {
            bool was_valid = current->data.crc_indication_rel8_tag.CRCFLAG;

            current->data = updated_data;
            if (updated_data.crc_indication_rel8_tag.CRCFLAG && !was_valid) {
                list->valid_count++;
                list->invalid_count--;
            } else if (!updated_data.crc_indication_rel8_tag.CRCFLAG && was_valid) {
                list->invalid_count++;
                list->valid_count--;
            }
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
}

void remove_structure(CRCList* list, RNTI rnti) {
    pthread_mutex_lock(&list->mutex);

    Node *current = list->head, *prev = NULL;

    while (current) {
        if (current->data.rnti == rnti) {
            if (current->data.crc_indication_rel8_tag.CRCFLAG) {
                list->valid_count--;
            } else {
                list->invalid_count--;
            }

            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
}

void validate_crc_flags(CRCList* list) {
    pthread_mutex_lock(&list->mutex);

    Node* current = list->head;
    int temp_valid_count = 0, temp_invalid_count = 0;

    while (current) {
        if (current->data.crc_indication_rel8_tag.CRCFLAG) {
            temp_valid_count++;
        } else {
            temp_invalid_count++;
        }
        current = current->next;
    }

    list->valid_count = temp_valid_count;
    list->invalid_count = temp_invalid_count;

    pthread_mutex_unlock(&list->mutex);
}

void print_statistics(CRCList* list) {
    pthread_mutex_lock(&list->mutex);

    printf("Valid CRCFLAGS: %d\n", list->valid_count);
    printf("Invalid CRCFLAGS: %d\n", list->invalid_count);

    pthread_mutex_unlock(&list->mutex);
}

void free_list(CRCList* list) {
    pthread_mutex_lock(&list->mutex);

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;

    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

// Example usage
int main() {
    CRCList list;
    init_list(&list);

    // Add, update, remove operations here

    print_statistics(&list);
    free_list(&list);

    return 0;
}
