#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_EVENTS 1000
#define MAX_SAMPLE_SIZE 1024

typedef struct {
    int sensor_id;
    time_t timestamp;
    void *data; // Pointer to a dynamically allocated memory pool for data samples
    size_t data_size;
} SensorEvent;

typedef struct MemoryPool {
    size_t block_size;
    size_t total_blocks;
    void **blocks;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->total_blocks = num_blocks;
    pool->blocks = malloc(num_blocks * sizeof(void *));
    if (!pool->blocks) {
        free(pool);
        return NULL;
    }

    for (size_t i = 0; i < num_blocks; ++i) {
        pool->blocks[i] = malloc(block_size);
        if (!pool->blocks[i]) {
            // Free previously allocated blocks on failure
            while (--i) free(pool->blocks[i]);
            free(pool->blocks);
            free(pool);
            return NULL;
        }
    }

    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_memory_pool(MemoryPool *pool) {
    if (pool) {
        for (size_t i = 0; i < pool->total_blocks; ++i)
            free(pool->blocks[i]);
        free(pool->blocks);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

void* allocate_from_pool(MemoryPool *pool, size_t size) {
    if (size > pool->block_size) return NULL;

    void *allocated = NULL;
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->total_blocks; ++i) {
        if (!pool->blocks[i]) {
            allocated = pool->blocks[i];
            break;
        }
    }

    pthread_mutex_unlock(&pool->lock);

    return allocated;
}

void deallocate_to_pool(MemoryPool *pool, void *ptr) {
    if (!ptr) return;

    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->total_blocks; ++i) {
        if (pool->blocks[i] == ptr) {
            pool->blocks[i] = NULL;
            break;
        }
    }

    pthread_mutex_unlock(&pool->lock);
}

typedef struct SensorEventCollection {
    SensorEvent *events[MAX_EVENTS];
    size_t count;
    MemoryPool *memory_pool;
    pthread_rwlock_t rw_lock;
} SensorEventCollection;

SensorEventCollection* create_sensor_event_collection(size_t pool_block_size, size_t num_blocks) {
    SensorEventCollection *collection = malloc(sizeof(SensorEventCollection));
    if (!collection) return NULL;

    collection->count = 0;
    memset(collection->events, 0, sizeof(SensorEvent*) * MAX_EVENTS);
    collection->memory_pool = create_memory_pool(pool_block_size, num_blocks);

    pthread_rwlock_init(&collection->rw_lock, NULL);
    return collection;
}

void destroy_sensor_event_collection(SensorEventCollection *collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->count; ++i) {
        deallocate_to_pool(collection->memory_pool, collection->events[i]->data);
        free(collection->events[i]);
    }

    pthread_rwlock_destroy(&collection->rw_lock);
    destroy_memory_pool(collection->memory_pool);
    free(collection);
}

int add_sensor_event(SensorEventCollection *collection, int sensor_id, const void *sample_data, size_t data_size) {
    if (!collection || data_size > MAX_SAMPLE_SIZE) return -1;

    pthread_rwlock_wrlock(&collection->rw_lock);

    if (collection->count >= MAX_EVENTS) {
        pthread_rwlock_unlock(&collection->rw_lock);
        return -1;
    }

    SensorEvent *event = malloc(sizeof(SensorEvent));
    if (!event) {
        pthread_rwlock_unlock(&collection->rw_lock);
        return -1;
    }

    event->sensor_id = sensor_id;
    event->timestamp = time(NULL);
    event->data_size = data_size;

    void *allocated_data = allocate_from_pool(collection->memory_pool, data_size);
    if (!allocated_data) {
        free(event);
        pthread_rwlock_unlock(&collection->rw_lock);
        return -1;
    }

    memcpy(allocated_data, sample_data, data_size);
    event->data = allocated_data;

    collection->events[collection->count++] = event;

    pthread_rwlock_unlock(&collection->rw_lock);

    // Example: Log success or error based on operations
    printf("Added sensor event for ID %d\n", sensor_id);

    return 0;
}

void* read_sensor_event(void *arg) {
    SensorEventCollection *collection = (SensorEventCollection *)arg;

    pthread_rwlock_rdlock(&collection->rw_lock);

    // Process events: Example logic for reading
    for (size_t i = 0; i < collection->count; ++i) {
        printf("Reading event from sensor ID %d at time %ld\n", 
               collection->events[i]->sensor_id, 
               collection->events[i]->timestamp);
    }

    pthread_rwlock_unlock(&collection->rw_lock);

    return NULL;
}

// Example main function
int main() {
    SensorEventCollection *collection = create_sensor_event_collection(256, 500);

    int sensor_data[] = {1, 2, 3, 4};
    add_sensor_event(collection, 101, sensor_data, sizeof(sensor_data));

    pthread_t reader_thread;
    pthread_create(&reader_thread, NULL, read_sensor_event, collection);
    pthread_join(reader_thread, NULL);

    destroy_sensor_event_collection(collection);

    return 0;
}
