    if (!new_list) {
        perror("Failed to resize RRC list");
        exit(EXIT_FAILURE);
    }
    list->pdu_list = new_list;
    list->capacity = new_capacity;
}

// Add event function for NFAPI_RRC_PDU_T
void add_file_event(NFAPI_RRC_PDU_T *pdu, FILE_EVENT_TAG *event) {
    pthread_mutex_lock(&pdu->mutex);
    if (pdu->event_count >= 10) { // Simplified overflow check
        log_transaction("Buffer Overflow Detected", pdu->transaction_id);
        pthread_mutex_unlock(&pdu->mutex);
        return;
    }
    // Allocate and set event data
    FILE_EVENT_TAG *new_events = realloc(pdu->file_events, (pdu->event_count + 1) * sizeof(FILE_EVENT_TAG));
    if (!new_events) {
        perror("Failed to allocate memory for file events");
        pthread_mutex_unlock(&pdu->mutex);
        exit(EXIT_FAILURE);
    }
    pdu->file_events = new_events;
    memcpy(&pdu->file_events[pdu->event_count], event, sizeof(FILE_EVENT_TAG));
    pdu->event_count++;
    log_transaction("File Event Added", pdu->transaction_id); // Logging the operation
    pthread_mutex_unlock(&pdu->mutex);
}

// Initialize LRUCache
void init_lru_cache(LRUCACHE *cache) {
    cache->head = NULL;
    cache->tail = NULL;
    cache->size = 0;
    pthread_mutex_init(&cache->cache_mutex, NULL);
}

// Add to LRU Cache
void lru_cache_add(LRUCACHE *cache, FILE_EVENT_TAG *event_tag) {
    pthread_mutex_lock(&cache->cache_mutex);

    // Remove from existing position if it exists
    CACHE_NODE **curr = &cache->head;
    while (*curr && (*curr)->event_tag != event_tag) {
        curr = &(*curr)->next;
    }
    if (*curr) {
        *curr = (*curr)->next; 
        if (cache->tail == *curr) {
            cache->tail = (*curr)->prev;
        }
        if (*curr) {
            (*curr)->prev = NULL;
        }
    }

    // Add to front of the list
    CACHE_NODE *new_node = malloc(sizeof(CACHE_NODE));
    new_node->event_tag = event_tag;
    new_node->next = cache->head;
    new_node->prev = NULL;

    if (cache->head) {
        cache->head->prev = new_node;
    }
    cache->head = new_node;

    if (!cache->tail) {
        cache->tail = new_node;
    }

    // Evict least recently used if cache is full
    if (++(cache->size) > CACHE_SIZE) {
        CACHE_NODE *evicted = cache->tail;
        cache->tail = evicted->prev;
        if (cache->tail) {
            cache->tail->next = NULL;
        }
        free(evicted);
        --(cache->size);
    }

    pthread_mutex_unlock(&cache->cache_mutex);
}

// JavaScript function to recursively traverse the DOM
function findElementsWithSelector(root, selector, testFn) {
    const elements = [];
    function traverse(node) {
        if (node.nodeType === 1 && testFn(node)) { // Check for element node and apply test function
            elements.push(node);
        }
        Array.from(node.childNodes).forEach(traverse);
    }
    traverse(root);
    return elements.filter(el => el.matches(selector));
}
