#include <unistd.h>
#include "jpeg_to_pdf_converter.h" // External library for JPEG to PDF conversion

#define MAX_ENTRIES 1000000
#define INITIAL_SIZE 1024

typedef struct {
    int rrc_message;
    int transaction_id;
    int sequence_number;
} NFAPI_RRC_PDU_T;

typedef struct Entry {
    NFAPI_RRC_PDU_T pdu;
    struct Entry *next;
} Entry;

typedef struct {
    Entry *head[MAX_ENTRIES];
    pthread_mutex_t mutexes[MAX_ENTRIES];
} NFAPI_RRC_Manager;

void init_manager(NFAPI_RRC_Manager *manager) {
    for (int i = 0; i < MAX_ENTRIES; ++i) {
        manager->head[i] = NULL;
        pthread_mutex_init(&manager->mutexes[i], NULL);
    }
}

Entry* create_entry(const NFAPI_RRC_PDU_T *pdu) {
    Entry *entry = malloc(sizeof(Entry));
    if (entry) {
        entry->pdu = *pdu;
        entry->next = NULL;
    }
    return entry;
}

void add_entry(NFAPI_RRC_Manager *manager, const NFAPI_RRC_PDU_T *pdu) {
    int index = pdu->transaction_id % MAX_ENTRIES;
    pthread_mutex_lock(&manager->mutexes[index]);

    Entry *entry = create_entry(pdu);
    if (!manager->head[index]) {
        manager->head[index] = entry;
    } else {
        Entry *current = manager->head[index];
        while (current->next) {
            current = current->next;
        }
        current->next = entry;
    }

    pthread_mutex_unlock(&manager->mutexes[index]);
}

NFAPI_RRC_PDU_T* get_latest_message(NFAPI_RRC_Manager *manager, int transaction_id) {
    int index = transaction_id % MAX_ENTRIES;
    pthread_mutex_lock(&manager->mutexes[index]);

    Entry *current = manager->head[index];
    NFAPI_RRC_PDU_T *latest_pdu = NULL;

    while (current) {
        if (!latest_pdu || current->pdu.sequence_number > latest_pdu->sequence_number) {
            latest_pdu = &current->pdu;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->mutexes[index]);
    return latest_pdu;
}

typedef struct {
    int *int_array;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} DynamicIntArray;

void init_dynamic_int_array(DynamicIntArray *array) {
    array->capacity = INITIAL_SIZE;
    array->count = 0;
    array->int_array = malloc(array->capacity * sizeof(int));
    pthread_mutex_init(&array->mutex, NULL);
}

void add_to_dynamic_int_array(DynamicIntArray *array, int value) {
    pthread_mutex_lock(&array->mutex);

    if (array->count == array->capacity) {
        array->capacity *= 2;
        array->int_array = realloc(array->int_array, array->capacity * sizeof(int));
    }
    array->int_array[array->count++] = value;

    pthread_mutex_unlock(&array->mutex);
}

int find_largest_in_dynamic_int_array(DynamicIntArray *array) {
    pthread_mutex_lock(&array->mutex);

    int largest = INT_MIN;
    for (size_t i = 0; i < array->count; ++i) {
        if (array->int_array[i] > largest) {
            largest = array->int_array[i];
        }
    }

    pthread_mutex_unlock(&array->mutex);
    return largest;
}

typedef struct {
    time_t timestamp;
    int unique_id;
} EventRecord;

void processMediaAndAnalyzeEvents() {
    DynamicIntArray int_array;
    init_dynamic_int_array(&int_array);

    printf("Enter integers (end with EOF):\n");
    int value;
    while (scanf("%d", &value) == 1) {
        add_to_dynamic_int_array(&int_array, value);
    }

    int largest = find_largest_in_dynamic_int_array(&int_array);
    printf("Largest integer: %d\n", largest);

    FILE *jpeg_file = fopen("input.jpg", "rb");
    if (!jpeg_file) {
        perror("Failed to open JPEG file");
        return 1;
    }

    int retry_count = 3;
    while (retry_count--) {
        if (convert_jpeg_to_pdf(jpeg_file, "output.pdf") == 0) {
            break;
        }
        fprintf(stderr, "Conversion failed, retrying...\n");
        sleep(1);
    }

    fclose(jpeg_file);

    free(int_array.int_array);
    pthread_mutex_destroy(&int_array.mutex);

    return 0; // Success
}

int main() {
    NFAPI_RRC_Manager manager;
    init_manager(&manager);

    int result = processMediaAndAnalyzeEvents();
    if (result != 0) {
        fprintf(stderr, "Error processing media and analyzing events\n");
        return result;
    }

    return 0;
}
