#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>

#define MAX_RNTIs 1000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint32_t CRCFLAG; // Random value
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct hash_node {
    uint16_t rnti;
    struct hash_node *next;
} hash_node_t;

#define HASH_TABLE_SIZE 1024

hash_node_t* hash_table[HASH_TABLE_SIZE];
pthread_mutex_t table_lock = PTHREAD_MUTEX_INITIALIZER;

unsigned int hash_function(uint16_t rnti) {
    return rnti % HASH_TABLE_SIZE;
}

int is_rnti_present(uint16_t rnti) {
    unsigned int index = hash_function(rnti);
    pthread_mutex_lock(&table_lock);

    hash_node_t *node = hash_table[index];
    while (node != NULL) {
        if (node->rnti == rnti) {
            pthread_mutex_unlock(&table_lock);
            return 1;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&table_lock);
    return 0;
}

void add_rnti(uint16_t rnti) {
    unsigned int index = hash_function(rnti);

    pthread_mutex_lock(&table_lock);
    hash_node_t *new_node = (hash_node_t *)malloc(sizeof(hash_node_t));
    if (!new_node) {
        perror("Failed to allocate memory for hash node");
        exit(EXIT_FAILURE);
    }
    new_node->rnti = rnti;
    new_node->next = hash_table[index];
    hash_table[index] = new_node;

    pthread_mutex_unlock(&table_lock);
}

void remove_rntis() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hash_node_t *node = hash_table[i];
        while (node != NULL) {
            hash_node_t *temp = node;
            node = node->next;
            free(temp);
        }
        hash_table[i] = NULL;
    }
}

int allocate_and_populate_crc_pdu(NFAPI_CRC_INDICATION_PDU_T **array, size_t num_elements) {
    if (num_elements > MAX_RNTIs) return -1;

    *array = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*array) {
        perror("Failed to allocate memory for CRC PDU array");
        return -1;
    }

    for (size_t i = 0; i < num_elements; ++i) {
        uint16_t rnti;
        do {
            rnti = rand() % MAX_RNTIs + 1; // Avoid RNTI 0
        } while (is_rnti_present(rnti));

        (*array)[i].RX_UE_INFORMATION_TAG = i + 1;
        (*array)[i].RNTI = rnti;
        (*array)[i].CRC_INDICATION_REL8_TAG = rand() % 256; // Random byte
        (*array)[i].CRCFLAG = rand(); // Random CRC flag

        add_rnti(rnti);
    }

    return 0;
}

void cleanup_crc_pdu(NFAPI_CRC_INDICATION_PDU_T **array) {
    free(*array);
    *array = NULL;

    remove_rntis();
}
