#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
    long* offsetRef;
    void* metadata;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    size_t count;
    char* name;  // For logging purposes
} dataset;

// Function declarations
int process_datasets(dataset datasets[], size_t num_datasets, const char* ranges[][2], void (*sort_func)(record**, size_t));
void custom_sort(record** records, size_t count);
void free_dataset_memory(dataset* ds);
size_t query_records_processed(const dataset* ds);
const record* get_record_by_index(const dataset* ds, size_t index);
const record* get_record_by_metadata(const dataset** datasets, size_t num_datasets, void* metadata);

// Implementations
int process_datasets(dataset datasets[], size_t num_datasets, const char* ranges[][2], void (*sort_func)(record**, size_t)) {
    srand(time(NULL));
    for (size_t i = 0; i < num_datasets; ++i) {
        printf("Processing dataset: %s\n", datasets[i].name);

        int min_val = atoi(ranges[i][0]);
        int max_val = atoi(ranges[i][1]);

        if ((datasets[i].offsets = malloc(sizeof(long) * datasets[i].count)) == NULL ||
            (datasets[i].keys = malloc(sizeof(int) * datasets[i].count)) == NULL ||
            (datasets[i].records = malloc(sizeof(record*) * datasets[i].count)) == NULL) {
            fprintf(stderr, "Memory allocation failed for dataset: %s\n", datasets[i].name);
            return -1; // Allocation failure
        }

        for (size_t j = 0; j < datasets[i].count; ++j) {
            int random_value = min_val + rand() % (max_val - min_val + 1);
            long offset_value = (long)(random_value * 10);  // Example offset calculation

            record* rec = malloc(sizeof(record));
            if (!rec) {
                fprintf(stderr, "Memory allocation failed for a record in dataset: %s\n", datasets[i].name);
                free_dataset_memory(&datasets[i]);
                return -1;  // Allocation failure
            }

            rec->value = random_value;
            rec->offsetRef = &offset_value;
            rec->metadata = &datasets[i];

            datasets[i].offsets[j] = offset_value;
            datasets[i].keys[j] = random_value;
            datasets[i].records[j] = rec;
        }

        sort_func(datasets[i].records, datasets[i].count);

        printf("Completed processing dataset: %s\n", datasets[i].name);
    }

    return 0; // Success
}

void custom_sort(record** records, size_t count) {
    for (size_t i = 0; i < count - 1; ++i) {
        for (size_t j = 0; j < count - i - 1; ++j) {
            if (records[j]->value > records[j + 1]->value) {
                record* temp = records[j];
                records[j] = records[j + 1];
                records[j + 1] = temp;
            }
        }
    }
}

void free_dataset_memory(dataset* ds) {
    for (size_t i = 0; i < ds->count; ++i) {
        free(ds->records[i]);
    }
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
}

size_t query_records_processed(const dataset* ds) {
    return ds->count;
}

const record* get_record_by_index(const dataset* ds, size_t index) {
    if (index < ds->count) {
        return ds->records[index];
    }
    return NULL;  // Out of bounds
}

const record* get_record_by_metadata(const dataset** datasets, size_t num_datasets, void* metadata) {
    for (size_t i = 0; i < num_datasets; ++i) {
        if (*(dataset**)metadata == datasets[i]) {
            for (size_t j = 0; j < datasets[i]->count; ++j) {
                if (datasets[i]->records[j]->metadata == metadata) {
                    return datasets[i]->records[j];
                }
            }
        }
    }
    return NULL;
}

int main() {
    const char* ranges[] = { "1", "100" };

    dataset datasets[2] = {
        {.count = 5, .name = "Dataset1"},
        {.count = 7, .name = "Dataset2"}
    };

    int result = process_datasets(datasets, 2, ranges, custom_sort);
    if (result != 0) {
        fprintf(stderr, "Processing failed with error code: %d\n", result);
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < 2; ++i) {
        printf("Dataset %s has processed %zu records.\n", datasets[i].name, query_records_processed(&datasets[i]));
        free_dataset_memory(&datasets[i]);
    }

    return EXIT_SUCCESS;
}
