['Below is a C implementation for the described task using a doubly linked list to manage `NetworkPerformanceMetrics` structures. It includes thread safety with mutexes, memory management, moving average calculation, and error logging:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 200

typedef struct {
    int cellId;
    time_t timeStamp;
    double throughput;
    double movingAverageThroughput;
} NetworkPerformanceMetrics;

typedef struct Node {
    NetworkPerformanceMetrics data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t lock;
    FILE* logFile;
    int enableLogging;
} MetricsList;

void logError(MetricsList* list, const char* message) {
    if (list->enableLogging && list->logFile != NULL) {
        fprintf(list->logFile, "ERROR: %s\n", message);
        fflush(list->logFile);
    }
}

MetricsList* initMetricsList(FILE* logFile, int enableLogging) {
    MetricsList* list = (MetricsList*)malloc(sizeof(MetricsList));
    if (!list) {
        perror("Failed to allocate MetricsList");
        return NULL;
    }

    list->head = list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->logFile = logFile;
    list->enableLogging = enableLogging;

    return list;
}

void freeMetricsList(MetricsList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int addMetric(MetricsList* list, int cellId, time_t timeStamp, double throughput) {
    if (!list) return 0;

    pthread_mutex_lock(&list->lock);

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        logError(list, "Failed to allocate memory for new node");
        pthread_mutex_unlock(&list->lock);
        return 0;
    }

    newNode->data.cellId = cellId;
    newNode->data.timeStamp = timeStamp;
    newNode->data.throughput = throughput;

    if (list->tail) {
        list->tail->next = newNode;
        newNode->prev = list->tail;
        list->tail = newNode;
    } else {
        list->head = list->tail = newNode;
        newNode->next = newNode->prev = NULL;
    }

    double movingAvg = 0.0;
    Node* tempNode = list->tail;
    int count = 0;

    for (int i = 0; i < 100 && tempNode != NULL; ++i) {
        if (tempNode) {
            movingAvg += tempNode->data.throughput;
            tempNode = tempNode->prev;
            count++;
        }
    }

    newNode->data.movingAverageThroughput = movingAvg / count;

    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 1;
}

void calculateMovingAverages(MetricsList* list) {
    if (!list || !list->head) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->tail;
    double movingAvg = 0.0;
    int count = 0;

    while (current != NULL && count < 100) {
        movingAvg += current->data.throughput;
        current = current->prev;
        count++;
    }

    current = list->head;
    while (current != NULL) {
        current->data.movingAverageThroughput = movingAvg / count;
        movingAvg -= (count > 0 && current->next ? current->next->data.throughput : 0);
        if (current->prev) {
            movingAvg += current->prev->data.throughput;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

int main() {
    FILE* logFile = fopen("error.log", "a");
    MetricsList* metricsList = initMetricsList(logFile, 1);

    if (!metricsList) return EXIT_FAILURE;

    // Simulate adding metrics
    for (int i = 0; i < 300; ++i) {
        addMetric(metricsList, i, time(NULL), (double)(rand() % 100));
    }

    calculateMovingAverages(metricsList);

    freeMetricsList(metricsList);
    fclose(logFile);

    return EXIT_SUCCESS;
}
```

### Key Features:
- **Doubly Linked List**: Efficient for insertions and deletions.
- **Thread Safety**: Mutexes ensure safe concurrent access.
- **Error Logging**: Logs errors to a file descriptor if enabled.
- **Moving Average Calculation**: Uses a sliding window approach over the last 100 entries.
- **Dynamic Memory Management**: Handles memory allocation failures gracefully.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_EVENTS 1000
#define CATEGORY_MAX_LEN 50
#define DESCRIPTION_MAX_LEN 200
#define TAG_MAX_LEN 30
#define RESOURCE_ID_MAX_LEN 20
#define STATUS_CODE_MAX_LEN 10
#define METADATA_MAX_LEN 256

typedef struct {
    char resource_id[RESOURCE_ID_MAX_LEN];
    char status_code[STATUS_CODE_MAX_LEN];
} details_t;

typedef struct {
    int event_id;
    char description[DESCRIPTION_MAX_LEN];
    char tag[TAG_MAX_LEN];
    details_t detail1, detail2;
} event_t;

typedef struct {
    double processing_time;
    int success_status;
} metadata_t;

typedef struct Node {
    void *data;
    struct Node* next;
} Node;

typedef struct {
    Node* front;
    Node* rear;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    size_t count;
    size_t accesses;
} ThreadSafeQueue;

void logError(const char* message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

ThreadSafeQueue* createQueue(size_t capacity) {
    ThreadSafeQueue* q = (ThreadSafeQueue*)malloc(sizeof(ThreadSafeQueue));
    if (!q) {
        logError("Failed to allocate queue");
        return NULL;
    }
    q->front = q->rear = NULL;
    q->capacity = capacity;
    pthread_mutex_init(&q->lock, NULL);
    pthread_cond_init(&q->cond, NULL);
    q->count = 0;
    q->accesses = 0;
    return q;
}

int enqueue(ThreadSafeQueue* q, void* data) {
    pthread_mutex_lock(&q->lock);
    if (q->count >= q->capacity) {
        // Drop least recently added
        Node* oldFront = q->front;
        q->front = q->front->next;
        free(oldFront->data);
        free(oldFront);
        q->count--;
    }
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&q->lock);
        logError("Failed to allocate node for queue");
        return -1; // Memory allocation failure
    }
    newNode->data = data;
    newNode->next = NULL;
    if (q->rear == NULL) {
        q->front = q->rear = newNode;
    } else {
        q->rear->next = newNode;
        q->rear = newNode;
    }
    q->count++;
    pthread_cond_signal(&q->cond);
    q->accesses++;
    pthread_mutex_unlock(&q->lock);
    return 0; // Success
}

int dequeue(ThreadSafeQueue* q, void** data) {
    pthread_mutex_lock(&q->lock);
    while (q->count == 0 && !pthread_cond_wait(&q->cond, &q->lock)) {}
    if (q->count == 0) {
        pthread_mutex_unlock(&q->lock);
        return -1; // Queue is empty
    }
    Node* oldFront = q->front;
    *data = oldFront->data;
    q->front = q->front->next;
    if (q->front == NULL) {
        q->rear = NULL;
    }
    free(oldFront);
    q->count--;
    pthread_mutex_unlock(&q->lock);
    return 0; // Success
}

int validateEventID(int event_id, int* valid_ids, size_t num_events) {
    for (size_t i = 0; i < num_events; ++i) {
        if (valid_ids[i] == event_id) {
            return -1; // Duplicate ID found
        }
    }
    if (event_id < 0 || event_id > MAX_EVENTS) {
        return -2; // Invalid range
    }
    return 0; // Valid
}

int* allocateAndInitializeEventArrays(size_t num_events, size_t system_limit, ThreadSafeQueue** queue) {
    if (num_events <= 0) {
        logError("Invalid number of events");
        return NULL;
    }

    size_t total_memory_needed = sizeof(int) * num_events +
                                 sizeof(char*) * num_events +
                                 sizeof(event_t) * num_events +
                                 sizeof(details_t) * 2 * num_events +
                                 sizeof(metadata_t) * num_events;

    if (total_memory_needed > system_limit) {
        logError("Memory allocation exceeds system limit");
        return NULL;
    }

    int* event_ids = (int*)malloc(sizeof(int) * num_events);
    char** categories = (char**)malloc(sizeof(char*) * num_events);
    event_t* events = (event_t*)malloc(sizeof(event_t) * num_events);
    metadata_t* metadata = (metadata_t*)malloc(sizeof(metadata_t) * num_events);

    if (!event_ids || !categories || !events || !metadata) {
        logError("Memory allocation failed");
        free(event_ids); free(categories); free(events); free(metadata);
        return NULL;
    }

    int valid_ids[MAX_EVENTS] = {0};
    for (size_t i = 0; i < num_events; ++i) {
        event_ids[i] = rand() % MAX_EVENTS; // Example ID generation
        if (validateEventID(event_ids[i], valid_ids, i) != 0) {
            logError("Invalid event ID or duplicate found");
            continue;
        }
        valid_ids[i] = event_ids[i];

        categories[i] = strdup("Example Category"); // Assigning example category
        snprintf(events[i].description, DESCRIPTION_MAX_LEN, "Description for Event %d", i);
        snprintf(events[i].tag, TAG_MAX_LEN, "Tag%d", i);

        snprintf(events[i].detail1.resource_id, RESOURCE_ID_MAX_LEN, "ResourceID%d", i);
        snprintf(events[i].detail2.status_code, STATUS_CODE_MAX_LEN, "Status%d", i);

        metadata[i].processing_time = 0.0;
        metadata[i].success_status = 0;
    }

    *queue = createQueue(num_events);
    if (!*queue) {
        logError("Failed to create queue");
        free(event_ids); free(categories); free(events); free(metadata);
        return NULL;
