// Assuming record structure is defined as follows:
struct Record {
    int value;
    std::string* identifier;

    Record() : value(0), identifier(nullptr) {}
};

class DataProcessor {
public:
    // Constructor
    DataProcessor(size_t numRecords, int seed);

    // Destructor
    ~DataProcessor();

private:
    size_t numRecords_;
    long* offsetArray_;
    int* keyArray_;
    Record* recordArray_;

    std::mutex mtx_;  // For thread safety

    bool initializeMemory();
    void releaseMemory();

    // Custom pseudo-random number generator for reproducibility
    static int customRandom(int min, int max, unsigned seed);
};

DataProcessor::DataProcessor(size_t numRecords, int seed)
    : numRecords_(numRecords), offsetArray_(nullptr), keyArray_(nullptr), recordArray_(nullptr) {

    // Initialize external service to get the initial seed for reproducibility
    std::srand(seed);

    if (!initializeMemory()) {
        std::cerr << "Failed to initialize memory!" << std::endl;
        exit(EXIT_FAILURE);
    }

    // Fill records with random values and unique identifiers
    std::lock_guard<std::mutex> lock(mtx_);
    for (size_t i = 0; i < numRecords_; ++i) {
        recordArray_[i].value = customRandom(1, 100, seed + static_cast<unsigned>(i));
        recordArray_[i].identifier = new(std::nothrow) std::string("ID_" + std::to_string(i));
        if (!recordArray_[i].identifier) {
            releaseMemory();
            exit(EXIT_FAILURE);
        }
    }
}

DataProcessor::~DataProcessor() {
    releaseMemory();
}

bool DataProcessor::initializeMemory() {
    offsetArray_ = new(std::nothrow) long[numRecords_];
    keyArray_ = new(std::nothrow) int[numRecords_];
    recordArray_ = new(std::nothrow) Record[numRecords_];

    if (!offsetArray_ || !keyArray_ || !recordArray_) {
        return false;
    }
    return true;
}

void DataProcessor::releaseMemory() {
    delete[] offsetArray_;
    delete[] keyArray_;

    for (size_t i = 0; i < numRecords_; ++i) {
        delete recordArray_[i].identifier;
    }

    delete[] recordArray_;
}

int DataProcessor::customRandom(int min, int max, unsigned seed) {
    std::srand(seed);
    return std::rand() % (max - min + 1) + min;
}
