typedef struct {
    int value;
    long offsetRef;
} Record;

int generateUniqueRandomKeys(int *keys, int n, int minValue, int maxValue, unsigned int seed) {
    int unique_keys = 0;
    srand(seed);
    while (unique_keys < n) {
        int key = rand() % (maxValue - minValue + 1) + minValue;
        int exists = 0;

        for (int i = 0; i < unique_keys; ++i) {
            if (keys[i] == key) {
                exists = 1;
                break;
            }
        }

        if (!exists) {
            keys[unique_keys++] = key;
        }
    }
    return 0;
}

Record* initializeRecords(int n, int minValue, int maxValue, unsigned int seed) {
    if (n <= 0 || minValue >= maxValue) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    long *offsets = malloc(n * sizeof(long));
    int *keys = malloc(n * sizeof(int));
    Record *records = malloc(n * sizeof(Record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    for (int i = 0; i < n; ++i) {
        offsets[i] = i * 1000L;
    }

    generateUniqueRandomKeys(keys, n, 1, 10000, seed);

    srand(seed); // Re-seed the random number generator
    for (int i = 0; i < n; ++i) {
        records[i].value = rand() % (maxValue - minValue + 1) + minValue;
        records[i].offsetRef = offsets[i];
    }

    return records;
}

