NFAPI_L1_RX_FRAME_INFO_T* initialize_dynamic_array(int num_frames) {
    if (num_frames <= 0) return NULL;

    NFAPI_L1_RX_FRAME_INFO_T *head = NULL, **current = &head;
    for (int i = 0; i < num_frames; ++i) {
        NFAPI_L1_RX_FRAME_INFO_T* new_node = malloc(sizeof(NFAPI_L1_RX_FRAME_INFO_T));
