                *current = temp->next;
                free(temp);
            }
            return NULL;
        }
        new_node->next = NULL;
        *current = new_node;
        current = &new_node->next;
    }

    populate_frames(head, num_frames);
    return head;
}

void populate_frames(NFAPI_L1_RX_FRAME_INFO_T* head, int num_frames) {
    if (!head) return;

    srand((unsigned int)time(NULL)); // Seed random number generator

    NFAPI_L1_RX_FRAME_INFO_T *current = head;
    for (int i = 0; i < num_frames; ++i) {
        current->rx_frame_info.rx_power_dbm = rand() % 100 - 50; // Random range [-50, +49]
        current->rx_frame_info.frame_loss_rate = ((float)rand() / RAND_MAX) * 10.0f;
        current->rx_frame_info.crc_error_count = rand() % 1000;

        // Populate tx_power_level_indication as needed

        current = current->next;
    }
}

void update_frames_periodically(NFAPI_L1_RX_FRAME_INFO_T* head) {
    if (!head) return;

    pthread_mutex_lock(&array_lock);
    NFAPI_L1_RX_FRAME_INFO_T *current = head;
    while (current) {
        current->rx_frame_info.rx_power_dbm += rand() % 10 - 5; // Random change [-5, +4]
        current->rx_frame_info.frame_loss_rate += ((float)rand() / RAND_MAX) - 0.5f; 
        current->rx_frame_info.crc_error_count = (current->rx_frame_info.crc_error_count + rand() % 100) % 1000;

        // Update tx_power_level_indication as needed

        current = current->next;
    }
    pthread_mutex_unlock(&array_lock);
}

NFAPI_L1_RX_FRAME_INFO_T* filter_frames(NFAPI_L1_RX_FRAME_INFO_T* head, int rx_power_dbm_threshold) {
    if (!head) return NULL;

    NFAPI_L1_RX_FRAME_INFO_T *current = head, *prev = NULL;
    while (current) {
        if (current->rx_frame_info.rx_power_dbm < rx_power_dbm_threshold) {
            pthread_mutex_lock(&array_lock);
            if (prev) {
                prev->next = current->next;
            } else {
                head = current->next;
            }
            NFAPI_L1_RX_FRAME_INFO_T *temp = current;
            current = current->next;
            free(temp);
            pthread_mutex_unlock(&array_lock);
        } else {
            prev = current;
            current = current->next;
        }
    }
    return head;
}

void free_dynamic_array(NFAPI_L1_RX_FRAME_INFO_T* head) {
    while (head != NULL) {
        NFAPI_L1_RX_FRAME_INFO_T *temp = head;
        head = head->next;
        free(temp);
    }
}

