['Below is an outline of the C library structure you described, including headers and source files for managing a heterogeneous data queue with thread safety and dynamic resizing.

### `queue.h`

```c
#ifndef QUEUE_H
#define QUEUE_H

#include <stddef.h>
#include <pthread.h>

typedef enum {
    LOW,
    MEDIUM,
    HIGH
} PriorityLevel;

typedef struct Message {
    char *text;
    time_t timestamp;
    PriorityLevel priority;
} Message;

typedef union DataUnion {
    int integer;
    float floating_point;
    void *pointer_to_node;
    Message custom_message;
} DataUnion;

typedef struct Node {
    DataUnion data;
    struct Node *next;
} Node;

typedef struct PriorityQueue {
    Node **buckets; // Array of pointers to linked list nodes
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} PriorityQueue;

PriorityQueue* pq_create(size_t initial_capacity);
void pq_destroy(PriorityQueue *pq);

int pq_enqueue(PriorityQueue *pq, DataUnion data);
DataUnion pq_dequeue(PriorityQueue *pq);

void pq_serialize(const char *filename, const PriorityQueue *pq);
PriorityQueue* pq_deserialize(const char *filename);

#endif // QUEUE_H
```

### `queue.c`

```c
#include "queue.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

static unsigned int hash_priority(PriorityLevel priority) {
    return (unsigned int)priority % 3;
}

PriorityQueue* pq_create(size_t initial_capacity) {
    PriorityQueue *pq = malloc(sizeof(PriorityQueue));
    if (!pq) return NULL;

    pq->buckets = calloc(initial_capacity, sizeof(Node *));
    if (!pq->buckets) {
        free(pq);
        return NULL;
    }

    pq->capacity = initial_capacity;
    pq->count = 0;
    pthread_mutex_init(&pq->lock, NULL);

    return pq;
}

void pq_destroy(PriorityQueue *pq) {
    pthread_mutex_lock(&pq->lock);

    for (size_t i = 0; i < pq->capacity; ++i) {
        Node *node = pq->buckets[i];
        while (node) {
            Node *tmp = node;
            node = node->next;
            free(tmp);
        }
    }

    free(pq->buckets);
    pthread_mutex_unlock(&pq->lock);
    pthread_mutex_destroy(&pq->lock);
    free(pq);
}

int pq_enqueue(PriorityQueue *pq, DataUnion data) {
    if (!pq) return -1;

    unsigned int index = hash_priority(data.custom_message.priority);

    Node *new_node = malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&pq->lock);
    new_node->next = pq->buckets[index];
    pq->buckets[index] = new_node;
    ++(pq->count);

    // Handle resizing if necessary
    if (pq->count > pq->capacity * 0.75) {
        size_t new_capacity = pq->capacity * 2;
        Node **new_buckets = calloc(new_capacity, sizeof(Node *));
        if (!new_buckets) {
            free(new_node);
            pthread_mutex_unlock(&pq->lock);
            return -1;
        }

        for (size_t i = 0; i < pq->capacity; ++i) {
            Node *node = pq->buckets[i];
            while (node) {
                unsigned int new_index = hash_priority(node->data.custom_message.priority) % new_capacity;
                Node *next_node = node->next;

                node->next = new_buckets[new_index];
                new_buckets[new_index] = node;

                node = next_node;
            }
        }

        free(pq->buckets);
        pq->buckets = new_buckets;
        pq->capacity = new_capacity;
    }

    pthread_mutex_unlock(&pq->lock);

    return 0;
}

DataUnion pq_dequeue(PriorityQueue *pq) {
    DataUnion data = { .integer = 0 }; // Initialize with zero

    if (!pq) return data;

    pthread_mutex_lock(&pq->lock);

    for (unsigned int i = 0; i < pq->capacity; ++i) {
        Node **slot = &(pq->buckets[i]);

        while (*slot && ((*slot)->data.custom_message.priority != HIGH)) {
            slot = &((*slot)->next);
        }

        if (!*slot) continue;

        Node *node_to_remove = *slot;
        data = node_to_remove->data;
        *slot = node_to_remove->next;

        free(node_to_remove);
        --(pq->count);

        break;
    }

    pthread_mutex_unlock(&pq->lock);

    return data;
}

void pq_serialize(const char *filename, const PriorityQueue *pq) {
    if (!filename || !pq) return;

    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&(pq->capacity), sizeof(size_t), 1, file);
    pthread_mutex_lock(&pq->lock);

    for (size_t i = 0; i < pq->capacity; ++i) {
        Node *node = pq->buckets[i];
        while (node) {
            fwrite(&(node->data.custom_message.priority), sizeof(PriorityLevel), 1, file);
            fwrite(node->data.custom_message.text, strlen(node->data.custom_message.text) + 1, 1, file);
            fwrite(&node->data.custom_message.timestamp, sizeof(time_t), 1, file);

            node = node->next;
        }
    }

    pthread_mutex_unlock(&pq->lock);
    fclose(file);
}

PriorityQueue* pq_deserialize(const char *filename) {
    if (!filename) return NULL;

    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    PriorityQueue *pq = malloc(sizeof(PriorityQueue));
    if (!pq) goto error;

    fread(&(pq->capacity), sizeof(size_t), 1, file);
    pq->buckets = calloc(pq->capacity, sizeof(Node *));
    if (!pq->buckets) goto error;

    pq->count = 0;
    pthread_mutex_init(&pq->lock, NULL);

    PriorityLevel priority;
    char text[256];
    time_t timestamp;

    while (fread(&priority, sizeof(PriorityLevel), 1, file)) {
        fread(text, sizeof(char), sizeof(text) - 1, file);
        text[sizeof(text) - 1] = '\0';

        fread(&timestamp, sizeof(time_t), 1, file);

        Node *new_node = malloc(sizeof(Node));
        if (!new_node) goto error;

        new_node->data.custom_message.priority = priority;
        new_node->data.custom_message.text = strdup(text);
        new_node->data.custom_message.timestamp = timestamp;
        new_node->next = NULL;

        unsigned int index = hash_priority(priority);

        pthread_mutex_lock(&pq->lock);
        new_node->next = pq->buckets[index];
        pq->buckets[index] = new_node;
        ++(pq->count);
        pthread_mutex_unlock(&pq->lock);
    }

    fclose(file);
    return pq;

error:
    if (file) fclose(file);
    if (pq) {
        pq_destroy(pq);
    }
    return NULL;
}
