    int processingStatusFlag;
} Metadata;

typedef struct {
    long offset;
    Record record;
} LongRecordPair;

// Helper function to calculate the median
int calculateMedian(int *arr, size_t n) {
    if (n % 2 == 0)
        return (arr[n / 2 - 1] + arr[n / 2]) / 2;
    else
        return arr[n / 2];
}

// Comparator function for qsort
int compareKeys(const void *a, const void *b) {
    LongRecordPair *pairA = (LongRecordPair *)a;
    LongRecordPair *pairB = (LongRecordPair *)b;
    return pairA->record.key - pairB->record.key;
}

// Logging function (stub)
void logEvent(const char *message) {
    // Assume this logs to an external logging library
    printf("%s\n", message);
}

// Function to process and sort records
int processAndSortRecords(int fd, int calculateOnSubset, int subsetRangeStart, int subsetRangeEnd, int exportFd) {
    pthread_mutex_t lock;
    if (pthread_mutex_init(&lock, NULL) != 0) {
        return -1; // Error initializing mutex
    }

    size_t maxRecords = 10000000;
    long *offsets = malloc(maxRecords * sizeof(long));
    int *keys = malloc(maxRecords * sizeof(int));
    Record *records = malloc(maxRecords * sizeof(Record));
    Metadata *metadata = malloc(maxRecords * sizeof(Metadata));

    if (!offsets || !keys || !records || !metadata) {
        logEvent("Memory allocation failed");
        pthread_mutex_destroy(&lock);
        free(offsets); free(keys); free(records); free(metadata);
        return -1;
    }

    logEvent("Memory allocated");

    // Initialize records with random values
    for (size_t i = 0; i < maxRecords; ++i) {
        records[i].key = rand() % 1000000; // Random key between 0 and 999999
    }

    ssize_t bytesRead;
    int *integers = malloc(maxRecords * sizeof(int));
    if (!integers) {
        logEvent("Memory allocation for integers failed");
        pthread_mutex_destroy(&lock);
        free(offsets); free(keys); free(records); free(metadata);
        return -1;
    }

    size_t numIntegers = 0;
    while ((bytesRead = read(fd, &integers[numIntegers], sizeof(int))) > 0) {
        if (numIntegers < maxRecords) {
            ++numIntegers;
        } else {
            logEvent("Maximum integer capacity reached");
            break;
        }
    }

    if (bytesRead == -1) {
        strcpy(metadata[0].errorMessage, "Error reading from file descriptor");
        metadata[0].processingStatusFlag = 1;
        pthread_mutex_destroy(&lock);
        free(offsets); free(keys); free(records); free(metadata); free(integers);
        return -1;
    }

    // Populate records with integers read
    for (size_t i = 0; i < numIntegers && i < maxRecords; ++i) {
        records[i].key = integers[i];
        offsets[i] = lseek(fd, 0, SEEK_CUR); // Simulate offset storage
    }

    // Sort records based on keys
    LongRecordPair *pairs = malloc(numIntegers * sizeof(LongRecordPair));
    if (!pairs) {
        logEvent("Memory allocation for pairs failed");
        pthread_mutex_destroy(&lock);
        free(offsets); free(keys); free(records); free(metadata); free(integers);
        return -1;
    }

    for (size_t i = 0; i < numIntegers; ++i) {
        pairs[i].offset = offsets[i];
        pairs[i].record = records[i];
    }

    qsort(pairs, numIntegers, sizeof(LongRecordPair), compareKeys);

    // Calculate median
    int subsetSize = calculateOnSubset ? (subsetRangeEnd - subsetRangeStart + 1) : numIntegers;
    if (subsetSize > numIntegers) {
        subsetSize = numIntegers;
    }

    qsort(integers, subsetSize, sizeof(int), compareKeys);
    int median = calculateMedian(integers, subsetSize);
    printf("Median: %d\n", median);

    // Export sorted records to new file descriptor if specified
    if (exportFd != -1) {
        for (size_t i = 0; i < numIntegers && i < maxRecords; ++i) {
            write(exportFd, &pairs[i].record.key, sizeof(int));
        }
    }

    // Free allocated memory
    pthread_mutex_lock(&lock);
    free(offsets); logEvent("Offset array deallocated");
    free(keys); logEvent("Key array deallocated");
    free(records); logEvent("Record array deallocated");
    free(metadata); logEvent("Metadata array deallocated");
    free(integers); logEvent("Integer array deallocated");
    free(pairs); logEvent("Pair array deallocated");
    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);

    return 0;
}
