// Mutex for thread safety
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Logging function
void log(const char *message) {
    static FILE *log_file = NULL;
    if (!log_file) {
        log_file = fopen("process.log", "w");
        if (!log_file) {
            fprintf(stderr, "Error opening log file.\n");
            exit(EXIT_FAILURE);
        }
    }
    pthread_mutex_lock(&lock);
    fprintf(log_file, "%s\n", message);
    fflush(log_file);
    pthread_mutex_unlock(&lock);
}

// Comparison function for qsort
int compare_records(const void *a, const void *b) {
    record *rec1 = (record *)a;
    record *rec2 = (record *)b;
    return rec1->num - rec2->num;
}

// Function to generate a unique identifier from int and float
char* generate_id(int num, float value) {
    char id[ID_MAX_LENGTH];
    snprintf(id, ID_MAX_LENGTH, "%d-%.2f", num, value);
    return strdup(id); // Duplicate string for safe memory management
}

// Main function to initialize records
int initialize_records(record **records, size_t count) {
    if (count > MAX_RECORDS || !records) {
        log("Invalid input parameters.");
        return -1;
    }

    *records = malloc(count * sizeof(record));
    if (!*records) {
        log("Memory allocation failed for records array.");
        return -2;
    }

    srand((unsigned int)time(NULL)); // Seed random number generator
    for (size_t i = 0; i < count; ++i) {
        (*records)[i].num = rand() % 100; // Random int between 0 and 99
        (*records)[i].value = ((float)rand() / RAND_MAX) * 100.0f; // Random float between 0.0 and 100.0

        char *id_str = generate_id((*records)[i].num, (*records)[i].value);
        if (!id_str) {
            log("Memory allocation failed for ID string.");
            // Free previously allocated memory
            for (size_t j = 0; j < i; ++j) free((*records)[j].id);
            free(*records);
            return -3;
        }
        (*records)[i].id = id_str;
    }

    qsort(*records, count, sizeof(record), compare_records);

    log("Records initialized and sorted successfully.");
    return 0;
}

// Function to free allocated memory
void free_records(record *records, size_t count) {
    if (!records) return;

    for (size_t i = 0; i < count; ++i) {
        free(records[i].id);
    }
    free(records);
}
