// Function to initialize and populate the LTE_RRC_CONNECTION_RECONFIGURATION_PDU structure
void init_and_populate_pdu(LTE_RRC_CONNECTION_RECONFIGURATION_PDU* pdu, size_t num_cells, unsigned int start_id) {
    if (pdu == NULL) return;

    // Initialize update tag with a valid value
    pdu->update_tag.tag = 1;  // Assuming '1' is a valid update tag for illustration

    // Allocate memory for the list of cell identities
    pdu->list_of_cell_identities = malloc(num_cells * sizeof(Irvine_CELL_IDENTITY_TAG));

    if (pdu->list_of_cell_identities == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;  // Early exit due to failure in memory allocation
    }

    pthread_mutex_lock(&mutex);  // Ensure thread-safe access to shared resources

    pdu->count = num_cells;

    for (size_t i = 0; i < num_cells; ++i) {
        // Dynamically allocate and assign cell identities
        pdu->list_of_cell_identities[i].cell_identity = malloc(20 * sizeof(char));  // Assuming each identity string is at most 19 characters long + null-terminator

        if (pdu->list_of_cell_identities[i].cell_identity == NULL) {
            fprintf(stderr, "Memory allocation failed for cell identities\n");

            // Free any previously allocated memory in case of failure
            while (--i >= 0) free(pdu->list_of_cell_identities[i].cell_identity);
            free(pdu->list_of_cell_identities);
            pdu->list_of_cell_identities = NULL;
            pdu->count = 0;

            pthread_mutex_unlock(&mutex);  // Unlock mutex before returning
            return;
        }

        snprintf(pdu->list_of_cell_identities[i].cell_identity, 20, "CellID_%u", start_id + i);
    }

    pthread_mutex_unlock(&mutex);  // Release the lock after completing operations
}

// Example usage in a multi-threaded environment
void* thread_function(void* arg) {
    LTE_RRC_CONNECTION_RECONFIGURATION_PDU pdu;
    init_and_populate_pdu(&pdu, 10, 100);  // Example with 10 cells starting from ID 100

    // Process the PDU...

    // Cleanup
    for (size_t i = 0; i < pdu.count; ++i) {
        free(pdu.list_of_cell_identities[i].cell_identity);
    }
