    return 0;
}

int add_sensor_metadata(WeatherData *data, SensorMetadata *metadata) {
    size_t new_size = (data->metadata_count + 1) * sizeof(SensorMetadata*);
    SensorMetadata **new_data = realloc(data->metadata, new_size);
    if (!new_data) return -2;

    data->metadata = new_data;
    data->metadata[data->metadata_count++] = metadata;

    return 0;
}

int serialize_weather_data(const WeatherData *data, FILE *file) {
    fwrite(&data->temperature_count, sizeof(size_t), 1, file);
    fwrite(data->temperature_data, sizeof(float), data->temperature_count, file);

    fwrite(&data->humidity_count, sizeof(size_t), 1, file);
    fwrite(data->humidity_data, sizeof(int), data->humidity_count, file);

    fwrite(&data->metadata_count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < data->metadata_count; ++i) {
        fwrite(data->metadata[i], sizeof(SensorMetadata), 1, file);
    }

    return 0;
}

int deserialize_weather_data(WeatherData *data, FILE *file) {
    size_t temp_count, humidity_count, meta_count;

    fread(&temp_count, sizeof(size_t), 1, file);
    data->temperature_data = realloc(data->temperature_data, temp_count * sizeof(float));
    if (!data->temperature_data) return -2;
    fread(data->temperature_data, sizeof(float), temp_count, file);

    fread(&humidity_count, sizeof(size_t), 1, file);
    data->humidity_data = realloc(data->humidity_data, humidity_count * sizeof(int));
    if (!data->humidity_data) return -3;
    fread(data->humidity_data, sizeof(int), humidity_count, file);

    fread(&meta_count, sizeof(size_t), 1, file);
    data->metadata = realloc(data->metadata, meta_count * sizeof(SensorMetadata*));
    if (!data->metadata) return -4;

    for (size_t i = 0; i < meta_count; ++i) {
        SensorMetadata *metadata = malloc(sizeof(SensorMetadata));
        if (!metadata) return -5;
        fread(metadata, sizeof(SensorMetadata), 1, file);
        data->metadata[i] = metadata;
    }

    data->temperature_count = temp_count;
    data->humidity_count = humidity_count;
    data->metadata_count = meta_count;

    return 0;
}

void free_weather_data(WeatherData *data) {
    if (data) {
        free(data->temperature_data);
        free(data->humidity_data);

        for (size_t i = 0; i < data->metadata_count; ++i) {
            free(data->metadata[i]);
        }

        free(data->metadata);
        free(data);
    }
}
