typedef struct Record {
    int value;
    struct Record* next;
} Record;

typedef struct ListNode {
    int key;
    Record* record;
    struct ListNode* next;
} ListNode;

ListNode* createLinkedList(int size, long* offsetArray, int* keyArray) {
    ListNode* head = NULL;
    ListNode** currentPtr = &head;

    for (int i = 0; i < size; ++i) {
        // Allocate and initialize record
        Record* record = (Record*)malloc(sizeof(Record));
        if (!record) {
            freeLinkedList(head);
            return NULL;
        }
        record->value = i; // Example initialization
        record->next = NULL;

        // Simulate key retrieval with potential delay handling or caching logic
        int key = keyArray[i]; // Assume keyArray is populated externally

        // Create a new list node for the current key and record
        ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
        if (!newNode) {
            free(record);
            freeLinkedList(head);
            return NULL;
        }
        newNode->key = key;
        newNode->record = record;
        newNode->next = NULL;

        // Insert into the linked list in a sorted manner
        ListNode* prev = NULL;
        ListNode* temp = head;
        while (temp && temp->key < key) {
            prev = temp;
            temp = temp->next;
        }

        if (!prev) {  // Insert at the beginning or as new head
            newNode->next = head;
            *currentPtr = newNode;
        } else {  // Insert in the middle or end
            prev->next = newNode;
            newNode->next = temp;
        }
    }

    return head;
}

void freeLinkedList(ListNode* head) {
    ListNode* current = head;
    while (current) {
        ListNode* next = current->next;
        Record* record = current->record;
        free(record);
        free(current);
        current = next;
    }
}

