        exit(EXIT_FAILURE);
    }

    // Initialize temperature data
    for (size_t i = 0; i < num_temperatures; ++i) {
        (*temperature_data)[i] = -50 + ((double)rand() / RAND_MAX) * (120 + 50); // Random values within the range
    }

    // Initialize text descriptions and metadata with sample data
    strncpy(*text_descriptions, "Temperature readings and system information", text_size);
    strcpy((*metadata_ptr)->system_info, "System v1.0; Initialized");

    // Initialize items
    for (size_t i = 0; i < num_items; ++i) {
        (*items)[i].temperature = -50 + ((float)rand() / RAND_MAX) * (120 + 50); // Random values within the range
        (*items)[i] = (item){(*items)[i].temperature, rand(), 'A' + (rand() % 26)};
    }

    // Initialize log entries with sample data
    for (size_t i = 0; i < num_log_entries; ++i) {
        snprintf((*log_entries)[i].description, sizeof((*log_entries)[i].description), 
