        (*log_entries)[i] = (log_entry){i + 1, ""};
    }
}

void free_resources(double *temperature_data, char *text_descriptions,
                    item *items, log_entry *log_entries, metadata *metadata_ptr) {
    if (temperature_data)
        free(temperature_data);
    if (text_descriptions)
        free(text_descriptions);
    if (items)
        free(items);
    if (log_entries)
        free(log_entries);
    if (metadata_ptr)
        free(metadata_ptr);
}

int serialize_data(const double *temperature_data, const char *text_descriptions,
                   const item *items, size_t num_items, const log_entry *log_entries,
                   size_t num_log_entries, const metadata *metadata_ptr, 
                   unsigned char **output_buffer, size_t *output_size) {
    if (!temperature_data || !text_descriptions || !items || !log_entries || !metadata_ptr || 
        !output_buffer || !output_size)
        return -1;

    // Calculate buffer size
    size_t total_size = num_items * sizeof(item) + num_log_entries * sizeof(log_entry) +
                        strlen(text_descriptions) + sizeof(metadata);

    *output_buffer = (unsigned char *)malloc(total_size);
    if (!*output_buffer)
        return -1;

    unsigned char *ptr = *output_buffer;
    memcpy(ptr, items, num_items * sizeof(item));
    ptr += num_items * sizeof(item);

    memcpy(ptr, log_entries, num_log_entries * sizeof(log_entry));
    ptr += num_log_entries * sizeof(log_entry);

    memcpy(ptr, text_descriptions, strlen(text_descriptions) + 1);
    ptr += (strlen(text_descriptions) + 1);

    memcpy(ptr, metadata_ptr, sizeof(metadata));

    *output_size = total_size;
    return 0;
}

int deserialize_data(double *temperature_data, char *text_descriptions,
                     item *items, size_t num_items, log_entry *log_entries,
                     size_t num_log_entries, metadata *metadata_ptr, 
                     const unsigned char *input_buffer, size_t input_size) {
    if (!temperature_data || !text_descriptions || !items || !log_entries || !metadata_ptr ||
        !input_buffer || input_size == 0)
        return -1;

    unsigned char *ptr = (unsigned char *)input_buffer;

    memcpy(items, ptr, num_items * sizeof(item));
    ptr += num_items * sizeof(item);

    memcpy(log_entries, ptr, num_log_entries * sizeof(log_entry));
    ptr += num_log_entries * sizeof(log_entry);

    size_t text_size = input_size - (num_items * sizeof(item) + num_log_entries * sizeof(log_entry) + sizeof(metadata));
    if (text_size > strlen(text_descriptions))
        return -1;

    memcpy(text_descriptions, ptr, text_size);
    text_descriptions[text_size] = '\0';

    memcpy(metadata_ptr, ptr + text_size, sizeof(metadata));

    return 0;
}

// Example usage
int main() {
    double *temperature_data;
    char *text_descriptions;
    item *items;
    log_entry *log_entries;
    metadata *metadata_ptr;

    initialize_data(&temperature_data, &text_descriptions, &items, &log_entries, &metadata_ptr);

    // Serialize data
    unsigned char *serialized_data = NULL;
    size_t serialized_size = 0;
    if (serialize_data(temperature_data, text_descriptions, items, 50, log_entries, 20, metadata_ptr,
                       &serialized_data, &serialized_size) == 0) {
        printf("Data serialized successfully.\n");
    }

    // Deserialize data
    double *new_temperature_data;
    char new_text_descriptions[1024];
    item *new_items = (item *)malloc(50 * sizeof(item));
    log_entry *new_log_entries = (log_entry *)malloc(20 * sizeof(log_entry));
    metadata *new_metadata_ptr = (metadata *)malloc(sizeof(metadata));

    if (deserialize_data(new_temperature_data, new_text_descriptions,
                         new_items, 50, new_log_entries, 20, new_metadata_ptr,
                         serialized_data, serialized_size) == 0) {
        printf("Data deserialized successfully.\n");
    }

    free_resources(temperature_data, text_descriptions, items, log_entries, metadata_ptr);
    free(new_items);
    free(new_log_entries);
    free(new_metadata_ptr);
    if (serialized_data)
        free(serialized_data);

    return 0;
}
