#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define constants based on protocol specs and system requirements
#define MAX_NEIGHBOR_CELLS 100
#define NUM_THREADS 4

typedef struct {
    int measurement_object_tag;
} MEASUREMENT_OBJECT_TAG;

typedef struct {
    char* cell_id;
} NEIGHBOR_CELL_ID_TAG;

typedef struct {
    MEASUREMENT_OBJECT_TAG obj_tag;
    NEIGHBOR_CELL_ID_TAG* neighbor_cells;
    size_t num_neighbors;
} NR_RRM_MEASUREMENT_REQUEST;

// Thread-safe list of measurement requests
typedef struct {
    NR_RRM_MEASUREMENT_REQUEST** requests;
    size_t size;
    pthread_mutex_t lock;
} MeasurementRequestList;

MeasurementRequestList request_list = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

void* generate_measurement_requests(void* arg) {
    // Simulate geographic region, frequency band, and operator preferences
    int region_id = *(int*)arg;

    // Determine number of requests based on region specifics (example logic)
    size_t num_requests = (region_id % 5 + 1) * 10; 

    NR_RRM_MEASUREMENT_REQUEST* new_requests = malloc(num_requests * sizeof(NR_RRM_MEASUREMENT_REQUEST));
    if (!new_requests) {
        fprintf(stderr, "Memory allocation failed for measurement requests\n");
        return NULL;
    }

    // Populate each request
    for (size_t i = 0; i < num_requests; ++i) {
        new_requests[i].obj_tag.measurement_object_tag = i + 1;

        size_t num_neighbors = (rand() % MAX_NEIGHBOR_CELLS) + 1;
        new_requests[i].neighbor_cells = malloc(num_neighbors * sizeof(NEIGHBOR_CELL_ID_TAG));
        if (!new_requests[i].neighbor_cells) {
            fprintf(stderr, "Memory allocation failed for neighbor cells\n");
            free(new_requests);
            return NULL;
        }

        // Simulate cell ID generation
        for (size_t j = 0; j < num_neighbors; ++j) {
            char* cell_id = malloc(20); // Assume fixed length for simplicity
            if (!cell_id) {
                fprintf(stderr, "Memory allocation failed for a neighbor cell ID\n");
                free(new_requests[i].neighbor_cells);
                free(new_requests);
                return NULL;
            }
            snprintf(cell_id, 20, "Cell-%zu", j + 1);
            new_requests[i].neighbor_cells[j].cell_id = cell_id;
        }

        new_requests[i].num_neighbors = num_neighbors;
    }

    // Add requests to the global list in a thread-safe manner
    pthread_mutex_lock(&request_list.lock);

    request_list.requests = realloc(request_list.requests, (request_list.size + num_requests) * sizeof(NR_RRM_MEASUREMENT_REQUEST*));
    if (!request_list.requests) {
        fprintf(stderr, "Memory allocation failed for request list\n");
        // Free allocated requests and their neighbors
        for (size_t i = 0; i < num_requests; ++i) {
            for (size_t j = 0; j < new_requests[i].num_neighbors; ++j) {
                free(new_requests[i].neighbor_cells[j].cell_id);
            }
            free(new_requests[i].neighbor_cells);
        }
        free(new_requests);
        pthread_mutex_unlock(&request_list.lock);
        return NULL;
    }

    for (size_t i = 0; i < num_requests; ++i) {
        request_list.requests[request_list.size + i] = &new_requests[i];
    }
    request_list.size += num_requests;

    pthread_mutex_unlock(&request_list.lock);

    free(new_requests);
    return NULL;
}

void initialize_measurement_system(int* region_ids, size_t count) {
    pthread_t threads[NUM_THREADS];

    // Create threads to generate measurement requests
    for (size_t i = 0; i < count && i < NUM_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, generate_measurement_requests, &region_ids[i])) {
            fprintf(stderr, "Error creating thread\n");
            return;
        }
    }

    // Wait for all threads to complete
    for (size_t i = 0; i < count && i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    int regions[] = {1, 2, 3}; // Example region IDs

    initialize_measurement_system(regions, sizeof(regions)/sizeof(int));

    // Cleanup
    pthread_mutex_lock(&request_list.lock);

    for (size_t i = 0; i < request_list.size; ++i) {
        for (size_t j = 0; j < request_list.requests[i]->num_neighbors; ++j) {
            free(request_list.requests[i]->neighbor_cells[j].cell_id);
        }
        free(request_list.requests[i]->neighbor_cells);
    }

    free(request_list.requests);

    pthread_mutex_unlock(&request_list.lock);
    return 0;
}
