#define MAX_DATA_POINTS 100000
#define MEMORY_THRESHOLD_MB 1024 // Example threshold in MB

typedef struct {
    int timestamp;
    double air_quality;
    double temperature;
    double humidity;
} SensorData;

typedef struct {
    int key;
    long offset;
    SensorData data[MAX_DATA_POINTS];
} Record;

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize OpenSSL
void init_openssl() {
    SSL_load_error_strings();
    OpenSSL_add_ssl_algorithms();
}

// Function to cleanup OpenSSL
void cleanup_openssl() {
    EVP_cleanup();
}

// Dynamic memory allocation and initialization function
Record* allocate_and_initialize_records(size_t num_records, int random_range) {
    if (num_records > MAX_DATA_POINTS) {
        fprintf(stderr, "Exceeded maximum data points limit.\n");
        return NULL;
    }

    size_t total_memory = sizeof(Record) * num_records;
    // Check memory threshold
    if ((total_memory / (1024 * 1024)) > MEMORY_THRESHOLD_MB) {
        fprintf(stderr, "Memory allocation exceeds threshold.\n");
        return NULL;
    }

    Record* records = (Record*)calloc(num_records, sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records.");
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        records[i].key = rand() % random_range;
        records[i].offset = rand();
        pthread_mutex_lock(&mutex);
        for (int j = 0; j < MAX_DATA_POINTS; ++j) {
            records[i].data[j].timestamp = rand(); // Mock data
            records[i].data[j].air_quality = rand() % 100;
            records[i].data[j].temperature = rand() % 50 + (-10);
            records[i].data[j].humidity = rand() % 100;
        }
        pthread_mutex_unlock(&mutex);
    }

    return records;
}

// Function to serialize data into a binary format
int serialize_data(Record* record, size_t num_records, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing.");
        return -1;
    }

    pthread_mutex_lock(&mutex);
    fwrite(record, sizeof(Record), num_records, file);
    pthread_mutex_unlock(&mutex);

    fclose(file);
    return 0;
}

// Function to handle concurrent data updates and access
void* update_data(void* arg) {
    Record* record = (Record*)arg;

    pthread_mutex_lock(&mutex);
    // Mock update logic
    for (int i = 0; i < MAX_DATA_POINTS; ++i) {
        record->data[i].air_quality += 1.0;
        record->data[i].temperature += 0.5;
        record->data[i].humidity += 2.0;
    }
    pthread_mutex_unlock(&mutex);

    return NULL;
}

// Function to simulate HTTP request handling with retry logic
int fetch_data_with_retry(const char* url, int max_retries) {
    for (int attempt = 0; attempt < max_retries; ++attempt) {
        // Simulate network request
        if (rand() % 2 == 0) { // Random success/failure
            printf("Data fetched successfully from %s\n", url);
            return 0;
        } else {
            fprintf(stderr, "Failed to fetch data. Retrying...\n");
        }
    }

    fprintf(stderr, "Max retries reached. Could not fetch data.\n");
    return -1;
}

int main() {
    init_openssl();

    size_t num_records = 1000;
    int random_range = 10000;

    Record* records = allocate_and_initialize_records(num_records, random_range);
    if (!records) {
        cleanup_openssl();
        return EXIT_FAILURE;
    }

    // Serialize data to a binary file
    if (serialize_data(records, num_records, "data.bin") != 0) {
        free(records);
        cleanup_openssl();
        return EXIT_FAILURE;
    }

    // Simulate concurrent updates
    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, update_data, records);
    }
    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Simulate HTTP request handling
    fetch_data_with_retry("http://example.com/api/data", 3);

    free(records);
    cleanup_openssl();
    return EXIT_SUCCESS;
}
