['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <zlib.h>
#include <stdbool.h>

#define INITIAL_CACHE_SIZE 1024

typedef struct {
    char *key;
    char *value;
    time_t expiration_timestamp;
    char *metadata;
} CACHE_ITEM_T;

typedef struct CacheNode {
    CACHE_ITEM_T item;
    struct CacheNode *next;
} CacheNode;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    CacheNode *head;
    size_t current_size;
    FILE *log_file;
} Cache;

// Function declarations
void init_cache(Cache *cache, size_t initial_capacity);
int store_item(Cache *cache, const char *key, const char *value, time_t expiration, const char *metadata);
CACHE_ITEM_T* retrieve_item(Cache *cache, const char *key);
void evict_expired_items(Cache *cache);
void log_operation(const Cache *cache, const char *operation, const CACHE_ITEM_T *item);
void export_cache_to_file(const Cache *cache, const char *filename, int compression_level);
void compress_data(void *data, size_t data_size, void **compressed_data, size_t *compressed_size, int level);

// Initialize the cache
void init_cache(Cache *cache, size_t initial_capacity) {
    pthread_mutex_init(&cache->lock, NULL);
    cache->capacity = initial_capacity;
    cache->head = NULL;
    cache->current_size = 0;
    cache->log_file = fopen("cache_log.txt", "a");
}

// Store an item in the cache
int store_item(Cache *cache, const char *key, const char *value, time_t expiration, const char *metadata) {
    pthread_mutex_lock(&cache->lock);

    // Check for duplicate key
    CacheNode *current = cache->head;
    while (current != NULL) {
        if (strcmp(current->item.key, key) == 0) {
            pthread_mutex_unlock(&cache->lock);
            return -1; // Duplicate key found
        }
        current = current->next;
    }

    // Create new item
    CacheNode *new_node = malloc(sizeof(CacheNode));
    if (!new_node) {
        pthread_mutex_unlock(&cache->lock);
        return -2; // Memory allocation failed
    }
    new_node->item.key = strdup(key);
    new_node->item.value = strdup(value);
    new_node->item.expiration_timestamp = expiration;
    new_node->item.metadata = metadata ? strdup(metadata) : NULL;

    // Insert at head for LRU policy
    new_node->next = cache->head;
    cache->head = new_node;
    cache->current_size++;

    log_operation(cache, "INSERT", &new_node->item);

    pthread_mutex_unlock(&cache->lock);
    return 0; // Success
}

// Retrieve an item from the cache
CACHE_ITEM_T* retrieve_item(Cache *cache, const char *key) {
    pthread_mutex_lock(&cache->lock);

    CacheNode *current = cache->head;
    while (current != NULL) {
        if (strcmp(current->item.key, key) == 0 && current->item.expiration_timestamp > time(NULL)) {
            log_operation(cache, "RETRIEVE", &current->item);
            pthread_mutex_unlock(&cache->lock);
            return &current->item;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&cache->lock);
    return NULL; // Not found or expired
}

// Evict expired items from the cache
void evict_expired_items(Cache *cache) {
    pthread_mutex_lock(&cache->lock);

    time_t now = time(NULL);
    CacheNode **current = &cache->head;
    while (*current != NULL) {
        if ((*current)->item.expiration_timestamp <= now) {
            CacheNode *to_delete = *current;
            log_operation(cache, "EVICT", &to_delete->item);

            *current = to_delete->next;
            free(to_delete->item.key);
            free(to_delete->item.value);
            free(to_delete->item.metadata);
            free(to_delete);

            cache->current_size--;
        } else {
            current = &(*current)->next;
        }
    }

    pthread_mutex_unlock(&cache->lock);
}

// Log cache operations
void log_operation(const Cache *cache, const char *operation, const CACHE_ITEM_T *item) {
    if (cache && item && cache->log_file) {
        fprintf(cache->log_file, "%s - Key: %s, Value: %s, Timestamp: %ld\n",
                operation, item->key, item->value, item->expiration_timestamp);
        fflush(cache->log_file);
    }
}

// Export the cache to a file with optional compression
void export_cache_to_file(const Cache *cache, const char *filename, int compression_level) {
    pthread_mutex_lock((pthread_mutex_t*)&cache->lock);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        pthread_mutex_unlock((pthread_mutex_t*)&cache->lock);
        return;
    }

    for (CacheNode *current = cache->head; current != NULL; current = current->next) {
        size_t data_size = strlen(current->item.key) + strlen(current->item.value) + 1;
        char *data = malloc(data_size);
        if (!data) continue;

        snprintf(data, data_size, "%s:%s", current->item.key, current->item.value);

        void *compressed_data = NULL;
        size_t compressed_size = 0;
        compress_data(data, data_size, &compressed_data, &compressed_size, compression_level);

        fwrite(compressed_data, 1, compressed_size, file);
        free(compressed_data);
        free(data);
    }

    fclose(file);
    pthread_mutex_unlock((pthread_mutex_t*)&cache->lock);
}

// Compress data using zlib
void compress_data(void *data, size_t data_size, void **compressed_data, size_t *compressed_size, int level) {
    uLongf dest_size = compressBound(data_size);
    *compressed_data = malloc(dest_size);
    if (*compressed_data) {
        compress2((Bytef *)*compressed_data, &dest_size, (const Bytef *)data, data_size, level);
        *compressed_size = dest_size;
    }
}

// Clean up cache resources
void destroy_cache(Cache *cache) {
    pthread_mutex_lock(&cache->lock);

    CacheNode *current = cache->head;
    while (current != NULL) {
        CacheNode *to_delete = current;
        current = current->next;

        free(to_delete->item.key);
        free(to_delete->item.value);
        free(to_delete->item.metadata);
        free(to_delete);
    }

    fclose(cache->log_file);
    pthread_mutex_unlock(&cache->lock);
    pthread_mutex_destroy(&cache->lock);
}
