#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ID_LEN 256
#define POOL_SIZE 10000000

typedef struct Item {
    char identifier[MAX_ID_LEN];
    int value;
    time_t last_accessed;
    struct Item* next;
} Item;

typedef struct Pool {
    Item** buckets;
    pthread_mutex_t locks[POOL_SIZE];
} Pool;

unsigned long hash(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % POOL_SIZE;
}

Pool* create_pool() {
    Pool* pool = (Pool*)malloc(sizeof(Pool));
    pool->buckets = (Item**)calloc(POOL_SIZE, sizeof(Item*));
    for (int i = 0; i < POOL_SIZE; ++i) {
        pthread_mutex_init(&pool->locks[i], NULL);
    }
    return pool;
}

void free_pool(Pool* pool) {
    for (int i = 0; i < POOL_SIZE; ++i) {
        Item* item = pool->buckets[i];
        while (item) {
            Item* next = item->next;
            free(item);
            item = next;
        }
    }
    free(pool->buckets);
    for (int i = 0; i < POOL_SIZE; ++i) {
        pthread_mutex_destroy(&pool->locks[i]);
    }
    free(pool);
}

void add_item(Pool* pool, const char *identifier, int value) {
    unsigned long index = hash(identifier);
    pthread_mutex_lock(&pool->locks[index]);

    Item* item = (Item*)malloc(sizeof(Item));
    strncpy(item->identifier, identifier, MAX_ID_LEN);
    item->value = value;
    time(&(item->last_accessed));

    item->next = pool->buckets[index];
    pool->buckets[index] = item;

    pthread_mutex_unlock(&pool->locks[index]);
}

void update_item(Pool* pool, const char *identifier, int new_value) {
    unsigned long index = hash(identifier);
    pthread_mutex_lock(&pool->locks[index]);

    Item* item = pool->buckets[index];
    while (item) {
        if (strcmp(item->identifier, identifier) == 0) {
            item->value = new_value;
            time(&(item->last_accessed));
            break;
        }
        item = item->next;
    }

    pthread_mutex_unlock(&pool->locks[index]);
}

void remove_item(Pool* pool, const char *identifier) {
    unsigned long index = hash(identifier);
    pthread_mutex_lock(&pool->locks[index]);

    Item* current = pool->buckets[index];
    Item* prev = NULL;

    while (current) {
        if (strcmp(current->identifier, identifier) == 0) {
            if (prev) {
                prev->next = current->next;
            } else {
                pool->buckets[index] = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&pool->locks[index]);
}

Item* get_item(Pool* pool, const char *identifier) {
    unsigned long index = hash(identifier);
    pthread_mutex_lock(&pool->locks[index]);

    Item* item = pool->buckets[index];
    while (item) {
        if (strcmp(item->identifier, identifier) == 0) {
            time(&(item->last_accessed));
            pthread_mutex_unlock(&pool->locks[index]);
            return item;
        }
        item = item->next;
    }

    pthread_mutex_unlock(&pool->locks[index]);
    return NULL;
}

Item* get_most_recently_accessed(Pool* pool) {
    Item* most_recent = NULL;

    for (int i = 0; i < POOL_SIZE; ++i) {
        pthread_mutex_lock(&pool->locks[i]);

        Item* item = pool->buckets[i];
        while (item) {
            if (!most_recent || item->last_accessed > most_recent->last_accessed) {
                most_recent = item;
            }
            item = item->next;
        }

        pthread_mutex_unlock(&pool->locks[i]);
    }

    return most_recent;
}

// Example usage
int main() {
    Pool* pool = create_pool();

    add_item(pool, "item1", 100);
    update_item(pool, "item1", 200);

    Item* item = get_item(pool, "item1");
    if (item) {
        printf("Item: %s, Value: %d\n", item->identifier, item->value);
    }

    remove_item(pool, "item1");

    free_pool(pool);
    return 0;
}
```

### Key Considerations:

- **Hashing**: The hash function is designed to minimize collisions and distribute identifiers evenly across the pool.
- **Concurrency**: Each bucket has its own mutex to allow concurrent access while minimizing contention.
- **Memory Management**: Items are dynamically allocated and freed, with a focus on minimizing fragmentation through careful management of linked lists within each bucket.
- **Performance**: The design balances time complexity (O(1) average for add/update/remove) with space efficiency by using separate chaining for collision resolution.
- **Cache Efficiency**: The use of fixed-size structures helps optimize cache usage, especially when accessing items in the same bucket.

This implementation can be integrated into larger applications by exposing functions to manage the pool and interfacing with external data sources as needed. Considerations for integration include handling large datasets efficiently and ensuring thread safety across different parts of the application.']

