    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < num_elements; ++i) {
        (*array)[i].RX_UE_INFORMATION_TAG = MIN_RX_UE_INFO_TAG + rand() % (MAX_RX_UE_INFO_TAG - MIN_RX_UE_INFO_TAG + 1);
