#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <thread>
#include <mutex>
#include <sqlite3.h>
#include <fstream>
#include <chrono>
#include <queue>

// RandomRecordGenerator class using Mersenne Twister
class RandomRecordGenerator {
public:
    RandomRecordGenerator(size_t size) : size_(size), mt_(std::random_device()()) {}

    ~RandomRecordGenerator() = default;

    // Move semantics for efficient data handling
    RandomRecordGenerator(RandomRecordGenerator&& other) noexcept 
        : size_(other.size_), offsets_(std::move(other.offsets_)), keys_(std::move(other.keys_)), records_(std::move(other.records_)) {}

    RandomRecordGenerator& operator=(RandomRecordGenerator&& other) noexcept {
        if (this != &other) {
            size_ = other.size_;
            offsets_ = std::move(other.offsets_);
            keys_ = std::move(other.keys_);
            records_ = std::move(other.records_);
        }
        return *this;
    }

    struct Record {
        int value;
    };

    void generate() {
        try {
            offsets_ = new long[size_];
            keys_ = new int[size_];
            records_ = new Record[size_];

            for (size_t i = 0; i < size_; ++i) {
                offsets_[i] = mt_(std::uniform_int_distribution<long>(-10000, 10000));
                keys_[i] = mt_(std::uniform_int_distribution<int>(-1000, 1000));

                records_[i].value = mt_(std::uniform_int_distribution<int>(1, 100));
            }

            std::vector<size_t> indices(size_);
            std::iota(indices.begin(), indices.end(), 0);
            std::sort(indices.begin(), indices.end(),
                      [this](size_t a, size_t b) { return keys_[a] < keys_[b]; });

            for (size_t i = 0; i < size_; ++i) {
                records_[i] = records_[indices[i]];
                keys_[i] = keys_[indices[i]];
            }
        } catch (...) {
            delete[] offsets_;
            delete[] keys_;
            delete[] records_;
            throw;
        }
    }

private:
    size_t size_;
    long* offsets_ = nullptr;
    int* keys_ = nullptr;
    Record* records_ = nullptr;
    std::mt19937 mt_;
};

// Function to find and print the k-th largest integer
void kthLargest(int k, const std::vector<int>& data) {
    if (k <= 0 || k > data.size()) return;

    auto comp = [&data](int a, int b) { return data[a] < data[b]; };
    std::priority_queue<int, std::vector<int>, decltype(comp)> pq(comp);

    for (size_t i = 0; i < data.size(); ++i)
        pq.push(i);

    for (int i = 1; i < k; ++i)
        pq.pop();

    std::cout << "The " << k << "-th largest integer is: " << data[pq.top()] << "\n";
}

// SQLite database integration
class SQLiteDatabase {
public:
    SQLiteDatabase(const std::string& db_path) : db_path_(db_path) {
        if (sqlite3_open(db_path_.c_str(), &db_) != SQLITE_OK) {
            throw std::runtime_error("Can't open database");
        }
    }

    ~SQLiteDatabase() {
        sqlite3_close(db_);
    }

    void createTable(const std::string& query) {
        char* err_msg = nullptr;
        if (sqlite3_exec(db_, query.c_str(), 0, 0, &err_msg) != SQLITE_OK) {
            std::string error(err_msg);
            sqlite3_free(err_msg);
            throw std::runtime_error("SQL error: " + error);
        }
    }

    void insertRecords(const RandomRecordGenerator::Record* records, size_t count) {
        std::mutex mtx;
        for (size_t i = 0; i < count; ++i) {
            std::lock_guard<std::mutex> lock(mtx);
            std::string query = "INSERT INTO Records (value) VALUES (" + std::to_string(records[i].value) + ");";
            char* err_msg = nullptr;
            if (sqlite3_exec(db_, query.c_str(), 0, 0, &err_msg) != SQLITE_OK) {
                std::string error(err_msg);
                sqlite3_free(err_msg);
                throw std::runtime_error("SQL error: " + error);
            }
        }
    }

private:
    std::string db_path_;
    sqlite3* db_ = nullptr;
};

// Logging mechanism
class Logger {
public:
    void log(const std::string& message) {
        std::lock_guard<std::mutex> lock(mtx_);
        log_queue_.push(message);
        if (log_queue_.size() > 10) {
            log_queue_.pop();
        }

        // Write to file or console
        std::ofstream logfile("logfile.txt", std::ios_base::app);
        logfile << message << "\n";
    }

private:
    std::mutex mtx_;
    std::queue<std::string> log_queue_;
};

int main() {
    try {
        RandomRecordGenerator generator(1000);
        generator.generate();

        SQLiteDatabase db("records.db");
        db.createTable("CREATE TABLE IF NOT EXISTS Records (value INT);");

        db.insertRecords(generator.records_, 1000);

        std::vector<int> input_data = {5, 3, 8, 9, 1};
        kthLargest(2, input_data);

    } catch (const std::exception& e) {
        Logger().log(std::string("Error: ") + e.what());
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
