#include <pthread.h>

#define MAX_LOG_SIZE (1 * 1024 * 1024) // 1 MB
#define FREQUENCY_BAND_MIN_RNTI 0x0000
#define FREQUENCY_BAND_MAX_RNTI 0xFFFF
#define LOG_FILE_NAME "audit_log.txt"

typedef struct {
    uint16_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint32_t RNTI;
    // Other fields...
} RX_UE_INFORMATION_TAG;

