    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;

int validate_rnti(uint32_t rnti) {
    return (rnti >= FREQUENCY_BAND_MIN_RNTI && rnti <= FREQUENCY_BAND_MAX_RNTI);
}

void append_log(const char *message) {
    FILE *file;
    pthread_mutex_lock(&log_lock);

    // Check if the current log file size exceeds MAX_LOG_SIZE
    struct stat st;
    if (stat(LOG_FILE_NAME, &st) == 0 && st.st_size >= MAX_LOG_SIZE) {
        // Archive or truncate old entries. Here we'll simply truncate.
        freopen(">>" LOG_FILE_NAME, "w", stdout);
        printf("\nLog file truncated due to size limit.\n");
    }

    file = fopen(LOG_FILE_NAME, "a");
    if (file != NULL) {
        fprintf(file, "%s\n", message);
        fclose(file);
    }

    pthread_mutex_unlock(&log_lock);
}

void *create_and_log_pdu(void *arg) {
    int num_pdus = *(int *)arg;
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) return NULL;

    for (int i = 0; i < num_pdus; ++i) {
        pdus[i].rx_ue_info_tag.RNTI = rand() % (FREQUENCY_BAND_MAX_RNTI + 1);

        if (!validate_rnti(pdus[i].rx_ue_info_tag.RNTI)) continue;

        pdus[i].rnti = pdus[i].rx_ue_info_tag.RNTI;
        pdus[i].crc_indication_rel8_tag.CRCFLAG = i % 2; // Sample CRCFLAG value

        char log_message[256];
        snprintf(log_message, sizeof(log_message), "PDU %d: RNTI=%u, CRCFLAG=%u", 
                 i, pdus[i].rnti, pdus[i].crc_indication_rel8_tag.CRCFLAG);

        append_log(log_message);
    }

    free(pdus);
    return NULL;
}

int main() {
    int num_pdus = 1000; // Example number of PDUs
    create_and_log_pdu(&num_pdus);

    pthread_mutex_destroy(&log_lock);
    return 0;
}
```

