void serialize_records(const char *filename, record *records, size_t count) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Error opening file for writing");
        return;
    }

    // Write the number of records to the file
    fwrite(&count, sizeof(size_t), 1, file);

    // Write each record to the file
    for (size_t i = 0; i < count; ++i) {
        fwrite(&(records[i].value), sizeof(int), 1, file);
    }

    fclose(file);
}

int deserialize_records(const char *filename, record **records) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Error opening file for reading");
        return -1;
    }

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    *records = malloc(count * sizeof(record));
    if (!*records) {
        perror("Memory allocation failed");
        fclose(file);
        return -1;
    }

    for (size_t i = 0; i < count; ++i) {
