['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    long *offset;
} record;

record* initialize_records(int initial_size, const long* offsets, const int* keys, int max_records, int random_range_min, int random_range_max) {
    if (initial_size <= 0 || initial_size > max_records || random_range_max < random_range_min) {
        return NULL; // Invalid input sizes or range
    }

    record *records = (record*)malloc(initial_size * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    for (int i = 0; i < initial_size; ++i) {
        records[i].value = keys ? keys[i] : rand() % (random_range_max - random_range_min + 1) + random_range_min;
        records[i].offset = (long*)malloc(sizeof(long));
        if (!records[i].offset) {
            perror("Failed to allocate memory for offset");
            // Clean up already allocated resources
            for (int j = 0; j < i; ++j) {
                free(records[j].offset);
            }
            free(records);
            return NULL;
        }
        *records[i].offset = offsets ? offsets[i] : -1; // Default to -1 if no offset provided
    }

    return records;
}

void add_record(record **records, int current_size, long new_offset, int max_records, int random_range_min, int random_range_max) {
    if (current_size >= max_records) {
        fprintf(stderr, "Maximum number of records reached.\n");
        return;
    }

    // Reallocate memory for one more record
    *records = (record*)realloc(*records, (current_size + 1) * sizeof(record));
    if (!*records) {
        perror("Failed to reallocate memory for records");
        return;
    }

    (*records)[current_size].value = rand() % (random_range_max - random_range_min + 1) + random_range_min;
    (*records)[current_size].offset = (long*)malloc(sizeof(long));
    if (!(*records)[current_size].offset) {
        perror("Failed to allocate memory for offset");
        // Clean up the newly added record
        free((*records)[current_size].value);
        free(*records);
        return;
    }
    *(*records)[current_size].offset = new_offset;

    current_size++;
}

void cleanup_records(record *records, int size) {
    if (!records) return;
    for (int i = 0; i < size; ++i) {
        free(records[i].offset);
    }
    free(records);
}

