        return EXIT_FAILURE;
    }

    add_record(&records, initial_size, 60, max_records, random_range_min, random_range_max);
    // Add more records as needed

    cleanup_records(records, (initial_size + 1)); // Adjust size accordingly
    return EXIT_SUCCESS;
}
