['```c
#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
#include <time.h>

#define MAX_MEMORY_USAGE 10485760 // Maximum memory usage (10 MB for example)
#define RANGESIZE 100

typedef struct ListNode {
    short value;
    struct ListNode* next;
} ListNode;

typedef struct Record {
    int key;
    double floating_value;
    ListNode* linked_list_head;
} Record;

typedef struct RecordCollection {
    size_t record_count;
    Record** records;
    pthread_mutex_t mutex;
} RecordCollection;

// Function prototypes
RecordCollection* create_record_collection(size_t count);
void destroy_record_collection(RecordCollection* collection);
int add_random_value_to_record(double min, double max, Record* record);
void serialize_records(const char* filename, RecordCollection* collection);
int deserialize_records(const char* filename, RecordCollection* collection);
void log_memory_operation(const char* operation, const char* info);

// Function implementations

RecordCollection* create_record_collection(size_t count) {
    if (count * sizeof(Record*) > MAX_MEMORY_USAGE) return NULL;

    RecordCollection* collection = malloc(sizeof(RecordCollection));
    if (!collection) {
        log_memory_operation("malloc", "Failed to allocate RecordCollection");
        return NULL;
    }

    collection->record_count = count;
    collection->records = calloc(count, sizeof(Record*));
    pthread_mutex_init(&collection->mutex, NULL);

    for (size_t i = 0; i < count; ++i) {
        collection->records[i] = malloc(sizeof(Record));
        if (!collection->records[i]) {
            log_memory_operation("malloc", "Failed to allocate Record");
            destroy_record_collection(collection);
            return NULL;
        }

        collection->records[i]->key = (int)i;
        collection->records[i]->linked_list_head = NULL;
        add_random_value_to_record(0.0, 100.0, collection->records[i]);
    }

    log_memory_operation("malloc", "Successfully allocated RecordCollection");
    return collection;
}

void destroy_record_collection(RecordCollection* collection) {
    if (!collection) return;

    pthread_mutex_lock(&collection->mutex);
    for (size_t i = 0; i < collection->record_count; ++i) {
        ListNode* current = collection->records[i]->linked_list_head;
        while (current) {
            ListNode* next = current->next;
            free(current);
            log_memory_operation("free", "Freed ListNode");
            current = next;
        }
        free(collection->records[i]);
        log_memory_operation("free", "Freed Record");
    }

    free(collection->records);
    pthread_mutex_unlock(&collection->mutex);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
    log_memory_operation("free", "Successfully freed all resources in RecordCollection");
}

int add_random_value_to_record(double min, double max, Record* record) {
    if (!record) return -1;

    record->floating_value = (double)rand() / RAND_MAX * (max - min) + min;

    ListNode* new_node = malloc(sizeof(ListNode));
    if (!new_node) {
        log_memory_operation("malloc", "Failed to allocate ListNode");
        return -1;
    }

    new_node->value = rand() % RANGESIZE;
    new_node->next = record->linked_list_head;
    record->linked_list_head = new_node;

    log_memory_operation("malloc", "Successfully added a new ListNode");
    return 0;
}

void serialize_records(const char* filename, RecordCollection* collection) {
    if (!filename || !collection) return;

    FILE *file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&collection->mutex);
    fwrite(&collection->record_count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < collection->record_count; ++i) {
        Record* record = collection->records[i];
        fwrite(&record->key, sizeof(int), 1, file);
        fwrite(&record->floating_value, sizeof(double), 1, file);

        int list_size = 0;
        ListNode* current = record->linked_list_head;
        while (current) {
            ++list_size;
            current = current->next;
        }

        fwrite(&list_size, sizeof(int), 1, file);

        for (int j = 0; j < list_size; ++j) {
            current = record->linked_list_head;
            for (int k = 0; k < j; ++k) {
                current = current->next;
            }

            fwrite(&current->value, sizeof(short), 1, file);
        }
    }

    pthread_mutex_unlock(&collection->mutex);
    fclose(file);

    log_memory_operation("serialization", "Successfully serialized records to file");
}

int deserialize_records(const char* filename, RecordCollection* collection) {
    if (!filename || !collection) return -1;

    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    pthread_mutex_lock(&collection->mutex);
    for (size_t i = 0; i < count; ++i) {
        Record* record = collection->records[i];

        fread(&record->key, sizeof(int), 1, file);
        fread(&record->floating_value, sizeof(double), 1, file);

        int list_size;
        fread(&list_size, sizeof(int), 1, file);

        ListNode* current = NULL;
        for (int j = 0; j < list_size; ++j) {
            short value;

            if (j == 0) {
                record->linked_list_head = malloc(sizeof(ListNode));
                if (!record->linked_list_head) return -1;
                current = record->linked_list_head;
            } else {
                ListNode* new_node = malloc(sizeof(ListNode));
                if (!new_node) return -1;
                current->next = new_node;
                current = new_node;
            }

            fread(&value, sizeof(short), 1, file);
            current->value = value;
            current->next = NULL;
        }
    }

    pthread_mutex_unlock(&collection->mutex);
    fclose(file);

    log_memory_operation("deserialization", "Successfully deserialized records from file");
    return 0;
}

void log_memory_operation(const char* operation, const char* info) {
    // This is a placeholder for the logging mechanism
    printf("%s: %s\n", operation, info);
}
