    char config_params[256];
    MeasurementReport* measurement_list_head;
} UECtx;

int initialize_ue_contexts(UECtx** ue_ctx_array, size_t ue_count) {
    if (ue_ctx_array == NULL || ue_count > MAX_UE_COUNT) {
        fprintf(stderr, "Invalid UE context array or count.\n");
        return -1;
    }

    *ue_ctx_array = malloc(ue_count * sizeof(UECtx));
    if (*ue_ctx_array == NULL) {
        perror("Failed to allocate memory for UE contexts");
        return -2;
    }

    for (size_t i = 0; i < ue_count; ++i) {
        UECtx* ctx = &((*ue_ctx_array)[i]);

        // Initialize unique UE identifier
        ctx->ue_id = i + 1;

        // Initialize configuration parameters
        strncpy(ctx->config_params, DEFAULT_CONFIG, sizeof(ctx->config_params));
        ctx->config_params[sizeof(ctx->config_params) - 1] = '\0';

        // Initialize measurement reports linked list with random data
        MeasurementReport* current = NULL;
        for (int j = 0; j < MEASUREMENT_REPORT_SIZE; ++j) {
            MeasurementReport* report = malloc(sizeof(MeasurementReport));
            if (report == NULL) {
                perror("Failed to allocate memory for measurement report");
                // Free previously allocated reports in case of failure
                while (current != NULL) {
                    MeasurementReport* temp = current;
                    current = current->next;
                    free(temp);
                }
                return -3;
            }

            report->report_id = rand() % 1000;  // Example random id
            report->value = (float)(rand() % 100) / 10.0f;  // Random value
            report->next = NULL;

            if (ctx->measurement_list_head == NULL) {
                ctx->measurement_list_head = report;
            } else {
                current->next = report;
            }

            current = report;
        }

        // Retry mechanism or fallback strategy could be implemented here
    }

    return 0;
}

void free_ue_contexts(UECtx* ue_ctx_array, size_t ue_count) {
    if (ue_ctx_array == NULL) return;

    for (size_t i = 0; i < ue_count; ++i) {
        MeasurementReport* current = ue_ctx_array[i].measurement_list_head;
        while (current != NULL) {
            MeasurementReport* temp = current;
            current = current->next;
            free(temp);
        }
    }

    free(ue_ctx_array);
}

int main() {
    UECtx* ue_ctx_array = NULL;

    if (initialize_ue_contexts(&ue_ctx_array, 10) != 0) {
        fprintf(stderr, "Failed to initialize UE contexts.\n");
        return -1;
    }

    // Usage of the UE context array...

    free_ue_contexts(ue_ctx_array, 10);

    return 0;
}
