#include <time.h>

// Define a structure for linked list nodes to store measurement data.
typedef struct Node {
    float temperature;
    char *label;
    struct Node *next;
} Node;

// Function prototypes
Node* createLinkedList(int size, const char *range, const char *source_file);
void freeLinkedList(Node *head);
void serializeLinkedList(const char *filename, Node *head);
Node* deserializeLinkedList(const char *filename);
float randomTemperature(float min, float max);
char** readLabelsFromFile(const char *filename, int *count);

// Main function to demonstrate functionality
int main() {
    // Example usage of the create and manage linked list.
    int size;

    printf("Enter the number of temperature readings: ");
    if (scanf("%d", &size) != 1 || size <= 0) {
        fprintf(stderr, "Invalid input. Exiting.\n");
        return EXIT_FAILURE;
    }

    Node *temperatureList = createLinkedList(size, "20-30", "labels.txt");
    if (!temperatureList) {
        fprintf(stderr, "Failed to create linked list. Exiting.\n");
        return EXIT_FAILURE;
    }

    serializeLinkedList("measurements.bin", temperatureList);
    Node *deserializedList = deserializeLinkedList("measurements.bin");

    // Free the linked lists
    freeLinkedList(temperatureList);
    freeLinkedList(deserializedList);

    return 0;
}

// Function to create and initialize a linked list with random temperatures and labels.
Node* createLinkedList(int size, const char *range, const char *source_file) {
    if (size <= 0 || !source_file) return NULL;

    // Parse the range for temperature
    float min = strtof(strtok((char *)range, "-"), NULL);
    float max = strtof(strtok(NULL, "-"), NULL);

    // Allocate memory for labels and read from file
    int labelCount;
    char **labels = readLabelsFromFile(source_file, &labelCount);
    if (!labels) {
        fprintf(stderr, "Failed to read labels. Exiting.\n");
        return NULL;
    }

    Node *head = NULL, *current = NULL;

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < size; ++i) {
        Node *newNode = malloc(sizeof(Node));
        if (!newNode) {
            fprintf(stderr, "Memory allocation failed. Exiting.\n");
            freeLinkedList(head);
            return NULL;
        }

        // Randomly assign temperature and label
        newNode->temperature = randomTemperature(min, max);
        newNode->label = labels[i % labelCount];
        newNode->next = NULL;

        if (!head) {
            head = newNode;
        } else {
            current->next = newNode;
        }
        current = newNode;
    }

    return head;
}

// Function to free the linked list
void freeLinkedList(Node *head) {
    Node *current = head;
    while (current) {
        Node *temp = current;
        current = current->next;
        free(temp);
    }
}

// Function to serialize a linked list to a binary file.
void serializeLinkedList(const char *filename, Node *head) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    Node *current = head;
    while (current) {
        fwrite(&current->temperature, sizeof(float), 1, file);
        size_t len = strlen(current->label) + 1; // Include null terminator
        fwrite(&len, sizeof(size_t), 1, file);   // Write length of the label
        fwrite(current->label, sizeof(char), len, file);
        current = current->next;
    }

    fclose(file);
}

// Function to deserialize a linked list from a binary file.
Node* deserializeLinkedList(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return NULL;
    }

    Node *head = NULL, *current = NULL;

    while (1) {
        float temperature;
        size_t len;

        // Attempt to read a floating-point temperature and label length
        if (fread(&temperature, sizeof(float), 1, file) != 1 || fread(&len, sizeof(size_t), 1, file) != 1)
            break; // End of file or error

        char *label = malloc(len);
        if (!label) {
            fprintf(stderr, "Memory allocation failed. Exiting.\n");
            freeLinkedList(head);
            fclose(file);
            return NULL;
        }

        if (fread(label, sizeof(char), len, file) != len) { // Read the label
            free(label);
            break; // Error occurred during reading
        }

        Node *newNode = malloc(sizeof(Node));
        if (!newNode) {
            fprintf(stderr, "Memory allocation failed. Exiting.\n");
            free(label);
            freeLinkedList(head);
            fclose(file);
            return NULL;
        }

        newNode->temperature = temperature;
        newNode->label = label;
        newNode->next = NULL;

        if (!head) {
            head = newNode;
        } else {
            current->next = newNode;
        }
        current = newNode;
    }

    fclose(file);

    return head;
}

// Function to generate a random float within a specified range.
float randomTemperature(float min, float max) {
    return (min + ((max - min) * rand()) / RAND_MAX);
}

// Function to read labels from an external source file.
char** readLabelsFromFile(const char *filename, int *count) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open label file");
        return NULL;
    }

    char **labels = NULL;
    size_t capacity = 10;
    labels = malloc(capacity * sizeof(char *));
    if (!labels) {
        fprintf(stderr, "Memory allocation failed. Exiting.\n");
        fclose(file);
        return NULL;
    }

    *count = 0;

    while (1) {
        char line[256];
        if (fgets(line, sizeof(line), file) == NULL)
            break; // End of file

        size_t len = strlen(line);
        if (len > 0 && line[len - 1] == '\n')
            line[--len] = '\0'; // Remove newline character

        if (*count >= capacity) {
            capacity *= 2;
            labels = realloc(labels, capacity * sizeof(char *));
            if (!labels) {
                fprintf(stderr, "Memory allocation failed. Exiting.\n");
                break;
            }
        }

        labels[*count] = strdup(line);
        if (!labels[*count]) {
            fprintf(stderr, "Memory allocation failed. Exiting.\n");
            // Clean up previously allocated memory
            for (int i = 0; i < *count; ++i) {
                free(labels[i]);
            }
            free(labels);
            break;
        }

        (*count)++;
    }

    fclose(file);

    return labels;
}
