Item* create_item_array(size_t capacity) {
    Item* items = malloc(capacity * sizeof(Item));
    if (!items) {
        perror("Failed to allocate memory for item array");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < capacity; ++i) {
        items[i].string = NULL;
        items[i].value = 0.0;
    }
    return items;
}

void resize_item_array(Item** items, size_t* capacity) {
    pthread_mutex_lock(&lock);
    *capacity *= 2;
    Item* new_items = realloc(*items, (*capacity) * sizeof(Item));
    if (!new_items) {
        perror("Failed to reallocate memory for item array");
        exit(EXIT_FAILURE);
    }
    for (size_t i = *capacity / 2; i < *capacity; ++i) {
        new_items[i].string = NULL;
        new_items[i].value = 0.0;
    }
    *items = new_items;
    pthread_mutex_unlock(&lock);
}

void add_item(Item** items, size_t* count, size_t* capacity, const char* initial_str) {
    if (*count >= *capacity) {
        resize_item_array(items, capacity);
    }

    Item* item = &(*items)[*count];
    item->string = strdup(initial_str); // Allocates memory and copies the string
    item->value = 0.0;
    ++(*count);
}

long long hash_string(const char* str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c

    return (long long)hash;
}

void initialize_data_structures(long** long_offsets, int** int_keys, Item*** items, size_t* item_count) {
    *long_offsets = malloc(LONG_ARRAY_SIZE * sizeof(long));
    if (!*long_offsets) {
        perror("Failed to allocate memory for long offsets array");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < LONG_ARRAY_SIZE; ++i) {
        (*long_offsets)[i] = rand() % 10000;
    }

    *int_keys = malloc(INT_KEYS_ARRAY_SIZE * sizeof(int));
    if (!*int_keys) {
