    }

    *items = create_item_array(ITEM_INITIAL_CAPACITY);
    if (!*items) {
        perror("Failed to initialize item array");
        exit(EXIT_FAILURE);
    }
    *item_count = 0;
}

void free_data_structures(long* long_offsets, int* int_keys, Item** items) {
