#include <iostream>
#include <vector>
#include <mutex>
#include <random>
#include <memory>
#include <thread>
#include <chrono>

// Mock definitions for the purpose of this example.
struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
};

const int MAX_STRUCTURES = 1000;

class GraphDatabaseApplication {
public:
    GraphDatabaseApplication() : success_count_(0) {}

    // Method to manage list of structures.
    void ManageStructures(int N);

    // Release all allocated resources.
    void ReleaseResources();

private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> buffer_;
    int success_count_;
    std::mutex mutex_;

    static const char* LogLevelToString(int level) {
        switch (level) {
            case 0: return "ERROR";
            case 1: return "WARNING";
            case 2: return "INFO";
            case 3: return "DEBUG";
            default: return "UNKNOWN";
        }
    }

    void Log(const std::string& message, int level = 2);

    bool AllocateAndInitialize(int N);
};

void GraphDatabaseApplication::Log(const std::string& message, int level) {
    static const int LOG_LEVEL = 2; // INFO by default
    if (level <= LOG_LEVEL) {
        std::lock_guard<std::mutex> lock(mutex_);
        std::cout << "[" << LogLevelToString(level)
                  << "] " << std::this_thread::get_id() 
                  << ": " << message << std::endl;
    }
}

bool GraphDatabaseApplication::AllocateAndInitialize(int N) {
    if (N <= 0 || N > MAX_STRUCTURES) {
        Log("Invalid input for number of structures.", 0);
        return false;
    }

    buffer_.resize(N);
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> tag_dist(1, 100);
    std::uniform_int_distribution<> rnti_dist(1, 100);
    std::uniform_int_distribution<> crcflag_dist(0, 1);

    for (int i = 0; i < N; ++i) {
        buffer_[i].RX_UE_INFORMATION_TAG = tag_dist(gen);
        buffer_[i].RNTI = rnti_dist(gen);
        buffer_[i].CRC_INDICATION_REL8_TAG.CRCFLAG = crcflag_dist(gen) == 1;
    }

    success_count_ += N;
    Log("Successfully allocated and initialized structures.", 3);
    return true;
}

void GraphDatabaseApplication::ManageStructures(int N) {
    std::lock_guard<std::mutex> lock(mutex_);

    if (!AllocateAndInitialize(N)) {
        Log("Failed to allocate structures.", 0);
    }

    // Simulate asynchronous processing.
    std::thread async_task([this, N]() {
        this->Log("Async task started", 3);

        // Simulate work.
        std::this_thread::sleep_for(std::chrono::milliseconds(100));

        // Log completion of the task.
        this->Log("Async task completed", 2);
    });
    async_task.detach();
}

void GraphDatabaseApplication::ReleaseResources() {
    std::lock_guard<std::mutex> lock(mutex_);
    buffer_.clear();
    success_count_ = 0;
    Log("All resources released.", 1);
}

int main() {
    GraphDatabaseApplication app;

    // Test with varying N values.
    app.ManageStructures(500);
    app.ManageStructures(1000);
    app.ManageStructures(-5); // Invalid case
    app.ReleaseResources();

    return 0;
}
```

### Explanation

1. **Memory Management**: The code uses a `std::vector` to manage the structures, resizing dynamically based on input `N`.

2. **Thread Safety**: A `std::mutex` ensures that shared resources are protected during concurrent access.

3. **Logging**: Implemented logging with different levels (ERROR, WARNING, INFO, DEBUG) controlled by a log level variable.

4. **Random Initialization**: Structures are initialized with random values using the C++ `<random>` library.

5. **Asynchronous Processing**: A separate thread simulates asynchronous work to minimize CPU usage during high-load scenarios.

6. **Resource Management**: Resources are released explicitly through `ReleaseResources`, clearing the buffer and resetting counters.

7. **Error Handling**: The code checks for invalid input values of `N` and logs errors accordingly.']

