#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    time_t seconds;
    long nanoseconds;
} timestamp;

typedef struct {
    float temperature;
    char quality;
    timestamp ts;
} sensor_data;

// Comparator for qsort and bsearch
int compare_sensor_data(const void *a, const void *b) {
    return ((sensor_data *)a)->ts.seconds - ((sensor_data *)b)->ts.seconds;
}

// Linked list node
typedef struct SensorNode {
    sensor_data data;
    struct SensorNode* next;
} SensorNode;

// Linked list structure
typedef struct {
    SensorNode* head;
    pthread_mutex_t lock;
} SensorList;

// Function to initialize a new linked list
SensorList* init_sensor_list() {
    SensorList* list = (SensorList*)malloc(sizeof(SensorList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to add sensor data to the linked list
int add_sensor_data(SensorList* list, sensor_data data) {
    pthread_mutex_lock(&list->lock);

    SensorNode* new_node = (SensorNode*)malloc(sizeof(SensorNode));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to free the linked list
void free_sensor_list(SensorList* list) {
    pthread_mutex_lock(&list->lock);

    SensorNode* current = list->head;
    while (current) {
        SensorNode* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Function to simulate sensor data generation
void generate_sensor_data(SensorList* list, int count) {
    for (int i = 0; i < count; ++i) {
        sensor_data data;
        data.temperature = rand() % 100 + (rand() / (float)RAND_MAX);
        data.quality = 'A' + (rand() % 3); // Quality A, B, or C
        time_t now = time(NULL);
        data.ts.seconds = now - (rand() % 3600); // Random timestamp within the last hour
        data.ts.nanoseconds = rand() % 1000000000;

        add_sensor_data(list, data);
    }
}

// Function to sort sensor data in a linked list
void sort_sensor_list(SensorList* list) {
    pthread_mutex_lock(&list->lock);

    int count = 0;
    SensorNode** array = NULL;

    SensorNode* current = list->head;
    while (current) {
        ++count;
        current = current->next;
    }

    if (count == 0) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    array = (SensorNode**)malloc(count * sizeof(SensorNode*));
    if (!array) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    current = list->head;
    for (int i = 0; i < count; ++i) {
        array[i] = current;
        current = current->next;
    }

    qsort(array, count, sizeof(SensorNode*), compare_sensor_data);

    SensorNode dummy = { .next = NULL };
    SensorNode** tail = &dummy.next;

    for (int i = 0; i < count; ++i) {
        *tail = array[i];
        tail = &array[i]->next;
    }

    list->head = dummy.next;
    free(array);

    pthread_mutex_unlock(&list->lock);
}

// Function to query sensor data within a time range
void query_sensor_data(SensorList* list, time_t start_time, time_t end_time) {
    pthread_mutex_lock(&list->lock);

    SensorNode* current = list->head;
    while (current) {
        if (current->data.ts.seconds >= start_time && current->data.ts.seconds <= end_time) {
            printf("Temperature: %.2f, Quality: %c\n", current->data.temperature, current->data.quality);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Main function for demonstration
int main() {
    SensorList* list = init_sensor_list();
    if (!list) {
        fprintf(stderr, "Failed to initialize sensor list\n");
        return EXIT_FAILURE;
    }

    generate_sensor_data(list, 10);
    sort_sensor_list(list);

    time_t now = time(NULL);
    query_sensor_data(list, now - 3600, now); // Query last hour

    free_sensor_list(list);
    return EXIT_SUCCESS;
}
```

### Key Considerations:
- **Linked List vs. Array**: The linked list is chosen for its flexibility in handling dynamic insertions and deletions without memory fragmentation concerns typical of large arrays.
- **Thread Safety**: Mutex locks ensure thread safety when accessing or modifying the sensor data list.
- **Sorting**: Sorting is done using an array to leverage efficient `qsort`, then re-linking nodes back into the linked list.
- **Memory Management**: Handles allocation failures gracefully and ensures all allocated memory is freed appropriately.']

