void sort_records_by_key(long *offsets, int *keys, record *records, size_t n) {
    for (size_t i = 0; i < n - 1; ++i) {
        for (size_t j = 0; j < n - i - 1; ++j) {
            if (keys[j] > keys[j + 1]) {
                int temp_key = keys[j];
                long temp_offset = offsets[j];
                record temp_record = records[j];

                keys[j] = keys[j + 1];
                offsets[j] = offsets[j + 1];
                records[j] = records[j + 1];

                keys[j + 1] = temp_key;
                offsets[j + 1] = temp_offset;
                records[j + 1] = temp_record;
            }
        }
    }
}

int find_largest_integer(int *array, size_t n) {
    int largest = array[0];
    for (size_t i = 1; i < n; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

