    int count, value;
    scanf("%d", &count);
    *array = safe_malloc(count * sizeof(int));
    if (!*array) return;

    for (size_t i = 0; i < count; ++i) {
        scanf("%d", &value);
        (*array)[i] = value;
    }
    *n = count;
}

int processMediaFile(const char *input_filename, const char *output_filename, int lossless) {
    if (!validate_jpeg(input_filename)) {
