        return ERROR_CODE;
    }

    double start_time = (double)clock() / CLOCKS_PER_SEC;

    size_t n = 100; // Example size
    long *offsets = safe_malloc(n * sizeof(long));
    int *keys = safe_malloc(n * sizeof(int));
    record *records = safe_malloc(n * sizeof(record));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return ERROR_CODE;
    }

    srand(time(NULL));
    for (size_t i = 0; i < n; ++i) {
        offsets[i] = rand() % 1000000;
        keys[i] = rand() % 10000;
        records[i].value = rand() % 1000;
    }

    sort_records_by_key(offsets, keys, records, n);

    int *input_array = NULL;
    size_t input_count = 0;
    process_input_integers(&input_array, &input_count);
    if (input_array) {
        printf("Largest integer: %d\n", find_largest_integer(input_array, input_count));
        free(input_array);
    }

    int conversion_result = convert_jpeg_to_pdf(input_filename, output_filename);
    compress_pdf(output_filename, lossless);

    double end_time = (double)clock() / CLOCKS_PER_SEC;
    log_call_duration(end_time - start_time);

    free(offsets);
    free(keys);
    free(records);

    return conversion_result ? 1 : 0;
}
