["```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_FILENAME_LENGTH 256

typedef struct {
    char *filename;
    int key;
    long offset;
} record;

int initialize_records(int offset_count, int key_count, FILE *file_handle) {
    // Seed random number generator
    srand(time(NULL));

    record *records = NULL;
    char **filenames = NULL;
    int *keys = NULL;
    long *offsets = NULL;

    records = (record *)malloc(offset_count * key_count * sizeof(record));
    if (!records) return -1; // Memory allocation failed

    filenames = (char **)malloc(offset_count * key_count * sizeof(char *));
    if (!filenames) {
        free(records);
        return -2;
    }

    for (int i = 0; i < offset_count * key_count; ++i) {
        filenames[i] = (char *)malloc((MAX_FILENAME_LENGTH + 1) * sizeof(char));
        if (!filenames[i]) {
            for (int j = 0; j <= i; ++j) free(filenames[j]);
            free(filenames);
            free(records);
            return -3;
        }
    }

    keys = (int *)malloc(offset_count * key_count * sizeof(int));
    offsets = (long *)malloc(offset_count * key_count * sizeof(long));

    if (!keys || !offsets) {
        for (int i = 0; i < offset_count * key_count; ++i) free(filenames[i]);
        free(filenames);
        free(keys); if (keys) keys = NULL;
        free(offsets); if (offsets) offsets = NULL;
        free(records);
        return -4;
    }

    for (int i = 0; i < offset_count * key_count; ++i) {
        records[i].filename = filenames[i];

        // Read filename
        if (!fgets(filenames[i], MAX_FILENAME_LENGTH, file_handle)) {
            for (int j = 0; j <= i; ++j) free(filenames[j]);
            free(filenames);
            free(keys);
            free(offsets);
            free(records);
            return -5;
        }

        // Remove newline if present
        size_t len = strlen(filenames[i]);
        if (len > 0 && filenames[i][len-1] == '\n') {
            filenames[i][len-1] = '\0';
        }

        records[i].key = rand() % (100 - 1 + 1) + 1; // Random key in range [1, 100]
        records[i].offset = rand() % ((long)(1e6) - (long)(1e5) + 1) + (long)(1e5); // Random offset in range [1e5, 1e6]

        keys[i] = records[i].key;
        offsets[i] = records[i].offset;
    }

    free(filenames);
    free(keys);
    free(offsets);

    return (int)records; // Return pointer to array of records as int
}
```"]

['Here's an outline with code snippets implementing a dynamic data store using both a linked list and a balanced binary search tree (AVL Tree) in C:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define the node structure for both linked list and AVL tree.
typedef struct Node {
    int key;
    long value;
    struct Node* next;  // For linked list usage
    struct Node* left;  // For AVL tree usage
    struct Node* right; // For AVL tree usage
} Node;

// Define the data store structure with linked list and AVL Tree roots.
typedef struct DataStore {
    Node* head;  // Head of linked list
    Node* avlRoot; // Root of AVL tree
    pthread_mutex_t lock; // Mutex for thread safety
} DataStore;

// Function prototypes for AVL Tree operations (balance, insert, delete, find).
Node* avlInsert(Node* root, int key, long value);
Node* avlFind(Node* root, int key);
Node* avlDelete(Node* root, int key);
int getHeight(Node* node);
int getBalanceFactor(Node* node);
Node* rightRotate(Node* y);
Node* leftRotate(Node* x);
void freeAVLTree(Node* root);

// Function prototypes for linked list operations.
Node* insertLinkedList(DataStore* store, int key, long value);
Node* findInLinkedList(DataStore* store, int key);
void deleteFromLinkedList(DataStore* store, int key);
void freeLinkedList(Node* head);

// Initialize the Data Store
DataStore* initDataStore() {
    DataStore* store = (DataStore*)malloc(sizeof(DataStore));
    if (!store) return NULL;

    store->head = NULL;
    store->avlRoot = NULL;
    pthread_mutex_init(&store->lock, NULL);
    return store;
}

// Insert a key-value pair into both data structures
void insert(DataStore* store, int key, long value) {
    if (!store) return;

    pthread_mutex_lock(&store->lock);

    // Insert in linked list
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate memory for node");
        pthread_mutex_unlock(&store->lock);
        return;
    }
    newNode->key = key;
    newNode->value = value;
    newNode->next = NULL;
    insertLinkedList(store, key, value);

    // Insert in AVL Tree
    store->avlRoot = avlInsert(store->avlRoot, key, value);

    pthread_mutex_unlock(&store->lock);
}

// Retrieve a value by key from both data structures and ensure consistency
long retrieve(DataStore* store, int key) {
    if (!store) return -1;

    long value;
    pthread_mutex_lock(&store->lock);

    Node* node = findInLinkedList(store, key);
    if (node) {
        value = node->value;
    } else {
        node = avlFind(store->avlRoot, key);
        if (node) {
            value = node->value;
        } else {
            fprintf(stderr, "Key not found in data store.\n");
            pthread_mutex_unlock(&store->lock);
            return -1;
        }
    }

    // Data integrity check
    Node* avlNode = avlFind(store->avlRoot, key);
    if (!node || (node->key != avlNode->key || node->value != avlNode->value)) {
        fprintf(stderr, "Data inconsistency detected!\n");
        pthread_mutex_unlock(&store->lock);
        return -1;
    }

    pthread_mutex_unlock(&store->lock);

    return value;
}

// Delete a key-value pair from both data structures
void delete(DataStore* store, int key) {
    if (!store) return;

    pthread_mutex_lock(&store->lock);

    // Delete from linked list
    deleteFromLinkedList(store, key);

    // Delete from AVL Tree
    store->avlRoot = avlDelete(store->avlRoot, key);

    pthread_mutex_unlock(&store->lock);
}

// Free all resources associated with the data store
void freeDataStore(DataStore* store) {
    if (!store) return;

    pthread_mutex_lock(&store->lock);

    // Free linked list and AVL Tree nodes
    freeLinkedList(store->head);
    freeAVLTree(store->avlRoot);

    pthread_mutex_unlock(&store->lock);
    pthread_mutex_destroy(&store->lock);
    free(store);
}

// Implementations for linked list operations (insert, find, delete, free)
Node* insertLinkedList(DataStore* store, int key, long value) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;

    newNode->key = key;
    newNode->value = value;
    newNode->next = store->head;
    store->head = newNode;

    return newNode;
}

Node* findInLinkedList(DataStore* store, int key) {
    Node* current = store->head;
    while (current) {
        if (current->key == key)
            return current;
        current = current->next;
    }
    return NULL;
}

void deleteFromLinkedList(DataStore* store, int key) {
    Node *current = store->head, *prev = NULL;

    while (current) {
        if (current->key == key) {
            if (prev)
                prev->next = current->next;
            else
                store->head = current->next;

            free(current);
            return;
        }
        prev = current;
        current = current->next;
    }
}

void freeLinkedList(Node* head) {
    Node *temp;
    while (head) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

// Implementations for AVL Tree operations
Node* avlInsert(Node* root, int key, long value) {
    if (!root) return createNode(key, value);

    if (key < root->key)
        root->left = avlInsert(root->left, key, value);
    else if (key > root->key)
        root->right = avlInsert(root->right, key, value);
    else
        return root; // Duplicate keys not allowed

    int balance = getBalanceFactor(root);

    // Left-Left Case
    if (balance > 1 && key < root->left->key)
        return rightRotate(root);

    // Right-Right Case
    if (balance < -1 && key > root->right->key)
        return leftRotate(root);

    // Left-Right Case
    if (balance > 1 && key > root->left->key) {
        root->left = leftRotate(root->left);
        return rightRotate(root);
    }

    // Right-Left Case
    if (balance < -1 && key < root->right->key) {
        root->right = rightRotate(root->right);
        return leftRotate(root);
    }

    return root;
}

Node* avlFind(Node* root, int key) {
    if (!root || root->key == key)
        return root;

    if (key < root->key)
        return avlFind(root->left, key);

    return avlFind(root->right, key);
}

Node* avlDelete(Node* root, int key) {
    if (!root) return root;

    if (key < root->key)
        root->left = avlDelete(root->left, key);
    else if (key > root->key)
        root->right = avlDelete(root->right, key);
    else {
        // Node with only one child or no child
        if (!root->left) {
            Node* temp = root->right;
            free(root);
            return temp;
        } else if (!root->right) {
            Node* temp = root->left;
            free(root);
            return temp;
        }

        // Node with two children: Get the inorder successor
        Node* temp = minValueNode(root->right);

        root->key = temp->key;
        root->value = temp->value;

        root->right = avlDelete(root->right, temp->key);
    }

    if (!root) return root;

    int balance = getBalanceFactor(root);

    // Left-Left Case
    if (balance > 1 && getBalanceFactor(root->left) >= 0)
        return rightRotate(root);

    // Left-Right Case
    if (balance > 1 && getBalanceFactor(root->left) < 0) {
        root->left = leftRotate(root->left);
        return rightRotate(root);
    }

    // Right-Right Case
    if (balance < -1 && getBalanceFactor(root->right) <= 0)
        return leftRotate(root);

    // Right-Left Case
    if (balance < -1 && getBalanceFactor(root->right) > 0) {
        root->right = rightRotate(root->right);
        return leftRotate(root);
    }

    return root;
}

int getHeight(Node* node) {
    if (!node) return 0;
    return 1 + fmax(getHeight(node->left), getHeight(node->right));
}

int getBalanceFactor(Node* node) {
    if (!node) return 0;
    return getHeight(node->left) - getHeight(node->right);
}

Node* rightRotate(Node* y) {
    Node* x = y->left;
    Node* T2 = x->right;

    x->right = y;
    y->left = T2;

    return x;
}

Node* leftRotate(Node* x) {
    Node* y = x->right;
    Node* T2 = y->left;

    y->left = x;
    x->right = T2;

    return y;
}

void freeAVLTree(Node* root) {
    if (root) {
        freeAVLTree(root->left);
        freeAVLTree(root->right);
        free(root);
    }
}

Node* createNode(int key, long value) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    node->key = key;
    node->value = value;
    node->left = NULL;
    node->right = NULL;

    return node;
}

// Helper function to find the minimum value node in AVL Tree
Node* minValueNode(Node* node) {
    Node* current = node;

    while (current && current->left != NULL)
        current = current->left;

    return current;
}
```

### Design Document

#### Approach:
1. **Data Structures**: 
   - Use a linked list for O(1) insertion at the beginning and linear search.
   - Use an AVL Tree to maintain balance, offering O(log n) complexity for insertions, deletions, and lookups.

2. **Thread Safety**:
   - Employ a `pthread_mutex_t` lock within the DataStore structure to manage concurrent access safely.

3. **Memory Management**: 
   - Gracefully handle memory allocation failures with checks after each allocation.
   - Ensure all allocated nodes are freed appropriately using dedicated free functions for linked lists and AVL trees.

4. **Data Integrity**:
   - After every insertion or retrieval, verify the consistency between linked list and AVL tree.

5. **Scalability & Performance**:
   - The balanced nature of the AVL Tree ensures efficient handling as data grows.
   - Linked lists facilitate rapid insertions but are checked for integrity with AVL Trees.

6. **External Dependencies**: 
   - Not explicitly handled in this code; integration would involve managing updates and potential inconsistencies during fetches from external sources.

7. **Configuration**:
   - The structure allows for configuration, such as adjusting the balance between memory usage and speed (e.g., by modifying tree balancing thresholds or linked list node allocation policies).

#### Trade-offs:
- Using both a linked list and an AVL tree increases complexity but ensures high performance and integrity.
- Thread safety via mutex may lead to contention under heavy load. Consider read-write locks for optimization.

This design can be extended with additional features like logging, error handling strategies, or custom balancing algorithms based on specific requirements of the existing system it will integrate into.']

['Below is a C implementation for initializing and populating a dynamic array of `CellularPacketStats` structures with handling for unique `SourceMACAddress`, cumulative packet size calculations, and efficient memory management.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Assuming these constants for simplicity. Adjust as needed.
#define MAC_ADDRESS_LENGTH 6
#define MAX_PACKETS 10000

typedef struct {
    unsigned long Timestamp;
    unsigned char SourceMACAddress[MAC_ADDRESS_LENGTH];
    int PacketSize;
} CellularPacketStats;

typedef struct {
    unsigned char SourceMACAddress[MAC_ADDRESS_LENGTH];
    int CumulativePacketSize;
} MACStatistics;

// Custom comparator for sorting and searching MAC addresses
int compare_mac_addresses(const void *a, const void *b) {
    return memcmp(*(unsigned char **)a, *(unsigned char **)b, MAC_ADDRESS_LENGTH);
}

CellularPacketStats* initialize_packet_stats_array(int num_packets, CellularPacketStats packets[], int* initialized_count) {
    if (!num_packets || !packets || !initialized_count) return NULL;

    CellularPacketStats *dynamicArray = (CellularPacketStats *)malloc(num_packets * sizeof(CellularPacketStats));
    if (!dynamicArray) return NULL;

    MACStatistics *mac_stats_array = malloc(MAX_PACKETS * sizeof(MACStatistics));
    int mac_count = 0;
    qsort(packets, num_packets, sizeof(CellularPacketStats), compare_mac_addresses);

    for (int i = 0; i < num_packets; ++i) {
        if (i > 0 && memcmp(packets[i].SourceMACAddress, packets[i - 1].SourceMACAddress, MAC_ADDRESS_LENGTH) == 0) {
            // Duplicate MAC address found, update existing cumulative size
            for (int j = 0; j < mac_count; ++j) {
                if (memcmp(mac_stats_array[j].SourceMACAddress, packets[i].SourceMACAddress, MAC_ADDRESS_LENGTH) == 0) {
                    mac_stats_array[j].CumulativePacketSize += packets[i].PacketSize;
                    break;
                }
            }
        } else {
            // Unique MAC address found
            memcpy(dynamicArray[*initialized_count].Timestamp, &packets[i].Timestamp, sizeof(packets[i].Timestamp));
            memcpy(dynamicArray[*initialized_count].SourceMACAddress, packets[i].SourceMACAddress, MAC_ADDRESS_LENGTH);
            dynamicArray[*initialized_count].PacketSize = packets[i].PacketSize;

            // Add to mac_stats_array
            memcpy(mac_stats_array[mac_count].SourceMACAddress, packets[i].SourceMACAddress, MAC_ADDRESS_LENGTH);
            mac_stats_array[mac_count++].CumulativePacketSize = packets[i].PacketSize;

            (*initialized_count)++;
        }
    }

    free(mac_stats_array);  // Free the temporary memory used for managing MAC stats
    return dynamicArray;
}

int main() {
    CellularPacketStats example_packets[MAX_PACKETS] = {
        { .Timestamp = 1234567890, .SourceMACAddress = {0x00, 0x1A, 0x2B, 0x3C, 0x4D, 0x5E}, .PacketSize = 150 },
        // Add more packets for testing
    };

    int num_packets = 1; // Set to the number of actual packets you have
    int initialized_count = 0;

    CellularPacketStats *packet_array = initialize_packet_stats_array(num_packets, example_packets, &initialized_count);

    if (packet_array) {
        for (int i = 0; i < initialized_count; ++i) {
            printf("Timestamp: %lu, MAC: %.2X:%.2X:%.2X:%.2X:%.2X:%.2X, PacketSize: %d\n",
                   packet_array[i].Timestamp,
                   packet_array[i].SourceMACAddress[0], packet_array[i].SourceMACAddress[1],
                   packet_array[i].SourceMACAddress[2], packet_array[i].SourceMACAddress[3],
                   packet_array[i].SourceMACAddress[4], packet_array[i].SourceMACAddress[5],
                   packet_array[i].PacketSize);
        }
        free(packet_array);  // Free the dynamic array after use
    }

    return 0;
}
```

### Key Points:
- The function `initialize_packet_stats_array` initializes a dynamic array of `CellularPacketStats`, handles duplicates, and calculates cumulative packet sizes for unique MAC addresses.
- It uses `qsort` to sort packets based on the MAC address to easily detect and handle duplicates.
- Memory management is considered by dynamically allocating memory only as needed and freeing it appropriately.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RNTIS 1000
#define MAX_TIMESTAMPS 1000
#define INITIAL_UE_ITEMS 10

typedef struct {
    uint32_t RNTI;
    long timestamp;
} UEInformationTag;

typedef struct {
    char *metadata;
    double latency;
} UEInfoItem;

// Global variables for logging and synchronization
pthread_mutex_t lock;
int max_allocated_items = 0;

void log_allocation(const char* message) {
    // Placeholder function to integrate with an external logging framework
    printf("%s\n", message);
}

uint32_t get_random_rnti() {
    return rand() % MAX_RNTIS + 1;  // Example random RNTI generation
}

long get_current_timestamp_offset() {
    return (long)time(NULL);  // Example timestamp generation
}

void initialize_ue_information(UEInformationTag **rntis, long **timestamps,
                               UEInfoItem ***ue_items, int initial_count) {
    pthread_mutex_lock(&lock);

    *rntis = malloc(MAX_RNTIS * sizeof(UEInformationTag));
    if (*rntis == NULL) {
        log_allocation("Memory allocation failed for RNTIs.");
        pthread_mutex_unlock(&lock);
        return;
    }

    *timestamps = malloc(MAX_TIMESTAMPS * sizeof(long));
    if (*timestamps == NULL) {
        free(*rntis);
        log_allocation("Memory allocation failed for timestamps.");
        pthread_mutex_unlock(&lock);
        return;
    }

    *ue_items = malloc(initial_count * sizeof(UEInfoItem*));
    if (*ue_items == NULL) {
        free(*rntis);
        free(*timestamps);
        log_allocation("Memory allocation failed for UEInfoItems.");
        pthread_mutex_unlock(&lock);
        return;
    }

    // Initialize RNTIs and timestamps with predefined values
    for (int i = 0; i < MAX_RNTIS; ++i) {
        (*rntis)[i].RNTI = get_random_rnti();
        (*rntis)[i].timestamp = get_current_timestamp_offset();
    }

    // Initialize UEInfoItems with default values
    for (int i = 0; i < initial_count; ++i) {
        (*ue_items)[i] = malloc(sizeof(UEInfoItem));
        if ((*ue_items)[i] == NULL) {
            log_allocation("Memory allocation failed for a UEInfoItem.");
            pthread_mutex_unlock(&lock);
            return;
        }
        (*ue_items)[i]->metadata = strdup("");
        (*ue_items)[i]->latency = 0.0;
    }

    max_allocated_items = initial_count;

    log_allocation("Initialization complete with memory allocations logged.");

    pthread_mutex_unlock(&lock);
}

void resize_ue_info_items(UEInfoItem ***ue_items, int new_size) {
    pthread_mutex_lock(&lock);

    UEInfoItem **temp_items = realloc(*ue_items, new_size * sizeof(UEInfoItem*));
    if (temp_items == NULL) {
        log_allocation("Memory reallocation failed for UEInfoItems.");
        pthread_mutex_unlock(&lock);
        return;
    }

    // Initialize newly added UEInfoItems
    for (int i = max_allocated_items; i < new_size; ++i) {
        temp_items[i] = malloc(sizeof(UEInfoItem));
        if (temp_items[i] == NULL) {
            log_allocation("Memory allocation failed for a new UEInfoItem.");
            pthread_mutex_unlock(&lock);
            return;
        }
        temp_items[i]->metadata = strdup("");
        temp_items[i]->latency = 0.0;
    }

    *ue_items = temp_items;
    max_allocated_items = new_size;

    log_allocation("UEInfoItems resized and initialized.");

    pthread_mutex_unlock(&lock);
}

void free_resources(UEInformationTag *rntis, long *timestamps,
                    UEInfoItem **ue_items) {
    if (rntis != NULL) {
        free(rntis);
    }
    if (timestamps != NULL) {
        free(timestamps);
    }
    if (ue_items != NULL) {
        for (int i = 0; i < max_allocated_items; ++i) {
            if (ue_items[i] != NULL) {
                free(ue_items[i]->metadata);
                free(ue_items[i]);
            }
        }
        free(ue_items);
    }

