// Function to initialize data structures
int init_data_structures(double** doubles_array, char*** strings_array, Node*** nodes_array, Edge*** edges_array) {
    if (!doubles_array || !strings_array || !nodes_array || !edges_array)
        return ALLOC_FAILURE;

    *doubles_array = malloc(4 * sizeof(double));
    *strings_array = malloc(4 * sizeof(char*));
    *nodes_array = malloc(4 * sizeof(Node*));
    *edges_array = malloc(4 * sizeof(Edge*));

    if (!(*doubles_array) || !(*strings_array) || !(*nodes_array) || !(*edges_array))
        return ALLOC_FAILURE;

    for (int i = 0; i < 4; ++i) {
        (*doubles_array)[i] = (double)i;
        (*strings_array)[i] = malloc(MAX_STRING_LENGTH * sizeof(char));
        if (!(*strings_array)[i]) {
            destroy_data_structures(doubles_array, strings_array, nodes_array, edges_array);
            return ALLOC_FAILURE;
        }
        snprintf((*strings_array)[i], MAX_STRING_LENGTH, "String %d", i);

        (*nodes_array)[i] = create_node(0, 100); // Random range example
