            return ALLOC_FAILURE;
        }

        (*edges_array)[i] = malloc(sizeof(Edge));
        if (!(*edges_array)[i]) {
            destroy_data_structures(doubles_array, strings_array, nodes_array, edges_array);
            return ALLOC_FAILURE;
        }
    }

    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        Edge edge = { rand() % 100, (*nodes_array)[(i + 1) % 4] };
        pthread_create(&threads[i], NULL, (void*(*)(void*))update_graph, &edge);
    }

    for (int i = 0; i < 4; ++i)
        pthread_join(threads[i], NULL);

    return SUCCESS;
}

// Helper function to destroy data structures
void destroy_data_structures(double** doubles_array, char*** strings_array, Node*** nodes_array, Edge*** edges_array) {
    if (!doubles_array || !strings_array || !nodes_array || !edges_array)
        return;

    free(*doubles_array);
    for (int i = 0; i < 4; ++i)
        free((*strings_array)[i]);
    free(*strings_array);

    for (int i = 0; i < 4; ++i)
        destroy_tree((*nodes_array)[i]);
    free(*nodes_array);

    for (int i = 0; i < 4; ++i)
        free((*edges_array)[i]);
    free(*edges_array);
}

Node* create_node(int min_key, int max_key) {
    Node* node = malloc(sizeof(Node));
    if (!node) return NULL;

    pthread_mutex_init(&node->lock, NULL);
    node->key = rand() % (max_key - min_key + 1) + min_key;
    node->children = calloc(2, sizeof(Node*)); // Two children for binary tree
    node->edges = NULL;
    node->edge_count = 0;

    return node;
}

void destroy_tree(Node* root) {
    if (!root) return;

    pthread_mutex_lock(&root->lock);
    free(root->children);
    for (size_t i = 0; i < root->edge_count; ++i)
        free(&(root->edges[i]));
    free(root->edges);
    pthread_mutex_unlock(&root->lock);

    destroy_tree(root->children[0]);
    destroy_tree(root->children[1]);

    pthread_mutex_destroy(&root->lock);
    free(root);
}

void insert_node(Node** root, Node* node, int min_key, int max_key) {
    if (!root || !node) return;

    pthread_mutex_lock(&(*root)->lock);

    if (*root == NULL) {
        *root = node;
    } else if (node->key < (*root)->key) {
        insert_node(&((*root)->children[0]), node, min_key, max_key);
    } else {
        insert_node(&((*root)->children[1]), node, min_key, max_key);
    }

    pthread_mutex_unlock(&(*root)->lock);
}

Node* search_tree(Node* root, int key) {
    if (!root || root->key == key)
        return root;

    if (key < root->key)
        return search_tree(root->children[0], key);

    return search_tree(root->children[1], key);
}

void update_graph(void* arg) {
    Edge* edge = (Edge*)arg;
    pthread_mutex_lock(&edge->destination->lock);

    // Add or update edge logic
    edge->destination->edges = realloc(edge->destination->edges, sizeof(Edge) * (edge->destination->edge_count + 1));
    if (!edge->destination->edges) {
        pthread_mutex_unlock(&edge->destination->lock);
        return;
    }
    edge->destination->edges[edge->destination->edge_count++] = *edge;

    pthread_mutex_unlock(&edge->destination->lock);
}
