    dc->offsets = malloc(MAX_LONG_OFFSET * sizeof(long));
    if (!dc->offsets) goto fail;

    dc->keys = malloc(MAX_INT_KEY * sizeof(int));
    if (!dc->keys) goto fail;

    dc->items = malloc(INITIAL_ITEM_CAPACITY * sizeof(Item));
    if (!dc->items) goto fail;

    for (int i = 0; i < MAX_LONG_OFFSET; ++i) {
