    dc->key_count = MAX_INT_KEY;
    dc->item_capacity = INITIAL_ITEM_CAPACITY;
    dc->item_size = 0;

    return dc;

fail:
    if (dc) {
        free(dc->items);
        free(dc->keys);
        free(dc->offsets);
        pthread_mutex_destroy(&dc->lock);
        free(dc);
    }
    return NULL;
}

int add_item(DataCollection* dc, const char* initial_string) {
    pthread_mutex_lock(&dc->lock);

    if (dc->item_size >= dc->item_capacity) {
        int new_capacity = dc->item_capacity * 2;
        Item* new_items = realloc(dc->items, new_capacity * sizeof(Item));
        if (!new_items) {
            pthread_mutex_unlock(&dc->lock);
            return -1;
        }
        dc->items = new_items;
        dc->item_capacity = new_capacity;
    }

    dc->items[dc->item_size].string = strdup(initial_string);
    if (!dc->items[dc->item_size].string) {
        pthread_mutex_unlock(&dc->lock);
        return -1;
    }
    dc->items[dc->item_size].value = 0.0;

    ++dc->item_size;

    pthread_mutex_unlock(&dc->lock);
    return 0;
}

void destroy_data_collection(DataCollection* dc) {
