#define MIN_EMAIL_LENGTH 5
#define PASSWORD_MIN 100000
#define PASSWORD_MAX 999999
#define MEMORY_LIMIT (OFFSET_COUNT * sizeof(long) + \
                     KEY_COUNT * sizeof(int) + \
                     RECORD_COUNT * (sizeof(char *) + sizeof(int)))

typedef struct {
    char *email;
    int value;
} record;

void initialize_random_seed() {
    srand((unsigned int)time(NULL));
}

int generate_valid_password() {
    int password = 0;
    while (1) {
        password = PASSWORD_MIN + rand() % (PASSWORD_MAX - PASSWORD_MIN + 1);
        // Example criteria: must be a six-digit number with at least one digit
        if (password >= PASSWORD_MIN && password <= PASSWORD_MAX) break; 
    }
    return password;
}

char* generate_random_email(int length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789@.";
    char *email = malloc(length + 1);
    if (!email) exit(EXIT_FAILURE);

    for (int i = 0; i < length; ++i) {
        email[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    email[length] = '\0';

    // Ensure valid format by appending '@domain.com'
    char *at_sign_pos = strchr(email, '@');
    if (!at_sign_pos || strlen(at_sign_pos) < 10) {
        free(email);
        length += 9; // Adjust for "@domain.com"
        email = malloc(length + 1);
        if (!email) exit(EXIT_FAILURE);

        strncpy(email, at_sign_pos ? at_sign_pos : "", strlen(at_sign_pos ? at_sign_pos : ""));
        strcat(email, "@example.com");
    }

    return email;
}

void* allocate_and_initialize(int offset_count, int key_count, int record_count, long *total_memory_used) {
    long total_memory = 0;

    // Allocate memory for offsets
    long *offsets = malloc(offset_count * sizeof(long));
    if (!offsets || (total_memory += offset_count * sizeof(long)) > MEMORY_LIMIT)
        return NULL;

    // Allocate memory for keys
    int *keys = malloc(key_count * sizeof(int));
    if (!keys || (total_memory += key_count * sizeof(int)) > MEMORY_LIMIT) {
        free(offsets);
        return NULL;
    }

    // Allocate memory for records
    record *recs = malloc(record_count * sizeof(record));
    if (!recs || (total_memory += record_count * sizeof(record)) > MEMORY_LIMIT) {
        free(keys);
        free(offsets);
        return NULL;
    }

    *total_memory_used = total_memory;

    // Initialize keys and records
    for (int i = 0; i < key_count; ++i) {
        keys[i] = generate_valid_password();
    }

    for (int i = 0; i < record_count; ++i) {
        int email_length = MIN_EMAIL_LENGTH + rand() % (MAX_EMAIL_LENGTH - MIN_EMAIL_LENGTH + 1);
        recs[i].email = generate_random_email(email_length);
        if (!recs[i].email) {
            // Handle memory allocation failure
            return NULL;
        }
        total_memory += email_length + 1; // Include null terminator

        recs[i].value = generate_valid_password();

        if ((total_memory + sizeof(int)) > MEMORY_LIMIT) {
            free(recs[i].email);
            return NULL;
        }

        total_memory += sizeof(int);
    }

    return malloc(sizeof(long *) * 3 + sizeof(int *) + sizeof(record *));
}

void* initialize_data() {
    long total_memory_used = 0;
    void *data_structure = allocate_and_initialize(OFFSET_COUNT, KEY_COUNT, RECORD_COUNT, &total_memory_used);

    if (!data_structure) {
        fprintf(stderr, "Failed to allocate memory. Total used: %ld\n", total_memory_used);
        return NULL;
    }

    long *offsets = (long *)data_structure;
    offsets[0] = 0; // Example offset value
    offsets[1] = 10; // Example offset value

    int *keys = (int *)(offsets + OFFSET_COUNT);
    record *records = (record *)((char *)keys + KEY_COUNT * sizeof(int));

    return data_structure;
}

void free_allocated_memory(void *data_structure) {
    if (!data_structure) return;

    long *offsets = (long *)data_structure;
    int *keys = (int *)(offsets + OFFSET_COUNT);
    record *records = (record *)((char *)keys + KEY_COUNT * sizeof(int));

    for (int i = 0; i < RECORD_COUNT; ++i) {
        free(records[i].email);
    }

    free(records);
    free(keys);
    free(offsets);
}

int main() {
    initialize_random_seed();

    void *data_structure = initialize_data();
    if (!data_structure) return EXIT_FAILURE;

    // Use data...

    free_allocated_memory(data_structure);

    return EXIT_SUCCESS;
}
