['Below is a C function to manage a dynamic array of custom message objects in a high-concurrency environment. This implementation considers concurrency, memory management, and efficient searching. It uses mutexes for thread safety and periodic cleanup based on timestamps.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MESSAGE_EXPIRY_THRESHOLD 60 // seconds

typedef struct {
    char source[256];
    char destination[256];
} MessageHeader;

typedef struct {
    MessageHeader header;
    void* payload; // Pointer to dynamically allocated memory
    size_t payload_size;
    time_t timestamp;
    int id; // Unique identifier for the message
} Message;

typedef struct Node {
    Message* message;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} MessageList;

MessageList messages = {NULL, PTHREAD_MUTEX_INITIALIZER};

// Function to add or update a message by its unique identifier
void add_or_update_message(Message* new_message) {
    pthread_mutex_lock(&messages.lock);

    Node** current = &messages.head;
    while (*current) {
        if ((*current)->message->id == new_message->id) {
            // Update existing message
            free((*current)->message->payload);
            (*current)->message->header = new_message->header;
            (*current)->message->payload_size = new_message->payload_size;
            (*current)->message->payload = malloc(new_message->payload_size);
            memcpy((*current)->message->payload, new_message->payload, new_message->payload_size);
            (*current)->message->timestamp = time(NULL);
            pthread_mutex_unlock(&messages.lock);
            return;
        }
        current = &(*current)->next;
    }

    // Add new message
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->message = malloc(sizeof(Message));
    *new_node->message = *new_message;
    new_node->next = messages.head;
    messages.head = new_node;

    pthread_mutex_unlock(&messages.lock);
}

// Function to search for messages by destination address
void search_messages_by_destination(const char* destination, Message** results, int* count) {
    pthread_mutex_lock(&messages.lock);

    Node* current = messages.head;
    *count = 0;
    while (current && *count < MAX_RESULTS) {
        if (strcmp(current->message->header.destination, destination) == 0) {
            results[(*count)++] = current->message;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&messages.lock);
}

// Function to clean up expired messages
void cleanup_expired_messages() {
    time_t now = time(NULL);
    pthread_mutex_lock(&messages.lock);

    Node *current = messages.head, *prev = NULL;
    while (current) {
        if (difftime(now, current->message->timestamp) > MESSAGE_EXPIRY_THRESHOLD) {
            if (prev) {
                prev->next = current->next;
            } else {
                messages.head = current->next;
            }
            free(current->message->payload);
            free(current->message);
            Node* to_delete = current;
            current = current->next;
            free(to_delete);
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&messages.lock);
}

// Periodic cleanup task
void* periodic_cleanup(void* arg) {
    while (1) {
        sleep(CLEANUP_INTERVAL);
        cleanup_expired_messages();
    }
    return NULL;
}

int main() {
    // Start the periodic cleanup thread
    pthread_t cleanup_thread;
    if (pthread_create(&cleanup_thread, NULL, periodic_cleanup, NULL)) {
        fprintf(stderr, "Error creating cleanup thread\n");
        return 1;
    }

    // Example usage of adding or updating a message
    Message msg = { .header = {"source_address", "destination_address"}, .payload_size = 128 };
    msg.payload = malloc(msg.payload_size);
    strcpy((char*)msg.payload, "Sample payload data");
    msg.timestamp = time(NULL);
    msg.id = 1;

    add_or_update_message(&msg);

    // Example usage of searching messages
    Message* results[MAX_RESULTS];
    int count;
    search_messages_by_destination("destination_address", results, &count);

    // Cleanup and exit
    pthread_join(cleanup_thread, NULL);
    return 0;
}
```

### Key Points:
