        data->offsets[i] = rand() % 100000;
        data->keys[i] = rand() % 10000;
        data->records[i].key = rand() % 10000;

        // Populate with random values (omitted for brevity)
    }

    fclose(file);
    return 0;
}

int sort_records(file_data *data) {
    qsort(data->keys, data->count, sizeof(int), (int (*)(const void *, const void *))strcmp);

    record temp;
    int index;
    for (size_t i = 0; i < data->count - 1; ++i) {
        index = i;
        for (size_t j = i + 1; j < data->count; ++j) {
            if (data->keys[j] < data->keys[index]) {
                index = j;
            }
        }

        temp = data->records[i];
        data->records[i] = data->records[index];
        data->records[index] = temp;

        int key_temp = data->keys[i];
        data->keys[i] = data->keys[index];
        data->keys[index] = key_temp;
    }
    return 0;
}

int processAndSortNetworkEventsWithDir(const char *directory_name, const char *env_var) {
