typedef struct DoublyLinkedList {
    Record *head;
    Record *tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

void log_system_info(const char *logFile) {
    FILE *file = fopen(logFile, "a");
    if (file == NULL) return;

    // Example system info logging (use actual system calls for real implementation)
    fprintf(file, "Memory and CPU load info\n");
