void check_and_delete_files(const char **files, int numFiles) {
    for (int i = 0; i < numFiles; ++i) {
        if (access(files[i], F_OK) == 0) {
            remove(files[i]);
        }
    }
}

void delete_directory_contents(const char *dirPath) {
    // Use system calls or platform-specific APIs to list and remove files
}

void free_record(Record *record) {
    if (record->stringValue != NULL) {
        free(record->stringValue);
    }
    free(record);
}

void destroy_list(DoublyLinkedList *list) {
    Record *current = list->head;
    while (current != NULL) {
        Record *next = current->next;
        free_record(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

DoublyLinkedList* create_list() {
    DoublyLinkedList *list = malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void add_record(DoublyLinkedList *list, Record *record) {
    pthread_mutex_lock(&list->lock);

    record->prev = list->tail;
    record->next = NULL;
    if (list->tail != NULL) {
        list->tail->next = record;
    } else {
        list->head = record;
    }
    list->tail = record;

    pthread_mutex_unlock(&list->lock);
}

