        }

        char buffer[1024];
        while (fgets(buffer, sizeof(buffer), process) != NULL) {
            // Process output
        }

        pclose(process);
        break;
    }

    for (int i = 0; i < numLongOffsets * numIntKeys * numDoubleValues * numCharStrings; ++i) {
        Record *record = malloc(sizeof(Record));
        if (!record) continue;

        record->intValue = rand() % 100;
