#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define DEFAULT_TIMESTAMP 0
#define DEFAULT_VALUE 0.0
#define MAX_LOG_MESSAGE_LENGTH 256

typedef struct Event {
    unsigned long id;
    unsigned long timestamp;
    double value;
    char log_message[MAX_LOG_MESSAGE_LENGTH];
    struct Event* next;
} Event;

Event* create_event(unsigned long id, unsigned long timestamp, double value, const char* log_message) {
    Event* new_event = (Event*)malloc(sizeof(Event));
    if (!new_event) return NULL;

    new_event->id = id;
    new_event->timestamp = timestamp;
    new_event->value = value;
    strncpy(new_event->log_message, log_message, MAX_LOG_MESSAGE_LENGTH - 1);
    new_event->log_message[MAX_LOG_MESSAGE_LENGTH - 1] = '\0';
    new_event->next = NULL;

    return new_event;
}

void insert_sorted(Event** head, Event* new_event) {
    if (!(*head) || (*head)->timestamp > new_event->timestamp) {
        new_event->next = *head;
        *head = new_event;
    } else {
        Event* current = *head;
        while (current->next && current->next->timestamp <= new_event->timestamp) {
            current = current->next;
        }
        new_event->next = current->next;
        current->next = new_event;
    }
}

int parse_csv_and_initialize_events(const char* filename, Event** head) {
    FILE* file = fopen(filename, "r");
    if (!file) return -1;

    char line[1024];
    unsigned long id_counter = 0;
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    while (fgets(line, sizeof(line), file)) {
        pthread_mutex_lock(&lock);

        char* timestamp_str = strtok(line, ",");
        char* value_str = strtok(NULL, ",");
        char* log_message_str = strtok(NULL, ",");

        unsigned long timestamp = DEFAULT_TIMESTAMP;
        double value = DEFAULT_VALUE;
        if (timestamp_str && *timestamp_str) {
            timestamp = strtoul(timestamp_str, NULL, 10);
        }

        if (value_str && *value_str) {
            value = strtof(value_str, NULL);
        }

        char log_message[MAX_LOG_MESSAGE_LENGTH] = "";
        if (log_message_str && *log_message_str) {
            strncpy(log_message, log_message_str, MAX_LOG_MESSAGE_LENGTH - 1);
            log_message[MAX_LOG_MESSAGE_LENGTH - 1] = '\0';
        }

        Event* new_event = create_event(id_counter++, timestamp, value, log_message);
        if (!new_event) {
            pthread_mutex_unlock(&lock);
            fclose(file);
            return -1;
        }

        insert_sorted(head, new_event);

        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_destroy(&lock);
    fclose(file);
    return 0;
}

void free_events(Event* head) {
    Event* current = head;
    while (current) {
        Event* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    Event* events = NULL;
    if (parse_csv_and_initialize_events("events.csv", &events) == 0) {
        // Successfully parsed and initialized the event list
        // Process the events or append more as needed...

        free_events(events);
    } else {
        fprintf(stderr, "Failed to initialize events from CSV file.\n");
    }

    return 0;
}
```

### Key Points:
- **Dynamic Memory Allocation**: Each `Event` is dynamically allocated and linked together in a sorted manner.
- **Thread Safety**: A mutex (`pthread_mutex_t`) is used for locking critical sections during the parsing to ensure thread safety.
- **Error Handling**: The function returns `-1` if any file operations or memory allocations fail, allowing the caller to handle errors appropriately.
- **Sorting on Insertion**: Events are inserted in sorted order based on their timestamps to avoid needing a separate sorting step.']

