    NFAPI_CRC_INDICATION_PDU_T *array = aligned_alloc(64, sizeof(NFAPI_CRC_INDICATION_PDU_T) * count);
    if (!array) return NULL;

    for (size_t i = 0; i < count; ++i) {
        array[i].rx_ue_information_tag.validRX_UE_INFORMATION_TAG = rand() % UINT16_MAX;
        array[i].rnti = rand();
        array[i].crc_indication_rel8_tag.CRCFLAG = rand() % 2;
    }

    return array;
}

// Function to allocate memory for interconnected data structures
typedef struct {
    long *offsets;
    int *keys;
    record *records;
    double *doubles;
    node **nodes;
    edge **edges;
} DataStructures;

DataStructures* allocate_data_structures(size_t offsets_count, size_t keys_count,
                                         size_t records_count, size_t doubles_count,
                                         size_t nodes_count, size_t edges_count) {
    if (offsets_count == 0 || keys_count == 0 || records_count == 0 ||
        doubles_count == 0 || nodes_count == 0 || edges_count == 0)
        return NULL;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    DataStructures *data_struct = aligned_alloc(64, sizeof(DataStructures));
    if (!data_struct) {
        pthread_mutex_destroy(&lock);
        return NULL;
    }

    // Allocate offsets
    data_struct->offsets = aligned_alloc(64, sizeof(long) * offsets_count);

    // Allocate keys
    data_struct->keys = aligned_alloc(64, sizeof(int) * keys_count);

    // Allocate records
    data_struct->records = malloc(sizeof(record) * records_count);  // Unaligned

    // Allocate doubles
    data_struct->doubles = aligned_alloc(64, sizeof(double) * doubles_count);

    // Allocate nodes and edges
    data_struct->nodes = malloc(sizeof(node*) * nodes_count);  // Unaligned
    data_struct->edges = malloc(sizeof(edge*) * edges_count);  // Unaligned

    for (size_t i = 0; i < keys_count; ++i) {
        pthread_mutex_lock(&lock);
        data_struct->keys[i] = rand() % 10000;
        pthread_mutex_unlock(&lock);
    }

    srand(time(NULL));

    for (size_t i = 0; i < nodes_count; ++i) {
        node *n = malloc(sizeof(node));
        if (!n) {
            // Handle allocation failure
            free(data_struct->nodes);
            data_struct->nodes = NULL;
            free_data_structures(data_struct, false);
            return NULL;
        }
        n->key = rand() % 10000;
        n->children = malloc(2 * sizeof(node*));  // For binary tree structure
        n->edges = malloc(sizeof(edge) * edges_count / nodes_count);  // Distribute edges
        if (!n->children || !n->edges) {
            free(n);
            // Handle allocation failure
            for (size_t j = 0; j < i; ++j)
                free(data_struct->nodes[j]);
            data_struct->nodes = NULL;
            free_data_structures(data_struct, false);
            return NULL;
        }
        n->edges_count = edges_count / nodes_count;

        for (size_t j = 0; j < n->edges_count; ++j) {
            edge *e = malloc(sizeof(edge));
            if (!e) {
                // Handle allocation failure
                free(n->children);
                free(n->edges);
                free(n);
                // Clean up other allocated structures
                for (size_t k = 0; k < i; ++k)
                    free(data_struct->nodes[k]);
                data_struct->nodes = NULL;
                free_data_structures(data_struct, false);
                return NULL;
            }
            e->weight = ((double)rand() / RAND_MAX) * 100.0;  // Random weight between 0 and 100
            n->edges[j] = e;
        }

        data_struct->nodes[i] = n;
    }

    pthread_mutex_destroy(&lock);
    return data_struct;
}

// Function to free allocated memory
void free_data_structures(DataStructures *data_struct, int preserve_offsets) {
    if (!data_struct) return;

    if (data_struct->offsets && !preserve_offsets)
        free(data_struct->offsets);

    for (size_t i = 0; i < keys_count; ++i)
        free(data_struct->keys[i]);

    for (size_t i = 0; i < records_count; ++i) {
        free(data_struct->records[i]);
    }
    free(data_struct->records);

    for (size_t i = 0; i < doubles_count; ++i) {
        free(data_struct->doubles[i]);
    }
    free(data_struct->doubles);

    for (size_t i = 0; i < nodes_count; ++i) {
        node *n = data_struct->nodes[i];
        if (!n) continue;
        for (size_t j = 0; j < n->edges_count; ++j) {
            free(n->edges[j]);
        }
        free(n->edges);
        free(n->children);
        free(n);
    }
    free(data_struct->nodes);

    for (size_t i = 0; i < edges_count; ++i) {
        free(data_struct->edges[i]);
    }
    free(data_struct->edges);

    free(data_struct);
}

// Note: This example assumes appropriate values for counts such as offsets_count, keys_count,
// records_count, doubles_count, nodes_count, and edges_count. In practice, these should be 
// provided by the caller based on specific requirements.
