    void DynamicDataProcessor::initializeRecords() {
        records.reserve(numRecords);
        std::uniform_int_distribution<int> offsetDist(1, 1000);
        std::normal_distribution<double> keyDist(50.0, 10.0);

        for (size_t i = 0; i < numRecords; ++i) {
            Record record;
            record.offset = offsetDist(rng);
            record.key = keyDist(rng);
            record.value = "Value_" + std::to_string(i);
            records.push_back(record);
        }
    }

    void DynamicDataProcessor::sortRecords() {
        std::lock_guard<std::mutex> lock(mtx);
        std::stable_sort(records.begin(), records.end(),
                         [](const Record& a, const Record& b) { return a.key < b.key; });
    }

