            sqlite3_finalize(stmt);
        } else {
            std::cerr << "Failed to execute query: " << sqlite3_errmsg(db) << std::endl;
        }
    }

    void DynamicDataProcessor::executeTask(const std::function<void()>& task) {
        {
            std::lock_guard<std::mutex> lock(mtx);
            tasks.push(task);
        }
        cv.notify_one();
    }

    void DynamicDataProcessor::startThreadPool(size_t numThreads) {
        for (size_t i = 0; i < numThreads; ++i) {
            poolThreads.emplace_back([this]() {
                while (true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(mtx);
                        cv.wait(lock, [this] { return stopThreadPool || !tasks.empty(); });
                        if (stopThreadPool && tasks.empty()) return;

                        task = std::move(tasks.front());
                        tasks.pop();
                    }
                    task();
                }
            });
        }
    }

    void DynamicDataProcessor::stopThreadPool() {
        {
            std::lock_guard<std::mutex> lock(mtx);
            stopThreadPool = true;
        }
        cv.notify_all();
        for (auto& thread : poolThreads) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

}

int main(int argc, char* argv[]) {
    if (argc < 3) {
        std::cerr << "Usage: " << argv[0] << " <seed> <numRecords>" << std::endl;
        return 1;
    }

    int seed = std::stoi(argv[1]);
    size_t numRecords = std::stoul(argv[2]);

    DataProcessing::DynamicDataProcessor processor(seed, numRecords);
    processor.processData();
    processor.retrieveEmployeeDetails("Supervisor1");

    return 0;
}
