// Initialize message collection
MessageCollection* initialize_collection(size_t initial_capacity) {
    MessageCollection *collection = (MessageCollection *)malloc(sizeof(MessageCollection));
    if (!collection) return NULL;

    collection->records = (Record **)calloc(initial_capacity, sizeof(Record *));
    collection->record_count = 0;
    collection->capacity = initial_capacity;

    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

// Add a new message
bool add_message(MessageCollection *collection, const char *source, const char *destination, Event **events, size_t event_count) {
    pthread_mutex_lock(&collection->lock);

    if (collection->record_count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record **new_records = (Record **)realloc(collection->records, new_capacity * sizeof(Record *));
        if (!new_records) {
            pthread_mutex_unlock(&collection->lock);
            return false;
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    Record *record = (Record *)malloc(sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&collection->lock);
        return false;
    }

    record->timestamp = generate_timestamp();
    record->unique_id = rand();
    record->events = malloc(event_count * sizeof(Event *));
    memcpy(record->events, events, event_count * sizeof(Event *));
    record->event_count = event_count;

    collection->records[collection->record_count++] = record;
    pthread_mutex_unlock(&collection->lock);
    return true;
}

// Update an existing message
bool update_message(MessageCollection *collection, uint64_t unique_id, Event **events, size_t event_count) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->record_count; ++i) {
        Record *record = collection->records[i];
        if (record->unique_id == unique_id) {
            free(record->events);
            record->events = malloc(event_count * sizeof(Event *));
            memcpy(record->events, events, event_count * sizeof(Event *));
            record->event_count = event_count;
            pthread_mutex_unlock(&collection->lock);
            return true;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return false;
}

// Search for messages by destination
Record** search_messages_by_destination(MessageCollection *collection, const char *destination, size_t *count) {
    pthread_mutex_lock(&collection->lock);

    Record **results = (Record **)malloc(collection->record_count * sizeof(Record *));
    if (!results) {
        pthread_mutex_unlock(&collection->lock);
        return NULL;
    }

    *count = 0;
    for (size_t i = 0; i < collection->record_count; ++i) {
        Record *record = collection->records[i];
        if (strcmp(record->destination, destination) == 0) {
            results[(*count)++] = record;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return results;
}

// Cleanup expired messages
void cleanup_expired_messages(MessageCollection *collection, uint64_t threshold) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->record_count;) {
        Record *record = collection->records[i];
        if (is_message_expired(record->timestamp, threshold)) {
            free(record->events);
            free(record);
            collection->records[i] = collection->records[--collection->record_count];
        } else {
            ++i;
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

// Generate timestamp with fallback
uint64_t generate_timestamp() {
    // Simulate external service call with a random failure
    if (rand() % 10 < 2) { // 20% chance of failure
        return get_current_time();
    }
    // Simulate successful external service call
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return ts.tv_sec * 1000 + ts.tv_nsec / 1000000; // Convert to milliseconds
}

// Get current time from local clock
uint64_t get_current_time() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return ts.tv_sec * 1000 + ts.tv_nsec / 1000000; // Convert to milliseconds
}

// Check if a message is expired
bool is_message_expired(uint64_t timestamp, uint64_t threshold) {
    uint64_t current_time = get_current_time();
    return (current_time - timestamp) > threshold;
}

// Free all resources
void free_collection(MessageCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->record_count; ++i) {
        Record *record = collection->records[i];
        free(record->events);
        free(record);
    }
    free(collection->records);

    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

