hash_table_t* create_hash_table(size_t size) {
    hash_table_t *table = malloc(sizeof(hash_table_t));
    if (!table) {
        perror("Memory allocation failed");
        return NULL;
    }
    table->size = size;
    table->buckets = calloc(table->size, sizeof(hash_table_entry_t *));
    if (!table->buckets) {
        perror("Memory allocation failed");
        free(table);
        return NULL;
    }
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

unsigned int hash(void *key, size_t key_size, size_t table_size) {
    unsigned char *data = (unsigned char *)key;
    unsigned int h = 0;
    for (size_t i = 0; i < key_size; ++i)
        h = (h * HASH_MULTIPLIER) ^ data[i];
    return h % table_size;
}

void insert_to_hash_table(hash_table_t *table, void *key, size_t key_size, void *value, size_t value_size) {
    unsigned int index = hash(key, key_size, table->size);
    pthread_mutex_lock(&table->lock);

    hash_table_entry_t *entry = malloc(sizeof(hash_table_entry_t));
    if (!entry) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&table->lock);
        return;
    }

    entry->key = malloc(key_size);
    entry->value = malloc(value_size);
    if (!entry->key || !entry->value) {
        perror("Memory allocation failed");
        free(entry->key);
        free(entry->value);
        free(entry);
        pthread_mutex_unlock(&table->lock);
        return;
    }

    memcpy(entry->key, key, key_size);
    memcpy(entry->value, value, value_size);

    entry->next = table->buckets[index];
    table->buckets[index] = entry;

    pthread_mutex_unlock(&table->lock);
}

void* find_in_hash_table(hash_table_t *table, void *key, size_t key_size) {
    unsigned int index = hash(key, key_size, table->size);
    pthread_mutex_lock(&table->lock);

    hash_table_entry_t *entry = table->buckets[index];
    while (entry) {
        if (memcmp(entry->key, key, key_size) == 0) {
            void *result = entry->value;
            pthread_mutex_unlock(&table->lock);
            return result;
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void free_hash_table(hash_table_t *table) {
    for (size_t i = 0; i < table->size; ++i) {
        hash_table_entry_t *entry = table->buckets[i];
        while (entry) {
            hash_table_entry_t *next = entry->next;
            free(entry->key);
            free(entry->value);
            free(entry);
            entry = next;
        }
    }
    pthread_mutex_destroy(&table->lock);
    free(table->buckets);
    free(table);
}
