typedef struct {
    int64_t timestamp;
} record;

typedef struct {
    void *key;
    void *value;
} map_entry;

typedef struct {
    void *key;
    void *data;
} cache_entry;

#define INITIAL_CAPACITY 16
#define LOAD_FACTOR_THRESHOLD 0.75

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

typedef struct hashtable {
    size_t capacity;
    size_t count;
    map_entry **buckets;
} hashtable;

// Utility functions for hashing and resizing
static inline uint64_t hash_function(const void *key) {
    // Simple hash function (replace with a better one if needed)
    return *(uint64_t *)key % INITIAL_CAPACITY;
}

hashtable *create_hashtable(size_t initial_capacity) {
    hashtable *ht = malloc(sizeof(hashtable));
    ht->capacity = initial_capacity;
    ht->count = 0;
    ht->buckets = calloc(initial_capacity, sizeof(map_entry *));
    return ht;
}

void free_hashtable(hashtable *ht) {
    for (size_t i = 0; i < ht->capacity; ++i) {
        if (ht->buckets[i]) {
            free(ht->buckets[i]->key);
            free(ht->buckets[i]->value);
            free(ht->buckets[i]);
        }
    }
    free(ht->buckets);
    free(ht);
}

void rehash(hashtable *ht);

static void ensure_capacity(hashtable *ht) {
    if ((double)ht->count / ht->capacity > LOAD_FACTOR_THRESHOLD) {
        pthread_mutex_lock(&lock);
        if ((double)ht->count / ht->capacity > LOAD_FACTOR_THRESHOLD) { // Double-check lock
            size_t new_capacity = ht->capacity * 2;
            map_entry **new_buckets = calloc(new_capacity, sizeof(map_entry *));

            for (size_t i = 0; i < ht->capacity; ++i) {
                if (ht->buckets[i]) {
                    uint64_t index = hash_function(ht->buckets[i]->key) % new_capacity;
                    new_buckets[index] = ht->buckets[i];
                }
            }

            free(ht->buckets);
            ht->buckets = new_buckets;
            ht->capacity = new_capacity;
        }
        pthread_mutex_unlock(&lock);
    }
}

void insert_entry(hashtable *ht, void *key, void *value) {
    ensure_capacity(ht);

    pthread_mutex_lock(&lock);
    uint64_t index = hash_function(key) % ht->capacity;
    map_entry *entry = malloc(sizeof(map_entry));
    entry->key = key;
    entry->value = value;

    while (ht->buckets[index]) {
        if ((*(uint64_t *)key == *(uint64_t *)(ht->buckets[index]->key)) /* Key comparison logic */) {
            free(ht->buckets[index]->value);
            ht->buckets[index]->value = value; // Overwrite existing entry
            pthread_mutex_unlock(&lock);
            return;
        }
        index = (index + 1) % ht->capacity;
    }

    ht->buckets[index] = entry;
    ht->count++;
    pthread_mutex_unlock(&lock);
}

void *retrieve_entry(hashtable *ht, void *key) {
    pthread_mutex_lock(&lock);

    uint64_t index = hash_function(key) % ht->capacity;
    while (ht->buckets[index]) {
        if ((*(uint64_t *)key == *(uint64_t *)(ht->buckets[index]->key)) /* Key comparison logic */) {
            void *value = ht->buckets[index]->value;
            pthread_mutex_unlock(&lock);
            return value;
        }
        index = (index + 1) % ht->capacity;
    }

    pthread_mutex_unlock(&lock);
    return NULL; // Entry not found
}

void delete_entry(hashtable *ht, void *key) {
    pthread_mutex_lock(&lock);

    uint64_t index = hash_function(key) % ht->capacity;
    while (ht->buckets[index]) {
        if ((*(uint64_t *)key == *(uint64_t *)(ht->buckets[index]->key)) /* Key comparison logic */) {
            free(ht->buckets[index]->value);
            free(ht->buckets[index]);
            ht->buckets[index] = NULL; // Mark as deleted
            ht->count--;
            pthread_mutex_unlock(&lock);
            return;
        }
        index = (index + 1) % ht->capacity;
    }

    pthread_mutex_unlock(&lock);
}

// Monitoring component
void log_system_metrics(hashtable *ht) {
    double load_factor = (double)ht->count / ht->capacity;
    printf("Current Load Factor: %.2f\n", load_factor);
    // Additional metrics can be logged here, like rehash frequency and cache hit/miss rates.
}

// Example usage
int main() {
    hashtable *ht = create_hashtable(INITIAL_CAPACITY);

    int key1 = 1;
    char *value1 = strdup("Data for key 1");
    insert_entry(ht, &key1, value1);

    char *retrieved_value = retrieve_entry(ht, &key1);
    if (retrieved_value) {
        printf("Retrieved: %s\n", retrieved_value);
    }

    delete_entry(ht, &key1);
    log_system_metrics(ht);

    free(value1);
    free_hashtable(ht);

    return 0;
}
