#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define BATCH_THRESHOLD 5

typedef struct {
    int type;
    size_t length;
    unsigned char *data;
} MAC_FRAME_DATA;

typedef struct {
    int mac_event_tag;
    time_t timestamp;
    MAC_FRAME_DATA *frames;
    size_t frame_count;
    size_t capacity;
} NETWORK_EVENT;

typedef struct {
    NETWORK_EVENT **events;
    size_t event_count;
    size_t capacity;
    pthread_mutex_t lock;
} EVENT_LIST;

void init_event_list(EVENT_LIST *list) {
    list->events = malloc(INITIAL_CAPACITY * sizeof(NETWORK_EVENT *));
    list->event_count = 0;
    list->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&list->lock, NULL);
}

void resize_event_list(EVENT_LIST *list) {
    size_t new_capacity = list->capacity * 2;
    NETWORK_EVENT **new_events = realloc(list->events, new_capacity * sizeof(NETWORK_EVENT *));
    if (new_events) {
        list->events = new_events;
        list->capacity = new_capacity;
    } else {
        fprintf(stderr, "Failed to resize event list\n");
        exit(EXIT_FAILURE);
    }
}

void add_event(EVENT_LIST *list, NETWORK_EVENT *event) {
    pthread_mutex_lock(&list->lock);

    if (list->event_count == list->capacity) {
        resize_event_list(list);
    }

    list->events[list->event_count++] = event;

    pthread_mutex_unlock(&list->lock);
}

void add_events_batch(EVENT_LIST *list, NETWORK_EVENT **batch, size_t batch_size) {
    pthread_mutex_lock(&list->lock);

    if (list->event_count + batch_size > list->capacity) {
        while (list->event_count + batch_size > list->capacity) {
            resize_event_list(list);
        }
    }

    for (size_t i = 0; i < batch_size; ++i) {
        list->events[list->event_count++] = batch[i];
    }

    pthread_mutex_unlock(&list->lock);
}

void free_event_list(EVENT_LIST *list) {
    for (size_t i = 0; i < list->event_count; ++i) {
        NETWORK_EVENT *event = list->events[i];
        for (size_t j = 0; j < event->frame_count; ++j) {
            free(event->frames[j].data);
        }
        free(event->frames);
        free(event);
    }
    free(list->events);
    pthread_mutex_destroy(&list->lock);
}

void process_events(EVENT_LIST *list, void (*process)(NETWORK_EVENT *)) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->event_count; ++i) {
        process(list->events[i]);
    }

    pthread_mutex_unlock(&list->lock);
}

void log_event(NETWORK_EVENT *event, int detail_level) {
    printf("Event Tag: %d\n", event->mac_event_tag);
    printf("Timestamp: %ld\n", event->timestamp);
    if (detail_level > 1) {
        for (size_t i = 0; i < event->frame_count; ++i) {
            printf("Frame Type: %d, Length: %zu\n", event->frames[i].type, event->frames[i].length);
        }
    }
}

// Example usage
void example_process(NETWORK_EVENT *event) {
    log_event(event, 2);
}

int main() {
    EVENT_LIST list;
    init_event_list(&list);

    // Add and process events...

    free_event_list(&list);
    return 0;
}
```

