}

// Allocate memory for audio streams
int allocateMemory(audioStream** streams, size_t numStreams) {
    for (size_t i = 0; i < numStreams; ++i) {
        streams[i] = malloc(sizeof(audioStream));
        if (!streams[i]) return ERROR_CODE;

