            }
            streams[i]->frames[j]->timestamp = (float)rand() / RAND_MAX * 100.0f;
        }
    }
    return 0;
}

// Free memory for an audio stream
void freeMemory(audioStream* stream) {
    if (!stream) return;

    for (size_t i = 0; i < stream->numFrames; ++i) {
        free(stream->frames[i]->samples);
        free(stream->frames[i]);
    }
    free(stream->frames);
    pthread_mutex_destroy(&stream->lock);
    free(stream);
}

// Calculate moving average
float movingAverage(float* window, size_t windowSize) {
    float sum = 0.0f;
    for (size_t i = 0; i < windowSize; ++i) {
        sum += window[i];
    }
    return sum / windowSize;
}

// Find maximum timestamp
float maxTimestamp(const float* timestamps, size_t count) {
    if (!timestamps || count == 0) return -1.0f;

    float max = timestamps[0];
    for (size_t i = 1; i < count; ++i) {
        if (timestamps[i] > max) {
            max = timestamps[i];
        }
    }
    return max;
}

