typedef struct {
    double value;
    char flag[10];
    unsigned int identifier;
} data_point;

// Predefined list of substrings for the `char` flag field
const char *flag_list[] = {"A1", "B2", "C3", "D4"};
const size_t num_flags = sizeof(flag_list) / sizeof(flag_list[0]);

typedef struct {
    data_point *data_points;
    size_t count;
} dataset;

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

double calculate_value(long offset, int key) {
    // Example function ensuring numerical stability and precision
    return (offset / (double)(key + 1));
}

char* get_random_flag() {
    size_t index = rand() % num_flags;
    char *flag_copy = strdup(flag_list[index]);
    return flag_copy;
}

int compare_data_points(const void *a, const void *b) {
    data_point *dp_a = (data_point *)a;
    data_point *dp_b = (data_point *)b;
    return (dp_a->identifier > dp_b->identifier) - (dp_a->identifier < dp_b->identifier);
}

int initialize_dataset(dataset *ds, size_t num_points, int start_key, long offset_range_min, long offset_range_max) {
    pthread_mutex_lock(&mutex);

    // Check for invalid inputs
    if (num_points == 0 || start_key < 0 || offset_range_min > offset_range_max)
        return -1;

    ds->count = num_points;
    ds->data_points = malloc(num_points * sizeof(data_point));
    if (!ds->data_points) {
        pthread_mutex_unlock(&mutex);
        return -2; // Memory allocation failed
    }

    srand(time(NULL));

    for (size_t i = 0; i < num_points; ++i) {
        long offset = rand() % (offset_range_max - offset_range_min + 1) + offset_range_min;
        int key = start_key + i;

        ds->data_points[i].value = calculate_value(offset, key);
        char *flag_str = get_random_flag();
        strncpy(ds->data_points[i].flag, flag_str, sizeof(ds->data_points[i].flag) - 1);
        free(flag_str); // Free the allocated string after use

        ds->data_points[i].identifier = (unsigned int)(offset + key); // Simple unique identifier
    }

    qsort(ds->data_points, num_points, sizeof(data_point), compare_data_points);

    pthread_mutex_unlock(&mutex);
    return 0; // Success
}

void free_dataset(dataset *ds) {
    pthread_mutex_lock(&mutex);
    free(ds->data_points);
    ds->count = 0;
    pthread_mutex_unlock(&mutex);
}
