['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    uint32_t taskId;
    uint8_t priorityLevel;
    time_t executionStart;
    uint32_t estimatedDuration; // in seconds
} DataProcessingTask;

typedef struct Node {
    DataProcessingTask task;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t capacity;
    pthread_mutex_t lock;
} PriorityQueue;

// Function prototypes
PriorityQueue* createPriorityQueue(size_t initialCapacity);
void destroyPriorityQueue(PriorityQueue* pq);
int insertTask(PriorityQueue* pq, DataProcessingTask task);
DataProcessingTask retrieveHighestPriorityTask(PriorityQueue* pq);
uint32_t calculateCompletionTime(DataProcessingTask task);

// Utility functions for memory management and logging
static void logError(const char *message);
static void* safeMalloc(size_t size);
static void freeAll(PriorityQueue* pq);

PriorityQueue* createPriorityQueue(size_t initialCapacity) {
    PriorityQueue* pq = (PriorityQueue*)safeMalloc(sizeof(PriorityQueue));
    if (!pq) return NULL;

    pq->head = NULL;
    pq->capacity = initialCapacity;
    pthread_mutex_init(&pq->lock, NULL);

    return pq;
}

void destroyPriorityQueue(PriorityQueue* pq) {
    freeAll(pq);
    pthread_mutex_destroy(&pq->lock);
    free(pq);
}

int insertTask(PriorityQueue* pq, DataProcessingTask task) {
    if (!pq) return -1;

    Node* newNode = (Node*)safeMalloc(sizeof(Node));
    if (!newNode) return -2;

    newNode->task = task;
    newNode->next = NULL;

    pthread_mutex_lock(&pq->lock);

    // Insert in sorted order based on priorityLevel
    if (!pq->head || pq->head->task.priorityLevel < task.priorityLevel) {
        newNode->next = pq->head;
        pq->head = newNode;
    } else {
        Node* current = pq->head;
        while (current->next && current->next->task.priorityLevel >= task.priorityLevel) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }

    pthread_mutex_unlock(&pq->lock);

    return 0;
}

DataProcessingTask retrieveHighestPriorityTask(PriorityQueue* pq) {
    if (!pq || !pq->head) {
        DataProcessingTask emptyTask = {0};
        return emptyTask;
    }

    pthread_mutex_lock(&pq->lock);

    Node* tempNode = pq->head;
    DataProcessingTask task = tempNode->task;

    pq->head = tempNode->next;
    free(tempNode);

    pthread_mutex_unlock(&pq->lock);

    return task;
}

uint32_t calculateCompletionTime(DataProcessingTask task) {
    uint64_t start_time_ms = (uint64_t)task.executionStart * 1000; // Convert to milliseconds
    uint64_t duration_ms = (uint64_t)task.estimatedDuration * 1000;

    if ((UINT32_MAX - start_time_ms) < duration_ms) {
        logError("Integer overflow in time calculation");
        return UINT32_MAX;
    }

    return (uint32_t)((start_time_ms + duration_ms) / 1000); // Convert back to seconds
}

static void logError(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

static void* safeMalloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        logError("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

static void freeAll(PriorityQueue* pq) {
    Node* current = pq->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
}
