#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

#define MAX_PROTOCOLS 10000
#define INITIAL_POOL_SIZE 1024
#define BUFFER_INCREMENT 512

typedef struct {
    uint32_t protocol_id;
    uint16_t message_type;
    size_t size;
    char *data;
} ProtocolBuffer;

typedef struct {
    ProtocolBuffer *buffers;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} BufferPool;

void initialize_pool(BufferPool *pool) {
    pool->capacity = INITIAL_POOL_SIZE;
    pool->buffers = malloc(pool->capacity * sizeof(ProtocolBuffer));
    if (!pool->buffers) {
        perror("Failed to allocate buffer pool");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->cond, NULL);
}

void resize_pool(BufferPool *pool) {
    size_t new_capacity = pool->capacity + BUFFER_INCREMENT;
    ProtocolBuffer *new_buffers = realloc(pool->buffers, new_capacity * sizeof(ProtocolBuffer));
    if (!new_buffers) {
        perror("Failed to resize buffer pool");
        exit(EXIT_FAILURE);
    }
    pool->buffers = new_buffers;
    pool->capacity = new_capacity;
}

int add_protocol_buffer(BufferPool *pool, ProtocolBuffer *buffer) {
    pthread_mutex_lock(&pool->lock);

    while (/* condition for full pool */) {
        pthread_cond_wait(&pool->cond, &pool->lock);
    }

    if (/* buffer is full */) {
        resize_pool(pool);
    }

    // Add the new protocol buffer
    memcpy(&pool->buffers[/* appropriate index */], buffer, sizeof(ProtocolBuffer));

    pthread_mutex_unlock(&pool->lock);
    pthread_cond_signal(&pool->cond);

    return 0;
}

int remove_protocol_buffer(BufferPool *pool, uint32_t protocol_id) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->capacity; ++i) {
        if (pool->buffers[i].protocol_id == protocol_id) {
            // Remove the buffer
            memset(&pool->buffers[i], 0, sizeof(ProtocolBuffer));
            pthread_cond_signal(&pool->cond);
            pthread_mutex_unlock(&pool->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&pool->lock);
    return -1; // Buffer not found
}

void destroy_pool(BufferPool *pool) {
    free(pool->buffers);
    pthread_mutex_destroy(&pool->lock);
    pthread_cond_destroy(&pool->cond);
}

// Example usage
int main() {
    BufferPool pool;
    initialize_pool(&pool);

    ProtocolBuffer buffer = { .protocol_id = 1, .message_type = 100, .size = sizeof("Hello"), .data = "Hello" };
    add_protocol_buffer(&pool, &buffer);

    remove_protocol_buffer(&pool, 1);
    destroy_pool(&pool);

    return 0;
}
```

### Documentation:
- **Configuration**: Adjust `INITIAL_POOL_SIZE` and `BUFFER_INCREMENT` based on expected load and memory availability.
- **Concurrency**: The pool uses a mutex and condition variable to manage concurrent access. Consider using more advanced lock-free structures for higher concurrency.
- **Error Handling**: Proper error checks are included for memory allocation failures.
- **Performance Tuning**: Profile the application under different loads to identify bottlenecks. Adjust buffer sizes and pool capacity based on profiling results.
- **Memory Management**: Monitor memory usage periodically, especially in high-throughput scenarios, to prevent excessive consumption.

This code provides a basic structure for managing protocol buffers with concurrency support. Further optimization may be necessary depending on specific application requirements and network characteristics.']

