#include <iostream>
#include <string>
#include <vector>
#include <mutex>
#include <thread>
#include <random>
#include <fstream>

namespace DataProcessingFramework {

    class DynamicHashMap {
    private:
        struct Entry {
            std::string key;
            int value;
            bool occupied;

            Entry() : occupied(false) {}
        };

        std::vector<Entry> table;
        size_t capacity;
        std::mutex mtx;

        size_t hashFunction(const std::string &key) const {
            std::hash<std::string> hasher;
            return hasher(key) % capacity;
        }

        void resize(size_t new_capacity) {
            std::lock_guard<std::mutex> lock(mtx);

            std::vector<Entry> old_table = table;
            capacity = new_capacity;
            table.assign(capacity, Entry());

            for (const auto &entry : old_table) {
                if (entry.occupied) {
                    insert(entry.key, entry.value);
                }
            }
        }

    public:
        DynamicHashMap(size_t initial_capacity = 16)
            : capacity(initial_capacity), table(initial_capacity) {
            std::random_device rd;
            std::mt19937 gen(rd());
            std::uniform_int_distribution<> dis(1, 100);

            for (size_t i = 0; i < capacity; ++i) {
                std::string key = "Key_" + std::to_string(i);
                int value = dis(gen); 
                insert(key, value);
            }
        }

        ~DynamicHashMap() {
            // Destructor to release resources if needed
        }

        bool insert(const std::string &key, int value) {
            std::lock_guard<std::mutex> lock(mtx);

            size_t index = hashFunction(key);
            while (table[index].occupied && table[index].key != key) {
                index = (index + 1) % capacity;
            }

            if (!table[index].occupied) {
                table[index] = {key, value, true};
                return true;
            } else {
                // Key already exists
                table[index].value = value;
                return false;
            }
        }

        bool remove(const std::string &key) {
            std::lock_guard<std::mutex> lock(mtx);

            size_t index = hashFunction(key);
            while (table[index].occupied && table[index].key != key) {
                index = (index + 1) % capacity;
            }

            if (table[index].occupied) {
                table[index].occupied = false;
                return true;
            } else {
                // Key not found
                return false;
            }
        }

        bool lookup(const std::string &key, int &value) const {
            std::lock_guard<std::mutex> lock(mtx);

            size_t index = hashFunction(key);
            while (table[index].occupied && table[index].key != key) {
                index = (index + 1) % capacity;
            }

            if (table[index].occupied) {
                value = table[index].value;
                return true;
            } else {
                // Key not found
                return false;
            }
        }

        void calculateAverageValue() const {
            std::lock_guard<std::mutex> lock(mtx);

            int sum = 0;
            size_t count = 0;

            for (const auto &entry : table) {
                if (entry.occupied) {
                    sum += entry.value;
                    ++count;
                }
            }

            double average = count > 0 ? static_cast<double>(sum) / count : 0.0;
            std::cout << "Average value: " << average << std::endl;
        }
    };
}

int main() {
    DataProcessingFramework::DynamicHashMap hashMap;

    // Example usage
    int value;
    if (hashMap.lookup("Key_5", value)) {
        std::cout << "Value for Key_5: " << value << std::endl;
    }

    hashMap.calculateAverageValue();

    return 0;
}
```

### Design Decisions:
- **Namespace:** Encapsulated the class in a namespace to avoid global scope pollution.
- **Dynamic Array-based Structure:** Utilized `std::vector` for dynamic resizing and efficient memory usage.
- **Thread Safety:** Used `std::mutex` to ensure thread-safe operations, crucial for concurrent access scenarios.
- **Collision Handling:** Implemented open addressing with linear probing to handle hash collisions efficiently.
- **Resizing Strategy:** Not fully implemented but designed to allow easy integration of a load factor-based resizing mechanism.
- **Initialization:** Randomly initialized values using `std::random_device` and `std::mt19937`.
- **Error Handling:** Gracefully handled operations without explicit error codes; can be extended as needed.

This implementation balances simplicity, performance, and maintainability while providing a robust foundation for further enhancements like resizing logic or external data integration.']

