#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <ctype.h>

#define MAX_STRING_LENGTH 100

typedef struct {
    char *name;
    float value;
} entry;

typedef struct {
    entry *entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} dynamic_list;

// Helper function to trim leading and trailing whitespace
char* trim_whitespace(char *str) {
    if (!str) return NULL;

    // Trim leading space
    while (isspace((unsigned char)*str)) str++;

    if (*str == 0) return str; // All spaces?

    // Trim trailing space
    char *end = str + strlen(str) - 1;
    while (end > str && isspace((unsigned char)*end)) end--;

    // Write new null terminator character
    *(end+1) = '\0';

    return str;
}

// Validate and normalize a string entry
int validate_and_normalize_entry(char *input, char **output, size_t max_length) {
    char *trimmed = trim_whitespace(input);
    if (!trimmed || strlen(trimmed) > max_length) {
        fprintf(stderr, "Validation failed: String length exceeds maximum allowed.\n");
        return -1;
    }

    // Copy to new buffer
    *output = malloc(max_length + 1);
    if (*output == NULL) {
        perror("Failed to allocate memory for entry string");
        return -1;
    }

    strncpy(*output, trimmed, max_length);
    (*output)[max_length] = '\0';
    return 0;
}

// Normalize the float value
float normalize_float(float value, int precision) {
    char buffer[50];
    snprintf(buffer, sizeof(buffer), "%.*f", precision, value);
    sscanf(buffer, "%f", &value);
    return value;
}

// Initialize dynamic list
void init_dynamic_list(dynamic_list *list, size_t initial_capacity) {
    list->entries = malloc(initial_capacity * sizeof(entry));
    if (!list->entries) {
        perror("Failed to allocate memory for entries");
        exit(EXIT_FAILURE);
    }
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

// Resize dynamic list
void resize_dynamic_list(dynamic_list *list, size_t new_capacity) {
    entry *new_entries = realloc(list->entries, new_capacity * sizeof(entry));
    if (!new_entries) {
        perror("Failed to reallocate memory for entries");
        exit(EXIT_FAILURE);
    }
    list->entries = new_entries;
    list->capacity = new_capacity;
}

// Add an entry
int add_entry(dynamic_list *list, const char *name, float value, size_t max_string_length, int precision) {
    pthread_mutex_lock(&list->lock);

    // Validate and normalize the string
    char *normalized_name;
    if (validate_and_normalize_entry((char *)name, &normalized_name, max_string_length) != 0) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Error occurred
    }

    // Normalize float value
    float normalized_value = normalize_float(value, precision);

    // Resize if necessary
    if (list->count == list->capacity) {
        resize_dynamic_list(list, list->capacity * 2);
    }

    // Add entry
    list->entries[list->count].name = normalized_name;
    list->entries[list->count].value = normalized_value;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

// Iterate over entries and apply a user-defined function to the float values
void iterate_entries(dynamic_list *list, void (*func)(float *)) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        func(&(list->entries[i].value));
    }

    pthread_mutex_unlock(&list->lock);
}

// Free dynamic list
void free_dynamic_list(dynamic_list *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->entries[i].name); // Free each allocated string name
    }
    free(list->entries);
    pthread_mutex_destroy(&list->lock);
}

// Example user-defined function to update the float value
void example_update_function(float *value) {
    if (value) {
        *value *= 1.1f; // Example operation: increase by 10%
    }
}

int main() {
    dynamic_list list;
    init_dynamic_list(&list, 4);

    add_entry(&list, "   Entry One   ", 3.14159f, MAX_STRING_LENGTH, 2);
    add_entry(&list, "Entry Two", 2.71828f, MAX_STRING_LENGTH, 3);

    iterate_entries(&list, example_update_function);

    for (size_t i = 0; i < list.count; ++i) {
        printf("Name: %s, Value: %.2f\n", list.entries[i].name, list.entries[i].value);
    }

    free_dynamic_list(&list);

    return 0;
}
```

This implementation provides a thread-safe dynamic list with features for managing entries with string trimming and float normalization. It uses mutex locks to ensure safe concurrent access and includes error handling when memory allocation or validation fails. The `resize_dynamic_list` function doubles the capacity, balancing between speed and memory usage efficiently under varying loads.']

