#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_LOG_LENGTH 1024
#define TIMESTAMP_SIZE sizeof(time_t)

typedef struct {
    time_t timestamp;
    char message[MAX_LOG_LENGTH];
} LogEntry;

typedef struct {
    LogEntry *entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} LogEntries;

typedef struct {
    char *message;
    int frequency;
} UniqueMessage;

LogEntries* create_log_entries(size_t initial_capacity) {
    LogEntries *log_entries = malloc(sizeof(LogEntries));
    if (!log_entries) return NULL;

    log_entries->entries = malloc(initial_capacity * sizeof(LogEntry));
    if (!log_entries->entries) {
        free(log_entries);
        return NULL;
    }

    log_entries->capacity = initial_capacity;
    log_entries->count = 0;

    pthread_mutex_init(&log_entries->mutex, NULL);

    return log_entries;
}

void destroy_log_entries(LogEntries *log_entries) {
    if (!log_entries) return;

    free(log_entries->entries);
    pthread_mutex_destroy(&log_entries->mutex);
    free(log_entries);
}

int is_valid_timestamp(time_t timestamp, time_t start_time, time_t end_time) {
    return (timestamp >= start_time && timestamp <= end_time);
}

int parseAndProcessLogEntries(const char *file_path, time_t start_time, time_t end_time, size_t max_message_length) {
    if (!file_path || !*file_path) return -1;

    FILE *file = fopen(file_path, "r");
    if (!file) return -1;

    LogEntries *log_entries = create_log_entries(10);
    if (!log_entries) {
        fclose(file);
        return -1;
    }

    pthread_mutex_t unique_messages_mutex = PTHREAD_MUTEX_INITIALIZER;
    UniqueMessage *unique_messages = NULL;
    size_t unique_capacity = 0, unique_count = 0;

    char line[MAX_LOG_LENGTH];
    time_t timestamp;
    while (fgets(line, sizeof(line), file)) {
        if (sscanf(line, "%ld %[^\n]", &timestamp, log_entries->entries[log_entries->count].message) == 2) {
            if (strlen(log_entries->entries[log_entries->count].message) > max_message_length || !is_valid_timestamp(timestamp, start_time, end_time)) continue;

            pthread_mutex_lock(&log_entries->mutex);
            if (log_entries->count >= log_entries->capacity) {
                size_t new_capacity = log_entries->capacity * 2;
                LogEntry *new_entries = realloc(log_entries->entries, new_capacity * sizeof(LogEntry));
                if (!new_entries) break;

                log_entries->entries = new_entries;
                log_entries->capacity = new_capacity;
            }

            log_entries->entries[log_entries->count].timestamp = timestamp;
            strncpy(log_entries->entries[log_entries->count].message, line + strlen(line), max_message_length);
            pthread_mutex_unlock(&log_entries->mutex);

            pthread_mutex_lock(&unique_messages_mutex);
            int found = 0;
            for (size_t i = 0; i < unique_count; ++i) {
                if (strcmp(unique_messages[i].message, log_entries->entries[log_entries->count].message) == 0) {
                    unique_messages[i].frequency++;
                    found = 1;
                    break;
                }
            }

            if (!found) {
                if (unique_count >= unique_capacity) {
                    size_t new_capacity = unique_capacity ? unique_capacity * 2 : 10;
                    UniqueMessage *new_unique_messages = realloc(unique_messages, new_capacity * sizeof(UniqueMessage));
                    if (!new_unique_messages) break;

                    unique_messages = new_unique_messages;
                    unique_capacity = new_capacity;
                }

                unique_messages[unique_count].message = strdup(log_entries->entries[log_entries->count].message);
                unique_messages[unique_count].frequency = 1;
                unique_count++;
            }
            pthread_mutex_unlock(&unique_messages_mutex);

            log_entries->count++;
        }
    }

    fclose(file);

    for (size_t i = 0; i < unique_count; ++i) {
        free(unique_messages[i].message);
    }
    free(unique_messages);

    destroy_log_entries(log_entries);
    return 0;
}
```']

