```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    uint64_t timestamp;
} MAC_EVENT_TAG;

typedef struct {
    // Define the frame data structure as needed.
    char *data;
    size_t length;
} MAC_FRAME_DATA;

typedef struct Event {
    MAC_EVENT_TAG tag;
    uint64_t timestamp;
    MAC_FRAME_DATA *frames;
    size_t frame_count;
    struct Event *next;
} Event;

typedef struct {
    Event *head;
    pthread_mutex_t lock;
    size_t max_events;
    size_t max_frame_size;
    size_t memory_pool_size;
    // Memory pool for events and frames.
    void *memory_pool;
    size_t used_memory;
} NetworkEventManager;

NetworkEventManager* create_manager(size_t max_events, size_t max_frame_size, size_t memory_pool_size) {
    NetworkEventManager *manager = (NetworkEventManager *)malloc(sizeof(NetworkEventManager));
    if (!manager) return NULL;

    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    manager->max_events = max_events;
    manager->max_frame_size = max_frame_size;
    manager->memory_pool_size = memory_pool_size;
    manager->used_memory = 0;

    // Initialize the memory pool.
    manager->memory_pool = malloc(memory_pool_size);
    if (!manager->memory_pool) {
        free(manager);
        return NULL;
    }

    memset(manager->memory_pool, 0, memory_pool_size);

    return manager;
}

void* allocate_from_pool(NetworkEventManager *manager, size_t size) {
    if (size + manager->used_memory > manager->memory_pool_size) {
        fprintf(stderr, "Memory pool overflow\n");
        return NULL;
    }

    void *ptr = (char *)manager->memory_pool + manager->used_memory;
    manager->used_memory += size;
    return ptr;
}

void free_manager(NetworkEventManager *manager) {
    pthread_mutex_lock(&manager->lock);
    Event *current = manager->head;
    while (current) {
        Event *next = current->next;
        for (size_t i = 0; i < current->frame_count; ++i) {
            free(current->frames[i].data);
        }
        free(current->frames);
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager->memory_pool);
    free(manager);
}

int add_event(NetworkEventManager *manager, MAC_EVENT_TAG tag, uint64_t timestamp, MAC_FRAME_DATA *frames, size_t frame_count) {
    if (frame_count > manager->max_frame_size) return -1;

    pthread_mutex_lock(&manager->lock);

    // Check for maximum events
    Event *current = manager->head;
    while (current && current->next) current = current->next;
    if (current && frame_count + manager->used_memory / sizeof(Event) >= manager->max_events) {
        fprintf(stderr, "Event list overflow\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    // Allocate event
    Event *event = (Event *)allocate_from_pool(manager, sizeof(Event));
    if (!event) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    // Allocate frames within the event
    MAC_FRAME_DATA *frame_data = (MAC_FRAME_DATA *)allocate_from_pool(manager, frame_count * sizeof(MAC_FRAME_DATA));
    if (!frame_data) {
        free(event);
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    memcpy(frame_data, frames, frame_count * sizeof(MAC_FRAME_DATA));
    for (size_t i = 0; i < frame_count; ++i) {
        frame_data[i].data = allocate_from_pool(manager, frame_data[i].length);
        if (!frame_data[i].data) {
            for (size_t j = 0; j < i; ++j) {
                free(frame_data[j].data);
            }
            free(frame_data);
            free(event);
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }

        memcpy(frame_data[i].data, frames[i].data, frame_data[i].length);
    }

    event->tag = tag;
    event->timestamp = timestamp;
    event->frames = frame_data;
    event->frame_count = frame_count;
    event->next = NULL;

    if (!manager->head) {
        manager->head = event;
    } else {
        current->next = event;
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void log_event(NetworkEventManager *manager, const char *message) {
    // Thread-safe logging mechanism
    pthread_mutex_lock(&manager->lock);
    fprintf(stderr, "[%s] %s\n", message, (char *)malloc(256)); // Example of logging with dynamic memory.
    pthread_mutex_unlock(&manager->lock);
}

// Additional functions for removing and accessing events can be implemented similarly.

int main() {
    NetworkEventManager *manager = create_manager(1000, 10, 1024 * 1024); // Example configuration

    if (!manager) return -1;

    MAC_EVENT_TAG tag = {.timestamp = 123456789};
    MAC_FRAME_DATA frames[2] = {{"frame1", 5}, {"frame2", 6}};

    add_event(manager, tag, 1625157600, frames, 2);

    free_manager(manager);
    return 0;
}
```

This code implements a scalable network event manager with the specified requirements. It includes thread-safe operations using mutexes, a simple memory pool for efficient resource management, and basic error reporting. Further optimizations and features can be added as needed.']

