    CircularBuffer memoryMovingAverage;
} SystemPerformanceMetrics;

int configureSystemMonitor(SystemPerformanceMetrics metrics[], size_t numMetrics) {
    if (numMetrics == 0 || metrics == NULL) return -1; // Error code for invalid input

    pthread_mutex_t arrayLock = PTHREAD_MUTEX_INITIALIZER;

    double *cpuBuffer = malloc(sizeof(double) * numMetrics);
    char **hostNames = malloc(sizeof(char*) * numMetrics);
    processInfo **processes = malloc(sizeof(processInfo*) * numMetrics);

    if (!cpuBuffer || !hostNames || !processes) {
        // Handle allocation failure
        free(cpuBuffer);
        for (size_t i = 0; i < numMetrics && hostNames[i]; ++i) {
            free(hostNames[i]);
        }
        free(hostNames);
        for (size_t i = 0; i < numMetrics && processes[i]; ++i) {
            free(processes[i]);
        }
        free(processes);
        return -2; // Error code for memory allocation failure
    }

    time_t currentTime;
    time(&currentTime);

    for (size_t i = 0; i < numMetrics; ++i) {
        metrics[i].hostId = i + 1;

        metrics[i].startTime = currentTime - (30 * 60) + (i * 60);

        // Synthetic CPU and memory usage
        cpuBuffer[i] = rand() / (double)(RAND_MAX / MAX_CPU_UTILIZATION);
        double memUsage = rand() / (double)(RAND_MAX / MAX_MEMORY_USAGE);

        metrics[i].cpuUtilization = cpuBuffer[i];
        metrics[i].memoryUsage = memUsage;

        // Initialize CircularBuffers
        pthread_mutex_init(&metrics[i].cpuMovingAverage.lock, NULL);
        pthread_mutex_init(&metrics[i].memoryMovingAverage.lock, NULL);

        if (i < 5) {
            metrics[i].cpuMovingAverage.capacity = 5;
            metrics[i].cpuMovingAverage.size = i + 1;
            metrics[i].cpuMovingAverage.head = 0;

            metrics[i].memoryMovingAverage.capacity = 5;
            metrics[i].memoryMovingAverage.size = i + 1;
            metrics[i].memoryMovingAverage.head = 0;

        } else {
            metrics[i].cpuMovingAverage.capacity = 5;
            metrics[i].cpuMovingAverage.size = 5;
            metrics[i].cpuMovingAverage.head = (metrics[i].cpuMovingAverage.head + 1) % 5;

            metrics[i].memoryMovingAverage.capacity = 5;
            metrics[i].memoryMovingAverage.size = 5;
            metrics[i].memoryMovingAverage.head = (metrics[i].memoryMovingAverage.head + 1) % 5;
        }

        // Initialize hostNames and processInfo
        hostNames[i] = malloc(sizeof(char) * PROCESS_NAME_LENGTH);
        snprintf(hostNames[i], PROCESS_NAME_LENGTH, "Host_%d", i + 1);

        processes[i] = malloc(sizeof(processInfo));
        snprintf(processes[i]->name, PROCESS_NAME_LENGTH, "Process_%d", (i + 1) * 1000);
        processes[i]->pid = (i + 1) * 1000;
        processes[i]->memoryFootprint = rand() % 50 + 10; // Random memory footprint between 10 and 60

        pthread_mutex_lock(&metrics[i].cpuMovingAverage.lock);
        metrics[i].cpuMovingAverage.buffer = malloc(sizeof(double) * metrics[i].cpuMovingAverage.capacity);
        memcpy(metrics[i].cpuMovingAverage.buffer, &cpuBuffer[0] + i - (i >= 5 ? 4 : i), sizeof(double) * metrics[i].cpuMovingAverage.size);
        pthread_mutex_unlock(&metrics[i].cpuMovingAverage.lock);

        pthread_mutex_lock(&metrics[i].memoryMovingAverage.lock);
        metrics[i].memoryMovingAverage.buffer = malloc(sizeof(double) * metrics[i].memoryMovingAverage.capacity);
        memcpy(metrics[i].memoryMovingAverage.buffer, &memUsage - (i >= 5 ? 4 : i), sizeof(double) * metrics[i].memoryMovingAverage.size);
        pthread_mutex_unlock(&metrics[i].memoryMovingAverage.lock);
    }

    // Free allocated memory at the end of the function
    free(cpuBuffer);
    for (size_t i = 0; i < numMetrics; ++i) {
        free(hostNames[i]);
        free(processes[i]);
    }
    free(hostNames);
    free(processes);

    pthread_mutex_destroy(&arrayLock);

    return 0; // Success
}
