#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define ERROR_MEMORY_ALLOCATION -1

typedef struct {
    int key;
    long timestamp;
    int ref_count;
} record;

typedef struct node {
    int key;
    struct node* next;
} node_t;

typedef struct {
    node_t* head;
    pthread_mutex_t lock;
} hash_table;

hash_table* create_hash_table() {
    hash_table* ht = (hash_table*)malloc(sizeof(hash_table));
    if (!ht) return NULL;
    ht->head = NULL;
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

int insert_key(hash_table* ht, int key) {
    node_t* new_node = (node_t*)malloc(sizeof(node_t));
    if (!new_node) return ERROR_MEMORY_ALLOCATION;

    new_node->key = key;
    pthread_mutex_lock(&ht->lock);

    // Check for duplicates
    node_t* current = ht->head;
    while (current != NULL) {
        if (current->key == key) {
            free(new_node);
            pthread_mutex_unlock(&ht->lock);
            return ERROR_MEMORY_ALLOCATION; // Duplicate found
        }
        current = current->next;
    }

    new_node->next = ht->head;
    ht->head = new_node;

    pthread_mutex_unlock(&ht->lock);
    return 0;
}

int is_key_present(hash_table* ht, int key) {
    pthread_mutex_lock(&ht->lock);

    node_t* current = ht->head;
    while (current != NULL) {
        if (current->key == key) {
            pthread_mutex_unlock(&ht->lock);
            return 1; // Key found
        }
        current = current->next;
    }

    pthread_mutex_unlock(&ht->lock);
    return 0; // Key not present
}

void free_hash_table(hash_table* ht) {
    node_t* current = ht->head;
    while (current != NULL) {
        node_t* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

int compare_records(const void* a, const void* b) {
    record* rec_a = *(record**)a;
    record* rec_b = *(record**)b;

    if (rec_a->key != rec_b->key)
        return rec_a->key - rec_b->key;
    else
        return rec_b->timestamp - rec_a->timestamp; // Descending order of timestamp
}

int initialize_records(record** records, size_t n, int min_key, int max_key) {
    if (min_key >= max_key || n <= 0) return ERROR_MEMORY_ALLOCATION;

    hash_table* ht = create_hash_table();
    if (!ht) return ERROR_MEMORY_ALLOCATION;

    *records = (record*)malloc(n * sizeof(record));
    if (!(*records)) {
        free_hash_table(ht);
        return ERROR_MEMORY_ALLOCATION;
    }

    srand(time(NULL));

    for (size_t i = 0; i < n; ++i) {
        int key = rand() % (max_key - min_key + 1) + min_key;

        if (!is_key_present(ht, key)) {
            (*records)[i].key = key;
            (*records)[i].timestamp = time(NULL);
            (*records)[i].ref_count = 0;

            pthread_mutex_t* lock = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t));
            pthread_mutex_init(lock, NULL);

            if (insert_key(ht, key) == ERROR_MEMORY_ALLOCATION) {
                free_hash_table(ht);
                for (size_t j = 0; j < i; ++j) {
                    pthread_mutex_destroy((pthread_mutex_t*)((*records)[j].ref_count + sizeof(int)));
                    free((*records)[j].ref_count);
                }
                free(*records);
                return ERROR_MEMORY_ALLOCATION;
            }

            (*records)[i].ref_count = (int*)lock;
        } else {
            i--; // Retry for a unique key
        }
    }

    qsort((void*)(*records), n, sizeof(record*), compare_records);

    free_hash_table(ht);
    return 0; // Success
}

void increment_ref_count(record* rec) {
    pthread_mutex_t* lock = (pthread_mutex_t*)(rec->ref_count);
    pthread_mutex_lock(lock);
    ++(*(int*)lock);
    pthread_mutex_unlock(lock);
}

void decrement_ref_count(record* rec) {
    pthread_mutex_t* lock = (pthread_mutex_t*)(rec->ref_count);
    pthread_mutex_lock(lock);
    if (*(int*)lock > 0)
        --(*(int*)lock);
    pthread_mutex_unlock(lock);

    if (*(int*)lock == 0) {
        pthread_mutex_destroy(lock);
        free(rec->ref_count);
    }
}

void release_memory(record* records, size_t n) {
    for (size_t i = 0; i < n; ++i)
        decrement_ref_count(&records[i]);
    free(records);
}
```

This code provides a robust implementation of the described task. It uses a hash table to track unique keys and manage memory efficiently with mutex locks for concurrency control. The `initialize_records` function handles dynamic memory allocation, key uniqueness verification, and reference counting. The records are sorted based on specified criteria before releasing all allocated resources.']

