#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

typedef struct Session {
    int user_id;
    time_t start_timestamp;
    time_t expiration_timestamp;
    int ref_count;
} Session;

#define INITIAL_HASH_SIZE 16

typedef struct HashTable {
    size_t size;
    size_t count;
    pthread_mutex_t lock;
    Session **buckets;
} HashTable;

// Statistics
size_t active_sessions = 0;
time_t total_session_duration = 0;
int peak_concurrent_users = 0;
pthread_mutex_t stats_lock;

void init_hash_table(HashTable *table) {
    table->size = INITIAL_HASH_SIZE;
    table->count = 0;
    pthread_mutex_init(&table->lock, NULL);
    table->buckets = calloc(table->size, sizeof(Session *));
}

int hash_function(int user_id, size_t size) {
    return (user_id & 0x7FFFFFFF) % size;
}

void resize_hash_table(HashTable *table);

Session* find_session(HashTable *table, int user_id) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(user_id, table->size);
    Session *session = table->buckets[index];
    while (session != NULL && session->user_id != user_id) {
        session = session->next;
    }
    pthread_mutex_unlock(&table->lock);
    return session;
}

void add_session(HashTable *table, int user_id, time_t expiration_timestamp) {
    Session *new_session = malloc(sizeof(Session));
    new_session->user_id = user_id;
    new_session->start_timestamp = time(NULL);
    new_session->expiration_timestamp = expiration_timestamp;
    new_session->ref_count = 1;

    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(user_id, table->size);

    if (table->buckets[index] != NULL) {
        Session *current = table->buckets[index];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_session;
    } else {
        table->buckets[index] = new_session;
    }

    table->count++;
    active_sessions++;

    if (table->count / (float)table->size > 0.75) {
        resize_hash_table(table);
    }

    pthread_mutex_unlock(&table->lock);

    // Update statistics
    pthread_mutex_lock(&stats_lock);
    total_session_duration += expiration_timestamp - new_session->start_timestamp;
    peak_concurrent_users = peak_concurrent_users > active_sessions ? peak_concurrent_users : active_sessions;
    pthread_mutex_unlock(&stats_lock);
}

void renew_session(HashTable *table, int user_id, time_t new_expiration) {
    Session *session = find_session(table, user_id);
    if (session != NULL) {
        pthread_mutex_lock(&table->lock);
        session->expiration_timestamp = new_expiration;
        pthread_mutex_unlock(&table->lock);

        // Update statistics
        pthread_mutex_lock(&stats_lock);
        total_session_duration += new_expiration - session->start_timestamp;
        pthread_mutex_unlock(&stats_lock);
    }
}

void increment_ref_count(HashTable *table, int user_id) {
    Session *session = find_session(table, user_id);
    if (session != NULL) {
        pthread_mutex_lock(&table->lock);
        session->ref_count++;
        pthread_mutex_unlock(&table->lock);
    }
}

void decrement_ref_count(HashTable *table, int user_id) {
    Session *session = find_session(table, user_id);
    if (session != NULL && session->ref_count > 0) {
        pthread_mutex_lock(&table->lock);
        session->ref_count--;
        if (session->ref_count == 0) {
            size_t index = hash_function(user_id, table->size);
            Session **current = &table->buckets[index];
            while (*current != NULL && (*current)->user_id != user_id) {
                current = &(*current)->next;
            }
            if (*current != NULL) {
                *current = session->next;
                free(session);
                active_sessions--;
            }
        }
        pthread_mutex_unlock(&table->lock);
    }
}

int is_session_expired(HashTable *table, int user_id) {
    Session *session = find_session(table, user_id);
    return session == NULL || time(NULL) > session->expiration_timestamp;
}

void close_session(HashTable *table, int user_id) {
    decrement_ref_count(table, user_id);
}

size_t get_active_sessions() {
    pthread_mutex_lock(&stats_lock);
    size_t active = active_sessions;
    pthread_mutex_unlock(&stats_lock);
    return active;
}

time_t get_average_session_duration() {
    pthread_mutex_lock(&stats_lock);
    time_t avg_duration = total_session_duration / (active_sessions > 0 ? active_sessions : 1);
    pthread_mutex_unlock(&stats_lock);
    return avg_duration;
}

int get_peak_concurrent_users() {
    pthread_mutex_lock(&stats_lock);
    int peak = peak_concurrent_users;
    pthread_mutex_unlock(&stats_lock);
    return peak;
}

void resize_hash_table(HashTable *table) {
    size_t new_size = table->size * 2;
    Session **new_buckets = calloc(new_size, sizeof(Session *));

    for (size_t i = 0; i < table->size; i++) {
        Session *session = table->buckets[i];
        while (session != NULL) {
            Session *next_session = session->next;
            size_t new_index = hash_function(session->user_id, new_size);
            session->next = new_buckets[new_index];
            new_buckets[new_index] = session;
            session = next_session;
        }
    }

    free(table->buckets);
    table->size = new_size;
    table->buckets = new_buckets;
}

void checkpoint_sessions(HashTable *table) {
    pthread_mutex_lock(&table->lock);
    // Simulate saving to disk
    printf("Checkpointing sessions...\n");
    for (size_t i = 0; i < table->size; i++) {
        Session *session = table->buckets[i];
        while (session != NULL) {
            // Save session state to disk here
            session = session->next;
        }
    }
    pthread_mutex_unlock(&table->lock);
}

void init_statistics() {
    pthread_mutex_init(&stats_lock, NULL);
    active_sessions = 0;
    total_session_duration = 0;
    peak_concurrent_users = 0;
}

int main() {
    HashTable table;
    init_hash_table(&table);
    init_statistics();

    add_session(&table, 1, time(NULL) + 3600);
    renew_session(&table, 1, time(NULL) + 7200);
    increment_ref_count(&table, 1);
    decrement_ref_count(&table, 1);

    printf("Active sessions: %zu\n", get_active_sessions());
    printf("Average session duration: %ld\n", get_average_session_duration());
    printf("Peak concurrent users: %d\n", get_peak_concurrent_users());

    checkpoint_sessions(&table);

    return 0;
}
