// Define constants for user account limits and other configurations
#define MAX_USERS 1000000
#define MAX_THREADS 1000

// Structure to represent a User Account
typedef struct {
    int id;
    char name[256];
    char email[256];
    char password[256];
    bool is_deleted;
} UserAccount;

// Structure for managing the dynamic list of user accounts
typedef struct {
    UserAccount *users;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // Mutex for thread safety
} AccountManager;

// Function prototypes
bool validate_user_data(const UserAccount *user);
void save_user_data(const UserAccount *user);
void compress_data(UserAccount *user);
void log_error(const char *error_message);

// Initialize the account manager
AccountManager* init_account_manager(size_t initial_capacity) {
    AccountManager *manager = (AccountManager *)malloc(sizeof(AccountManager));
    if (!manager) return NULL;

    manager->users = (UserAccount *)aligned_alloc(64, initial_capacity * sizeof(UserAccount));
    if (!manager->users) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

// Resize the user list dynamically
bool resize_account_list(AccountManager *manager, size_t new_capacity) {
    UserAccount *new_users = (UserAccount *)aligned_alloc(64, new_capacity * sizeof(UserAccount));
    if (!new_users) return false;

    memcpy(new_users, manager->users, manager->count * sizeof(UserAccount));
    free(manager->users);

    manager->users = new_users;
    manager->capacity = new_capacity;

    return true;
}

// Add or update a user account
bool add_or_update_user(AccountManager *manager, const UserAccount *user) {
    pthread_mutex_lock(&manager->lock);

    if (!validate_user_data(user)) {
        log_error("Invalid user data");
        pthread_mutex_unlock(&manager->lock);
        return false;
    }

    // Check for existing user
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->users[i].id == user->id) {
            memcpy(&manager->users[i], user, sizeof(UserAccount));
            pthread_mutex_unlock(&manager->lock);
            return true;
        }
    }

    // Resize list if necessary
    if (manager->count >= manager->capacity) {
        if (!resize_account_list(manager, manager->capacity * 2)) {
            log_error("Failed to resize user list");
            pthread_mutex_unlock(&manager->lock);
            return false;
        }
    }

    memcpy(&manager->users[manager->count++], user, sizeof(UserAccount));
    compress_data((UserAccount *)&manager->users[manager->count - 1]);
    save_user_data(user);

    pthread_mutex_unlock(&manager->lock);
    return true;
}

// Delete a user account
bool delete_user(AccountManager *manager, int user_id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->users[i].id == user_id) {
            manager->users[i].is_deleted = true;
            log_error("User account deleted");
            pthread_mutex_unlock(&manager->lock);
            return true;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return false;
}

// Render user scripts as HTML
char* render_user_scripts(AccountManager *manager) {
    size_t script_length = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        if (!manager->users[i].is_deleted) {
            script_length += snprintf(NULL, 0,
                "<script>var user%d = {id: %d, name: '%s', email: '%s'};</script>\n",
                (int)i, manager->users[i].id, manager->users[i].name, manager->users[i].email);
        }
    }

    char *scripts = (char *)malloc(script_length + 1);
    if (!scripts) return NULL;

    char *ptr = scripts;
    for (size_t i = 0; i < manager->count; ++i) {
        if (!manager->users[i].is_deleted) {
            ptr += snprintf(ptr, script_length - (ptr - scripts),
                "<script>var user%d = {id: %d, name: '%s', email: '%s'};</script>\n",
                (int)i, manager->users[i].id, manager->users[i].name, manager->users[i].email);
        }
    }

