import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.*;
import java.nio.channels.FileChannel;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.Level;
import java.util.logging.Logger;
import java.util.stream.Collectors;

class Event {
    private final long timestamp;
    private final String source;
    private final String type;
    private final JsonNode payload;
    private final Map<String, String> metadata;

    public Event(long timestamp, String source, String type, JsonNode payload, Map<String, String> metadata) {
        this.timestamp = timestamp;
        this.source = source;
        this.type = type;
        this.payload = payload;
        this.metadata = metadata;
    }

    // Getters and other methods...
}

public class EventManager {
    private final ConcurrentHashMap<Long, Event> events = new ConcurrentHashMap<>();
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(2);
    private final ObjectMapper objectMapper = new ObjectMapper();
    private static final Logger logger = Logger.getLogger(EventManager.class.getName());

    public EventManager(long retentionMillis) {
        schedulePruning(retentionMillis);
    }

    public void insertEvent(Event event) {
        try {
            JsonNode root = objectMapper.readTree(event.getPayload().toString());
            if (!root.has("transactionId")) throw new IllegalArgumentException("Invalid payload");
            events.put(event.getTimestamp(), event);
            sendMessage(event);
            persistToDisk(event);
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Failed to insert event: " + e.getMessage(), e);
        }
    }

    public void deleteEvent(long timestamp) {
        events.remove(timestamp);
    }

    public Optional<Event> retrieveEvent(long timestamp) {
        return Optional.ofNullable(events.get(timestamp));
    }

    private void schedulePruning(final long retentionMillis) {
        scheduler.scheduleAtFixedRate(() -> pruneEvents(retentionMillis), 0, retentionMillis / 1000, TimeUnit.SECONDS);
    }

    private void pruneEvents(long retentionMillis) {
        long currentTime = System.currentTimeMillis();
        List<Long> toRemove = events.keySet().stream()
                .filter(timestamp -> currentTime - timestamp > retentionMillis)
                .collect(Collectors.toList());

        for (Long timestamp : toRemove) {
            events.remove(timestamp);
            // Optionally delete from disk if needed
        }
    }

    private void sendMessage(Event event) {
        // Implement async communication with retry logic
    }

    private synchronized void persistToDisk(Event event) {
        Path path = Paths.get("events_" + System.currentTimeMillis() + ".json");
        try (FileChannel fileChannel = FileChannel.open(path, StandardOpenOption.CREATE, StandardOpenOption.WRITE)) {
            byte[] bytes = objectMapper.writeValueAsBytes(event);
            ByteBuffer buffer = ByteBuffer.wrap(bytes);
            fileChannel.write(buffer);
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Failed to write event to disk: " + e.getMessage(), e);
        }
    }

    public void shutdown() throws InterruptedException {
        scheduler.shutdown();
        if (!scheduler.awaitTermination(60, TimeUnit.SECONDS)) {
            scheduler.shutdownNow();
        }
    }

    // Monitor resource utilization and scale as needed
}
