#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define INITIAL_CAPACITY 16
#define LOAD_FACTOR 0.75

typedef struct {
    int userId;
    time_t sessionStart;
    time_t sessionEnd;
    int sessionDuration;
    int activityScore;
} UserSessionData;

typedef struct {
    UserSessionData *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} SessionHashTable;

// External logging function (mock)
void log_event(const char *message) {
    printf("%s\n", message);
}

static int hash(int key, size_t capacity) {
    return key % capacity;
}

SessionHashTable* initializeHashTable() {
    SessionHashTable *table = malloc(sizeof(SessionHashTable));
    if (!table) {
        log_event("Failed to allocate memory for hash table");
        return NULL;
    }

    table->data = calloc(INITIAL_CAPACITY, sizeof(UserSessionData));
    if (!table->data) {
        free(table);
        log_event("Failed to allocate memory for session data");
        return NULL;
    }

    table->capacity = INITIAL_CAPACITY;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);

    log_event("Hash table initialized successfully");

    return table;
}

void resizeHashTable(SessionHashTable *table) {
    size_t new_capacity = table->capacity * 2;
    UserSessionData *new_data = realloc(table->data, new_capacity * sizeof(UserSessionData));

    if (!new_data) {
        log_event("Failed to reallocate memory for hash table");
        return;
    }

    memset(new_data + table->capacity, 0, (new_capacity - table->capacity) * sizeof(UserSessionData));
    table->data = new_data;
    table->capacity = new_capacity;

    log_event("Hash table resized successfully");
}

void insert(SessionHashTable *table, UserSessionData session) {
    pthread_mutex_lock(&table->lock);

    if ((double)table->size / table->capacity >= LOAD_FACTOR) {
        resizeHashTable(table);
    }

    size_t idx = hash(session.userId, table->capacity);
    size_t i = 0;

    while (table->data[idx].userId != 0 && i < table->capacity) {
        size_t step = i * i;
        idx = (idx + step) % table->capacity;
        i++;
    }

    if (i == table->capacity) {
        log_event("Hash table is full, unable to insert");
        pthread_mutex_unlock(&table->lock);
        return;
    }

    table->data[idx] = session;
    table->size++;

    pthread_mutex_unlock(&table->lock);

    log_event("UserSessionData inserted successfully");
}

void* initializeAndManageSessions(void *arg) {
    int seed = *(int*)arg;

    srand(seed);

    SessionHashTable *table = initializeHashTable();
    if (!table) return NULL;

    // Simulate reading from a file descriptor or other data source
    for (int i = 0; i < 10000; ++i) { // Adjust the loop based on dataset size
        UserSessionData session;
        session.userId = rand() % 100000;
        session.sessionStart = time(NULL);
        session.sessionEnd = session.sessionStart + rand() % 3600; 
        session.sessionDuration = (int)difftime(session.sessionEnd, session.sessionStart);
        session.activityScore = rand() % 100;

        insert(table, session);
    }

    // Cleanup
    free(table->data);
    pthread_mutex_destroy(&table->lock);
    free(table);

    log_event("Session management completed and resources deallocated");

    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <seed>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int seed = atoi(argv[1]);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, initializeAndManageSessions, &seed)) {
        log_event("Failed to create a new thread");
        return EXIT_FAILURE;
    }

    pthread_join(thread_id, NULL);

    return EXIT_SUCCESS;
}
