    // Simulate network delay
    sleep(rand() % 3);

    int retry_count = 0;
    while (retry_count < MAX_RETRIES) {
        size_t template_index = rand() % 3;
        strncpy(template, possible_templates[template_index], max_size);

        if (strlen(possible_templates[template_index]) <= max_size) {
            return 1; // Success
        }
        retry_count++;
    }

    return 0; // Failure after retries
}

int is_password_strong(const char *password) {
    int has_upper = 0, has_lower = 0, has_digit = 0, has_special = 0;

    for (size_t i = 0; password[i] != '\0'; ++i) {
        if (isupper(password[i])) has_upper = 1;
        else if (islower(password[i])) has_lower = 1;
        else if (isdigit(password[i])) has_digit = 1;
        else if (!ispunct(password[i])) return 0; // Invalid character
    }

    return strlen(password) >= 8 && has_upper && has_lower && has_digit && has_special;
}
