typedef struct FILE_EVENT {
    FILE_EVENT_TAG event_tag;
    FILE_METADATA metadata;
    FILE_BLOCK_DATA *blocks;
    int block_count;
    pthread_mutex_t lock; // Per-event mutex for fine-grained locking
} FILE_EVENT;

// Cache structure
#define CACHE_SIZE 100

typedef struct LRUCACHE_NODE {
    FILE_EVENT *event;
    struct LRUCACHE_NODE *prev, *next;
} LRUCACHE_NODE;

typedef struct {
    LRUCACHE_NODE *head, *tail;
    LRUCACHE_NODE cache[CACHE_SIZE];
    pthread_mutex_t lock;
} LRUCACHE;

// Dynamic list structure
typedef struct DYNAMIC_LIST {
    FILE_EVENT **events;
    size_t count;
    size_t capacity;
    pthread_rwlock_t rwlock; // Read-write lock for the entire list
    LRUCACHE *cache;
} DYNAMIC_LIST;

