void cache_put(LRUCACHE *cache, FILE_EVENT *event);
FILE_EVENT* encrypt_and_store_event(FILE_EVENT *event, const char *key, const char *algo);

// Initialize the dynamic list
void init_dynamic_list(DYNAMIC_LIST *list) {
    pthread_rwlock_init(&list->rwlock, NULL);
    list->events = NULL;
    list->count = 0;
    list->capacity = 0;

    list->cache = (LRUCACHE*)malloc(sizeof(LRUCACHE));
    pthread_mutex_init(&list->cache->lock, NULL);
    list->cache->head = &list->cache->cache[0];
    list->cache->tail = &list->cache->cache[CACHE_SIZE - 1];

    for (int i = 0; i < CACHE_SIZE - 1; ++i) {
        list->cache->cache[i].next = &list->cache->cache[i + 1];
        list->cache->cache[i].prev = &list->cache->cache[i - 1];
    }
    list->cache->tail->next = NULL;
}

// Destroy the dynamic list
void destroy_dynamic_list(DYNAMIC_LIST *list) {
    pthread_rwlock_destroy(&list->rwlock);
    for (size_t i = 0; i < list->count; ++i) {
        free(list->events[i]->blocks);
        pthread_mutex_destroy(&list->events[i]->lock);
        free(list->events[i]);
    }
    free(list->events);
    pthread_mutex_destroy(&list->cache->lock);
    free(list->cache);
}

// Add a new event
FILE_EVENT* add_event(DYNAMIC_LIST *list, FILE_EVENT_TAG tag, off_t size, time_t last_modified) {
    pthread_rwlock_wrlock(&list->rwlock);

    if (list->count == list->capacity) {
        resize_list(list, list->capacity ? list->capacity * 2 : 16);
    }

    FILE_EVENT *event = (FILE_EVENT*)malloc(sizeof(FILE_EVENT));
    strncpy(event->event_tag.tag, tag.tag, sizeof(event->event_tag.tag));
    event->metadata.size = size;
    event->metadata.last_modified = last_modified;
    pthread_mutex_init(&event->lock, NULL);

    list->events[list->count++] = event;

    pthread_rwlock_unlock(&list->rwlock);
    return encrypt_and_store_event(event, "encryption_key", "AES");
}

// Resize the dynamic list
void resize_list(DYNAMIC_LIST *list, size_t new_capacity) {
    FILE_EVENT **new_events = (FILE_EVENT**)realloc(list->events, new_capacity * sizeof(FILE_EVENT*));
    if (!new_events) return;

    for (size_t i = list->count; i < new_capacity; ++i) {
        new_events[i] = NULL;
    }

    list->events = new_events;
    list->capacity = new_capacity;
}

