#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    double value;
} record;

// Function declarations
record* load_records_from_csv(const char *filename, int *count);
void release_memory(record **records);
int populate_and_sort_records(record **records, const char *csv_filename, int (*compare)(const void *, const void *));
void custom_quicksort(void *base, size_t nmemb, size_t size, int (*compar)(const void *, const void *));
int compare_records(const void *a, const void *b);
int validate_sorted_array(record *records, int count);

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

record* load_records_from_csv(const char *filename, int *count) {
    FILE *file = fopen(filename, "r");
    if (!file) return NULL;

    // Temporary storage to determine the number of records
    char line[256];
    while (fgets(line, sizeof(line), file)) (*count)++;

    rewind(file);

    record *records = malloc(*count * sizeof(record));
    if (!records) {
        fclose(file);
        return NULL;
    }

    for (int i = 0; i < *count; ++i) {
        if (fscanf(file, "%ld,%d,%lf", &records[i].offset, &records[i].key, &records[i].value) != 3) {
            free(records);
            fclose(file);
            return NULL;
        }
    }

    fclose(file);
    return records;
}

void release_memory(record **records) {
    if (records && *records) {
        free(*records);
        *records = NULL;
    }
}

int populate_and_sort_records(record **records, const char *csv_filename, int (*compare)(const void *, const void *)) {
    pthread_mutex_lock(&mutex);

    int count = 0;
    record *temp_records = load_records_from_csv(csv_filename, &count);

    if (!temp_records) {
        pthread_mutex_unlock(&mutex);
        return -1; // Error code for memory allocation failure
    }

    *records = temp_records;

    custom_quicksort(*records, count, sizeof(record), compare);

    int valid = validate_sorted_array(*records, count);
    if (!valid) {
        release_memory(records);
        pthread_mutex_unlock(&mutex);
        return -2; // Error code for validation failure
    }

    pthread_mutex_unlock(&mutex);
    return 0;
}

void custom_quicksort(void *base, size_t nmemb, size_t size, int (*compar)(const void *, const void *)) {
    // Implement quicksort or other sorting algorithm as needed
    qsort(base, nmemb, size, compar);
}

int compare_records(const void *a, const void *b) {
    record *recordA = (record *)a;
    record *recordB = (record *)b;
    return (recordA->key - recordB->key);
}

int validate_sorted_array(record *records, int count) {
    for (int i = 1; i < count; ++i) {
        if (compare_records(&records[i-1], &records[i]) > 0) {
            return 0;
        }
    }
    return 1;
}
