// Define the data_entry structure
typedef struct {
    double value;
    char *name;
    int id;
} data_entry;

// Function to allocate memory for an array of data_entries
data_entry* create_data_entries(int count, const char names[][50], int name_count) {
    if (count <= 0 || name_count <= 0) return NULL;

    // Allocate memory for the array of structures
    data_entry *entries = (data_entry*)malloc(count * sizeof(data_entry));
    if (!entries) {
        fprintf(stderr, "Memory allocation failed for data entries.\n");
        return NULL;
    }

    // Populate each data_entry with unique ID and corresponding name
    for (int i = 0; i < count && i < name_count; ++i) {
        entries[i].id = i + 1;  // Assign a unique ID starting from 1
        entries[i].value = (double)(i + 1);  // Example: Set value equal to ID

        // Allocate memory for the name string and handle allocation failure
        entries[i].name = (char*)malloc((strlen(names[i]) + 1) * sizeof(char));
        if (!entries[i].name) {
            fprintf(stderr, "Memory allocation failed for name at index %d.\n", i);

            // Free already allocated memory on partial failure before returning
            for (int j = 0; j < i; ++j) {
                free(entries[j].name);
            }
            free(entries);
            return NULL;
        }

        // Copy the name from predefined list to the structure's name field
        strcpy(entries[i].name, names[i]);
    }

    return entries;
}

// Function to deallocate memory for an array of data_entries
void free_data_entries(data_entry *entries, int count) {
    if (!entries) return;

    for (int i = 0; i < count; ++i) {
        free(entries[i].name);  // Free each name string
    }

    free(entries);  // Finally, free the array of data_entries
}

// Example usage function to demonstrate allocation and deallocation
void manage_data_entries(int entry_count, const char names[][50], int name_count) {
    data_entry *entries = create_data_entries(entry_count, names, name_count);

    if (entries) {
        // Perform operations with the entries
        for (int i = 0; i < entry_count && i < name_count; ++i) {
            printf("ID: %d, Value: %.2f, Name: %s\n", entries[i].id, entries[i].value, entries[i].name);
        }

        // Free the allocated memory
        free_data_entries(entries, entry_count);
    }
}

int main() {
    const char names[][50] = {"Alice", "Bob", "Charlie", "Diana"};
    int name_count = sizeof(names) / sizeof(names[0]);

    manage_data_entries(4, names, name_count);  // Manage data entries with predefined names

    return 0;
}
