```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 64

typedef enum {
    EVENT_TYPE_1,
    EVENT_TYPE_2,
    // Add more event types as needed
} EventType;

typedef struct {
    time_t timestamp;
    EventType event_type;
    char *message; // Variable-length message
} NetworkEventLogEntry;

typedef struct {
    NetworkEventLogEntry *entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // Mutex for thread safety
} NetworkEventLogArray;

// Function prototypes
void initialize_log_array(NetworkEventLogArray *log_array);
void destroy_log_array(NetworkEventLogArray *log_array);
int add_entry(NetworkEventLogArray *log_array, time_t timestamp, EventType event_type, const char *message);
int update_entry(NetworkEventLogArray *log_array, time_t timestamp, EventType event_type, const char *new_message);
NetworkEventLogEntry* get_entries_by_event_type(NetworkEventLogArray *log_array, EventType event_type);
void serialize_log_array(const NetworkEventLogArray *log_array, const char *filename);
int deserialize_log_array(NetworkEventLogArray *log_array, const char *filename);

// Function implementations
void initialize_log_array(NetworkEventLogArray *log_array) {
    log_array->entries = malloc(INITIAL_CAPACITY * sizeof(NetworkEventLogEntry));
    if (!log_array->entries) return;
    log_array->capacity = INITIAL_CAPACITY;
    log_array->count = 0;
    pthread_mutex_init(&log_array->lock, NULL);
}

void destroy_log_array(NetworkEventLogArray *log_array) {
    for (size_t i = 0; i < log_array->count; ++i) {
        free(log_array->entries[i].message);
    }
    free(log_array->entries);
    pthread_mutex_destroy(&log_array->lock);
}

int add_entry(NetworkEventLogArray *log_array, time_t timestamp, EventType event_type, const char *message) {
    pthread_mutex_lock(&log_array->lock);

    if (log_array->count == log_array->capacity) {
        size_t new_capacity = log_array->capacity * 2;
        NetworkEventLogEntry *new_entries = realloc(log_array->entries, new_capacity * sizeof(NetworkEventLogEntry));
        if (!new_entries) {
            pthread_mutex_unlock(&log_array->lock);
            return -1; // Memory allocation failed
        }
        log_array->entries = new_entries;
        log_array->capacity = new_capacity;
    }

    NetworkEventLogEntry *entry = &log_array->entries[log_array->count++];
    entry->timestamp = timestamp;
    entry->event_type = event_type;
    entry->message = strdup(message);

    pthread_mutex_unlock(&log_array->lock);
    return 0; // Success
}

int update_entry(NetworkEventLogArray *log_array, time_t timestamp, EventType event_type, const char *new_message) {
    pthread_mutex_lock(&log_array->lock);

    for (size_t i = 0; i < log_array->count; ++i) {
        if (log_array->entries[i].timestamp == timestamp && log_array->entries[i].event_type == event_type) {
            free(log_array->entries[i].message);
            log_array->entries[i].message = strdup(new_message);
            pthread_mutex_unlock(&log_array->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&log_array->lock);
    return -1; // Entry not found
}

NetworkEventLogEntry* get_entries_by_event_type(NetworkEventLogArray *log_array, EventType event_type) {
    size_t current_count = log_array->count;
    NetworkEventLogEntry temp_array[current_count];

    pthread_mutex_lock(&log_array->lock);
    for (size_t i = 0; i < current_count; ++i) {
        if (log_array->entries[i].event_type == event_type) {
            memcpy(&temp_array[i], &log_array->entries[i], sizeof(NetworkEventLogEntry));
            temp_array[i].message = strdup(log_array->entries[i].message);
        }
    }
    pthread_mutex_unlock(&log_array->lock);

    return temp_array;
}

void serialize_log_array(const NetworkEventLogArray *log_array, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&(log_array->count), sizeof(size_t), 1, file);
    for (size_t i = 0; i < log_array->count; ++i) {
        fwrite(&log_array->entries[i].timestamp, sizeof(time_t), 1, file);
        fwrite(&log_array->entries[i].event_type, sizeof(EventType), 1, file);
        size_t message_length = strlen(log_array->entries[i].message) + 1;
        fwrite(&message_length, sizeof(size_t), 1, file);
        fwrite(log_array->entries[i].message, sizeof(char), message_length, file);
    }

    fclose(file);
}

int deserialize_log_array(NetworkEventLogArray *log_array, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    for (size_t i = log_array->count; i < count; ++i) {
        add_entry(log_array, 0, 0, ""); // Initialize space
    }

    pthread_mutex_lock(&log_array->lock);
    for (size_t i = 0; i < count; ++i) {
        fread(&log_array->entries[i].timestamp, sizeof(time_t), 1, file);
        fread(&log_array->entries[i].event_type, sizeof(EventType), 1, file);

        size_t message_length;
        fread(&message_length, sizeof(size_t), 1, file);
        log_array->entries[i].message = malloc(message_length);
        if (!log_array->entries[i].message) {
            pthread_mutex_unlock(&log_array->lock);
            fclose(file);
            return -1; // Memory allocation failed
        }
        fread(log_array->entries[i].message, sizeof(char), message_length, file);
    }
    log_array->count = count;
    pthread_mutex_unlock(&log_array->lock);

    fclose(file);
    return 0; // Success
}
