int initialize_records_manager(RecordsManager *manager, size_t num_records) {
    if (num_records > MAX_RECORDS || num_records == 0) {
        return -1; // Invalid input
    }

    manager->records = malloc(num_records * sizeof(Record));
    if (!manager->records) {
