#define MAX_QUEUE_SIZE 10000

typedef struct {
    int PHY_RX_FRAME_TAG;
    // Other relevant fields for RRC_CONNECTION_ESTABLISHMENT_REQUEST and NAS_MESSAGE
} LTE_PHY_RX_FRAME;

typedef struct {
    LTE_PHY_RX_FRAME frames[MAX_QUEUE_SIZE];
    int front, rear;
    sem_t full, empty;
    pthread_mutex_t lock;
} Queue;

Queue* create_queue() {
    Queue* q = (Queue*)malloc(sizeof(Queue));
    q->front = q->rear = 0;
    sem_init(&q->full, 0, 0);
    sem_init(&q->empty, 0, MAX_QUEUE_SIZE);
    pthread_mutex_init(&q->lock, NULL);
    return q;
}

bool is_queue_full(Queue* q) {
    return ((q->rear + 1) % MAX_QUEUE_SIZE) == q->front;
}

bool is_queue_empty(Queue* q) {
    return q->front == q->rear;
}

void enqueue(Queue* q, LTE_PHY_RX_FRAME frame) {
    sem_wait(&q->empty);
    pthread_mutex_lock(&q->lock);
    q->frames[q->rear] = frame;
    q->rear = (q->rear + 1) % MAX_QUEUE_SIZE;
    pthread_mutex_unlock(&q->lock);
    sem_post(&q->full);
}

LTE_PHY_RX_FRAME dequeue(Queue* q) {
    LTE_PHY_RX_FRAME frame;
    sem_wait(&q->full);
    pthread_mutex_lock(&q->lock);
    frame = q->frames[q->front];
    q->front = (q->front + 1) % MAX_QUEUE_SIZE;
    pthread_mutex_unlock(&q->lock);
    sem_post(&q->empty);
    return frame;
}

