```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRING_SIZE 256
#define CONFIG_FILE "config.txt"

typedef struct edge {
    struct node *destination;
    double weight;
    time_t expiration_timestamp;
} Edge;

typedef struct metadata {
    // Add necessary fields for metadata
    char description[MAX_STRING_SIZE];
} Metadata;

typedef struct node {
    int key;
    struct node *left, *right;
    Edge *edges;
    size_t edge_count;
    int ref_count;
    pthread_mutex_t lock;
    Metadata *metadata;
} Node;

// Function prototypes
Node* create_node(int key);
void insert_node(Node **root, Node *new_node);
Edge* create_edge(Node *destination, double weight, time_t expiration_timestamp);
Metadata* create_metadata(const char *description);
int load_configuration(Node **root, const char *config_file);

// Utility functions for memory allocation and error handling
void *custom_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Function to initialize the resource management system
int init_resource_management_system(Node **root) {
    srand(time(NULL));
    pthread_mutex_init(&(*root)->lock, NULL);

    // Load configuration and populate the binary search tree
    int items_count = load_configuration(root, CONFIG_FILE);
    if (items_count < 0) {
        fprintf(stderr, "Failed to load configuration\n");
        return -1;
    }

    return items_count;
}

Node* create_node(int key) {
    Node *node = custom_malloc(sizeof(Node));
    node->key = key;
    node->left = node->right = NULL;
    node->edges = NULL;
    node->edge_count = 0;
    node->ref_count = 1;
    pthread_mutex_init(&node->lock, NULL);
    node->metadata = create_metadata("Default metadata");
    return node;
}

void insert_node(Node **root, Node *new_node) {
    if (*root == NULL) {
        *root = new_node;
        return;
    }

    pthread_mutex_lock(&(*root)->lock);
    if (new_node->key < (*root)->key) {
        insert_node(&(*root)->left, new_node);
    } else if (new_node->key > (*root)->key) {
        insert_node(&(*root)->right, new_node);
    }
    pthread_mutex_unlock(&(*root)->lock);
}

Edge* create_edge(Node *destination, double weight, time_t expiration_timestamp) {
    Edge *edge = custom_malloc(sizeof(Edge));
    edge->destination = destination;
    edge->weight = weight;
    edge->expiration_timestamp = expiration_timestamp;
    return edge;
}

Metadata* create_metadata(const char *description) {
    Metadata *metadata = custom_malloc(sizeof(Metadata));
    strncpy(metadata->description, description, MAX_STRING_SIZE - 1);
    metadata->description[MAX_STRING_SIZE - 1] = '\0';
    return metadata;
}

int load_configuration(Node **root, const char *config_file) {
    FILE *file = fopen(config_file, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return -1;
    }

    int items_count = 0;
    while (fscanf(file, "%d", &(*root)->key) == 1) {
        Node *new_node = create_node((*root)->key);
        insert_node(root, new_node);
        items_count++;

        // Load edges for the node
        int edge_count;
        fscanf(file, "%d", &edge_count);
        new_node->edges = custom_malloc(edge_count * sizeof(Edge));
        new_node->edge_count = edge_count;

        for (int i = 0; i < edge_count; ++i) {
            Node *destination = NULL; // Assume a function to find the destination node
            double weight = (double)rand() / RAND_MAX;
            time_t expiration_timestamp = time(NULL) + rand() % 100000;

            new_node->edges[i] = create_edge(destination, weight, expiration_timestamp);
        }
    }

    fclose(file);
    return items_count;
}

int main() {
    Node *root = create_node(0); // Placeholder root node
    int items_count = init_resource_management_system(&root);

    if (items_count > 0) {
        printf("Resource management system initialized with %d items.\n", items_count);
    } else {
        fprintf(stderr, "Failed to initialize resource management system\n");
    }

    return 0;
}
```

