['Below is a C code implementation for managing a dynamic dataset of geographic points using a self-balancing binary search tree (AVL Tree). This example includes functions to initialize, insert, delete, and retrieve nodes, ensuring thread safety with mutex locks.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    double latitude;
    double longitude;
    time_t timestamp;
} GeoPoint;

typedef struct Node {
    GeoPoint point;
    char *location_name;
    struct Node *left, *right;
    int height;
} Node;

typedef struct {
    Node *root;
    pthread_mutex_t lock;
} GeoTree;

int max(int a, int b) {
    return (a > b) ? a : b;
}

int getHeight(Node *N) {
    if (N == NULL)
        return 0;
    return N->height;
}

Node* newNode(GeoPoint point, char *name) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    node->point = point;
    node->location_name = strdup(name);
    if (!node->location_name) {
        free(node);
        return NULL;
    }

    node->left = node->right = NULL;
    node->height = 1;
    return node;
}

Node *rightRotate(Node *y) {
    Node *x = y->left;
    Node *T2 = x->right;

    x->right = y;
    y->left = T2;

    y->height = max(getHeight(y->left), getHeight(y->right)) + 1;
    x->height = max(getHeight(x->left), getHeight(x->right)) + 1;

    return x;
}

Node *leftRotate(Node *x) {
    Node *y = x->right;
    Node *T2 = y->left;

    y->left = x;
    x->right = T2;

    x->height = max(getHeight(x->left), getHeight(x->right)) + 1;
    y->height = max(getHeight(y->left), getHeight(y->right)) + 1;

    return y;
}

int getBalance(Node *N) {
    if (N == NULL)
        return 0;
    return getHeight(N->left) - getHeight(N->right);
}

Node* insert(Node* node, GeoPoint point, char *name) {
    if (node == NULL)
        return newNode(point, name);

    if ((point.latitude < node->point.latitude) ||
        (point.latitude == node->point.latitude && point.longitude < node->point.longitude)) {

        node->left = insert(node->left, point, name);
    } else if ((point.latitude > node->point.latitude) ||
               (point.latitude == node->point.latitude && point.longitude > node->point.longitude)) {

        node->right = insert(node->right, point, name);
    } else {
        free(name);
        return node;
    }

    node->height = 1 + max(getHeight(node->left), getHeight(node->right));
    int balance = getBalance(node);

    if (balance > 1 && (point.latitude < node->left->point.latitude ||
                        (point.latitude == node->left->point.latitude &&
                         point.longitude <= node->left->point.longitude))) {
        return rightRotate(node);
    }

    if (balance < -1 && (point.latitude > node->right->point.latitude ||
                         (point.latitude == node->right->point.latitude &&
                          point.longitude >= node->right->point.longitude))) {
        return leftRotate(node);
    }

    if (balance > 1 && (point.latitude > node->left->point.latitude ||
                        (point.latitude == node->left->point.latitude &&
                         point.longitude > node->left->point.longitude))) {
        node->left = leftRotate(node->left);
        return rightRotate(node);
    }

    if (balance < -1 && (point.latitude < node->right->point.latitude ||
                         (point.latitude == node->right->point.latitude &&
                          point.longitude < node->right->point.longitude))) {
        node->right = rightRotate(node->right);
        return leftRotate(node);
    }

    return node;
}

Node* minValueNode(Node* node) {
    Node* current = node;

    while (current->left != NULL)
        current = current->left;

    return current;
}

Node *deleteNode(Node* root, GeoPoint point) {
    if (root == NULL)
        return root;

    if ((point.latitude < root->point.latitude) ||
        (point.latitude == root->point.latitude && point.longitude < root->point.longitude)) {

        root->left = deleteNode(root->left, point);
    } else if ((point.latitude > root->point.latitude) ||
               (point.latitude == root->point.latitude && point.longitude > root->point.longitude)) {

        root->right = deleteNode(root->right, point);
    } else {
        if ((root->left == NULL) || (root->right == NULL)) {
            Node *temp = root->left ? root->left : root->right;

            if (temp == NULL) {
                temp = root;
                root = NULL;
            } else
                *root = *temp;

            free(temp->location_name);
            free(temp);
        } else {
            Node* temp = minValueNode(root->right);

            root->point = temp->point;
            root->location_name = strdup(temp->location_name);
            if (!root->location_name) {
                fprintf(stderr, "Memory allocation failed\n");
                exit(EXIT_FAILURE);
            }

            root->right = deleteNode(root->right, temp->point);
        }
    }

    if (root == NULL)
      return root;

    root->height = 1 + max(getHeight(root->left), getHeight(root->right));
    int balance = getBalance(root);

    if (balance > 1 && getBalance(root->left) >= 0)
        return rightRotate(root);

    if (balance > 1 && getBalance(root->left) < 0) {
        root->left = leftRotate(root->left);
        return rightRotate(root);
    }

    if (balance < -1 && getBalance(root->right) <= 0)
        return leftRotate(root);

    if (balance < -1 && getBalance(root->right) > 0) {
        root->right = rightRotate(root->right);
        return leftRotate(root);
    }

    return root;
}

GeoTree* createGeoTree() {
    GeoTree *tree = (GeoTree*)malloc(sizeof(GeoTree));
    if (!tree) return NULL;

    tree->root = NULL;
    pthread_mutex_init(&tree->lock, NULL);

    return tree;
}

void freeNode(Node* node) {
    if (node == NULL)
        return;

    free(node->location_name);
    freeNode(node->left);
    freeNode(node->right);
    free(node);
}

void deleteGeoTree(GeoTree *tree) {
    pthread_mutex_lock(&tree->lock);
    freeNode(tree->root);
    pthread_mutex_unlock(&tree->lock);

    pthread_mutex_destroy(&tree->lock);
    free(tree);
}

void insertPoint(GeoTree *tree, GeoPoint point, char *name) {
    pthread_mutex_lock(&tree->lock);
    tree->root = insert(tree->root, point, name);
    pthread_mutex_unlock(&tree->lock);
}

void deletePoint(GeoTree *tree, GeoPoint point) {
    pthread_mutex_lock(&tree->lock);
    tree->root = deleteNode(tree->root, point);
    pthread_mutex_unlock(&tree->lock);
}
```

