["```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

// Constants
#define INITIAL_CAPACITY 10
#define ALIGNMENT 64

typedef enum {
    FILE_EVENT_TAG_1,
    FILE_EVENT_TAG_2,
    // Add more tags as needed
} FILE_EVENT_TAG;

typedef struct {
    uint32_t size;
    time_t last_modified;
} FileMetadata;

typedef struct {
    FILE_EVENT_TAG tag;
    FileMetadata metadata;
    char *blocks; // Variable-length sequence of FILE_BLOCK_DATA tags
    size_t block_count;
} FileEvent;

typedef struct {
    FileEvent **events;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} EventList;

// Helper function for aligned memory allocation
void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL; // Allocation failed
    }
    return ptr;
}

// Function to initialize the event list
int init_event_list(EventList *list) {
    if (!list) return -1;

    pthread_mutex_init(&list->lock, NULL);
    list->capacity = INITIAL_CAPACITY;
    list->count = 0;
    list->events = aligned_alloc(ALIGNMENT, sizeof(FileEvent*) * list->capacity);
    if (!list->events) return -1;

    for (size_t i = 0; i < list->capacity; ++i) {
        list->events[i] = NULL;
    }
    return 0;
}

// Function to resize the event list
int resize_event_list(EventList *list) {
    if (!list) return -1;

    size_t new_capacity = list->capacity * 2;
    FileEvent **new_events = aligned_alloc(ALIGNMENT, sizeof(FileEvent*) * new_capacity);
    if (!new_events) return -1;

    for (size_t i = 0; i < list->count; ++i) {
        new_events[i] = list->events[i];
    }

    free(list->events);
    list->events = new_events;
    list->capacity = new_capacity;

    return 0;
}

// Function to add an event
int add_event(EventList *list, FileEvent *event) {
    if (!list || !event) return -1;

    pthread_mutex_lock(&list->lock);

    // Resize if necessary
    if (list->count == list->capacity) {
        int status = resize_event_list(list);
        if (status != 0) {
            pthread_mutex_unlock(&list->lock);
            return status;
        }
    }

    // Allocate memory for the event's blocks with alignment
    size_t block_size = event->block_count * sizeof(char); // Assume each block is 1 byte for simplicity
    void *aligned_blocks = aligned_alloc(ALIGNMENT, block_size);
    if (!aligned_blocks) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    memcpy(aligned_blocks, event->blocks, block_size);

    list->events[list->count++] = (FileEvent*)malloc(sizeof(FileEvent));
    if (!list->events[list->count - 1]) {
        free(aligned_blocks);
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    list->events[list->count - 1]->tag = event->tag;
    list->events[list->count - 1]->metadata.size = event->metadata.size;
    list->events[list->count - 1]->metadata.last_modified = event->metadata.last_modified;
    list->events[list->count - 1]->blocks = (char*)aligned_blocks;
    list->events[list->count - 1]->block_count = event->block_count;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to remove an event by index
int remove_event(EventList *list, size_t index) {
    if (!list || index >= list->count) return -1;

    pthread_mutex_lock(&list->lock);

    if (index < list->count) {
        free(list->events[index]->blocks);
        free(list->events[index]);
        for (size_t i = index; i < list->count - 1; ++i) {
            list->events[i] = list->events[i + 1];
        }
        --list->count;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to free the event list
void destroy_event_list(EventList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        free(list->events[i]->blocks);
        free(list->events[i]);
    }

    free(list->events);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
