```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_HUMIDITY_THRESHOLD 75.0

typedef struct {
    time_t start_time;
    time_t end_time;
} timestamp;

typedef struct {
    double metric_value;
    char status_indicator;
    timestamp log_timestamp;
} resource_usage;

typedef struct {
    double temperature; // Celsius
    int humidity;       // Percentage
    double pressure;    // hPa
} environmental_data;

// Global mutex for thread safety
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

int allocate_resource_usages(resource_usage **usages, size_t count) {
    pthread_mutex_lock(&global_lock);
    *usages = (resource_usage *)malloc(count * sizeof(resource_usage));
    if (*usages == NULL) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&global_lock);
        return -1;
    }
    pthread_mutex_unlock(&global_lock);
    return 0;
}

void free_resource_usages(resource_usage *usages) {
    free(usages);
}

int add_resource_usage(resource_usage **usages, size_t *count, resource_usage new_record) {
    pthread_mutex_lock(&global_lock);

    // Reallocate memory
    resource_usage *temp = realloc(*usages, (*count + 1) * sizeof(resource_usage));
    if (temp == NULL) {
        perror("Memory reallocation failed");
        pthread_mutex_unlock(&global_lock);
        return -1;
    }
    *usages = temp;

    // Add new record
    (*usages)[*count] = new_record;
    (*count)++;

    // Sort by timestamps
    for (size_t i = 0; i < *count - 1; ++i) {
        for (size_t j = 0; j < *count - i - 1; ++j) {
            if ((*usages)[j].log_timestamp.start_time > (*usages)[j + 1].log_timestamp.start_time) {
                resource_usage temp_record = (*usages)[j];
                (*usages)[j] = (*usages)[j + 1];
                (*usages)[j + 1] = temp_record;
            }
        }
    }

    pthread_mutex_unlock(&global_lock);
    return 0;
}

int filter_by_humidity(resource_usage **usages, size_t *count) {
    pthread_mutex_lock(&global_lock);

    resource_usage *filtered = (resource_usage *)malloc(*count * sizeof(resource_usage));
    if (filtered == NULL) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&global_lock);
        return -1;
    }

    size_t new_count = 0;
    for (size_t i = 0; i < *count; ++i) {
        if ((*usages)[i].metric_value <= MAX_HUMIDITY_THRESHOLD) {
            filtered[new_count++] = (*usages)[i];
        }
    }

    free(*usages);
    *usages = filtered;
    *count = new_count;

    pthread_mutex_unlock(&global_lock);
    return 0;
}

int allocate_environmental_data(environmental_data **data, size_t count) {
    pthread_mutex_lock(&global_lock);

    *data = (environmental_data *)malloc(count * sizeof(environmental_data));
    if (*data == NULL) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&global_lock);
        return -1;
    }

    // Simulate environmental data
    for (size_t i = 0; i < count; ++i) {
        (*data)[i].temperature = rand() % 40; // Celsius between 0 and 39
        (*data)[i].humidity = rand() % 100;   // Percentage 0 to 99
        (*data)[i].pressure = 950 + (rand() % 51); // hPa between 950 and 1000
    }

    // Sort by temperature
    for (size_t i = 0; i < count - 1; ++i) {
        for (size_t j = 0; j < count - i - 1; ++j) {
            if ((*data)[j].temperature > (*data)[j + 1].temperature) {
                environmental_data temp_record = (*data)[j];
                (*data)[j] = (*data)[j + 1];
                (*data)[j + 1] = temp_record;
            }
        }
    }

    pthread_mutex_unlock(&global_lock);
    return 0;
}

void free_environmental_data(environmental_data *data) {
    free(data);
}

int main() {
    resource_usage *resource_records = NULL;
    size_t record_count = 0;

    if (allocate_resource_usages(&resource_records, 10) != 0) {
        fprintf(stderr, "Failed to allocate initial resources\n");
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < 10; ++i) {
        resource_usage new_record;
        new_record.metric_value = rand() % 100 / 10.0;
        new_record.status_indicator = 'A' + (rand() % 26);

        time(&new_record.log_timestamp.start_time); // Simulate current time
        new_record.log_timestamp.end_time = new_record.log_timestamp.start_time + (rand() % 3600);

        if (add_resource_usage(&resource_records, &record_count, new_record) != 0) {
            fprintf(stderr, "Failed to add resource usage record\n");
            free_resource_usages(resource_records);
            return EXIT_FAILURE;
        }
    }

    // Filtering by humidity
    if (filter_by_humidity(&resource_records, &record_count) != 0) {
        fprintf(stderr, "Failed to filter records by humidity\n");
        free_resource_usages(resource_records);
        return EXIT_FAILURE;
    }

    environmental_data *env_data = NULL;
    if (allocate_environmental_data(&env_data, 10) != 0) {
        fprintf(stderr, "Failed to allocate environmental data\n");
        free_resource_usages(resource_records);
        return EXIT_FAILURE;
    }

    // Simulated operations and memory cleanup
    for (size_t i = 0; i < record_count; ++i) {
        printf("Metric: %.1f, Status: %c, Start Time: %ld, End Time: %ld\n",
               resource_records[i].metric_value,
               resource_records[i].status_indicator,
               resource_records[i].log_timestamp.start_time,
               resource_records[i].log_timestamp.end_time);
    }

    free_resource_usages(resource_records);
    free_environmental_data(env_data);

    return EXIT_SUCCESS;
}
