#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the NetworkPerformanceMetrics structure
typedef struct {
    int cellId;
    time_t timeStamp;
    double throughput;
} NetworkPerformanceMetrics;

// Node for linked list
typedef struct Node {
    NetworkPerformanceMetrics data;
    struct Node* next;
} Node;

// Hash table entry
typedef struct {
    void* key;
    void* value;
} HashEntry;

// Define a hash table
#define HASH_TABLE_SIZE 101

typedef struct {
    HashEntry* entries[HASH_TABLE_SIZE];
    pthread_mutex_t lock;
} HashTable;

// Function prototypes
NetworkPerformanceMetrics* allocateMetricsArray(int size, unsigned int seed);
void freeMetricsArray(NetworkPerformanceMetrics* metrics, int size);
Node* insertIntoLinkedList(Node* head, NetworkPerformanceMetrics data);
HashTable* initializeHashTable();
void hashInsert(HashTable* table, void* key, void* value);
void* hashRetrieve(HashTable* table, void* key);
void freeHashTable(HashTable* table);

// Helper functions
unsigned long hashFunction(void* key) {
    unsigned char* str = (unsigned char*)key;
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % HASH_TABLE_SIZE;
}

NetworkPerformanceMetrics* allocateMetricsArray(int size, unsigned int seed) {
    NetworkPerformanceMetrics* metrics = (NetworkPerformanceMetrics*)malloc(size * sizeof(NetworkPerformanceMetrics));
    if (!metrics) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    srand(seed);

    for (int i = 0; i < size; ++i) {
        metrics[i].cellId = i;
        metrics[i].timeStamp = time(NULL);
        // Simulate throughput with random value
        metrics[i].throughput = ((double)rand() / RAND_MAX) * 100.0;

        // Initialize linked list and hash table for each metric
        Node* head = NULL; 
        HashTable* hashTable = initializeHashTable();

        // Insert into the linked list (example operation)
        head = insertIntoLinkedList(head, metrics[i]);

        // Example usage of hash table
        double* floatKey = malloc(sizeof(double));
        *floatKey = metrics[i].throughput;
        int* intKey = malloc(sizeof(int));
        *intKey = metrics[i].cellId;

        hashInsert(hashTable, floatKey, &metrics[i]);
        hashInsert(hashTable, intKey, &metrics[i]);

        // Clean up hash table and linked list
        freeHashTable(hashTable);
    }

    return metrics;
}

void freeMetricsArray(NetworkPerformanceMetrics* metrics, int size) {
    if (metrics) {
        free(metrics);
    }
}

Node* insertIntoLinkedList(Node* head, NetworkPerformanceMetrics data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    newNode->data = data;
    newNode->next = head;
    return newNode;
}

HashTable* initializeHashTable() {
    HashTable* table = (HashTable*)calloc(1, sizeof(HashTable));
    if (!table) {
        perror("Failed to allocate memory for hash table");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void hashInsert(HashTable* table, void* key, void* value) {
    pthread_mutex_lock(&table->lock);

    unsigned long index = hashFunction(key);
    HashEntry* entry = (HashEntry*)malloc(sizeof(HashEntry));
    if (!entry) {
        perror("Failed to allocate memory for hash entry");
        exit(EXIT_FAILURE);
    }

    entry->key = key;
    entry->value = value;
    table->entries[index] = entry;

    pthread_mutex_unlock(&table->lock);
}

void* hashRetrieve(HashTable* table, void* key) {
    unsigned long index = hashFunction(key);

    pthread_mutex_lock(&table->lock);
    if (table->entries[index]) {
        if (strcmp((char*)key, (char*)(table->entries[index]->key)) == 0) {
            pthread_mutex_unlock(&table->lock);
            return table->entries[index]->value;
        }
    }
    pthread_mutex_unlock(&table->lock);

    return NULL;
}

void freeHashTable(HashTable* table) {
    if (!table) return;

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashEntry* entry = table->entries[i];
        if (entry) {
            free(entry->key);
            free(entry->value);
            free(entry);
        }
    }

    pthread_mutex_destroy(&table->lock);
    free(table);
}

int main() {
    int size = 10;
    unsigned int seed = 12345;

    NetworkPerformanceMetrics* metrics = allocateMetricsArray(size, seed);

    // Example retrieval
    for (int i = 0; i < size; ++i) {
        double* floatKey = malloc(sizeof(double));
        *floatKey = metrics[i].throughput;
        int* intKey = malloc(sizeof(int));
        *intKey = metrics[i].cellId;

        NetworkPerformanceMetrics* retrievedData = (NetworkPerformanceMetrics*)hashRetrieve(initializeHashTable(), floatKey);
        if (retrievedData) {
            printf("Retrieved: CellID=%d, Throughput=%.2f\n", retrievedData->cellId, retrievedData->throughput);
        }

        free(floatKey);
    }

    freeMetricsArray(metrics, size);

    return 0;
}
