// Thread-safe data structure to store rolling medians
typedef struct {
    float* temperatures;
    size_t size;
    pthread_mutex_t lock;
} RollingMedian;

void initRollingMedian(RollingMedian* rm, size_t size) {
    rm->temperatures = (float*)malloc(size * sizeof(float));
    if (!rm->temperatures) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    rm->size = size;
    pthread_mutex_init(&rm->lock, NULL);
}

void freeRollingMedian(RollingMedian* rm) {
    free(rm->temperatures);
    pthread_mutex_destroy(&rm->lock);
}

float calculateMedian(float* temperatures, size_t size) {
    float* tempCopy = (float*)malloc(size * sizeof(float));
    if (!tempCopy) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    memcpy(tempCopy, temperatures, size * sizeof(float));

    // Simple bubble sort for sorting
    for (size_t i = 0; i < size - 1; ++i) {
        for (size_t j = 0; j < size - i - 1; ++j) {
            if (tempCopy[j] > tempCopy[j + 1]) {
                float swap = tempCopy[j];
                tempCopy[j] = tempCopy[j + 1];
                tempCopy[j + 1] = swap;
            }
        }
    }

    float median;
    if (size % 2 == 0) {
        median = (tempCopy[size / 2 - 1] + tempCopy[size / 2]) / 2.0f;
    } else {
        median = tempCopy[size / 2];
    }

    free(tempCopy);
    return median;
}

