} MAC_FRAME_DATA;

typedef struct {
    MAC_EVENT_TAG mac_event_tag;
    long timestamp;
    MAC_FRAME_DATA *frame_data;
    size_t frame_count;
} NetworkEvent;

typedef struct {
    int id;
    NetworkEvent *events;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} EventList;

void initialize_list(EventList *list) {
    list->id = 0;
    list->capacity = INITIAL_CAPACITY;
    list->count = 0;
    list->events = malloc(sizeof(NetworkEvent) * list->capacity);
    if (!list->events) {
        perror("Failed to allocate memory for events");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&list->lock, NULL);
}

void free_list(EventList *list) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        free(list->events[i].frame_data);
    }
    free(list->events);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

void resize_list(EventList *list, size_t new_capacity) {
    NetworkEvent *new_events = realloc(list->events, sizeof(NetworkEvent) * new_capacity);
    if (!new_events) {
        perror("Failed to reallocate memory for events");
        exit(EXIT_FAILURE);
    }
    list->events = new_events;
    list->capacity = new_capacity;
}

void add_event(EventList *list, MAC_EVENT_TAG tag, long timestamp, MAC_FRAME_DATA *frame_data, size_t frame_count) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        resize_list(list, list->capacity * 2);
    }

    NetworkEvent new_event;
    new_event.mac_event_tag = tag;
    new_event.timestamp = timestamp;

    // Allocate and initialize frame_data
    new_event.frame_data = malloc(sizeof(MAC_FRAME_DATA) * frame_count);
    if (!new_event.frame_data) {
        perror("Failed to allocate memory for frame data");
        pthread_mutex_unlock(&list->lock);
        exit(EXIT_FAILURE);
    }

    memcpy(new_event.frame_data, frame_data, sizeof(MAC_FRAME_DATA) * frame_count);

    new_event.frame_count = frame_count;
    list->events[list->count++] = new_event;

    pthread_mutex_unlock(&list->lock);
}

void handle_external_failure() {
