['Below is an implementation of the described Rust function, incorporating the necessary components for managing records in a distributed system environment with a focus on scalability, reliability, and efficient resource utilization.

```rust
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};
use rand::Rng;
use rand::distributions::{Distribution, Uniform};

const MAX_OFFSET: i64 = 1_000_000;
const FLOAT_RANGE_START: f32 = 0.0;
const FLOAT_RANGE_END: f32 = 100.0;
const TOTAL_FLOAT_SUM_THRESHOLD: f32 = 10_000.0;
const HASH_TABLE_SIZE: usize = 1024;

#[derive(Clone)]
struct Record {
    int_value: i32,
}

fn main() {
    let (status, logs) = manage_records(5);
    println!("Status: {}", status);
    if !logs.is_empty() {
        println!("Logs:\n{}", logs.join("\n"));
    }
}

fn manage_records(num_threads: usize) -> (bool, Vec<String>) {
    let records = Arc::new(Mutex::new(HashMap::with_capacity(HASH_TABLE_SIZE)));
    let log_messages = Arc::new(Mutex::new(Vec::new()));
    let start_time = Instant::now();

    let mut handles = vec![];

    for i in 0..num_threads {
        let records_clone = Arc::clone(&records);
        let log_messages_clone = Arc::clone(&log_messages);

        let handle = thread::spawn(move || {
            generate_and_insert_records(records_clone, log_messages_clone)
        });

        handles.push(handle);
    }

    for handle in handles {
        handle.join().unwrap();
    }

    let logs = {
        let mut logs = log_messages.lock().unwrap();
        logs.drain(..).collect::<Vec<_>>()
    };

    let duration = start_time.elapsed();

    if records.lock().unwrap().len() < HASH_TABLE_SIZE {
        (true, logs)
    } else {
        (false, vec![format!("Hash table became full after {} threads.", num_threads)].into_iter().chain(logs.into_iter()).collect())
    }
}

fn generate_and_insert_records(records: Arc<Mutex<HashMap<u32, (i64, f32, Record)>>>, log_messages: Arc<Mutex<Vec<String>>>) {
    let secret_seed = 42;
    let mut offset = 0;
    let mut rng = rand::thread_rng();
    let float_dist = Uniform::new(FLOAT_RANGE_START, FLOAT_RANGE_END);

    while offset < MAX_OFFSET {
        let key = generate_key(offset as usize, secret_seed);
        if records.lock().unwrap().contains_key(&key) {
            log_messages.lock().unwrap().push(format!("Collision detected for key: {}", key));
            continue;
        }

        let value = float_dist.sample(&mut rng);
        let record = Record { int_value: 42 }; // Example logic to set an integer within a range
        records.lock().unwrap().insert(key, (offset, value, record));

        offset += 1;
    }
}

fn generate_key(index: usize, seed: u32) -> u32 {
    use std::hash::{Hasher, SipHasher};
    let mut hasher = SipHasher::new_with_keys(seed as u64, seed as u64);
    hasher.write_usize(index);
    hasher.write_usize(std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_millis() as usize);
    hasher.finish()
}

fn get_resident_set_size() -> u64 {
    // This function would typically use platform-specific APIs to measure memory usage.
    0
}
```

### Key Components:
- **Concurrency**: Utilizes `Arc` and `Mutex` for thread-safe shared access to the records hashmap.
- **Unique Key Generation**: Combines index, system time, and a secret seed using `SipHasher`.
- **Random Value Generation**: Uses `rand` crate with uniform distribution within specified range.
- **Logging**: Captures messages about key collisions or other issues.
- **Performance Measurement**: Measures execution time using `std::time`.

This code provides a robust foundation for managing records in a distributed system while ensuring thread safety and efficient resource utilization.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 16
#define LOAD_FACTOR 0.75

typedef struct {
    int userId;
    time_t sessionStart;
    time_t sessionEnd;
    double sessionDuration;
    int activityScore;
} UserSessionData;

typedef struct HashNode {
    UserSessionData data;
    struct HashNode* next;
} HashNode;

typedef struct {
    HashNode** table;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} HashTable;

unsigned long hashFunction(int userId, size_t capacity) {
    return (unsigned long)userId % capacity;
}

HashTable* createHashTable() {
    HashTable* hashtable = malloc(sizeof(HashTable));
    if (!hashtable) return NULL;

    hashtable->capacity = INITIAL_CAPACITY;
    hashtable->size = 0;
    hashtable->table = calloc(hashtable->capacity, sizeof(HashNode*));
    if (!hashtable->table) {
        free(hashtable);
        return NULL;
    }

    pthread_mutex_init(&hashtable->mutex, NULL);
    return hashtable;
}

void resizeHashTable(HashTable* hashtable);

int insertSessionData(HashTable* hashtable, UserSessionData data) {
    pthread_mutex_lock(&hashtable->mutex);

    if ((double)hashtable->size / hashtable->capacity >= LOAD_FACTOR) {
        resizeHashTable(hashtable);
    }

    unsigned long index = hashFunction(data.userId, hashtable->capacity);
    HashNode* newNode = malloc(sizeof(HashNode));
    if (!newNode) {
        pthread_mutex_unlock(&hashtable->mutex);
        return -1;
    }

    *newNode = (HashNode){ .data = data, .next = NULL };

    HashNode* current = hashtable->table[index];
    while (current && current->data.userId != data.userId) {
        if (!current->next) break;
        current = current->next;
    }

    if (current && current->data.userId == data.userId) { // Update existing
        free(newNode);
    } else {
        newNode->next = hashtable->table[index];
        hashtable->table[index] = newNode;
        hashtable->size++;
    }

    pthread_mutex_unlock(&hashtable->mutex);
    return 0;
}

UserSessionData* getSessionData(HashTable* hashtable, int userId) {
    pthread_mutex_lock(&hashtable->mutex);

    unsigned long index = hashFunction(userId, hashtable->capacity);
    HashNode* current = hashtable->table[index];

    while (current && current->data.userId != userId) {
        current = current->next;
    }

    UserSessionData* result = NULL;
    if (current) {
        result = &current->data;
    }

    pthread_mutex_unlock(&hashtable->mutex);
    return result;
}

void deleteSessionData(HashTable* hashtable, int userId) {
    pthread_mutex_lock(&hashtable->mutex);

    unsigned long index = hashFunction(userId, hashtable->capacity);
    HashNode *current = hashtable->table[index], *prev = NULL;

    while (current && current->data.userId != userId) {
        prev = current;
        current = current->next;
    }

    if (current) {
        if (prev) {
            prev->next = current->next;
        } else {
            hashtable->table[index] = current->next;
        }
        free(current);
        hashtable->size--;
    }

    pthread_mutex_unlock(&hashtable->mutex);
}

void resizeHashTable(HashTable* hashtable) {
    size_t newCapacity = hashtable->capacity * 2;
    HashNode** newTable = calloc(newCapacity, sizeof(HashNode*));
    if (!newTable) return;

    for (size_t i = 0; i < hashtable->capacity; ++i) {
        HashNode* current = hashtable->table[i];
        while (current) {
            unsigned long newIndex = hashFunction(current->data.userId, newCapacity);
            HashNode* next = current->next;

            current->next = newTable[newIndex];
            newTable[newIndex] = current;

            current = next;
        }
    }

    free(hashtable->table);
    hashtable->table = newTable;
    hashtable->capacity = newCapacity;
}

void freeHashTable(HashTable* hashtable) {
    for (size_t i = 0; i < hashtable->capacity; ++i) {
        HashNode* current = hashtable->table[i];
        while (current) {
            HashNode* next = current->next;
            free(current);
            current = next;
        }
    }

    free(hashtable->table);
    pthread_mutex_destroy(&hashtable->mutex);
    free(hashtable);
}

void generateSessionDuration(double min, double max, unsigned int seed) {
    srand(seed);
    return (double)(min + ((max - min) * rand()) / RAND_MAX);
}

char* renderHTMLScripts(char** scripts, size_t scriptCount) {
    char* result = malloc(1024); // Initial allocation
    if (!result) return NULL;

    size_t pos = 0;
    for (size_t i = 0; i < scriptCount; ++i) {
        const char *scriptCode = scripts[i];
        size_t len = strlen(scriptCode);

        if (pos + len + 100 > sizeof(result)) { // Resize logic
            char* newResult = realloc(result, pos + len + 200); // Add extra space for safety
            if (!newResult) {
                free(result);
                return NULL;
            }
            result = newResult;
        }

        sprintf(result + pos, "<script key=\"%zu\">%s</script>", i, scriptCode);
        pos += strlen(result + pos) + 1; // Move to end of string
    }

    if (pos > sizeof(result)) { // Final resize in case last allocation was small
        result = realloc(result, pos + 1); 
    }

    return result;
}

int main() {
    HashTable* hashtable = createHashTable();
    if (!hashtable) return -1;

    srand(time(NULL)); // Initialize random seed

    for (int i = 0; i < 100; ++i) { // Example usage
        UserSessionData data;
        data.userId = i + 1;
        data.sessionStart = time(NULL);
        data.sessionEnd = data.sessionStart + 3600; // Mock end time, 1 hour later
        data.sessionDuration = generateSessionDuration(10.0, 100.0, rand());
        data.activityScore = rand() % 100;

        insertSessionData(hashtable, data);
    }

    UserSessionData* retrievedData = getSessionData(hashtable, 5);
    if (retrievedData) {
        printf("User ID: %d\n", retrievedData->userId);
    }

    char* scripts[] = {"console.log('Script 1');", "alert('Script 2');"};
    char* htmlScripts = renderHTMLScripts(scripts, 2);
    if (htmlScripts) {
        printf("%s\n", htmlScripts);
        free(htmlScripts);
    }

    // Cleanup
    freeHashTable(hashtable);

    return 0;
}
```']

