#define MAX_SIZE 1500

typedef struct {
    // Define the structure according to your requirements
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T data[MAX_SIZE];
    size_t head;
    size_t tail;
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    bool full;
} CircularBuffer;

// Initialize the circular buffer
void initCircularBuffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
    cb->full = false;
    pthread_mutex_init(&cb->mutex, NULL);
    pthread_cond_init(&cb->cond, NULL);
}

// Check if the buffer is full
bool isBufferFull(CircularBuffer *cb) {
    return cb->full || (cb->count == MAX_SIZE);
}

// Check if the buffer is empty
bool isBufferEmpty(CircularBuffer *cb) {
    return (!cb->full && (cb->head == cb->tail));
}

// Add a new structure to the buffer
void addStructure(CircularBuffer *cb, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&cb->mutex);

    while (isBufferFull(cb)) {
        // Implement backpressure mechanism here if necessary
        pthread_cond_wait(&cb->cond, &cb->mutex);
    }

    cb->data[cb->head] = pdu;
    cb->head = (cb->head + 1) % MAX_SIZE;

    if (cb->count == MAX_SIZE - 1) {
        cb->full = true;
    }
    cb->count++;

    pthread_cond_signal(&cb->cond);
    pthread_mutex_unlock(&cb->mutex);

    // Log the addition attempt
    printf("Added structure with RNTI: %d\n", pdu.RNTI);
}

// Remove a structure from the buffer
bool removeStructure(CircularBuffer *cb, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&cb->mutex);

    while (isBufferEmpty(cb)) {
        // Implement timeout mechanism if necessary
        pthread_cond_wait(&cb->cond, &cb->mutex);
    }

    *pdu = cb->data[cb->tail];
    cb->tail = (cb->tail + 1) % MAX_SIZE;
    cb->count--;

    if (cb->count == MAX_SIZE - 1) {
        cb->full = false;
    }

    pthread_cond_signal(&cb->cond);
    pthread_mutex_unlock(&cb->mutex);

    // Trigger callback for event processing
    printf("Removed structure with RNTI: %d\n", pdu->RNTI);

    return true;
}

// Get the current state of the buffer
void getBufferState(CircularBuffer *cb, size_t *activeCount) {
    pthread_mutex_lock(&cb->mutex);
    *activeCount = cb->count;
    pthread_mutex_unlock(&cb->mutex);
}

// Function to generate a structure with random CRCFLAG
NFAPI_CRC_INDICATION_PDU_T createRandomPdu() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rand(); // Replace with valid tag generation
    pdu.RNTI = rand(); // Replace with valid RNTI generation
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 256; // Random CRC flag
    return pdu;
}

// Periodic monitoring and adjustment function
void monitorAndAdjust(CircularBuffer *cb) {
    while (true) {
        pthread_mutex_lock(&cb->mutex);

        // Adjust MAX_SIZE based on system load and resource usage
        // Placeholder logic for adjusting size
        if (cb->count > 0.8 * MAX_SIZE) {
            printf("High load, consider increasing resources\n");
        } else if (cb->count < 0.2 * MAX_SIZE) {
            printf("Low load, consider decreasing resources\n");
        }

        pthread_mutex_unlock(&cb->mutex);
        sleep(5); // Monitor every 5 seconds
    }
}

// Main function to manage the buffer
void* manageBuffer(void *arg) {
    CircularBuffer cb;
    initCircularBuffer(&cb);

    pthread_t monitorThread;
    pthread_create(&monitorThread, NULL, (void*)monitorAndAdjust, &cb);

    while (true) {
        NFAPI_CRC_INDICATION_PDU_T pdu = createRandomPdu();
        addStructure(&cb, pdu);
        sleep(1); // Simulate time between structure generations
    }

    pthread_join(monitorThread, NULL);
}

int main() {
    srand(time(NULL));
    pthread_t bufferManager;
    pthread_create(&bufferManager, NULL, manageBuffer, NULL);
    pthread_join(bufferManager, NULL);

    return 0;
}
```

### Key Features:
