#include <iostream>
#include <vector>
#include <random>
#include <ctime>
#include <boost/graph/adjacency_list.hpp>
#include <stdexcept>

struct Record {
    int timestamp;
    bool statusFlag;
};

class GraphDatabase {
public:
    static const size_t InitialCapacity = 100;
    static const double ResizeFactor = 1.5;

    GraphDatabase(int startTime, int interval) 
        : currentTime(startTime), interval(interval),
          records(InitialCapacity), offsets(InitialCapacity, 0L),
          keys(InitialCapacity, 0) {
        resizeRecordsIfNeeded();
    }

    void populateRecords(size_t numRecords) {
        try {
            for (size_t i = 0; i < numRecords; ++i) {
                if (records.size() <= i) {
                    resizeRecordsIfNeeded();
                }
                records[i].timestamp = currentTime + interval * i;
                records[i].statusFlag = false;

                keys[i] = generateRandomKey(1, 100);
            }
        } catch (const std::exception &e) {
            std::cerr << "Error populating records: " << e.what() << std::endl;
        }
    }

    void addVertex(int vertexId) {
        boostGraph.add_vertex(vertexId);
    }

    void addEdge(int from, int to) {
        boostGraph.add_edge(from, to, boost::no_property());
    }

private:
    int currentTime;
    int interval;

    std::vector<Record> records;
    std::vector<long> offsets;
    std::vector<int> keys;

    typedef boost::adjacency_list<boost::vecS, boost::vecS, boost::undirectedS> Graph;
    Graph boostGraph;

    void resizeRecordsIfNeeded() {
        size_t newSize = static_cast<size_t>(records.capacity() * ResizeFactor);
        records.resize(newSize, {0, false});
        offsets.resize(newSize, 0L);
        keys.resize(newSize, 0);
    }

    int generateRandomKey(int min, int max) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(min, max);
        return dis(gen);
    }
};

