#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_TABLE_SIZE 16
#define HASH_MULTIPLIER 31

typedef struct Record {
    int key;
    long offset;
    struct Record* prev;
    struct Record* next;
} Record;

typedef struct Node {
    Record* record;
    struct Node* next;
} Node;

typedef struct HashTable {
    Node** buckets;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

// Function prototypes
HashTable* init_hash_table(size_t size);
void free_hash_table(HashTable* table);
unsigned long hash_function(int key, size_t size);
Node* create_node(Record* record);
void insert_record(HashTable* table, Record* record);
Record* find_record_by_key(HashTable* table, int key);
void delete_all_records(HashTable* table);

// Initialize a hash table
HashTable* init_hash_table(size_t size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->size = size;
    table->buckets = (Node**)calloc(size, sizeof(Node*));
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

// Free a hash table
void free_hash_table(HashTable* table) {
    if (!table) return;

    delete_all_records(table);
    for (size_t i = 0; i < table->size; ++i) {
        Node* node = table->buckets[i];
        while (node) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

// Hash function
unsigned long hash_function(int key, size_t size) {
    return (key * HASH_MULTIPLIER) % size;
}

// Create a new node
Node* create_node(Record* record) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    node->record = record;
    node->next = NULL;
    return node;
}

// Insert a record into the hash table
void insert_record(HashTable* table, Record* record) {
    unsigned long index = hash_function(record->key, table->size);
    Node* new_node = create_node(record);

    pthread_mutex_lock(&table->lock);
    if (!new_node) {
        printf("Memory allocation failed for node\n");
        return;
    }

    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;
    pthread_mutex_unlock(&table->lock);
}

// Find a record by key
Record* find_record_by_key(HashTable* table, int key) {
    unsigned long index = hash_function(key, table->size);

    pthread_mutex_lock(&table->lock);
    Node* node = table->buckets[index];
    while (node) {
        if (node->record->key == key) {
            pthread_mutex_unlock(&table->lock);
            return node->record;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&table->lock);

    return NULL;
}

// Delete all records in the hash table
void delete_all_records(HashTable* table) {
    for (size_t i = 0; i < table->size; ++i) {
        Node* node = table->buckets[i];
        while (node) {
            Node* temp = node;
            node = node->next;
            free(temp->record);
            free(temp);
        }
    }
}

// Initialize a record with random key
Record* init_record(int min_key, int max_key, long offset) {
    if (offset < 0) return NULL;

    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) return NULL;

    srand(time(NULL));
    record->key = rand() % (max_key - min_key + 1) + min_key;
    record->offset = offset;
    record->prev = record->next = NULL;

