#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define ERROR_MEMORY_ALLOCATION -1
#define LOG_LEVEL_NONE 0
#define LOG_LEVEL_BASIC 1
#define LOG_LEVEL_DETAILED 2

typedef struct {
    int offset;
    int key;
} Record;

void logMessage(int level, const char* format, ...) {
    if (level > LOG_LEVEL_DETAILED) return;
    va_list args;
    va_start(args, format);
    time_t now = time(NULL);
    printf("[%s] ", ctime(&now));
    vprintf(format, args);
    printf("\n");
    va_end(args);
}

typedef struct {
    pthread_mutex_t lock;
    int logLevel;
} Logger;

Logger logger = {PTHREAD_MUTEX_INITIALIZER, LOG_LEVEL_DETAILED};

void* processRecord(void* arg) {
    Record* record = (Record*)arg;
    // Simulated transformation
    record->offset *= 2; 
    return NULL;
}

int batchProcessRecordsWithDynamicResourceManagement(size_t numRecords, int enableParallelProcessing, unsigned long seed, Logger* loggerConfig) {
    pthread_mutex_lock(&loggerConfig->lock);
    logger.logLevel = loggerConfig->logLevel;
    pthread_mutex_unlock(&loggerConfig->lock);

    logMessage(logger.logLevel, "Initializing random number generator with seed %lu", seed);
    srand(seed);

    long* offsets = (long*)malloc(numRecords * sizeof(long));
    int* keys = (int*)malloc(numRecords * sizeof(int));

    if (!offsets || !keys) {
        logMessage(LOG_LEVEL_DETAILED, "Memory allocation failed");
        free(offsets); // Ensure to free the other array even if one fails
        free(keys);
        return ERROR_MEMORY_ALLOCATION;
    }

    logMessage(logger.logLevel, "Allocated memory for %zu records", numRecords);

    pthread_t* threads = NULL;
    if (enableParallelProcessing) {
        threads = malloc(numRecords * sizeof(pthread_t));
        if (!threads) {
            logMessage(LOG_LEVEL_DETAILED, "Memory allocation failed for threads");
            free(offsets);
            free(keys);
            return ERROR_MEMORY_ALLOCATION;
        }
    }

    Record* records = malloc(numRecords * sizeof(Record));
    if (!records) {
        logMessage(LOG_LEVEL_DETAILED, "Memory allocation failed for records");
        free(offsets);
        free(keys);
        if (enableParallelProcessing) free(threads);
        return ERROR_MEMORY_ALLOCATION;
    }

    logMessage(logger.logLevel, "Starting record processing");

    for (size_t i = 0; i < numRecords; ++i) {
        offsets[i] = rand() % 10000;
        keys[i] = rand() % 100;
        records[i].offset = offsets[i];
        records[i].key = keys[i];

        if (enableParallelProcessing) {
            pthread_create(&threads[i], NULL, processRecord, &records[i]);
        } else {
            processRecord(&records[i]);
        }
    }

    if (enableParallelProcessing) {
        for (size_t i = 0; i < numRecords; ++i) {
            pthread_join(threads[i], NULL);
        }
        free(threads);
    }

    // Sort records based on key
    qsort(records, numRecords, sizeof(Record), [](const void* a, const void* b) -> int {
        Record* recA = (Record*)a;
        Record* recB = (Record*)b;
        return recA->key - recB->key;
    });

    logMessage(logger.logLevel, "Completed record processing and sorting");

    // Copy sorted records back to original arrays
    for (size_t i = 0; i < numRecords; ++i) {
        offsets[i] = records[i].offset;
        keys[i] = records[i].key;
    }

    free(records);
    logMessage(logger.logLevel, "Memory deallocation completed");

    return 0;
}

int main() {
    Logger loggerConfig = {PTHREAD_MUTEX_INITIALIZER, LOG_LEVEL_DETAILED};
    batchProcessRecordsWithDynamicResourceManagement(1000000, 1, 42, &loggerConfig);
    return 0;
}
```

### Explanation
- **Random Initialization**: Uses `srand` with a provided seed for reproducibility.
- **Memory Management**: Handles allocation and deallocation of resources, logging failure cases.
- **Thread Safety**: Mutex used to protect logger configuration changes.
- **Parallel Processing**: Optional threading based on user's choice.
- **Logging**: Detailed logs are generated, including timestamps. The log level is configurable.
- **Sorting**: Uses `qsort` for sorting records by their keys.']

