    pthread_mutex_unlock(&mutex);

    return NULL;
}

unsigned char* compute_md5(const char *data, size_t len) {
    if (!md5_hashing_enabled)
        return NULL;

    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5((const unsigned char*)data, len, hash);

    static unsigned char hex_output[33]; // 32 characters + null terminator
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(hex_output + i * 2, "%02x", hash[i]);
    }
    return hex_output;
}

