int add_sensor_event(SensorList *list, SENSOR_EVENT_TAG tag, time_t timestamp, SENSOR_DATA *data_points, size_t data_count) {
    if (!list || !data_points) return -1;

    pthread_mutex_lock(&list->lock);

    SensorEvent *new_event = malloc(sizeof(SensorEvent));
    if (!new_event) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation error
    }

    new_event->tag = tag;
    new_event->timestamp = timestamp;

    // Use a memory pool or bulk allocation strategy to minimize fragmentation
    new_event->data_points = malloc(sizeof(SENSOR_DATA) * data_count);
    if (!new_event->data_points) {
        free(new_event);
        pthread_mutex_unlock(&list->lock);
        return -3; // Memory allocation error
    }

    for (size_t i = 0; i < data_count; ++i) {
        new_event->data_points[i] = data_points[i];
    }
    new_event->data_count = data_count;
    new_event->next = list->head;
    list->head = new_event;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void free_sensor_list(SensorList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    SensorEvent *current = list->head;
    while (current) {
        SensorEvent *next = current->next;
        free(current->data_points);
        free(current);
        current = next;
    }
    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

