```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000
#define VALUE_RANGE_MIN 1
#define VALUE_RANGE_MAX 100

typedef struct {
    long offset;
    int key;
    int value;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordPool;

RecordPool* create_record_pool(size_t initial_capacity) {
    RecordPool *pool = (RecordPool*)malloc(sizeof(RecordPool));
    if (!pool) return NULL;

    pool->records = (Record*)malloc(initial_capacity * sizeof(Record));
    if (!pool->records) {
        free(pool);
        return NULL;
    }

    pool->capacity = initial_capacity;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

int is_key_unique(RecordPool *pool, int key) {
    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->records[i].key == key) {
            return 0;
        }
    }
    return 1;
}

int generate_random_value(int min, int max) {
    return rand() % (max - min + 1) + min;
}

int add_record(RecordPool *pool, long offset, int key) {
    pthread_mutex_lock(&pool->lock);

    if (pool->count >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        Record *new_records = (Record*)realloc(pool->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&pool->lock);
            return -1; // Memory allocation failed
        }
        pool->records = new_records;
        pool->capacity = new_capacity;
    }

    if (!is_key_unique(pool, key)) {
        pthread_mutex_unlock(&pool->lock);
        return -2; // Key already exists
    }

    int value = generate_random_value(VALUE_RANGE_MIN, VALUE_RANGE_MAX);

    pool->records[pool->count].offset = offset;
    pool->records[pool->count].key = key;
    pool->records[pool->count].value = value;
    pool->count++;

    pthread_mutex_unlock(&pool->lock);
    return 0; // Success
}

void free_record_pool(RecordPool *pool) {
    if (pool) {
        if (pool->records) {
            free(pool->records);
        }
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

int main() {
    srand(time(NULL));

    RecordPool *pool = create_record_pool(10);
    if (!pool) {
        fprintf(stderr, "Failed to create record pool\n");
        return 1;
    }

    for (int i = 0; i < MAX_RECORDS; ++i) {
        int key = rand() % 10000 + 1;
        int result = add_record(pool, (long)i, key);
        if (result != 0) {
            fprintf(stderr, "Failed to add record with key %d: Error code %d\n", key, result);
        }
    }

    free_record_pool(pool);
    return 0;
}
```

