    Activity *activities;
} Session;

typedef struct HashTableEntry {
    int key;
    Session *session;
    struct HashTableEntry *next;
} HashTableEntry;

typedef struct HashTable {
    size_t bucket_count;
    HashTableEntry **buckets;
    pthread_mutex_t *locks;
} HashTable;

HashTable* create_hash_table(size_t initial_bucket_count);
void destroy_hash_table(HashTable *table);
unsigned long hash_function(int key, size_t bucket_count);
void resize_hash_table_if_needed(HashTable *table);
Session* find_session(HashTable *table, int user_id);
int add_or_update_session(HashTable *table, Session *session);
