// Function implementations
HashTable* create_hash_table(size_t initial_bucket_count) {
    HashTable *table = malloc(sizeof(HashTable));
    table->bucket_count = initial_bucket_count;
    table->buckets = calloc(initial_bucket_count, sizeof(HashTableEntry*));
    table->locks = calloc(initial_bucket_count, sizeof(pthread_mutex_t));

    for (size_t i = 0; i < initial_bucket_count; ++i) {
        pthread_mutex_init(&table->locks[i], NULL);
    }

    return table;
}

void destroy_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->bucket_count; ++i) {
        HashTableEntry *entry = table->buckets[i];
        while (entry) {
            HashTableEntry *temp = entry;
            entry = entry->next;
            free(temp->session->activities);
            free(temp->session);
            free(temp);
        }
    }

    for (size_t i = 0; i < table->bucket_count; ++i) {
        pthread_mutex_destroy(&table->locks[i]);
    }

    free(table->buckets);
    free(table->locks);
    free(table);
}

unsigned long hash_function(int key, size_t bucket_count) {
    return ((unsigned long)key * 2654435761u) % bucket_count;
}

void resize_hash_table_if_needed(HashTable *table) {
    // Placeholder for dynamic resizing logic
}

Session* find_session(HashTable *table, int user_id) {
    unsigned long index = hash_function(user_id, table->bucket_count);
    pthread_mutex_lock(&table->locks[index]);

    HashTableEntry *entry = table->buckets[index];
    while (entry) {
        if (entry->key == user_id) {
            Session *session = entry->session;
            pthread_mutex_unlock(&table->locks[index]);
            return session;
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&table->locks[index]);
    return NULL;
}

int add_or_update_session(HashTable *table, Session *session) {
    unsigned long index = hash_function(session->user_id, table->bucket_count);
    pthread_mutex_lock(&table->locks[index]);

    HashTableEntry **entry_ptr = &table->buckets[index];
    while (*entry_ptr) {
        if ((*entry_ptr)->key == session->user_id) {
            // Update existing session
            free((*entry_ptr)->session->activities);
            (*entry_ptr)->session->activities = malloc(session->activity_count * sizeof(Activity));
            memcpy((*entry_ptr)->session->activities, session->activities, session->activity_count * sizeof(Activity));
            pthread_mutex_unlock(&table->locks[index]);
            return 1;
        }
        entry_ptr = &(*entry_ptr)->next;
    }

    // Add new session
    HashTableEntry *new_entry = malloc(sizeof(HashTableEntry));
    new_entry->key = session->user_id;
    new_entry->session = malloc(sizeof(Session));
    memcpy(new_entry->session, session, sizeof(Session));

    new_entry->next = table->buckets[index];
    table->buckets[index] = new_entry;

    pthread_mutex_unlock(&table->locks[index]);
    return 0;
}

char* append_slash_if_within_limit(const char *input, size_t limit) {
    if (strlen(input) >= limit) {
        return NULL;
    }

    char *result = malloc(limit + 2);
    if (!result) return NULL;

    strcpy(result, input);
    strcat(result, "/");

    return result;
}

// Main function for demonstration
int main() {
