    // Example usage
    Session session1 = { .user_id = 1, .timestamp = time(NULL), .activity_count = 2 };
    Activity activities[] = { {"Logged in"}, {"Viewed dashboard"} };
    session1.activities = activities;

    add_or_update_session(table, &session1);

    char *modified_string = append_slash_if_within_limit("example", 10);
    if (modified_string) {
        printf("%s\n", modified_string);
        free(modified_string);
    } else {
        printf("Input exceeds limit.\n");
    }

    destroy_hash_table(table);

    return 0;
}
