typedef enum { SUCCESS, ERROR_SIZE_MISMATCH, ERROR_MEMORY_ALLOCATION, ERROR_DUPLICATE_KEY } Status;

void set_seed(int seed) {
    srand(seed);
}

int random_delay(int min, int max) {
    return min + rand() % (max - min + 1);
}

Status manage_memory(long *offset_array, long offset_size, 
                     int *key_array, int key_size, 
                     record **record_array, int record_count, 
                     int *offsets, int offset_count, 
                     int keys[], int key_count) {

    if (offset_count != offset_size) {
        return ERROR_SIZE_MISMATCH;
    }

    // Allocate memory for offset array
    long *allocated_offsets = (long *)malloc(offset_size * sizeof(long));
    if (!allocated_offsets) return ERROR_MEMORY_ALLOCATION;

    memcpy(allocated_offsets, offsets, offset_size * sizeof(long));

    // Validate and insert unique keys with retry mechanism
    int key_index = 0;
    for (int i = 0; i < key_count; ++i) {
        int retries = 0;
        while (retries < MAX_RETRIES) {
            if (key_array == NULL || 
                (key_index > 0 && !bsearch(&keys[i], key_array, key_index, sizeof(int), compare_ints))) {

                // Shift existing keys to make space for the new one
                memmove(key_array + key_index + 1, key_array + key_index, (key_size - key_index - 1) * sizeof(int));

                key_array[key_index] = keys[i];
                ++key_index;
                break;
            } else {
                int delay_ms = random_delay(MIN_DELAY_MS, MAX_DELAY_MS);
                usleep(delay_ms * 1000); // Convert ms to us
                retries++;
            }
        }
        if (retries == MAX_RETRIES) {
            free(allocated_offsets);
            return ERROR_DUPLICATE_KEY;
        }
    }

    // Allocate memory for records
    record *allocated_records = (record *)malloc(record_count * sizeof(record));
    if (!allocated_records) {
        free(allocated_offsets);
        return ERROR_MEMORY_ALLOCATION;
    }

    set_seed(time(NULL)); // Ensure consistent random values across runs

    for (int i = 0; i < record_count; ++i) {
        allocated_records[i].value = rand() % 1000; // Example range
        allocated_records[i].offset_ptr = &allocated_offsets[i];
    }

    *record_array = allocated_records;
    *offset_array = allocated_offsets;

    return SUCCESS;
}

int compare_ints(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}
