#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

// External library functions for random number generation
void init_random(int seed);
int get_random(int min, int max);

typedef struct {
    int value;
} record;

typedef enum { SUCCESS = 0, ERROR = 1 } status_t;

status_t manage_memory_allocation(size_t array_size, long min_value, long max_value) {
    // Variables for memory management
    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;

    // Thread safety lock
    pthread_mutex_t records_lock = PTHREAD_MUTEX_INITIALIZER;

    if (array_size == 0) {
        fprintf(stderr, "Error: array_size must be greater than zero.\n");
        return ERROR;
    }

    // Allocate and initialize memory for offsets and keys arrays
    offsets = (long *)malloc(array_size * sizeof(long));
    keys = (int *)malloc(array_size * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Error: Memory allocation failed for offsets or keys.\n");
        free(offsets);
        free(keys);
        return ERROR;
    }

    // Initialize random number generator
    init_random(42);  // Example seed value

    // Allocate and initialize memory for records array
    records = (record *)malloc(array_size * sizeof(record));
    if (!records) {
        fprintf(stderr, "Error: Memory allocation failed for records.\n");
        free(offsets);
        free(keys);
        return ERROR;
    }

    bool unique_values[array_size];
    for (size_t i = 0; i < array_size; ++i) {
        unique_values[i] = false;
    }

    int num_unique = 0;
    while (num_unique < array_size) {
        int random_value = get_random(min_value, max_value);

        // Check if the value is already in use
        bool found = false;
        for (size_t i = 0; i < array_size; ++i) {
            if (records[i].value == random_value) {
                found = true;
                break;
            }
        }

        if (!found) {
            pthread_mutex_lock(&records_lock);
            records[num_unique].value = random_value;
            unique_values[num_unique] = true;
            num_unique++;
            pthread_mutex_unlock(&records_lock);
        }
    }

    // Log successful allocations
    printf("Successfully allocated memory for offsets, keys, and records.\n");

    // Function to deallocate all resources
    auto cleanup = [&]() {
        free(offsets);
        free(keys);
        free(records);
    };

    // Return SUCCESS or ERROR based on execution
    if (num_unique == array_size) {
        return SUCCESS;
    } else {
        cleanup();
        fprintf(stderr, "Error: Failed to initialize all records with unique values.\n");
        return ERROR;
    }
}

// Example usage in unit tests or main function

int main() {
    size_t array_size = 1000; // Example size
    long min_value = 1;
    long max_value = 2000;

    status_t result = manage_memory_allocation(array_size, min_value, max_value);

    if (result == SUCCESS) {
        printf("Memory allocation and initialization succeeded.\n");
    } else {
        fprintf(stderr, "An error occurred during memory management.\n");
    }

    return result;
}
