#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
    long *offsetPtr;
} Record;

#define MAX_RETRIES 5

// Hash table structure for key to record mapping
typedef struct HashTableEntry {
    int key;
    Record *record;
    struct HashTableEntry *next;
} HashTableEntry;

typedef struct {
    size_t capacity;
    size_t size;
    HashTableEntry **buckets;
} HashTable;

// Function declarations
long* allocate_long_array(size_t expected_size, const long* user_data, size_t user_data_size);
int* insert_unique_keys(int* key_array, size_t array_size, int new_key);
Record* initialize_records_with_random_values(size_t record_count, long* offset_array);
HashTable* create_hash_table(size_t capacity);
void hash_table_insert(HashTable* table, int key, Record *record);
Record* hash_table_lookup(HashTable* table, int key);

// Hash function
unsigned int hash_function(int key, size_t capacity) {
    return (unsigned int)(key % capacity);
}

// Memory allocator for long array
long* allocate_long_array(size_t expected_size, const long* user_data, size_t user_data_size) {
    long *array = malloc(expected_size * sizeof(long));
    if (!array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    size_t copy_size = (user_data_size < expected_size) ? user_data_size : expected_size;
    memcpy(array, user_data, copy_size * sizeof(long));

    return array;
}

// Function to insert unique keys
int* insert_unique_keys(int* key_array, size_t array_size, int new_key) {
    for (size_t i = 0; i < array_size; ++i) {
        if (key_array[i] == new_key) {
            int retries = 0;
            while (retries < MAX_RETRIES) {
                srand(time(NULL) + retries);
                usleep(rand() % 100000); // Random delay
                for (size_t j = 0; j < array_size; ++j) {
                    if (key_array[j] == new_key)
                        break;
                    if (j == array_size - 1) { 
                        return key_array;
                    }
                }
                retries++;
            }
            fprintf(stderr, "Max retries reached for inserting key %d\n", new_key);
            exit(EXIT_FAILURE);
        }
    }

    int *new_key_array = realloc(key_array, (array_size + 1) * sizeof(int));
    if (!new_key_array) {
        perror("Failed to reallocate memory");
        free(key_array);
        exit(EXIT_FAILURE);
    }
    key_array = new_key_array;
    key_array[array_size] = new_key;

    return key_array;
}

// Function to initialize records
Record* initialize_records_with_random_values(size_t record_count, long* offset_array) {
    Record *records = malloc(record_count * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL)); // Seed the random number generator
    for (size_t i = 0; i < record_count; ++i) {
        records[i].value = rand() % 100; // Random value between 0 and 99
        records[i].offsetPtr = &offset_array[i];
    }

    return records;
}

// Hash table creation function
HashTable* create_hash_table(size_t capacity) {
    HashTable *table = malloc(sizeof(HashTable));
    if (!table) {
        perror("Failed to allocate memory for hash table");
        exit(EXIT_FAILURE);
    }
    table->capacity = capacity;
    table->size = 0;
    table->buckets = calloc(capacity, sizeof(HashTableEntry*));
    if (!table->buckets) {
        perror("Failed to allocate memory for hash buckets");
        free(table);
        exit(EXIT_FAILURE);
    }

    return table;
}

// Hash table insertion function
void hash_table_insert(HashTable* table, int key, Record *record) {
    unsigned int index = hash_function(key, table->capacity);
    HashTableEntry *entry = malloc(sizeof(HashTableEntry));
    if (!entry) {
        perror("Failed to allocate memory for hash table entry");
        exit(EXIT_FAILURE);
    }
    entry->key = key;
    entry->record = record;
    entry->next = table->buckets[index];
    table->buckets[index] = entry;
    table->size++;
}

// Hash table lookup function
Record* hash_table_lookup(HashTable* table, int key) {
    unsigned int index = hash_function(key, table->capacity);
    for (HashTableEntry *entry = table->buckets[index]; entry != NULL; entry = entry->next) {
        if (entry->key == key)
            return entry->record;
    }
    return NULL;
}

// Function to manage memory and operations
void* manage_memory_and_operations(const long* user_data, size_t user_data_size,
                                   int* keys, size_t key_count, size_t record_count) {

    // Step 1: Allocate and initialize the array of longs with user data
    size_t expected_long_array_size = user_data_size;
    long *offset_values = allocate_long_array(expected_long_array_size, user_data, user_data_size);

    // Step 2: Insert unique keys into the key array
    int* key_array = malloc(key_count * sizeof(int));
    if (!key_array) {
        perror("Failed to allocate memory for key array");
        free(offset_values);
        exit(EXIT_FAILURE);
    }
    memcpy(key_array, keys, key_count * sizeof(int));

    for (size_t i = 0; i < key_count; ++i) {
        key_array = insert_unique_keys(key_array, key_count + i, keys[i]);
    }

    // Step 3: Initialize records with random values and pointers to offset
    Record* records = initialize_records_with_random_values(record_count, offset_values);

    // Step 4: Create and populate the hash table for fast lookups
    HashTable* hash_table = create_hash_table(key_count);
    for (size_t i = 0; i < record_count; ++i) {
        hash_table_insert(hash_table, key_array[i], &records[i]);
    }

    // Return all data structures along with their sizes
    void *results[4] = {offset_values, key_array, records, hash_table};
    size_t results_sizes[4] = {expected_long_array_size, key_count, record_count, 0}; // Hash table capacity is not needed for return

    return results;
}

// Example usage
int main() {
    long user_data[] = {10L, 20L, 30L};
    int keys[] = {1, 2, 3};

    void *results[4];
    size_t results_sizes[4];

    manage_memory_and_operations(user_data, sizeof(user_data) / sizeof(long),
                                 keys, sizeof(keys) / sizeof(int), 3);

    return 0;
}
