```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RETRIES 5
#define DELAY_MIN_MS 100
#define DELAY_MAX_MS 500

typedef struct {
    time_t timestamp;
    void *dataPointer;
} Frame;

typedef struct {
    char *fileType;
    char *filePath;
    int duration; // in seconds
    Frame **metadata;
} MediaInfo;

// Simulated external library functions
int retrieveFileMetadata(const char *filePath, MediaInfo *mediaInfo);
void logError(const char *message);

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int globalMemoryLeakCounter = 0;

int isUniqueMediaType(MediaInfo *infos, int count, const char *fileType, int duration) {
    for (int i = 0; i < count; ++i) {
        if ((strcmp(infos[i].fileType, fileType) == 0) && (infos[i].duration == duration)) {
            return 0;
        }
    }
    return 1;
}

void processFile(const char *filePath, MediaInfo **mediaInfos, int *count, int maxRetries) {
    MediaInfo *info = malloc(sizeof(MediaInfo));
    if (!info) {
        logError("Memory allocation failed for MediaInfo");
        return;
    }

    memset(info, 0, sizeof(MediaInfo));
    info->filePath = strdup(filePath);

    for (int attempt = 0; attempt <= maxRetries; ++attempt) {
        if (retrieveFileMetadata(filePath, info)) {
            logError("Failed to retrieve metadata");
            free(info->filePath);
            free(info);
            return;
        }

        pthread_mutex_lock(&mutex);

        if (isUniqueMediaType(*mediaInfos, *count, info->fileType, info->duration)) {
            (*mediaInfos)[*count] = info;
            ++(*count);
            break;
        } else {
            int delay_ms = DELAY_MIN_MS + rand() % (DELAY_MAX_MS - DELAY_MIN_MS + 1);
            usleep(delay_ms * 1000); // Sleep for 'delay_ms' milliseconds
        }

        pthread_mutex_unlock(&mutex);

        if (attempt == maxRetries) {
            logError("Max retries reached, skipping file");
            free(info->filePath);
            free(info);
            return;
        }
    }
}

void* handleFile(void *arg) {
    char **filePaths = (char **)arg;
    int numFiles = *(int *)(((char *)arg) + sizeof(char *) * 100); // Assuming max of 100 files
    MediaInfo *mediaInfos[100];
    int count = 0;

    for (int i = 0; i < numFiles; ++i) {
        processFile(filePaths[i], mediaInfos, &count, MAX_RETRIES);
    }

    return NULL;
}

int processMediaAndHandleConcurrency(char **filePaths, int numFiles, int maxThreads) {
    if (!filePaths || numFiles <= 0) {
        logError("Invalid file paths or number of files");
        return -1;
    }

    pthread_t threads[maxThreads];
    int threadCount = (numFiles < maxThreads) ? numFiles : maxThreads;

    for (int i = 0; i < threadCount; ++i) {
        if (pthread_create(&threads[i], NULL, handleFile, (void *)(filePaths + i * (numFiles / threadCount))) != 0) {
            logError("Failed to create thread");
            return -1;
        }
    }

    for (int i = 0; i < threadCount; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Check for memory leaks
    if (globalMemoryLeakCounter > 0) {
        logError("Memory leak detected");
    }

    return 0;
}

