} SystemConfig;

typedef struct {
    SystemConfig config;
    size_t numSessions;
    NFAPI_CRC_INDICATION_PDU_T* sessions[MAX_SESSIONS];
} SessionManager;

uint8_t generate_crc_flag(unsigned int seed) {
    srand(seed);
    return rand() % 2; // Generates either 0 or 1
}

int validate_rnti(uint16_t rnti, SystemConfig config) {
    return (rnti >= config.minRNTI && rnti <= config.maxRNTI);
}

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

NFAPI_CRC_INDICATION_PDU_T* create_session(uint16_t rxTag, uint16_t rnti, SystemConfig config, unsigned int seed) {
    if (!validate_rnti(rnti, config)) {
        log_error("Invalid RNTI detected.");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* session = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!session) {
        log_error("Memory allocation failed for session.");
        return NULL;
    }

    session->RX_UE_INFORMATION_TAG = rxTag;
    session->RNTI = rnti;
    session->CRC_INDICATION_REL8_TAG = 0; // Placeholder, assuming some default
    session->CRCFLAG = generate_crc_flag(seed);

    return session;
}

int add_session(SessionManager* manager, uint16_t rxTag, uint16_t rnti, unsigned int seed) {
    if (manager->numSessions >= MAX_SESSIONS) {
        log_error("Maximum number of sessions reached.");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T* session = create_session(rxTag, rnti, manager->config, seed);
    if (!session) {
        return -1;
    }

    manager->sessions[manager->numSessions++] = session;

    return 0;
}

void cleanup_sessions(SessionManager* manager) {
    for (size_t i = 0; i < manager->numSessions; ++i) {
        free(manager->sessions[i]);
    }
    manager->numSessions = 0;
}

int main() {
    SessionManager manager = { .config = {100, 200}, .numSessions = 0 };

    // Example usage
    unsigned int seed = time(NULL);
    for (uint16_t rnti = 105; rnti <= 110; ++rnti) {
        add_session(&manager, rand() % 256, rnti, seed++);
    }

    cleanup_sessions(&manager);

    return 0;
}
