namespace RecordProcessing {

    struct record {
        int value;
    };

    class RandomNumberGenerator {
    public:
        RandomNumberGenerator() : rng(std::mt19937(std::random_device{}())) {}

        ~RandomNumberGenerator() {}

        int generate(int min, int max) {
            std::uniform_int_distribution<int> dist(min, max);
            return dist(rng);
        }

    private:
        std::mt19937 rng;
    };

    class RecordManager {
    public:
        RecordManager(size_t size)
            : offsetArray(nullptr), keyArray(nullptr), recordArray(nullptr),
              error(false) {

            try {
                offsetArray = new long[size];
                keyArray = new int[size];
                recordArray = new record[size];

                for (size_t i = 0; i < size; ++i) {
                    offsetArray[i] = static_cast<long>(rand() % 10000); // Example range
                    keyArray[i] = static_cast<int>(rand() % 10000);
                    recordArray[i].value = rng.generate(1, 100); // Random value between 1 and 100
                }
            } catch (const std::bad_alloc&) {
                error = true;
                cleanup();
            }

            if (!error) {
                sortRecords();
            }
        }

        ~RecordManager() {
            cleanup();
        }

        static void processAndSortRecords(size_t size) {
            RecordManager manager(size);
            // Process completed, memory is automatically cleaned up
        }

    private:
        long* offsetArray;
        int* keyArray;
        record* recordArray;

        RandomNumberGenerator rng;
        bool error;

        std::mutex mtx;  // Ensures thread safety

        void sortRecords() {
            std::lock_guard<std::mutex> lock(mtx);
            std::vector<size_t> indices(offsetArray, offsetArray + size);

            std::sort(indices.begin(), indices.end(),
                      [&](size_t i1, size_t i2) { return keyArray[i1] < keyArray[i2]; });

            for (size_t i = 0; i < size; ++i) {
                recordArray[i] = recordArray[indices[i]];
                offsetArray[i] = offsetArray[indices[i]];
                keyArray[i] = keyArray[indices[i]];
            }
        }

        void cleanup() {
            delete[] offsetArray;
            delete[] keyArray;
            delete[] recordArray;

            offsetArray = nullptr;
            keyArray = nullptr;
            recordArray = nullptr;
        }
    };

    void findAndPrintLargestInteger() {
        std::vector<int> numbers;
        int number;
        while (std::cin >> number) {
            numbers.push_back(number);
        }

        if (!numbers.empty()) {
            auto max_it = std::max_element(numbers.begin(), numbers.end());
            std::cout << "The largest integer is: " << *max_it << std::endl;
        }
    }

}  // namespace RecordProcessing

