    if (!pool->memory_pool) {
        free(pool);
        return NULL;
    }

    pool->pool_size = total_size;
    pool->block_size = block_size;
    return pool;
}

void* memory_pool_alloc(MemoryPool *pool) {
    static size_t current_offset = 0;

    if (current_offset + pool->block_size > pool->pool_size)
        return NULL; // Out of memory

    void *ptr = (char*)pool->memory_pool + current_offset;
    current_offset += pool->block_size;
    return ptr;
