        // Allocate memory for record's integer value
        manager->records[i].value = (int*)malloc(sizeof(int));
        if (!manager->records[i].value) goto error_cleanup4;

        // Initialize the record with a random unique value and set initialized flag
        *manager->records[i].value = generate_unique_random(min_val, max_val, used_values, manager->size);
        manager->records[i].initialized = true;
    }

    if (reset_operation) {
        for (size_t i = 0; i < manager->size; ++i) {
            if (manager->records[i].value) {
                *manager->records[i].value = 0;
            }
        }
    }

    // Clean up used values
    free(used_values);

    if (manager->concurrent_access_enabled) {
        pthread_mutex_unlock(&manager->mutex);
    }

    if (free_memory_after_completion) {
        free(manager->offsets);
        free(manager->keys);
        for (size_t i = 0; i < manager->size; ++i) {
            if (manager->records[i].value) {
                free(manager->records[i].value);
            }
        }
        free(manager->records);
    }

    pthread_mutex_destroy(&manager->mutex);
    return NULL;

error_cleanup4:
    for (size_t i = 0; i <= idx; ++i) {
        if (manager->records[i].value) {
            free(manager->records[i].value);
        }
    }
error_cleanup3:
    free(used_values);
error_cleanup2:
    free(manager->records);
error_cleanup1:
    free(manager->keys);
error_cleanup:
    free(manager->offsets);

    pthread_mutex_destroy(&manager->mutex);
    return NULL;
}

int main() {
    MemoryManager manager = {0};
    manager.size = 10; // Example size
    initialize_random_seed();

    int min_val = 1, max_val = 100;

    // Simulate thread execution
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, manage_memory, &manager)) {
        fprintf(stderr, "Error creating thread\n");
        return 1;
    }

    if (pthread_join(thread_id, NULL)) {
        fprintf(stderr, "Error joining thread\n");
        return 2;
    }

    return 0;
