#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int key;
    long offset;
    int value;
    struct Record* next;
} Record;

typedef struct DataStructure {
    Record* head;
    pthread_rwlock_t lock;
    int record_count;
} DataStructure;

DataStructure* create_data_structure() {
    DataStructure* ds = (DataStructure*)malloc(sizeof(DataStructure));
    if (!ds) return NULL;

    ds->head = NULL;
    pthread_rwlock_init(&ds->lock, NULL);
    ds->record_count = 0;
    return ds;
}

void free_record(Record* record) {
    free(record);
}

void compact_records(DataStructure* ds) {
    pthread_rwlock_wrlock(&ds->lock);

    Record *current = ds->head, *prev = NULL;
    while (current && current->next) {
        if ((long)(current + 1) == current->next) { // Check adjacency
            Record* next_next = current->next->next;
            free_record(current->next);
            current->next = next_next;
            ds->record_count--;
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_rwlock_unlock(&ds->lock);
}

void insert_record(DataStructure* ds, int key, long offset, int value) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) return;

    new_record->key = key;
    new_record->offset = offset;
    new_record->value = value;

    pthread_rwlock_wrlock(&ds->lock);

    new_record->next = ds->head;
    ds->head = new_record;
    ds->record_count++;

    pthread_rwlock_unlock(&ds->lock);
}

Record* find_record(DataStructure* ds, int key) {
    Record* current = NULL;
    pthread_rwlock_rdlock(&ds->lock);

    for (current = ds->head; current != NULL; current = current->next) {
        if (current->key == key)
            break;
    }

    pthread_rwlock_unlock(&ds->lock);
    return current;
}

void update_record(DataStructure* ds, int key, long offset, int value) {
    Record* record = find_record(ds, key);
    if (!record) return;

    pthread_rwlock_wrlock(&ds->lock);

    record->offset = offset;
    record->value = value;

    pthread_rwlock_unlock(&ds->lock);
}

void delete_record(DataStructure* ds, int key) {
    Record *current = NULL, *prev = NULL;

    pthread_rwlock_wrlock(&ds->lock);

    for (current = ds->head; current != NULL; prev = current, current = current->next) {
        if (current->key == key)
            break;
    }

    if (!current) {
        pthread_rwlock_unlock(&ds->lock);
        return;
    }

    if (prev == NULL) { // Removing head
        ds->head = current->next;
    } else {
        prev->next = current->next;
    }

    free_record(current);
    ds->record_count--;

    pthread_rwlock_unlock(&ds->lock);
}

void destroy_data_structure(DataStructure* ds) {
    Record *current = NULL, *next = NULL;

    pthread_rwlock_wrlock(&ds->lock);

    for (current = ds->head; current != NULL; current = next) {
        next = current->next;
        free_record(current);
    }

    pthread_rwlock_unlock(&ds->lock);
    pthread_rwlock_destroy(&ds->lock);
    free(ds);
}

// Example of usage
int main() {
    DataStructure* ds = create_data_structure();
    if (!ds) {
        fprintf(stderr, "Failed to allocate data structure\n");
        return 1;
    }

    insert_record(ds, 1, 100L, 10);
    Record* record = find_record(ds, 1);
    if (record) {
        printf("Found record: key=%d, offset=%ld, value=%d\n", 
               record->key, record->offset, record->value);
    }

    update_record(ds, 1, 200L, 20);
    delete_record(ds, 1);

    destroy_data_structure(ds);

    return 0;
}
