typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int TX_POWER_INFO_TAG;
    int UE_IDENTITY_INFO_TAG;
    int FREQ_SELECTIVE_DOWNSPREADER_TAG;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = (DynamicArray *)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->data = (NFAPI_CRC_INDICATION_PDU_T *)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void resize_dynamic_array(DynamicArray *array) {
    size_t new_capacity = array->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) return; // Handle realloc failure gracefully

    array->data = new_data;
    array->capacity = new_capacity;
}

bool add_element(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&array->lock);

    if (array->size == array->capacity) {
        resize_dynamic_array(array);
        if (array->size == array->capacity) { // Check again after resizing
            pthread_mutex_unlock(&array->lock);
            return false;
        }
    }

    array->data[array->size++] = element;

    pthread_mutex_unlock(&array->lock);
    return true;
}

bool remove_element(DynamicArray *array, size_t index) {
    pthread_mutex_lock(&array->lock);

    if (index >= array->size) {
        pthread_mutex_unlock(&array->lock);
        return false;
    }

    for (size_t i = index; i < array->size - 1; ++i) {
        array->data[i] = array->data[i + 1];
    }

    --array->size;
    pthread_mutex_unlock(&array->lock);
    return true;
}

bool update_element(DynamicArray *array, size_t index, NFAPI_CRC_INDICATION_PDU_T new_element) {
    pthread_mutex_lock(&array->lock);

    if (index >= array->size) {
        pthread_mutex_unlock(&array->lock);
        return false;
    }

    array->data[index] = new_element;
    pthread_mutex_unlock(&array->lock);
    return true;
}

void free_dynamic_array(DynamicArray *array) {
    pthread_mutex_lock(&array->lock);

    free(array->data);
    array->data = NULL;
    array->capacity = 0;
    array->size = 0;

    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

// Example usage
int main() {
    DynamicArray *array = create_dynamic_array(4);

    NFAPI_CRC_INDICATION_PDU_T element1 = {{1, 2, 3, {0}}};
    add_element(array, element1);

    element1.rx_ue_information_tag.crc_indication_rel8_tag.CRCFLAG = rand() % 2;
    update_element(array, 0, element1);

    remove_element(array, 0);

    free_dynamic_array(array);
    return 0;
}
