typedef struct {
    int *data;
    bool is_initialized;
} record;

void DynamicMemoryAllocator(size_t offset_size, size_t key_size, size_t record_size,
                            int min_val, int max_val, bool reset_flag, bool free_memory,
                            unsigned int *seed) {

    long *offsets = (long *)malloc(offset_size * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets.\n");
        return;
    }

    int *keys = (int *)malloc(key_size * sizeof(int));
    if (!keys) {
        free(offsets);
        fprintf(stderr, "Memory allocation failed for keys.\n");
        return;
    }

    record *records = (record *)malloc(record_size * sizeof(record));
    if (!records) {
        free(keys);
        free(offsets);
        fprintf(stderr, "Memory allocation failed for records.\n");
        return;
    }

    srand(*seed);

    // Initialize keys with unique values in the given range
    bool found;
    for (size_t i = 0; i < key_size; ++i) {
        do {
            found = false;
            keys[i] = rand() % (max_val - min_val + 1) + min_val;

            for (size_t j = 0; j < i; ++j) {
                if (keys[j] == keys[i]) {
                    found = true;
                    break;
                }
            }
        } while (found);
    }

    // Initialize offsets and records
    for (size_t i = 0; i < record_size; ++i) {
        offsets[i] = rand() % key_size;

        records[i].data = (int *)malloc(sizeof(int));
        if (!records[i].data) {
            fprintf(stderr, "Memory allocation failed for record data.\n");
            // Free previously allocated memory
            while (--i >= 0) free(records[i].data);
            free(keys);
            free(offsets);
            free(records);
            return;
        }

        *records[i].data = rand() % (max_val - min_val + 1) + min_val;
        records[i].is_initialized = true;
    }

    // Reset mechanism
    if (reset_flag) {
        for (size_t i = 0; i < record_size; ++i) {
            *records[i].data = 0;
        }
    }

    // Free allocated memory if requested
    if (free_memory) {
        for (size_t i = 0; i < record_size; ++i) {
            free(records[i].data);
        }
        free(keys);
        free(offsets);
        free(records);
    }
}

int main() {
    unsigned int seed = time(NULL);
    DynamicMemoryAllocator(10, 5, 7, 1, 100, true, false, &seed);

    // Simulate freeing memory after use
    DynamicMemoryAllocator(0, 0, 0, 0, 0, false, true, &seed);

    return 0;
}
