#define MAX_STRUCTS 10000
#define VALID_RNTI_MAX 65535

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
        // other fields...
    } CRC_INDICATION_REL8_TAG;
