// Global variables for tracking
static volatile int keep_running = 1;
pthread_mutex_t mtx = PTHREAD_MUTEX_INITIALIZER;
uint32_t total_time_ns = 0, memory_usage_kb = 0; // Simplified metrics

// Simulate external RNTI validation with caching mechanism
int is_valid_rnti(uint16_t rnti) {
    static uint16_t cache[MAX_STRUCTS];
    static int cache_size = 0;

    for (int i = 0; i < cache_size; ++i) {
        if (cache[i] == rnti) return 1;
    }

    // Simulate network call and caching
    // This would be replaced by actual RNTI validation logic.
    int valid = (rnti <= VALID_RNTI_MAX);
    if (valid && cache_size < MAX_STRUCTS) {
        cache[cache_size++] = rnti;
    }

    return valid;
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    keep_running = 0;
}

void setup_signal_handling() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* process_crc_indications(int num_structs) {
    if (num_structs > MAX_STRUCTS || num_structs <= 0) {
        fprintf(stderr, "Invalid number of structures.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(num_structs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        perror("Memory allocation failed");
        return NULL;
    }

    clockid_t clk_id = CLOCK_MONOTONIC;
    struct timespec start, end;

    // Timing execution
    clock_gettime(clk_id, &start);

    srand((unsigned int)time(NULL));
    for (int i = 0; i < num_structs; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 65536;

        uint16_t rnti;
        do {
            rnti = rand() % 65536;
        } while (!is_valid_rnti(rnti));

        pdus[i].RNTI = rnti;
        pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() & 1);
    }

    // Timing end
    clock_gettime(clk_id, &end);
    total_time_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);

    // Simulated memory usage tracking (in KB)
    memory_usage_kb = num_structs * sizeof(NFAPI_CRC_INDICATION_PDU_T) / 1024;

    return pdus;
}

void cleanup_resources() {
    pthread_mutex_lock(&mtx);
    printf("Total time taken: %lu ns\n", total_time_ns);
    printf("Memory usage: %u KB\n", memory_usage_kb);
    pthread_mutex_unlock(&mtx);
}

int main(int argc, char *argv[]) {
    setup_signal_handling();

    int num_structs = 10000; // Example input
    NFAPI_CRC_INDICATION_PDU_T* pdus = process_crc_indications(num_structs);

    if (pdus) {
        printf("Processing completed.\n");
        free(pdus);
    } else {
        fprintf(stderr, "Failed to process CRC indications.\n");
    }

    cleanup_resources();

    return 0;
}
