typedef struct {
    int *value;
    bool is_initialized;
} Record;

typedef struct {
    pthread_mutex_t mutex;
    uint32_t active_threads;
    uint32_t max_threads;
} ThreadManager;

static void log_event(const char* event_type, const char* message) {
    time_t now = time(NULL);
    printf("[%s] %s: %s\n", ctime(&now), event_type, message);
}

void initialize_thread_manager(ThreadManager *tm, uint32_t max_threads) {
    pthread_mutex_init(&tm->mutex, NULL);
    tm->active_threads = 0;
    tm->max_threads = max_threads;
}

void lock_thread_manager(ThreadManager *tm) {
    pthread_mutex_lock(&tm->mutex);
    if (tm->active_threads >= tm->max_threads) {
        // Graceful degradation logic
        sleep(1); // Simulate wait time when max threads are active
    }
    tm->active_threads++;
    pthread_mutex_unlock(&tm->mutex);
}

void unlock_thread_manager(ThreadManager *tm) {
    pthread_mutex_lock(&tm->mutex);
    tm->active_threads--;
    pthread_mutex_unlock(&tm->mutex);
}

int generate_unique_random_int(int min, int max, bool* used_values) {
    int num_range = max - min + 1;
    while (true) {
        int rand_val = rand() % num_range + min;
        if (!used_values[rand_val]) {
            used_values[rand_val] = true;
            return rand_val;
        }
    }
}

void allocate_and_initialize(int offset_count, int key_count, int record_count, int value_min, int value_max) {
    long *offsets = malloc(offset_count * sizeof(long));
    if (!offsets) { log_event("ERROR", "Failed to allocate offsets"); return; }

    int *keys = malloc(key_count * sizeof(int));
    if (!keys) { log_event("ERROR", "Failed to allocate keys"); free(offsets); return; }

    Record *records = malloc(record_count * sizeof(Record));
    if (!records) { log_event("ERROR", "Failed to allocate records"); free(keys); free(offsets); return; }

    bool used_values[value_max - value_min + 1] = {false};

    for (int i = 0; i < record_count; ++i) {
        int *value_ptr = malloc(sizeof(int));
        if (!value_ptr) { log_event("ERROR", "Failed to allocate integer in record"); break; }

        records[i].value = value_ptr;
        records[i].is_initialized = true;

        *records[i].value = generate_unique_random_int(value_min, value_max, used_values);
    }

    // Simulate logging
    log_event("INFO", "Memory allocated and initialized");

    free(offsets); 
    free(keys); 
    for (int i = 0; i < record_count; ++i) {
        if (records[i].is_initialized) {
            free(records[i].value);
        }
    }
    free(records);

    log_event("INFO", "Memory deallocated");
}

void reset_records(Record *records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (records[i].is_initialized && records[i].value) {
            *records[i].value = 0;
        }
    }
}

void export_state(const char *filename, long *offsets, int offset_count, int *keys, int key_count, Record *records, int record_count) {
    FILE *file = fopen(filename, "w");
    if (!file) { log_event("ERROR", "Failed to open file for exporting"); return; }

    fprintf(file, "Offsets:\n");
    for (int i = 0; i < offset_count; ++i) {
        fprintf(file, "%ld\n", offsets[i]);
    }
    fprintf(file, "Keys:\n");
    for (int i = 0; i < key_count; ++i) {
        fprintf(file, "%d\n", keys[i]);
    }
    fprintf(file, "Records:\n");
    for (int i = 0; i < record_count; ++i) {
        if (records[i].is_initialized && records[i].value) {
            fprintf(file, "%d %s\n", *records[i].value, records[i].is_initialized ? "Initialized" : "Not Initialized");
        }
    }

    fclose(file);
    log_event("INFO", "State exported successfully");
}

// Main function demonstrating usage
int main() {
    srand(time(NULL)); // Seed for random number generation

