    int *keys = malloc(key_count * sizeof(int));
    Record *records = malloc(record_count * sizeof(Record));

    lock_thread_manager(&tm);
    allocate_and_initialize(offset_count, key_count, record_count, value_min, value_max);
    unlock_thread_manager(&tm);

