} FileInfo;

FileInfo* collectFileMetadata(char *filePaths[], int numFiles, size_t *sizesArray, time_t *timestampsArray, mode_t *permissionsArray) {
    if (!filePaths || !numFiles > 0) return NULL;

    FileInfo *filesInfo = (FileInfo *)malloc(numFiles * sizeof(FileInfo));
    sizesArray = (size_t *)malloc(numFiles * sizeof(size_t));
    timestampsArray = (time_t *)malloc(numFiles * sizeof(time_t));
    permissionsArray = (mode_t *)malloc(numFiles * sizeof(mode_t));

    for (int i = 0; i < numFiles; ++i) {
        struct stat fileStat;

        if (stat(filePaths[i], &fileStat) == -1) {
            fprintf(stderr, "Warning: Could not access %s\n", filePaths[i]);
            filesInfo[i].file_size = 0;
            filesInfo[i].mod_time = 0;
            filesInfo[i].permissions = 0;
        } else {
            filesInfo[i].file_size = fileStat.st_size;
            filesInfo[i].mod_time = fileStat.st_mtime;
            filesInfo[i].permissions = fileStat.st_mode;

            sizesArray[i] = filesInfo[i].file_size;
            timestampsArray[i] = filesInfo[i].mod_time;
            permissionsArray[i] = filesInfo[i].permissions;
        }
    }

    return filesInfo;
}

void freeFileMetadata(FileInfo *filesInfo, size_t numFiles) {
    if (filesInfo) {
        free(filesInfo);
    }
}
