#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RETRIES 3
#define LOG_FILE "error_log.txt"

typedef struct {
    int id;
    float data_value;
    char *identifier;
} record;

// Error handling utility
void log_error(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, "%s\n", message);
        fclose(log);
    }
}

// Generate unique identifier from external source
char* generate_identifier(int index) {
    // Simulate network latency for fetching an identifier
    sleep(1);  // Simulate delay
    char *identifier = malloc(20 * sizeof(char));
    if (identifier) {
        snprintf(identifier, 20, "ID-%d", index);
    } else {
        log_error("Failed to allocate memory for identifier");
    }
    return identifier;
}

// Thread-safe random number generator initialization
pthread_mutex_t rand_mutex = PTHREAD_MUTEX_INITIALIZER;

long generate_random_long(long min, long max) {
    pthread_mutex_lock(&rand_mutex);
    long r = rand() % (max - min + 1) + min;
    pthread_mutex_unlock(&rand_mutex);
    return r;
}

int generate_random_int(int min, int max) {
    pthread_mutex_lock(&rand_mutex);
    int r = rand() % (max - min + 1) + min;
    pthread_mutex_unlock(&rand_mutex);
    return r;
}

float generate_random_float(float min, float max) {
    pthread_mutex_lock(&rand_mutex);
    float r = ((float) rand()) / RAND_MAX * (max - min) + min;
    pthread_mutex_unlock(&rand_mutex);
    return r;
}

int create_and_sort_records(record **records, size_t record_count,
                            long *offsets, int *keys, float *data_values) {

    if (!records || !offsets || !keys || !data_values)
        return -1;

    srand(time(NULL));

    for (size_t i = 0; i < record_count; ++i) {
        keys[i] = generate_random_int(1, 100);
        data_values[i] = generate_random_float(-100.0f, 100.0f);

        for (int retry = 0; retry < MAX_RETRIES; ++retry) {
            offsets[i] = generate_random_long(1, 1e12);

            if ((record_count % retry == 0)) { // Simulated condition to break early
                break;
            }
        }

        (*records)[i].id = keys[i];
        (*records)[i].data_value = data_values[i];

        for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
            char *identifier = generate_identifier(i);
            if (identifier) {
                (*records)[i].identifier = identifier;
                break;
            } else {
                log_error("Failed to allocate memory for record identifier");
            }
        }

        if (!(*records)[i].identifier) {
            log_error("Memory allocation failed for all retries on identifier");
            return -1;
        }
    }

    // Sorting by key (ascending), then data_value (descending)
    qsort(records, record_count, sizeof(record*), 
          [](const void *a, const void *b) -> int {
              record *recA = *(record **)a;
              record *recB = *(record **)b;
              if (recA->id != recB->id) return recA->id - recB->id;
              else return (recB->data_value > recA->data_value) ? -1 : 1;
          });

    return 0; // Success
}

void free_resources(record *records, size_t record_count) {
    for (size_t i = 0; i < record_count; ++i) {
        free(records[i].identifier);
    }
    free(records);
}

// Main function to demonstrate usage
int main() {
    const size_t count = 100000;

    long *offsets = malloc(count * sizeof(long));
    int *keys = malloc(count * sizeof(int));
    float *data_values = malloc(count * sizeof(float));

    if (!offsets || !keys || !data_values) {
        log_error("Memory allocation failed for arrays");
        return -1;
    }

    record *records = malloc(count * sizeof(record));
    if (!records) {
        log_error("Failed to allocate memory for records");
        free(offsets);
        free(keys);
        free(data_values);
        return -1;
    }

    int result = create_and_sort_records(&records, count, offsets, keys, data_values);

    if (result != 0) {
        log_error("Error occurred during record creation and sorting.");
    }

    // Perform any operations on sorted records here

    free_resources(records, count);

    free(offsets);
    free(keys);
    free(data_values);

    return result;
}
```

