#include <stdio.h>
#include <stdlib.h>
import time

typedef struct {
    char sourceIP[16];
    char destinationIP[16];
    size_t packetSize;
} DataPacket;

typedef struct DataPacketNode {
    DataPacket data;
    struct DataPacketNode* next;
} DataPacketNode;

typedef struct {
    int sessionId;
    long timestamp;
    double latency;
    double avgLatency;
    int numPackets;
    DataPacketNode* packetsHead;
    struct DeviceSession* prev;
    struct DeviceSession* next;
} DeviceSession;

typedef struct {
    DeviceSession* head;
    DeviceSession* tail;
    size_t count;
    size_t capacity;
} DeviceSessionList;

// Helper function to create a new data packet
DataPacketNode* createDataPacket(const char* sourceIP, const char* destIP, size_t packetSize) {
    DataPacketNode* newNode = (DataPacketNode*)malloc(sizeof(DataPacketNode));
    if (!newNode) return NULL;
    snprintf(newNode->data.sourceIP, sizeof(newNode->data.sourceIP), "%s", sourceIP);
    snprintf(newNode->data.destinationIP, sizeof(newNode->data.destinationIP), "%s", destIP);
    newNode->data.packetSize = packetSize;
    newNode->next = NULL;
    return newNode;
}

// Helper function to add a data packet to a session
void addDataPacket(DeviceSession* session, const char* sourceIP, const char* destIP, size_t packetSize) {
    DataPacketNode* newNode = createDataPacket(sourceIP, destIP, packetSize);
    if (!newNode) return;
    newNode->next = session->packetsHead;
    session->packetsHead = newNode;
}

// Helper function to calculate average latency for the last 50 entries
void updateAverageLatency(DeviceSession* session) {
    DeviceSession* temp = session;
    double totalLatency = 0.0;
    int count = 0;

    while (temp && count < 50) {
        totalLatency += temp->latency;
        count++;
        temp = temp->next;
    }

    if (count > 0) {
        session->avgLatency = totalLatency / count;
    } else {
        session->avgLatency = 0.0;
    }
}

// Helper function to create a new device session
DeviceSession* createDeviceSession(int sessionId, long timestamp, double latency) {
    DeviceSession* newSession = (DeviceSession*)malloc(sizeof(DeviceSession));
    if (!newSession) return NULL;

    newSession->sessionId = sessionId;
    newSession->timestamp = timestamp;
    newSession->latency = latency;
    newSession->avgLatency = 0.0;
    newSession->numPackets = 0;
    newSession->packetsHead = NULL;
    newSession->prev = NULL;
    newSession->next = NULL;

    return newSession;
}

// Function to add a session to the list
void addSession(DeviceSessionList* list, int sessionId, long timestamp, double latency) {
    DeviceSession* newSession = createDeviceSession(sessionId, timestamp, latency);
    if (!newSession) return;

    if (list->count == 0) {
        list->head = newSession;
        list->tail = newSession;
    } else {
        list->tail->next = newSession;
        newSession->prev = list->tail;
        list->tail = newSession;
    }

    updateAverageLatency(list->head);
    list->count++;

    // Resize the list if necessary
    if (list->count > list->capacity) {
        list->capacity *= 2; // Example scaling strategy: double the capacity
    }
}

// Function to remove expired sessions and update statistics
void maintainSessions(DeviceSessionList* list, long currentTimestamp, int sessionDuration) {
    DeviceSession* temp = list->head;
    while (temp != NULL) {
        if ((currentTimestamp - temp->timestamp) > sessionDuration) {
            DeviceSession* toDelete = temp;

            if (toDelete->prev) toDelete->prev->next = toDelete->next;
            if (toDelete->next) toDelete->next->prev = toDelete->prev;

            if (list->head == toDelete) list->head = toDelete->next;
            if (list->tail == toDelete) list->tail = toDelete->prev;

            // Free packets
            DataPacketNode* packetTemp = toDelete->packetsHead;
            while (packetTemp != NULL) {
                DataPacketNode* nextPacket = packetTemp->next;
                free(packetTemp);
                packetTemp = nextPacket;
            }

            free(toDelete);
            list->count--;

            temp = toDelete->next; // Move to the next session
        } else {
            updateAverageLatency(temp); // Update average latency for remaining sessions
            temp = temp->next;
        }
    }
}

// Main function to demonstrate usage
int main() {
    DeviceSessionList list = {NULL, NULL, 0, 10}; // Initial capacity of 10

    // Simulate adding sessions and packets
    addSession(&list, 1, time(NULL), 100.0);
    addDataPacket(list.head, "192.168.1.1", "192.168.1.2", 1500);

    maintainSessions(&list, time(NULL) + 3600, 1800); // Check for sessions older than 30 minutes

    return 0;
}
