} CircularBuffer;

CircularBuffer* create_circular_buffer(int capacity) {
    CircularBuffer* buffer = (CircularBuffer*)malloc(sizeof(CircularBuffer));
    if (!buffer) return NULL;

    buffer->entries = (LogEntry*)malloc(capacity * sizeof(LogEntry));
    if (!buffer->entries) {
        free(buffer);
        return NULL;
    }

    buffer->capacity = capacity;
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;

    pthread_mutex_init(&buffer->lock, NULL);

    return buffer;
}

int is_valid_timestamp(long timestamp) {
