}

LogEntry* allocate_log_entries(int num_entries, long** timestamps, char*** usernames, CircularBuffer** buffer) {
    if (num_entries <= 0 || SYSTEM_MEMORY_LIMIT < sizeof(LogEntry) * num_entries + sizeof(CircularBuffer)) {
        log_error("Insufficient memory or invalid number of entries");
        return NULL;
    }

    LogEntry* logs = (LogEntry*)malloc(num_entries * sizeof(LogEntry));
    if (!logs) {
        log_error("Memory allocation failed for LogEntries");
        return NULL;
    }

    *timestamps = (long*)malloc(num_entries * sizeof(long));
    if (!(*timestamps)) {
        free(logs);
        log_error("Memory allocation failed for Timestamps");
        return NULL;
    }

    *usernames = (char**)malloc(num_entries * sizeof(char*));
    if (!(*usernames)) {
        free(logs);
        free(*timestamps);
        log_error("Memory allocation failed for Usernames");
        return NULL;
    }

    for (int i = 0; i < num_entries; ++i) {
        (*usernames)[i] = (char*)malloc(MAX_USERNAME_LENGTH * sizeof(char));
        if (!(*usernames)[i]) {
            free(logs);
            free(*timestamps);
            while (--i >= 0) free((*usernames)[i]);
            free(*usernames);
            log_error("Memory allocation failed for Username");
            return NULL;
        }
    }

    int buffer_capacity = num_entries / 2; // Example capacity
    *buffer = create_circular_buffer(buffer_capacity);
    if (!*buffer) {
        free(logs);
        free(*timestamps);
        while (--num_entries >= 0) free((*usernames)[num_entries]);
        free(*usernames);
        log_error("Memory allocation failed for CircularBuffer");
        return NULL;
    }

    // Example: Initialize with valid data
    for (int i = 0; i < num_entries; ++i) {
        (*timestamps)[i] = time(NULL); // Current timestamp as placeholder
        snprintf((*usernames)[i], MAX_USERNAME_LENGTH, "User%d", i + 1);
        if (!is_valid_timestamp((*timestamps)[i])) {
            log_error("Invalid timestamp detected");
            continue;
        }

        logs[i].timestamp = (*timestamps)[i];
        strncpy(logs[i].message, "Sample message", sizeof(logs[i].message) - 1);
        snprintf(logs[i].session_id, SESSION_ID_LENGTH, "Session%d", i + 1);

        pthread_mutex_lock(&(*buffer)->lock);
        if ((*buffer)->count < (*buffer)->capacity) {
            (*buffer)->entries[(*buffer)->tail] = logs[i];
            (*buffer)->tail = ((*buffer)->tail + 1) % (*buffer)->capacity;
            ++(*buffer)->count;
        } else {
            // Buffer overflow, drop oldest entry
            (*buffer)->head = ((*buffer)->head + 1) % (*buffer)->capacity;
            (*buffer)->entries[(*buffer)->tail] = logs[i];
            (*buffer)->tail = ((*buffer)->tail + 1) % (*buffer)->capacity;
        }
        pthread_mutex_unlock(&(*buffer)->lock);
    }

    return logs;
}

void free_resources(LogEntry* logs, long* timestamps, char** usernames, CircularBuffer* buffer) {
    if (logs) free(logs);
    if (timestamps) free(timestamps);
    if (usernames) {
        for (int i = 0; usernames[i] != NULL; ++i) {
            free(usernames[i]);
        }
        free(usernames);
    }
    if (buffer) {
        pthread_mutex_destroy(&buffer->lock);
        free(buffer->entries);
        free(buffer);
    }
}

