                newNode->next = head;
                head = newNode;
            } else {
                Node* current = head;
                while (current->next != NULL && current->next->key < newNode->key) {
                    current = current->next;
                }
                newNode->next = current->next;
                current->next = newNode;
            }
            pthread_mutex_unlock(&lock);
        }
    }

    // Find the largest integer in keys
    int largestKey = keys[0];
    for (size_t i = 1; i < n; ++i) {
        if (keys[i] > largestKey) {
            largestKey = keys[i];
        }
    }
    printf("Largest Key: %d\n", largestKey);

    // Free allocated memory
    freeMemory(head, offsets, keys);

    pthread_mutex_destroy(&lock);
    return NULL;
}

