    return 0; // Success code
}

// Comparison function for sorting by key in ascending order.
int compare_by_key(const void *a, const void *b) {
    Record *record_a = (Record *)a;
    Record *record_b = (Record *)b;
    return record_a->key - record_b->key;
}

// Comparison function for sorting weights in descending order.
int compare_by_weight_desc(const void *a, const void *b) {
    Record *record_a = (Record *)a;
    Record *record_b = (Record *)b;
    if (record_a->weight < record_b->weight)
        return 1;
    else if (record_a->weight > record_b->weight)
        return -1;
    return 0;
}

// Function to optionally sort records.
