    pthread_mutex_lock(&record_mutex);

    // Sorting based on configuration
    if (config.sort_by_key) {
        qsort(records, count, sizeof(Record), compare_by_key);
    }

    if (config.sort_descending_weight) {
        qsort(records, count, sizeof(Record), compare_by_weight_desc);
    }

    pthread_mutex_unlock(&record_mutex);
}

