float computeAverageBattery(float *batteryLevels, int count) {
    float sum = 0.0;
    for (int i = 0; i < count; ++i) {
        sum += batteryLevels[i];
    }
    return count > 0 ? sum / count : 0.0f;
}

void initializeDeviceHealthMetrics(DeviceHealthMetrics *metrics, int numDevices) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < numDevices && i < MAX_DEVICES; ++i) {
        snprintf(metrics[i].deviceId, sizeof(metrics[i].deviceId), "Device_%d", i + 1);
        metrics[i].timestamp = time(NULL);
        float batteryLevels[24] = {0};

        for (int j = 0; j < 24; ++j) {
            // Simulating power usage data
            batteryLevels[j] = rand() % 101;
        }

        metrics[i].batteryLevel = batteryLevels[rand() % 24];
        int eventCount = rand() % MAX_EVENTS;

        for (int k = 0; k < eventCount && k < MAX_EVENTS; ++k) {
            metrics[i].events[k].timestamp = time(NULL) - (rand() % (60 * 60 * 24));
            metrics[i].events[k].eventCode = rand();
            metrics[i].events[k].eventType = EventType(rand() % 3);
        }

        metrics[i].averageBatteryLast24H = computeAverageBattery(batteryLevels, 24);

        // Diagnostic logging
        printf("Initialized Device: %s, Avg Battery Last 24h: %.2f%%\n",
               metrics[i].deviceId, metrics[i].averageBatteryLast24H);
    }

    pthread_mutex_unlock(&lock);
}

int main() {
    srand(time(NULL));
    DeviceHealthMetrics deviceMetrics[MAX_DEVICES];

    initializeDeviceHealthMetrics(deviceMetrics, MAX_DEVICES);

    return 0;
}
