    class Logger {
    public:
        void log(const std::string& message) {
            std::lock_guard<std::mutex> lock(mutex_);
            std::cout << "[LOG] " << message << std::endl;
        }

        void alert(const std::string& anomaly) {
            std::lock_guard<std::mutex> lock(mutex_);
            std::cerr << "[ALERT] " << anomaly << std::endl;
        }
    private:
        std::mutex mutex_;
    };

    class DataProcessor {
    public:
        DataProcessor(const std::string& file_path)
            : logger_(std::make_shared<Logger>()) {}

        void loadTransactions() {
            std::ifstream file(file_path_);
            if (!file.is_open()) {
                logger_->log("Failed to open file.");
                return;
            }

            std::string line;
            while (std::getline(file, line)) {
                auto transaction = parseTransaction(line);
                if (transaction) {
                    std::unique_lock lock(mutex_);
                    transactions_[std::get<1>(*transaction)] = *transaction;
                }
            }
        }

