            // Implementation for aggregating transaction amounts by user ID
        }

        void exportToJSON(const std::string& output_file) {
            nlohmann::json j;
            {
                std::shared_lock lock(mutex_);
                for (const auto& [id, txn] : transactions_) {
                    j.push_back({
                        {"timestamp", std::get<0>(txn)},
                        {"transaction_id", id},
                        {"amount", std::get<2>(txn)},
                        {"status", std::get<3>(txn)}
                    });
                }
            }

            std::ofstream file(output_file);
            if (file.is_open()) {
                file << j.dump(4);
            } else {
                logger_->log("Failed to open output file.");
            }
        }

    private:
        Transaction parseTransaction(const std::string& line) {
            std::istringstream ss(line);
            std::string timestamp, transaction_id, status;
            double amount;

            if (!(ss >> timestamp >> transaction_id >> amount >> status)) {
                logger_->log("Malformed transaction entry.");
                return nullptr;
            }

            // Validate data
            if (amount < 0) {
                logger_->alert("Negative transaction amount detected.");
                return nullptr;
            }

            return std::make_tuple(timestamp, transaction_id, amount, status);
        }

        const std::string file_path_;
        TransactionsMap transactions_;
        mutable std::shared_mutex mutex_;
        std::shared_ptr<Logger> logger_;

    };

