['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_LOG_SIZE 1024

typedef struct Node {
    int key;
    void *data;
    struct Node **dependencies;
    size_t dependency_count;
} Node;

typedef struct Dataset {
    Node **nodes;
    size_t node_count;
    pthread_mutex_t lock;
} Dataset;

typedef enum { SUCCESS, MEMORY_ERROR, FILE_ERROR, LOG_ERROR } ErrorCode;

void log_message(const char *message) {
    static pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&log_lock);

    FILE *log_file = fopen("dataset.log", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    char full_message[MAX_LOG_SIZE];
    snprintf(full_message, MAX_LOG_SIZE, "%s\n", message);

    fputs(full_message, log_file);
    fclose(log_file);

    pthread_mutex_unlock(&log_lock);
}

Dataset* initialize_dataset(const char *filename) {
    Dataset *dataset = malloc(sizeof(Dataset));
    if (!dataset) return NULL;

    dataset->nodes = NULL;
    dataset->node_count = 0;
    pthread_mutex_init(&dataset->lock, NULL);

    FILE *file = fopen(filename, "rb");
    if (!file) {
        log_message("Failed to open file.");
        free(dataset);
        return NULL;
    }

    Node *temp_nodes[1024]; // Temporary storage
    size_t temp_count = 0;

    while (fread(&temp_nodes[temp_count], sizeof(Node), 1, file)) {
        if (!temp_nodes[temp_count].dependencies) {
            log_message("File format anomaly: Missing dependencies.");
            fclose(file);
            free(dataset);
            return NULL;
        }
        temp_count++;
    }

    if (ferror(file)) {
        log_message("Error reading from file.");
        fclose(file);
        free(dataset);
        return NULL;
    }

    fclose(file);

    dataset->nodes = malloc(temp_count * sizeof(Node *));
    if (!dataset->nodes) {
        log_message("Memory allocation failed for nodes array.");
        free(dataset);
        return NULL;
    }

    memcpy(dataset->nodes, temp_nodes, temp_count * sizeof(Node *));
    dataset->node_count = temp_count;

    // Sort nodes by key
    qsort(dataset->nodes, temp_count, sizeof(Node *), (int (*)(const void *, const void *)) strcmp);

    log_message("Dataset initialized and sorted.");
    return dataset;
}

ErrorCode update_node(Dataset *dataset, int key, void *new_data) {
    pthread_mutex_lock(&dataset->lock);

    for (size_t i = 0; i < dataset->node_count; ++i) {
        if (dataset->nodes[i]->key == key) {
            free(dataset->nodes[i]->data);
            dataset->nodes[i]->data = new_data;

            log_message("Node updated.");
            pthread_mutex_unlock(&dataset->lock);
            return SUCCESS;
        }
    }

    log_message("Key not found for update.");
    pthread_mutex_unlock(&dataset->lock);
    return MEMORY_ERROR; // Or another appropriate error code
}

ErrorCode add_node(Dataset *dataset, Node *new_node) {
    pthread_mutex_lock(&dataset->lock);

    size_t new_count = dataset->node_count + 1;
    Node **new_nodes = realloc(dataset->nodes, new_count * sizeof(Node *));

    if (!new_nodes) {
        log_message("Memory allocation failed for adding node.");
        pthread_mutex_unlock(&dataset->lock);
        return MEMORY_ERROR;
    }

    dataset->nodes = new_nodes;
    dataset->node_count = new_count;

    // Find insertion point to maintain sorted order
    size_t i;
    for (i = 0; i < dataset->node_count - 1; ++i) {
        if (dataset->nodes[i]->key > new_node->key)
            break;
    }

    memmove(&dataset->nodes[i + 1], &dataset->nodes[i], (dataset->node_count - i - 1) * sizeof(Node *));
    dataset->nodes[i] = new_node;

    log_message("Node added and sorted.");
    pthread_mutex_unlock(&dataset->lock);
    return SUCCESS;
}

void free_dataset(Dataset *dataset) {
    if (!dataset) return;

    for (size_t i = 0; i < dataset->node_count; ++i) {
        free(dataset->nodes[i]->data); // Assuming data was dynamically allocated
        free(dataset->nodes[i]->dependencies);
        free(dataset->nodes[i]);
    }

    free(dataset->nodes);
    pthread_mutex_destroy(&dataset->lock);
    free(dataset);

    log_message("Dataset freed.");
}
