#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    int userId;
    time_t sessionStart;
    time_t sessionEnd;
    double sessionDuration; // in seconds
    int sessionActivityScore;
} UserSessionData;

// Global atomic lock-free counter for thread-safe access
_Atomic size_t global_session_count = 0;

// Function to generate random duration based on normal distribution using Box-Muller transform
double generate_random_duration(double mean, double stddev, unsigned int seed) {
    srand(seed);
    double u1 = (rand() / (RAND_MAX + 1.0));
    double u2 = (rand() / (RAND_MAX + 1.0));

    // Apply Box-Muller Transform
    double z0 = sqrt(-2.0 * log(u1)) * cos(2.0 * M_PI * u2);
    return mean + z0 * stddev;
}

// Function to calculate session activity score based on threshold model
int calculate_activity_score(double duration, int threshold) {
    // Simple threshold-based scoring; can be replaced with more complex logic
    return (duration >= threshold) ? 1 : 0;
}

UserSessionData* initialize_sessions(size_t count, double mean_duration, double stddev_duration, unsigned int seed, int score_threshold) {
    UserSessionData* sessions = malloc(sizeof(UserSessionData) * count);
    if (!sessions) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        double duration = generate_random_duration(mean_duration, stddev_duration, seed + i);

