// Implementations of utility functions and structures.

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;
    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->pool = malloc(block_size * num_blocks);
    if (!pool->pool) {
        free(pool);
        return NULL;
    }
    memset(pool->pool, 0, block_size * num_blocks);
    return pool;
}

Record* allocate_record_from_pool(MemoryPool* pool) {
    if (!pool || !pool->pool) return NULL;
    void *record_memory = (char*)pool->pool + ((void**)pool->pool)[-1];
    ((void**)pool->pool)[-1] = record_memory + pool->block_size;
    return (Record*)record_memory;
}

void free_memory_pool(MemoryPool* pool) {
    if (!pool) return;
    free(pool->pool);
    free(pool);
}

ThreadSafeList* create_thread_safe_list() {
    ThreadSafeList *list = malloc(sizeof(ThreadSafeList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int add_record(ThreadSafeList* list, int value) {
    if (!list || !pthread_mutex_trylock(&list->lock)) {
        Record *new_record = allocate_record_from_pool(NULL);  // Simulate allocation.
        if (!new_record) return -1;
        new_record->value = value;
        new_record->next = list->head;
        list->head = new_record;
        pthread_mutex_unlock(&list->lock);
        return 0; // Success
    }
    return -1; // Mutex already locked, handle error or wait.
}

Record* get_head_record(ThreadSafeList* list) {
    if (!list || !pthread_mutex_lock(&list->lock)) {
        Record *record = list->head;
        pthread_mutex_unlock(&list->lock);
        return record;
    }
    return NULL; // Error handling
}

void free_thread_safe_list(ThreadSafeList* list) {
    if (!list) return;
    pthread_mutex_lock(&list->lock);
    Record *current = list->head;
    while (current) {
        Record *next = current->next;
        free(current);  // Free each record.
        current = next;
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
