```cpp
#include <iostream>
#include <vector>
#include <string>
#include <random>
#include <thread>
#include <mutex>
#include <queue>
#include <condition_variable>
#include <algorithm>
#include <sqlite3.h>  // Assuming SQLite for simplicity

// Thread-safe queue implementation using mutex and condition variable.
template<typename T>
class SafeQueue {
    std::queue<T> queue;
    mutable std::mutex m;
    std::condition_variable cv;

public:
    void push(T value) {
        std::lock_guard<std::mutex> lock(m);
        queue.push(std::move(value));
        cv.notify_one();
    }

    bool try_pop(T& value) {
        std::unique_lock<std::mutex> lock(m);
        if (queue.empty()) return false;
        value = std::move(queue.front());
        queue.pop();
        return true;
    }

    void wait_and_pop(T& value) {
        std::unique_lock<std::mutex> lock(m);
        cv.wait(lock, [this]{return !queue.empty();});
        value = std::move(queue.front());
        queue.pop();
    }
};

// Record structure
struct Record {
    int id;
    std::string key;
    // Other fields...

    Record(int id, const std::string& key) : id(id), key(key) {}
};

// Generate random records
void generateRandomRecords(SafeQueue<Record>& recordQueue, int numRecords) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(1, 1000);

    for (int i = 0; i < numRecords; ++i) {
        std::string key = "Key_" + std::to_string(dis(gen));
        recordQueue.push(Record(i, key));
    }
}

// Sorting function using stable_sort
void sortRecords(std::vector<Record>& records) {
    std::stable_sort(records.begin(), records.end(),
                     [](const Record& a, const Record& b) { return a.key < b.key; });
}

// Database interaction class
class DBInterface {
public:
    static bool init(const char* dbFile) {
        int rc = sqlite3_open(dbFile, &db);
        if (rc) {
            std::cerr << "Can't open database: " << sqlite3_errmsg(db) << "\n";
            return false;
        }
        return true;
    }

    static bool getEmployeeDetails(int supervisorId, std::string& name, std::string& city, std::string& address) {
        const char* sql = "SELECT name, city, address FROM Employees WHERE supervisor_id=?";
        sqlite3_stmt* stmt;

        if (sqlite3_prepare_v2(db, sql, -1, &stmt, NULL) != SQLITE_OK) {
            return false;
        }

        sqlite3_bind_int(stmt, 1, supervisorId);

        if (sqlite3_step(stmt) == SQLITE_ROW) {
            name = reinterpret_cast<const char*>(sqlite3_column_text(stmt, 0));
            city = reinterpret_cast<const char*>(sqlite3_column_text(stmt, 1));
            address = reinterpret_cast<const char*>(sqlite3_column_text(stmt, 2));
            sqlite3_finalize(stmt);
            return true;
        }

        sqlite3_finalize(stmt);
        return false;
    }

private:
    static sqlite3* db;
};

sqlite3* DBInterface::db = nullptr;

// Data consumer function
void processData(SafeQueue<Record>& recordQueue) {
    std::vector<Record> records;

    while (true) {
        Record rec(0, "");
        if (!recordQueue.try_pop(rec)) break;  // Exit condition

        records.push_back(std::move(rec));

        if (records.size() >= 100) {  // Batch processing
            sortRecords(records);

            for (const auto& record : records) {
                std::string name, city, address;
                if (DBInterface::getEmployeeDetails(record.id, name, city, address)) {
                    std::cout << "ID: " << record.id << ", Name: " << name << ", City: " << city << ", Address: " << address << "\n";
                }
            }

            records.clear();
        }
    }
}

int main() {
    SafeQueue<Record> recordQueue;

    if (!DBInterface::init("employees.db")) return 1;

    std::thread producer(generateRandomRecords, std::ref(recordQueue), 1000);
    std::vector<std::thread> consumers;

    for (int i = 0; i < 4; ++i) {
        consumers.emplace_back(processData, std::ref(recordQueue));
    }

    producer.join();
    for (auto& consumer : consumers) {
        if (consumer.joinable()) consumer.join();
    }

    return 0;
}
```

### Key Points:
- **Thread Safety**: Utilized `SafeQueue` to manage concurrency safely.
- **Sorting**: Used `std::stable_sort` for stable and efficient sorting of records.
- **Database Interaction**: Implemented using SQLite with parameterized queries for security against SQL injection.
- **Concurrency**: Producer-consumer model for data handling, ensuring minimal latency and optimal throughput.

This code is modular and can be extended to accommodate future requirements such as more complex sorting or additional database operations.']

