    size_t access_frequency;
    time_t last_accessed;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record *records;
    size_t capacity;
    pthread_mutex_t lock;
    size_t current_memory_usage;
} DataManager;

// Error codes
#define SUCCESS 0
#define MEMORY_OVERFLOW -1
#define KEY_VALIDATION_FAILED -2

DataManager* create_data_manager(size_t initial_capacity) {
    DataManager *dm = malloc(sizeof(DataManager));
    if (!dm) return NULL;

    pthread_mutex_init(&dm->lock, NULL);
    dm->capacity = initial_capacity;
    dm->current_memory_usage = 0;

    dm->offsets = calloc(initial_capacity, sizeof(long));
    if (!dm->offsets) { free(dm); return NULL; }
    dm->current_memory_usage += initial_capacity * sizeof(long);

    dm->keys = malloc(initial_capacity * sizeof(int));
    if (!dm->keys) { free(dm->offsets); free(dm); return NULL; }
    dm->current_memory_usage += initial_capacity * sizeof(int);

    dm->records = malloc(initial_capacity * sizeof(Record));
    if (!dm->records) { free(dm->keys); free(dm->offsets); free(dm); return NULL; }
    dm->current_memory_usage += initial_capacity * sizeof(Record);

    return dm;
}

int validate_key(int key) {
    // Simulate network latency and error handling
    int simulated_error = 0; // Replace with actual validation logic
    if (simulated_error) return KEY_VALIDATION_FAILED;
    return SUCCESS;
}

int resize_data_manager(DataManager *dm, size_t new_capacity) {
    if (new_capacity * (sizeof(long) + sizeof(int) + sizeof(Record)) > MAX_MEMORY_SIZE - dm->current_memory_usage) {
        return MEMORY_OVERFLOW;
    }

    long *new_offsets = realloc(dm->offsets, new_capacity * sizeof(long));
    int *new_keys = realloc(dm->keys, new_capacity * sizeof(int));
    Record *new_records = realloc(dm->records, new_capacity * sizeof(Record));

    if (!new_offsets || !new_keys || !new_records) {
        free(new_offsets);
        free(new_keys);
        free(new_records);
        return MEMORY_OVERFLOW;
    }

    dm->current_memory_usage += (new_capacity - dm->capacity) * (sizeof(long) + sizeof(int) + sizeof(Record));
    dm->offsets = new_offsets;
    dm->keys = new_keys;
    dm->records = new_records;
    dm->capacity = new_capacity;

    return SUCCESS;
}

int insert_record(DataManager *dm, int key, Record record) {
    pthread_mutex_lock(&dm->lock);

    if (validate_key(key) != SUCCESS) {
        pthread_mutex_unlock(&dm->lock);
        return KEY_VALIDATION_FAILED;
    }

    for (size_t i = 0; i < dm->capacity; ++i) {
        if (dm->keys[i] == key) {
            dm->records[i] = record;
            dm->records[i].access_frequency++;
            time(&(dm->records[i].last_accessed));
            pthread_mutex_unlock(&dm->lock);
            return SUCCESS;
        }
    }

    // Resize if necessary
    if (resize_data_manager(dm, dm->capacity * 2) != SUCCESS) {
        pthread_mutex_unlock(&dm->lock);
        return MEMORY_OVERFLOW;
    }

    size_t new_index = dm->capacity / 2; // New element index after resizing

    dm->keys[new_index] = key;
    dm->records[new_index] = record;
    dm->records[new_index].access_frequency = 1;
    time(&(dm->records[new_index].last_accessed));

    pthread_mutex_unlock(&dm->lock);
    return SUCCESS;
}

Record* get_record(DataManager *dm, int key) {
    pthread_mutex_lock(&dm->lock);

    for (size_t i = 0; i < dm->capacity; ++i) {
        if (dm->keys[i] == key) {
            dm->records[i].access_frequency++;
            time(&(dm->records[i].last_accessed));
            pthread_mutex_unlock(&dm->lock);
            return &dm->records[i];
        }
    }

    pthread_mutex_unlock(&dm->lock);
    return NULL;
}

void free_data_manager(DataManager *dm) {
    pthread_mutex_destroy(&dm->lock);
    free(dm->offsets);
    free(dm->keys);
    free(dm->records);
    free(dm);
}
