#include <pthread.h>
#include <string.h>
#include <stdbool.h>

// Custom Types and Constants
typedef struct MAC_FRAME_DATA {
    uint32_t type;
    uint8_t data[256]; // Adjustable size based on configuration
} MAC_FRAME_DATA;

typedef struct MAC_EVENT_TAG {
    uint64_t tag_id;
    uint64_t timestamp; // Timestamp in nanoseconds
    MAC_FRAME_DATA *frames;
    size_t frame_count;
} MAC_EVENT_TAG;

// Event structure definition
typedef struct NetworkEvent {
    MAC_EVENT_TAG event_tag;
    struct NetworkEvent* next;
} NetworkEvent;

// Memory Pool Structure
typedef struct {
    void** free_list;
    size_t block_size;
    size_t pool_size;
    pthread_mutex_t mutex;
} MemoryPool;

// Configuration parameters
static size_t max_events = 1000; // Adjustable at runtime
static size_t max_frame_size = 256;
static size_t memory_pool_size = 1024; // Number of blocks

// Global variables for managing events and memory pool
NetworkEvent* event_list_head = NULL;
MemoryPool frame_memory_pool;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void init_memory_pool(MemoryPool* pool, size_t block_size, size_t pool_size);
MAC_FRAME_DATA* allocate_frame(MemoryPool* pool);
void deallocate_frame(MemoryPool* pool, MAC_FRAME_DATA* frame);
NetworkEvent* add_event(MAC_EVENT_TAG event_tag);
bool remove_event(uint64_t tag_id);
int validate_event_data(const MAC_EVENT_TAG* event_tag);

// Initialize memory pool
void init_memory_pool(MemoryPool* pool, size_t block_size, size_t pool_size) {
    pthread_mutex_init(&pool->mutex, NULL);
    pool->free_list = (void**)malloc(pool_size * sizeof(void*));
    pool->block_size = block_size;
    pool->pool_size = pool_size;

    for (size_t i = 0; i < pool_size; ++i) {
        void* block = malloc(block_size);
        if (!block) {
            perror("Failed to allocate memory pool block");
            exit(EXIT_FAILURE);
        }
        pool->free_list[i] = block;
    }
}

// Allocate frame from memory pool
MAC_FRAME_DATA* allocate_frame(MemoryPool* pool) {
    pthread_mutex_lock(&pool->mutex);

    if (NULL == pool->free_list[0]) { // No available blocks
        pthread_mutex_unlock(&pool->mutex);
        return NULL;  // Out of memory in the pool
    }

    MAC_FRAME_DATA* frame = (MAC_FRAME_DATA*)pool->free_list[--(size_t)pool->free_list];
    pthread_mutex_unlock(&pool->mutex);

    memset(frame, 0, pool->block_size); // Clear block before use
    return frame;
}

// Deallocate frame back to memory pool
void deallocate_frame(MemoryPool* pool, MAC_FRAME_DATA* frame) {
    if (frame == NULL) return;

    pthread_mutex_lock(&pool->mutex);
    pool->free_list[(size_t)pool->free_list++] = frame; // Insert the block back into free list
    pthread_mutex_unlock(&pool->mutex);
}

// Add an event to the global event list
NetworkEvent* add_event(MAC_EVENT_TAG event_tag) {
    if (!validate_event_data(&event_tag)) return NULL;

    NetworkEvent* new_event = (NetworkEvent*)malloc(sizeof(NetworkEvent));
    if (!new_event) {
        perror("Failed to allocate memory for network event");
        return NULL;
    }

    new_event->event_tag = event_tag;
    new_event->next = NULL;

    pthread_mutex_lock(&list_mutex);
    if (NULL == event_list_head) { // Empty list
        event_list_head = new_event;
    } else {
        NetworkEvent* current = event_list_head;
        while (current->next != NULL)
            current = current->next;
        current->next = new_event;
    }
    pthread_mutex_unlock(&list_mutex);

    return new_event;
}

// Remove an event from the global event list by tag_id
bool remove_event(uint64_t tag_id) {
    if (!event_list_head) return false;

    pthread_mutex_lock(&list_mutex);
    NetworkEvent *current = event_list_head, *prev = NULL;

    while (current != NULL && current->event_tag.tag_id != tag_id) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) { // Event not found
        pthread_mutex_unlock(&list_mutex);
        return false;
    }

    if (prev == NULL) { // Remove head event
        event_list_head = current->next;
    } else {
        prev->next = current->next; 
    }

    for (size_t i = 0; i < current->event_tag.frame_count; ++i) {
        deallocate_frame(&frame_memory_pool, current->event_tag.frames[i]);
    }

    free(current);
    pthread_mutex_unlock(&list_mutex);

    return true;
}

// Validate event data
int validate_event_data(const MAC_EVENT_TAG* event_tag) {
    if (NULL == event_tag || event_tag->timestamp == 0 || event_tag->frame_count > max_events) {
        fprintf(stderr, "Invalid event data\n");
        return false;
    }

    for (size_t i = 0; i < event_tag->frame_count; ++i) {
        if (!event_tag->frames[i]) { // Frame allocation failed
            fprintf(stderr, "Event contains null frame pointer at index %zu\n", i);
            return false;
        }

        if (sizeof(MAC_FRAME_DATA) > max_frame_size) {
            fprintf(stderr, "Frame size exceeds maximum allowed\n");
            return false;
        }
    }

    return true;
}

// Main function for testing
int main() {
    // Initialize the memory pool for MAC_FRAME_DATA structures
    init_memory_pool(&frame_memory_pool, sizeof(MAC_FRAME_DATA), memory_pool_size);

    // Example usage: adding an event
    MAC_EVENT_TAG new_event_tag = {12345, 1627894567890, NULL, 0};

    MAC_FRAME_DATA* frame1 = allocate_frame(&frame_memory_pool);
    if (frame1) {
        frame1->type = 1;
        memcpy(frame1->data, "Hello", 5);

        new_event_tag.frames = malloc(sizeof(MAC_FRAME_DATA*) * 1);
        new_event_tag.frame_count = 1;
        new_event_tag.frames[0] = frame1;

        add_event(new_event_tag);
    }

    // Example usage: removing an event
    if (remove_event(12345)) {
        printf("Event removed successfully\n");
    } else {
        fprintf(stderr, "Failed to remove the event\n");
    }

    return 0;
}
```

This code provides a basic framework for managing network events using custom-defined structures and thread-safe operations. It includes memory management with a memory pool for efficient allocation and deallocation of MAC_FRAME_DATA structures. The implementation supports concurrent access from multiple threads, uses mutexes to ensure data integrity during list modifications, and validates event data before processing it.']

