    }

    private static void loadConfiguration(String configFilePath) throws IOException {
        Properties properties = new Properties();
        properties.load(Paths.get(configFilePath).toFile().newInputStream());

        int nStructures = Integer.parseInt(properties.getProperty("n"));
        int seed = Integer.parseInt(properties.getProperty("seed"));

        secureRandom.setSeed(seed);

        structuresPerSecondLimit = Integer.parseInt(properties.getProperty("structuresPerSecondLimit", "10"));
        numThreads = Integer.parseInt(properties.getProperty("numThreads", "4"));
    }

    private static void initializeEncryption() throws Exception {
        KeyGenerator keyGen = KeyGenerator.getInstance("AES");
        keyGen.init(256);
        secretKey = keyGen.generateKey();
    }

    private static NFAPI_CRC_INDICATION_PDU_T createStructure() throws InterruptedException {
        Thread.sleep(1000 / structuresPerSecondLimit);

        String rnti = generateRandomRNTI();
        if (isDuplicateRNTI(rnti)) {
            throw new RuntimeException("Duplicate RNTI detected: " + rnti);
        }

        boolean crcFlag = secureRandom.nextBoolean();

        NFAPI_CRC_INDICATION_PDU_T structure = new NFAPI_CRC_INDICATION_PDU_T();
        structure.setRXUEINFORMATIONTAG(generateRandomTXUEINFO());
        structure.setRNTI(rnti);
        CRC_INDICATION_REL8_TAG crcTag = new CRC_INDICATION_REL8_TAG(crcFlag);

        if (!verifyCRCIntegrity(crcTag)) {
            throw new RuntimeException("CRC Integrity Check Failed for RNTI: " + rnti);
        }

        structure.setCRCINDICATIONREL8TAG(crcTag);
        return structure;
    }

    private static boolean isDuplicateRNTI(String rnti) {
        return structureList.stream().anyMatch(s -> s.getRNTI().equals(rnti));
    }

    private static String generateRandomTXUEINFO() {
        // Implementation of random TX UE Info generation
        return UUID.randomUUID().toString();
    }

    private static String generateRandomRNTI() {
        return Integer.toHexString(secureRandom.nextInt(Integer.MAX_VALUE));
    }

    private static boolean verifyCRCIntegrity(CRC_INDICATION_REL8_TAG crcTag) {
        // Implement integrity verification logic for CRC tag
        return true;
    }

    private static void logCreation(NFAPI_CRC_INDICATION_PDU_T structure) {
        logger.info("Created Structure: RNTI=" + structure.getRNTI() + ", CRCFLAG=" + structure.getCRCINDICATIONREL8TAG().getCRCFLAG());
    }

    private static void exportToFile(String filename) throws IOException, InterruptedException {
        Path path = Paths.get(filename);
        if (Files.exists(path)) Files.deleteIfExists(path);

        // Use multiple threads for parallel write operations
        ExecutorService fileWriterExecutor = Executors.newFixedThreadPool(numThreads);

        try (DataOutputStream dos = new DataOutputStream(new BufferedOutputStream(Files.newOutputStream(path)))) {
            structureList.forEach(structure -> {
                fileWriterExecutor.submit(() -> {
                    try {
                        compressedAndEncryptedWrite(dos, structure);
                    } catch (IOException e) {
                        logger.severe("Failed to write structure: " + e.getMessage());
                    }
                });
            });

            fileWriterExecutor.shutdown();
            fileWriterExecutor.awaitTermination(1, TimeUnit.MINUTES);
        }

        executeCommand("echo Export Complete", null, path.getParentFile());

        // Clear list after export
        synchronized (structureList) {
            structureList.clear();
        }
    }

    private static void compressedAndEncryptedWrite(DataOutputStream dos, NFAPI_CRC_INDICATION_PDU_T structure)
            throws IOException {
        byte[] serializedData = serializeStructure(structure);
        byte[] compressedData = compressData(serializedData);
        byte[] encryptedData = encryptData(compressedData);

        dos.writeInt(encryptedData.length);
        dos.write(encryptedData);
    }

    private static byte[] compressData(byte[] data) {
        // Implement custom compression algorithm
        return data;
    }

    private static byte[] encryptData(byte[] data) throws Exception {
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        IvParameterSpec iv = new IvParameterSpec(new byte[16]);
        cipher.init(Cipher.ENCRYPT_MODE, secretKey, iv);

        return cipher.doFinal(data);
    }

    private static byte[] serializeStructure(NFAPI_CRC_INDICATION_PDU_T structure) {
        // Serialize the structure into a byte array
        return new byte[0];
    }

    private static void executeCommand(String command, String workingDirPath, File workDir) throws IOException, InterruptedException {
        Path path = Paths.get(workingDirPath == null ? "." : workingDirPath);

        ProcessBuilder processBuilder = new ProcessBuilder(command.split(" "));
        processBuilder.directory(workDir);

        Process process = processBuilder.start();
        logProcessOutput(process.getInputStream(), "OUTPUT");
        logProcessOutput(process.getErrorStream(), "ERROR");

        int exitCode = process.waitFor();
        if (exitCode != 0) {
            throw new RuntimeException("Command execution failed with code: " + exitCode);
        }
    }

    private static void logProcessOutput(InputStream inputStream, String streamType) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))) {
            String line;
            while ((line = reader.readLine()) != null) {
                logger.info(streamType + ": " + line);
            }
        }
    }
}

