#define TABLE_SIZE 256

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG; // Randomly set
    int session_activity_score;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct HashNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct HashNode* next;
} HashNode;

typedef struct {
    HashNode** buckets;
    pthread_mutex_t lock;
} ConcurrentHashTable;

// Function to create a new hash table
ConcurrentHashTable* create_hash_table() {
    ConcurrentHashTable* table = malloc(sizeof(ConcurrentHashTable));
    if (!table) return NULL;
    table->buckets = calloc(TABLE_SIZE, sizeof(HashNode*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

// Hash function
unsigned int hash_function(uint32_t tag, uint16_t rnti) {
    return (tag ^ rnti) % TABLE_SIZE;
}

// Function to insert a node into the hash table
void insert_node(ConcurrentHashTable* table, NFAPI_CRC_INDICATION_PDU_T pdu) {
    unsigned int index = hash_function(pdu.RX_UE_INFORMATION_TAG, pdu.RNTI);
    HashNode* new_node = malloc(sizeof(HashNode));
    if (!new_node) return;

    memcpy(&new_node->data, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = NULL;

    pthread_mutex_lock(&table->lock);

    HashNode* head = table->buckets[index];
    if (head == NULL) {
        table->buckets[index] = new_node;
    } else {
        while (head->next != NULL) {
            head = head->next;
        }
        head->next = new_node;
    }

    pthread_mutex_unlock(&table->lock);
}

// Function to retrieve a node from the hash table
NFAPI_CRC_INDICATION_PDU_T* get_node(ConcurrentHashTable* table, uint32_t tag, uint16_t rnti) {
    unsigned int index = hash_function(tag, rnti);

    pthread_mutex_lock(&table->lock);
    HashNode* head = table->buckets[index];
    while (head != NULL) {
        if (head->data.RX_UE_INFORMATION_TAG == tag && head->data.RNTI == rnti) {
            pthread_mutex_unlock(&table->lock);
            return &head->data;
        }
        head = head->next;
    }
    pthread_mutex_unlock(&table->lock);

    return NULL;
}

// Function to delete a node from the hash table
void delete_node(ConcurrentHashTable* table, uint32_t tag, uint16_t rnti) {
    unsigned int index = hash_function(tag, rnti);

    pthread_mutex_lock(&table->lock);
    HashNode *head = table->buckets[index], *prev = NULL;
    while (head != NULL) {
        if (head->data.RX_UE_INFORMATION_TAG == tag && head->data.RNTI == rnti) {
            if (prev == NULL) {
                table->buckets[index] = head->next;
            } else {
                prev->next = head->next;
            }
            free(head);
            pthread_mutex_unlock(&table->lock);
            return;
        }
        prev = head;
        head = head->next;
    }
    pthread_mutex_unlock(&table->lock);
}

// Function to initialize a PDU with random CRCFLAG and session activity score
void init_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu) return;
    pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    pdu->session_activity_score = 0; // Initialize session activity score
}

// OAuth 2.0 Authentication and User Information Retrieval
void authenticate_and_retrieve_user_info(OAuth2Client* client, const char* token_url, const char* user_info_url) {
    char* access_token = oauth2_client_authenticate(client, token_url);
    if (access_token) {
        printf("Access Token: %s\n", access_token);

        // Store the access token in session variable
        set_session_variable("oauth_access_token", access_token);

        // Retrieve user information using the access token
        char* user_info = oauth2_client_get_user_info(client, user_info_url, access_token);
        if (user_info) {
            printf("User Info: %s\n", user_info);
            free(user_info);
        }

        free(access_token);
    }
}

// Example usage
int main() {
    srand(time(NULL)); // Seed random number generator

    ConcurrentHashTable* table = create_hash_table();
    if (!table) {
        fprintf(stderr, "Failed to create hash table\n");
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu;
    init_pdu(&pdu);
    pdu.RX_UE_INFORMATION_TAG = 12345; // Example values
    pdu.RNTI = 6789;

    insert_node(table, pdu);

    NFAPI_CRC_INDICATION_PDU_T* retrieved_pdu = get_node(table, 12345, 6789);
    if (retrieved_pdu) {
        printf("Retrieved PDU: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRCFLAG=%d\n",
               retrieved_pdu->RX_UE_INFORMATION_TAG,
               retrieved_pdu->RNTI,
               retrieved_pdu->CRCFLAG);
    }

    delete_node(table, 12345, 6789);

    // OAuth 2.0 Authentication
    OAuth2Client* client = oauth2_client_create();
    authenticate_and_retrieve_user_info(client, "https://example.com/token", "https://example.com/userinfo");

    free_hash_table(table);
    return 0;
}

// Function to free the hash table
void free_hash_table(ConcurrentHashTable* table) {
    if (!table) return;

    for (int i = 0; i < TABLE_SIZE; ++i) {
        HashNode* head = table->buckets[i];
        while (head != NULL) {
            HashNode* temp = head;
            head = head->next;
            free(temp);
        }
    }

    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}
