```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef enum { SUCCESS, FAILURE } Status;

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

Status allocate_and_initialize(long maxAddressSpaceSize, long maxHeapMemory, 
                               int numOffsets, int minKey, int maxKey,
                               int numRecords, int minVal, int maxVal,
                               long **offsets, int **keys, record ***records) {
    pthread_mutex_lock(&mutex);

    if (maxAddressSpaceSize < sizeof(long) * numOffsets + sizeof(int) * numKeysNeeded(minKey, maxKey) + sizeof(record) * numRecords) {
        pthread_mutex_unlock(&mutex);
        return FAILURE;
    }

    // Allocate memory for offsets
    *offsets = (long *)malloc(sizeof(long) * numOffsets);
    if (*offsets == NULL) {
        pthread_mutex_unlock(&mutex);
        return FAILURE;
    }

    // Initialize offset array
    for (int i = 0; i < numOffsets && i < maxHeapMemory / sizeof(long); ++i) {
        (*offsets)[i] = i;
    }

    // Allocate memory for keys and populate with unique values
    int keyRange = maxKey - minKey + 1;
    *keys = (int *)malloc(sizeof(int) * numKeysNeeded(minKey, maxKey));
    if (*keys == NULL) {
        free(*offsets);
        pthread_mutex_unlock(&mutex);
        return FAILURE;
    }

    populateUniqueKeys(*keys, keyRange, minKey);

    // Allocate memory for records
    *records = (record **)malloc(sizeof(record *) * numRecords);
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        pthread_mutex_unlock(&mutex);
        return FAILURE;
    }

    // Populate record array with random values
    srand(time(NULL));
    int allocatedKeys[keyRange];
    memset(allocatedKeys, 0, sizeof(int) * keyRange);

    for (int i = 0; i < numRecords; ++i) {
        (*records)[i] = malloc(sizeof(record));
        if ((*records)[i] == NULL) {
            // Free all in case of failure
            for (int j = 0; j < i; ++j) {
                free((*records)[j]);
            }
            free(*offsets);
            free(*keys);
            free(*records);
            pthread_mutex_unlock(&mutex);
            return FAILURE;
        }

        int key, value;
        do {
            key = minKey + rand() % keyRange;
        } while (allocatedKeys[key - minKey]);

        allocatedKeys[key - minKey] = 1;

        do {
            value = minVal + rand() % (maxVal - minVal + 1);
        } while (!isValidValue(value, minVal, maxVal));

        (*records)[i]->value = value;
    }

    pthread_mutex_unlock(&mutex);
    return SUCCESS;
}

int numKeysNeeded(int minKey, int maxKey) {
    // Estimate the number of unique keys needed
    return (maxKey - minKey + 1);
}

