    return value >= minVal && value <= maxVal;
}

void free_resources(long *offsets, int *keys, record **records, int numRecords) {
    pthread_mutex_lock(&mutex);

    if (offsets != NULL) {
        free(offsets);
    }
    if (keys != NULL) {
        free(keys);
    }
    for (int i = 0; i < numRecords; ++i) {
        if (records[i] != NULL) {
            free(records[i]);
        }
    }
    if (records != NULL) {
        free(records);
    }

    pthread_mutex_unlock(&mutex);
}

// Example usage
