Node* hashTable[HASH_TABLE_SIZE];

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

unsigned int hashFunction(int rnti) {
    return rnti % HASH_TABLE_SIZE;
}

void initHashTable() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hashTable[i] = NULL;
    }
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;

    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void insertOrUpdate(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&lock);

    unsigned int index = hashFunction(data.RNTI);
    Node* current = hashTable[index];

    while (current) {
        if (current->data.RNTI == data.RNTI) {
            // Update existing node
            current->data.CRC_INDICATION_REL8_TAG.CRCFLAG ^= 1;  // Flip CRCFLAG for demonstration
            pthread_mutex_unlock(&lock);
            return;
        }
        current = current->next;
    }

    Node* newNode = createNode(data);
    if (newNode) {
        newNode->next = hashTable[index];
        hashTable[index] = newNode;
    }

    pthread_mutex_unlock(&lock);
}

NFAPI_CRC_INDICATION_PDU_T* retrieve(int rnti) {
    pthread_mutex_lock(&lock);

    unsigned int index = hashFunction(rnti);
    Node* current = hashTable[index];

    while (current) {
        if (current->data.RNTI == rnti) {
            NFAPI_CRC_INDICATION_PDU_T* dataCopy = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            *dataCopy = current->data;
            pthread_mutex_unlock(&lock);
            return dataCopy;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
    return NULL;  // Not found
}

void deleteNode(int rnti) {
    pthread_mutex_lock(&lock);

    unsigned int index = hashFunction(rnti);
    Node* current = hashTable[index];
    Node* prev = NULL;

    while (current) {
        if (current->data.RNTI == rnti) {
            if (prev)
                prev->next = current->next;
            else
                hashTable[index] = current->next;

            free(current);
            pthread_mutex_unlock(&lock);
            return;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

