    size_t new_memory_size = calculate_memory_size(new_size);
    if (new_memory_size > MAX_MEMORY_SIZE)
        handle_error("Exceeded maximum memory size limit");

    long* new_offsets = realloc(manager->offsets, new_memory_size * sizeof(long));
