void* get_record(hash_table *ht, int key) {
    pthread_mutex_lock(&ht->lock);
    record *rec = ht->records[key % (sizeof(ht->keys) / sizeof(ht->keys[0]))];
    if (rec) {
        rec->access_frequency++;
        rec->last_accessed = time(NULL);
        rec->ref_count++;
    }
    pthread_mutex_unlock(&ht->lock);
    return rec;
}

void set_record(hash_table *ht, int key, record *rec) {
    pthread_mutex_lock(&ht->lock);
    ht->keys[key % (sizeof(ht->keys) / sizeof(ht->keys[0]))] = key;
    ht->records[key % (sizeof(ht->keys) / sizeof(ht->keys[0]))] = rec;
    pthread_mutex_unlock(&ht->lock);
}

void initialize_data_structures(int num_records, int value_range_min, int value_range_max) {
    long total_memory_used = 0;

    // Arrays
    size_t array_size = num_records * sizeof(long);
    long *offsets = malloc(array_size);
    if (!offsets) exit(EXIT_FAILURE);
    total_memory_used += array_size;

    array_size = num_records * sizeof(int);
    int *keys = malloc(array_size);
    if (!keys) { free(offsets); exit(EXIT_FAILURE); }
    total_memory_used += array_size;

    // Hash table
    hash_table *ht = create_hash_table(num_records);
    total_memory_used += sizeof(hash_table);

    for (int i = 0; i < num_records; ++i) {
        if (total_memory_used > memory_limit) {
            fprintf(stderr, "Memory limit exceeded!\n");
            free(offsets); free(keys);
            free_hash_table(ht);
            exit(EXIT_FAILURE);
        }

        // Random record
        int value = rand() % (value_range_max - value_range_min + 1) + value_range_min;
        record *rec = malloc(sizeof(record));
        if (!rec) { 
            free(offsets); free(keys); 
            free_hash_table(ht);
            exit(EXIT_FAILURE); 
        }
        rec->value = value;
        rec->access_frequency = 0;
        rec->last_accessed = time(NULL);
        rec->ref_count = 1;

        // Set in hash table
        set_record(ht, keys[i], rec);

        total_memory_used += sizeof(record);
    }

    free(offsets); // Assuming offsets are no longer needed after initialization

    printf("Data structures initialized successfully.\n");
}

void adjust_memory_limit(long new_limit) {
    pthread_mutex_t lock;
    pthread_mutex_lock(&lock);
    memory_limit = new_limit;
    pthread_mutex_unlock(&lock);
}

int main() {
    srand(time(NULL));

    // Configuration through environment variables
    char *env_value = getenv("MAX_MEMORY_LIMIT");
    if (env_value) {
        long limit = atol(env_value);
        adjust_memory_limit(limit);
    }

    initialize_data_structures(1000, 1, 100);

    return 0;
}
```

### Key Points:
- **Memory Management**: The function dynamically allocates memory for arrays and a hash table. It checks if the total allocated memory exceeds a specified limit.
- **Concurrency**: Uses mutex locks to ensure thread safety during concurrent access.
- **Configuration**: Allows adjusting the maximum memory limit via environment variables.
- **Logging**: Simple logging is implemented using `printf` for demonstration purposes.

This code provides a basic framework and can be extended with more sophisticated error handling, dynamic resizing, and additional features as needed.']

