#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <stdatomic.h>

#define MAX_RETRIES 5
#define CACHE_SIZE 1024
#define RANDOM_FLOAT_RANGE (1.0, 100.0)

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
    float someFloatValue;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    unsigned long RNTI;
    char metadata[256];
} MetadataCacheEntry;

static MetadataCacheEntry cache[CACHE_SIZE];
static pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

unsigned long hash_function(size_t index, time_t system_time, const char* metadata) {
    return ((index * 2654435761u) ^ (system_time % 1000000)) + (metadata ? strlen(metadata) : 0);
}

void* fetch_metadata(unsigned long rnti, char* buffer, size_t buffer_size) {
    // Simulate fetching metadata with variable latency
    usleep(rand() % 10000); // Random delay between 0 and 10ms
    snprintf(buffer, buffer_size, "Metadata for RNTI: %lu", rnti);
    return buffer;
}

void* allocate_and_initialize_structures(size_t num_structs) {
    NFAPI_CRC_INDICATION_PDU_T* structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_structs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structures) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < num_structs; ++i) {
        structures[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        structures[i].RNTI = rand() % 1000000;

        // Fetch metadata with caching
        pthread_mutex_lock(&cache_lock);
        MetadataCacheEntry* entry = NULL;
        for (int j = 0; j < CACHE_SIZE; ++j) {
            if (cache[j].RNTI == structures[i].RNTI) {
                entry = &cache[j];
                break;
            }
        }

        char metadata[256] = {0};
        if (!entry) {
            entry = &cache[rand() % CACHE_SIZE];
            fetch_metadata(structures[i].RNTI, entry->metadata, sizeof(entry->metadata));
            entry->RNTI = structures[i].RNTI;
        }
        pthread_mutex_unlock(&cache_lock);

        // Set CRCFLAG randomly
        structures[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        // Generate a unique key with retries
        atomic_int retry_count = 0;
        unsigned long key;
        do {
            time_t system_time = time(NULL);
            key = hash_function(i, system_time, entry->metadata);

            for (size_t j = 0; j < i; ++j) {
                if (structures[j].RNTI == structures[i].RNTI && hash_function(j, system_time, cache[(entry - cache + CACHE_SIZE) % CACHE_SIZE]->metadata) == key) {
                    retry_count++;
                    break;
                }
            }

            if (retry_count >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached for unique key generation\n");
                free(structures);
                return NULL;
            }
        } while (retry_count > 0);

        // Log the generated key
        printf("Generated key: %lu for RNTI: %lu\n", key, structures[i].RNTI);

        // Set a random float value within range
        structures[i].someFloatValue = RANDOM_FLOAT_RANGE[0] + (float)rand() / RAND_MAX * (RANDOM_FLOAT_RANGE[1] - RANDOM_FLOAT_RANGE[0]);
    }

    size_t total_size_in_bytes = num_structs * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    return (void*)structures;
}

void free_allocated_memory(void* ptr) {
    if (ptr) {
        free(ptr);
    }
}

int main() {
    size_t num_structs = 100;
    NFAPI_CRC_INDICATION_PDU_T* structures = (NFAPI_CRC_INDICATION_PDU_T*)allocate_and_initialize_structures(num_structs);

    if (structures) {
        size_t total_size_in_bytes = num_structs * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        printf("Allocated %zu structures, total size: %zu bytes\n", num_structs, total_size_in_bytes);

        free_allocated_memory(structures);
    }

    return 0;
}
```

### Key Points:
- **Memory Allocation**: Uses `malloc` for dynamic memory allocation.
- **Metadata Caching**: Implements a simple cache to store metadata fetched from an external source.
- **Concurrency**: Utilizes mutex locks to ensure thread-safe access to the cache.
- **Key Generation**: Generates unique keys using a hashing function and retries on collision.
- **Random Number Generation**: Sets random float values within a specified range.
- **Logging**: Logs key generation for debugging purposes.
- **Memory Deallocation**: Provides a function to free allocated memory.

This implementation is designed to be efficient, scalable, and robust under varying loads.']

