// Struct Definitions
typedef struct {
    long id;
    char *name;
    time_t timestamp;
} item;

typedef struct BSTNode {
    void *data; // Generic pointer for different data types
    int dataType; // 1: int, 2: double, 3: item*, 4: void*
    struct BSTNode *left, *right;
} BSTNode;

// Function Prototypes
int fetchDataFromURL(const char* url);
void freeBST(BSTNode *root);

// Dynamic Memory Allocation and Initialization Functions
int initArrays(int **intArray, size_t intSize, 
               double **doubleArray, size_t doubleSize,
               item ***itemPointers, size_t itemCount,
               void ***voidPointers, size_t voidCount) {
    // Allocate memory for arrays
    *intArray = malloc(intSize * sizeof(int));
    if (!*intArray) return -1;

    *doubleArray = malloc(doubleSize * sizeof(double));
    if (!*doubleArray) { free(*intArray); return -1; }

    *itemPointers = malloc(itemCount * sizeof(item *));
    if (!*itemPointers) { free(*intArray); free(*doubleArray); return -1; }

    *voidPointers = malloc(voidCount * sizeof(void *));
    if (!*voidPointers) {
        for (size_t i = 0; i < itemCount; ++i) 
            free((*itemPointers)[i]);
        free(*intArray);
        free(*doubleArray);
        free(*itemPointers);
        return -1;
    }

    // Initialize arrays
    for (size_t i = 0; i < intSize; i++) (*intArray)[i] = 0;
    for (size_t i = 0; i < doubleSize; i++) (*doubleArray)[i] = 0.0;
    for (size_t i = 0; i < itemCount; i++) {
        (*itemPointers)[i] = malloc(sizeof(item));
        if (!(*itemPointers)[i]) { // Handle allocation failure
            freeBST(NULL); // Free other resources
            return -1;
        }
        (*itemPointers)[i]->id = 0;
        (*itemPointers)[i]->name = strdup("");
        (*itemPointers)[i]->timestamp = time(NULL);
    }

    for (size_t i = 0; i < voidCount; i++) 
        (*voidPointers)[i] = NULL;

    return 0;
}

// Binary Search Tree Operations
BSTNode* createBSTNode(void *data, int dataType) {
    BSTNode *node = malloc(sizeof(BSTNode));
    if (!node) return NULL;
    node->data = data;
    node->dataType = dataType;
    node->left = node->right = NULL;
    return node;
}

// Insertion into BST (for simplicity, a simple insert without balancing)
BSTNode* insertBST(BSTNode *root, void *data, int dataType) {
    if (!root) return createBSTNode(data, dataType);
    if (dataType < root->dataType) 
        root->left = insertBST(root->left, data, dataType);
    else if (dataType > root->dataType)
        root->right = insertBST(root->right, data, dataType);
    // Assume equal type numbers are unique
    return root;
}

// Free BST Nodes Recursively
void freeBST(BSTNode *root) {
    if (!root) return;
    freeBST(root->left);
    freeBST(root->right);
    free(root->data);  // Custom freeing logic depending on dataType
    free(root);
}

// Network Request Function using libcurl
int fetchDataFromURL(const char* url) {
    CURL *curl = curl_easy_init();
    if (!curl) return -1;

    CURLcode res;
    struct curl_slist *headers = NULL;  // Add headers if needed

    // Set URL and options
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);  // Custom write callback

    // Perform the request
    res = curl_easy_perform(curl);

    // Check for errors
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        return -1;
    }

    // Cleanup
    curl_slist_free_all(headers);  // Free headers list
    curl_easy_cleanup(curl);

    return 0;
}

// Callback function for libcurl's write operation
size_t write_callback(void *ptr, size_t size, size_t nmemb, void *stream) {
    // Append data to stream (e.g., a file or buffer)
    fwrite(ptr, size, nmemb, (FILE*)stream);
    return size * nmemb;
}

// Main Function
int main(int argc, char **argv) {
    int *intArray = NULL;
    double *doubleArray = NULL;
    item **itemPointers = NULL;
    void **voidPointers = NULL;

    if (initArrays(&intArray, 10, &doubleArray, 5, &itemPointers, 3, &voidPointers, 2) != 0) {
        fprintf(stderr, "Error initializing arrays\n");
        return -1;
    }

    // Example use of BST
    BSTNode *bstRoot = NULL;
    bstRoot = insertBST(bstRoot, intArray, 1);

    if (fetchDataFromURL("http://example.com/data.json") != 0) {
        fprintf(stderr, "Error fetching data from URL\n");
    }

    // Free resources
    free(intArray);
    free(doubleArray);
    for (size_t i = 0; i < 3; ++i)
        free(itemPointers[i]);
    free(itemPointers);
    free(voidPointers);
    freeBST(bstRoot);

    return 0;
}
