```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define MAX_THREADS 100
#define MIN_AMOUNT 1.0
#define MAX_AMOUNT 10000000.0
#define SYSTEM_MEMORY_LIMIT 1024 * 1024 * 512 // Example limit: 512 MB

typedef struct {
    time_t timestamp;
    char transaction_id[32];
    double amount;
    char status[16];
} Transaction;

typedef struct {
    Transaction **transactions;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
    FILE *log_file;
} TransactionCollection;

TransactionCollection* create_collection(size_t initial_capacity, const char* log_filename) {
    TransactionCollection *collection = malloc(sizeof(TransactionCollection));
    collection->transactions = calloc(initial_capacity, sizeof(Transaction *));
    collection->count = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->mutex, NULL);
    collection->log_file = fopen(log_filename, "a");
    return collection;
}

void log_message(TransactionCollection *collection, const char *message) {
    if (collection->log_file) {
        fprintf(collection->log_file, "%s\n", message);
        fflush(collection->log_file);
    }
}

int validate_transaction(double amount) {
    return amount >= MIN_AMOUNT && amount <= MAX_AMOUNT;
}

void add_transaction(TransactionCollection *collection, Transaction *transaction) {
    pthread_mutex_lock(&collection->mutex);

    if (collection->count == collection->capacity || 
        sizeof(Transaction *) * collection->capacity + sizeof(Transaction) > SYSTEM_MEMORY_LIMIT) {
        log_message(collection, "Memory limit reached. Cannot insert transaction.");
        pthread_mutex_unlock(&collection->mutex);
        return;
    }

    if (!validate_transaction(transaction->amount)) {
        char msg[256];
        snprintf(msg, sizeof(msg), "Invalid transaction amount: %.2f for ID %s", 
                 transaction->amount, transaction->transaction_id);
        log_message(collection, msg);
        pthread_mutex_unlock(&collection->mutex);
        return;
    }

    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Transaction **new_transactions = realloc(collection->transactions, 
                                                 new_capacity * sizeof(Transaction *));
        if (!new_transactions) {
            log_message(collection, "Failed to allocate memory for transactions.");
            pthread_mutex_unlock(&collection->mutex);
            return;
        }
        collection->transactions = new_transactions;
        collection->capacity = new_capacity;
    }

    collection->transactions[collection->count++] = transaction;
    pthread_mutex_unlock(&collection->mutex);
}

Transaction* find_transaction(TransactionCollection *collection, const char *transaction_id) {
    pthread_mutex_lock(&collection->mutex);

    for (size_t i = 0; i < collection->count; ++i) {
        if (strcmp(collection->transactions[i]->transaction_id, transaction_id) == 0) {
            Transaction *found = collection->transactions[i];
            pthread_mutex_unlock(&collection->mutex);
            return found;
        }
    }

    log_message(collection, "Transaction not found.");
    pthread_mutex_unlock(&collection->mutex);
    return NULL;
}

void free_collection(TransactionCollection *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->transactions[i]);
    }
    free(collection->transactions);
    fclose(collection->log_file);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

void handle_signal(int signal) {
    // Implement graceful shutdown logic here
    printf("Signal %d received. Shutting down gracefully.\n", signal);
    exit(0);
}

int main() {
    TransactionCollection *collection = create_collection(10, "transaction_log.txt");

    signal(SIGINT, handle_signal);

    // Example usage
    Transaction *tx1 = malloc(sizeof(Transaction));
    strcpy(tx1->transaction_id, "TX10001");
    tx1->timestamp = time(NULL);
    tx1->amount = 5000.0;
    strcpy(tx1->status, "PENDING");

    add_transaction(collection, tx1);

    Transaction *found_tx = find_transaction(collection, "TX10001");
    if (found_tx) {
        printf("Transaction found: %s\n", found_tx->transaction_id);
    }

    free_collection(collection);
    return 0;
}
```

### Key Features:

