#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>

#define MAX_ALLOWED_TRANSPORT_CONTEXTS 1000

typedef struct {
    int TRANSPORT_FORMAT;
} DATA_INDICATION;

typedef struct {
    int SEQUENCE_NUMBER;
    int TRANSPORT_CONTEXT;
    DATA_INDICATION tag;
} NFMMAC_PDU;

static size_t total_unique_sequence_numbers = 0;
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_error(const char *message) {
    FILE *log_file = fopen("error_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

bool is_unique_sequence_number(int seq_num, NFMMAC_PDU *array, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (array[i].SEQUENCE_NUMBER == seq_num) {
            return false;
        }
    }
    return true;
}

bool is_unique_transport_context(int context, NFMMAC_PDU *array, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (array[i].TRANSPORT_CONTEXT == context) {
            return false;
        }
    }
    return true;
}

void initialize_array(NFMMAC_PDU **array, size_t *capacity) {
    *capacity = MAX_ALLOWED_TRANSPORT_CONTEXTS;
    *array = malloc(*capacity * sizeof(NFMMAC_PDU));
    if (*array == NULL) {
        log_error("Memory allocation failed for NFMMAC_PDU array.");
        exit(EXIT_FAILURE);
    }
}

void resize_array(NFMMAC_PDU **array, size_t *current_size, size_t new_capacity) {
    *array = realloc(*array, new_capacity * sizeof(NFMMAC_PDU));
    if (*array == NULL) {
        log_error("Memory allocation failed during array resizing.");
        exit(EXIT_FAILURE);
    }
}

NFMMAC_PDU* manage_array(size_t M, unsigned int seed) {
    static NFMMAC_PDU *array = NULL;
    static size_t capacity = 0;
    static size_t current_size = 0;

    pthread_mutex_lock(&lock);

    if (M > MAX_ALLOWED_TRANSPORT_CONTEXTS) {
        log_error("Requested elements exceed maximum allowed limit.");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    if (array == NULL) {
        initialize_array(&array, &capacity);
    }

    if (current_size + M > capacity) {
        size_t new_capacity = current_size + M;
        resize_array(&array, &current_size, new_capacity);
        capacity = new_capacity;
    }

    srand(seed);

    for (size_t i = 0; i < M; ++i) {
        int seq_num, context;
        do {
            seq_num = rand() % 10000; // Example range
        } while (!is_unique_sequence_number(seq_num, array, current_size));

        do {
            context = rand() % MAX_ALLOWED_TRANSPORT_CONTEXTS;
        } while (!is_unique_transport_context(context, array, current_size));

        array[current_size].SEQUENCE_NUMBER = seq_num;
        array[current_size].TRANSPORT_CONTEXT = context;
        array[current_size].tag.TRANSPORT_FORMAT = rand() % 3; // Example formats

        total_unique_sequence_numbers++;
        current_size++;
    }

    pthread_mutex_unlock(&lock);
    return array;
}

size_t get_total_unique_sequence_numbers() {
    pthread_mutex_lock(&lock);
    size_t count = total_unique_sequence_numbers;
    pthread_mutex_unlock(&lock);
    return count;
}

void cleanup_array(NFMMAC_PDU **array, size_t *current_size) {
    if (*array != NULL) {
        free(*array);
        *array = NULL;
        *current_size = 0;
    }
}
