```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct Offset {
    long value;
    struct Offset* next;
} Offset;

typedef struct Record {
    int primary_key;
    double weight;
    double metadata;
    double timestamp;
    Offset* offsets_head;
    int secondary_key;
    int tertiary_key;
} Record;

typedef struct Cache {
    Record** records;
    size_t capacity;
    pthread_mutex_t lock;
} Cache;

#define ERROR_CODE -1

pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

// Utility function to generate random long values
long generate_random_long() {
    return rand() % 1000000; // Adjust range as needed
}

// Function to log messages
void log_message(const char* message) {
    printf("%s\n", message);
}

// Function to initialize and allocate memory for records
int initialize_records(size_t num_records, int primary_range, double weight_range, 
                       double metadata_range, double start_time, double interval,
                       Cache* cache) {

    if (num_records == 0 || !cache->records || cache->capacity < num_records) {
        log_message("Invalid input parameters.");
        return ERROR_CODE;
    }

    pthread_mutex_lock(&global_lock);
    srand(time(NULL));

    for (size_t i = 0; i < num_records; ++i) {
        Record* record = &cache->records[i];

        // Initialize fields
        record->primary_key = rand() % primary_range;
        record->weight = weight_range * ((double)rand() / RAND_MAX);
        record->metadata = metadata_range * ((double)rand() / RAND_MAX);
        record->timestamp = start_time + (i * interval);

        // Allocate memory for offsets
        Offset* head = NULL;
        Offset** current = &head;

        size_t num_offsets = rand() % 10; // Example: up to 10 offsets per record
        for (size_t j = 0; j < num_offsets; ++j) {
            Offset* new_offset = malloc(sizeof(Offset));
            if (!new_offset) {
                log_message("Memory allocation failed for offset.");
                pthread_mutex_unlock(&global_lock);
                return ERROR_CODE;
            }
            new_offset->value = generate_random_long();
            new_offset->next = NULL;
            *current = new_offset;
            current = &new_offset->next;
        }

        record->offsets_head = head;

        // Secondary and tertiary keys for cross-referencing
        record->secondary_key = rand() % 1000; // Example range
        record->tertiary_key = rand() % 1000; // Example range

        log_message("Record initialized successfully.");
    }

    pthread_mutex_unlock(&global_lock);

    // Sort records based on primary, secondary, and tertiary keys
    qsort(cache->records, num_records, sizeof(Record*), [](const void *a, const void *b) {
        Record** record_a = (Record**)a;
        Record** record_b = (Record**)b;

        if ((*record_a)->primary_key != (*record_b)->primary_key)
            return (*record_a)->primary_key - (*record_b)->primary_key;

        if ((*record_a)->secondary_key != (*record_b)->secondary_key)
            return (*record_a)->secondary_key - (*record_b)->secondary_key;

        return (*record_a)->tertiary_key - (*record_b)->tertiary_key;
    });

    return 0; // Success
}

// Function to clear and reinitialize records
void clear_and_reinit_records(Cache* cache, size_t num_records) {
    pthread_mutex_lock(&global_lock);
    for (size_t i = 0; i < num_records; ++i) {
        Record* record = &cache->records[i];
        Offset* current_offset = record->offsets_head;

        while (current_offset) {
            Offset* next_offset = current_offset->next;
            free(current_offset);
            current_offset = next_offset;
        }
    }

    initialize_records(num_records, 1000, 10.0, 1.0, 0.0, 1.0, cache);
    pthread_mutex_unlock(&global_lock);
}

// Function to release all allocated memory
void free_resources(Cache* cache, size_t num_records) {
    pthread_mutex_lock(&global_lock);
    for (size_t i = 0; i < num_records; ++i) {
        Record* record = &cache->records[i];

        Offset* current_offset = record->offsets_head;
        while (current_offset) {
            Offset* next_offset = current_offset->next;
            free(current_offset);
            current_offset = next_offset;
        }
    }

    if (cache->records)
        free(cache->records);

    pthread_mutex_unlock(&global_lock);
}

int main() {
    size_t num_records = 100; // Example number of records
    Cache cache;

    cache.records = malloc(num_records * sizeof(Record*));
    if (!cache.records) {
        log_message("Memory allocation failed for cache.");
        return ERROR_CODE;
    }
    cache.capacity = num_records;

    pthread_mutex_init(&cache.lock, NULL);

    int result = initialize_records(num_records, 1000, 10.0, 1.0, 0.0, 1.0, &cache);
    if (result == ERROR_CODE) {
        log_message("Initialization failed.");
        free_resources(&cache, num_records);
        return ERROR_CODE;
    }

    clear_and_reinit_records(&cache, num_records);

    free_resources(&cache, num_records);

    pthread_mutex_destroy(&cache.lock);
    return 0;
}
```

This implementation covers dynamic memory allocation for records and linked lists of offsets, sorting by keys, logging, thread safety with mutexes, and basic cache management. The function handles concurrent writes using a global lock to ensure data integrity during initialization and updates.']

