#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define INITIAL_CAPACITY 100
#define MOVING_AVERAGE_SIZE 10

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int cellId;
    time_t timestamp;
    double throughput;
    double moving_avg_throughput[MOVING_AVERAGE_SIZE];
    size_t avg_index;
    size_t count;
} NetworkPerformanceMetrics;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *nfadata_array;
    size_t nfadata_count;
    NetworkPerformanceMetrics *metrics_array;
    size_t metrics_capacity;
    size_t metrics_count;
    pthread_mutex_t lock;
} DataStore;

// Function to initialize the data store
void initializeDataStore(DataStore *store) {
    store->nfadata_count = 0;
    store->metrics_capacity = INITIAL_CAPACITY;
    store->metrics_array = malloc(store->metrics_capacity * sizeof(NetworkPerformanceMetrics));
    if (!store->metrics_array) {
        perror("Failed to allocate memory for metrics array");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&store->lock, NULL);
}

// Function to resize the metrics array
void resizeMetricsArray(DataStore *store) {
    size_t new_capacity = store->metrics_capacity * 2;
    NetworkPerformanceMetrics *new_array = realloc(store->metrics_array, new_capacity * sizeof(NetworkPerformanceMetrics));
    if (!new_array) {
        perror("Failed to reallocate memory for metrics array");
        exit(EXIT_FAILURE);
    }
    store->metrics_array = new_array;
    store->metrics_capacity = new_capacity;
}

// Function to simulate traffic pattern and calculate throughput
double simulateTrafficPattern() {
    // Simulate peak and off-peak patterns
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    int hour = local_time->tm_hour;

    if (hour >= 8 && hour <= 20) { // Peak hours
        return ((double)rand() / RAND_MAX) * 100.0 + 50.0; // Random throughput between 50 and 150 Mbps
    } else {
        return ((double)rand() / RAND_MAX) * 30.0 + 10.0; // Random throughput between 10 and 40 Mbps
    }
}

// Function to calculate moving average
void updateMovingAverage(NetworkPerformanceMetrics *metric, double new_throughput) {
    metric->moving_avg_throughput[metric->avg_index] = new_throughput;
    double sum = 0;
    for (size_t i = 0; i < MOVING_AVERAGE_SIZE; ++i) {
        sum += metric->moving_avg_throughput[i];
    }
    metric->throughput = sum / MOVING_AVERAGE_SIZE;

    // Update index
    metric->avg_index = (metric->avg_index + 1) % MOVING_AVERAGE_SIZE;
}

// Main function to populate NFADATA and Network Metrics
void populateNfadataAndNetworkMetrics(DataStore *store, size_t count) {
    srand(time(NULL));

    pthread_mutex_lock(&store->lock);

    for (size_t i = 0; i < count; ++i) {
        if (store->metrics_count >= store->metrics_capacity) {
            resizeMetricsArray(store);
        }

        // Populate NFADATA
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RNTI = rand() % 10000;
        pdu.crc_tag.CRCFLAG = rand() % 2;

        if (store->nfadata_count < count) {
            store->nfadata_array[store->nfadata_count++] = pdu;
        }

        // Populate NetworkMetrics
        NetworkPerformanceMetrics metric;
        metric.cellId = i;
        metric.timestamp = time(NULL);
        double throughput = simulateTrafficPattern();
        updateMovingAverage(&metric, throughput);

        if (store->metrics_count < store->metrics_capacity) {
            store->metrics_array[store->metrics_count++] = metric;
        }
    }

    pthread_mutex_unlock(&store->lock);
}

// Function to free allocated resources
void cleanupDataStore(DataStore *store) {
    free(store->nfadata_array);
    free(store->metrics_array);
    pthread_mutex_destroy(&store->lock);
}

int main() {
    DataStore store;
    initializeDataStore(&store);

    // Example usage
    populateNfadataAndNetworkMetrics(&store, 200); // Adjust count as needed

    cleanupDataStore(&store);
    return 0;
}
```

