        int cellID = i + 1;

        cellConfigs[i].cellID = cellID;
        cellConfigs[i].pucchConfigIndex = PUCCH_CONFIG_INDEX;

        // Select a subset of bands
        size_t numBands = (MAX_BANDS_PER_CELL < MAX_SUPPORTED_BANDS) ? 
                          MAX_BANDS_PER_CELL : MAX_SUPPORTED_BANDS;

        cellConfigs[i].supportedBands = 
            (Band_t*)malloc(numBands * sizeof(Band_t));

        for (size_t j = 0; j < numBands; ++j) {
            // Example selection logic: simple modulo operation
            int bandIndex = (cellID + j) % MAX_SUPPORTED_BANDS;
            cellConfigs[i].supportedBands[j].band = predefinedBands[bandIndex];
        }

        cellConfigs[i].numSupportedBands = numBands;
    }

    return cellConfigs;
}

void freeCellConfigs(LTE_UERadioResourceConfigCommon_t* cellConfigs, int numCells) {
    if (cellConfigs == NULL) return;

    for (int i = 0; i < numCells; ++i) {
        free(cellConfigs[i].supportedBands);
    }

    free(cellConfigs);
}

