pthread_mutex_t mutex;

// JSON parsing function
void parseConfig(const char *jsonString) {
    json_error_t error;
    json_t *root = json_loads(jsonString, 0, &error);
    if (!root) {
        logMessage("Failed to parse config: Invalid JSON");
        return;
    }

    json_t *minValue = json_object_get(root, "minRandValue");
    json_t *maxValue = json_object_get(root, "maxRandValue");
    json_t *datasetSize = json_object_get(root, "maxDatasetSize");

    if (json_is_integer(minValue)) config.minRandValue = json_integer_value(minValue);
    if (json_is_integer(maxValue)) config.maxRandValue = json_integer_value(maxValue);
    if (json_is_integer(datasetSize)) config.maxDatasetSize = json_integer_value(datasetSize);

    json_decref(root);
}

// Logging function
void logMessage(const char *message) {
    pthread_mutex_lock(&mutex);
    FILE *logFile;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char fileName[100];
    strftime(fileName, sizeof(fileName), "log_%Y%m%d%H%M%S.txt", t);

    logFile = fopen(fileName, "a");
    if (logFile) {
        fprintf(logFile, "%s\n", message);
        fclose(logFile);
    } else {
        // Default logging location
        FILE *defaultLog = fopen("default_log.txt", "a");
        if (defaultLog) {
            fprintf(defaultLog, "%s\n", message);
            fclose(defaultLog);
        }
    }
    pthread_mutex_unlock(&mutex);
}

// Function to find the largest integer in an array
int findLargestInteger(int *array, size_t size) {
    int largest = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

// Function to process and sort records
void processAndSortRecords() {
    pthread_mutex_init(&mutex, NULL);

    // Read configuration from JSON file
    FILE *configFile = fopen("config.json", "r");
    if (!configFile) {
        logMessage("Failed to open config file. Using default settings.");
    } else {
        fseek(configFile, 0, SEEK_END);
        long fsize = ftell(configFile);
        fseek(configFile, 0, SEEK_SET);

        char *jsonString = (char *)malloc(fsize + 1);
        fread(jsonString, 1, fsize, configFile);
        jsonString[fsize] = '\0';
        parseConfig(jsonString);
        free(jsonString);
        fclose(configFile);
    }

    // Allocate memory
    long *offsets = (long *)calloc(config.maxDatasetSize, sizeof(long));
    int *keys = (int *)calloc(config.maxDatasetSize, sizeof(int));
    Record *records = (Record *)malloc(config.maxDatasetSize * sizeof(Record));

    if (!offsets || !keys || !records) {
        logMessage("Memory allocation failed.");
        free(offsets);
        free(keys);
        free(records);
        pthread_mutex_destroy(&mutex);
        return;
    }

    // Initialize records with random values
    srand(time(NULL));
    for (size_t i = 0; i < config.maxDatasetSize; ++i) {
        records[i].value = rand() % (config.maxRandValue - config.minRandValue + 1) + config.minRandValue;
        keys[i] = rand(); // Random key
    }

    // Sort records based on keys using qsort for simplicity and efficiency with large datasets
    qsort(keys, config.maxDatasetSize, sizeof(int), (int (*)(const void *, const void *))strcmp);

    logMessage("Records processed and sorted.");

    // Read integers from standard input
    size_t numIntegers;
    scanf("%zu", &numIntegers);
    int *inputArray = (int *)malloc(numIntegers * sizeof(int));
    if (!inputArray) {
        logMessage("Failed to allocate memory for input array.");
        free(offsets);
        free(keys);
        free(records);
        pthread_mutex_destroy(&mutex);
        return;
    }

    for (size_t i = 0; i < numIntegers; ++i) {
        scanf("%d", &inputArray[i]);
    }

    int largestInteger = findLargestInteger(inputArray, numIntegers);
    printf("The largest integer is: %d\n", largestInteger);

    // Clean up
    free(offsets);
    free(keys);
    free(records);
    free(inputArray);
    pthread_mutex_destroy(&mutex);
}

int main() {
    processAndSortRecords();
    return 0;
}
