['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define a record structure
typedef struct Record {
    int key;
    long offset;
    int value;
    struct Record* next;
} Record;

// Memory pool structure
typedef struct {
    size_t blockSize;
    void** freeList;
    size_t listSize;
    pthread_mutex_t lock; // For thread safety
} MemoryPool;

// Function to initialize a memory pool
void initMemoryPool(MemoryPool* pool, size_t blockSize, size_t numBlocks) {
    pool->blockSize = blockSize;
    pool->listSize = numBlocks;
    pool->freeList = (void**)malloc(numBlocks * sizeof(void*));

    pthread_mutex_init(&pool->lock, NULL);
}

// Function to allocate memory from the pool
void* poolAlloc(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    if (!pool->freeList[0]) { // No free blocks available
        pthread_mutex_unlock(&pool->lock);
        return malloc(pool->blockSize); // Fallback to standard allocation
    }

    void* block = pool->freeList[0];
    memmove(pool->freeList, pool->freeList + 1, --pool->listSize * sizeof(void*));

    pthread_mutex_unlock(&pool->lock);
    return block;
}

// Function to free memory back into the pool
void poolFree(MemoryPool* pool, void* block) {
    pthread_mutex_lock(&pool->lock);

    if (pool->listSize < sizeof(pool->freeList) / sizeof(void*)) {
        pool->freeList[pool->listSize++] = block;
    }

    pthread_mutex_unlock(&pool->lock);
}

// Function to initialize and manage the data structures
void initDataStructures(int numRecords, int keyRange, long offsetRange, int valueMin, int valueMax) {
    srand(time(NULL));

    MemoryPool pool;
    initMemoryPool(&pool, sizeof(Record), 100); // Example chunk size

    Record* head = NULL;

    for (int i = 0; i < numRecords; ++i) {
        Record* newRecord = (Record*)poolAlloc(&pool);
        if (!newRecord) { 
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }

        // Initialize record
        newRecord->key = rand() % keyRange;
        newRecord->offset = (rand() % offsetRange);
        newRecord->value = valueMin + rand() % (valueMax - valueMin + 1);
        newRecord->next = head;

        head = newRecord; // Insert at the beginning for efficiency
    }

    // Example usage of records: traverse and print (for demonstration)
    Record* current = head;
    while (current) {
        printf("Key: %d, Offset: %ld, Value: %d\n", current->key, current->offset, current->value);
        current = current->next;
    }

    // Free allocated memory
    while (head) {
        Record* temp = head;
        head = head->next;
        poolFree(&pool, temp);
    }
}

int main() {
    initDataStructures(1000, 100, 10000L, 1, 100); // Example parameters
    return 0;
}
```

### Explanation:

- **Memory Pool**: A custom memory pool is used to manage memory efficiently, reducing fragmentation and improving performance.

- **Thread Safety**: The `pthread_mutex_t` lock ensures that memory operations are thread-safe.

- **Random Initialization**: Each record's key and value are initialized with random numbers within specified ranges.

- **Linked List**: Records are inserted into a linked list for efficient insertion and deletion.

- **Error Handling**: Basic error handling is included to log memory allocation failures.

This implementation balances between performance, memory usage, and maintainability, suitable for high-load conditions.']

