// Main function to allocate and initialize memory
void* allocate_and_initialize_records(size_t num_offsets, unsigned int seed) {
    if (num_offsets == 0) return NULL;

    // Seed the random number generator
    if (seed == 0) {
        srand((unsigned int)time(NULL));
    } else {
        srand(seed);
    }

    offset_t *offsets = NULL;
    key_t *keys = NULL;
    record_t *records = NULL;

    // Allocate memory for offsets, keys and records
    size_t total_size = sizeof(offset_t) + sizeof(key_t) + num_offsets * sizeof(record_t);

    if (total_size > SIZE_MAX - sizeof(offset_t) || total_size > SIZE_MAX - sizeof(key_t)) {
        log_error("Integer overflow detected during size calculation.");
        goto cleanup;
    }

    offsets = (offset_t*)malloc(sizeof(offset_t));
    if (!offsets) {
        log_error("Failed to allocate memory for offsets.");
        goto cleanup;
    }

    keys = (key_t*)malloc(sizeof(key_t) * num_offsets);
    if (!keys) {
        log_error("Failed to allocate memory for keys.");
        free(offsets);
        goto cleanup;
    }

    records = (record_t*)malloc(num_offsets * sizeof(record_t));
    if (!records) {
        log_error("Failed to allocate memory for records.");
        free(keys);
        free(offsets);
        goto cleanup;
    }

    // Initialize the value fields of each record with random integers
    for (size_t i = 0; i < num_offsets; ++i) {
        records[i].value = rand() % 1000 + 1;
    }

    return offsets;

cleanup:
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);

    return NULL;
}

// Example usage
