LTE_PHY_TEST_CONFIG* load_ue_configurations(const char *config_file, size_t *num_configs) {
    FILE *fp = fopen(config_file, "r");
    if (!fp) {
        perror("Failed to open config file");
        return NULL;
    }

    struct json_object *parsed_json;
    struct json_object *profiles;
    struct json_object *profile;

    // Read and parse the JSON configuration file
    size_t n = fread(buffer, 1, sizeof(buffer), fp);
    buffer[n] = '\0';
    parsed_json = json_tokener_parse(buffer);

    // Extract profiles array from JSON
    if (!json_object_object_get_ex(parsed_json, "profiles", &profiles)) {
        fprintf(stderr, "Error: 'profiles' not found in configuration\n");
        fclose(fp);
        return NULL;
    }

    *num_configs = json_array_length(profiles);

    // Allocate memory for the configurations array
    LTE_PHY_TEST_CONFIG *configs = (LTE_PHY_TEST_CONFIG *)malloc(*num_configs * sizeof(LTE_PHY_TEST_CONFIG));
    if (!configs) {
        perror("Memory allocation failed");
        fclose(fp);
        return NULL;
    }

