        json_object_array_get_idx(profiles, i, &profile);

        struct json_object *param1_obj, *param2_obj, *desc_obj;

        if (!json_object_object_get_ex(profile, "parameter1", &param1_obj)) {
            fprintf(stderr, "Error: 'parameter1' missing in profile %zu\n", i);
            free(configs);
            fclose(fp);
            return NULL;
        }

        if (!json_object_object_get_ex(profile, "parameter2", &param2_obj)) {
            fprintf(stderr, "Error: 'parameter2' missing in profile %zu\n", i);
            free(configs);
            fclose(fp);
            return NULL;
        }

        if (!json_object_object_get_ex(profile, "description", &desc_obj)) {
            fprintf(stderr, "Warning: 'description' missing in profile %zu, using default empty string\n", i);
            strcpy(configs[i].description, "");
        } else {
            strncpy(configs[i].description, json_object_get_string(desc_obj), sizeof(configs[i].description) - 1);
        }

        configs[i].parameter1 = json_object_get_int(param1_obj);
        configs[i].parameter2 = json_object_get_int(param2_obj);
    }

    fclose(fp);
    return configs;
}

// Function to deallocate the configurations array
