```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_BATCH_SIZE 1000
#define MEMORY_POOL_SIZE 1024

typedef struct {
    long offset;
    int key;
    double value;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;
} HashTableBucket;

typedef struct {
    HashTableBucket* buckets;
    size_t bucket_count;
    size_t total_size;
    pthread_mutex_t pool_lock;
    Record* memory_pool;
    int pool_offset; // Index for the next free record in the pool
} MemoryPool;

MemoryPool* create_memory_pool(size_t bucket_count) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->buckets = calloc(bucket_count, sizeof(HashTableBucket));
    if (!pool->buckets) {
        free(pool);
        return NULL;
    }

    for (size_t i = 0; i < bucket_count; ++i) {
        pthread_mutex_init(&pool->buckets[i].lock, NULL);
    }

    pool->bucket_count = bucket_count;
    pool->total_size = MEMORY_POOL_SIZE;
    pool->memory_pool = malloc(sizeof(Record) * MEMORY_POOL_SIZE);
    if (!pool->memory_pool) {
        free(pool->buckets);
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->pool_lock, NULL);
    pool->pool_offset = 0;

    // Initialize logging (Assumed external dependency)
    // init_logging();

    return pool;
}

int hash_function(int key, size_t bucket_count) {
    return key % bucket_count;
}

Record* allocate_record(MemoryPool* pool) {
    pthread_mutex_lock(&pool->pool_lock);

    if (pool->pool_offset < MEMORY_POOL_SIZE) {
        Record* record = &pool->memory_pool[pool->pool_offset++];
        pthread_mutex_unlock(&pool->pool_lock);
        return record;
    } else {
        // Log memory allocation failure
        // log_error("Memory pool exhausted");
        pthread_mutex_unlock(&pool->pool_lock);
        return NULL;
    }
}

void insert_record(MemoryPool* pool, long offset, int key, double value) {
    Record* record = allocate_record(pool);
    if (!record) return;

    record->offset = offset;
    record->key = key;
    record->value = value;

    size_t index = hash_function(key, pool->bucket_count);

    pthread_mutex_lock(&pool->buckets[index].lock);

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        // Log memory allocation failure
        // log_error("Failed to allocate node");
        pthread_mutex_unlock(&pool->buckets[index].lock);
        return;
    }

    new_node->record = *record;
    new_node->next = pool->buckets[index].head;
    pool->buckets[index].head = new_node;
    pool->buckets[index].count++;

    pthread_mutex_unlock(&pool->buckets[index].lock);
}

Record* find_record(MemoryPool* pool, int key) {
    size_t index = hash_function(key, pool->bucket_count);

    pthread_mutex_lock(&pool->buckets[index].lock);

    Node* current = pool->buckets[index].head;
    while (current) {
        if (current->record.key == key) {
            Record* result = malloc(sizeof(Record));
            *result = current->record;
            pthread_mutex_unlock(&pool->buckets[index].lock);
            return result;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&pool->buckets[index].lock);
    return NULL;
}

void delete_record(MemoryPool* pool, int key) {
    size_t index = hash_function(key, pool->bucket_count);

    pthread_mutex_lock(&pool->buckets[index].lock);

    Node *current = pool->buckets[index].head;
    Node *prev = NULL;

    while (current) {
        if (current->record.key == key) {
            if (prev) {
                prev->next = current->next;
            } else {
                pool->buckets[index].head = current->next;
            }
            free(current);
            pool->buckets[index].count--;
            pthread_mutex_unlock(&pool->buckets[index].lock);
            return;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&pool->buckets[index].lock);
}

void serialize_data(MemoryPool* pool, FILE* file) {
    for (size_t i = 0; i < pool->bucket_count; ++i) {
        pthread_mutex_lock(&pool->buckets[i].lock);

        Node* current = pool->buckets[i].head;
        while (current) {
            fprintf(file, "%ld,%d,%f\n", current->record.offset, 
                    current->record.key, current->record.value);
            current = current->next;
        }

        pthread_mutex_unlock(&pool->buckets[i].lock);
    }
}

void destroy_memory_pool(MemoryPool* pool) {
    for (size_t i = 0; i < pool->bucket_count; ++i) {
        pthread_mutex_lock(&pool->buckets[i].lock);

        Node* current = pool->buckets[i].head;
        while (current) {
            Node* next = current->next;
            free(current);
            current = next;
        }

        pthread_mutex_unlock(&pool->buckets[i].lock);
    }

    free(pool->memory_pool);
    free(pool->buckets);
    free(pool);
}
```

This implementation provides a basic framework for managing records with efficient memory usage and thread safety. It includes a hash table for O(1) average-time complexity lookups, dynamic resizing is not implemented here but can be added by monitoring the load factor of the hash table. The serialization function writes data to a file in CSV format. Logging is assumed to be integrated externally.']

