bool is_valid_mac_address(const char *mac) {
    if (strlen(mac) != MAC_ADDRESS_MAX_LEN - 1) return false;
    for (int i = 0; i < MAC_ADDRESS_MAX_LEN - 2; i++) {
        if ((i % 3 == 2 && mac[i] != ':') || 
            (i % 3 != 2 && !isxdigit(mac[i]))) {
            return false;
        }
    }
    return true;
}

bool is_unique_device_name(const char *name) {
    for (size_t i = 0; i < device_count; ++i) {
        if (strcmp(devices[i].device_name, name) == 0) {
            return false;
        }
    }
    return true;
}

void log_error(const char *error_message) {
    fprintf(stderr, "Error: %s\n", error_message);
}

void add_device(Device *dev_list, const char *name, unsigned int device_id) {
    if (device_count >= MAX_DEVICES) {
        log_error("Maximum number of devices reached.");
        return;
    }
    if (!is_unique_device_name(name)) {
        log_error("Device name must be unique.");
        return;
    }
    strncpy(dev_list[device_count].device_name, name, MAX_NAME_LENGTH);
    dev_list[device_count].device_id = device_id;
    dev_list[device_count].data_entries = NULL;
    dev_list[device_count].entry_count = 0;
    device_count++;
}

void add_data_entry(Device *dev_list, unsigned int device_id, float temperature, const char *mac_address) {
    for (size_t i = 0; i < device_count; ++i) {
        if (dev_list[i].device_id == device_id) {
            DataEntry *entries = realloc(dev_list[i].data_entries, 
                                         sizeof(DataEntry) * (dev_list[i].entry_count + 1));
            if (!entries) {
                log_error("Memory allocation failed for data entry.");
                return;
            }
            dev_list[i].data_entries = entries;

            DataEntry *new_entry = &dev_list[i].data_entries[dev_list[i].entry_count];
            new_entry->timestamp = time(NULL);
            new_entry->temperature = temperature;
            strncpy(new_entry->mac_address, mac_address, MAC_ADDRESS_MAX_LEN);

            if (!is_valid_mac_address(mac_address)) {
                log_error("Invalid MAC address format.");
                return;
            }

            dev_list[i].entry_count++;
            return;
        }
    }
    log_error("Device not found for data entry.");
}

void free_resources(Device *dev_list) {
    for (size_t i = 0; i < device_count; ++i) {
        free(dev_list[i].data_entries);
    }
}

