['Below is a C code implementation for managing dynamic memory allocation and initialization for a hybrid data structure using linked lists and hash tables. The implementation includes custom memory pool management, thread safety with mutexes, logging, and basic operations like insertion, deletion, and retrieval.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define CHUNK_SIZE 1024
#define TABLE_SIZE 256

typedef struct Record {
    int id;
    long value1;
    double value2;
    struct Record* next; // For linked list in the hash table bucket
} Record;

typedef struct HashTable {
    Record** buckets;
    pthread_mutex_t locks[TABLE_SIZE];
} HashTable;

// Memory pool structure
typedef struct MemoryPool {
    size_t chunk_size;
    void* pool;
    size_t used_memory;
    size_t total_memory;
    pthread_mutex_t lock;
} MemoryPool;

// Function prototypes
void initializeHashTable(HashTable* table);
Record* createRecord(MemoryPool* mp, int id, long value1, double value2);
void insertRecord(HashTable* table, Record* record);
Record* findRecordByOffset(HashTable* table, size_t offset);
void deleteRecord(HashTable* table, int id);
void freeHashTable(HashTable* table);
void initializeMemoryPool(MemoryPool* mp, size_t chunk_size, size_t num_chunks);
void* allocateFromPool(MemoryPool* mp);
void freeMemoryPool(MemoryPool* mp);

// Logging macro
#define LOG(msg) printf("LOG: %s\n", msg)

// Function implementations

void initializeHashTable(HashTable* table) {
    table->buckets = (Record**)calloc(TABLE_SIZE, sizeof(Record*));
    for (int i = 0; i < TABLE_SIZE; ++i) {
        pthread_mutex_init(&table->locks[i], NULL);
    }
}

Record* createRecord(MemoryPool* mp, int id, long value1, double value2) {
    Record* record = allocateFromPool(mp);
    if (!record) {
        LOG("Memory allocation failed");
        return NULL;
    }

    record->id = id;
    record->value1 = value1;
    record->value2 = value2;
    record->next = NULL;

    return record;
}

void insertRecord(HashTable* table, Record* record) {
    int index = record->id % TABLE_SIZE;
    pthread_mutex_lock(&table->locks[index]);

    record->next = table->buckets[index];
    table->buckets[index] = record;

    pthread_mutex_unlock(&table->locks[index]);
}

Record* findRecordByOffset(HashTable* table, size_t offset) {
    int index = (int)(offset % TABLE_SIZE);
    pthread_mutex_lock(&table->locks[index]);

    Record* current = table->buckets[index];
    while (current) {
        if ((size_t)current == offset) {
            pthread_mutex_unlock(&table->locks[index]);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&table->locks[index]);
    return NULL;
}

void deleteRecord(HashTable* table, int id) {
    int index = id % TABLE_SIZE;
    pthread_mutex_lock(&table->locks[index]);

    Record *current = table->buckets[index], *prev = NULL;
    while (current && current->id != id) {
        prev = current;
        current = current->next;
    }

    if (current) {
        if (!prev)
            table->buckets[index] = current->next;
        else
            prev->next = current->next;

        // Memory pool will handle deallocation
    }

    pthread_mutex_unlock(&table->locks[index]);
}

void freeHashTable(HashTable* table) {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        Record* record = table->buckets[i];
        while (record) {
            Record* next = record->next;
            // Memory pool will handle deallocation
            record = next;
        }
    }

    free(table->buckets);
    for (int i = 0; i < TABLE_SIZE; ++i) {
        pthread_mutex_destroy(&table->locks[i]);
    }
}

void initializeMemoryPool(MemoryPool* mp, size_t chunk_size, size_t num_chunks) {
    mp->chunk_size = chunk_size;
    mp->pool = malloc(chunk_size * num_chunks);
    mp->used_memory = 0;
    mp->total_memory = chunk_size * num_chunks;
    pthread_mutex_init(&mp->lock, NULL);

    if (!mp->pool) {
        LOG("Memory pool initialization failed");
    }
}

void* allocateFromPool(MemoryPool* mp) {
    pthread_mutex_lock(&mp->lock);

    void* block = (char*)mp->pool + mp->used_memory;
    if ((size_t)(block - (char*)mp->pool) + mp->chunk_size <= mp->total_memory) {
        mp->used_memory += mp->chunk_size;
        pthread_mutex_unlock(&mp->lock);
        return block;
    }

    pthread_mutex_unlock(&mp->lock);
    LOG("Memory pool exhausted");
    return NULL;
}

void freeMemoryPool(MemoryPool* mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
}

int main() {
    HashTable table;
    MemoryPool memoryPool;

    initializeHashTable(&table);
    initializeMemoryPool(&memoryPool, CHUNK_SIZE, 1024);

    // Example usage
    Record* record = createRecord(&memoryPool, 1, 123456789L, 3.14159);
    if (record) insertRecord(&table, record);

    Record* found = findRecordByOffset(&table, (size_t)record);
    if (found) {
        printf("Found Record: id=%d, value1=%ld, value2=%.5f\n", 
               found->id, found->value1, found->value2);
    }

    deleteRecord(&table, 1);
    freeHashTable(&table);
    freeMemoryPool(&memoryPool);

    return 0;
}
```

### Key Features:
- **Thread Safety**: Uses mutexes to protect hash table operations.
- **Custom Memory Pool**: Manages dynamic memory allocation efficiently with a fixed-size pool.
- **Logging**: Basic logging for monitoring purposes.
- **Scalability**: Designed to handle large datasets and high concurrency.
- **Error Handling**: Checks for memory exhaustion and logs errors.

This implementation is designed for educational purposes, focusing on the core concepts of hybrid data structures, custom memory management, and thread safety.']

