```c
#include <stdio.h>
#include <stdlib.h>
import <jpeglib.h> // External library for JPEG handling.
#include <poppler.h> // External library for PDF conversion.
#include <pthread.h>
#include <time.h>

typedef struct {
    int *array;
    size_t used;
    size_t size;
} DynamicArray;

// Mutex and condition variable for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond_var = PTHREAD_COND_INITIALIZER;

void initDynamicArray(DynamicArray *a, size_t initialSize) {
    a->array = (int *)malloc(initialSize * sizeof(int));
    if (!a->array) exit(EXIT_FAILURE);
    a->used = 0;
    a->size = initialSize;
}

void insertArray(DynamicArray *a, int element) {
    pthread_mutex_lock(&mutex);
    if (a->used == a->size) {
        a->size *= 2;
        a->array = realloc(a->array, a->size * sizeof(int));
        if (!a->array) exit(EXIT_FAILURE);
    }
    a->array[a->used++] = element;
    pthread_mutex_unlock(&mutex);
}

int findLargest(DynamicArray *a) {
    int largest = a->array[0];
    for (size_t i = 1; i < a->used; ++i) {
        if (a->array[i] > largest)
            largest = a->array[i];
    }
    return largest;
}

void freeDynamicArray(DynamicArray *a) {
    free(a->array);
    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&cond_var);
}

