```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ITEMS 50000

typedef struct {
    int PHY_RX_FRAME_TAG;
    void* LTE_RRC_UE_CONTEXT; // Placeholder for actual structure
} LTE_PHY_RX_FRAME;

typedef struct {
    double value;
    char *identifier;
    int flag;
} Item;

typedef struct Node {
    Item item;
    struct Node *next;
} Node;

typedef struct MemoryPool {
    void **free_list;
    size_t element_size;
    size_t total_elements;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool create_memory_pool(size_t element_size, size_t total_elements) {
    MemoryPool pool;
    pool.element_size = element_size;
    pool.total_elements = total_elements;
    pool.free_list = malloc(total_elements * sizeof(void*));

    for (size_t i = 0; i < total_elements; ++i) {
        void *element = malloc(element_size);
        pool.free_list[i] = element;
    }

    pthread_mutex_init(&pool.lock, NULL);
    return pool;
}

void destroy_memory_pool(MemoryPool *pool) {
    for (size_t i = 0; i < pool->total_elements; ++i) {
        free(pool->free_list[i]);
    }
    free(pool->free_list);
    pthread_mutex_destroy(&pool.lock);
}

void* allocate_from_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->total_elements == 0) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    void *element = pool->free_list[--(pool->total_elements)];
    pthread_mutex_unlock(&pool->lock);
    return element;
}

void deallocate_to_pool(MemoryPool *pool, void *element) {
    pthread_mutex_lock(&pool->lock);
    if (pool->total_elements < MAX_ITEMS) {
        pool->free_list[pool->total_elements++] = element;
    } else {
        free(element);
    }
    pthread_mutex_unlock(&pool->lock);
}

typedef struct LinkedList {
    Node *head;
} LinkedList;

LinkedList* create_linked_list() {
    LinkedList *list = malloc(sizeof(LinkedList));
    list->head = NULL;
    return list;
}

void insert_node(LinkedList *list, Item item) {
    Node *new_node = allocate_from_pool(&global_memory_pool);
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    new_node->item = item;
    new_node->next = list->head;
    list->head = new_node;
}

void delete_node(LinkedList *list, Item target_item) {
    Node **curr = &list->head;

    while (*curr) {
        if ((*curr)->item.flag == target_item.flag) {
            Node *temp = *curr;
            *curr = (*curr)->next;
            deallocate_to_pool(&global_memory_pool, temp);
            return;
        }
        curr = &(*curr)->next;
    }
}

void free_linked_list(LinkedList *list) {
    Node *current = list->head;
    while (current) {
        Node *temp = current;
        current = current->next;
        deallocate_to_pool(&global_memory_pool, temp);
    }
    free(list);
}

typedef struct CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void handle_crc_indication(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu->CRC_INDICATION_REL8_TAG.CRCFLAG < 0 || pdu->CRC_INDICATION_REL8_TAG.CRCFLAG > 1) {
        fprintf(stderr, "Invalid CRCFLAG setting\n");
        return;
    }
    // Process the CRC indication
}

int main() {
    global_memory_pool = create_memory_pool(sizeof(Node), MAX_ITEMS);

    LinkedList *long_offset_list = create_linked_list();
    LinkedList *key_list = create_linked_list();

    Item item1 = { .value = 3.14, .identifier = "Item1", .flag = 1 };
    insert_node(long_offset_list, item1);

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = 101;
    pdu.RNTI = 202;
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    handle_crc_indication(&pdu);

    delete_node(long_offset_list, item1);
    free_linked_list(long_offset_list);

    destroy_memory_pool(&global_memory_pool);

