                sqlite3_bind_text(stmt, 2, supervisorRecords[i].name.c_str(), -1, SQLITE_STATIC);

                if (sqlite3_step(stmt) != SQLITE_DONE) {
                    logOperation("Failed to insert record into database.");
                }
                sqlite3_finalize(stmt);
            } else {
                logOperation("Failed to prepare statement for insertion.");
            }
        }

        if (sqlite3_exec(db, "COMMIT;", nullptr, nullptr, &errorMessage) != SQLITE_OK) {
            logOperation("Failed to commit transaction.");
        }
    }

public:
    DynamicDataProcessor(size_t numOffsets, size_t numKeys, size_t numRecords, size_t numSupervisors)
        : numberOfOffsets(numOffsets), numberOfKeys(numKeys), 
          numberOfRecords(numRecords), numberOfSupervisorRecords(numSupervisors) {

        offsets = std::make_unique<long[]>(numOffsets);
        keys = std::make_unique<int[]>(numKeys);
        records = std::make_unique<Record[]>(numRecords);
        supervisorRecords = std::make_unique<SupervisorRecord[]>(numSupervisors);

        RandomGenerator::MersenneTwister rng(12345); // Example seed

        for (size_t i = 0; i < numOffsets; ++i) {
            offsets[i] = rng.generateLong(1, 100000);
        }

        for (size_t i = 0; i < numKeys; ++i) {
            keys[i] = rng.generateInt(-50000, 50000);
        }

        for (size_t i = 0; i < numRecords; ++i) {
            records[i].value = rng.generateInt(1, 1000);
        }
    }

    ~DynamicDataProcessor() {
        sqlite3_close(db);
    }

    DynamicDataProcessor(DynamicDataProcessor&& other)
        : offsets(std::move(other.offsets)),
          keys(std::move(other.keys)),
          records(std::move(other.records)),
          supervisorRecords(std::move(other.supervisorRecords)),
          db(other.db) {}

    DynamicDataProcessor& operator=(DynamicDataProcessor&& other) noexcept {
        if (this != &other) {
            offsets = std::move(other.offsets);
            keys = std::move(other.keys);
            records = std::move(other.records);
            supervisorRecords = std::move(other.supervisorRecords);
