            while (sqlite3_step(stmt) == SQLITE_ROW) {
                const char* name = reinterpret_cast<const char*>(sqlite3_column_text(stmt, 0));
                const char* city = reinterpret_cast<const char*>(sqlite3_column_text(stmt, 1));
                const char* address = reinterpret_cast<const char*>(sqlite3_column_text(stmt, 2));

                std::cout << "Name: " << name 
                          << ", City: " << city
                          << ", Address: " << address << std::endl;
            }
            sqlite3_finalize(stmt);
        } else {
            logOperation("Failed to prepare statement for retrieval.");
        }
    }

    void exportSortedRecordsToCSV(const std::string& filePath) {
        std::ofstream file(filePath);

        if (!file.is_open()) {
            logOperation("Failed to open CSV file.");
            return;
        }

        for (size_t i = 0; i < numberOfKeys; ++i) {
            file << keys[i] << ',' << records[i].value << '\n';
        }
