    void sortRecordsByKeys() {
        std::vector<std::pair<int, int>> keyRecordPairs;

        for (size_t i = 0; i < numberOfKeys; ++i) {
            keyRecordPairs.emplace_back(keys[i], i);
        }

        std::sort(keyRecordPairs.begin(), keyRecordPairs.end());

        std::unique_ptr<Record[]> sortedRecords = std::make_unique<Record[]>(numberOfRecords);

        for (size_t i = 0; i < numberOfKeys; ++i) {
            int originalIndex = keyRecordPairs[i].second;
            sortedRecords[i] = records[originalIndex];
        }

        std::swap(records, sortedRecords);
    }

    void kthLargest(std::istream& input, size_t k) {
        std::priority_queue<int, std::vector<int>, std::greater<int>> minHeap;

        int number;
        while (input >> number) {
            if (minHeap.size() < static_cast<size_t>(k)) {
                minHeap.push(number);
            } else if (number > minHeap.top()) {
                minHeap.pop();
                minHeap.push(number);
            }
        }

        std::cout << "The " << k << "-th largest number is: " 
                  << minHeap.top() << std::endl;
    }

private:
