['Below is a C code implementation that manages a dynamic collection of `resource_usage` records using an array-based approach to optimize for cache performance and minimize memory fragmentation, while supporting concurrent updates and efficient querying:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int seconds;
    int nanoseconds;
} timestamp;

typedef struct {
    double metric_value;
    char status_indicator;
    timestamp start_time;
    timestamp end_time;
} resource_usage;

typedef struct {
    resource_usage *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} ResourceManager;

#define INITIAL_CAPACITY 10

ResourceManager* create_resource_manager() {
    ResourceManager *rm = (ResourceManager*)malloc(sizeof(ResourceManager));
    if (!rm) return NULL;

    rm->records = (resource_usage*)calloc(INITIAL_CAPACITY, sizeof(resource_usage));
    if (!rm->records) {
        free(rm);
        return NULL;
    }

    rm->capacity = INITIAL_CAPACITY;
    rm->count = 0;
    pthread_mutex_init(&rm->lock, NULL);

    return rm;
}

int add_resource_usage(ResourceManager *rm, resource_usage usage) {
    pthread_mutex_lock(&rm->lock);

    if (rm->count == rm->capacity) {
        size_t new_capacity = rm->capacity * 2;
        resource_usage *new_records = (resource_usage*)realloc(rm->records, new_capacity * sizeof(resource_usage));
        if (!new_records) {
            pthread_mutex_unlock(&rm->lock);
            return -1; // Memory allocation failure
        }
        rm->records = new_records;
        rm->capacity = new_capacity;
    }

    rm->records[rm->count++] = usage;

    pthread_mutex_unlock(&rm->lock);
    return 0;
}

void free_resource_manager(ResourceManager *rm) {
    if (rm) {
        free(rm->records);
        pthread_mutex_destroy(&rm->lock);
        free(rm);
    }
}

// Simulate and populate metric values with measurements
void simulate_measurements(resource_usage *usage, int interval_count, double accuracy_factor) {
    for (int i = 0; i < interval_count; ++i) {
        double measurement = ((double)rand() / RAND_MAX) * accuracy_factor;
        pthread_mutex_lock(&usage->lock);
        usage->metric_value += measurement;
        pthread_mutex_unlock(&usage->lock);
    }
}

// Statistical filtering to smooth out noisy data points
void filter_metrics(resource_usage *records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        // Simple moving average or other statistical methods can be applied here
        double sum = records[i].metric_value;
        int n = 1; // Number of measurements contributing to this record

        if (i > 0 && i < count - 1) { // Skip first and last for simplicity
            sum += records[i-1].metric_value + records[i+1].metric_value;
            n += 2;
        }

        pthread_mutex_lock(&records[i].lock);
        records[i].metric_value = sum / n;
        pthread_mutex_unlock(&records[i].lock);
    }
}

// Query resource usage within a specified time range
size_t query_resource_usage(const ResourceManager *rm, timestamp start_time, timestamp end_time, resource_usage **results) {
    size_t match_count = 0;

    for (size_t i = 0; i < rm->count; ++i) {
        if ((rm->records[i].start_time.seconds >= start_time.seconds &&
             rm->records[i].start_time.nanoseconds >= start_time.nanoseconds) &&
            (rm->records[i].end_time.seconds <= end_time.seconds &&
             rm->records[i].end_time.nanoseconds <= end_time.nanoseconds)) {

            results[match_count++] = &rm->records[i];
        }
    }

    return match_count;
}

int main() {
    ResourceManager *rm = create_resource_manager();
    if (!rm) {
        fprintf(stderr, "Failed to create resource manager\n");
        return EXIT_FAILURE;
    }

    // Example usage
    resource_usage usage1 = {0.0, 'A', (timestamp){10, 0}, (timestamp){20, 0}};
    add_resource_usage(rm, usage1);

    resource_usage *results;
    size_t count = query_resource_usage(rm, (timestamp){5, 0}, (timestamp){25, 0}, &results);

    for (size_t i = 0; i < count; ++i) {
        printf("Resource Usage: %f\n", results[i]->metric_value);
    }

    free_resource_manager(rm);

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Array-Based Implementation**: Chosen for better cache performance and reduced memory fragmentation.
- **Concurrency Handling**: Uses mutex locks to ensure thread safety during updates.
- **Dynamic Memory Management**: Handles reallocation gracefully, doubling capacity when needed.
- **Statistical Filtering**: Simple averaging is used; more complex filters can be added as needed.
- **Query Functionality**: Efficiently retrieves records within a specified time range.
- **Graceful Error Handling**: Returns specific error codes for memory allocation failures.']

