#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int key;
    char *value; // Dynamically allocated string
} Data;

typedef struct Item {
    Data *data;
    struct Item *next;
} Item;

// Function to create a new item node
Item* create_item(Data *data) {
    if (!data) return NULL;

    Item *item = (Item *)malloc(sizeof(Item));
    if (!item) return NULL;

    item->data = data;
    item->next = NULL;
    return item;
}

// Function to free all allocated memory
void cleanup(Item **head, Data **data_array, size_t data_count) {
    Item *current = *head;
    while (current != NULL) {
        Item *temp = current;
        current = current->next;

        if (temp->data && temp->data->value) {
            free(temp->data->value);
            free(temp->data);
        }
        free(temp);
    }

    for (size_t i = 0; i < data_count; ++i) {
        if (data_array[i] && data_array[i]->value) {
            free(data_array[i]->value);
            free(data_array[i]);
        }
    }

    *head = NULL;
}

// Thread-safe function to populate the linked list with data entries
pthread_mutex_t lock;

void populate_linked_list(Item **head, Data ***data_sources, size_t num_sources) {
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < num_sources; ++i) {
        Data *data_array = data_sources[i];
        size_t data_count = 0;

        while (data_array[data_count]) {
            // Assuming each source provides an array of Data structures ending with a NULL
            if (data_array[data_count]->value) { 
                Item *new_item = create_item(data_array[data_count]);

                if (*head == NULL) {
                    *head = new_item;
                } else {
                    Item *current = *head;
                    while (current->next != NULL) {
                        current = current->next;
                    }
                    current->next = new_item;
