// Function to initialize the list with dynamic memory allocation
NFAPI_CRC_INDICATION_PDU_T* init_crc_list(int *size, int max_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(max_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        log_message("Memory allocation failed during initialization.");
        return NULL;
    }
    *size = 0;
    return list;
}

// Function to add an entry to the list
int add_crc_entry(NFAPI_CRC_INDICATION_PDU_T **list, int *size, int max_capacity) {
    if (*size >= max_capacity) {
        log_message("Maximum capacity reached. Cannot add more entries.");
        return 0;
    }

    // Generate random values for RX_UE_INFORMATION_TAG and CRCFLAG
    srand(time(NULL));
    int new_rnti = rand() % 10000; // Example RNTI generation

    // Ensure no consecutive structures share the same RNTI value
    if (*size > 0 && (*list)[*size - 1].RNTI == new_rnti) {
        return add_crc_entry(list, size, max_capacity); // Retry with a different random RNTI
    }

    NFAPI_CRC_INDICATION_PDU_T *temp = realloc(*list, (*size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp) {
        log_message("Memory reallocation failed.");
        return 0;
    }

    (*list) = temp;
    (*list)[*size].rx_ue_information_tag.RNTI = new_rnti;
    (*list)[*size].RNTI = new_rnti;
    (*list)[*size].crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Random CRCFLAG

    log_message("Added new NFAPI_CRC_INDICATION_PDU_T entry.");
    (*size)++;
    return 1;
}

// Function to free the list
