} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ueInfo;
} NFAPI_CRC_INDICATION_PDU_T;

// Global variables for metrics array
NetworkPerformanceMetrics *metricsArray = NULL;
int metricsCount = 0;
int capacity = INITIAL_CAPACITY;
pthread_mutex_t metricsMutex = PTHREAD_MUTEX_INITIALIZER;

void initializeRandom() {
    srand(time(NULL));
}

CRC_INDICATION_REL8_TAG generateCrcIndicationTag() {
    CRC_INDICATION_REL8_TAG tag;
    tag.crcFlag = rand() % 2; // Randomly set to 0 or 1
    return tag;
}

RX_UE_INFORMATION_TAG generateRxUeInformation(unsigned int rnti) {
    RX_UE_INFORMATION_TAG ueInfo;
    ueInfo.rnti = rnti;
    ueInfo.crcTag = generateCrcIndicationTag();
    return ueInfo;
}

NFAPI_CRC_INDICATION_PDU_T* createPduList(int size, unsigned int *rntis) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < size; i++) {
        pdus[i].ueInfo = generateRxUeInformation(rntis[i]);
    }

    return pdus;
}

double simulateThroughput() {
    // Simulate traffic pattern with random throughput value
    return ((rand() % 100) + 1.0); // Random throughputs between 1 and 100 Mbps
}

void resizeMetricsArray(int newCapacity) {
    NetworkPerformanceMetrics *newArray = realloc(metricsArray, newCapacity * sizeof(NetworkPerformanceMetrics));
    if (newArray != NULL) {
        metricsArray = newArray;
        capacity = newCapacity;
    }
}

int calculateMovingAverage(double throughput, int index) {
    // Calculate moving average for the last 10 entries
    double sum = 0.0;
    for (int i = 0; i < 10; i++) {
        sum += metricsArray[(index + i) % capacity].throughput;
    }
    return (int)(sum / 10);
}

void updateMetrics(NetworkPerformanceMetrics *metrics, unsigned int cellId) {
    pthread_mutex_lock(&metricsMutex);

    if (metricsCount >= capacity) {
        resizeMetricsArray(capacity * 2);
    }

    metrics->cellId = cellId;
    metrics->timestamp = time(NULL);
    metrics->throughput = simulateThroughput();
    metrics->index = metricsCount % 10;

    int avgIndex = metricsCount > 9 ? (metricsCount - 1) : 0;
    metrics->movingAvgThroughput[avgIndex] = calculateMovingAverage(metrics->throughput, metricsCount);

    metricsArray[metricsCount++] = *metrics;

    pthread_mutex_unlock(&metricsMutex);
}

void populateNfadataAndNetworkMetrics(unsigned int *rntis, int pduSize) {
    initializeRandom();

    // Create list of PDU structures
    NFAPI_CRC_INDICATION_PDU_T *pdus = createPduList(pduSize, rntis);

    for (int i = 0; i < pduSize; i++) {
        NetworkPerformanceMetrics metric;
        updateMetrics(&metric, i);
    }

    free(pdus);
}

int main() {
    unsigned int rntiValues[] = {1, 2, 3, 4, 5};
    populateNfadataAndNetworkMetrics(rntiValues, 5);

    for (int i = 0; i < metricsCount; i++) {
        printf("CellId: %u, Timestamp: %ld, Throughput: %.2f, Moving Avg: %.2f\n",
               metricsArray[i].cellId,
               metricsArray[i].timestamp,
               metricsArray[i].throughput,
               metricsArray[i].movingAvgThroughput[metricsArray[i].index]);
    }

    free(metricsArray);
    return 0;
}
```

