// Define the structure for user session
typedef struct {
    int userID;
    time_t timestamp;
    char activities[100][256];
    size_t activityCount;
} UserSession;

// Hash table entry for session management
typedef struct SessionHashNode {
    unsigned long hashValue;
    UserSession *session;
    struct SessionHashNode *next;
} SessionHashNode;

#define HASH_TABLE_SIZE 1024

SessionHashNode **hashTable = NULL;
pthread_mutex_t hashMutex[HASH_TABLE_SIZE];

// Initialize the hash table
void initHashTable() {
    hashTable = (SessionHashNode **)malloc(HASH_TABLE_SIZE * sizeof(SessionHashNode *));
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hashTable[i] = NULL;
        pthread_mutex_init(&hashMutex[i], NULL);
    }
}

// Hash function
unsigned long hashFunction(int userID) {
    return ((unsigned long)userID) % HASH_TABLE_SIZE;
}

// Insert a session into the hash table
void insertSession(UserSession *session) {
    unsigned long hashValue = hashFunction(session->userID);

    pthread_mutex_lock(&hashMutex[hashValue]);

    SessionHashNode *newNode = (SessionHashNode *)malloc(sizeof(SessionHashNode));
    newNode->hashValue = hashValue;
    newNode->session = session;
    newNode->next = hashTable[hashValue];
    hashTable[hashValue] = newNode;

    pthread_mutex_unlock(&hashMutex[hashValue]);
}

// Retrieve a session from the hash table
UserSession *getSession(int userID) {
    unsigned long hashValue = hashFunction(userID);

    pthread_mutex_lock(&hashMutex[hashValue]);

    SessionHashNode *current = hashTable[hashValue];
    while (current != NULL) {
        if (current->session->userID == userID) {
            UserSession *result = current->session;
            pthread_mutex_unlock(&hashMutex[hashValue]);
            return result;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&hashMutex[hashValue]);
    return NULL;
}

// Function to dynamically allocate and initialize a user session
UserSession *createUserSession(int userID) {
    UserSession *session = (UserSession *)malloc(sizeof(UserSession));
    if (!session) {
        perror("Failed to allocate memory for session");
        exit(EXIT_FAILURE);
    }
    session->userID = userID;
    session->timestamp = time(NULL);
    session->activityCount = 0;
    return session;
}

