    public:
        DataProcessor(size_t num_offsets, size_t num_keys1, size_t num_keys2)
            : offsets(new (std::nothrow) long[num_offsets]),
              keys1(new (std::nothrow) int[num_keys1]),
              keys2(new (std::nothrow) int[num_keys2]),
              records(new (std::nothrow) Record[1000]), // Assume 1000 as default size
              file_metadata(new (std::nothrow) FileMetadata()) {
            if (!offsets || !keys1 || !keys2 || !records || !file_metadata)
