            }
        }

        ~DataProcessor() {
            delete[] offsets;
            delete[] keys1;
            delete[] keys2;
            delete[] records;
            delete file_metadata;
        }

        DataProcessor(const DataProcessor& other)
            : offsets(new (std::nothrow) long[other.num_offsets]),
              keys1(new (std::nothrow) int[other.num_keys1]),
              keys2(new (std::nothrow) int[other.num_keys2]),
              records(new (std::nothrow) Record[1000]), // Assume 1000 as default size
              file_metadata(new (std::nothrow) FileMetadata()) {
            if (!offsets || !keys1 || !keys2 || !records || !file_metadata)
                throw std::runtime_error("Memory allocation failed");

            *this = other;
        }

        DataProcessor& operator=(const DataProcessor& other) {
            if (this != &other) {
                delete[] offsets;
                delete[] keys1;
                delete[] keys2;
                delete[] records;
                delete file_metadata;

                size_t num_offsets = other.num_offsets;
                size_t num_keys1 = other.num_keys1;
                size_t num_keys2 = other.num_keys2;

                offsets = new (std::nothrow) long[num_offsets];
                keys1 = new (std::nothrow) int[num_keys1];
                keys2 = new (std::nothrow) int[num_keys2];
                records = new (std::nothrow) Record[1000]; // Assume 1000 as default size
                file_metadata = new (std::nothrow) FileMetadata();

                if (!offsets || !keys1 || !keys2 || !records || !file_metadata)
                    throw std::runtime_error("Memory allocation failed");

                memcpy(offsets, other.offsets, num_offsets * sizeof(long));
                memcpy(keys1, other.keys1, num_keys1 * sizeof(int));
                memcpy(keys2, other.keys2, num_keys2 * sizeof(int));
                memcpy(records, other.records, 1000 * sizeof(Record));
                *file_metadata = *(other.file_metadata);
            }
            return *this;
        }

    private:
        long* offsets;
        int* keys1;
        int* keys2;
        Record* records;
        FileMetadata* file_metadata;

        size_t num_offsets, num_keys1, num_keys2;

        std::mutex mtx; // Mutex for thread safety

    public:
