```cpp
#include <iostream>
#include <vector>
#include <random>
#include <boost/graph/adjacency_list.hpp>
#include <boost/thread/shared_mutex.hpp>

// Mock of the external metadata service interface
class MetadataService {
public:
    virtual std::string getAttributes(const std::string& key) = 0;
};

// Caching layer to minimize API calls
class AttributeCache {
private:
    std::unordered_map<std::string, std::string> cache_;
    boost::shared_mutex mutex_;

public:
    std::string getAttribute(const std::string& key, MetadataService* service) {
        boost::unique_lock<boost::shared_mutex> lock(mutex_);
        auto it = cache_.find(key);
        if (it != cache_.end()) {
            return it->second;
        }
        std::string attribute = service->getAttributes(key);
        cache_[key] = attribute;
        return attribute;
    }
};

// Structure to hold a record
struct Record {
    int value;

    Record(int val) : value(val) {}
};

// Function declarations for memory management
void* allocateMemory(size_t size);
void initializeArray(long* array, size_t size, long initValue);
void initializeArray(int* array, size_t size, int initValue);
void initializeRecords(Record** records, size_t size, int minValue, int maxValue);

class GraphManager {
private:
    typedef boost::adjacency_list<boost::vecS, boost::vecS, boost::undirectedS> Graph;
    Graph graph_;
    MetadataService* metadataService_;
    AttributeCache cache_;

public:
    GraphManager(MetadataService* service) : metadataService_(service) {}

    void addVertexWithAttributes(const std::string& key) {
        // Fetch attributes from metadata service
        std::string attributes = cache_.getAttribute(key, metadataService_);

        // Add vertex to the graph (simulated with a string attribute)
        auto v = boost::add_vertex(attributes, graph_);

        logOperation("Vertex added", key);
    }

    void addEdgeWithAttributes(const std::string& sourceKey, const std::string& targetKey) {
        // Fetch attributes and manage connectivity
        auto s = boost::vertex(sourceKey, graph_);
        auto t = boost::vertex(targetKey, graph_);

        if (s.first != graph_.null_vertex() && t.first != graph_.null_vertex()) {
            boost::add_edge(s.first, t.first, graph_);
            logOperation("Edge added", sourceKey + "->" + targetKey);
        }
    }

private:
    void logOperation(const std::string& operationType, const std::string& detail) {
        // Implement logging mechanism based on configurable levels
        std::cout << "[INFO] " << operationType << ": " << detail << std::endl;
    }
};

// Memory management functions implemented in C
extern "C" {
void* allocateMemory(size_t size) {
    return malloc(size);
}

void initializeArray(long* array, size_t size, long initValue) {
    for (size_t i = 0; i < size; ++i) {
        array[i] = initValue;
    }
}

void initializeArray(int* array, size_t size, int initValue) {
    for (size_t i = 0; i < size; ++i) {
        array[i] = initValue;
    }
}

void initializeRecords(Record** records, size_t size, int minValue, int maxValue) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(minValue, maxValue);

    *records = reinterpret_cast<Record*>(allocateMemory(size * sizeof(Record)));
    for (size_t i = 0; i < size; ++i) {
        (*records)[i] = Record(dis(gen));
    }
}
}

// Example usage
int main() {
    // Assume MetadataServiceImpl is a concrete implementation of MetadataService
    MetadataService* service = new MetadataServiceImpl();
    GraphManager manager(service);

    // Adding vertices and edges
    manager.addVertexWithAttributes("vertex1");
    manager.addVertexWithAttributes("vertex2");
    manager.addEdgeWithAttributes("vertex1", "vertex2");

    // Memory management example
    long offsets[10];
    int keys[10];
    Record* records = nullptr;

    initializeArray(offsets, 10, 0L);
    initializeArray(keys, 10, -1);
    initializeRecords(&records, 10, 1, 100);

    delete[] reinterpret_cast<char*>(records); // Proper cleanup
    delete service;

    return 0;
}
```

