} CachedProfile;

CachedProfile profile_cache[MAX_PROFILES];
int cache_count = 0;

void load_json_profile(const char *filename, LTE_PHY_TEST_CONFIG *config) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open JSON file");
        exit(EXIT_FAILURE);
    }

    struct json_object *parsed_json;
    struct json_object *json_obj;
    parsed_json = json_object_from_file(file);
    fclose(file);

    if (!parsed_json) {
        fprintf(stderr, "Failed to parse JSON\n");
        exit(EXIT_FAILURE);
    }

    json_object_object_get_ex(parsed_json, "frequency", &json_obj);
    config->frequency = (unsigned int)json_object_get_int(json_obj);

    // Populate other fields as necessary
}

LTE_PHY_TEST_CONFIG *initialize_ue_configurations(const char *config_file, size_t num_ues) {
    LTE_PHY_TEST_CONFIG *configs = malloc(num_ues * sizeof(LTE_PHY_TEST_CONFIG));
    if (!configs) {
        perror("Failed to allocate memory for configurations");
        exit(EXIT_FAILURE);
    }

    load_json_profile(config_file, configs);

    // Cache the configuration
    CachedProfile new_cache;
    new_cache.profile_name = strdup(config_file);
    memcpy(&new_cache.config, configs, sizeof(LTE_PHY_TEST_CONFIG));
    if (cache_count < MAX_PROFILES) {
        profile_cache[cache_count++] = new_cache;
    }

    return configs;
}

LTE_PHY_TEST_CONFIG *get_cached_profile(const char *profile_name) {
    for (int i = 0; i < cache_count; ++i) {
        if (strcmp(profile_name, profile_cache[i].profile_name) == 0) {
            return &profile_cache[i].config;
        }
    }
    return NULL;
}

void free_ue_configurations(LTE_PHY_TEST_CONFIG *configs, size_t num_ues) {
    free(configs);
    for (int i = 0; i < cache_count; ++i) {
        free(profile_cache[i].profile_name);
    }
}

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <config_file> <number_of_ues>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *config_file = argv[1];
