    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Dynamic array management functions
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t size;
    size_t capacity;
} NFAPI_CRC_ARRAY;

void initializeNFAPI_CRC_ARRAY(NFAPI_CRC_ARRAY *nfaArray, size_t initialCapacity) {
    nfaArray->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfaArray->array) {
        // Handle allocation error
        exit(EXIT_FAILURE);
    }
    nfaArray->size = 0;
    nfaArray->capacity = initialCapacity;
}

void freeNFAPI_CRC_ARRAY(NFAPI_CRC_ARRAY *nfaArray) {
    free(nfaArray->array);
    nfaArray->array = NULL;
    nfaArray->size = 0;
    nfaArray->capacity = 0;
}

int addOrUpdateNFAPI_CRC_INDICATION_PDU(NFAPI_CRC_ARRAY *nfaArray, int index,
                                        int RX_UE_INFORMATION_TAG, int RNTI) {
    if (index < 0 || index >= nfaArray->size) {
        // Check capacity and resize if necessary
        if (nfaArray->size == nfaArray->capacity) {
            size_t newCapacity = nfaArray->capacity * 2;
            NFAPI_CRC_INDICATION_PDU_T* newArray =
                (NFAPI_CRC_INDICATION_PDU_T*)realloc(nfaArray->array, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!newArray) {
                // Handle allocation error
                return -1;  // Indicate failure
            }
            nfaArray->array = newArray;
            nfaArray->capacity = newCapacity;
        }

        // Add a new entry at the end or specific index
        NFAPI_CRC_INDICATION_PDU_T* pdu = &nfaArray->array[nfaArray->size++];
        pdu->index = index < 0 ? (int)nfaArray->size - 1 : index;
    } else {
        // Update existing entry
        NFAPI_CRC_INDICATION_PDU_T* pdu = &nfaArray->array[index];
        if (pdu == NULL) {
            return -2;  // Indicate failure: invalid index
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &nfaArray->array[(index < 0) ? nfaArray->size - 1 : index];
    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    // Randomly set CRCFLAG (0 or 1)
    pdu->crcIndicationRel8Tag.CRCFLAG = rand() % 2;

    return 0;  // Indicate success
}

NFAPI_CRC_INDICATION_PDU_T* getNFAPI_CRC_ARRAY(NFAPI_CRC_ARRAY *nfaArray, size_t *count) {
    if (!nfaArray || !count) {
        return NULL;
    }
    *count = nfaArray->size;
    return nfaArray->array;
}

