// External logging library mockup for demonstration purposes.
void log_event(const char *event) {
    printf("Log: %s\n", event);
}

typedef struct {
    double *numbers;
    size_t num_count;
    char *strings;
    size_t str_size;
    pthread_mutex_t lock;
} DataAggregator;

// Helper function to calculate mean and standard deviation
void calculate_statistics(const double *data, size_t count, double *mean, double *std_dev) {
    if (count == 0) return;

    double sum = 0.0, sq_sum = 0.0;
    for (size_t i = 0; i < count; ++i) {
        sum += data[i];
        sq_sum += data[i] * data[i];
    }
    *mean = sum / count;
    *std_dev = sqrt((sq_sum - sum * sum / count) / (count - 1));
}

// Function to merge and sort numbers
void merge_and_sort(double *numbers, size_t n) {
    if (n < 2) return;

    size_t mid = n / 2;
    double *left = malloc(mid * sizeof(double));
    double *right = malloc((n - mid) * sizeof(double));

    for (size_t i = 0; i < mid; ++i) left[i] = numbers[i];
    for (size_t i = mid; i < n; ++i) right[i - mid] = numbers[i];

    merge_and_sort(left, mid);
    merge_and_sort(right, n - mid);

    size_t i = 0, j = 0, k = 0;
    while (i < mid && j < n - mid) {
        if (left[i] <= right[j]) numbers[k++] = left[i++];
        else numbers[k++] = right[j++];
    }

    while (i < mid) numbers[k++] = left[i++];
    while (j < n - mid) numbers[k++] = right[j++];

    free(left);
    free(right);
}

// Thread function for data ingestion
void* ingest_data(void *arg) {
    DataAggregator *aggregator = (DataAggregator *)arg;
    char buffer[BUFFER_SIZE];
    FILE *file = fopen("data.bin", "rb"); // Replace with actual file descriptor

    while (fread(buffer, sizeof(char), BUFFER_SIZE, file)) {
        pthread_mutex_lock(&aggregator->lock);

        for (size_t i = 0; i < BUFFER_SIZE;) {
            if (sscanf(buffer + i, "%lf%n", &aggregator->numbers[aggregator->num_count], &n) == 1) {
                aggregator->num_count++;
                i += n;
            } else if (strchr(buffer + i, '\0')) { // Check for null-terminated string
                char *str = strdup(buffer + i);
                str[strcspn(str, "\x00")] = '\0'; // Remove any null characters
                size_t len = strlen(str) + 1;

                aggregator->strings = realloc(aggregator->strings, aggregator->str_size + len);
                memcpy(aggregator->strings + aggregator->str_size, str, len);
                aggregator->str_size += len;

                free(str);
                i += n;
            } else {
                // Move to next potential valid entry
                while (buffer[i] && !isdigit(buffer[i]) && buffer[i] != '\0') i++;
                i++;
            }
        }

        pthread_mutex_unlock(&aggregator->lock);
    }

    fclose(file);
    return NULL;
}

void processAndAggregateData(int num_files) {
    DataAggregator aggregator = { .numbers = malloc(MAX_DATA_POINTS * sizeof(double)),
                                  .num_count = 0,
                                  .strings = malloc(1),
                                  .str_size = 0,
                                  .lock = PTHREAD_MUTEX_INITIALIZER };

    pthread_t threads[num_files];

    for (int i = 0; i < num_files; ++i) {
        if (pthread_create(&threads[i], NULL, ingest_data, &aggregator)) {
            perror("Failed to create thread");
            exit(1);
        }
    }

    for (int i = 0; i < num_files; ++i) {
        pthread_join(threads[i], NULL);
    }

    merge_and_sort(aggregator.numbers, aggregator.num_count);

    double mean, std_dev;
    calculate_statistics(aggregator.numbers, aggregator.num_count, &mean, &std_dev);

    printf("Mean: %f\n", mean);
    printf("Standard Deviation: %f\n", std_dev);

    log_event("Data aggregation completed.");

    free(aggregator.numbers);
    free(aggregator.strings);
}
