#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_RECORDS 10000000

typedef struct Record {
    int value;
    int *key_ptr;
    double *double_ptr;
    struct Record *next; // For LRU linked list
} Record;

typedef struct HashTableEntry {
    int key;
    Record *record;
    struct HashTableEntry *next;
} HashTableEntry;

typedef struct {
    HashTableEntry **table;
    size_t size;
    size_t count;
    pthread_mutex_t lock;
    Record *lru_head;
    Record *lru_tail;
    size_t memory_usage_threshold;
    FILE *log_file;
} RecordPool;

unsigned int hash_function(int key, size_t table_size) {
    return (key & 0x7FFFFFFF) % table_size; // Simple hash function
}

RecordPool* create_record_pool(size_t initial_size, size_t threshold) {
    RecordPool *pool = malloc(sizeof(RecordPool));
    pool->size = initial_size;
    pool->count = 0;
    pool->table = calloc(pool->size, sizeof(HashTableEntry*));
    pthread_mutex_init(&pool->lock, NULL);
    pool->lru_head = NULL;
    pool->lru_tail = NULL;
    pool->memory_usage_threshold = threshold;
    pool->log_file = fopen("memory_log.txt", "a");
    return pool;
}

void log_memory_action(const char *action) {
    fprintf(pool->log_file, "%s\n", action);
    fflush(pool->log_file); // Ensure immediate write to disk
}

Record* create_record(int value, int *key_ptr, double *double_ptr) {
    Record *record = malloc(sizeof(Record));
    record->value = value;
    record->key_ptr = key_ptr;
    record->double_ptr = double_ptr;
    record->next = NULL;
    return record;
}

void add_record(RecordPool *pool, int key, int value, int *key_ptr, double *double_ptr) {
    pthread_mutex_lock(&pool->lock);

    unsigned int index = hash_function(key, pool->size);
    HashTableEntry *entry = pool->table[index];
    while (entry != NULL) {
        if (entry->key == key) {
            entry->record->value = value;
            entry->record->key_ptr = key_ptr;
            entry->record->double_ptr = double_ptr;

            // Move record to LRU head
            if (entry->record != pool->lru_head) {
                if (entry->record == pool->lru_tail) {
                    pool->lru_tail = entry->record->next;
                }
                if (entry->record->next != NULL) {
                    entry->record->next->prev = entry->record->prev;
                }
                if (entry->record->prev != NULL) {
                    entry->record->prev->next = entry->record->next;
                }
                entry->record->next = pool->lru_head;
                entry->record->prev = NULL;
                if (pool->lru_head != NULL) {
                    pool->lru_head->prev = entry->record;
                }
                pool->lru_head = entry->record;
            }
            log_memory_action("Updated record");
            pthread_mutex_unlock(&pool->lock);
            return;
        }
        entry = entry->next;
    }

    // Insert new record
    Record *new_record = create_record(value, key_ptr, double_ptr);

    HashTableEntry *new_entry = malloc(sizeof(HashTableEntry));
    new_entry->key = key;
    new_entry->record = new_record;
    new_entry->next = pool->table[index];
    pool->table[index] = new_entry;

    // Update LRU list
    new_record->prev = NULL;
    if (pool->lru_tail != NULL) {
        pool->lru_tail->next = new_record;
        new_record->prev = pool->lru_tail;
    }
    pool->lru_tail = new_record;
    if (pool->lru_head == NULL) {
        pool->lru_head = new_record;
    }

    pool->count++;
    log_memory_action("Added record");

    // Check memory usage and evict if necessary
    while (sizeof(Record) * pool->count > pool->memory_usage_threshold) {
        evict_lru_record(pool);
    }

    pthread_mutex_unlock(&pool->lock);
}

void evict_lru_record(RecordPool *pool) {
    if (pool->lru_head == NULL) return;

    Record *record_to_evict = pool->lru_head;
    unsigned int index = hash_function(*(int *)record_to_evict->key_ptr, pool->size);

    HashTableEntry *entry = pool->table[index];
    HashTableEntry *prev_entry = NULL;
    while (entry != NULL) {
        if (entry->record == record_to_evict) {
            if (prev_entry != NULL) {
                prev_entry->next = entry->next;
            } else {
                pool->table[index] = entry->next;
            }
            free(entry);
            break;
        }
        prev_entry = entry;
        entry = entry->next;
    }

    if (record_to_evict == pool->lru_tail) {
        pool->lru_tail = record_to_evict->prev;
    }
    if (record_to_evict->next != NULL) {
        record_to_evict->next->prev = record_to_evict->prev;
    }
    if (pool->lru_head == record_to_evict) {
        pool->lru_head = record_to_evict->next;
    }

    free(record_to_evict);
    pool->count--;
    log_memory_action("Evicted LRU record");
}

void remove_record(RecordPool *pool, int key) {
    pthread_mutex_lock(&pool->lock);

    unsigned int index = hash_function(key, pool->size);
    HashTableEntry *entry = pool->table[index];
    HashTableEntry *prev_entry = NULL;
    while (entry != NULL) {
        if (entry->key == key) {
            Record *record_to_remove = entry->record;

            // Update LRU list
            if (record_to_remove == pool->lru_head) {
                pool->lru_head = record_to_remove->next;
            }
            if (record_to_remove == pool->lru_tail) {
                pool->lru_tail = record_to_remove->prev;
            }
            if (record_to_remove->prev != NULL) {
                record_to_remove->prev->next = record_to_remove->next;
            }
            if (record_to_remove->next != NULL) {
                record_to_remove->next->prev = record_to_remove->prev;
            }

            // Remove from hash table
            if (prev_entry != NULL) {
                prev_entry->next = entry->next;
            } else {
                pool->table[index] = entry->next;
            }
            free(entry);

            free(record_to_remove);
            pool->count--;
            log_memory_action("Removed record");
            pthread_mutex_unlock(&pool->lock);
            return;
        }
        prev_entry = entry;
        entry = entry->next;
    }

    pthread_mutex_unlock(&pool->lock);
}

void resize_record_pool(RecordPool *pool) {
    pthread_mutex_lock(&pool->lock);

    size_t new_size = pool->size * 2;
    HashTableEntry **new_table = calloc(new_size, sizeof(HashTableEntry*));

    for (size_t i = 0; i < pool->size; ++i) {
        HashTableEntry *entry = pool->table[i];
        while (entry != NULL) {
            unsigned int new_index = hash_function(entry->key, new_size);
            HashTableEntry *new_entry = malloc(sizeof(HashTableEntry));
            *new_entry = *entry;
            new_entry->next = new_table[new_index];
            new_table[new_index] = new_entry;

            entry = entry->next;
        }
    }

    free(pool->table);
    pool->table = new_table;
    pool->size = new_size;
    log_memory_action("Resized hash table");

    pthread_mutex_unlock(&pool->lock);
}

void checkpoint_record_pool(RecordPool *pool) {
    pthread_mutex_lock(&pool->lock);

    FILE *checkpoint_file = fopen("record_checkpoint.bin", "wb");
    if (checkpoint_file == NULL) {
        pthread_mutex_unlock(&pool->lock);
        return;
    }

    fwrite(&pool->size, sizeof(pool->size), 1, checkpoint_file);
    fwrite(&pool->count, sizeof(pool->count), 1, checkpoint_file);

    for (size_t i = 0; i < pool->size; ++i) {
        HashTableEntry *entry = pool->table[i];
        while (entry != NULL) {
            int key = entry->key;
            fwrite(&key, sizeof(key), 1, checkpoint_file);
            Record *record = entry->record;

            int value = record->value;
            fwrite(&value, sizeof(value), 1, checkpoint_file);

            int *key_ptr = record->key_ptr;
            fwrite(key_ptr, sizeof(int), 1, checkpoint_file);

            double *double_ptr = record->double_ptr;
            fwrite(double_ptr, sizeof(double), 1, checkpoint_file);

            entry = entry->next;
        }
    }

    fclose(checkpoint_file);
    log_memory_action("Checkpointed records");

    pthread_mutex_unlock(&pool->lock);
}

void restore_record_pool(RecordPool *pool) {
    FILE *checkpoint_file = fopen("record_checkpoint.bin", "rb");
    if (checkpoint_file == NULL) return;

    fread(&pool->size, sizeof(pool->size), 1, checkpoint_file);
    fread(&pool->count, sizeof(pool->count), 1, checkpoint_file);

    pool->table = calloc(pool->size, sizeof(HashTableEntry*));

    for (size_t i = 0; i < pool->count; ++i) {
        int key;
        fread(&key, sizeof(key), 1, checkpoint_file);

        int value;
        fread(&value, sizeof(value), 1, checkpoint_file);

        int *key_ptr = malloc(sizeof(int));
        fread(key_ptr, sizeof(int), 1, checkpoint_file);

        double *double_ptr = malloc(sizeof(double));
        fread(double_ptr, sizeof(double), 1, checkpoint_file);

        add_record(pool, key, value, key_ptr, double_ptr);
    }

    fclose(checkpoint_file);
}

void free_record_pool(RecordPool *pool) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->size; ++i) {
        HashTableEntry *entry = pool->table[i];
        while (entry != NULL) {
            HashTableEntry *temp_entry = entry;
            entry = entry->next;
            free(temp_entry);
        }
    }

    free(pool->table);

    while (pool->lru_head != NULL) {
        Record *record_to_free = pool->lru_head;
        pool->lru_head = record_to_free->next;
        free(record_to_free);
    }

    pthread_mutex_unlock(&pool->lock);
    fclose(pool->log_file);
    free(pool);
}

int main() {
    // Example usage
    RecordPool *pool = create_record_pool(1024, 10 * sizeof(Record));
    int key1 = 1;
    int value1 = 100;
    double double_value1 = 3.14;

    add_record(pool, key1, value1, &key1, &double_value1);

    checkpoint_record_pool(pool);
    restore_record_pool(pool);

    remove_record(pool, key1);
    free_record_pool(pool);

    return 0;
}
