#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/types.h>
#include <fcntl.h>

#define MAX_TEMP_READINGS 1024
#define CONFIG_FILE "config.cfg"
#define BUFFER_SIZE 2048

typedef struct {
    float temperature;
    char sensor_id[16];
} Measurement;

typedef struct {
    Measurement *buffer;
    size_t head, tail;
    size_t max_size;
    pthread_mutex_t mutex;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} CircularBuffer;

static CircularBuffer temp_buffer = {0};
static pthread_mutex_t config_mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    size_t pool_size;
    Measurement *pool;
} MemoryPool;

MemoryPool memory_pool = {0};

void initialize_config() {
    pthread_mutex_lock(&config_mutex);
    // Check if configuration file exists and reload
    int fd = open(CONFIG_FILE, O_RDONLY);
    if (fd != -1) {
        close(fd);
        printf("Configuration reloaded\n");
    }
    pthread_mutex_unlock(&config_mutex);
}

void initialize_memory_pool(size_t pool_size) {
    memory_pool.pool_size = pool_size;
    memory_pool.pool = (Measurement *)malloc(pool_size * sizeof(Measurement));
    if (!memory_pool.pool) {
        perror("Failed to allocate memory pool");
        exit(EXIT_FAILURE);
    }
}

Measurement* allocate_measurement() {
    pthread_mutex_lock(&temp_buffer.mutex);

    while ((temp_buffer.head - temp_buffer.tail + temp_buffer.max_size) % temp_buffer.max_size == 0) {
        pthread_cond_wait(&temp_buffer.not_full, &temp_buffer.mutex);
    }

    Measurement *measurement = &memory_pool.pool[temp_buffer.tail++ % memory_pool.pool_size];
    memset(measurement, 0, sizeof(Measurement));

    pthread_cond_signal(&temp_buffer.not_empty);
    pthread_mutex_unlock(&temp_buffer.mutex);

    return measurement;
}

void deallocate_measurement() {
    pthread_mutex_lock(&temp_buffer.mutex);
    pthread_cond_signal(&temp_buffer.not_full);
    pthread_mutex_unlock(&temp_buffer.mutex);
}

int initialize_circular_buffer(size_t max_size) {
    temp_buffer.buffer = (Measurement *)malloc(max_size * sizeof(Measurement));
    if (!temp_buffer.buffer) {
        perror("Failed to allocate circular buffer");
        return -1;
    }

    temp_buffer.max_size = max_size;
    pthread_mutex_init(&temp_buffer.mutex, NULL);
    pthread_cond_init(&temp_buffer.not_full, NULL);
    pthread_cond_init(&temp_buffer.not_empty, NULL);

    return 0;
}

void add_measurement(Measurement *measurement) {
    pthread_mutex_lock(&temp_buffer.mutex);

    while ((temp_buffer.head - temp_buffer.tail + temp_buffer.max_size) % temp_buffer.max_size == 0) {
        pthread_cond_wait(&temp_buffer.not_full, &temp_buffer.mutex);
    }

    temp_buffer.buffer[temp_buffer.head++ % temp_buffer.max_size] = *measurement;

    pthread_cond_signal(&temp_buffer.not_empty);
    pthread_mutex_unlock(&temp_buffer.mutex);
}

Measurement* get_measurement() {
    pthread_mutex_lock(&temp_buffer.mutex);

    while (temp_buffer.tail == temp_buffer.head) {
        pthread_cond_wait(&temp_buffer.not_empty, &temp_buffer.mutex);
    }

    Measurement *measurement = &temp_buffer.buffer[temp_buffer.tail++ % temp_buffer.max_size];

    pthread_cond_signal(&temp_buffer.not_full);
    pthread_mutex_unlock(&temp_buffer.mutex);

    return measurement;
}

void release_resources() {
    free(temp_buffer.buffer);
    pthread_mutex_destroy(&temp_buffer.mutex);
    pthread_cond_destroy(&temp_buffer.not_full);
    pthread_cond_destroy(&temp_buffer.not_empty);

    free(memory_pool.pool);
}

void execute_shell_command(const char *cmd, char **output) {
    int pipefd[2];
    pid_t cpid;
    size_t buf_size = 1024;

    if (pipe(pipefd) == -1) {
        perror("pipe");
        exit(EXIT_FAILURE);
    }

    cpid = fork();
    if (cpid == -1) {
        perror("fork");
        exit(EXIT_FAILURE);
    }

    if (cpid == 0) { // Child process
        close(pipefd[0]);
        dup2(pipefd[1], STDOUT_FILENO);
        execlp("/bin/sh", "sh", "-c", cmd, NULL);
        perror("execlp");
        exit(EXIT_FAILURE);
    } else { // Parent process
        close(pipefd[1]);
        char buf[buf_size];
        ssize_t count;
        *output = malloc(buf_size);
        if (*output == NULL) {
            perror("malloc");
            exit(EXIT_FAILURE);
        }
        *output[0] = '\0';

        while ((count = read(pipefd[0], buf, buf_size - 1)) > 0) {
            buf[count] = '\0';
            strcat(*output, buf);
        }

        if (count == -1) {
            perror("read");
            free(*output);
            exit(EXIT_FAILURE);
        }

        close(pipefd[0]);
        wait(NULL); // Wait for child process to finish
    }
}

int main() {
    initialize_config();
    initialize_memory_pool(MAX_TEMP_READINGS);

    if (initialize_circular_buffer(BUFFER_SIZE) == -1) {
        release_resources();
        return EXIT_FAILURE;
    }

    // Example usage of adding and getting measurements
    Measurement *new_measurement = allocate_measurement();
    new_measurement->temperature = 23.5f;
    strcpy(new_measurement->sensor_id, "S001");
    add_measurement(new_measurement);

    Measurement *retrieved_measurement = get_measurement();
    printf("Temperature: %.2f, Sensor ID: %s\n", retrieved_measurement->temperature, retrieved_measurement->sensor_id);

    char *command_output;
    execute_shell_command("date", &command_output);
    printf("Shell Command Output: %s\n", command_output);
    free(command_output);

    deallocate_measurement();

    release_resources();

    return 0;
}
