['Below is a C implementation that addresses your requirements for dynamically allocating and initializing a network of nodes in a distributed system. The code includes functions for creating nodes, populating keys with random values, inserting edges probabilistically, ensuring tree balance, managing memory gracefully, and supporting thread safety.

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define ERROR_CODE_MEMORY_ALLOCATION_FAILURE -1

typedef struct Edge {
    int target_node_key;
    double weight;
    struct Edge* next;
} Edge;

typedef struct Node {
    int key;
    struct Node* left;
    struct Node* right;
    struct Edge* edges;
    pthread_mutex_t lock; // For thread safety
} Node;

Node* create_node(int key) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    node->key = key;
    node->left = node->right = NULL;
    node->edges = NULL;
    pthread_mutex_init(&node->lock, NULL);

    return node;
}

void free_node(Node* node) {
    if (node) {
        pthread_mutex_destroy(&node->lock);
        Edge* edge = node->edges;
        while (edge) {
            Edge* temp = edge;
            edge = edge->next;
            free(temp);
        }
        free(node);
    }
}

void insert_edge(Node* from, Node* to, double weight) {
    pthread_mutex_lock(&from->lock);

    Edge* new_edge = (Edge*)malloc(sizeof(Edge));
    if (!new_edge) {
        pthread_mutex_unlock(&from->lock);
        return;
    }

    new_edge->target_node_key = to->key;
    new_edge->weight = weight;
    new_edge->next = from->edges;

    from->edges = new_edge;

    pthread_mutex_unlock(&from->lock);
}

void free_network(Node* root) {
    if (!root) return;

    free_network(root->left);
    free_network(root->right);

    free_node(root);
}

Node* insert_into_bst(Node* node, int key) {
    if (node == NULL) return create_node(key);

    if (key < node->key)
        node->left = insert_into_bst(node->left, key);
    else if (key > node->key)
        node->right = insert_into_bst(node->right, key);

    return node;
}

int populate_keys(Node* root, int min_key, int max_key) {
    if (!root) return 0;

    pthread_mutex_lock(&root->lock);
    root->key = rand() % (max_key - min_key + 1) + min_key;
    pthread_mutex_unlock(&root->lock);

    populate_keys(root->left, min_key, max_key);
    populate_keys(root->right, min_key, max_key);

    return 0;
}

int insert_edges_probabilistically(Node* root, double probability, int num_nodes) {
    if (!root || num_nodes <= 1) return 0;

    Node** nodes = (Node**)malloc(num_nodes * sizeof(Node*));
    if (!nodes) return ERROR_CODE_MEMORY_ALLOCATION_FAILURE;

    // Collect all nodes
    void collect_nodes(Node* node, Node** nodes, int* index) {
        if (!node || *index >= num_nodes) return;
        nodes[*index] = node;
        (*index)++;

        collect_nodes(node->left, nodes, index);
        collect_nodes(node->right, nodes, index);
    }

    int index = 0;
    collect_nodes(root, nodes, &index);

    for (int i = 0; i < num_nodes - 1; ++i) {
        for (int j = i + 1; j < num_nodes; ++j) {
            if ((double)rand() / RAND_MAX <= probability) {
                insert_edge(nodes[i], nodes[j], rand() % 100 / 10.0);
            }
        }
    }

    free(nodes);
    return 0;
}

Node* initialize_network(int num_nodes, int min_key, int max_key, double edge_probability) {
    if (num_nodes <= 0) return NULL;

    srand(time(NULL));

    Node* root = NULL;
    for (int i = 0; i < num_nodes; ++i) {
        int key = rand() % (max_key - min_key + 1) + min_key;
        root = insert_into_bst(root, key);
    }

    populate_keys(root, min_key, max_key);

    if (insert_edges_probabilistically(root, edge_probability, num_nodes) == ERROR_CODE_MEMORY_ALLOCATION_FAILURE) {
        free_network(root);
        return NULL; // Return error code
    }

    return root;
}

int main() {
    int num_nodes = 10;
    int min_key = 1, max_key = 100;
    double edge_probability = 0.3;

    Node* network_root = initialize_network(num_nodes, min_key, max_key, edge_probability);
    if (!network_root) {
        printf("Failed to initialize network due to memory allocation error.\n");
        return ERROR_CODE_MEMORY_ALLOCATION_FAILURE;
    }

    // Perform operations with the network...

    free_network(network_root);

    return 0;
}
```

### Key Points:
- The `Node` structure holds a key, left and right pointers for BST management, an edge list for connections, and a mutex for thread safety.
- Functions handle memory allocation errors gracefully by returning `NULL`.
- Edges are inserted probabilistically between nodes to ensure connectivity while maintaining balance.
- Thread safety is managed using `pthread_mutex_t` in each node. 
- The code ensures efficient BST operations with dynamic growth and deletion management.
- The entire network can be freed upon completion, handling memory cleanup effectively.']

