// Insert a new configuration into the list
void insert_config(TrafficFlowConfig** head, uint64_t imsi, int qci, uint32_t arp) {
    pthread_mutex_lock(&list_lock);

    if (!is_valid_imsi(imsi) || !is_unique_imsi(*head, imsi) || (qci < 1 || qci > 254)) {
        pthread_mutex_unlock(&list_lock);
        return;
    }

    TrafficFlowConfig* new_node = malloc(sizeof(TrafficFlowConfig));
    if (!new_node) {
        pthread_mutex_unlock(&list_lock);
        return;
    }
    new_node->imsi = imsi;
    new_node->qci = qci;
    new_node->arp = arp;
    new_node->next = *head;
    *head = new_node;

    pthread_mutex_unlock(&list_lock);
}

// Validate IMSI range
int is_valid_imsi(uint64_t imsi) {
    return (imsi >= IMSI_MIN && imsi <= IMSI_MAX);
}

// Check for unique IMSI in the list
int is_unique_imsi(TrafficFlowConfig* head, uint64_t imsi) {
    while (head != NULL) {
        if (head->imsi == imsi) return 0;
        head = head->next;
    }
    return 1;
}

// Generate a unique ARP tag
uint32_t generate_unique_arp(TrafficFlowConfig* head) {
    uint32_t arp;
    int is_unique;

    do {
        arp = rand() % UINT32_MAX;
        is_unique = 1;

        for (TrafficFlowConfig* node = head; node != NULL; node = node->next) {
            if (node->arp == arp) {
                is_unique = 0;
                break;
            }
        }
    } while (!is_unique);

    return arp;
}

// Compact the list to remove unused nodes
void compact_list(TrafficFlowConfig** head) {
    pthread_mutex_lock(&list_lock);

    TrafficFlowConfig* prev = NULL;
    TrafficFlowConfig* current = *head;

    while (current != NULL) {
        if (/* condition for unused node */) { // Define your own condition
            TrafficFlowConfig* next_node = current->next;
            free(current);
            if (prev == NULL) {
                *head = next_node;
            } else {
                prev->next = next_node;
            }
        } else {
            prev = current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list_lock);
}

// Serialize the list to a file
void serialize_list(const TrafficFlowConfig* head, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    while (head != NULL) {
        fwrite(head, sizeof(TrafficFlowConfig), 1, file);
        head = head->next;
    }

    fclose(file);
}

// Deserialize the list from a file
TrafficFlowConfig* deserialize_list(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return NULL;

    TrafficFlowConfig* head = NULL, *tail = NULL;

    TrafficFlowConfig node;
    while (fread(&node, sizeof(TrafficFlowConfig), 1, file)) {
        TrafficFlowConfig* new_node = malloc(sizeof(TrafficFlowConfig));
        if (!new_node) break;

        *new_node = node;
        new_node->next = NULL;

        if (tail == NULL) head = tail = new_node;
        else {
            tail->next = new_node;
            tail = new_node;
        }
    }

    fclose(file);
    return head;
}

// Example usage
int main() {
    TrafficFlowConfig* list = init_traffic_flow_list();

    // Insert configurations (example)
    insert_config(&list, 1234567890, 5, generate_unique_arp(list));
    insert_config(&list, 9876543210, 10, generate_unique_arp(list));

    // Serialize and Deserialize
    serialize_list(list, "config.dat");
    TrafficFlowConfig* restored_list = deserialize_list("config.dat");

    // Compact list if needed
    compact_list(&restored_list);

    return 0;
}
