} record;

int allocate_and_initialize(int offset_size, int key_size, int record_size) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;

    size_t offsets_memory = sizeof(long) * offset_size;
    size_t keys_memory = sizeof(int) * key_size;
    size_t records_memory = sizeof(record) * record_size + (RECORD_STRING_MAX_LENGTH + 1) * record_size; // Include string memory

    if (offsets_memory + keys_memory + records_memory > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Error: Requested memory exceeds maximum limit of 1 MB\n");
        return -1;
    }

    offsets = aligned_alloc(8, offsets_memory);
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        goto cleanup;
    }

    keys = aligned_alloc(8, keys_memory);
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free(offsets);
        goto cleanup;
    }

    records = aligned_alloc(8, records_memory);
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(keys);
        free(offsets);
        goto cleanup;
    }

    // Simulate integration with external data source for keys
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < key_size && i < record_size; ++i) {
