    }
    pthread_mutex_unlock(&mutex);

    // Initialize records
    for (int i = 0; i < record_size; ++i) {
        records[i].value = i;
        snprintf(records[i].str, RECORD_STRING_MAX_LENGTH + 1, "Record_%d", i);
    }

    // Return the number of successfully initialized records or -1 on failure
    return record_size;

cleanup:
    free(offsets);
    free(keys);
    free(records);

    pthread_mutex_destroy(&mutex);
    return -1;
}

int main() {
