#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    unsigned long timestamp;
    int sourceID;
    size_t payloadLength;
} DataPacket;

typedef struct {
    DataPacket *packets;
    size_t count;
    size_t maxPackets;
    size_t totalPayloadSize;
    size_t payloadThreshold;
    pthread_mutex_t mutex;
} PacketManager;

int initializePacketManager(PacketManager *manager, size_t maxPackets, size_t payloadThreshold) {
    if (maxPackets == 0 || payloadThreshold == 0) return -1;

    manager->packets = NULL;
    manager->count = 0;
    manager->maxPackets = maxPackets;
    manager->totalPayloadSize = 0;
    manager->payloadThreshold = payloadThreshold;

    if (pthread_mutex_init(&manager->mutex, NULL) != 0)
        return -1;

    return 0;
}

void cleanupPacketManager(PacketManager *manager) {
    pthread_mutex_lock(&manager->mutex);
    free(manager->packets);
    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);

    manager->packets = NULL;
    manager->count = 0;
    manager->totalPayloadSize = 0;
}

int addPacket(PacketManager *manager, DataPacket newPacket) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->count >= manager->maxPackets ||
        manager->totalPayloadSize + newPacket.payloadLength > manager->payloadThreshold)
    {
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    // Resize the packet array
    DataPacket *newArray = realloc(manager->packets, (manager->count + 1) * sizeof(DataPacket));
    if (!newArray) {
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }
    manager->packets = newArray;

    // Add new packet
    manager->packets[manager->count] = newPacket;
    manager->totalPayloadSize += newPacket.payloadLength;
    manager->count++;

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

