#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_CACHE_SIZE 100
#define ERROR_CODE -1

typedef struct {
    int value;
    long offset;
    void* metadata;
    time_t timestamp;
} record;

typedef struct {
    int key;
    char* name; // Example field for dataset source tracking
} metadata;

// Cache node structure for caching mechanism
typedef struct cache_node {
    record* rec;
    struct cache_node* next;
} cache_node;

typedef struct {
    cache_node** entries;
    size_t size;
    size_t capacity;
} cache;

cache* create_cache(size_t capacity) {
    cache* c = (cache*)malloc(sizeof(cache));
    if (!c) return NULL;

    c->entries = (cache_node**)calloc(capacity, sizeof(cache_node*));
    if (!c->entries) {
        free(c);
        return NULL;
    }

    c->size = 0;
    c->capacity = capacity;
    return c;
}

void cache_put(cache* c, record* rec) {
    if (c->size >= c->capacity) return; // Simplified eviction policy

    size_t index = rec->value % c->capacity;
    cache_node* node = (cache_node*)malloc(sizeof(cache_node));
    if (!node) return;

    node->rec = rec;
    node->next = c->entries[index];
    c->entries[index] = node;
    c->size++;
}

record* cache_get(cache* c, int value) {
    size_t index = value % c->capacity;
    cache_node* node = c->entries[index];

    while (node) {
        if (node->rec->value == value) {
            return node->rec;
        }
        node = node->next;
    }

    return NULL;
}

void free_cache(cache* c) {
    for (size_t i = 0; i < c->capacity; ++i) {
        cache_node* node = c->entries[i];
        while (node) {
            cache_node* next = node->next;
            free(node);
            node = next;
        }
    }
    free(c->entries);
    free(c);
}

typedef struct dataset {
    long* offsets;
    int* keys;
    record* records;
    metadata** metadata_ptrs;
    time_t* timestamps;
    size_t num_records;
} dataset;

void log(const char* message) {
    printf("%s\n", message);
}

int process_datasets(int num_datasets, size_t* num_records_per_dataset, int min_value, int max_value) {
    srand(time(NULL));
    cache* record_cache = create_cache(MAX_CACHE_SIZE);
    if (!record_cache) return ERROR_CODE;

    dataset* datasets = (dataset*)malloc(num_datasets * sizeof(dataset));
    if (!datasets) {
        free_cache(record_cache);
        return ERROR_CODE;
    }

    for (int d = 0; d < num_datasets; ++d) {
        log("Starting processing of dataset");

        size_t num_records = num_records_per_dataset[d];
        datasets[d].offsets = (long*)malloc(num_records * sizeof(long));
        datasets[d].keys = (int*)malloc(num_records * sizeof(int));
        datasets[d].records = (record*)malloc(num_records * sizeof(record));
        datasets[d].metadata_ptrs = (metadata**)malloc(num_records * sizeof(metadata*));
        datasets[d].timestamps = (time_t*)malloc(num_records * sizeof(time_t));

        if (!datasets[d].offsets || !datasets[d].keys || !datasets[d].records ||
            !datasets[d].metadata_ptrs || !datasets[d].timestamps) {
            log("Memory allocation failure");
            free_cache(record_cache);

            for (int i = 0; i <= d; ++i) {
                if (datasets[i].offsets) free(datasets[i].offsets);
                if (datasets[i].keys) free(datasets[i].keys);
                if (datasets[i].records) free(datasets[i].records);
                if (datasets[i].metadata_ptrs) free(datasets[i].metadata_ptrs);
                if (datasets[i].timestamps) free(datasets[i].timestamps);
            }

            free(datasets);
            return ERROR_CODE;
        }

        for (size_t i = 0; i < num_records; ++i) {
            datasets[d].offsets[i] = rand();
            datasets[d].keys[i] = rand() % (max_value - min_value + 1) + min_value;
            datasets[d].records[i].value = datasets[d].keys[i];
            datasets[d].records[i].offset = datasets[d].offsets[i];
            datasets[d].metadata_ptrs[i] = malloc(sizeof(metadata));
            if (!datasets[d].metadata_ptrs[i]) {
                log("Memory allocation failure");
                free_cache(record_cache);

                for (int j = 0; j <= d; ++j) {
                    if (datasets[j].offsets) free(datasets[j].offsets);
                    if (datasets[j].keys) free(datasets[j].keys);
                    if (datasets[j].records) free(datasets[j].records);
                    if (datasets[j].metadata_ptrs) free(datasets[j].metadata_ptrs);
                    for (size_t k = 0; k < num_records_per_dataset[j]; ++k)
                        free(datasets[j].metadata_ptrs[k]);
                    if (datasets[j].timestamps) free(datasets[j].timestamps);
                }

                free(datasets);
                return ERROR_CODE;
            }

            datasets[d].records[i].metadata = datasets[d].metadata_ptrs[i];
            datasets[d].records[i].timestamp = time(NULL);

            cache_put(record_cache, &datasets[d].records[i]);
        }

        // Simple sorting algorithm (Bubble sort for demonstration)
        for (size_t i = 0; i < num_records - 1; ++i) {
            for (size_t j = 0; j < num_records - i - 1; ++j) {
                if (datasets[d].records[j].value > datasets[d].records[j + 1].value) {
                    record temp = datasets[d].records[j];
                    datasets[d].records[j] = datasets[d].records[j + 1];
                    datasets[d].records[j + 1] = temp;

                    int key_temp = datasets[d].keys[j];
                    datasets[d].keys[j] = datasets[d].keys[j + 1];
                    datasets[d].keys[j + 1] = key_temp;

                    long offset_temp = datasets[d].offsets[j];
                    datasets[d].offsets[j] = datasets[d].offsets[j + 1];
                    datasets[d].offsets[j + 1] = offset_temp;
                }
            }
        }

        log("Finished processing of dataset");
    }

    // Cleanup
    free_cache(record_cache);

    for (int d = 0; d < num_datasets; ++d) {
        free(datasets[d].offsets);
        free(datasets[d].keys);
        free(datasets[d].records);
        for (size_t i = 0; i < datasets[d].num_records; ++i)
            free(datasets[d].metadata_ptrs[i]);
        free(datasets[d].metadata_ptrs);
        free(datasets[d].timestamps);
    }

    free(datasets);
    return 0;
}

int main() {
    size_t num_records_per_dataset[] = {5, 10};
    int result = process_datasets(2, num_records_per_dataset, 1, 100);

    if (result == ERROR_CODE) {
        printf("An error occurred during processing.\n");
    } else {
        printf("Datasets processed successfully.\n");
    }

    return 0;
}
```

This code implements a function to manage and process multiple datasets with the specified requirements. It includes dynamic memory allocation, initialization of components for each dataset, sorting records by keys, caching frequently accessed records, logging, and handling memory allocation failures gracefully. The cache uses a simple eviction policy based on size limits.']

