#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define IMSI_MIN 1000000000
#define IMSI_MAX 9999999999
#define QCI_MIN 1
#define QCI_MAX 254

typedef struct TrafficFlowConfig {
    long imsi;
    int qci;
    char arp[16];
    int latency; // in milliseconds
    struct TrafficFlowConfig* next;
} TrafficFlowConfig;

// Global variables
TrafficFlowConfig* head = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
int total_lookup_count = 0;
int total_latency_time = 0;

// Function prototypes
void initialize_list();
int validate_imsi(long imsi);
int generate_unique_arp(char *arp, size_t size);
TrafficFlowConfig* create_node(long imsi, int qci, char* arp, int latency);
void insert_config(TrafficFlowConfig* new_node);
void delete_config_by_imsi(long imsi);
void compact_list();
void update_latency(int latency);
int lookup_config(long imsi);
void adjust_arp_logic_based_on_network_conditions();
void serialize_to_file(const char *filename);
TrafficFlowConfig* deserialize_from_file(const char *filename);
void log_change(const char* message);

// Function implementations

void initialize_list() {
    pthread_mutex_lock(&list_mutex);
    compact_list(); // Ensure no memory leaks
    pthread_mutex_unlock(&list_mutex);
}

int validate_imsi(long imsi) {
    return (imsi >= IMSI_MIN && imsi <= IMSI_MAX);
}

int generate_unique_arp(char *arp, size_t size) {
    char possible_chars[] = "0123456789ABCDEF";
    int is_unique;

    do {
        is_unique = 1;
        for (size_t i = 0; i < size - 1; ++i) {
            arp[i] = possible_chars[rand() % (sizeof(possible_chars) - 1)];
        }
        arp[size - 1] = '\0';

        pthread_mutex_lock(&list_mutex);
        TrafficFlowConfig* current = head;
        while (current != NULL) {
            if (strcmp(current->arp, arp) == 0) {
                is_unique = 0;
                break;
            }
            current = current->next;
        }
        pthread_mutex_unlock(&list_mutex);

    } while (!is_unique);

    return 1;
}

TrafficFlowConfig* create_node(long imsi, int qci, char* arp, int latency) {
    TrafficFlowConfig* new_node = (TrafficFlowConfig*)malloc(sizeof(TrafficFlowConfig));
    if (!new_node) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    new_node->imsi = imsi;
    new_node->qci = qci;
    strncpy(new_node->arp, arp, sizeof(new_node->arp) - 1);
    new_node->latency = latency;
    new_node->next = NULL;

    log_change("Created new node");

    return new_node;
}

void insert_config(TrafficFlowConfig* new_node) {
    pthread_mutex_lock(&list_mutex);

    if (!head || head->imsi > new_node->imsi) {
        new_node->next = head;
        head = new_node;
    } else {
        TrafficFlowConfig *current = head, *prev = NULL;
        while (current && current->imsi < new_node->imsi) {
            prev = current;
            current = current->next;
        }
        if (!current || strcmp(current->arp, new_node->arp) != 0) {
            prev->next = new_node;
            new_node->next = current;
        } else {
            free(new_node); // Duplicate ARP found
        }
    }

    pthread_mutex_unlock(&list_mutex);
}

void delete_config_by_imsi(long imsi) {
    pthread_mutex_lock(&list_mutex);

    TrafficFlowConfig *current = head, *prev = NULL;
    while (current && current->imsi != imsi) {
        prev = current;
        current = current->next;
    }

    if (current) {
        if (!prev) { // Node to delete is the head
            head = current->next;
        } else {
            prev->next = current->next;
        }
        free(current);
        log_change("Deleted node by IMSI");
    }

    pthread_mutex_unlock(&list_mutex);
}

void compact_list() {
    TrafficFlowConfig *current, *prev = NULL, *temp;

    pthread_mutex_lock(&list_mutex);

    current = head;
    while (current) {
        if (!current->next || strcmp(current->arp, current->next->arp) != 0) {
            prev = current;
            current = current->next;
        } else {
            temp = current->next;
            prev->next = temp->next; // Remove duplicate
            free(temp);
            log_change("Compacted list");
        }
    }

    pthread_mutex_unlock(&list_mutex);
}

void update_latency(int latency) {
    total_lookup_count++;
    total_latency_time += latency;
}

int lookup_config(long imsi) {
    int start_time = clock();

    pthread_mutex_lock(&list_mutex);

    TrafficFlowConfig* current = head;
    while (current) {
        if (current->imsi == imsi) {
            int end_time = clock();
            update_latency(end_time - start_time);
            pthread_mutex_unlock(&list_mutex);
            return 1; // Found
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list_mutex);

    return 0; // Not found
}

void adjust_arp_logic_based_on_network_conditions() {
    // Placeholder for ARP adjustment logic based on network conditions
    log_change("Adjusted ARP logic");
}

void serialize_to_file(const char *filename) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    pthread_mutex_lock(&list_mutex);

    TrafficFlowConfig* current = head;
    while (current) {
        fprintf(file, "%ld,%d,%s,%d\n", current->imsi, current->qci, current->arp, current->latency);
        current = current->next;
    }

    pthread_mutex_unlock(&list_mutex);

    fclose(file);
    log_change("Serialized list to file");
}

TrafficFlowConfig* deserialize_from_file(const char *filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    pthread_mutex_lock(&list_mutex);

    compact_list(); // Clear existing data
    head = NULL;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        long imsi;
        int qci, latency;
        char arp[16];

        if (sscanf(line, "%ld,%d,%15[^,\n],%d", &imsi, &qci, arp, &latency) == 4) {
            char* unique_arp = malloc(strlen(arp) + 1);
            strcpy(unique_arp, arp);

            TrafficFlowConfig* new_node = create_node(imsi, qci, unique_arp, latency);
            insert_config(new_node);
            free(unique_arp);
        }
    }

    pthread_mutex_unlock(&list_mutex);

    fclose(file);
    log_change("Deserialized list from file");

    return head;
}

void log_change(const char* message) {
    FILE* log_file = fopen("traffic_flow_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    fprintf(log_file, "%s: %s\n", ctime(&now), message);

    fclose(log_file);
}

int main() {
    srand(time(NULL));

    initialize_list();

    // Example usage
    char arp[16];
    generate_unique_arp(arp, sizeof(arp));

    TrafficFlowConfig* new_config = create_node(1234567890L, 5, arp, 20);
    insert_config(new_config);

    if (lookup_config(1234567890L)) {
        printf("Configuration found.\n");
    } else {
        printf("Configuration not found.\n");
    }

    serialize_to_file("traffic_flow_config.txt");

    TrafficFlowConfig* deserialized_head = deserialize_from_file("traffic_flow_config.txt");

    delete_config_by_imsi(1234567890L);

    compact_list();

    return 0;
}
