    int *keys;
    record *records;
    size_t num_records;
} data_structure;

typedef enum {
    SEED_FIXED,
    SEED_TIMESTAMP
} seed_source_t;

typedef struct {
    int min_value;
    int max_value;
    seed_source_t seed_source;
    unsigned long fixed_seed;
} config_t;

config_t load_config(const char *filename) {
    config_t config = {0, 100, SEED_FIXED, 12345}; // Default values
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Configuration file not found. Using default settings.\n");
        return config;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        if (sscanf(line, "min_value %d", &config.min_value) == 1 ||
            sscanf(line, "max_value %d", &config.max_value) == 1 ||
            sscanf(line, "seed_source %d", &(int*)&config.seed_source) == 1 ||
            sscanf(line, "fixed_seed %lu", &config.fixed_seed) == 1) {
            // Successfully parsed
        } else {
            fprintf(stderr, "Malformed configuration line: %s", line);
        }
    }

    fclose(file);
    return config;
}

unsigned long generate_seed(config_t *config) {
    if (config->seed_source == SEED_TIMESTAMP) {
        return time(NULL);
    } else {
        return config->fixed_seed;
    }
}

void populate_records(data_structure *ds, unsigned long seed) {
    srand(seed);
    for (size_t i = 0; i < ds->num_records; ++i) {
        ds->records[i].value = rand() % (ds->num_records + 1); // Uniform distribution
    }
}

void execute_js(v8::Isolate* isolate, const char* code) {
    v8::HandleScope handle_scope(isolate);
    v8::Local<v8::Context> context = v8::Context::New(isolate);
    v8::Context::Scope context_scope(context);

    v8::Local<v8::String> source = v8::String::NewFromUtf8Literal(isolate, code).ToLocalChecked();
    v8::Local<v8::Script> script = v8::Script::Compile(source).ToLocalChecked();

    if (script.IsEmpty()) {
        fprintf(stderr, "JavaScript code failed to compile.\n");
        return;
    }

    v8::Local<v8::Value> result = script->Run(context);
    if (result.IsEmpty()) {
        fprintf(stderr, "JavaScript code execution failed.\n");
    }
}

void free_resources(data_structure *ds) {
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
}

data_structure* initialize_data(size_t num_records) {
    data_structure *ds = malloc(sizeof(data_structure));
    if (!ds) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    ds->num_records = num_records;
    ds->offsets = malloc(num_records * sizeof(long));
    ds->keys = malloc(num_records * sizeof(int));
    ds->records = malloc(num_records * sizeof(record));

    if (!ds->offsets || !ds->keys || !ds->records) {
        free_resources(ds);
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    config_t config = load_config("config.txt");
    unsigned long seed = generate_seed(&config);

    populate_records(ds, seed);

    // Example JavaScript code
    const char* js_code = 
        "function transformRecords(records) {"
        "  for (let i = 0; i < records.length; i++) {"
        "    if (records[i].value % 2 === 0) {"
        "      records[i].value *= 2;"
        "    } else {"
        "      records[i].value += 1;"
        "    }"
        "  }"
        "}";

    v8::V8::InitializeICUDefaultLocation("");
    v8::V8::InitializeExternalStartupData("");
    v8::UniquePtr<v8::Platform> platform(v8::platform::NewDefaultPlatform());
    v8::V8::InitializePlatform(platform.get());
    v8::V8::Initialize();

    v8::Isolate::CreateParams create_params;
    create_params.array_buffer_allocator = v8::ArrayBuffer::Allocator::NewDefaultAllocator();
    v8::Isolate* isolate = v8::Isolate::New(create_params);
    execute_js(isolate, js_code);

    v8::V8::Dispose();
    v8::V8::ShutdownPlatform();
    delete create_params.array_buffer_allocator;

    return ds;
}

void serialize_records(const data_structure *ds) {
    FILE *file = fopen("records.bin", "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing.\n");
        return;
    }

    fwrite(ds->records, sizeof(record), ds->num_records, file);
    fclose(file);
}

int main() {
    size_t num_records = 1000;
    data_structure *ds = initialize_data(num_records);

    if (ds) {
        serialize_records(ds);
        free_resources(ds);
    }

    return 0;
}
