#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the structure for RX_UE_INFORMATION_TAG
typedef struct {
    uint16_t rnti;
} RX_UE_INFORMATION_TAG;

// Define the CRC_INDICATION_REL8_TAG with random initialization
typedef struct {
    uint32_t crc_value;
} CRC_INDICATION_REL8_TAG;

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_CAPACITY 10

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} DynamicArray;

// Initialize dynamic array
void init_dynamic_array(DynamicArray *da) {
    da->capacity = INITIAL_CAPACITY;
    da->count = 0;
    da->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(da->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&da->mutex, NULL);
}

// Resize dynamic array
void resize_dynamic_array(DynamicArray *da) {
    size_t new_capacity = da->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_array) {
        da->array = new_array;
        da->capacity = new_capacity;
    } else {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

// Add an element to the dynamic array
void add_element(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&da->mutex);

    if (da->count == da->capacity) {
        resize_dynamic_array(da);
    }

    da->array[da->count++] = pdu;

    pthread_mutex_unlock(&da->mutex);
}

// Randomly initialize CRC value
void randomize_crc(CRC_INDICATION_REL8_TAG *crc_tag) {
    srand(time(NULL));
    crc_tag->crc_value = rand();
}

// Populate dynamic array with initialized structures
void populate_dynamic_array(DynamicArray *da, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.rx_ue_information_tag.rnti = i + 1; // Example RNTI
        randomize_crc(&pdu.crc_indication_rel8_tag);
        add_element(da, pdu);
    }
}

// Delete dynamic array and free resources
void delete_dynamic_array(DynamicArray *da) {
    pthread_mutex_lock(&da->mutex);

    if (da->array) {
        free(da->array);
        da->array = NULL;
        da->capacity = 0;
        da->count = 0;
    }

    pthread_mutex_unlock(&da->mutex);
    pthread_mutex_destroy(&da->mutex);
}

// Event handler stub
void event_handler(void *data, size_t len) {
    // Process events here
}

int main() {
    DynamicArray da;
    init_dynamic_array(&da);

    populate_dynamic_array(&da, 15); // Example population

    delete_dynamic_array(&da);
    return 0;
}
