#define MAX_STRUCTS 1000
#define CACHE_SIZE 128

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    float CRCFLAG; // float value within specified range
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    size_t key;
    NFAPI_CRC_INDICATION_PDU_T data;
} CachedMetadata;

static CachedMetadata cache[CACHE_SIZE];
static unsigned int cache_hits = 0, cache_misses = 0;

unsigned long hash_function(unsigned index, time_t sys_time) {
    return (index * sys_time + (rand() % 100)) & 0xFFFFFFFF;
}

bool is_key_unique(unsigned long key, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (cache[i].key == key) return false;
    }
    return true;
}

void initialize_cache() {
    memset(cache, 0, sizeof(CachedMetadata) * CACHE_SIZE);
}

CachedMetadata* fetch_metadata(size_t index, unsigned long& generated_key) {
    time_t sys_time = time(NULL);
    generated_key = hash_function(index, sys_time);

    for (size_t i = 0; i < CACHE_SIZE; ++i) {
        if (cache[i].key == generated_key) {
            cache_hits++;
            return &cache[i];
        }
    }

    cache_misses++;
    for (size_t i = 0; i < CACHE_SIZE; ++i) {
        if (cache[i].key == 0) {
            cache[i].key = generated_key;
            return &cache[i];
        }
    }

    // Fallback: replace the oldest cached entry
    for (size_t i = 0; i < CACHE_SIZE; ++i) {
        if (cache[i].key != 0 && is_key_unique(generated_key, CACHE_SIZE)) {
            cache[i].key = generated_key;
            return &cache[i];
        }
    }

    // In a real implementation, additional logging and error handling would be done here
    fprintf(stderr, "Cache is full. Cannot fetch metadata.\n");
    exit(EXIT_FAILURE);
}

void serialize_to_file(NFAPI_CRC_INDICATION_PDU_T* structures, size_t count) {
    FILE *file = fopen("serialized_data.bin", "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fwrite(&count, sizeof(size_t), 1, file);
    float total_crcflag = 0;

    for (size_t i = 0; i < count; ++i) {
        fwrite(&structures[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        total_crcflag += structures[i].CRCFLAG;
    }

    fwrite(&total_crcflag, sizeof(float), 1, file);

    fclose(file);
}

NFAPI_CRC_INDICATION_PDU_T* manage_dynamic_list(size_t num_elements) {
    if (num_elements > MAX_STRUCTS) {
        fprintf(stderr, "Requested number of elements exceeds the maximum limit.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *structures = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structures) {
        perror("Memory allocation failed");
        return NULL;
    }

    initialize_cache();

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < num_elements; ++i) {
        structures[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        structures[i].RNTI = rand() % 10000;
        structures[i].CRC_INDICATION_REL8_TAG = rand() % 10000;

        unsigned long key;
        CachedMetadata* metadata = fetch_metadata(i, key);

        while (!is_key_unique(key, num_elements)) {
            fprintf(stderr, "Duplicate key detected: %lu. Retrying...\n", key);
            metadata->key = hash_function(i, time(NULL));
            key = metadata->key;
        }

        structures[i].CRCFLAG = (float)(rand() / (RAND_MAX + 1.0) * 100.0); // Random float in [0, 100]
    }

    serialize_to_file(structures, num_elements);

    printf("Cache Hits: %u\n", cache_hits);
    printf("Cache Misses: %u\n", cache_misses);

    return structures;
}

size_t allocated_size(size_t num_elements) {
    return num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T);
}

void memory_profiler() {
