typedef struct {
    int value;
} record;

#define INITIAL_SIZE 10

typedef struct {
    long *offsets;
    size_t offset_size;
    pthread_mutex_t offset_lock;

    int *keys;
    size_t key_size;
    pthread_mutex_t key_lock;

    record *records;
    size_t record_size;
    pthread_mutex_t record_lock;
} DataManager;

void initialize_data_manager(DataManager *dm) {
    pthread_mutex_init(&dm->offset_lock, NULL);
    pthread_mutex_init(&dm->key_lock, NULL);
    pthread_mutex_init(&dm->record_lock, NULL);

    dm->offsets = (long *)malloc(INITIAL_SIZE * sizeof(long));
    if (!dm->offsets) { perror("Failed to allocate offsets"); exit(EXIT_FAILURE); }
    dm->offset_size = INITIAL_SIZE;

    dm->keys = (int *)malloc(INITIAL_SIZE * sizeof(int));
    if (!dm->keys) { perror("Failed to allocate keys"); free(dm->offsets); exit(EXIT_FAILURE); }
    dm->key_size = INITIAL_SIZE;

    dm->records = (record *)malloc(INITIAL_SIZE * sizeof(record));
    if (!dm->records) { perror("Failed to allocate records"); free(dm->keys); free(dm->offsets); exit(EXIT_FAILURE); }
    dm->record_size = INITIAL_SIZE;
}

void resize_array(void **array, size_t current_size, size_t new_size, size_t element_size) {
    void *new_array = realloc(*array, new_size * element_size);
    if (!new_array) { perror("Failed to reallocate array"); exit(EXIT_FAILURE); }
    *array = new_array;
}

void manage_memory(DataManager *dm, size_t offset_count, size_t key_count, size_t record_count) {
    pthread_mutex_lock(&dm->offset_lock);
    if (offset_count > dm->offset_size) {
        resize_array((void **)&dm->offsets, dm->offset_size, offset_count, sizeof(long));
        dm->offset_size = offset_count;
    }
    pthread_mutex_unlock(&dm->offset_lock);

    pthread_mutex_lock(&dm->key_lock);
    if (key_count > dm->key_size) {
        resize_array((void **)&dm->keys, dm->key_size, key_count, sizeof(int));
        dm->key_size = key_count;
    }
    pthread_mutex_unlock(&dm->key_lock);

    pthread_mutex_lock(&dm->record_lock);
    if (record_count > dm->record_size) {
        resize_array((void **)&dm->records, dm->record_size, record_count, sizeof(record));
        dm->record_size = record_count;
    }
    pthread_mutex_unlock(&dm->record_lock);
}

void cleanup_data_manager(DataManager *dm) {
    free(dm->offsets);
    free(dm->keys);
    free(dm->records);

    pthread_mutex_destroy(&dm->offset_lock);
    pthread_mutex_destroy(&dm->key_lock);
    pthread_mutex_destroy(&dm->record_lock);
}

int main() {
    DataManager dm;
    initialize_data_manager(&dm);

    // Example usage
    manage_memory(&dm, 15, 20, 25); // Resize arrays as needed

    cleanup_data_manager(&dm);
    return 0;
}
