typedef struct {
    long timestamp;
    float temperature;
    char status;
    int sensorID;
} Sensor;

int is_unique_id(int *ids, int current_size, int new_id) {
    for (int i = 0; i < current_size; ++i) {
        if (ids[i] == new_id)
            return 0;
    }
    return 1;
}

void generate_unique_id(int *ids, int *current_size) {
    int new_id;
    do {
        new_id = rand() % 10000 + 1; // Example range for IDs
    } while (!is_unique_id(ids, *current_size, new_id));
    ids[(*current_size)++] = new_id;
}

void collect_sensor_data(int num_sensors, int duration_seconds, int update_frequency_seconds) {
    if (num_sensors <= 0 || duration_seconds <= 0 || update_frequency_seconds <= 0)
        return;

    Sensor *sensors = NULL;
    size_t sensors_size = 0;
    int *sensor_ids = NULL;
    size_t sensor_ids_size = 0;

    srand((unsigned)time(NULL));

    for (int t = 0; t < duration_seconds; t += update_frequency_seconds) {
        size_t current_num_sensors = num_sensors + sensors_size / sizeof(Sensor);
        Sensor *temp_sensors = realloc(sensors, current_num_sensors * sizeof(Sensor));

        if (!temp_sensors) {
            fprintf(stderr, "Memory allocation failed\n");
            free(sensors);
            free(sensor_ids);
            return;
        }
        sensors = temp_sensors;

        int *temp_sensor_ids = realloc(sensor_ids, sensor_ids_size + current_num_sensors * sizeof(int));
        if (!temp_sensor_ids) {
            fprintf(stderr, "Memory allocation failed\n");
            free(sensors);
            free(sensor_ids);
            return;
        }
        sensor_ids = temp_sensor_ids;

        for (int i = 0; i < num_sensors; ++i) {
            Sensor *sensor = &sensors[sensors_size / sizeof(Sensor) + i];
            generate_unique_id(sensor_ids, &sensor_ids_size);

            sensor->timestamp = time(NULL);
            sensor->temperature = ((float)(rand() % 500 - 250)) / 10.0; // Simulating temperature range from -25.0 to 24.9
            sensor->status = (char)('A' + rand() % 26); // Random status character
            sensor->sensorID = sensor_ids[sensor_ids_size - 1];
        }

        sensors_size += num_sensors * sizeof(Sensor);
    }

    printf("Sensor data collection completed.\n");

    free(sensors);
    free(sensor_ids);
}

int main() {
    collect_sensor_data(5, 60, 10); // Collecting data for 5 sensors over 60 seconds at every 10-second interval
    return 0;
}
