    list->capacity = 10; // Initial capacity
    list->accounts = (UserAccount**)malloc(list->capacity * sizeof(UserAccount*));

    pthread_mutex_init(&list->lock, NULL);
    pthread_rwlock_init(&list->rwlock, NULL);

    for (int i = 0; i < MAX_USERS; ++i) {
        update_count[i] = 0;
        last_update_time[i] = time(NULL);
    }

    return list;
}

void destroy_user_list(UserList *list) {
    if (!list) return;

    pthread_mutex_destroy(&list->lock);
    pthread_rwlock_destroy(&list->rwlock);

    for (size_t i = 0; i < list->size; ++i) {
        free(list->accounts[i]->name);
        free(list->accounts[i]->email);
        free(list->accounts[i]->password);
        free(list->accounts[i]->sub_action);
        free(list->accounts[i]->profile_picture_url);
        free(list->accounts[i]);
    }
    free(list->accounts);
    free(list);
}

void resize_user_list(UserList *list) {
    size_t new_capacity = list->capacity * 2;
    UserAccount **new_accounts = (UserAccount**)realloc(list->accounts, new_capacity * sizeof(UserAccount*));

    if (!new_accounts) return; // Handle realloc failure

    list->accounts = new_accounts;
    list->capacity = new_capacity;
}

void validate_user_data(UserAccount *account) {
    if (!account || !account->user_id || !account->name || !account->email || !account->password)
        exit(EXIT_FAILURE); // In a real system, handle this more gracefully
}

int authenticate_user(const char *email, const char *password) {
