}

void log_operation(const char *operation, int user_id, const char *error) {
    time_t now = time(NULL);
    printf("[%ld] Operation: %s, User ID: %d, Error: %s\n", (long)now, operation, user_id, error ? error : "None");
}

int update_quota(UserList *list, int user_id) {
    time_t current_time = time(NULL);

    if (current_time - list->last_update_time[user_id] > 86400) { // Reset daily quota
        list->update_count[user_id] = 0;
        list->last_update_time[user_id] = current_time;
    }

    return ++list->update_count[user_id] <= QUOTA_LIMIT;
}

json_object* handle_request(UserList *list, UserAccount *account) {
    pthread_rwlock_wrlock(&list->rwlock);

    int authenticated = authenticate_user(account->email, account->password);
    if (!authenticated) {
        pthread_rwlock_unlock(&list->rwlock);
        return json_object_new_string("{\"message\": \"error\"}");
