    if (!update_quota(list, account->user_id)) {
        pthread_rwlock_unlock(&list->rwlock);
        return json_object_new_string("{\"message\": \"quota exceeded\"}");
    }

    if (account->sub_action && strcmp(account->sub_action, "delete") == 0) {
        // Handle deletion
    } else if (account->sub_action && strcmp(account->sub_action, "update_profile_picture") == 0) {
        // Update profile picture logic
    }

    pthread_rwlock_unlock(&list->rwlock);

    return json_object_new_string("{\"message\": \"success\"}");
}

void add_or_update_user(UserList *list, UserAccount *account) {
    validate_user_data(account);

    if (list->size == list->capacity) {
        resize_user_list(list);
    }

    pthread_rwlock_wrlock(&list->rwlock);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->accounts[i]->user_id == account->user_id) {
            // Update existing user logic
            break;
        }
    }

    list->accounts[list->size++] = malloc(sizeof(UserAccount));
    *list->accounts[list->size - 1] = *account;

    pthread_rwlock_unlock(&list->rwlock);
}

