#define INITIAL_SIZE 10
#define CACHE_SIZE 100

// Structure for managing data structures with synchronization
typedef struct {
    long *offsets;
    size_t offset_size;
    pthread_mutex_t offsets_lock;

    int *keys;
    size_t key_size;
    pthread_mutex_t keys_lock;

    record **records; // Array of pointers to records
    size_t record_count;
    pthread_rwlock_t records_rwlock;

    unsigned char *cache[CACHE_SIZE]; // Simple LRU cache
    int cache_usage[CACHE_SIZE];
    pthread_mutex_t cache_lock;
} DataManager;

// Helper function for reallocating arrays with error checking
void *safe_realloc(void *ptr, size_t new_size) {
    void *new_ptr = realloc(ptr, new_size);
    if (!new_ptr && ptr != NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        free(ptr);
        exit(EXIT_FAILURE);
    }
    return new_ptr;
}

// Initialize the data manager
DataManager* init_data_manager(size_t initial_offset_size, size_t initial_key_size, size_t initial_record_count) {
    DataManager *manager = malloc(sizeof(DataManager));
    if (!manager) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&manager->offsets_lock, NULL);
    manager->offsets = calloc(initial_offset_size, sizeof(long));
    if (!manager->offsets) {
        free(manager);
        exit(EXIT_FAILURE);
    }
    manager->offset_size = initial_offset_size;

    pthread_mutex_init(&manager->keys_lock, NULL);
    manager->keys = calloc(initial_key_size, sizeof(int));
    if (!manager->keys) {
        free(manager->offsets);
        free(manager);
        exit(EXIT_FAILURE);
    }
    manager->key_size = initial_key_size;

    pthread_rwlock_init(&manager->records_rwlock, NULL);
    manager->records = calloc(initial_record_count, sizeof(record*));
    if (!manager->records) {
        free(manager->keys);
        free(manager->offsets);
        free(manager);
        exit(EXIT_FAILURE);
    }
    manager->record_count = initial_record_count;

    pthread_mutex_init(&manager->cache_lock, NULL);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        manager->cache[i] = NULL;
        manager->cache_usage[i] = -1;
    }

    return manager;
}

// Free the data manager
void free_data_manager(DataManager *manager) {
    pthread_mutex_lock(&manager->offsets_lock);
    free(manager->offsets);
    pthread_mutex_unlock(&manager->offsets_lock);

    pthread_mutex_lock(&manager->keys_lock);
    free(manager->keys);
    pthread_mutex_unlock(&manager->keys_lock);

    pthread_rwlock_wrlock(&manager->records_rwlock);
    for (size_t i = 0; i < manager->record_count; ++i) {
        if (manager->records[i]) {
            free(manager->records[i]);
        }
    }
    free(manager->records);
    pthread_rwlock_unlock(&manager->records_rwlock);

    pthread_mutex_lock(&manager->cache_lock);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (manager->cache[i]) {
            free(manager->cache[i]);
        }
    }
    pthread_mutex_unlock(&manager->cache_lock);

    pthread_mutex_destroy(&manager->offsets_lock);
    pthread_mutex_destroy(&manager->keys_lock);
    pthread_rwlock_destroy(&manager->records_rwlock);
    pthread_mutex_destroy(&manager->cache_lock);

    free(manager);
}

// Example function for adding a record
void add_record(DataManager *manager, int value) {
    pthread_rwlock_wrlock(&manager->records_rwlock);

    // Resize if necessary
    if (manager->record_count >= manager->offset_size) {
        size_t new_size = manager->offset_size * 2;
        record **new_records = safe_realloc(manager->records, new_size * sizeof(record*));

        for (size_t i = manager->record_count; i < new_size; ++i) {
            new_records[i] = NULL;
        }

        pthread_rwlock_unlock(&manager->records_rwlock);
        pthread_rwlock_wrlock(&manager->records_rwlock);

        free(manager->records);
        manager->records = new_records;
        manager->offset_size = new_size;
    }

    record *rec = malloc(sizeof(record));
    if (!rec) {
        fprintf(stderr, "Memory allocation for record failed\n");
        pthread_rwlock_unlock(&manager->records_rwlock);
        exit(EXIT_FAILURE);
    }

    rec->value = value;
    manager->records[manager->record_count++] = rec;

    pthread_rwlock_unlock(&manager->records_rwlock);
}

// Placeholder function for compressing records
void compress_record(record *rec, unsigned char **compressed_data) {
    // Simple compression using zlib (for illustration)
    uLongf compressed_size = compressBound(sizeof(record));
    *compressed_data = malloc(compressed_size);
    if (!*compressed_data) {
        fprintf(stderr, "Memory allocation for compression failed\n");
        exit(EXIT_FAILURE);
    }

    int res = compress(*compressed_data, &compressed_size, (unsigned char *)rec, sizeof(record));
    if (res != Z_OK) {
        free(*compressed_data);
        *compressed_data = NULL;
    }
