// Placeholder function to decompress records
void decompress_record(unsigned char *compressed_data, size_t compressed_size, record **rec) {
    uLongf decompressed_size = sizeof(record);
    *rec = malloc(decompressed_size);
    if (!*rec) {
        fprintf(stderr, "Memory allocation for decompression failed\n");
        exit(EXIT_FAILURE);
    }

    int res = uncompress((unsigned char *)*rec, &decompressed_size, compressed_data, compressed_size);
    if (res != Z_OK) {
        free(*rec);
        *rec = NULL;
    }
}

// Example function to demonstrate caching
void cache_record(DataManager *manager, record *rec) {
    pthread_mutex_lock(&manager->cache_lock);

    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (manager->cache_usage[i] == -1) { // Empty slot found
            unsigned char *compressed_data;
            compress_record(rec, &compressed_data);
            manager->cache[i] = compressed_data;
            manager->cache_usage[i] = 0; // Mark as used
            break;
        }
    }

    pthread_mutex_unlock(&manager->cache_lock);
}

// Main function for demonstration purposes
int main() {
