#define MAX_LOG_LEVEL 3

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    int CRC_INDICATION_REL8_TAG;
    char CRCFLAG; // '1' or '0'
} NFAPI_CRC_INDICATION_PDU_T;

// External logging interface
typedef void (*log_callback_t)(int level, const char* message);

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t count;
} NFAPI_CRC_LIST_T;

void log_message(int level, const char* format, ...) {
    if (level > MAX_LOG_LEVEL) return;

    va_list args;
    va_start(args, format);
    vprintf(format, args);
    printf("\n");
    va_end(args);
}

int add_pdu(NFAPI_CRC_LIST_T* list, NFAPI_CRC_INDICATION_PDU_T pdu, size_t max_mem_limit, log_callback_t logger) {
    if (list->count >= list->capacity || sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->capacity + 1) > max_mem_limit) {
        logger(2, "Memory limit reached or capacity exceeded.");
        return -1;
    }

    for (size_t i = 0; i < list->count; ++i) {
        if (list->data[i].RNTI == pdu.RNTI) {
            logger(1, "RNTI collision detected. Attempting to find alternative RNTI.");

            // Simple resolution: try next possible RNTI
            int original_rnti = pdu.RNTI;
            for (pdu.RNTI += 1; pdu.RNTI != original_rnti; pdu.RNTI++) {
                int conflict = 0;
                for (size_t j = 0; j < list->count; ++j) {
                    if (list->data[j].RNTI == pdu.RNTI) {
                        conflict = 1;
                        break;
                    }
                }
                if (!conflict) break;
            }

            // If we looped back to the original RNTI, it means no available alternative
            if (pdu.RNTI == original_rnti) {
                logger(0, "Failed to resolve RNTI collision.");
                return -1;
            }
        }
    }

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 4; // Start with capacity of 4 if initially empty
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);

        if (!new_data) {
            logger(0, "Failed to allocate memory for expanding the list.");
            return -1;
        }

        list->data = new_data;
        list->capacity = new_capacity;
    }

    // Set CRCFLAG randomly
    srand(time(NULL) ^ rand()); // Seed with current time and a random value
    pdu.CRCFLAG = (rand() % 2) ? '1' : '0';

    list->data[list->count++] = pdu;
    logger(3, "Successfully added PDU with RNTI: %u", pdu.RNTI);
    return 0;
}

NFAPI_CRC_LIST_T* create_list(size_t initial_capacity, size_t max_mem_limit) {
    NFAPI_CRC_LIST_T* list = malloc(sizeof(NFAPI_CRC_LIST_T));
    if (!list || sizeof(NFAPI_CRC_INDICATION_PDU_T) * initial_capacity > max_mem_limit) {
        return NULL;
    }

    list->data = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->count = 0;

    return list;
}

void free_list(NFAPI_CRC_LIST_T* list) {
    if (list) {
        free(list->data);
        free(list);
    }
}
