#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// NAS message structure definition
typedef struct {
    char imsi[16]; // Assuming IMSI is 15 digits + null terminator
    char tmsi[10];
    // Add other NAS_AUTHENTICATION_REQUEST fields as needed
} NAS_Message;

// UMTS NAS message entry
typedef struct {
    char imsi[16];
    char tmsi[10];
    NAS_Message *nas_messages;
    size_t num_nas_messages;
} UM_TMS_Entry;

// Node for the list of entries
typedef struct EntryNode {
    UM_TMS_Entry entry;
    struct EntryNode* next;
} EntryNode;

// Dynamic list structure with thread safety and scalability in mind
typedef struct {
    EntryNode *head;
    pthread_rwlock_t lock;
} NAS_List;

// Function prototypes
NAS_List* nas_list_create();
void nas_list_destroy(NAS_List *list);
int insert_entry(NAS_List *list, UM_TMS_Entry entry);
int remove_entry_by_imsi(NAS_List *list, const char *imsi);
UM_TMS_Entry* find_entry_by_imsi(NAS_List *list, const char *imsi);
void validate_nas_message(const NAS_Message *message);

// Function implementations

NAS_List* nas_list_create() {
    NAS_List *list = (NAS_List*)malloc(sizeof(NAS_List));
    if (!list) return NULL;

    list->head = NULL;
    pthread_rwlock_init(&list->lock, NULL);
    return list;
}

void nas_list_destroy(NAS_List *list) {
    EntryNode *current = list->head, *next;

    while (current != NULL) {
        next = current->next;
        free(current->entry.nas_messages);
        free(current);
        current = next;
    }

    pthread_rwlock_destroy(&list->lock);
    free(list);
}

int insert_entry(NAS_List *list, UM_TMS_Entry entry) {
    EntryNode *new_node = (EntryNode*)malloc(sizeof(EntryNode));
    if (!new_node) return -1;

    new_node->entry = entry;
    new_node->next = NULL;

    pthread_rwlock_wrlock(&list->lock);

    new_node->next = list->head;
    list->head = new_node;

    pthread_rwlock_unlock(&list->lock);
    return 0;
}

int remove_entry_by_imsi(NAS_List *list, const char *imsi) {
    pthread_rwlock_wrlock(&list->lock);

    EntryNode **current = &(list->head);
    while (*current != NULL) {
        if (strncmp((*current)->entry.imsi, imsi, 16) == 0) {
            EntryNode *to_delete = *current;
            *current = to_delete->next;
            free(to_delete->entry.nas_messages);
            free(to_delete);
            pthread_rwlock_unlock(&list->lock);
            return 0;
        }
        current = &((*current)->next);
    }

    pthread_rwlock_unlock(&list->lock);
    return -1; // Entry not found
}

UM_TMS_Entry* find_entry_by_imsi(NAS_List *list, const char *imsi) {
    pthread_rwlock_rdlock(&list->lock);

    EntryNode *current = list->head;
    while (current != NULL) {
        if (strncmp(current->entry.imsi, imsi, 16) == 0) {
            pthread_rwlock_unlock(&list->lock);
            return &(current->entry);
        }
        current = current->next;
    }

    pthread_rwlock_unlock(&list->lock);
    return NULL; // Entry not found
}

void validate_nas_message(const NAS_Message *message) {
    if (!message || strlen(message->imsi) != 15 || strlen(message->tmsi) != 9) {
        fprintf(stderr, "Invalid NAS message: IMSI or TMSI format incorrect\n");
        // Implement more detailed validation as necessary
    }
}

// Usage example (for testing purposes)
int main() {
    NAS_List *list = nas_list_create();

    UM_TMS_Entry entry;
    strcpy(entry.imsi, "123456789012345");
    strcpy(entry.tmsi, "9876543210");
    entry.num_nas_messages = 1;
    entry.nas_messages = (NAS_Message*)malloc(sizeof(NAS_Message));
    strcpy(entry.nas_messages[0].imsi, "123456789012345");
    strcpy(entry.nas_messages[0].tmsi, "9876543210");

    insert_entry(list, entry);

    UM_TMS_Entry *found_entry = find_entry_by_imsi(list, "123456789012345");
    if (found_entry) {
        printf("Entry found: IMSI=%s, TMSI=%s\n", found_entry->imsi, found_entry->tmsi);
    }

    remove_entry_by_imsi(list, "123456789012345");

    nas_list_destroy(list);

    return 0;
}
