#include <string.h>

typedef struct {
    int id;
    char *value; // Pointer to a string representing user's name
} Item;

// Function prototypes
Item* initializeItemList(size_t count, const char* dictionaryFile);
void freeItemList(Item* itemList, size_t itemCount);

// Helper functions
int readFileLines(const char* filename, char*** lines, size_t* lineCount);
char* generateUniqueNames(char** names, size_t nameCount, size_t requiredCount);

Item* initializeItemList(size_t count, const char* dictionaryFile) {
    if (count == 0 || dictionaryFile == NULL) return NULL;

    // Read the user names from the file
    char **userNames = NULL;
    size_t userNameCount = 0;
    if (!readFileLines(dictionaryFile, &userNames, &userNameCount)) {
        fprintf(stderr, "Error reading dictionary file.\n");
        return NULL;
    }

    if (userNameCount < count) {
        fprintf(stderr, "Not enough unique names available in the dictionary file.\n");
        free(userNames);
        return NULL;
    }

    // Generate a list of required unique user names
    char *uniqueUserNames = generateUniqueNames(userNames, userNameCount, count);
    if (uniqueUserNames == NULL) {
        fprintf(stderr, "Error generating unique user names.\n");
        free(userNames);
        return NULL;
    }

    free(userNames);

    // Allocate memory for the list of items
    Item *itemList = (Item*)malloc(count * sizeof(Item));
    if (!itemList) {
        free(uniqueUserNames);
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    // Initialize each item with a unique id and user name
    for (size_t i = 0; i < count; ++i) {
        itemList[i].id = i + 1;

        size_t nameLen = strlen(uniqueUserNames + i * MAX_NAME_LENGTH);
        char *nameCopy = (char*)malloc(nameLen + 1); // +1 for null-terminator
        if (!nameCopy) {
            fprintf(stderr, "Memory allocation failed.\n");
            freeItemList(itemList, count);
            free(uniqueUserNames);
            return NULL;
        }

        strncpy(nameCopy, uniqueUserNames + i * MAX_NAME_LENGTH, nameLen);
        nameCopy[nameLen] = '\0';

        itemList[i].value = nameCopy;
    }

    free(uniqueUserNames);

    // Successfully initialized the list
    return itemList;
}

void freeItemList(Item* itemList, size_t itemCount) {
    if (!itemList) return;

    for (size_t i = 0; i < itemCount; ++i) {
        if (itemList[i].value) {
            free(itemList[i].value);
        }
    }

    free(itemList);
}

// Helper function to read lines from a file into an array
int readFileLines(const char* filename, char*** lines, size_t* lineCount) {
    FILE *file = fopen(filename, "r");
    if (!file) return 0;

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    rewind(file);

    char *buffer = (char*)malloc(fileSize + 1);
    if (!buffer) {
        fclose(file);
        return 0;
    }

    fread(buffer, 1, fileSize, file);
    buffer[fileSize] = '\0';

    char *line = strtok(buffer, "\n");
    size_t count = 0;
    while (line) {
        ++count;
        line = strtok(NULL, "\n");
    }

    *lines = (char**)malloc(count * sizeof(char*));
    if (!(*lines)) {
        free(buffer);
        fclose(file);
        return 0;
    }

    rewind(file);
    fread(buffer, 1, fileSize, file);

    char *lineStart = buffer;
    for (size_t i = 0; i < count; ++i) {
        (*lines)[i] = lineStart;
        lineStart = strchr(lineStart, '\n') + 1;
    }

    free(buffer);
    fclose(file);

    *lineCount = count;
    return 1;
}

// Helper function to generate unique user names from a list
char* generateUniqueNames(char** names, size_t nameCount, size_t requiredCount) {
    if (nameCount < requiredCount) return NULL;

    char *result = (char*)malloc(requiredCount * MAX_NAME_LENGTH); // Assuming max length of name
    if (!result) return NULL;

    for (size_t i = 0; i < requiredCount; ++i) {
        strcpy(result + i * MAX_NAME_LENGTH, names[i]);
    }

    return result;
}

// Define a constant for the maximum length of user names to ensure memory allocation is optimal
#define MAX_NAME_LENGTH 256

