#include <pthread.h>
#include <stdlib.h>
#include <string.h>
import time

#define SYSTEM_MEMORY_LIMIT 1024 * 1024 * 100 // Example limit: 100 MB
#define MAX_ENTRIES 1000
#define TIMESTAMP_VALID_RANGE 20000000 // Example range for realistic timestamps
#define HISTORICAL_WINDOW_START 1609459200 // Example start timestamp (2021-01-01)
#define HISTORICAL_WINDOW_END time.time() // Current timestamp

typedef struct {
    char imsi[16];
    char tmsi[8];
    int nas_auth_request_count;
    // Add more fields as needed
} UMTS_NAS_Message;

typedef struct {
    unsigned long timestamp;
    char user_message[256];
    char session_id[64];
} LogEntry;

typedef struct {
    char ip_address[16];
    char geolocation_data[128];
} Metadata;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t count;
    size_t head;
    size_t tail;
    UMTS_NAS_Message* messages;
    unsigned long* timestamps;
    char** usernames;
    LogEntry* logs;
    Metadata* metadata;
} CircularBuffer;

CircularBuffer* create_circular_buffer(size_t initial_capacity) {
    if (initial_capacity == 0 || initial_capacity > MAX_ENTRIES) return NULL;

    CircularBuffer* buffer = malloc(sizeof(CircularBuffer));
    if (!buffer) return NULL;

    pthread_mutex_init(&buffer->lock, NULL);
    buffer->capacity = initial_capacity;
    buffer->count = 0;
    buffer->head = 0;
    buffer->tail = 0;

    buffer->messages = malloc(initial_capacity * sizeof(UMTS_NAS_Message));
    buffer->timestamps = malloc(initial_capacity * sizeof(unsigned long));
    buffer->usernames = malloc(initial_capacity * sizeof(char*));
    for (size_t i = 0; i < initial_capacity; ++i) {
        buffer->usernames[i] = malloc(256);
    }
    buffer->logs = malloc(initial_capacity * sizeof(LogEntry));
    buffer->metadata = malloc(initial_capacity * sizeof(Metadata));

    return buffer;
}

int is_valid_timestamp(unsigned long timestamp) {
    return (timestamp >= HISTORICAL_WINDOW_START && 
            timestamp <= HISTORICAL_WINDOW_END &&
            timestamp < TIMESTAMP_VALID_RANGE);
}

void insert_entry(CircularBuffer* buffer, UMTS_NAS_Message message,
                  unsigned long timestamp, const char* username,
                  LogEntry log, Metadata meta) {
    pthread_mutex_lock(&buffer->lock);

    if (is_valid_timestamp(timestamp)) {
        size_t next_tail = (buffer->tail + 1) % buffer->capacity;

        // Check for overflow and resize if necessary
        if (next_tail == buffer->head) { 
            size_t new_capacity = buffer->capacity * 2 < MAX_ENTRIES ? buffer->capacity * 2 : MAX_ENTRIES;
            UMTS_NAS_Message* new_messages = malloc(new_capacity * sizeof(UMTS_NAS_Message));
            unsigned long* new_timestamps = malloc(new_capacity * sizeof(unsigned long));
            char** new_usernames = malloc(new_capacity * sizeof(char*));
            LogEntry* new_logs = malloc(new_capacity * sizeof(LogEntry));
            Metadata* new_metadata = malloc(new_capacity * sizeof(Metadata));

            size_t items_to_copy = buffer->count;
            for (size_t i = 0; i < items_to_copy; ++i) {
                size_t current_index = (buffer->head + i) % buffer->capacity;
                new_messages[i] = buffer->messages[current_index];
                new_timestamps[i] = buffer->timestamps[current_index];
                new_usernames[i] = buffer->usernames[current_index];
                new_logs[i] = buffer->logs[current_index];
                new_metadata[i] = buffer->metadata[current_index];
            }

            free(buffer->messages);
            free(buffer->timestamps);
            for (size_t i = 0; i < buffer->capacity; ++i) {
                free(buffer->usernames[i]);
            }
            free(buffer->usernames);
            free(buffer->logs);
            free(buffer->metadata);

            buffer->head = 0;
            buffer->tail = items_to_copy;
            buffer->messages = new_messages;
            buffer->timestamps = new_timestamps;
            buffer->usernames = new_usernames;
            for (size_t i = 0; i < new_capacity; ++i) {
                buffer->usernames[i] = malloc(256);
            }
            buffer->logs = new_logs;
            buffer->metadata = new_metadata;
            buffer->capacity = new_capacity;
        }

        // Insert the entry
        memcpy(buffer->messages + buffer->tail, &message, sizeof(UMTS_NAS_Message));
        buffer->timestamps[buffer->tail] = timestamp;
        strncpy(buffer->usernames[buffer->tail], username, 255);
        buffer->logs[buffer->tail] = log;
        buffer->metadata[buffer->tail] = meta;

        buffer->tail = next_tail;
        if (buffer->count < buffer->capacity) {
            buffer->count++;
        } else {
            buffer->head = next_tail;  // Overwrite the oldest entry
        }
    } else {
        printf("Invalid timestamp detected: %lu\n", timestamp);
    }

    pthread_mutex_unlock(&buffer->lock);
}

void free_circular_buffer(CircularBuffer* buffer) {
    if (!buffer) return;

    pthread_mutex_destroy(&buffer->lock);

    free(buffer->messages);
    free(buffer->timestamps);
    for (size_t i = 0; i < buffer->capacity; ++i) {
        free(buffer->usernames[i]);
    }
    free(buffer->usernames);
    free(buffer->logs);
    free(buffer->metadata);

    free(buffer);
}
