void initialize_data(long n, long range, const char* config_file) {
    clock_t start = clock();

    // Configuration reading logic (simplified)
    int seed_source_fixed = 1; // Assume fixed seed for demonstration
    if (!seed_source_fixed) {
        printf("Config file missing or malformed\n");
        return;
    }

    long *offsets = (long *)malloc(n * sizeof(long));
    int *keys = (int *)malloc(n * sizeof(int));
    record *records = (record *)malloc(n * sizeof(record));

    if (!offsets || !keys || !records) {
        printf("Memory allocation failed\n");
        free_resources(offsets, keys, records, n);
        return;
    }

    long seed = generate_seed(seed_source_fixed ? "fixed" : "timestamp");

    srand48(seed);

    for (long i = 0; i < n; ++i) {
        offsets[i] = lrand48() % range;
        keys[i] = rand() % range;
        records[i].value = random_value(0, range - 1); // Assuming [0, range-1]
    }

    uint32_t serialized_size = serialize_records(records, n, "records.bin");

    clock_t end = clock();
    double time_taken_ms = (double)(end - start) * 1000 / CLOCKS_PER_SEC;

    printf("Initialization took %.2f milliseconds\n", time_taken_ms);
    printf("Serialized data size: %u bytes\n", serialized_size);

    free_resources(offsets, keys, records, n);
}

long generate_seed(const char* seed_source) {
    if (strcmp(seed_source, "fixed") == 0) {
        return 123456789L; // Example fixed seed
    } else {
        return (long)time(NULL); // Timestamp-based seed
    }
}

int random_value(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void free_resources(long *offsets, int *keys, record *records, size_t n) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
}

uint32_t serialize_records(record *records, size_t n, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return 0;

    uint32_t serialized_size = fwrite(records, sizeof(record), n, file);
    fclose(file);

    return serialized_size;
}
