import java.util.Arrays;

public class DisjointPairs {

    public static void main(String[] args) {
        int[] array = {1, 2, 3, 4, 5};
        long timeTaken = countDisjointPairs(array);
        System.out.println("Number of disjoint pairs: " + (timeTaken / 1000));
        System.out.println("Time taken for disjoint checks: " + (timeTaken % 1000) + " milliseconds");
    }

    public static long countDisjointPairs(int[] array) {
        if (array == null || array.length < 2) return 0;

        int n = array.length;
        UnionFind uf = new UnionFind(n);

        long start = System.currentTimeMillis();
        long disjointCount = 0;

        for (int i = 0; i < n - 1; i++) {
            for (int j = i + 1; j < n; j++) {
                if (!uf.connected(i, j)) {
                    uf.union(i, j);
                    disjointCount++;
                }
            }
        }

        long end = System.currentTimeMillis();
        return end - start;
    }

    static class UnionFind {
        private int[] parent, rank;

        public UnionFind(int size) {
            parent = new int[size];
            rank = new int[size];
            for (int i = 0; i < size; i++) {
                parent[i] = i;
            }
        }

        public int find(int p) {
            while (p != parent[p]) {
                parent[p] = parent[parent[p]]; // path compression
                p = parent[p];
            }
            return p;
        }

        public boolean connected(int p, int q) {
            return find(p) == find(q);
        }

        public void union(int p, int q) {
            int rootP = find(p), rootQ = find(q);
            if (rootP == rootQ) return;

            // rank-based union
            if (rank[rootP] > rank[rootQ]) {
                parent[rootQ] = rootP;
            } else if (rank[rootP] < rank[rootQ]) {
                parent[rootP] = rootQ;
            } else {
                parent[rootQ] = rootP;
                rank[rootP]++;
            }
        }
    }
}
