#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define constants for maximum limit and memory threshold
#define MAX_OFFSET_LIMIT 1000
#define MEMORY_THRESHOLD (10 * 1024 * 1024) // 10 MB

typedef struct {
    int key;
    long offset;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
    struct Node* prev;
} Node;

// Global variables for thread safety and memory management
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
size_t total_memory_usage = 0;
Node* head = NULL; // Head of doubly linked list for LRU cache

// Function prototypes
void initialize_records(int num_keys, int increment_factor);
void serialize_data(const char* filename);
int deserialize_data(const char* filename);
void access_record(int key);
void release_lru();

// Memory tracking functions
size_t calculate_memory_usage(size_t record_count) {
    return sizeof(Record) * record_count;
}

void update_memory_usage(size_t usage_delta) {
    pthread_mutex_lock(&mutex);
    total_memory_usage += usage_delta;
    if (total_memory_usage > MEMORY_THRESHOLD) {
        release_lru();
    }
    pthread_mutex_unlock(&mutex);
}

// Function to initialize records
void initialize_records(int num_keys, int increment_factor) {
    pthread_t threads[2];

    // Start serialization/deserialization thread
    pthread_create(&threads[0], NULL, (void* (*)(void*))deserialize_data, "records.dat");

    // Initialize offset and key arrays
    long* offsets = malloc(num_keys * sizeof(long));
    int* keys = malloc(num_keys * sizeof(int));

    for (int i = 0; i < num_keys; ++i) {
        offsets[i] = i * increment_factor;
        if (offsets[i] > MAX_OFFSET_LIMIT) {
            free(offsets);
            free(keys);
            fprintf(stderr, "Offset exceeds maximum limit\n");
            exit(EXIT_FAILURE);
        }
    }

    // Create records
    for (int i = 0; i < num_keys; ++i) {
        Record record = { keys[i], offsets[i] };

        Node* new_node = malloc(sizeof(Node));
        new_node->record = record;
        new_node->next = head;
        new_node->prev = NULL;

        if (head != NULL) {
            head->prev = new_node;
        }

        head = new_node;
    }

    update_memory_usage(calculate_memory_usage(num_keys));

    // Join threads
    pthread_join(threads[0], NULL);
}

// Function to serialize data to a file
void serialize_data(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    Node* current = head;
    while (current != NULL) {
        fwrite(&(current->record), sizeof(Record), 1, file);
        current = current->next;
    }

    fclose(file);
}

// Function to deserialize data from a file
int deserialize_data(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    Record record;
    while (fread(&record, sizeof(Record), 1, file)) {
        Node* new_node = malloc(sizeof(Node));
        new_node->record = record;
        new_node->next = head;
        new_node->prev = NULL;

        if (head != NULL) {
            head->prev = new_node;
        }

        head = new_node;
    }

    fclose(file);
    return 0;
}

// Function to access a record by key
void access_record(int key) {
    pthread_mutex_lock(&mutex);

    Node* current = head;
    while (current != NULL) {
        if (current->record.key == key) {
            // Move accessed node to front (MRU)
            if (current->prev) {
                current->prev->next = current->next;
            }
            if (current->next) {
                current->next->prev = current->prev;
            }
            if (head == current) {
                head = current->next;
            } else {
                current->next = head;
                current->prev = NULL;
                head->prev = current;
            }
            head = current;
            pthread_mutex_unlock(&mutex);
            return;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&mutex);
}

// Function to release the least recently used record
void release_lru() {
    if (head == NULL) return;

    Node* lru_node = head;
    head = head->next;
    if (head != NULL) {
        head->prev = NULL;
    }

    update_memory_usage(-sizeof(Record));
    free(lru_node);
}

int main() {
    initialize_records(100, 5);

    // Simulate accessing records
    access_record(10);
    access_record(20);

    serialize_data("records.dat");

    return 0;
}
```

