#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef enum {
    INFO,
    WARN,
    ERROR,
    CRITICAL
} log_level;

typedef struct {
    time_t timestamp;
    char *message;
    log_level severity;
} log_entry;

#define MAX_LOG_ENTRIES 10000

log_entry *log_entries = NULL;
size_t current_size = 0;
pthread_mutex_t lock;

void initialize_log_system(size_t initial_size) {
    pthread_mutex_lock(&lock);

    if (log_entries != NULL) {
        for (size_t i = 0; i < current_size; i++) {
            free(log_entries[i].message);
        }
        free(log_entries);
    }

    log_entries = malloc(initial_size * sizeof(log_entry));
    if (!log_entries) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&lock);
        exit(EXIT_FAILURE);
    }

    current_size = initial_size;

    for (size_t i = 0; i < current_size; i++) {
        log_entries[i].timestamp = time(NULL);
        log_entries[i].message = strdup(""); // Default empty message
        log_entries[i].severity = INFO;      // Default severity level
    }

    pthread_mutex_unlock(&lock);
}

void reset_log_entries() {
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < current_size; i++) {
        free(log_entries[i].message);
        log_entries[i].timestamp = time(NULL);
        log_entries[i].message = strdup(""); // Default empty message
        log_entries[i].severity = INFO;      // Reset to default severity level
    }

    pthread_mutex_unlock(&lock);
}

void add_log_entry(const char *new_message, log_level new_severity) {
    pthread_mutex_lock(&lock);

    if (current_size >= MAX_LOG_ENTRIES) {
        fprintf(stderr, "Log entry limit reached.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    size_t index = current_size % MAX_LOG_ENTRIES; // Use modulo to handle overflow
    log_entries[index].timestamp = time(NULL);
    free(log_entries[index].message);  // Free the previous message if any
    log_entries[index].message = strdup(new_message ? new_message : "");
    log_entries[index].severity = new_severity;

    current_size++;

    pthread_mutex_unlock(&lock);
}

void cleanup_log_system() {
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < current_size; i++) {
        free(log_entries[i].message);
    }

    free(log_entries);
    log_entries = NULL;
    current_size = 0;

    pthread_mutex_unlock(&lock);
}

int main() {
    pthread_mutex_init(&lock, NULL);

    initialize_log_system(100); // Start with an initial size

    add_log_entry("System startup", INFO);
    add_log_entry("Low disk space warning", WARN);
    add_log_entry("Unable to connect to database", ERROR);

    reset_log_entries();

    add_log_entry("High CPU usage detected", CRITICAL);

    cleanup_log_system();
    pthread_mutex_destroy(&lock);

    return 0;
}
