typedef struct {
    int value;
    int *key_ptr;
} record;

int manage_memory_allocation(size_t num_records, size_t min_offset, size_t max_offset, 
                             int min_key, int max_key, int min_value, int max_value,
                             size_t max_memory_usage, long **offsets, int **keys, record ***records) {
    if (num_records == 0 || min_offset > max_offset || min_key >= max_key || 
        min_value > max_value || max_memory_usage < sizeof(long) + sizeof(int)) {
        return -1; // Invalid parameters
    }

    size_t offset_size = num_records * sizeof(long);
    size_t key_size = num_records * sizeof(int);
    size_t record_size = num_records * sizeof(record);

    size_t total_memory_needed = offset_size + key_size + record_size;

    if (total_memory_needed > max_memory_usage) {
        printf("Memory constraint exceeded.\n");
        return -2; // Memory limit exceeded
    }

    srand(time(NULL)); // Seed for random number generation

    *offsets = malloc(offset_size);
    *keys = malloc(key_size);
    *records = malloc(record_size);

    if (!*offsets || !*keys || !*records) {
        printf("Memory allocation failed.\n");
        free(*offsets); free(*keys); free(*records);
        return -3; // Memory allocation failure
    }

    for (size_t i = 0; i < num_records; ++i) {
        (*offsets)[i] = min_offset + (i * (max_offset - min_offset) / (num_records - 1));
    }

    int used_keys[num_records];
    memset(used_keys, 0, sizeof(used_keys));

    for (size_t i = 0; i < num_records; ++i) {
        int key;
        do {
            key = rand() % (max_key - min_key + 1) + min_key;
        } while (used_keys[key - min_key]);

        (*keys)[i] = key;
        used_keys[key - min_key] = 1;
    }

    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].value = rand() % (max_value - min_value + 1) + min_value;
        (*records)[i].key_ptr = &(*keys)[i];
    }

    return 0; // Success
}
