    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
}

int insert_pdu(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!validate_structure(&pdu)) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    memcpy(&new_node->data, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_rwlock_wrlock(&list->read_write_lock);

    if (!list->head) {
        list->head = list->tail = new_node;
        new_node->next = new_node->prev = NULL;
    } else {
        new_node->next = NULL;
        new_node->prev = list->tail;
        list->tail->next = new_node;
        list->tail = new_node;
    }

    pthread_rwlock_unlock(&list->read_write_lock);
    log_operation("Insert", &pdu);

    return 0;
}

void* iterate_forward(CRCList* list, void (*callback)(const NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!list) return NULL;

    pthread_rwlock_rdlock(&list->read_write_lock);

    Node* current = list->head;
    while (current) {
        callback(&current->data);
        current = current->next;
    }

    pthread_rwlock_unlock(&list->read_write_lock);
}

void* iterate_backward(CRCList* list, void (*callback)(const NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!list) return NULL;

    pthread_rwlock_rdlock(&list->read_write_lock);

    Node* current = list->tail;
    while (current) {
        callback(&current->data);
        current = current->prev;
    }

    pthread_rwlock_unlock(&list->read_write_lock);
}

void log_operation(const char* operation, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Placeholder for actual logging implementation
    printf("Operation: %s, RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
           operation,
           pdu->RX_UE_INFORMATION_TAG,
           pdu->RNTI,
           pdu->CRC_INDICATION_REL8_TAG.CRCFLAG);
}

void free_list(CRCList* list) {
    if (!list) return;

    pthread_rwlock_wrlock(&list->read_write_lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_rwlock_unlock(&list->read_write_lock);

    pthread_mutex_destroy(&list->lock);
    pthread_rwlock_destroy(&list->read_write_lock);
    free(list);
}

int main() {
