    if (!list) return -1;

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = 1234; // Example value
    pdu.RNTI = 5678; // Example value

    set_random_crcflag(&pdu);
    insert_pdu(list, pdu);

    iterate_forward(list, [](const NFAPI_CRC_INDICATION_PDU_T* pdu) {
        printf("Forward Iteration - RX_UE_INFORMATION_TAG: %d\n", pdu->RX_UE_INFORMATION_TAG);
    });

    iterate_backward(list, [](const NFAPI_CRC_INDICATION_PDU_T* pdu) {
        printf("Backward Iteration - RX_UE_INFORMATION_TAG: %d\n", pdu->RX_UE_INFORMATION_TAG);
    });

    free_list(list);

    return 0;
}
