// Add MAC PDU structures to the pool
bool add_mac_pdu(MemPool *mpool, uint32_t max_mem_limit, int N, LogLevel log_level, LogCallback logger) {
    if (N * sizeof(MAC_PDU_T) > max_mem_limit || mpool->used + N * sizeof(MAC_PDU_T) > mpool->pool_size) {
        return false; // Exceeds memory limits
    }

    uint16_t sn = 0;
    bool success = true;

    for (int i = 0; i < N && success; ++i) {
        MAC_PDU_T *pdu = NULL;
        int retries = 3;

        while (retries > 0) {
            if (!allocate_from_pool(mpool, &pdu)) {
                return false;
