            // Generate unique LCG
            pdu->LCG = rand(); // Simplified example; in practice, use a better random number generator.
            for (size_t j = 0; j < mpool->used / sizeof(MAC_PDU_T); ++j) {
                MAC_PDU_T *existing_pdu = (MAC_PDU_T *)(mpool->pool + j * sizeof(MAC_PDU_T));
                if (existing_pdu->LCG == pdu->LCG) {
                    deallocate_from_pool(mpool, pdu);
                    --retries;
                    break;
                }
            }

            if (retries > 0 || retries == 0 && allocate_from_pool(mpool, &pdu)) {
                break; // Exit retry loop successfully
            }
        }

        if (retries == 0) {
            success = false; // Couldn't generate a unique LCG after retries
            logger(LOG_LEVEL_WARNING, "Failed to add MAC_PDU due to LCG collision.");
        } else {
            pdu->PDCP_SN = ++sn;
            pdu->LCG_PRBS_STATE = rand() % 256; // Example PRBS state assignment
            logger(log_level, "Added MAC_PDU with SN: %d", pdu->PDCP_SN);
        }
    }

