#include <stdio.h>
#include <stdlib.h>
import threading
from random import randint

typedef struct {
    int value;
} record_t;

typedef struct {
    long offset;
    int key;
    record_t record;
} entry_t;

typedef struct {
    entry_t *entries;
    size_t count;
    size_t capacity;
    int max_size;
    pthread_mutex_t lock;
    FILE *log_file;
} collection_t;

#define ERROR_CODE (-1)

collection_t* init_collection(size_t initial_capacity, int min_value, int max_value, int max_size) {
    if (initial_capacity == 0 || min_value >= max_value || max_size <= 0) {
        return NULL;
    }

    collection_t *col = malloc(sizeof(collection_t));
    if (!col) return NULL;

    col->entries = calloc(initial_capacity, sizeof(entry_t));
    if (!col->entries) {
        free(col);
        return NULL;
    }

    col->count = 0;
    col->capacity = initial_capacity;
    col->max_size = max_size;

    if (pthread_mutex_init(&col->lock, NULL) != 0) {
        free(col->entries);
        free(col);
        return NULL;
    }

    if ((col->log_file = fopen("collection_log.txt", "a")) == NULL) {
        pthread_mutex_destroy(&col->lock);
        free(col->entries);
        free(col);
        return NULL;
    }

    for (size_t i = 0; i < initial_capacity; ++i) {
        col->entries[i].offset = (long)i * 1000; // Example offset
        col->entries[i].key = rand() % (max_value - min_value + 1) + min_value;
        col->entries[i].record.value = rand() % (max_value - min_value + 1) + min_value;

        log_change(col, "init", i);
    }

    return col;
}

int resize_collection(collection_t *col) {
    if (col->count >= col->capacity && col->capacity < col->max_size) {
        size_t new_capacity = col->capacity * 2;
        if (new_capacity > col->max_size) {
            new_capacity = col->max_size;
        }

        entry_t *temp_entries = realloc(col->entries, new_capacity * sizeof(entry_t));
        if (!temp_entries) return ERROR_CODE;

        col->entries = temp_entries;
        col->capacity = new_capacity;
    }

    return 0;
}

void log_change(collection_t *col, const char *action, size_t index) {
    pthread_mutex_lock(&col->lock);
    fprintf(col->log_file, "Action: %s, Index: %zu\n", action, index);
    fflush(col->log_file);
    pthread_mutex_unlock(&col->lock);
}

int add_record(collection_t *col, int key, int value) {
    pthread_mutex_lock(&col->lock);

    if (resize_collection(col) == ERROR_CODE) {
        log_change(col, "error_resize", 0);
        pthread_mutex_unlock(&col->lock);
        return ERROR_CODE;
    }

    entry_t new_entry;
    new_entry.offset = col->count * 1000;
    new_entry.key = key;
    new_entry.record.value = value;

    if (col->count < col->capacity) {
        col->entries[col->count] = new_entry;
    } else {
        pthread_mutex_unlock(&col->lock);
        return ERROR_CODE;
    }

    log_change(col, "add", col->count);

    col->count++;
    pthread_mutex_unlock(&col->lock);

    return 0;
}

void free_collection(collection_t *col) {
    if (!col) return;

    pthread_mutex_lock(&col->lock);
    free(col->entries);
    fclose(col->log_file);
    pthread_mutex_unlock(&col->lock);

    pthread_mutex_destroy(&col->lock);
    free(col);
}
```

