#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

#define INITIAL_CAPACITY 10

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t used;
    size_t capacity;
    pthread_mutex_t mutex;
    pthread_rwlock_t rwlock;
} PduList;

// Initialize list with a specified initial capacity
PduList* pdu_list_init(size_t init_capacity) {
    PduList* list = (PduList*)malloc(sizeof(PduList));
    if (!list) return NULL;

    list->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(init_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->array) {
        free(list);
        return NULL;
    }
    list->used = 0;
    list->capacity = init_capacity;

    pthread_mutex_init(&list->mutex, NULL);
    pthread_rwlock_init(&list->rwlock, NULL);

    return list;
}

// Resize the internal array
static int pdu_list_resize(PduList* list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* temp = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp) return 0;

    list->capacity = new_capacity;
    memset(temp + list->used, 0, (new_capacity - list->used) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    list->array = temp;
    return 1;
}

// Thread-safe add function
int pdu_list_add(PduList* list, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_rwlock_wrlock(&list->rwlock);

    if (list->used == list->capacity && !pdu_list_resize(list, list->capacity * 2)) {
        pthread_rwlock_unlock(&list->rwlock);
        return 0;
    }

    list->array[list->used++] = item;

    pthread_rwlock_unlock(&list->rwlock);
    return 1;
}

// Thread-safe remove function
int pdu_list_remove(PduList* list, size_t index) {
    if (index >= list->used) return 0;

    pthread_rwlock_wrlock(&list->rwlock);

    memmove(list->array + index, list->array + index + 1, (list->used - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    --list->used;

    if (list->used <= list->capacity / 4 && list->capacity > INITIAL_CAPACITY) {
        pdu_list_resize(list, list->capacity / 2);
    }

    pthread_rwlock_unlock(&list->rwlock);
    return 1;
}

// Thread-safe iteration function
int pdu_list_iterate(PduList* list, void (*func)(NFAPI_CRC_INDICATION_PDU_T)) {
    if (!func) return 0;

    pthread_rwlock_rdlock(&list->rwlock);

    for (size_t i = 0; i < list->used; ++i) {
        func(list->array[i]);
    }

    pthread_rwlock_unlock(&list->rwlock);
    return 1;
}

// Cleanup function
void pdu_list_free(PduList* list) {
    if (!list) return;

    free(list->array);
    pthread_mutex_destroy(&list->mutex);
    pthread_rwlock_destroy(&list->rwlock);
    free(list);
}

// Function to randomly set CRCFLAG with overflow protection
int random_crcflag() {
    int max_value = RAND_MAX / 2 * 2; // Ensure even value for demonstration
    return rand() % (max_value + 1); // Prevent potential overflow by restricting range
}

// Example function demonstrating adding an item
void add_example_item(PduList* list) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = /* Fetch from external source */;
    pdu.RNTI = /* Fetch or compute */;
    pdu.CRC_INDICATION_REL8_TAG = /* Fetch or determine */;
    pdu.CRCFLAG = random_crcflag();

    if (!pdu_list_add(list, pdu)) {
        fprintf(stderr, "Failed to add PDU item.\n");
    }
}

// Initialize random number generator
void initialize_rng() {
    srand((unsigned)time(NULL));
}
