```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_MEMORY_USAGE 1024 * 1024 // Example limit: 1 MB
#define RECORD_COUNT 1000
#define RANDOM_MIN 10
#define RANDOM_MAX 99

typedef struct {
    int value;
} record;

// Function prototypes
void* manage_memory(void* args);
int verify_records(record* records, size_t count, int min, int max);
void free_resources(long** offsets, int** keys, record** records, size_t offset_count, size_t key_count);

// Thread-safe memory management function
void* manage_memory(void* args) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);
    pthread_mutex_lock(&lock);

    long total_memory = 0;
    size_t offset_count = RECORD_COUNT;
    size_t key_count = RECORD_COUNT;

    long* offsets = (long*)malloc(offset_count * sizeof(long));
    int* keys = (int*)malloc(key_count * sizeof(int));
    record* records = (record*)malloc(offset_count * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&lock);
        pthread_mutex_destroy(&lock);
        free_resources(&offsets, &keys, &records, offset_count, key_count);
        return NULL;
    }

    total_memory += offset_count * sizeof(long);
    total_memory += key_count * sizeof(int);
    total_memory += offset_count * sizeof(record);

    if (total_memory > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Exceeded memory usage limit\n");
        free_resources(&offsets, &keys, &records, offset_count, key_count);
        pthread_mutex_unlock(&lock);
        pthread_mutex_destroy(&lock);
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < offset_count; ++i) {
        records[i].value = rand() % (RANDOM_MAX - RANDOM_MIN + 1) + RANDOM_MIN;
    }

    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);

    if (!verify_records(records, offset_count, RANDOM_MIN, RANDOM_MAX)) {
        fprintf(stderr, "Record verification failed\n");
    } else {
        printf("All records verified successfully.\n");
    }

    free_resources(&offsets, &keys, &records, offset_count, key_count);
    return NULL;
}

int verify_records(record* records, size_t count, int min, int max) {
    for (size_t i = 0; i < count; ++i) {
        if (records[i].value < min || records[i].value > max) {
            return 0;
        }
    }
    return 1;
}

void free_resources(long** offsets, int** keys, record** records, size_t offset_count, size_t key_count) {
    if (*offsets) free(*offsets);
    if (*keys) free(*keys);
    if (*records) free(*records);
    *offsets = NULL;
    *keys = NULL;
    *records = NULL;
}

int main() {
    pthread_t thread1, thread2;

    // Simulate concurrent execution
    pthread_create(&thread1, NULL, manage_memory, NULL);
    pthread_create(&thread2, NULL, manage_memory, NULL);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    return 0;
}
```

This code provides a thread-safe memory management function that allocates and verifies memory for arrays of `long`, `int`, and `record` structures. It includes error handling for failed allocations and ensures that the total memory usage does not exceed a predefined limit. The function is designed to be easily extendable and handles potential race conditions using mutex locks.']

