        free(current);
        current = next;
    }

    pthread_rwlock_unlock(&list->lock);
    pthread_rwlock_destroy(&list->lock);
    free(list);
}

int insert_message(NasMessageList* list, const char* imsi, unsigned int tmsi) {
    if (!list || !imsi) return -1;

    pthread_rwlock_wrlock(&list->lock);

    // Check for existing entry
    PoolElem *current = list->head;
    while (current) {
        if (strcmp(current->data->imsi, imsi) == 0) {
            pthread_rwlock_unlock(&list->lock);
            return -1; // IMSI already exists
        }
        current = current->next;
    }

    // Allocate and initialize new NasMessage from the pool or heap
    PoolElem* elem = (PoolElem*)malloc(sizeof(PoolElem));
    if (!elem) {
        pthread_rwlock_unlock(&list->lock);
        return -1; // Memory allocation failure
    }
    elem->data = (NasMessage*)malloc(sizeof(NasMessage));
    if (!elem->data) {
        free(elem);
        pthread_rwlock_unlock(&list->lock);
        return -1;
    }

    strncpy(elem->data->imsi, imsi, sizeof(elem->data->imsi) - 1);
    elem->data->tmsi = tmsi;

    // Validate the NAS message content
    validate_nas_content(elem->data);

    // Insert at head for efficiency
    elem->next = list->head;
    list->head = elem;
    list->count++;

    pthread_rwlock_unlock(&list->lock);
    return 0; // Success
}

int remove_message(NasMessageList* list, const char* imsi) {
    if (!list || !imsi) return -1;

    pthread_rwlock_wrlock(&list->lock);

    PoolElem **current = &(list->head), *temp;
    while (*current) {
        if (strcmp((*current)->data->imsi, imsi) == 0) {
            temp = *current;
            *current = temp->next;
            free(temp->data);
            free(temp);
            list->count--;
            pthread_rwlock_unlock(&list->lock);
            return 0; // Success
        }
        current = &((*current)->next);
    }

    pthread_rwlock_unlock(&list->lock);
    return -1; // IMSI not found
}

NasMessage* find_message(const NasMessageList* list, const char* imsi) {
    if (!list || !imsi) return NULL;

    pthread_rwlock_rdlock((pthread_rwlock_t*)&list->lock);

    for (PoolElem *current = list->head; current != NULL; current = current->next) {
        if (strcmp(current->data->imsi, imsi) == 0) {
            pthread_rwlock_unlock((pthread_rwlock_t*)&list->lock);
            return current->data;
        }
    }

    pthread_rwlock_unlock((pthread_rwlock_t*)&list->lock);
    return NULL; // IMSI not found
}

