['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int x;
    int y;
} Point;

typedef struct GraphNode {
    double value;
    char character;
    struct Point* point;
    struct GraphNode* next;  // For linked list structure within the graph
} GraphNode;

// Union-Find with path compression and union by rank
typedef struct {
    int *parent, *rank;
} UnionFind;

UnionFind* UF_create(int size) {
    UnionFind* uf = (UnionFind*)malloc(sizeof(UnionFind));
    uf->parent = (int*)malloc(size * sizeof(int));
    uf->rank = (int*)calloc(size, sizeof(int));

    for (int i = 0; i < size; i++) {
        uf->parent[i] = i;
    }
    return uf;
}

void UF_destroy(UnionFind* uf) {
    free(uf->parent);
    free(uf->rank);
    free(uf);
}

int UF_find(UnionFind* uf, int x) {
    if (uf->parent[x] != x)
        uf->parent[x] = UF_find(uf, uf->parent[x]);
    return uf->parent[x];
}

void UF_union(UnionFind* uf, int x, int y) {
    int rootX = UF_find(uf, x);
    int rootY = UF_find(uf, y);

    if (rootX != rootY) {
        if (uf->rank[rootX] > uf->rank[rootY]) {
            uf->parent[rootY] = rootX;
        } else if (uf->rank[rootX] < uf->rank[rootY]) {
            uf->parent[rootX] = rootY;
        } else {
            uf->parent[rootY] = rootX;
            uf->rank[rootX]++;
        }
    }
}

int count_disjoint_pairs(UnionFind* uf, int size) {
    int disjointPairs = 0;
    for (int i = 0; i < size; ++i) {
        if (UF_find(uf, i) == i)
            disjointPairs++;
    }
    return disjointPairs - 1; // Subtracting 1 because each element is its own root
}

void initialize_random_point(Point* point) {
    point->x = rand() % 100;
    point->y = rand() % 100;
}

GraphNode* create_graph_node(double value, char character) {
    GraphNode* node = (GraphNode*)malloc(sizeof(GraphNode));
    if (!node) return NULL;

    node->value = value;
    node->character = character;
    node->point = (Point*)malloc(sizeof(Point));
    if (!node->point) {
        free(node);
        return NULL;
    }

    initialize_random_point(node->point);
    node->next = NULL;
    return node;
}

void destroy_graph_node(GraphNode* node) {
    if (node) {
        destroy_graph_node(node->next);
        free(node->point);
        free(node);
    }
}

GraphNode** create_and_initialize_graph(int num_nodes, double min_value, double max_value, int buffer_size) {
    GraphNode** graph = (GraphNode**)malloc(num_nodes * sizeof(GraphNode*));
    if (!graph) return NULL;

    UnionFind* uf = UF_create(num_nodes);

    for (int i = 0; i < num_nodes; ++i) {
        double random_value = min_value + ((double)rand() / RAND_MAX) * (max_value - min_value);
        char random_char = 'A' + rand() % 26;

        graph[i] = create_graph_node(random_value, random_char);

        if (!graph[i]) {
            // Clean up in case of allocation failure
            for (int j = 0; j < i; ++j) destroy_graph_node(graph[j]);
            free(graph);
            UF_destroy(uf);
            return NULL;
        }

        int target_index = rand() % num_nodes;
        UF_union(uf, i, target_index);

        if ((i + 1) % buffer_size == 0 || i == num_nodes - 1) {
            clock_t start_time = clock();
            int disjoint_pairs_count = count_disjoint_pairs(uf, num_nodes);
            clock_t end_time = clock();
            double time_taken_ms = (double)(end_time - start_time) * 1000.0 / CLOCKS_PER_SEC;

            printf("Buffer processed: Disjoint pairs=%d, Time taken=%.2f ms\n", disjoint_pairs_count, time_taken_ms);
        }
    }

    int final_disjoint_pairs = count_disjoint_pairs(uf, num_nodes);
    UF_destroy(uf);

    return graph;
}

void destroy_graph(GraphNode** graph, int size) {
    for (int i = 0; i < size; ++i) {
        destroy_graph_node(graph[i]);
    }
    free(graph);
}

int main() {
    srand(time(NULL));
    int num_nodes = 1000;
    double min_value = 1.0, max_value = 10.0;
    int buffer_size = 100;

    GraphNode** graph = create_and_initialize_graph(num_nodes, min_value, max_value, buffer_size);

    if (graph) {
        // Perform operations on the graph

        destroy_graph(graph, num_nodes);
    }

    return 0;
}
```

This code initializes a dynamic number of graph nodes with random values and manages memory efficiently. It uses a union-find data structure to handle disjoint sets within the graph, ensuring robust performance even under resource constraints. The buffering mechanism helps balance initialization speed and system load by processing in chunks, making it suitable for large datasets and concurrent environments.']

