```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <string.h>

#define INITIAL_CAPACITY 10
#define THRESHOLD_MULTIPLIER 2

typedef struct {
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint16_t RNTI;
    uint8_t RX_UE_INFORMATION_TAG;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int insert_count;
    int delete_count;
} LinkedList;

void init_list(LinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);
    list->insert_count = 0;
    list->delete_count = 0;
}

void destroy_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond);
}

void insert_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_node->data = data;
    new_node->next = NULL;
    new_node->prev = list->tail;

    if (list->tail != NULL) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }

    list->tail = new_node;
    list->size++;
    list->insert_count++;

    pthread_mutex_unlock(&list->lock);
}

void remove_node(LinkedList* list, uint16_t rnti) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL && current->data.RNTI != rnti) {
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (current->prev != NULL) {
        current->prev->next = current->next;
    } else {
        list->head = current->next;
    }

    if (current->next != NULL) {
        current->next->prev = current->prev;
    } else {
        list->tail = current->prev;
    }

    free(current);
    list->size--;
    list->delete_count++;

    pthread_mutex_unlock(&list->lock);
}

void iterate_forward(LinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        callback(&(current->data));
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void iterate_backward(LinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->tail;
    while (current != NULL) {
        callback(&(current->data));
        current = current->prev;
    }

    pthread_mutex_unlock(&list->lock);
}

void log_list_status(LinkedList* list) {
    printf("Insertions: %d, Deletions: %d, Current Size: %zu\n", 
           list->insert_count, list->delete_count, list->size);
}

int main() {
    LinkedList list;
    init_list(&list);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T data = { .RNTI = 1, .RX_UE_INFORMATION_TAG = 2, .crc_tag = {.CRCFLAG = rand() % 2} };
    insert_node(&list, data);

    iterate_forward(&list, [](NFAPI_CRC_INDICATION_PDU_T* pdu) {
        printf("RNTI: %u, RX UE TAG: %u, CRC FLAG: %d\n", 
               pdu->RNTI, pdu->RX_UE_INFORMATION_TAG, pdu->crc_tag.CRCFLAG);
    });

    log_list_status(&list);

    destroy_list(&list);
    return 0;
}
```

This code provides a doubly linked list with thread-safe operations for insertion and deletion. It includes functions to iterate over the list in both directions and logs the list's status. The implementation uses mutexes and condition variables for concurrency control, ensuring safe access across multiple threads.']
